def custom_pow(base: float, exponent: int) -> float:
    """
    Custom implementation of the power function that raises a number to a specific power.
    """
    if exponent == 0:
        return 1.0
    if base == 0:
        return 0.0

    def power(x: float, n: int) -> float:
        if n == 0:
            return 1.0
        half = power(x, n // 2)
        if n % 2 == 0:
            return half * half
        else:
            return half * half * x

    result = power(base, abs(exponent))
    return result if exponent > 0 else 1 / result

