from typing import List

def generate_k_combinations(arr: List[int], k: int) -> List[List[int]]:
    def recursive_combinations(start: int, comb: List[int], res: List[List[int]]):
        if len(comb) == k:
            res.append(comb.copy())
            return
        for i in range(start, len(arr)):
            comb.append(arr[i])
            recursive_combinations(i + 1, comb, res)
            comb.pop()

    result = []
    recursive_combinations(0, [], result)
    return result

