def is_valid_parenthesis(s: str) -> bool:
    """
    Determine if the input string is a valid parenthesis expression.

    Parameters:
    s (str): The input string consisting of only `(` and `)`.

    Returns:
    bool: True if the string is a valid parenthesis expression, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
        else:
            return False  # invalid character other than parentheses
    return len(stack) == 0

def fibonacci(n: int, memo: dict[int, int] = None) -> int:
    """
    Computes the nth Fibonacci number using a recursive approach with memoization.

    :param n: An integer representing the position in Fibonacci sequence.
             0 <= n <= 50.
    :param memo: A dictionary to store the already computed Fibonacci numbers to avoid redundant computations.
    :return: The nth Fibonacci number.
    """
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]
    if n <= 1:
        return n

    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

