from typing import List

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_sum_decomposition(n: int) -> List[int]:
    # Special cases where n itself is prime
    if is_prime(n):
        return [n]

    # Start by checking for the smallest primes that can form the sum n
    primes = []
    # Handle even numbers
    if n % 2 == 0:
        primes = [2] * (n // 2)
    else:
        # Handle odd numbers
        primes.append(3)
        n -= 3
        primes += [2] * (n // 2)

    return primes

