def fast_exponentiation(base: int, exp: int) -> int:
    result = 1
    while exp > 0:
        if exp % 2 == 1:
            result *= base
        base *= base
        exp //= 2
    return result

def find_sum_combinations(numbers: list[int], target_sum: int) -> list[list[int]]:
    def backtrack(start, target, path):
        if target == 0:
            result.append(path[:])
            return
        for i in range(start, len(numbers)):
            if numbers[i] > target:
                break
            path.append(numbers[i])
            backtrack(i, target - numbers[i], path)
            path.pop()

    numbers.sort()
    result = []
    backtrack(0, target_sum, [])
    return result

def evaluate_postfix(expression: str) -> float:
    """
    Evaluates a postfix (Reverse Polish Notation) expression and returns the result.

    Parameters:
    expression (str): A string representing a postfix expression where operands are separated by spaces.

    Returns:
    float: The evaluated result of the postfix expression.
    """

    stack = []

    for token in expression.split():
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()

            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)
        else:
            stack.append(float(token))

    return stack[0]

