def compress_string(s: str) -> str:
    if not s:
        return s

    compressed_str = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed_str.append(s[i - 1] + str(count))
            count = 1

    # Append the last character and its count
    compressed_str.append(s[-1] + str(count))

    compressed_result = ''.join(compressed_str)

    return compressed_result if len(compressed_result) < len(s) else s

def find_pairs_with_sum(nums: list[int], k: int) -> list[tuple[int, int]]:
    seen = set()
    pairs = set()

    for num in nums:
        complement = k - num
        if complement in seen:
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    return sorted(pairs)

