def sum_matrix_elements(matrix: List[List[int]]) -> Tuple[List[int], List[int]]:
    if not matrix or not matrix[0]:
        return ([], [])

    row_sums = [sum(row) for row in matrix]
    num_columns = len(matrix[0])
    column_sums = [sum(matrix[row][col] for row in range(len(matrix))) for col in range(num_columns)]

    return (row_sums, column_sums)

