from typing import List, Dict, Any

def build_path_tree(paths: List[List[str]]) -> Dict[str, Any]:
    def insert_path(tree: Dict[str, Any], path: List[str]):
        if not path:
            return
        node = path[0]
        if node not in tree:
            tree[node] = {}
        insert_path(tree[node], path[1:])

    tree = {}
    for path in paths:
        insert_path(tree, path)
    return tree

