def validate_syntax(syntax: str) -> bool:
    """
    Validate if the input syntax has correctly nested and closed parentheses and braces.

    :param syntax: String containing the syntax with parentheses and braces
    :return: Boolean value True if syntax is valid, False otherwise.
    """
    stack = []
    matching_bracket = {')': '(', '}': '{'}

    for char in syntax:
        if char in "({":
            stack.append(char)
        elif char in ")}":
            if not stack or stack.pop() != matching_bracket[char]:
                return False
    return not stack

