def find_pair_with_sum(nums: list[int], target: int) -> tuple[int, int]:
    def binary_search(nums: list[int], start: int, end: int, key: int) -> int:
        left, right = start, end
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == key:
                return mid
            elif nums[mid] < key:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    for i in range(len(nums)):
        complement = target - nums[i]
        j = binary_search(nums, i + 1, len(nums) - 1, complement)
        if j != -1:
            return (nums[i], nums[j])

    return ()

