import csv

def calculate_average_salary(csv_filename: str) -> dict:
    department_salary = {}
    department_count = {}

    with open(csv_filename, mode='r') as file:
        csv_reader = csv.DictReader(file)
        for row in csv_reader:
            department = row.get('Department')
            salary = row.get('Salary')

            if not department or not salary:
                continue

            try:
                salary = float(salary)
            except ValueError:
                continue

            if department not in department_salary:
                department_salary[department] = 0
                department_count[department] = 0

            department_salary[department] += salary
            department_count[department] += 1

    average_salary_by_department = {dept: department_salary[dept] / department_count[dept]
                                    for dept in department_salary}

    return average_salary_by_department

