def longest_increasing_path(matrix):
    """
    Find the length of the longest increasing path in the given matrix.

    :param matrix: A 2D list of integers representing the matrix.
    :return: An integer representing the length of the longest increasing path.
    """
    if not matrix or not matrix[0]:
        return 0

    rows, cols = len(matrix), len(matrix[0])

    memo = [[-1] * cols for _ in range(rows)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(x, y):
        if memo[x][y] != -1:
            return memo[x][y]

        max_length = 1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and matrix[nx][ny] > matrix[x][y]:
                max_length = max(max_length, 1 + dfs(nx, ny))

        memo[x][y] = max_length
        return max_length

    max_path = 0
    for r in range(rows):
        for c in range(cols):
            max_path = max(max_path, dfs(r, c))

    return max_path

