def convert_temperature(value: float, input_unit: str, output_unit: str) -> float:
    """
    Converts the given temperature value from one unit to another.

    Args:
    value (float): The temperature value to be converted.
    input_unit (str): The unit of the input temperature. Can be 'C', 'F', or 'K'.
    output_unit (str): The unit of the output temperature. Can be 'C', 'F', or 'K'.

    Returns:
    float: The converted temperature value.

    Raises:
    ValueError: If input_unit or output_unit is not valid.
    """

    # Check for valid units
    valid_units = {'C', 'F', 'K'}
    if input_unit not in valid_units:
        raise ValueError("Invalid input unit")
    if output_unit not in valid_units:
        raise ValueError("Invalid output unit")

    # Conversion logic
    temp_in_celsius = value

    if input_unit == 'F':
        temp_in_celsius = (value - 32) / 1.8
    elif input_unit == 'K':
        temp_in_celsius = value - 273.15

    if output_unit == 'C':
        return temp_in_celsius
    elif output_unit == 'F':
        return temp_in_celsius * 1.8 + 32
    elif output_unit == 'K':
        return temp_in_celsius + 273.15

