def char_frequency(s: str) -> dict:
    """
    This function builds a frequency dictionary of the characters in the input string,
    ignoring spaces and case.
    """
    freq_dict = {}
    for char in s.replace(" ", "").lower():
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1
    return freq_dict

def can_form_palindrome(freq_dict: dict) -> bool:
    """
    This function checks if the given character frequency dictionary can form a palindrome.
    """
    odd_count = 0
    for count in freq_dict.values():
        if count % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False
    return True

def is_permutation_of_palindrome(s: str) -> bool:
    """
    This function returns True if the input string is a permutation of a palindrome,
    and False otherwise.
    """
    freq_dict = char_frequency(s)
    return can_form_palindrome(freq_dict)

