from typing import List

def is_prime(n: int) -> bool:
    """Helper function to check if a number is a prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_indices_in_list(arr: List[int]) -> List[int]:
    """
    Returns a list of indices where the elements of the list are prime numbers.
    """
    return [index for index, value in enumerate(arr) if is_prime(value)]

def process_queries(arr, queries):
    prefix_sum = [0] * (len(arr) + 1)

    def update_prefix_sum():
        for i in range(1, len(arr) + 1):
            prefix_sum[i] = prefix_sum[i - 1] + arr[i - 1]

    update_prefix_sum()
    results = []

    for query in queries:
        if query[0] == 1:
            x, y = query[1], query[2]
            arr[x] += y
            update_prefix_sum()
        elif query[0] == 2:
            x = query[1]
            results.append(arr[x])
        elif query[0] == 3:
            l, r = query[1], query[2]
            sum_range = prefix_sum[r + 1] - prefix_sum[l]
            results.append(sum_range)

    return results

