from typing import List

def next_prime(nums: List[int]) -> List[int]:
    def is_prime(x: int) -> bool:
        if x <= 1:
            return False
        if x <= 3:
            return True
        if x % 2 == 0 or x % 3 == 0:
            return False
        i = 5
        while i * i <= x:
            if x % i == 0 or x % (i + 2) == 0:
                return False
            i += 6
        return True

    def find_next_prime(n: int) -> int:
        candidate = n + 1
        while not is_prime(candidate):
            candidate += 1
        return candidate

    return [find_next_prime(n) for n in nums]

