def configure_display(time_of_day: str, ambient_light: int) -> int:
    # Split the time_of_day into hours and minutes
    hours, minutes = map(int, time_of_day.split(':'))

    # Check if it's night time (20:00 to 06:59)
    if (hours >= 20 or hours < 7):
        # Cap the brightness at 40 during the night
        return 40
    else:
        # Calculate enhanced brightness with a 20% enhancement
        enhanced_brightness = int(ambient_light * 1.2)
        # Clamp the brightness to a maximum of 100
        return min(enhanced_brightness, 100)

