from math import isqrt

def nth_prime(n: int) -> int:
    """
    Returns the nth prime number.

    :param n: A positive integer representing the sequence position of the prime number to compute.
    :return: The nth prime number.
    :raises TypeError: If the input is not an integer.
    :raises ValueError: If the input is less than 1.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")

    if n < 1:
        raise ValueError("Input must be a positive integer greater than or equal to 1")

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = []
    candidate = 2
    while len(primes) < n:
        if is_prime(candidate):
            primes.append(candidate)
        candidate += 1

    return primes[-1]

