from typing import List, Tuple
import heapq

def find_shortest_path(grid: List[List[int]], start: Tuple[int, int], target: Tuple[int, int]) -> List[Tuple[int, int]]:
    def h(pos: Tuple[int, int]) -> int:
        # Heuristic function: Manhattan distance to the target
        return abs(pos[0] - target[0]) + abs(pos[1] - target[1])

    def get_neighbors(pos: Tuple[int, int]) -> List[Tuple[int, int]]:
        x, y = pos
        neighbors = []
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == 0:
                neighbors.append((nx, ny))
        return neighbors

    open_set = []
    came_from = {}
    g_score = {start: 0}
    f_score = {start: h(start)}

    heapq.heappush(open_set, (f_score[start], start))

    while open_set:
        _, current = heapq.heappop(open_set)

        if current == target:
            # Reconstruct path
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            return path[::-1]

        for neighbor in get_neighbors(current):
            tentative_g_score = g_score[current] + 1
            if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                came_from[neighbor] = current
                g_score[neighbor] = tentative_g_score
                f_score[neighbor] = tentative_g_score + h(neighbor)

                if all(neighbor != item[1] for item in open_set):
                    heapq.heappush(open_set, (f_score[neighbor], neighbor))

    return []

def sum_neighbors(arr):
    if len(arr) == 1:
        return arr

    res = []
    n = len(arr)

    for i in range(n):
        # handle the first element
        if i == 0:
            res.append(arr[i] + arr[i+1])
        # handle the last element
        elif i == n-1:
            res.append(arr[i] + arr[i-1])
        # handle all other elements
        else:
            res.append(arr[i-1] + arr[i] + arr[i+1])

    return res

def are_transactions_valid(transactions: list, lower_bound: float, upper_bound: float) -> bool:
    # Check if the input is a list and it's not empty
    if not isinstance(transactions, list) or not transactions:
        raise ValueError('Input must be a non-empty list of transactions.')

    # Check if all transactions are within the given range
    return all(lower_bound <= transaction <= upper_bound for transaction in transactions)

def sum_of_valid_transactions(transactions: list, lower_bound: float, upper_bound: float) -> float:
    # Check if the input is a list
    if not isinstance(transactions, list):
        raise ValueError('Input must be a list of transactions.')

    # Sum of transactions that are within the given range
    return sum(transaction for transaction in transactions if lower_bound <= transaction <= upper_bound)

