def analyze_log_data(
    log_entries: list[tuple[str, int, str]]
) -> tuple[dict[int, int], dict[str, int]]:
    status_counts = {}
    url_counts = {}

    for timestamp, status_code, url in log_entries:
        if status_code in status_counts:
            status_counts[status_code] += 1
        else:
            status_counts[status_code] = 1

        if url in url_counts:
            url_counts[url] += 1
        else:
            url_counts[url] = 1

    return status_counts, url_counts

