from typing import List

def longest_balanced_subarray(arr: List[int]) -> int:
    prefix_sum = 0
    prefix_sum_indices = {0: -1}
    max_length = 0

    for index, num in enumerate(arr):
        prefix_sum += num

        if prefix_sum in prefix_sum_indices:
            max_length = max(max_length, index - prefix_sum_indices[prefix_sum])
        else:
            prefix_sum_indices[prefix_sum] = index

    return max_length

