def basic_calculator(expression: str) -> int:
    """
    Evaluates a simple arithmetic expression.
    """
    def operate(op, second, first):
        if op == '+':
            return first + second
        elif op == '-':
            return first - second
        elif op == '*':
            return first * second
        elif op == '/':
            return int(first / second) # python behaves like truncating towards zero for negative

    # Removing all whitespaces from the expression to handle the simpler string
    expression = expression.replace(" ", "")
    stack = []
    current_number = 0
    current_operator = '+'

    i = 0
    while i < len(expression):
        char = expression[i]

        if char.isdigit():
            current_number = current_number * 10 + int(char)

        # if char is an operator or it's the last character in the expression
        if char in "+-*/" or i == len(expression) - 1:
            if current_operator == '+':
                stack.append(current_number)
            elif current_operator == '-':
                stack.append(-current_number)
            elif current_operator in "*/":
                last = stack.pop()
                stack.append(operate(current_operator, current_number, last))

            current_operator = char
            current_number = 0

        i += 1

    return sum(stack)

