def shift_encrypt(shift, message):
    """
    Encrypt the given message using the Shift Cipher with the given shift value.

    Args:
    shift (int): The number of positions to shift each letter.
    message (str): The message to encrypt.

    Returns:
    str: The encrypted message.
    """
    encrypted_message = []

    for char in message:
        if char.isalpha():
            if char.islower():
                new_char = chr(((ord(char) - 97 + shift) % 26) + 97)
            else:
                new_char = chr(((ord(char) - 65 + shift) % 26) + 65)
            encrypted_message.append(new_char)
        else:
            encrypted_message.append(char)

    return ''.join(encrypted_message)


def shift_decrypt(shift, message):
    """
    Decrypt the given message using the Shift Cipher with the given shift value.

    Args:
    shift (int): The number of positions to shift each letter back.
    message (str): The message to decrypt.

    Returns:
    str: The decrypted message.
    """
    return shift_encrypt(-shift, message)

from typing import List

def apply_filter(image: List[List[int]], filter_name: str) -> List[List[int]]:
    if filter_name not in {"invert", "lighten", "darken", "threshold"}:
        raise ValueError(f"Invalid filter name: {filter_name}")

    if filter_name == "invert":
        return [[255 - pixel for pixel in row] for row in image]

    if filter_name == "lighten":
        return [[min(pixel + 50, 255) for pixel in row] for row in image]

    if filter_name == "darken":
        return [[max(pixel - 50, 0) for pixel in row] for row in image]

    if filter_name == "threshold":
        return [[255 if pixel > 128 else 0 for pixel in row] for row in image]

