def longest_common_subsequence(A: str, B: str) -> int:
    m = len(A)
    b = len(B)

    # Create a 2D array to store the length of LCS
    dp = [[0] * (b+1) for _ in range(m+1)]

    # Fill the dp array
    for i in range(m+1):
        for j in range(b+1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif A[i-1] == B[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # The value in dp[m][b] contains the length of LCS of A and B
    return dp[m][b]

