from typing import List

def group_anagrams(strs: List[str]) -> List[List[str]]:
    anagram_dict = {}
    for word in strs:
        sorted_word = ''.join(sorted(word))
        if sorted_word in anagram_dict:
            anagram_dict[sorted_word].append(word)
        else:
            anagram_dict[sorted_word] = [word]

    result = list(anagram_dict.values())
    return result

def spell_check(input_text: str, dictionary: set) -> list:
    from difflib import get_close_matches

    def edit_distance_one(word, dictionary):
        """Finds words in the dictionary that are one edit distance away from the given word."""
        suggestions = []
        for dic_word in dictionary:
            if len(dic_word) == len(word) and sum(1 for a, b in zip(dic_word, word) if a != b) == 1:
                suggestions.append(dic_word)
            elif abs(len(dic_word) - len(word)) == 1:
                if len(dic_word) > len(word) and any(dic_word[:i]+dic_word[i+1:] == word for i in range(len(dic_word))):
                    suggestions.append(dic_word)
                elif len(dic_word) < len(word) and any(word[:i]+word[i+1:] == dic_word for i in range(len(word))):
                    suggestions.append(dic_word)
        return suggestions

    dictionary_lower = {word.lower() for word in dictionary}
    input_words = input_text.split()

    misspelled_words = []

    for word in input_words:
        if word.lower() not in dictionary_lower:
            suggestions = get_close_matches(word.lower(), dictionary_lower, n=3, cutoff=0.8)
            suggestions.extend(edit_distance_one(word.lower(), dictionary_lower))
            suggestions = list(set(suggestions))  # Remove duplicates
            misspelled_words.append((word, suggestions))

    return misspelled_words

def add_word_to_dictionary(word: str, dictionary: set):
    """
    Adds a word to the dictionary in a case-insensitive manner.
    """
    dictionary.add(word.lower())

