from typing import List

def mergeIntervals(intervals: List[List[int]]) -> List[List[int]]:
    if not intervals:
        return []

    # Sort intervals by the starting time
    intervals.sort(key=lambda x: x[0])
    merged = [intervals[0]]

    for current in intervals[1:]:
        previous = merged[-1]

        if current[0] <= previous[1]:
            # There is an overlap, hence merge the intervals
            merged[-1] = [previous[0], max(previous[1], current[1])]
        else:
            # No overlap, add to the result
            merged.append(current)

    return merged

from typing import List

def find_min_time_difference(times: List[str]) -> int:
    if len(times) < 2:
        return 0

    def time_to_minutes(t: str) -> int:
        h, m = map(int, t.split(':'))
        return h * 60 + m

    minutes = sorted(time_to_minutes(t) for t in times)
    minutes.append(minutes[0] + 24 * 60)  # Account for the wrap-around scenario

    min_diff = float('inf')
    for i in range(1, len(minutes)):
        min_diff = min(min_diff, minutes[i] - minutes[i-1])

    return min_diff

