import re
from collections import defaultdict

def count_atoms(formula: str) -> dict:
    def parse():
        stack = [defaultdict(int)]
        i, n = 0, len(formula)
        while i < n:
            if formula[i] == '(' or formula[i] == '[':
                stack.append(defaultdict(int))
                i += 1
            elif formula[i] == ')' or formula[i] == ']':
                top = stack.pop()
                i += 1
                i_start = i
                while i < n and formula[i].isdigit():
                    i += 1
                multiply = int(formula[i_start:i] or 1)
                for element in top:
                    stack[-1][element] += top[element] * multiply
            else:
                i_start = i
                i += 1
                while i < n and formula[i].islower():
                    i += 1
                element = formula[i_start:i]
                i_start = i
                while i < n and formula[i].isdigit():
                    i += 1
                count = int(formula[i_start:i] or 1)
                stack[-1][element] += count
        return stack.pop()

    return dict(parse())

