def bitwise_and_sum(list1: list[int], list2: list[int]) -> int:
    """
    Returns the sum of all bitwise AND computations between pairs of
    integers from list1 and list2.
    """
    total_sum = 0
    for i in list1:
        for j in list2:
            total_sum += i & j
    return total_sum

