def longest_subsequence_with_diff(arr, diff):
    """
    Finds the length of the longest subsequence such that the absolute difference between any
    two consecutive elements is less than or equal to the given difference.

    :param arr: List of integers
    :param diff: Maximum allowed difference between consecutive elements in the subsequence
    :return: Length of the longest subsequence meeting the difference constraint
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n  # dp[i] will store the length of the longest subsequence ending at index i

    for i in range(n):
        for j in range(i):
            if abs(arr[i] - arr[j]) <= diff:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

