def find_common_elements(matrix1: List[List[int]], matrix2: List[List[int]]) -> List[int]:
    # Flatten both matrices into sets of unique elements
    set1 = {element for row in matrix1 for element in row}
    set2 = {element for row in matrix2 for element in row}

    # Find the intersection of both sets
    common_elements = set1.intersection(set2)

    # Convert to a sorted list and return
    return sorted(common_elements)

