from typing import List, Tuple

def find_unsorted_subarray(nums: List[int]) -> Tuple[int, int]:
    n = len(nums)
    start, end = 0, -1
    max_seen, min_seen = float('-inf'), float('inf')

    # Traverse from the start to identify the end of the window
    for i in range(n):
        max_seen = max(max_seen, nums[i])
        if nums[i] < max_seen:
            end = i

    # Traverse from the end to identify the start of the window
    for i in range(n - 1, -1, -1):
        min_seen = min(min_seen, nums[i])
        if nums[i] > min_seen:
            start = i

    if end == -1:
        # The array is already sorted
        return (-1, -1)
    else:
        return (start, end)

