from typing import List, Tuple

def analyze_rainfall(data: List[Tuple[str, float]]) -> Tuple[float, str, str]:
    if not data:
        return (0, "", "")

    total_rainfall = 0.0
    max_rainfall = float('-inf')
    min_rainfall = float('inf')
    max_date = ''
    min_date = ''

    for date, rainfall in data:
        total_rainfall += rainfall

        if rainfall > max_rainfall:
            max_rainfall = rainfall
            max_date = date

        if rainfall < min_rainfall:
            min_rainfall = rainfall
            min_date = date

    return (total_rainfall, max_date, min_date)

