def depth_first_search(graph: dict, start_node: int) -> list:
    visited = []
    stack = [start_node]

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.append(node)
            # Add neighbors in reverse order to visit them in the correct sequence
            stack.extend(reversed(graph.get(node, [])))

    return visited

