def sum_of_digits_until_single_digit(number: int) -> int:
    """
    Given a non-negative integer, repeatedly sum its digits until a single-digit result is obtained.
    Returns the single-digit result.
    """
    if not isinstance(number, int):
        raise TypeError("Input value must be a 'int' type")
    if number == 0:
        return 0
    return 1 + (number - 1) % 9 if number > 0 else 0

