def is_prime(n):
    """
    Helper function to check if a number n is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while (i * i) <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_safe_prime_sequence(terms: int) -> list[int]:
    """
    Generate the first `terms` Safe Prime numbers.
    """
    if terms <= 0:
        raise ValueError("Number of terms must be a positive integer")

    safe_primes = []
    i = 1
    while len(safe_primes) < terms:
        if is_prime(i) and is_prime(2 * i + 1):
            safe_primes.append(2 * i + 1)
        i += 1
    return safe_primes

