def is_ascii_balanced(s: str) -> bool:
    """
    Determines if the average ASCII value of characters in the string s is an integer.
    """
    if not s:
        return False  # Return False for empty string as input constraints ensure 1 <= len(s)

    total_ascii_value = sum(ord(char) for char in s)
    return total_ascii_value % len(s) == 0

