from typing import Dict, List

def parse_email(email_text: str) -> Dict[str, str]:
    """
    Parse the email text to extract and return the subject and body.
    """
    lines = email_text.strip().split("\n")
    subject = ""
    body = []
    if lines:
        subject = lines[0].replace("Subject:", "").strip()
        body = lines[1:]
    body = "\n".join(body).replace("Body:", "").strip()
    return {"subject": subject, "body": body}

def categorize_email(email: Dict[str, str], categories: Dict[str, List[str]]) -> str:
    """
    Categorize the email based on keywords found in the subject or body.
    """
    for category, keywords in categories.items():
        for keyword in keywords:
            if keyword.lower() in email["subject"].lower() or keyword.lower() in email["body"].lower():
                return category
    return "Uncategorized"   # default category when no keywords match

