from typing import List

def moving_average(sequence: List[int], window_size: int) -> List[float]:
    if not sequence or window_size <= 0:
        return []

    result = []
    window_sum = 0

    for i in range(len(sequence)):
        if i < window_size:
            window_sum += sequence[i]
            result.append(window_sum / (i + 1))
        else:
            window_sum += sequence[i] - sequence[i - window_size]
            result.append(window_sum / window_size)

    return result

