from typing import List, Dict

def assign_tasks(tasks: List[str], workers: List[str]) -> Dict[str, List[str]]:
    # Initialize a dictionary with worker names as keys and empty lists as values
    task_distribution = {worker: [] for worker in workers}

    # Assign each task to a worker in a round-robin fashion
    for i, task in enumerate(tasks):
        worker = workers[i % len(workers)]
        task_distribution[worker].append(task)

    return task_distribution

