def count_paths(maze):
    """
    Finds the number of distinct paths from the top-left to bottom-right in a grid-based maze.
    """
    # If start or end point is blocked, return 0
    m, n = len(maze), len(maze[0])
    if maze[0][0] == 1 or maze[m-1][n-1] == 1:
        return 0

    # Create a DP table to store path counts
    dp = [[0] * n for _ in range(m)]

    # Initialize the starting point
    dp[0][0] = 1

    # Fill the DP table
    for i in range(m):
        for j in range(n):
            if maze[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

