import heapq
from typing import List, Dict, Tuple

def find_shortest_path(
    servers: List[str],
    latencies: Dict[Tuple[str, str], float],
    start_server: str,
    end_server: str
) -> Tuple[List[str], float]:
    def dijkstra(graph, start, goal):
        queue = []
        heapq.heappush(queue, (0, start))
        distances = {server: float('inf') for server in servers}
        previous_nodes = {server: None for server in servers}
        distances[start] = 0

        while queue:
            current_distance, current_node = heapq.heappop(queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node].items():
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous_nodes[neighbor] = current_node
                    heapq.heappush(queue, (distance, neighbor))

        # Reconstruct the shortest path
        path = []
        current = goal
        while previous_nodes[current] is not None:
            path.insert(0, current)
            current = previous_nodes[current]
        if path:
            path.insert(0, start)

        return path, distances[goal]

    # Create graph representation
    graph = {server: {} for server in servers}
    for (src, dst), latency in latencies.items():
        graph[src][dst] = latency

    return dijkstra(graph, start_server, end_server)

from typing import List

def longest_increasing_path(grid: List[List[int]]) -> int:
    M = len(grid)
    N = len(grid[0])

    if M == 0 or N == 0:
        return 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    dp = [[-1 for _ in range(N)] for _ in range(M)]

    def dfs(x, y):
        if dp[x][y] != -1:
            return dp[x][y]

        max_length = 1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < M and 0 <= ny < N and grid[nx][ny] > grid[x][y]:
                length = 1 + dfs(nx, ny)
                max_length = max(max_length, length)

        dp[x][y] = max_length
        return dp[x][y]

    max_path = 0
    for i in range(M):
        for j in range(N):
            max_path = max(max_path, dfs(i, j))

    return max_path

