def fibonacci_matrix_exponentiation(n: int) -> int:
    """
    Calculates the n-th Fibonacci number using matrix exponentiation.

    Args:
        n: The position in the Fibonacci sequence to compute.

    Returns:
        An integer, the n-th Fibonacci number.
    """

    def matrix_mult(A, B):
        return [
            [A[0][0]*B[0][0] + A[0][1]*B[1][0], A[0][0]*B[0][1] + A[0][1]*B[1][1]],
            [A[1][0]*B[0][0] + A[1][1]*B[1][0], A[1][0]*B[0][1] + A[1][1]*B[1][1]]
        ]

    def matrix_pow(matrix, power):
        result = [[1, 0], [0, 1]] # Identity matrix
        base = matrix

        while power:
            if power % 2 == 1:
                result = matrix_mult(result, base)
            base = matrix_mult(base, base)
            power //= 2

        return result

    F = [[1, 1], [1, 0]]

    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        result = matrix_pow(F, n-1)
        return result[0][0]

from typing import List

def sum_of_unique_elements(numbers: List[int]) -> int:
    """
    Returns the sum of unique elements in the list.
    """
    elements_count = {}

    # Count the occurrences of each element
    for number in numbers:
        if number in elements_count:
            elements_count[number] += 1
        else:
            elements_count[number] = 1

    # Sum up the elements that occur exactly once
    unique_sum = sum(number for number, count in elements_count.items() if count == 1)

    return unique_sum

