from typing import List

def num_islands(grid: List[List[str]]) -> int:
    if not grid:
        return 0

    def dfs(r, c):
        if r < 0 or c < 0 or r >= len(grid) or c >= len(grid[0]) or grid[r][c] == '0':
            return
        grid[r][c] = '0'  # Mark the cell as visited by sinking the island to water.
        # Call DFS recursively for all the four adjacent cells.
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    num_of_islands = 0
    for row in range(len(grid)):
        for col in range(len(grid[0])):
            if grid[row][col] == '1':  # Start a DFS from this cell
                num_of_islands += 1
                dfs(row, col)

    return num_of_islands

def comb_sort(arr: list[int]) -> list[int]:
    if not isinstance(arr, list):
        raise TypeError("Input must be a list of integers.")
    for item in arr:
        if not isinstance(item, int):
            raise ValueError("All elements of the list must be integers.")

    n = len(arr)
    gap = n
    shrink = 1.3
    sorted = False

    while not sorted:
        gap = int(gap // shrink)
        if gap <= 1:
            gap = 1
            sorted = True

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                sorted = False

    return arr

