from typing import List

def package_items(weights: List[int], max_weight: int) -> List[List[int]]:
    """
    Distributes the items into packages such that no package exceeds the max_weight.
    """
    # Sort weights in descending order for easier packaging
    weights.sort(reverse=True)

    packages = []

    for weight in weights:
        placed = False
        for package in packages:
            if sum(package) + weight <= max_weight:
                package.append(weight)
                placed = True
                break

        if not placed:
            # Start a new package if it couldn't be placed in existing ones
            packages.append([weight])

    return packages

