from typing import List

def find_equilibrium_index(arr: List[int]) -> int:
    total_sum = sum(arr)
    left_sum = 0

    for i, value in enumerate(arr):
        total_sum -= value

        if left_sum == total_sum:
            return i

        left_sum += value

    return -1

