from typing import List

def matrix_product(matrix_a: List[List[int]], matrix_b: List[List[int]]) -> List[List[int]]:
    n = len(matrix_a)

    # Initialize the result matrix with zeros
    result = [[0] * n for _ in range(n)]

    # Perform matrix multiplication
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] += matrix_a[i][k] * matrix_b[k][j]

    return result

from typing import List

def longest_increasing_subsequence(arr: List[int]) -> int:
    if not isinstance(arr, list):
        raise TypeError("Input must be a list.")
    if any(not isinstance(x, int) for x in arr):
        raise ValueError("All elements in the list must be integers.")

    if not arr:
        return 0

    # Creating an array to store our sub-problems, initialized to 1
    dp = [1] * len(arr)

    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest increasing subsequence will be the maximum value in dp
    return max(dp)

