def is_one_edit_distance(s: str, t: str) -> bool:
    """
    Check if two strings s and t are one edit distance apart.
    """
    if s == t:
        return False

    len_s, len_t = len(s), len(t)

    # If the length difference is more than 1, they cannot be one edit distance apart
    if abs(len_s - len_t) > 1:
        return False

    # Make sure s is the shorter string or same length as t
    if len_s > len_t:
        s, t = t, s
        len_s, len_t = len_t, len_s

    found_difference = False
    i, j = 0, 0

    while i < len_s and j < len_t:
        if s[i] != t[j]:
            if found_difference:
                return False
            found_difference = True
            if len_s == len_t:
                i += 1 # If replace we move both pointers
        else:
            i += 1
        j += 1

    # If we finished the loop normally, it means there was at most one edit
    return True

