import heapq
from typing import List, Tuple, Dict

def shortest_path(edges: List[Tuple[str, str, int]], start_node: str, end_node: str) -> List[str]:
    graph = {}

    # Create the graph as an adjacency list
    for src, dst, weight in edges:
        if src not in graph:
            graph[src] = []
        if dst not in graph:
            graph[dst] = []
        graph[src].append((dst, weight))

    # Priority queue for Dijkstra's algorithm
    queue = [(0, start_node, [])]  # (current_distance, current_node, path_taken)
    visited = set()
    distances = {node: float('inf') for node in graph}
    distances[start_node] = 0

    while queue:
        current_distance, current_node, path = heapq.heappop(queue)

        if current_node in visited:
            continue

        path = path + [current_node]

        if current_node == end_node:
            return path

        visited.add(current_node)

        for neighbor, weight in graph[current_node]:
            if neighbor in visited:
                continue

            new_distance = current_distance + weight

            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                heapq.heappush(queue, (new_distance, neighbor, path))

    return []

