from typing import List
import heapq
import sys

def dijkstra(adjacency_matrix: List[List[int]], start: int, end: int) -> int:
    n = len(adjacency_matrix)
    dist = [sys.maxsize] * n
    dist[start] = 0
    visited = [False] * n
    min_heap = [(0, start)]

    while min_heap:
        current_dist, u = heapq.heappop(min_heap)

        if visited[u]:
            continue

        visited[u] = True

        for v in range(n):
            if adjacency_matrix[u][v] != float('inf') and not visited[v]:
                if current_dist + adjacency_matrix[u][v] < dist[v]:
                    dist[v] = current_dist + adjacency_matrix[u][v]
                    heapq.heappush(min_heap, (dist[v], v))

    return dist[end] if dist[end] != sys.maxsize else -1

import heapq

def trap_water(matrix: list[list[int]]) -> int:
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])
    visited = [[False] * n for _ in range(m)]
    pq = []

    # initialize the priority queue with all the border cells
    for i in range(m):
        for j in range(n):
            if i == 0 or i == m - 1 or j == 0 or j == n - 1:
                heapq.heappush(pq, (matrix[i][j], i, j))
                visited[i][j] = True

    water_trapped = 0
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while pq:
        height, x, y = heapq.heappop(pq)

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                visited[nx][ny] = True
                water_trapped += max(0, height - matrix[nx][ny])
                heapq.heappush(pq, (max(height, matrix[nx][ny]), nx, ny))

    return water_trapped

