from threading import Lock
from threading import Thread

def simulate_banking(balance: int, operations: list) -> int:
    lock = Lock()

    def process_operation(operation):
        nonlocal balance
        operation_type = operation.get("type")
        amount = operation.get("amount")

        if not isinstance(amount, int) or amount <= 0:
            return
        if operation_type not in ["deposit", "withdrawal"]:
            return

        with lock:
            if operation_type == "deposit":
                balance += amount
            elif operation_type == "withdrawal" and balance >= amount:
                balance -= amount

    threads = []
    for operation in operations:
        thread = Thread(target=process_operation, args=(operation,))
        thread.start()
        threads.append(thread)

    for thread in threads:
        thread.join()

    return balance

from typing import List, Dict, Any

def top_genres(book_data: List[Dict[str, Any]]) -> List[str]:
    # Dictionary to keep count of genres
    genre_count = {}

    # Calculate the total count of each genre
    for book in book_data:
        for genre in book['genres']:
            if genre in genre_count:
                genre_count[genre] += 1
            else:
                genre_count[genre] = 1

    # Sort genres based on their popularity in descending order
    sorted_genres = sorted(genre_count.items(), key=lambda x: x[1], reverse=True)

    # Extract the top 3 genres
    top_3_genres = [genre for genre, count in sorted_genres[:3]]

    return top_3_genres

