def fib_iterative(n):
    """
    Returns the nth Fibonacci number using an iterative approach.
    """
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def fib_recursive(n):
    """
    Returns the nth Fibonacci number using a recursive approach.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fib_recursive(n - 1) + fib_recursive(n - 2)

def get_fibonacci_number(n):
    """
    Returns the nth Fibonacci number using both iterative and recursive methods.
    """
    return fib_iterative(n), fib_recursive(n)

