def reverse_string_base(n: str, base: int) -> str:
    # Reverse the string n
    reversed_n = n[::-1]

    # Convert the reversed string to an integer given the base
    integer_value = int(reversed_n, base)

    # Convert the integer back to a string in the original base
    if base == 2:
        return bin(integer_value)[2:]  # Remove '0b' prefix
    elif base == 8:
        return oct(integer_value)[2:]  # Remove '0o' prefix
    elif base == 10:
        return str(integer_value)      # No prefix for decimal
    elif base == 16:
        return hex(integer_value)[2:].upper()  # Remove '0x' prefix and use uppercase letters

    raise ValueError("Base must be one of [2, 8, 10, 16]")

