def count_connected_components(graph):
    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if current not in visited:
                visited.add(current)
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        stack.append(neighbor)

    visited = set()
    components = 0

    for node in graph:
        if node not in visited:
            dfs(node)
            components += 1

    return components

