from typing import List
import re

def validate_email_addresses(email_addresses: List[str]) -> None:
    invalid_spaces = []
    invalid_chars = []
    missing_at_symbol = []

    # Regex to match valid character portion of email (excluding `@` symbol).
    valid_char_pattern = re.compile(r'^[A-Za-z0-9._%+-]+$')

    for email in email_addresses:
        if email.strip() != email:  # Check for leading or trailing spaces
            invalid_spaces.append(email)
        elif '@' not in email:      # Check for missing `@` symbol
            missing_at_symbol.append(email)
        else:
            local, domain = email.split('@', 1)
            if not (valid_char_pattern.match(local) and valid_char_pattern.match(domain)):
                invalid_chars.append(email)

    invalid_count = len(invalid_spaces) + len(invalid_chars) + len(missing_at_symbol)

    if invalid_spaces:
        print(f"{len(invalid_spaces)} emails contain leading/trailing spaces:")
        for email in invalid_spaces:
            print(email)

    if invalid_chars:
        print(f"{len(invalid_chars)} emails contain invalid characters:")
        for email in invalid_chars:
            print(email)

    if missing_at_symbol:
        print(f"{len(missing_at_symbol)} emails are missing the @ symbol:")
        for email in missing_at_symbol:
            print(email)

    print(f"{invalid_count} invalid emails")
    raise ValueError(f"{invalid_count} invalid emails")

