def character_frequency_analysis(text: str) -> dict:
    """
    Analyzes the frequency of each alphanumeric character in the given text.

    Parameters:
    text (str): The input text to analyze

    Returns:
    dict: A dictionary with characters as keys and their respective counts as values
    """
    if not (1 <= len(text) <= 100000):
        raise ValueError("Input string must be between 1 and 100000 characters long.")

    frequency = {}
    for char in text:
        if char.isalnum():
            char = char.lower()
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

    return frequency

