from typing import List

def longest_piece(grid: List[List[int]]) -> int:
    n = len(grid)

    def get_max_len(sequence):
        max_len = cur_len = 1
        for i in range(1, len(sequence)):
            if sequence[i] == sequence[i-1]:
                cur_len += 1
            else:
                max_len = max(max_len, cur_len)
                cur_len = 1
        return max(max_len, cur_len)

    max_length = 0

    # Check horizontal pieces
    for row in grid:
        max_length = max(max_length, get_max_len(row))

    # Check vertical pieces
    for col in range(n):
        column = [grid[row][col] for row in range(n)]
        max_length = max(max_length, get_max_len(column))

    return max_length

from typing import List

def longest_common_suffix(strs: List[str]) -> str:
    if not strs:
        return ""

    # Reverse all strings in the list
    reversed_strs = [s[::-1] for s in strs]

    # Find the longest common prefix of the reversed strings
    longest_suffix = ""
    for chars in zip(*reversed_strs):
        if all(char == chars[0] for char in chars):
            longest_suffix += chars[0]
        else:
            break

    # Reverse the result to get the longest common suffix
    return longest_suffix[::-1]

