def count_encodings(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: an empty string has one way to be decoded

    for i in range(1, n + 1):
        # Check the last one digit
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]

        # Check the last two digits if they form a valid encoding
        if i > 1 and '10' <= s[i - 2:i] <= '26':
            dp[i] += dp[i - 2]

    return dp[n]

