def find_duplicates(file_names, file_contents):
    """
    Function to find duplicate files based on their content.

    Parameters:
        file_names (list of str): List containing the names of the files.
        file_contents (list of str): List containing the contents of the corresponding files.

    Returns:
        list of str: List of file names which have duplicate content.
    """
    content_to_files = {}

    for file_name, content in zip(file_names, file_contents):
        if content in content_to_files:
            content_to_files[content].append(file_name)
        else:
            content_to_files[content] = [file_name]

    duplicates = []
    for files in content_to_files.values():
        if len(files) > 1:
            duplicates.extend(files)

    return duplicates

def is_balanced(input_string: str) -> bool:
    if not input_string:
        raise ValueError("Input string cannot be empty")

    stack = []
    matching_bracket = {')': '(', ']': '[', '}': '{'}
    opening_brackets = matching_bracket.values()

    for char in input_string:
        if char in opening_brackets:
            stack.append(char)
        elif char in matching_bracket:
            if stack and stack[-1] == matching_bracket[char]:
                stack.pop()
            else:
                return False

    return not stack

def find_median_sorted_arrays(nums1: [int], nums2: [int]) -> float:
    def merge(arr1, arr2):
        sorted_arr = []
        i = j = 0
        while i < len(arr1) and j < len(arr2):
            if arr1[i] < arr2[j]:
                sorted_arr.append(arr1[i])
                i += 1
            else:
                sorted_arr.append(arr2[j])
                j += 1
        sorted_arr.extend(arr1[i:])
        sorted_arr.extend(arr2[j:])
        return sorted_arr

    def find_median(sorted_arr):
        n = len(sorted_arr)
        mid = n // 2
        if n % 2 == 0:
            return (sorted_arr[mid - 1] + sorted_arr[mid]) / 2
        else:
            return sorted_arr[mid]

    merged_array = merge(nums1, nums2)
    return find_median(merged_array)

