def largest_connected_component(adj_matrix):
    def dfs(node):
        stack = [node]
        count = 0
        while stack:
            cur = stack.pop()
            if not visited[cur]:
                visited[cur] = True
                count += 1
                for neighbor in range(len(adj_matrix)):
                    if adj_matrix[cur][neighbor] == 1 and not visited[neighbor]:
                        stack.append(neighbor)
        return count

    n = len(adj_matrix)
    visited = [False] * n
    largest = 0

    for i in range(n):
        if not visited[i]:
            component_size = dfs(i)
            largest = max(largest, component_size)

    return largest

