from typing import List

def diagonal_traverse(matrix: List[List[int]]) -> List[int]:
    if not matrix or not matrix[0]:
        return []

    rows, cols = len(matrix), len(matrix[0])
    result = []
    intermediate = []

    for d in range(rows + cols - 1):
        intermediate.clear()

        r = 0 if d < cols else d - cols + 1
        c = d if d < cols else cols - 1

        while r < rows and c > -1:
            intermediate.append(matrix[r][c])
            r += 1
            c -= 1

        if d % 2 == 0:
            result.extend(intermediate[::-1])
        else:
            result.extend(intermediate)

    return result

def apply_discount(prices: dict, discount: float, threshold: float) -> dict:
    """
    Returns a dictionary with product prices after applying discount

    :param prices: A dictionary where keys are product names and values are their original prices.
    :param discount: A float representing the discount percentage to be applied.
    :param threshold: A float representing the price threshold above which the discount is applied.

    :return: A dictionary where keys are product names and values are the new prices after applying the discount.

    >>> apply_discount({}, 10.0, 100)
    {}

    >>> apply_discount({"product1": 150.0}, 10.0, 100)
    {'product1': 135.0}

    >>> apply_discount({"product1": 90.0, "product2": 200.0}, 20.0, 100)
    {'product1': 90.0, 'product2': 160.0}

    >>> apply_discount({"product1": 100.0, "product2": 100.0}, 50.0, 100)
    {'product1': 100.0, 'product2': 100.0}

    >>> apply_discount({"product1": 250.0, "product2": 350.0}, 10.0, 200)
    {'product1': 225.0, 'product2': 315.0}
    """
    if not isinstance(prices, dict):
        raise ValueError("Prices should be a dictionary")
    if not (isinstance(discount, (float, int)) and isinstance(threshold, (float, int))):
        raise ValueError("Discount and threshold should be floats or integers")

    discounted_prices = {}
    for product, price in prices.items():
        if price > threshold:
            new_price = price * (1 - discount / 100)
            discounted_prices[product] = round(new_price, 2)
        else:
            discounted_prices[product] = price
    return discounted_prices

