def flight_info_system(operations):
    flight_set = set()
    result = []

    for operation in operations:
        op_parts = operation.split()
        if op_parts[0] == "arrival":
            flight_set.add(op_parts[1])
        elif op_parts[0] == "depart":
            if op_parts[1] in flight_set:
                flight_set.remove(op_parts[1])
        elif op_parts[0] == "next_departure":
            if flight_set:
                result.append(min(flight_set))
        elif op_parts[0] == "current_flights":
            result.append(",".join(sorted(flight_set)))
        elif op_parts[0] == "clear":
            flight_set.clear()

    return result

def find_min_removals(s: str) -> tuple:
    """
    Given a string of parentheses, determine the minimum number of parentheses
    to remove to make it valid and return the resulting valid string.

    Args:
    s (str): A string containing only '(' and ')'.

    Returns:
    tuple: A tuple containing two elements:
           - An integer count of removed parentheses.
           - The resulting valid string.
    """
    stack = []
    indices_to_remove = set()

    # Determine the indices of invalid parentheses
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                indices_to_remove.add(i)

    while stack:
        indices_to_remove.add(stack.pop())

    # Build the resulting valid string
    result = []
    for i, char in enumerate(s):
        if i not in indices_to_remove:
            result.append(char)

    return (len(indices_to_remove), "".join(result))

