from typing import List

def custom_quick_sort(arr: List[int]) -> List[int]:
    if len(arr) <= 1:
        return arr

    mid_index = len(arr) // 2
    pivot = arr[mid_index]

    less_than_pivot = [x for x in arr if x < pivot]
    equal_to_pivot = [x for x in arr if x == pivot]
    greater_than_pivot = [x for x in arr if x > pivot]

    return custom_quick_sort(less_than_pivot) + equal_to_pivot + custom_quick_sort(greater_than_pivot)

