def filter_and_sort_evens(input_list: list) -> list:
    """
    Returns a new list containing only the even numbers from the original list, sorted in ascending order.
    Raises a TypeError if the input is not a list or contains non-integer elements.
    """
    if not isinstance(input_list, list):
        raise TypeError("Input must be a list of integers.")

    for item in input_list:
        if not isinstance(item, int):
            raise TypeError("Input must be a list of integers.")

    even_numbers = [num for num in input_list if num % 2 == 0]
    return sorted(even_numbers)

