def sieve_of_eratosthenes(limit: int) -> (list, int):
    """
    This function returns all prime numbers up to a given limit using the Sieve of Eratosthenes algorithm.
    It also returns the count of these prime numbers.
    """
    if limit < 2:
        return ([], 0)

    # Mark initial assumption: all numbers are prime
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not primes

    p = 2
    while p * p <= limit:
        if is_prime[p] == True:
            # Marking multiples of p as false starting from p*p and incrementing by p
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1

    # Collecting all prime numbers
    primes = [number for number, prime in enumerate(is_prime) if prime]
    return primes, len(primes)

