def three_sum_to_target(nums: list[int], target: int) -> bool:
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == target:
                return True
            elif total < target:
                left += 1
            else:
                right -= 1

    return False

