def min_time_to_complete_tasks(tasks, durations):
    from collections import defaultdict, deque

    # Detecting circular dependencies using Kahn's algorithm (Topological Sort)
    indegree = {task: 0 for task in tasks}
    graph = defaultdict(list)

    for task in tasks:
        for dependent in tasks[task]:
            indegree[dependent] += 1
            graph[task].append(dependent)

    # Queue for maintaining tasks with zero indegree
    zero_indegree_queue = deque([task for task in tasks if indegree[task] == 0])
    topo_order = []
    visited_count = 0

    while zero_indegree_queue:
        current_task = zero_indegree_queue.popleft()
        topo_order.append(current_task)
        visited_count += 1

        for dependent in graph[current_task]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                zero_indegree_queue.append(dependent)

    # Check for a cycle (if there are unvisited tasks)
    if visited_count != len(tasks):
        return -1

    # Calculate the minimum total time using the topological order
    completion_time = {task: 0 for task in tasks}

    for task in topo_order:
        task_duration = durations[task]
        # Update the completion time of dependents
        for dependent in tasks[task]:
            completion_time[dependent] = max(completion_time[dependent], completion_time[task] + task_duration)

    # The total time is the max completion time among all tasks
    total_time = max(completion_time[task] + durations[task] for task in tasks)

    return total_time

