def binary_search(arr: list, target: int) -> int:
    '''
    Perform a binary search on a sorted list `arr` to find the target value `target`.
    Return the target's index if found; otherwise, return -1.
    '''
    def helper(arr: list, target: int, low: int, high: int) -> int:
        if low <= high:
            mid = (low + high) // 2
            if arr[mid] == target:
                return mid
            elif arr[mid] < target:
                return helper(arr, target, mid + 1, high)
            else:
                return helper(arr, target, low, mid - 1)
        else:
            return -1

    return helper(arr, target, 0, len(arr) - 1)

