from typing import List, Tuple

def binary_search(arr: List[int], target: int) -> Tuple[int, int]:
    """
    Performs a binary search to find the index of the target value in the sorted list.
    Also returns the number of iterations it took to find the target.
    """
    left, right = 0, len(arr) - 1
    iterations = 0

    while left <= right:
        iterations += 1
        mid = (left + right) // 2
        if arr[mid] == target:
            return (mid, iterations)
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return (-1, iterations)

