def to_title_case(text: str) -> str:
    """
    Convert a given string to title case.
    """
    def capitalize(word):
        if word:
            return word[0].upper() + word[1:].lower()
        return word

    words = text.split(' ')
    return ' '.join(capitalize(word) for word in words)

