from typing import List, Tuple

def compute_scores(rallies: List[str]) -> Tuple[int, int]:
    score_a = 0
    score_b = 0

    for rally in rallies:
        if rally == 'A':
            score_a += 1
        elif rally == 'B':
            score_b += 1

    return score_a, score_b

def determine_winner(score_a: int, score_b: int, team_a: str, team_b: str) -> str:
    if score_a > score_b:
        return team_a
    elif score_b > score_a:
        return team_b
    else:
        return "Tie"

def track_volleyball_points(rallies: List[str], team_a: str, team_b: str) -> Tuple[int, int, str]:
    score_a, score_b = compute_scores(rallies)
    winner = determine_winner(score_a, score_b, team_a, team_b)
    return score_a, score_b, winner

