def add_sparse_matrices(matrix1: dict, matrix2: dict) -> dict:
    """
    Adds two sparse matrices and returns the resulting sparse matrix.

    :param matrix1: First sparse matrix
    :param matrix2: Second sparse matrix
    :return: Sum of matrix1 and matrix2 as a sparse matrix
    """
    result = {}

    # Add elements of matrix1 to result
    for key, value in matrix1.items():
        result[key] = value

    # Add elements of matrix2 to result, sum up if key already exists
    for key, value in matrix2.items():
        if key in result:
            result[key] += value
        else:
            result[key] = value

    # Remove entries where the sum is zero
    result = {key: value for key, value in result.items() if value != 0}

    return result

def transpose_sparse_matrix(matrix: dict) -> dict:
    """
    Computes the transpose of a sparse matrix.

    :param matrix: The sparse matrix to transpose
    :return: The transposed sparse matrix
    """
    transposed = {}

    for (row, col), value in matrix.items():
        transposed[(col, row)] = value

    return transposed

