def rotate_matrix_90_clockwise(matrix):
    """
    Rotates the given n x n matrix 90 degrees clockwise in place.
    """
    n = len(matrix)
    # First step: transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Second step: reverse each row
    for i in range(n):
        matrix[i].reverse()

