from typing import List, Tuple
from collections import defaultdict, Counter

def recommend_books(user_id: int, purchases: List[Tuple[int, int]]) -> List[int]:
    user_books = defaultdict(set)

    # Step 1: Build user-book purchase history
    for u_id, b_id in purchases:
        user_books[u_id].add(b_id)

    # Step 2: Extract the target user's purchased books
    target_books = user_books[user_id]

    # Step 3: Find books purchased by other users who have similar books with the target user
    recommended_books = Counter()
    for u_id, books in user_books.items():
        if u_id != user_id:
            common_books = target_books.intersection(books)
            if common_books:
                for book in books - target_books:
                    recommended_books[book] += 1

    # Step 4: Sort the recommended books by their frequency in descending order
    recommended_books = [book for book, count in recommended_books.most_common()]

    return recommended_books

