def process_operations(operations):
    """
    Process a list of operations and return the results of 'size' queries.

    :param operations: List of operations as strings ("append X", "pop", "size")
    :return: List of integers representing the results of 'size' operations
    """
    array = []
    size_results = []

    for operation in operations:
        if operation.startswith('append'):
            _, value = operation.split()
            array.append(int(value))
        elif operation == 'pop':
            if array:
                array.pop()
        elif operation == 'size':
            size_results.append(len(array))

    return size_results

