def flatten_list(nested_list):
    def _flatten_helper(nested_list, accumulator):
        """Tail-recursive helper function to flatten the list."""
        if not nested_list:
            return accumulator
        head, *tail = nested_list
        if isinstance(head, list):
            return _flatten_helper(head + tail, accumulator)
        else:
            return _flatten_helper(tail, accumulator + [head])

    return _flatten_helper(nested_list, [])

