def has_cycle(graph: dict) -> bool:
    """
    Check if the directed graph contains a cycle.

    :param graph: Dict representing the adjacency list of the graph.
    :return: Bool indicating whether the graph has a cycle.
    """
    def dfs(node):
        if node in rec_stack:
            return True
        if node in visited:
            return False

        visited.add(node)
        rec_stack.add(node)

        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        rec_stack.remove(node)
        return False

    visited = set()
    rec_stack = set()

    for node in graph:
        if dfs(node):
            return True

    return False

