import math

def filling_time(radius: float, height: float, flow_rate: float) -> float:
    if radius <= 0:
        raise ValueError("Radius must be positive.")
    if height <= 0:
        raise ValueError("Height must be positive.")
    if flow_rate <= 0:
        raise ValueError("Flow rate must be positive.")

    volume = math.pi * radius**2 * height  # Volume of the cylinder
    time_to_fill = volume / flow_rate  # Time required to fill the cylinder
    return round(time_to_fill, 2)

