def evaluate_expression(expression: str) -> int:
    """
    Evaluate a given arithmetic expression string and return its result,
    respecting the operator precedence and associativity.
    """
    def operate(a, b, operator):
        if operator == '+':
            return a + b
        elif operator == '-':
            return a - b
        elif operator == '*':
            return a * b
        elif operator == '/':
            return int(a / b)  # Use int() to perform integer division

    # Initialize variables to hold the current number and stack for operations
    num = 0
    stack = []
    op = '+'

    for i, ch in enumerate(expression):
        if ch.isdigit():
            num = num * 10 + int(ch)

        if ch in "+-*/" or i == len(expression) - 1:
            if op == '+':
                stack.append(num)
            elif op == '-':
                stack.append(-num)
            elif op == '*':
                stack.append(stack.pop() * num)
            elif op == '/':
                stack.append(int(stack.pop() / num))  # int() for truncation towards zero

            op = ch
            num = 0

    return sum(stack)

