def add_item(inventory: dict, item_name: str, quantity: int) -> dict:
    """
    Add a specific quantity of an item to the inventory.
    """
    if quantity <= 0:
        return inventory
    if item_name in inventory:
        inventory[item_name] += quantity
    else:
        inventory[item_name] = quantity
    return inventory

def remove_item(inventory: dict, item_name: str, quantity: int) -> dict:
    """
    Remove a specific quantity of an item from the inventory.
    """
    if quantity <= 0:
        return inventory
    if item_name in inventory:
        inventory[item_name] = max(inventory[item_name] - quantity, 0)
    return inventory

def check_stock(inventory: dict, item_name: str) -> int:
    """
    Check the stock level of a specific item.
    """
    return inventory.get(item_name, 0)

