def three_sum(nums, target):
    """
    Returns all unique triplets in the array which sum to the given target.
    """
    nums.sort()
    result = []
    n = len(nums)

    for i in range(n):
        # Avoid duplicates for the first element of the triplet
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, n - 1

        while left < right:
            sum_three = nums[i] + nums[left] + nums[right]

            if sum_three == target:
                result.append([ nums[i], nums[left], nums[right] ])

                # Avoid duplicates for the second element of the triplet
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                # Avoid duplicates for the third element of the triplet
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1

                left += 1
                right -= 1

            elif sum_three < target:
                left += 1
            else:
                right -= 1

    return result

