def count_occurrences(numbers: list[int]) -> dict[int, int]:
    """
    Returns a dictionary with the counts of each integer in the input list.
    """
    occurrence_dict = {}
    for number in numbers:
        if number in occurrence_dict:
            occurrence_dict[number] += 1
        else:
            occurrence_dict[number] = 1
    return occurrence_dict

