from typing import List
from collections import defaultdict, deque

def alien_order(words: List[str]) -> str:
    # Step 1: Create a graph and a dictionary to count in-degrees of each node
    graph = defaultdict(set)
    in_degree = {char: 0 for word in words for char in word}

    # Step 2: Build the graph by comparing adjacent words
    for i in range(len(words) - 1):
        first_word, second_word = words[i], words[i + 1]
        min_length = min(len(first_word), len(second_word))

        # Check if it's an invalid case where prefix is longer and equal to the next word
        if len(first_word) > len(second_word) and first_word.startswith(second_word):
            return ""

        for j in range(min_length):
            if first_word[j] != second_word[j]:
                if second_word[j] not in graph[first_word[j]]:
                    graph[first_word[j]].add(second_word[j])
                    in_degree[second_word[j]] += 1
                break

    # Step 3: Perform topological sort using Kahn's algorithm
    queue = deque([char for char in in_degree if in_degree[char] == 0])
    order = []

    while queue:
        current_char = queue.popleft()
        order.append(current_char)

        for neighbor in graph[current_char]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If the order contains all the characters, return it, otherwise return ""
    if len(order) == len(in_degree):
        return "".join(order)
    else:
        return ""

