from typing import List

def merge_sorted_arrays(arr1: List[int], arr2: List[int]) -> List[int]:
    """
    Merges two sorted lists of integers into one sorted list without duplicates.
    """
    merged = []
    i, j = 0, 0
    # Traverse both arrays
    while i < len(arr1) and j < len(arr2):
        # If element of arr1 is smaller, add it and move pointer
        if arr1[i] < arr2[j]:
            if not merged or merged[-1] != arr1[i]:
                merged.append(arr1[i])
            i += 1
        # If element of arr2 is smaller, add it and move pointer
        elif arr1[i] > arr2[j]:
            if not merged or merged[-1] != arr2[j]:
                merged.append(arr2[j])
            j += 1
        else:
            # If elements are equal, add any one and move both pointers
            if not merged or merged[-1] != arr1[i]:
                merged.append(arr1[i])
            i += 1
            j += 1

    # Add remaining elements from arr1
    while i < len(arr1):
        if not merged or merged[-1] != arr1[i]:
            merged.append(arr1[i])
        i += 1

    # Add remaining elements from arr2
    while j < len(arr2):
        if not merged or merged[-1] != arr2[j]:
            merged.append(arr2[j])
        j += 1

    return merged

def flatten_list(nested_list):
    """
    Flattens a nested list of integers, maintaining the order of elements.

    Args:
    nested_list (list): The input list containing nested lists of integers.

    Returns:
    list: A flattened list of integers.

    Raises:
    TypeError: If any elements in the nested lists are not integers.
    """
    def flatten_helper(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten_helper(item)
            elif isinstance(item, int):
                yield item
            else:
                raise TypeError("All elements must be integers within the nested lists")

    return list(flatten_helper(nested_list))

