from typing import List, Tuple
import heapq

def find_min_delivery_time(n: int, roads: List[Tuple[int, int, int]]) -> int:
    """
    Finds the minimum time required to deliver packages from city 1 to all other cities.

    Parameters:
    n (int): The number of cities.
    roads (List[Tuple[int, int, int]]): List of tuples representing roads between cities and travel times.

    Returns:
    int: The minimum time required to deliver packages from city 1 to all other cities.
    """
    # Create adjacency list representation of the graph
    adj = {i: [] for i in range(1, n + 1)}
    for u, v, t in roads:
        adj[u].append((v, t))
        adj[v].append((u, t))

    # Implement Dijkstra's Algorithm
    def dijkstra(start: int):
        dist = {i: float('inf') for i in range(1, n + 1)}
        dist[start] = 0
        min_heap = [(0, start)]  # (distance, city)

        while min_heap:
            current_dist, u = heapq.heappop(min_heap)

            if current_dist > dist[u]:
                continue

            for neighbor, weight in adj[u]:
                distance = current_dist + weight

                if distance < dist[neighbor]:
                    dist[neighbor] = distance
                    heapq.heappush(min_heap, (distance, neighbor))

        return dist

    distances = dijkstra(1)
    return max(distances.values())

