from typing import List, Tuple
import heapq

def find_max_capacity(num_warehouses: int, routes: List[Tuple[int, int, int]], start: int, destination: int) -> int:
    def dijkstra_max_capacity():
        max_capacity = [0] * num_warehouses
        max_capacity[start] = float('inf')

        # Max-heap to store the current capacity from the start node
        heap = [(-max_capacity[start], start)]

        while heap:
            current_capacity, u = heapq.heappop(heap)
            current_capacity = -current_capacity

            if u == destination:
                return current_capacity

            for v, edge_capacity in adj[u]:
                capacity = min(current_capacity, edge_capacity)
                if capacity > max_capacity[v]:
                    max_capacity[v] = capacity
                    heapq.heappush(heap, (-capacity, v))

        return 0

    # Adjacency list representation of the graph
    adj = [[] for _ in range(num_warehouses)]
    for u, v, capacity in routes:
        adj[u].append((v, capacity))
        adj[v].append((u, capacity))

    return dijkstra_max_capacity()

