from typing import List
from collections import deque, defaultdict

def word_ladder(begin_word: str, end_word: str, word_list: List[str]) -> int:
    """
    Returns the length of the shortest transformation sequence from begin_word to end_word using BFS.
    Each transformation changes exactly one letter and each intermediate word must be in the word_list.
    If no such transformation sequence exists, returns 0.
    """
    if end_word not in word_list:
        return 0

    # All words are of same length
    word_length = len(begin_word)

    # Create a dictionary to hold all possible intermediate states
    all_combo_dict = defaultdict(list)
    for word in word_list:
        for i in range(word_length):
            intermediate_word = word[:i] + "*" + word[i+1:]
            all_combo_dict[intermediate_word].append(word)

    # BFS to find the shortest path
    queue = deque([(begin_word, 1)])
    visited = {begin_word: True}

    while queue:
        current_word, level = queue.popleft()

        for i in range(word_length):
            intermediate_word = current_word[:i] + "*" + current_word[i+1:]

            for word in all_combo_dict[intermediate_word]:
                if word == end_word:
                    return level + 1
                if word not in visited:
                    visited[word] = True
                    queue.append((word, level + 1))
            all_combo_dict[intermediate_word] = []  # Clear intermediate words list to save memory

    return 0

