def find_subarray_with_sum(nums: list[int], k: int) -> int:
    if not isinstance(nums, list) or not all(isinstance(x, int) for x in nums):
        raise ValueError("nums must be a list of integers")
    if not isinstance(k, int):
        raise ValueError("k must be an integer")

    sum_dict = {}
    current_sum = 0
    min_length = float('inf')

    for i in range(len(nums)):
        current_sum += nums[i]

        if current_sum == k:
            min_length = min(min_length, i + 1)

        if (current_sum - k) in sum_dict:
            min_length = min(min_length, i - sum_dict[current_sum - k])

        if current_sum not in sum_dict:
            sum_dict[current_sum] = i

    return min_length if min_length != float('inf') else -1

