def can_accommodate_bookings(bookings, rooms):
    if not bookings:
        return True

    events = []
    for start, end in bookings:
        events.append((start, 1))  # 1 indicates a booking starts
        events.append((end, -1))   # -1 indicates a booking ends

    events.sort()

    current_rooms = 0
    for time, event in events:
        current_rooms += event
        if current_rooms > rooms:
            return False

    return True

