def longest_consecutive_sequence(grid):
    if not grid or not grid[0]:
        return 0

    def dfs(x, y):
        if (x, y) in memo:
            return memo[(x, y)]

        max_len = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == grid[x][y] + 1:
                max_len = max(max_len, 1 + dfs(nx, ny))

        memo[(x, y)] = max_len
        return max_len

    memo = {}
    return max(dfs(x, y) for x in range(len(grid)) for y in range(len(grid[0])))

