def character_frequency(string: str) -> dict:
    """
    Returns the frequency of each character in the string.
    """
    frequency = {}
    for char in string:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency

def reconstruct_string(char_freq: dict) -> str:
    """
    Reconstructs a string based on the given character frequency dictionary.
    """
    if not isinstance(char_freq, dict):
        raise ValueError("Input must be a dictionary.")

    reconstructed = []

    for char, freq in char_freq.items():
        if not isinstance(freq, int) or freq < 0:
            raise ValueError("Frequencies must be non-negative integers.")
        reconstructed.append(char * freq)

    return ''.join(reconstructed)

