def longest_common_substring(strings):
    def common_substring_between_two(s1, s2):
        len1, len2 = len(s1), len(s2)
        max_len = 0
        end_index = 0
        dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

        for i in range(1, len1 + 1):
            for j in range(1, len2 + 1):
                if s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    if dp[i][j] > max_len:
                        max_len = dp[i][j]
                        end_index = i

        return s1[end_index - max_len:end_index]

    if not strings:
        raise ValueError("Input list cannot be empty.")

    if len(strings) == 1:
        return strings[0]

    common_substr = strings[0]
    for i in range(1, len(strings)):
        common_substr = common_substring_between_two(common_substr, strings[i])
        if not common_substr:
            break

    return common_substr

