def merge_sorted_chunks(L):
    """
    This function merges a list of integers containing sorted chunks.
    """
    if not L:
        return []

    def merge(left, right):
        merged, i, j = [], 0, 0
        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                merged.append(left[i])
                i += 1
            else:
                merged.append(right[j])
                j += 1
        merged.extend(left[i:])
        merged.extend(right[j:])
        return merged

    def find_chunks(L):
        chunks = []
        start = 0
        for i in range(1, len(L)):
            if L[i] < L[i - 1]:
                chunks.append(L[start:i])
                start = i
        chunks.append(L[start:])
        return chunks

    chunks = find_chunks(L)
    while len(chunks) > 1:
        new_chunks = []
        for i in range(0, len(chunks), 2):
            if i + 1 < len(chunks):
                new_chunks.append(merge(chunks[i], chunks[i + 1]))
            else:
                new_chunks.append(chunks[i])
        chunks = new_chunks

    return chunks[0]

