def set_operation(operation: str, sets: list[set], element: int = None):
    """
    Performs set operations based on the input parameters.
    """
    if operation == "union" and len(sets) >= 2:
        return set.union(*sets)
    elif operation == "intersection" and len(sets) >= 2:
        return set.intersection(*sets)
    elif operation == "difference" and len(sets) == 2:
        return sets[0].difference(sets[1])
    elif operation == "symmetric_difference" and len(sets) == 2:
        return sets[0].symmetric_difference(sets[1])
    elif operation == "subset" and len(sets) == 2:
        return sets[0].issubset(sets[1])
    elif operation == "superset" and len(sets) == 2:
        return sets[0].issuperset(sets[1])
    elif operation == "cardinality" and len(sets) == 1:
        return len(sets[0])
    elif operation == "membership" and len(sets) == 1 and element is not None:
        return element in sets[0]
    return None

