from typing import List

def custom_sort(strings: List[str], custom_order: str) -> List[str]:
    # Create a priority dictionary based on custom order
    order_dict = {char: index for index, char in enumerate(custom_order)}

    # Define a custom key function for sorting
    def custom_key(word):
        # Convert each character in the string to its corresponding priority
        return [order_dict.get(char, len(custom_order)) for char in word]

    # Sort the strings using the custom key function, ensuring stability
    return sorted(strings, key=custom_key)

