from typing import List, Dict, Union

def evaluate_expressions(expressions: List[str]) -> Dict[str, Union[int, str]]:
    def validate_expression(expression: str) -> str:
        # Check if parentheses are balanced
        stack = []
        for char in expression:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack:
                    return "Syntax Error"
                stack.pop()
        if stack:
            return "Syntax Error"
        return ""

    def safe_eval(expression: str):
        try:
            result = eval(expression)
            if isinstance(result, (int, float)):
                return result
            else:
                return "Syntax Error"
        except:
            return "Syntax Error"

    results = {}
    for expr in expressions:
        validation_error = validate_expression(expr)
        if validation_error:
            results[expr] = validation_error
        else:
            results[expr] = safe_eval(expr)

    return results

