def longest_arith_seq_length(nums):
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    dp = [{} for _ in range(n)]
    max_length = 2

    for i in range(1, n):
        for j in range(i):
            diff = nums[i] - nums[j]

            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2  # a new sequence that starts with length 2

            max_length = max(max_length, dp[i][diff])

    return max_length

