def get_authors_by_award(books, award_name):
    """
    Returns a list of authors who have won the specified award.

    Parameters:
    books (list of dict): The list of books with authors.
    award_name (str): The name of the award to search for.

    Returns:
    list of str: The list of authors who have won the specified award.
    """
    authors_with_award = set()

    for book in books:
        for author in book['authors']:
            if award_name in author['awards']:
                authors_with_award.add(author['name'])

    return list(authors_with_award)

