def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for j in range(1, n + 1):
        if p[j-1] == '*':
            dp[0][j] = dp[0][j-1]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j-1] == '*':
                dp[i][j] = dp[i-1][j] or dp[i][j-1]
            elif p[j-1] == '?' or p[j-1] == s[i-1]:
                dp[i][j] = dp[i-1][j-1]

    return dp[m][n]

def min_moves_to_balance(s: str) -> int:
    """
    Returns the minimum number of moves required to balance the parentheses string.
    Each move can either involve inserting a parenthesis or removing an existing one.
    """
    left_unbalanced = 0
    right_unbalanced = 0

    for char in s:
        if char == '(':
            left_unbalanced += 1
        else:  # char == ')'
            if left_unbalanced > 0:
                left_unbalanced -= 1
            else:
                right_unbalanced += 1

    return left_unbalanced + right_unbalanced

def encode_rle(data: str) -> str:
    """
    Encodes the given string using Run-Length Encoding (RLE).

    :param data: The input string to encode.
    :return: The RLE-encoded string.
    """
    if not data:
        return ""

    encoded = []
    count = 1
    prev_char = data[0]

    for char in data[1:]:
        if char == prev_char:
            count += 1
        else:
            encoded.append(f"{count}{prev_char}")
            count = 1
            prev_char = char

    encoded.append(f"{count}{prev_char}")  # Don't forget the last run
    return "".join(encoded)

def decode_rle(encoded: str) -> str:
    """
    Decodes a Run-Length Encoded (RLE) string.

    :param encoded: The RLE-encoded string.
    :return: The original uncompressed string.
    """
    if not encoded:
        return ""

    decoded = []
    count = ""

    for char in encoded:
        if char.isdigit():
            count += char
        else:
            decoded.append(char * int(count))
            count = ""

    return "".join(decoded)

