def detect_cycle_in_graph(graph):
    """
    Detects if a directed graph contains any cycles using DFS.
    """
    def dfs(node):
        if node in recursion_stack:
            return True  # Cycle detected
        if node in visited:
            return False

        visited.add(node)
        recursion_stack.add(node)

        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        recursion_stack.remove(node)
        return False

    visited = set()
    recursion_stack = set()

    for node in graph:
        if node not in visited:
            if dfs(node):
                return True

    return False

