from typing import List
from collections import deque

def word_ladder(start: str, end: str, dictionary: List[str]) -> int:
    if end not in dictionary:
        return -1

    word_set = set(dictionary)
    queue = deque([(start, 1)])  # (current word, current length of transformation sequence)

    # BFS
    while queue:
        current_word, length = queue.popleft()

        if current_word == end:
            return length

        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if c != current_word[i]:
                    next_word = current_word[:i] + c + current_word[i+1:]
                    if next_word in word_set:
                        word_set.remove(next_word)
                        queue.append((next_word, length + 1))

    return -1

def rotate_matrix(matrix: list[list[int]]) -> None:
    """
    Rotate the given n x n matrix by 90 degrees clockwise in-place.

    :param matrix: 2D list of integers
    """
    n = len(matrix)

    # Step 1: Transpose the matrix (swap rows with columns)
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Step 2: Reverse each row
    for i in range(n):
        matrix[i].reverse()

