def is_balanced(s: str, pairs: dict) -> bool:
    # Dictionary to quickly lookup closing brackets
    opening_brackets = pairs.keys()
    closing_brackets = pairs.values()
    matching_brackets = {closing: opening for opening, closing in pairs.items()}

    stack = []

    for char in s:
        if char in opening_brackets:
            stack.append(char)
        elif char in closing_brackets:
            if stack and stack[-1] == matching_brackets[char]:
                stack.pop()
            else:
                return False

    return len(stack) == 0

