def count_item_frequency(transactions: list[list[str]]) -> dict[str, int]:
    """
    Counts the frequency of each item in the list of transactions.

    :param transactions: List of lists of items representing transactions.
    :return: Dictionary with item names as keys and their frequencies as values.

    Example:
    >>> count_item_frequency([["apple", "banana"], ["banana", "carrot"], ["apple", "carrot", "banana"]])
    {'apple': 2, 'banana': 3, 'carrot': 2}
    >>> count_item_frequency([["apple"], ["banana"], ["apple", "banana"], ["banana", "banana"]])
    {'apple': 2, 'banana': 4}
    >>> count_item_frequency([["milk", "bread"], ["milk"], ["bread"]])
    {'milk': 2, 'bread': 2}
    >>> count_item_frequency([[]])
    {}
    """
    frequency = {}
    for transaction in transactions:
        for item in transaction:
            if item in frequency:
                frequency[item] += 1
            else:
                frequency[item] = 1
    return frequency

