def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def is_anagram(n1, n2):
    return sorted(str(n1)) == sorted(str(n2))

def are_prime_anagrams(num1, num2):
    return is_prime(num1) and is_prime(num2) and is_anagram(num1, num2)

