def find_anagram_pairs(words: list[str]) -> list[list[str]]:
    from collections import defaultdict

    # A dictionary to store the sorted tuple of characters as key and original words as values
    anagrams = defaultdict(list)

    # Iterate over each word and add it to the correct list in the dictionary
    for word in words:
        sorted_word = ''.join(sorted(word.lower()))  # Sort characters alphabetically and convert to lower case
        anagrams[sorted_word].append(word)

    # Generate pairs of anagrams from the lists in the dictionary
    anagram_pairs = []
    for key, group in anagrams.items():
        for i in range(len(group)):
            for j in range(i + 1, len(group)):
                anagram_pairs.append([group[i], group[j]])

    return anagram_pairs

