from typing import List

def longest_arithmetic_subsequence(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    # dp dictionary to store subsequences and their lengths
    dp = {}

    max_len = 1

    for i in range(n):
        for j in range(i):
            diff = nums[i] - nums[j]
            if (j, diff) in dp:
                dp[(i, diff)] = dp[(j, diff)] + 1
            else:
                dp[(i, diff)] = 2
            max_len = max(max_len, dp[(i, diff)])

    return max_len

