def sort_products(products: List[Dict[str, Union[str, float]]]) -> List[Dict[str, Union[str, float]]]:
    """
    Sort a list of product dictionaries by price (ascending) and rating (descending).
    """
    required_keys = {'name', 'price', 'rating'}

    # Verify all products contain required keys
    for product in products:
        if not required_keys.issubset(product.keys()):
            raise ValueError(f"Product {product} is missing one of the required keys: 'name', 'price', 'rating'.")

    # Sort by price (ascending) and then by rating (descending)
    sorted_products = sorted(products, key=lambda x: (x['price'], -x['rating']))
    return sorted_products

def extract_integers_from_json(json_data):
    """
    Recursively extract all integer values from a nested JSON structure.

    Parameters:
    - json_data (dict): The JSON object to search within.

    Returns:
    - list[int]: A list of integers found in the JSON object.
    """
    integers = []

    def recurse(data):
        if isinstance(data, dict):
            for key, value in data.items():
                recurse(value)
        elif isinstance(data, list):
            for item in data:
                recurse(item)
        elif isinstance(data, int):
            integers.append(data)

    recurse(json_data)
    return integers

