def find_duplicate_emails(email_list):
    """
    Identifies duplicate email addresses from a list of email addresses and returns a dictionary
    where the keys are the duplicate email addresses and the values are the count of each email.

    :param email_list: List of email addresses
    :return: Dictionary with duplicate emails as keys and counts as values
    """
    email_count = {}
    for email in email_list:
        normalized_email = email.lower()
        if normalized_email in email_count:
            email_count[normalized_email] += 1
        else:
            email_count[normalized_email] = 1

    duplicates = {email: count for email, count in email_count.items() if count > 1}
    return duplicates

