def compress(input_str: str) -> str:
    if not input_str:
        return ""
    compressed = []
    count = 1
    for i in range(1, len(input_str) + 1):
        if i < len(input_str) and input_str[i] == input_str[i - 1]:
            count += 1
        else:
            compressed.append(input_str[i - 1] + str(count))
            count = 1
    return "".join(compressed)

def decompress(input_compressed: str) -> str:
    if not input_compressed:
        return ""
    decompressed = []
    i = 0
    while i < len(input_compressed):
        char = input_compressed[i]
        count = ""
        i += 1
        while i < len(input_compressed) and input_compressed[i].isdigit():
            count += input_compressed[i]
            i += 1
        decompressed.append(char * int(count))
    return "".join(decompressed)

