def fraction_to_decimal(numerator: int, denominator: int) -> str:

    if numerator == 0:
        return '0'

    # Determine sign of the result
    sign = '-' if (numerator * denominator) < 0 else ''

    # Work with absolute values to simplify
    numerator, denominator = abs(numerator), abs(denominator)

    # Initial integer part of the fraction
    integer_part = numerator // denominator
    remainder = numerator % denominator

    if remainder == 0:
        return sign + str(integer_part)

    decimal_part = []
    remainder_map = {}

    while remainder != 0:
        if remainder in remainder_map:
            index = remainder_map[remainder]
            decimal_part.insert(index, '(')
            decimal_part.append(')')
            break

        remainder_map[remainder] = len(decimal_part)
        remainder *= 10
        decimal_part.append(str(remainder // denominator))
        remainder %= denominator

    return sign + str(integer_part) + '.' + ''.join(decimal_part)

