def string_case_permutations(s: str) -> List[str]:
    def backtrack(sub="", index=0):
        if index == len(s):
            result.append(sub)
            return
        if s[index].isalpha():
            backtrack(sub + s[index].lower(), index + 1)
            backtrack(sub + s[index].upper(), index + 1)
        else:
            backtrack(sub + s[index], index + 1)

    result = []
    backtrack()
    return result

def unique_substrings_score(s: str, k: int):
    """
    Returns a dictionary of unique substrings of length k and their corresponding scores.
    """
    substrings_score = {}
    for i in range(len(s) - k + 1):
        substr = s[i:i+k]
        if substr not in substrings_score:
            score = sum(ord(char) for char in substr)
            substrings_score[substr] = score
    return substrings_score

