from typing import List, Tuple
from datetime import datetime

def parse_date(date_str: str) -> datetime:
    return datetime.strptime(date_str, "%Y-%m-%d")

def detect_overlaps(subscriptions: List[Tuple[str, str, str]]) -> List[Tuple[str, str]]:
    overlaps = []
    n = len(subscriptions)

    for i in range(n):
        user1, start1, end1 = subscriptions[i]
        start1, end1 = parse_date(start1), parse_date(end1)

        for j in range(i + 1, n):
            user2, start2, end2 = subscriptions[j]
            start2, end2 = parse_date(start2), parse_date(end2)

            if start1 <= end2 and start2 <= end1:
                overlaps.append((user1, user2))

    return overlaps

