def validate_knight_moves(moves: list) -> bool:
    def is_valid_move(start, end):
        x1, y1 = start
        x2, y2 = end
        # A knight move in chess is valid if it moves in an L shape:
        # 2 squares in one direction, and then 1 square in a perpendicular direction
        return (abs(x1 - x2), abs(y1 - y2)) in [(2, 1), (1, 2)]

    for i in range(len(moves) - 1):
        if not is_valid_move(moves[i], moves[i + 1]):
            return False

    return True

