def longest_empty_sequence(grid: list) -> int:
    def longest_sequence_in_line(line):
        max_length = 0
        current_length = 0
        for char in line:
            if char == ' ':
                current_length += 1
                max_length = max(max_length, current_length)
            else:
                current_length = 0
        return max_length

    n = len(grid)
    max_sequence_length = 0

    # Check all the rows
    for row in grid:
        max_sequence_length = max(max_sequence_length, longest_sequence_in_line(row))

    # Check all the columns
    for col in range(n):
        column_string = ''.join(grid[row][col] for row in range(n))
        max_sequence_length = max(max_sequence_length, longest_sequence_in_line(column_string))

    return max_sequence_length

