def unique_paths(m, n):
    if m <= 0 or n <= 0:
        raise ValueError("Both m and n must be positive integers.")

    # Initialize a 2D list dp where dp[i][j] represents the number of unique paths to cell (i, j)
    dp = [[1] * n for _ in range(m)]  # Initially set all cells to 1

    for i in range(1, m):
        for j in range(1, n):
            # The number of unique paths to cell (i, j) is the sum of the number of unique paths
            # to the cell directly above (i-1, j) and to the cell directly to the left (i, j-1)
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[-1][-1]

