import logging

def log_and_handle_exceptions(func):
    def wrapper(*args, **kwargs):
        func_name = func.__name__
        logging.info(f"Function called: {func_name}({', '.join(map(repr, args))})")
        try:
            result = func(*args, **kwargs)
            logging.info(f"Returned: {repr(result)}")
            return result
        except Exception as e:
            logging.error(f"Exception in {func_name}: {str(e)}")
            raise
    return wrapper

# Example functions to demonstrate the decorator

@log_and_handle_exceptions
def divide(a, b):
    return a / b

@log_and_handle_exceptions
def greet(name):
    if not name:
        raise ValueError("Name cannot be empty!")
    return f"Hello, {name}!"

