import heapq

def shortest_path(graph, start, target):
    """
    Finds the shortest path from start to target in a weighted, undirected graph using Dijkstra's algorithm.
    """
    if not graph:
        raise ValueError("Graph is empty")
    if start not in graph or target not in graph:
        raise ValueError("Start or target node is not in the graph")

    # Priority queue to hold nodes to be processed, initialized with the start node
    pq = [(0, start)]  # (distance, node)
    distances = {node: float('inf') for node in graph}
    distances[start] = 0
    # To reconstruct the path
    previous_nodes = {node: None for node in graph}

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node == target:
            break  # We have reached the target node

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            # Only consider this new path if it's better
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                previous_nodes[neighbor] = current_node
                heapq.heappush(pq, (distance, neighbor))

    # Reconstruct the shortest path
    path = []
    current = target
    while current is not None:
        path.append(current)
        current = previous_nodes[current]

    if path[-1] != start:
        return []  # If no valid path is found

    path.reverse()
    return path

