from typing import List

def sieve_of_eratosthenes(n: int) -> List[int]:
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    p = 2  # Start with the first prime number

    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    return [p for p in range(2, n + 1) if is_prime[p]]

