def generate_permutations(elements: list) -> list:
    """
    Returns all possible permutations of the input list of elements.
    """
    if len(elements) == 0:
        return [[]]

    permutations = []
    for i, elem in enumerate(elements):
        rest = elements[:i] + elements[i+1:]
        for perm in generate_permutations(rest):
            permutations.append([elem] + perm)

    return permutations

from typing import List
import math

def secure_prime_factors(input_num: int) -> List[int]:
    if not isinstance(input_num, int) or input_num <= 0:
        raise ValueError("Input must be a positive integer")

    if input_num == 1:
        return []

    prime_factors = []
    # Check for number of 2s that divide input_num
    while input_num % 2 == 0:
        prime_factors.append(2)
        input_num //= 2

    # n must be odd at this point, so a skip of 2 (i.e., 3, 5, 7, ...) is used
    for i in range(3, int(math.sqrt(input_num)) + 1, 2):
        while input_num % i == 0:
            prime_factors.append(i)
            input_num //= i

    # If n is a prime number greater than 2, it will remain as is
    if input_num > 2:
        prime_factors.append(input_num)

    return prime_factors

