from typing import List

def find_winning_team_scores(scores: List[List[int]]) -> int:
    """
    Args:
        scores (List[List[int]]): A list of lists of points, where each inner list represents a round.

    Returns:
        int: The total score of the winning team.

    Raises:
        ValueError: If scores contain non-integer types or if input data is invalid.
    """
    if not scores:
        raise ValueError("The input scores list should not be empty.")

    num_teams = len(scores[0])

    total_scores = [0] * num_teams

    for round_scores in scores:
        if len(round_scores) != num_teams:
            raise ValueError("All rounds must have the same number of scores as the number of teams.")

        for i, score in enumerate(round_scores):
            if not isinstance(score, int):
                raise ValueError("All scores must be integers.")
            if score < 0:
                raise ValueError("Scores must be non-negative integers.")
            total_scores[i] += score

    return max(total_scores)

