def fibonacci_number(n: int) -> int:
    """
    Returns the n-th Fibonacci number.
    Raises a ValueError if the index n is negative.
    """
    if n < 0:
        raise ValueError("Index can't be negative.")

    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

def fibonacci_sequence_up_to_n(n: int) -> list:
    """
    Generates a list of Fibonacci numbers from F(0) up to F(n).
    Raises a ValueError if the index n is negative.
    """
    if n < 0:
        raise ValueError("Index can't be negative.")

    if n == 0:
        return [0]

    sequence = [0, 1]
    for i in range(2, n + 1):
        sequence.append(sequence[-1] + sequence[-2])

    return sequence

