def find_most_similar_word(words, target):
    def longest_contiguous_subsequence_length(word, target):
        max_len = 0
        len_word = len(word)
        len_target = len(target)
        for i in range(len_word):
            for j in range(len_target):
                k = 0
                while i + k < len_word and j + k < len_target and word[i + k] == target[j + k]:
                    k += 1
                max_len = max(max_len, k)
        return max_len

    max_length = 0
    most_similar_word = ""
    for word in words:
        length = longest_contiguous_subsequence_length(word, target)
        if length > max_length:
            max_length = length
            most_similar_word = word

    return most_similar_word

