def validate_and_notify(book_inventory: dict, min_stock: int, max_stock: int) -> str:
    # Check if min_stock is a non-negative integer
    if not isinstance(min_stock, int) or min_stock < 0:
        return "Error: Minimum stock should be a non-negative integer"

    # Check if max_stock is greater than min_stock
    if not isinstance(max_stock, int) or max_stock <= min_stock:
        return "Error: Maximum stock should be greater than minimum stock"

    # List to collect books out of stock range
    out_of_range_books = []

    # Check every book's stock level
    for book, stock in book_inventory.items():
        if not (min_stock <= stock <= max_stock):
            out_of_range_books.append(book)

    # Return appropriate message based on the collected books
    if out_of_range_books:
        books_list = ", ".join(out_of_range_books)
        return f"Books out of stock range: [{books_list}]"
    else:
        return "All books are within the acceptable stock levels."

