def is_arithmetic_sequence(nums: list) -> bool:
    """
    Determine if the given list of numbers forms an arithmetic sequence.

    :param nums: List of integers.
    :return: True if the list forms an arithmetic sequence, False otherwise.
    """
    if len(nums) < 2:
        return False

    difference = nums[1] - nums[0]

    for i in range(1, len(nums)):
        if nums[i] - nums[i - 1] != difference:
            return False

    return True

