def count_connected_components(graph: dict[int, list[int]]) -> int:
    """
    Counts the number of connected components in an undirected graph.

    :param graph: A dictionary where the keys are nodes and the values are lists of neighboring nodes.
    :return: An integer representing the number of connected components in the graph.
    """
    def dfs(node):
        """Depth First Search helper function to traverse the graph."""
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor)

    visited = set()
    num_components = 0

    for node in graph:
        if node not in visited:
            dfs(node)
            num_components += 1

    return num_components

