def has_cycle(graph):
    """
    This function detects if a directed graph contains a cycle.

    :param graph: Dictionary representing the directed graph as an adjacency list.
    :return: Boolean True if the graph contains at least one cycle, False otherwise.
    """
    visited = set()
    rec_stack = set()

    def dfs(node):
        if node not in visited:
            visited.add(node)
            rec_stack.add(node)

            if node in graph:
                for neighbor in graph[node]:
                    if neighbor not in visited and dfs(neighbor):
                        return True
                    elif neighbor in rec_stack:
                        return True

            rec_stack.remove(node)
        return False

    for node in graph:
        if node not in visited:
            if dfs(node):
                return True

    return False

