def find_peaks_valleys(prices):
    """
    Identifies all local peaks and valleys in the given list of stock prices.
    A local peak is a price higher than its neighbors, and a local valley is a price lower than its neighbors.
    Returns a list of tuples of the form (index, value).
    """
    if len(prices) < 2:
        # If there are less than 2 prices, no peaks or valleys can be found.
        return []

    result = []

    for i in range(1, len(prices) - 1):
        if prices[i-1] < prices[i] > prices[i+1]:
            result.append((i, prices[i]))
        elif prices[i-1] > prices[i] < prices[i+1]:
            result.append((i, prices[i]))

    return result

