from typing import List
import math

def minimum_bst_height(values: List[int]) -> int:
    def build_min_height_bst(values: List[int]) -> int:
        if not values:
            return -1
        mid = len(values) // 2
        left_height = build_min_height_bst(values[:mid])
        right_height = build_min_height_bst(values[mid+1:])
        return 1 + max(left_height, right_height)

    return build_min_height_bst(sorted(values))

