from typing import List, Dict

def recommend_products(user_history: List[str], product_db: Dict[str, List[str]]) -> List[str]:
    recommended = set()
    recommendations = []

    # Process each category in user history
    for category in user_history:
        if category in product_db:
            for product in product_db[category]:
                if product not in recommended:
                    recommended.add(product)
                    recommendations.append(product)
                if len(recommendations) == 5:
                    break
        if len(recommendations) == 5:
            break

    # Fill the remaining recommendations, if needed, from unused categories
    if len(recommendations) < 5:
        for category, products in product_db.items():
            if category not in user_history:
                for product in products:
                    if product not in recommended:
                        recommended.add(product)
                        recommendations.append(product)
                    if len(recommendations) == 5:
                        break
            if len(recommendations) == 5:
                break

    return recommendations

