from typing import List

def rotate_matrix_elements(matrix: List[List[int]]) -> List[List[int]]:
    m, n = len(matrix), len(matrix[0])
    last_element = matrix[m-1][n-1]

    # Rotate elements within the matrix by one position in reverse order
    for i in range(m-1, -1, -1):
        for j in range(n-1, -1, -1):
            if j == 0:
                if i > 0:
                    matrix[i][j] = matrix[i-1][n-1]
            else:
                matrix[i][j] = matrix[i][j-1]

    # Place the last element to the first position
    matrix[0][0] = last_element
    return matrix

def encode_message(message: str, shift: int) -> str:
    """
    Encodes a message by shifting its letters by the specified number of positions in the alphabet.
    """
    def shift_char(c, shift):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        return c

    return ''.join(shift_char(c, shift) for c in message)

def decode_message(encoded_message: str, shift: int) -> str:
    """
    Decodes a message that was encoded with a shift cipher by reversing the shift.
    """
    return encode_message(encoded_message, -shift)

