def compare_strings(s1: str, s2: str, custom_order: str) -> int:
    # Create a dictionary to store the custom order
    custom_index = {char: index for index, char in enumerate(custom_order)}

    # Get the length of the shorter string to avoid IndexError
    min_len = min(len(s1), len(s2))

    # Compare character by character using the custom order
    for i in range(min_len):
        if s1[i] != s2[i]:
            if custom_index[s1[i]] < custom_index[s2[i]]:
                return -1
            else:
                return 1

    # If all characters matched so far, then the shorter string is less
    if len(s1) < len(s2):
        return -1
    elif len(s1) > len(s2):
        return 1
    else:
        return 0

