import string

def is_anagram(word1, word2):
    """
    Determines if word1 is an anagram of word2.

    Parameters:
    - word1: First word to compare (string).
    - word2: Second word to compare (string).

    Returns:
    - True if word1 is an anagram of word2, False otherwise.
    """
    if not isinstance(word1, str) or not isinstance(word2, str):
        raise ValueError("Both inputs must be strings.")

    # Normalize inputs by converting to lowercase and removing non-alphabetic characters
    translater = str.maketrans("", "", string.punctuation + " ")
    word1 = word1.lower().translate(translater)
    word2 = word2.lower().translate(translater)

    # Use a frequency dictionary to count occurrences of each character
    def char_frequency(word):
        freq = {}
        for char in word:
            if char in freq:
                freq[char] += 1
            else:
                freq[char] = 1
        return freq

    return char_frequency(word1) == char_frequency(word2)

