def integer_partition(n: int) -> int:
    MODULO = 10**9 + 7

    # Initialize a list to store the partition counts
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        for j in range(i, n + 1):
            dp[j] = (dp[j] + dp[j - i]) % MODULO

    return dp[n]

def number_to_words(num):
    if num is None or not isinstance(num, int):
        return "Invalid input, please enter an integer."

    def translate_hundreds(n):
        ones = ("Zero", "One", "Two", "Three", "Four", "Five",
                "Six", "Seven", "Eight", "Nine", "Ten", "Eleven",
                "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen",
                "Seventeen", "Eighteen", "Nineteen")
        tens = ("", "", "Twenty", "Thirty", "Forty", "Fifty",
                "Sixty", "Seventy", "Eighty", "Ninety")

        if n < 20:
            return ones[n]
        elif n < 100:
            return tens[n // 10] + ("" if n % 10 == 0 else "-" + ones[n % 10])
        else:
            return ones[n // 100] + " Hundred" + ("" if n % 100 == 0 else " " + translate_hundreds(n % 100))

    if num == 0:
        return "Zero"

    if num < 0:
        return "Minus " + translate_hundreds(-num)

    return translate_hundreds(num)

