def find_duplicates(arr):
    """
    Returns a list of duplicate elements in the order of their first occurrence.
    """
    seen = set()
    duplicates = set()

    for item in arr:
        if item in seen:
            duplicates.add(item)
        else:
            seen.add(item)

    return list(duplicates)

