def substring_sum(s: str) -> int:
    """
    Calculate the sum of all numeric substrings in the given string.
    """
    def is_digit(c):
        return '0' <= c <= '9'

    total_sum = 0
    num_str = ''

    # Iterate over each character in the string
    for char in s:
        if is_digit(char):
            num_str += char
        else:
            if num_str:
                total_sum += int(num_str)
                num_str = ''

    # If there's a number left at the end of the string, add it to the sum
    if num_str:
        total_sum += int(num_str)

    return total_sum

