def summarize_logs(logs: list[tuple[int, str]], start_time: str, end_time: str) -> dict[str, list[str]]:
    from collections import defaultdict
    from datetime import datetime

    def is_within_range(log_time_str, start_time_str, end_time_str):
        log_time = datetime.strptime(log_time_str, "%Y-%m-%d %H:%M:%S")
        start_time = datetime.strptime(start_time_str, "%Y-%m-%d %H:%M:%S")
        end_time = datetime.strptime(end_time_str, "%Y-%m-%d %H:%M:%S")
        return start_time <= log_time <= end_time

    result = defaultdict(list)

    for priority, log_message in logs:
        timestamp, message = log_message.split('|', 1)
        if is_within_range(timestamp, start_time, end_time):
            result[str(priority)].append(log_message)

    for priority in result:
        result[priority].sort()

    return dict(result)

from typing import List

def rotated_binary_search(nums: List[int], target: int) -> int:
    """
    Searches for a target value within a rotated sorted array and
    returns the position (index) of the target if found, otherwise -1.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        # Identify the sorted part of the array
        if nums[left] <= nums[mid]:
            # Left part is sorted
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right part is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def merge(arr, start, mid, end):
    start2 = mid + 1

    if arr[mid] <= arr[start2]:  # Already in place
        return

    while start <= mid and start2 <= end:
        if arr[start] <= arr[start2]:
            start += 1
        else:
            value = arr[start2]
            index = start2

            while index != start:
                arr[index] = arr[index - 1]
                index -= 1

            arr[start] = value

            start += 1
            mid += 1
            start2 += 1

def in_place_merge_sort_helper(arr, l, r):
    if l < r:
        m = l + (r - l) // 2

        in_place_merge_sort_helper(arr, l, m)
        in_place_merge_sort_helper(arr, m + 1, r)

        merge(arr, l, m, r)

def in_place_merge_sort(arr):
    if not arr or len(arr) == 1:
        return
    in_place_merge_sort_helper(arr, 0, len(arr) - 1)

