def simulate_file_system(operations: List[Tuple[str, str]]) -> List[str]:
    file_system = {}

    def mkdir(path):
        parts = path.split('/')
        cur = file_system
        for part in parts:
            if part:
                if part not in cur:
                    cur[part] = {}
                cur = cur[part]

    def ls(path):
        parts = path.split('/')
        cur = file_system
        for part in parts:
            if part:
                cur = cur[part]

        return '\n'.join(sorted(cur.keys()))

    results = []
    for command, path in operations:
        if command == "mkdir":
            mkdir(path)
        elif command == "ls":
            results.append(ls(path))

    return results

