from collections import defaultdict, deque
import heapq

def topological_sort(N, edges):
    in_degree = [0] * N
    graph = defaultdict(list)

    for u, v, w in edges:
        graph[u].append((v, w))
        in_degree[v] += 1

    queue = deque([i for i in range(N) if in_degree[i] == 0])
    topo_order = []

    while queue:
        node = queue.popleft()
        topo_order.append(node)

        for neighbor, weight in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return topo_order

def shortest_path_dag(N, edges, start):
    topo_order = topological_sort(N, edges)
    dist = [float('inf')] * N
    dist[start] = 0

    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    for u in topo_order:
        if dist[u] != float('inf'):
            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w

    return dist

