from typing import List

def min_pages_partition(nums: List[int], k: int) -> int:
    def can_partition(max_pages):
        current_sum = 0
        partitions = 1
        for pages in nums:
            if current_sum + pages > max_pages:
                partitions += 1
                current_sum = pages
                if partitions > k:
                    return False
            else:
                current_sum += pages
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_partition(mid):
            right = mid
        else:
            left = mid + 1
    return left

