def extract_substrings(s: str, k: int) -> list[str]:
    """
    Extract all substrings of length k from the given string s.
    """
    return [s[i:i+k] for i in range(len(s) - k + 1)]

def count_frequencies(substrings: list[str]) -> dict[str, int]:
    """
    Count the frequency of each substring in the given list.
    """
    frequency = {}
    for substring in substrings:
        if substring in frequency:
            frequency[substring] += 1
        else:
            frequency[substring] = 1
    return frequency

def find_repeated_substrings(s: str, k: int) -> list[str]:
    """
    Identify substrings of length k that appear more than once in the given string s.
    """
    substrings = extract_substrings(s, k)
    frequency = count_frequencies(substrings)
    return [substring for substring, count in frequency.items() if count > 1]

