from typing import List, Tuple
import itertools

def shortest_path_to_check_all_rooms(n: int, corridors: List[Tuple[int, int, int]], start: int) -> int:
    # Create the adjacency matrix representing the graph
    INF = float('inf')
    graph = [[INF]*n for _ in range(n)]

    for u, v, w in corridors:
        graph[u][v] = w
        graph[v][u] = w

    # We need to solve the Traveling Salesman Problem (TSP) where the salesman must visit
    # every node and return to the starting node with minimum cost.
    dp = [[INF]*n for _ in range(1<<n)]
    dp[1<<start][start] = 0

    for mask in range(1<<n):
        for u in range(n):
            if mask & (1<<u):
                for v in range(n):
                    if mask & (1<<v) == 0:
                        dp[mask | (1<<v)][v] = min(dp[mask | (1<<v)][v], dp[mask][u] + graph[u][v])

    ans = INF
    for u in range(n):
        ans = min(ans, dp[(1<<n) - 1][u] + graph[u][start])

    return ans

def deep_copy(original_dict):
    """
    Returns a deep copy of the given dictionary.
    """
    if isinstance(original_dict, dict):
        return {key: deep_copy(value) for key, value in original_dict.items()}
    elif isinstance(original_dict, list):
        return [deep_copy(element) for element in original_dict]
    else:
        return original_dict

