def rotate_matrix(matrix: list) -> None:
    """
    Rotates the given N x N matrix by 90 degrees clockwise in place.
    """
    n = len(matrix)

    # Transpose the matrix: Swap elements across the diagonal
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row to get the final rotated matrix
    for row in matrix:
        row.reverse()

