from typing import Tuple

def robot_moves(commands: str) -> Tuple[int, int]:
    x, y = 0, 0  # Starting at the origin (0, 0)

    # Loop over each command character
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return (x, y)

