def evaluate_expression(expression: str) -> int:
    num = 0
    stack = []
    sign = '+'
    n = len(expression)

    for i in range(n):
        char = expression[i]

        if char.isdigit():
            num = num * 10 + int(char)

        if char in '+-*/' or i == n - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                stack.append(int(float(stack.pop()) / num))  # use int() to truncate towards zero

            sign = char
            num = 0

    return sum(stack)

