def max_parenthesis_depth(s: str) -> int:
    """
    Determine the maximum depth of a valid, balanced parenthesis string.

    :param s: A balanced parenthesis string composed of characters '(' and ')'.
    :return: An integer representing the maximum depth of nested parentheses.
    """
    max_depth = 0
    current_depth = 0

    for char in s:
        if char == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif char == ')':
            current_depth -= 1

    return max_depth

