def calculate_green_time(input_grid):
    """
    Counts the number of green lights (either 'N' for north-south or 'E' for east-west) in a given input grid
    of traffic light intersections.
    """
    rows = len(input_grid)
    cols = len(input_grid[0])

    result_grid = [[0] * cols for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if input_grid[i][j] == 'N' or input_grid[i][j] == 'E':
                result_grid[i][j] = 1

    return result_grid

