import csv
from datetime import datetime
from collections import defaultdict

def analyze_stock_data(file_path: str, tickers: list) -> dict:
    stock_data = defaultdict(lambda: defaultdict(list))

    # Read CSV file and aggregate data
    with open(file_path, newline='') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            try:
                date = datetime.strptime(row['date'], '%Y-%m-%d')
                year = date.year
                ticker = row['company_ticker']
                if ticker in tickers:
                    open_price = float(row['open'])
                    close_price = float(row['close'])
                    stock_data[ticker][year].append((open_price, close_price))
            except (ValueError, KeyError) as e:
                print(f"Skipping row due to error: {e}, row: {row}")

    results = {}
    for ticker in tickers:
        yearly_data = stock_data[ticker]
        yearly_returns = {}
        for year, prices in sorted(yearly_data.items()):
            if prices:  # Ensure there are prices available for the year
                start_close = prices[0][1]
                end_close = prices[-1][1]
                yearly_return = ((end_close - start_close) / start_close) * 100
                yearly_returns[year] = yearly_return
        results[ticker] = {"yearly_returns": yearly_returns}

    return results

