from typing import List

def string_permutations(s: str) -> List[str]:
    def permute(remaining, path, result):
        if not remaining:
            result.add(path)
            return
        for i in range(len(remaining)):
            permute(remaining[:i] + remaining[i+1:], path + remaining[i], result)

    result = set()
    permute(s, "", result)
    return sorted(result)

from typing import List

def remove_duplicates(arr: List[int]) -> int:
    if not arr:
        return 0

    write_index = 1

    for read_index in range(1, len(arr)):
        if arr[read_index] != arr[write_index - 1]:
            arr[write_index] = arr[read_index]
            write_index += 1

    return write_index

