def are_permutations(s1: str, s2: str) -> bool:
    if len(s1) != len(s2):
        return False

    char_count = {}

    for char in s1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s2:
        if char in char_count:
            char_count[char] -= 1
            if char_count[char] < 0:
                return False
        else:
            return False

    return True

