from typing import List

def merge_sort(arr: List[int]) -> List[int]:
    if len(arr) <= 1:
        return arr

    def merge(left: List[int], right: List[int]) -> List[int]:
        sorted_list = []
        i = j = 0

        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                sorted_list.append(left[i])
                i += 1
            else:
                sorted_list.append(right[j])
                j += 1

        sorted_list.extend(left[i:])
        sorted_list.extend(right[j:])

        return sorted_list

    mid = len(arr) // 2
    left_half = merge_sort(arr[:mid])
    right_half = merge_sort(arr[mid:])

    return merge(left_half, right_half)

def sum_of_prime_factors(n: int) -> int:
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    # To store prime numbers using Sieve of Eratosthenes
    max_limit = n + 1
    sieve = [True] * max_limit
    p = 2
    while (p * p <= n):
        if (sieve[p] == True):
            for i in range(p * p, max_limit, p):
                sieve[i] = False
        p += 1

    prime_factors_sum = 0
    # Check for each number if it is a factor and prime
    for i in range(2, n + 1):
        if n % i == 0 and sieve[i]:
            prime_factors_sum += i

    return prime_factors_sum

