from typing import List, Tuple

def top_rated_movies(reviews: List[Tuple[str, int]]) -> List[str]:
    if not reviews:
        return []

    movie_ratings = {}

    for movie, rating in reviews:
        if movie not in movie_ratings:
            movie_ratings[movie] = [0, 0]  # [sum of ratings, number of ratings]
        movie_ratings[movie][0] += rating
        movie_ratings[movie][1] += 1

    max_avg_rating = -1
    top_movies = []

    for movie, (total_rating, count) in movie_ratings.items():
        average_rating = total_rating / count
        if average_rating > max_avg_rating:
            max_avg_rating = average_rating
            top_movies = [movie]
        elif average_rating == max_avg_rating:
            top_movies.append(movie)

    return sorted(top_movies)

import math

def quadratic_roots(a: float, b: float, c: float) -> tuple[float, float]:
    if a == 0:
        raise ValueError("Coefficient 'a' cannot be zero")

    discriminant = b**2 - 4*a*c

    if discriminant < 0:
        raise ValueError("Complex roots are not supported")

    root1 = (-b + math.sqrt(discriminant)) / (2*a)
    root2 = (-b - math.sqrt(discriminant)) / (2*a)

    return (min(root1, root2), max(root1, root2))

