from typing import List, Tuple

def binary_search_range(arr: List[int], target: int) -> Tuple[int, int]:
    def find_first(arr: List[int], target: int) -> int:
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = left + (right - left) // 2
            if arr[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_last(arr: List[int], target: int) -> int:
        left, right = 0, len(arr) - 1
        while left <= right:
            mid = left + (right - left) // 2
            if arr[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    start = find_first(arr, target)
    end = find_last(arr, target)
    if start < len(arr) and arr[start] == target:
        return start, end
    else:
        return -1, -1

