from typing import List

def find_temperature_fluctuations(temperatures: List[float], threshold: float) -> List[bool]:
    """
    Detects significant temperature fluctuations over a given list of temperature readings.
    """
    if len(temperatures) < 2:
        return []  # Not enough data to determine fluctuations

    fluctuations = [False]  # Start with False for the first element as there's no previous temperature to compare

    for i in range(1, len(temperatures)):
        if abs(temperatures[i] - temperatures[i - 1]) > threshold:
            fluctuations.append(True)
        else:
            fluctuations.append(False)

    return fluctuations

