def min_palindromic_substrings(s: str) -> int:
    """
    Finds and returns the minimum number of palindromic substrings required to cover the entire given string.

    Parameters:
    - s (str): The input string consisting of lowercase alphabets.

    Returns:
    - int: The minimum number of palindromic substrings.
    """
    n = len(s)
    dp = [[False] * n for _ in range(n)]

    # Length 1 substrings are palindrome
    for i in range(n):
        dp[i][i] = True

    # Length 2 substrings are palindrome if characters are same
    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = True

    # Fill the dp table for substrings longer than 2
    for length in range(3, n+1):
        for i in range(n-length+1):
            j = i+length-1
            if s[i] == s[j] and dp[i+1][j-1]:
                dp[i][j] = True

    # Minimum cuts dp array
    cuts = [0] * n
    for i in range(n):
        if dp[0][i]:
            cuts[i] = 0
        else:
            cuts[i] = float('inf')
            for j in range(i):
                if dp[j+1][i]:
                    cuts[i] = min(cuts[i], cuts[j]+1)

    return cuts[-1] + 1

