def detect_cycle(graph):
    """
    Detects a cycle in a directed graph and returns one of the cycles if present.
    Returns None if the graph is acyclic.

    :param graph: A dictionary representing the directed graph.
    :return: A list representing a cycle or None.
    """
    color = {node: "white" for node in graph}
    parent = {node: None for node in graph}
    found_cycle = []

    def dfs(node):
        nonlocal found_cycle
        if found_cycle:
            return
        color[node] = "gray"
        for neighbour in graph[node]:
            if color[neighbour] == "white":
                parent[neighbour] = node
                dfs(neighbour)
            elif color[neighbour] == "gray":
                # Back edge detected
                cycle_node = node
                while cycle_node != neighbour:
                    found_cycle.append(cycle_node)
                    cycle_node = parent[cycle_node]
                found_cycle.append(neighbour)
                found_cycle.append(node)
                found_cycle.reverse()
                return
        color[node] = "black"

    for node in graph:
        if color[node] == "white":
            dfs(node)

    return found_cycle if found_cycle else None

