def is_valid_bst_sequence(sequence: list[int]) -> bool:
    """
    Determines if it is possible to build a valid BST from the given sequence of values.
    """
    if not sequence:
        return True

    def verify_preorder(sequence):
        stack = []
        root = float('-inf')

        for value in sequence:
            if value < root:
                return False

            while stack and stack[-1] < value:
                root = stack.pop()

            stack.append(value)

        return True

    return verify_preorder(sequence)

