def rotation_cipher(text: str, shift: int) -> str:
    """
    Encrypts a given string using a rotation cipher.

    Args:
    text (str): The string to encrypt.
    shift (int): The number of characters to shift in the cipher.

    Returns:
    str: The encrypted string.
    """
    def shift_char(c, shift):
        if c.islower():
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif c.isupper():
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c, shift) for c in text)

