def most_popular_hashtag(posts: list[str]) -> str:
    from collections import Counter
    import re

    hashtag_pattern = re.compile(r'#\w+')
    hashtags = []

    for post in posts:
        hashtags.extend(hashtag_pattern.findall(post))

    if not hashtags:
        return ""

    hashtag_count = Counter(hashtags)
    return max(hashtag_count, key=hashtag_count.get)

