from typing import List

def find_broken_elements(lst: List[int]) -> List[int]:
    broken_indices = []
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            if i not in broken_indices:
                broken_indices.append(i)
            if i + 1 not in broken_indices:
                broken_indices.append(i + 1)
    return broken_indices

