def factorial_iterative(n):
    """
    Computes the factorial of n using an iterative approach.
    """
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def factorial_recursive(n):
    """
    Computes the factorial of n using a recursive approach.
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial_recursive(n - 1)

def factorial_comparison(number):
    """
    Computes the factorial using both the iterative and recursive methods.
    Compares the results and returns a message indicating if they match or not.
    """
    if number < 0:
        return "Invalid input, expected non-negative integer"

    iterative_result = factorial_iterative(number)
    recursive_result = factorial_recursive(number)

    if iterative_result == recursive_result:
        return f"Matching Factorials: {iterative_result}"
    else:
        return f"Discrepancy: Iterative calculated {iterative_result}, Recursive calculated {recursive_result}"

