def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced parentheses substring.
    """
    max_length = 0

    # Left to right pass
    left = right = 0
    for char in s:
        if char == '(':
            left += 1
        else:
            right += 1
        if left == right:
            max_length = max(max_length, 2 * right)
        elif right > left:
            left = right = 0

    # Right to left pass
    left = right = 0
    for char in reversed(s):
        if char == '(':
            left += 1
        else:
            right += 1
        if left == right:
            max_length = max(max_length, 2 * left)
        elif left > right:
            left = right = 0

    return max_length

