def is_balanced_string(s: str) -> bool:
    """
    Determine if the input string is balanced considering '(' as left parenthesis,
    ')' as right parenthesis, and '*' as a wildcard that can be treated as '(', ')', or empty.
    """
    left_balance, right_balance = 0, 0

    for char in s:
        if char == '(' or char == '*':
            left_balance += 1
        else:
            left_balance -= 1

        if left_balance < 0:
            return False

    for char in reversed(s):
        if char == ')' or char == '*':
            right_balance += 1
        else:
            right_balance -= 1

        if right_balance < 0:
            return False

    return True

