def first_non_repeating_element(arr: list) -> int:
    """
    Returns the first non-repeating element in the array.
    If all elements are repeated, returns -1.
    """
    if not arr:
        return -1

    element_count = {}

    # Count occurrences of each element
    for el in arr:
        if el in element_count:
            element_count[el] += 1
        else:
            element_count[el] = 1

    # Find the first non-repeating element
    for el in arr:
        if element_count[el] == 1:
            return el

    # Return -1 if all elements are repeated
    return -1

