def generate_grade_report(scores):
    # Initialize the grade report
    report = {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}

    # Validate scores and increment respective grade count
    for score in scores:
        if not isinstance(score, int) or not (0 <= score <= 100):
            raise ValueError("Scores must be integers between 0 and 100 inclusive.")
        if 90 <= score <= 100:
            report['A'] += 1
        elif 80 <= score <= 89:
            report['B'] += 1
        elif 70 <= score <= 79:
            report['C'] += 1
        elif 60 <= score <= 69:
            report['D'] += 1
        else:
            report['F'] += 1

    return report

