import hashlib
from typing import List, Tuple, Dict

def hash_block(block: Dict) -> str:
    block_string = f"{block['sender']}{block['receiver']}{block['amount']}{block['previous_hash']}"
    return hashlib.sha256(block_string.encode()).hexdigest()

def add_to_blockchain(transactions: List[Tuple[str, str, int]]) -> List[Dict]:
    blockchain = []
    previous_hash = "0"

    for sender, receiver, amount in transactions:
        block = {
            "sender": sender,
            "receiver": receiver,
            "amount": amount,
            "previous_hash": previous_hash
        }
        current_hash = hash_block(block)
        block["hash"] = current_hash
        blockchain.append(block)
        previous_hash = current_hash

    return blockchain

