def evaluate_expression(expression: str) -> float:
    """
    Evaluates a mathematical expression provided as a string and returns the result as a float.
    """
    # Define a scope with restricted built-in functions for eval
    allowed_names = {"__builtins__": None}
    expression = expression.replace(' ', '')  # Remove spaces in the expression

    # Try to evaluate the expression using eval within the restricted scope
    try:
        result = eval(expression, allowed_names)
        return float(result)
    except ZeroDivisionError:
        raise ZeroDivisionError("division by zero")
    except SyntaxError:
        raise ValueError("Invalid expression provided")
    except Exception as e:
        raise ValueError(f"An error occurred: {e}")

# Example Usage:
# print(evaluate_expression("3 + 5"))           # Outputs: 8.0
# print(evaluate_expression("10 - 2 * 3"))      # Outputs: 4.0
# print(evaluate_expression("2.5 * 4"))         # Outputs: 10.0
# print(evaluate_expression("8 / 2 + 3"))       # Outputs: 7.0

