def max_depth(nested_list: list) -> int:
    """
    Compute the maximum depth of a list containing nested sub-lists.

    :param list nested_list: The list to compute the maximum depth for.
    :return int: The maximum depth of the nested lists.
    """
    if not isinstance(nested_list, list):
        raise TypeError("Input must be a list.")

    def get_depth(lst, level):
        if not lst:
            return level
        return max(get_depth(item, level + 1) if isinstance(item, list) else level for item in lst)

    return get_depth(nested_list, 1)

