def summarize_sales(sales: List[Dict[str, Any]]) -> Dict[int, Dict[str, int]]:
    summary = {}

    for sale in sales:
        product_id = sale["product_id"]
        sale_amount = sale["sale_amount"]

        if product_id not in summary:
            summary[product_id] = {
                "total_sales": 0,
