from typing import List

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    p = 3
    while p * p <= num:
        if num % p == 0:
            return False
        p += 2
    return True

def generate_primes(limit: int) -> List[int]:
    primes = []
    candidate = 2
    while len(primes) < limit:
        if is_prime(candidate):
            primes.append(candidate)
        candidate += 1
    return primes

def cumulative_prime_sum(n: int) -> List[int]:
    if n <= 0:
        return []
    primes = generate_primes(n)
    cumulative_sum = []
    total = 0
    for prime in primes:
        total += prime
        cumulative_sum.append(total)
    return cumulative_sum

