from typing import List

def find_tallest_peak(heights: List[int]) -> int:
    n = len(heights)

    if n < 3:
        return 0  # A peak requires at least 3 buildings

    tallest_peak = 0
    i = 1

    while i < n - 1:
        # Check if heights[i] is a peak
        if heights[i-1] < heights[i] > heights[i+1]:
            left = i - 1
            right = i + 1

            # Find the maximum peak height
            while left > 0 and heights[left-1] < heights[left]:
                left -= 1
            while right < n - 1 and heights[right+1] < heights[right]:
                right += 1

            tallest_peak = max(tallest_peak, heights[i])

            # Move i to the end of the right slope
            i = right
        else:
            i += 1

    return tallest_peak

