from typing import Set

def levenshtein_distance(a, b):
    if len(a) > len(b):
        a, b = b, a
    distances = range(len(a) + 1)
    for i2, c2 in enumerate(b):
        distances_ = [i2 + 1]
        for i1, c1 in enumerate(a):
            if c1 == c2:
                distances_.append(distances[i1])
            else:
                distances_.append(1 + min((distances[i1], distances[i1 + 1], distances_[-1])))
        distances = distances_
    return distances[-1]

def correct_spelling(message: str, correct_words: Set[str]) -> str:
    def find_closest_word(word, correct_words):
        closest_word = None
        min_distance = float('inf')
        for correct_word in correct_words:
            distance = levenshtein_distance(word, correct_word)
            if distance < min_distance or (distance == min_distance and correct_word < closest_word):
                min_distance = distance
                closest_word = correct_word
        return closest_word

    words = message.split()
    corrected_words = [find_closest_word(word, correct_words) for word in words]
    return ' '.join(corrected_words)

