from typing import List

def find_smallest_missing_positive(nums: List[int]) -> int:
    n = len(nums)

    # Step 1: Mark numbers (num < 1 or num > n) with a larger number (n+1)
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Step 2: Use the index as a hash and mark the corresponding index negative
    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            nums[num - 1] = -abs(nums[num - 1])

    # Step 3: Find the first missing positive number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

