from typing import List, Tuple

def social_network(n: int, operations: List[Tuple[str, int, int]]) -> List[str]:
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])  # Path compression
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)

        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    result = []

    for op in operations:
        if op[0] == 'union':
            union(op[1], op[2])
        elif op[0] == 'find':
            if find(op[1]) == find(op[2]):
                result.append("Yes")
            else:
                result.append("No")

    return result

def process_transactions(start_balance: float | str, transactions: list[tuple[str, float | str]]) -> float:
    try:
        balance = float(start_balance)
    except ValueError:
        return 0.0

    if balance < 0:
        return 0.0

    for transaction in transactions:
        try:
            trans_type, amount = transaction
            amount = float(amount)
        except (ValueError, TypeError):
            return 0.0

        if trans_type == 'deposit':
            balance += amount
        elif trans_type == 'withdraw':
            if balance >= amount:
                balance -= amount
        else:
            return 0.0

    return balance

