def prime_factors_and_divisors(n: int) -> (list, int):
    """
    Calculate the prime factors and the number of divisors of a given integer.

    Parameters:
    n (int): The integer to factorize (1 <= n <= 10^12).

    Returns:
    tuple: A tuple containing a list of prime factors of n,
           and an integer representing the total number of divisors of n.
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer.")

    if n == 1:
        return ([], 1)

    def prime_factors(n):
        i = 2
        factors = {}
        while i * i <= n:
            while (n % i) == 0:
                if i in factors:
                    factors[i] += 1
                else:
                    factors[i] = 1
                n //= i
            i += 1
        if n > 1:
            factors[n] = 1
        return factors

    factors = prime_factors(n)
    prime_factors_list = list(factors.keys())

    num_divisors = 1
    for exponent in factors.values():
        num_divisors *= (exponent + 1)

    return (prime_factors_list, num_divisors)

