from typing import List
import re
from collections import Counter

def are_anagrams(titles: List[str]) -> bool:
    """
    Determines if all book titles in the list are anagrams of each other.
    This function ignores case, spaces, and punctuation characters.
    """
    if not titles:
        return True

    def normalize(title: str) -> str:
        # Remove non-alphabetic characters and convert to lowercase
        return ''.join(sorted(re.sub(r'\W+', '', title).lower()))

    # Normalize the first title to compare others
    normalized_first = normalize(titles[0])

    # Compare all normalized titles to the first normalized title
    for title in titles[1:]:
        if normalize(title) != normalized_first:
            return False

    return True

