def optimal_meeting_point(grid: list[list[str]]) -> tuple[int, int]:
    from collections import deque

    def bfs(start):
        m, n = len(grid), len(grid[0])
        visited = set()
        q = deque([start])
        cluster = []
        while q:
            x, y = q.popleft()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            cluster.append((x, y))
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == '1' and (nx, ny) not in visited:
                    q.append((nx, ny))
        return cluster

    m, n = len(grid), len(grid[0])
    largest_cluster = []

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                candidate_cluster = bfs((i, j))
                if len(candidate_cluster) > len(largest_cluster):
                    largest_cluster = candidate_cluster

    if not largest_cluster:
        return None

    xs = sorted(x for x, y in largest_cluster)
    ys = sorted(y for x, y in largest_cluster)

    median_x = xs[len(xs) // 2]
    median_y = ys[len(ys) // 2]

    return (median_x, median_y)

