def has_cycle(num_nodes: int, edges: list[tuple[int, int]]) -> bool:
    from collections import defaultdict, deque

    def build_graph(num_nodes, edges):
        graph = defaultdict(list)
        in_degree = [0] * num_nodes
        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1
        return graph, in_degree

    def is_cyclic(graph, in_degree, num_nodes):
        queue = deque([node for node in range(num_nodes) if in_degree[node] == 0])
        visited = 0

        while queue:
            node = queue.popleft()
            visited += 1

            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return visited != num_nodes

    graph, in_degree = build_graph(num_nodes, edges)
    return is_cyclic(graph, in_degree, num_nodes)

