from typing import List

def longest_unique_starting_subsequence(words: List[str]) -> int:
    """
    Returns the length of the longest subsequence of words
    such that each word starts with a different letter from the English alphabet.
    """
    seen_letters = set()

    for word in words:
        # Convert the starting letter to lower case and check if seen before
        first_letter = word[0].lower()
        if first_letter not in seen_letters:
            seen_letters.add(first_letter)

    return len(seen_letters)

