import re

def longest_word_frequency(file_path: str) -> tuple:
    try:
        with open(file_path, 'r') as file:
            text = file.read().strip()
            if not text:
                raise ValueError("File is empty")
            words = re.findall(r'\b\w+\b', text)
            longest_word = ''
            frequency = 0
            word_count = {}

            # Find the longest word and count the frequencies of all words
            for word in words:
                if len(word) > len(longest_word):
                    longest_word = word
                    frequency = 1
                elif len(word) == len(longest_word):
                    if word == longest_word:
                        frequency += 1
                    # Since the task specifies to return the first appearing word, we do not change the longest_word
                word_count[word] = word_count.get(word, 0) + 1

            return longest_word, word_count[longest_word]

    except FileNotFoundError:
        raise ValueError("File not found")

    except Exception as e:
        raise ValueError("An error occurred: " + str(e))

