def count_increasing_subarrays(temperatures: list[int]) -> int:
    n = len(temperatures)
    if n == 0:
        return 0

    count = 0
    length = 1

    for i in range(1, n):
        if temperatures[i] > temperatures[i - 1]:
            length += 1
        else:
            if length > 1:
                count += (length * (length - 1)) // 2
            length = 1

    if length > 1:
        count += (length * (length - 1)) // 2

    return count

