def capture_regions(board: list[list[str]]) -> None:
    """
    Capture all surrounded regions in the board.
    """
    if not board:
        return

    rows, cols = len(board), len(board[0])

    def dfs(i, j):
        if i < 0 or j < 0 or i >= rows or j >= cols or board[i][j] != 'O':
            return
        board[i][j] = 'E'  # Mark as escaped (not surrounded)
        # Perform DFS in all four directions
        dfs(i - 1, j)
        dfs(i + 1, j)
        dfs(i, j - 1)
        dfs(i, j + 1)

    # Start from the borders and mark the escapable 'O's
    for i in range(rows):
        if board[i][0] == 'O':
            dfs(i, 0)
        if board[i][cols - 1] == 'O':
            dfs(i, cols - 1)

    for j in range(cols):
        if board[0][j] == 'O':
            dfs(0, j)
        if board[rows - 1][j] == 'O':
            dfs(rows - 1, j)

    # Convert all 'O's to 'X's and all 'E's back to 'O'
    for i in range(rows):
        for j in range(cols):
            if board[i][j] == 'O':
                board[i][j] = 'X'
            elif board[i][j] == 'E':
                board[i][j] = 'O'

def min_traversal_cost(grid: list[list[int]]) -> int:
    """
    Calculate the minimum cost to traverse from the top-left to the bottom-right corner of a grid.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    dp[0][0] = grid[0][0]

    # Fill the first row (can only come from the left)
    for j in range(1, cols):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column (can only come from above)
    for i in range(1, rows):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp table
    for i in range(1, rows):
        for j in range(1, cols):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[-1][-1]

def count_distinct_subsequences(s: str, t: str) -> int:
    m, n = len(t), len(s)
    if m > n:
        return 0

    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for j in range(n + 1):
        dp[0][j] = 1  # An empty t has 1 subsequence in any prefix of s.

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if t[i - 1] == s[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i][j - 1]
            else:
                dp[i][j] = dp[i][j - 1]

    return dp[m][n]

