from typing import List

def linear_interpolation(x_values: List[float], y_values: List[float], x: float) -> float:
    if len(x_values) != len(y_values):
        raise ValueError("x_values and y_values must have the same length")

    if len(x_values) < 2:
        raise ValueError("x_values and y_values must contain at least two data points")

    sorted_indices = sorted(range(len(x_values)), key=lambda i: x_values[i])
    x_values = [x_values[i] for i in sorted_indices]
    y_values = [y_values[i] for i in sorted_indices]

    if x < x_values[0] or x > x_values[-1]:
        raise ValueError("x should be within the range of x_values")

    for i in range(len(x_values) - 1):
        if x_values[i] <= x <= x_values[i+1]:
            x0, x1 = x_values[i], x_values[i+1]
            y0, y1 = y_values[i], y_values[i+1]
            return y0 + (x - x0) * (y1 - y0) / (x1 - x0)

    raise ValueError("Failed to interpolate")

def polynomial_interpolation(x_values: List[float], y_values: List[float], x: float) -> float:
    if len(x_values) != len(y_values):
        raise ValueError("x_values and y_values must have the same length")

    if len(x_values) < 2:
        raise ValueError("x_values and y_values must contain at least two data points")

    def lagrange_poly(x, x_values, y_values):
        total = 0
        n = len(x_values)
        for i in range(n):
            term = y_values[i]
            for j in range(n):
                if i != j:
                    term *= (x - x_values[j]) / (x_values[i] - x_values[j])
            total += term
        return total

    return lagrange_poly(x, x_values, y_values)

