import heapq
from typing import List, Optional

def min_heap_operations(operations: List[str], values: List[int]) -> List[Optional[int]]:
    min_heap = []
    result = []

    for op, val in zip(operations, values):
        if op == "insert":
            heapq.heappush(min_heap, val)
        elif op == "extract_min":
            if min_heap:
                result.append(heapq.heappop(min_heap))
            else:
                result.append(None)  # to handle invalid extract_min operation
        elif op == "get_min":
            if min_heap:
                result.append(min_heap[0])
            else:
                result.append(None)  # to handle invalid get_min operation

    return result

