def search_files_with_tags(files, tags):
    """
    Returns a list of file names that contain all the specified tags.

    :param files: dict where keys are file names and values are lists of tags
    :param tags: list of tags to search for
    :return: list of file names that have all the specified tags
    """
    if not tags:
        return list(files.keys())

    def has_all_tags(file_tags, required_tags):
        return all(tag in file_tags for tag in required_tags)

    result = [file_name for file_name, file_tags in files.items() if has_all_tags(file_tags, tags)]
    return result

