def find_primes_in_range(start: int, end: int) -> list[int]:
    """
    Returns a list of all prime numbers within the range [start, end], inclusive.
    """
    if start > end:
        return []

    # Sieve of Eratosthenes to find all primes up to sqrt(end)
    def sieve(limit):
        is_prime = [True] * (limit + 1)
        p = 2
        while p * p <= limit:
            if is_prime[p]:
                for i in range(p * p, limit + 1, p):
                    is_prime[i] = False
            p += 1
        return [p for p in range(2, limit + 1) if is_prime[p]]

    import math
    sieve_limit = int(math.sqrt(end)) + 1
    small_primes = sieve(sieve_limit)

    # Use the small primes to mark non-primes in the range [start, end]
    is_prime_range = [True] * (end - start + 1)
    for prime in small_primes:
        # Find the starting point of marking for this prime
        start_index = max(prime * prime, start + (prime - start % prime) % prime)
        for j in range(start_index, end + 1, prime):
            is_prime_range[j - start] = False

    # Special case: 1 is not a prime number
    if start == 1:
        is_prime_range[0] = False
    if start == 0:
        if end >= 1:
            is_prime_range[1] = False
        if end >= 0:
            is_prime_range[0] = False

    return [num for num, is_prime in enumerate(is_prime_range, start=start) if is_prime]

def factorial(n: int) -> int:
    """
    Helper function to calculate the factorial of n recursively.
    """
    if n == 1:
        return 1
    else:
        return n * factorial(n-1)

def recursive_factorial_sum(n: int) -> int:
    """
    Function to calculate the sum of factorials from 1 to n recursively.
    """
    if n == 1:
        return 1
    else:
        return factorial(n) + recursive_factorial_sum(n-1)

