def longest_prefix_suffix(s):
    """
    Returns the longest prefix which is also a suffix in the given string.
    Note: The prefix and suffix cannot overlap.
    """
    n = len(s)
    lps = [0] * n  # lps array to store the length of the longest prefix suffix values for the prefix ending at i

    j = 0  # length of previous longest prefix suffix
    i = 1

    while i < n:
        if s[i] == s[j]:
            j += 1
            lps[i] = j
            i += 1
        else:
            if j != 0:
                j = lps[j-1]
            else:
                lps[i] = 0
                i += 1

    # lps[n-1] contains the length of the longest prefix which is also a suffix
    prefix_len = lps[-1]

    if prefix_len > 0 and prefix_len < n:
        return s[:prefix_len]
    else:
        return ""

