def sum_of_k_smallest_elements(nums: list[int], k: int) -> int:
    """
    Returns the sum of the k smallest elements in the given list of numbers.

    If k is greater than the length of the list, raises a ValueError.
    """
    if k < 0:
        raise ValueError("k must be non-negative")
    if k > len(nums):
        raise ValueError("Not enough elements in the list")

    sorted_nums = sorted(nums)
    return sum(sorted_nums[:k])

