def sum_of_divisors(n: int) -> int:
    def prime_factors(n):
        factors = {}
        d = 2
        while d * d <= n:
            while (n % d) == 0:
                if d in factors:
                    factors[d] += 1
                else:
                    factors[d] = 1
                n //= d
            d += 1
        if n > 1:
            factors[n] = 1
        return factors

    def sum_divisors_from_factors(factors):
        sum_divisors = 1
        for p, e in factors.items():
            sum_p = (p**(e+1) - 1) // (p - 1)
            sum_divisors *= sum_p
        return sum_divisors

    factors = prime_factors(n)
    return sum_divisors_from_factors(factors)

