def is_happy_string(s: str) -> bool:
    from collections import Counter

    # Step 1: Create a frequency dictionary
    frequency = Counter(s)

    # Step 2: Filter characters that occur more than once
    repeated_chars = {char: count for char, count in frequency.items() if count > 1}

    # Step 3: If no character occurs more than once, it's automatically happy
    if not repeated_chars:
        return True

    # Step 4: Get the list of frequencies of the repeated characters
    frequencies = list(repeated_chars.values())

    # Step 5: Check if all frequencies are the same
    return all(frequency == frequencies[0] for frequency in frequencies)

