def evaluate_expression(expression: str) -> int:
    def calculate(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()
        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)

    operators = []
    values = []
    i = 0
    while i < len(expression):
        char = expression[i]

        if char == ' ':
            i += 1
            continue

        if char.isdigit():
            num = 0
            while i < len(expression) and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            values.append(num)
            continue

        if char == '(':
            operators.append(char)

        elif char == ')':
            while operators and operators[-1] != '(':
                calculate(operators, values)
            operators.pop()  # Pop the '(' from the stack

        elif char in '+-':
            while (operators and operators[-1] in "+-" and
                   (char in '+-' or operators[-1] in '+-')):
                calculate(operators, values)
            operators.append(char)

        i += 1

    while operators:
        calculate(operators, values)

    return values[0]

