def longest_increasing_subsequence(arr: list) -> int:
    if not arr:
        return 0

    # Create an array to store the longest increasing subsequence length at each index
    lis = [1] * len(arr)

    # Iterate over each element of the array
    for i in range(1, len(arr)):
        for j in range(0, i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in the lis array
    return max(lis)

