from typing import List, Tuple
from collections import deque

def shortest_path(grid: List[List[str]]) -> int:
    def in_bounds(x, y):
        return 0 <= x < n and 0 <= y < m

    def is_empty(x, y):
        return grid[x][y] == ' '

    n, m = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (x, y, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if x == n - 1 and y == m - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if in_bounds(nx, ny) and is_empty(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

