def generate_distinct_permutations(s: str) -> list[str]:
    """
    Generates all distinct permutations of the given string.

    :param s: A string containing only lowercase alphabets.
    :return: A list containing all distinct permutations, each represented as a string.
    """
    def permute(current, remaining):
        if not remaining:
            results.add(current)
            return
        for i in range(len(remaining)):
            permute(current + remaining[i], remaining[:i] + remaining[i+1:])

    results = set()
    permute("", s)
    return sorted(list(results))

