def count_connected_components(graph: dict[int, list[int]]) -> int:
    """
    This function returns the number of connected components in an undirected graph using DFS.
    """
    def dfs(node, visited):
        stack = [node]
        while stack:
            current = stack.pop()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    visited = set()
    count = 0

    for node in graph:
        if node not in visited:
            count += 1
            visited.add(node)
            dfs(node, visited)

    return count

