def duplicate_count(nums: List[int]) -> int:
    """
    Returns the number of unique integers that appear more than once in the list.
    """
    element_count = {}
    for num in nums:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    duplicate_count = 0
    for count in element_count.values():
        if count > 1:
            duplicate_count += 1

    return duplicate_count

