def matrix_multiplication(matrix_a, matrix_b):
    """
    Multiplies two matrices and returns the resulting matrix.
    """
    if not matrix_a or not matrix_b:
        raise ValueError("Input matrices cannot be empty.")

    m, n = len(matrix_a), len(matrix_a[0])
    n_b, p = len(matrix_b), len(matrix_b[0])

    if n != n_b:
        raise ValueError("Number of columns of matrix_a must be equal to number of rows of matrix_b.")

    # Prepare the result matrix with zeros
    result = [[0] * p for _ in range(m)]

    # Sparse representation of matrix_a and matrix_b
    sparse_a = {}
    sparse_b = {}

    for i in range(m):
        for j in range(n):
            if matrix_a[i][j] != 0:
                if i not in sparse_a:
                    sparse_a[i] = {}
                sparse_a[i][j] = matrix_a[i][j]

    for i in range(n):
        for j in range(p):
            if matrix_b[i][j] != 0:
                if i not in sparse_b:
                    sparse_b[i] = {}
                sparse_b[i][j] = matrix_b[i][j]

    # Perform multiplication
    for i in sparse_a:
        for k in sparse_a[i]:
            if k in sparse_b:
                for j in sparse_b[k]:
                    result[i][j] += sparse_a[i][k] * sparse_b[k][j]

    return result

