def search_hierarchy(hierarchy, path):
    def search_helper(node, sub_path):
        if not sub_path:
            # Collect all objects from current node recursively
            if isinstance(node, list):
                return node
            elif isinstance(node, dict):
                objects = []
                for key in node:
                    objects.extend(search_helper(node[key], sub_path))
                return objects
            else:
                return []
        first, *rest = sub_path
        if first in node:
            return search_helper(node[first], rest)
        else:
            return []

    return search_helper(hierarchy, path)

