def is_palindrome(s: str) -> bool:
    def helper(start: int, end: int) -> bool:
        # Base case when the pointers have crossed each other or are the same
        if start >= end:
            return True
        # Check if characters at start and end are the same
        if s[start] != s[end]:
            return False
        # Recur for the next pair of characters
        return helper(start + 1, end - 1)

    return helper(0, len(s) - 1)

