def fibonacci_basic(n: int) -> int:
    """
    Returns the n-th Fibonacci number using a direct recursive method.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    if n == 0:
        return 0
    if n == 1:
        return 1
    return fibonacci_basic(n - 1) + fibonacci_basic(n - 2)

def fibonacci_optimized(n: int) -> int:
    """
    Returns the n-th Fibonacci number using memoization.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    fib_cache = {0: 0, 1: 1}

    def helper(x):
        if x in fib_cache:
            return fib_cache[x]
        fib_cache[x] = helper(x - 1) + helper(x - 2)
        return fib_cache[x]

    return helper(n)

