from typing import List, Tuple, Dict

def calculate_genre_scores(viewing_history: List[Tuple[str, int]]) -> Dict[str, float]:
    genres = ['Action', 'Comedy', 'Drama', 'Romance', 'Sci-Fi']
    genre_ratings = {genre: [] for genre in genres}

    for genre, rating in viewing_history:
        genre_ratings[genre].append(rating)

    genre_scores = {}
    for genre in genres:
        if genre_ratings[genre]:
            genre_scores[genre] = round(sum(genre_ratings[genre]) / len(genre_ratings[genre]), 2)
        else:
            genre_scores[genre] = 0.0

    return genre_scores

