from typing import List

def tic_tac_toe_outcome(board: List[List[str]]) -> str:
    def check_winner(marker):
        # Check rows and columns
        for i in range(3):
            if all([cell == marker for cell in board[i]]) or all([board[j][i] == marker for j in range(3)]):
                return True
        # Check diagonals
        if all([board[i][i] == marker for i in range(3)]) or all([board[i][2-i] == marker for i in range(3)]):
            return True
        return False

    if check_winner('X'):
        return 'X wins'
    if check_winner('O'):
        return 'O wins'

    # Check for empty cells
    if any(cell == '' for row in board for cell in row):
        return 'Unfinished'

    return 'Draw'

