def custom_xor_encrypt(message: bytes, key: bytes) -> bytes:
    """
    Encrypts the message using XOR with the provided key.
    """
    if not key:
        return message

    encrypted_message = bytearray()
    key_length = len(key)
    for i, byte in enumerate(message):
        encrypted_message.append(byte ^ key[i % key_length])

    return bytes(encrypted_message)

def custom_xor_decrypt(encrypted_message: bytes, key: bytes) -> bytes:
    """
    Decrypts the message that was encrypted using XOR with the provided key.
    """
    # Since XOR encryption is symmetric, decryption is the same as encryption
    return custom_xor_encrypt(encrypted_message, key)

def caesar_cipher(text: str, shift: int) -> str:
    """
    Encrypt the given text using the Caesar Cipher technique.
    Parameters:
    text (str): the input text to be encrypted.
    shift (int): the shift number (1 ≤ |shift| ≤ 25).

    Returns:
    str: the encrypted text.
    """
    result = []

    for char in text:
        if char.isupper():
            result.append(chr((ord(char) - ord('A') + shift) % 26 + ord('A')))
        elif char.islower():
            result.append(chr((ord(char) - ord('a') + shift) % 26 + ord('a')))
        else:
            result.append(char)

    return ''.join(result)

