def shift_string(s: str, shift: int) -> str:
    def shift_char(c, shift):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + shift) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + shift) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c, shift) for c in s)

