import heapq
from typing import List, Tuple

def is_valid_position(position, grid):
    r, c = position
    return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == 0

def escape_maze(grid: List[List[int]], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start_x, start_y = start
    goal_x, goal_y = goal

    dist = {start: 0}
    prev = {start: None}
    pq = [(0, start)]  # (distance, (x, y))

    while pq:
        current_distance, current_position = heapq.heappop(pq)

        if current_position == goal:
            path = []
            while current_position:
                path.append(current_position)
                current_position = prev[current_position]
            return path[::-1]

        for direction in directions:
            neighbor = (current_position[0] + direction[0], current_position[1] + direction[1])

            if is_valid_position(neighbor, grid):
                distance = current_distance + 1

                if neighbor not in dist or distance < dist[neighbor]:
                    dist[neighbor] = distance
                    priority = distance
                    heapq.heappush(pq, (priority, neighbor))
                    prev[neighbor] = current_position

    return []  # If there's no path to the goal

