from collections import defaultdict
from typing import List, Tuple

def most_influential_employee(connections: List[Tuple[int, int]]) -> int:
    connection_count = defaultdict(int)

    for a, b in connections:
        connection_count[a] += 1
        connection_count[b] += 1

    if not connection_count:
        return -1

    max_connections = -1
    most_influential = None

    for employee, count in connection_count.items():
        if count > max_connections or (count == max_connections and employee < most_influential):
            max_connections = count
            most_influential = employee

    return most_influential

