def evaluate_expression(expression: str) -> float:
    """
    Evaluates a mathematical expression string and returns the result as a float.

    :param expression: A string representing a mathematical expression.
    :return: The result of the evaluated expression as a float.
    """
    try:
        # Remove any possible whitespaces in the expression
        expression = expression.replace(" ", "")
        # Evaluate the expression using Python's eval function
        result = eval(expression)
        return float(result)
    except ZeroDivisionError:
        raise ZeroDivisionError("Division by zero is not allowed.")
    except SyntaxError:
        raise ValueError("Invalid expression syntax.")
    except Exception as e:
        raise ValueError(f"Error evaluating expression: {e}")

