from typing import List

def maximal_square(matrix: List[List[int]]) -> int:
    if not matrix or not matrix[0]:
        return 0

    rows = len(matrix)
    cols = len(matrix[0])
    dp = [[0] * cols for _ in range(rows)]
    max_side = 0

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side * max_side

def is_in_order(timestamps: list[int]) -> bool:
    """
    Determines if the given list of timestamps is in non-decreasing order.

    :param timestamps: List of integers representing timestamps
    :return: Boolean value indicating whether timestamps are in non-decreasing order
    """
    for i in range(1, len(timestamps)):
        if timestamps[i] < timestamps[i - 1]:
            return False
    return True

