def generate_zigzag_pattern(n: int, m: int) -> list:
    matrix = []
    num = 1
    for i in range(n):
        row = []
        for j in range(m):
            row.append(num)
            num += 1
        if i % 2 == 1:
            row.reverse()
        matrix.append(row)
    return matrix

def consecutive_subsequence_sum(nums, target):
    n = len(nums)
    for start in range(n):
        current_sum = 0
        for end in range(start, n):
            current_sum += nums[end]
            if current_sum == target:
                return True
            elif current_sum > target:
                break
    return False

def calculate_median(nums: list[int | float]) -> float:
    """
    Calculate the median of a list of numbers.
    If the list length is even, it returns the average of the two middle numbers.
    If the list is empty, raises a ValueError.
    """
    if not nums:
        raise ValueError("List is empty")

    nums.sort()
    n = len(nums)
    mid = n // 2

    if n % 2 == 0:
        median = (nums[mid - 1] + nums[mid]) / 2
    else:
        median = nums[mid]

    return float(median)

