def calculate(expression):
    def operate(op, second, first):
        if op == '+':
            return first + second
        elif op == '-':
            return first - second
        elif op == '*':
            return first * second
        elif op == '/':
            return int(first / second)

    def precedence(op):
        if op == '+' or op == '-':
            return 1
        if op == '*' or op == '/':
            return 2
        return 0

    operators = []
    values = []
    i = 0
    while i < len(expression):
        if expression[i].isdigit() or (expression[i] == '-' and (i == 0 or expression[i-1] in "+-*/")):
            j = i + 1
            while j < len(expression) and expression[j].isdigit():
                j += 1
            values.append(int(expression[i:j]))
            i = j
        else:
            while (operators and precedence(operators[-1]) >= precedence(expression[i])):
                values.append(operate(operators.pop(), values.pop(), values.pop()))
            operators.append(expression[i])
            i += 1
    while operators:
        values.append(operate(operators.pop(), values.pop(), values.pop()))

    return values[-1]

