from typing import List

def max_triplet_xor(arr: List[int]) -> int:
    """
    Given an array of integers, finds the maximum XOR value of any triplet (a, b, c).
    """
    n = len(arr)
    if n < 3:
        return 0  # Not enough elements to form a triplet

    max_val = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                current_xor = arr[i] ^ arr[j] ^ arr[k]
                if current_xor > max_val:
                    max_val = current_xor

    return max_val

