def sequence_sum(sequence: str) -> int:
    """
    Calculate the sum of integers in the string sequence.
    """
    if not sequence:
        return 0

    try:
        numbers = [int(x) for x in sequence.split(',')]
    except ValueError:
        raise ValueError("Invalid input: sequence must contain only integers separated by commas")

    total_sum = 0
    for num in numbers:
        total_sum += num

    return total_sum


def sequence_product(sequence: str) -> int:
    """
    Calculate the product of integers in the string sequence.
    """
    if not sequence:
        return 1

    try:
        numbers = [int(x) for x in sequence.split(',')]
    except ValueError:
        raise ValueError("Invalid input: sequence must contain only integers separated by commas")

    total_product = 1
    for num in numbers:
        total_product *= num

    return total_product

