def extract_keywords(feedback, keywords, case_sensitive=True):
    """
    Extracts and returns feedback entries that contain specific keywords.

    Parameters:
    feedback (list of str): List of feedback entries.
    keywords (list of str): List of keywords to search for.
    case_sensitive (bool): Whether the search should be case sensitive.

    Returns:
    dict: A dictionary where keys are keywords and values are lists of feedback entries containing those keywords.
    """
    result = {keyword: [] for keyword in keywords}

    for entry in feedback:
        for keyword in keywords:
            if case_sensitive:
                if keyword in entry:
                    result[keyword].append(entry)
            else:
                if keyword.lower() in entry.lower():
                    result[keyword].append(entry)

    return result

