from typing import List

def calculate_total_resistance(resistors: List[List[float]]) -> float:
    if not resistors or not all(resistors) or any(r <= 0 for group in resistors for r in group):
        raise ValueError("Input must be a list of lists with positive resistance values.")

    total_resistance = 0
    for parallel_group in resistors:
        reciprocal_sum = sum(1/r for r in parallel_group)
        parallel_resistance = 1 / reciprocal_sum
        total_resistance += parallel_resistance

    return round(total_resistance, 3)

