    components = path.split("/")
    stack = []

    for part in components:
        if part == "..":
            if stack:
                stack.pop()
        elif part and part != ".":
            stack.append(part)

    simplified_path = "/" + "/".join(stack)
    return simplified_path

def reorder_heights(heights):
    heights.sort()

    if len(heights) == 1:
        return heights

    result = []
    left = 0
    right = len(heights) - 1

    # Use a two-pointer approach to alternate between the smallest and largest remaining heights
    while left <= right:
        if left == right:
            result.append(heights[left])
        else:
            result.append(heights[left])
            result.append(heights[right])
        left += 1
        right -= 1

    # Verify the result to see if it satisfies the conditions
    for i in range(1, len(result)):
        if abs(result[i] - result[i-1]) < 1:
            return []

    return result

