def to_base64(input_str: str) -> str:
    if not input_str:
        raise ValueError("Empty string was passed to the function")

    base64_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    binary_string = ''.join(f"{ord(char):08b}" for char in input_str)

    padding_length = (6 - len(binary_string) % 6) % 6
    binary_string = binary_string + '0' * padding_length

    base64_string = ''
    for i in range(0, len(binary_string), 6):
        base64_string += base64_chars[int(binary_string[i:i+6], 2)]

    while len(base64_string) % 4 != 0:
        base64_string += '='

    return base64_string

