def detect_cycle_in_directed_graph(V, graph):
    def dfs(vertex, visited, rec_stack):
        visited[vertex] = True
        rec_stack[vertex] = True

        for neighbor in graph[vertex]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, rec_stack):
                    return True
            elif rec_stack[neighbor]:
                return True

        rec_stack[vertex] = False
        return False

    visited = [False] * V
    rec_stack = [False] * V

    for node in range(V):
        if not visited[node]:
            if dfs(node, visited, rec_stack):
                return True
    return False

from collections import defaultdict, deque

def min_semesters(tasks: dict) -> int:
    def topological_sort_with_levels(graph):
        in_degree = {node: 0 for node in graph}
        for node in graph:
            for neighbor in graph[node]:
                in_degree[neighbor] += 1

        queue = deque([node for node in graph if in_degree[node] == 0])
        levels = 0
        count_of_processed_nodes = 0

        while queue:
            next_level = deque()
            while queue:
                node = queue.popleft()
                count_of_processed_nodes += 1
                for neighbor in graph[node]:
                    in_degree[neighbor] -= 1
                    if in_degree[neighbor] == 0:
                        next_level.append(neighbor)
            queue = next_level
            levels += 1

        if count_of_processed_nodes == len(graph):
            return levels
        return -1

    return topological_sort_with_levels(tasks)

