def find_central_element(data):
    """
    Returns the central element(s) of a sorted list.

    If the list has an odd number of elements, return the single central element.
    If the list has an even number of elements, return the two central elements as a tuple.
    """
    n = len(data)
    mid = n // 2
    if n % 2 == 1:
        return data[mid]
    else:
        return (data[mid - 1], data[mid])

def is_interleave(s1: str, s2: str, s3: str) -> bool:
    """
    Determines if s3 is formed by an interleaving of s1 and s2.
    """
    m, n = len(s1), len(s2)

    if m + n != len(s3):
        return False

    dp = [[False] * (n+1) for _ in range(m+1)]
    dp[0][0] = True

    for i in range(1, m+1):
        dp[i][0] = dp[i-1][0] and s1[i-1] == s3[i-1]

    for j in range(1, n+1):
        dp[0][j] = dp[0][j-1] and s2[j-1] == s3[j-1]

    for i in range(1, m+1):
        for j in range(1, n+1):
            dp[i][j] = (dp[i-1][j] and s1[i-1] == s3[i+j-1]) or (dp[i][j-1] and s2[j-1] == s3[i+j-1])

    return dp[m][n]

