def count_connected_components(graph):
    """
    Returns the number of connected components in an undirected graph represented by an adjacency list.
    """
    def dfs(node, visited):
        stack = [node]
        while stack:
            current = stack.pop()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    visited = set()
    num_components = 0

    for i in range(len(graph)):
        if i not in visited:
            num_components += 1
            visited.add(i)
            dfs(i, visited)

    return num_components

