from collections import Counter
import heapq

def rearrange_string(s: str) -> str:
    frequency = Counter(s)
    max_heap = [(-freq, char) for char, freq in frequency.items()]
    heapq.heapify(max_heap)

    prev_char = None
    prev_freq = 0
    result = []

    while max_heap or prev_freq < 0:
        if not max_heap and prev_freq < 0:
            return ""

        if max_heap:
            freq, char = heapq.heappop(max_heap)
            result.append(char)
            if prev_freq < 0:
                heapq.heappush(max_heap, (prev_freq, prev_char))
            prev_char = char
            prev_freq = freq + 1

    return "".join(result)

