def calculate_tree_height(tree: dict) -> int:
    """
    Calculate the height of the binary tree represented by a nested dictionary.

    Parameters:
    tree (dict): The nested dictionary representing the tree.

    Returns:
    int: The height of the tree.
    """
    if not tree:
        return -1

    def height(node):
        if not node:
            return 0
        return 1 + max((height(child) for child in node.values()), default=-1)

    return max((height(tree[root]) for root in tree), default=-1)

