def top_sales_reps(sales_data: dict[str, list[float]], n: int) -> list[tuple[str, float]]:
    if n <= 0:
        raise ValueError("The number of top performers 'n' must be a positive integer.")

    for sales in sales_data.values():
        if any(sale < 0 for sale in sales):
            raise ValueError("Sales figures can not be negative.")

    total_sales = {rep: sum(sales) for rep, sales in sales_data.items()}
    sorted_sales = sorted(total_sales.items(), key=lambda x: x[1], reverse=True)

    return sorted_sales[:n]

