from typing import Iterator, List, Optional
from collections import deque

def optimized_average(data_stream: Iterator[int], window_size: int) -> Iterator[Optional[float]]:
    if window_size <= 0:
        raise ValueError("Window size must be a positive integer.")

    window = deque()
    current_sum = 0.0

    for value in data_stream:
        window.append(value)
        current_sum += value

        if len(window) > window_size:
            current_sum -= window.popleft()

        if len(window) == window_size:
            yield round(current_sum / window_size, 2)
        else:
            yield None

