from collections import deque

def process_events(events: list[tuple[str, int]]) -> list[int]:
    """
    Simulates processing of a list of events involving queue operations.

    Args:
    events: A list of tuples, where each tuple is an event ("enqueue", value) or ("dequeue", 0).

    Returns:
    The final state of the queue as a list of integers.

    Raises:
    ValueError: If an invalid event type is encountered.
    IndexError: If a "dequeue" event occurs when the queue is empty.
    """
    queue = deque()

    for event in events:
        if len(event) != 2:
            raise ValueError("Event must be a tuple with 2 elements")

        event_type, value = event

        if event_type == "enqueue":
            queue.append(value)
        elif event_type == "dequeue":
            if not queue:
                raise IndexError("Dequeue operation attempted on an empty queue")
            queue.popleft()
        else:
            raise ValueError(f"Invalid event type: {event_type}")

    return list(queue)

