import heapq
from typing import List, Tuple

def shortest_travel_time(num_cities: int, roads: List[Tuple[int, int, int]], start: int, end: int) -> int:
    # Create a graph from the roads
    graph = {i: [] for i in range(num_cities)}
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Dijkstra's algorithm initialization
    heap = [(0, start)]  # (distance, node)
    distances = {i: float('inf') for i in range(num_cities)}
    distances[start] = 0
    visited = set()

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        if current_node in visited:
            continue

        visited.add(current_node)

        # If we reach the end city, return the distance
        if current_node == end:
            return current_distance

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))

    # If end was not reached
    return -1

