def count_connected_components(adj_matrix):
    """
    Returns the number of connected components in the undirected graph represented by the adjacency matrix.
    """
    def dfs(node):
        stack = [node]
        while stack:
            curr = stack.pop()
            for neighbor, connected in enumerate(adj_matrix[curr]):
                if connected and neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    visited = set()
    components = 0

    for node in range(len(adj_matrix)):
        if node not in visited:
            visited.add(node)
            dfs(node)
            components += 1

    return components

def kmp_search(txt: str, pat: str) -> int:
    def compute_lps(pattern):
        lps = [0] * len(pattern)
        length = 0
        i = 1
        while i < len(pattern):
            if pattern[i] == pattern[length]:
                length += 1
                lps[i] = length
                i += 1
            else:
                if length != 0:
                    length = lps[length - 1]
                else:
                    lps[i] = 0
                    i += 1
        return lps

    n, m = len(txt), len(pat)
    if m == 0:
        return 0

    lps = compute_lps(pat)
    i, j = 0, 0
    while i < n:
        if pat[j] == txt[i]:
            i += 1
            j += 1

        if j == m:
            return i - j
        elif i < n and pat[j] != txt[i]:
            if j != 0:
                j = lps[j - 1]
            else:
                i += 1

    return -1

