from typing import List

def can_distribute(weights: List[int], k: int, max_weight: int) -> bool:
    current_sum = 0
    required_trucks = 1

    for weight in weights:
        if current_sum + weight > max_weight:
            required_trucks += 1
            current_sum = weight
            if required_trucks > k:
                return False
        else:
            current_sum += weight

    return True

def load_balancer(weights: List[int], k: int) -> int:
    left = max(weights)
    right = sum(weights)

    while left < right:
        mid = (left + right) // 2
        if can_distribute(weights, k, mid):
            right = mid
        else:
            left = mid + 1

    return left

