def count_unique_substrings(s: str) -> int:
    """
    Counts the number of unique substrings in a given string.

    :param s: The input string containing only lowercase English letters.
    :return: The total number of unique substrings.
    """
    substrings = set()

    for i in range(len(s)):
        for j in range(i, len(s)):
            substrings.add(s[i:j+1])

    return len(substrings)

