from collections import deque
from typing import List, Tuple, Optional

def find_shortest_path(maze: List[List[int]], start: Tuple[int, int], target: Tuple[int, int]) -> Optional[int]:
    n, m = len(maze), len(maze[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_in_bounds(x: int, y: int) -> bool:
        return 0 <= x < n and 0 <= y < m

    visited = set()
    queue = deque([(start[0], start[1], 0)])  # (x, y, distance)
    visited.add(start)

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == target:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_in_bounds(nx, ny) and (nx, ny) not in visited and maze[nx][ny] == 0:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return None

def generate_ngrams(s, n):
    """Generate n-grams for a given string and length."""
    return {s[i:i+n] for i in range(len(s) - n + 1)}

def jaccard_similarity(s1, s2, n):
    """
    Returns the Jaccard similarity coefficient between two strings based on their n-grams.
    """
    if n > len(s1) or n > len(s2):
        return 0.0

    ngrams1 = generate_ngrams(s1, n)
    ngrams2 = generate_ngrams(s2, n)

    intersection = ngrams1.intersection(ngrams2)
    union = ngrams1.union(ngrams2)

    if not union:
        return 0.0  # Avoid division by zero

    return len(intersection) / len(union)

from collections import deque

def shortest_path(graph, start, end):
    """
    Returns the length of the shortest path from the start node to the end node in an unweighted, undirected graph.
    If no path exists, return -1.
    """
    if start == end:
        return 0

    visited = set()
    queue = deque([(start, 0)])  # (current_node, current_distance)

    while queue:
        current_node, current_distance = queue.popleft()
        if current_node == end:
            return current_distance

        visited.add(current_node)

        for neighbor in graph.get(current_node, []):
            if neighbor not in visited:
                queue.append((neighbor, current_distance + 1))
                visited.add(neighbor)

    return -1

