def letter_frequency_counter(text: str) -> dict:
    """
    Counts the frequency of each letter in a given string, case-insensitive.
    Non-alphabetic characters are ignored.

    Args:
    text (str): The input string to be analyzed.

    Returns:
    dict: A dictionary with letters as keys and their frequencies as values.
    """
    text = text.lower()
    frequency = {}

    for char in text:
        if char.isalpha():
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

    return frequency

