from typing import List

def transform_array(arr: List[int]) -> List[int]:
    def sum_of_digits(n: int) -> int:
        return sum(int(digit) for digit in str(abs(n)))

    def product_of_digits(n: int) -> int:
        product = 1
        for digit in str(abs(n)):
            product *= int(digit)
        return product

    result = []
    for num in arr:
        if num % 2 == 0:
            result.append(sum_of_digits(num))
        else:
            result.append(product_of_digits(num))
    return result

