def longest_consecutive_sequence(dna: str) -> int:
    """
    Finds the length of the longest consecutive sequence of a single character in the DNA strand.
    :param dna: A string representing the DNA sequence
    :return: The length of the longest consecutive sequence of a single character
    """
    if not dna:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(dna)):
        if dna[i] == dna[i - 1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    return max(max_length, current_length)

