import re

def are_anagrams(str1: str, str2: str) -> bool:
    """
    Check if str1 and str2 are anagrams of each other, considering:
    - Only alphabet characters (ignore digits, spaces, punctuation)
    - Case insensitivity
    Raise TypeError if inputs are not strings.
    """
    if not isinstance(str1, str) or not isinstance(str2, str):
        raise TypeError("Both inputs must be of type str")

    def clean_string(s):
        return sorted(re.sub(r'[^a-zA-Z]', '', s).lower())

    return clean_string(str1) == clean_string(str2)

def encode_message(message: str, shift: int) -> str:
    encoded_message = []

    for char in message:
        if char.isalpha():
            new_char = chr((ord(char.lower()) - 97 + shift) % 26 + 97)
            if char.isupper():
                new_char = new_char.upper()
            encoded_message.append(new_char)
        else:
            encoded_message.append(char)

    return ''.join(encoded_message)

def decode_message(encoded_message: str, shift: int) -> str:
    decoded_message = []

    for char in encoded_message:
        if char.isalpha():
            new_char = chr((ord(char.lower()) - 97 - shift) % 26 + 97)
            if char.isupper():
                new_char = new_char.upper()
            decoded_message.append(new_char)
        else:
            decoded_message.append(char)

    return ''.join(decoded_message)

