from typing import List

def find_palindromic_substrings(s: str) -> List[str]:
    palindromes = set()

    def is_palindrome(sub: str) -> bool:
        return sub == sub[::-1]

    n = len(s)
    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            if is_palindrome(substring):
                palindromes.add(substring)

    return sorted(palindromes, key=lambda x: (len(x), x))

