def edit_distance(str1: str, str2: str) -> int:
    n = len(str1)
    m = len(str2)

    # Create a 2D array to store the distance
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the distances for converting empty string to a string
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    # Fill the dp array
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # Characters match
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],  # Deletion
                                   dp[i][j - 1],  # Insertion
                                   dp[i - 1][j - 1])  # Substitution

    return dp[n][m]

def solve_maze(maze, start, end):

    def is_valid_move(x, y):
        return (
            0 <= x < len(maze) and
            0 <= y < len(maze[0]) and
            maze[x][y] == ' '
        )

    def backtrack(x, y):
        # If we've reached the end, return True
        if (x, y) == end:
            return True

        # Mark as visited
        maze[x][y] = '#'

        # Explore possible directions
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if is_valid_move(nx, ny) and backtrack(nx, ny):
                return True

        # Unmark as visited (backtrack)
        maze[x][y] = ' '

        # If no path found
        return False

    return backtrack(start[0], start[1])

