def count_robot_paths(m, n):
    """
    Returns the number of unique paths in a m x n grid where the robot can only move right or down.
    """
    if m == 1 and n == 1:
        return 1

    dp = [[0] * n for _ in range(m)]

    for i in range(m):
        dp[i][0] = 1

    for j in range(n):
        dp[0][j] = 1

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

