def sum_of_unique_prime_factors(n: int) -> int:
    def prime_factors(num):
        factors = set()
        # Check for number of 2s in the factorization
        while num % 2 == 0:
            factors.add(2)
            num = num // 2
        # Now check for odd factors
        for i in range(3, int(num**0.5) + 1, 2):
            while num % i == 0:
                factors.add(i)
                num = num // i
        # This condition is to check if num is a prime
        # number greater than 2
        if num > 2:
            factors.add(num)
        return factors

    return sum(prime_factors(n))

