def factorial(n: int, method: str) -> int:
    """
    Compute the factorial of a given non-negative integer `n` using the specified method.

    Parameters:
    n (int): Non-negative integer for which the factorial is to be computed.
    method (str): Method to use for computation, either 'iterative' or 'recursive'.

    Returns:
    int: Factorial of the given number `n`. If the method input is invalid, return -1.
    """
    if method == 'iterative':
        return iterative_factorial(n)
    elif method == 'recursive':
        return recursive_factorial(n)
    else:
        return -1

def iterative_factorial(n: int) -> int:
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def recursive_factorial(n: int) -> int:
    if n == 0:
        return 1
    return n * recursive_factorial(n - 1)

