def generate_note_hierarchy(notes, root_tag):
    """
    Constructs a nested tag hierarchy starting from the root_tag.

    Args:
    notes (List[Dict[str, Any]]): A list of dictionaries where each dictionary represents a note.
    root_tag (str): The starting tag to build the hierarchy from.

    Returns:
    Dict[str, Any]: A dictionary representing the hierarchy of tags starting from the root_tag.
    """
    def insert_into_hierarchy(hierarchy, path, note_id):
        """Helper function to insert note into the hierarchy given its path."""
        for tag in path:
            if tag not in hierarchy:
                hierarchy[tag] = {}
            hierarchy = hierarchy[tag]
        if '_notes' not in hierarchy:
            hierarchy['_notes'] = []
        hierarchy['_notes'].append(note_id)

    filtered_notes = [note for note in notes if root_tag in note['tags']]

    root_index = None
    for note in filtered_notes:
        if root_tag in note['tags']:
            root_index = note['tags'].index(root_tag)
        break

    if root_index is None:
        return {}

    hierarchy = {}

    for note in filtered_notes:
        path = note['tags'][root_index + 1 :]
        insert_into_hierarchy(hierarchy, path, note['id'])

    return hierarchy

