def can_solve_maze(maze):
    def find_start(maze):
        for i in range(len(maze)):
            for j in range(len(maze[i])):
                if maze[i][j] == 'S':
                    return i, j
        return None

    def is_in_bound(maze, i, j):
        return 0 <= i < len(maze) and 0 <= j < len(maze[0])

    def dfs(maze, visited, i, j):
        if not is_in_bound(maze, i, j) or maze[i][j] == '#' or visited[i][j]:
            return False
        if maze[i][j] == 'E':
            return True

        visited[i][j] = True
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        for di, dj in directions:
            ni, nj = i + di, j + dj
            if dfs(maze, visited, ni, nj):
                return True

        visited[i][j] = False
        return False

    start = find_start(maze)
    if not start:
        return False

    visited = [[False for _ in range(len(maze[0]))] for _ in range(len(maze))]
    return dfs(maze, visited, start[0], start[1])

from typing import List

def dist_count_subarrays_with_sum(arr: List[int], k: int) -> int:
    # Dictionary to store the cumulative sum and its frequency
    cumulative_sum_frequency = {}
    cumulative_sum_frequency[0] = 1
    cumulative_sum = 0
    count = 0

    for num in arr:
        cumulative_sum += num
        desired_sum = cumulative_sum - k
        if desired_sum in cumulative_sum_frequency:
            count += cumulative_sum_frequency[desired_sum]
        if cumulative_sum in cumulative_sum_frequency:
            cumulative_sum_frequency[cumulative_sum] += 1
        else:
            cumulative_sum_frequency[cumulative_sum] = 1

    return count

