def knapsack(max_weight: int, items: list[tuple[int, int]]) -> int:
    """
    Determine the maximum value of items that can be placed in a truck given its weight capacity.

    Parameters:
    max_weight (int): The maximum weight capacity of the truck.
    items (list of tuples): Each tuple contains (weight of the item, value of the item).

    Returns:
    int: The maximum value that can be carried in the truck.
    """
    if max_weight < 0:
        raise ValueError("max_weight must be a non-negative integer")
    for weight, value in items:
        if weight < 0 or value < 0:
            raise ValueError("Item weights and values must be non-negative integers")

    dp = [0] * (max_weight + 1)

    for weight, value in items:
        for w in range(max_weight, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)

    return dp[max_weight]

