import heapq

def shortest_path(graph, start_node, end_node):
    """
    Find the shortest path in a weighted directed graph.

    @param graph: Dictionary representing the adjacency list of the graph.
                  Each key is a node, and the value is a list of tuples (neighbor, weight).
    @param start_node: The node to start the path from.
    @param end_node: The node to end the path at.

    @return: A tuple containing the total cost of the shortest path and the path itself as a list of nodes.
             If there is no path from start_node to end_node, return (float('inf'), []).
    """
    # Priority queue to keep track of nodes to explore
    pq = [(0, start_node, [])]
    # Dictionary to store the best cost to reach each node
    min_cost = {start_node: 0}

    while pq:
        current_cost, current_node, path = heapq.heappop(pq)

        # If we've reached the end_node, return the result
        if current_node == end_node:
            return (current_cost, path + [current_node])

        # Continue to its neighbors
        for neighbor, weight in graph.get(current_node, []):
            total_cost = current_cost + weight
            if neighbor not in min_cost or total_cost < min_cost[neighbor]:
                min_cost[neighbor] = total_cost
                heapq.heappush(pq, (total_cost, neighbor, path + [current_node]))

    # If there's no path from start_node to end_node
    return (float('inf'), [])

