from typing import List

def find_common_elements(*lists: List[int]) -> List[int]:
    if not lists:
        return []

    # Convert the first list to a set to start the intersection process
    common_elements = set(lists[0])

    # Intersect with each subsequent list
    for lst in lists[1:]:
        common_elements &= set(lst)

    # Return the sorted list of common elements
    return sorted(common_elements)

