def move_character(grid, moves):
    # Starting position
    row, col = 0, 0
    rows, cols = len(grid), len(grid[0])

    move_dict = {
        'U': (-1, 0),
        'D': (1, 0),
        'L': (0, -1),
        'R': (0, 1)
    }

    for move in moves:
        new_row = row + move_dict[move][0]
        new_col = col + move_dict[move][1]

        # Check if new position is within grid bounds and not an obstacle
        if 0 <= new_row < rows and 0 <= new_col < cols and grid[new_row][new_col] != '#':
            row, col = new_row, new_col

    return (row, col)

