def has_cycle(graph):
    """
    Returns True if the directed graph has a cycle, False otherwise.
    :param graph: Dict[str, List[str]]
    """
    def visit(vertex):
        if vertex in temp:
            return True
        if vertex in perm:
            return False
        temp.add(vertex)
        for neighbor in graph.get(vertex, []):
            if visit(neighbor):
                return True
        temp.remove(vertex)
        perm.add(vertex)
        return False

    temp = set()
    perm = set()

    for node in graph:
        if visit(node):
            return True

    return False

