from typing import Sequence
import bisect

def longest_increasing_subsequence(nums: Sequence[int] | None = None) -> int:
    if nums is None or len(nums) == 0:
        raise ValueError("Input sequence should not be empty")

    dp = []
    for num in nums:
        pos = bisect.bisect_left(dp, num)
        if pos == len(dp):
            dp.append(num)
        else:
            dp[pos] = num

    return len(dp)

