from heapq import heappop, heappush
import sys

def dijkstra_delivery_routes(grid, init, deliveries, cost):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dijkstra(start):
        heap = [(0, start)]
        distances = {start: 0}
        previous = {start: None}

        while heap:
            cur_cost, (x, y) = heappop(heap)
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < rows and 0 <= ny < cols and grid[nx][ny] == 0:
                    next_cost = cur_cost + cost
                    if (nx, ny) not in distances or next_cost < distances[(nx, ny)]:
                        distances[(nx, ny)] = next_cost
                        previous[(nx, ny)] = (x, y)
                        heappush(heap, (next_cost, (nx, ny)))

        return previous

    def get_path(previous, target):
        path = []
        while target is not None:
            path.append(target)
            target = previous[target]
        path.reverse()
        return path

    previous = dijkstra(init)
    routes = {}

    for target in deliveries:
        if target in previous:
            routes[target] = get_path(previous, target)
        else:
            routes[target] = None

    return routes

def unique_staircase_climb(n):
    """
    Returns the number of unique ways to climb a staircase with 'n' steps
    where no step size is taken more than twice consecutively.
    """
    if n == 0:
        return 1
    if n == 1:
        return 1
    if n == 2:
        return 2

    dp = [0] * (n + 1)
    dp[0], dp[1], dp[2] = 1, 1, 2

    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2] + dp[i - 3]

    return dp[n]

