def search_product(products, **criteria):
    """
    Searches for products based on the given search criteria.

    Args:
        products (list of dict): The product catalog.
        criteria (dict): The search criteria which may include 'name', 'category',
                         'price' (as a tuple of (min_price, max_price)), and 'available'.

    Returns:
        list of dict: The list of products that match the search criteria.
    """
    results = products
    for key, value in criteria.items():
        if key == "price":
            results = [
                product for product in results
                if value[0] <= product['price'] <= value[1]
            ]
        elif key == "name" or key == "category":
            results = [
                product for product in results
                if value.lower() in product[key].lower()
            ]
        elif key == "available":
            results = [
                product for product in results
                if product[key] == value
            ]
    return results

