from typing import List, Dict

def analyze_stock_prices(prices: List[int]) -> Dict[str, int]:
    """
    Analyzes a list of stock prices to determine the best buy and sell days
    for maximum profit.

    Args:
    prices (List[int]): A list of integers representing daily stock prices.

    Returns:
    Dict[str, int]: A dictionary containing:
        - 'buy_day': index of the best day to buy (int)
        - 'sell_day': index of the best day to sell (int)
        - 'max_profit': maximum profit possible (int)
    """
    if not prices or len(prices) < 2:
        return {'buy_day': -1, 'sell_day': -1, 'max_profit': 0}

    min_price_day = 0
    max_profit = 0
    buy_day = -1
    sell_day = -1

    for current_day in range(1, len(prices)):
        if prices[current_day] < prices[min_price_day]:
            min_price_day = current_day

        current_profit = prices[current_day] - prices[min_price_day]

        if current_profit > max_profit:
            max_profit = current_profit
            buy_day = min_price_day
            sell_day = current_day

    if max_profit == 0:
        return {'buy_day': -1, 'sell_day': -1, 'max_profit': 0}

    return {'buy_day': buy_day, 'sell_day': sell_day, 'max_profit': max_profit}

