def find_min(rotated_array):
    """
    This function finds the minimum element in a rotated sorted array.
    """
    if not rotated_array:
        raise ValueError("The input array cannot be empty")

    left, right = 0, len(rotated_array) - 1
    while left < right:
        mid = (left + right) // 2

        if rotated_array[mid] > rotated_array[right]:
            # The minimum value is in the right part
            left = mid + 1
        else:
            # The minimum value is in the left part including mid
            right = mid

    return rotated_array[left]

