from typing import List, Dict

def lighting_schedule(graph: List[List[int]], rooms: Dict[int, str]) -> List[str]:
    def topological_sort(node, visited, stack):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                topological_sort(neighbor, visited, stack)
        stack.append(node)

    num_rooms = len(rooms)
    visited = [False] * num_rooms
    stack = []

    for i in range(num_rooms):
        if not visited[i]:
            topological_sort(i, visited, stack)

    ordered_indices = stack[::-1]
    result = [rooms[idx] for idx in ordered_indices]
    return result

