from typing import List

def zigzag(arr: List[int]) -> List[int]:
    n = len(arr)
    if n < 2:
        return arr

    flag = True
    for i in range(n-1):
        if flag:
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
        else:
            if arr[i] < arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
        flag = not flag
    return arr

