def determine_winner(board):
    """
    Determines the winner of a Tic-Tac-Toe game or identifies if the game is a tie or still pending.

    Args:
    board (List[List[str]]): A 3x3 list of lists representing the Tic-Tac-Toe board.

    Returns:
    str: "X" if X wins, "O" if O wins, "Tie" if the game is a tie, "Pending" if the game is still ongoing.
    """
    # Check rows and columns for a winner
    for i in range(3):
        if board[i][0] == board[i][1] == board[i][2] and board[i][0] != '':
            return board[i][0]
        if board[0][i] == board[1][i] == board[2][i] and board[0][i] != '':
            return board[0][i]

    # Check diagonals for a winner
    if board[0][0] == board[1][1] == board[2][2] and board[0][0] != '':
        return board[0][0]
    if board[0][2] == board[1][1] == board[2][0] and board[0][2] != '':
        return board[0][2]

    # Check for any empty cell to determine if the game is still pending
    for row in board:
        if '' in row:
            return "Pending"

    # If no winner and no empty cell, it's a tie
    return "Tie"

