def is_sorted(arr: list[int]) -> bool:
    """
    Checks if the given list is sorted in ascending order.
    """
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False
    return True

def custom_binary_search(arr: list[int], target: int, log_steps: bool = False) -> tuple[int, list[tuple[int, str]]]:
    """
    Performs binary search on a sorted array with logging and error handling for unsorted arrays.

    Args:
    arr: list[int] - Array of integers to search within.
    target: int - The target integer to search for.
    log_steps: bool - Flag to log the steps taken during search.

    Returns:
    tuple[int, list[tuple[int, str]]] - A tuple containing the index of the target if found,
                                         and a log of steps as (midpoint, comparison result) tuples.
    """
    if not is_sorted(arr):
        raise ValueError("The array is not sorted in ascending order.")

    left, right = 0, len(arr) - 1
    log = []

    while left <= right:
        mid = (left + right) // 2
        if log_steps:
            if arr[mid] == target:
                log.append((mid, 'equal'))
            elif arr[mid] < target:
                log.append((mid, 'less'))
            else:
                log.append((mid, 'greater'))

        if arr[mid] == target:
            return (mid, log)
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return (-1, log)

