def order_frequency(order_list):
    """
    Returns the frequency of each product in the order list.
    The frequency count is case-insensitive.
    """
    frequency_dict = {}
    for product in order_list:
        product_lower = product.lower()
        if product_lower in frequency_dict:
            frequency_dict[product_lower] += 1
        else:
            frequency_dict[product_lower] = 1
    return frequency_dict

