def list_intersection(lst1, lst2):
    """
    Returns a list of unique integers that are present in both lst1 and lst2, sorted in ascending order.
    """
    intersection = []
    seen_lst1 = {}
    seen_lst2 = {}

    # Count occurrences in lst1
    for num in lst1:
        if num not in seen_lst1:
            seen_lst1[num] = 0
        seen_lst1[num] += 1

    # Count occurrences in lst2
    for num in lst2:
        if num not in seen_lst2:
            seen_lst2[num] = 0
        seen_lst2[num] += 1

    # Find the intersection
    for num in seen_lst1:
        if num in seen_lst2:
            intersection.append(num)

    # Sort the result
    intersection.sort()

    return intersection

