from collections import Counter
import math

def factorize(n):
    factors = []
    # Check for the number of twos in n
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    # n must be odd at this point, so check for odd factors from 3 onwards
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    return factors

def prime_factor_visualization(number: int) -> str:
    factors = factorize(number)
    count_factors = Counter(factors)

    result = []
    for prime in sorted(count_factors):
        result.append(f"{prime}: {'*' * count_factors[prime]}")

    return '\n'.join(result)

