def simple_calculator(expression: str) -> float:
    """
    Parses and evaluates a simple mathematical expression provided as a string.
    Supports operations: addition, subtraction, multiplication, division.
    Handles parentheses for precedence.
    """
    try:
        result = eval(expression)
        if result == float('inf') or result == -float('inf'):
            return result
        return float(result)
    except ZeroDivisionError:
        return float('inf') if '/' in expression and not '-' in expression else -float('inf')
    except Exception:
        raise ValueError("Invalid expression")

