def rle_compress(data: str) -> str:
    """
    Compresses the input string using Run-Length Encoding (RLE).
    """
    if not data:
        return ""

    compressed = []
    count = 1
    for i in range(1, len(data)):
        if data[i] == data[i - 1]:
            count += 1
        else:
            compressed.append(data[i - 1] + str(count))
            count = 1
    compressed.append(data[-1] + str(count))

    return ''.join(compressed)

def rle_decompress(encoded_data: str) -> str:
    """
    Decompresses the Run-Length Encoded string back to its original form.
    """
    if not encoded_data:
        return ""

    decompressed = []
    i = 0
    while i < len(encoded_data):
        char = encoded_data[i]
        count = ""
        i += 1
        while i < len(encoded_data) and encoded_data[i].isdigit():
            count += encoded_data[i]
            i += 1
        decompressed.append(char * int(count))

    return ''.join(decompressed)

