def find_pairs_with_sum(numbers, target_sum):
    """
    Returns a list of tuples where each tuple contains a pair of elements from the input list
    that add up to the target sum.
    """
    seen_numbers = {}
    pairs = set()

    for number in numbers:
        complement = target_sum - number
        if complement in seen_numbers:
            pairs.add((min(number, complement), max(number, complement)))
        seen_numbers[number] = True

    return list(pairs)

