def longest_increasing_engagement_period(engagements):
    if not engagements:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(engagements)):
        if engagements[i] > engagements[i - 1]:
            current_length += 1
        else:
            current_length = 1

        max_length = max(max_length, current_length)

    return max_length

