from typing import List, Tuple

def shortest_path(num_locations: int, roads: List[Tuple[int, int, int]], start: int, target: int) -> List[int]:
    # Step 1: Build the graph as an adjacency list
    graph = {i: [] for i in range(num_locations)}
    for u, v, d in roads:
        graph[u].append((v, d))
        graph[v].append((u, d))  # Assuming undirected graph, omit if directed

    # Step 2: Initialize data structures for Dijkstra's algorithm
    distances = {node: float('inf') for node in range(num_locations)}
    distances[start] = 0
    priority_queue = [(0, start)]
    predecessors = {node: None for node in range(num_locations)}

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we reach the target, no need to continue
        if current_node == target:
            break

        # Check next nodes
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If a shorter path to `neighbor` is found
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                predecessors[neighbor] = current_node
                heapq.heappush(priority_queue, (distance, neighbor))

    # Step 3: Reconstruct the shortest path
    path = []
    step = target
    while step is not None:
        path.insert(0, step)
        step = predecessors[step]

    if path[0] == start:
        return path
    else:
        return []  # No path found

def reformat_string(input_string: str) -> str:
    """
    Returns a string where all digits come before all characters,
    maintaining their initial relative order.
    """
    digits = []
    letters = []

    for char in input_string:
        if char.isdigit():
            digits.append(char)
        elif char.isalpha():
            letters.append(char)

    return ''.join(digits + letters)

def digit_to_word(s: str) -> str:
    digit_map = {
        '0': 'zero',
        '1': 'one',
        '2': 'two',
        '3': 'three',
        '4': 'four',
        '5': 'five',
        '6': 'six',
        '7': 'seven',
        '8': 'eight',
        '9': 'nine'
    }

    result = []

    for char in s:
        if char.isdigit():
            result.append(digit_map[char])
        else:
            result.append(char)

    return ''.join(result)

