def compress_string(s: str) -> str:
    if not s:
        return ""

    compressed = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            if count == 1:
                compressed.append(current_char)
            else:
                compressed.append(current_char + str(count))
            current_char = char
            count = 1

    if count == 1:
        compressed.append(current_char)
    else:
        compressed.append(current_char + str(count))

    return ''.join(compressed)

