def round_off(x: float) -> int:
    """
    Custom round-off function to round a float to the nearest integer.
    If the fractional part is exactly 0.5, it rounds to the nearest even integer.
    """
    integer_part = int(x)
    fractional_part = x - integer_part

    if fractional_part > 0.5 or (fractional_part == 0.5 and integer_part % 2 != 0):
        return integer_part + 1
    elif fractional_part < -0.5 or (fractional_part == -0.5 and integer_part % 2 != 0):
        return integer_part - 1
    else:
        return integer_part

