def char_frequency(text):
    """
    Computes the frequency of each character in the input string.

    :param text: str - input string to be analyzed.
    :return: dict - dictionary where each key is a character from the string,
                    and its corresponding value is the count of that character in the input string.
    """
    frequency = {}
    for char in text:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency

