def find_articulation_points(n: int, edges: list[tuple[int, int]]) -> list[int]:
    """
    Find all articulation points in an undirected graph.
    """
    from collections import defaultdict

    def dfs(at):
        nonlocal dfs_timer
        visited[at] = True
        ids[at] = low[at] = dfs_timer
        dfs_timer += 1
        children = 0

        for to in graph[at]:
            if to == parent[at]:
                continue
            if not visited[to]:
                parent[to] = at
                children += 1
                dfs(to)

                low[at] = min(low[at], low[to])

                if parent[at] == -1 and children > 1:
                    articulation_points.add(at)
                if parent[at] != -1 and low[to] >= ids[at]:
                    articulation_points.add(at)
            else:
                low[at] = min(low[at], ids[to])

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    ids = [-1] * n
    low = [-1] * n
    visited = [False] * n
    parent = [-1] * n
    articulation_points = set()
    dfs_timer = 0

    for i in range(n):
        if not visited[i]:
            dfs(i)

    return list(sorted(articulation_points))

def integer_square_root(n: int) -> int:
    if n < 0:
        raise ValueError("n must be a non-negative integer")
    if n in {0, 1}:
        return n
    left, right = 0, n
    while left <= right:
        mid = (left + right) // 2
        if mid * mid == n:
            return mid
        elif mid * mid < n:
            left = mid + 1
        else:
            right = mid - 1
    return right

def precise_square_root(n: float, precision: float) -> float:
    if n < 0:
        raise ValueError("n must be a non-negative number")
    if precision <= 0 or precision >= 1:
        raise ValueError("precision must be a positive float less than 1")
    if n in {0, 1}:
        return float(n)
    left, right = 0.0, n
    while right - left > precision:
        mid = (left + right) / 2
        if mid * mid == n:
            return mid
        elif mid * mid < n:
            left = mid
        else:
            right = mid
    return (left + right) / 2

