from typing import List, Tuple

def perform_operations(records: List[Tuple[int, int, int]], operations: List[str]) -> List[int]:
    results = []

    for record in records:
        a, b, c = record

        for operation in operations:
            if operation == "SUM":
                results.append(a + b + c)
            elif operation == "PRODUCT":
                results.append(a * b * c)
            elif operation == "MAX":
                results.append(max(a, b, c))

    return results

