def is_back_to_origin(moves: str) -> bool:
    """
    Determines if a given route brings the drone back to the origin.

    Args:
    moves (str): A string of moves consisting of 'U' (up), 'D' (down), 'L' (left), and 'R' (right).

    Returns:
    bool: True if the route returns to the origin, False otherwise.
    """

    x, y = 0, 0

    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return x == 0 and y == 0

def calculate_perimeter(matrix):
    rows, cols = len(matrix), len(matrix[0])
    perimeter = 0

    def is_water_or_boundary(r, c):
        return r < 0 or r >= rows or c < 0 or c >= cols or matrix[r][c] == 0

    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 1:
                # Check all four directions
                if is_water_or_boundary(r-1, c):
                    perimeter += 1
                if is_water_or_boundary(r+1, c):
                    perimeter += 1
                if is_water_or_boundary(r, c-1):
                    perimeter += 1
                if is_water_or_boundary(r, c+1):
                    perimeter += 1

    return perimeter

