import math

def is_fibonacci(number: int) -> bool:
    """
    Determines whether a given number is a Fibonacci number.
    """
    if number < 0:
        return False

    # A number is a Fibonacci number if and only if one or both of (5*n^2 + 4) or (5*n^2 - 4) is a perfect square
    def is_perfect_square(x):
        s = int(math.isqrt(x))
        return s*s == x

    return is_perfect_square(5 * number * number + 4) or is_perfect_square(5 * number * number - 4)

def nth_fibonacci(n: int) -> int:
    """
    Returns the nth number in the Fibonacci sequence.
    """
    if n < 0:
        raise ValueError("Input should be a non-negative integer")
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(n-1):
        a, b = b, a + b

    return b

