import math

def find_optimal_route(locations):
    def euclidean_distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    if not locations:
        return []

    n = len(locations)
    visited = [False] * n
    route = []

    current_index = 0
    route.append(locations[current_index])
    visited[current_index] = True

    while len(route) < n:
        min_distance = float('inf')
        next_index = None
        for i in range(n):
            if not visited[i]:
                distance = euclidean_distance(locations[current_index], locations[i])
                if distance < min_distance:
                    min_distance = distance
                    next_index = i
        if next_index is not None:
            visited[next_index] = True
            route.append(locations[next_index])
            current_index = next_index

    route.append(route[0])  # Return to starting point
    return route

def find_potential_duplicates(users):
    name_dict = {}
    email_dict = {}
    duplicates = set()

    for user in users:
        user_id = user['id']
        name = user['name']
        email = user['email']

        if name in name_dict:
            for duplicate_id in name_dict[name]:
                duplicates.add((min(user_id, duplicate_id), max(user_id, duplicate_id)))
            name_dict[name].append(user_id)
        else:
            name_dict[name] = [user_id]

        if email in email_dict:
            for duplicate_id in email_dict[email]:
                duplicates.add((min(user_id, duplicate_id), max(user_id, duplicate_id)))
            email_dict[email].append(user_id)
        else:
            email_dict[email] = [user_id]

    return sorted(list(duplicates))

from typing import List

def min_rectangle_area(grid: List[List[int]]) -> int:
    """
    Returns the area of the smallest rectangle that contains all the '1's in the grid.
    """
    if not grid or not all(isinstance(row, list) for row in grid):
        raise TypeError("The grid should be a 2D list.")

    rows = len(grid)
    cols = len(grid[0])

    for row in grid:
        if len(row) != cols or not all(isinstance(val, int) for val in row):
            raise TypeError("The grid should be a 2D list of integers with consistent row lengths.")

    min_row, max_row = rows, -1
    min_col, max_col = cols, -1

    dirty_spots_found = False

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                dirty_spots_found = True
                if r < min_row:
                    min_row = r
                if r > max_row:
                    max_row = r
                if c < min_col:
                    min_col = c
                if c > max_col:
                    max_col = c

    if not dirty_spots_found:
        raise ValueError("No dirty spots in the grid.")

    height = max_row - min_row + 1
    width = max_col - min_col + 1

    return height * width

def calculate_grades(students: dict) -> dict:
    def get_grade(average):
        if 90 <= average <= 100:
            return "A"
        elif 80 <= average < 90:
            return "B"
        elif 70 <= average < 80:
            return "C"
        elif 60 <= average < 70:
            return "D"
        else:
            return "F"

    final_grades = {}
    for student, subjects in students.items():
        if subjects:
            average = sum(subjects.values()) / len(subjects)
            final_grades[student] = get_grade(average)

    return final_grades

