def compress_repeating_chars(s: str) -> str:
    """
    Compresses consecutive repeating characters in the string `s`.

    Parameters:
    s (str): Input string containing alphanumeric characters.

    Returns:
    str: A new string with consecutive repeating characters replaced by
         the single character followed by the count of repetitions.
    """
    if not s:
        return ""

    compressed_string = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed_string.append(s[i - 1])
            if count > 1:
                compressed_string.append(str(count))
            count = 1

    # Handle the last group of characters
    compressed_string.append(s[-1])
    if count > 1:
        compressed_string.append(str(count))

    return "".join(compressed_string)

