def find_palindrome_pairs(words):
    def is_palindrome(word):
        return word == word[::-1]

    word_dict = {word: i for i, word in enumerate(words)}
    palindrome_pairs = []

    for i, word in enumerate(words):
        n = len(word)
        for j in range(n + 1):
            prefix = word[:j]
            suffix = word[j:]

            if is_palindrome(prefix):
                rev_suffix = suffix[::-1]
                if rev_suffix in word_dict and word_dict[rev_suffix] != i:
                    palindrome_pairs.append((word_dict[rev_suffix], i))

            if j != n and is_palindrome(suffix):
                rev_prefix = prefix[::-1]
                if rev_prefix in word_dict and word_dict[rev_prefix] != i:
                    palindrome_pairs.append((i, word_dict[rev_prefix]))

    return palindrome_pairs

