    """
    Returns the length of the longest increasing subsequence
    where all elements are less than or equal to max_value.
    """
    if not arr:
        return 0

    lis = []
    for num in arr:
        if num <= max_value:
            pos = bisect.bisect_left(lis, num)
            if pos < len(lis):
                lis[pos] = num
            else:
                lis.append(num)
    return len(lis)

