def is_sorted_non_decreasing(nums: List[int]) -> bool:
    """
    This function checks if the given list of integers is sorted in non-decreasing order.
    """
    for i in range(1, len(nums)):
        if nums[i] < nums[i - 1]:
            return False
    return True

