def reorder_strings(input_list):
    uppercase_strings = []
    lowercase_strings = []

    for string in input_list:
        if string[0].isupper():
            uppercase_strings.append(string)
        else:
            lowercase_strings.append(string)

    return uppercase_strings + lowercase_strings

