def detect_temperature_anomalies(temperatures: list[float], threshold: float) -> list[tuple[int, int]]:
    """
    Detects continuous periods during which the recorded temperature readings exceed a specified threshold value.

    Args:
    temperatures (list[float]): List of hourly temperature readings in degrees Celsius.
    threshold (float): The temperature threshold in degrees Celsius.

    Returns:
    list[tuple[int, int]]: List of tuples, each containing the start and end hour of periods
                           where temperatures consistently exceed the threshold.
    """
    periods = []
    start = None

    for hour, temp in enumerate(temperatures):
        if temp > threshold:
            if start is None:
                start = hour
        else:
            if start is not None:
                periods.append((start, hour - 1))
                start = None

    if start is not None:
        periods.append((start, len(temperatures) - 1))

