from typing import List, Tuple

def find(parent, i):
    if parent[i] == i:
        return i
    else:
        return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def mst_kruskal(vertices: int, edges: List[Tuple[int, int, int]]) -> int:
    result = []
    i = 0
    e = 0

    edges = sorted(edges, key=lambda item: item[2])

    parent = []
    rank = []

    for node in range(vertices):
        parent.append(node)
        rank.append(0)

    while e < vertices - 1:
        u, v, w = edges[i]
        i = i + 1
        x = find(parent, u)
        y = find(parent, v)

        if x != y:
            e = e + 1
            result.append((u, v, w))
            union(parent, rank, x, y)

    minimumCost = 0
    for u, v, weight in result:
        minimumCost += weight
    return minimumCost

