from typing import List

def normalize_values(values: List[float]) -> List[float]:
    if not values:
        raise ValueError("Input list cannot be empty.")

    min_val = min(values)
    max_val = max(values)

    if min_val == max_val:
        raise ValueError("Normalization not possible when all values are identical.")

    normalized_values = [(value - min_val) / (max_val - min_val) for value in values]
    return [round(val, 3) for val in normalized_values]

