def find_unique_anagrams(words):
    """
    Returns a list of words that do not have any anagrams in the given list.
    """
    norm_to_words = {}

    # Normalize and collect words in dictionary
    for word in words:
        norm_word = ''.join(sorted(word))
        if norm_word in norm_to_words:
            norm_to_words[norm_word].append(word)
        else:
            norm_to_words[norm_word] = [word]

    # Collect words that do not have anagrams
    result = []
    for norm_word, word_list in norm_to_words.items():
        if len(word_list) == 1:
            result.append(word_list[0])

    return result

