def topological_sort(graph):
    def dfs(node, visited, recursion_stack, sorted_order):
        visited[node] = True
        recursion_stack[node] = True

        if node in graph:
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    if not dfs(neighbor, visited, recursion_stack, sorted_order):
                        return False
                elif recursion_stack[neighbor]:
                    return False

        recursion_stack[node] = False
        sorted_order.append(node)
        return True

    visited = {node: False for node in graph}
    recursion_stack = {node: False for node in graph}
    sorted_order = []

    for node in graph:
        if not visited[node]:
            if not dfs(node, visited, recursion_stack, sorted_order):
                return "Graph contains a cycle"

    sorted_order.reverse()
    return sorted_order

