def prime_factors_count(n: int) -> dict:
    """
    Returns a dictionary where the keys are the distinct prime factors of the number n
    and the values are the counts of each prime factor.
    """
    factors = {}
    divisor = 2
    while n >= 2:
        if n % divisor == 0:
            if divisor in factors:
                factors[divisor] += 1
            else:
                factors[divisor] = 1
            n //= divisor
        else:
            divisor += 1
    return factors

