def first_non_repeating_char(input_str: str) -> str:
    """
    Returns the first non-repeating character in the input string.
    If all characters repeat, returns an empty string.
    """
    # Dictionary to store frequency of each character
    char_count = {}

    # First pass: count frequency of each character
    for char in input_str:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass: find the first non-repeating character
    for char in input_str:
        if char_count[char] == 1:
            return char

    # If no non-repeating character found, return empty string
    return ''

