def numDecodings(s: str) -> int:
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: An empty string can be decoded in one way

    for i in range(1, n + 1):
        single_digit = int(s[i-1:i])
        if 1 <= single_digit <= 9:
            dp[i] += dp[i-1]

        if i > 1:
            double_digit = int(s[i-2:i])
            if 10 <= double_digit <= 26:
                dp[i] += dp[i-2]

    return dp[n]

