from typing import List

def cyclic_sort(a: List[int]) -> None:
    """
    This function sorts the array containing elements in a contiguous range from `1` to `n` in-place.
    """
    i = 0
    while i < len(a):
        correct_index = a[i] - 1
        if a[i] != a[correct_index]:
            # Swap a[i] with a[correct_index]
            a[i], a[correct_index] = a[correct_index], a[i]
        else:
            i += 1

