def check_parentheses(expression: str) -> str:
    """
    Check if the given expression has balanced and correctly nested parentheses.

    Parameters:
    expression (str): The expression to be checked.

    Returns:
    str: "Balanced and Nested" if the parentheses are balanced and correctly nested,
    or a specific error message otherwise.
    """
    if expression == "":
        return "Empty input"

    valid_chars = {"(", ")", "{", "}", "[", "]"}
    for char in expression:
        if char not in valid_chars:
            return "Invalid character found"

    stack = []
    matching_parentheses = {")": "(", "}": "{", "]": "["}

    for char in expression:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if not stack:
                return "Unbalanced parentheses"
            if stack[-1] == matching_parentheses[char]:
                stack.pop()
            else:
                return "Unbalanced parentheses"

    if stack:
        return "Unbalanced parentheses"

    return "Balanced and Nested"

def rotate_image(matrix: list[list[int]]) -> None:
    """
    Rotates the input n x n matrix by 90 degrees clockwise in place.
    """
    n = len(matrix)

    # First, transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Then, reverse each row
    for i in range(n):
        matrix[i].reverse()

