from typing import List

def find_subsequence_indices(main_sequence: List[int], sub_sequence: List[int]) -> List[int]:
    """
    Finds the starting indices where sub_sequence appears in main_sequence.
    """
    if not sub_sequence or not main_sequence or len(sub_sequence) > len(main_sequence):
        return []

    result = []
    for i in range(len(main_sequence) - len(sub_sequence) + 1):
        if main_sequence[i:i+len(sub_sequence)] == sub_sequence:
            result.append(i)
    return result

