from typing import List

def prims_algorithm(adjacency_matrix: List[List[int]]) -> int:
    import heapq

    n = len(adjacency_matrix)
    if any(len(row) != n for row in adjacency_matrix):
        raise ValueError("Adjacency matrix must be square.")

    visited = [False] * n
    min_heap = [(0, 0)]  # (cost, vertex)
    total_weight = 0

    while min_heap:
        weight, u = heapq.heappop(min_heap)

        if visited[u]:
            continue
        visited[u] = True
        total_weight += weight

        for v, cost in enumerate(adjacency_matrix[u]):
            if cost != 0 and not visited[v]:
                heapq.heappush(min_heap, (cost, v))

    if not all(visited):
        raise ValueError("The graph is not connected.")

    return total_weight

def topological_sort(graph):
    """Returns a list of nodes in topologically sorted order."""
    def dfs(node):
        """Helper function to perform depth-first search."""
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor)
        topological_order.append(node)

    visited = set()
    topological_order = []

    for node in graph:
        if node not in visited:
            dfs(node)

    return topological_order[::-1]  # Reverse the order to get the sorted list

