from typing import List, Tuple, Union

def dynamic_array(n: int, q: int, queries: List[Tuple[str, Union[int, float]]]) -> List[Union[int, float]]:
    # Initialize the array with zeroes of length n
    array = [0] * n

    for query in queries:
        operation = query[0]

        if operation == "update":
            i, value = query[1], query[2]
            array[i] = value
        elif operation == "add":
            i, value = query[1], query[2]
            array[i] += value
        elif operation == "multiply":
            i, value = query[1], query[2]
            array[i] *= value
        elif operation == "reset":
            array = [0] * n

    return array

