def manage_inventory(transactions: list[tuple[str, int]]) -> dict:
    """
    Returns the final inventory of books.
    """
    inventory = {}

    for book, change in transactions:
        if book in inventory:
            inventory[book] += change
        else:
            inventory[book] = change

    return inventory

