def rotate_image(matrix: list[list[int]]) -> None:
    """
    Rotates the image represented by the n x n matrix by 90 degrees clockwise in place.
    """
    n = len(matrix)
    # First, transpose the matrix
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Then, reverse each row
    for i in range(n):
        matrix[i].reverse()

def fibonacci_recursive(n: int) -> list[int]:
    """
    Generate Fibonacci sequence up to the n-th term using recursion.

    :param n: The number of terms in the Fibonacci sequence to generate.
    :return: A list of integers representing the Fibonacci sequence up to the n-th term.
    :raises ValueError: If the input is not a non-negative integer.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")

    def fib_recursive(n):
        if n == 0:
            return [0]
        elif n == 1:
            return [0, 1]
        else:
            seq = fib_recursive(n - 1)
            seq.append(seq[-1] + seq[-2])
            return seq

    return fib_recursive(n)[:n]


def fibonacci_iterative(n: int) -> list[int]:
    """
    Generate Fibonacci sequence up to the n-th term using iteration.

    :param n: The number of terms in the Fibonacci sequence to generate.
    :return: A list of integers representing the Fibonacci sequence up to the n-th term.
    :raises ValueError: If the input is not a non-negative integer.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return []
    elif n == 1:
        return [0]

    seq = [0, 1]
    for _ in range(2, n):
        seq.append(seq[-1] + seq[-2])
    return seq

