def compress_rle(data: str) -> str:
    if not data:
        return ''

    compressed = []
    i = 0
    while i < len(data):
        count = 1
        while i + 1 < len(data) and data[i] == data[i + 1]:
            i += 1
            count += 1
        compressed.append(f"{count}{data[i]}")
        i += 1

    return ''.join(compressed)

def decompress_rle(data: str) -> str:
    decompressed = []
    i = 0
    while i < len(data):
        if not data[i].isdigit():
            raise ValueError("Invalid RLE format")

        count = 0
        while i < len(data) and data[i].isdigit():
            count = count * 10 + int(data[i])
            i += 1

        if i >= len(data) or not data[i].isalpha():
            raise ValueError("Invalid RLE format")

        decompressed.append(data[i] * count)
        i += 1

    return ''.join(decompressed)

