def evaluate_expression(expression: str) -> int:
    """
    Evaluates a mathematical expression string with '+' and '*' operators,
    respecting the standard order of operations (multiplication before addition).
    """
    def apply_operation(ops, nums):
        if ops[-1] == '+':
            nums[-2] += nums[-1]
        elif ops[-1] == '*':
            nums[-2] *= nums[-1]
        nums.pop()
        ops.pop()

    nums = []
    ops = []
    i = 0
    n = len(expression)
    while i < n:
        if expression[i].isdigit():
            num = 0
            while i < n and expression[i].isdigit():
                num = num * 10 + int(expression[i])
                i += 1
            nums.append(num)
            i -= 1
        elif expression[i] in '+*':
            while ops and ops[-1] == '*':
                apply_operation(ops, nums)
            ops.append(expression[i])
        i += 1

    while ops:
        apply_operation(ops, nums)

    return nums[0]

