def recommend_authors(user_read_books: List[str], available_books: Dict[str, List[str]]) -> List[str]:
    user_read_set = set(user_read_books)
    recommendable_authors = []

    for author, books in available_books.items():
        if any(book not in user_read_set for book in books):
            recommendable_authors.append(author)

    return sorted(recommendable_authors)

