def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def sum_of_primes(a, b):
    """
    Returns the sum of all prime numbers in the range [a, b].
    """
    return sum(x for x in range(a, b + 1) if is_prime(x))

