from collections import deque, defaultdict

def bfs_shortest_path(adjacency_list, start_node, end_node):
    """
    Returns the shortest path from start_node to end_node using BFS in a directed cyclic graph.
    """
    # Parent map to keep track of the path
    parent = {start_node: None}
    # Distance map to keep track of shortest paths
    distance = {start_node: 0}

    queue = deque([start_node])

    while queue:
        current_node = queue.popleft()

        for neighbor, weight in adjacency_list.get(current_node, []):
            new_distance = distance[current_node] + weight

            if neighbor not in distance or new_distance < distance[neighbor]:
                distance[neighbor] = new_distance
                parent[neighbor] = current_node
                queue.append(neighbor)

    if end_node not in parent:
        return []  # No path found

    # Reconstruct path from end_node to start_node using parent map
    path = []
    while end_node is not None:
        path.append(end_node)
        end_node = parent[end_node]

    return list(reversed(path))

