def look_and_say_sequence(n: int) -> list:
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer")

    def next_term(term):
        result = []
        i = 0
        while i < len(term):
            count = 1
            while i + 1 < len(term) and term[i] == term[i + 1]:
                i += 1
                count += 1
            result.append(f"{count}{term[i]}")
            i += 1
        return ''.join(result)

    sequence = ["1"]
    for _ in range(n - 1):
        sequence.append(next_term(sequence[-1]))

    return sequence

