def calculate_total_weight(weights):
    """
    Returns the total weight of a list of items.
    """
    return sum(weights)

def find_heaviest_item(weights):
    """
    Returns the weight of the heaviest item in the list.
    If the list is empty, returns None.
    """
    return max(weights, default=None)

def max_items_within_weight(weights, max_weight):
    """
    Returns the maximum number of items that can be carried without exceeding the weight limit.
    """
    weights.sort()
    total_weight = 0
    count = 0

    for weight in weights:
        if total_weight + weight <= max_weight:
            total_weight += weight
            count += 1
        else:
            break

    return count

