def verify_and_augment_matrices(matrix_a: list[list[int]], matrix_b: list[list[int]]) -> list[list[int]]:
    # Verify matrix dimensions
    if len(matrix_a[0]) != len(matrix_b):
        raise ValueError('Incompatible matrices for multiplication.')

    # Initialize product matrix with zeroes
    product_matrix = [[0 for _ in range(len(matrix_b[0]))] for _ in range(len(matrix_a))]

    # Perform matrix multiplication
    for i in range(len(matrix_a)):
        for j in range(len(matrix_b[0])):
            for k in range(len(matrix_b)):
                product_matrix[i][j] += matrix_a[i][k] * matrix_b[k][j]

    # Calculate column sums
    column_sums = [sum(row[j] for row in product_matrix) for j in range(len(product_matrix[0]))]

    # Augment product matrix with column sums
    product_matrix.append(column_sums)

    return product_matrix

def simplify_expression(expr: str, vars: dict) -> int:
    def eval_expr(expression, variables):
        stack, num, sign = [], 0, 1
        result = 0
        i = 0

        while i < len(expression):
            char = expression[i]

            if char.isdigit():
                num = num * 10 + int(char)

            elif char.isalpha():
                var_name = ''
                while i < len(expression) and expression[i].isalpha():
                    var_name += expression[i]
                    i += 1
                i -= 1
                num = variables[var_name]

            elif char == '+':
                result += sign * num
                num, sign = 0, 1

            elif char == '-':
                result += sign * num
                num, sign = 0, -1

            elif char == '(':
                stack.append(result)
                stack.append(sign)
                result, sign = 0, 1

            elif char == ')':
                result += sign * num
                result *= stack.pop()
                result += stack.pop()
                num = 0

            i += 1

        return result + sign * num

    return eval_expr(expr, vars)

