def digit_sum(number: int) -> int:
    """
    Returns the sum of the digits of a given non-negative integer until a single-digit result is achieved.
    """
    if number == 0:
        return 0

    while number >= 10:
        number = sum(int(digit) for digit in str(number))

    return number

