from typing import List

def generate_pascal_triangle(n: int) -> List[List[int]]:
    if n == 0:
        return []
    triangle = [[1]]
    for i in range(1, n):
        row = [1]
        for j in range(1, i):
            row.append(triangle[i-1][j-1] + triangle[i-1][j])
        row.append(1)
        triangle.append(row)
    return triangle

def collatz_sequence_length(n: int) -> int:
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

def find_first_divisible(start: int, end: int, divisor: int) -> int:
    """
    Function to find the first number within range [start, end] that is divisible by the specified divisor.
    Returns the first divisible number or -1 if no divisible number is found.
    """
    for number in range(start, end + 1):
        if number % divisor == 0:
            return number
    return -1

