def evaluate_rpn(tokens):
    """
    Evaluates the given expression in Reverse Polish Notation and returns the result.
    """
    stack = []
    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                # Truncate towards zero for integer division
                stack.append(int(a / b))
        else:
            stack.append(int(token))
    return stack[0]

