from typing import List, Tuple

def find_connected_components(friendships: List[Tuple[int, int]]) -> int:
    def bfs(node):
        queue = [node]
        visited.add(node)
        while queue:
            current = queue.pop(0)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    if not friendships:
        return 0

    graph = {}
    for a, b in friendships:
        if a not in graph:
            graph[a] = []
        if b not in graph:
            graph[b] = []
        graph[a].append(b)
        graph[b].append(a)

    visited = set()
    count = 0
    for node in graph:
        if node not in visited:
            count += 1
            bfs(node)

    return count

def word_pattern(pattern: str, s: str) -> bool:
    words = s.split()
    if len(pattern) != len(words):
        return False

    char_to_word = {}
    word_to_char = {}

    for p, w in zip(pattern, words):
        if p in char_to_word:
            if char_to_word[p] != w:
                return False
        else:
            char_to_word[p] = w

        if w in word_to_char:
            if word_to_char[w] != p:
                return False
        else:
            word_to_char[w] = p

    return True

def inventory_system(operations):
    """
    Simulates a basic inventory system for a small store.

    Params:
    operations: List[Tuple[str, str, int]] - List of operations to be performed on the inventory.

    Returns:
    List[int] - Results of the check operations.
    """

    inventory = {}
    results = []

    for operation in operations:
        op_type, item, qty = operation

        if op_type == "add":
            if item not in inventory:
                inventory[item] = 0
            inventory[item] += qty

        elif op_type == "remove":
            if item in inventory:
                inventory[item] -= qty
                # Ensure quantity doesn't go below zero
                if inventory[item] < 0:
                    inventory[item] = 0

        elif op_type == "check":
            results.append(inventory.get(item, 0))

    return results

def distinct_ways_to_climb(n):
    """
    Returns the number of distinct ways to climb a staircase of n steps,
    given that you can take 1, 2, or 3 steps at a time.
    """
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n == 3:
        return 4

    dp = [0] * (n + 1)
    dp[1], dp[2], dp[3] = 1, 2, 4

    for i in range(4, n + 1):
        dp[i] = dp[i-1] + dp[i-2] + dp[i-3]

    return dp[n]

def identify_license_plate(plate: str, formats: list) -> str:
    """
    Identify the native format of a given license plate number from a list of defined formats.

    Parameters:
    - plate (str): The license plate number to be checked (consists of alphanumeric characters).
    - formats (list): A list of format strings defining possible valid formats.

    Returns:
    - (str): The matching format string from the list or "Unknown" if no format matches.
    """

    def matches_format(plate, fmt):
        if len(plate) != len(fmt):
            return False
        for p_char, f_char in zip(plate, fmt):
            if f_char == '#' and not p_char.isdigit():
                return False
            if f_char == '@' and not p_char.isalpha():
                return False
        return True

    for fmt in formats:
        if matches_format(plate, fmt):
            return fmt
    return "Unknown"

