def adjust_prices(items: list[tuple[str, int, int]], sales: list[tuple[str, int]]) -> list[tuple[str, int]]:
    # Create a dictionary of sales for quick lookup
    sales_dict = {name: units_sold for name, units_sold in sales}

    adjusted_prices = []
    for name, initial_price, adjustment_factor in items:
        units_sold = sales_dict.get(name, 0)
        adjusted_price = initial_price + (units_sold * adjustment_factor)
        adjusted_prices.append((name, adjusted_price))

