def first_unique_character(s: str) -> int:
    """
    Finds the first non-repeating character in the string and returns its index.
    If there are no non-repeating characters, returns -1.
    """
    # First pass to count occurrences of each character
    count = {}
    for char in s:
        count[char] = count.get(char, 0) + 1

    # Second pass to find the first unique character
    for idx, char in enumerate(s):
        if count[char] == 1:
            return idx

    return -1

