def analyze_sales_data(sales_data: dict[str, list[int]]) -> tuple[str, float]:
    max_avg_sales = 0
    best_product_id = None

    for product_id, sales in sales_data.items():
        avg_sales = sum(sales) / len(sales)
        if avg_sales > max_avg_sales:
            max_avg_sales = avg_sales
            best_product_id = product_id

    return (best_product_id, max_avg_sales)

