def is_power_of_three(n: int) -> bool:
    if n < 1:
        return False
    if n == 1:
        return True
    if n % 3 != 0:
        return False
    return is_power_of_three(n // 3)

def max_sum_increasing_subsequence(arr):
    if not isinstance(arr, list) or not all(isinstance(i, int) for i in arr):
        raise TypeError("Input must be a list of integers")

    n = len(arr)
    if n == 0:
        return 0

    # Initialize the max_sum array with the values from arr
    max_sum = arr.copy()

    # Fill max_sum[] using the iterative method
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and max_sum[i] < max_sum[j] + arr[i]:
                max_sum[i] = max_sum[j] + arr[i]

    # Return the maximum value from max_sum[]
    return max(max_sum)

def fibonacci(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1

    def matrix_multiply(A, B):
        return [
            [A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
            [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]],
        ]

    def matrix_power(matrix, power):
        if power == 1:
            return matrix
        if power % 2 == 0:
            half_power = matrix_power(matrix, power // 2)
            return matrix_multiply(half_power, half_power)
        else:
            return matrix_multiply(matrix, matrix_power(matrix, power - 1))

    result_matrix = matrix_power([[1, 1], [1, 0]], n - 1)
    return result_matrix[0][0]

