from typing import List, Dict

def count_elements(arr: List[int]) -> Dict[int, int]:
    """
    Counts the frequency of each unique element in the input list.

    Parameters:
    arr (List[int]): List of integers.

    Returns:
    Dict[int, int]: Dictionary with unique elements as keys and their counts as values.
    """
    frequency_dict = {}
    for num in arr:
        if num in frequency_dict:
            frequency_dict[num] += 1
        else:
            frequency_dict[num] = 1
    return frequency_dict

