from typing import List

def word_breaks(s: str, word_dict: List[str]) -> List[str]:
    """
    Finds all possible word breaks for a given string s using a provided dictionary of words.
    """
    def backtrack(start):
        if start == len(s):
            return [[]]

        if start in memo:
            return memo[start]

        results = []
        for end in range(start + 1, len(s) + 1):
            word = s[start:end]
            if word in word_dict_set:
                for rest in backtrack(end):
                    results.append([word] + rest)

        memo[start] = results
        return results

    word_dict_set = set(word_dict)
    memo = {}
    results = backtrack(0)
    return [' '.join(words) for words in results]

def smallest_prime_factor_sum(max_n: int) -> int:
    def prime_factors_sum(n):
        sum_pf = 0
        # Check for number of twos that divide n
        while n % 2 == 0:
            sum_pf += 2
            n = n // 2
        # n must be odd at this point so check for odd factors
        for i in range(3, int(n**0.5)+1, 2):
            while n % i == 0:
                sum_pf += i
                n = n // i
        # This condition is to check if n is a prime number greater than 2
        if n > 2:
            sum_pf += n
        return sum_pf

    min_sum = float('inf')
    min_num = 2
    for i in range(2, max_n + 1):
        pf_sum = prime_factors_sum(i)
        if pf_sum < min_sum:
            min_sum = pf_sum
            min_num = i
    return min_num

