import heapq

def shortest_path(graph, start_node, end_node):
    """
    Implements Dijkstra's algorithm to find the shortest path in terms of latency from start_node to end_node.
    """
    # Priority queue for the Dijkstra's algorithm, initialized with the start_node and a distance of 0.
    priority_queue = [(0, start_node)]
    # Dictionary to keep track of the shortest path to each node.
    shortest_paths = {start_node: 0}

    while priority_queue:
        current_latency, current_node = heapq.heappop(priority_queue)

        # If we have reached the end_node, we can return the latency.
        if current_node == end_node:
            return current_latency

        # Explore neighbors
        for neighbor, latency in graph[current_node].items():
            distance = current_latency + latency

            # If the calculated distance is shorter, update the shortest_paths and add to queue.
            if neighbor not in shortest_paths or distance < shortest_paths[neighbor]:
                shortest_paths[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    # If there's no path found, return an infinite latency which is indicative that the nodes are not connected
    return float('inf')

