def fibonacci_recursive(n):
    if n <= 1:
        return n
    return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)

def fibonacci_iterative(n):
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def compare_fib_methods(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer")

    fib_recursive = fibonacci_recursive(n)
    fib_iterative = fibonacci_iterative(n)

    if fib_recursive != fib_iterative:
        raise AssertionError("Mismatch between recursive and iterative methods")

    return fib_recursive

