def count_primes(n: int) -> int:
    """
    Returns the number of prime numbers less than a given positive integer n.
    """
    if n < 2:
        return 0

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n, start):
                is_prime[multiple] = False

    return sum(is_prime)

from collections import deque

def shortest_connection_path(network, user_a, user_b):
    """
    Returns the shortest path of connections from user_a to user_b using BFS.
    If no path exists, returns an empty list.
    """
    if user_a not in network or user_b not in network:
        return []
    if user_a == user_b:
        return [user_a]

    visited = set()
    queue = deque([(user_a, [user_a])])

    while queue:
        current_user, path = queue.popleft()

        if current_user == user_b:
            return path

        visited.add(current_user)
        for friend in network.get(current_user, []):
            if friend not in visited:
                queue.append((friend, path + [friend]))

    return []

