def max_subarray_sum(nums: list) -> int:
    """
    Finds the contiguous subarray with the largest sum and returns that sum.
    """
    if not nums:
        return 0  # If the list is empty, return 0 (though per constraints, list will have at least one element)

    # Initialize the current subarray sum and maximum subarray sum with the first element
    current_sum = max_sum = nums[0]

    # Iterate over the array starting from the second element
    for num in nums[1:]:
        current_sum = max(num, current_sum + num)  # Update the current subarray sum
        max_sum = max(max_sum, current_sum)        # Update the maximum subarray sum found so far

    return max_sum

