def transform_string(text: str) -> str:
    """
    Returns a new string where no character appears consecutively more than once.

    Parameters:
    text (str): a non-empty string containing only uppercase English letters (A-Z)

    Returns:
    str: a transformed string with consecutive duplicates removed.
    """
    if not text:
        return ""

    result = [text[0]]
    for char in text[1:]:
        if char != result[-1]:
            result.append(char)

    return "".join(result)

def is_cyclic_rotation(s1: str, s2: str) -> bool:
    """
    Checks if s2 is a cyclic rotation of s1.
    """
    if len(s1) != len(s2):
        return False
    if len(s1) == 0:
        return True
    return s2 in (s1 + s1)

