import random
import math

def simulated_annealing_tsp(dist_matrix, start_temp=100.0, alpha=0.99, stop_temp=1e-3):
    def total_distance(path):
        return sum(dist_matrix[path[i]][path[i + 1]] for i in range(len(path) - 1))

    def random_swap(path):
        i, j = random.sample(range(1, len(path) - 1), 2)  # Avoid the first and last city
        path[i], path[j] = path[j], path[i]
        return path

    num_cities = len(dist_matrix)

    if any(len(row) != num_cities for row in dist_matrix):
        raise ValueError("Distance matrix must be square")

    if any(any(dist < 0 for dist in row) for row in dist_matrix):
        raise ValueError("Distance matrix must not contain negative values")

    # Initial solution
    current_path = list(range(num_cities)) + [0]
    current_dist = total_distance(current_path)

    best_path = list(current_path)
    best_dist = current_dist

    temp = start_temp

    while temp > stop_temp:
        candidate_path = random_swap(list(current_path))
        candidate_dist = total_distance(candidate_path)

        if candidate_dist < current_dist or random.random() < math.exp((current_dist - candidate_dist) / temp):
            current_path, current_dist = candidate_path, candidate_dist

            if current_dist < best_dist:
                best_path, best_dist = current_path, current_dist

        temp *= alpha

    return best_path

