from datetime import datetime

def find_overdue_books(users: List[Dict[str, Union[str, List[str]]]], current_date: str) -> List[str]:
    overdue_users = []

    # Convert current_date to datetime object for comparison
    current_date_dt = datetime.strptime(current_date, '%Y-%m-%d')

    for user in users:
        for book in user['borrowed_books']:
            book_title, due_date_str = book.split(':')
            due_date_dt = datetime.strptime(due_date_str, '%Y-%m-%d')

            if due_date_dt < current_date_dt:
                overdue_users.append(user['name'])
                # Once we know a user has an overdue book, no need to check the rest of their books
                break

    return sorted(overdue_users)

