from typing import List

def detect_cycle(graph: List[List[int]], v: int) -> bool:
    def dfs(vertex, visited, rec_stack):
        visited[vertex] = True
        rec_stack[vertex] = True

        for neighbor in graph[vertex]:
            if not visited[neighbor]:
                if dfs(neighbor, visited, rec_stack):
                    return True
            elif rec_stack[neighbor]:
                return True

        rec_stack[vertex] = False
        return False

    visited = [False] * v
    rec_stack = [False] * v
    for node in range(v):
        if not visited[node]:
            if dfs(node, visited, rec_stack):
                return True
    return False

from typing import List

def preprocess(arr: List[int]) -> List[int]:
    prefix_sums = [0] * len(arr)
    if arr:
        prefix_sums[0] = arr[0]
        for i in range(1, len(arr)):
            prefix_sums[i] = prefix_sums[i - 1] + arr[i]
    return prefix_sums

def range_query(prefix_sums: List[int], left: int, right: int) -> int:
    if left == 0:
        return prefix_sums[right]
    else:
        return prefix_sums[right] - prefix_sums[left - 1]

def update(arr: List[int], prefix_sums: List[int], index: int, value: int) -> List[int]:
    difference = value - arr[index]
    arr[index] = value
    for i in range(index, len(arr)):
        prefix_sums[i] += difference
    return prefix_sums

