def longest_palindromic_substring_length(s: str) -> int:
    n = len(s)
    if n == 0:
        return 0

    # Create a table to store results of subproblems
    dp = [[False] * n for _ in range(n)]

    # All substrings of length 1 are palindromic
    max_length = 1
    for i in range(n):
        dp[i][i] = True

    start = 0
    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = True
            start = i
            max_length = 2

    for length in range(3, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j] and dp[i+1][j-1]:
                dp[i][j] = True
                start = i
                max_length = length

    return max_length

