def simulate_disease_spread(grid, days):
    """
    Returns the state of the population grid after a given number of days,
    where the disease spreads to adjacent cells from any infected cell.
    """
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]

    for _ in range(days):
        # Copy the grid to avoid modifications during iteration
        new_grid = [row[:] for row in grid]

        for r in range(rows):
            for c in range(cols):
                if grid[r][c] == 1:
                    for dr, dc in directions:
                        nr, nc = r + dr, c + dc
                        if is_valid(nr, nc) and grid[nr][nc] == 0:
                            new_grid[nr][nc] = 1

        grid = new_grid

    return grid

from typing import List

def find_kth_number(arr: List[int], k: int, order: str) -> int:
    if k < 1 or k > len(arr):
        raise ValueError("k is out of the valid range")

    if order not in ["smallest", "largest"]:
        raise ValueError("order must be either 'smallest' or 'largest'")

    arr_sorted = sorted(arr)

    if order == "smallest":
        return arr_sorted[k-1]
    elif order == "largest":
        return arr_sorted[-k]

