from typing import List

def find_and_replace_pattern(words: List[str], pattern: str) -> List[str]:
    def matches(word: str, pattern: str) -> bool:
        if len(word) != len(pattern):
            return False
        char_to_pattern = {}
        pattern_to_char = {}
        for w_char, p_char in zip(word, pattern):
            if w_char in char_to_pattern and char_to_pattern[w_char] != p_char:
                return False
            if p_char in pattern_to_char and pattern_to_char[p_char] != w_char:
                return False
            char_to_pattern[w_char] = p_char
            pattern_to_char[p_char] = w_char
        return True

    return [word for word in words if matches(word, pattern)]

def find_first_non_repeating(s: str) -> str:
    from collections import OrderedDict
    counts = OrderedDict()

    # First pass: count all characters
    for ch in s:
        if ch in counts:
            counts[ch] += 1
        else:
            counts[ch] = 1

    # Second pass: find the first non-repeating character
    for ch in counts:
        if counts[ch] == 1:
            return ch

    return "_"

