def max_nested_depth(s: str) -> int:
    """
    Determine the maximum depth of nested parentheses in the given string.

    :param s: The input string containing only '(' and ')'
    :return: An integer representing the maximum depth of nested parentheses

    Raises:
        ValueError: If the input string contains characters other than '(' and ')'.
    """
    if not all(char in '()' for char in s):
        raise ValueError("Input string contains characters other than '(' and ')'.")

    max_depth = 0
    current_depth = 0

    for char in s:
        if char == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif char == ')':
            current_depth -= 1

        # This condition is to check if the parentheses are unbalanced
        if current_depth < 0:
            raise ValueError("Input string is unbalanced.")

    if current_depth != 0:
        raise ValueError("Input string is unbalanced.")

    return max_depth

