def longest_distinct_substring(s: str) -> int:
    max_length = 0
    start = 0
    char_index_map = {}

    for end in range(len(s)):
        if s[end] in char_index_map:
            # Move the start position to the right of the last occurrence of the current character
            start = max(start, char_index_map[s[end]] + 1)

        # Update the last seen index of the current character
        char_index_map[s[end]] = end

        # Calculate the maximum length of substring seen so far
        max_length = max(max_length, end - start + 1)

    return max_length

def has_cycle(graph: dict) -> bool:
    """
    Detects if there is a cycle in the given directed graph.

    :param graph: A dictionary where keys are vertex identifiers (strings)
                  and values are lists of adjacent vertex identifiers.
    :return: Boolean indicating whether a cycle is present in the graph.
    """
    def dfs(vertex, visited, stack):
        visited.add(vertex)
        stack.add(vertex)

        for neighbor in graph.get(vertex, []):
            if neighbor not in visited:
                if dfs(neighbor, visited, stack):
                    return True
            elif neighbor in stack:
                return True

        stack.remove(vertex)
        return False

    visited = set()
    stack = set()

    for vertex in graph:
        if vertex not in visited:
            if dfs(vertex, visited, stack):
                return True
    return False

