from typing import List, Tuple

def constrained_shortest_path(adj_matrix: List[List[int]], max_edges: int) -> Tuple[int, List[int]]:
    n = len(adj_matrix)
    dp = [[[float('inf'), []] for _ in range(max_edges + 1)] for _ in range(n)]
    dp[0][0] = [0, [0]]

    for e in range(1, max_edges + 1):
        for u in range(n):
            for v in range(n):
                if adj_matrix[u][v] < float('inf') and dp[u][e-1][0] < float('inf'):
                    new_cost = dp[u][e-1][0] + adj_matrix[u][v]
                    if new_cost < dp[v][e][0]:
                        dp[v][e][0] = new_cost
                        dp[v][e][1] = dp[u][e-1][1] + [v]

    min_cost = float('inf')
    path = []
    for e in range(max_edges + 1):
        if dp[-1][e][0] < min_cost:
            min_cost = dp[-1][e][0]
            path = dp[-1][e][1]

    return (min_cost, path)

from typing import List

def count_increasing_subsequences(arr: List[int], k: int) -> int:
    """
    Returns the number of strictly increasing subsequences of length k that can be found in arr.
    """
    if k == 0:
        return 1
    if k > len(arr):
        return 0

    # Create a 2D dp array, where dp[i][j] represents the number of increasing subsequences
    # of length j+1 ending with arr[i].
    dp = [[0] * k for _ in range(len(arr))]

    # Initialize dp for subsequences of length 1
    for i in range(len(arr)):
        dp[i][0] = 1

    # Fill the dp array
    for j in range(1, k):
        for i in range(j, len(arr)):  # i needs to be at least j (to have enough elements before)
            for p in range(i):  # Consider all previous elements arr[p] < arr[i]
                if arr[p] < arr[i]:
                    dp[i][j] += dp[p][j-1]

    # Sum up all the ways to end a subsequence of length k
    result = 0
    for i in range(len(arr)):
        result += dp[i][k-1]

    return result

