def is_valid_word_chain(word_chain: list[str]) -> bool:
    def is_neighbor(w1, w2):
        len1, len2 = len(w1), len(w2)

        # Case when lengths differ by more than 1
        if abs(len1 - len2) > 1:
            return False

        # Case when lengths are equal
        if len1 == len2:
            diff_count = sum(1 for a, b in zip(w1, w2) if a != b)
            return diff_count == 1

        # Case when one word is longer by exactly one character
        if len1 > len2:
            longer, shorter = w1, w2
        else:
            longer, shorter = w2, w1

        # Trying to remove one character
        for i in range(len(longer)):
            if longer[:i] + longer[i+1:] == shorter:
                return True

        return False

    for i in range(len(word_chain) - 1):
        if not is_neighbor(word_chain[i], word_chain[i+1]):
            return False

    return True

