from heapq import heappop, heappush
from typing import List, Tuple

def heuristic(a: Tuple[int, int], b: Tuple[int, int]) -> int:
    """
    Calculate the Manhattan distance heuristic.
    """
    return abs(a[0] - b[0]) + abs(a[1] - b[1])

def a_star_search(grid: List[List[int]], start: Tuple[int, int], goal: Tuple[int, int]) -> List[Tuple[int, int]]:
    """
    Perform A* search to find the shortest path from start to goal in a grid with obstacles.
    """
    rows, cols = len(grid), len(grid[0])
    open_set = [(0, start)]  # Priority queue: (f_score, position)
    came_from = {}  # Path dictionary

    g_score = {start: 0}
    f_score = {start: heuristic(start, goal)}

    while open_set:
        current = heappop(open_set)[1]

        if current == goal:
            path = []
            while current in came_from:
                path.append(current)
                current = came_from[current]
            path.append(start)
            path.reverse()
            return path

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            neighbor = (current[0] + dx, current[1] + dy)
            if 0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols and grid[neighbor[0]][neighbor[1]] == 0:
                tentative_g_score = g_score[current] + 1

                if neighbor not in g_score or tentative_g_score < g_score[neighbor]:
                    came_from[neighbor] = current
                    g_score[neighbor] = tentative_g_score
                    f_score[neighbor] = tentative_g_score + heuristic(neighbor, goal)
                    heappush(open_set, (f_score[neighbor], neighbor))

    return []

