from typing import List, Tuple

def find_two_numbers(nums: List[int], target: int) -> Tuple[int, int]:
    """
    Finds two numbers in `nums` that add up to the `target`.
    Returns a tuple of these two numbers or (-1, -1) if no such pair exists.
    """
    num_map = {}
    for num in nums:
        complement = target - num
        if complement in num_map:
            return (complement, num)
        num_map[num] = True
    return (-1, -1)

