def assign_rooms(preferences: dict[str, list[int]], available_rooms: list[int]) -> dict[str, int]:
    # Create a data structure to facilitate the assignment process
    room_assignments = {}
    room_assigned = set()

    # Process each student and try to assign one of their preferred rooms
    for student, prefs in preferences.items():
        assigned = False
        for room in prefs:
            if room in available_rooms and room not in room_assigned:
                room_assignments[student] = room
                room_assigned.add(room)
                assigned = True
                break  # Move to the next student once the room is assigned

    return room_assignments

