from typing import List, Tuple
from collections import Counter

def recommend_book(user_books: List[str], catalog: List[Tuple[str, str]]) -> str:
    # Create a lookup dictionary for book title to genre
    catalog_dict = {title: genre for title, genre in catalog}

    # Count genres for the user's books
    user_genres = []
    for book in user_books:
        if book not in catalog_dict:
            raise ValueError(f"Book '{book}' not found in the catalog.")
        user_genres.append(catalog_dict[book])

    # Find the most frequent genre
    genre_counter = Counter(user_genres)
    most_frequent_genre = genre_counter.most_common(1)[0][0]

    # Recommend a book from this genre
    for book, genre in catalog:
        if genre == most_frequent_genre:
            return book

from typing import List

def min_cost_path(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])
    dp = [0] * m

    dp[0] = grid[0][0]

    for j in range(1, m):
        dp[j] = dp[j-1] + grid[0][j]

    for i in range(1, n):
        dp[0] += grid[i][0]
        for j in range(1, m):
            dp[j] = min(dp[j], dp[j-1]) + grid[i][j]

    return dp[-1]

