from typing import List

def find_missing_element(arr: List[int]) -> int:
    n = len(arr) + 1

    if not isinstance(arr, list):
        raise TypeError('Input must be a list.')

    if not all(isinstance(i, int) for i in arr):
        raise TypeError('All elements in the list must be integers.')

    if not all(1 <= i <= n for i in arr):
        raise ValueError('Elements must be within the range from 1 to n.')

    if len(arr) != len(set(arr)):
        raise ValueError('All elements in the list must be unique.')

    total_sum = n * (n + 1) // 2
    actual_sum = sum(arr)

    return total_sum - actual_sum

