def manage_parking_lot(commands: list) -> dict:
    parked_cars = {}
    total_occupied_time = 0
    occupied_spots = 0
    max_spots = 10

    for command in commands:
        action, car_id, time = command

        if action == "enter":
            if occupied_spots < max_spots and car_id not in parked_cars:
                parked_cars[car_id] = time
                occupied_spots += 1

        elif action == "leave":
            if car_id in parked_cars:
                total_occupied_time += time - parked_cars[car_id]
                del parked_cars[car_id]
                occupied_spots -= 1

    return {
        'occupied_spots': occupied_spots,
        'total_occupied_time': total_occupied_time
    }

def longest_palindrome_substring(s: str) -> str:
    """
    Identify the longest palindromic substring in the given string.
    """
    def preprocess(s):
        # Function to filter out non-alphanumeric and make all characters lower case
        return ''.join(c.lower() for c in s if c.isalnum())

    def longest_palindrome(s):
        n = len(s)
        if n == 0:
            return ""

        # Initialize a table to record palindromic substrings
        table = [[False] * n for _ in range(n)]

        # All substrings of length 1 are palindromic
        start = 0
        max_length = 1
        for i in range(n):
            table[i][i] = True

        # Check for substrings of length 2
        for i in range(n - 1):
            if s[i] == s[i + 1]:
                table[i][i + 1] = True
                start = i
                max_length = 2

        # Check for lengths greater than 2 and up to n
        for length in range(3, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                # Checking if the substring from i to j is a palindrome
                if s[i] == s[j] and table[i + 1][j - 1]:
                    table[i][j] = True
                    if length > max_length:
                        start = i
                        max_length = length

        return s[start:start + max_length]

    preprocessed = preprocess(s)
    longest_substr = longest_palindrome(preprocessed)

    return longest_substr

