def find_hamiltonian_path_or_cycle(graph, max_node):
    def is_hamiltonian_path(path):
        return len(path) == max_node and len(set(path)) == max_node

    def dfs(node, path):
        if is_hamiltonian_path(path):
            return path[:]
        for neighbor in graph[node]:
            if neighbor not in path:
                path.append(neighbor)
                result = dfs(neighbor, path)
                if result:
                    return result
                path.pop()
        return None

    for start in range(1, max_node + 1):
        path = [start]
        hamiltonian_path = dfs(start, path)
        if hamiltonian_path:
            print("graph has a Hamiltonian path")
            print(hamiltonian_path)
            if hamiltonian_path[0] in graph[hamiltonian_path[-1]]:
                print("graph has a Hamiltonian cycle")
                print(hamiltonian_path + [hamiltonian_path[0]])
            return
    print("graph is not Hamiltonian")
    print("no path")

