def sqrt_newton_method(S: float, tolerance: float = 1e-10) -> float:
    """
    Approximates the square root of a non-negative number S using Newton's method.
    """
    if S < 0:
        raise ValueError("S must be a non-negative number.")

    if S == 0:
        return 0.0

    x_n = max(S / 2.0, 1.0)

    while True:
        x_n1 = 0.5 * (x_n + S / x_n)
        if abs(x_n1 - x_n) < tolerance:
            return x_n1
        x_n = x_n1

