def find_max_length(nums: list[int]) -> int:
    if not nums:
        raise ValueError("Input list cannot be empty")

    # Convert all 0s to -1s to make the problem similar to finding a subarray with sum zero
    nums = [-1 if num == 0 else 1 for num in nums]

    max_length = 0
    cumulative_sum = 0
    sum_indices = {0: -1}  # Cumulative sum has been seen at index -1 as initial condition

    for index, num in enumerate(nums):
        cumulative_sum += num
        if cumulative_sum in sum_indices:
            max_length = max(max_length, index - sum_indices[cumulative_sum])
        else:
            sum_indices[cumulative_sum] = index

    return max_length

