def find_and_replace(text: str, original: str, replacement: str) -> str:
    """
    This function finds all instances of the original word in the text and replaces them with the replacement word,
    such that only whole word matches are replaced and not substrings within other words.
    """
    words = text.split()
    for i in range(len(words)):
        if words[i] == original:
            words[i] = replacement
    return ' '.join(words)

