def encode_string(s):
    """
    Encode the string s to a list of tuples containing each character and the number of its consecutive appearances.
    """
    if not s:
        return []

    result = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            result.append((current_char, count))
            current_char = char
            count = 1

    result.append((current_char, count))

    return result


def decode_string(encoded):
    """
    Decode a list of tuples to the original string.
    """
    result = []

    for char, count in encoded:
        result.append(char * count)

    return ''.join(result)

def track_order_status(order_id: str, status_logs: list[tuple[str, str]]) -> str:
    """
    Returns the final status of an order based on the provided status logs.
    """
    final_status = ""
    for timestamp, status in status_logs:
        if status == "Cancelled":
            return "Cancelled"  # If status is Cancelled, subsequent statuses are ignored
        final_status = status

    return final_status

