def encrypt_message(text):
    """
    Encrypt a message by shifting characters forward in the ASCII table based on their position index.
    """
    encrypted_message = []
    for index, char in enumerate(text):
        new_char = chr((ord(char) + index + 1 - 32) % (126 - 32 + 1) + 32)
        encrypted_message.append(new_char)
    return ''.join(encrypted_message)

def decrypt_message(encrypted_text):
    """
    Decrypt a message by shifting characters backward in the ASCII table based on their position index.
    """
    decrypted_message = []
    for index, char in enumerate(encrypted_text):
        original_char = chr((ord(char) - index - 1 - 32) % (126 - 32 + 1) + 32)
        decrypted_message.append(original_char)
    return ''.join(decrypted_message)

