def first_unique_character(s: str) -> int:
    """
    Finds the index of the first unique character in a given string s.
    If no such character exists, return -1.

    :param s: str - The input string containing lowercase English letters.
    :return: int - The index of the first unique character or -1 if none exists.
    """
    # Step 1: Count the frequency of each character in the string
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Step 2: Find the index of the first unique character
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    return -1

