from typing import List

def longest_increasing_subsequence(arr: List[int]) -> int:
    """
    Returns the length of the longest increasing subsequence in the array.
    """
    if not arr:  # Edge case: empty array
        return 0

    # Stores the largest possible value for the minimum ending value
    # of an increasing subsequence of length i at tails[i - 1]
    tails = []

    for num in arr:
        # Binary search for the smallest number in tails such that tails[i] >= num
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid

        # If left points to the end of tails, it means num is greater than
        # any element in tails, so we append it to extend the subsequence.
        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num

    return len(tails)

