def update_inventory(inventory: dict, transactions: list) -> dict:
    for book_title, quantity_change in transactions:
        if book_title in inventory:
            inventory[book_title] += quantity_change
            if inventory[book_title] < 0:
                inventory[book_title] = 0
        else:
            if quantity_change > 0:
                inventory[book_title] = quantity_change
            else:
                inventory[book_title] = 0
    return inventory

