from typing import List

def custom_permutation_sort(arr: List[int]) -> List[int]:
    """
    This function sorts a list of integers by checking every possible permutation of the array
    and returning the first one that is sorted.
    """
    for perm in permutations(arr):
        if list(perm) == sorted(arr):
            return list(perm)

