from typing import List, Dict, Any

def manage_inventory(actions: List[Dict[str, Any]]) -> Dict[str, int]:
    """
    Processes a list of inventory management actions and returns the current state of the warehouse inventory.

    Parameters:
    - actions (List[Dict[str, Any]]): List of actions to perform on the inventory.

    Returns:
    - Dict[str, int]: The current state of the inventory.
    """
    inventory = {}
    for action in actions:
        if action["action"] == "add":
            if action["product"] not in inventory:
                inventory[action["product"]] = action["quantity"]
            else:
                inventory[action["product"]] += action["quantity"]
        elif action["action"] == "update":
            if action["product"] in inventory:
                inventory[action["product"]] = action["quantity"]
        elif action["action"] == "delete":
            if action["product"] in inventory:
                del inventory[action["product"]]
    return inventory

