def optimal_rental_price(base_price: float, days: int, is_peak_season: bool, car_category: str) -> float:
    """
    Computes the optimal rental price for a car based on base price, number of rental days,
    whether it is peak season or not, and the car category.
    """
    total_price = base_price * days

    # Apply peak season surcharge
    if is_peak_season:
        total_price *= 1.20

    # Apply car category surcharge
    if car_category == "standard":
        total_price *= 1.10
    elif car_category == "luxury":
        total_price *= 1.30

    return round(total_price, 2)

