def sort_books(inventory: list[tuple[int, str]]) -> list[tuple[int, str]]:
    """
    Sorts a list of book inventory records in ascending order based on book titles using the bubble sort algorithm.

    :param inventory: A list of tuples, each containing an integer representing qty and a string with the book title.
    :return: The sorted list based on book titles.
    """
    n = len(inventory)
    for i in range(n):
        for j in range(0, n-i-1):
            if inventory[j][1] > inventory[j+1][1]:
                inventory[j], inventory[j+1] = inventory[j+1], inventory[j]
    return inventory

