def is_prime(num):
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def find_prime_gap(m, n):
    primes = [num for num in range(m, n+1) if is_prime(num)]
    if len(primes) < 2:
        return -1
    min_gap = float('inf')
    for i in range(1, len(primes)):
        min_gap = min(min_gap, primes[i] - primes[i-1])
    return min_gap

