def detect_cycle(graph):
    def dfs(node, parent):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    visited = set()

    for node in graph:
        if node not in visited:
            if dfs(node, -1):
                return True
    return False

