def evaluate_stack_operations(operations: list[str]) -> list[int]:
    stack = []

    for op in operations:
        if op.startswith("PUSH"):
            _, value = op.split()
            stack.append(int(value))
        elif op == "POP":
            if stack:
                stack.pop()
        elif op == "PEEK":
            if stack:
                pass  # PEEK does not modify the stack

    return stack

