import math

def cylinder_volume(radius: float, height: float, volume: float) -> dict[str, float]:
    if radius < 0:
        raise ValueError("Radius cannot be negative")
    if height < 0:
        raise ValueError("Height cannot be negative")
    if volume < 0:
        raise ValueError("Volume cannot be negative")

    if sum(x == 0 for x in (radius, height, volume)) != 1:
        raise ValueError("One and only one argument must be 0")

    if radius == 0:
        # Calculate radius given height and volume
        radius_result = math.sqrt(volume / (math.pi * height))
        return {"radius": radius_result}
    elif height == 0:
        # Calculate height given radius and volume
        height_result = volume / (math.pi * radius ** 2)
        return {"height": height_result}
    else:
        # Calculate volume given radius and height
        volume_result = math.pi * radius ** 2 * height
        return {"volume": volume_result}

