def find_pattern(text: str, pattern: str) -> int:
    """
    Returns the starting index of the first occurrence of the pattern within the text.
    If the pattern is not found, returns -1.
    """
    if not pattern:
        raise ValueError("Pattern must be a non-empty string")

    n, m = len(text), len(pattern)

    # Simple implementation using Python's built-in string method
    for i in range(n - m + 1):
        if text[i:i + m] == pattern:
            return i
    return -1

