def sum_primes(n):
    """
    Returns the sum of all prime numbers less than or equal to n.

    Args:
    n (int): The upper limit for the summation of prime numbers.

    Returns:
    int: Sum of all prime numbers up to and including n.
    """
    if n < 2:
        return 0

    sieve = [True] * (n+1)
    sieve[0] = sieve[1] = False # 0 and 1 are not primes

    p = 2
    while (p * p <= n):
        if (sieve[p] == True):
            for i in range(p * p, n+1, p):
                sieve[i] = False
        p += 1

    prime_sum = 0
    for p in range(n+1):
        if sieve[p]:
            prime_sum += p

    return prime_sum

