def is_valid_rotation(matrix):
    """
    Returns True if any 90-degree rotation of the matrix results in the same matrix, otherwise returns False.
    """
    def rotate_90(matrix):
        N = len(matrix)
        return [[matrix[N - j - 1][i] for j in range(N)] for i in range(N)]

    def rotate_180(matrix):
        return rotate_90(rotate_90(matrix))

    def rotate_270(matrix):
        return rotate_90(rotate_180(matrix))

    rotated_90 = rotate_90(matrix)
    rotated_180 = rotate_180(matrix)
    rotated_270 = rotate_270(matrix)

    return matrix == rotated_90 or matrix == rotated_180 or matrix == rotated_270

