def pair_sum(nums: list[int], target: int) -> list[list[int]]:
    pairs = set()
    seen = {}

    for num in nums:
        complement = target - num
        if complement in seen:
            pair = sorted([num, complement])
            pairs.add(tuple(pair))
        seen[num] = True

    result = [list(pair) for pair in pairs]
    result.sort()
    return result

