def optimized_fibonacci(n: int) -> int:
    """
    Returns the nth Fibonacci number using matrix exponentiation.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1

    def matrix_mult(A, B):
        return [[A[0][0] * B[0][0] + A[0][1] * B[1][0], A[0][0] * B[0][1] + A[0][1] * B[1][1]],
                [A[1][0] * B[0][0] + A[1][1] * B[1][0], A[1][0] * B[0][1] + A[1][1] * B[1][1]]]

    def matrix_pow(M, p):
        if p == 1:
            return M
        elif p % 2 == 0:
            half_pow = matrix_pow(M, p // 2)
            return matrix_mult(half_pow, half_pow)
        else:
            return matrix_mult(M, matrix_pow(M, p - 1))

    F = [[1, 1], [1, 0]]
    result = matrix_pow(F, n-1)

    return result[0][0]

def fib_recursive(n, memo=None):
    """
    Calculates the nth Fibonacci number using recursive approach with memoization.
    """
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n <= 1:
        return n

    memo[n] = fib_recursive(n-1, memo) + fib_recursive(n-2, memo)
    return memo[n]

def fib_iterative(n):
    """
    Calculates the nth Fibonacci number using an iterative approach.
    """
    if n <= 1:
        return n

    prev, curr = 0, 1
    for _ in range(2, n+1):
        prev, curr = curr, prev + curr

    return curr

