def simplify_path(path: str) -> str:
    # Split the given path by '/'
    parts = path.split('/')
    stack = []

    # Process each part
    for part in parts:
        if part == '' or part == '.':
            # Ignore empty and current directory parts
            continue
        elif part == '..':
            # Pop from stack if '..' found and stack is not empty
            if stack:
                stack.pop()
        else:
            # Otherwise, push the part onto stack
            stack.append(part)

    # Join the parts with '/' and return with a leading '/'
    return '/' + '/'.join(stack)

