from collections import deque

def level_order_traversal(tree: list) -> list:
    if not tree:
        return []

    queue = deque([0])  # Start with the root node index
    result = []

    while queue:
        node_index = queue.popleft()
        value, left_index, right_index = tree[node_index]
        result.append(value)

        if left_index is not None:
            queue.append(left_index)
        if right_index is not None:
            queue.append(right_index)

    return result

