def primes_up_to_n(n: int) -> list[int]:
    """
    Returns all prime numbers up to and including n using the Sieve of Eratosthenes algorithm.

    :param n: int - The upper limit for the prime numbers to be found.
    :return: list of integers representing all prime numbers up to and including n.
    :raises ValueError: If the input n is negative.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n < 2:
        return []

    sieve = [True] * (n + 1)
    sieve[0], sieve[1] = False, False

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start * start, n + 1, start):
                sieve[multiple] = False

    primes = [num for num in range(2, n + 1) if sieve[num]]
    return primes

