from typing import List

def is_chessboard_pattern(arr: List[List[int]]) -> bool:
    """
    Checks if the given 2D binary array forms a valid chessboard pattern.
    """
    rows = len(arr)
    cols = len(arr[0])

    def valid_neighbors(r, c):
        """
        Helper function to check if the current cell alternates correctly with its neighbors.
        """
        if r > 0 and arr[r][c] == arr[r-1][c]:
            return False
        if c > 0 and arr[r][c] == arr[r][c-1]:
            return False
        return True

    # Check each cell in the grid:
    for r in range(rows):
        for c in range(cols):
            if not valid_neighbors(r, c):
                return False
    return True

def integer_square_root(n):
    """
    Returns the largest integer m such that m^2 <= n.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return 0
    start, end = 1, n
    while start <= end:
        mid = (start + end) // 2
        mid_squared = mid * mid
        if mid_squared == n:
            return mid
        elif mid_squared < n:
            start = mid + 1
        else:
            end = mid - 1
    return end

