def calculate_price(price: float, category: str) -> float:
    """
    Calculates the total price of an item after applying the sales tax based on the category.

    :param price: Base price of the item.
    :param category: The category of the item, which can be "essential", "luxury", or "other".
    :return: Total price after applying the sales tax.
    """
    if not isinstance(price, (float, int)) or price < 0:
        raise ValueError("Price must be a non-negative float or int.")

    if category not in ["essential", "luxury", "other"]:
        raise ValueError("Category must be one of 'essential', 'luxury', or 'other'.")

    tax_rates = {
        "essential": 0.05,
        "luxury": 0.15,
        "other": 0.10
    }

    tax_rate = tax_rates.get(category)
    total_price = price + (price * tax_rate)
    return round(total_price, 2)


def apply_bulk_discount(price: float, quantity: int) -> float:
    """
    Applies a bulk discount if the quantity is 10 or more.

    :param price: Total price of the items.
    :param quantity: Quantity of the items.
    :return: Total price after applying the bulk discount.
    """
    if not isinstance(price, (float, int)) or price < 0:
        raise ValueError("Price must be a non-negative float or int.")

    if not isinstance(quantity, int) or quantity < 0:
        raise ValueError("Quantity must be a non-negative integer.")

    discount_rate = 0.05
    if quantity >= 10:
        price = price - (price * discount_rate)

    return round(price, 2)

