def calculate_bmi_and_recommendation(height: float, weight: float) -> dict:
    """
    Calculate BMI (Body Mass Index) and provide health recommendation.

    :param height: A positive float representing the height in meters.
    :param weight: A positive float representing the weight in kilograms.
    :return: A dictionary containing the BMI value and the health recommendation.
    :raises ValueError: If height or weight is non-positive.
    :raises TypeError: If height or weight is not a number.
    """
    if not isinstance(height, (int, float)) or not isinstance(weight, (int, float)):
        raise TypeError("Both height and weight must be numbers.")

    if height <= 0:
        raise ValueError("Invalid height. Should be a positive number.")

    if weight <= 0:
        raise ValueError("Invalid weight. Should be a positive number.")

    bmi = weight / (height ** 2)
    bmi = round(bmi, 2)

    if bmi < 18.5:
        recommendation = "Underweight"
    elif 18.5 <= bmi < 24.9:
        recommendation = "Normal weight"
    elif 25.0 <= bmi < 29.9:
        recommendation = "Overweight"
    else:
        recommendation = "Obesity"

    return {"bmi": bmi, "recommendation": recommendation}

