def longest_consecutive_ones(start: int, end: int) -> int:
    def count_consecutive_ones(n: int) -> int:
        """
        Helper function to count maximum consecutive 1s in binary representation of n.
        """
        return max(map(len, bin(n)[2:].split('0')))

    longest = 0
    for num in range(start, end + 1):
        longest = max(longest, count_consecutive_ones(num))

    return longest

