from collections import defaultdict

def average_department_salaries(employees):
    """
    Calculate the average salary for each department from the given list of employee records.

    Parameters:
        employees (list[dict]): List of employee records, each record contains 'name', 'department', and 'salary'.

    Returns:
        dict: Dictionary with department names as keys and average salaries as values.
    """
    department_salaries = defaultdict(list)

    for employee in employees:
        try:
            department = employee['department']
            salary = employee['salary']
            if isinstance(salary, int):
                department_salaries[department].append(salary)
        except KeyError:
            pass  # Ignore entries with missing 'department' or 'salary'

    average_salaries = {
        department: sum(salaries) / len(salaries)
        for department, salaries in department_salaries.items()
    }

    return average_salaries

