from typing import List

def generate_sequences(char_set: List[str], n: int) -> List[str]:
    def backtrack(seq):
        if len(seq) == n:
            result.append("".join(seq))
            return
        for char in char_set:
            if not seq or seq[-1] != char:
                seq.append(char)
                backtrack(seq)
                seq.pop()

    result = []
    backtrack([])
    return result

