from datetime import datetime

def validate_and_format_date(date_strings):
    formats = ["%m/%d/%Y", "%d-%m-%Y", "%Y.%m.%d"]
    valid_dates = []

    for date_string in date_strings:
        valid_date = None
        for fmt in formats:
            try:
                valid_date = datetime.strptime(date_string, fmt).date()
                break
            except ValueError:
                pass

        if valid_date:
            valid_dates.append(valid_date.strftime("%Y-%m-%d"))

    return valid_dates

