from typing import List

def remove_consecutive_duplicates(lst: List[int]) -> List[int]:
    if not lst:
        return []

    # Initialize an empty list for the result
    result = []

    # Start by adding the first element to the result
    result.append(lst[0])

    # Iterate over the elements, starting from the second one
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1]:
            result.append(lst[i])

    return result

