def move_orb(x: int, y: int, direction: str, max_x: int, max_y: int) -> (int, int):
    if direction == 'up':
        new_y = max(0, y - 1)
        return (x, new_y)
    elif direction == 'down':
        new_y = min(max_y, y + 1)
        return (x, new_y)
    elif direction == 'left':
        new_x = max(0, x - 1)
        return (new_x, y)
    elif direction == 'right':
        new_x = min(max_x, x + 1)
        return (new_x, y)
    else:
        # In case of invalid direction, return the original position
        return (x, y)

