def is_valid_move(piece: str, start_pos: str, end_pos: str) -> bool:
    """
    Validates if a move for a given piece from start_pos to end_pos is valid according to standard chess rules.
    """
    start_col, start_row = ord(start_pos[0]), int(start_pos[1])
    end_col, end_row = ord(end_pos[0]), int(end_pos[1])

    if piece == "pawn":
        if start_col == end_col:
            if start_row == 2 and end_row == 4:
                return True
            if end_row == start_row + 1:
                return True
        elif abs(start_col - end_col) == 1 and end_row == start_row + 1:
            return True
        return False

    if piece == "rook":
        return start_col == end_col or start_row == end_row

    if piece == "knight":
        return (abs(start_col - end_col), abs(start_row - end_row)) in [(2, 1), (1, 2)]

    if piece == "bishop":
        return abs(start_col - end_col) == abs(start_row - end_row)

    if piece == "queen":
        return (start_col == end_col or start_row == end_row or
                abs(start_col - end_col) == abs(start_row - end_row))

    if piece == "king":
        return max(abs(start_col - end_col), abs(start_row - end_row)) == 1

    return False

