def can_travel(flights: list[tuple[str, str]], passengers: list[tuple[str, str]]) -> list[bool]:
    from collections import defaultdict, deque

    # Build adjacency list for the graph
    graph = defaultdict(list)
    for start, end in flights:
        graph[start].append(end)

    def bfs(start, end):
        # Perform BFS to find if there is a path from start to end
        if start == end:
            return True
        visited = set()
        queue = deque([start])
        while queue:
            current = queue.popleft()
            if current in visited:
                continue
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor == end:
                    return True
                queue.append(neighbor)
        return False

    results = []
    for start, end in passengers:
        results.append(bfs(start, end))
    return results

