from typing import List

def pawn_possible_moves(position: str, move_type: str) -> List[str]:
    """
    Determine the possible positions a pawn could move to based on the given
    initial position and move type ('move' for normal forward move or 'capture'
    for diagonal capture move).

    :param position: A string representing current position of pawn (e.g., 'e2').
    :param move_type: A string indicating the type of move ('move' or 'capture').

    :return: A list of strings representing possible new positions.
    """
    col, row = position[0], int(position[1])
    possible_moves = []

    if move_type == 'move':
        if row < 8:
            possible_moves.append(f"{col}{row + 1}")
    elif move_type == 'capture':
        if row < 8:
            if col > 'a':
                possible_moves.append(f"{chr(ord(col) - 1)}{row + 1}")
            if col < 'h':
                possible_moves.append(f"{chr(ord(col) + 1)}{row + 1}")

    return possible_moves

def evaluate_rpn(expression: str) -> float:
    """
    Evaluates an expression in Reverse Polish Notation (RPN) and returns the result as a float.

    :param expression: A string representing a valid RPN expression
    :return: The result of the RPN expression as a float
    """
    if not expression:
        raise ValueError("The input RPN expression is empty.")

    tokens = expression.split()
    stack = []

    for token in tokens:
        if token.lstrip('-').isdigit():  # Check if the token is an integer
            stack.append(float(token))
        elif token in ('+', '-', '*', '/'):
            if len(stack) < 2:
                raise ValueError("The input RPN expression is not valid.")
            b = stack.pop()  # Second operand
            a = stack.pop()  # First operand

            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                if b == 0:
                    raise ZeroDivisionError("Division by zero.")
                result = a / b

            stack.append(result)
        else:
            raise ValueError(f"Invalid token '{token}' found in the expression.")

    if len(stack) != 1:
        raise ValueError("The input RPN expression is not valid.")

    return stack[0]

