def caesar_encode(s: str, shift: int) -> str:
    encoded = []
    for char in s:
        encoded_char = chr(((ord(char) - ord('a') + shift) % 26) + ord('a'))
        encoded.append(encoded_char)
    return ''.join(encoded)

def caesar_decode(encoded_s: str, shift: int) -> str:
    decoded = []
    for char in encoded_s:
        decoded_char = chr(((ord(char) - ord('a') - shift) % 26) + ord('a'))
        decoded.append(decoded_char)
    return ''.join(decoded)

def run_length_encoding(s: str) -> str:
    if not s:  # If the string is empty
        return ""

    encoded = []
    count = 1
    prev_char = s[0]

    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            encoded.append(f"{prev_char}{count}")
            prev_char = char
            count = 1

    encoded.append(f"{prev_char}{count}")  # Append the last sequence

    return ''.join(encoded)

