def is_balanced_bracket_sequence(s: str) -> bool:
    """
    Checks if the bracket sequence is balanced.

    Parameters:
    - s (str): A string consisting of only the characters ({[ and ]})

    Returns:
    - bool: True if the bracket sequence is balanced, False otherwise.
    """
    stack = []
    bracket_map = {'(': ')', '[': ']', '{': '}'}

    for char in s:
        if char in bracket_map:
            stack.append(char)
        else:
            if not stack or bracket_map[stack.pop()] != char:
                return False

    return not stack

