def flatten_json_structure(nested_dict, parent_key='', sep='.'):
    items = {}
    for k, v in nested_dict.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.update(flatten_json_structure(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

