def matches_pattern(s: str, pattern: str) -> bool:
    """
    Check if the string `s` contains the exact sequence of characters specified
    in `pattern`.
    """
    if not isinstance(s, str) or not isinstance(pattern, str) or not s or not pattern:
        raise ValueError("Invalid input types or empty strings")

    return pattern in s

def transform_string(s: str, transformations: dict) -> str:
    """
    Transform the string `s` according to the rules specified in the `transformations`
    dictionary.
    """
    if not isinstance(s, str) or not isinstance(transformations, dict) or not s or not transformations:
        raise ValueError("Invalid input types or empty inputs")

    transformed = []
    for char in s:
        if char in transformations:
            transformed.append(transformations[char])
        else:
            transformed.append(char)
    return ''.join(transformed)

