def regex_parser(pattern):
    """
    Parses a simplified regex pattern into a list of tuples, where each tuple contains:
    - Character or special character (like .)
    - Boolean indicating if the character is followed by *
    """
    parsed_pattern = []
    i = 0
    while i < len(pattern):
        if i + 1 < len(pattern) and pattern[i + 1] == '*':
            parsed_pattern.append((pattern[i], True))
            i += 2
        else:
            parsed_pattern.append((pattern[i], False))
            i += 1
    return parsed_pattern

def regex_matcher(parsed_pattern, text):
    """
    Matches the text against the parsed regex pattern.
    """
    def match(i, j):
        # If we reach the end of both the pattern and the text, it's a match
        if i == len(parsed_pattern):
            return j == len(text)

        # Check if we have a match at the current position
        current_char, is_star = parsed_pattern[i]
        match_here = j < len(text) and (current_char == text[j] or current_char == '.')

        if is_star:
            # If there is a star, we can either skip it or match one char and continue
            return (match(i + 1, j) or
                    (match_here and match(i, j + 1)))
        else:
            return match_here and match(i + 1, j + 1)

    return match(0, 0)

def has_cycle(graph: dict) -> bool:
    def visit(node):
        if node in visiting:
            return True
        if node in visited:
            return False
        visiting.add(node)
        for neighbor in graph.get(node, []):
            if visit(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    visited = set()
    visiting = set()
    for node in graph:
        if visit(node):
