from typing import List, Tuple, Set

def get_neighbors(x: int, y: int, grid: List[List[str]]) -> List[Tuple[int, int]]:
    neighbors = []
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows, cols = len(grid), len(grid[0])

    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < rows and 0 <= ny < cols:
            neighbors.append((nx, ny))

    return neighbors

def longest_word_from(x: int, y: int, grid: List[List[str]], visited: Set[Tuple[int, int]]) -> int:
    visited.add((x, y))
    max_length = 1

    for neighbor in get_neighbors(x, y, grid):
        if neighbor not in visited:
            max_length = max(max_length, 1 + longest_word_from(neighbor[0], neighbor[1], grid, visited))

    visited.remove((x, y))
    return max_length

def longest_snake_word(grid: List[List[str]]) -> int:
    max_length = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            max_length = max(max_length, longest_word_from(i, j, grid, set()))
    return max_length

