def is_palindrome(s: str) -> bool:
    """
    Returns True if the given string s is a palindrome, otherwise False.
    The function is case insensitive and ignores non-alphanumeric characters.
    """
    def clean_string(s: str) -> str:
        return ''.join(char.lower() for char in s if char.isalnum())

    def check_palindrome(clean_s: str, left: int, right: int) -> bool:
        if left >= right:
            return True
        if clean_s[left] != clean_s[right]:
            return False
        return check_palindrome(clean_s, left + 1, right - 1)

    clean_s = clean_string(s)
    return check_palindrome(clean_s, 0, len(clean_s) - 1)

