def group_logs_by_user(logs):
    """
    Groups log messages by user ID and sorts actions by timestamp.

    Args:
    logs (list): A list of dictionary objects representing log messages with keys:
                 - 'user_id' (int): Positive integer representing the user ID.
                 - 'timestamp' (int): Non-negative integer representing the Unix timestamp of the log message.
                 - 'action' (str): Non-empty string describing the action performed.

    Returns:
    dict: A dictionary where each key is a user ID, and the value is a list of action strings sorted
          by timestamp in ascending order.
    """
    if not isinstance(logs, list):
        raise TypeError("logs must be a list of dictionaries")

    for log in logs:
        if not isinstance(log, dict):
            raise TypeError("each log entry must be a dictionary")
        if 'user_id' not in log or 'timestamp' not in log or 'action' not in log:
            raise ValueError("every log entry must contain 'user_id', 'timestamp', and 'action' keys")
        if not isinstance(log['user_id'], int) or log['user_id'] <= 0:
            raise ValueError("user_id must be a positive integer")
        if not isinstance(log['timestamp'], int) or log['timestamp'] < 0:
            raise ValueError("timestamp must be a non-negative integer")
        if not isinstance(log['action'], str) or not log['action']:
            raise ValueError("action must be a non-empty string")

    from collections import defaultdict

    user_logs = defaultdict(list)

    for log in logs:
        user_logs[log['user_id']].append((log['timestamp'], log['action']))

    for user_id in user_logs:
        user_logs[user_id].sort()
        user_logs[user_id] = [action for timestamp, action in user_logs[user_id]]

    return dict(user_logs)

from datetime import datetime
from typing import List, Tuple


def can_accept_reservation(
        existing_reservations: List[Tuple[str, str, str]],
        new_reservation: Tuple[str, str, str]) -> bool:

    def parse_date(date_str: str) -> datetime:
        return datetime.strptime(date_str, '%Y-%m-%d')

    new_start_date = parse_date(new_reservation[1])
    new_end_date = parse_date(new_reservation[2])

    for _, start_str, end_str in existing_reservations:
        start_date = parse_date(start_str)
        end_date = parse_date(end_str)

        if max(start_date, new_start_date) <= min(end_date, new_end_date):
            return False

    return True

