def fibonacci_like_sequence(x: int, y: int, n: int) -> List[int]:
    if n == 2:
        return [x, y]

    sequence = [x, y]
    for i in range(2, n):
        next_value = sequence[-1] + sequence[-2]
        sequence.append(next_value)

    return sequence

