def reverse_primes(numbers: list) -> list:
    """
    Returns a list of prime numbers found in 'numbers', in reverse order.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    list: A list of prime numbers in reverse order.

    Raises:
    TypeError: If 'numbers' is not a list.
    ValueError: If the list contains non-integer elements.
    """

    if not isinstance(numbers, list):
        raise TypeError("Input must be a list")

    for num in numbers:
        if not isinstance(num, int):
            raise ValueError("All elements in the list must be integers")

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = [num for num in numbers if is_prime(num)]
    return primes[::-1]

