from typing import List

def find_k_combination(arr: List[int], k: int) -> List[List[int]]:
    if arr is None or k is None or not isinstance(k, int):
        raise TypeError("Invalid input: None")
    if k < 0:
        raise TypeError("The target sum cannot be negative")

    arr.sort()
    res = []

    def backtrack(start, path, target):
        if target == 0:
            res.append(path)
            return
        if target < 0:
            return
        for i in range(start, len(arr)):
            if i > start and arr[i] == arr[i-1]:
                continue
            backtrack(i + 1, path + [arr[i]], target - arr[i])

    backtrack(0, [], k)
    return res

