import heapq

def dijkstra_shortest_path(graph: list[list[int]], start_node: int) -> dict[int, int]:
    """
    Implements Dijkstra's Algorithm to find the shortest path from a start node to all other nodes in a graph.

    :param graph: A 2D list representing the adjacency matrix of the graph.
    :param start_node: An integer representing the starting node.
    :return: A dictionary with node indices as keys and the shortest travel time from the start node as values.
    """
    n = len(graph)
    distances = {i: float('inf') for i in range(n)}
    distances[start_node] = 0
    priority_queue = [(0, start_node)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in enumerate(graph[current_node]):
            if weight != 9999999 and weight != 0:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

    return distances

