def ternary_search(arr: list, target: int) -> int:
    def search(left: int, right: int) -> int:
        if left > right:
            return -1

        one_third = left + (right - left) // 3
        two_third = right - (right - left) // 3

        if arr[one_third] == target:
            return one_third
        if arr[two_third] == target:
            return two_third

        if target < arr[one_third]:
            return search(left, one_third - 1)
        elif target > arr[two_third]:
            return search(two_third + 1, right)
        else:
            return search(one_third + 1, two_third - 1)

    return search(0, len(arr) - 1)

