def highlight_keywords(sentence, keywords):
    """
    Highlights the keywords in the sentence by surrounding them with asterisks ('*').
    """
    words = sentence.split()
    keyword_set = set(keywords.split())

    for i, word in enumerate(words):
        if word in keyword_set:
            words[i] = f"*{word}*"

    return ' '.join(words)

