def find_champion_skill(T, test_cases):
    def compete(skills):
        while len(skills) > 1:
            next_round = []
            for i in range(len(skills) // 2):
                next_round.append(max(skills[i], skills[-(i+1)]))
            skills = next_round
        return skills[0]

    results = []
    for i in range(T):
        N = test_cases[i][0]
        skills = test_cases[i][1]
        results.append(compete(skills))
    return results

