def is_valid_parentheses(s):
    """
    Returns True if the given string s is a valid parentheses sequence, otherwise False.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

def count_char_types(s):
    """
    Takes a string containing alphabets and numbers as input and returns a dictionary
    with the count of each character type. The dictionary has two keys: 'alphabets'
    and 'numbers'.
    """
    result = {'alphabets': 0, 'numbers': 0}

    for char in s:
        if char.isalpha():
            result['alphabets'] += 1
        elif char.isdigit():
            result['numbers'] += 1

    return result

