import math

def is_prime(n):
    """
    Checks if a given number n is a prime number.

    :param n: int
    :return: bool
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

