def find_longest_subarray(arr):
    """
    Returns the length of the longest contiguous subarray where the absolute
    difference between any two elements is less than or equal to 1.
    """
    if not arr:
        return 0

    max_length = 1
    current_subarray_start = 0

    for i in range(1, len(arr)):
        if abs(arr[i] - arr[i-1]) > 1:
            current_subarray_start = i
        else:
            max_length = max(max_length, i - current_subarray_start + 1)

    return max_length

