def common_elements(list1, list2):
    """
    Returns a list containing the common elements between list1 and list2 without duplicates.
    If inputs are not both lists of integers, returns "Invalid input".
    """
    if not isinstance(list1, list) or not isinstance(list2, list):
        return "Invalid input"

    if not all(isinstance(item, int) for item in list1) or not all(isinstance(item, int) for item in list2):
        return "Invalid input"

    common_set = set(list1) & set(list2)
    return list(common_set)

