def process_instructions(q, instructions):
    """
    Process a sequence of instructions and provide the correct outputs for all the "3" instructions.

    Parameters:
    q (int): the number of instructions.
    instructions (list of str): each instruction in one of the formats described above.

    Returns:
    list: output for each "3" instruction.
    """
    result = []
    current_set = set()

    for instruction in instructions:
        parts = instruction.split()
        if parts[0] == "1":
            current_set.add(int(parts[1]))
        elif parts[0] == "2":
            current_set.discard(int(parts[1]))
        elif parts[0] == "3":
            if current_set:
                result.append(max(current_set))
            else:
                result.append("EMPTY")

    return result

