def minDeletionsForPalindrome(s):
    """
    Returns the minimum number of characters to be removed
    to transform the given string into a palindrome.
    """
    n = len(s)

    # Create a table to store results of subproblems
    dp = [[0] * n for _ in range(n)]

    # Fill the table
    for cl in range(2, n+1):
        for i in range(n-cl+1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 0
            elif s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = min(dp[i][j-1], dp[i+1][j]) + 1

    # Result will be the minimum deletions needed for s[0..n-1]
    return dp[0][n-1]

