def smallest_missing_positive(nums):
    """
    Returns the smallest positive integer that is not present in the array.
    If the array consists entirely of non-positive integers, return 1.

    :param nums: List[int]
    :return: int
    """
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

