def count_knight_moves(T, positions):
    # All possible moves a knight can make
    knight_moves = [(-2, -1), (-1, -2), (1, -2), (2, -1),
                    (2, 1), (1, 2), (-1, 2), (-2, 1)]

    result = []
    for x, y in positions:
        count = 0
        for dx, dy in knight_moves:
            nx, ny = x + dx, y + dy
            if 1 <= nx <= 8 and 1 <= ny <= 8:
                count += 1
        result.append(count)

    return result

