def check_palindrome_in_ranges(strings: List[str], ranges: List[Tuple[int, int]]) -> List[bool]:
    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    results = []
    for start, end in ranges:
        concatenated = ''.join(strings[start:end+1])
        results.append(is_palindrome(concatenated))
    return results

