def carrying_capacity(strength_score, race):
    """
    Returns the total carrying capacity of a character based on their strength score and race.
    """
    if strength_score <= 10:
        base_capacity = strength_score * 10
    elif strength_score <= 20:
        base_capacity = (strength_score - 10) * 20 + 100
    elif strength_score <= 30:
        base_capacity = (strength_score - 20) * 30 + 300
    else:
        base_capacity = (strength_score - 30) * 40 + 600

    race_modifiers = {
        "Human": 1.0,
        "Dwarf": 1.2,
        "Elf": 0.9,
        "Orc": 1.3,
    }

    total_capacity = int(base_capacity * race_modifiers[race])
    return total_capacity

