def gcd(a, b):
    """
    Returns the Greatest Common Divisor of `a` and `b` using the Euclidean algorithm.
    """
    while b:
        a, b = b, a % b
    return a

def shared_divisors(x, y):
    """
    Returns the number of common divisors of `x` and `y`.
    """
    def count_divisors(n):
        count = 0
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                count += 1
                if i != n // i:
                    count += 1
        return count

    common_gcd = gcd(x, y)
    return count_divisors(common_gcd)

