def max_profit(prices):
    """
    Returns the maximum profit that can be achieved by buying and selling one share of the stock.

    :param prices: List[int] : A list of stock prices where the index represents the day.
    :return: int : The maximum profit, 0 if no profit is possible.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

