from typing import List

def longest_subarray_with_sum_k(arr: List[int], k: int) -> int:
    sum_map = {}
    curr_sum = 0
    max_len = 0

    for i in range(len(arr)):
        curr_sum += arr[i]

        if curr_sum == k:
            max_len = i + 1

        if (curr_sum - k) in sum_map:
            max_len = max(max_len, i - sum_map[curr_sum - k])

        if curr_sum not in sum_map:
            sum_map[curr_sum] = i

    return max_len

