def length_of_longest_AP(arr):
    n = len(arr)
    if n <= 2:
        return n

    L = [[2 for i in range(n)] for j in range(n)]
    length = 2

    for j in range(n - 2, -1, -1):
        i, k = j - 1, j + 1
        while (i >= 0 and k <= n - 1):
            if (arr[i] + arr[k] < 2 * arr[j]):
                k += 1
            elif (arr[i] + arr[k] > 2 * arr[j]):
                L[i][j] = 2
                i -= 1
            else:
                L[i][j] = L[j][k] + 1
                length = max(length, L[i][j])
                i -= 1
                k += 1

        while (i >= 0):
            L[i][j] = 2
            i -= 1

    return length

def find_max_length_AP(T, test_cases):
    results = []
    for t in range(T):
        N = test_cases[t][0]
        arr = test_cases[t][1]
        results.append(length_of_longest_AP(arr))
    return results

