def number_to_words(n):
    if not (1 <= n <= 999):
        raise ValueError("The number must be in the range from 1 to 999.")

    ones = [
        "", "one", "two", "three", "four", "five", "six",
        "seven", "eight", "nine"
    ]
    teens = [
        "ten", "eleven", "twelve", "thirteen", "fourteen",
        "fifteen", "sixteen", "seventeen", "eighteen",
        "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty",
        "sixty", "seventy", "eighty", "ninety"
    ]

    def two_digit_number_to_words(num):
        if num < 10:
            return ones[num]
        elif num < 20:
            return teens[num - 10]
        else:
            ten = num // 10
            one = num % 10
            return tens[ten] + ("-" + ones[one] if one > 0 else "")

    hundred = n // 100
    remainder = n % 100

    if hundred > 0 and remainder > 0:
        return ones[hundred] + " hundred " + two_digit_number_to_words(remainder)
    elif hundred > 0:
        return ones[hundred] + " hundred"
    else:
        return two_digit_number_to_words(remainder)

