from collections import deque, defaultdict

def topological_sort(vertices, edges):
    in_degree = defaultdict(int)
    graph = defaultdict(list)

    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    zero_in_degree = deque([v for v in range(1, vertices+1) if v not in in_degree])
    top_order = []
    count = 0

    while zero_in_degree:
        vertex = zero_in_degree.popleft()
        top_order.append(vertex)

        for neighbor in graph[vertex]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                zero_in_degree.append(neighbor)

        count += 1

    if count != vertices:
        return "IMPOSSIBLE"

    return top_order

def solve_topological_sort(cases):
    results = []
    for vertices, edges in cases:
        result = topological_sort(vertices, edges)
        if result == "IMPOSSIBLE":
            results.append(result)
        else:
            results.append(" ".join(map(str, result)))
    return results

def is_prime(n):
    """
    Helper function to check if a number is a prime number.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def filter_primes(numbers):
    """
    Takes a list of integers and returns a list of prime numbers from that list.
    """
    return [num for num in numbers if is_prime(num)]

