def min_distance(source: str, target: str) -> int:
    m, n = len(source), len(target)

    # Create a table to store results of subproblems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp[][] in bottom up manner
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If source is empty, insert all characters of target
            elif j == 0:
                dp[i][j] = i  # If target is empty, remove all characters of source
            elif source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # If characters match, no new operation
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],      # Remove
                                   dp[i][j - 1],      # Insert
                                   dp[i - 1][j - 1])  # Replace

    return dp[m][n]

