def rob(nums):
    """
    Returns the maximum amount of money you can steal without triggering the alarm.
    """

    # Helper function
    def rob_line(houses):
        prev = curr = 0
        for money in houses:
            prev, curr = curr, max(curr, prev + money)
        return curr

    if len(nums) == 1:
        return nums[0]
    return max(rob_line(nums[:-1]), rob_line(nums[1:]))

