def alternating_characters(s: str) -> int:
    """
    Returns the minimum number of deletions required so that no two adjacent characters are the same.
    """
    deletions = 0

    # Iterate through the string and count adjacent duplicates
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            deletions += 1

    return deletions

