def encrypt(text):
    def shift_char(c):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') + 13) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') + 13) % 26 + ord('A'))
        else:
            return c

    return ''.join(shift_char(c) for c in text)

def decrypt(cipher):
    # As the encryption is symmetric (ROT13), the decrypt function
    # can re-use the same logic as the encrypt function
    return encrypt(cipher)

