import math

def minDistanceToBuildings(grid):
    def euclidean_distance(x1, y1, x2, y2):
        return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

    N = len(grid)
    buildings = [(i, j) for i in range(N) for j in range(N) if grid[i][j] == 1]

    min_distance = float('inf')
    best_location = None

    for i in range(N):
        for j in range(N):
            if grid[i][j] == 0:
                total_distance = sum(euclidean_distance(i, j, bx, by) for bx, by in buildings)
                if total_distance < min_distance:
                    min_distance = total_distance
                    best_location = (i, j)

    return best_location

def determine_progression(sequence):
    is_ap = True
    is_gp = True
    n = len(sequence)

    # Check for Arithmetic Progression
    common_difference = sequence[1] - sequence[0]
    for i in range(1, n):
        if sequence[i] - sequence[i - 1] != common_difference:
            is_ap = False
            break

    # Check for Geometric Progression
    if sequence[0] != 0:
        common_ratio = sequence[1] / sequence[0]
        for i in range(1, n):
            if sequence[i] == 0 or sequence[i - 1] == 0 or sequence[i] / sequence[i - 1] != common_ratio:
                is_gp = False
                break
    else:
        is_gp = False

    if is_ap and is_gp:
        return "Both"
    elif is_ap:
        return "Arithmetic Progression"
    elif is_gp:
        return "Geometric Progression"
    else:
        return "Neither"

def progression_type(T, sequences):
    results = []
    for sequence in sequences:
        results.append(determine_progression(sequence))
    return results

