from typing import List, Tuple, Dict

def count_cocktails(order_list: List[str], cocktail_alias_list: List[Tuple[str, List[str]]]) -> Dict[str, int]:
    cocktail_counts = {cocktail: 0 for cocktail, _ in cocktail_alias_list}
    alias_to_cocktail = {alias: cocktail for cocktail, aliases in cocktail_alias_list for alias in aliases}

    for order in order_list:
        if order in alias_to_cocktail:
            cocktail_name = alias_to_cocktail[order]
            cocktail_counts[cocktail_name] += 1

    return cocktail_counts

