def min_operations_to_delete_string(s):
    """
    Returns the minimum number of operations required to delete all characters in the string.
    """
    if not s:
        return 0

    # Initialize the count of operations with 1 (for the first character of any string)
    operations = 1

    # Loop through the string and count transitions between different characters
    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            operations += 1

    return operations

