def min_monotonic_sections(n, problems):
    if n == 1:
        return 1

    sections = 1
    increasing = True
    prev = problems[0]

    for i in range(1, n):
        if increasing:
            if problems[i] < prev:
                sections += 1
                increasing = False
        else:
            if problems[i] > prev:
                sections += 1
                increasing = True
        prev = problems[i]

    return sections

