def is_prime(n):
    """
    Checks if a number n is prime.
    """
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_numbers_up_to_N(N):
    """
    Returns a list of all prime numbers from 1 to N.
    """
    primes = []
    for num in range(2, N + 1):
        if is_prime(num):
            primes.append(num)
    return primes

