def reverseParentheses(s: str) -> str:
    stack = []
    for char in s:
        if char == ')':
            temp = []
            while stack and stack[-1] != '(':
                temp.append(stack.pop())
            stack.pop() # Removing the '('
            stack.extend(temp)
        else:
            stack.append(char)
    return ''.join(stack)

