def exists(grid, word):
    def dfs(x, y, word_idx):
        if word_idx == len(word):
            return True
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] != word[word_idx]:
            return False

        temp = grid[x][y]
        grid[x][y] = '#'

        found = (
            dfs(x + 1, y, word_idx + 1) or
            dfs(x - 1, y, word_idx + 1) or
            dfs(x, y + 1, word_idx + 1) or
            dfs(x, y - 1, word_idx + 1)
        )

        grid[x][y] = temp
        return found

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if dfs(i, j, 0):
                return True
    return False

def longest_substring_k_distinct(test_cases):
    def longest_substring_with_k_distinct(s, k):
        n = len(s)
        if n == 0 or k == 0:
            return ""

        left, right = 0, 0
        char_map = {}
        max_len = 0
        max_substr = ""

        while right < n:
            char_map[s[right]] = char_map.get(s[right], 0) + 1

            while len(char_map) > k:
                char_map[s[left]] -= 1
                if char_map[s[left]] == 0:
                    del char_map[s[left]]
                left += 1

            if (right - left + 1) > max_len:
                max_len = right - left + 1
                max_substr = s[left:right + 1]

            right += 1

        return max_substr

    results = []
    for i, (k, s) in enumerate(test_cases):
        longest_substr = longest_substring_with_k_distinct(s, k)
        results.append(f"Case #{i + 1}: {longest_substr}")

    return results

