from math import isqrt

def is_prime(n):
    """
    Returns True if n is a prime number, otherwise returns False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_products(a, b):
    """
    Given two lists of positive integers a and b, returns True if the product of the integers in each
    list are both prime numbers, otherwise returns False.
    """
    product_a = 1
    product_b = 1

    for num in a:
        product_a *= num

    for num in b:
        product_b *= num

    return is_prime(product_a) and is_prime(product_b)

