def remove_duplicates(nums):
    """
    Removes duplicates from the sorted list 'nums' in-place such that each unique element appears at most twice.
    Returns the new length of nums after removing the duplicates.
    """
    if len(nums) <= 2:
        return len(nums)

    # Start from the third element and check for duplicates
    count = 2
    for i in range(2, len(nums)):
        if nums[i] != nums[count - 2]:
            nums[count] = nums[i]
            count += 1

    return count

def maximum_sum(nums):
    n = len(nums)

    if n == 1:
        return nums[0]

    max_end_here = [0] * n
    max_start_here = [0] * n

    max_end_here[0] = nums[0]
    for i in range(1, n):
        max_end_here[i] = max(nums[i], max_end_here[i - 1] + nums[i])

    max_start_here[-1] = nums[-1]
    for i in range(n - 2, -1, -1):
        max_start_here[i] = max(nums[i], max_start_here[i + 1] + nums[i])

    max_sum = max(max_end_here)
    for i in range(1, n - 1):
        max_sum = max(max_sum, max_end_here[i - 1] + max_start_here[i + 1])

    return max_sum

