def minimum_sum_of_three(arr):
    """
    This function returns the smallest possible sum of any three distinct integers in the array.
    If the array has fewer than three distinct integers, it returns None.
    """
    unique_numbers = sorted(set(arr))

    if len(unique_numbers) < 3:
        return None

    return sum(unique_numbers[:3])

