from typing import List

def maxVisibleBuildings(heights: List[int], k: int) -> int:
    n = len(heights)
    max_visible = 1

    for i in range(n):
        visible_count = 1
        left_max = heights[i]

        # Check left side from position i
        for j in range(i - 1, -1, -1):
            if heights[j] > left_max:
                visible_count += 1
                left_max = heights[j]
            if visible_count == k:
                break

        # If already reached the limit, no need to check right side
        if visible_count < k:
            right_max = heights[i]

            # Check right side from position i
            for j in range(i + 1, n):
                if heights[j] > right_max:
                    visible_count += 1
                    right_max = heights[j]
                if visible_count == k:
                    break

        max_visible = max(max_visible, visible_count)

    return max_visible

