def is_balanced_parentheses(s):
    """
    Determines if the input string s has balanced parentheses.
    :param s: str - A string consisting of '(', ')', '{', '}', '[' and ']'
    :return: bool - True if the string is balanced, False otherwise
    """
    stack = []
    opening = {'(': ')', '{': '}', '[': ']'}

    for char in s:
        if char in opening:
            stack.append(char)
        elif char in opening.values():
            if not stack or opening[stack.pop()] != char:
                return False

    return not stack

