def lis_length(arr):
    """
    Function to return the length of the longest increasing subsequence.
    """
    if not arr:
        return 0
    n = len(arr)
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)
    return max(lis)

def lds_length(arr):
    """
    Function to return the length of the longest decreasing subsequence.
    """
    if not arr:
        return 0
    n = len(arr)
    lds = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] < arr[j]:
                lds[i] = max(lds[i], lds[j] + 1)
    return max(lds)

def difference_lis_lds(arr):
    """
    Function to return the difference between the length of the longest increasing
    subsequence and the length of the longest decreasing subsequence.
    """
    lis = lis_length(arr)
    lds = lds_length(arr)
    return lis - lds

