def expand_garden(n, plants, k):
    """
    Expands the garden by appending the mirror image of the last k elements.
    If k is greater than or equal to the length of the array, mirrors the entire array.
    """
    if k >= n:
        mirrored_part = plants[::-1]
    else:
        mirrored_part = plants[-k:][::-1]
    return plants + mirrored_part

