def maximum_swap(S):
    """
    Given a string S representing a positive integer, return the largest possible number
    after swapping at most one pair of digits.
    """
    n = len(S)
    arr = list(S)

    # Track the last occurrence of each digit in the string
    last = {int(x): i for i, x in enumerate(arr)}

    # Traverse the string and find the first occurrence where a larger digit appears later
    for i in range(n):
        for d in range(9, int(arr[i]), -1):
            if last.get(d, -1) > i:
                arr[i], arr[last[d]] = arr[last[d]], arr[i]
                return ''.join(arr)

    return S

def can_communicate(x1, y1, r1, x2, y2, r2):
    """
    Determines if two spaceships can communicate based on their coordinates and transmission radii.
    """
    distance_squared = (x1 - x2)**2 + (y1 - y2)**2
    return distance_squared <= (r1 + r2)**2

def count_communication_pairs(test_cases):
    results = []
    for t in test_cases:
        n = t[0]
        spaceships = t[1]
        count = 0
        for i in range(n):
            for j in range(i+1, n):
                if can_communicate(spaceships[i][0], spaceships[i][1], spaceships[i][2],
                                  spaceships[j][0], spaceships[j][1], spaceships[j][2]):
                    count += 1
        results.append(count)
    return results

