def transform_coordinates(coords, scale, translate):
    if not coords:
        return []

    result = []
    for coord in coords:
        x, y = map(int, coord.strip("()").split(", "))
        x = x * scale + translate
        y = y * scale + translate
        result.append(f"({x}, {y})")

    return result

