def most_common_nucleotide(dna):
    """
    Returns the most common nucleotide in the given DNA string.
    If multiple nucleotides have the same highest frequency,
    returns the one which appears first in alphabetical order.
    If the input string is empty, returns "No nucleotides found."
    """
    if not dna:
        return "No nucleotides found."

    # Convert the string to uppercase to ensure case-insensitivity
    dna = dna.upper()

    nucleotide_counts = {}
    for nucleotide in dna:
        if nucleotide in nucleotide_counts:
            nucleotide_counts[nucleotide] += 1
        else:
            nucleotide_counts[nucleotide] = 1

    most_common_nuc = None
    max_count = 0

    for nucleotide in sorted(nucleotide_counts):
        if nucleotide_counts[nucleotide] > max_count:
            max_count = nucleotide_counts[nucleotide]
            most_common_nuc = nucleotide

    return most_common_nuc

