def count_k_distinct_substrings(s: str, k: int) -> int:
    """
    Returns the number of substrings of length k that have exactly k distinct characters.
    """
    if k > len(s):
        return 0

    count = 0
    for i in range(len(s) - k + 1):
        substr = s[i:i+k]
        if len(set(substr)) == k:
            count += 1
    return count

