def longestChain(words):
    word_set = set(words)
    memo = {}

    def dfs(word):
        if word in memo:
            return memo[word]

        max_len = 1
        for i in range(len(word)):
            next_word = word[:i] + word[i+1:]
            if next_word in word_set:
                current_len = 1 + dfs(next_word)
                max_len = max(max_len, current_len)

        memo[word] = max_len
        return max_len

    max_chain_length = 0
    for word in words:
        max_chain_length = max(max_chain_length, dfs(word))

    return max_chain_length

