def two_sum(nums, target):
    """
    Returns the indices of the two numbers in the list 'nums' that add up to 'target'.
    Assumes that there is exactly one solution and does not use the same element twice.
    """
    indices_map = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in indices_map:
            return [indices_map[complement], i]
        indices_map[num] = i

