def min_days_to_complete_tasks(tasks):
    """
    Determine the minimum number of days required to complete all tasks.

    :param tasks: List[int] - List of integers representing the number of tasks assigned to each worker.
    :return: int - Minimum number of days required to complete all tasks.
    """
    def days_needed_for_tasks(task_count):
        if task_count <= 2:
            return 1
        else:
            quotient, remainder = divmod(task_count, 2)
            return quotient + remainder

    return max(days_needed_for_tasks(task) for task in tasks)

