def min_spells_needed(R, C, forest):
    rows_with_trees = set()
    columns_with_trees = set()

    for i in range(R):
        for j in range(C):
            if forest[i][j] == 'T':
                rows_with_trees.add(i)
                columns_with_trees.add(j)

    return min(len(rows_with_trees), len(columns_with_trees))

