def generate_mountain(n):
    if n <= 0:
        return ""

    lines = []

    # generate the upper part of the mountain
    for i in range(1, n + 1):
        line = " ".join(str(x) for x in range(1, i + 1))
        lines.append(line.center(2 * n - 1))

    # generate the lower part of the mountain
    for i in range(n - 1, 0, -1):
        line = " ".join(str(x) for x in range(1, i + 1))
        lines.append(line.center(2 * n - 1))

    return "\n".join(lines)

def run_length_encoding(s):
    if not s:
        return ""

    result = []
    i = 0
    while i < len(s):
        count = 1
        while i + 1 < len(s) and s[i] == s[i + 1]:
            i += 1
            count += 1
        result.append(f"{s[i]}{count}")
        i += 1

    return "".join(result)

