def largest_subset_size(n, elements):
    """
    Finds the size of the largest subset such that no two elements in the subset differ by more than 1.

    Parameters:
    n (int): Number of elements in the list.
    elements (list): List of positive integers.

    Returns:
    int: Size of the largest subset.
    """
    if n == 1:
        return 1

    frequency = {}
    for element in elements:
        if element in frequency:
            frequency[element] += 1
        else:
            frequency[element] = 1

    max_subset_size = 0

    for element in frequency:
        size = frequency[element]
        if element + 1 in frequency:
            size += frequency[element + 1]
        max_subset_size = max(max_subset_size, size)

    return max_subset_size

