def remaining_petals(N, M, petals, storms):
    """
    Calculate the total number of petals remaining after all the storm intervals are processed.

    :param N: Number of flowers
    :param M: Number of storm intervals
    :param petals: List of integers representing the initial number of petals on each flower
    :param storms: List of tuples (L, R, P) representing the storm intervals
    :return: Integer representing the total number of petals remaining on all flowers
    """
    for L, R, P in storms:
        for i in range(L - 1, R):
            petals[i] = max(0, petals[i] - P)

    return sum(petals)

