def convert_to_grade(scores):
    """
    Converts a list of numeric scores into a list of letter grades based on the school's grading policy.

    Parameters:
    scores (list): A list of integers representing student scores.

    Returns:
    list: A list of single-character strings representing the corresponding letter grades.
    """
    grades = []
    for score in scores:
        if score >= 90:
            grades.append('A')
        elif score >= 80:
            grades.append('B')
        elif score >= 70:
            grades.append('C')
        elif score >= 60:
            grades.append('D')
        else:
            grades.append('F')
    return grades

