from collections import defaultdict, deque

def max_profit(m, d, profits, dependencies):
    # Create graph and in-degree count
    graph = defaultdict(list)
    in_degree = [0] * m
    for u, v in dependencies:
        graph[u-1].append(v-1)
        in_degree[v-1] += 1

    # Apply topological sort (Kahn's algorithm)
    queue = deque()
    for i in range(m):
        if in_degree[i] == 0:
            queue.append(i)

    total_profit = 0
    while queue:
        task = queue.popleft()
        total_profit += profits[task]
        for neighbor in graph[task]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return total_profit

