    Helper function to check if a number n is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def filter_primes(numbers):
    """
    Returns a list of prime numbers filtered from the input list.
    If the length of the input list is greater than 10, the resulting list
    is sorted in ascending order.
    """
    prime_numbers = [num for num in numbers if is_prime(num)]
    if len(numbers) > 10:
        prime_numbers.sort()
    return prime_numbers

