def splitArray(nums, k):
    """
    Split the array into `k` non-empty subsets such that the maximum sum of any subset is minimized.
    Returns the minimized maximum sum of any subset.
    """
    def can_split(mid):
        subset_count = 1
        current_sum = 0
        for num in nums:
            if current_sum + num > mid:
                subset_count += 1
                current_sum = num
                if subset_count > k:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1

    return left

