def can_obtain_by_reversing(S1, S2):
    if S1 == S2:
        return "YES"

    n = len(S1)
    for i in range(n):
        for j in range(i + 1, n + 1):
            reversed_subarray = S2[:i] + S2[i:j][::-1] + S2[j:]
            if reversed_subarray == S1:
                return "YES"

    return "NO"

def process_queries(queries):
    results = []
    for S1, S2 in queries:
        results.append(can_obtain_by_reversing(S1, S2))
    return results

