def has_four_elements_with_sum(arr, target):
    """
    Returns True if there are four distinct elements in the list that add up to the target sum.
    """
    arr.sort()
    n = len(arr)
    if n < 4:
        return False

    for i in range(n - 3):
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and arr[j] == arr[j - 1]:
                continue
            left = j + 1
            right = n - 1
            while left < right:
                current_sum = arr[i] + arr[j] + arr[left] + arr[right]
                if current_sum == target:
                    return True
                elif current_sum < target:
                    left += 1
                else:
                    right -= 1

    return False

