def longest_substring_with_two_a_and_two_b(s):
    """
    This function finds the length of the longest substring containing exactly two 'a's and two 'b's.
    If no such substring exists, it returns 0.
    """
    max_length = 0
    for i in range(len(s)):
        for j in range(i, len(s)):
            substring = s[i: j+1]
            if substring.count('a') == 2 and substring.count('b') == 2:
                max_length = max(max_length, len(substring))
    return max_length

def matrix_rotate(matrix):
    """
    Rotates an NxN matrix (2D list) 90 degrees clockwise in place.
    """
    n = len(matrix)
    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row
    for i in range(n):
        matrix[i].reverse()

