def min_diff_partition(players):
    total_strength = sum(players)
    n = len(players)
    dp = [[False] * (total_strength + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, total_strength + 1):
            if players[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - players[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    min_diff = float('inf')
    for j in range(total_strength // 2 + 1):
        if dp[n][j]:
            min_diff = min(min_diff, total_strength - 2 * j)

    return min_diff

