def uniquePathsWithObstacles(obstacleGrid):
    """
    Returns the number of unique paths from top-left to bottom-right of the grid
    avoiding obstacles.
    """
    if not obstacleGrid or obstacleGrid[0][0] == 1:
        return 0

    n = len(obstacleGrid)
    m = len(obstacleGrid[0])

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if obstacleGrid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

def unique_paths_with_obstacles(grid):
    """
    Returns the number of unique paths from the top-left to the bottom-right corner of the grid,
    avoiding obstacles.
    """
    if not grid or grid[0][0] == 1:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

