def count_good_subarrays(array, q, queries):
    results = []

    for k in queries:
        count = 0
        n = len(array)

        for i in range(n):
            sum_ = 0
            for j in range(i, n):
                sum_ += array[j]
                if sum_ != 0 and sum_ % k == 0:
                    count += 1

        results.append(count)

    return results

