def is_abnormal_temperature(temperatures):
    """
    Determines if each recorded temperature is abnormal.
    """
    if not temperatures:
        return []

    max_temp_so_far = float('-inf')
    result = []

    for temp in temperatures:
        if temp > max_temp_so_far:
            result.append(True)
            max_temp_so_far = temp
        else:
            result.append(False)

    return result

