def evaluate_expression(s):
    """
    Evaluates a mathematical expression string containing digits, parentheses, addition and subtraction.
    Follows standard operator precedence.
    """
    def helper(tokens):
        stack = []
        num = 0
        sign = 1

        while tokens:
            token = tokens.pop(0)
            if token.isdigit():
                num = num * 10 + int(token)
            elif token in '+-':
                stack.append(num * sign)
                num = 0
                sign = 1 if token == '+' else -1
            elif token == '(':
                num = helper(tokens)
            elif token == ')':
                break

        stack.append(num * sign)
        return sum(stack)

    tokens = []
    for char in s:
        if char in '0123456789+-()':
            tokens.append(char)
        elif char == ' ':
            continue

    return helper(tokens)

