def are_permutations(str1, str2):
    """
    Check if the two given strings are permutations of each other.

    Args:
    str1: string
    str2: string

    Returns:
    bool: True if the strings are permutations of each other, False otherwise.
    """
    if len(str1) != len(str2):
        return False

    char_count = {}

    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in str2:
        if char in char_count:
            char_count[char] -= 1
            if char_count[char] == 0:
                del char_count[char]
        else:
            return False

    return len(char_count) == 0

def wordBreak(s, wordDict):
    """
    Returns all possible sentences from the string that can be segmented into space-separated
    sequence of words from the dictionary.
    """
    word_set = set(wordDict)
    memo = {len(s): ['']}

    def sentences(i):
        if i not in memo:
            memo[i] = []
            for j in range(i + 1, len(s) + 1):
                word = s[i:j]
                if word in word_set:
                    for tail in sentences(j):
                        memo[i].append(word + (tail and ' ' + tail))
        return memo[i]

    return sentences(0)

