def unique_paths(grid):
    """
    Returns the number of unique paths in a grid from top-left to bottom-right corner.
    Parameters:
    grid (List[List[int]]): 2D grid where 0 is traversable and 1 is blocked.

    Returns:
    int: the number of unique paths.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    M, N = len(grid), len(grid[0])

    # Initialize a dp array where dp[i][j] represents the number of ways to reach cell (i, j)
    dp = [[0 for _ in range(N)] for _ in range(M)]
    dp[0][0] = 1  # Start at the top-left corner

    # Fill the dp array
    for i in range(M):
        for j in range(N):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

    return dp[-1][-1]

