def max_sum_subarray_with_exactly_m_distinct(coins, n, k, m):
    from collections import defaultdict

    max_sum = -1
    current_sum = 0
    freq = defaultdict(int)

    left = 0
    for right in range(n):
        freq[coins[right]] += 1
        current_sum += coins[right]

        while len(freq) > m:
            freq[coins[left]] -= 1
            if freq[coins[left]] == 0:
                del freq[coins[left]]
            current_sum -= coins[left]
            left += 1

        if right - left + 1 == k:
            if len(freq) == m:
                max_sum = max(max_sum, current_sum)

            freq[coins[left]] -= 1
            if freq[coins[left]] == 0:
                del freq[coins[left]]
            current_sum -= coins[left]
            left += 1

    return max_sum

def coin_game_solution(test_cases):
    results = []
    for coins, n, k, m in test_cases:
        results.append(max_sum_subarray_with_exactly_m_distinct(coins, n, k, m))
    return results

