def evaluate_expression(s):
    """
    Evaluates the mathematical expression given in the string s and returns the result as an integer.
    Division truncates toward zero.
    """
    # Remove all spaces from the string
    s = s.replace(' ', '')

    # Initialize stack, number and sign variables
    stack = []
    num = 0
    sign = "+"

    i = 0
    while i < len(s):
        char = s[i]

        if char.isdigit():
            num = num * 10 + int(char)

        if not char.isdigit() or i == len(s) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                stack.append(int(stack.pop() / num))

            sign = char
            num = 0

        i += 1

    return sum(stack)

