def min_containers(test_cases):
    results = []

    for n, samples in test_cases:
        containers = []

        for sample in samples:
            placed = False
            for container in containers:
                if container[-1] < sample:
                    container.append(sample)
                    placed = True
                    break
            if not placed:
                containers.append([sample])

        results.append(len(containers))

    return results

