from typing import List

def longest_common_prefix(strs: List[str]) -> str:
    if not strs:
        return ""

    # Find the shortest string in the list
    min_length = min(len(s) for s in strs)

    # Initialize the prefix with the first string fully
    prefix = strs[0][:min_length]

    for i in range(min_length):
        # Get the current character to check
        char = prefix[i]
        # Compare it with the same position in all strings
        for s in strs:
            if s[i] != char:
                return prefix[:i]

    return prefix

