def manage_inventory(N, M, shipments, orders):
    # Initialize inventory with zeros
    inventory = [0] * N
    fulfilled_days = 0

    for day in range(M):
        # Add shipment items to inventory
        for i in range(N):
            inventory[i] += shipments[day][i]

        # Check if orders can be fulfilled
        can_fulfill = True
        for i in range(N):
            if inventory[i] < orders[day][i]:
                can_fulfill = False
                break

        if can_fulfill:
            # Fulfill the orders
            for i in range(N):
                inventory[i] -= orders[day][i]
            fulfilled_days += 1
        else:
            break

    return fulfilled_days

def max_profit(prices):
    """
    Returns the maximum profit from a single buy-sell transaction.
    """
    if not prices or len(prices) < 2:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

