def partitionLabels(s):
    """
    Divide the string into as many parts as possible so that each letter appears in at most one part.
    Return the lengths of each part in an array.
    """
    # First, find the last occurrence of each character
    last_occurrence = {char: idx for idx, char in enumerate(s)}

    parts = []
    start, end = 0, 0

    for i, char in enumerate(s):
        end = max(end, last_occurrence[char])
        if i == end:
            parts.append(i - start + 1)
            start = i + 1

    return parts

