def sudoku_validator(grid):
    def is_valid_line(line):
        elements = [num for num in line if num != 0]
        return len(elements) == len(set(elements))

    def is_valid_subgrid(grid, start_row, start_col):
        elements = []
        for i in range(3):
            for j in range(3):
                num = grid[start_row + i][start_col + j]
                if num != 0:
                    elements.append(num)
        return len(elements) == len(set(elements))

    for row in grid:
        if not is_valid_line(row):
            return False

    for col in range(9):
        if not is_valid_line([grid[row][col] for row in range(9)]):
            return False

    for row in range(0, 9, 3):
        for col in range(0, 9, 3):
            if not is_valid_subgrid(grid, row, col):
                return False

    return True

def character_frequency(input_str):
    """
    Calculate the frequency of each character in the given string.
    Characters are considered case-insensitively.

    :param input_str: The input string
    :return: Dictionary with characters as keys and their frequencies as values.
    """
    if not isinstance(input_str, str) or input_str == "":
        return {}

    frequency_dict = {}
    for char in input_str.lower():
        if char.isalpha():
            frequency_dict[char] = frequency_dict.get(char, 0) + 1

    return frequency_dict

