def k_palindrome(s, k):
    """
    Determine if the string s can be transformed into a palindrome
    by removing at most k characters.
    """
    def longest_common_subsequence(s1, s2):
        len1, len2 = len(s1), len(s2)
        dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]

        for i in range(1, len1 + 1):
            for j in range(1, len2 + 1):
                if s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[len1][len2]

    s_reversed = s[::-1]
    lcs_length = longest_common_subsequence(s, s_reversed)
    return len(s) - lcs_length <= k

