def sort_string(s):
    """
    This function takes a string with a mix of letters and digits.
    It returns a new string with all the digits coming before the letters,
    while preserving the relative order of the digits and letters in the original string.
    """
    digits = []
    letters = []

    for char in s:
        if char.isdigit():
            digits.append(char)
        else:
            letters.append(char)

    return ''.join(digits) + ''.join(letters)

