def isSudokuValid(board):
    def is_valid_group(group):
        """Helper function to check if a group contains digits 1-9 without repetition"""
        return sorted(group) == list(range(1, 10))

    def extract_sub_boxes(board):
        """Extract all 3x3 sub-boxes from the board"""
        sub_boxes = []
        for i in range(0, 9, 3):
            for j in range(0, 9, 3):
                sub_box = [board[x][y] for x in range(i, i + 3) for y in range(j, j + 3)]
                sub_boxes.append(sub_box)
        return sub_boxes

    if len(board) != 9 or any(len(row) != 9 for row in board):
        return False

    for row in board:
        if any(not isinstance(cell, int) or not (1 <= cell <= 9) for cell in row):
            return False

    # Check rows and columns
    for i in range(9):
        row = board[i]
        column = [board[j][i] for j in range(9)]
        if not is_valid_group(row) or not is_valid_group(column):
            return False

    # Check 3x3 sub-boxes
    sub_boxes = extract_sub_boxes(board)
    for sub_box in sub_boxes:
        if not is_valid_group(sub_box):
            return False

    return True

def longest_contiguous_subarray(arr):
    """
    Returns the length of the longest contiguous subarray with all elements equal.
    """
    if not arr:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(arr)):
        if arr[i] == arr[i-1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    max_length = max(max_length, current_length)

    return max_length

