from math import gcd
from functools import reduce

def max_gcd_subsequence_length(t, test_cases):
    results = []

    for i in range(t):
        n, g = test_cases[i][0]
        a = test_cases[i][1]

        # Select all numbers that are multiples of g
        multiples_of_g = [num for num in a if num % g == 0]

        if not multiples_of_g:
            results.append(-1)
        else:
            # Compute the GCD of the selected numbers
            current_gcd = reduce(gcd, multiples_of_g)

            if current_gcd == g:
                results.append(len(multiples_of_g))
            else:
                results.append(-1)

    return results

