from typing import List

def find_peaks(numbers: List[int]) -> List[int]:
    """
    Returns a list of peaks from the given list of integers.
    A peak is defined as an element that is strictly greater than its neighbours.
    """
    peaks = []
    n = len(numbers)

    if n == 0:
        return peaks

    for i in range(n):
        if i == 0 and n > 1 and numbers[i] > numbers[i + 1]:
            peaks.append(numbers[i])
        elif i == n - 1 and n > 1 and numbers[i] > numbers[i - 1]:
            peaks.append(numbers[i])
        elif 0 < i < n - 1 and numbers[i] > numbers[i - 1] and numbers[i] > numbers[i + 1]:
            peaks.append(numbers[i])
        elif n == 1:
            peaks.append(numbers[i])

    return peaks

def department_counts(employees):
    """
    Returns a dictionary with the count of employees in each department.
    """
    department_count = {}
    for employee in employees:
        department = employee['department']
        if department in department_count:
            department_count[department] += 1
        else:
            department_count[department] = 1
    return department_count

