def is_prime(num):
    """
    Returns True if num is a prime number, otherwise False.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def prime_factors(n):
    """
    Returns a list of all prime factors of the given integer n in ascending order.
    Each prime factor appears in the list as many times as it divides n.
    """
    factors = []
    # Check for number of 2s in n
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    # Check for odd factors from 3 to sqrt(n)
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 2:
        factors.append(n)
    return factors

