def min_deletions_to_palindrome(n, s):
    """
    This function returns the minimum number of deletions required to make a given string a palindrome.
    """

    def longest_palindromic_subsequence(s):
        """
        Helper function to calculate the length of the longest palindromic subsequence in s.
        """
        m = len(s)
        dp = [[0] * m for _ in range(m)]

        for i in range(m):
            dp[i][i] = 1

        for cl in range(2, m + 1):
            for i in range(m - cl + 1):
                j = i + cl - 1
                if s[i] == s[j]:
                    if cl == 2:
                        dp[i][j] = 2
                    else:
                        dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

        return dp[0][m - 1]

    lps = longest_palindromic_subsequence(s)
    return n - lps

def process_test_cases(t, test_cases):
    """
    This function processes multiple test cases and returns the minimum deletions for each case.
    """
    result = []
    for i in range(t):
        n, s = test_cases[i]
        result.append(min_deletions_to_palindrome(n, s))
    return result

def find_two_sum(nums, target):
    """
    Given an array of integers nums and an integer target, return indices of the two numbers
    such that they add up to the target. Assumes that there's exactly one solution.
    """
    num_to_index = {}

    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], index]
        num_to_index[num] = index

