def find_pair(numbers_str, target):
    """
    Finds a pair of integers from the comma-separated input string that sum up to the target.

    :param numbers_str: A string of comma-separated integers.
    :param target: The target sum we want to achieve.
    :return: A tuple containing the pair of integers that sum to the target, or an empty tuple if no such pair exists.
    """
    numbers = list(map(int, numbers_str.split(',')))
    seen = set()

    for number in numbers:
        complement = target - number
        if complement in seen:
            return (complement, number)
        seen.add(number)

    return ()

