def find_smallest_missing_positive(nums):
    """
    Returns the smallest positive integer that is missing from the list.
    """
    nums = [num for num in nums if num > 0]
    n = len(nums)

    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            pos = nums[i] - 1
            nums[i], nums[pos] = nums[pos], nums[i]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

