def longest_equal_subarray(arr):
    """
    Returns the length of the longest subarray where the number of 0s equals the number of 1s.
    """
    count_map = {0: -1}
    max_len = 0
    count = 0

    for i, num in enumerate(arr):
        count += -1 if num == 0 else 1

        if count in count_map:
            max_len = max(max_len, i - count_map[count])
        else:
            count_map[count] = i

    return max_len

