def max_virtual_objects(n, m, d, k, potential_positions):
    def dist(x1, y1, x2, y2):
        return ((x1 - x2) ** 2 + (y1 - y2) ** 2) ** 0.5

    def can_place(position):
        for i, placed in enumerate(placed_positions):
            if dist(position[0], position[1], placed[0], placed[1]) < d:
                return False
        return True

    placed_positions = []
    for i in range(k):
        x, y = potential_positions[2*i], potential_positions[2*i + 1]
        if can_place((x, y)):
            placed_positions.append((x, y))

    return len(placed_positions)

