def unique_digits(s):
    """
    Checks whether the given string is a valid integer and all its digits are unique.
    Returns True if the integer has no repeated digits, and False otherwise.
    """
    if not s.lstrip('-').isdigit():
        return False

    digit_set = set()
    for char in s.lstrip('-'):
        if char in digit_set:
            return False
        digit_set.add(char)

    # Check for leading zeros
    if s != '0' and s.lstrip('-')[0] == '0':
        return False

    return True

