def cherryPickup(grid):
    m, n = len(grid), len(grid[0])
    dp = [[[0] * n for _ in range(n)] for _ in range(m)]
    dp[0][0][n-1] = grid[0][0] + (grid[0][n-1] if n > 1 else 0)

    for r in range(1, m):
        for c1 in range(min(r+1, n)):
            for c2 in range(max(0, n-1-r), n):
                max_cherries = 0
                for dc1 in [-1, 0, 1]:
                    for dc2 in [-1, 0, 1]:
                        prev_c1, prev_c2 = c1 + dc1, c2 + dc2
                        if 0 <= prev_c1 < n and 0 <= prev_c2 < n:
                            max_cherries = max(max_cherries, dp[r-1][prev_c1][prev_c2])

                dp[r][c1][c2] = max_cherries + grid[r][c1] + (0 if c1 == c2 else grid[r][c2])

    return max(dp[m-1][c1][c2] for c1 in range(n) for c2 in range(n))

