from typing import List, Tuple

def find_peak(grid: List[List[int]]) -> Tuple[int, int]:
    """
    Find a peak element in a 2D grid and return its coordinates.
    An element is a peak if it is greater than its neighbors.
    Treat elements outside the bounds of the grid as negative infinity.
    """
    rows = len(grid)
    cols = len(grid[0])

    def is_peak(i: int, j: int) -> bool:
        """
        Checks if the grid[i][j] is a peak element.
        """
        current = grid[i][j]
        # Check top
        if i > 0 and grid[i-1][j] >= current:
            return False
        # Check bottom
        if i < rows - 1 and grid[i+1][j] >= current:
            return False
        # Check left
        if j > 0 and grid[i][j-1] >= current:
            return False
        # Check right
        if j < cols - 1 and grid[i][j+1] >= current:
            return False
        return True

    for i in range(rows):
        for j in range(cols):
            if is_peak(i, j):
                return (i, j)

    # Should not reach here as there should be at least one peak in the grid.
    return (-1, -1)

def num_ways_to_traverse(matrix):
    N = len(matrix)
    M = len(matrix[0])

    if matrix[0][0] == 1 or matrix[N-1][M-1] == 1:
        return 0

    dp = [[0]*M for _ in range(N)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if matrix[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[N-1][M-1]

