def convert_to_base26(n):
    """
    Converts a positive integer n to a string representing the number in base 26 using the letters 'A' to 'Z'.
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer")

    base26 = []
    while n > 0:
        n -= 1  # Adjust for 0-indexed calculation
        base26.append(chr((n % 26) + ord('A')))
        n //= 26

    return ''.join(reversed(base26))

def min_transfer_time(n, rootID, parent, dataTransfer):
    from collections import defaultdict

    def dfs(server):
        max_time = 0
        for child in tree[server]:
            child_time = dfs(child) + dataTransfer[child]
            max_time = max(max_time, child_time)
        return max_time

    tree = defaultdict(list)
    for i in range(n):
        if parent[i] != -1:
            tree[parent[i]].append(i)

    return dfs(rootID)

