def longest_increasing_subsequence(arr):
    """
    Function to return the length of the longest increasing subsequence in an array of integers.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n  # dp[i] represents the length of LIS ending at index i

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

