def contains_nearby_almost_duplicate(nums, k, t):
    """
    Determines if there are two distinct indices i and j in the array such that
    the absolute difference between nums[i] and nums[j] is at most t and
    the absolute difference between i and j is at most k.
    """
    if k <= 0 or t < 0 or not nums:
        return False

    n = len(nums)

    values = {}

    for i in range(n):
        bucket_id = nums[i] // (t + 1)
        if bucket_id in values:
            return True
        if bucket_id - 1 in values and abs(nums[i] - values[bucket_id - 1]) <= t:
            return True
        if bucket_id + 1 in values and abs(nums[i] - values[bucket_id + 1]) <= t:
            return True

        values[bucket_id] = nums[i]

        if i >= k:
            del values[nums[i - k] // (t + 1)]

    return False

