    """
    def dfs(x, y, direction):
        if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]) or grid[x][y] == 0:
            return
        grid[x][y] = 0
        shape_signature.append(direction)
        dfs(x + 1, y, 'd')  # down
        dfs(x - 1, y, 'u')  # up
        dfs(x, y + 1, 'r')  # right
        dfs(x, y - 1, 'l')  # left
        shape_signature.append('b')  # backtracking

    distinct_shapes = set()
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                shape_signature = []
                dfs(i, j, 'o')  # origin
                distinct_shapes.add(tuple(shape_signature))

    return len(distinct_shapes)

def dict_operations(n, commands):
    dictionary = {}
    result = []

    for command in commands:
        command_parts = command.split()
        action = command_parts[0]

        if action == 'add':
            key, value = command_parts[1], command_parts[2]
            if value.isdigit():
                value = int(value)
            dictionary[key] = value

        elif action == 'remove':
            key = command_parts[1]
            if key in dictionary:
                del dictionary[key]

        elif action == 'exists':
            key = command_parts[1]
            result.append(key in dictionary)

        elif action == 'get':
            key = command_parts[1]
            result.append(dictionary.get(key))

        elif action == 'keys':
            result.append(list(dictionary.keys()))

        elif action == 'values':
            result.append(list(dictionary.values()))

        elif action == 'clear':
            dictionary.clear()

    return result

