def is_prime(num):
    """
    Helper function to determine if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def sum_of_primes(array):
    """
    Function to calculate the sum of all prime numbers in an array.
    """
    return sum(num if is_prime(num) else 0 for num in array)

