def mostFrequentCharacter(s):
    """
    Returns the character that appears most frequently in the string `s`.
    If there are multiple characters with the same highest frequency,
    returns the one that appears first in the string. Spaces are ignored.

    :param s: input string
    :return: character that appears most frequently
    """
    frequency = {}
    max_count = 0
    most_frequent_char = None

    for char in s:
        if char == ' ':
            continue
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

        if frequency[char] > max_count or (frequency[char] == max_count and most_frequent_char is None):
            max_count = frequency[char]
            most_frequent_char = char

    return most_frequent_char

