def secure_transform(message, key):
    def char_to_number(char):
        return ord(char) - ord('A') + 1

    def number_to_char(num):
        return chr(((num - 1) % 26) + ord('A'))

    transformed_message = ""
    for char in message:
        original_number = char_to_number(char)
        transformed_number = (original_number + key - 1) % 26 + 1
        transformed_message += number_to_char(transformed_number)

    return transformed_message

