def compute_values(lines):
    results = []
    for line in lines:
        if line.strip() == "":
            break
        numbers = list(map(int, line.split()))
        S = sum(n for n in numbers if n < 0)
        D = max(numbers) - min(numbers) if len(numbers) > 1 else 0
        results.append(f"{S} {D}")
    return results

from typing import List

def min_partition_difference(nums: List[int]) -> List[int]:
    total_sum = sum(nums)
    n = len(nums)

    # DP Table to store boolean values
    dp = [[False] * (total_sum // 2 + 1) for _ in range(n + 1)]

    # Initialization of DP table
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, total_sum // 2 + 1):
            if nums[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Finding the maximum value that can be achieved close to total_sum / 2
    for j in range(total_sum // 2, -1, -1):
        if dp[n][j] == True:
            sum1 = j
            break

    sum2 = total_sum - sum1

    return [sum1, sum2]

