def is_valid_email(email):
    """
    Returns True if the input string is a valid email address according to the specified rules, otherwise False.
    """
    if "@" not in email or email.count("@") != 1:
        return False

    local_part, domain_part = email.split("@")

    if not local_part or not domain_part:
        return False

    if "." not in domain_part or ".." in email or domain_part.startswith("."):
        return False

    if domain_part.find('.') == len(domain_part) - 1:
        return False

    return True

