def is_prime(n):
    """
    Determine if the input number is a prime number.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def filter_primes(numbers):
    """
    Returns a list of prime numbers from the given list.
    """
    return [n for n in numbers if is_prime(n)]

