def longest_zero_sum_subarray(arr):
    """
    Returns the length of the longest subarray with a sum of zero.
    """
    sum_index_map = {}
    max_len = 0
    curr_sum = 0

    for i in range(len(arr)):
        curr_sum += arr[i]

        if curr_sum == 0:
            max_len = i + 1
        if curr_sum in sum_index_map:
            subarray_len = i - sum_index_map[curr_sum]
            max_len = max(max_len, subarray_len)
        else:
            sum_index_map[curr_sum] = i

    return max_len

