def audit_inventory(actions):
    """
    Updates inventory quantities based on a list of actions.

    Parameters:
    actions (list of tuple): A list where each tuple contains:
                             - A unique item ID (string)
                             - A quantity (integer)
                             - An action (string): either "add" or "remove"

    Returns:
    dict: A dictionary with item IDs as keys and their final quantities as values.
    """
    inventory = {}

    for item_id, quantity, action in actions:
        if item_id not in inventory:
            inventory[item_id] = 0

        if action == "add":
            inventory[item_id] += quantity
        elif action == "remove":
            inventory[item_id] -= quantity
            if inventory[item_id] < 0:
                inventory[item_id] = 0

    return inventory

