def is_balanced(sequence):
    """
    Determines if the input string consisting of parentheses and brackets is balanced.

    Args:
    sequence (str): The string containing the sequence of parentheses and brackets.

    Returns:
    bool: Returns True if the string is balanced, False otherwise.
    """
    stack = []
    matching_bracket = {')':'(', ']':'['}

    for char in sequence:
        if char in '([':
            stack.append(char)
        elif char in ')]':
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return len(stack) == 0

