def final_position(start_x, start_y, instructions):
    """
    Calculate the final coordinates after executing a series of movement instructions.

    Args:
    start_x (int): Starting x-coordinate
    start_y (int): Starting y-coordinate
    instructions (str): A string of movement instructions which can be 'U', 'D', 'L', 'R'

    Returns:
    tuple: Final coordinates (end_x, end_y) after performing all the movements
    """
    x, y = start_x, start_y

    for instruction in instructions:
        if instruction == 'U':
            y += 1
        elif instruction == 'D':
            y -= 1
        elif instruction == 'L':
            x -= 1
        elif instruction == 'R':
            x += 1

    return (x, y)

