def minimumDifference(nums):
    total_sum = sum(nums)
    n = len(nums)
    dp = [0] * (total_sum // 2 + 1)

    for num in nums:
        for i in range(total_sum // 2, num - 1, -1):
            dp[i] = max(dp[i], dp[i - num] + num)

    sum1 = dp[total_sum // 2]
    sum2 = total_sum - sum1
    return abs(sum1 - sum2)

