def process_subarray_sums(n, array, q, queries):
    # Calculate prefix sums
    prefix_sums = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_sums[i] = prefix_sums[i - 1] + array[i - 1]

    results = []
    for l, r in queries:
        subarray_sum = prefix_sums[r] - prefix_sums[l - 1]
        if subarray_sum % 2 == 0:
            results.append(subarray_sum - 1)
        else:
            results.append(subarray_sum + 1)

    return results

def evaluate_expression(expression):
    """
    Evaluates a mathematical expression consisting of positive integers, '+', '*', and parentheses.

    :param expression: str, a string representing the mathematical expression
    :return: int, the result of the evaluated expression
    """
    def helper(s, index):
        stack = []
        num = 0
        sign = "+"

        while index < len(s):
            ch = s[index]

            if ch.isdigit():
                num = num * 10 + int(ch)

            if ch == '(':
                num, index = helper(s, index + 1)

            if ch in "+*)" or index == len(s) - 1:
                if sign == '+':
                    stack.append(num)
                elif sign == '*':
                    stack[-1] = stack[-1] * num

                if ch == ')':
                    return sum(stack), index

                sign = ch
                num = 0

            index += 1

        return sum(stack), index

    return helper(expression, 0)[0]

