def find_anagrams(array1, array2):
    """
    Returns a sorted array of unique strings that are anagrams of each other from the two input arrays.
    """
    def is_anagram(str1, str2):
        return sorted(str1) == sorted(str2)

    result = set()
    for word1 in array1:
        for word2 in array2:
            if is_anagram(word1, word2):
                result.add(word1)
                result.add(word2)

    return sorted(result)

def count_distinct_paths(grid):
    from functools import lru_cache

    M = len(grid)
    N = len(grid[0])

    @lru_cache(None)
    def dfs(x, y):
        # If we hit an obstacle, return 0
        if x < 0 or x >= M or y < 0 or y >= N or grid[x][y] == '#':
            return 0

        # If we reached the bottom-right corner, return 1
        if x == M-1 and y == N-1:
            return 1

        # Explore all possible paths
        return dfs(x+1, y) + dfs(x, y+1)

    if grid[0][0] == '#' or grid[M-1][N-1] == '#':
        return 0

    return dfs(0, 0)

