def oldest_in_each_group(people_str):
    if not people_str:
        return ""

    people = people_str.split(", ")

    groups = {}
    for person in people:
        name, age, group = person.split("|")
        age = int(age)
        group = group.lower()  # Case-insensitive comparison

        if group not in groups or groups[group][1] < age:
            groups[group] = (name, age)

    result = []
    for group in sorted(groups):
        name, age = groups[group]
        result.append(f"Group {group.upper()}: {name}|{age}")

    return ", ".join(result)

