def inventory_manager(input_str):
    """
    Parses the inventory list string and returns an array of dictionaries.

    :param input_str: str, the inventory list string
    :return: list of dictionaries
    """
    if not input_str:
        return []

    items = input_str.split(';')
    inventory_list = []

    for item in items:
        parts = item.split(',')
        if len(parts) == 3:
            equipment_type, equipment_id, description = parts
            inventory_list.append({
                "type": equipment_type,
                "id": equipment_id,
                "description": description
            })

    return inventory_list

