def is_manager(n, reports, a, b):
    """
    Determine if employee `a` is a direct or indirect manager of employee `b`.
    """
    from collections import defaultdict, deque

    management_tree = defaultdict(list)

    for manager, direct_report in reports:
        management_tree[manager].append(direct_report)

    queue = deque([a])

    while queue:
        current = queue.popleft()
        if current == b:
            return True
        for direct_report in management_tree[current]:
            queue.append(direct_report)

    return False

def balance_fleet(weights):
    """
    Calculate the minimum possible difference between the sums of weights of two groups.
    """
    total_weight = sum(weights)
    n = len(weights)
    dp = [[False] * (total_weight // 2 + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for w in range(total_weight // 2 + 1):
            if dp[i - 1][w]:
                dp[i][w] = True
            elif w >= weights[i - 1]:
                dp[i][w] = dp[i - 1][w] or dp[i - 1][w - weights[i - 1]]

    for w in range(total_weight // 2, -1, -1):
        if dp[n][w]:
            return total_weight - 2 * w

