from collections import deque

def deque_operations(operations):
    """
    Performs operations on a deque and returns the final state of the deque.

    :param operations: List of strings, each representing an operation
    :return: Final state of the deque as a list
    """
    d = deque()

    for operation in operations:
        if operation.startswith("push_front"):
            _, x = operation.split()
            d.appendleft(int(x))
        elif operation.startswith("push_back"):
            _, x = operation.split()
            d.append(int(x))
        elif operation == "pop_front":
            if d:
                d.popleft()
        elif operation == "pop_back":
            if d:
                d.pop()

    return list(d)

