def count_pairs_with_difference(nums, target):
    """
    Returns the number of pairs of integers in the array whose difference is equal to target.
    """
    if target == 0:
        counts = {}
        for num in nums:
            if num in counts:
                counts[num] += 1
            else:
                counts[num] = 1
        return sum(c * (c - 1) // 2 for c in counts.values())

    num_set = set(nums)
    count = 0
    for num in nums:
        if num + target in num_set:
            count += 1
        if num - target in num_set:
            count += 1
        num_set.discard(num)
    return count

