from itertools import permutations

def can_arrange_paintings(n, k, beauty_scores):
    # Generate all the permutations of indices
    for perm in permutations(range(1, n+1)):
        valid = True
        # Check every group of three consecutive paintings
        for i in range(n-2):
            total_beauty = beauty_scores[perm[i]-1] + beauty_scores[perm[i+1]-1] + beauty_scores[perm[i+2]-1]
            if total_beauty % k == 0:
                valid = False
                break
        if valid:
            return ("Yes", list(perm))
    return ("No",)

