def minJumps(arr: list) -> int:
    if len(arr) <= 1:
        return 0

    # If the first element is 0, we cannot move anywhere
    if arr[0] == 0:
        return -1

    jumps = 0
    current_end = 0
    farthest = 0

    for i in range(len(arr) - 1):
        farthest = max(farthest, i + arr[i])

        # If we have reached the end of the range for the current jump
        if i == current_end:
            jumps += 1
            current_end = farthest

            # If the farthest we can reach is already the end, return jumps
            if current_end >= len(arr) - 1:
                return jumps

    return -1 if current_end < len(arr) - 1 else jumps

def evaluate_expression(s: str) -> int:
    def helper(tokens):
        stack = []
        num = 0
        sign = '+'
        while tokens:
            token = tokens.pop(0)
            if token.isdigit():
                num = num * 10 + int(token)
            if token == '(':
                num = helper(tokens)
            if (not token.isdigit() and token != ' ') or not tokens:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack[-1] *= num
                elif sign == '/':
                    stack[-1] = int(stack[-1] / num)
                sign = token
                num = 0
            if token == ')':
                break
        return sum(stack)

    tokens = list(s)
    return helper(tokens)

