def process_commands(commands):
    total_income = 0
    total_expenses = 0
    income_report = []
    expenses_report = []

    for command in commands:
        parts = command.split()
        action = parts[0]

        if action == "income":
            amount = int(parts[1])
            total_income += amount
        elif action == "expense":
            amount = int(parts[1])
            total_expenses += amount
        elif action == "report":
            income_report.append(total_income)
            expenses_report.append(total_expenses)

    return (income_report, expenses_report)

