def customSortString(s: str) -> str:
    """
    Sorts the characters in the string as follows:
    - All alphabetical characters (both uppercase and lowercase) come first,
    - Followed by numeric characters,
    - Followed by punctuation marks.
    Within each category, characters appear in the order they first appear in the input string.
    """
    alphabetic_characters = []
    numeric_characters = []
    punctuation_characters = []

    for char in s:
        if char.isalpha():
            alphabetic_characters.append(char)
        elif char.isdigit():
            numeric_characters.append(char)
        else:
            punctuation_characters.append(char)

    return ''.join(alphabetic_characters + numeric_characters + punctuation_characters)

