def is_prime(n):
    """
    Checks whether the given integer n is a prime number.

    Parameters:
    n (int): the integer to check, should be >= 2

    Returns:
    bool: True if n is a prime number, False otherwise
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

