from typing import List

def count_paths(grid: List[List[str]]) -> int:
    """
    Returns the number of unique paths from the top-left to the bottom-right corner of the grid.
    """
    if not grid or grid[0][0] == '#' or grid[-1][-1] == '#':
        return 0

    M, N = len(grid), len(grid[0])
    dp = [[0] * N for _ in range(M)]

    dp[0][0] = 1  # Start at the top-left corner

    for r in range(M):
        for c in range(N):
            if grid[r][c] == '#':
                dp[r][c] = 0
            else:
                if r > 0:
                    dp[r][c] += dp[r-1][c]
                if c > 0:
                    dp[r][c] += dp[r][c-1]

    return dp[-1][-1]

