def is_path(graph, start, end):
    """
    Checks if there is a path from start to end in the given graph.
    Uses Depth-First Search (DFS) to explore the path.
    """
    def dfs(node, visited):
        if node == end:
            return True
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                if dfs(neighbor, visited):
                    return True
        return False

    return dfs(start, set())

