def max_non_consecutive_sum(n, arr):
    """
    Returns the maximum sum of a non-consecutive subsequence in the array.
    """
    if n == 0:
        return 0
    if n == 1:
        return max(0, arr[0])

    dp = [0] * n
    dp[0] = max(0, arr[0])

    for i in range(1, n):
        dp[i] = max(dp[i-1], arr[i] + (dp[i-2] if i > 1 else 0))

    return dp[-1]

