def count_peaks(altitudes):
    """
    Returns the number of distinct peaks in the array.
    A peak is defined as a point that is strictly greater than its immediately adjacent elements.
    """
    if len(altitudes) < 3:
        return 0

    peaks_count = 0

    for i in range(1, len(altitudes) - 1):
        if altitudes[i] > altitudes[i - 1] and altitudes[i] > altitudes[i + 1]:
            peaks_count += 1

    return peaks_count

