import heapq

def shortest_path(num_cases, cases):
    results = []
    for case in cases:
        N, M, connections, S, D = case
        graph = [[] for _ in range(N + 1)]

        for u, v, w in connections:
            graph[u].append((v, w))
            graph[v].append((u, w))  # Because the subway connection is bidirectional

        # Dijkstra's algorithm to find the shortest path
        def dijkstra(start, end):
            min_heap = [(0, start)]
            dist = {i: float('inf') for i in range(1, N + 1)}
            dist[start] = 0

            while min_heap:
                current_dist, u = heapq.heappop(min_heap)

                if current_dist > dist[u]:
                    continue

                for v, weight in graph[u]:
                    distance = current_dist + weight
                    if distance < dist[v]:
                        dist[v] = distance
                        heapq.heappush(min_heap, (distance, v))

            return dist[end]

        shortest_time = dijkstra(S, D)
        results.append(shortest_time)

    return results

