def min_books_to_move(test_cases):
    results = []
    for n, heights in test_cases:
        # Find the longest non-decreasing subsequence
        lis = []
        for h in heights:
            pos = binary_search_lis(lis, h)
            if pos == len(lis):
                lis.append(h)
            else:
                lis[pos] = h
        results.append(n - len(lis))
    return results

# Helper function. Finds the position to replace in the LIS.
def binary_search_lis(lis, height):
    low, high = 0, len(lis)
    while low < high:
        mid = (low + high) // 2
        if lis[mid] <= height:
            low = mid + 1
        else:
            high = mid
    return low

