def deep_search(data, target):
    """
    Recursively searches through all levels of a nested dictionary or list to determine
    if the target value exists. Returns True if the value is found, False otherwise.
    """
    if isinstance(data, dict):
        for value in data.values():
            if deep_search(value, target):
                return True

    elif isinstance(data, list):
        for item in data:
            if deep_search(item, target):
                return True

    else:
        return data == target

    return False

