def swap_language_greeting(sentence):
    """
    Swaps the greeting in the sentence based on predefined greetings.

    If the sentence contains "Hello", change it to "Hi".
    If the sentence contains "Hola", change it to "Buenos días".
    If the sentence contains "Bonjour", change it to "Salut".

    :param sentence: String containing the input sentence
    :return: String with the swapped greeting
    """
    if "Hello" in sentence:
        return sentence.replace("Hello", "Hi")
    elif "Hola" in sentence:
        return sentence.replace("Hola", "Buenos días")
    elif "Bonjour" in sentence:
        return sentence.replace("Bonjour", "Salut")
    else:
        return sentence

def uniquePaths(grid):
    def is_in_bounds(x, y):
        return 0 <= x < len(grid) and 0 <= y < len(grid[0])

    def dfs(x, y):
        if not is_in_bounds(x, y) or grid[x][y] == 1:
            return 0
        if (x, y) == (len(grid) - 1, len(grid[0]) - 1):
            return 1

        if (x, y) in memo:
            return memo[(x, y)]

        grid[x][y] = 1
        paths = dfs(x + 1, y) + dfs(x - 1, y) + dfs(x, y + 1) + dfs(x, y - 1)
        grid[x][y] = 0
        memo[(x, y)] = paths
        return paths

    if grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    memo = {}
    return dfs(0, 0)

