def hq9plus_interpreter(program):
    """
    Interpret and execute the given HQ9+ program.

    Args:
    program (str): The HQ9+ program as a string.

    Returns:
    List of strings representing the output of the program.
    """
    def bottles_of_beer():
        lyrics = ""
        for i in range(99, 0, -1):
            lyrics += f"{i} bottles of beer on the wall, {i} bottles of beer.\n"
            if i == 1:
                lyrics += "Take one down and pass it around, no more bottles of beer on the wall.\n"
            else:
                lyrics += f"Take one down and pass it around, {i-1} bottles of beer on the wall.\n"
        lyrics += "No more bottles of beer on the wall, no more bottles of beer.\n"
        lyrics += "Go to the store and buy some more, 99 bottles of beer on the wall.\n"
        return lyrics

    output = []
    accumulator = 0

    for command in program:
        if command == 'H':
            output.append("Hello, World!")
        elif command == 'Q':
            output.append(program)
        elif command == '9':
            output.append(bottles_of_beer())
        elif command == '+':
            accumulator += 1

    return output

def max_profit(prices):
    if not prices or len(prices) < 2:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices[1:]:
        if price < min_price:
            min_price = price
        profit = price - min_price
        if profit > max_profit:
            max_profit = profit

    return max_profit

def process_test_cases(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        prices = test_cases[i][1]
        result = max_profit(prices)
        results.append(result)
    return results

def max_unique_users(events, k):
    """
    Returns the maximum number of unique users in any window of k consecutive events.

    :param events: List of tuples, where each tuple contains two elements: a user ID (string) and a timestamp (integer).
    :param k: Integer indicating the length of the window in the number of events.
    :return: Maximum number of unique users in any window of k consecutive events.
    """
    if k > len(events):
        return len(set(user for user, _ in events))

    user_count = {}
    unique_users = 0
    max_unique = 0

    for i in range(len(events)):
        user_id, _ = events[i]
        if user_id in user_count:
            user_count[user_id] += 1
        else:
            user_count[user_id] = 1
            unique_users += 1

        if i >= k:
            old_user_id, _ = events[i - k]
            user_count[old_user_id] -= 1
            if user_count[old_user_id] == 0:
                del user_count[old_user_id]
                unique_users -= 1

        if i >= k - 1:
            max_unique = max(max_unique, unique_users)

    return max_unique

