def replace_digits(s):
    """
    Replaces digits in the string with '*' for even numbers and '#' for odd numbers.

    Args:
    s (str): The input string containing digits.

    Returns:
    str: The modified string after replacing digits based on the rules.
    """
    # Mapping function for easy replacement
    def replace(char):
        if char in '02468':
            return '*'
        else:
            return '#'

    # Using list comprehension for efficient string transformation
    return ''.join(replace(char) for char in s)

def calculate_typing_score(typed_string: str) -> int:
    """
    This function calculates the typing score based on typed_text and intended_text.
    """
    typed_text, intended_text = typed_string.split('|')

    score = 0
    length = min(len(typed_text), len(intended_text))

    for i in range(length):
        if typed_text[i] == intended_text[i]:
            score += 5
        else:
            score -= 2

    return score

