def update_inventory(inventory, orders):
    """
    Returns the updated inventory after fulfilling as many orders as possible.
    """
    updated_inventory = []

    for i, stock in enumerate(inventory):
        if orders[i] >= stock:
            updated_inventory.append(0)
        else:
            updated_inventory.append(stock - orders[i])

    return updated_inventory

