def balance_check(s):
    """
    Check if the provided string s has balanced brackets.

    Args:
    s (str): The string containing brackets.

    Returns:
    bool: True if the brackets are balanced, False otherwise.
    """
    stack = []
    bracket_pair = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_pair.values():
            stack.append(char)
        elif char in bracket_pair.keys():
            if stack == [] or bracket_pair[char] != stack.pop():
                return False
        else:
            continue

    return stack == []

