def LongestCommonPrefix(strs):
    """
    Finds the longest common prefix string amongst an array of strings.
    If there is no common prefix, returns an empty string.
    """
    if not strs:
        return ""

    # Start with the shortest string as the candidate for the longest common prefix
    shortest_str = min(strs, key=len)

    for i, char in enumerate(shortest_str):
        for other in strs:
            if other[i] != char:
                return shortest_str[:i]

    return shortest_str

def track_parking_lot(events):
    """
    Tracks the entries and exits of cars in a parking lot and returns the number of distinct cars present.

    Parameters:
    events (List[Tuple[str, str]]): List of events where each event is a tuple (action, license_plate)

    Returns:
    int: Number of distinct cars currently present in the parking lot
    """
    parking_lot = set()

    for action, license_plate in events:
        if action == "enter":
            parking_lot.add(license_plate)
        elif action == "exit":
            parking_lot.discard(license_plate)

    return len(parking_lot)

