def find_palindromic_substrings(s):
    """
    Counts and returns the number of distinct palindromic substrings in the given string s.
    """
    palindromes = set()

    def expand_from_center(left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            palindromes.add(s[left:right+1])
            left -= 1
            right += 1

    for i in range(len(s)):
        expand_from_center(i, i)  # Odd length palindromes
        expand_from_center(i, i + 1)  # Even length palindromes

    return len(palindromes)

