def reverseValidArray(arr):
    """
    Returns a new array where each integer is reversed.
    """
    if not isinstance(arr, list):
        return 'Invalid input'

    reversed_array = []
    for element in arr:
        if not isinstance(element, int):
            return 'Invalid element'
        reversed_element = int(str(element)[::-1]) if element >= 0 else -int(str(-element)[::-1])
        reversed_array.append(reversed_element)

    return reversed_array

