def fibonacci(n):
    """
    Returns the first n elements of the Fibonacci sequence.
    """
    if n <= 0:
        return []
    sequence = [0, 1]
    while len(sequence) < n:
        sequence.append(sequence[-1] + sequence[-2])
    return sequence[:n]

