def max_profit(prices):
    if not prices:
        return 0

    n = len(prices)
    hold, sold, reset = float('-inf'), 0, 0

    for price in prices:
        pre_sold = sold
        sold = hold + price
        hold = max(hold, reset - price)
        reset = max(reset, pre_sold)

    return max(sold, reset)

