def next_lexicographic_permutation(s: str) -> str:
    """
    This function returns the next lexicographic permutation of the input string.
    If no higher permutation exists, it returns the string sorted in ascending order.
    """
    s = list(s)
    i = len(s) - 2
    # Find the rightmost character which is smaller than its next character
    while i >= 0 and s[i] >= s[i + 1]:
        i -= 1

    # If no such character is found, that means the string is sorted in descending order
    if i == -1:
        return "".join(sorted(s))

    # Find the smallest character on right side of (i) which is greater than s[i]
    for j in range(len(s) - 1, i, -1):
        if s[j] > s[i]:
            # Swap the found character with character at i
            s[i], s[j] = s[j], s[i]
            break

    # Reverse the characters after the (i-th) index
    s = s[:i + 1] + s[i + 1:][::-1]
    return "".join(s)

