def find_duplicates(numbers):
    """
    Returns a list of all the integers that appear more than once in the input list.
    The integers in the output list should be in the order that they first appeared in the input list.
    """
    seen = set()
    duplicates = set()
    result = []

    for number in numbers:
        if number in seen:
            if number not in duplicates:
                result.append(number)
                duplicates.add(number)
        else:
            seen.add(number)

    return result

