def rotateMatrix(matrix):
    """
    Rotates a square matrix 90 degrees clockwise.
    """
    n = len(matrix)
    result = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            result[j][n - i - 1] = matrix[i][j]

    return result

def is_prime(n):
    """
    Checks if a number n is a prime number.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def filter_primes(numbers):
    """
    Returns a list of prime numbers from the given list of integers.
    """
    return [num for num in numbers if is_prime(num)]

