def aggregateObject(objs):
    """
    Aggregates multiple objects into a single object. If a property key appears in more than one object,
    the values of those keys will be concatenated into an array.
    Params:
        - objs (List[Dict]): A list of objects to be aggregated.
    Returns:
        - Dict: The aggregated object.
    """
    result = {}
    for obj in objs:
        for key, value in obj.items():
            if key in result:
                if isinstance(value, list):
                    result[key].extend(value)
                else:
                    result[key].append(value)
            else:
                if isinstance(value, list):
                    result[key] = value[:]
                else:
                    result[key] = [value]
    return result

