from typing import List

def is_prime(n: int) -> bool:
    """
    Returns True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def untangle_list(arr: List[int]) -> List[int]:
    """
    Returns a new array containing the prime numbers from the input array followed by
    the non-prime numbers, both groups sorted in ascending order.
    """
    primes = []
    non_primes = []

    for num in arr:
        if is_prime(num):
            primes.append(num)
        else:
            non_primes.append(num)

    primes.sort()
    non_primes.sort()

    return primes + non_primes

