def longest_equal_subarray(arr):
    """
    Returns the length of the longest subarray with all elements equal in the given array.
    """
    if not arr:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(arr)):
        if arr[i] == arr[i - 1]:
            current_len += 1
        else:
            current_len = 1

        if current_len > max_len:
            max_len = current_len

    return max_len

