def min_operations_to_heads(n, coins):
    """
    Function to calculate minimum number of operations to make all coins show heads (H).
    """
    coins = list(coins)
    operations = 0

    for i in range(n):
        if coins[i] == 'T':
            operations += 1
            # Flip all coins from i-th position to the end
            for j in range(i, n):
                coins[j] = 'H' if coins[j] == 'T' else 'T'

    return operations

def process_cases(t, cases):
    results = []
    for i in range(t):
        n, coins = cases[i]
        results.append(min_operations_to_heads(n, coins))
    return results

