def find_pairs(lst, target):
    """
    Returns a list of pairs from the input list that add up to the target integer.
    Each pair is in ascending order, and the final list is sorted.
    Returns 'Invalid input!' if the input is not a list of integers or if the target is not an integer.
    """
    if not isinstance(lst, list) or not isinstance(target, int) or not all(isinstance(x, int) for x in lst):
        return 'Invalid input!'

    seen = set()
    pairs = set()

    for number in lst:
        complement = target - number
        if complement in seen:
            pairs.add(tuple(sorted((number, complement))))
        seen.add(number)

    return sorted([list(pair) for pair in pairs])

