def compress_string(s):
    """
    Returns the run-length encoding of the input string.
    """
    if not s:
        return s

    result = []
    i = 0
    length = len(s)

    while i < length:
        count = 1
        while (i + 1) < length and s[i] == s[i + 1]:
            count += 1
            i += 1
        if count > 1:
            result.append(s[i] + str(count))
        else:
            result.append(s[i])
        i += 1

    return ''.join(result)

