def max_subarray_product(yield_list):
    def max_product_of_subarray(subarray):
        max_prod = float('-inf')
        n = len(subarray)
        for i in range(n):
            current_prod = 1
            for j in range(n):
                current_prod *= subarray[(i + j) % n]
            max_prod = max(max_prod, current_prod)
        return max_prod

    n = len(yield_list)
    max_product = float('-inf')

    for start in range(n):
        for end in range(start + 1, n + 1):
            subarray = yield_list[start:end]
            max_product = max(max_product, max_product_of_subarray(subarray))

    return max_product

