import math

def findNextPerfectSquare(n):
    """
    Returns the next perfect square if n is a perfect square, otherwise returns -1.
    """
    if n < 0:
        return -1
    root = int(math.sqrt(n))
    if root * root == n:
        return (root + 1) * (root + 1)
    else:
        return -1

