def best_selling_book(n, sales):
    from collections import defaultdict

    sales_dict = defaultdict(int)

    for title, copies in sales:
        sales_dict[title] += copies

    max_sales = max(sales_dict.values())

    best_sellers = [title for title, copies in sales_dict.items() if copies == max_sales]

    return min(best_sellers)

