from collections import deque
from typing import List

def walls_and_gates(matrix: List[List[int]]) -> List[List[int]]:
    if not matrix or not matrix[0]:
        return matrix

    INF = 2**31 - 1
    m, n = len(matrix), len(matrix[0])
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    queue = deque()

    # Add all gates to the queue first
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 0:
                queue.append((i, j))

    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            new_x, new_y = x + dx, y + dy
            if 0 <= new_x < m and 0 <= new_y < n and matrix[new_x][new_y] == INF:
                matrix[new_x][new_y] = matrix[x][y] + 1
                queue.append((new_x, new_y))

    return matrix

