def factorial(n):
    """
    Returns the factorial of a given non-negative integer n.
    If n is 0, returns 1 as 0! is defined as 1.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

