def find_dominant(lst):
    """
    Returns the dominant integer from the list if it exists, otherwise returns None.
    A dominant integer is an integer that appears more than half the size of the list.
    """
    threshold = len(lst) // 2
    count_dict = {}

    for num in lst:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

        if count_dict[num] > threshold:
            return num

    return None

