def check_possibility(nums):
    """
    Determine if the array could become non-decreasing by modifying at most one element.

    :param nums: List[int] - The input array of integers.
    :return: bool - True if the array could become non-decreasing, False otherwise.
    """
    count = 0  # To keep track of the modifications
    for i in range(1, len(nums)):
        if nums[i] < nums[i - 1]:
            if count == 1:
                return False  # More than one modification required
            count += 1

            # Determine whether to fix nums[i-1] or nums[i]
            if i == 1 or nums[i] >= nums[i - 2]:
                nums[i - 1] = nums[i]
            else:
                nums[i] = nums[i - 1]

    return True

