def min_fuel_needed(grid, N, M):
    """
    Returns the minimum fuel needed to reach the bottom-right corner of the grid.
    If it's impossible, returns -1.
    """
    dp = [[float('inf')] * M for _ in range(N)]
    dp[0][0] = grid[0][0]

    for i in range(N):
        for j in range(M):
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + grid[i][j])

    return dp[N-1][M-1]

def driving_simulation(N, M, F, grid):
    min_needed_fuel = min_fuel_needed(grid, N, M)
    if min_needed_fuel <= F:
        return min_needed_fuel
    else:
        return "Impossible"

