def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced substring.
    """
    max_length = 0
    stack = [-1]  # Initialize stack with a base index

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if stack:
                max_length = max(max_length, i - stack[-1])
            else:
                stack.append(i)

    return max_length

