from typing import List, Tuple, Dict
from collections import defaultdict, deque

def calculateHeight(edges: List[Tuple[int, int]], root: int) -> int:
    # Create an adjacency list for the tree
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    # Breadth-first search (BFS) to calculate the height
    def bfs_height(root: int) -> int:
        visited = set()
        queue = deque([(root, 0)])  # (node, current_height)
        max_height = 0

        while queue:
            node, height = queue.popleft()
            if node not in visited:
                visited.add(node)
                max_height = max(height, max_height)
                for neighbor in tree[node]:
                    if neighbor not in visited:
                        queue.append((neighbor, height + 1))

        return max_height

    return bfs_height(root)

