def min_edit_distance(str1, str2):
    """
    Returns the minimum number of edits (insertions, deletions, or substitutions)
    required to transform str1 into str2.
    """
    m = len(str1)
    n = len(str2)

    # Create a dp table to store results of subproblems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp[][] in a bottom up manner
    for i in range(m + 1):
        for j in range(n + 1):

            if i == 0:
                dp[i][j] = j    # If str1 is empty, insert all characters of str2

            elif j == 0:
                dp[i][j] = i    # If str2 is empty, remove all characters of str1

            elif str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]

            else:
                dp[i][j] = 1 + min(dp[i][j - 1],    # Insert
                                   dp[i - 1][j],    # Remove
                                   dp[i - 1][j - 1])# Replace

    return dp[m][n]

