def count_distinct_increasing_subsequences(seq):
    from itertools import combinations

    def is_increasing(subseq):
        return all(x < y for x, y in zip(subseq, subseq[1:]))

    n = len(seq)
    all_subsequences = set()

    for i in range(1, n + 1):
        for subseq in combinations(seq, i):
            if is_increasing(subseq):
                all_subsequences.add(subseq)

    return len(all_subsequences)

