from typing import List

def num_islands(grid: List[List[str]]) -> int:
    def dfs(grid, i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == "0":
            return
        grid[i][j] = "0"  # Mark the land as visited by sinking it to water
        dfs(grid, i + 1, j)
        dfs(grid, i - 1, j)
        dfs(grid, i, j + 1)
        dfs(grid, i, j - 1)

    if not grid or not grid[0]:
        return 0

    num_islands = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == "1":
                num_islands += 1
                dfs(grid, i, j)
    return num_islands

from collections import deque, defaultdict

def min_number_of_semesters(n, m, prerequisites):
    # Build the graph
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for a, b in prerequisites:
        graph[a].append(b)
        in_degree[b] += 1

    # Start with all courses that have no prerequisites
    queue = deque()
    for course in range(1, n + 1):
        if in_degree[course] == 0:
            queue.append(course)

    semesters = 0
    completed_courses = 0

    # Topological sort using BFS
    while queue:
        semesters += 1
        for _ in range(len(queue)):  # Process all nodes at the current level (i.e., in the current semester)
            course = queue.popleft()
            completed_courses += 1
            for next_course in graph[course]:
                in_degree[next_course] -= 1
                if in_degree[next_course] == 0:
                    queue.append(next_course)

    if completed_courses == n:
        return semesters
    else:
        return -1

def merge_sentences(sentences):
    """
    Joins a list of sentences into a single paragraph ensuring proper grammar rules.
    """
    if not sentences:
        return ""

    merged_sentences = []

    for i, sentence in enumerate(sentences):
        sentence = sentence.strip()
        if not sentence:
            continue

        if i == 0:
            sentence = sentence.capitalize()
        else:
            sentence = sentence[0].upper() + sentence[1:]

        if sentence[-1] not in '.!?':
            sentence += '.'

        merged_sentences.append(sentence)

    return ' '.join(merged_sentences)

