def search(nums, target):
    """
    Searches for the target value in a rotated sorted array.

    :param nums: List[int], the rotated sorted array
    :param target: int, the value to search for
    :return: int, the index of the target value if found, otherwise -1
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        if nums[left] <= nums[mid]:  # Left part is sorted
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # Right part is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

