from itertools import combinations

def find_overlapping_employees(schedules):
    def is_overlap(t1, t2):
        """
        Helper function to check if two time periods overlap
        """
        return max(t1[0], t2[0]) < min(t1[1], t2[1])

    overlapping_pairs = set()

    # Generate all pairs of employees
    for emp1, emp2 in combinations(schedules.keys(), 2):
        for day in schedules[emp1]:
            if is_overlap(schedules[emp1][day], schedules[emp2][day]):
                # Add tuple in sorted order to ensure alphabetical order of names
                overlapping_pairs.add(tuple(sorted((emp1, emp2))))
                break

    return list(overlapping_pairs)

