def find_longest_slowdown_sequences(T, test_cases):
    results = []
    for i in range(T):
        N, L = test_cases[i][0]
        response_times = test_cases[i][1]

        max_length = 0
        current_length = 0

        for response in response_times:
            if response >= L:
                current_length += 1
                if current_length > max_length:
                    max_length = current_length
            else:
                current_length = 0

        results.append(max_length)

    return results

