def NestedArraySum(nested_array):
    """
    Returns the sum of all integers in a nested array.
    """
    total_sum = 0

    def sum_helper(array):
        nonlocal total_sum
        for element in array:
            if isinstance(element, list):
                sum_helper(element)
            else:
                total_sum += element

    sum_helper(nested_array)
    return total_sum

