def robot_path_possible(t, test_cases):
    def is_path_possible(grid, m, n):
        if grid[0][0] == 'R' or grid[m-1][n-1] == 'R':
            return False
        dp = [[0]*n for _ in range(m)]
        dp[0][0] = 1
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'R':
                    dp[i][j] = 0
                else:
                    if i > 0:
                        dp[i][j] += dp[i-1][j]
                    if j > 0:
                        dp[i][j] += dp[i][j-1]
        return dp[m-1][n-1] != 0

    results = []
    for case in test_cases:
        m, n, grid = case
        results.append("YES" if is_path_possible(grid, m, n) else "NO")
    return results

