def min_moves_to_collect_treasures(N, a):
    """
    Returns the minimum number of moves required to collect all the treasures on the map.
    """
    moves = 0
    i = 0
    while i < N:
        if a[i] > 0:
            moves += 1
            while i < N and a[i] > 0:
                i += 1
        else:
            i += 1
    return moves

