from collections import defaultdict
from typing import List, Tuple

def can_form_straight_flush(deck: List[Tuple[int, str]]) -> str:
    # Organize cards by suit
    suits = defaultdict(list)
    for value, suit in deck:
        suits[suit].append(value)

    # Check each suit for possible straight flush
    for cards in suits.values():
        cards.sort()
        if has_straight(cards):
            return "Straight Flush Found!"
    return "No Straight Flush"

def has_straight(cards: List[int]) -> bool:
    n = len(cards)
    for i in range(n - 4):
        if cards[i + 4] - cards[i] == 4:
            return True
    return False

