def first_missing_positive(nums):
    """
    Returns the smallest positive integer that does not appear in the array.
    """
    n = len(nums)

    # Place each number in its right place
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            # Swap the numbers to their correct positions
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    # Identify the first missing positive number
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

