def process_hotel_operations(T, operations):
    occupied_rooms = set()
    result = []

    for operation in operations:
        op, room = operation.split()
        room = int(room)

        if op == "check-in":
            if room not in occupied_rooms:
                occupied_rooms.add(room)
        elif op == "check-out":
            if room in occupied_rooms:
                occupied_rooms.remove(room)

    result = sorted(occupied_rooms)
    return result

