def find_min_cameras(n, m, edges):
    from collections import defaultdict

    # Helper function for finding a vertex cover of the graph
    def find_vertex_cover(n, edges):
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        # Initialize all vertices as not visited
        visited = [False] * (n + 1)
        vertex_cover = []

        # Consider each edge
        for u, v in edges:
            if not visited[u] and not visited[v]:
                visited[u] = True
                visited[v] = True
                vertex_cover.append(u)
                vertex_cover.append(v)

        return len(vertex_cover) // 2

    return find_vertex_cover(n, edges)

def has_cycle(graph):
    def dfs(node, parent, visited):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, node, visited):
                    return True
            elif parent is not None and neighbor != parent:
                return True
        return False

    visited = set()
    for node in graph:
        if node not in visited:
            if dfs(node, None, visited):
                return True
    return False

