def balanced_parentheses(s):
    """
    Checks if the parentheses in the input string are balanced.
    """
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0

