def analyze_migration_pattern(c):
    if not c or not c[0]:
        return "no specific pattern"

    steady = True
    rise = True
    fall = True

    for day in c:
        for i in range(1, len(day)):
            if day[i] != day[i-1]:
                steady = False
            if day[i] <= day[i-1]:
                rise = False
            if day[i] >= day[i-1]:
                fall = False

    if steady:
        return "steady"
    if rise:
        return "rise"
    if fall:
        return "fall"

    return "no specific pattern"

def search(nums, target):
    """
    Searches for target in a rotated sorted array nums.
    Returns the index of target if found, otherwise -1.
    """
    if not nums:
        return -1

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        # Check the left portion
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Check the right portion
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

def is_valid_potion_composition(T, compositions):
    results = []
    for composition in compositions:
        char_count = {}
        for char in composition:
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1

        is_valid = all(count % 2 == 0 for count in char_count.values())

        if is_valid:
            results.append("YES")
        else:
            results.append("NO")

    return results

