from typing import List

def min_cost_to_climb(cost: List[int]) -> int:
    n = len(cost)
    if n == 0:
        return 0
    elif n == 1:
        return cost[0]

    dp = [0] * n
    dp[0] = cost[0]
    dp[1] = cost[1]

    for i in range(2, n):
        dp[i] = cost[i] + min(dp[i-1], dp[i-2])

    return min(dp[-1], dp[-2])

