def most_frequent_character(s):
    """
    Returns the most frequently occurring character in the string `s`.
    If there are multiple characters with the same highest frequency,
    returns the one that appears first in the string.
    Returns None if the input string is empty.
    """
    if not s:
        return None

    frequency = {}
    max_count = 0
    most_frequent_char = None

    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

        if frequency[char] > max_count:
            max_count = frequency[char]
            most_frequent_char = char

    return most_frequent_char

