def generate_unique_permutations(nums):
    def backtrack(start=0):
        if start == len(nums) - 1:
            permutations.add(tuple(nums[:]))
            return

        for i in range(start, len(nums)):
            nums[start], nums[i] = nums[i], nums[start]
            backtrack(start + 1)
            nums[start], nums[i] = nums[i], nums[start]

    permutations = set()
    backtrack()
    return [list(p) for p in permutations]

