def book_sales(inventory, sales):
    total_revenue = 0
    isbn_to_book = {book['ISBN']: book for book in inventory}

    for sale in sales:
        isbn = sale['ISBN']
        quantity = sale['quantity']

        if isbn in isbn_to_book:
            book = isbn_to_book[isbn]
            available_copies = book['copies']
            copies_to_sell = min(quantity, available_copies)
            total_revenue += copies_to_sell * book['price']
            book['copies'] -= copies_to_sell

    return total_revenue

