def min_repeats(a: str, b: str) -> int:
    # Function to check if b is a subsequence of s
    def is_subsequence(s, b):
        b_idx = 0
        for char in s:
            if b_idx < len(b) and char == b[b_idx]:
                b_idx += 1
            if b_idx == len(b):
                return True
        return b_idx == len(b)

    # Lengths of the strings
    len_a = len(a)
    len_b = len(b)

    # Maximum number of repetitions needed to cover the length of b
    max_repeats = (len_b + len_a - 1) // len_a + 1  # one extra to handle boundaries

    # Check with increasing repetitions of a
    for repeats in range(1, max_repeats + 1):
        if is_subsequence(a * repeats, b):
            return repeats

    return -1

