def numClosedIslands(grid):
    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n:
            return False
        if grid[x][y] == 1:
            return True

        grid[x][y] = 1  # mark as visited

        up = dfs(x - 1, y)
        down = dfs(x + 1, y)
        left = dfs(x, y - 1)
        right = dfs(x, y + 1)

        return up and down and left and right

    if not grid:
        return 0

    m, n = len(grid), len(grid[0])
    closed_islands = 0

    for i in range(1, m - 1):
        for j in range(1, n - 1):
            if grid[i][j] == 0:
                if dfs(i, j):
                    closed_islands += 1

    return closed_islands

def process_commands(commands):
    """
    Processes a list of commands to manipulate a list of integers.

    Args:
    commands (list of str): List of commands to process.

    Returns:
    list of int: Output response for each 'PrintMax' command.
    """
    numbers = []
    result = []

    for command in commands:
        parts = command.split()
        if parts[0] == 'Insert':
            num = int(parts[1])
            numbers.append(num)
        elif parts[0] == 'Delete':
            num = int(parts[1])
            if num in numbers:
                numbers.remove(num)
        elif parts[0] == 'PrintMax':
            if numbers:
                result.append(max(numbers))

    return result

