def max_temperature_difference(temperatures):
    """
    Finds the maximum difference between two temperatures such that the second temperature occurs after the first one.
    Returns 0 if no such pair exists.
    """
    if len(temperatures) < 2:
        return 0

    max_diff = 0
    min_temp = temperatures[0]

    for temp in temperatures[1:]:
        if temp - min_temp > max_diff:
            max_diff = temp - min_temp
        if temp < min_temp:
            min_temp = temp

    return max_diff

