def evaluate_rpn(expression: list) -> int:
    """
    Evaluate the value of an arithmetic expression in Reverse Polish Notation.
    Valid operators are +, -, *, and /. Each operand may be an integer or another expression.
    Division should truncate towards zero.
    If the input is invalid, raise a ValueError with the message "Invalid RPN expression".
    """
    stack = []

    for token in expression:
        if token.lstrip('-').isdigit():  # This will cover negative numbers as well
            stack.append(int(token))
        else:
            if len(stack) < 2:
                raise ValueError("Invalid RPN expression")

            b = stack.pop()
            a = stack.pop()

            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))  # Ensure division truncates towards zero
            else:
                raise ValueError("Invalid RPN expression")

    if len(stack) != 1:
        raise ValueError("Invalid RPN expression")

    return stack[0]

