def process_commands(command_string: str) -> str:
    parts = command_string.split(":")
    header = parts[0]
    footer = parts[-1]

    if header != "BEGIN" or footer != "END":
        return "BEGIN:ERROR_INVALID_FORMAT:END"

    accumulator = 0

    for part in parts[1:-1]:
        operation = part[:3]
        value = int(part[3:])

        if operation == "ADD":
            accumulator += value
        elif operation == "SUB":
            accumulator -= value
        elif operation == "MUL":
            accumulator *= value
        elif operation == "DIV":
            if value == 0:
                return "BEGIN:ERROR_DIV_BY_ZERO:END"
            accumulator //= value
        else:
            return "BEGIN:ERROR_INVALID_OPERATION:END"

    accumulator = max(accumulator, 0)
    return f"{header}:RESULT{accumulator}:{footer}"

