from typing import List

def determine_grade(scores: List[float]) -> str:
    """
    Determines the letter grade for a student based on the average of the given scores.

    Parameters:
    scores (List[float]): A list of floating-point numbers representing the percentages of scores

    Returns:
    str: The letter grade based on the average score
    """
    if not scores:
        raise ValueError("The list of scores cannot be empty.")

    average_score = sum(scores) / len(scores)

    if average_score >= 90:
        return 'A'
    elif average_score >= 80:
        return 'B'
    elif average_score >= 70:
        return 'C'
    elif average_score >= 60:
        return 'D'
    else:
        return 'F'

def find_pair_with_sum(lst, target):
    """
    Returns a pair of integers from the list that sum up to the target value, or None if no such pair exists.
    """
    seen = set()
    for num in lst:
        complement = target - num
        if complement in seen:
            return (complement, num)
        seen.add(num)
    return None

