def final_coordinates(test_cases):
    results = []

    for case in test_cases:
        M, steps = case
        x, y = 0, 0

        for step in steps:
            if step == 'N':
                y += 1
            elif step == 'S':
                y -= 1
            elif step == 'E':
                x += 1
            elif step == 'W':
                x -= 1

        results.append((x, y))

    return results

