def calculate_ascii_score(user_id):
    """
    Calculate the ASCII score of a user ID by summing ASCII values of all characters.
    """
    return sum(ord(char) for char in user_id)

def find_highest_score_user(ids):
    """
    Given a list of user IDs, find the one(s) with the highest ASCII value score.
    """
    if not ids:
        return []

    highest_score = float('-inf')
    highest_scoring_ids = []

    for user_id in ids:
        score = calculate_ascii_score(user_id)
        if score > highest_score:
            highest_score = score
            highest_scoring_ids = [user_id]
        elif score == highest_score:
            highest_scoring_ids.append(user_id)

    return highest_scoring_ids

from typing import List

def adjust_list(numbers: List[int]) -> List[int]:
    """
    Adjust the list of numbers according to specific rules.
    """
    for i in range(len(numbers)):
        if i % 2 == 0:  # Even index
            if numbers[i] % 2 == 0:
                numbers[i] += 1
            else:
                numbers[i] -= 1
        else:  # Odd index
            if numbers[i] % 2 == 0:
                numbers[i] += 2
            else:
                numbers[i] -= 2
    return numbers

