def does_route_return_to_start(routes):
    """
    Determines if the given routes form a closed loop returning to the start.

    Parameters:
    routes (list of str): A list of strings representing the routes taken by scouts.

    Returns:
    list of str: A list of "Yes" or "No" indicating if each route forms a closed loop.
    """
    results = []
    for route in routes:
        x, y = 0, 0
        for move in route:
            if move == 'N':
                y += 1
            elif move == 'S':
                y -= 1
            elif move == 'E':
                x += 1
            elif move == 'W':
                x -= 1
        if x == 0 and y == 0:
            results.append("Yes")
        else:
            results.append("No")
    return results

