def length_of_lis(arr):
    """
    Returns the length of longest increasing subsequence in the given array.
    """
    if not arr:
        return 0

    # Create an array to store our subsequence
    lis = []

    for num in arr:
        # Use binary search to find the insertion point of the num in lis
        left, right = 0, len(lis)
        while left < right:
            mid = (left + right) // 2
            if lis[mid] < num:
                left = mid + 1
            else:
                right = mid
        if left == len(lis):
            lis.append(num)
        else:
            lis[left] = num

    return len(lis)

def process_library_cases(cases):
    """
    Processes multiple test cases and returns a list with the length of longest
    increasing subsequence for each case.
    """
    results = []
    for case in cases:
        N, books = case
        results.append(length_of_lis(books))
    return results

