def product_of_primes(M):
    """ Returns the product of all prime numbers less than or equal to M """
    if M < 2:
        return 1

    sieve = [True] * (M + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not prime
    for start in range(2, int(M**0.5) + 1):
        if sieve[start]:
            for multiple in range(start * start, M + 1, start):
                sieve[multiple] = False

    primes = [num for num, is_prime in enumerate(sieve) if is_prime]
    product = 1
    for prime in primes:
        product *= prime
    return product

def process_test_cases(test_cases):
    results = []
    for M in test_cases:
        results.append(product_of_primes(M))
    return results

from collections import Counter
from math import factorial

def rearrange_count(s):
    counter = Counter(s)
    a, b, c = counter['a'], counter['b'], counter['c']

    if max(a, b, c) > (len(s) + 1) // 2:
        return 0

    num_permutations = factorial(len(s))
    for count in counter.values():
        num_permutations //= factorial(count)

    return num_permutations

def number_of_valid_rearrangements(test_cases):
    results = []
    for s in test_cases:
        results.append(rearrange_count(s))
    return results

