def max_product_of_two(arr):
    """
    Returns the maximum product of any two distinct numbers in the array.
    """
    if len(arr) < 2:
        return None

    arr.sort(reverse=True)

    max1 = arr[0] * arr[1]  # Product of the two largest numbers
    max2 = arr[-1] * arr[-2]  # Product of the two smallest numbers (which could be negative)

    return max(max1, max2)

