def minDistance(word1, word2):
    """
    Returns the minimum number of operations required to convert word1 to word2.
    The allowed operations are insertion, deletion, and substitution of a single character.
    """
    m, n = len(word1), len(word2)

    # Initialize the dp table with size (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the base cases where one of the words is empty
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i-1] == word2[j-1]:
                dp[i][j] = dp[i-1][j-1]  # No operation required
            else:
                dp[i][j] = min(dp[i-1][j] + 1, dp[i][j-1] + 1, dp[i-1][j-1] + 1)  # Insert, Delete, or Substitute

    return dp[m][n]

