import math
from collections import defaultdict, deque

def is_perfect_square(x):
    return int(math.isqrt(x)) ** 2 == x

def sum_of_sizes_of_connected_components(n, toy_ids):
    def bfs(node):
        queue = deque([node])
        visited[node] = True
        size = 0
        while queue:
            current = queue.popleft()
            size += 1
            for neighbor in graph[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return size

    graph = defaultdict(list)
    toy_ids = sorted(toy_ids)

    for i in range(n):
        for j in range(i + 1, n):
            if is_perfect_square(abs(toy_ids[j] - toy_ids[i])):
                graph[toy_ids[i]].append(toy_ids[j])
                graph[toy_ids[j]].append(toy_ids[i])

    visited = {toy_id: False for toy_id in toy_ids}
    total_size = 0

    for toy_id in toy_ids:
        if not visited[toy_id]:
            total_size += bfs(toy_id)

    return total_size

