def spiral_matrix(m, n, arr):
    if m < 1 or n < 1 or len(arr) != m * n:
        return ""

    matrix = [[0] * n for _ in range(m)]
    top, bottom, left, right = 0, m-1, 0, n-1
    index = 0

    while index < len(arr):
        for i in range(left, right+1):
            if index < len(arr):
                matrix[top][i] = arr[index]
                index += 1
        top += 1

        for i in range(top, bottom+1):
            if index < len(arr):
                matrix[i][right] = arr[index]
                index += 1
        right -= 1

        for i in range(right, left-1, -1):
            if index < len(arr):
                matrix[bottom][i] = arr[index]
                index += 1
        bottom -= 1

        for i in range(bottom, top-1, -1):
            if index < len(arr):
                matrix[i][left] = arr[index]
                index += 1
        left += 1

    return '\n'.join([' '.join(map(str, row)) for row in matrix])

def lastIndexOf(text, substring):
    """
    Returns the last index at which the substring is found in the text.
    If the substring is not found, returns -1.
    If the substring is empty, returns the length of the text.
    """
    if substring == "":
        return len(text)
    return text.rfind(substring)

