def moves(sequence):
    """
    Determines whether a given sequence of moves causes the robot to return to the origin.

    Args:
    sequence (str): Sequence of moves consisting of characters 'U', 'D', 'L', 'R'.

    Returns:
    bool: True if the moves bring the robot back to the origin, False otherwise.
    """
    x, y = 0, 0
    for move in sequence:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
    return x == 0 and y == 0

