def evaluate_expression(expression: str) -> int:
    """
    Evaluate the given mathematical expression string containing
    positive integers and the operators '+', '-', '*', '/'.
    """
    def apply_operation(operands, operator):
        b = operands.pop()
        a = operands.pop()
        if operator == '+':
            operands.append(a + b)
        elif operator == '-':
            operands.append(a - b)
        elif operator == '*':
            operands.append(a * b)
        elif operator == '/':
            operands.append(a // b)

    import re
    tokens = re.findall(r'\d+|[+*/-]', expression)
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    operands = []
    operators = []

    for token in tokens:
        if token.isdigit():
            operands.append(int(token))
        else:
            while operators and precedence[operators[-1]] >= precedence[token]:
                apply_operation(operands, operators.pop())
            operators.append(token)

    while operators:
        apply_operation(operands, operators.pop())

    return operands[0]

