import itertools

def is_palindrome(s):
    cleaned = ''.join(filter(str.isalnum, s)).lower()
    return cleaned == cleaned[::-1]

def palindrome_permutations(S):
    permutations = set(itertools.permutations(S))
    palindrome_perms = ["".join(p) for p in permutations if is_palindrome("".join(p))]

    if not palindrome_perms:
        print("-1")
    else:
        for perm in palindrome_perms:
            print(perm)

