def evaluate_expression(expression):
    """
    Evaluates a simple mathematical expression string consisting of positive integers
    and the operators +, -, *, and /. Operator precedence is respected.
    """
    import re

    # Split expression into tokens of numbers and operators
    tokens = re.findall(r'\d+|\+|\-|\*|\/', expression)

    # Lists to hold numbers and operators separately
    values = []
    operators = []

    def apply_operator(operators, values):
        rhs = values.pop()
        lhs = values.pop()
        op = operators.pop()
        if op == '+':
            values.append(lhs + rhs)
        elif op == '-':
            values.append(lhs - rhs)
        elif op == '*':
            values.append(lhs * rhs)
        elif op == '/':
            values.append(lhs / rhs)

    # Precedences for operators
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    for token in tokens:
        if token.isdigit():
            # Push number to values stack
            values.append(float(token))
        else:
            # Token is an operator
            while (operators and precedence[operators[-1]] >= precedence[token]):
                apply_operator(operators, values)
            operators.append(token)

    # Apply remaining operators
    while operators:
        apply_operator(operators, values)

    # The final value on the values stack is the result
    return values[0]

