def maximum_robbery(T, test_cases):
    def rob_house(houses):
        n = len(houses)
        if n == 0:
            return 0
        if n == 1:
            return houses[0]

        dp = [0] * n
        dp[0] = houses[0]
        dp[1] = max(houses[0], houses[1])

        for i in range(2, n):
            dp[i] = max(dp[i-1], houses[i] + dp[i-2])

        return dp[-1]

    results = []
    for i in range(T):
        N, houses = test_cases[i]
        results.append(rob_house(houses))
    return results

