def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.
    """
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def filter_primes(arr):
    """
    Returns a list containing only the prime numbers in the given array.
    """
    return [x for x in arr if is_prime(x)]

