from typing import List

def minimal_cut_to_alternate_heights(heights: List[int]) -> int:
    n = len(heights)
    if n <= 1:
        return 0

    cuts = 0
    for i in range(1, n):
        if heights[i] == heights[i - 1]:
            # A tree must be cut so that the current one is different from the previous one
            cuts += 1
            heights[i] -= 1  # Cut the current tree by 1

    return cuts

