def count_ways_to_reach_end(grid, n, m):
    # Initialize DP table to hold number of ways to get to each cell
    dp = [[0 for _ in range(m)] for _ in range(n)]

    # Start is always accessible
    dp[0][0] = 1

    # Populate dp table
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    # The bottom-right corner will have the number of ways to get to (n, m)
    return dp[n-1][m-1]

def process_test_cases(T, test_cases):
    results = []
    for test_case in test_cases:
        n, m, grid = test_case
        result = count_ways_to_reach_end(grid, n, m)
        results.append(result)
    return results

