def convert_temperature(value, scale):
    """
    Convert the given temperature value to other two scales.

    Parameters:
    value (float): Temperature value to be converted.
    scale (str): The scale of the given temperature value, 'C' for Celsius, 'F' for Fahrenheit, 'K' for Kelvin.

    Returns:
    dict: A dictionary with converted temperature values. Empty dictionary if input is invalid.
    """
    try:
        value = float(value)  # Ensure the temperature value is float
    except ValueError:
        return {}

    if scale not in ('C', 'F', 'K'):
        return {}

    conversions = {}

    if scale == 'C':
        conversions['F'] = round((value * 9/5) + 32, 2)
        conversions['K'] = round(value + 273.15, 2)
    elif scale == 'F':
        conversions['C'] = round((value - 32) * 5/9, 2)
        conversions['K'] = round(((value - 32) * 5/9) + 273.15, 2)
    elif scale == 'K':
        conversions['C'] = round(value - 273.15, 2)
        conversions['F'] = round(((value - 273.15) * 9/5) + 32, 2)

    return conversions

