def num_of_isolated_groups(grid):
    if not grid or not grid[0]:
        return 0

    M, N = len(grid), len(grid[0])
    visited = [[False for _ in range(N)] for _ in range(M)]

    def is_water_or_visited(i, j):
        return grid[i][j] == 'W' or visited[i][j]

    def explore(i, j):
        if i < 0 or i >= M or j < 0 or j >= N or is_water_or_visited(i, j):
            return
        if grid[i][j] == '.':
            return
        visited[i][j] = True
        explore(i + 1, j)
        explore(i - 1, j)
        explore(i, j + 1)
        explore(i, j - 1)

    group_count = 0
    for i in range(M):
        for j in range(N):
            if grid[i][j] == 'T' and not visited[i][j]:
                group_count += 1
                explore(i, j)

    return group_count

def forest_isolated_groups(T, test_cases):
    results = []
    for idx in range(T):
        M, N, grid = test_cases[idx]
        result = num_of_isolated_groups(grid)
        results.append(f"Case {idx + 1}: {result}")
    return results

