def find_cheapest_dish(M, T, cafe_data, queries):
    results = []
    for query in queries:
        c, C = query[0]
        preferred_cafes = query[1]

        min_price = float('inf')
        for cafe_index in preferred_cafes:
            dishes = cafe_data[cafe_index - 1]
            for price, calorie in dishes:
                if calorie <= C and price < min_price:
                    min_price = price

        if min_price == float('inf'):
            results.append(-1)
        else:
            results.append(min_price)

    return results

# Helper function to process the input into the required format
def process_input(M, T, raw_data, raw_queries):
    cafe_data = []
    curr_index = 0

    for _ in range(M):
        L = raw_data[curr_index]
        dishes = []
        for i in range(L):
            price = raw_data[curr_index + 1 + 2 * i]
            calorie = raw_data[curr_index + 2 + 2 * i]
            dishes.append((price, calorie))
        curr_index += 1 + 2 * L
        cafe_data.append(dishes)

    queries = []
    for i in range(T):
        c_C = (raw_queries[2 * i][0], raw_queries[2 * i][1])
        cafes = raw_queries[2 * i + 1]
        queries.append((c_C, cafes))

    return cafe_data, queries

