from collections import deque, defaultdict

def spread_time(graph, initial_infected):
    if not graph or not initial_infected:
        return -1

    # Convert the graph to adjacency list representation
    adjacency_list = defaultdict(list)
    all_nodes = set()
    for src, dest in graph:
        adjacency_list[src].append(dest)
        adjacency_list[dest].append(src)
        all_nodes.update([src, dest])

    if set(initial_infected) == all_nodes:
        return 0

    infected = set(initial_infected)
    queue = deque((node, 0) for node in initial_infected)
    max_time = 0

    while queue:
        current_node, current_time = queue.popleft()
        for neighbor in adjacency_list[current_node]:
            if neighbor not in infected:
                infected.add(neighbor)
                queue.append((neighbor, current_time + 1))
                max_time = max(max_time, current_time + 1)

    if len(infected) == len(all_nodes):
        return max_time
    else:
        return -1

