def process_commands(commands):
    records = []

    for command in commands:
        parts = command.split()
        action = parts[0]

        if action == 'add':
            name = parts[1]
            grade = int(parts[2])
            records.append((name, grade))

        elif action == 'remove':
            name = parts[1]
            for i in range(len(records)):
                if records[i][0] == name:
                    records.pop(i)
                    break

        elif action == 'update':
            name = parts[1]
            new_grade = int(parts[2])
            for i in range(len(records)):
                if records[i][0] == name:
                    records[i] = (name, new_grade)
                    break

        elif action == 'print':
            print(records)

        elif action == 'average':
            if records:
                avg = sum(grade for name, grade in records) / len(records)
                print(avg)
            else:
                print("N/A")

