def roundGrades(grades):
    """
    Given a list of grades, return the list with the grades rounded according to the specified rules.
    """
    rounded_grades = []
    for grade in grades:
        if grade >= 38:
            next_multiple_of_5 = ((grade // 5) + 1) * 5
            if next_multiple_of_5 - grade < 3:
                grade = next_multiple_of_5
        rounded_grades.append(grade)
    return rounded_grades

