from typing import List

def max_allocated_area(grid: List[List[str]]) -> int:
    if not grid or not grid[0]:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # Initialize dp arrays
    height = [0] * (cols + 1)

    max_area = 0

    for row in grid:
        for col in range(cols):
            height[col] = height[col] + 1 if row[col] == '.' else 0

        stack = [-1]
        for col in range(cols + 1):
            while height[col] < height[stack[-1]]:
                h = height[stack.pop()]
                w = col - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(col)

    return max_area

