def is_prime(number):
    """
    Returns whether a number is a prime number.
    """
    if number <= 1:
        return False
    if number <= 3:
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False
    i = 5
    while i * i <= number:
        if number % i == 0 or number % (i + 2) == 0:
            return False
        i += 6
    return True

def find_element_to_remove_for_prime_product(arr):
    """
    Tries to find an element whose removal makes the product of remaining elements a prime number.
    """
    total_product = 1
    for num in arr:
        total_product *= num
    for i, num in enumerate(arr):
        if total_product % num == 0 and is_prime(total_product // num):
            return i + 1  # Return 1-based index
    return -1

def solve_prime_product_problem(test_cases):
    results = []
    for n, arr in test_cases:
        index = find_element_to_remove_for_prime_product(arr)
        if index != -1:
            results.append(("Yes", index))
        else:
            results.append(("No",))
    return results

