def shift_string(s: str, k: int) -> str:
    def shift_char(c, k):
        if 'a' <= c <= 'z':  # Lowercase letters
            return chr((ord(c) - ord('a') + k) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':  # Uppercase letters
            return chr((ord(c) - ord('A') + k) % 26 + ord('A'))
        else:
            return c  # Non-alphabetic characters stay the same

    return ''.join(shift_char(c, k) for c in s)

from collections import deque
from typing import List, Tuple

def min_steps_to_cut_trees(forest: List[List[int]]) -> int:
    def bfs(start: Tuple[int, int], goal: Tuple[int, int]) -> int:
        m, n = len(forest), len(forest[0])
        visited = set()
        queue = deque([(start[0], start[1], 0)])  # store (x, y, steps)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while queue:
            x, y, steps = queue.popleft()
            if (x, y) == goal:
                return steps
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited:
                    if forest[nx][ny] > 0:
                        visited.add((nx, ny))
                        queue.append((nx, ny, steps + 1))
        return -1

    trees = sorted((height, r, c)
                   for r, row in enumerate(forest)
                   for c, height in enumerate(row)
                   if height > 1)

    start = (0, 0)
    total_steps = 0

    for height, r, c in trees:
        steps = bfs(start, (r, c))
        if steps == -1:
            return -1
        total_steps += steps
        start = (r, c)

    return total_steps

from typing import List

def min_path_sum(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize the first row and column with their respective sums
    for i in range(1, m):
        grid[i][0] += grid[i-1][0]
    for j in range(1, n):
        grid[0][j] += grid[0][j-1]

    # Calculate the minimum path sum for each cell
    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += min(grid[i-1][j], grid[i][j-1])

    return grid[m-1][n-1]

