def levenshtein_distance(a, b):
    """
    Calculate the Levenshtein distance between two strings.
    """
    if len(a) < len(b):
        return levenshtein_distance(b, a)

    if len(b) == 0:
        return len(a)

    previous_row = range(len(b) + 1)
    for i, c1 in enumerate(a):
        current_row = [i + 1]
        for j, c2 in enumerate(b):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def spell_checker(text: str, dictionary: list) -> str:
    """
    Corrects all misspelled words in a given text based on a provided dictionary.
    """
    def find_closest_match(word):
        closest_distance = float('inf')
        closest_word = word
        for correct_word in dictionary:
            distance = levenshtein_distance(word, correct_word)
            if distance < closest_distance or (distance == closest_distance and correct_word < closest_word):
                closest_distance = distance
                closest_word = correct_word
        return closest_word

    words = text.split()
    corrected_words = [find_closest_match(word) for word in words]
    return ' '.join(corrected_words)

def is_prime(n):
    """
    Determines if a given number `n` is a prime number.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def sum_of_digits_is_prime(number):
    """
    Determines if the sum of the digits of `number` is a prime number.
    """
    digit_sum = sum(int(digit) for digit in str(number))
    return is_prime(digit_sum)

