def evaluate_rpn(expression):
    """
    Evaluates a Reverse Polish Notation (RPN) expression.

    Parameters:
    expression (str): A string containing the RPN expression.

    Returns:
    float: The result of the evaluation.
    """
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token in {"+", "-", "*", "/"}:
            b = stack.pop()
            a = stack.pop()

            if token == "+":
                result = a + b
            elif token == "-":
                result = a - b
            elif token == "*":
                result = a * b
            elif token == "/":
                result = a / b

            stack.append(result)
        else:
            stack.append(float(token))

    return stack[0]

