from typing import List, Tuple
from collections import defaultdict

def find_anagram_pairs(words: List[str]) -> List[Tuple[str, str]]:
    """
    Returns a list of tuples containing all anagram pairs from the input list of words.
    """
    # Using a dictionary to group words by sorted tuple of characters
    anagram_dict = defaultdict(list)

    for word in words:
        sorted_word = tuple(sorted(word))
        anagram_dict[sorted_word].append(word)

    anagram_pairs = []

    # For each group of anagrams, we need to generate pair combinations
    for group in anagram_dict.values():
        if len(group) > 1:
            sorted_group = sorted(group)
            for i in range(len(sorted_group)):
                for j in range(i + 1, len(sorted_group)):
                    anagram_pairs.append((sorted_group[i], sorted_group[j]))

    return anagram_pairs

