def minReplacements(n, memo=None):
    """
    Returns the minimum number of replacements needed for n to become 1.
    """
    if memo is None:
        memo = {}

    if n == 1:
        return 0

    if n in memo:
        return memo[n]

    if n % 2 == 0:
        memo[n] = 1 + minReplacements(n // 2, memo)
    else:
        memo[n] = 1 + min(minReplacements(n + 1, memo), minReplacements(n - 1, memo))

    return memo[n]

