def get_highest_scores(entries):
    """
    Returns a list of tuples representing the student names and their highest scores
    in the order of their first appearance.
    """
    highest_scores = {}
    first_appearance = {}

    for i, entry in enumerate(entries):
        name, score = entry.split()
        score = int(score)

        if name not in highest_scores:
            highest_scores[name] = score
            first_appearance[name] = i
        else:
            if score > highest_scores[name]:
                highest_scores[name] = score

    sorted_names = sorted(first_appearance, key=first_appearance.get)
    result = [(name, highest_scores[name]) for name in sorted_names]

    return result

