def exist(grid, word):
    """
    Checks if the word exists in the 2D grid.
    """
    rows, cols = len(grid), len(grid[0])

    def dfs(r, c, index):
        if index == len(word):
            return True
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] != word[index]:
            return False

        temp = grid[r][c]
        grid[r][c] = '#'

        found = (dfs(r+1, c, index+1) or   # down
                 dfs(r-1, c, index+1) or   # up
                 dfs(r, c+1, index+1) or   # right
                 dfs(r, c-1, index+1))     # left

        grid[r][c] = temp
        return found

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == word[0] and dfs(i, j, 0):
                return True

    return False

def transform_to_frequency_dict(s: str) -> dict:
    """
    Returns a dictionary with characters as keys and their frequency as values.
    Only alphabet characters are considered, and it is case-insensitive.
    """
    freq_dict = {}
    for char in s.lower():
        if char.isalpha():
            if char in freq_dict:
                freq_dict[char] += 1
            else:
                freq_dict[char] = 1
    return freq_dict

