def encode(string):
    """
    Encodes the given string using a simplified version of the Run-Length Encoding (RLE) algorithm.
    """
    if not string:
        return ""

    encoded = []
    count = 1
    for i in range(1, len(string)):
        if string[i] == string[i - 1]:
            count += 1
        else:
            if count > 1:
                encoded.append(f"{string[i - 1]}{count}")
            else:
                encoded.append(string[i - 1])
            count = 1
    # Add the last character/count
    if count > 1:
        encoded.append(f"{string[-1]}{count}")
    else:
        encoded.append(string[-1])

    return "".join(encoded)

def decode(string):
    """
    Decodes the given encoded string back to its original form using the rules of the simplified RLE algorithm.
    """
    decoded = []
    i = 0
    while i < len(string):
        char = string[i]
        if i + 1 < len(string) and string[i + 1].isdigit():
            count = int(string[i + 1])
            decoded.append(char * count)
            i += 2
        else:
            decoded.append(char)
            i += 1

    return "".join(decoded)

def top_3_high_avg_scores(usernames, scores):
    from collections import defaultdict

    user_scores = defaultdict(list)

    for username, score in zip(usernames, scores):
        user_scores[username].append(score)

    valid_avg_scores = {}
    for user, score_list in user_scores.items():
        if len(score_list) >= 3:
            avg_score = sum(score_list) / len(score_list)
            valid_avg_scores[user] = avg_score

    top_users = sorted(
        valid_avg_scores.keys(),
        key=lambda user: (-valid_avg_scores[user], user)
    )[:3]

    return top_users

