def max_fish(events):
    """
    Determines the maximum number of fish in a single tank at any given day, given a series of daily events.

    Args:
    events (list of str): List of events in the format described in the problem.

    Returns:
    int: The maximum number of fish in a single tank at any point throughout the events.
    """
    tanks = {}
    max_fish_in_tank = 0

    for event in events:
        parts = event.split()
        action = parts[0]
        tank_number = int(parts[0][1:])

        if action[0] == '+':
            fish_count = int(parts[1])
            if tank_number in tanks:
                tanks[tank_number] += fish_count
            else:
                tanks[tank_number] = fish_count
            max_fish_in_tank = max(max_fish_in_tank, tanks[tank_number])
        elif action[0] == '-':
            if tank_number in tanks:
                tanks[tank_number] = 0

    return max_fish_in_tank

