def flatten_list(nested_list):
    """
    Flattens a nested list of integers and strings while preserving the order
    of the integers. Strings are ignored. Only the innermost integers are added to
    the final list. If the input is not a list, an empty list is returned.

    :param nested_list: list containing integers, strings, and sublists
    :return: a list containing all the integers from the input list in order
    """
    def flatten(nested):
        for elem in nested:
            if isinstance(elem, list):
                yield from flatten(elem)
            elif isinstance(elem, int):
                yield elem

    if not isinstance(nested_list, list):
        return []

    return list(flatten(nested_list))

