def create_zigzag_matrix(N, M):
    matrix = [[0]*M for _ in range(N)]
    num = 1
    for i in range(N):
        if i % 2 == 0:
            for j in range(M):
                matrix[i][j] = num
                num += 1
        else:
            for j in range(M-1, -1, -1):
                matrix[i][j] = num
                num += 1
    return matrix

def zigzag_matrices(test_cases):
    results = []
    for N, M in test_cases:
        matrix = create_zigzag_matrix(N, M)
        results.append(matrix)
    return results

