from heapq import heappush, heappop
from collections import Counter

def rearrange_cost(s):
    freq = Counter(s)
    max_freq = max(freq.values())

    if max_freq > (len(s) + 1) // 2:
        return -1

    max_heap = []
    for char, count in freq.items():
        heappush(max_heap, (-count, char))

    result = []
    while len(max_heap) >= 2:
        count1, char1 = heappop(max_heap)
        count2, char2 = heappop(max_heap)

        result.append(char1)
        result.append(char2)

        if -count1 > 1:
            heappush(max_heap, (count1 + 1, char1))
        if -count2 > 1:
            heappush(max_heap, (count2 + 1, char2))

    if max_heap:
        result.append(max_heap[0][1])

    return 0

def solve(test_cases):
    results = []
    for s in test_cases:
        results.append(rearrange_cost(s))
    return results

def find_intersection(arr1, arr2):
    """
    Returns the intersection of two arrays including duplicates.
    """
    # Dictionary to count the elements in arr1
    counts = {}
    for num in arr1:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # List to store the intersection
    intersection = []
    for num in arr2:
        if num in counts and counts[num] > 0:
            intersection.append(num)
            counts[num] -= 1

    return intersection

from collections import deque

def wordTransformation(start, end, valid_words):
    """
    Finds the shortest transformation sequence from start to end where each word in the sequence is in valid_words
    and only one letter differs from the previous word.
    """
    if start == end:
        return [start]

    valid_words = set(valid_words)
    if end not in valid_words:
        return []

    queue = deque([(start, [start])])
    visited = set()

    while queue:
        current_word, path = queue.popleft()
        visited.add(current_word)

        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                next_word = current_word[:i] + c + current_word[i+1:]
                if next_word == end:
                    return path + [next_word]
                if next_word in valid_words and next_word not in visited:
                    queue.append((next_word, path + [next_word]))
                    visited.add(next_word)

    return []

