def prime_game_winner(test_cases):
    results = []
    for case in test_cases:
        n, numbers = case
        primes = [num for num in numbers if is_prime(num)]

        # Sort primes in descending order to simulate optimal play
        primes_sorted = sorted(primes, reverse=True)

        if not primes_sorted:
            # Since no prime numbers are there, checking whose turn would it be if there were primes
            results.append("Bob")
            continue

        largest_prime = primes_sorted[0]
        if primes_sorted.index(largest_prime) % 3 == 0:
            results.append("Alice")
        elif primes_sorted.index(largest_prime) % 3 == 1:
            results.append("Bob")
        else:
            results.append("Charlie")
    return results

def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def is_palindrome_before(s: str, k: int) -> bool:
    """
    Returns True if the string s can be made into a palindrome by rotating it
    up to k times. Otherwise, returns False.
    """

    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    n = len(s)
    for i in range(k + 1):
        rotated_s = s[i:] + s[:i]
        if is_palindrome(rotated_s):
            return True
    return False

