from collections import deque

def shortestPathWithWallBreak(grid, N, M):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[[False, False] for _ in range(M)] for _ in range(N)]
    queue = deque([(0, 0, 0, 1)])  # (x, y, wall_broken, distance)
    visited[0][0][0] = True

    while queue:
        x, y, wall_broken, dist = queue.popleft()

        if x == N - 1 and y == M - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < M:
                if grid[nx][ny] == '.' and not visited[nx][ny][wall_broken]:
                    visited[nx][ny][wall_broken] = True
                    queue.append((nx, ny, wall_broken, dist + 1))

                if grid[nx][ny] == '#' and wall_broken == 0 and not visited[nx][ny][1]:
                    visited[nx][ny][1] = True
                    queue.append((nx, ny, 1, dist + 1))

    return -1

def solveShortPathAllCases(test_cases):
    results = []
    for case in test_cases:
        N, M, grid = case
        result = shortestPathWithWallBreak(grid, N, M)
        results.append(result)
    return results

