def calculate_tree_depths(n, edges):
    from collections import deque, defaultdict

    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    depths = [-1] * (n + 1)
    queue = deque([(1, 0)])
    depths[1] = 0

    while queue:
        node, depth = queue.popleft()
        for neighbor in tree[node]:
            if depths[neighbor] == -1:
                depths[neighbor] = depth + 1
                queue.append((neighbor, depth + 1))

    return depths

def minimum_servers_to_isolate(n, edges, scenarios):
    depths = calculate_tree_depths(n, edges)
    return [depths[s] for s in scenarios]

