def is_mountain_array(arr):
    """
    Returns True if the given list of integers represents a mountain array, False otherwise.
    """
    if len(arr) < 3:
        return False

    i = 1
    # Walk up
    while i < len(arr) and arr[i] > arr[i - 1]:
        i += 1

    # Peak can't be first or last
    if i == 1 or i == len(arr):
        return False

    # Walk down
    while i < len(arr) and arr[i] < arr[i - 1]:
        i += 1

    return i == len(arr)

def evaluate_expression(expression: str) -> int:
    """
    Evaluates the mathematical expression contained in the given string and returns the result as an integer.
    :param expression: str - The mathematical expression to evaluate.
    :return: int - The result of the expression.
    """
    def helper(s, idx):
        stack = []
        num = 0
        sign = 1
        while idx < len(s):
            char = s[idx]
            if char.isdigit():
                num = num * 10 + int(char)
            elif char == '+':
                stack.append(sign * num)
                num = 0
                sign = 1
            elif char == '-':
                stack.append(sign * num)
                num = 0
                sign = -1
            elif char == '(':
                num, idx = helper(s, idx + 1)
                stack.append(sign * num)
                num = 0
            elif char == ')':
                stack.append(sign * num)
                return sum(stack), idx
            idx += 1
        stack.append(sign * num)
        return sum(stack)

    return helper(expression, 0)

