def count_pairs_with_sum(test_cases):
    results = []
    for case in test_cases:
        n, K, arr = case
        count = 0
        seen = {}

        for number in arr:
            target = K - number
            if target in seen:
                count += seen[target]

            if number in seen:
                seen[number] += 1
            else:
                seen[number] = 1

        results.append(count)
    return results

