def check_politeness(T, strings):
    def is_palindrome(s):
        return s == s[::-1]

    def is_almost_polite(s):
        left, right = 0, len(s) - 1
        changes = 0
        while left < right:
            if s[left] != s[right]:
                changes += 1
                if changes > 1:
                    return False
            left += 1
            right -= 1
        return True

    results = []
    for s in strings:
        if is_palindrome(s):
            results.append("polite")
        elif is_almost_polite(s):
            results.append("almost polite")
        else:
            results.append("impolite")
    return results

