def calculate(expression: str) -> int:
    def parse_expression(expression):
        tokens = []
        number = 0
        has_number = False
        for char in expression:
            if char.isdigit():
                number = number * 10 + int(char)
                has_number = True
            else:
                if has_number:
                    tokens.append(number)
                    number = 0
                    has_number = False
                if char in "+-*/":
                    tokens.append(char)
        if has_number:
            tokens.append(number)
        return tokens

    def evaluate_tokens(tokens):
        stack = []
        current_operator = '+'
        i = 0
        while i < len(tokens):
            token = tokens[i]
            if isinstance(token, int):
                if current_operator == '+':
                    stack.append(token)
                elif current_operator == '-':
                    stack.append(-token)
                elif current_operator == '*':
                    stack[-1] = stack[-1] * token
                elif current_operator == '/':
                    stack[-1] = int(stack[-1] / token)
            else:
                current_operator = token
            i += 1
        return sum(stack)

    tokens = parse_expression(expression.replace(' ', ''))
    return evaluate_tokens(tokens)

