def next_alphabet(s: str) -> str:
    def shift_char(c):
        if 'a' <= c <= 'z':
            return 'a' if c == 'z' else chr(ord(c) + 1)
        elif 'A' <= c <= 'Z':
            return 'A' if c == 'Z' else chr(ord(c) + 1)
        return c

    return ''.join(shift_char(c) for c in s)

