from typing import List, Tuple

def can_rent_bike(availabilities: List[Tuple[int, int]], requests: List[Tuple[int, int]]) -> List[bool]:
    results = []
    for req_start, req_end in requests:
        fulfilled = False
        for avail_start, avail_end in availabilities:
            if req_start >= avail_start and req_end <= avail_end:
                fulfilled = True
                break
        results.append(fulfilled)
    return results

