def has_consecutive_increasing_digits(s):
    """
    Returns True if the string contains exactly three consecutive digits in increasing order.
    """
    for i in range(len(s) - 2):
        if s[i].isdigit() and s[i+1].isdigit() and s[i+2].isdigit():
            if int(s[i]) + 1 == int(s[i+1]) and int(s[i+1]) + 1 == int(s[i+2]):
                return True
    return False

