def maxTreasure(treasures):
    if not treasures:
        return 0
    if len(treasures) == 1:
        return treasures[0]
    if len(treasures) == 2:
        return max(treasures)

    def rob_linear(houses):
        n = len(houses)
        dp = [0] * n
        if n >= 1:
            dp[0] = houses[0]
        if n >= 2:
            dp[1] = max(houses[0], houses[1])
        for i in range(2, n):
            dp[i] = max(dp[i-1], dp[i-2] + houses[i])
        return dp[-1]

    return max(rob_linear(treasures[:-1]), rob_linear(treasures[1:]))

