    """
    merged_array = merge_arrays(arr1, arr2)
    length = len(merged_array)

    if length % 2 == 1:
        return float(merged_array[length // 2])
    else:
        mid1, mid2 = merged_array[length // 2 - 1], merged_array[length // 2]
        return (mid1 + mid2) / 2.0

def merge_arrays(arr1, arr2):
    merged = []
    i, j = 0, 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] <= arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1
    while i < len(arr1):
        merged.append(arr1[i])
        i += 1
    while j < len(arr2):
        merged.append(arr2[j])
        j += 1
    return merged

