from collections import deque
from typing import List, Tuple

def min_stops(flights: List[Tuple[str, str]], start: str, destination: str) -> int:
    if start == destination:
        return 0

    # Create adjacency list to represent the flight connections
    graph = {}
    for source, dest in flights:
        if source not in graph:
            graph[source] = []
        if dest not in graph:
            graph[dest] = []
        graph[source].append(dest)
        graph[dest].append(source)  # since flights can be used in either direction

    # Perform BFS to find the shortest path
    queue = deque([(start, 0)])  # (current_city, stops)
    visited = set()
    visited.add(start)

    while queue:
        current_city, stops = queue.popleft()
        for neighbor in graph.get(current_city, []):
            if neighbor == destination:
                return stops + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, stops + 1))

    return -1

