def can_travel(grid):
    """
    Check if there is a path from top-left to bottom-right in the grid.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return False

    rows, cols = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def within_bounds(x, y):
        return 0 <= x < rows and 0 <= y < cols

    def dfs(x, y, visited):
        if (x, y) == (rows - 1, cols - 1):
            return True
        visited.add((x, y))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if within_bounds(nx, ny) and grid[nx][ny] == 0 and (nx, ny) not in visited:
                if dfs(nx, ny, visited):
                    return True
        return False

    return dfs(0, 0, set())

