def wordWrap(text, limit):
    if not text.strip():
        return ""

    words = text.split()

    if any(len(word) > limit for word in words):
        raise ValueError("The limit is less than the length of the longest word in the text.")

    wrapped_text = []
    current_line = []
    current_length = 0

    for word in words:
        if current_length + len(word) + len(current_line) > limit:
            wrapped_text.append(" ".join(current_line))
            current_line = [word]
            current_length = len(word)
        else:
            current_line.append(word)
            current_length += len(word)

    if current_line:
        wrapped_text.append(" ".join(current_line))

    return "\n".join(wrapped_text)

def days_in_month(month, year):
    """
    Returns the number of days in the given month of the given year.
    Accounts for leap years in February.
    Returns None if the month is invalid.
    """
    if month < 1 or month > 12:
        return None

    if month == 2:
        # Check for leap year
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
            return 29
        else:
            return 28

    # Months with 31 days
    if month in [1, 3, 5, 7, 8, 10, 12]:
        return 31

    # Months with 30 days
    return 30

