def caesar_cipher(s: str, n: int) -> str:
    """
    Shifts each alphabetic character in the string s forward by n positions in the alphabet.
    Non-alphabetic characters remain unchanged.
    """
    result = []
    for char in s:
        if char.isalpha():
            shift = ord('A') if char.isupper() else ord('a')
            result.append(chr(shift + (ord(char) - shift + n) % 26))
        else:
            result.append(char)
    return "".join(result)

