def longest_arith_seq_length(A):
    if not A:
        return 0

    n = len(A)
    if n == 1:
        return 1

    # Create a dictionary to store the length of arithmetic sequences.
    # dp[i][d] means the length of arithmetic subsequence ending with A[i] and common difference d
    dp = [{} for _ in range(n)]
    max_length = 0

    for i in range(n):
        for j in range(i):
            diff = A[i] - A[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2
            max_length = max(max_length, dp[i][diff])

    return max_length

