def convert_temperature(value, scale):
    """
    Convert temperature between Celsius and Fahrenheit.

    Parameters:
    value (float): The temperature value to be converted.
    scale (str): The target scale for conversion ("C" for Celsius, "F" for Fahrenheit).

    Returns:
    float: The converted temperature rounded to 1 decimal place.
    """
    if scale == "C":
        return round((value - 32) * 5 / 9, 1)
    elif scale == "F":
        return round((value * 9 / 5) + 32, 1)
    else:
        raise ValueError("Invalid scale. Use 'C' for Celsius or 'F' for Fahrenheit.")

