def is_robot_bounded(instructions: str) -> bool:
    """
    Determines if the robot is bounded in a circle.

    :param instructions: str: The sequence of commands for the robot.
    :return: bool: True if the robot is bounded in a circle, otherwise False.
    """
    # Initial position and direction
    x, y = 0, 0
    dx, dy = 0, 1  # Facing north (positive y direction)

    for command in instructions:
        if command == 'G':
            x, y = x + dx, y + dy
        elif command == 'L':
            dx, dy = -dy, dx  # 90 degrees left turn
        elif command == 'R':
            dx, dy = dy, -dx  # 90 degrees right turn

    # After one sequence of instructions, check position and direction
    return (x == 0 and y == 0) or (dx != 0 or dy != 1)

