def are_parentheses_closed(s):
    """
    Returns True if all parentheses in the string are properly closed and nested, otherwise returns False.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    return not stack

