def longestSubstringWithTwoDistinct(s):
    """
    Returns the length of the longest substring that contains at most two different types of characters.
    """
    n = len(s)
    if n <= 2:
        return n

    max_len = 0
    left = 0
    char_count = {}

    for right in range(n):
        char_count[s[right]] = char_count.get(s[right], 0) + 1

        while len(char_count) > 2:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

