def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers less than or equal to n.
    Uses the Sieve of Eratosthenes algorithm for efficient computation.
    """
    if n < 2:
        return []

    sieve = [True] * (n + 1)
    sieve[0], sieve[1] = False, False  # 0 and 1 are not primes

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n+1, start):
                sieve[multiple] = False

    return [num for num in range(n + 1) if sieve[num]]

from collections import deque

def manage_follows(M, K, initial_follows, N, actions):
    follows = deque(initial_follows)

    for action in actions:
        if action > 0:
            if action not in follows:
                follows.append(action)
                if len(follows) > K:
                    follows.popleft()
        elif action < 0:
            if -action in follows:
                follows.remove(-action)

    return list(follows)

def backspace_compare(s, t):
    """
    Compares two strings considering backspace characters '#' and determines if they are equal.
    """

    def build(string):
        stack = []
        for char in string:
            if char != '#':
                stack.append(char)
            elif stack:
                stack.pop()
        return "".join(stack)

    return build(s) == build(t)

