def calculateSpan(expression):
    """
    Evaluates a postfix expression and returns the result.

    Parameters:
    expression (str): A string containing a postfix arithmetic expression.

    Returns:
    int/None: The result of the postfix expression or None in case of an error.
    """
    if not isinstance(expression, str):
        return None

    stack = []
    operators = set(["+", "-", "*", "/"])

    tokens = expression.split()

    for token in tokens:
        if token.lstrip('-').isdigit():  # Check if the token is an integer, considering negative numbers.
            stack.append(int(token))
        elif token in operators:
            if len(stack) < 2:
                return None  # Not enough operands
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                if b == 0:  # Handle division by zero
                    return None
                stack.append(a // b)  # Integer division
        else:
            return None  # Invalid token

    if len(stack) != 1:
        return None  # There should be exactly one result if the expression is valid

    return stack[0]

