def fibonacci_up_to(n):
    """
    Returns a list of all Fibonacci numbers less than or equal to `n`.
    """
    if n == 0:
        return [0]
    fib_sequence = [0, 1]
    while True:
        next_fib = fib_sequence[-1] + fib_sequence[-2]
        if next_fib > n:
            break
        fib_sequence.append(next_fib)
    return fib_sequence

