def max_profit(prices):
    """
    Calculate the maximum profit that can be achieved from buying and selling the stock once.

    :param prices: List[int] representing the daily prices of a stock.
    :return: int representing the maximum profit possible.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

