def match_summary(matches):
    total_singles = 0
    total_doubles = 0
    highest_seed = float('-inf')
    total_score = 0
    num_matches = len(matches)

    for match in matches:
        category, seed, score = match
        if category == 'singles':
            total_singles += 1
        elif category == 'doubles':
            total_doubles += 1

        if seed > highest_seed:
            highest_seed = seed

        total_score += score

    average_score = total_score / num_matches if num_matches > 0 else 0

    return {
        'total_singles': total_singles,
        'total_doubles': total_doubles,
        'highest_seed': highest_seed,
        'average_score': round(average_score, 2)
    }

