def find_best_hotel(test_cases):
    results = []
    for case in test_cases:
        N, R, D = case['NRD']
        hotels = case['hotels']

        best_hotel_index = -1
        max_rooms = 0
        min_distance = float('inf')

        for i, (rooms, distance) in enumerate(hotels):
            if rooms >= R and distance <= D:
                if rooms > max_rooms or (rooms == max_rooms and distance < min_distance):
                    best_hotel_index = i + 1
                    max_rooms = rooms
                    min_distance = distance

        results.append(best_hotel_index)

    return results

