def min_removals_to_palindrome(n, s):
    """
    Returns the smallest k for which it is possible to remove exactly k characters from s to make it a palindrome.
    """
    def min_deletions(i, j):
        if i >= j:
            return 0
        if dp[i][j] != -1:
            return dp[i][j]

        if s[i] == s[j]:
            dp[i][j] = min_deletions(i + 1, j - 1)
        else:
            dp[i][j] = 1 + min(min_deletions(i + 1, j), min_deletions(i, j - 1))

        return dp[i][j]

    dp = [[-1] * n for _ in range(n)]
    return min_deletions(0, n - 1)

