def isBalanced(s):
    """
    Returns whether the given string s has properly nested and balanced brackets.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            # If there is any other character in the string, we just ignore
            continue

    return stack == []

