def nth_prime(n: int) -> int:
    """
    Returns the nth prime number.

    Note: Returns -1 if n is less than 1 since there is no zeroth or negative prime number.
    """
    if n < 1:
        return -1

    primes = []
    candidate = 2

    while len(primes) < n:
        is_prime = True
        for p in primes:
            if p * p > candidate:
                break
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1

    return primes[-1]

def validate_paintings(wall_width, wall_height, paintings):
    """
    Validates if the paintings can be placed on the wall without overlapping and within the wall boundaries.
    """
    n = len(paintings)

    for i in range(n):
        x1, y1, w1, h1 = paintings[i]

        # Check if the current painting fits within the wall boundaries
        if x1 < 0 or y1 < 0 or x1 + w1 > wall_width or y1 + h1 > wall_height:
            return False

        for j in range(i + 1, n):
            x2, y2, w2, h2 = paintings[j]

            # Check for overlap with any other painting
            if not (x1 + w1 <= x2 or x2 + w2 <= x1 or y1 + h1 <= y2 or y2 + h2 <= y1):
                return False

    return True

