def calculate_expression(expr: str) -> str:
    """
    Evaluates a basic arithmetic expression consisting of two integers and an operator (+, -, *, or /)
    separated by spaces, and returns the result as a string.
    """
    try:
        parts = expr.split()
        if len(parts) != 3:
            return "invalid input"

        num1, operator, num2 = parts
        num1, num2 = int(num1), int(num2)

        if operator == '+':
            result = num1 + num2
        elif operator == '-':
            result = num1 - num2
        elif operator == '*':
            result = num1 * num2
        elif operator == '/':
            if num2 == 0:
                return "undefined"
            result = num1 // num2  # Use integer division for consistent result type

        return str(result)

    except (ValueError, TypeError):
        return "invalid input"

