def isValidString(s):
    """
    Returns True if the string `s` is valid according to the specified rules:
    - No consecutive 'b's
    - No more than two 'a's in a row
    Otherwise, returns False.
    """
    a_count = 0

    for i in range(len(s)):
        if s[i] == 'a':
            a_count += 1
            if a_count > 2:
                return False
        else:
            a_count = 0
            if i > 0 and s[i - 1] == 'b':
                return False

    return True

def canPartition(digits, divisor):
    """
    Returns whether a partition is possible such that each subarray forms a number divisible by the given divisor.
    """
    def is_valid_partition(index):
        if index == len(digits):
            return True
        num = 0
        for i in range(index, len(digits)):
            num = num * 10 + digits[i]
            if num % divisor == 0:
                if is_valid_partition(i + 1):
                    return True
        return False

    return is_valid_partition(0)

