def min_path_sum(matrix):
    """
    Given an M x N matrix filled with non-negative integers, find a path from the top-left corner
    to the bottom-right corner which minimizes the sum of all numbers along its path.
    You can only move to the right or down from a given cell.
    """
    if not matrix or not matrix[0]:
        return 0

    M, N = len(matrix), len(matrix[0])
    dp = [[0]*N for _ in range(M)]

    dp[0][0] = matrix[0][0]

    for i in range(1, M):
        dp[i][0] = dp[i-1][0] + matrix[i][0]

    for j in range(1, N):
        dp[0][j] = dp[0][j-1] + matrix[0][j]

    for i in range(1, M):
        for j in range(1, N):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    return dp[M-1][N-1]

