def count_geometric_subarrays(A):
    """
    Returns the number of geometric subarrays in array A.
    """
    n = len(A)
    if n < 3:
        return 0

    count = 0

    for i in range(n):
        for j in range(i + 1, n):
            ratio = A[j] / A[i]
            k = j + 1
            while k < n and A[k] / A[k - 1] == ratio:
                count += 1
                k += 1

    return count

