def has_increasing_triplet(T, test_cases):
    results = []

    for i in range(T):
        N, A = test_cases[i]
        if N < 3:
            results.append("NO")
            continue

        first = float('inf')
        second = float('inf')

        for number in A:
            if number <= first:
                first = number
            elif number <= second:
                second = number
            else:
                results.append("YES")
                break
        else:
            results.append("NO")

    return results

