def contains_nearby_almost_duplicate(nums, k, t):
    if k < 0 or t < 0:
        return False
    num_dict = {}
    for i in range(len(nums)):
        bucket = nums[i] // (t + 1)
        if bucket in num_dict:
            return True
        if (bucket - 1) in num_dict and abs(nums[i] - num_dict[bucket - 1]) <= t:
            return True
        if (bucket + 1) in num_dict and abs(nums[i] - num_dict[bucket + 1]) <= t:
            return True
        num_dict[bucket] = nums[i]
        if i >= k:
            del num_dict[nums[i - k] // (t + 1)]
    return False

