def calculate_min_cost(bottles):
    """
    Calculate the minimum cost for a given number of lemonade bottles.

    :param bottles: int - Number of lemonade bottles.
    :return: float - Minimum cost rounded to two decimal places.
    """
    if bottles < 0:
        raise ValueError("The number of bottles cannot be negative.")

    prices = [(15, 5.00), (7, 2.50), (3, 1.00), (1, 0.50)]

    total_cost = 0.0
    for qty, price in prices:
        while bottles >= qty:
            total_cost += price
            bottles -= qty

    return round(total_cost, 2)

