def can_ship_travel_without_hitting_obstacles(x1, y1, x2, y2, obstacles):
    import math

    def is_point_to_segment_distance_less_than_circle(center_x, center_y, radius, x1, y1, x2, y2):
        """
        Check if the distance from center of the circle to the segment is less than the circle's radius.
        """
        def distance(x1, y1, x2, y2):
            return math.sqrt((x1 - x2)**2 + (y1 - y2)**2)

        if distance(center_x, center_y, x1, y1) <= radius or distance(center_x, center_y, x2, y2) <= radius:
            return True

        if (x1 == x2 and y1 == y2):
            return distance(center_x, center_y, x1, y1) <= radius

        A = center_x - x1
        B = center_y - y1
        C = x2 - x1
        D = y2 - y1

        dot = A * C + B * D
        len_sq = C * C + D * D
        param = dot / len_sq if len_sq != 0 else -1

        if param < 0:
            nearest_x, nearest_y = x1, y1
        elif param > 1:
            nearest_x, nearest_y = x2, y2
        else:
            nearest_x = x1 + param * C
            nearest_y = y1 + param * D

        return distance(center_x, center_y, nearest_x, nearest_y) <= radius

    for center_x, center_y, radius in obstacles:
        if is_point_to_segment_distance_less_than_circle(center_x, center_y, radius, x1, y1, x2, y2):
            return "NO"

    return "YES"

