from collections import defaultdict

def minimum_stop_signs(n, roads):
    def dfs(node, visited, on_stack, graph):
        visited.add(node)
        on_stack.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, visited, on_stack, graph):
                    return True
            elif neighbor in on_stack:
                return True
        on_stack.remove(node)
        return False

    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)

    stop_signs = set()
    visited = set()
    on_stack = set()

    for node in range(1, n + 1):
        if node not in visited:
            if dfs(node, visited, on_stack, graph):
                stop_signs.add(node)

    return len(stop_signs)

