def calculate_nutritional_value(n, fruits):
    total_nutritional_value = 0.0
    for fruit in fruits:
        fruit_type, weight, ripeness = fruit
        weight = int(weight)
        ripeness = float(ripeness)

        if fruit_type == "Apple":
            total_nutritional_value += 2 * weight * (ripeness / 100)
        elif fruit_type == "Banana":
            total_nutritional_value += 1.5 * weight * (ripeness / 100)
        elif fruit_type == "Cherry":
            total_nutritional_value += 0.5 * weight * (ripeness / 100)

    return round(total_nutritional_value, 2)

