import bisect

def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest increasing subsequence in the array.
    Time complexity: O(n log n)
    """
    if not arr:
        return 0

    # create an array to store the smallest ending element of each increasing subsequence of length i+1
    lis = []

    for num in arr:
        # find the index where `num` can be placed to maintain the sorted order of `lis`
        pos = bisect.bisect_left(lis, num)

        # if pos is equal to the length of `lis`, it means `num` is greater than any element in `lis`
        if pos == len(lis):
            lis.append(num)
        else:
            lis[pos] = num

    # the length of `lis` will give the length of the longest increasing subsequence
    return len(lis)

