def findGCD(a, b):
    """
    Returns the greatest common divisor (GCD) of two non-negative integers a and b using the Euclidean algorithm.
    """
    if a == 0 and b == 0:
        return 0
    while b != 0:
        a, b = b, a % b
    return a

import heapq

def shortest_path(n, edges):
    from collections import defaultdict

    # Create adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Dijkstra's algorithm to find shortest path from 0 to n-1
    def dijkstra(source, target):
        heap = [(0, source, [])]
        visited = set()

        while heap:
            cost, node, path = heapq.heappop(heap)

            if node in visited:
                continue

            visited.add(node)
            path = path + [node]

            if node == target:
                return path

            for neighbor, weight in graph[node]:
                if neighbor not in visited:
                    heapq.heappush(heap, (cost + weight, neighbor, path))

        return []

    return dijkstra(0, n-1)

