def find_peak_elements(nums):
    """
    Returns a list of all peak elements. A peak element is an element that is greater than its neighbors.
    """
    n = len(nums)
    peaks = []

    for i in range(n):
        if (i == 0 or nums[i] > nums[i - 1]) and (i == n - 1 or nums[i] > nums[i + 1]):
            peaks.append(nums[i])

    return peaks

