def is_prime(n):
    """
    Check if a number is a prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def rotate_number(n):
    """
    Generate all rotations of a number.
    """
    s = str(n)
    rotations = []
    for i in range(len(s)):
        rotated = int(s[i:] + s[:i])
        rotations.append(rotated)
    return rotations

def is_circular_prime(n):
    """
    Determine if a number is a circular prime.
    """
    if not is_prime(n):
        return False
    rotations = rotate_number(n)
    for rotation in rotations:
        if not is_prime(rotation):
            return False
    return True

