def longest_palindromic_subsequence(seq):
    N = len(seq)
    dp = [[0] * N for _ in range(N)]

    for i in range(N):
        dp[i][i] = 1

    for cl in range(2, N + 1):
        for i in range(N - cl + 1):
            j = i + cl - 1
            if seq[i] == seq[j] and cl == 2:
                dp[i][j] = 2
            elif seq[i] == seq[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return dp[0][N - 1]

def solve_palindromic_subsequence(test_cases):
    results = []
    for seq in test_cases:
        results.append(longest_palindromic_subsequence(seq))
    return results

def parse_input(input_str):
    input_lines = input_str.strip().split('\n')
    index = 0
    T = int(input_lines[index])
    index += 1
    test_cases = []

    for _ in range(T):
        N = int(input_lines[index])
        index += 1
        sequence = list(map(int, input_lines[index].split()))
        index += 1
        test_cases.append(sequence)

    return test_cases

def process_operations(operations):
    product_ratings = {}

    results = []

    for operation in operations:
        parts = operation.split()
        command = parts[0]

        if command == "rate":
            product_id = int(parts[1])
            rating = int(parts[2])

            if product_id not in product_ratings:
                product_ratings[product_id] = []

            product_ratings[product_id].append(rating)

        elif command == "average":
            product_id = int(parts[1])

            if product_id in product_ratings and product_ratings[product_id]:
                average_rating = sum(product_ratings[product_id]) / len(product_ratings[product_id])
                results.append(f"{average_rating:.2f}")
            else:
                results.append("No ratings")

    return results

