def generateParentheses(n):
    """
    Generates all combinations of well-formed parentheses for n pairs of parentheses.
    Returns an alphabetically sorted list of valid strings.
    """
    if not isinstance(n, int) or n < 1:
        return []

    result = []

    def backtrack(current_str, open_count, close_count):
        if len(current_str) == 2 * n:
            result.append(current_str)
            return

        if open_count < n:
            backtrack(current_str + "(", open_count + 1, close_count)
        if close_count < open_count:
            backtrack(current_str + ")", open_count, close_count + 1)

    backtrack("", 0, 0)
    return sorted(result)

def frequency_counter(lst):
    """
    Returns a dictionary with the frequency of each unique integer in the list.

    :param lst: List of integers
    :return: Dictionary with integers as keys and their frequencies as values
    """
    freq_dict = {}
    for num in lst:
        if num in freq_dict:
            freq_dict[num] += 1
        else:
            freq_dict[num] = 1
    return freq_dict

