def most_frequent_char(s):
    """
    Returns the most frequently occurring character in the string s.
    In case of a tie, returns the character that appears first in the string.
    """
    from collections import Counter

    if not s:
        return None

    char_count = Counter(s)
    max_count = max(char_count.values())

    for char in s:
        if char_count[char] == max_count:
            return char

