def decode(cipher_text):
    """
    Decodes a message encoded with a mirrored alphabet cipher.

    Parameters:
    cipher_text (str): The encoded message to decode.

    Returns:
    str: The decoded message.
    """
    decoded_message = []

    for char in cipher_text:
        if 'a' <= char <= 'z':
            decoded_message.append(chr(219 - ord(char)))
        elif 'A' <= char <= 'Z':
            decoded_message.append(chr(155 - ord(char)))
        else:
            decoded_message.append(char)

    return ''.join(decoded_message)

# Example usage
# print(decode("Svool Dliow!"))  # Output: Hello World!

