def count_divisors(n):
    """
    Returns a list of integers representing the counts of the divisors of each number from 1 to n inclusive.
    """
    def count_divisors_of_num(num):
        count = 0
        for i in range(1, num + 1):
            if num % i == 0:
                count += 1
        return count

    return [count_divisors_of_num(i) for i in range(1, n + 1)]

