def ticket_sales(events):
    """
    Calculates the total number of tickets sold for each ticket type.

    Args:
    events (list of lists): A list of ticket sales events, where each event is a list [ticket_type, quantity].

    Returns:
    dict: A dictionary with ticket types as keys and total quantities as values.
    """
    ticket_summary = {}

    for event in events:
        ticket_type, quantity = event
        if ticket_type not in ['adult', 'child', 'senior', 'student', 'vip']:
            ticket_type = 'other'
        if ticket_type in ticket_summary:
            ticket_summary[ticket_type] += quantity
        else:
            ticket_summary[ticket_type] = quantity

    return ticket_summary

