def find_S(N):
    """
    Finds the value of S[N] according to the given sequence definition.
    """
    if N == 1:
        return 1

    # Using a dictionary to store computed values
    memo = {1: 1}

    # Helper function to calculate S(i) using memoization
    def S(i):
        if i in memo:
            return memo[i]
        if i % 2 == 0:
            memo[i] = S(i // 2)
        else:
            k = (i - 1) // 2
            memo[i] = S(k) + S(k + 1)
        return memo[i]

    return S(N)

