def char_frequencies(t, strings):
    """
    Returns the frequency of each character in the strings.

    Parameters:
    t (int): The number of test cases.
    strings (list of str): The strings for which to determine the frequencies.

    Returns:
    list of str: The frequencies of the characters in alphabetical order for each string.
    """
    results = []
    for s in strings:
        frequency = {}
        for char in s:
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

        sorted_chars = sorted(frequency.items())
        result = "\n".join(f"{char}: {count}" for char, count in sorted_chars)
        results.append(result)
    return "\n\n".join(results)

