def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes(n: int) -> int:
    """
    Returns the sum of the first n prime numbers.
    """
    count = 0
    sum_primes = 0
    num = 2
    while count < n:
        if is_prime(num):
            sum_primes += num
            count += 1
        num += 1
    return sum_primes

