from typing import List, Tuple

def largest_connected_component(matrix: List[List[int]], x: int, y: int) -> int:
    def dfs(matrix: List[List[int]], x: int, y: int, target: int, visited: set) -> int:
        if (x, y) in visited or x < 0 or y < 0 or x >= len(matrix) or y >= len(matrix[0]) or matrix[x][y] != target:
            return 0
        visited.add((x, y))
        size = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            size += dfs(matrix, x + dx, y + dy, target, visited)
        return size

    target = matrix[x][y]
    visited = set()
    return dfs(matrix, x, y, target, visited)

