def largest_balanced_substring(s):
    """
    Finds and returns the length of the largest balanced substring.
    A balanced substring is one in which the number of 'a's is equal
    to the number of 'b's.

    Parameters:
    s (str): The input string consisting of 'a's and 'b's.

    Returns:
    int: The length of the largest balanced substring.
    """
    longest = 0
    balance = 0
    balance_dict = {0: -1}

    for i, char in enumerate(s):
        if char == 'a':
            balance += 1
        else:
            balance -= 1

        if balance in balance_dict:
            longest = max(longest, i - balance_dict[balance])
        else:
            balance_dict[balance] = i

    return longest

