def cardGame(deck):
    """
    Determines the winner of the card game between John and Sarah.

    Args:
    deck (list): List of 52 strings representing the suits of the cards in the order they are drawn.
                Possible values are 'H' (Hearts), 'D' (Diamonds), 'C' (Clubs), and 'S' (Spades).

    Returns:
    str: "John", "Sarah", or "Draw" based on the scores.
    """
    john_score = 0
    sarah_score = 0

    points = {
        'H': 4,
        'D': 3,
        'C': 2,
        'S': 1
    }

    for i, card in enumerate(deck):
        if i % 2 == 0:  # John's turn (0, 2, 4, ...)
            john_score += points[card]
        else:           # Sarah's turn (1, 3, 5, ...)
            sarah_score += points[card]

    if john_score > sarah_score:
        return "John"
    elif sarah_score > john_score:
        return "Sarah"
    else:
        return "Draw"

def longest_repeated_substring(s):
    """
    Returns the longest substring which occurs more than once in the string s.
    If there are multiple substrings with the same maximum length, return the one that appears first.
    The comparison is case-sensitive.
    """
    n = len(s)
    longest_substring = ""

    for length in range(1, n):
        seen = {}
        for i in range(n - length + 1):
            substring = s[i:i+length]
            if substring in seen:
                seen[substring] += 1
            else:
                seen[substring] = 1

            if seen[substring] > 1 and len(substring) > len(longest_substring):
                longest_substring = substring

    return longest_substring

