def find_subarray_concatenations(t, test_cases):
    from collections import Counter

    def count_concatenations(s, words):
        word_length = len(words[0])
        num_words = len(words)
        concat_length = word_length * num_words
        word_count = Counter(words)

        result = 0
        for i in range(len(s) - concat_length + 1):
            seen_words = {}
            for j in range(num_words):
                part = s[i + j * word_length : i + (j + 1) * word_length]
                if part in word_count:
                    if part in seen_words:
                        seen_words[part] += 1
                    else:
                        seen_words[part] = 1
                    if seen_words[part] > word_count[part]:
                        break
                else:
                    break
            if seen_words == word_count:
                result += 1
        return result

    results = []
    for i in range(t):
        s = test_cases[i][0]
        words = test_cases[i][1]
        results.append(count_concatenations(s, words))

    return results

