def increasing_triplet(nums):
    """
    Returns true if there is a subsequence of length 3 that is strictly increasing, otherwise returns false.
    """
    first = second = float('inf')

    for num in nums:
        if num <= first:
            first = num
        elif num <= second:
            second = num
        else:
            return True

    return False

