def count_vowels(s):
    """
    Counts the number of vowels in the string s and returns a dictionary
    with vowels as keys and their counts as values. Case-insensitive.

    Parameters:
        s (str): The input string.

    Returns:
        dict: A dictionary with vowels and their counts.
    """
    vowels = "aeiou"
    vowel_count = {}

    # Convert the string to lowercase to handle case-insensitivity
    s = s.lower()

    for char in s:
        if char in vowels:
            if char in vowel_count:
                vowel_count[char] += 1
            else:
                vowel_count[char] = 1

    return vowel_count

