def vending_machine(items, transactions):
    """
    Simulates a vending machine transaction based on the provided items and transactions.

    Parameters:
    items (dict): Dictionary containing item names as keys and their prices in cents as values.
    transactions (list): List of tuples, each containing the item name and the amount of money inserted in cents.

    Returns:
    list: List containing results of each transaction.
          Each result is a tuple with the item name and either the remaining balance or a message "Insufficient funds".
    """
    result = []

    for item, money_inserted in transactions:
        if item in items:
            item_price = items[item]
            if money_inserted == item_price:
                result.append((item, 0))
            elif money_inserted > item_price:
                result.append((item, money_inserted - item_price))
            else:
                result.append((item, "Insufficient funds"))
        else:
            result.append((item, "Item not found"))

    return result

