from itertools import permutations

def differs_by_one_char(w1, w2):
    """
    Helper function to determine if two words differ by exactly one character.
    """
    if len(w1) != len(w2):
        return False
    count = 0
    for c1, c2 in zip(w1, w2):
        if c1 != c2:
            count += 1
            if count > 1:
                return False
    return count == 1

def special_permutation_exists(words):
    """
    Determines if there exists a permutation of words where every adjacent
    pair of words differs by exactly one character.
    """
    for perm in permutations(words):
        special = True
        for i in range(len(perm) - 1):
            if not differs_by_one_char(perm[i], perm[i + 1]):
                special = False
                break
        if special:
            return True
    return False

