def longest_increasing_sequence(nums):
    """
    Returns the length of the longest consecutive sequence of increasing numbers in the list `nums`.
    """
    if not nums:
        return 0

    longest = 0
    current_length = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            current_length += 1
        else:
            longest = max(longest, current_length)
            current_length = 1

    return max(longest, current_length)

