def total_weight(items):
    """
    Returns the total weight of all items in a possibly nested dictionary.

    Parameters:
    items (dict): A nested dictionary where the innermost values represent weights.

    Returns:
    int: The total weight of all items.
    """
    def recursive_sum(d):
        total = 0
        for value in d.values():
            if isinstance(value, dict):
                total += recursive_sum(value)
            else:
                total += value
        return total

    return recursive_sum(items)

