def can_distribute(weights, F, max_load):
    current_load = 0
    friends_used = 1

    for weight in weights:
        if current_load + weight > max_load:
            friends_used += 1
            current_load = weight
            if friends_used > F:
                return False
        else:
            current_load += weight

    return True

def minimize_maximum_load(T, test_cases):
    results = []
    for i in range(T):
        F = test_cases[i][0]
        S = test_cases[i][1]
        weights = test_cases[i][2]

        low, high = max(weights), sum(weights)
        while low < high:
            mid = (low + high) // 2
            if can_distribute(weights, F, mid):
                high = mid
            else:
                low = mid + 1

        results.append(low)

    return results

# Helper function to read the input data
def process_input(input_data):
    lines = input_data.strip().split('\n')
    T = int(lines[0])
    test_cases = []
    idx = 1
    for _ in range(T):
        F = int(lines[idx])
        S = int(lines[idx+1])
        weights = list(map(int, lines[idx+2].split()))
        test_cases.append((F, S, weights))
        idx += 3
    return T, test_cases

def two_sum(nums, target):
    """
    Returns the indices of the two numbers that add up to the target.

    :param nums: List[int] - List of integers
    :param target: int - Target sum
    :return: List[int] - Indices of the two numbers adding up to target
    """
    hashmap = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in hashmap:
            return [hashmap[complement], i]
        hashmap[num] = i

