def find_duplicates(arr):
    """
    Returns a list of duplicate elements from the input list arr, with duplicates
    reported only once in the order of their first appearance.
    """
    seen = set()
    duplicates = set()
    result = []

    for num in arr:
        if num in seen:
            if num not in duplicates:
                duplicates.add(num)
                result.append(num)
        else:
            seen.add(num)

    return result

