from typing import List, Tuple

def validate_task_order(order: str, constraints: List[Tuple[str, str]]) -> bool:
    """
    Validates if the given task order satisfies all the given constraints.
    """
    tasks = order.split("->")
    position = {task: index for index, task in enumerate(tasks)}

    for a, b in constraints:
        if position[a] >= position[b]:
            return False
    return True

