def can_escape(grid):
    from collections import deque

    rows = len(grid)
    cols = len(grid[0])

    # Find the starting point (S)
    start = (-1, -1)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 'S':
                start = (r, c)
                break
        if start != (-1, -1):
            break

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS to find the path
    queue = deque([start])
    visited = set()
    visited.add(start)

    while queue:
        r, c = queue.popleft()

        if grid[r][c] == 'E':
            return True

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited:
                if grid[nr][nc] == '.' or grid[nr][nc] == 'E':
                    queue.append((nr, nc))
                    visited.add((nr, nc))

    return False

