def longest_increasing_subsequence(heights):
    """
    Returns the length of the longest strictly increasing subsequence of heights.
    """
    if not heights:
        return 0

    # Array to store the length of the longest increasing subsequence up to each position
    lis = [1] * len(heights)

    # Build the `lis` array
    for i in range(1, len(heights)):
        for j in range(i):
            if heights[i] > heights[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)

