def min_elite_guards(N, M, u, v):
    """
    Returns the minimum number of elite guards needed to monitor all the tunnels in AlgoLandia.
    """
    from collections import defaultdict
    import itertools

    adjacency_list = defaultdict(set)
    for i in range(M):
        adjacency_list[u[i]].add(v[i])
        adjacency_list[v[i]].add(u[i])

    # Note: This converts to a vertex cover problem for the undirected graph
    def vertex_cover(adj_list):
        vc = [False] * (N + 1)
        degree = [0] * (N + 1)
        for key in adj_list:
            degree[key] = len(adj_list[key])

        result = 0
        for node in range(1, N + 1):
            if degree[node] > 0 and not vc[node]:
                for neighbor in adj_list[node]:
                    if not vc[neighbor]:
                        vc[node] = True
                        vc[neighbor] = True
                        result += 1
                        break

        return result

    return vertex_cover(adjacency_list)

from typing import List

def find_pair(nums: List[int], target: int) -> List[int]:
    """
    Returns a list containing two distinct numbers that add up to the target, in ascending order.
    If no such pair is found, returns an empty list.
    """
    # Dictionary to store the number and its index
    num_dict = {}
    for num in nums:
        complement = target - num
        if complement in num_dict:
            return sorted([num, complement])
        num_dict[num] = True
    return []

