def find_critical_districts(n, m, bridges):
    """
    Returns a list of all critical districts in the given city.
    """
    from collections import defaultdict

    def dfs(v, visited, low, disc, parent, graph, aps, time):
        children = 0
        visited[v] = True
        disc[v] = time
        low[v] = time
        time += 1

        for to in graph[v]:
            if not visited[to]:
                parent[to] = v
                children += 1
                dfs(to, visited, low, disc, parent, graph, aps, time)

                low[v] = min(low[v], low[to])

                if parent[v] == -1 and children > 1:
                    aps.add(v)
                if parent[v] != -1 and low[to] >= disc[v]:
                    aps.add(v)
            elif to != parent[v]:
                low[v] = min(low[v], disc[to])

    visited = [False] * n
    disc = [float('inf')] * n
    low = [float('inf')] * n
    parent = [-1] * n
    aps = set()

    graph = defaultdict(list)
    for u, v in bridges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    for i in range(n):
        if not visited[i]:
            dfs(i, visited, low, disc, parent, graph, aps, 0)

    return sorted(list(map(lambda x: x + 1, aps)))

