def final_position(commands: str) -> tuple:
    """
    Calculates the final position of the robot given a series of movement commands.

    Parameters:
    commands (str): A string consisting of 'U', 'D', 'L', 'R' which represent Up, Down, Left, and Right moves.

    Returns:
    tuple: A tuple (x, y) representing the final coordinates after executing the commands.
    """
    x, y = 0, 0

    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return (x, y)

