def min_operations_to_equivalent_grid(test_cases):
    results = []

    for case in test_cases:
        N = case['N']
        grid = case['grid']

        max_val = max(map(max, grid))
        operations = 0

        for i in range(N):
            for j in range(N):
                operations += max_val - grid[i][j]

        results.append(operations)

    return results

def parse_input(input_str):
    lines = input_str.strip().split("\n")
    T = int(lines[0])
    test_cases = []

    idx = 1
    for _ in range(T):
        N = int(lines[idx])
        grid = []
        for i in range(N):
            grid.append(list(map(int, lines[idx + 1 + i].split())))
        test_cases.append({'N': N, 'grid': grid})
        idx += 1 + N

    return test_cases

