from collections import defaultdict, deque

def find_order(num_tasks, prerequisites):
    """
    Determine if it is possible to complete all tasks given prerequisites.
    If possible, return the order of tasks; otherwise, return an empty list.
    """
    in_degree = {i: 0 for i in range(num_tasks)}
    graph = defaultdict(list)

    for dest, src in prerequisites:
        graph[src].append(dest)
        in_degree[dest] += 1

    queue = deque([node for node in range(num_tasks) if in_degree[node] == 0])
    ordered_tasks = []

    while queue:
        node = queue.popleft()
        ordered_tasks.append(node)

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(ordered_tasks) == num_tasks:
        return ordered_tasks
    else:
        return []

