def find_islands(users, follow_relationships):
    from collections import defaultdict

    # Building the adjacency list
    adj_list = defaultdict(set)
    for follower, followee in follow_relationships:
        adj_list[follower].add(followee)
        adj_list[followee].add(follower)  # Since we need to consider bi-directional reachability

    # DFS to find all connected components
    def dfs(node, visited, island):
        visited[node] = True
        island.add(node)
        for neighbor in adj_list[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, island)

    visited = {user: False for user in users}
    islands = []

    for user in users:
        if not visited[user]:
            island = set()
            dfs(user, visited, island)
            islands.append(island)

    return islands

