def count_subordinates(N, M, relationships, Q, queries):
    from collections import defaultdict, deque

    # Build the adjacency list for the tree
    subordinates = defaultdict(list)
    for u, v in relationships:
        subordinates[u].append(v)

    # Function to use DFS to count subordinates for each node
    def dfs_count(node):
        stack = [node]
        visited = set()
        count = 0
        while stack:
            current = stack.pop()
            if current not in visited:
                visited.add(current)
                count += 1
                for neighbor in subordinates[current]:
                    if neighbor not in visited:
                        stack.append(neighbor)
        return count - 1  # exclude the manager node itself

    # Pre-compute the results for each query
    results = {}
    for xi in queries:
        if xi not in results:
            results[xi] = dfs_count(xi)

    return [results[xi] for xi in queries]

def process_queries(S, queries):
    results = []
    for Li, Ri, Ci in queries:
        if Ci in S[Li-1:Ri]:
            results.append("YES")
        else:
            results.append("NO")
    return results

