def max_odd_rows_with_flips(n, m, k, grid):
    from collections import defaultdict

    # Count the number of heads in each row
    row_heads = [sum(row) for row in grid]

    # Function to calculate how many rows have an odd number of heads
    def count_odd_rows(row_heads):
        return sum(1 for head_count in row_heads if head_count % 2 == 1)

    # Initial count of rows with odd number of heads
    initial_odd_rows = count_odd_rows(row_heads)

    # To keep track of maximum rows with odd number of heads
    max_odd_rows = initial_odd_rows

    # Flip positions mapped to rows they affect to maximum advantage
    flip_effects = defaultdict(int)

    for row in range(n):
        for col in range(m):
            flip_effects[(row, col)] = 0

    for flip_count in range(k + 1):
        possible_flips = []

        for row in range(n):
            for col in range(m):
                flips_needed = (((row_heads[row] + grid[row][col]) % 2) != 0)
                possible_flips.append((flips_needed, row, col))

        possible_flips.sort(reverse=True)

        for _, row, col in possible_flips[:flip_count]:
            grid[row][col] = 1 - grid[row][col]

        flipped_heads = [sum(row) for row in grid]
        max_odd_rows = max(max_odd_rows, count_odd_rows(flipped_heads))

    return max_odd_rows

