def longest_fertile_line(m, n, grid):
    def search_direction(x, y, dx, dy):
        length = 0
        while 0 <= x < m and 0 <= y < n and grid[x][y] == 'F':
            length += 1
            x += dx
            y += dy
        return length

    max_length = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 'F':
                max_length = max(max_length, search_direction(i, j, 1, 0))  # vertical down
                max_length = max(max_length, search_direction(i, j, 0, 1))  # horizontal right
                max_length = max(max_length, search_direction(i, j, 1, 1))  # diagonal down-right
                max_length = max(max_length, search_direction(i, j, 1, -1)) # diagonal down-left

    return max_length

