def max_in_list_after_operations(operations):
    """
    Returns the maximum integer in the list after performing all operations.
    If the list is empty, returns "EMPTY".
    """
    current_list = []
    for operation in operations:
        op, num = operation.split()
        num = int(num)

        if op == "add":
            current_list.append(num)
        elif op == "remove":
            if num in current_list:
                current_list.remove(num)

    if current_list:
        return max(current_list)
    else:
        return "EMPTY"

