def edit_distance(n, m, s, t):
    """
    Compute the minimum number of operations required to convert string s into string t.
    """
    # Create a DP table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the table with base cases
    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0:
                dp[i][j] = j  # If s is empty, we need to insert all characters of t
            elif j == 0:
                dp[i][j] = i  # If t is empty, we need to delete all characters of s
            elif s[i-1] == t[j-1]:
                dp[i][j] = dp[i-1][j-1]  # If characters are same, no new operation needed
            else:
                dp[i][j] = 1 + min(dp[i-1][j],    # Deletion
                                   dp[i][j-1],    # Insertion
                                   dp[i-1][j-1])  # Replacement

    return dp[n][m]

