def longest_subarray_with_at_most_k_evens(arr, k):
    """
    Returns the length of the longest contiguous subarray that contains at most k even numbers.
    """
    n = len(arr)
    left = 0
    even_count = 0
    max_length = 0

    for right in range(n):
        if arr[right] % 2 == 0:
            even_count += 1

        while even_count > k:
            if arr[left] % 2 == 0:
                even_count -= 1
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

# Function to parse input and call the main logic
def main(n, k, arr):
    return longest_subarray_with_at_most_k_evens(arr, k)

