def identify_items_to_restock(w, t, warehouse_data):
    restock_items = set()

    for warehouse in warehouse_data:
        for item_id, quantity in warehouse:
            if quantity < t:
                restock_items.add(item_id)

    return sorted(restock_items)

# Helper function to parse given input structure
def parse_input(input_data):
    input_lines = input_data.strip().split('\n')
    w, t = map(int, input_lines[0].split())
    warehouse_data = []

    for i in range(1, w + 1):
        items = list(map(int, input_lines[i].split()))
        k = items[0]
        warehouse_info = [(items[j], items[j + 1]) for j in range(1, 2 * k, 2)]
        warehouse_data.append(warehouse_info)

    return w, t, warehouse_data

def first_missing_positive(arr):
    """
    Returns the first missing positive integer from the array.
    """
    n = len(arr)

    # Step 1: Replace negative numbers and zeros with n+1
    for i in range(n):
        if arr[i] <= 0:
            arr[i] = n + 1

    # Step 2: Use the array indices as a way of marking present positive numbers
    for i in range(n):
        num = abs(arr[i])
        if num <= n:
            arr[num - 1] = -abs(arr[num - 1])  # Mark the value at this index as negative

    # Step 3: Find the first index which is positive
    for i in range(n):
        if arr[i] > 0:
            return i + 1

    # If all indices are marked, then return n + 1
    return n + 1

