def partition_list(arr):
    total_sum = sum(arr)
    n = len(arr)

    dp = [[False] * (total_sum // 2 + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(total_sum // 2 + 1):
            dp[i][j] = dp[i - 1][j]
            if j >= arr[i - 1]:
                dp[i][j] = dp[i][j] or dp[i - 1][j - arr[i - 1]]

    for j in range(total_sum // 2, -1, -1):
        if dp[n][j]:
            return total_sum - 2 * j

