def findWords(grid, words):
    """
    Returns the list of words that can be found in the grid.
    """
    def dfs(x, y, node, path):
        letter = grid[x][y]
        curr_child = node[letter]

        if "end" in curr_child:
            result.append(path)
            curr_child.pop("end")  # To avoid repeated addition

        grid[x][y] = '#'

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] in curr_child:
                dfs(nx, ny, curr_child, path + grid[nx][ny])

        grid[x][y] = letter


    def build_trie(words):
        root = {}
        for word in words:
            node = root
            for letter in word:
                node = node.setdefault(letter, {})
            node["end"] = True
        return root

    result = []
    trie = build_trie(words)

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] in trie:
                dfs(i, j, trie, grid[i][j])

    return result

from typing import List

def longest_subsequence_with_constant_diff(arr: List[int]) -> int:
    """
    Finds the length of the longest subsequence such that the difference between consecutive elements is the same.
    """
    if not arr:
        return 0

    n = len(arr)
    diff_map = {}

    for i in range(n):
        for j in range(i+1, n):
            diff = arr[j] - arr[i]
            if (i, diff) in diff_map:
                diff_map[(j, diff)] = diff_map[(i, diff)] + 1
            else:
                diff_map[(j, diff)] = 2

    return max(diff_map.values(), default=1)

