def max_product_after_changes(nums, k):
    """
    Returns the maximum possible product of the list after making at most k changes.
    """
    n = len(nums)

    if k == 0:
        # No changes allowed, return the product of current list.
        result = 1
        for num in nums:
            result *= num
        return result

    if n == 1:
        # If list contains only one element, the product is the element itself.
        return nums[0]

    def product(lst):
        result = 1
        for num in lst:
            result *= num
        return result

    max_product = float('-inf')
    for i in range(n):
        for j in range(i, min(i+2, n)):
            new_list = nums[:i] + nums[i:j+1][::-1] + nums[j+1:]
            max_product = max(max_product, product(new_list))

    return max_product

