from collections import defaultdict, deque

def alien_order(words):
    # Create a graph and a degree dictionary
    graph = defaultdict(set)  # To store the adjacency list representation of the graph
    in_degree = {char: 0 for word in words for char in word}  # In-degree of each node/character

    # Build the graph
    for i in range(len(words) - 1):
        first_word = words[i]
        second_word = words[i+1]
        min_len = min(len(first_word), len(second_word))

        # Find the first different character and create the edges
        for j in range(min_len):
            if first_word[j] != second_word[j]:
                if second_word[j] not in graph[first_word[j]]:
                    graph[first_word[j]].add(second_word[j])
                    in_degree[second_word[j]] += 1
                break
        else:
            if len(first_word) > len(second_word):
                return ""

    # Topological Sort (Kahn's algorithm)
    queue = deque([char for char in in_degree if in_degree[char] == 0])
    ordered_chars = []

    while queue:
        current_char = queue.popleft()
        ordered_chars.append(current_char)

        for neighbor in graph[current_char]:
            in_degree[neighbor] -= 1  # Remove edge
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If we have ordered all characters, return the order
    if len(ordered_chars) == len(in_degree):
        return ''.join(ordered_chars)
    else:
        return ""

