def unique_paths(H, W, grid):
    """
    This function calculates the number of unique paths
    from the top-left to the bottom-right of a grid.
    """
    if grid[0][0] == '#' or grid[H-1][W-1] == '#':
        return 0

    dp = [[0] * W for _ in range(H)]
    dp[0][0] = 1

    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[H-1][W-1]


def parse_input(input_string):
    """
    Parses the input string and returns H, W, and the grid.
    """
    lines = input_string.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = [list(line) for line in lines[1:]]
    return H, W, grid

def length_of_lis(arr):
    import bisect
    lis = []
    for num in arr:
        pos = bisect.bisect_left(lis, num)
        if pos == len(lis):
            lis.append(num)
        else:
            lis[pos] = num
    return len(lis)

