def longest_subsequence_with_all_characters(dna_sequence):
    """
    Finds the length of the longest subsequence where each character 'A', 'T', 'C', and 'G' appears at least once.
    If no such subsequence exists, returns -1.
    """
    required_chars = {'A', 'T', 'C', 'G'}
    present_chars = set(dna_sequence)

    if not required_chars.issubset(present_chars):
        return -1

    return len(dna_sequence)

