def knapsack(n, W, values, weights):
    # Initialize the dp array with zeros
    dp = [0] * (W + 1)

    # Iterate through all items
    for i in range(n):
        # Update the dp array from end to start
        for w in range(W, weights[i] - 1, -1):
            dp[w] = max(dp[w], dp[w - weights[i]] + values[i])

    return dp[W]

