def modify_matrix(matrix):
    n = len(matrix)
    m = len(matrix[0])

    rows_to_update = set()
    cols_to_update = set()

    # First pass to find the rows and columns that need to be updated
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == 1:
                rows_to_update.add(i)
                cols_to_update.add(j)

    # Apply the updates to rows
    for row in rows_to_update:
        for j in range(m):
            matrix[row][j] = 1

    # Apply the updates to columns
    for col in cols_to_update:
        for i in range(n):
            matrix[i][col] = 1

    return matrix

def smallest_x(a, b):
    """
    Returns the smallest non-negative integer x such that (a + x) % b == 0
    """
    remainder = a % b
    if remainder == 0:
        return 0
    else:
        return b - remainder

