def minimum_space_stations(n, m, highways):
    from collections import defaultdict, deque

    # Create a graph
    graph = defaultdict(list)

    for u, v in highways:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    # Find all connected components
    components = 0
    for i in range(1, n + 1):
        if not visited[i]:
            components += 1
            bfs(i)

    return components

