def max_steal(house_values):
    """
    Returns the maximum amount of money that can be stolen without stealing from two adjacent houses.
    """
    n = len(house_values)
    if n == 0:
        return 0
    if n == 1:
        return house_values[0]

    dp = [0] * n
    dp[0] = house_values[0]
    if n > 1:
        dp[1] = max(house_values[0], house_values[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + house_values[i])

    return dp[-1]

