def max_sub_array_sum(arr, queries):
    def kadane(arr):
        max_sum = float('-inf')
        current_sum = 0
        for value in arr:
            current_sum = max(value, current_sum + value)
            max_sum = max(max_sum, current_sum)
        return max_sum

    results = []
    for l, r in queries:
        sub_array = arr[l-1:r]
        results.append(kadane(sub_array))

    return results

import heapq

def find_shortest_paths(n, m, roads):
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, t in roads:
        graph[u].append((v, t))

    # Dijkstra's algorithm to find the shortest paths from the central node (1)
    def dijkstra(start):
        distances = {i: float('inf') for i in range(1, n + 1)}
        distances[start] = 0
        priority_queue = [(0, start)]  # (distance, node)

        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))

        return distances

    shortest_paths = dijkstra(1)
    result = []

    for i in range(1, n + 1):
        if shortest_paths[i] == float('inf'):
            result.append("INF")
        else:
            result.append(shortest_paths[i])

    return result

