def process_transactions(n, transactions):
    inventory = {}

    for transaction in transactions:
        action, item_id, count = transaction[0], transaction[1], int(transaction[2])
        if action == "add":
            if item_id in inventory:
                inventory[item_id] += count
            else:
                inventory[item_id] = count
        elif action == "remove":
            if item_id in inventory:
                if inventory[item_id] >= count:
                    inventory[item_id] -= count
                # If removal tries to take more than available, do nothing
        # If the action has to be ignored, it does nothing

    sorted_inventory = sorted(inventory.items())
    return [(item, count) for item, count in sorted_inventory]

def min_monotonically_increasing_subarrays(nums):
    """
    Returns the minimum number of monotonically increasing subarrays needed
    to partition the given array.
    """
    count = 1
    for i in range(1, len(nums)):
        if nums[i] < nums[i-1]:
            count += 1
    return count

