def find_final_coordinates(directions):
    """
    Given a string of directions, returns the final coordinates on a 2D plane starting from (0, 0).
    """
    x, y = 0, 0

    for direction in directions:
        if direction == 'L':
            x -= 1
        elif direction == 'R':
            x += 1
        elif direction == 'U':
            y += 1
        elif direction == 'D':
            y -= 1

    return (x, y)

