def surviving_trees(trees):
    while True:
        new_trees = [trees[0]]
        for i in range(1, len(trees)):
            if trees[i] <= trees[i-1]:
                new_trees.append(trees[i])
        if len(new_trees) == len(trees):
            return len(new_trees)
        trees = new_trees

def solution(test_cases):
    results = []
    for t in test_cases:
        N, heights = t
        results.append(surviving_trees(heights))
    return results

def read_input(input_str):
    input_lines = input_str.strip().split('\n')
    T = int(input_lines[0])
    test_cases = []
    line_idx = 1
    for _ in range(T):
        N = int(input_lines[line_idx])
        heights = list(map(int, input_lines[line_idx + 1].split()))
        test_cases.append((N, heights))
        line_idx += 2
    return test_cases

def process_commands(commands):
    stack = []
    result = []

    for command in commands:
        if command.startswith("push"):
            _, x = command.split()
            stack.append(int(x))
        elif command == "pop":
            if stack:
                result.append(stack.pop())
            else:
                result.append("EMPTY")
        elif command.startswith("inc"):
            _, k, x = command.split()
            k = int(k)
            x = int(x)
            for i in range(min(k, len(stack))):
                stack[i] += x

    return result

import heapq

def min_time_to_attend_patients(N, M, patient_times):
    """
    Determines the minimum time required for all doctors to attend to all patients at least once.
    """
    if N >= M:
        return max(patient_times)

    patient_times.sort(reverse=True)
    doctors = [0] * N
    heapq.heapify(doctors)

    for time in patient_times:
        earliest_available = heapq.heappop(doctors)
        heapq.heappush(doctors, earliest_available + time)

    return max(doctors)

