def find_most_influential_employee(employee_list):
    from collections import defaultdict

    # Build an adjacency list to represent the management tree
    tree = defaultdict(list)
    root = None

    for employee_id, manager_id in employee_list:
        if manager_id == -1:
            root = employee_id
        else:
            tree[manager_id].append(employee_id)

    # Function to count subordinates for each node
    def count_subordinates(node):
        if node not in tree:
            return 0
        count = 0
        for child in tree[node]:
            count += 1 + count_subordinates(child)
        return count

    # Determine the employee with the maximum number of subordinates
    max_subordinates = -1
    influential_employee = None

    for employee, _ in employee_list:
        sub_count = count_subordinates(employee)
        if sub_count > max_subordinates:
            max_subordinates = sub_count
            influential_employee = employee

    return influential_employee

