def min_swaps_to_bring_ones_together(n, arr):
    num_ones = sum(arr)
    if num_ones == 0 or num_ones == n:
        return 0

    max_ones_in_window = 0
    current_ones_count = 0

    for i in range(num_ones):
        current_ones_count += arr[i]

    max_ones_in_window = current_ones_count

    for i in range(num_ones, n):
        current_ones_count += arr[i] - arr[i - num_ones]
        max_ones_in_window = max(max_ones_in_window, current_ones_count)

    return num_ones - max_ones_in_window

def min_swaps_for_all_cases(test_cases):
    results = []
    for n, arr in test_cases:
        results.append(min_swaps_to_bring_ones_together(n, arr))
    return results

def find_longest_active_sequence(T, test_cases):
    """
    T: The number of test cases.
    test_cases: A list of tuples, each tuple contains an integer N, followed by list of N integers (either 0 or 1)
    """
    results = []
    for case in test_cases:
        N, statuses = case
        max_length = 0
        max_start_idx = -1
        curr_length = 0
        curr_start_idx = -1

        for i in range(N):
            if statuses[i] == 1:
                if curr_length == 0:
                    curr_start_idx = i
                curr_length += 1
            else:
                if curr_length > max_length:
                    max_length = curr_length
                    max_start_idx = curr_start_idx
                curr_length = 0

        # Final check in case the longest sequence ends at the last element
        if curr_length > max_length:
            max_length = curr_length
            max_start_idx = curr_start_idx

        if max_length == 0:
            results.append("No active sequence found")
        else:
            results.append(f"{max_start_idx} {max_start_idx + max_length - 1}")

    return results

def can_return_to_origin(s):
    """
    Determines if the robot can return to the origin after k full repetitions of the instruction sequence.
    """
    x, y = 0, 0

    for char in s:
        if char == 'L':
            x -= 1
        elif char == 'R':
            x += 1
        elif char == 'U':
            y += 1
        elif char == 'D':
            y -= 1

    if x == 0 and y == 0:
        return "YES"
    else:
        return "NO"

