def min_sweet_difference(n, s):
    total_sum = sum(s)
    half_sum = total_sum // 2

    # Create a DP array to store the possible subset sums
    dp = [False] * (half_sum + 1)
    dp[0] = True

    for sweetness in s:
        for j in range(half_sum, sweetness - 1, -1):
            if dp[j - sweetness]:
                dp[j] = True

    # Find the largest value which can be reached
    # that is <= half_sum
    for i in range(half_sum, -1, -1):
        if dp[i]:
            subset_sum1 = i
            break

    subset_sum2 = total_sum - subset_sum1
    return abs(subset_sum2 - subset_sum1)

