def is_almost_palindrome(s):
    """
    Determine whether the string can be converted into a palindrome by removing at most one character.
    """
    def is_palindrome_range(s, left, right):
        while left < right:
            if s[left] != s[right]:
                return False
            left += 1
            right -= 1
        return True

    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            return is_palindrome_range(s, left+1, right) or is_palindrome_range(s, left, right-1)
        left += 1
        right -= 1

    return True

