def longest_ap_length(gems):
    if len(gems) == 1:
        return 1

    gems.sort()
    n = len(gems)

    # Create a dictionary to store the lengths of APs
    dp = [{} for _ in range(n)]
    max_length = 1

    for j in range(n):
        for i in range(j):
            diff = gems[j] - gems[i]
            if diff in dp[i]:
                dp[j][diff] = dp[i][diff] + 1
            else:
                dp[j][diff] = 2

            max_length = max(max_length, dp[j][diff])

    return max_length

def max_ap_lengths(test_cases):
