from itertools import permutations

def query_edge(graph, u, v):
    return "Yes" if graph[u-1][v-1] == 1 else "No"

def find_hamiltonian_path(n, graph):
    nodes = range(1, n + 1)

    for perm in permutations(nodes):
        is_path = True
        for i in range(n - 1):
            u, v = perm[i], perm[i+1]
            if query_edge(graph, u, v) == "No":
                is_path = False
                break
        if is_path:
            return "Yes"
    return "No"

