def robot_return_to_origin(movements):
    """
    Determines if the robot returns to the origin after executing the movements.

    Parameters:
    - movements (str): A string of characters 'L', 'R', 'U', 'D'.

    Returns:
    - str: "YES" if the robot returns to the origin, otherwise "NO".
    """
    x, y = 0, 0

    for move in movements:
        if move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    return "YES" if x == 0 and y == 0 else "NO"

