from typing import List

def count_subarrays(distances: List[int], k: int, D: int) -> int:
    count = 0
    n = len(distances)

    current_sum = sum(distances[:k])
    if current_sum / k >= D:
        count += 1

    for i in range(k, n):
        current_sum = current_sum - distances[i - k] + distances[i]
        if current_sum / k >= D:
            count += 1

    return count

def countRegions(m, n, grid):
    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if 0 <= cx < m and 0 <= cy < n and grid[cx][cy] == '0':
                grid[cx][cy] = '2'  # Mark this cell as visited
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    stack.append((cx + dx, cy + dy))

    region_count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '0':
                dfs(i, j)
                region_count += 1
    return region_count

def max_sum_kxk_submatrix(matrix, n, m, k):
    max_sum = float('-inf')

    # Compute sum of all k x k submatrices
    for i in range(n - k + 1):
        for j in range(m - k + 1):
            current_sum = 0
            for a in range(k):
                for b in range(k):
                    current_sum += matrix[i + a][j + b]
            max_sum = max(max_sum, current_sum)

    return max_sum

