def can_reach_target_with_stops(N, M, S, connections):
    from collections import defaultdict, deque

    # Build the adjacency list
    adj_list = defaultdict(list)
    for a, b in connections:
        adj_list[a].append(b)
        adj_list[b].append(a)

    # Use BFS to check if it's possible to reach node N using exactly S steps
    queue = deque([(1, 0)])  # (current_position, current_steps)
    visited = defaultdict(set)  # Store steps and positions to prevent re-visiting

    while queue:
        position, steps = queue.popleft()

        if steps == S:
            if position == N:
                return "yes"
            continue

        if S - steps > (N - 1):  # More stops than potentially required, skip.
            continue

        for neighbor in adj_list[position]:
            if steps + 1 not in visited[neighbor]:
                visited[neighbor].add(steps + 1)
                queue.append((neighbor, steps + 1))

    return "no"

def process_test_cases(input_data):
    results = []
    i = 0
    while i < len(input_data):
        N, M, S = map(int, input_data[i].split())
        if N == 0 and M == 0 and S == 0:
            break
        connections = []
        for j in range(1, M+1):
            connections.append(tuple(map(int, input_data[i+j].split())))
        results.append(can_reach_target_with_stops(N, M, S, connections))
        i += M + 1
    return results

