def longest_even_odd_subseq(arr):
    """
    Returns the length of the longest contiguous subsequence with an equal number
    of even and odd numbers.
    """
    n = len(arr)
    # Dictionary to store the first occurrence of each diff value
    diff_map = {0: -1}
    max_len = 0
    diff = 0  # This will store the difference of counts of even and odd numbers

    for i in range(n):
        if arr[i] % 2 == 0:
            diff += 1  # Even number
        else:
            diff -= 1  # Odd number

        if diff in diff_map:
            max_len = max(max_len, i - diff_map[diff])
        else:
            diff_map[diff] = i

    return max_len

