def three_sum(nums, target):
    """
    Determines if there are three distinct indices i, j, k in nums such that the sum at these indexes equals target.
    """
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, n - 1
        while left < right:
            summation = nums[i] + nums[left] + nums[right]
            if summation == target:
                return "YES"
            elif summation < target:
                left += 1
            else:
                right -= 1

    return "NO"

