import collections

def can_assign(preferences, N, M, limit):
    counters = [0] * M
    for pref in preferences:
        assigned = False
        for i in range(M):
            project_index = pref[i] - 1
            if counters[project_index] < limit:
                counters[project_index] += 1
                assigned = True
                break
        if not assigned:
            return False
    return True

def find_minimum_maximum(N, M, preferences):
    left, right = 1, N
    result = N
    while left <= right:
        mid = (left + right) // 2
        if can_assign(preferences, N, M, mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1
    return result

def main(input_str):
    data = input_str.strip().split('\n')
    N, M = map(int, data[0].split())
    preferences = [list(map(int, line.split())) for line in data[1:]]
    return find_minimum_maximum(N, M, preferences)

def maximalRectangle(matrix):
    if not matrix:
        return 0

    max_area = 0
    dp = [0] * len(matrix[0])

    for row in matrix:
        for j in range(len(row)):
            dp[j] = dp[j] + 1 if row[j] == 1 else 0

        max_area = max(max_area, largestRectangleArea(dp))

    return max_area


def largestRectangleArea(heights):
    stack = [-1]
    max_area = 0

    for i in range(len(heights)):
        while stack[-1] != -1 and heights[stack[-1]] >= heights[i]:
            height = heights[stack.pop()]
            width = i - stack[-1] - 1
            max_area = max(max_area, height * width)
        stack.append(i)

    while stack[-1] != -1:
        height = heights[stack.pop()]
        width = len(heights) - stack[-1] - 1
        max_area = max(max_area, height * width)

    return max_area

