def are_anagrams(s1, s2):
    """
    Determines if two strings s1 and s2 are anagrams of each other.
    """
    # Normalize the strings by converting to lowercase and removing spaces
    normalized_s1 = ''.join(s1.lower().split())
    normalized_s2 = ''.join(s2.lower().split())

    # Count the frequency of each character
    return sorted(normalized_s1) == sorted(normalized_s2)

