def find_longest_valid_word(s, n, words):
    from collections import Counter

    s_count = Counter(s)

    def is_valid(word):
        word_count = Counter(word)
        for letter in word_count:
            if word_count[letter] > s_count.get(letter, 0):
                return False
        return True

    longest_word = ""

    for word in words:
        if is_valid(word):
            if len(word) > len(longest_word) or (len(word) == len(longest_word) and word < longest_word):
                longest_word = word

    return longest_word

