def longest_even_sum_subsequence(test_cases):
    results = []

    for case in test_cases:
        n, seq = case[0], case[1:]
        seq_sum = sum(seq)

        if seq_sum % 2 == 0:
            results.append(n)
        else:
            # If there is any odd number in the sequence
            odd_present = any(x % 2 != 0 for x in seq)
            if odd_present:
                results.append(n - 1)
            else:
                # If there's no odd number, we can't make the sum even
                results.append(0)

    return results

