def can_transform(array):
    n = len(array)
    if n <= 2:
        return True

    def is_sorted(subarray):
        return all(subarray[i] <= subarray[i + 1] for i in range(len(subarray) - 1))

    # Try partition array in every place and check if that makes the array sorted
    for i in range(n - 1):
        left = array[:i + 1]
        right = array[i + 1:]
        if is_sorted(sorted(left) + sorted(right)):
            return True
    return False

def process_test_cases(t, test_cases):
    results = []
    for n, array in test_cases:
        if can_transform(array):
            results.append("YES")
        else:
            results.append("NO")
    return results

