from collections import defaultdict, deque

def count_unique_paths(n, m, roads, start, end):
    """
    Returns the number of unique paths from start to end.

    n : int : number of cities
    m : int : number of one-way roads
    roads : List[Tuple[int, int]] : list of one-way roads represented as tuples (a, b)
    start : int : starting city
    end : int : destination city
    """
    graph = defaultdict(list)
    for a, b in roads:
        graph[a].append(b)

    def count_paths(graph, start, end):
        queue = deque([(start, set())])
        unique_paths_count = 0
        while queue:
            current_city, visited_roads = queue.popleft()
            if current_city == end:
                unique_paths_count += 1
                continue
            for next_city in graph[current_city]:
                if (current_city, next_city) not in visited_roads:
                    new_visited_roads = visited_roads | {(current_city, next_city)}
                    queue.append((next_city, new_visited_roads))
        return unique_paths_count

    return count_paths(graph, start, end)

