def rle_compress(s: str) -> str:
    if not s:
        return ""

    result = []
    count = 1
    prev_char = s[0]

    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            if count > 1:
                result.append(f"{prev_char}({count})")
            else:
                result.append(prev_char)
            prev_char = char
            count = 1

    # Add the last run
    if count > 1:
        result.append(f"{prev_char}({count})")
    else:
        result.append(prev_char)

    return "".join(result)

