def min_popularity_score_difference(n, popularity):
    total_popularity = sum(popularity)
    half_total_popularity = total_popularity // 2

    dp = [[False] * (half_total_popularity + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(half_total_popularity + 1):
            dp[i][j] = dp[i-1][j]
            if j >= popularity[i-1]:
                dp[i][j] = dp[i][j] or dp[i-1][j-popularity[i-1]]

    for j in range(half_total_popularity, -1, -1):
        if dp[n][j]:
            return total_popularity - 2 * j

