def count_components(n, roads):
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootX] = rootY

    for u, v in roads:
        union(u - 1, v - 1)

    return len(set(find(x) for x in range(n)))

def minimum_additional_roads(n, m, roads):
    # Count the number of connected components
    connected_components = count_components(n, roads)

    # Number of roads to add is number of disjoint components minus 1
    return connected_components - 1

