from collections import deque

def min_moves_to_reach_target(m, n, grid, sr, sc, tr, tc):
    if grid[sr][sc] == 1 or grid[tr][tc] == 1:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(sr, sc, 0)])  # (current row, current column, current move count)
    visited = set((sr, sc))

    while queue:
        r, c, moves = queue.popleft()

        if (r, c) == (tr, tc):
            return moves

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited and grid[nr][nc] == 0:
                queue.append((nr, nc, moves + 1))
                visited.add((nr, nc))

    return -1

def create_playlist(songs):
    songs.sort(key=lambda x: x[2])

    playlist = []
    last_artist = None

    while songs:
        for i, song in enumerate(songs):
            if song[1] != last_artist:
                playlist.append(song[0])
                last_artist = song[1]
                songs.pop(i)
                break
        else:
            # If no valid song is found, it means it's not possible to create the playlist
            return "Not possible."

    return " ".join(playlist)

def process_input(data):
    n = int(data[0])
    songs = [tuple(data[i].split()) for i in range(1, n + 1)]
    for i in range(n):
        songs[i] = (songs[i][0], songs[i][1], int(songs[i][2]))
    return songs

