from collections import deque

def min_moves_with_magic_wand(grid):
    N = len(grid)
    if N == 0:
        return -1

    def in_bounds(x, y):
        return 0 <= x < N and 0 <= y < N

    def bfs(start_x, start_y, can_use_wand):
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        queue = deque([(start_x, start_y, 0, can_use_wand)])
        visited = set((start_x, start_y, can_use_wand))

        while queue:
            x, y, dist, wand_left = queue.popleft()
            if (x, y) == (N-1, N-1):
                return dist

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if in_bounds(nx, ny):
                    next_pos = (nx, ny, wand_left)
                    if wand_left and grid[nx][ny] == '#':
                        next_pos_with_wand = (nx, ny, False)
                        if next_pos_with_wand not in visited:
                            visited.add(next_pos_with_wand)
                            queue.append((nx, ny, dist + 1, False))
                    if grid[nx][ny] == '.' and next_pos not in visited:
                        visited.add(next_pos)
                        queue.append((nx, ny, dist + 1, wand_left))
        return -1  # No path found

    return bfs(0, 0, True)

