def floyd_warshall(n, graph):
    dist = [[float('inf')] * n for _ in range(n)]

    for u in range(n):
        for v in range(n):
            dist[u][v] = graph[u][v]

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

def find_minimum_distances(T, test_cases):
    results = []

    for case in test_cases:
        N, M, roads, Q, queries = case
        graph = [[float('inf')] * N for _ in range(N)]

        for i in range(N):
            graph[i][i] = 0

        for u, v, d in roads:
            graph[u-1][v-1] = d
            graph[v-1][u-1] = d

        dist = floyd_warshall(N, graph)

        for u, v in queries:
            distance = dist[u-1][v-1]
            results.append(distance if distance != float('inf') else -1)

    return results

