def is_prime(n):
    """
    Returns True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes_subarray(arr, L, R):
    """
    Returns the sum of prime numbers in the subarray defined by the indices L and R (inclusive).
    """
    return sum(x for x in arr[L-1:R] if is_prime(x))

def process_queries(arr, queries):
    """
    Processes each query and returns the results as a list.
    """
    results = []
    for L, R in queries:
        results.append(sum_of_primes_subarray(arr, L, R))
    return results

def max_sum_increasing_subsequence(arr):
    """
    Find the maximum sum of a strictly increasing subsequence in the list.

    Parameters:
    arr (list): List of integers.

    Returns:
    int: The maximum sum of a strictly increasing subsequence.
    """
    n = len(arr)
    if n == 0:
        return 0

    # Initialize the dp array
    dp = arr[:]

    # Build the dp array to find the maximum sum increasing subsequence
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and dp[i] < dp[j] + arr[i]:
                dp[i] = dp[j] + arr[i]

    # Find the maximum value in dp array
    return max(dp)

