def count_elements_with_two_prime_factors(n, array):
    """
    Returns the number of elements in the array that have at least two distinct prime factors.
    """
    def prime_factors_count(x):
        """
        Returns the count of distinct prime factors of x.
        """
        count = 0
        if x % 2 == 0:
            count += 1
            while x % 2 == 0:
                x //= 2

        for i in range(3, int(x**0.5) + 1, 2):
            if x % i == 0:
                count += 1
                while x % i == 0:
                    x //= i

        if x > 2:
            count += 1

        return count

    elements_count = 0

    for elem in array:
        if prime_factors_count(elem) >= 2:
            elements_count += 1

    return elements_count

