def can_divide_grid(n, m, grid):
    from collections import deque

    total_fertility = sum(sum(row) for row in grid)

    if total_fertility % 2 != 0:
        return "NO"

    target_fertility = total_fertility // 2
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start, target_fertility):
        queue = deque([start])
        visited = set([start])
        current_sum = grid[start[0]][start[1]]

        while queue:
            x, y = queue.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny))
                    current_sum += grid[nx][ny]
                    if current_sum == target_fertility:
                        return True
                    elif current_sum > target_fertility:
                        return False
        return False

    for i in range(n):
        for j in range(m):
            if grid[i][j] <= target_fertility:
                if bfs((i, j), target_fertility):
                    return "YES"

    return "NO"

def longest_mountain(prices):
    """
    Returns the length of the longest mountain sequence in the given list of prices.
    """
    n = len(prices)
    if n < 3:
        return 0

    longest = 0

    for i in range(1, n - 1):
        if prices[i - 1] < prices[i] > prices[i + 1]:
            left = i
            right = i

            while left > 0 and prices[left - 1] < prices[left]:
                left -= 1

            while right < n - 1 and prices[right] > prices[right + 1]:
                right += 1

            longest = max(longest, right - left + 1)

    return longest

