def can_rearrange_books(t, test_cases):
    def is_possible(n, heights):
        from collections import Counter

        counter = Counter(heights)
        most_common_count = counter.most_common(1)[0][1]

        # Only need one book of each remaining height, hence (remaining unique) ≥ (most common count - 1)
        if most_common_count > (n + 1) // 2:
            return "NO"
        else:
            return "YES"

    results = []
    for i in range(t):
        n, heights = test_cases[i]
        results.append(is_possible(n, heights))

    return results

