def min_total_road_length(n, cities):
    def manhattan_distance(city1, city2):
        return abs(city1[0] - city2[0]) + abs(city1[1] - city2[1])

    # Kruskal's helpers
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    # Create all edges
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            dist = manhattan_distance(cities[i], cities[j])
            edges.append((dist, i, j))

    # Sort edges by weight (distance)
    edges.sort()

    minimum_total_distance = 0
    num_edges_used = 0

    # Kruskal's algorithm to form MST
    for dist, u, v in edges:
        if find(u) != find(v):
            union(u, v)
            minimum_total_distance += dist
            num_edges_used += 1
            if num_edges_used == n - 1:  # MST will have exactly n-1 edges
                break

    return minimum_total_distance

