from typing import List, Tuple, Dict

def find_lca(n: int, edges: List[Tuple[int, int]], values: Dict[int, int], root: int, node1: int, node2: int) -> int:
    from collections import defaultdict, deque

    def build_graph(edges):
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        return graph

    def dfs(node, parent):
        parent_map[node] = parent
        for neighbor in graph[node]:
            if neighbor != parent:
                dfs(neighbor, node)

    def find_path_to_root(node):
        path = []
        while node is not None:
            path.append(node)
            node = parent_map[node]
        return path

    # Step 1: Build graph
    graph = build_graph(edges)

    # Step 2: Perform DFS to map each node to its parent
    parent_map = {}
    dfs(root, None)

    # Step 3: Find paths from node1 and node2 to the root
    path1 = find_path_to_root(node1)
    path2 = find_path_to_root(node2)

    # Step 4: Find the common ancestor in both paths
    lca_node = None
    path1_set = set(path1)
    for node in path2:
        if node in path1_set:
            lca_node = node
            break

    return values[lca_node]

