def num_irrigation_systems(m, n, grid):
    if not grid or not grid[0]:
        return 0

    visited = [[False for _ in range(n)] for _ in range(m)]

    def dfs(i, j, plant_type):
        stack = [(i, j)]
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        while stack:
            x, y = stack.pop()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] == plant_type:
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    irrigation_systems = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] != 0 and not visited[i][j]:
                visited[i][j] = True
                dfs(i, j, grid[i][j])
                irrigation_systems += 1

    return irrigation_systems

