def is_magic_square(square):
    n = len(square)
    # Calculate the sum of the first row to use as reference
    expected_sum = sum(square[0])

    # Check sums of all rows
    for row in square:
        if sum(row) != expected_sum:
            return "NO"

    # Check sums of all columns
    for col in range(n):
        if sum(square[row][col] for row in range(n)) != expected_sum:
            return "NO"

    # Check the sum of the main diagonal
    if sum(square[i][i] for i in range(n)) != expected_sum:
        return "NO"

    # Check the sum of the anti-diagonal
    if sum(square[i][n-1-i] for i in range(n)) != expected_sum:
        return "NO"

    return "YES"

