def manage_list(n, q, initial_list, operations):
    result_list = initial_list

    result = []

    for operation in operations:
        op = operation.split()
        type_of_operation = int(op[0])

        if type_of_operation == 1:
            x = int(op[1])
            y = int(op[2])
            if x > len(result_list):
                result_list.append(y)
            else:
                result_list.insert(x - 1, y)

        elif type_of_operation == 2:
            x = int(op[1])
            if 1 <= x <= len(result_list):
                result_list.pop(x - 1)

        elif type_of_operation == 3:
            x = int(op[1])
            y = int(op[2])
            if 1 <= x <= len(result_list):
                result_list[x - 1] = y

        elif type_of_operation == 4:
            y = int(op[1])
            result.append(result_list.count(y))

    return result

