def verify_password(password: str) -> str:
    """
    Verifies if the given password meets security criteria:
    - At least 8 characters long
    - Contains at least one uppercase letter
    - Contains at least one lowercase letter
    - Contains at least one digit
    - Contains at least one special character from the set !@#$%^&*()-+
    - Does not contain spaces
    """

    import re

    failed_criteria = []

    special_characters = set("!@#$%^&*()-+")

    if len(password) < 8:
        failed_criteria.append("Must be at least 8 characters long")

    if not re.search("[A-Z]", password):
        failed_criteria.append("Must contain at least one uppercase letter")

    if not re.search("[a-z]", password):
        failed_criteria.append("Must contain at least one lowercase letter")

    if not re.search("[0-9]", password):
        failed_criteria.append("Must contain at least one digit")

    if not any(char in special_characters for char in password):
        failed_criteria.append("Must contain at least one special character from the set !@#$%^&*()-+")

    if " " in password:
        failed_criteria.append("Must not contain spaces")

    if failed_criteria:
        return "Invalid Password: " + ", ".join(failed_criteria)

    return "Valid Password"

