def minimum_removal_cost(n, k, arr):
    dp = [float('inf')] * (n + 1)
    dp[0] = 0  # No cost to remove zero elements

    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i - j >= 0:
                dp[i] = min(dp[i], dp[i - j] + sum(arr[i - j: i]))

    return dp[n]

