def process_library_operations(K, N, operations):
    borrowed_books = set()
    results = []

    for operation in operations:
        op, book_id_str = operation.split()
        book_id = int(book_id_str)

        if op == "BORROW":
            if len(borrowed_books) < K and book_id not in borrowed_books:
                borrowed_books.add(book_id)
                results.append("SUCCESS")
            else:
                results.append("FAIL")

        elif op == "RETURN":
            if book_id in borrowed_books:
                borrowed_books.remove(book_id)
                results.append("SUCCESS")
            else:
                results.append("FAIL")

    return results

from collections import defaultdict, deque

def tree_diameter(n, connections):
    def bfs(start):
        visited = [-1] * n
        visited[start] = 0
        q = deque([start])
        max_distance = (0, start)

        while q:
            node = q.popleft()
            for neighbor in graph[node]:
                if visited[neighbor] == -1:
                    visited[neighbor] = visited[node] + 1
                    q.append(neighbor)
                    if visited[neighbor] > max_distance[0]:
                        max_distance = (visited[neighbor], neighbor)

        return max_distance

    graph = defaultdict(list)
    for u, v in connections:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    first_bfs_result = bfs(0)
    second_bfs_result = bfs(first_bfs_result[1])

    return second_bfs_result[0]

def calculate_diameter(n, edges):
    return tree_diameter(n, edges)

