def find_minimum_cost(capacity, weights):
    """
    Returns the minimum total cost of transporting all packages using the least
    number of trucks required, or "impossible" if it is not feasible to transport
    all packages within the given constraints.
    """
    if any(weight > capacity for weight in weights):
        return "impossible"

    weights.sort(reverse=True)
    trucks = []

    for weight in weights:
        placed = False
        for i in range(len(trucks)):
            if trucks[i] + weight <= capacity:
                trucks[i] += weight
                placed = True
                break

        if not placed:
            trucks.append(weight)

    return sum(trucks)

