def count_and_say(n):
    def next_term(term):
        result = ""
        count = 1
        for i in range(1, len(term)):
            if term[i] == term[i - 1]:
                count += 1
            else:
                result += str(count) + term[i - 1]
                count = 1
        result += str(count) + term[-1]
        return result

    term = "1"
    for _ in range(n - 1):
        term = next_term(term)

    return term

