def most_frequent_character(s):
    """
    Returns the most frequently occurring character in the string s.
    In case of a tie, returns the lexicographically smallest character.
    """
    # Dictionary to store the frequency of each character
    frequency = {}

    # Calculate frequency of each character
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    # Find the most frequent character
    max_frequency = -1
    most_frequent_char = ''

    for char in frequency:
        if frequency[char] > max_frequency or (frequency[char] == max_frequency and char < most_frequent_char):
            max_frequency = frequency[char]
            most_frequent_char = char

    return most_frequent_char

