def num_ways_to_traverse(n, m, grid):
    MOD = 1000000007
    dp = [[0]*m for _ in range(n)]

    if grid[0][0] == '#':
        return 0

    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD

    return dp[n-1][m-1]

# Auxiliary function to facilitate testing with given examples
def grid_ways_from_input(input_str):
    lines = input_str.strip().split("\n")
    n, m = map(int, lines[0].strip().split())
    grid = [lines[i + 1].strip() for i in range(n)]
    return num_ways_to_traverse(n, m, grid)

