def longest_sequence(n, m, cars, selections):
    # Store the start and end of each special selection
    special_selections = [(l-1, r-1) for l, r in selections]

    # Create a list to mark the indices in special selections
    special_indices = set()
    for l, r in special_selections:
        for i in range(l, r + 1):
            special_indices.add(i)

    # Form a new list, keeping special selections as they are
    result = []
    i = 0
    while i < n:
        if i in special_indices:
            for l, r in special_selections:
                if l == i:
                    result.extend(cars[l:r + 1])
                    i = r
                    break
        else:
            result.append(cars[i])
        i += 1

    # Sort the non-special parts of the result list
    non_special_parts = sorted([x for i, x in enumerate(result) if i not in special_indices])

    # Merge them back together
    final_result = []
    j = 0
    for i in range(n):
        if i in special_indices:
            final_result.append(result[i])
        else:
            final_result.append(non_special_parts[j])
            j += 1

    return len(final_result)

# Example usage
# print(longest_sequence(5, 1, [1932, 1940, 1965, 1954, 1988], [(2, 3)])) # Output should be 5
# print(longest_sequence(6, 2, [1923, 1935, 1955, 1942, 1977, 1963], [(1, 2), (5, 6)])) # Output should be 6

