def is_permutation(s1, s2):
    """
    Returns True if s1 is a permutation of s2, False otherwise.
    """
    # If the lengths are different, they cannot be permutations
    if len(s1) != len(s2):
        return False

    # Sort both strings and compare the sorted versions
    return sorted(s1) == sorted(s2)

