def count_course_combinations(datasets):
    results = []

    for dataset in datasets:
        time_slots = {}

        for course, slot in dataset:
            if slot not in time_slots:
                time_slots[slot] = 0
            time_slots[slot] += 1

        if len(time_slots) < max(time_slots.keys()):
            results.append(0)
        else:
            ways = 1
            for slot in time_slots.keys():
                ways *= time_slots[slot]
            results.append(ways)

    return results

def process_input(data):
    lines = data.strip().split('\n')
    index = 0
    T = int(lines[index])
    index += 1

    datasets = []
    for _ in range(T):
        dataset = []
        N = int(lines[index])
        index += 1
        while True:
            course_id, slot_id = map(int, lines[index].split())
            index += 1
            if course_id == 0 and slot_id == 0:
                break
            dataset.append((course_id, slot_id))
        datasets.append(dataset)

    return datasets

def solution(data):
    datasets = process_input(data)
    return count_course_combinations(datasets)

