def can_fulfill_orders(n, orders, k, beds):
    # Initialize dictionaries to store the needed and available bouquets
    needs = {}
    availability = {}

    # Populate needs dictionary
    for i in range(n):
        flower_type, bouquets_needed = orders[i]
        if flower_type in needs:
            needs[flower_type] += bouquets_needed
        else:
            needs[flower_type] = bouquets_needed

    # Populate availability dictionary
    for i in range(k):
        bed_type, bouquets_produced = beds[i]
        if bed_type in availability:
            availability[bed_type] += bouquets_produced
        else:
            availability[bed_type] = bouquets_produced

    # Check if all needs can be met with the available bouquets
    for flower_type in needs:
        if needs[flower_type] > availability.get(flower_type, 0):
            return "NO"

    return "YES"

