def can_achieve_target(n, k, power_levels):
    dp = {}

    def find_combination(index, current_sum):
        if current_sum == k:
            return True
        if index >= n or current_sum > k:
            return False
        if (index, current_sum) in dp:
            return dp[(index, current_sum)]

        # Decision to skip the current artifact
        consider_skip = find_combination(index + 1, current_sum)

        # Decision to take the current artifact if it's not adjacent to the previous one
        consider_take = find_combination(index + 2, current_sum + power_levels[index])

        dp[(index, current_sum)] = consider_skip or consider_take
        return dp[(index, current_sum)]

    return "YES" if find_combination(0, 0) else "NO"

def calculate_rental_cost(t, rental_periods):
    def calculate_period_cost(start, end):
        working_hour_start = 9
        working_hour_end = 17
        working_hour_rate = 15
        non_working_hour_rate = 20
        total_cost = 0

        for hour in range(start, end):
            if working_hour_start <= hour < working_hour_end:
                total_cost += working_hour_rate
            else:
                total_cost += non_working_hour_rate
        return total_cost

    results = []
    for start, end in rental_periods:
        if start < end:
            results.append(calculate_period_cost(start, end))
        else:
            # Case where rental period spans midnight
            results.append(calculate_period_cost(start, 24) + calculate_period_cost(0, end))

    return results

