def find_peak_element(nums):
    """
    Finds and returns the index of a peak element in the input list of integers `nums`.
    """
    n = len(nums)

    # Handle the edge case where the list has only one element.
    if n == 1:
        return 0

    left, right = 0, n - 1

    while left < right:
        mid = (left + right) // 2

        if nums[mid] > nums[mid + 1]:
            right = mid
        else:
            left = mid + 1

    return left

