def minimized_sum(n, k):
    """
    Returns the minimum sum of a sequence of length n where 1 ≤ ai ≤ k,
    adjacent elements are not the same, and the sum of the elements
    is minimized.
    """
    # If k == 1, only one unique value is available, and it won't be possible
    # to ensure all ai != ai+1. Hence this would be an invalid input based
    # on the problem constraints. We assume k >= 2 for valid input.

    if k == 1:
        return -1  # Or raise an exception as the input would not be valid based on the problem details.

    # The minimal way to ensure ai != ai+1 is to alternate between 1 and 2
    seq = [0] * n
    for i in range(n):
        if i % 2 == 0:
            seq[i] = 1
        else:
            seq[i] = 2

    return sum(seq)

