import math

def euclidean_distance(x1, y1, x2, y2):
    return math.sqrt((x1 - x2)**2 + (y1 - y2)**2)

def process_queries(n, points, q, queries):
    results = []
    for a, b in queries:
        x1, y1 = points[a - 1]
        x2, y2 = points[b - 1]
        distance = euclidean_distance(x1, y1, x2, y2)
        results.append(round(distance, 6))
    return results

from collections import defaultdict, deque

def find_task_order(n, m, dependencies):
    # Create an adjacency list to represent the graph of dependencies
    adj_list = defaultdict(list)
    in_degree = {i: 0 for i in range(n)}

    for a, b in dependencies:
        adj_list[a].append(b)
        in_degree[b] += 1

    # Use a queue to perform topological sort
    queue = deque()
    for task in range(n):
        if in_degree[task] == 0:
            queue.append(task)

    task_order = []

    while queue:
        task = queue.popleft()
        task_order.append(task)

        for dependent_task in adj_list[task]:
            in_degree[dependent_task] -= 1
            if in_degree[dependent_task] == 0:
                queue.append(dependent_task)

    if len(task_order) != n:
        return "Impossible"

    return task_order

