def can_convert(s, t):
    """
    Checks if string s can be converted into string t by deleting some characters from s.
    """
    # Pointers for s and t
    s_pointer, t_pointer = 0, 0

    # Traverse s and t
    while s_pointer < len(s) and t_pointer < len(t):
        if s[s_pointer] == t[t_pointer]:
            t_pointer += 1
        s_pointer += 1

    # Check if all characters in t are found in order in s
    return t_pointer == len(t)

def process_queries(queries):
    results = []
    for s, t in queries:
        if can_convert(s, t):
            results.append("YES")
        else:
            results.append("NO")
    return results

