import heapq

def can_reach_destination(m, n, roads, s, d, W):
    graph = {i: [] for i in range(1, m + 1)}
    for u, v, l in roads:
        graph[u].append((v, l))
        graph[v].append((u, l))

    # Dijkstra's algorithm to find the shortest path
    pq = [(0, s)]  # (distance, node)
    distances = {i: float('inf') for i in range(1, m + 1)}
    distances[s] = 0

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        for neighbor, length in graph[current_node]:
            distance = current_distance + length

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return "YES" if distances[d] <= W else "NO"

# Parsing input function
def parse_input(input_string):
    lines = input_string.strip().split('\n')
    m, n = map(int, lines[0].split())
    roads = [tuple(map(int, line.split())) for line in lines[1:n+1]]
    s, d, W = map(int, lines[n+1].split())
    return m, n, roads, s, d, W

def check_transactions(transactions):
    """
    Verifies if the book transactions are valid according to the given rules.
    """
    borrowed = set()

    for transaction in transactions:
        action, book_id_str = transaction.split()
        book_id = int(book_id_str)

        if action == 'B':
            if book_id in borrowed:
                return "Invalid"
            borrowed.add(book_id)
        elif action == 'R':
            if book_id not in borrowed:
                return "Invalid"
            borrowed.remove(book_id)

    return "Valid"

