def longest_subsegment(s):
    n = len(s)

    def count_length(arr, char):
        max_length = 0
        current_length = 0
        for c in arr:
            if c == char:
                current_length += 1
            else:
                max_length = max(max_length, current_length)
                current_length = 0
        return max(max_length, current_length)

    max_length = count_length(s, '0') + 1  # change one '1' to '0' in the longest segment of '0'
    max_length = max(max_length, count_length(s, '1') + 1)  # change one '0' to '1' in the longest segment of '1'

    return min(max_length, n)

