def find_top_student(num_students, num_exams, scores):
    highest_avg = -1
    top_student_index = -1

    for i in range(num_students):
        avg_score = sum(scores[i]) / num_exams
        if avg_score > highest_avg:
            highest_avg = avg_score
            top_student_index = i
        elif avg_score == highest_avg and i < top_student_index:
