def find_longest_subarray(cards):
    """
    Returns the length of the longest subarray and maximum sum of values of the cards in that subarray.
    """
    n = len(cards)
    max_len = 0
    max_sum = 0
    balance_dict = {0: -1}
    current_balance = 0
    current_sum = 0

    for i, (color, value) in enumerate(cards):
        if color == 'R':
            current_balance += 1
        else:
            current_balance -= 1
        current_sum += value

        if current_balance in balance_dict:
            start_index = balance_dict[current_balance]
            subarray_length = i - start_index
            subarray_sum = current_sum if start_index == -1 else current_sum - sum(v for c, v in cards[:start_index+1])

            if subarray_length > max_len or (subarray_length == max_len and subarray_sum > max_sum):
                max_len = subarray_length
                max_sum = subarray_sum
        else:
            balance_dict[current_balance] = i

    return max_len, max_sum

