def has_zero_sum_submatrix(n, m, matrix):
    """
    Determine if there exists any submatrix with a sum of elements equal to zero.

    Parameters:
    n (int): Number of rows in the matrix.
    m (int): Number of columns in the matrix.
    matrix (list of list of int): The matrix itself.

    Returns:
    str: "YES" if there exists a submatrix with a sum of elements equal to zero, otherwise "NO".
    """
    for i in range(n):
        for j in range(m):
            # Trying all submatrices starting from (i, j)
            for p in range(i, n):
                for q in range(j, m):
                    submatrix_sum = 0
                    for x in range(i, p + 1):
                        for y in range(j, q + 1):
                            submatrix_sum += matrix[x][y]
                    if submatrix_sum == 0:
                        return "YES"
    return "NO"

