def first_missing_positive(nums):
    """
    Returns the smallest missing positive integer from the given list `nums`.
    """
    n = len(nums)
    # Step 1: Clean up the list by removing non-positive numbers and numbers greater than n
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Step 2: Use the index as a hash to record the presence of an element
    for num in nums:
        num = abs(num)  # Work with the absolute value in case it has been flagged
        if num <= n:
            nums[num - 1] = -abs(nums[num - 1])

    # Step 3: Find the first missing positive
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If all indices are flagged, then the next positive number is n+1
    return n + 1

