from typing import List

def count_islands(grid: List[List[str]]) -> int:
    def dfs(x, y):
        if x < 0 or y < 0 or x >= n or y >= n or grid[x][y] != 'L':
            return
        grid[x][y] = 'V'  # Mark as visited
        dfs(x + 1, y)     # Check down
        dfs(x - 1, y)     # Check up
        dfs(x, y + 1)     # Check right
        dfs(x, y - 1)     # Check left

    if not grid:
        return 0

    n = len(grid)
    islands_count = 0

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'L':
                islands_count += 1
                dfs(i, j)

    return islands_count

