def countPairsWithSum(arr, target):
    """
    Returns the number of unique pairs of elements in arr such that their sum is equal to target.
    """
    seen = set()
    pairs = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            pairs.add(tuple(sorted((num, complement))))
        seen.add(num)

    return len(pairs)

def longest_palindromic_substring(s):
    """
    Returns the longest palindromic substring in s.
    """
    def expand_around_center(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    if len(s) == 0:
        return ""

    longest = s[0]
    for i in range(len(s)):
        # Odd length palindromes
        temp = expand_around_center(s, i, i)
        if len(temp) > len(longest):
            longest = temp

        # Even length palindromes
        temp = expand_around_center(s, i, i + 1)
        if len(temp) > len(longest):
            longest = temp

    return longest

