from collections import deque

def shortest_path(graph, start, end):
    """
    Finds the shortest path between two nodes in an unweighted graph represented as an adjacency list.
    """
    if start == end:
        return [start]

    queue = deque([(start, [start])])
    visited = set([start])

    while queue:
        current, path = queue.popleft()

        for neighbor in graph[current]:
            if neighbor not in visited:
                if neighbor == end:
                    return path + [neighbor]
                queue.append((neighbor, path + [neighbor]))
                visited.add(neighbor)

    return None

def input_to_graph(n, adjacency_list, start, end):
    graph = {}
    for i in range(n):
        graph[i] = adjacency_list[i]

    return graph, start, end

