def min_max_time(n, m, tasks):
    # Helper function to check if a given max_time is feasible
    def is_feasible(max_time):
        num_workers = 1
        current_time = 0
        for task in tasks:
            if current_time + task <= max_time:
                current_time += task
            else:
                num_workers += 1
                current_time = task
                if num_workers > m:
                    return False
        return True

    # Binary search on the answer
    tasks.sort(reverse=True)  # Sorting in descending order helps in reducing the complexity
    left, right = max(tasks), sum(tasks)
    answer = right

    while left <= right:
        mid = (left + right) // 2
        if is_feasible(mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

    # Now we know the minimum possible maximum time, we need to find the assignment
    assignment = [[] for _ in range(m)]
    current_worker = 0
    current_time = 0

    for i, task in enumerate(tasks, start=1):
        if current_time + task <= answer:
            assignment[current_worker].append(i)
            current_time += task
        else:
            current_worker += 1
            assignment[current_worker].append(i)
            current_time = task

    return answer, assignment

