    stack = []
    cycle_start = [-1]
    cycle = []

    for i in range(1, n + 1):
        if color[i] == 0:
            if dfs(i):
                if cycle_start[0] != -1:
                    return "CYCLE " + ' '.join(map(str, cycle))

    return "NO CYCLE"

