from collections import defaultdict, deque

def is_tree(n, m, edges):
    if m != n - 1:
        return "NO"

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    queue = deque([1])
    visited[1] = True
    count_visited = 1

    while queue:
        node = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)
                count_visited += 1

    return "YES" if count_visited == n else "NO"

