def can_balance_expression(s):
    """
    Determines if it is possible to balance a mathematical expression
    by adding a minimal number of parentheses to make the expression valid.
    """
    open_parentheses = 0
    for char in s:
        if char == '(':
            open_parentheses += 1
        elif char == ')':
            if open_parentheses == 0:
                return "NO"  # There's an unmatched closing parenthesis
            open_parentheses -= 1
    return "YES" if open_parentheses == 0 else "NO"

