def form_minimum_subarray_array(n, k, a):
    """
    Forms a new array b such that b[i] is the minimum element in the subarray a[i:i+k-1]
    for 1 ≤ i ≤ n-k+1 and rest of the elements will be -1.
    """
    b = [-1] * n

    for i in range(n):
        if i + k - 1 < n:
            b[i] = min(a[i:i+k])
        else:
            b[i] = -1

    return b

