from typing import List

def findLongestWord(s: str, d: List[str]) -> str:
    def is_subsequence(x):
        it = iter(s)
        return all(c in it for c in x)

    longest_word = ""
    for word in sorted(d, key=lambda x: (-len(x), x)):
        if is_subsequence(word):
            return word
    return longest_word

def peak_usage_hour(n, records):
    """
    Determines the hour with the highest number of concurrent users.

    :param n: Number of usage records
    :param records: List of tuples containing start and end time of usage in (h1, m1, h2, m2) format
    :return: Hour of the day (0-23) with the highest peak usage
    """
    usage_counts = [0] * 24  # Array to hold count of users for each hour

    for record in records:
        h1, m1, h2, m2 = record
        if h1 == h2:  # If the usage is within the same hour
            usage_counts[h1] += 1
        else:
            usage_counts[h1] += 1
            for i in range(h1 + 1, h2):
                usage_counts[i] += 1
            if m2 > 0:
                usage_counts[h2] += 1

    return usage_counts.index(max(usage_counts))

