from datetime import datetime, timedelta

def parse_time(time_str):
    return datetime.strptime(time_str, "%H:%M")

def total_time_in_range(start_log, end_log, start_query, end_query):
    start = max(start_log, start_query)
    end = min(end_log, end_query)
    if start >= end:
        return timedelta()
    return end - start

def analyze_logs(N, logs, Q, queries):
    log_entries = {}

    # Store log entries
    for log in logs:
        engineer_id, module_id, start_time, end_time = log
        if (engineer_id, module_id) not in log_entries:
            log_entries[(engineer_id, module_id)] = []
        log_entries[(engineer_id, module_id)].append((parse_time(start_time), parse_time(end_time)))

    results = []
    for query in queries:
        engineer_id, module_id, start_time, end_time = query
        total_duration = timedelta()

        if (engineer_id, module_id) in log_entries:
            start_query = parse_time(start_time)
            end_query = parse_time(end_time)

            for log_start, log_end in log_entries[(engineer_id, module_id)]:
                total_duration += total_time_in_range(log_start, log_end, start_query, end_query)

        total_minutes = int(total_duration.total_seconds() // 60)
        hours, minutes = divmod(total_minutes, 60)
        results.append(f"{hours:02}:{minutes:02}")

    return results

def perform_operations(operations):
    array = []
    result_string = ""

    for operation in operations:
        op_type, value = operation.split()

        if op_type == "1":
            array.append(value)
        elif op_type == "2":
            index = int(value) - 1
            if 0 <= index < len(array):
                result_string += array.pop(index)

    return result_string

def sum_of_divisors(n):
    """
    Calculate the sum of all distinct positive divisors (including 1 and the number itself) of a given integer n.
    """
    divisors_sum = 0
    for i in range(1, n+1):
        if n % i == 0:
            divisors_sum += i
    return divisors_sum

