def min_sorted_subarrays(arr):
    """
    Returns the minimum number of contiguous subarrays
    that the input array can be partitioned into such that
    each subarray is sorted in non-decreasing order.
    """
    if not arr:
        return 0

    subarrays_count = 1
    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            subarrays_count += 1

    return subarrays_count

