def process_hierarchy(n, relationships, q, queries):
    tree = defaultdict(list)
    for supervisor, subordinate in relationships:
        tree[supervisor].append(subordinate)

    def get_all_subordinates(employee):
        subordinates = []
        queue = deque([employee])
        while queue:
            current = queue.popleft()
            for subordinate in tree[current]:
                subordinates.append(subordinate)
                queue.append(subordinate)
        return sorted(subordinates)

    results = []
    for employee in queries:
        results.append(get_all_subordinates(employee))
    return results

