def evaluate_expression(expression):
    """
    Evaluates the given arithmetic expression and returns the result.
    """
    try:
        # Using Python's eval() for simplicity in handling arithmetic expressions
        # Assuming the expression is well-formed and safe as per the problem statement
        result = eval(expression)
        return int(result)  # Cast the result to int as expected in the output
    except:
        return None  # In case of any error, return None (though per problem statement, expressions are valid)

def process_test_cases(T, expressions):
    """
    Processes multiple test cases and returns the results as a list.
    """
    results = []
    for expression in expressions:
        result = evaluate_expression(expression)
        results.append(result)
    return results

