def max_non_overlapping_tasks(n, tasks):
    # Sort tasks by their ending times
    tasks.sort(key=lambda x: x[1])

    count = 0
    last_end_time = -1

    for start, end in tasks:
        if start >= last_end_time:
            count += 1
            last_end_time = end

    return count

def digit_sum_check(num1, num2):
    """
    Check if the sum of digits of num1 is equal to the sum of digits of num2.

    Parameters:
    - num1 (int): First number in the range 100 to 999.
    - num2 (int): Second number in the range 100 to 999.

    Returns:
    - str: "YES" if the sum of digits of both numbers is equal, "NO" otherwise.
    """
    def digit_sum(n):
        return sum(int(digit) for digit in str(n))

    if digit_sum(num1) == digit_sum(num2):
        return "YES"
    else:
        return "NO"

from itertools import combinations

def maximum_rod_length(k, rods, m):
    """
    Returns the maximum length that can be achieved by combining some or all
    of the rods without exceeding the length limit m.
    """
    max_length = 0
    for i in range(1, k+1):
        for comb in combinations(rods, i):
            length = sum(comb)
            if length <= m:
                max_length = max(max_length, length)
    return max_length

