import heapq

def shortest_paths_from_capital(N, M, roads):
    graph = {i: [] for i in range(1, N+1)}

    for road in roads:
        u, v, w = road
        graph[u].append((w, v))
        graph[v].append((w, u))

    distances = {i: float('inf') for i in range(1, N+1)}
    distances[1] = 0
    priority_queue = [(0, 1)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for weight, adjacent in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[adjacent]:
                distances[adjacent] = distance
                heapq.heappush(priority_queue, (distance, adjacent))

    result = []
    for i in range(2, N+1):
        if distances[i] == float('inf'):
            result.append(-1)
        else:
            result.append(distances[i])

    return result

# Function to parse input and call the solving function
def minimum_distances_from_input(input_string):
    input_lines = input_string.strip().split("\n")
    N, M = map(int, input_lines[0].split())
    roads = [tuple(map(int, line.split())) for line in input_lines[1:1+M]]
    return shortest_paths_from_capital(N, M, roads)

