def exist(board, word):
    def dfs(board, word, i, j, nth):
        if nth == len(word):
            return True
        if i < 0 or i >= len(board) or j < 0 or j >= len(board[0]) or board[i][j] != word[nth]:
            return False
        tmp = board[i][j]
        board[i][j] = '#'
        found = dfs(board, word, i+1, j, nth+1) or \
                dfs(board, word, i-1, j, nth+1) or \
                dfs(board, word, i, j+1, nth+1) or \
                dfs(board, word, i, j-1, nth+1)
        board[i][j] = tmp
        return found

    for i in range(len(board)):
        for j in range(len(board[0])):
            if dfs(board, word, i, j, 0):
                return "true"
    return "false"

