def max_subarray_sum(n, nums):
    """
    Returns the largest sum of a contiguous subarray within a given array of integers.
    """
    if n == 0:
        return 0

    max_current = max_global = nums[0]

    for i in range(1, n):
        max_current = max(nums[i], max_current + nums[i])
        if max_current > max_global:
            max_global = max_current

    return max_global

