def can_return_to_origin(t, sequences):
    """
    Determines if the robot can return to the origin after executing a sequence of moves for each test case.

    Parameters:
    t (int): number of test cases
    sequences (list of str): list of move sequences

    Returns:
    list of str: "YES" if the robot returns to the origin, "NO" otherwise for each test case
    """
    results = []
    for s in sequences:
        x, y = 0, 0
        for move in s:
            if move == 'U':
                y += 1
            elif move == 'D':
                y -= 1
            elif move == 'L':
                x -= 1
            elif move == 'R':
                x += 1
        if x == 0 and y == 0:
            results.append("YES")
        else:
            results.append("NO")
    return results

