def can_arrange_seating(n, m, dislikes):
    from itertools import permutations

    # Create the adjacency matrix for dislikes
    adj_matrix = [[0]*n for _ in range(n)]
    for a, b in dislikes:
        adj_matrix[a-1][b-1] = 1
        adj_matrix[b-1][a-1] = 1

    def is_valid(arrangement):
        for i in range(n):
            if adj_matrix[arrangement[i]-1][arrangement[(i+1)%n]-1] == 1:
                return False
        return True

    for arrangement in permutations(range(1, n+1)):
        if is_valid(arrangement):
            return "YES"

    return "NO"

def max_anagram_pairs(test_cases):
    results = []

    for words in test_cases:
        anagram_dict = {}
        for word in words:
            sorted_word = ''.join(sorted(word))
            if sorted_word not in anagram_dict:
                anagram_dict[sorted_word] = 0
            anagram_dict[sorted_word] += 1

        pairs = sum(count // 2 for count in anagram_dict.values())
        results.append(pairs)

    return results

