import math
from typing import List

def find_minimum_possible_max_element(arr: List[int]) -> int:
    def gcd(a: int, b: int) -> int:
        return math.gcd(a, b)

    overall_gcd = arr[0]
    for num in arr[1:]:
        overall_gcd = gcd(overall_gcd, num)
    return overall_gcd

def process_test_cases(test_cases: List[List[int]]) -> List[int]:
    results = []
    for test_case in test_cases:
        result = find_minimum_possible_max_element(test_case)
        results.append(result)
    return results

