def decodeString(s):
    stack = []
    current_num = 0
    current_str = ''

    for ch in s:
        if ch.isdigit():
            current_num = current_num * 10 + int(ch)
        elif ch == '[':
            stack.append((current_str, current_num))
            current_str = ''
            current_num = 0
        elif ch == ']':
            last_str, num = stack.pop()
            current_str = last_str + current_str * num
        else:
            current_str += ch

    return current_str

