def is_prime(n):
    """
    Helper function to check whether a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def can_form_special_prime(k, primes):
    """
    Function to determine if there exists at least one pair of prime numbers
    from the list that concatenates to form a special prime number.
    """
    for i in range(k):
        for j in range(k):
            if i != j:
                concatenated_p1p2 = int(str(primes[i]) + str(primes[j]))
                concatenated_p2p1 = int(str(primes[j]) + str(primes[i]))
                if is_prime(concatenated_p1p2) or is_prime(concatenated_p2p1):
                    print("YES")
                    return
    print("NO")

