def is_arithmetic_progression(sequence):
    """
    Checks if a given sequence is an arithmetic progression.
    """
    if len(sequence) < 2:
        return False
    # Calculate the difference between first two elements
    diff = sequence[1] - sequence[0]

    # Check if each consecutive elements have the same difference
    for i in range(1, len(sequence)):
        if sequence[i] - sequence[i - 1] != diff:
            return False
    return True

def check_arithmetic_progressions(test_cases):
