            results.append("NO")
    return results

def lexicographically_smallest_string(s):
    """
    Returns the lexicographically smallest string after removing at most one character.
    """
    n = len(s)
    if n == 1:
        return ""

    min_string = s[1:]  # Assume the smallest string is by removing the first character

    for i in range(n):
        new_string = s[:i] + s[i+1:]  # String after removing the i-th character
        if new_string < min_string:
            min_string = new_string

    return min_string

