from collections import defaultdict, deque

def count_paths(n, m, edges):
    """
    Returns the number of different paths from node 1 to node n in a DAG.
    """
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # dp array to store the number of paths from node 1 to node i
    dp = [0] * (n + 1)
    dp[1] = 1

    # topologically sort the nodes
    in_degree = [0] * (n + 1)
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    zero_in_degree_queue = deque([i for i in range(1, n + 1) if in_degree[i] == 0])

    topo_order = []
    while zero_in_degree_queue:
        u = zero_in_degree_queue.popleft()
        topo_order.append(u)
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                zero_in_degree_queue.append(v)

    # calculate number of paths using topological order
    for node in topo_order:
        for neighbor in graph[node]:
            dp[neighbor] += dp[node]

    return dp[n]

def can_match_subarrays(n, m, k, A, B):
    """
    Determines if a k-length subarray from A can be rearranged to match
    a k-length subarray from B.
    """
    from collections import Counter

    def get_k_length_subarray_counts(arr, k):
        subarray_counts = []
        for i in range(len(arr) - k + 1):
            subarray_counts.append(Counter(arr[i:i+k]))
        return subarray_counts

    A_subarray_counts = get_k_length_subarray_counts(A, k)
    B_subarray_counts = get_k_length_subarray_counts(B, k)

    for count_a in A_subarray_counts:
        for count_b in B_subarray_counts:
            if count_a == count_b:
                return "Yes"
    return "No"

from typing import List, Tuple

def min_fires_needed_to_burn_trees(grid: List[str], fires: List[Tuple[int, int]]) -> int:
    N = len(grid)
    M = len(grid[0])

    def is_tree(i, j):
        return 0 <= i < N and 0 <= j < M and grid[i][j] == 'T'

    def bfs(start_i, start_j, visited):
        queue = [(start_i, start_j)]
        while queue:
            i, j = queue.pop(0)
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if is_tree(ni, nj) and (ni, nj) not in visited:
                    visited.add((ni, nj))
                    queue.append((ni, nj))

    visited = set()
    fire_count = 0

    for i in range(N):
        for j in range(M):
            if is_tree(i, j) and (i, j) not in visited:
                fire_count += 1
                bfs(i, j, visited)

    return fire_count

def max_subarray_sum(arr):
    """
    Returns the maximum sum of a contiguous subarray within the given array.
    Uses Kadane's Algorithm for optimal performance.
    """
    if not arr:
        return 0

    max_current = max_global = arr[0]

    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

