def find_distinct_positions(L, query_function):
    """
    Takes the length of the string L and a query_function.
    Returns positions of two distinct characters in the string.
    """
    # If the string length is 2, then the two positions must be 1 and 2.
    if L == 2:
        return 1, 2

    # Perform initial queries to find the first position with a change in the number of distinct characters
    for i in range(1, L):
        distinct_count = query_function(1, i)
        if query_function(1, i + 1) > distinct_count:
            return i, i + 1

    # In the worst case where no distinct character is found in previous loop
    return -1, -1  # This case should not happen

# Helper function to simulate querying the number of distinct characters
def simulated_query(encrypted_message, i, j):
    return len(set(encrypted_message[i-1:j]))

