def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    L = int(data[0])
    encrypted_message = data[1]  # for simulation purposes

    def query_function(i, j):
        print(f"? {i} {j}")
        sys.stdout.flush()
        return simulated_query(encrypted_message, i, j)

    pos1, pos2 = find_distinct_positions(L, query_function)

    if pos1 != -1 and pos2 != -1:
        print(f"! {pos1} {pos2}")
    else:
        print("Error: No distinct characters found, which shouldn't happen.")

