def min_access_points(n, m, grid):
    """
    Returns the minimum number of access points needed to cover all buildings.
    """
    visited = [[False] * m for _ in range(n)]

    def in_bounds(x, y):
        return 0 <= x < n and 0 <= y < m

    def explore(x, y):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if not in_bounds(cx, cy) or visited[cx][cy] or grid[cx][cy] == '.':
                continue
            visited[cx][cy] = True
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                stack.append((cx + dx, cy + dy))

    access_points = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B' and not visited[i][j]:
                access_points += 1
                explore(i, j)
    return access_points

def unique_paths_with_obstacles(n, m, grid):
    if grid[0][0] == '#' or grid[-1][-1] == '#':
        return 0

    dp = [[0]*m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

# Example usage:
# n = 3, m = 3
# grid = [
#     ['.', '.', '.'],
#     ['.', '#', '.'],
#     ['.', '.', '.']
# ]
