from collections import Counter

def longest_palindromic_substring_permutation(s):
    """
    Returns the longest substring of s that can be rearranged to form a palindrome.
    """
    char_count = Counter(s)
    longest_palindrome = []
    middle_char = ""

    for char, count in char_count.items():
        if count % 2 == 1:
            if len(middle_char) == 0 or count > char_count[middle_char]:
                middle_char = char

    for char, count in char_count.items():
        longest_palindrome += [char] * (count // 2)

    longest_palindrome = ''.join(longest_palindrome)
    if middle_char:
        return longest_palindrome + middle_char + longest_palindrome[::-1]
    else:
        return longest_palindrome + longest_palindrome[::-1]

