def warehouse_operations(n, q, heights, instructions):
    results = []

    for instruction in instructions:
        parts = instruction.split()
        op_type = int(parts[0])
        i = int(parts[1]) - 1

        if op_type == 1:
            x = int(parts[2])
            heights[i] += x

        elif op_type == 2:
            x = int(parts[2])
            heights[i] -= x

        elif op_type == 3:
            results.append(heights[i])

    return results

