def exist(board, word):
    rows, cols = len(board), len(board[0])

    def backtrack(row, col, suffix):
        if len(suffix) == 0:
            return True

        if row < 0 or row >= rows or col < 0 or col >= cols or board[row][col] != suffix[0]:
            return False

        ret = False
        board[row][col] = "#"  # Mark as visited

        for row_offset, col_offset in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            ret = backtrack(row+row_offset, col+col_offset, suffix[1:])
            if ret:
                break

        board[row][col] = suffix[0]  # Unmark as visited
        return ret

    for row in range(rows):
        for col in range(cols):
            if backtrack(row, col, word):
                return "YES"

    return "NO"

def sequence_length(n):
    """
    Returns the length of the sequence starting from n and ending with 1
    according to the given rules.
    """
    length = 1
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = n * 3 + 1
        length += 1
    return length

