import sys

def minimum_travel_cost(n1, n2, n3, a, b, c, m1, flights1, m2, flights2):
    if m1 == 0 or m2 == 0:
        return -1

    # Create adjacency lists for the flight connections
    adj1 = {i: [] for i in range(n1)}
    adj2 = {i: [] for i in range(n2)}

    for x, y in flights1:
        adj1[x-1].append(y-1)

    for x, y in flights2:
        adj2[x-1].append(y-1)

    # Initialize min costs with infinity
    min_cost = sys.maxsize
    for i in range(n1):
        for j in adj1[i]:
            for k in adj2[j]:
                total_cost = a[i] + b[j] + c[k]
                min_cost = min(min_cost, total_cost)

    return min_cost if min_cost != sys.maxsize else -1

