def min_cost_to_monitor_network(n, m, costs, connections):
    from collections import defaultdict
    import sys

    # Step 1: Create the graph using adjacency list representation
    graph = defaultdict(list)

    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)

    def dfs(node):
        stack = [node]
        component = []
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                component.append(current)
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return component

    # Step 2: Find connected components
    components = []
    for i in range(1, n + 1):
        if not visited[i]:
            component = dfs(i)
            components.append(component)

    # Step 3: Calculate the minimum cost to monitor each component
    min_total_cost = 0
    for component in components:
        min_cost = sys.maxsize
        for node in component:
            min_cost = min(min_cost, costs[node - 1])
        min_total_cost += min_cost

    return min_total_cost

# Function to parse the input and call the main function
def solve(n, m, costs, connections):
    return min_cost_to_monitor_network(n, m, costs, connections)

