def longest_reading_journey(n, books):
    """
    Returns the length of the longest reading journey.
    """
    if n == 0:
        return 0

    max_journey = 1
    current_journey = 1

    for i in range(1, n):
        if books[i] == books[i - 1]:
            current_journey += 1
        else:
            max_journey = max(max_journey, current_journey)
            current_journey = 1

    max_journey = max(max_journey, current_journey)
    return max_journey

