def max_brightness_subgrid(N, M, grid):
    MOD = 10**9 + 7
    max_brightness = -float('inf')
    count = 0

    dp = [[0]*(M+1) for _ in range(N+1)]

    for i in range(1, N+1):
        for j in range(1, M+1):
            dp[i][j] = grid[i-1][j-1] + dp[i-1][j] + dp[i][j-1] - dp[i-1][j-1]

    for i1 in range(1, N+1):
        for j1 in range(1, M+1):
            for i2 in range(i1, N+1):
                for j2 in range(j1, M+1):
                    curr_sum = dp[i2][j2] - dp[i1-1][j2] - dp[i2][j1-1] + dp[i1-1][j1-1]
                    if curr_sum > max_brightness:
                        max_brightness = curr_sum
                        count = 1
                    elif curr_sum == max_brightness:
                        count += 1
                        count %= MOD

    return max_brightness, count

