def calculate_total_height_diff(T, test_cases):
    results = []
    for case in test_cases:
        M, B = case
        H = [0] * (M + 1)

        for i in range(1, M + 1):
            if B[i - 1] == 1:
                H[i] = i * i
            elif B[i - 1] == 2:
                H[i] = H[i - 1] + i

        results.append(H[M])

    return results

