def rotate_90_degrees(garden, n, m):
    return [[garden[n - 1 - i][j] for i in range(n)] for j in range(m)]

def rotate_garden(n, m, garden, k):
    k = k % 4  # Since 4 rotations result in the same pattern
    for _ in range(k):
        garden = rotate_90_degrees(garden, n, m)
        n, m = m, n
    return garden

def process_queries(n, m, arr, queries):
    results = []

    for query in queries:
        if query[0] == 1:
            # Increment subarray
            _, l, r, x = query
            for i in range(l - 1, r):
                arr[i] += x
        elif query[0] == 2:
            # Sum subarray
            _, l, r = query
            results.append(sum(arr[l-1:r]))
        elif query[0] == 3:
            # Replace subarray
            _, l, r, y = query
            for i in range(l - 1, r):
                arr[i] = y

    return results

def largest_connected_crops(n, m, field):
    def dfs(x, y):
        if x < 0 or x >= n or y < 0 or y >= m or field[x][y] == '.':
            return 0
        # Mark the cell as visited
        field[x][y] = '.'
        size = 1
        # Explore the 4 possible directions: up, down, left, right
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            size += dfs(x + dx, y + dy)
        return size

    max_size = 0
    for i in range(n):
        for j in range(m):
            if field[i][j] == 'C':
                max_size = max(max_size, dfs(i, j))

    return max_size

def longest_subarray_sum(nums, n):
    """
    Returns the length of the longest contiguous subarray that sums up to n.
    """
    sum_indices = {0: -1}
    current_sum = 0
    max_length = 0

    for i, num in enumerate(nums):
        current_sum += num
        if current_sum - n in sum_indices:
            max_length = max(max_length, i - sum_indices[current_sum - n])
        if current_sum not in sum_indices:
            sum_indices[current_sum] = i

    return max_length

