def max_travel_time(n, m, k, roads, routes):
    from collections import defaultdict

    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    for u, v, w in roads:
        graph[u].append((v, w))

    def calculate_travel_time(route):
        total_time = 0
        for (p, q) in zip(route[:-1], route[1:]):
            for v, w in graph[p]:
                if v == q:
                    total_time += w
                    break
        return total_time

    max_time = 0
    for t, l, *stops in routes:
        travel_time = calculate_travel_time(stops)
        max_time = max(max_time, travel_time)

    return max_time

