def spiralOrder(matrix):
    """
    Returns a list of elements of the matrix in spiral order.
    """
    res = []
    while matrix:
        res += matrix.pop(0)
        if matrix and matrix[0]:
            for row in matrix:
                res.append(row.pop())
        if matrix:
            res += matrix.pop()[::-1]
        if matrix and matrix[0]:
            for row in matrix[::-1]:
                res.append(row.pop(0))
    return res

def matrix_input(m, n, elements):
    matrix = []
    index = 0
    for i in range(m):
        matrix.append(elements[index:index + n])
        index += n
    return matrix

def spiral_matrix_input(m, n, elements):
    matrix = matrix_input(m, n, elements)
    return ' '.join(map(str, spiralOrder(matrix)))

from collections import deque

def shortest_path(N, M, P, obstacles, Q, queries):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    obstacle_set = set((x, y) for x, y in obstacles)

    def bfs(start, end):
        sx, sy = start
        tx, ty = end
        if (sx, sy) in obstacle_set or (tx, ty) in obstacle_set:
            return -1

        visited = set()
        queue = deque([(sx - 1, sy - 1, 0)])  # Python uses 0-based indexing
        visited.add((sx - 1, sy - 1))

        while queue:
            x, y, dist = queue.popleft()
            if (x, y) == (tx - 1, ty - 1):
                return dist

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < N and 0 <= ny < M and (nx, ny) not in visited and (nx, ny) not in obstacle_set:
                    visited.add((nx, ny))
                    queue.append((nx, ny, dist + 1))

        return -1

    results = []
    for start, end in queries:
        results.append(bfs(start, end))

    return results

def longest_increasing_subarray_length(arr):
    """
    Returns the length of the longest strictly increasing subarray.
    """
    if not arr:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            current_length += 1
        else:
            current_length = 1
        max_length = max(max_length, current_length)

    return max_length

