    results = []

    for command in commands:
        if command[0] == 1:
            # Report the current width of the river with the specified id
            id = command[1]
            results.append(river_widths[id - 1])
        elif command[0] == 2:
            # Set the width of all rivers from index l to r to x
            l, r, x = command[1], command[2], command[3]
            for i in range(l - 1, r):
                river_widths[i] = x
        elif command[0] == 3:
            # Adjust the width of every river from index l to r by adding x meters
            l, r, x = command[1], command[2], command[3]
            for i in range(l - 1, r):
                river_widths[i] += x
                if river_widths[i] > 1000:
                    river_widths[i] = 1000

    return results

