def max_value_min_deviation(N, W, books):
    dp = [None] * (W + 1)
    dp[0] = 0

    for weight, value in books:
        for current_weight in range(W, weight - 1, -1):
            if dp[current_weight - weight] is not None:
                if dp[current_weight] is None:
                    dp[current_weight] = dp[current_weight - weight] + value
                else:
                    dp[current_weight] = max(dp[current_weight], dp[current_weight - weight] + value)

    best_value = 0
    for i in range(W + 1):
        if dp[i] is not None:
            best_value = max(best_value, dp[i])

    return best_value

