from collections import defaultdict
from math import gcd

def max_monsters_towards_artifact(n, coordinates):
    if n == 1:
        return 1

    max_count = 0

    for i in range(n):
        direction_count = defaultdict(int)
        same_position_count = 1

        for j in range(n):
            if i != j:
                dx, dy = coordinates[j][0] - coordinates[i][0], coordinates[j][1] - coordinates[i][1]
                if dx == 0 and dy == 0:
                    same_position_count += 1
                else:
                    g = gcd(dx, dy)
                    direction_count[(dx // g, dy // g)] += 1

        max_direction_count = max(direction_count.values(), default=0)
        max_count = max(max_count, max_direction_count + same_position_count)

    return max_count

