def find_triplet_with_zero_sum(arr):
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        left = i + 1
        right = n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == 0:
                return "YES"
            elif current_sum < 0:
                left += 1
            else:
                right -= 1

    return "NO"

