def max_sum_subarray(arr, subarray_length, validity):
    n = len(arr)
    max_sum = -1

    # Initialize the current sum of the first possible subarray of length subarray_length
    current_sum = 0
    valid_count = 0
    for i in range(subarray_length):
        if not validity[i]:
            current_sum += arr[i]
            valid_count += 1

    if valid_count == subarray_length:
        max_sum = current_sum

    # Slide the window across the array
    for i in range(subarray_length, n):
        if not validity[i]:
            current_sum += arr[i]
            valid_count += 1
        if not validity[i - subarray_length]:
            current_sum -= arr[i - subarray_length]
            valid_count -= 1

        if valid_count == subarray_length:
            max_sum = max(max_sum, current_sum)

    return max_sum

