def max_profit(N, K, prices):
    if not prices:
        return 0

    # If K is greater than or equal to half of the days, treat it as unlimited transactions
    if K >= N // 2:
        return sum(max(prices[i+1] - prices[i], 0) for i in range(N-1))

    # Initialize the dp table
    dp = [[0] * N for _ in range(K + 1)]

    for k in range(1, K + 1):
        max_diff = -prices[0]
        for i in range(1, N):
            dp[k][i] = max(dp[k][i-1], prices[i] + max_diff)
            max_diff = max(max_diff, dp[k-1][i] - prices[i])

    return dp[K][N-1]

def process_input(input_string):
    input_lines = input_string.strip().split("\n")
    T = int(input_lines[0])
    idx = 1
    results = []

    for _ in range(T):
        N, K = map(int, input_lines[idx].split())
        prices = list(map(int, input_lines[idx+1].split()))
        idx += 2
        results.append(max_profit(N, K, prices))

    return results

