def min_operations(S, T):
    """
    Returns the minimum number of operations required to transform S into T.
    """
    len_s, len_t = len(S), len(T)
    dp = [[0] * (len_t + 1) for _ in range(len_s + 1)]

    for i in range(len_s + 1):
        for j in range(len_t + 1):
            if i == 0:
                dp[i][j] = j  # Inserting all characters of T
            elif j == 0:
                dp[i][j] = i  # Deleting all characters of S
            else:
                if S[i - 1] == T[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = 1 + min(dp[i - 1][j - 1],  # Replace
                                       dp[i - 1][j],    # Delete
                                       dp[i][j - 1])    # Insert

    return dp[len_s][len_t]

