def max_profit(t, test_cases):
    def max_billboard_profit(buildings):
        n = len(buildings)
        if n == 0:
            return 0
        dp = [0] * n
        for i in range(n):
            if i == 0:
                dp[i] = buildings[i]
            elif i == 1:
                dp[i] = max(buildings[i], dp[i-1])
            else:
                dp[i] = max(dp[i-1], dp[i-2] + buildings[i])
        return dp[-1]

    results = []
    for case in test_cases:
        n, heights = case
        results.append(max_billboard_profit(heights))

    return results

