def can_complete_marathon(initial_stamina, path):
    """
    Determines if Emma can complete the marathon given the initial stamina and path.

    Parameters:
    initial_stamina (int): Initial stamina Emma starts with.
    path (str): String representing the marathon path.

    Returns:
    str: "YES" if Emma can complete the marathon, "NO" otherwise.
    """
    stamina = initial_stamina

    for section in path:
        if section == 'R':
            stamina -= 1
        elif section == 'S':
            stamina -= 2
        elif section == 'U':
            stamina -= 3
        elif section == 'D':
            stamina += 1

        if stamina < 0:
            return "NO"

    return "YES"

