def highest_average_genre(n, g, songs):
    from collections import defaultdict
    genre_qualities = defaultdict(list)

    for genre, quality in songs:
        genre_qualities[genre].append(quality)

    max_avg = -1
    best_genre = None

    for genre in range(1, g + 1):
        if genre_qualities[genre]:
            avg_quality = sum(genre_qualities[genre]) / len(genre_qualities[genre])
            if avg_quality > max_avg or (avg_quality == max_avg and genre < best_genre):
                max_avg = avg_quality
                best_genre = genre

    return best_genre

def longest_contiguous_ones(S):
    """
    Returns the length of the longest contiguous subsequence of `1`s in the binary string S.
    """
    max_len = 0
    current_len = 0

    for char in S:
        if char == '1':
            current_len += 1
            max_len = max(max_len, current_len)
        else:
            current_len = 0

    return max_len

