def lexicographically_smallest_string(s, k):
    """
    Returns the lexicographically smallest string by rotating a substring k times.
    """
    if k == 1:
        # When k is 1, we can only rotate the entire string, consider all rotations and choose the smallest one.
        smallest = s
        for i in range(1, len(s)):
            rotated = s[i:] + s[:i]
            if rotated < smallest:
                smallest = rotated
        return smallest
    else:
        # When k >= 2, we can arbitrarily sort the string.
        return ''.join(sorted(s))

