def can_fulfill_order(n):
    """
    Determines if it is possible to fulfill an order of exactly n flowers
    using 10, 15, or 25 flower bouquets.
    """
    for i in range(n // 10 + 1):
        for j in range(n // 15 + 1):
            for k in range(n // 25 + 1):
                if i * 10 + j * 15 + k * 25 == n:
                    return "Yes"
    return "No"

def process_orders(T, orders):
    results = []
    for n in orders:
        results.append(can_fulfill_order(n))
    return results

