def can_connect_hooks(n, m, strings):
    """
    Determines if it is possible to connect all hooks with the given constraints.
    """
    from collections import defaultdict, deque

    if m < n - 1:
        return "NO"

    graph = defaultdict(list)

    for u, v in strings:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    components = 0

    def bfs(start):
        queue = deque([start])
        visited[start] = True

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    for i in range(1, n + 1):
        if not visited[i]:
            components += 1
            if components > 1:
                return "NO"
            bfs(i)

    return "YES"

