def min_reversals_to_balance(s):
    """
    Returns the minimum number of reversals required to balance the brackets in string s.
    If it is not possible, returns -1.
    """
    # Check if the length of the string is odd
    if len(s) % 2 != 0:
        return -1

    # Stack to keep track of unbalanced brackets
    stack = []

    # Traverse through the string
    for char in s:
        if char == '{':
            stack.append(char)
        else:
            # This is a closing bracket
            if stack and stack[-1] == '{':
                stack.pop()  # Balanced part
            else:
                stack.append(char)  # Unbalanced closing bracket

    # Now stack contains only unbalanced brackets
    unbalanced_len = len(stack)

    # Find number of '{' and '}' at the end of the array
    open_brackets = 0
    while stack and stack[-1] == '{':
        stack.pop()
        open_brackets += 1

    close_brackets = unbalanced_len - open_brackets

    # Minimum reversals required
    return (close_brackets // 2) + (open_brackets // 2) + (close_brackets % 2) + (open_brackets % 2)

