def is_prime(n):
    """
    Checks if n is a prime number.
    """
    if n <= 1:
        return False
    if n == 2:
        return True  # as 2 is the only even prime number
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def find_twin_primes(L, R):
    """
    Finds and returns all twin primes within the range [L, R].
    """
    twin_primes = []
    for num in range(L, R-1):  # Stop at R-1 since we need pairs (num, num+2)
        if is_prime(num) and is_prime(num + 2):
            twin_primes.append((num, num + 2))

    if not twin_primes:
        return "No twin primes found"
    return twin_primes

def format_twin_primes(twin_primes):
    """
    Formats the twin primes as string output for display purposes.
    """
    if twin_primes == "No twin primes found":
        return twin_primes
    return "\n".join(f"({p1}, {p2})" for p1, p2 in twin_primes)

