def min_operations_to_unique_heights(n, heights):
    heights.sort()
    operations = 0

    for i in range(1, n):
        if heights[i] <= heights[i - 1]:
            needed_increase = heights[i - 1] - heights[i] + 1
            heights[i] += needed_increase
            operations += needed_increase

    return operations

