def process_inventory_operations(operations):
    inventory = {}

    for operation in operations:
        op_type, bookID, quantity = operation
        bookID = int(bookID)
        quantity = int(quantity)

        if bookID not in inventory:
            inventory[bookID] = 0

        if op_type == "sale":
            inventory[bookID] -= quantity
        elif op_type == "restock":
            inventory[bookID] += quantity

    result = []
    for bookID in sorted(inventory.keys()):
        result.append((bookID, inventory[bookID]))

    return result

