def find_cycle(n, m, routes):
    from collections import defaultdict, deque

    def dfs(v):
        state[v] = 1  # visited
        stack.append(v)
        for u in graph[v]:
            if state[u] == 1:  # found a back edge, indicating a cycle
                cycle = stack[stack.index(u):]
                cycle.append(u)
                return cycle
            if state[u] == 0:
                result = dfs(u)
                if result:
                    return result
        state[v] = 2  # fully processed
        stack.pop()
        return None

    graph = defaultdict(list)
    for u, v in routes:
        graph[u].append(v)

    state = [0] * (n + 1)  # 0: unvisited, 1: visiting, 2: visited
    stack = []

    for i in range(1, n + 1):
        if state[i] == 0:
            cycle = dfs(i)
            if cycle:
                return "Cycle Found: " + ' '.join(map(str, cycle))

    return "No cycle"

