def sum_of_primes(N):
    """
    Returns the sum of all prime numbers less than or equal to N using the Sieve of Eratosthenes algorithm.
    """
    if N < 2:
        return 0

    sieve = [True] * (N + 1)
    sieve[0], sieve[1] = False, False

    for i in range(2, int(N**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, N + 1, i):
                sieve[j] = False

    return sum(i for i, is_prime in enumerate(sieve) if is_prime)

