    quadruplets = []
    n = len(nums)

    for i in range(n - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        for j in range(i + 1, n - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue

            left, right = j + 1, n - 1

            while left < right:
                sum_of_four = nums[i] + nums[j] + nums[left] + nums[right]

                if sum_of_four == target:
                    quadruplets.append([nums[i], nums[j], nums[left], nums[right]])

                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1

                    left += 1
                    right -= 1

                elif sum_of_four < target:
                    left += 1
                else:
                    right -= 1

    return quadruplets

def min_coins(coins, amount):
    """
    Returns the minimum number of coins needed to make exactly the given amount of money.
    If it's not possible to make the amount with the given coins, returns -1.
    """
    dp = [float('inf')] * (amount + 1)
    dp[0] = 0

    for coin in coins:
        for x in range(coin, amount + 1):
            dp[x] = min(dp[x], dp[x - coin] + 1)

    if dp[amount] == float('inf'):
        return -1
    else:
        return dp[amount]

