def longest_unique_subsequence(s):
    """
    Returns the starting and ending indices (1-based) of the longest subsequence of unique letters.
    """
    last_seen = {}
    start = 0
    max_length = 0
    start_index = 0

    for i in range(len(s)):
        if s[i] in last_seen:
            start = max(start, last_seen[s[i]] + 1)
        last_seen[s[i]] = i
        if i - start + 1 > max_length:
            max_length = i - start + 1
            start_index = start

    return start_index + 1, start_index + max_length

