def min_cost_to_achieve_value(n, req_value, items):
    """
    Returns the minimum cost to achieve or exceed the required minimum value
    """
    min_cost = float('inf')

    for s, e, c in items:
        if s <= req_value <= e:
            min_cost = min(min_cost, c)

    return min_cost if min_cost != float('inf') else -1

def count_empty_regions(n, grid):
    def dfs(x, y):
        if x < 0 or x >= n or y < 0 or y >= n or grid[x][y] == '1' or visited[x][y]:
            return
        visited[x][y] = True
        dfs(x-1, y)  # up
        dfs(x+1, y)  # down
        dfs(x, y-1)  # left
        dfs(x, y+1)  # right

    visited = [[False] * n for _ in range(n)]
    regions = 0

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '0' and not visited[i][j]:
                regions += 1
                dfs(i, j)

    return regions

