def escape_the_maze(m, n, maze):
    """
    Determines if there exists a path from 'S' to 'E' in the given maze.

    :param m: int - number of rows in the maze.
    :param n: int - number of columns in the maze.
    :param maze: List[str] - the maze grid.

    :return: str - "YES" if a path exists from 'S' to 'E', otherwise "NO".
    """
    from collections import deque

    # Find the start (S) and exit (E) positions
    start = exit = None
    for i in range(m):
        for j in range(n):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'E':
                exit = (i, j)

    # Directions for moving: right, left, down, up
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < m and 0 <= y < n and maze[x][y] in ('.', 'E')

    # BFS to find path
    queue = deque([start])
    visited = set([start])

    while queue:
        x, y = queue.popleft()

        # If we reached the exit
        if (x, y) == exit:
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return "NO"

def unique_pairs_with_difference(nums, k):
    """
    Returns the number of unique pairs (i, j) such that i ≠ j and |nums[i] - nums[j]| = k.

    Args:
    nums: List of integers.
    k: An integer which is the required difference.

    Returns:
    An integer representing the number of unique pairs.
    """
    # Dictionary to store frequency of each number
    freq = {}
    count = 0

    for num in nums:
        freq[num] = freq.get(num, 0) + 1

    if k == 0:
        # Special case: when k=0, count the pairs formed by same elements
        for value in freq.values():
            count += value * (value - 1) // 2
    else:
        for num in freq:
            if num + k in freq:
                count += freq[num] * freq[num + k]

    return count

