from typing import List

def longest_increasing_subarray(arr: List[int]) -> List[int]:
    if not arr:
        return []

    max_len = 1
    curr_len = 1
    start_index = 0
    curr_start = 0

    for i in range(1, len(arr)):
        if arr[i] > arr[i - 1]:
            curr_len += 1
        else:
            if curr_len > max_len:
                max_len = curr_len
                start_index = curr_start
            curr_len = 1
            curr_start = i

    # Final check in case the longest subarray is at the end
    if curr_len > max_len:
        max_len = curr_len
        start_index = curr_start

    return arr[start_index:start_index + max_len]

