def max_pastries(T, test_cases):
    results = []
    for i in range(T):
        N, E = test_cases[i][:2]
        egg_requirements = sorted(test_cases[i][2])
        total_eggs = 0
        types_count = 0
        for eggs in egg_requirements:
            if total_eggs + eggs <= E:
                total_eggs += eggs
                types_count += 1
            else:
                break
        results.append(types_count)
    return results

