def process_garden_operations(n, m, garden, operations):
    for operation in operations:
        op_parts = operation.split()
        op_type = op_parts[0]

        if op_type == "Add":
            r, c, d = int(op_parts[1]), int(op_parts[2]), int(op_parts[3])
            garden[r-1][c-1] = d

        elif op_type == "Remove":
            r, c = int(op_parts[1]), int(op_parts[2])
            garden[r-1][c-1] = 0

        elif op_type == "Swap":
            r1, c1, r2, c2 = int(op_parts[1]), int(op_parts[2]), int(op_parts[3]), int(op_parts[4])
            garden[r1-1][c1-1], garden[r2-1][c2-1] = garden[r2-1][c2-1], garden[r1-1][c1-1]

    return garden

from typing import List

def arrange_packages(n: int, grid: List[List[int]]) -> List[List[int]]:
    from itertools import permutations

    def is_valid(arrangement):
        rows_with_one = all(sum(arrangement[i]) == 1 for i in range(n))
        cols_with_one = all(sum(arrangement[i][j] for i in range(n)) == 1 for j in range(n))
        return rows_with_one and cols_with_one

    for perm in permutations(range(n)):
        new_grid = [[0] * n for _ in range(n)]
        valid = True
        for i in range(n):
            column = perm[i]
            if grid[i][column] == 0:
                valid = False
                break
            new_grid[i][column] = 1
        if valid and is_valid(new_grid):
            return new_grid
    return []

def process_delivery_updates(inputs):
    updates = inputs.splitlines()
    deliveries = {}
    results = []

    while updates:
        # Read the first line for n and m
        line = updates.pop(0)
        if line == "0 0":
            break

        n, m = map(int, line.split())

        for _ in range(n):
            package_update = updates.pop(0).split()
            package_id = package_update[0]
            status = package_update[1]
            deliveries[package_id] = status

        for _ in range(m):
            package_query = updates.pop(0)
            if package_query in deliveries:
                results.append(f"{package_query} {deliveries[package_query]}")
            else:
                results.append(f"{package_query} UNKNOWN")

    return results

def is_palindrome(s):
    return s == s[::-1]

def palindromic_splits_helper(s, memo):
    if s in memo:
        return memo[s]

    if not s:
        return 1

    total_splits = 0
    for i in range(1, len(s) + 1):
        if is_palindrome(s[:i]):
            total_splits += palindromic_splits_helper(s[i:], memo)

    memo[s] = total_splits
    return total_splits

def palindromic_splits(t, cases):
    results = []
    for s in cases:
        memo = {}
        results.append(palindromic_splits_helper(s, memo))
    return results

