def count_stars(n, m, board):
    """
    Counts the number of stars (horizontal or vertical contiguous sequences of '*') on the board.
    """
    def mark_visited_horizontal(i, j):
        """
        Mark all horizontally contiguous '*' cells as visited.
        """
        while j < m and board[i][j] == '*':
            visited[i][j] = True
            j += 1

    def mark_visited_vertical(i, j):
        """
        Mark all vertically contiguous '*' cells as visited.
        """
        while i < n and board[i][j] == '*':
            visited[i][j] = True
            i += 1

    visited = [[False] * m for _ in range(n)]
    star_count = 0

    for i in range(n):
        for j in range(m):
            if board[i][j] == '*' and not visited[i][j]:
                star_count += 1
                if j+1 < m and board[i][j+1] == '*':
                    mark_visited_horizontal(i, j)
                else:
                    mark_visited_vertical(i, j)

    return star_count

def count_divisible_pairs(arr, k):
    """
    Returns the number of pairs (i, j) where i < j and arr[i] + arr[j] is divisible by k.
    """
    n = len(arr)
    count = 0
    remainder_freq = [0] * k

    for num in arr:
        remainder_freq[num % k] += 1

    count += remainder_freq[0] * (remainder_freq[0] - 1) // 2

    for i in range(1, k // 2 + 1):
        if i != k - i:
            count += remainder_freq[i] * remainder_freq[k - i]

    if k % 2 == 0:
        count += remainder_freq[k // 2] * (remainder_freq[k // 2] - 1) // 2

    return count

