def can_eva_clean_all(m, n, grid):
    def is_within_bounds(x, y):
        return 0 <= x < m and 0 <= y < n

    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            if grid[cx][cy] == '*':
                grid[cx][cy] = '.'  # Clean the cell
                # Explore all 4 directions
                for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nx, ny = cx + dx, cy + dy
                    if is_within_bounds(nx, ny) and grid[nx][ny] == '*':
                        stack.append((nx, ny))

    grid = [list(row) for row in grid]

    # Find all initial dirty cells
    dirty_cells = [(i, j) for i in range(m) for j in range(n) if grid[i][j] == '*']

    if not dirty_cells:
        return "YES"

    # Start from the first dirty cell
    start_x, start_y = dirty_cells[0]
    dfs(start_x, start_y)

    # Check if all dirty cells are cleaned
    for x, y in dirty_cells:
        if grid[x][y] == '*':
            return "NO"

    return "YES"

