def can_reach_target(n, m, initial_position, target_position, movement_rules):
    from collections import defaultdict, deque

    # Build the graph from movement rules
    graph = defaultdict(list)
    for x, y in movement_rules:
        graph[x].append(y)

    # BFS to find if we can reach the target position from the initial position
    queue = deque([initial_position])
    visited = set()

    while queue:
        current = queue.popleft()
        if current == target_position:
            return "YES"
        if current not in visited:
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    queue.append(neighbor)

    return "NO"

