import heapq

def dijkstra(n, roads, s, d):
    # Build the graph
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, t in roads:
        graph[u].append((v, t))
        graph[v].append((u, t))

    # Priority queue for Dijkstra's algorithm
    pq = [(0, s)]
    dist = {i: float('inf') for i in range(1, n + 1)}
    dist[s] = 0

    while pq:
        current_dist, u = heapq.heappop(pq)

        if u == d:
            return current_dist

        for v, weight in graph[u]:
            distance = current_dist + weight
            if distance < dist[v]:
                dist[v] = distance
                heapq.heappush(pq, (distance, v))

    return -1

def shortest_travel_time(n, m, roads, s, d):
    return dijkstra(n, roads, s, d)

def shortest_repeating_substring_length(s):
    """
    Given a string s, returns the length of the shortest substring that, when repeated infinitely,
    can form the original string s.
    """
    n = len(s)
    for i in range(1, n + 1):
        if n % i == 0 and s[:i] * (n // i) == s:
            return i
    return n

def process_test_cases(t, test_cases):
    results = []
    for s in test_cases:
        results.append(shortest_repeating_substring_length(s))
    return results

def can_plant_flowers(n, flowerbeds, m):
    count = 0
    i = 0

    while i < n:
        if flowerbeds[i] == 0:
            if (i == 0 or flowerbeds[i-1] == 0) and (i == n-1 or flowerbeds[i+1] == 0):
                flowerbeds[i] = 1
                count += 1
        if count >= m:
            return "Yes"
        i += 1

    return "No"

