from collections import deque

def min_steps_to_treasure(n, m, matrix):
    # Directions for moving up, down, left, and right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Find the starting point and the treasure point
    start = (0, 0)
    treasure = None
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == 'T':
                treasure = (i, j)

    if not treasure:
        return -1  # No treasure found

    # Breadth-First Search (BFS) initialization
    queue = deque([start])
    visited = set([start])
    steps = 0

    while queue:
        for _ in range(len(queue)):
            x, y = queue.popleft()

            # Check if we have reached the treasure
            if (x, y) == treasure:
                return steps

            # Explore neighboring cells
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and matrix[nx][ny] != '#':
                    visited.add((nx, ny))
                    queue.append((nx, ny))

        steps += 1

    return -1  # If the treasure is not reachable

def longest_unique_substring_length(s: str) -> int:
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    max_length = 0
    start = 0

    for index, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = index
        max_length = max(max_length, index - start + 1)

    return max_length

