def process_queries(queries):
    arr = []
    results = []

    for query in queries:
        if query[0] == '+':
            arr.append(int(query[2:]))
        elif query[0] == '-':
            x = int(query[2:])
            arr.remove(x)
        elif query[0] == '?':
            l, r = map(int, query[2:].split())
            subarray = arr[l-1:r]
            results.append(len(set(subarray)))

    return results

