def min_abs_difference(n, fun_values):
    """
    Returns the minimum possible absolute difference between the total fun values of toys in two separate boxes.
    """
    total_sum = sum(fun_values)
    max_sum = total_sum // 2

    dp = [0] * (max_sum + 1)

    for value in fun_values:
        for j in range(max_sum, value - 1, -1):
            dp[j] = max(dp[j], dp[j - value] + value)

    box1_sum = dp[max_sum]
    box2_sum = total_sum - box1_sum

    return abs(box1_sum - box2_sum)

