def sieve_of_eratosthenes(limit):
    is_prime = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if is_prime[p]:
            for i in range(p * p, limit + 1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = []
    for p in range(2, limit + 1):
        if is_prime[p]:
            prime_numbers.append(p)
    return prime_numbers

def find_longest_sequence(n, k):
    primes = sieve_of_eratosthenes(n)
    sequence = []
    sum_powers = 0
    for prime in primes:
        power_prime = prime ** k
        if sum_powers + power_prime <= n:
            sum_powers += power_prime
            sequence.append(prime)
    if not sequence:
        return -1
    return sequence

def place_sensors(m, n, k):
    def is_safe(board, row, col):
        for i in range(row):
            if board[i] == col or abs(board[i] - col) == (row - i):
                return False
        return True

    def solve(board, row):
        if row == k:
            result = [(i + 1, board[i] + 1) for i in range(k)]
            return True, result

        for col in range(n):
            if is_safe(board, row, col):
                board[row] = col
                solved, result = solve(board, row + 1)
                if solved:
                    return True, result
                board[row] = -1

        return False, []

    if k == 0:
        return 'YES', []

    board = [-1] * k
    solved, result = solve(board, 0)

    if solved:
        return 'YES', result
    else:
        return 'NO', []

