def exists_palindromic_path(n, m, grid):
    from collections import defaultdict

    # Table to store lengths and possibilities of paths at each (i, j)
    dp = [[defaultdict(set) for _ in range(m)] for _ in range(n)]

    # Initialize DP table
    dp[0][0][1].add(grid[0][0])

    for i in range(n):
        for j in range(m):
            if i > 0:
                for path_length, substrings in dp[i-1][j].items():
                    for substring in substrings:
                        dp[i][j][path_length + 1].add(substring + grid[i][j])
            if j > 0:
                for path_length, substrings in dp[i][j-1].items():
                    for substring in substrings:
                        dp[i][j][path_length + 1].add(substring + grid[i][j])

    # Check for palindrome in the bottom-right cell
    for substring in dp[n-1][m-1][n + m - 1]:
        if substring == substring[::-1]:
            return "YES"
    return "NO"

