def fibonacci_tree_branches(n):
    """
    Returns the total number of branches on the Fibonacci Tree at the nth iteration.
    """
    if n == 0:
        return 1
    elif n == 1:
        return 2
    else:
        a, b = 1, 2
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

