from collections import defaultdict, deque

def kosaraju_scc_count(n, edges):
    def dfs(v, graph, visited, stack=None, component=None):
        visited[v] = True
        if component is not None:
            component.append(v)
        for neighbour in graph[v]:
            if not visited[neighbour]:
                dfs(neighbour, graph, visited, stack, component)
        if stack is not None:
            stack.append(v)

    graph = defaultdict(list)
    reverse_graph = defaultdict(list)

    for u, v in edges:
        graph[u].append(v)
        reverse_graph[v].append(u)

    stack = []
    visited = [False] * (n + 1)

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, graph, visited, stack)

    visited = [False] * (n + 1)
    scc_count = 0

    while stack:
        node = stack.pop()
        if not visited[node]:
            component = []
            dfs(node, reverse_graph, visited, component=component)
            if component:
                scc_count += 1

    return scc_count

# Function to process input and call the SCC function
def find_scc_count(n, m, edges):
    return kosaraju_scc_count(n, edges)

