def next_prime_digit_number(n):
    """
    Returns the smallest number greater than n that consists only of prime digits (2, 3, 5, 7).
    """
    prime_digits = ['2', '3', '5', '7']

    def is_prime_digit_number(num):
        return all(ch in prime_digits for ch in num)

    n = str(n)
    length = len(n)

    # function to increment the number and check for prime digit number
    num = int(n) + 1
    while True:
        if is_prime_digit_number(str(num)):
            return str(num)
        num += 1

