from typing import List

def maxPower(crystals: List[int]) -> int:
    n = len(crystals)
    if n == 0:
        return 0
    if n == 1:
        return max(0, crystals[0])

    # Using two variables to keep track of maximum sums
    prev1 = max(0, crystals[0])
    prev2 = max(prev1, max(0, crystals[1]))

    for i in range(2, n):
        current = max(prev1 + max(0, crystals[i]), prev2)
        prev1 = prev2
        prev2 = current

    return prev2

