def can_travel_between_locations(N, M, roads, queries):
    from collections import defaultdict, deque

    def bfs(start, end):
        visited = set()
        queue = deque([start])

        while queue:
            node = queue.popleft()
            if node == end:
                return True
            if node not in visited:
                visited.add(node)
                queue.extend(graph[node] - visited)

        return False

    graph = defaultdict(set)
    for u, v in roads:
        graph[u].add(v)
        graph[v].add(u)

    results = []
    for u, v in queries:
        if bfs(u, v):
            results.append("YES")
        else:
            results.append("NO")

    return results

