def can_organize_hackathon(t, test_cases):
    """
    Determines if it is possible to organize seating for the hackathon based on given constraints.
    """
    from collections import defaultdict, deque

    results = []

    for i in range(t):
        n, p = test_cases[i]['n'], test_cases[i]['p']
        friends_constraints = defaultdict(list)
        rivals_constraints = []

        for j in range(p):
            constraint = test_cases[i]['constraints'][j]
            if constraint[0] == 'F':
                _, u, v = constraint
                friends_constraints[u].append(v)
                friends_constraints[v].append(u)
            elif constraint[0] == 'R':
                _, x, y = constraint
                rivals_constraints.append((x, y))

        parent = {i: i for i in range(1, n + 1)}

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            parent[find(x)] = find(y)

        for u in friends_constraints:
            for v in friends_constraints[u]:
                union(u, v)

        valid = True
        for x, y in rivals_constraints:
            if find(x) == find(y):
                valid = False
                break

        results.append("YES" if valid else "NO")

    return results

