def check_people_count(rooms_snapshots, k):
    """
    Returns 'yes' if any room had at least k number of people at any moment, otherwise 'no'.

    rooms_snapshots: list of list of int, each sublist represents the snapshots for one room
    k: int, the specified number of people to check against
    """
    for room in rooms_snapshots:
        if any(people_count >= k for people_count in room):
            return "yes"
    return "no"

