def has_subarray_with_sum(arr, k):
    """
    Determines if there exists a contiguous subarray with a sum equal to k.
    """
    n = len(arr)
    current_sum = 0
    sum_dict = {}

    for i in range(n):
        current_sum += arr[i]

        if current_sum == k:
            return "YES"

        if (current_sum - k) in sum_dict:
            return "YES"

        sum_dict[current_sum] = i

    return "NO"

