def is_balanced(B, T, data):
    results = []

    start = 0
    for _ in range(B):
        M = data[start]
        monthly_reports = data[start + 1: start + 1 + M]
        balanced = True
        for report in monthly_reports:
            max_sale = max(report)
            min_sale = min(report)
            if max_sale - min_sale > T:
                balanced = False
                break
        if balanced:
            results.append("Balanced")
        else:
            results.append("Not Balanced")

        start = start + 1 + M

    return results

