def count_grades(scores):
    """
    Given a list of scores, returns the counts of grades A, B, C, D, and F.
    """
    # Initialize counts for each letter grade
    counts = {'A': 0, 'B': 0, 'C': 0, 'D': 0, 'F': 0}

    for score in scores:
        if 90 <= score <= 100:
            counts['A'] += 1
        elif 80 <= score <= 89:
            counts['B'] += 1
        elif 70 <= score <= 79:
            counts['C'] += 1
        elif 60 <= score <= 69:
            counts['D'] += 1
        elif 0 <= score <= 59:
            counts['F'] += 1

    # Return the counts in the order of A, B, C, D, F
    return counts['A'], counts['B'], counts['C'], counts['D'], counts['F']

