def isBalanced(s):
    """
    Determines if a string of brackets is balanced.

    Args:
    s (str): A string containing only '(', ')', '{', '}', '[' and ']'.

    Returns:
    bool: True if the string is balanced, False otherwise.
    """
    stack = []
    brackets = {'(': ')', '{': '}', '[': ']'}

    for char in s:
        if char in brackets:
            stack.append(char)
        elif char in brackets.values():
            if not stack or brackets[stack.pop()] != char:
                return False
    return not stack

def has_triplet_sum(arr, target):
    """
    Determines if there exists a triplet in the array that sums up to the target value.
    """
    arr.sort()
    n = len(arr)
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            triplet_sum = arr[i] + arr[left] + arr[right]
            if triplet_sum == target:
                return True
            elif triplet_sum < target:
                left += 1
            else:
                right -= 1
    return False

def process_test_cases(test_cases):
    results = []
    for case in test_cases:
        n, target, arr = case
        result = has_triplet_sum(arr, target)
        results.append(result)
    return results

def compress_string(s):
    if not s:
        return ""

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1])
            if count > 1:
                compressed.append(str(count))
            count = 1

    compressed.append(s[-1])
    if count > 1:
        compressed.append(str(count))

    return "".join(compressed)

