def restore_hexabracelet(n, s):
    """
    Given a length n and a bracelet string s of length n, restores the bracelet
    by replacing '?' with the characters from 'R', 'G', 'B', 'Y', 'W', 'K'
    such that the count of each bead type is as equal as possible.
    """
    if n % 6 != 0:
        return "###"

    beads = ['R', 'G', 'B', 'Y', 'W', 'K']
    counter = {bead: 0 for bead in beads}

    for char in s:
        if char in counter:
            counter[char] += 1

    max_count = n // 6

    result = []
    idx = 0

    def replace_question_mark():
        nonlocal idx
        while counter[beads[idx]] >= max_count:
            idx += 1
        counter[beads[idx]] += 1
        return beads[idx]

    for char in s:
        if char == '?':
            result.append(replace_question_mark())
        else:
            result.append(char)

    return ''.join(result)

