def access_control(input_data):
    """
    Determines which badges have access to specific areas based on their access level.
    """
    lines = input_data.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse badge information
    badges = {}
    for i in range(1, n+1):
        badge_id, access_level = lines[i].split()
        badges[badge_id] = int(access_level)

    result = []
    # Parse area information and determine access
    for i in range(n+1, n+m+1):
        area_id, required_access_level = lines[i].split()
        required_access_level = int(required_access_level)

        # Find badge IDs that meet the access level requirement
        access_list = [badge_id for badge_id, access_level in badges.items() if access_level >= required_access_level]

        if access_list:
            result.append(" ".join(access_list))
        else:
            result.append("No access")

    return "\n".join(result)

