def can_create_harmonious_council(n, regions):
    from itertools import combinations

    # Iterate over all possible subsets of regions
    for r in range(1, n + 1):
        for subset in combinations(regions, r):
            elf_sum = sum(region[0] for region in subset)
            dwarf_sum = sum(region[1] for region in subset)
            if elf_sum == dwarf_sum:
                return "YES"
    return "NO"

def find_max_block_size(n, grid):
    def dfs(x, y, height):
        if x < 0 or x >= n or y < 0 or y >= n or grid[x][y] != height:
            return 0
        grid[x][y] = -1  # mark as visited
        size = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            size += dfs(x + dx, y + dy, height)
        return size

    max_block_size = 0

    for i in range(n):
        for j in range(n):
            if grid[i][j] != -1:  # not visited
                height = grid[i][j]
                max_block_size = max(max_block_size, dfs(i, j, height))

    return max_block_size

def query_results(n, q, array, queries):
    results = []

    for x, y, k in queries:
        found = False
        for i in range(x - 1, y):
            if array[i] % k == 0:
                found = True
                break
        results.append("YES" if found else "NO")

    return results

def execute(number_of_elements, number_of_queries, elements, queries):
    return query_results(number_of_elements, number_of_queries, elements, queries)

