def matrix_multiply(m, n, p, A, B):
    """
    Multiplies two matrices A and B.
    """
    # Initialize resulting matrix C with zeros
    C = [[0] * p for _ in range(m)]

    # Perform matrix multiplication
    for i in range(m):
        for j in range(p):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]

    return C

import heapq

def sum_largest_k_donations(n, k, donations):
    # Using a min heap to keep track of the largest k donations
    min_heap = []
    total = 0

    for donation in donations:
        if len(min_heap) < k:
            heapq.heappush(min_heap, donation)
            total += donation
        elif donation > min_heap[0]:
            total -= heapq.heappushpop(min_heap, donation)
            total += donation

    return total

