def process_operations(n, operations):
    stack = []

    for op in operations:
        parts = op.split()
        if parts[0] == "add":
            id = parts[1]
            strength = int(parts[2])
            if not stack or stack[-1][1] >= strength:
                stack.append((id, strength))
        elif parts[0] == "remove":
            if stack:
                stack.pop()

    if not stack:
        return ["empty"]
    else:
        return [brick[0] for brick in stack]

from typing import List

def maxLength(arr: List[str]) -> int:
    def dfs(start, current):
        if len(current) != len(set(current)):
            return 0
        max_length = len(current)
        for i in range(start, len(arr)):
            max_length = max(max_length, dfs(i + 1, current + arr[i]))
        return max_length

    return dfs(0, "")

