    for i, (categories, knowledgeable) in enumerate(test_cases):
        score = sum(categories[category] for category in knowledgeable)
        results.append(f"Case {i + 1}: {score}")
    return results

def main(input_data):
    input_lines = input_data.strip().split('\n')
    index = 0
    test_cases = []
    while index < len(input_lines):
        N = int(input_lines[index])
        if N == 0:
            break
        index += 1
        categories = {}
        for _ in range(N):
            category_name, difficulty_score = input_lines[index].split()
            categories[category_name] = int(difficulty_score)
            index += 1
        M = int(input_lines[index])
        index += 1
        knowledgeable = []
        for _ in range(M):
            knowledgeable.append(input_lines[index])
            index += 1
        test_cases.append((categories, knowledgeable))
    return calculate_highest_score(test_cases)

