def check_valid_sentence(sentence):
    """
    Checks if the input string forms a valid sentence.
    """
    # Ensure the first letter is uppercase and ends with a period
    if not sentence[0].isupper() or not sentence.endswith('.'):
        return "INVALID"

    # Check specific comma and space pattern
    words = sentence[:-1].split(', ')

    # If split doesn't match the original length, it means the commas are not followed by spaces properly
    if len(', '.join(words) + '.') != len(sentence):
        return "INVALID"

    # Ensure all words are alphabetical and within length constraints
    for word in words:
        if not word.isalpha() or not (1 <= len(word) <= 20):
            return "INVALID"

    # Check for overall length
    if len(sentence) > 200:
        return "INVALID"

    return "VALID"

