def restore_ip_addresses(s):
    def is_valid(segment):
        return 0 <= int(segment) <= 255 and (segment == "0" or segment[0] != "0")

    def backtrack(start=0, end=1, current_parts=None):
        if current_parts is None:
            current_parts = []

        if len(current_parts) == 4 and start == len(s):
            result.append(".".join(current_parts))
            return
        elif len(current_parts) == 4:
            return

        for end in range(start + 1, min(len(s) + 1, start + 4)):
            segment = s[start:end]
            if is_valid(segment):
                backtrack(end, end + 1, current_parts + [segment])

    result = []
    backtrack()
    return result

