def is_sorted(words, order):
    """
    Determines if the array of strings 'words' is sorted according to the given 'order'.
    """
    order_index = {char: idx for idx, char in enumerate(order)}

    def compare(word1, word2):
        len1, len2 = len(word1), len(word2)
        for i in range(min(len1, len2)):
            if word1[i] != word2[i]:
                return order_index[word1[i]] < order_index[word2[i]]
        return len1 <= len2

    for i in range(len(words) - 1):
        if not compare(words[i], words[i + 1]):
            return "NO"
    return "YES"

# Usage
# print(is_sorted(["hello", "leetcode"], "hlabcdefgijkmnopqrstuvwxyz"))  # Expected output: YES
# print(is_sorted(["word", "world", "row"], "worldabcefghijkmnpqstuvxyz"))  # Expected output: NO

