def min_operations_to_identical(t, cases):
    results = []
    for s in cases:
        char_counts = {}
        for char in s:
            if char in char_counts:
                char_counts[char] += 1
            else:
                char_counts[char] = 1
        max_char_count = max(char_counts.values())
        min_operations = len(s) - max_char_count
        results.append(min_operations)
    return results

