def min_removed_parentheses(s):
    """
    This function removes the minimum number of parentheses to make the input string valid.
    """
    stack = []
    to_remove = set()

    # Identify the parentheses to be removed
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                to_remove.add(i)

    # Add any leftover '(' indices to the removal set
    to_remove = to_remove.union(set(stack))

    # Build the valid string by skipping indices in the to_remove set
    result = ''.join([char for i, char in enumerate(s) if i not in to_remove])

    return result

