import itertools
import math

def calculate_distance(p1, p2):
    """
    Calculate the Euclidean distance between two points p1 and p2.
    """
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def total_distance(route):
    """
    Calculate the total distance of the given route which starts and ends at the first location.
    """
    distance = 0
    for i in range(len(route) - 1):
        distance += calculate_distance(route[i], route[i + 1])
    distance += calculate_distance(route[-1], route[0]) # returning to the starting point
    return distance

def find_min_route(locations):
    """
    Find the minimum route that visits all locations exactly once and returns to the start point.
    """
    min_distance = float('inf')
    for perm in itertools.permutations(locations):
        current_distance = total_distance(perm)
        if current_distance < min_distance:
            min_distance = current_distance
    return round(min_distance, 2)

def sum_of_grid_values(n, m, operations):
    grid = [[0]*n for _ in range(n)]

    for r1, r2, value in operations:
        for i in range(n):
            grid[r1-1][i] += value
            grid[r2-1][i] += value

    total_sum = sum(sum(row) for row in grid)
    return total_sum

