def detect_conflicts(test_cases):
    results = []
    for events in test_cases:
        events.sort(key=lambda x: x[0])
        conflict_found = False

        for i in range(1, len(events)):
            if events[i][0] < events[i-1][1]:
                conflict_found = True
                break

        results.append("YES" if conflict_found else "NO")

    return results

def parse_input(input_string):
    lines = input_string.strip().split("\n")
    T = int(lines[0])
    line_index = 1
    test_cases = []

    for _ in range(T):
        N = int(lines[line_index])
        line_index += 1
        events = []
        for _ in range(N):
            S, E = map(int, lines[line_index].split())
            events.append((S, E))
            line_index += 1
        test_cases.append(events)

    return test_cases

def main(input_string):
    test_cases = parse_input(input_string)
    return detect_conflicts(test_cases)

