def num_distinct_fertile_patches(n, m, field):
    def dfs(x, y):
        if x < 0 or x >= n or y < 0 or y >= m or field[x][y] == '0':
            return
        field[x][y] = '0'
        dfs(x - 1, y)
        dfs(x + 1, y)
        dfs(x, y - 1)
        dfs(x, y + 1)

    patches_count = 0
    for i in range(n):
        for j in range(m):
            if field[i][j] == '1':
                dfs(i, j)
                patches_count += 1
    return patches_count

