def process_queries(n, q, queries):
    a = [0] * n
    results = []

    for query in queries:
        t = query[0]
        if t == 1:
            x, d = query[1], query[2]
            a[x-1] += d
        elif t == 2:
            l, r = query[1], query[2]
            results.append(sum(a[l-1:r]))

    return results

