def game_winner(n):
    """
    Determines if Alice can guarantee a win given n stones.

    Parameters:
    n (int): The initial number of stones (1 ≤ n ≤ 10^5)

    Returns:
    str: "Alice" if Alice can guarantee a win, otherwise "Bob"
    """
    # Initialize memoization table to store results of subproblems
    dp = [False] * (n + 1)

    # Base cases
    if n == 1:
        return "Alice"
    if n == 2:
        return "Bob"
    if n == 3:
        return "Alice"
    if n == 4:
        return "Alice"

    # Fill the dp table
    for i in range(1, n + 1):
        if i >= 1 and not dp[i - 1]:
            dp[i] = True
        elif i >= 3 and not dp[i - 3]:
            dp[i] = True
        elif i >= 4 and not dp[i - 4]:
            dp[i] = True

    return "Alice" if dp[n] else "Bob"

