def min_replacements_to_remove_blighted_crops(N, grid):
    """
    Returns the minimum number of cells that need to be replaced to remove all blighted crops.
    """
    def is_blighted(x, y):
        """
        Check if a cell is blighted or not.
        """
        return grid[x][y] < 0

    replacements = 0

    for i in range(N):
        for j in range(N):
            if is_blighted(i, j):
                replacements += 1
                grid[i][j] = -grid[i][j]

    return replacements

