def books_per_year(n, book_list):
    from collections import defaultdict

    year_count = defaultdict(int)

    for entry in book_list:
        year, book = entry.split(" ", 1)
        year_count[int(year)] += 1

    result = []
    for year in sorted(year_count.keys()):
        result.append(f"{year} {year_count[year]}")

    return "\n".join(result)

def min_operations_to_palindrome(s):
    """
    Returns the minimum number of operations required to make the string a palindrome.
    """
    def lcs(x , y):
        m = len(x)
        n = len(y)
        L = [[None]*(n+1) for i in range(m+1)]

        for i in range(m+1):
            for j in range(n+1):
                if i == 0 or j == 0 :
                    L[i][j] = 0
                elif x[i-1] == y[j-1]:
                    L[i][j] = L[i-1][j-1] + 1
                else:
                    L[i][j] = max(L[i-1][j] , L[i][j-1])

        return L[m][n]

    rev_s = s[::-1]
    lcs_length = lcs(s, rev_s)

    return len(s) - lcs_length

