def largest_square(n, grid):
    """
    Find the size of the largest square sub-grid that consists of only empty cells.

    :param n: int, the size of the grid (n x n)
    :param grid: list of str, each string represents a row of the grid
    :return: int, the side length of the largest square of empty cells
    """
    if n == 0:
        return 0

    dp = [[0] * n for _ in range(n)]
    max_side = 0

    # Populate the DP table
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '.':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])
            else:
                dp[i][j] = 0

    return max_side

