def min_cuts(n, m, garden):
    """
    Returns the minimum number of cuts required to isolate each flower in the garden.
    """
    horizontal_cuts = 0
    vertical_cuts = 0

    # Count horizontal cuts
    for i in range(n):
        previous_was_flower = False
        for j in range(m):
            if garden[i][j] == 'F':
                if not previous_was_flower:
                    horizontal_cuts += 1
                    previous_was_flower = True
            else:
                previous_was_flower = False

    # Count vertical cuts
    for j in range(m):
        previous_was_flower = False
        for i in range(n):
            if garden[i][j] == 'F':
                if not previous_was_flower:
                    vertical_cuts += 1
                    previous_was_flower = True
            else:
                previous_was_flower = False

    return min(horizontal_cuts, vertical_cuts)

from collections import deque

def shortest_path(grid):
    m, n = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[m-1][n-1] == '#':
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (x, y, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if x == m - 1 and y == n - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] == '.':
                queue.append((nx, ny, dist + 1))
                visited.add((nx, ny))

    return -1

# Function to convert input in required format
def find_shortest_path(m, n, grid_input):
    grid = grid_input.split()
    return shortest_path(grid)

