def find_city_name(n, l, m, q, city_data, queries):
    city_features_map = {}

    # Mapping city names to their respective features
    for data in city_data:
        parts = data.split()
        city_name = parts[0]
        features = tuple(map(float, parts[1:]))
        city_features_map[features] = city_name

    results = []
    for query in queries:
