def longest_same_parity_subarray(n, arr):
    if n == 0:
        return 0

    max_length = 1
    current_length = 1
    current_parity = arr[0] % 2

    for i in range(1, n):
        if arr[i] % 2 == current_parity:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1
            current_parity = arr[i] % 2

    max_length = max(max_length, current_length)
    return max_length

