def longest_palindromic_subseq_sum(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = ord(s[i])

    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2 * ord(s[i])
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return dp[0][n - 1]

def palindromic_subsequence_sum(T, lst):
    results = []
    for s in lst:
        results.append(longest_palindromic_subseq_sum(s))
