def has_cycle(N, M, edges):
    """
    Checks whether a cycle exists in an undirected graph.

    Parameters:
    N (int): Number of nodes.
    M (int): Number of edges.
    edges (list of tuples): List of edges where each edge is represented as a tuple (u, v).

    Returns:
    str: "Cycle Found" if a cycle exists, otherwise "No Cycle".
    """
    from collections import defaultdict

    def find(parent, i):
        if parent[i] == i:
            return i
        return find(parent, parent[i])

    def union(parent, rank, x, y):
        xroot = find(parent, x)
        yroot = find(parent, y)

        if xroot != yroot:
            if rank[xroot] < rank[yroot]:
                parent[xroot] = yroot
            elif rank[xroot] > rank[yroot]:
                parent[yroot] = xroot
            else:
                parent[yroot] = xroot
                rank[xroot] += 1
            return False
        return True

    parent = []
    rank = []

    for node in range(N):
        parent.append(node)
        rank.append(0)

    for edge in edges:
        u, v = edge
        if union(parent, rank, u - 1, v - 1):
            return "Cycle Found"

    return "No Cycle"

