def find_jumping_numbers(n):
    """
    Returns a list of all Jumping Numbers less than or equal to n.
    """
    if n < 10:
        return list(range(n + 1))

    result = list(range(10))
    from collections import deque
    queue = deque(range(1, 10))

    while queue:
        current = queue.popleft()
        last_digit = current % 10

        if last_digit > 0:
            next_number = current * 10 + (last_digit - 1)
            if next_number <= n:
                queue.append(next_number)
                result.append(next_number)

        if last_digit < 9:
            next_number = current * 10 + (last_digit + 1)
            if next_number <= n:
                queue.append(next_number)
                result.append(next_number)

    return sorted(result)

def jumping_numbers(t, test_cases):
    results = []
    for n in test_cases:
        results.append(find_jumping_numbers(n))
    return results

