def find_kth_smallest(n, k, arr1, arr2):
    """
    Returns the kth smallest element in the merged array formed by merging arr1 and arr2.
    """
    # Two pointer technique
    i, j, count = 0, 0, 0
    while i < n and j < n:
        if arr1[i] < arr2[j]:
            count += 1
            if count == k:
                return arr1[i]
            i += 1
        else:
            count += 1
            if count == k:
                return arr2[j]
            j += 1

    # If one of the arrays is exhausted
    while i < n:
        count += 1
        if count == k:
            return arr1[i]
        i += 1

    while j < n:
        count += 1
        if count == k:
            return arr2[j]
        j += 1

# Example usage
# n, k = 5, 3
