def max_planes_on_ground(flights):
    events = []

    for flight in flights:
        landing, departure = flight
        events.append((landing, 'arrive'))
        events.append((departure, 'depart'))

    events.sort()

    max_planes = 0
    current_planes = 0

    for event in events:
        if event[1] == 'arrive':
            current_planes += 1
            if current_planes > max_planes:
                max_planes = current_planes
        elif event[1] == 'depart':
            current_planes -= 1

    return max_planes

