def longest_palindromic_subsequence(S):
    """
    Returns the length of the longest palindromic subsequence in string S.
    """
    n = len(S)
    dp = [[0] * n for _ in range(n)]

    # Base case: Single letters are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table
    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if S[i] == S[j] and cl == 2:
                dp[i][j] = 2
            elif S[i] == S[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return dp[0][n - 1]

def process_test_cases(T, test_cases):
    """
    Process multiple test cases.
    """
    results = []
    for S in test_cases:
        results.append(longest_palindromic_subsequence(S))
    return results

