def min_chars_to_make_palindrome(S):
    """
    Returns the minimum number of characters that need to be added to S to make it a palindrome.
    """
    def is_palindrome(s):
        return s == s[::-1]

    n = len(S)
    for i in range(n):
        if is_palindrome(S[i:]):
            return i
    return n

