from collections import deque

def shortest_path_bfs(n, edges, start, end):
    adj_list = {i: [] for i in range(1, n+1)}
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    queue = deque([(start, 0)])
    visited = set()
    visited.add(start)

    while queue:
        node, distance = queue.popleft()
        if node == end:
            return distance

        for neighbor in adj_list[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))

    return -1

def delivery_service(n, m, edges, queries):
    results = []
    for a, b in queries:
        results.append(shortest_path_bfs(n, edges, a, b))
    return results

