def is_palindrome(s):
    return s == s[::-1]

def find_palindromic_substrings(S):
    result = []
    for i in range(len(S)):
        for j in range(i, len(S)):
            if is_palindrome(S[i:j+1]):
                result.append((i, j))
    return result if result else "No palindromic substrings"

def construct_matrix(n):
    if n % 2 == 0:
        return -1

    matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            matrix[i][j] = (i + j) % n + 1
    return matrix

def check_file_sizes(T, file_sizes):
    """
    This function takes an integer T and a list of integer file_sizes.
    It returns a list where for each file size if it's a power of two it returns '1' or 'Invalid Size' if it's not.
    """
    def is_power_of_two(n):
        return (n & (n - 1) == 0) and n != 0

    results = []
    for size in file_sizes:
        if is_power_of_two(size):
            results.append('1')
        else:
            results.append('Invalid Size')
    return results

