def count_books_by_genre(test_cases):
    results = []
    for books in test_cases:
        genre_count = {}
        for title, genre in books:
            if genre in genre_count:
                genre_count[genre] += 1
            else:
                genre_count[genre] = 1
        sorted_genres = sorted(genre_count.items())
        results.append("\n".join(f"{genre}: {count}" for genre, count in sorted_genres))
    return results

def process_input(input_data):
    lines = input_data.strip().split("\n")
    T = int(lines[0])
    index = 1
    test_cases = []

    for _ in range(T):
        N = int(lines[index])
        books = []
        for i in range(index + 1, index + 1 + N):
            title_genre = lines[i].rsplit(',', 1)
            title = title_genre[0]
            genre = title_genre[1]
            books.append((title, genre))
        test_cases.append(books)
        index += 1 + N

    return test_cases

def max_tokens(grid):
    n = len(grid)
    dp = [[0]*n for _ in range(n)]

    # Initialize dp table
    if grid[0][0] == 'E':
        dp[0][0] = 0
    else:
        dp[0][0] = 1

    # Fill dp table for the first row
    for j in range(1, n):
        if grid[0][j] == 'T':
            dp[0][j] = dp[0][j - 1] + 1
        else:
            dp[0][j] = dp[0][j - 1]

    # Fill dp table for the first column
    for i in range(1, n):
        if grid[i][0] == 'T':
            dp[i][0] = dp[i - 1][0] + 1
        else:
            dp[i][0] = dp[i - 1][0]

    # Fill the rest of dp table
    for i in range(1, n):
        for j in range(1, n):
            if grid[i][j] == 'T':
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]) + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[n - 1][n - 1]

