def unique_paths_with_obstacles(grid):
    """
    Given a grid with obstacles, return the number of unique paths from top-left to bottom-right.
    :param grid: List[List[int]]: The grid with 0 as open cell and 1 as an obstacle.
    :return: int: Number of unique paths.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    N = len(grid)
    M = len(grid[0])

    dp = [[0] * M for _ in range(N)]

    dp[0][0] = 1 - grid[0][0]

    for i in range(1, N):
        dp[i][0] = dp[i-1][0] * (1 - grid[i][0])

    for j in range(1, M):
        dp[0][j] = dp[0][j-1] * (1 - grid[0][j])

    for i in range(1, N):
        for j in range(1, M):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0

    return dp[-1][-1]

