def balance_string(s: str) -> int:
    """
    Counts the maximum number of balanced substrings that can be obtained from the input string.
    """
    balance = 0
    balanced_count = 0

    for char in s:
        if char == 'L':
            balance += 1
        else:
            balance -= 1

        if balance == 0:
            balanced_count += 1

    return balanced_count

