def largest_connected_component_size(N, M, edges):
    def dfs(node):
        stack = [node]
        size = 0
        while stack:
            u = stack.pop()
            if not visited[u]:
                visited[u] = True
                size += 1
                for v in graph[u]:
                    if not visited[v]:
                        stack.append(v)
        return size

    # Initialize the graph
    graph = {i: [] for i in range(N)}

    # Add the edges
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Track visited nodes
    visited = [False] * N

    largest_size = 0

    # Iterate over all nodes
    for i in range(N):
        if not visited[i]:
            component_size = dfs(i)
            largest_size = max(largest_size, component_size)

    return largest_size

