from collections import Counter

def longest_palindromic_subsequence_length(n, stones):
    count = Counter(stones)
    length = 0
    odd_count = 0

    for c in count.values():
        if c % 2 == 0:
            length += c
        else:
            length += c - 1
            odd_count += 1

    if odd_count > 0:
        length += 1

    return length

