def largest_connected_region(n, m, grid):
    """
    Returns the size of the largest connected region of 1s in the grid.
    """
    def dfs(x, y):
        if x < 0 or x >= n or y < 0 or y >= m or grid[x][y] == 0:
            return 0

        grid[x][y] = 0  # Mark this cell as visited
        size = 1  # Initialize region size

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:  # directions: up, down, left, right
            size += dfs(x + dx, y + dy)

        return size

    max_region = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                max_region = max(max_region, dfs(i, j))

    return max_region

def find(parent, i):
    if parent[i] == i:
        return i
    else:
        parent[i] = find(parent, parent[i])
        return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if xroot != yroot:
        if rank[xroot] > rank[yroot]:
            parent[yroot] = xroot
        elif rank[xroot] < rank[yroot]:
            parent[xroot] = yroot
        else:
            parent[yroot] = xroot
            rank[xroot] += 1

def min_connections_to_fully_connect(n, connections):
    parent = [i for i in range(n)]
    rank = [0] * n

    for u, v in connections:
        union(parent, rank, u-1, v-1)

    unique_components = len(set(find(parent, i) for i in range(n)))
    return unique_components - 1

