def parse_catalog(catalog):
    entries = catalog.split(';')
    category_dict = {}

    for entry in entries:
        parts = entry.split(',')
        book_id = parts[0]
        num_categories = int(parts[2])
        if num_categories > 0:
            categories = parts[3:3 + num_categories]
            for category in categories:
                if category not in category_dict:
                    category_dict[category] = []
                category_dict[category].append(book_id)

    unique_categories = list(category_dict.keys())
    unique_categories.sort()
    result = [str(len(unique_categories))]
    for category in unique_categories:
        result.append(f"{category} {' '.join(category_dict[category])}")

    return "\n".join(result)

