def num_ways_to_paint_fence(n, k):
    MOD = 1000000007

    if n == 0:
        return 0
    if n == 1:
        return k

    same = k
    diff = k * (k - 1)

    for i in range(3, n + 1):
        prev_diff = diff
        diff = (same + diff) * (k - 1) % MOD
        same = prev_diff

    return (same + diff) % MOD

