def largest_square_submatrix(matrix, n, m):
    """
    Given a n x m matrix of 0s and 1s, returns the size of the largest square sub-matrix containing only 1s.
    """
    if n == 0 or m == 0:
        return 0

    # Create a DP table initialized with 0s
    dp = [[0] * m for _ in range(n)]
    max_size = 0

    for i in range(n):
        for j in range(m):
            # If we're at the first row or first column, the value is the same as the matrix's value
            if i == 0 or j == 0:
                dp[i][j] = matrix[i][j]
            elif matrix[i][j] == 1:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
            else:
                dp[i][j] = 0

            # Keep track of the maximum size of square sub-matrix containing 1s
            if dp[i][j] > max_size:
                max_size = dp[i][j]

    return max_size

def solve_largest_square_submatrix(t, test_cases):
    """
    Processes multiple test cases for the largest square sub-matrix containing only 1s problem.
    """
    results = []
    for case in test_cases:
        n, m, matrix = case
        result = largest_square_submatrix(matrix, n, m)
        results.append(result)

    return results

