def count_unique_users(transaction_logs, start_time, end_time):
    """
    Returns the number of unique users who performed each type of transaction within the specified time range.

    Parameters:
    transaction_logs (list): List of transaction logs; each log is a tuple (timestamp, user_id, transaction_type)
    start_time (int): Start of the time range (inclusive)
    end_time (int): End of the time range (inclusive)

    Returns:
    dict: A dictionary where keys are transaction types and values are the number of unique users
    """
    transaction_dict = {}
    for log in transaction_logs:
        timestamp, user_id, transaction_type = log
        if start_time <= timestamp <= end_time:
            if transaction_type not in transaction_dict:
                transaction_dict[transaction_type] = set()
            transaction_dict[transaction_type].add(user_id)

    for transaction_type in transaction_dict:
        transaction_dict[transaction_type] = len(transaction_dict[transaction_type])

    return transaction_dict

