def sum_of_even_integers(datasets):
    results = []
    for dataset in datasets:
        if dataset[0] == 0:
            break
        n = dataset[0]
        integers = dataset[1:n+1]
        even_sum = sum(x for x in integers if x % 2 == 0)
        results.append(even_sum)
    return results

def parse_input(input_data):
    lines = input_data.strip().split('\n')
    datasets = []
    for line in lines:
        dataset = list(map(int, line.split()))
        datasets.append(dataset)
    return datasets

def process_input(input_data):
    datasets = parse_input(input_data)
    return sum_of_even_integers(datasets)

