def min_steps(grid):
    """
    Returns the minimum number of steps required for the robot to reach the target position
    from the start position, or -1 if it is unreachable.
    """
    # Locate start and target positions
    start = target = None
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                target = (i, j)
            if start and target:
                break
        if start and target:
            break

    if not start or not target:
        return -1

    # Initialize BFS
    q = deque([(start[0], start[1], 0)])  # (row, col, steps)
    visited = set([start])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    while q:
        x, y, steps = q.popleft()
        if (x, y) == target:
            return steps
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] != 1 and (nx, ny) not in visited:
                visited.add((nx, ny))
                q.append((nx, ny, steps + 1))

    return -1

def three_sum(nums):
    """
    Return all unique triplets [nums[i], nums[j], nums[k]] such that they sum up to zero.
    """
    nums.sort()
    result = []
    n = len(nums)

    for i in range(n):
        if i > 0 and nums[i] == nums[i-1]:
            continue

        left, right = i + 1, n - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                result.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif total < 0:
                left += 1
            else:
                right -= 1
    return result

