def findSmallestSubstring(S: str, K: int) -> int:
    if len(set(S)) < K:
        return -1

    freq = {}
    min_len = float('inf')
    distinct_count = 0
    left = 0

    for right in range(len(S)):
        if S[right] not in freq:
            freq[S[right]] = 0
        freq[S[right]] += 1

        if freq[S[right]] == 1:
            distinct_count += 1

        while distinct_count >= K:
            min_len = min(min_len, right - left + 1)
            freq[S[left]] -= 1
            if freq[S[left]] == 0:
                distinct_count -= 1
            left += 1

    return min_len if min_len != float('inf') else -1

