def count_trees_burned(grid, r_s, c_s):
    R = len(grid)
    C = len(grid[0])

    def dfs(r, c):
        if r < 0 or r >= R or c < 0 or c >= C or grid[r][c] == 0:
            return 0
        grid[r][c] = 0  # Mark this cell as burned
        return 1 + dfs(r + 1, c) + dfs(r - 1, c) + dfs(r, c + 1) + dfs(r, c - 1)

    return dfs(r_s, c_s)

