import heapq

def process_queries(n, queries):
    min_heap = []
    results = []

    for query in queries:
        if query.startswith("add"):
            _, x = query.split()
            heapq.heappush(min_heap, int(x))
        elif query == "remove_min":
            if min_heap:
                results.append(heapq.heappop(min_heap))
            else:
                results.append("None")

    return results

