def min_transactions(transactions):
    from collections import defaultdict

    # Stack to hold running sums
    stack = []
    sum_map = defaultdict(int)
    current_sum = 0

    for transaction in transactions:
        current_sum += transaction
        if current_sum == 0:
            # Found a zero sum from the beginning
            stack.clear()
            sum_map.clear()
        elif current_sum in sum_map:
            # Found a zero sum subarray
            pos = sum_map[current_sum]
            del stack[pos:]
        else:
            sum_map[current_sum] = len(stack)
            stack.append(transaction)

    return len(stack)

