from itertools import combinations

def is_independent_set(graph, subset):
    """
    Check if the given subset of vertices form an independent set in the graph.
    """
    for v1, v2 in combinations(subset, 2):
        if v2 in graph[v1]:
            return False
    return True

def max_independent_set_size(V, edges):
    """
    Return the size of the maximum independent set in the graph.
    """
    graph = {i: set() for i in range(V)}
    for v1, v2 in edges:
        graph[v1].add(v2)
        graph[v2].add(v1)

    max_size = 0
    for r in range(V + 1):
        for subset in combinations(range(V), r):
            if is_independent_set(graph, subset):
                max_size = max(max_size, len(subset))
    return max_size

