def is_prime(n):
    """Return True if n is prime, else False"""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_sum_subarrays(n, a):
    # Compute all possible subarray sums
    sums = []
    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += a[j]
            sums.append(current_sum)

    # Store sums that are prime
    prime_sums = set()
    for s in sums:
        if is_prime(s):
            if s in prime_sums:
                return "YES"
            prime_sums.add(s)

    return "NO"

