def longest_arith_seq_length(arr):
    if not arr:
        return 0

    n = len(arr)
    if n == 1:
        return 1

    # dp[i][d] holds the length of arithmetic subsequence ending at index i with common difference d
    dp = [{} for _ in range(n)]
    longest_length = 2

    for i in range(1, n):
        for j in range(i):
            diff = arr[i] - arr[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2
            longest_length = max(longest_length, dp[i][diff])

    return longest_length

