def process_commands(commands):
    lst = []
    results = []
    for command in commands:
        if command == "END":
            break
        action = command.split()
        if action[0] == "ADD":
            lst.append(int(action[1]))
        elif action[0] == "REMOVE":
            try:
                lst.remove(int(action[1]))
            except ValueError:
                pass
        elif action[0] == "PRINT":
