def count_new_roads(n, m, roads):
    from collections import defaultdict, deque

    def bfs(start, visited, adj_list):
        queue = deque([start])
        visited[start] = True
        component_size = 0
        while queue:
            node = queue.popleft()
            component_size += 1
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return component_size

    if n == 1:
        return 1 if m == 0 else 0

    adj_list = defaultdict(list)
    for u, v in roads:
        adj_list[u].append(v)
        adj_list[v].append(u)

    visited = [False] * (n + 1)
    components = []

    for planet in range(1, n + 1):
        if not visited[planet]:
            component_size = bfs(planet, visited, adj_list)
            components.append(component_size)

    if len(components) == 1:
        return 1

    components.sort(reverse=True)
    total_ways = 1
    for component in components[:-1]:
        total_ways *= component * components[-1]

    return total_ways

