import heapq

def floyd_warshall(n, edges):
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0
    for u, v, l in edges:
        dist[u-1][v-1] = min(dist[u-1][v-1], l)
        dist[v-1][u-1] = min(dist[v-1][u-1], l)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

def shortest_path(n, m, q, edges, queries):
    dist = floyd_warshall(n, edges)
    results = []
    for a, b in queries:
        result = dist[a-1][b-1] if dist[a-1][b-1] != float('inf') else -1
        results.append(result)
    return results

