def compute_aggregate_grid(t, test_cases):
    results = []

    for case in test_cases:
        n, m, original_grid = case
        aggregate_grid = [[0] * m for _ in range(n)]

        for i in range(n):
            for j in range(m):
                current_value = original_grid[i][j]
                if i > 0:
                    current_value += aggregate_grid[i-1][j]
                if j > 0:
                    current_value += aggregate_grid[i][j-1]
                if i > 0 and j > 0:
                    current_value -= aggregate_grid[i-1][j-1]
                aggregate_grid[i][j] = current_value

        results.append(aggregate_grid)

    return results

