import sys

def floyd_warshall(n, dist):
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

def find_shortest_paths(n, roads, queries):
    # Initialize the distances matrix with infinity
    dist = [[float('inf')] * n for _ in range(n)]

    # Distance to self is 0
    for i in range(n):
        dist[i][i] = 0

    # Populate the distances with the given road times
    for u, v, t in roads:
        dist[u-1][v-1] = t

    # Use the Floyd-Warshall algorithm to find all-pairs shortest paths
    floyd_warshall(n, dist)

    # Answer the queries
    results = []
    for a, b in queries:
        distance = dist[a-1][b-1]
        if distance == float('inf'):
            results.append(-1)
        else:
            results.append(distance)

    return results

def group_anagrams(datasets):
    def sorted_word(word):
        return ''.join(sorted(word))

    def process_dataset(words):
        sorted_word_dict = {}

        for word in words:
            key = sorted_word(word)
            if key in sorted_word_dict:
                sorted_word_dict[key].append(word)
            else:
                sorted_word_dict[key] = [word]

        result = []
        for anagrams in sorted_word_dict.values():
            anagrams.sort()
            result.append(anagrams)

        return result

    results = []
    for dataset in datasets:
        words = dataset.split()
        groups = process_dataset(words)
        groups_sorted = sorted(groups, key=lambda x: x[0])
        results.append(groups_sorted)

    return results

def is_valid_parentheses_sequence(n, operations):
    """
    Determine if the given sequence of operations results in a valid parentheses string.

    :param n: int, the number of operations.
    :param operations: str, the sequence of operations containing '(' and ')'.
    :return: str, "valid" or "invalid" based on whether the sequence is valid.
    """
    balance = 0

    for op in operations:
        if op == '(':
            balance += 1
        elif op == ')':
            balance -= 1
        if balance < 0:
            return "invalid"

    return "valid" if balance == 0 else "invalid"

