def max_possible_value(n, k, values):
    """
    Finds the maximum possible value that can be stored in k gift boxes.
    """
    if k == 1:  # If there's only one box, return the smallest value in the list.
        return min(values)

    # Sort values in descending order
    values.sort(reverse=True)

    # The highest k values represent the minimum value of k segments
    return sum(values[:k])

