def find_ranks_and_queries(n, q, scores, queries):
    # Create a list of (score, index) tuples for sorting
    score_index_pairs = [(scores[i], i) for i in range(n)]
    # Sort based on score in descending order
    score_index_pairs.sort(reverse=True, key=lambda x: x[0])

    # Initialize ranks array
    ranks = [0] * n
    current_rank = 1

    for i in range(n):
        if i == 0:
            ranks[score_index_pairs[i][1]] = current_rank
        else:
            if score_index_pairs[i][0] < score_index_pairs[i - 1][0]:
                current_rank = i + 1
            ranks[score_index_pairs[i][1]] = current_rank

    # Handle the queries
    results = []
    for query in queries:
        results.append(ranks[query - 1])

    return results

