from collections import deque

def can_alice_reach_bob(grid, start, end):
    """
    Determines if Alice (A) can reach Bob (B) in a forest represented by a 2D grid.

    Args:
    grid (list of list of str): The 2D grid representing the forest.
    start (tuple of int): The starting coordinates of Alice (A).
    end (tuple of int): The coordinates of Bob (B).

    Returns:
    str: "YES" if Alice can reach Bob, otherwise "NO".
    """
    N = len(grid)
    M = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    queue = deque([start])
    visited = set([start])

    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < M and (nx, ny) not in visited and grid[nx][ny] != 'T':
                visited.add((nx, ny))
                queue.append((nx, ny))

    return "NO"

def process_grid(N, M, grid):
    start = None
    end = None
    for i in range(N):
        for j in range(M):
            if grid[i][j] == 'A':
                start = (i, j)
            elif grid[i][j] == 'B':
                end = (i, j)

    return can_alice_reach_bob(grid, start, end)

