def distributeRewards(ratings):
    n = len(ratings)
    if n == 0: return 0

    rewards = [1] * n

    # From left to right, ensure right neighbor rules are met
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            rewards[i] = rewards[i - 1] + 1

    # From right to left, ensure left neighbor rules are met
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            rewards[i] = max(rewards[i], rewards[i + 1] + 1)

    return sum(rewards)

