def find_substring(s, words):
    if not s or not words:
        return []

    word_length = len(words[0])
    word_count = len(words)
    total_length = word_length * word_count

    # Creating a frequency map of the words
    word_map = {}
    for word in words:
        if word in word_map:
            word_map[word] += 1
        else:
            word_map[word] = 1

    def is_valid(start):
        seen = {}
        words_used = 0
        for i in range(start, start + total_length, word_length):
            part = s[i:i+word_length]
            if part in word_map:
                if part in seen:
                    seen[part] += 1
                else:
                    seen[part] = 1
                if seen[part] > word_map[part]:
                    return False
                words_used += 1
            else:
                return False
        return words_used == word_count

    result = []
    for i in range(len(s) - total_length + 1):
        if is_valid(i):
            result.append(i)

    return result

def tallest_plant(n, m, growth_patterns):
    """
    Determines the type of plant that will be the tallest on the last day (m-th day).
    Returns the 1-based index of the type with the maximum height on the m-th day.
    """
    tallest_index = 0
    max_height = -1

    for i in range(n):
        height_on_last_day = growth_patterns[i][m-1]
        if height_on_last_day > max_height:
            max_height = height_on_last_day
            tallest_index = i
        elif height_on_last_day == max_height:
            if i < tallest_index:
                tallest_index = i

    return tallest_index + 1

