def max_cargo_value(datasets):
    """
    Function to calculate the maximum total value of containers
    that can be loaded onto the ship without exceeding the weight capacity.
    """
    results = []
    for dataset in datasets:
        n, W = dataset[0]
        if n == 0 and W == 0:
            continue

        weights = []
        values = []
        for i in range(1, n+1):
            wi, vi = dataset[i]
            weights.append(wi)
            values.append(vi)

        dp = [0] * (W + 1)

        for i in range(n):
            for w in range(W, weights[i] - 1, -1):
                if w >= weights[i]:
                    dp[w] = max(dp[w], dp[w - weights[i]] + values[i])

        results.append(dp[W])

    return results

