def can_schedule_all_training(n, k, trainer_hours, animal_times):
    # Sort the trainer hours in descending order
    trainer_hours.sort(reverse=True)

    # Sort the animal times in descending order
    animal_times.sort(reverse=True)

    # Try to assign each animal to a trainer
    for i in range(n):
        assigned = False
        for j in range(k):
            if trainer_hours[j] >= animal_times[i]:
                trainer_hours[j] -= animal_times[i]
                assigned = True
                break
        if not assigned:
            return "No"

    return "Yes"

