from collections import deque

def min_operations(initial_sequence, final_sequence):
    """
    Calculate the minimum number of operations to transform initial_sequence into final_sequence.
    """

    def find_min_operations(x, y):
        """
        Use a BFS strategy to find the minimum operations needed to transform x into y.
        """
        if x == y:
            return 0

        queue = deque([(x, 0)])
        visited = set([x])

        while queue:
            current, steps = queue.popleft()

            # Generate the possible operations
            for operation_result in (current + 1, current - 1, current * 2):
                if operation_result == y:
                    return steps + 1

                if operation_result not in visited and 0 <= operation_result <= 2 * max(x, y):
                    visited.add(operation_result)
                    queue.append((operation_result, steps + 1))

            if current % 2 == 0:
                operation_result = current // 2
                if operation_result == y:
                    return steps + 1
                if operation_result not in visited:
                    visited.add(operation_result)
                    queue.append((operation_result, steps + 1))

        # It cannot reach here in theory due to the constraints
        return -1

    n = len(initial_sequence)
    total_operations = 0

    for i in range(n):
        total_operations += find_min_operations(initial_sequence[i], final_sequence[i])

    return total_operations

