def count_subsequences(S1, S2):
    """
    Returns the number of times the string S2 appears as a subsequence in the string S1.
    """
    m, n = len(S1), len(S2)

    if n == 0:
        return 1
    if m == 0:
        return 0

    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = 1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if S1[i - 1] == S2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[m][n]

