def can_fire_reach(grid, N, M, Q, queries):
    from collections import deque

    def bfs(start_x, start_y, end_x, end_y):
        queue = deque([(start_x, start_y)])
        visited = set([(start_x, start_y)])

        while queue:
            x, y = queue.popleft()

            if (x, y) == (end_x, end_y):
                return "Yes"

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy

                if 0 <= nx < N and 0 <= ny < M and (nx, ny) not in visited and grid[nx][ny] == 'T':
                    visited.add((nx, ny))
                    queue.append((nx, ny))

        return "No"

    results = []
    for sx, sy, ex, ey in queries:
        if grid[sx][sy] == 'T' and grid[ex][ey] == 'T':
            results.append(bfs(sx, sy, ex, ey))
        else:
            results.append("No")

    return results

