def max_coins(t, test_cases):
    results = []
    for case in test_cases:
        m, n, grid = case['m'], case['n'], case['grid']
        dp = [[-1] * n for _ in range(m)]
        if grid[0][0] == -1 or grid[m-1][n-1] == -1:
            results.append(-1)
            continue

        dp[0][0] = 0

        for i in range(m):
            for j in range(n):
                if grid[i][j] == -1:
                    continue
                if i > 0 and dp[i-1][j] != -1:
                    dp[i][j] = max(dp[i][j], dp[i-1][j] + grid[i][j])
                if j > 0 and dp[i][j-1] != -1:
                    dp[i][j] = max(dp[i][j], dp[i][j-1] + grid[i][j])

        results.append(dp[m-1][n-1] if dp[m-1][n-1] != -1 else -1)
    return results

def parse_input(input_data):
    lines = input_data.strip().split('\n')
    t = int(lines[0])
    idx = 1
    test_cases = []
    for _ in range(t):
        m, n = map(int, lines[idx].split())
        idx += 1
        grid = []
        for _ in range(m):
            grid.append(list(map(int, lines[idx].split())))
            idx += 1
        test_cases.append({'m': m, 'n': n, 'grid': grid})
    return t, test_cases

def max_combined_scare_capacity(n, w, x, scarecrows):
    """
    Returns the maximum combined scare capacity of exactly two scarecrows within budget.
    """
    wheat_scarecrows = []
    corn_scarecrows = []

    for si, pi, kind in scarecrows:
        if kind == "W":
            wheat_scarecrows.append((si, pi))
        elif kind == "C":
            corn_scarecrows.append((si, pi))

    max_combined_capacity = 0

    # Check combination of one wheat and one corn scarecrow
    for si_w, pi_w in wheat_scarecrows:
        if pi_w <= w:
            for si_c, pi_c in corn_scarecrows:
                if pi_c <= x:
                    max_combined_capacity = max(max_combined_capacity, si_w + si_c)

    return max_combined_capacity

def evaluate_rpn(expression):
    """
    Evaluate a Reverse Polish Notation (RPN) expression.

    Parameters:
    expression (str): A string containing a valid RPN expression with integers and operators separated by spaces.

    Returns:
    int: The result of the RPN expression evaluation.
    """
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            op2 = stack.pop()
            op1 = stack.pop()
            if token == '+':
                stack.append(op1 + op2)
            elif token == '-':
                stack.append(op1 - op2)
            elif token == '*':
                stack.append(op1 * op2)
            elif token == '/':
                stack.append(int(op1 / op2))  # Using int to truncate towards zero
        else:
            stack.append(int(token))

    return stack[0]

