def process_scooter_operations(s, a, t, operations):
    for operation in operations:
        parts = operation.split()
        if parts[0] == "pickup":
            i = int(parts[1])
            a[i] -= 1
        elif parts[0] == "return":
            i = int(parts[1])
            a[i] += 1
        elif parts[0] == "transit":
            i = int(parts[1])
            j = int(parts[2])
            k = int(parts[3])
            a[i] -= k
            a[j] += k
    return a

