def min_cost_subsets(t, test_cases):
    results = []

    for case in test_cases:
        n, m, costs, edges = case
        if m == 0:
            # No edges, just take the minimum cost vertex
            results.append(min(costs))
        else:
            min_edge_cost = float('inf')
            for u, v in edges:
                min_edge_cost = min(min_edge_cost, costs[u-1], costs[v-1])
            results.append(min_edge_cost)

    return results


def get_input_and_solve(input_data):
    input_lines = input_data.strip().split('\n')
    t = int(input_lines[0])
    test_cases = []

    index = 1
    for _ in range(t):
        n, m = map(int, input_lines[index].split())
        index += 1
        costs = list(map(int, input_lines[index].split()))
        index += 1
        edges = []
        for _ in range(m):
            u, v = map(int, input_lines[index].split())
            edges.append((u, v))
            index += 1
        test_cases.append((n, m, costs, edges))

    return min_cost_subsets(t, test_cases)

