def track_distinct_toys(test_cases):
    results = []
    for case in test_cases:
        operations = case['operations']
        inventory = set()
        for operation in operations:
            op = operation.split()
            command = op[0]
            toy_id = int(op[1])

            if command == "ADD":
                inventory.add(toy_id)
            elif command == "REMOVE" and toy_id in inventory:
                inventory.remove(toy_id)

            results.append(len(inventory))
    return results

