import math

def closestPair(points):
    def distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    def closest_pair_recursive(points_sorted_by_x, points_sorted_by_y):
        num_points = len(points_sorted_by_x)
        if num_points <= 3:
            return min(distance(points_sorted_by_x[i], points_sorted_by_x[j])
                       for i in range(num_points) for j in range(i + 1, num_points))

        mid = num_points // 2
        mid_point = points_sorted_by_x[mid]

        left_of_center = points_sorted_by_x[:mid]
        right_of_center = points_sorted_by_x[mid:]

        closest_distance_left = closest_pair_recursive(left_of_center, points_sorted_by_y)
        closest_distance_right = closest_pair_recursive(right_of_center, points_sorted_by_y)

        closest_distance = min(closest_distance_left, closest_distance_right)

        in_strip = [point for point in points_sorted_by_y if abs(point[0] - mid_point[0]) < closest_distance]

        for i in range(len(in_strip)):
            for j in range(i + 1, len(in_strip)):
                if (in_strip[j][1] - in_strip[i][1]) >= closest_distance:
                    break
                closest_distance = min(closest_distance, distance(in_strip[i], in_strip[j]))

        return closest_distance

    points_sorted_by_x = sorted(points, key=lambda p: p[0])
    points_sorted_by_y = sorted(points, key=lambda p: p[1])

    return round(closest_pair_recursive(points_sorted_by_x, points_sorted_by_y), 3)

