def findCombinations(arr, target):
    def backtrack(start, path, target):
        if target == 0:
            result.append(path)
            return
        if target < 0:
            return

        for i in range(start, len(arr)):
            backtrack(i, path + [arr[i]], target - arr[i])

    result = []
    arr.sort()
    backtrack(0, [], target)
    return result

