def compress_string(s):
    compressed_str = []

    i = 0
    while i < len(s):
        count = 1
        while i + 1 < len(s) and s[i] == s[i+1]:
            i += 1
            count += 1
        compressed_str.append(f"{count}{s[i]}")
        i += 1

    return "".join(compressed_str)


def decompress_string(s):
    decompressed_str = []

    i = 0
    while i < len(s):
        count = int(s[i])
        char = s[i + 1]
        decompressed_str.append(char * count)
        i += 2

    return "".join(decompressed_str)


def run_length_encoding(t, test_cases):
    results = []
    for s in test_cases:
        if len(s) % 2 == 0 and all(s[i].isdigit() for i in range(0, len(s), 2)):
            # Case when it is compressed (even length and contains digit in even index)
            results.append(decompress_string(s))
        else:
            # Case when it is normal string
            results.append(compress_string(s))

    return results

