from typing import List

def find_peak_element(nums: List[int]) -> int:
    """
    Finds the index of a peak element in a sorted array of distinct integers.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2
        if nums[mid] < nums[mid + 1]:
            left = mid + 1
        else:
            right = mid

    return left

