def perform_operations(queries):
    string = []
    results = []

    for query in queries:
        action, char = query.split()

        if action == 'append':
            string.append(char)
        elif action == 'remove':
            if char in string:
                string.remove(char)
        elif action == 'count':
            results.append(string.count(char))

    return results

