from typing import List, Tuple

def consecutive_count(input_string: str) -> List[Tuple[str, int]]:
    if not input_string:
        return []

    result = []
    current_char = input_string[0]
    current_count = 1

    for char in input_string[1:]:
        if char == current_char:
            current_count += 1
        else:
            result.append((current_char, current_count))
            current_char = char
            current_count = 1

    result.append((current_char, current_count))

    return result

