def top_three_scores(student_scores):
    """
    Returns a list of tuples (name, score) representing the top three highest scores.
    """
    scores_dict = {}

    for student_score in student_scores:
        name, score = student_score.rsplit(' ', 1)
        score = int(score)
        if score in scores_dict:
            scores_dict[score].append(name)
        else:
            scores_dict[score] = [name]

    sorted_scores = sorted(scores_dict.keys(), reverse=True)

    result = []
    for score in sorted_scores:
        for name in scores_dict[score]:
            result.append((name, score))
        if len(result) >= 3:
            break

    return result

def is_path_possible(n, m, grid):
    from collections import deque

    # Finding the starting point S
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                end = (i, j)

    # Directions array for 4 possible movements (right, left, down, up)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    # Queue for BFS
    queue = deque([start])
    visited = set()
    visited.add(start)

    while queue:
        x, y = queue.popleft()

        # If we reached the end point
        if (x, y) == end:
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] != '#':
                queue.append((nx, ny))
                visited.add((nx, ny))

    return "NO"

def count_days_exceeding_previous(pages_read):
    """
    Returns the number of days on which the number of pages read exceeds the number of pages read on the previous day.
    """
    count = 0
    for i in range(1, len(pages_read)):
        if pages_read[i] > pages_read[i - 1]:
            count += 1
    return count

