def find_peak_element(arr):
    """
    Finds and returns the index of any peak element in the array.
    A peak element is defined as one which is greater than its neighbors.
    The search is done in O(log n) time using a binary search approach.
    """

    n = len(arr)

    def binary_search(low, high):
        if low == high:
            return low
        mid = (low + high) // 2

        if arr[mid] > arr[mid + 1]:
            return binary_search(low, mid)
        return binary_search(mid + 1, high)

    return binary_search(0, n - 1)

