from collections import deque

def shortest_cycle(N, E, edges):
    graph = [[] for _ in range(N)]

    for u, v in edges:
        graph[u - 1].append(v - 1)
        graph[v - 1].append(u - 1)

    def bfs(start):
        dist = [-1] * N
        parent = [-1] * N
        dist[start] = 0
        queue = deque([start])

        shortest = float('inf')

        while queue:
            node = queue.popleft()

            for neighbor in graph[node]:
                if dist[neighbor] == -1:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:
                    shortest = min(shortest, dist[node] + dist[neighbor] + 1)

        return shortest

    result = float('inf')

    for i in range(N):
        result = min(result, bfs(i))

    return result if result != float('inf') else -1

# Function to parse input and call the main function
def find_shortest_cycle(N, E, edge_list):
    edges = [tuple(map(int, edge.split())) for edge in edge_list]
    return shortest_cycle(N, E, edges)

