def min_cost_to_balance(s):
    """
    Returns the minimum cost to balance the string of brackets.
    """
    stack = []
    cost = 0

    bracket_map = {
        ')': '(',
        '}': '{',
        ']': '['
    }

    for char in s:
        if char in bracket_map.values():  # if it's one of '(', '{', '['
            stack.append(char)
        else:
            if stack and stack[-1] == bracket_map[char]:
                stack.pop()
            else:
                cost += 1  # unbalanced so increase the cost and imagine we change it
                if stack:
                    stack.pop()

    cost += len(stack)  # remaining opening brackets to be balanced by adding closing brackets
    return cost

