def subarray_sums(t, test_cases):
    results = []
    for i in range(t):
        n, q, a, queries = test_cases[i]
        # Precompute prefix sums
        prefix_sums = [0] * (n + 1)
        for j in range(1, n + 1):
            prefix_sums[j] = prefix_sums[j - 1] + a[j - 1]

        for l, r in queries:
            sum_subarray = prefix_sums[r] - prefix_sums[l - 1]
            results.append(sum_subarray)
    return results

