def num_paths(grid, n, m, k):
    """
    Returns the number of distinct paths from the top-left corner to the bottom-right corner
    of a grid with blockage information taken into account, with the result modulo k.
    """
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return 0

    dp = [[0 for _ in range(m)] for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= k

    return dp[n-1][m-1]

