def largest_connected_component(grid):
    n = len(grid)
    m = len(grid[0])

    visited = [[False] * m for _ in range(n)]

    def dfs(x, y, value):
        # Base case: if out of bounds or already visited or different value
        if x < 0 or y < 0 or x >= n or y >= m or visited[x][y] or grid[x][y] != value:
            return 0
        # Mark this cell as visited
        visited[x][y] = True
        # Count this cell, then visit all 4 neighbors
        return 1 + dfs(x+1, y, value) + dfs(x-1, y, value) + dfs(x, y+1, value) + dfs(x, y-1, value)

    max_component_size = 0

    for i in range(n):
        for j in range(m):
            if not visited[i][j]:
                current_component_size = dfs(i, j, grid[i][j])
                max_component_size = max(max_component_size, current_component_size)

    return max_component_size

