def encrypt_string(s):
    """
    Encrypts a string by replacing each letter with the letter three positions further down the alphabet.
    Non-alphabet characters remain unchanged.
    """
    def shift_letter(letter):
        if 'a' <= letter <= 'z':
            return chr((ord(letter) - ord('a') + 3) % 26 + ord('a'))
        elif 'A' <= letter <= 'Z':
            return chr((ord(letter) - ord('A') + 3) % 26 + ord('A'))
        else:
            return letter

    return ''.join(shift_letter(c) for c in s)

