def is_possible_to_move_all_workers(n, m, grid, k, positions):
    from collections import deque

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start, goal):
        queue = deque([start])
        visited = {start}

        while queue:
            current = queue.popleft()

            if current == goal:
                return True

            for dx, dy in directions:
                nxt = (current[0] + dx, current[1] + dy)
                if 0 <= nxt[0] < n and 0 <= nxt[1] < m and nxt not in visited and grid[nxt[0]][nxt[1]] == '.':
                    visited.add(nxt)
                    queue.append(nxt)

        return False

    for r1, c1, r2, c2 in positions:
        if not bfs((r1, c1), (r2, c2)):
            return "NO"

    return "YES"

def count_paths(n, m, k, blocked_cells):
    MOD = 998244353
    dp = [[0] * m for _ in range(n)]

    if (1, 1) in blocked_cells or (n, m) in blocked_cells:
        return 0

    dp[0][0] = 1

    blocked_set = set((x - 1, y - 1) for x, y in blocked_cells)

    for i in range(n):
        for j in range(m):
            if (i, j) in blocked_set:
                dp[i][j] = 0
            elif i == 0 and j == 0:
                continue
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[n-1][m-1]

