import heapq

def min_toll_to_travel(N, M, roads):
    # Create an adjacency list
    adj = {i: [] for i in range(1, N+1)}
    for u, v, w in roads:
        adj[u].append((v, w))
        adj[v].append((u, w))

    # Dijkstra's algorithm
    pq = [(0, 1)]  # (toll, city)
    tolls = {i: float('inf') for i in range(1, N+1)}
    tolls[1] = 0
    visited = set()

    while pq:
        current_toll, city = heapq.heappop(pq)

        if city in visited:
            continue
        visited.add(city)

        if city == N:
            return current_toll

        for neighbor, weight in adj[city]:
            if neighbor not in visited:
                new_toll = current_toll + weight
                if new_toll < tolls[neighbor]:
                    tolls[neighbor] = new_toll
                    heapq.heappush(pq, (new_toll, neighbor))

    return -1 if tolls[N] == float('inf') else tolls[N]

import math

def smallest_common_factor(a, b):
    """
    Returns the smallest common factor greater than 1 for a and b or "invalid" if no such factor exists.
    """
    gcd_ab = math.gcd(a, b)
    if gcd_ab > 1:
        return min((i for i in range(2, gcd_ab + 1) if gcd_ab % i == 0))
    return "invalid"

def process_test_cases(t, cases):
    results = []
    for a, b in cases:
