def can_transform(A, B):
    """
    Determines if string A can be transformed into string B by inserting exactly one character into A.
    """
    if len(B) - len(A) != 1:
        return "NO"

    i, j = 0, 0
    while i < len(A) and j < len(B):
        if A[i] != B[j]:
            if i != j:
                return "NO"
            j += 1
        else:
            i += 1
            j += 1

    return "YES"

from collections import deque

def shortest_path(M, N, startX, startY, endX, endY, grid):
    def is_valid(x, y):
        return 0 <= x < M and 0 <= y < N and grid[x][y] == '.'

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(startX, startY, 0)])
    visited = set((startX, startY))

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == (endX, endY):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                queue.append((nx, ny, dist + 1))
                visited.add((nx, ny))

    return -1

def parse_input(input_str):
    lines = input_str.strip().split('\n')
    M, N = map(int, lines[0].split())
    startX, startY, endX, endY = map(int, lines[1].split())
    grid = lines[2:]
    return M, N, startX, startY, endX, endY, grid

from collections import deque

def min_moves_to_reach_bottom_right(N, M, grid):
    if grid[0][0] == '#' or grid[N-1][M-1] == '#':
        return -1

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    visited = [[False] * M for _ in range(N)]
    queue = deque([(0, 0, 0)])
    visited[0][0] = True

    while queue:
        x, y, moves = queue.popleft()
        if x == N-1 and y == M-1:
            return moves

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and not visited[nx][ny] and grid[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny, moves + 1))

    return -1

