def is_prime(n):
    """
    Determines if n is a prime number.
    If n is a prime number, return "Prime". Otherwise, return "Not Prime".
    """
    if n <= 1:
        return "Not Prime"
    if n == 2:
        return "Prime"
    if n % 2 == 0:
