from typing import List

def is_prime(n: int) -> bool:
    """
    Helper function to determine if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_prime_subarray(nums: List[int], k: int) -> bool:
    """
    Function to check if there is a sub-array of length k in nums whose sum is a prime number.
    """
    n = len(nums)
    if k > n:
        return False

    # Compute the sum for first sub-array of length k
    current_sum = sum(nums[:k])

    if is_prime(current_sum):
        return True

    # Sliding window to compute sum of next sub-arrays of length k
    for i in range(k, n):
        current_sum += nums[i] - nums[i - k]
        if is_prime(current_sum):
            return True

    return False

def maximalRectangle(matrix):
    def max_histogram_area(heights):
        stack = []
        max_area = 0
        index = 0

        while index < len(heights):
            if not stack or heights[stack[-1]] <= heights[index]:
                stack.append(index)
                index += 1
            else:
                top_of_stack = stack.pop()
                area = (heights[top_of_stack] *
                        ((index - stack[-1] - 1) if stack else index))
                max_area = max(max_area, area)

        while stack:
            top_of_stack = stack.pop()
            area = (heights[top_of_stack] *
                    ((index - stack[-1] - 1) if stack else index))
            max_area = max(max_area, area)

        return max_area

    if not matrix:
        return 0

    n = len(matrix)
    m = len(matrix[0])

    heights = [0] * m
    max_area = 0

    for i in range(n):
        for j in range(m):
            if matrix[i][j] == 0:
                heights[j] = 0
            else:
                heights[j] += 1

        max_area = max(max_area, max_histogram_area(heights))

    return max_area

