def check_median_age(n, ages, k):
    """
    Returns "YES" if the median age of the group is greater than or equal to k, otherwise "NO".
    """
    ages.sort()
    if n % 2 == 1:
        median = ages[n // 2]
    else:
        median = (ages[n // 2 - 1] + ages[n // 2]) / 2

    if median >= k:
        return "YES"
    else:
        return "NO"

