from itertools import combinations

def is_prime(n):
    """
    Checks if a number n (n > 1) is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def subset_prime_sum_exists(b):
    """
    Given a list of integers b, checks if there is a subset with a prime sum.
    """
    n = len(b)
    for i in range(1, n + 1):
        for subset in combinations(b, i):
            if is_prime(sum(subset)):
                return "YES"
    return "NO"

def solve(test_cases):
    """
    Processes multiple test cases and returns the result for each.
    """
    results = []
    for test_case in test_cases:
        m, b = test_case
        results.append(subset_prime_sum_exists(b))
    return results

