from typing import List

def two_sum(nums: List[int], target: int) -> List[int]:
    """
    Returns the indices of the two numbers such that they add up to the target.
    """
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], i]
        num_to_index[num] = i
    return []

def is_match(s, p):
    """
    Determines if the pattern p matches the string s with wildcard characters.
    ? - matches any single character
    * - matches any sequence of characters (including an empty sequence)
    """
    # Initialize a 2D table to store results of subproblems
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Base case: empty pattern matches empty string
    dp[0][0] = True

    # Handle patterns with '*' at the beginning
    for j in range(1, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 1]

    # Fill the table in bottom-up fashion
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == s[i - 1] or p[j - 1] == '?':
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]

    return "YES" if dp[len(s)][len(p)] else "NO"

def min_replacements_to_palindrome(s):
    """
    Returns the minimum number of character replacements required to turn the given string into a palindrome.
    """
    count = 0
    n = len(s)
    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            count += 1
    return count

