            if dfs(x + 1, y):
                return True
            path.pop()
        if y + 1 < m and grid[x][y + 1] == 0:
            path.append('R')
            if dfs(x, y + 1):
                return True
            path.pop()
        return False

    if grid[0][0] == 0 and dfs(0, 0):
        return ''.join(path)
    else:
        return '-1'

def can_assign_unique_meanings(n, word_meanings):
    meaning_to_word = {}

    for word, meaning in word_meanings:
        if meaning in meaning_to_word:
            if meaning_to_word[meaning] != word:
                return "NO"
        else:
            meaning_to_word[meaning] = word

    return "YES"

