def maximize_permutation(n):
    """
    Generates a permutation of the first n natural numbers such that
    the sum of the absolute differences between the adjacent elements is maximized.
    """
    if n == 1:
        return [1]

    permutation = [1]
    for i in range(n-1):
        if i % 2 == 0:
            permutation.append(n - (i//2))
        else:
            permutation.append((i//2) + 2)

    return permutation

def solve(t, test_cases):
    results = []
    for n in test_cases:
        results.append(maximize_permutation(n))
    return results

