from typing import List

def find_longest_word(s: str, d: List[str]) -> str:
    def is_subsequence(x, y):
        it = iter(y)
        return all(c in it for c in x)

    d.sort(key=lambda x: (-len(x), x))
    for word in d:
        if is_subsequence(word, s):
            return word
    return ""

def min_deletions_to_convert(A, B):
    len_A = len(A)
    len_B = len(B)

    # Create a DP table to store the lengths of the longest common subsequence
    dp = [[0] * (len_B + 1) for _ in range(len_A + 1)]

    # Fill the DP table
    for i in range(1, len_A + 1):
        for j in range(1, len_B + 1):
            if A[i - 1] == B[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Length of the Longest Common Subsequence
    lcs_length = dp[len_A][len_B]

    # Minimum deletions required to transform A into B
    return len_A - lcs_length

from typing import List

def calculate_avg_rating(ratings: List[int]) -> int:
    if len(ratings) < 3:
        return 0

    highest_rating = max(ratings)
    lowest_rating = min(ratings)

    ratings.remove(highest_rating)
    ratings.remove(lowest_rating)

    avg_rating = sum(ratings) / len(ratings)
    return round(avg_rating)

