def increment_range(array, l, r, x):
    """
    Increments all elements in the range [l, r] by x.
    """
    for i in range(l-1, r):
        array[i] += x

def range_sum(array, l, r):
    """
    Returns the sum of elements in the range [l, r].
    """
    return sum(array[l-1:r])

def process_operations(n, q, array, operations):
    """
    Processes the operations and returns results for all range_sum queries.
    """
    results = []
    for operation in operations:
        if operation[0] == 1:
            _, l, r, x = operation
            increment_range(array, l, r, x)
        elif operation[0] == 2:
            _, l, r = operation
            results.append(range_sum(array, l, r))
    return results

def move_robot(n, m, x, y, k, commands):
    """
    Returns the final position of the robot within the boundaries after processing all commands.

    :param n: int - Number of rows in the room
    :param m: int - Number of columns in the room
    :param x: int - Initial row position of the robot
    :param y: int - Initial column position of the robot
    :param k: int - Number of commands
    :param commands: str - A string of commands consisting of 'L', 'R', 'U', 'D'
    :return: tuple - Final row and column position of the robot
    """
    for command in commands:
        if command == 'L' and y > 1:
            y -= 1
        elif command == 'R' and y < m:
            y += 1
        elif command == 'U' and x > 1:
            x -= 1
        elif command == 'D' and x < n:
            x += 1
    return (x, y)

