def minimum_spanning_tree_cost(N, M, roads):
    def find(parent, i):
        if parent[i] == i:
            return i
        else:
            return find(parent, parent[i])

    def union(parent, rank, x, y):
        root_x = find(parent, x)
        root_y = find(parent, y)
        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    roads.sort(key=lambda x: x[2])
    parent = list(range(N))
    rank = [0] * N
    total_cost = 0
    edges_used = 0

    for u, v, w in roads:
        u -= 1
        v -= 1
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            total_cost += w
            edges_used += 1
            if edges_used == N - 1:
                break

    return total_cost

def pattern_exists(n, board):
    for i in range(n - 1):
        for j in range(n - 2):
            if board[i][j] == '.' and board[i + 1][j] == '.' and board[i][j + 1] == '.' and board[i][j + 2] == '.':
                return 'YES'

    for i in range(n - 1):
        for j in range(n - 2):
            if board[j][i] == '.' and board[j + 1][i] == '.' and board[j][i + 1] == '.' and board[j][i + 2] == '.':
                return 'YES'

