def max_subgrid_sum(n, m, grid):
    """
    Returns the maximum sum of all elements in any subgrid of the given n x m grid.
    """
    # Create the prefix sum array
    prefix_sum = [[0] * (m + 1) for _ in range(n + 1)]

    # Populate the prefix sum array
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            prefix_sum[i][j] = (
                grid[i-1][j-1] +
                prefix_sum[i-1][j] +
                prefix_sum[i][j-1] -
                prefix_sum[i-1][j-1]
            )

    max_sum = float('-inf')

    # Evaluate every subgrid using the prefix sums
    for r1 in range(1, n+1):
        for r2 in range(r1, n+1):
            for c1 in range(1, m+1):
                for c2 in range(c1, m+1):
                    subgrid_sum = (
                        prefix_sum[r2][c2] -
                        prefix_sum[r1-1][c2] -
                        prefix_sum[r2][c1-1] +
                        prefix_sum[r1-1][c1-1]
                    )
                    max_sum = max(max_sum, subgrid_sum)

    return max_sum

def find_top_students(test_cases):
    output = []
    for case in test_cases:
        student_scores = case
        subject_top_student = {}
        for student in student_scores:
            name, subject, score = student
            if subject not in subject_top_student:
                subject_top_student[subject] = (name, score)
            else:
                top_student, top_score = subject_top_student[subject]
                if score > top_score or (score == top_score and name < top_student):
                    subject_top_student[subject] = (name, score)

        sorted_subjects = sorted(subject_top_student.keys())

        result = []
        for subject in sorted_subjects:
            result.append(f"{subject}: {subject_top_student[subject][0]}")
        output.append(result)
    return output

