def find_element(S, N):
    """
    Returns the N-th element (1-based index) of the sequence at step S.
    """
    if S == 0:
        return 1
    segment_length = 2 ** S - 1
    if N <= segment_length:
        return find_element(S-1, N)
    elif N == segment_length + 1:
        return S + 1
    else:
        return find_element(S-1, 2 * segment_length + 2 - N)

