def find_most_influential_knight(n, m, points, duels):
    influence = [0] * n

    for i in range(n):
        influence[i] = points[i]

    duels_map = [[] for _ in range(n)]
    for u, v in duels:
        duels_map[u-1].append(v-1)

    for i in range(n):
        for j in duels_map[i]:
            influence[i] += points[j]

    max_influence = max(influence)
    return influence.index(max_influence) + 1

def unique_paths(m, n):
    """
    Calculate the number of unique paths from the top-left corner to the bottom-right corner in an m x n grid.
    """
    # Create a 2D list to store the number of unique paths to each cell
    dp = [[0] * n for _ in range(m)]

    # There is only one way to reach any cell in the first row or the first column
    for i in range(m):
        dp[i][0] = 1
    for j in range(n):
        dp[0][j] = 1

    # Use dynamic programming to fill in the rest of the dp table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

def process_test_cases(test_cases):
    results = []
    for m, n in test_cases:
        results.append(unique_paths(m, n))
    return results

