def max_treasure(n, m, E, grid):
    # Initialize a 3D dp array where dp[i][j][e] stands for the maximum treasures
    # that can be collected at position (i, j) with energy e.
    dp = [[[-1] * (E + 1) for _ in range(m)] for _ in range(n)]

    # Starting position with initial energy
    if grid[0][0] >= 0:
        dp[0][0][E] = grid[0][0]
    else:
        initial_energy = E + grid[0][0]
        if initial_energy >= 0:
            dp[0][0][initial_energy] = 0

    # Fill the dp table
    for i in range(n):
        for j in range(m):
            for e in range(E + 1):
                if dp[i][j][e] == -1:
                    continue
                # Move right
                if j + 1 < m:
                    next_val = grid[i][j + 1]
                    if next_val >= 0:
                        dp[i][j + 1][e] = max(dp[i][j + 1][e], dp[i][j][e] + next_val)
                    else:
                        next_energy = e + next_val
                        if next_energy >= 0:
                            dp[i][j + 1][next_energy] = max(dp[i][j + 1][next_energy], dp[i][j][e])

                # Move down
                if i + 1 < n:
                    next_val = grid[i + 1][j]
                    if next_val >= 0:
                        dp[i + 1][j][e] = max(dp[i + 1][j][e], dp[i][j][e] + next_val)
                    else:
                        next_energy = e + next_val
                        if next_energy >= 0:
                            dp[i + 1][j][next_energy] = max(dp[i + 1][j][next_energy], dp[i][j][e])

    # Find the maximum treasure collected
    max_treasure_collected = 0
    for e in range(E + 1):
        max_treasure_collected = max(max_treasure_collected, dp[n-1][m-1][e])

    return max_treasure_collected

