def is_path(maze):
    rows, cols = len(maze), len(maze[0])
    visited = set()

    def dfs(r, c):
        if r >= rows or c >= cols or maze[r][c] == 'X' or (r, c) in visited:
            return False
        if r == rows - 1 and c == cols - 1:
            return True

        visited.add((r, c))

        return dfs(r + 1, c) or dfs(r, c + 1)

    return dfs(0, 0)

