def can_visit_all_rooms(T, test_cases):
    results = []

    def dfs(current_room, dirt_levels, visited, K):
        for next_room in range(len(dirt_levels)):
            if not visited[next_room] and abs(dirt_levels[current_room] - dirt_levels[next_room]) <= K:
                visited[next_room] = True
                dfs(next_room, dirt_levels, visited, K)

    for test_case in test_cases:
        N, K = test_case[0]
        dirt_levels = test_case[1]
        visited = [False] * N

        visited[0] = True
        dfs(0, dirt_levels, visited, K)

        if all(visited):
            results.append("Yes")
        else:
            results.append("No")

    return results

