import math

def number_of_ways_to_park_bikes(n, m):
    """
    Returns the number of ways to park m bikes in n docks such that no dock is empty
    and no two bikes are placed in the same dock.
    """
    if n == m:
        # When n == m, the number of ways is simply m! (factorial of m)
        return math.factorial(m)
    else:
        # It's impossible to park more bikes than the number of docks or with empty docks
        return 0

