def process_string(s: str) -> str:
    """
    Process the input string according to the specified conditions:
    1. Remove all digits.
    2. Convert uppercase letters to lowercase.
    3. Replace special characters with underscore '_'.
    Maintain the order of characters as in the original string.
    """
    processed = []
    for char in s:
        if char.isdigit():
            continue
        elif char.isalpha():
            processed.append(char.lower())
        else:
            processed.append('_')
    return ''.join(processed)

