import math

def factorial_or_prime(n):
    """
    Returns the factorial of n if n is not a prime number, otherwise returns "Prime".
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(math.sqrt(num)) + 1):
            if num % i == 0:
                return False
        return True

    if is_prime(n):
        return "Prime"
    else:
        return math.factorial(n)

