def count_distinct_pairs(N, K, A):
    """
    Returns the number of distinct pairs (A_i, A_j) such that i < j and A_i ⊕ A_j = K.
    """
    pair_count = 0
    seen = {}

    for i in range(N):
        target = A[i] ^ K
        if target in seen:
            pair_count += seen[target]

        if A[i] in seen:
            seen[A[i]] += 1
        else:
            seen[A[i]] = 1

    return pair_count

