def count_paths(n, m, obstacles):
    """
    Returns the number of distinct paths from the top-left to the bottom-right
    corner of the grid, avoiding obstacles.
    """
    grid = [[0] * m for _ in range(n)]
    if (1, 1) in obstacles or (n, m) in obstacles:
        return 0

    grid[0][0] = 1

    for i in range(n):
        for j in range(m):
            if (i + 1, j + 1) in obstacles:
                grid[i][j] = 0
            else:
                if i > 0:
                    grid[i][j] += grid[i - 1][j]
                if j > 0:
                    grid[i][j] += grid[i][j - 1]

    return grid[-1][-1]

def parse_input(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    k = int(lines[1])
    obstacles = {tuple(map(int, line.split())) for line in lines[2:2 + k]}
    return n, m, obstacles

def grid_paths(input_str):
    n, m, obstacles = parse_input(input_str)
    return count_paths(n, m, obstacles)

