def solve_game(n, m, edges, a, b):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start):
        visited = [-1] * (n + 1)
        queue = deque([(start, 0)])
        visited[start] = 0

        while queue:
            node, dist = queue.popleft()
            for neigh in graph[node]:
                if visited[neigh] == -1:
                    visited[neigh] = dist + 1
                    queue.append((neigh, dist + 1))

        return visited

    # Perform BFS from both starting points
    dist_a = bfs(a)
    dist_b = bfs(b)

    # Check distances
    for i in range(1, n + 1):
        if i == a or i == b:
            continue  # Ignore starting positions
        if dist_a[i] < dist_b[i]:
            return "Andrew"
        elif dist_b[i] < dist_a[i]:
            return "Alex"

    # If it reaches here, both can reach all nodes in the same number of moves
    return "Andrew"  # If all distances are the same, Andrew wins because he starts first

def is_direct_path_possible(grid):
    """
    Determines if there is a direct path from 'S' to 'T' without crossing any obstacles '#'.
    :param grid: List of strings representing the grid
    :return: "YES" if a direct path exists, otherwise "NO"
    """
    rows = len(grid)
    cols = len(grid[0])

    # Find the positions of 'S' and 'T'
    s_pos = None
    t_pos = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'S':
                s_pos = (i, j)
            if grid[i][j] == 'T':
                t_pos = (i, j)

    if not s_pos or not t_pos:
        return "NO"

    s_row, s_col = s_pos
    t_row, t_col = t_pos

    # Check vertical path
    if s_col == t_col:
        if all(grid[row][s_col] != '#' for row in range(min(s_row, t_row), max(s_row, t_row) + 1)):
            return "YES"

    # Check horizontal path
    if s_row == t_row:
        if all(grid[s_row][col] != '#' for col in range(min(s_col, t_col), max(s_col, t_col) + 1)):
            return "YES"

    return "NO"

