def process_commands(commands):
    specimens = set()
    output = []

    for command in commands:
        parts = command.split()
        action = parts[0].upper()

        if action == "ADD":
            specimen_code = parts[1]
            specimens.add(specimen_code)
        elif action == "REMOVE":
            specimen_code = parts[1]
            specimens.discard(specimen_code)
        elif action == "CHECK":
            specimen_code = parts[1]
            output.append("YES" if specimen_code in specimens else "NO")
        elif action == "LIST":
            for specimen in sorted(specimens):
                output.append(specimen)

    return output

def process_test_cases(test_cases):
    results = []
    for commands in test_cases:
        result = process_commands(commands)
        if result:
            results.append(result)
    return results

