def find_swap_indices(sequence):
    n = len(sequence)

    for i in range(n):
        for j in range(i + 1, n):
            # Swap the elements at i and j
            sequence[i], sequence[j] = sequence[j], sequence[i]

            # Check if the sequence is strictly increasing
            if all(sequence[k] < sequence[k + 1] for k in range(n - 1)):
                return (i, j)

            # Swap back to restore original sequence
            sequence[i], sequence[j] = sequence[j], sequence[i]

    return (-1, -1)

