def can_restore_log(c, b, commits):
    from collections import defaultdict

    # Create a dictionary to store commits by branch
    branches = defaultdict(list)

    for index, branch, timestamp in commits:
        branches[branch].append(timestamp)

    # For each branch except the main branch (branch 0)
    for branch in range(1, b + 1):
        if branch in branches:
            timestamps = branches[branch]
            if timestamps != sorted(timestamps):
                return "NO"

    return "YES"

