    first_line = input_lines[0].split()
    c = int(first_line[0])
    b = int(first_line[1])
    commits = []
    for line in input_lines[1:]:
        index, branch, timestamp = map(int, line.split())
        commits.append((index, branch, timestamp))

    return can_restore_log(c, b, commits)

