def can_make_all_elements_equal(matrix):
    n = len(matrix)
    m = len(matrix[0])

    # Calculate the base difference (difference from the top-left corner)
    base_diff = matrix[0][0]

    for r in range(n):
        for c in range(m):
            if (matrix[r][c] - base_diff) % 2 != (r + c) % 2:
                return False
    return True

def process_test_cases(t, test_cases):
    results = []
    for matrix in test_cases:
        if can_make_all_elements_equal(matrix):
            results.append("YES")
        else:
            results.append("NO")
    return results

