def find_path(graph, start, end, path=[]):
    path = path + [start]
    if start == end:
        return path
    for node in graph[start]:
        if node not in path:
            new_path = find_path(graph, node, end, path)
            if new_path:
                return new_path
    return None

def max_value_on_path(values, path):
    return max(values[node - 1] for node in path)

def solve(n, q, node_values, edges, queries):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    results = []
    for u, v in queries:
        path = find_path(graph, u, v)
        results.append(max_value_on_path(node_values, path))

    return results

