def has_cycle(edges):
    from collections import defaultdict

    def dfs(v):
        visited[v] = True
        rec_stack[v] = True
        for neighbour in graph[v]:
            if not visited[neighbour]:
                if dfs(neighbour):
                    return True
            elif rec_stack[neighbour]:
                return True
        rec_stack[v] = False
        return False

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    visited = defaultdict(bool)
    rec_stack = defaultdict(bool)

    for node in list(graph):
        if not visited[node]:
            if dfs(node):
                return True
    return False

