def min_moves_to_zero_grid(grid):
    n = len(grid)
    m = len(grid[0])
    moves = 0

    for i in range(n - 1):
        for j in range(m - 1):
            if grid[i][j] == 1:
                moves += 1
                grid[i][j] ^= 1
                grid[i+1][j] ^= 1
                grid[i][j+1] ^= 1
                grid[i+1][j+1] ^= 1

    for i in range(n):
        if grid[i][m-1] == 1:
            return -1

    for j in range(m):
        if grid[n-1][j] == 1:
            return -1

    return moves

def process_input(input_string):
    results = []
    lines = input_string.strip().split('\n')
    i = 0
    while i < len(lines):
        n, m = map(int, lines[i].split())
        if n == 0 and m == 0:
            break
        grid = []
        for j in range(i + 1, i + n + 1):
            grid.append(list(map(int, lines[j].split())))
        moves = min_moves_to_zero_grid(grid)
        results.append(moves)
        i += n + 1
    return results

def max_equal_01_substring_length(T, test_cases):
    results = []
    for t in range(T):
        N = test_cases[t][0]
        S = test_cases[t][1]
        max_length = -1
        prefix_sum = {0: -1}  # Initialize with 0 to handle edge case
        current_sum = 0

        for i in range(N):
            if S[i] == '0':
                current_sum -= 1
            else:
                current_sum += 1

            if current_sum in prefix_sum:
                max_length = max(max_length, i - prefix_sum[current_sum])
            else:
                prefix_sum[current_sum] = i

        results.append(max_length)

    return results

import itertools

def find_min_travel_time(N, M, roads, S):
    # If only one city, no travel required.
    if N == 1:
        return 0

    # Create a dictionary to store travel times between cities
    travel_time = {}
    for u, v, t in roads:
        if u not in travel_time:
            travel_time[u] = {}
        if v not in travel_time:
            travel_time[v] = {}
        travel_time[u][v] = t
        travel_time[v][u] = t

    # To store minimum travel time
    min_travel_time = float('inf')

    # Generate all possible permutations of visiting cities (excluding the starting city)
    cities = [i for i in range(1, N+1) if i != S]
    for perm in itertools.permutations(cities):
        # Calculate total travel time of the current permutation
        current_time = 0
        current_city = S
        for next_city in perm:
            if next_city in travel_time[current_city]:
                current_time += travel_time[current_city][next_city]
                current_city = next_city
            else:
                current_time = float('inf')
                break
        # Add the return journey to the starting city
        if S in travel_time[current_city]:
            current_time += travel_time[current_city][S]
        else:
            current_time = float('inf')

        # Update minimum travel time
        min_travel_time = min(min_travel_time, current_time)

    # If no valid path found, return -1
    if min_travel_time == float('inf'):
        return -1
    return min_travel_time

