def can_segment_string(s, dict_words):
    """
    Returns true if the word 's' can be segmented into one or more dictionary words.
    """
    word_dict = set(dict_words)
    dp = [False] * (len(s) + 1)
    dp[0] = True

    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_dict:
                dp[i] = True
                break

    return dp[-1]

