def max_treasure(N, matrix):
    if N == 0:
        return 0

    # Prepare a matrix to store the maximum treasure points at each cell (i, j)
    dp = [[0] * N for _ in range(N)]

    # Initialize the starting point
    dp[0][0] = matrix[0][0]

    # Fill the dp table
    for i in range(N):
        for j in range(N):
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + matrix[i][j])
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + matrix[i][j])

    return dp[N-1][N-1]

