def max_balanced_teams(N, students):
    # Create a dictionary to hold lists of skill levels for each project type
    skill_dict = defaultdict(list)
    for skill, ptype in students:
        skill_dict[ptype].append(skill)

    # Sort the skill levels for each project type
    for ptype in skill_dict:
        skill_dict[ptype].sort()

    # Count possible teams
    count = 0
    while True:
        if not skill_dict['A'] or not skill_dict['B'] or not skill_dict['C']:
            break  # No more teams can be formed
        for a in skill_dict['A']:
            for b in skill_dict['B']:
                if b == a:
                    continue
                for c in skill_dict['C']:
                    if c != a and c != b:
                        # Found a valid team
                        count += 1
                        skill_dict['A'].remove(a)
                        skill_dict['B'].remove(b)
                        skill_dict['C'].remove(c)
                        break
                else:
                    continue
                break
            else:
                continue
            break
    return count

def min_insertions_to_palindrome(s):
    """
    Returns the minimum number of characters needed to insert into s
    to make it a palindrome.
    """
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = min(dp[i+1][j], dp[i][j-1]) + 1

    return dp[0][n-1]

