def longest_sequence(m, n, grid):
    def length_of_sequence(x, y, dx, dy):
        count = 0
        current_char = grid[x][y]
        while 0 <= x < m and 0 <= y < n and grid[x][y] == current_char:
            count += 1
            x += dx
            y += dy
        return count

    max_length = 0
    directions = [(1, 0), (0, 1), (1, 1), (1, -1)]  # down, right, down-right, down-left

    for i in range(m):
        for j in range(n):
            for dx, dy in directions:
                max_length = max(max_length, length_of_sequence(i, j, dx, dy))

    return max_length

