def is_balanced(s):
    """
    Determines if the sequence of brackets is balanced.

    Args:
    s (str): A string consisting of '(' and ')'

    Returns:
    str: "YES" if the sequence is balanced, otherwise "NO"
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return "NO"
            stack.pop()
    if not stack:
        return "YES"
    else:
        return "NO"

