def min_swaps_to_avoid_adjacent_same_colors(n, pots):
    swaps = 0

    for i in range(1, n):
        if pots[i] == pots[i - 1]:
            swaps += 1
            if i + 1 < n and pots[i + 1] != pots[i]:
                pots[i], pots[i + 1] = pots[i + 1], pots[i]
            else:
                pots[i] = -pots[i]  # temporarily change the color to avoid increasing the index

    return swaps

