def longest_consecutive_zeros(sequence):
    """
    Returns the length of the longest streak of consecutive zeros in the sequence.
    :param sequence: A string of integers separated by spaces.
    :return: An integer representing the maximum number of consecutive zeros.
    """
    numbers = sequence.split()

    max_count = 0
    current_count = 0

    for num in numbers:
        if num == '0':
            current_count += 1
        else:
            if current_count > max_count:
                max_count = current_count
            current_count = 0

    if current_count > max_count:
        max_count = current_count

    return max_count

