def min_swaps_to_sort_books(n, heights):
    def count_swaps(arr):
        arr = [(val, idx) for idx, val in enumerate(arr)]
        arr.sort()
        visited = [False] * n
        swaps = 0

        for i in range(n):
            if visited[i] or arr[i][1] == i:
                continue

            cycle_size = 0
            x = i
            while not visited[x]:
                visited[x] = True
                x = arr[x][1]
                cycle_size += 1

            if cycle_size > 1:
                swaps += (cycle_size - 1)

        return swaps

    sorted_heights_asc = sorted(heights)
    sorted_heights_desc = sorted(heights, reverse=True)

    swaps_to_ascend = count_swaps(heights[:])
    swaps_to_descend = count_swaps(heights[::-1])

    return min(swaps_to_ascend, swaps_to_descend)

