def find_min_crossing_roads(N, roads):
    from collections import defaultdict

    def dfs(node, parent):
        subtree_size[node] = 1
        for neighbor in graph[node]:
            if neighbor != parent:
                dfs(neighbor, node)
                subtree_size[node] += subtree_size[neighbor]

    if N == 1:
        return 0

    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    subtree_size = [0] * (N + 1)
    dfs(1, -1)

    min_roads_crossing = float('inf')
    for i in range(2, N + 1):
        if abs(subtree_size[i] - (N - subtree_size[i])) <= N // 2:
            min_roads_crossing = min(min_roads_crossing, 1)

    return min_roads_crossing

def calculate_total_donations(target, donations):
    total_donations = 0
    for donation in donations:
        if donation < 0:
            continue
        total_donations += donation
        if total_donations >= target:
            break
    return total_donations, ("Target met" if total_donations >= target else "Target not met")

def replace_phrases_with_abbreviations(n, phrases, m, sentences):
    from collections import defaultdict, Counter

    # Create a dictionary of the phrase to abbreviation mappings
    phrase_to_abbr = {}
    for phrase, abbr in phrases:
        phrase_to_abbr[phrase] = abbr

    # Calculate the frequency of each phrase in the sentences
    phrase_freq = Counter()
    for sentence in sentences:
        for phrase in phrase_to_abbr.keys():
            if phrase in sentence:
                phrase_freq[phrase] += sentence.count(phrase)

    # Sort phrases by frequency, then by length, then lexicographically
    sorted_phrases = sorted(phrase_to_abbr.keys(), key=lambda p: (-phrase_freq[p], len(p), p))

    # Replace the phrases with abbreviations in the sentences
    result = []
    for sentence in sentences:
        for phrase in sorted_phrases:
            sentence = sentence.replace(phrase, phrase_to_abbr[phrase])
        result.append(sentence)

    return result

def make_kingdom_tree(n, m, edges):
    parent = list(range(n+1))  # Union-Find Structure

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX, rootY = find(x), find(y)
        if rootX != rootY:
            parent[rootX] = rootY
            return True
        return False

    removed_roads = []
    for i in range(m):
        u, v = edges[i]
        if not union(u, v):
            removed_roads.append(i + 1)  # 1-based index

    # After processing all roads, if there is a single connected component
    root = find(1)
    for i in range(2, n+1):
        if find(i) != root:
            return "NO"

    return "YES\n" + " ".join(map(str, removed_roads))

def count_pools(building_heights):
    """
    Given a list of building heights, counts the number of distinct pools that will form
    after a rainstorm.
    """
    n = len(building_heights)
    if n == 0:
        return 0
    if n == 1:
        return 0

    pool_count = 0
    in_pool = False

    for i in range(n):
        if i == 0 or i == n-1:
            continue  # first and last building cannot form a pool on their own

        if building_heights[i] < building_heights[i-1] and building_heights[i] < building_heights[i+1]:
            if not in_pool:
                in_pool = True
                pool_count += 1
        else:
            in_pool = False

    return pool_count

