def distinct_substrings_count(s):
    """
    Returns the number of distinct substrings in the given string s.
    """
    n = len(s)
    substrings = set()

    for i in range(n):
        for j in range(i+1, n+1):
            substrings.add(s[i:j])

    return len(substrings)

def beauty_of_strings(T, strings):
    """
    Given a number of test cases T and a list of strings, returns a list containing the beauty
    of each string.
    """
    results = []
    for s in strings:
        results.append(distinct_substrings_count(s))

    return results

