def can_form_palindrome_substring(L, S):
    def can_form_palindrome(s):
        # Count the occurrences of each character in the substring
        frequency = {}
        for char in s:
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1

        # Count how many characters appear an odd number of times
        odd_count = 0
        for count in frequency.values():
            if count % 2 != 0:
                odd_count += 1

        # For the substring to be rearranged into a palindrome:
        # At most one character can have an odd frequency
        return odd_count <= 1

    for i in range(len(S) - L + 1):
        substring = S[i:i + L]
        if can_form_palindrome(substring):
            return "YES"

    return "NO"

def process_cases(test_cases):
    results = []
    for L, S in test_cases:
        result = can_form_palindrome_substring(L, S)
        results.append(result)
    return results

