from collections import deque
from typing import List

def robot_cleaner_path(grid: List[List[int]]) -> int:
    rows, cols = len(grid), len(grid[0])
    if grid[0][0] == 1 or grid[rows-1][cols-1] == 1:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(0, 0, 0)])  # (row, col, steps)
    visited = set((0, 0))

    while queue:
        r, c, steps = queue.popleft()

        if r == rows - 1 and c == cols - 1:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols and (nr, nc) not in visited and grid[nr][nc] == 0:
                queue.append((nr, nc, steps + 1))
                visited.add((nr, nc))

    return -1

def largest_connected_component(T, test_cases):
    def dfs(tree, adj_list, visited):
        stack = [tree]
        size = 0
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                size += 1
                for neighbor in adj_list[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return size

    result = []
    for n, e, edges in test_cases:
        adj_list = {i: [] for i in range(1, n + 1)}
        for u, v in edges:
            adj_list[u].append(v)
            adj_list[v].append(u)

        visited = {i: False for i in range(1, n + 1)}
        max_size = 0
        for tree in range(1, n + 1):
            if not visited[tree]:
                max_size = max(max_size, dfs(tree, adj_list, visited))
        result.append(max_size)
    return result

