def find_mst_total_length(B, roads):
    """
    Implementing Kruskal's algorithm to find the total length of the minimum spanning tree.

    Parameters:
    - B: Number of buildings (int)
    - roads: List of tuples (U, V, L) each representing a road of length L between buildings U and V

    Returns:
    - Total length of roads in the minimum spanning tree (int)
    """

    parent = list(range(B))
    rank = [0] * B

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX, rootY = find(x), find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    # Sort edges by their length
    roads.sort(key=lambda x: x[2])
    mst_length = 0

    for u, v, l in roads:
        if find(u) != find(v):
            union(u, v)
            mst_length += l

    return mst_length

def minimize_tallest_height(n, m, heights):
    heights = sorted(heights)

    if m == 1:
        # If there's only one height, that's the only possible height we can choose
        return heights[0]

    left, right = 0, len(heights) - 1

    while left < right:
        mid = (left + right) // 2
        if can_form_beautiful_garden(n, heights[:mid + 1]):
            right = mid
        else:
            left = mid + 1

    return heights[left]

def can_form_beautiful_garden(n, candidate_heights):
    if len(candidate_heights) == 1:
        return n == 1

    for i in range(1, n):
        if candidate_heights[i % len(candidate_heights)] == candidate_heights[(i - 1) % len(candidate_heights)]:
            return False

    return True

