def count_triangles(n, matrix):
    """
    Counts the number of triangles in a social network graph represented by an adjacency matrix.

    Parameters:
    n (int): Number of nodes in the graph.
    matrix (list of lists): Adjacency matrix representing the graph.

    Returns:
    int: Number of triangles in the graph.
    """
    triangles = 0

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if matrix[i][j] and matrix[j][k] and matrix[k][i]:
                    triangles += 1

    return triangles

def largest_tree_cluster(M, N, grid):
    """
    Returns the size of the largest connected cluster of trees in the given grid.
    """
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < M and 0 <= y < N and grid[x][y] == 1

    def dfs(x, y):
        stack = [(x, y)]
        cluster_size = 0
        while stack:
            cx, cy = stack.pop()
            if grid[cx][cy] == 1:
                grid[cx][cy] = -1  # Mark the cell as visited
                cluster_size += 1
                for dx, dy in directions:
                    nx, ny = cx + dx, cy + dy
                    if is_valid(nx, ny):
                        stack.append((nx, ny))
        return cluster_size

    max_cluster_size = 0
    for i in range(M):
        for j in range(N):
            if grid[i][j] == 1:
                max_cluster_size = max(max_cluster_size, dfs(i, j))

    return max_cluster_size

def fastest_car(n, car_list):
    """
    Returns the name of the car with the highest speed. If there are multiple cars with the same highest speed,
    returns the lexicographically smallest name.
    """
    car_speeds = {}

    for car, speed in car_list:
        if car in car_speeds:
            car_speeds[car] = max(car_speeds[car], speed)
        else:
            car_speeds[car] = speed

    max_speed = -1
    fastest_car_name = ""
    for car, speed in car_speeds.items():
        if speed > max_speed or (speed == max_speed and car < fastest_car_name):
            max_speed = speed
            fastest_car_name = car

    return fastest_car_name

