def maxSumContiguousSubarray(arr):
    """
    Returns the maximum sum of the contiguous subarray, or the least negative element if all elements are negative.
    """
    if not arr:
        return 0

    max_current = arr[0]
    max_global = arr[0]
    all_negative = all(x < 0 for x in arr)

    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    if all_negative:
        return max(arr)
    else:
        return max_global

