from datetime import datetime

def check_reminders(n, employee_logs, max_continuous_hours):
    max_continuous_minutes = max_continuous_hours * 60
    result = []

    for log in employee_logs:
        parts = log.split()
        name = parts[0]
        times = parts[1:]

        max_work_time = 0

        intervals = [(datetime.strptime(times[i], '%H:%M'), datetime.strptime(times[i + 1], '%H:%M'))
                     for i in range(0, len(times), 2)]

        for start, end in intervals:
            work_time = (end - start).total_seconds() / 60.0
            if work_time > max_work_time:
                max_work_time = work_time

        if max_work_time > max_continuous_minutes:
            result.append(f"{name} Reminder")
        else:
            result.append(f"{name} No Reminder")

    return result

def reverse_alphabet_cipher(text):
    """
    Encrypts a given text using the Reverse Alphabet Cipher.

    Args:
    text (str): The input string to be encrypted.

    Returns:
    str: The encrypted string.
    """
    encrypted_text = []

    for char in text:
        if 'a' <= char <= 'z':
            encrypted_text.append(chr(219 - ord(char)))  # 'a' -> 'z', 'b' -> 'y', etc.
        elif 'A' <= char <= 'Z':
            encrypted_text.append(chr(155 - ord(char)))  # 'A' -> 'Z', 'B' -> 'Y', etc.
        else:
            encrypted_text.append(char)  # Non-alphabetic characters remain unchanged

    return ''.join(encrypted_text)

