def count_unique_substrings(s, L):
    """
    Returns the number of distinct substrings of length L that appear exactly once in the string s.
    """
    substring_count = {}
    for i in range(len(s) - L + 1):
        substring = s[i:i+L]
        if substring in substring_count:
            substring_count[substring] += 1
        else:
            substring_count[substring] = 1

    unique_count = sum(1 for count in substring_count.values() if count == 1)
    return unique_count

