def generate_zigzag_matrix(n):
    """
    Generates an n x n zigzag matrix.

    Args:
    n (int): The order of the matrix.

    Returns:
    list: A 2D list representing the zigzag matrix.
    """
    matrix = [[0]*n for _ in range(n)]
    i, j = 0, 0
    direction = 1 # 1 for down-right, -1 for up-left

    for num in range(1, n*n + 1):
        matrix[i][j] = num
        if direction == 1:
            if j + 1 < n and i - 1 >= 0:
                i -= 1
                j += 1
            elif j + 1 == n:
                i += 1
                direction = -1
            else:
                j += 1
                direction = -1
        else:
            if i + 1 < n and j - 1 >= 0:
                i += 1
                j -= 1
            elif i + 1 == n:
                j += 1
                direction = 1
            else:
                i += 1
                direction = 1

    return matrix

def print_zigzag_matrix(matrix):
    for row in matrix:
        print(' '.join(map(str, row)))

