def max_temperature_difference(temperatures):
    """
    Returns the maximum difference between two temperatures such that the higher temperature
    occurs after the lower temperature. If no such pair exists, returns 0.
    """
    if len(temperatures) < 2:
        return 0

    min_temp = temperatures[0]
    max_diff = 0

    for temp in temperatures[1:]:
        if temp - min_temp > max_diff:
            max_diff = temp - min_temp
        if temp < min_temp:
            min_temp = temp

    return max_diff

