def generate_binary_string(n):
    """
    Constructs a binary string of length n where no two consecutive '1's are adjacent unless
    they are followed by '0'.
    """
    result = []

    for i in range(n):
        if i % 3 == 0:
            result.append('1')
        else:
            result.append('0')

    return ''.join(result)

