def count_paths(grid):
    n = len(grid)
    # Create a dp table of the same size as grid, initialized to 0
    dp = [[0]*n for _ in range(n)]

    # Initialize the starting point
    if grid[0][0] == 1:
        dp[0][0] = 1
    else:
        return 0

    # Fill the dp table
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    # The bottom-right corner will have the number of ways to reach it
    return dp[-1][-1]

def count_peaks(seq):
    """
    Returns the number of peaks in the list.
    A peak is an element that is strictly greater than its neighbors.
    """
    if len(seq) < 3:
        return 0  # A valid peak requires at least 3 elements to compare

    peak_count = 0
    for i in range(1, len(seq) - 1):
        if seq[i] > seq[i - 1] and seq[i] > seq[i + 1]:
            peak_count += 1

    return peak_count

