def max_books_in_stack(T, testcases):
    results = []
    for i in range(T):
        N, H = testcases[i][0]
        pages = testcases[i][1]
        pages.sort()
        total_pages = 0
        count = 0

        for page in pages:
            if total_pages + page <= H:
                total_pages += page
                count += 1
            else:
                break

        results.append(count)

    return results

