from typing import List

def three_sum(nums: List[int], target: int) -> bool:
    """
    Determine if there are three distinct elements in the list that add up to the target.
    """
    nums.sort()
    n = len(nums)

    for i in range(n-2):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        l, r = i + 1, n - 1
        while l < r:
            total = nums[i] + nums[l] + nums[r]
            if total == target:
                return True
            elif total < target:
                l += 1
            else:
                r -= 1

    return False

def min_operations_to_smallest_word(word):
    """
    Given a word, find the minimum number of valid operations needed to transform
    the input word into the lexicographically smallest possible word.
    """
    if not word:
        return 0

    smallest_word = ''.join(sorted(word))
    i, j = 0, 0
    operations = 0

    while i < len(word) and j < len(smallest_word):
        if word[i] != smallest_word[j]:
            operations += 1
        else:
            j += 1
        i += 1

    return operations + (len(word) - i)

