def flag_corrupted_submissions(n, submissions):
    device_data = {}
    corrupted_indices = []

    for i in range(n):
        device_id, reading, timestamp = submissions[i]

        if device_id not in device_data:
            device_data[device_id] = {'last_reading': 0, 'last_timestamp': 0}

        last_reading = device_data[device_id]['last_reading']
        last_timestamp = device_data[device_id]['last_timestamp']

        if reading < last_reading or timestamp < last_timestamp:
            corrupted_indices.append(i + 1)
        else:
            device_data[device_id]['last_reading'] = reading
            device_data[device_id]['last_timestamp'] = timestamp

    if not corrupted_indices:
        return "No corrupted submissions"

    return " ".join(map(str, corrupted_indices))

