def min_scarecrows(H, W, grid):
    row_guarded = [False] * H
    col_guarded = [False] * W

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                row_guarded[i] = True
                col_guarded[j] = True

    all_rows_guarded = all(row_guarded)
    all_cols_guarded = all(col_guarded)

    if all_rows_guarded and all_cols_guarded:
        return 0

    if not all_rows_guarded or not all_cols_guarded:
        return 'impossible'

    # Calculate the minimum scarecrows required
    scarecrows_needed = max(len([r for r in row_guarded if not r]), len([c for c in col_guarded if not c]))
    return scarecrows_needed

def parse_input(input_text):
    lines = input_text.strip().split("\n")
    index = 0
    results = []

    while index < len(lines):
        H, W = map(int, lines[index].split())
        index += 1

        if H == 0 and W == 0:
            break

        grid = []
        for _ in range(H):
            grid.append(lines[index])
            index += 1

        results.append(min_scarecrows(H, W, grid))

    return results

