def longestUniqueSubstring(s: str) -> int:
    if not s:
        return 0

    left = 0
    right = 0
    max_length = 0
    chars_set = set()

    while right < len(s):
        if s[right] not in chars_set:
            chars_set.add(s[right])
            right += 1
            max_length = max(max_length, right - left)
        else:
            chars_set.remove(s[left])
            left += 1

    return max_length

