def max_consecutive_flowers(n, flowers):
    """
    Determine the maximum number of consecutive flower beds that contain the same type of flower.

    :param n: An integer, the number of flower beds.
    :param flowers: A list of integers, each representing the type of flower in each flower bed.
    :return: An integer, the maximum length of consecutive flower beds of the same type.
    """
    if n == 0:
        return 0

    max_count = 1
    current_count = 1

    for i in range(1, n):
        if flowers[i] == flowers[i - 1]:
            current_count += 1
        else:
            max_count = max(max_count, current_count)
            current_count = 1

    return max(max_count, current_count)

