def recommend_friends(direct_friends, friends_of_friends):
    """
    Returns a list of recommended friends who are not already direct friends.

    :param direct_friends: List of direct friends
    :param friends_of_friends: List of friends of friends
    :return: List of recommended friends in alphabetical order
    """
    direct_friends_set = set(direct_friends)
    recommendations = set()

    for friend in friends_of_friends:
        if friend not in direct_friends_set:
            recommendations.add(friend)

    return sorted(recommendations)

def min_length_subarray(t, test_cases):
    results = []

    for test_case in test_cases:
        n, target = test_case['params']
        points = test_case['points']
        min_len = float('inf')
        current_sum = 0
        start = 0

        for end in range(n):
            current_sum += points[end]
            while current_sum >= target:
                min_len = min(min_len, end - start + 1)
                current_sum -= points[start]
                start += 1

        if min_len == float('inf'):
            results.append(-1)
        else:
            results.append(min_len)

    return results

