def largest_square_sub_garden(n, m, garden):
    # Create a dp table
    dp = [[0] * m for _ in range(n)]
    max_side = 0

    for i in range(n):
        for j in range(m):
            if garden[i][j] == 'T':
                if i == 0 or j == 0:
                    dp[i][j] = 1  # First row or first column
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

