def count_rectangular_plots(n, m, grid):
    """
    Returns the number of rectangular plots of cultivated land without gaps inside.

    Args:
    n : int - number of rows in the grid
    m : int - number of columns in the grid
    grid : list of str - the grid itself

    Returns:
    int - number of rectangular plots of cultivated land
    """
    count = 0
    visited = [[False for _ in range(m)] for _ in range(n)]

    def is_rectangular(x, y):
        """ Check if plot starting from (x, y) is a rectangle and mark visited cells """
        if grid[x][y] == '0' or visited[x][y]:
            return False

        right_limit = m
        for j in range(y, m):
            if grid[x][j] == '0':
                right_limit = j
                break

        bottom_limit = n
        for i in range(x, n):
            if grid[i][y:right_limit].count('0') > 0:
                bottom_limit = i
                break

        for i in range(x, bottom_limit):
            for j in range(y, right_limit):
                if grid[i][j] == '0':
                    return False
                visited[i][j] = True
        return True

    for i in range(n):
        for j in range(m):
