def calculate_final_position_and_distance(commands):
    x, y = 0, 0

    for command in commands:
        direction, value = command.split()
        value = int(value)

        if direction == "UP":
            y += value
        elif direction == "DOWN":
            y -= value
        elif direction == "LEFT":
            x -= value
        elif direction == "RIGHT":
            x += value

    manhattan_distance = abs(x) + abs(y)
    return (x, y), manhattan_distance

def main(inputs):
    results = []
    current_commands = []

    for line in inputs:
        if line.isdigit():
            if int(line) == 0:
                # Process the last set of commands (if any)
                if current_commands:
                    results.append(calculate_final_position_and_distance(current_commands))
                    current_commands = []
                break
            # Process the current set of commands (if any)
            elif current_commands:
                results.append(calculate_final_position_and_distance(current_commands))
                current_commands = []
        else:
            current_commands.append(line)

    return results

