def closest_element(arr, target):
    """
    Find the element in the sorted list arr which is closest to the target.
    """
    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return arr[mid]
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    # Check the closest of left and left-1 (or just left if it's the beginning)
    if left == 0:
        return arr[left]
    if left >= len(arr):
        return arr[-1]

    if abs(arr[left] - target) < abs(arr[left - 1] - target):
        return arr[left]
    elif abs(arr[left] - target) == abs(arr[left - 1] - target):
        return min(arr[left], arr[left - 1])
    else:
        return arr[left - 1]

