def num_paths(N, M, grid):
    """
    Computes the number of distinct paths from the grid's top-left corner to its bottom-right corner.
    """
    if grid[0][0] == 1 or grid[N-1][M-1] == 1:
        return 0

    dp = [[0]*M for _ in range(N)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[N-1][M-1]

