def smallest_integer_with_product(x):
    if x == 0:
        return -1
    if x == 1:
        return 1

    divisors = []
    for i in range(9, 1, -1):
        while x % i == 0:
            divisors.append(i)
            x //= i

    if x > 1:
        return -1

    divisors.sort()
    result = int(''.join(map(str, divisors)))
    return result

