def min_moves_to_equalize_rows(n, m, grid):
    def calculate_moves(row, target_row):
        return sum(abs(row[j] - target_row[j]) for j in range(m))

    min_moves = float('inf')

    for i in range(n):
        target_row = grid[i]
        total_moves = 0
        for j in range(n):
            if i != j:
                total_moves += calculate_moves(grid[j], target_row)
        if total_moves < min_moves:
            min_moves = total_moves

    return min_moves

