def process_carts(n, initial_carts, m, operations):
    # Initialize carts as a dictionary of sets to handle duplicates
    carts = {i: set() for i in range(1, n + 1)}

    # Fill the initial carts data
    for cart_data in initial_carts:
        cart_info = list(map(int, cart_data.split()))
        cart_id = cart_info[0]
        items = cart_info[1:]
        carts[cart_id].update(items)

    # Process each operation
    for operation in operations:
        op_parts = operation.split()
        if op_parts[0] == "add":
            cart_id = int(op_parts[1])
            item_id = int(op_parts[2])
            carts[cart_id].add(item_id)
        elif op_parts[0] == "merge":
            cart_id1 = int(op_parts[1])
            cart_id2 = int(op_parts[2])
            carts[cart_id1].update(carts[cart_id2])
            carts[cart_id2].clear()

    # Prepare the final output
    result = []
    for i in range(1, n + 1):
        if carts[i]:
            result.append(f"{i} " + " ".join(map(str, sorted(carts[i]))))
        else:
            result.append(f"{i}")

    return result

def longest_unique_subarray_length(t, test_cases):
    results = []
    for i in range(t):
        n, events = test_cases[i]
        max_length = 1
        current_length = 1

        for j in range(1, n):
            if events[j] == events[j-1]:
                current_length += 1
            else:
                max_length = max(max_length, current_length)
                current_length = 1

        max_length = max(max_length, current_length)
        results.append(max_length)

    return results

