def min_additional_radiators(n, m, positions, radii):
    heated = [False] * (n + 1)

    for i in range(m):
        left = max(1, positions[i] - radii[i])
        right = min(n, positions[i] + radii[i])
        for j in range(left, right + 1):
            heated[j] = True

    uncovered_segments = []
    i = 1
    while i <= n:
        if not heated[i]:
            start = i
            while i <= n and not heated[i]:
                i += 1
            end = i - 1
            uncovered_segments.append((start, end))
        i += 1

    if not uncovered_segments:
        return 0

    additional_radiators = 0
    for segment in uncovered_segments:
        length = segment[1] - segment[0] + 1
        additional_radiators += (length + 1) // 2

    return additional_radiators

