import heapq

def min_path_max_diff(n, m, grid):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    max_diff = [[float('inf')] * m for _ in range(n)]
    max_diff[0][0] = 0
    pq = [(0, 0, 0)]  # (difference, x, y)
    heapq.heapify(pq)

    while pq:
        current_diff, x, y = heapq.heappop(pq)

        if x == n-1 and y == m-1:
            return current_diff

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                new_diff = max(current_diff, abs(grid[x][y] - grid[nx][ny]))
                if new_diff < max_diff[nx][ny]:
                    max_diff[nx][ny] = new_diff
                    heapq.heappush(pq, (new_diff, nx, ny))

    return float('inf')

