def manage_inventory(operations):
    inventory = {}
    results = []

    for operation in operations:
        parts = operation.split()
        command = parts[0]

        if command == "add":
            name, value = parts[1], int(parts[2])
            inventory[name] = value
        elif command == "update":
            name, value = parts[1], int(parts[2])
            if name in inventory:
                inventory[name] = value
        elif command == "total":
            total_value = sum(inventory.values())
            results.append(total_value)

