import heapq

def find(parent, u):
    if parent[u] == u:
        return u
    parent[u] = find(parent, parent[u])
    return parent[u]

def union(parent, rank, u, v):
    root_u = find(parent, u)
    root_v = find(parent, v)

    if root_u != root_v:
        if rank[root_u] > rank[root_v]:
            parent[root_v] = root_u
        elif rank[root_u] < rank[root_v]:
            parent[root_u] = root_v
        else:
            parent[root_v] = root_u
            rank[root_u] += 1

def minimum_spanning_tree(n, edges):
    parent = [i for i in range(n)]
    rank = [0] * n

    # Sort edges by weight
    edges.sort(key=lambda x: x[2])

    mst_length = 0
    for u, v, w in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            mst_length += w

    return mst_length

def find_max_increase(N, jane_rates, rohan_rates):
    max_increase_jane = 0
    max_increase_rohan = 0

    for i in range(1, N):
        jane_increase = jane_rates[i] - jane_rates[i - 1]
        rohan_increase = rohan_rates[i] - rohan_rates[i - 1]

        if jane_increase > max_increase_jane:
            max_increase_jane = jane_increase

        if rohan_increase > max_increase_rohan:
            max_increase_rohan = rohan_increase

    if max_increase_jane > max_increase_rohan:
        return "Jane", max_increase_jane
    elif max_increase_rohan > max_increase_jane:
        return "Rohan", max_increase_rohan
    else:
        return "Draw", max_increase_jane

