def min_operations_to_convert(S1, S2):
    """
    Returns the minimum number of operations required to convert S1 into S2.
    Operations allowed are insert, delete, or replace a character.
    """
    m, n = len(S1), len(S2)

    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif S1[i - 1] == S2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i][j - 1], dp[i - 1][j], dp[i - 1][j - 1])

    return dp[m][n]

def string_transformation(T, test_cases):
    results = []
    for S1, S2 in test_cases:
        results.append(min_operations_to_convert(S1, S2))
    return results

