def determine_better_factory(a1, b1, c1, a2, b2, c2, d, e, f, g, h):
    """
    Determine which factory produces better quality widgets or if they are tied.
    """
    # Calculate the quality score for both factories
    total_quality_a = a1 * d + b1 * e + c1 * f + (g * (sum([a1, b1, c1]) // 50))
    total_quality_b = a2 * d + b2 * e + c2 * f + (h * (sum([a2, b2, c2]) // 50))

    if total_quality_a > total_quality_b:
        return "factory_a"
    elif total_quality_a < total_quality_b:
        return "factory_b"
    else:
        return "tie"

