import heapq

def dijkstra(N, edges, S):
    # Create adjacency list
    graph = {i: [] for i in range(1, N + 1)}
    for u, v, w in edges:
        graph[u].append((v, w))

    # Initialize distances with infinity
    distances = {i: float('inf') for i in range(1, N + 1)}
    distances[S] = 0

    # Min-heap priority queue
    priority_queue = [(0, S)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If we find a shorter way to this node, we continue
        if current_distance > distances[current_node]:
            continue

        # Explore the neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # If we find a shorter path to the neighbor, update priority queue
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    # Format the result
    result = []
    for i in range(1, N + 1):
        if distances[i] == float('inf'):
            result.append("INF")
        else:
            result.append(str(distances[i]))

    return " ".join(result)

def parse_input(input_str):
    lines = input_str.strip().split('\n')
    N, M, S = map(int, lines[0].split())
    edges = [tuple(map(int, line.split())) for line in lines[1:]]
    return N, M, S, edges

def shortest_paths(input_str):
    N, M, S, edges = parse_input(input_str)
    return dijkstra(N, edges, S)

def compute_temperature_and_duration(schedules):
    """
    This function computes the highest temperature and the longest duration
    from a list of temperature schedules.

    :param schedules: A list of tuples [(temperature, duration), ...]
    :return: A tuple (highest temperature, longest duration)
    """
    max_temperature = 0
    max_duration = 0

    for temp, dur in schedules:
        if temp > max_temperature:
            max_temperature = temp
        if dur > max_duration:
            max_duration = dur

    return (max_temperature, max_duration)

