def number_of_paths(n, m, blocked_positions):
    # Create a table to store results of subproblems
    dp = [[0]*m for _ in range(n)]

    # If the starting point is blocked, return 0
    if (1, 1) in blocked_positions:
        return 0

    # Initial position
    dp[0][0] = 1

    # Fill the dp table
    for i in range(n):
        for j in range(m):
            if (i+1, j+1) in blocked_positions:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

