def contains_subarray_with_sum(arr, n, k, s):
    """
    Returns "YES" if there exists a subarray of length exactly k whose sum is equal to s.
    """

    current_sum = sum(arr[:k])

    if current_sum == s:
        return "YES"

    for i in range(k, n):
        current_sum = current_sum - arr[i - k] + arr[i]
        if current_sum == s:
            return "YES"

    return "NO"

