def is_prime(num):
    """ Helper function to check if a number is prime """
    if num <= 1:
        return False
    if num == 2:
        return True  # 2 is the only even prime number
    if num % 2 == 0:
        return False  # Other even numbers are not primes

    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def count_prime_numbers(lists):
    """
    Takes a list of lists of numbers and returns a list of counts of prime numbers in each sublist.
    """
    # Verify the number of lists
    if len(lists) < 1 or len(lists) > 10:
        return "Invalid Test"

    prime_counts = []

    for lst in lists:
        count = 0

        # Verify each number in the list is within the valid range
        for num in lst:
            if num < 1 or num > 1000:
                return "Invalid Input"
            if is_prime(num):
                count += 1

        prime_counts.append(count)

    return prime_counts

