from math import isqrt

def count_perfect_square_subsequences(n, positions):
    def is_perfect_square(num):
        root = isqrt(num)
        return num == root * root

    count = 0

    for i in range(n):
        product = 1
        for j in range(i, n):
            product *= positions[j]
            if is_perfect_square(product):
                count += 1

    return count

