def construct_matrix(N):
    """
    Constructs an N-by-N matrix where:
    - Each element is a distinct positive integer from 1 to N^2.
    - The absolute difference between any two adjacent elements is at least N.
    """
    matrix = [[0] * N for _ in range(N)]
    num = 1
    for i in range(N):
        for j in range(N):
            matrix[i][j] = num
            num += N
            if num > N*N:
                num = (num % N) + 1
    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(" ".join(map(str, row)))

