def longest_subarray_with_two_distinct(nums):
    """
    Returns the length of the longest subarray with no more than two distinct integers.
    """
    if not nums:
        return 0

    max_len = 0
    left = 0
    count = {}

    for right in range(len(nums)):
        count[nums[right]] = count.get(nums[right], 0) + 1

        while len(count) > 2:
            count[nums[left]] -= 1
            if count[nums[left]] == 0:
                del count[nums[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

