def has_odd_sum_pair(arr):
    """
    Determines if there exists a pair of distinct indices (i, j) such that
    the sum of the elements at these indices is odd.

    :param arr: List of integers
    :return: "YES" if such a pair exists, otherwise "NO"
    """
    odd_count = 0
    even_count = 0

    for num in arr:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

    # An odd sum is possible if there is at least one odd number and one even number
