import heapq

def dijkstra(n, m, s, edges):
    """
    Returns the minimum latency to communicate from source node s to all other nodes in an undirected weighted graph.
    """
    graph = [[] for _ in range(n + 1)]
    for v, u, l in edges:
        graph[v].append((u, l))
        graph[u].append((v, l))

    dist = [float('inf')] * (n + 1)
    dist[s] = 0
    priority_queue = [(0, s)]

    while priority_queue:
        current_dist, current_node = heapq.heappop(priority_queue)

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_dist + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return [dist[i] if dist[i] != float('inf') else -1 for i in range(1, n + 1)]

def solve(n, m, s, edges):
    return dijkstra(n, m, s, edges)

