def is_beautiful_possible(t, test_cases):
    results = []
    for s in test_cases:
        counter = {}
        for char in s:
            if char in counter:
                counter[char] += 1
            else:
                counter[char] = 1

        odd_count = 0
        for count in counter.values():
            if count % 2 != 0:
                odd_count += 1

        # A string is beautiful by changing one character if there is at most one odd character count
        if odd_count <= 2:
            results.append("YES")
        else:
            results.append("NO")

    return results

