def decompress_sequence(s):
    """
    Decompress the given sequence as per the rules defined.

    :param s: Compressed sequence string
    :return: Decompressed original sequence string
    """
    parts = s.split(',')
    result = []

    for part in parts:
        if '*' in part:
            number, count = part.split('*')
            result.extend([number] * int(count))
        else:
            result.append(part)

    return ','.join(result)

