def min_trucks(n, weights, W):
    # Sort the package weights in descending order
    weights.sort(reverse=True)

    trucks = 0
    used = [False] * n  # Track which packages have been loaded into a truck

    for i in range(n):
        if used[i]:
            continue

        current_weight = weights[i]
        used[i] = True

        for j in range(i + 1, n):
            if not used[j] and current_weight + weights[j] <= W:
                current_weight += weights[j]
                used[j] = True

        trucks += 1

    return trucks

