def has_conflicts(presentations):
    from collections import defaultdict

    # Group presentations by room
    rooms = defaultdict(list)
    for p in presentations:
        room, start_h, start_m, end_h, end_m = p
        start = start_h * 60 + start_m  # Convert start time to minutes
        end = end_h * 60 + end_m  # Convert end time to minutes
        rooms[room].append((start, end))

    conflicts = set()

    for room, times in rooms.items():
        times.sort()  # Sort by start time
        for i in range(1, len(times)):
            if times[i][0] < times[i-1][1]:  # Check if current start time is less than previous end time
                conflicts.add(room)
                break

    if conflicts:
        return "Conflict\n" + "\n".join(map(str, sorted(conflicts)))
    else:
        return "No conflicts"

