def process_commands(n, commands):
    catalog = set()
    output = []

    for command in commands:
        cmd, *args = command.split(maxsplit=1)
        if cmd == "ADD":
            title = args[0]
            catalog.add(title)
        elif cmd == "REMOVE":
            title = args[0]
            catalog.discard(title)
        elif cmd == "HAS":
            title = args[0]
            output.append("YES" if title in catalog else "NO")
        elif cmd == "LIST":
            for title in sorted(catalog):
                output.append(title)

    return output

