def most_frequent_word(text):
    words = text.split()
    word_frequency = {}

    for word in words:
        if word in word_frequency:
            word_frequency[word] += 1
        else:
            word_frequency[word] = 1

    max_frequency = max(word_frequency.values())
    for word in words:
        if word_frequency[word] == max_frequency:
            return word

