def maximize_nutritional_value(t, test_cases):
    results = []
    for case in test_cases:
        n, k, B = case[0]
        acorns = case[1:]

        # Initialize dynamic programming array
        dp = [[[-float('inf')] * (B + 1) for _ in range(k + 1)] for _ in range(n + 1)]
        dp[0][0][0] = 0

        for i in range(1, n + 1):
            ni, bi = acorns[i-1]
            for j in range(0, k + 1):
                for b in range(0, B + 1):
                    dp[i][j][b] = dp[i-1][j][b]
                    if j > 0 and b >= bi:
                        dp[i][j][b] = max(dp[i][j][b], dp[i-1][j-1][b-bi] + ni)

        max_nutritional_value = 0
        for b in range(B + 1):
            max_nutritional_value = max(max_nutritional_value, dp[n][k][b])

        results.append(max_nutritional_value)
    return results

