def largest_square_subgrid(M, N, grid):
    # Create a 2D array to store the size of the largest square sub-grid ending at each cell
    dp = [[0] * (N + 1) for _ in range(M + 1)]
    max_side = 0

    for i in range(1, M + 1):
        for j in range(1, N + 1):
            if grid[i-1][j-1] == '1':
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

def can_partition_grid(n, m, grid):
    total_sum = sum(sum(row) for row in grid)

    if total_sum % 2 != 0:
        return "NO"

    target_sum = total_sum // 2

    def dfs(grid, visited, current_sum, row, col):
        if current_sum == target_sum:
            return True

        if row < 0 or row >= n or col < 0 or col >= m or visited[row][col]:
            return False

        visited[row][col] = True
        current_sum += grid[row][col]

        if current_sum > target_sum:
            visited[row][col] = False
            return False

        can_reach = (
            dfs(grid, visited, current_sum, row+1, col) or
            dfs(grid, visited, current_sum, row-1, col) or
            dfs(grid, visited, current_sum, row, col+1) or
            dfs(grid, visited, current_sum, row, col-1)
        )

        if not can_reach:
            visited[row][col] = False

        return can_reach

    visited = [[False for _ in range(m)] for _ in range(n)]
    return "YES" if dfs(grid, visited, 0, 0, 0) else "NO"

