def maximum_profit(n, initial_supply, m, orders):
    supply = initial_supply[:]
    max_profit = 0

    for order in orders:
        k = order[0]
        required = order[1:k*2+1:2]
        quantities = order[2:k*2+2:2]
        price = order[-1]

        can_fulfill = True

        for t, q in zip(required, quantities):
            if supply[t-1] < q:
                can_fulfill = False
                break

        if can_fulfill:
            for t, q in zip(required, quantities):
                supply[t-1] -= q

            max_profit = max(max_profit, price)

    return max_profit

def make_palindrome(s):
    """
    Returns the lexicographically smallest palindrome that can be obtained from the input string s
    with the fewest insertions.
    """
    n = len(s)
    dp = [[0]*n for _ in range(n)]

    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = min(dp[i+1][j], dp[i][j-1]) + 1

    def build_palindrome(i, j):
        if i > j:
            return ""
        if i == j:
            return s[i]
        if s[i] == s[j]:
            return s[i] + build_palindrome(i+1, j-1) + s[j]
        if dp[i+1][j] < dp[i][j-1]:
            return s[i] + build_palindrome(i+1, j) + s[i]
        if dp[i+1][j] > dp[i][j-1]:
            return s[j] + build_palindrome(i, j-1) + s[j]
        # When the values are equal, choose lexicographically smaller option
        opt1 = s[i] + build_palindrome(i+1, j) + s[i]
        opt2 = s[j] + build_palindrome(i, j-1) + s[j]
        return min(opt1, opt2)

    return build_palindrome(0, n-1)

