import json

def validate_json_form_update(n, json_updates):
    initial_structure = {
        "name": "string",
        "age": "integer",
        "email": "string",
        "is_student": "boolean"
    }

    def validate(json_obj):
        # Check if all required fields are present
        for key in initial_structure:
            if key not in json_obj:
                return "Invalid"

        # Check if there are any extra fields
        if set(json_obj.keys()) != set(initial_structure.keys()):
            return "Invalid"

        # Check type of each field
        for key, type_str in initial_structure.items():
            if type_str == "string":
                if not isinstance(json_obj[key], str):
                    return "Invalid"
            elif type_str == "integer":
                if not isinstance(json_obj[key], int):
                    return "Invalid"
            elif type_str == "boolean":
                if not isinstance(json_obj[key], bool):
                    return "Invalid"

        return "Valid"

    results = []
    for json_update in json_updates:
        try:
            json_obj = json.loads(json_update)
            results.append(validate(json_obj))
        except json.JSONDecodeError:
            results.append("Invalid")

    return results

