def minimum_venues_needed(N, M, capacities, participants_preferences):
    capacities = list(capacities)  # list from tuple for mutability
    allocation = [0] * M  # keep allocation counts of venues

    for preferences in participants_preferences:
        allocated = False
        for pref in preferences:
            if allocation[pref - 1] < capacities[pref - 1]:
                allocation[pref - 1] += 1
                allocated = True
                break
        if not allocated:
            return -1  # if any participant can't be accommodated at all, return -1

    venues_used = sum(1 for x in allocation if x > 0)
    return venues_used

