from typing import List

def is_valid_sudoku(board: List[List[str]]) -> bool:
    def is_valid_block(block: List[str]) -> bool:
        block = [num for num in block if num != '.']
        return len(block) == len(set(block))

    for row in board:
        if not is_valid_block(row):
            return False

    for col in zip(*board):
        if not is_valid_block(col):
            return False

    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            block = [
                board[x][y]
                for x in range(i, i + 3)
                for y in range(j, j + 3)
            ]
            if not is_valid_block(block):
                return False

    return True

def find_largest_file(filesystem: dict) -> int:
    def dfs(directory: dict) -> int:
        max_size = -1
        for name, value in directory.items():
            if isinstance(value, dict):
                max_size = max(max_size, dfs(value))
            elif isinstance(value, int):
                max_size = max(max_size, value)
        return max_size

    return dfs(filesystem)

