def is_valid_identifier(S):
    """
    Checks if the string S of length 4 is a valid identifier, containing
    at least one letter and at least one digit.

    Args:
    S (str): A string of length 4 containing digits or uppercase English letters.

    Returns:
    str: "Valid" if the string satisfies the conditions, otherwise "Invalid".
    """
    has_letter = False
    has_digit = False

    for char in S:
        if char.isalpha():
            has_letter = True
        if char.isdigit():
            has_digit = True

    if has_letter and has_digit:
        return "Valid"
    else:
        return "Invalid"

def maximum_contiguous_subsequence_length(n, m, sequence1, sequence2):
    # Use dynamic programming to find the longest common subarray
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    max_length = 0

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if sequence1[i - 1] == sequence2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                max_length = max(max_length, dp[i][j])

    return max_length

