def can_form_subsequence(n, m, s, t, k):
    """
    Determines if t can be formed as a subsequence of s by removing exactly k characters.
    """
    # Utility function to check if t is a subsequence of s.
    def is_subsequence(s, t):
        t_index = 0
        for char in s:
            if t_index < len(t) and char == t[t_index]:
                t_index += 1
        return t_index == len(t)

    # Try to remove exactly k characters and check if t becomes a subsequence
    for i in range(n - k + 1):
        new_s = s[:i] + s[i + k:]
        if is_subsequence(new_s, t):
            return "YES"
    return "NO"

