def sum_of_unique_numbers(sequence):
    """
    Takes a sequence of integers and returns the sum of all unique numbers.
    The input sequence is terminated by a zero, which should not be included in the sum.

    :param sequence: list of integers
    :return: sum of unique numbers
    """
    unique_numbers = set()
    for number in sequence:
        if number == 0:
            break
        unique_numbers.add(number)
    return sum(unique_numbers)

