def is_happy_number(n):
    """
    Returns True if n is a happy number, else False.
    """
    def get_next(number):
        return sum(int(char) ** 2 for char in str(number))

    slow = n
    fast = get_next(n)
    while fast != 1 and slow != fast:
        slow = get_next(slow)
        fast = get_next(get_next(fast))

    return fast == 1

def find_next_happy_number(n: int) -> int:
    """
    Finds the smallest happy number greater than n.
    """
    current = n + 1
    while not is_happy_number(current):
        current += 1
    return current

def generate_parentheses(n):
    def backtrack(s='', left=0, right=0):
        if len(s) == 2 * n:
            result.append(s)
            return
        if left < n:
            backtrack(s+'(', left+1, right)
        if right < left:
            backtrack(s+')', left, right+1)

    result = []
    backtrack()
    return result

def process_input_and_generate_combinations(input_list):
    output = []
    for n in input_list:
        if 1 <= n <= 8:
            combinations = generate_parentheses(n)
            output.append(combinations)
    return output

