def contains_anagram(s1, s2):
    from collections import Counter

    len1, len2 = len(s1), len(s2)

    if len2 > len1:
        return "NO"

    s2_counter = Counter(s2)
    window_counter = Counter(s1[:len2])

    if s2_counter == window_counter:
        return "YES"

    for i in range(len2, len1):
        start_char = s1[i - len2]
        end_char = s1[i]

        window_counter[end_char] += 1
        window_counter[start_char] -= 1

        if window_counter[start_char] == 0:
            del window_counter[start_char]

        if window_counter == s2_counter:
            return "YES"

    return "NO"

def collect_treasures(grid):
    def dfs(x, y, visited):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or (x, y) in visited or grid[x][y] == 'S':
            return
        visited.add((x, y))
        if grid[x][y] == 'T':
            treasures_visited.add((x, y))
        dfs(x + 1, y, visited)
        dfs(x - 1, y, visited)
        dfs(x, y + 1, visited)
        dfs(x, y - 1, visited)

    rows = len(grid)
    cols = len(grid[0])
    visited = set()
    treasures = set()

    start_position = None
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'L':
                start_position = (i, j)
                break
        if start_position:
            break

    if not start_position:
        return False

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'T':
                treasures.add((i, j))

    treasures_visited = set()
    dfs(start_position[0], start_position[1], visited)

    return treasures == treasures_visited

