from collections import deque, defaultdict

def shortest_cycle_length(N, M, edges):
    def bfs(start_vertex):
        dist = [-1] * (N + 1)
        dist[start_vertex] = 0
        parent = [-1] * (N + 1)
        queue = deque([start_vertex])

        while queue:
            v = queue.popleft()
            for u in graph[v]:
                if dist[u] == -1:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    queue.append(u)
                elif parent[v] != u:
                    return dist[v] + dist[u] + 1
        return float("inf")

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    shortest_len = float("inf")
    for i in range(1, N + 1):
        shortest_len = min(shortest_len, bfs(i))

    return shortest_len if shortest_len != float("inf") else -1

