def min_difference_partition(tasks):
    total = sum(tasks)
    n = len(tasks)
    dp = [[False] * (total // 2 + 1) for _ in range(n + 1)]

    # Initialize
    for i in range(n + 1):
        dp[i][0] = True

    # Populate dp array
    for i in range(1, n + 1):
        for j in range(1, total // 2 + 1):
            if tasks[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - tasks[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    # Find the largest value which we can achieve closest to total // 2
    for j in range(total // 2, -1, -1):
        if dp[n][j]:
            return total - 2 * j

