def largest_square_submatrix(matrix):
    """
    Given a binary matrix, this function finds the size of the largest square submatrix that contains all 1s.

    Args:
    matrix: List[List[int]]: A list of lists representing the binary matrix.

    Returns:
    int: The size of the largest square submatrix that contains all 1s.
    """
    if not matrix or not matrix[0]:
        return 0

    N = len(matrix)
    dp = [[0] * N for _ in range(N)]
    max_size = 0

    for i in range(N):
        for j in range(N):
            if i == 0 or j == 0:
                dp[i][j] = matrix[i][j]
            elif matrix[i][j] == 1:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
            else:
                dp[i][j] = 0
            max_size = max(max_size, dp[i][j])

    return max_size

def parse_input_and_find_largest_square_submatrix(input_string):
    lines = input_string.split("\n")
    N = int(lines[0])
    matrix = []
    for i in range(1, N + 1):
        row = list(map(int, list(lines[i].strip())))
        matrix.append(row)
    return largest_square_submatrix(matrix)

