from collections import deque

def is_path_exist(grid):
    n = len(grid)
    if grid[0][0] == '#' or grid[n-1][n-1] == '#':
        return "NO"

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    queue = deque([(0, 0)])
    visited = set()
    visited.add((0, 0))

    while queue:
        x, y = queue.popleft()
        if (x, y) == (n - 1, n - 1):
            return "YES"
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] == '.':
                visited.add((nx, ny))
                queue.append((nx, ny))

    return "NO"

def find_paths(test_cases):
    results = []
    for grid in test_cases:
        results.append(is_path_exist(grid))
    return results

