    for result in results:
        print(result)

def longest_arithmetic_subsequence(arr):
    if len(arr) <= 1:
        return len(arr)

    n = len(arr)
    dp = [{} for _ in range(n)]
    max_length = 2

    for i in range(n):
        for j in range(i + 1, n):
            diff = arr[j] - arr[i]
            if diff in dp[i]:
                dp[j][diff] = dp[i][diff] + 1
            else:
                dp[j][diff] = 2
            max_length = max(max_length, dp[j][diff])

    return max_length

