def smallest_subarray(n, arr, x, y, k):
    """
    Find the length of the smallest subarray where the absolute difference between the count of `x` and `y`
    in this subarray is at least `k`.
    """
    min_length = float('inf')

    for start in range(n):
        count_x = 0
        count_y = 0

        for end in range(start, n):
            if arr[end] == x:
                count_x += 1
            if arr[end] == y:
                count_y += 1

            if abs(count_x - count_y) >= k:
                min_length = min(min_length, end - start + 1)
                break  # No need to look further in this subarray because we already found a valid one

    return min_length if min_length != float('inf') else -1

def process_test_cases(T, test_cases):
    results = []
    for i in range(T):
        n, arr, x, y, k = test_cases[i]
        result = smallest_subarray(n, arr, x, y, k)
        results.append(result)
    return results

