def find_largest_region(grid, n, m):
    def dfs(x, y):
        stack = [(x, y)]
        size = 0
        while stack:
            cx, cy = stack.pop()
            if 0 <= cx < n and 0 <= cy < m and grid[cx][cy] == 1 and not visited[cx][cy]:
                visited[cx][cy] = True
                size += 1
                # Add all 4 possible neighbors
                stack.append((cx + 1, cy))
                stack.append((cx - 1, cy))
                stack.append((cx, cy + 1))
                stack.append((cx, cy - 1))
        return size

    visited = [[False] * m for _ in range(n)]
    largest = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1 and not visited[i][j]:
                largest = max(largest, dfs(i, j))
    return largest

def manage_farm(n, m, q, operations):
    grid = [[0] * m for _ in range(n)]
    results = []

    for operation in operations:
        parts = operation.split()
        if parts[0] == '1':
            x, y = int(parts[1]), int(parts[2])
            grid[x][y] = 1
        elif parts[0] == '2':
            results.append(find_largest_region(grid, n, m))

    return results

