def max_profit(prices):
    """
    Returns the maximum profit that can be achieved from a single buy and sell of stock prices
    provided in the list. If no profit is possible, returns 0.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        current_profit = price - min_price
        if current_profit > max_profit:
            max_profit = current_profit

    return max_profit

def process_input(data):
    results = []
    for line in data:
        prices = list(map(int, line.split()))
        if len(prices) == 1 and prices[0] == 0:
            break
        results.append(max_profit(prices[:-1]))
    return results

