def longest_subsequence(n, arr):
    """
    Returns the length of the longest subsequence where the difference between each pair of
    consecutive elements is either 1 or -1.
    """
    if n == 0:
        return 0

    # Create a dp array initialized to 1 (each element is a subsequence of length 1 by itself)
    dp = [1] * n

    # Iterate through the array to find the longest subsequence
    for i in range(1, n):
        for j in range(i):
            if abs(arr[i] - arr[j]) == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

