def count_non_overlapping_occurrences(s, t):
    """
    Returns the number of distinct non-overlapping occurrences of t in s.
    """
    count = 0
    i = 0
    while i <= len(s) - len(t):
        if s[i:i+len(t)] == t:
            count += 1
            i += len(t)
        else:
            i += 1
    return count

