def max_score_A(array):
    n = len(array)
    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = array[i]

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = max(
                array[i] + min(dp[i + 2][j] if i + 2 <= j else 0, dp[i + 1][j - 1] if i + 1 <= j - 1 else 0),
                array[j] + min(dp[i + 1][j - 1] if i + 1 <= j - 1 else 0, dp[i][j - 2] if i <= j - 2 else 0)
            )

    A_score = dp[0][n - 1]
    return A_score

