def highlight_students(n, m, candies):
    # Create a list of tuples (candies, index) so we can sort while preserving the original indices
    indexed_candies = [(candies[i], i + 1) for i in range(n)]

    # Sort by the number of candies in descending order, and by index in ascending order
    indexed_candies.sort(key=lambda x: (-x[0], x[1]))

    # Use a set to keep track of the distinct candies seen
    distinct_candies = set()
    selected_indices = []

    for candy, index in indexed_candies:
        if candy not in distinct_candies:
            distinct_candies.add(candy)
            selected_indices.append(index)
            if len(selected_indices) == m:
                break

    if len(selected_indices) == m:
        return "POSSIBLE", selected_indices
    else:
        return "IMPOSSIBLE", []

from collections import deque

def is_valid(x, y, n, m, grid, visited):
    return 0 <= x < n and 0 <= y < m and grid[x][y] == '.' and not visited[x][y]

def bfs(grid, start, end, n, m):
    directions = [(-1,0), (1,0), (0,-1), (0,1)]
    queue = deque([(start[0], start[1], 0)]) # (x, y, distance)
    visited = [[False] * m for _ in range(n)]

    while queue:
        x, y, dist = queue.popleft()
        if (x, y) == end:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, n, m, grid, visited):
                visited[nx][ny] = True
                queue.append((nx, ny, dist + 1))

    return -1

def min_steps_to_and_return(n, m, grid):
    start = (0, 0)
    end = (n - 1, m - 1)

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return -1

    steps_to_end = bfs(grid, start, end, n, m)
    if steps_to_end == -1:
        return -1

    steps_to_start = bfs(grid, end, start, n, m)
    if steps_to_start == -1:
        return -1

    return steps_to_end + steps_to_start

def longestStrChain(words):
    words.sort(key=len)
    longest_chain = {word: 1 for word in words}

    max_length = 1

    for word in words:
        for i in range(len(word)):
            predecessor = word[:i] + word[i + 1:]
            if predecessor in longest_chain:
                longest_chain[word] = max(longest_chain[word], longest_chain[predecessor] + 1)
                max_length = max(max_length, longest_chain[word])

    return max_length

