from collections import deque

def shortest_path_in_grid(n, m, grid):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == 0

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (x, y, distance)

    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return -1  # start or end is blocked

    grid[0][0] = 1  # mark as visited by setting to 1

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == (n-1, m-1):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                grid[nx][ny] = 1  # mark as visited
                queue.append((nx, ny, dist + 1))

    return -1

def process_test_cases(t, test_cases):
    results = []
    for case in test_cases:
        n, m = case['n'], case['m']
        grid = case['grid']
        result = shortest_path_in_grid(n, m, grid)
        results.append(result)
    return results

