def smallest_lexicographic_concatenation(n, k, words):
    """
    Returns the smallest lexicographic concatenation of k words from the list of words.
    """
    if k > n:
        return "-1"

    sorted_words = sorted(words)
    return "".join(sorted_words[:k])

