def evaluate_operations(n, operations):
    variable_dict = {}
    results = []

    for operation in operations:
        if operation.startswith("evaluate"):
            var = operation.split("(")[1].split(")")[0]
            results.append(variable_dict.get(var, "undefined"))
        elif "=" in operation:
            var, expr = operation.split("=")
            var = var.strip()
            expr = expr.strip()
            if "+" in expr:
                var1, var2 = map(str.strip, expr.split("+"))
                value = variable_dict.get(var1, 0) + int(var2) if var2.isdigit() else variable_dict.get(var2, 0)
            elif "-" in expr:
                var1, var2 = map(str.strip, expr.split("-"))
                value = variable_dict.get(var1, 0) - int(var2) if var2.isdigit() else variable_dict.get(var2, 0)
            else:
                value = int(expr)
            variable_dict[var] = value

    return results

