def can_divide_fruits_equally(n, k, sweetness_levels):
    total_sweetness = sum(sweetness_levels)

    if total_sweetness % k != 0:
        return "NO"

    target_sweetness = total_sweetness // k

    # Sort the sweetness levels in descending order for easier division
    sweetness_levels.sort(reverse=True)

    used = [False] * n

    def can_partition(start_index, k_remaining, current_sum):
        if k_remaining == 0:
            return True
        if current_sum == target_sweetness:
            return can_partition(0, k_remaining - 1, 0)

        for i in range(start_index, n):
            if not used[i] and current_sum + sweetness_levels[i] <= target_sweetness:
                used[i] = True
                if can_partition(i + 1, k_remaining, current_sum + sweetness_levels[i]):
                    return True
                used[i] = False

        return False

    if can_partition(0, k, 0):
        return "YES"
    else:
        return "NO"

