def solve(X, Y, Z):
    """
    Returns the sum of X, Y, and Z if X is a divisor of both Y and Z,
    otherwise, returns the product of X and the maximum of Y or Z.
    """
    if Y % X == 0 and Z % X == 0:
        return X + Y + Z
    else:
        return X * max(Y, Z)

