def count_distinct_palindromic_substrings(s):
    """
    Returns the count of distinct palindromic substrings in the given string s.
    """
    def expand_around_center(s, left, right, palindromes):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            palindromes.add(s[left:right+1])
            left -= 1
            right += 1

    palindromes = set()
    for i in range(len(s)):
        # Odd length palindromes
        expand_around_center(s, i, i, palindromes)
        # Even length palindromes
        expand_around_center(s, i, i+1, palindromes)

    return len(palindromes)

def count_palindromic_substrings_test_cases(test_cases):
    results = []
    for s in test_cases:
        results.append(count_distinct_palindromic_substrings(s))
    return results

