def zigzag_pattern(arr):
    """
    Rearranges the array elements into a zigzag pattern.
    :param arr: List[int], The input array of integers
    :return: List[int], The array rearranged in zigzag pattern
    """
    n = len(arr)
    for i in range(n - 1):
        if i % 2 == 0:
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
        else:
            if arr[i] < arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
    return arr

