def check_nodes_connectivity(n, m, nodes_to_check):
    """
    Returns "YES" if all given nodes can connect to the root node, otherwise returns "NO".
    """
    # The nodes should be in the range from 0 to n - 1
    for node in nodes_to_check:
        if node >= n:
            return "NO"
    return "YES"

