def max_continuous_ones(n, values, edges):
    from collections import defaultdict, deque

    def bfs_max_ones(root):
        max_continuous = 0
        queue = deque([(root, 0)])  # (currentNode, current length of continuous ones)

        while queue:
            node, current_length = queue.popleft()

            if values[node-1] == 1:
                current_length += 1
            else:
                current_length = 0

            max_continuous = max(max_continuous, current_length)

            for child in tree[node]:
                queue.append((child, current_length))

        return max_continuous

    # Building the tree adjacency list
    tree = defaultdict(list)
    for parent, child in edges:
        tree[parent].append(child)

    return bfs_max_ones(1)

def largest_uniform_subgrid(n, m, grid):
    """
    Returns the area of the largest rectangular subgrid that contains all the same character.
    """

    max_area = 0
    for i in range(n):
        for j in range(m):
            current_char = grid[i][j]
            # Start from (i, j) and try to expand the rectangle
            for k in range(i, n):
                for l in range(j, m):
                    if all(grid[x][y] == current_char for x in range(i, k + 1) for y in range(j, l + 1)):
                        max_area = max(max_area, (k - i + 1) * (l - j + 1))

    return max_area

def is_leap_year(year):
    """
    Returns 'Leap Year' if the given year is a leap year, otherwise returns 'Not a Leap Year'.
    """
    if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
        return "Leap Year"
    else:
        return "Not a Leap Year"

