from collections import defaultdict

def find_meeting_time(T, test_cases):
    results = []

    for i in range(T):
        N = test_cases[i][0]
        positions = test_cases[i][1]

        position_frequency = defaultdict(int)

        for pos in positions:
            position_frequency[pos] += 1

        max_frequency = max(position_frequency.values())

        if max_frequency > 1:
            results.append(0)
        else:
            results.append(1)

    return results

