def find_valid_substrings(s: str, k: int) -> int:
    from collections import Counter

    def at_most_k_distinct(s, k):
        count = Counter()
        left = 0
        result = 0
        for right in range(len(s)):
            count[s[right]] += 1
            while len(count) > k:
                count[s[left]] -= 1
                if count[s[left]] == 0:
                    del count[s[left]]
                left += 1
            result += right - left + 1
        return result

    return at_most_k_distinct(s, k) - at_most_k_distinct(s, k - 1)

