def has_subarray_with_sum(arr, K):
    """
    Returns "YES" if there exists a subarray that sums up to K, otherwise "NO".
    """
    current_sum = 0
    prefix_sums = {}

    for num in arr:
        current_sum += num

        if current_sum == K:
            return "YES"

        if (current_sum - K) in prefix_sums:
            return "YES"

        prefix_sums[current_sum] = True

    return "NO"

