def can_form_square(n, lengths):
    """
    Returns "YES" if it is possible to form a square with four sticks of the same length
    and "NO" otherwise.
    """
    if n < 4:
        return "NO"

    lengths_count = {}

    for length in lengths:
        if length in lengths_count:
            lengths_count[length] += 1
        else:
            lengths_count[length] = 1

    for count in lengths_count.values():
        if count >= 4:
            return "YES"

    return "NO"

