def shortest_common_supersequence(a, b):
    # Get the length of the input strings
    m, n = len(a), len(b)

    # Build the DP table for the lengths of longest common subsequence
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Building the shortest common supersequence from the dp table
    i, j = m, n
    scs = []

    while i > 0 and j > 0:
        if a[i - 1] == b[j - 1]:
            scs.append(a[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            scs.append(a[i - 1])
            i -= 1
        else:
            scs.append(b[j - 1])
            j -= 1

    while i > 0:
        scs.append(a[i - 1])
        i -= 1

    while j > 0:
        scs.append(b[j - 1])
        j -= 1

    scs.reverse()

    return ''.join(scs)

