def is_toeplitz(matrix):
    n = len(matrix)
    m = len(matrix[0])

    for i in range(n - 1):
        for j in range(m - 1):
            if matrix[i][j] != matrix[i + 1][j + 1]:
                return False
    return True

def main(input_lines):
    nm = input_lines[0].split()
    n = int(nm[0])
    m = int(nm[1])
    matrix = []

    for i in range(1, n + 1):
        row = list(map(int, input_lines[i].split()))
        matrix.append(row)

    result = is_toeplitz(matrix)
    return str(result)

