def min_operations_to_satisfy_children(t, test_cases):
    results = []

    for case in test_cases:
        m, n, candies, preferences = case
        candies.sort()
        preferences.sort()

        i = 0
        j = 0
        operations = 0

        while i < m and j < n:
            if candies[i] <= preferences[j]:
                operations += 1
                j += 1
            i += 1

        if operations < n:
            results.append(-1)
        else:
            results.append(operations)

    return results

