from collections import deque

def min_moves_to_reach_end(grid, N, M):
    if grid[0][0] == 0 or grid[N-1][M-1] == 0:
        return -1

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    queue = deque([(0, 0, 1)])  # (row, col, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if x == N-1 and y == M-1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < M and grid[nx][ny] == 1 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

def parse_input_and_solve(input_string):
    input_lines = input_string.strip().split('\n')
    N, M = map(int, input_lines[0].split())
    grid = [list(map(int, line.split())) for line in input_lines[1:]]
    return min_moves_to_reach_end(grid, N, M)

def count_beautiful_substrings(s):
    def is_palindrome(sub):
        return sub == sub[::-1]

    n = len(s)
    beautiful_count = 0

    for i in range(n):
        for j in range(i + 1, n + 1):
            if is_palindrome(s[i:j]):
                beautiful_count += 1

    return beautiful_count

