def count_equal_0s_1s_subarrays(arr):
    """
    Returns the number of subarrays with an equal number of 0s and 1s.

    Arguments:
    arr -- List of integers (only 0s and 1s).

    Return:
    int -- Count of subarrays with equal number of 0s and 1s.
    """
    count_map = {}
    current_sum = 0
    count = 0

    for num in arr:
        if num == 0:
            current_sum -= 1
        else:
            current_sum += 1

        if current_sum == 0:
            count += 1

        if current_sum in count_map:
            count += count_map[current_sum]
            count_map[current_sum] += 1
        else:
            count_map[current_sum] = 1

    return count

