def count_valid_ways(N):
    if N == 1:
        return 2  # 'A' and 'B'
    if N == 2:
        return 4  # 'AA', 'AB', 'BA', 'BB'

    # Base cases for dynamic programming
    dp = [0] * (N + 1)
    dp[1] = 2
    dp[2] = 4

    for i in range(3, N + 1):
        dp[i] = dp[i - 1] + dp[i - 2]

    return dp[N]

