def find_zero_sum_triplets(n, nums):
    if n < 3:
        return 0, []

    nums.sort()
    unique_triplets = set()

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        l, r = i + 1, n - 1
        while l < r:
            s = nums[i] + nums[l] + nums[r]
            if s == 0:
                unique_triplets.add((nums[i], nums[l], nums[r]))
                while l < r and nums[l] == nums[l + 1]:
                    l += 1
                while l < r and nums[r] == nums[r - 1]:
                    r -= 1
                l += 1
                r -= 1
            elif s < 0:
                l += 1
            else:
                r -= 1

    sorted_triplets = sorted(list(unique_triplets))
    return len(sorted_triplets), sorted_triplets

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def longest_distance(M, positions):
    positions.sort()
    diffs = [positions[i] - positions[i - 1] for i in range(1, M)]
    d = diffs[0]
    for i in range(1, M - 1):
        d = gcd(d, diffs[i])
        if d == 1:
            return 1
    return d

