def find_min_larger_than_neighbors(nums):
    """
    Returns the minimum element in the array that is larger than its neighbors.
    """
    n = len(nums)
    if n < 3:
        return -1  # Not enough elements to have a neighbor on both sides.

    min_peak = float('inf')
    found_peak = False

    for i in range(1, n - 1):
        if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
            if nums[i] < min_peak:
                min_peak = nums[i]
                found_peak = True

    return min_peak if found_peak else -1

