def count_unique_subarrays(nums, k):
    """
    Returns the number of unique subarrays of length k that have all distinct elements.

    :param nums: List of integers representing the array
    :param k: Target subarray length
    :return: Number of unique subarrays of length k with all distinct elements
    """
    if k > len(nums):
        return 0

    unique_count = 0
    window = {}
    left = 0

    for right in range(len(nums)):
        window[nums[right]] = window.get(nums[right], 0) + 1

        if right - left + 1 > k:
            if window[nums[left]] == 1:
                del window[nums[left]]
            else:
                window[nums[left]] -= 1
            left += 1

        if right - left + 1 == k and len(window) == k:
            unique_count += 1

    return unique_count

