from typing import List

def is_balanced(arr: List[int]) -> bool:
    n = len(arr)

    if n == 0:
        return True  # An empty array is considered balanced

    if n == 1:
        return True  # A single-element array is considered balanced

    if n % 2 == 0:
        left_sum = sum(arr[:n//2])
        right_sum = sum(arr[n//2:])
    else:
        left_sum = sum(arr[:n//2])
        right_sum = sum(arr[n//2+1:])

    return left_sum == right_sum

