import bisect

def longest_lexicographical_subsequence(transactions):
    """
    Returns the length of the longest lexicographical subsequence.
    """
    if not transactions:
        return 0

    # dp array to store the subsequence elements
    dp = []

    for t in transactions:
        # Find the place to insert t in the dp array
        pos = bisect.bisect_left(dp, t)
        if pos < len(dp):
            dp[pos] = t
        else:
            dp.append(t)

    return len(dp)

