def longest_increasing_subsequence_length(sequence):
    """
    Returns the length of the longest increasing subsequence in the given sequence.
    """
    if not sequence:
        return 0

    n = len(sequence)

    # Initialize the list to store the length of the longest increasing subsequence ending at each index
    lis = [1] * n

    # Build the lis array in a bottom-up manner
    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # The length of the longest increasing subsequence will be the maximum value in lis array
    return max(lis)

