def decimal_to_base7(n):
    """
    Converts a non-negative integer from decimal to base-7 representation.
    """
    if n == 0:
        return "0"

    digits = []
    while n > 0:
        digits.append(str(n % 7))
        n //= 7

    return ''.join(digits[::-1])

