def maximal_rectangle(grid):
    if not grid:
        return 0

    M, N = len(grid), len(grid[0])
    max_area = 0
    height = [0] * N
    left = [0] * N
    right = [N] * N

    for i in range(M):
        cur_left, cur_right = 0, N
        # Update height
        for j in range(N):
            if grid[i][j] == 'E':
                height[j] += 1
            else:
                height[j] = 0

        # Update left boundary (from left to right)
        for j in range(N):
            if grid[i][j] == 'E':
                left[j] = max(left[j], cur_left)
            else:
                left[j] = 0
                cur_left = j + 1

        # Update right boundary (from right to left)
        for j in range(N-1, -1, -1):
            if grid[i][j] == 'E':
                right[j] = min(right[j], cur_right)
            else:
                right[j] = N
                cur_right = j

        # Calculate the area of rectangle (height[j] * (right[j] - left[j]))
        for j in range(N):
            max_area = max(max_area, height[j] * (right[j] - left[j]))

    return max_area

from collections import deque

def min_steps_to_border(n, m, grid):
    def is_border_cell(x, y):
        return x == 0 or x == n-1 or y == 0 or y == m-1

    # Find the starting position
    start_x, start_y = None, None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start_x, start_y = i, j
                break
        if start_x is not None:
            break

    if is_border_cell(start_x, start_y):
        return 0

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS setup
    queue = deque([(start_x, start_y, 0)])
    visited = set((start_x, start_y))

    while queue:
        x, y, steps = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] == '.':
                if is_border_cell(nx, ny):
                    return steps + 1
                queue.append((nx, ny, steps + 1))
                visited.add((nx, ny))

    return -1

