def is_valid_isbn(isbn):
    """
    Check if the provided ISBN-13 number is valid.

    Args:
    isbn (str): The 13-digit ISBN number as a string.

    Returns:
    str: "Valid" if the ISBN is valid, "Invalid" otherwise.
    """
    if len(isbn) != 13 or not isbn.isdigit():
        return "Invalid"

    check_sum = 0
    for i in range(12):
        digit = int(isbn[i])
        if i % 2 == 0:
            check_sum += digit  # Multiple by 1 if index is even
        else:
            check_sum += digit * 3  # Multiple by 3 if index is odd

    check_digit = int(isbn[-1])
    calculated_check_digit = (10 - (check_sum % 10)) % 10

    if check_digit == calculated_check_digit:
        return "Valid"
    else:
        return "Invalid"

