import collections

def walls_and_gates(rooms):
    if not rooms or not rooms[0]:
        return rooms

    m, n = len(rooms), len(rooms[0])
    queue = collections.deque()

    # Collect all gates' positions
    for i in range(m):
        for j in range(n):
            if rooms[i][j] == 0:
                queue.append((i, j))

    while queue:
        x, y = queue.popleft()
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            new_x, new_y = x + dx, y + dy
            if 0 <= new_x < m and 0 <= new_y < n and rooms[new_x][new_y] == float('inf'):
                rooms[new_x][new_y] = rooms[x][y] + 1
                queue.append((new_x, new_y))

    return rooms

