def sieve_of_eratosthenes(n):
    """Use the Sieve of Eratosthenes to find all primes up to n."""
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(n**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, n + 1, start):
                is_prime[multiple] = False

    return [num for num, prime in enumerate(is_prime) if prime]

def largest_twin_prime_pair(n):
    """Find the largest twin prime pair (p, p+2) where p+2 ≤ n."""
    primes = sieve_of_eratosthenes(n)

    last_twin_prime = -1
    for i in range(len(primes) - 1):
        if primes[i+1] == primes[i] + 2:
            last_twin_prime = (primes[i], primes[i] + 2)

    if last_twin_prime == -1:
        return "-1"
    else:
        return f"{last_twin_prime[0]} {last_twin_prime[1]}"

