def has_same_type_rectangle(n, m, grid):
    """
    Function to check if there exists at least one rectangle of blocks with the same type
    in the given grid.

    Parameters:
    n (int): number of rows in the grid
    m (int): number of columns in the grid
    grid (list of list of int): the grid elements

    Returns:
    str: "YES" if there exists a rectangle of the same type blocks, otherwise "NO"
    """
    for row in range(n):
        for col in range(m - 1):
            for k in range(col + 1, m):
                type_val = grid[row][col]
                if grid[row][k] == type_val:
                    for temp_row in range(row + 1, n):
                        if grid[temp_row][col] == type_val and grid[temp_row][k] == type_val:
                            return "YES"
    return "NO"

def count_unique_pairs(arr, target):
    seen = set()
    pairs = set()

    for number in arr:
        complement = target - number
        if complement in seen:
            pairs.add(tuple(sorted((number, complement))))
        seen.add(number)

    return len(pairs)

