def find_smallest_in_subarray(A, queries):
    results = []
    for l, r, x in queries:
        subarray = A[l-1: r]
        valid_elements = [num for num in subarray if num >= x]
        if valid_elements:
            results.append(min(valid_elements))
        else:
            results.append(-1)
    return results

def process_queries(n, q, k, arr, queries):
    results = []
    for l, r, x in queries:
        subarray = arr[l-1:r]
        if subarray.count(x) > k:
            results.append("YES")
        else:
            results.append("NO")
    return results

