def max_boxes_in_row(n, boxes):
    def can_place(prev, curr):
        return prev[0] < curr[0] and prev[1] < curr[1]

    # Each box can either be taken as is or rotated
    transformed_boxes = []
    for w, h in boxes:
        transformed_boxes.append((min(w, h), max(w, h)))

    transformed_boxes.sort()

    dp = [1] * n  # Initialize the dp array with 1

    for i in range(n):
        for j in range(i):
            if can_place(transformed_boxes[j], transformed_boxes[i]):
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

