def min_cost_to_adjust_trees(n, A, B, heights):
    cost = 0
    for i in range(1, n):
        if heights[i] == heights[i-1]:
            if A < B:
                heights[i] += 1
                cost += A
            else:
                heights[i] -= 1
                cost += B
    return cost

