def count_non_overlapping_occurrences(S, T):
    """
    Returns the number of non-overlapping occurrences of substring T in string S.
    """
    count = 0
    i = 0
    while i <= len(S) - len(T):
        if S[i:i+len(T)] == T:
            count += 1
            i += len(T)
        else:
            i += 1
    return count

