def min_max_diff(n, books):
    total_sum = sum(books)

    # dp[i] will be True if sum 'i' can be achieved with some subset of books
    dp = [False] * (total_sum // 2 + 1)
    dp[0] = True

    for book in books:
        for j in range(total_sum // 2, book - 1, -1):
            if dp[j - book]:
                dp[j] = True

    for i in range(total_sum // 2, -1, -1):
        if dp[i]:
            first_part = i
            break

    second_part = total_sum - first_part
    return abs(second_part - first_part)


def minimize_max_diff(T, test_cases):
    results = []
    for t in range(T):
        n, books = test_cases[t]
        if n == 1:
            results.append(sum(books))  # If there is only one shelf, the difference is the total sum
        elif n >= len(books):
            results.append(0)  # If shelves are more than or equal to books, difference is zero
        else:
            results.append(min_max_diff(n, books))
    return results

from heapq import heappop, heappush
from typing import List

def min_effort_path(matrix: List[List[int]]) -> int:
    n, m = len(matrix), len(matrix[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    effort = [[float('inf')] * m for _ in range(n)]
    effort[0][0] = 0
    heap = [(0, 0, 0)]  # (effort, x, y)

    while heap:
        current_effort, x, y = heappop(heap)

        if x == n-1 and y == m-1:
            return current_effort

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                next_effort = max(current_effort, abs(matrix[nx][ny] - matrix[x][y]))
                if next_effort < effort[nx][ny]:
                    effort[nx][ny] = next_effort
                    heappush(heap, (next_effort, nx, ny))

    return -1

def most_frequent_word(s):
    """
    Finds the word that appears most frequently in the given string.
    If multiple words have the same highest frequency, returns the one that appears first.
    """
    words = s.split()
    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    max_freq = max(frequency.values())
    for word in words:
        if frequency[word] == max_freq:
            return word

