def find_max_value(M, N, queries):
    """
    Finds the maximum value in the grid after processing the given queries.

    Parameters:
    M (int): Number of rows.
    N (int): Number of columns.
    queries (list of tuples): A list of queries, each represented as a tuple (x1, y1, x2, y2).

    Returns:
    int: The maximum value present in the grid after processing all the queries.
    """

    # Initialize the grid with zeros
    grid = [[0]* (N + 1) for _ in range(M + 1)]

    # Process queries using a difference array approach
    for x1, y1, x2, y2 in queries:
        grid[x1][y1] += 1
        if x2 + 1 <= M:
            grid[x2 + 1][y1] -= 1
        if y2 + 1 <= N:
            grid[x1][y2 + 1] -= 1
        if x2 + 1 <= M and y2 + 1 <= N:
            grid[x2 + 1][y2 + 1] += 1

    # Apply the difference approach to get the final grid values
    for i in range(1, M + 1):
        for j in range(1, N + 1):
            if i > 1:
                grid[i][j] += grid[i - 1][j]
            if j > 1:
                grid[i][j] += grid[i][j - 1]
            if i > 1 and j > 1:
                grid[i][j] -= grid[i - 1][j - 1]

    # Find the maximum value in the grid
    max_value = 0
    for i in range(1, M + 1):
        for j in range(1, N + 1):
            max_value = max(max_value, grid[i][j] + 1)

    return max_value

