    array.sort()
    triplets = set()

    for i in range(n):
        if i > 0 and array[i] == array[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            sum = array[i] + array[left] + array[right]
            if sum == 0:
                triplets.add((array[i], array[left], array[right]))
                left += 1
                right -= 1
                while left < right and array[left] == array[left - 1]:
                    left += 1
                while left < right and array[right] == array[right + 1]:
                    right -= 1
            elif sum < 0:
                left += 1
            else:
                right -= 1

    for triplet in triplets:
        print(f"{triplet[0]} {triplet[1]} {triplet[2]}")

def install_solar_panels(n, m):
    # Check for edge case when it's impossible to install panels satisfying the condition
    if n == 1 and m == 1:
        return [[1]]

    panels = [[0] * m for _ in range(n)]

    # Fill panels grid with zigzag pattern
    num = 1
    for i in range(n):
        for j in range(m):
            panels[i][j] = num
            num += 1

    for i in range(n):
        if i % 2 == 1:
            panels[i].reverse()

    # Print and return the grid
    for line in panels:
        print(' '.join(map(str, line)))

    return panels

def is_magic_word(word):
    length = len(word)

    if length % 2 == 0:
        first_half = word[:length//2]
        second_half = word[length//2:]
    else:
        first_half = word[:length//2 + 1]
        second_half = word[length//2:]

    char_count = {}
    for char in first_half:
        if char in char_count:
            char_count[char][0] += 1
        else:
            char_count[char] = [1, 0]

    for char in second_half:
        if char in char_count:
            char_count[char][1] += 1
        else:
            char_count[char] = [0, 1]

    matching_chars = 0
    total_chars = len(first_half)

    for counts in char_count.values():
        if counts[0] == counts[1]:
            matching_chars += 1

    return "YES" if matching_chars >= total_chars / 2 else "NO"

def check_magic_words(test_cases):
    results = []
    for word in test_cases:
        results.append(is_magic_word(word))
    return results

