def count_paths(n, grid):
    # Initialize DP table with 0s.
    dp = [[0]*n for _ in range(n)]

    # If the starting point is an obstacle, return 0.
    if grid[0][0] == 'O':
        return 0

    # Starting point
    dp[0][0] = 1

    # Fill the dp table
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 'O':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

