def min_jumps(arr):
    """
    Returns the minimum number of jumps needed for the frog to reach the end of the array.
    If the end is not reachable, return -1.
    """
    n = len(arr)
    if n == 1:
        return 0
    if arr[0] == 0:
        return -1

    jumps = 0
    current_end = 0
    current_farthest = 0

    for i in range(n):
        current_farthest = max(current_farthest, i + arr[i])

        if i == current_end:
            jumps += 1
            current_end = current_farthest
            if current_end >= n - 1:
                return jumps

        if i >= current_farthest:
            return -1

    return -1

