def count_paths(m, n, blocked_cells):
    """
    Returns the number of distinct paths from the top-left corner to the bottom-right corner
    in an m x n grid with specified blocked cells.
    """
    # Create a grid to store the number of ways to reach each cell
    grid = [[0 for _ in range(n)] for _ in range(m)]

    # Initialize the starting point
    if (1, 1) in blocked_cells:
        return 0
    grid[0][0] = 1

    # Fill the grid
    for i in range(m):
        for j in range(n):
            if (i+1, j+1) in blocked_cells:
                grid[i][j] = 0
            else:
                if i > 0:
                    grid[i][j] += grid[i-1][j]
                if j > 0:
                    grid[i][j] += grid[i][j-1]

    return grid[m-1][n-1]

def solve(grid_cases):
    """
    Process multiple test cases and return a list with number of paths for each case.
    """
    results = []
    for case in grid_cases:
        m, n, b, blocked_cells = case
        results.append(count_paths(m, n, blocked_cells))
    return results

