def count_unique_codes(codes):
    """
    Returns the number of unique codes after removing all similar ones.
    """
    unique_codes = set()

    for code in codes:
        # Sort the digits of the code to get the canonical form
        sorted_code = ''.join(sorted(code))
        unique_codes.add(sorted_code)

    return len(unique_codes)

# Reading input method assumes a list of codes are directly passed to the function
def main(input_str):
    lines = input_str.strip().split("\n")
    N = int(lines[0])
    codes = lines[1:N+1]
    return count_unique_codes(codes)

def max_height_difference(n, heights):
    """
    Returns the maximum difference in height between any two points
    on the trail, where the higher point comes after the lower point.
    """
    if n <= 1:
        return 0

    max_diff = 0
    min_height = heights[0]

    for i in range(1, n):
        if heights[i] > min_height:
            max_diff = max(max_diff, heights[i] - min_height)
        else:
            min_height = min(min_height, heights[i])

    return max_diff

