def perform_operations(n, sequence, m, operations):
    """
    Perform a list of operations on a sequence of integers.

    :param n: int, number of elements in the sequence
    :param sequence: list of int, the sequence of integers
    :param m: int, number of operations
    :param operations: list of tuples, each operation in the form ("operation_type", x, y)
    :return: list of int, the final sequence after performing all operations
    """
    for operation, x, y in operations:
        if operation == "increase":
            for i in range(x - 1, y):
                sequence[i] += 1
        elif operation == "decrease":
            for i in range(x - 1, y):
                sequence[i] -= 1
    return sequence

