def min_operations_to_transform(s1, s2):
    """
    Returns the minimum number of operations required to transform s1 into s2.
    Operations allowed: insert, remove, replace a character.
    """
    # Get lengths of both strings
    m, n = len(s1), len(s2)

    # Create a DP array to store the number of operations
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize DP array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If s1 is empty, insert all characters of s2
            elif j == 0:
                dp[i][j] = i  # If s2 is empty, remove all characters of s1
            elif s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # No operation required if characters are same
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # Remove last character of s1
                                   dp[i][j - 1],    # Insert last character of s2
                                   dp[i - 1][j - 1] # Replace last character of s1
                                  )
    return dp[m][n]

