def num_islands(grid):
    """
    Returns the number of distinct islands in the given grid.

    Parameters:
    grid (List[List[str]]): The grid of terrain

    Returns:
    int: The number of distinct islands
    """
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])

    def dfs(i, j):
        if i < 0 or i >= n or j < 0 or j >= m or grid[i][j] != 'L':
            return
        grid[i][j] = 'Visited'
        movements = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for move in movements:
            ni, nj = i + move[0], j + move[1]
            dfs(ni, nj)

    count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'L':
                dfs(i, j)
                count += 1

    return count

def process_transactions(n, transactions):
    order_book = {}

    for transaction in transactions:
        stock = transaction["symbol"]
        if stock not in order_book:
            order_book[stock] = [0, 0]

        if transaction["type"] == "buy":
            order_book[stock][0] += transaction["shares"]
        elif transaction["type"] == "sell":
            order_book[stock][1] += transaction["shares"]

        # Match transactsions if possible
        if order_book[stock][0] > 0 and order_book[stock][1] > 0:
            min_shares = min(order_book[stock][0], order_book[stock][1])
            order_book[stock][0] -= min_shares
            order_book[stock][1] -= min_shares

    return order_book

