def can_become_strictly_increasing(arr):
    """
    Determines if it is possible to delete exactly one element to get a strictly increasing sequence.
    """
    n = len(arr)
    def is_strictly_increasing(sequence):
        for i in range(len(sequence) - 1):
            if sequence[i] >= sequence[i + 1]:
                return False
        return True

    for i in range(n):
        # Create a new sequence by skipping element at index i
        new_sequence = arr[:i] + arr[i+1:]
        if is_strictly_increasing(new_sequence):
            return "YES"
    return "NO"

