def find_extra_character(s, t):
    from collections import Counter

    # Count frequency of characters in both strings
    count_s = Counter(s)
    count_t = Counter(t)

    # Find the character that has an extra count in t
    for char in count_t:
        if count_t[char] != count_s.get(char, 0):
            return char

