from collections import deque, defaultdict

def max_hierarchy_levels(n, relations):
    if n == 1:
        return 1

    adjacency_list = defaultdict(list)
    for manager, subordinate in relations:
        adjacency_list[manager].append(subordinate)
        adjacency_list[subordinate].append(manager)

    def bfs_max_depth(start):
        visited = [False] * (n + 1)
        queue = deque([(start, 1)])  # (node, depth)
        max_depth = 0

        while queue:
            current, depth = queue.popleft()
            visited[current] = True
            max_depth = max(max_depth, depth)

            for neighbor in adjacency_list[current]:
                if not visited[neighbor]:
                    queue.append((neighbor, depth + 1))
                    visited[neighbor] = True

        return max_depth

    return bfs_max_depth(1)

# Example usage:
# n = 5
# relations = [(1, 2), (1, 3), (2, 4), (2, 5)]
