def max_non_overlapping_tasks(t: int, test_cases: list) -> list:
    results = []
    for case in test_cases:
        n, tasks = case
        tasks.sort(key=lambda x: x[1])  # Sort tasks by end time
        count = 0
        last_end_time = 0
        for start, end in tasks:
            if start >= last_end_time:
                count += 1
                last_end_time = end
        results.append(count)
    return results

