from collections import deque, defaultdict

def max_treasures(n, m, treasures, paths):
    graph = defaultdict(list)
    for u, v in paths:
        graph[u].append(v)

    # Initialize the maximum treasures to collect from each room as -1 (unreachable)
    max_treasures = [-1] * (n + 1)
    max_treasures[1] = treasures[0]  # Starting from room 1

    queue = deque([1])

    while queue:
        curr_room = queue.popleft()

        for next_room in graph[curr_room]:
            if max_treasures[next_room] < max_treasures[curr_room] + treasures[next_room - 1]:
                max_treasures[next_room] = max_treasures[curr_room] + treasures[next_room - 1]
                queue.append(next_room)

    return max_treasures[n] if max_treasures[n] != -1 else -1

