from collections import deque

def minimum_moves_to_reach_end(N, M, S, grid):
    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < M

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[[False] * (S + 1) for _ in range(M)] for _ in range(N)]
    queue = deque([(0, 0, 0, 0)])  # x, y, walls destroyed, steps

    while queue:
        x, y, walls_destroyed, steps = queue.popleft()
        if (x, y) == (N - 1, M - 1):
            return steps
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                if grid[nx][ny] == '#' and walls_destroyed < S and not visited[nx][ny][walls_destroyed + 1]:
                    visited[nx][ny][walls_destroyed + 1] = True
                    queue.append((nx, ny, walls_destroyed + 1, steps + 1))
                elif grid[nx][ny] == '.' and not visited[nx][ny][walls_destroyed]:
                    visited[nx][ny][walls_destroyed] = True
                    queue.append((nx, ny, walls_destroyed, steps + 1))
    return -1

