def longest_non_decreasing_subsequence(sequence):
    """
    Returns the length of the longest non-decreasing subsequence in the given sequence.
    """
    n = len(sequence)
    if n == 0:
        return 0

    # Initialize the dp array where each dp[i] will store the length of the longest
    # non-decreasing subsequence ending at index i
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if sequence[i] >= sequence[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

