def generate_triangle_pattern(N):
    result = []
    current_number = 1

    for i in range(1, N + 1):
        if i % 2 == 1:
            # Odd indexed line, increasing sequence
            line = list(range(current_number, current_number + i))
        else:
            # Even indexed line, decreasing sequence
            line = list(range(current_number + i - 1, current_number - 1, -1))

        result.append(line)
        current_number += i

    return result

