from collections import deque

def min_mutations(start, target, mutations):
    if start == target:
        return 0

    mutations = set(mutations)
    queue = deque([(start, 0)])
    visited = set()
    visited.add(start)

    while queue:
        current, steps = queue.popleft()

        if current == target:
            return steps

        for i in range(len(current)):
            for char in 'ACGT':
                if current[i] != char:
                    new_seq = current[:i] + char + current[i+1:]
                    if new_seq in mutations and new_seq not in visited:
                        queue.append((new_seq, steps + 1))
                        visited.add(new_seq)

    return -1

def process_test_cases(test_cases):
    results = []
    for case in test_cases:
        start, target, mutations = case
        result = min_mutations(start, target, mutations)
        results.append(result)
    return results

