def possible_to_color_graph(n, m, edges):
    from collections import defaultdict, deque
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    colors = [0] * (n + 1)

    def bfs(start):
        queue = deque([start])
        colors[start] = 1

        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if colors[neighbor] == 0:
                    colors[neighbor] = 4 - colors[node] if colors[node] != 3 else 1
                    queue.append(neighbor)
                elif colors[neighbor] == colors[node]:
                    return False
        return True

    for node in range(1, n + 1):
        if colors[node] == 0:
            if not bfs(node):
                return "NO"

    return "YES\n" + ' '.join(map(str, colors[1:]))

