def search_matrix(matrix, target):
    if not matrix or not matrix[0]:
        return -1, -1

    rows = len(matrix)
    cols = len(matrix[0])

    # Start from the top-right corner
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        current = matrix[row][col]
        if current == target:
            return row, col
        elif current > target:
            col -= 1  # Move left
        else:
            row += 1  # Move down

    # If the target was not found
    return -1, -1

