from itertools import permutations

def is_valid_arrangement(arrangement, preferences, A):
    n = len(arrangement)
    satisfaction_count = 0

    for g1, g2, sign in preferences:
        g1_index = arrangement.index(g1)
        g2_index = arrangement.index(g2)
        g1_next = arrangement[(g1_index + 1) % n]
        g1_prev = arrangement[(g1_index - 1) % n]

        if sign == '+':
            if g1_next == g2 or g1_prev == g2:
                satisfaction_count += 1
        elif sign == '-':
            if g1_next != g2 and g1_prev != g2:
                satisfaction_count += 1

    return satisfaction_count >= A

def can_seat_guests(num_guests, preferences, acquaintance_threshold):
    guests = list(range(1, num_guests + 1))
    for perm in permutations(guests):
        if is_valid_arrangement(perm, preferences, acquaintance_threshold):
            return True
    return False

def process_input(input_data):
    results = []
    for dataset in input_data:
        N, P, A = dataset[0]
        if N == 0:
            break
        preferences = dataset[1:]
        if can_seat_guests(N, preferences, A):
            results.append("YES")
        else:
            results.append("NO")
    return results

def longest_common_prefix(phrases):
    """
    Returns the longest common prefix from a list of phrases.
    """
    if not phrases:
        return ""

    # Start with the first phrase as the reference
    prefix = phrases[0]

    for phrase in phrases[1:]:
        while not phrase.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""

    return prefix

