def find_minimal_maintenance_cost(N, M, roads):
    parent = list(range(N + 1))
    rank = [0] * (N + 1)

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)

        if root_u != root_v:
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            elif rank[root_u] < rank[root_v]:
                parent[root_u] = root_v
            else:
                parent[root_v] = root_u
                rank[root_u] += 1

    edges = sorted(roads, key=lambda x: x[2])
    mst_cost = 0
    edges_used = 0

    for u, v, w in edges:
        if find(u) != find(v):
            union(u, v)
            mst_cost += w
            edges_used += 1
            if edges_used == N - 1:
                break

    if edges_used == N - 1:
        return mst_cost
    else:
        return -1

