def evaluate_expression(s: str) -> int:
    """
    Evaluate a mathematical expression and return the result as an integer.
    The expression only contains non-negative integers, +, -, *, / operators, and empty spaces.
    The integer division should truncate towards zero.
    """
    s = s.replace(" ", "")  # Remove all spaces
    stack = []
    num = 0
    sign = "+"

    for i in range(len(s)):
        if s[i].isdigit():
            num = num * 10 + int(s[i])

        if s[i] in "+-*/" or i == len(s) - 1:
            if sign == "+":
                stack.append(num)
            elif sign == "-":
                stack.append(-num)
            elif sign == "*":
                stack.append(stack.pop() * num)
            elif sign == "/":
                stack.append(int(stack.pop() / num))

            sign = s[i]
            num = 0

    return sum(stack)

