    l = 0

    for r in range(len(S)):
        s_count[S[r]] += 1

        if S[r] in t_count and s_count[S[r]] == t_count[S[r]]:
            have += 1

        while have == need:
            if (r - l + 1) < res_len:
                res = [l, r]
                res_len = r - l + 1

            s_count[S[l]] -= 1
            if S[l] in t_count and s_count[S[l]] < t_count[S[l]]:
                have -= 1
            l += 1

    l, r = res
    return S[l:r+1] if res_len != float("inf") else ""

