def compress_string(s):
    """
    Compresses the input string `s` by abbreviating repeated characters
    with the character followed by the number of repetitions.
    """
    if not s:
        return ""

    compressed = []
    current_char = s[0]
    count = 1

    for char in s[1:]:
        if char == current_char:
            count += 1
        else:
            compressed.append(f"{current_char}{count}")
            current_char = char
            count = 1
    compressed.append(f"{current_char}{count}")

    return ''.join(compressed)

