def unique_books_with_genres(n, books_genres):
    """
    Transforms the list of books to a list of unique book names sorted alphabetically
    along with their respective genres.
    """
    unique_books = {}

    for book_genre in books_genres:
        book, genre = book_genre.split()
        if book not in unique_books:
            unique_books[book] = genre

    sorted_unique_books = sorted(unique_books.items())

    output = []
    output.append(str(len(sorted_unique_books)))
    for book, genre in sorted_unique_books:
        output.append(f"{book} {genre}")

    return output

def uniquePaths(m, n, grid):
    MOD = 1000000007

    # If the start or end cell is blocked, return 0
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[m-1][n-1]

def longest_palindromic_substring(s):
    """
    Returns the length of the longest palindromic substring in the given string s.
    """
    n = len(s)
    if n == 0:
        return 0

    # Table to store results of subproblems
    dp = [[False] * n for _ in range(n)]

    max_length = 1

    # All substrings of length 1 are palindromic
    for i in range(n):
        dp[i][i] = True

    start = 0

    # Check for sub-strings of length 2
    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
            start = i
            max_length = 2

    # Check for lengths greater than 2
    for k in range(3, n + 1):
        for i in range(n - k + 1):
            j = i + k - 1
            if dp[i + 1][j - 1] and s[i] == s[j]:
                dp[i][j] = True
                if k > max_length:
                    start = i
                    max_length = k

    return max_length

