def caesar_cipher(t, cases):
    results = []
    for case in cases:
        s, k = case
        encrypted = []
        for char in s:
            new_char = chr(((ord(char) - ord('a') + k) % 26) + ord('a'))
            encrypted.append(new_char)
        results.append(''.join(encrypted))
    return results

def parse_input(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    cases = []
    for line in lines[1:]:
        parts = line.rsplit(' ', 1)
        s, k = parts[0], int(parts[1])
        cases.append((s, k))
    return t, cases

def run_caesar_cipher(input_str):
    t, cases = parse_input(input_str)
    results = caesar_cipher(t, cases)
    return '\n'.join(results)

def minimum_total_length(n, m, roads):
    from heapq import heappop, heappush

    if n == 1:
        return 0

    # Create adjacency list
    graph = [[] for _ in range(n + 1)]
    for u, v, l in roads:
        graph[u].append((l, v))
        graph[v].append((l, u))  # since we can travel in both directions in MST

    # Prim's algorithm to find Minimum Spanning Tree (MST)
    min_heap = [(0, 1)]  # (cost, start node)
    total_cost = 0
    visited = [False] * (n + 1)
    edges_used = 0

    while min_heap:
        cost, u = heappop(min_heap)
        if visited[u]:
            continue
        visited[u] = True
        total_cost += cost
        edges_used += 1
        for edge_cost, neighbor in graph[u]:
            if not visited[neighbor]:
                heappush(min_heap, (edge_cost, neighbor))

    # If we were able to visit all nodes, return total_cost; otherwise, return -1
    if edges_used == n:
        return total_cost
    else:
        return -1

