def count_distinct_palindromic_substrings(s):
    """
    Returns the number of distinct palindromic substrings in the given string s.
    """
    def is_palindrome(sub):
        return sub == sub[::-1]

    palindromic_substrings = set()

    for i in range(len(s)):
        for j in range(i, len(s)):
            substring = s[i:j+1]
            if is_palindrome(substring):
                palindromic_substrings.add(substring)

    return len(palindromic_substrings)

