def euler_totient(n):
    """
    Computes Euler's Totient Function φ(n).
    """
    if n == 1:
        return 1

    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1

    if n > 1:
        result -= result // n

    return result

def determine_winner(n, k, piles):
    """
    Determines if Alice can guarantee a win in the game.

    Parameters:
    n (int): Number of piles
    k (int): Maximum number of stones Alice can remove with her special move
    piles (list): List of integers representing the number of stones in each pile

    Returns:
    str: "Alice" if she can guarantee a win, otherwise "Bob"
    """
    xor_sum = 0
    for stones in piles:
        xor_sum ^= stones

    if xor_sum == 0:
        return "Bob"

    for stones in piles:
        if stones <= k:
            if xor_sum ^ stones == 0:
                return "Alice"

    return "Alice"

# Explicit check for special move, maximize move, and piles leveraging xor properties
def alice_wins(n, k, piles):
    xor_sum = 0
    for p in piles:
        xor_sum ^= p

    if xor_sum == 0:
        return "Bob"

    # Check if using the special move on any pile will guarantee Alice a win
    for p in piles:
        if xor_sum ^ p <= k:
            return "Alice"

    return "Alice"

