def does_robot_return(commands):
    """
    Determine if a robot returns to the original starting position after executing a series of commands.

    Parameters:
    commands (List[str]): A list of command strings.

    Returns:
    List[str]: List of "YES" or "NO" for each command string.
    """
    results = []

    for command in commands:
        x, y = 0, 0  # starting position

        for c in command:
            if c == 'U':
                y += 1
            elif c == 'D':
                y -= 1
            elif c == 'L':
                x -= 1
            elif c == 'R':
                x += 1

        if x == 0 and y == 0:
            results.append("YES")
        else:
            results.append("NO")

    return results

