def maximal_rectangle_area(matrix):
    if not matrix:
        return 0

    max_area = 0
    dp = [0] * len(matrix[0])  # DP array to store the height of columns

    for row in matrix:
        for index, value in enumerate(row):
            # Update the dp array to add height or reset the height
            dp[index] = dp[index] + 1 if value == '1' else 0

        # Update max_area with the largest rectangle in the histogram
        max_area = max(max_area, largest_histogram_area(dp))

    return max_area

def largest_histogram_area(heights):
    stack = []
    max_area = 0
    heights.append(0)  # Add a zero height to facilitate calculation
    for i, height in enumerate(heights):
        while stack and heights[stack[-1]] > height:
            h = heights[stack.pop()]
            w = i if not stack else i - stack[-1] - 1
            max_area = max(max_area, h * w)
        stack.append(i)

    heights.pop()  # Remove the zero height
    return max_area

# Convert the input format to a matrix and calculate the maximal rectangle area
def largest_rectangle_of_on_cells(N, M, grid):
    return maximal_rectangle_area(grid)

from typing import List, Tuple, Dict
from collections import defaultdict, deque

def build_tree(edges: List[Tuple[int, int]]) -> Dict[int, List[int]]:
    tree = defaultdict(list)
    for a, b in edges:
        tree[a].append(b)
    return tree

def distinct_paths_to_employee(n: int, edges: List[Tuple[int, int]], target: int) -> int:
    tree = build_tree(edges)

    def dfs(node: int) -> int:
        if node == target:
            return 1
        count = 0
        for child in tree[node]:
            count += dfs(child)
        return count

    return dfs(1)

