import itertools
import math

def minimum_standard_deviation(N, K, A):
    def standard_deviation(arr):
        mean = sum(arr) / len(arr)
        variance = sum((x - mean) ** 2 for x in arr) / len(arr)
        return math.sqrt(variance)

    min_std_dev = standard_deviation(A)

    for length in range(1, N + 1):
        for i in range(N - length + 1):
            subarray = A[i:i + length]
            for _ in range(K + 1):
                subarray_rotated = subarray[-1:] + subarray[:-1]
                new_A = A[:i] + subarray_rotated + A[i + length:]
                min_std_dev = min(min_std_dev, standard_deviation(new_A))
                subarray = subarray_rotated

    return round(min_std_dev, 4)

