def max_circular_subarray_start(n, k, arr):
    if k == 1:
        return arr.index(max(arr))

    max_sum = -float('inf')
    current_sum = sum(arr[:k])
    max_start_index = 0

    for i in range(n):
        if current_sum > max_sum:
            max_sum = current_sum
            max_start_index = i

        current_sum = current_sum - arr[i] + arr[(i + k) % n]

    return max_start_index

