def rotate_matrix_90_clockwise(matrix):
    """
    Rotates the given matrix 90 degrees clockwise.

    :param matrix: List of lists representing the matrix to be rotated
    :return: Rotated matrix
    """
    if not matrix or not matrix[0]:
        return []

    n = len(matrix)
    m = len(matrix[0])

    # Initialize a new matrix to store the rotated result
    rotated_matrix = [[0] * n for _ in range(m)]

    for i in range(n):
        for j in range(m):
            rotated_matrix[j][n - i - 1] = matrix[i][j]

    return rotated_matrix

def matrix_to_string(matrix):
    return '\n'.join(' '.join(map(str, row)) for row in matrix)

import heapq

def dijkstra(graph, start, end):
    n = len(graph)
    min_heap = [(0, start)]
    distances = {node: float('inf') for node in range(n)}
    distances[start] = 0
    visited = set()

    while min_heap:
        current_dist, current_node = heapq.heappop(min_heap)

        if current_node in visited:
            continue

        visited.add(current_node)

        if current_node == end:
            return current_dist

        for neighbor in range(n):
            if graph[current_node][neighbor] != -1 and neighbor not in visited:
                distance = current_dist + graph[current_node][neighbor]

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(min_heap, (distance, neighbor))

    return -1 if distances[end] == float('inf') else distances[end]

def minimum_cost_to_travel(N, adjacency_matrix):
    return dijkstra(adjacency_matrix, 0, N - 1)

