def contains_no_duplicates_within_distance(nums, k):
    """
    Check whether the array contains no duplicate integers within a distance of k.

    :param nums: List[int] - A list of integers.
    :param k: int - The maximum allowed distance between duplicate values.
    :return: bool - True if no duplicates within distance k, False otherwise.
    """
    seen = {}
    for i, num in enumerate(nums):
        if num in seen and i - seen[num] <= k:
            return False
        seen[num] = i
    return True

