def check_valid_sudoku(sudoku):
    """
    Verifies if a given Sudoku solution is valid.

    :param sudoku: A 9x9 grid containing the Sudoku puzzle as a list of lists.
    :return: "Valid" if the Sudoku is valid, "Invalid" otherwise.
    """
    def is_valid_block(block):
        return sorted(block) == list(range(1, 10))

    for row in sudoku:
        if not is_valid_block(row):
            return "Invalid"

    for col in zip(*sudoku):
        if not is_valid_block(col):
            return "Invalid"

    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            block = [sudoku[x][y] for x in range(i, i+3) for y in range(j, j+3)]
            if not is_valid_block(block):
                return "Invalid"

    return "Valid"

