def min_cost_to_transform(A, B):
    """
    Calculates the minimum cost to transform string A into string B.
    """
    m, n = len(A), len(B)

    # Create a (m+1) x (n+1) DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the table
    for i in range(m + 1):
        dp[i][0] = i  # Cost of deleting all characters from A
    for j in range(n + 1):
        dp[0][j] = j  # Cost of inserting all characters of B

    # Fill the table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if A[i - 1] == B[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # Deletion
                                   dp[i][j - 1],    # Insertion
                                   dp[i - 1][j - 1]) # Replacement

    return dp[m][n]

