def min_days_for_sessions(n, d, durations):
    """
    Returns the minimum number of days needed to accommodate all sessions within the given durations.
    """
    days = 0
    current_day_duration = 0

    for duration in durations:
        if current_day_duration + duration > 24:
            days += 1
            current_day_duration = duration
        else:
            current_day_duration += duration

    if current_day_duration > 0:
        days += 1

    return days

