def complete_roundabouts(m, n, grid):
    # Identify pre-placed roundabouts
    rows_with_roundabouts = [False] * m
    cols_with_roundabouts = [False] * n
    rounds_taken = set()

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                rows_with_roundabouts[i] = True
                cols_with_roundabouts[j] = True
                rounds_taken.add((i, j))

    # Fill the remaining roundabouts
    for i in range(m):
        if not rows_with_roundabouts[i]:
            for j in range(n):
                if not cols_with_roundabouts[j]:
                    grid[i][j] = '1'
                    rows_with_roundabouts[i] = True
                    cols_with_roundabouts[j] = True
                    rounds_taken.add((i, j))
                    break

    # Convert the set to list of list for output
    return [''.join(row) for row in grid]

