from collections import Counter

def longest_k_beautiful_string(s, k):
    """
    Returns the length of the longest k-beautiful string that can be achieved.
    """
    if k <= 0 or not s:
        return 0

    counter = Counter(s)
    length = 0

    for char, count in counter.items():
        if count >= k:
            length += (count // k) * k

    return length

