def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest strictly increasing subsequence.
    """
    from bisect import bisect_left

    if not arr:
        return 0

    n = len(arr)
    subseq = []

    for x in arr:
        pos = bisect_left(subseq, x)
        if pos == len(subseq):
            subseq.append(x)
        else:
            subseq[pos] = x

    return len(subseq)

