def compute_execution_times(log_entries):
    """
    Computes the total execution time for each unique operation ID based on log entries.

    Args:
    log_entries: List of tuples containing log data (timestamp, operation_ID, operation_type)

    Returns:
    A dictionary with operation_ID as keys and their total execution time as values
    """
    start_times = {}
    execution_times = {}
    order = []

    for timestamp, operation_id, operation_type in log_entries:
        if operation_type == "START":
            start_times[operation_id] = timestamp
            if operation_id not in execution_times:
                execution_times[operation_id] = 0
                order.append(operation_id)
        elif operation_type == "END":
            if operation_id in start_times:
                execution_times[operation_id] += timestamp - start_times[operation_id]

    result = [(op_id, execution_times[op_id]) for op_id in order]

    return result

def parse_input_and_compute_execution_times(n, lines):
    log_entries = []

    for line in lines:
        parts = line.split()
        timestamp = int(parts[0])
        operation_id = parts[1]
        operation_type = parts[2]
        log_entries.append((timestamp, operation_id, operation_type))

    return compute_execution_times(log_entries)

