def is_balanced_sequence(n, sequence):
    """
    Determines if a given sequence is a balanced sequence.

    Args:
    n : int : the number of elements in the sequence
    sequence : list of int : the elements of the sequence

    Returns:
    str : "YES" if the sequence is a balanced sequence, otherwise "NO"
    """
    if n == 1:
        return "YES"

    freq_map = {}
    group_size = 0
    current_freq_map = {}

    for num in sequence:
        if num not in current_freq_map:
            current_freq_map[num] = 0
        current_freq_map[num] += 1

        if num not in freq_map:
            freq_map[num] = 0
        freq_map[num] += 1

        if group_size == 0:
            group_size = current_freq_map[num]

        for val in current_freq_map.values():
            if val != group_size:
                return "NO"

        if sum(current_freq_map.values()) == group_size * len(current_freq_map):
            group_size = 0
            current_freq_map = {}

    for val in freq_map.values():
        if val % len(freq_map) != 0:
            return "NO"

    return "YES"

