def minimum_badges_required(num_cases, cases):
    results = []
    for case in cases:
        n, scores = case
        if n == 0:
            results.append(0)
            continue

        badges = [1] * n

        # Forward pass
        for i in range(1, n):
            if scores[i] > scores[i - 1]:
                badges[i] = badges[i - 1] + 1

        # Backward pass
        for i in range(n - 2, -1, -1):
            if scores[i] > scores[i + 1]:
                badges[i] = max(badges[i], badges[i + 1] + 1)

        results.append(sum(badges))

    return results

# Reading input and formatting it
def read_input_format(input_text):
    input_lines = input_text.strip().split('\n')
    t = int(input_lines[0])
    cases = []
    index = 1
    for _ in range(t):
        n = int(input_lines[index])
        scores = list(map(int, input_lines[index + 1].split()))
        cases.append((n, scores))
        index += 2
    return t, cases

# Function that will be called with the input
def badges_solver(input_text):
    num_cases, cases = read_input_format(input_text)
    return minimum_badges_required(num_cases, cases)

def subarray_sum(nums, k):
    """
    Returns the total number of continuous subarrays whose sum equals to k.
    """
    count = 0
    current_sum = 0
    prefix_sums = {0: 1}

    for num in nums:
        current_sum += num
        if current_sum - k in prefix_sums:
            count += prefix_sums[current_sum - k]
        if current_sum in prefix_sums:
            prefix_sums[current_sum] += 1
        else:
            prefix_sums[current_sum] = 1

    return count

