def largest_open_square(n, m, grid):
    if n == 0 or m == 0:
        return 0

    dp = [[0] * m for _ in range(n)]
    max_side = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

def longest_palindromic_substring_length(s):
    """
    Returns the length of the longest palindromic substring in the given string s.
    """
    n = len(s)
    if n <= 1:
        return n

    longest = 1
    dp = [[False] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = True

    for length in range(2, n+1):
        for start in range(n-length+1):
            end = start + length - 1
            if s[start] == s[end]:
                if length == 2:
                    dp[start][end] = True
                else:
                    dp[start][end] = dp[start+1][end-1]
                if dp[start][end]:
                    longest = max(longest, length)

    return longest

