def shortest_bead_string(n, s):
    """
    Returns the length of the shortest string Alice can achieve by removing pairs of adjacent beads
    that are of different colors.
    """
    stack = []
    for bead in s:
        if stack and stack[-1] != bead:
            stack.pop()
        else:
            stack.append(bead)
    return len(stack)

