def find_minimum_spanning_tree(n, m, edges):
    # Using Kruskal's algorithm for finding MST
    edges.sort(key=lambda x: x[2])

    parent = list(range(n))

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_u] = root_v

    mst_length = 0
    num_edges = 0

    for u, v, w in edges:
        if find(u-1) != find(v-1):
            union(u-1, v-1)
            mst_length += w
            num_edges += 1
            if num_edges == n - 1:
                break

    return mst_length

