def count_indirect_connections(n, m, roads):
    """
    Count the number of pairs of cities that are indirectly connected through exactly one other city.
    """
    from collections import defaultdict

    # Initialize adjacency list for the graph
    graph = defaultdict(set)
    for u, v in roads:
        graph[u].add(v)
        graph[v].add(u)

    # To keep track of how many valid pairs of cities we have
    indirect_pairs_count = 0

    # Iterate over all possible pairs of cities (i, j)
    for i in range(1, n+1):
        for j in range(i+1, n+1):
            # Cities i and j should not have a direct road between them
            if j not in graph[i]:
                # Check if there exists a city k that connects both i and j indirectly
                for k in range(1, n+1):
                    if k != i and k != j:
                        if k in graph[i] and k in graph[j]:
                            indirect_pairs_count += 1
                            break

    return indirect_pairs_count

