def minimum_bookshelf_width(n, t, m, pairs):
    from collections import defaultdict, deque

    # Create an adjacency list for the graph
    adjacency_list = defaultdict(list)
    for a, b in pairs:
        adjacency_list[a - 1].append(b - 1)
        adjacency_list[b - 1].append(a - 1)

    visited = [False] * n

    def bfs(start):
        queue = deque([start])
        visited[start] = True
        component = []

        while queue:
            node = queue.popleft()
            component.append(node)
            for neighbor in adjacency_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return component

    components = []

    for i in range(n):
        if not visited[i]:
            component = bfs(i)
            components.append(component)

    width = 0
    for component in components:
        sub_width = 0
        edges = 0
        for node in component:
            sub_width += t[node]
            edges += len(adjacency_list[node])

        if edges // 2 != len(component) - 1:
            return -1  # Not a tree, hence not possible to place them as needed

        width += sub_width

    return width

import random

def secret_santa(n, last_years_pairs):
    # Create initial assignments from last year's pairs
    last_year_dict = {a: b for a, b in last_years_pairs}

    # Initialize the current year assignment with -1 to indicate unassigned
    current_year_assignments = [-1] * n

    for i in range(1, n+1):
        # Exclude the current person and the person they gave a gift to last year
        possible_recipients = set(range(1, n+1)) - {i, last_year_dict[i]}
        if not possible_recipients:
            return "Impossible"

        # Randomly assign a possible recipient
        chosen = random.choice(list(possible_recipients))
        current_year_assignments[i-1] = chosen
        # Remove the recipient from all other possible lists to maintain balance
        for j in range(1, n+1):
            if chosen in possible_recipients:
                possible_recipients.remove(chosen)

    # Transform the result to the desired output format
    result = []
    for i in range(n):
        result.append((i+1, current_year_assignments[i]))

    return result

