def generate_planting_plan(n, m, k):
    if k == 1 and (n > 1 or m > 1):
        return ["NO"]

    plan = [[0] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            plan[i][j] = ((i + j) % k) + 1

    return ["YES"] + [' '.join(map(str, row)) for row in plan]

