def manage_employees(n, employee_details, q, queries):
    """
    Returns a list of strings where each string contains alphabetically sorted
    employee IDs for a respective query of department names.
    """
    # Dictionary to hold department to employees mapping
    department_dict = {}

    # Populate the dictionary with employee details
    for emp_id, dept in employee_details:
        if dept not in department_dict:
            department_dict[dept] = []
        department_dict[dept].append(emp_id)

    # List to store results for each query
    result = []

    # Process each query
    for dept in queries:
        if dept in department_dict:
            result.append(" ".join(sorted(department_dict[dept])))
        else:
            result.append("")

    return result

