def process_operations(n, operations):
    # Initialize all cells as unlocked
    cells = [False] * n  # False means unlocked, True means locked
    result = []

    for operation in operations:
        if operation[0] == 1:
            cell, action = operation[1] - 1, operation[2]
            if action == "lock":
                cells[cell] = True
            else:
                cells[cell] = False
        elif operation[0] == 2:
            start, end = operation[1] - 1, operation[2] - 1
            if all(cells[start:end + 1]):
                result.append("Yes")
            else:
                result.append("No")

    return result

def longest_palindrome_length(s):
    from collections import Counter

    count = Counter(s)
    length = 0
    odd_found = False

    for char_count in count.values():
        if char_count % 2 == 0:
            length += char_count
        else:
            length += char_count - 1
            odd_found = True

    if odd_found:
        length += 1

    return length

