def organize_sequence(n, integers):
    """
    Determine if it's possible to arrange the integers such that no two consecutive
    integers have the same parity. If possible, output "Yes" followed by a valid sequence.
    If not, output "No".
    """
    odds = [num for num in integers if num % 2 != 0]
    evens = [num for num in integers if num % 2 == 0]

    if abs(len(odds) - len(evens)) > 1:
        return "No"

    sequence = []
    if len(odds) > len(evens):
        for i in range(len(evens)):
            sequence.append(odds[i])
            sequence.append(evens[i])
        sequence.append(odds[-1])
    else:
        for i in range(len(odds)):
            sequence.append(evens[i])
            sequence.append(odds[i])
        if len(evens) > len(odds):
            sequence.append(evens[-1])

    return "Yes", sequence

def process_commands(input_data):
    index = 0
    results = []

    while index < len(input_data):
        n = int(input_data[index])  # Number of commands in the current dataset
        if n == 0:
            break

        current_position = [0, 0]

        for i in range(1, n + 1):
            command = input_data[index + i]
            if command.startswith('MOVE'):
                _, x, y = command.split()
                x, y = int(x), int(y)
                current_position[0] += x
                current_position[1] += y
            elif command == 'RESET':
                current_position = [0, 0]

        results.append(f"({current_position[0]}, {current_position[1]})")
        index += n + 1

    return results

