        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, current_sum + values[neighbor - 1]):
                    return True
        visited[node] = False
        return False

    results = []

    # Process each query independently
    for query in queries:
        n, m, s = query['n'], query['m'], query['s']
        values = query['values']
        edges = query['edges']

        # Building the graph
        graph = [[] for _ in range(n + 1)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        # Start DFS from each node
        path_exists = False
        for start_node in range(1, n + 1):
            visited = [False] * (n + 1)
            if dfs(start_node, values[start_node - 1]):
                path_exists = True
                break

        results.append("YES" if path_exists else "NO")

    return results

