def majority_element(nums):
    """
    Returns the majority element of the list if it exists, otherwise returns -1.
    """
    n = len(nums)
    candidate = None
    count = 0

    # Phase 1: Find a candidate using Boyer-Moore Voting Algorithm
    for num in nums:
        if count == 0:
            candidate = num
            count = 1
        elif num == candidate:
            count += 1
        else:
            count -= 1

    # Phase 2: Verify the candidate
    if nums.count(candidate) > n // 2:
        return candidate
    else:
        return -1

