def min_path_cost(grid):
    n = len(grid)
    m = len(grid[0])

    # Initialize a DP table
    dp = [[float('inf')] * m for _ in range(n)]
    dp[0][0] = grid[0][0]

    for i in range(n):
        for j in range(m):
            if i > 0:
                dp[i][j] = min(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = min(dp[i][j], dp[i][j-1] + grid[i][j])

    return dp[n-1][m-1]

def min_path_cost_from_input(grid_input):
    grid_input = grid_input.strip().split('\n')
    n, m = map(int, grid_input[0].split())
    grid = [[int(x) for x in line.split()] for line in grid_input[1:]]
    return min_path_cost(grid)

