def max_trees_to_cut(heights):
    """
    Determines the maximum number of trees that can be cut down such
    that the remaining tree heights form a non-decreasing sequence.
    """
    n = len(heights)

    # If only one tree or already sorted, no need to cut any tree
    if n <= 1 or all(heights[i] <= heights[i+1] for i in range(n-1)):
        return 0

    # LIS
    lis = []
    for h in heights:
        pos = binary_search(lis, h)
        if pos < len(lis):
            lis[pos] = h
        else:
            lis.append(h)

    # Minimum cuts needed to form non-decreasing sequence
    return n - len(lis)

def binary_search(lis, h):
    left, right = 0, len(lis) - 1
    while left <= right:
        mid = (left + right) // 2
        if lis[mid] < h:
            left = mid + 1
        else:
            right = mid - 1
    return left

