def can_be_non_decreasing_by_one_swap(n, arr):
    if n == 1:
        return "YES"

    def is_sorted(arr):
        return all(arr[i] <= arr[i + 1] for i in range(n - 1))

    if is_sorted(arr):
        return "YES"

    for i in range(n):
        for j in range(i + 1, n):
            arr[i], arr[j] = arr[j], arr[i]
            if is_sorted(arr):
                return "YES"
            arr[i], arr[j] = arr[j], arr[i]

    return "NO"

