def is_prime(num):
    """Checks if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def has_prime_sum_pair(a):
    """
    Determines if there exists a pair of indices (i, j) such that the sum of a[i] and a[j] is a prime number.
    """
    n = len(a)
    for i in range(n):
        for j in range(i + 1, n):
            if is_prime(a[i] + a[j]):
                return "YES"
    return "NO"

