import heapq
from collections import Counter

def rearrange_string(s, k):
    if k == 1:  # If k is 1, any arrangement is fine
        return s

    counter = Counter(s)
    max_heap = [(-count, char) for char, count in counter.items()]
    heapq.heapify(max_heap)

    queue = []
    result = []

    while max_heap:
        count, char = heapq.heappop(max_heap)
        result.append(char)
        queue.append((count + 1, char))  # Decrement the count

        if len(queue) >= k:
            count, char = queue.pop(0)
            if count < 0:
                heapq.heappush(max_heap, (count, char))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return "Not possible"

