from collections import deque, defaultdict

def can_place_nodes_on_line(n, m, edges):
    # Create an adjacency list and in-degree count.
    graph = defaultdict(list)
    in_degree = {i: 0 for i in range(n)}
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Queue for nodes with in-degree 0.
    queue = deque()
    for node in in_degree:
        if in_degree[node] == 0:
            queue.append(node)

    topological_order = []

    while queue:
        node = queue.popleft()
        topological_order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topological_order) == n:
        return "YES", topological_order
    else:
        return "NO", []

# Helper function to parse input and structure the response properly
def solve(n, m, edges):
    result, order = can_place_nodes_on_line(n, m, edges)
    if result == "NO":
        return "NO"
    else:
        return "YES\n" + " ".join(map(str, order))

