def sum_of_palindromic_substring_lengths(n, S):
    """
    Return the sum of the lengths of all distinct palindromic substrings of S.
    """
    def is_palindrome(s):
        return s == s[::-1]

    palindromic_substrings = set()

    for i in range(n):
        for j in range(i, n):
            substring = S[i:j+1]
            if is_palindrome(substring):
                palindromic_substrings.add(substring)

    return sum(len(p) for p in palindromic_substrings)

