def largest_square_submatrix_area(matrix):
    n = len(matrix)
    if n == 0:
        return 0

    max_side = 0
    dp = [[0]*n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if i == 0 or j == 0:
                dp[i][j] = matrix[i][j]
            elif matrix[i][j] == 1:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
            else:
                dp[i][j] = 0
            max_side = max(max_side, dp[i][j])

    return max_side * max_side

