        'fr': ["et", "le", "de", "la", "les", "des", "une", "que", "en", "pour"],
        'de': ["und", "die", "der", "das", "ist", "in", "zu", "den", "von", "mit"]
    }
    return stopwords

def preprocess(text):
    text = text.lower()
    text = text.translate(str.maketrans("", "", string.punctuation))
    return text.split()

def guess_language(article):
    stopwords = load_stopwords()

    # Split the article into lines
    lines = article.strip().split("\n")
    # Combine title and body into a single text
    content = " ".join(lines[1:])
    words = preprocess(content)

    word_counts = Counter(words)
    language_scores = {lang: 0 for lang in stopwords}

    for lang, stopword_list in stopwords.items():
        for stopword in stopword_list:
            language_scores[lang] += word_counts[stopword]

    return max(language_scores, key=language_scores.get)

