from typing import List

def generate_parentheses(N: int) -> List[str]:
    def backtrack(s, left, right):
        if len(s) == 2 * N:
            result.append(s)
            return
        if left < N:
            backtrack(s + '(', left + 1, right)
        if right < left:
            backtrack(s + ')', left, right + 1)

    result = []
    backtrack('', 0, 0)
    return result

def longest_palindromic_substring(s):
    """
    Returns the longest palindromic substring of the input string s.
    """
    if not s:
        return ""

    n = len(s)
    start, max_len = 0, 1

    def expand_center(left, right):
        while left >= 0 and right < n and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    for i in range(n):
        l1, r1 = expand_center(i, i)       # Odd length palindrome
        l2, r2 = expand_center(i, i + 1)   # Even length palindrome

        if r1 - l1 + 1 > max_len:
            start, max_len = l1, r1 - l1 + 1
        if r2 - l2 + 1 > max_len:
            start, max_len = l2, r2 - l2 + 1

    return s[start:start + max_len]

