def is_cyclic(n, edges):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    indegree = [0] * (n + 1)

    for u, v in edges:
        graph[u].append(v)
        indegree[v] += 1

    queue = deque([i for i in range(1, n + 1) if indegree[i] == 0])
    count = 0

    while queue:
        node = queue.popleft()
        count += 1
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    return count != n

def contains_cycle(n, m, edge_list):
    if is_cyclic(n, edge_list):
        return "YES"
    else:
        return "NO"

