from collections import deque

def virus_spread_time(m, n, grid):
    # Directions for neighboring cells (left, right, upward, downward)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque()
    minutes = 0
    healthy_cells = 0

    # Initialize the queue with all infected cells and count healthy cells
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                queue.append((i, j, 0))  # (x, y, time)
            elif grid[i][j] == 1:
                healthy_cells += 1

    # Perform BFS to spread the virus
    while queue:
        x, y, time = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (0 <= nx < m) and (0 <= ny < n) and (grid[nx][ny] == 1):
                grid[nx][ny] = 2  # Mark the cell as infected
                queue.append((nx, ny, time + 1))
                healthy_cells -= 1
                minutes = max(minutes, time + 1)

    # If there are healthy cells remaining, return -1
    if healthy_cells > 0:
        return -1

    return minutes

def handle_multiple_test_cases(t, test_cases):
    results = []
    for test_case in test_cases:
        m, n, grid = test_case
        result = virus_spread_time(m, n, grid)
        results.append(result)
    return results

