import math
from collections import defaultdict

def calculate_distance(bird1, bird2):
    return math.sqrt((bird1[0] - bird2[0])**2 + (bird1[1] - bird2[1])**2)

def find_clusters(n, d, coords):
    def dfs(bird_index, visited, cluster):
        visited[bird_index] = True
        cluster.append(bird_index)
        for neighbor in adjacency_list[bird_index]:
            if not visited[neighbor]:
                dfs(neighbor, visited, cluster)

    # Create an adjacency list
    adjacency_list = defaultdict(list)
    for i in range(n):
        for j in range(i + 1, n):
            if calculate_distance(coords[i], coords[j]) <= d:
                adjacency_list[i].append(j)
                adjacency_list[j].append(i)

    visited = [False] * n
    clusters = []

    for i in range(n):
        if not visited[i]:
            cluster = []
            dfs(i, visited, cluster)
            clusters.append(cluster)

    cluster_sizes = sorted([len(cluster) for cluster in clusters])
    return len(clusters), cluster_sizes

def min_operations(s, t):
    n, m = len(s), len(t)
    # dp[i][j] will hold the minimum edit distance between s[0..i-1] and t[0..j-1]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize dp array
    for i in range(n + 1):
        for j in range(m + 1):
            if i == 0:
                dp[i][j] = j    # If s is empty, we need to insert all characters of t
            elif j == 0:
                dp[i][j] = i    # If t is empty, we need to delete all characters of s
            elif s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]    # If last characters are equal, ignore last char
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],      # Delete
                                   dp[i][j - 1],      # Insert
                                   dp[i - 1][j - 1])  # Replace

    return dp[n][m]

