def search_rotated_array(nums, target):
    """
    Searches for a target in a rotated sorted array and returns its index.
    If the target is not found, returns -1.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

from typing import List
import bisect

def longest_increasing_subsequence(arr: List[int]) -> int:
    """
    Returns the length of the longest subsequence with strictly increasing order.
    """
    if not arr:
        return 0

    sub = []
    for num in arr:
        pos = bisect.bisect_left(sub, num)
        if pos == len(sub):
            sub.append(num)
        else:
            sub[pos] = num
