import math

def max_euclidean_distance(grid):
    """
    Given a grid with some cells containing gold, find the maximum Euclidean distance
    between any two cells containing gold.
    """
    gold_positions = []

    # Collect positions of all gold cells
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 'G':
                gold_positions.append((r, c))

    # Initialize max distance
    max_distance = 0

    # Calculate the Euclidean distance between every pair of gold cells
    for i in range(len(gold_positions)):
        for j in range(i + 1, len(gold_positions)):
            r1, c1 = gold_positions[i]
            r2, c2 = gold_positions[j]
            distance = math.sqrt((r2 - r1)**2 + (c2 - c1)**2)
            max_distance = max(max_distance, distance)

    # Return the maximum distance found
    return round(max_distance, 6)

