from heapq import heappop, heappush

def min_cost_to_reach_end(grid):
    m, n = len(grid), len(grid[0])
    if grid[0][0] == '#' or grid[m-1][n-1] == '#':
        return -1

    # Directions for moving in the grid
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Priority queue for Dijkstra's algorithm
    pq = [(0, 0, 0)]  # (cost, x, y)

    # Cost matrix initialized to infinity
    cost = [[float('inf')] * n for _ in range(m)]
    cost[0][0] = 0

    while pq:
        curr_cost, x, y = heappop(pq)

        if (x, y) == (m-1, n-1):
            return curr_cost

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != '#':
                next_cost = curr_cost + (2 if grid[nx][ny] == '*' else 1)
                if next_cost < cost[nx][ny]:
                    cost[nx][ny] = next_cost
                    heappush(pq, (next_cost, nx, ny))

    return -1

def solve(m, n, grid):
    grid = [list(row) for row in grid]
    return min_cost_to_reach_end(grid)

