def analyze_dns_logs(n, logs):
    unique_domains = set()
    queries_with_response = set()

    for log in logs:
        timestamp, message_type, domain = log.split()
        if message_type == "query":
            unique_domains.add(domain)
        elif message_type == "response":
            queries_with_response.add(domain)

    responded_queries_count = len(queries_with_response.intersection(unique_domains))
    return len(unique_domains), responded_queries_count

def interesting_substrings(s):
    """
    Given a string s, computes the number of interesting substrings.
    An interesting substring is one where no two consecutive characters are the same.
    """
    n = len(s)
    count = 0
    for start in range(n):
        for end in range(start, n):
            interesting = True
            for i in range(start, end):
                if s[i] == s[i + 1]:
                    interesting = False
                    break
            if interesting:
                count += 1
    return count

