def is_village_connected_after_reducing(n, m, roads):
    from itertools import combinations

    def is_connected(graph, excluded_road=None):
        from collections import deque

        visited = [False] * n
        adj_list = [[] for _ in range(n)]

        for u, v in graph:
            if excluded_road and sorted([u, v]) == sorted(excluded_road):
                continue
            adj_list[u-1].append(v-1)
            adj_list[v-1].append(u-1)

        def bfs(start):
            queue = deque([start])
            while queue:
                node = queue.popleft()
                if not visited[node]:
                    visited[node] = True
                    for neighbor in adj_list[node]:
                        if not visited[neighbor]:
                            queue.append(neighbor)

        bfs(0)  # starting from the first house
        return all(visited)

    for road in roads:
        if not is_connected(roads, excluded_road=road):
            return "No"

    return "Yes"

