def longest_unique_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    longest_length = 0
    start_idx = 0

    for i, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start_idx:
            start_idx = char_index_map[char] + 1
        else:
            longest_length = max(longest_length, i - start_idx + 1)

        char_index_map[char] = i

    return longest_length

