import heapq

def shortest_path_length(m, n, s, t, streets):
    graph = {i: [] for i in range(1, m + 1)}
    for a, b, l in streets:
        graph[a].append((b, l))

    distances = {i: float('inf') for i in range(1, m + 1)}
    distances[s] = 0
    priority_queue = [(0, s)]
    heapq.heapify(priority_queue)

    while priority_queue:
        current_dist, current_node = heapq.heappop(priority_queue)

        if current_node == t:
            return current_dist

        if current_dist > distances[current_node]:
            continue

        for neighbor, length in graph[current_node]:
            distance = current_dist + length
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return -1

def magic_sequence(n):
    if n == 1:
        return [1]

    if n == 2:
        return "IMPOSSIBLE"

    result = []

    for i in range(1, n+1):
        result.append(i)

    # Swap adjacent elements
    for i in range(0, n-1, 2):
        result[i], result[i+1] = result[i+1], result[i]

    return result

