def isPathSum(grid, n, m, k):
    """
    Function to determine if there exists a path from the top-left corner of the grid to
    the bottom-right corner such that the path sum is exactly k.
    """
    # Use Depth First Search with memoization to store the result of subproblems
    from functools import lru_cache

    @lru_cache(None)
    def dfs(row, col, current_sum):
        # Base case: If we reached the bottom-right corner
        if row == n - 1 and col == m - 1:
            return current_sum == k

        # Move right or down
        paths = []
        if row + 1 < n:
            paths.append(dfs(row + 1, col, current_sum + grid[row + 1][col]))
        if col + 1 < m:
            paths.append(dfs(row, col + 1, current_sum + grid[row][col + 1]))

        return any(paths)

    return "possible" if dfs(0, 0, grid[0][0]) else "impossible"

