def find_F_value(n, values, edges):
    from collections import defaultdict, deque

    # Create an adjacency list for the tree
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    root = 1
    value = {i + 1: values[i] for i in range(n)}
    children = defaultdict(list)

    # To identify the children we will do a BFS or DFS traversal and set the children correctly
    parent = {root: None}
    q = deque([root])

    while q:
        node = q.popleft()
        for neighbor in tree[node]:
            if neighbor != parent[node]:
                parent[neighbor] = node
                children[node].append(neighbor)
                q.append(neighbor)

    # To compute the F(i) values, we use a post-order traversal
    def dfs(node):
        sum_f = 0
        for child in children[node]:
            sum_f += dfs(child) + value[child]
        return sum_f

    return dfs(root)

