def find_non_decreasing_subarray(n, k, q, arr, queries):
    def is_valid_subarray(start, k, low, high):
        for i in range(start, start + k):
            if arr[i] < low or arr[i] > high:
                return False
        return True

    results = []

    for low, high in queries:
        found = False
        for i in range(n - k + 1):
            if all(arr[j] <= arr[j + 1] for j in range(i, i + k - 1)):
                if is_valid_subarray(i, k, low, high):
                    results.append(i + 1)
                    found = True
                    break
        if not found:
            results.append(-1)

    return results

