def find_first_peak(arr):
    """
    Returns the index of the first peak element in the array.
    """
    n = len(arr)
    if n == 1:
        return 0

    for i in range(n):
        # For the first element
        if i == 0:
            if arr[i] >= arr[i + 1]:
                return i

        # For the last element
        elif i == n - 1:
            if arr[i] >= arr[i - 1]:
                return i

        # For the elements in between
        else:
            if arr[i] >= arr[i - 1] and arr[i] >= arr[i + 1]:
                return i

