def min_operations_to_transform(s1, s2):
    """
    Returns the minimum number of operations required to transform s1 into s2.
    Allowed operations: insert, delete, replace a character.
    """
    m, n = len(s1), len(s2)

    # Create a DP table to store results of subproblems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the DP table
    for i in range(m + 1):
        for j in range(n + 1):

            if i == 0:
                dp[i][j] = j    # If s1 is empty, insert all characters of s2

            elif j == 0:
                dp[i][j] = i    # If s2 is empty, remove all characters of s1

            elif s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]  # If characters of the strings match, no operation is needed

            else:
                dp[i][j] = 1 + min(dp[i][j-1],    # Insert
                                   dp[i-1][j],    # Remove
                                   dp[i-1][j-1])  # Replace

    return dp[m][n]

