def longest_subsequence_for_powerful_reaction(n, sequence):
    """
    Returns the length of the longest sub-sequence that is either strictly increasing or strictly decreasing.
    """
    if n == 0:
        return 0

    # Longest Increasing Subsequence (LIS) Dynamic Programming Array
    lis = [1] * n

    # Longest Decreasing Subsequence (LDS) Dynamic Programming Array
    lds = [1] * n

    # Compute LIS values
    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Compute LDS values
    for i in range(1, n):
        for j in range(i):
            if sequence[i] < sequence[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1

    # The result is the maximum value between all LIS and LDS
    return max(max(lis), max(lds))

