def first_unique_char(s):
    """
    Returns the first non-repeating character in the string s.
    If every character repeats, returns an underscore (_).
    """
    char_count = {}

    # Count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character that has only one occurrence
    for char in s:
        if char_count[char] == 1:
            return char

    return '_'

