def longest_arith_seq_length(n, arr):
    if n == 1:
        return 1

    dp = [{} for _ in range(n)]
    max_len = 2

    for i in range(1, n):
        for j in range(i):
            d = arr[i] - arr[j]
            if d in dp[j]:
                dp[i][d] = dp[j][d] + 1
            else:
                dp[i][d] = 2
            max_len = max(max_len, dp[i][d])

    return max_len

