def find_groups_of_friends(n, m, edges):
    from collections import defaultdict, deque

    def bfs(node, adj_list, visited):
        queue = deque([node])
        visited[node] = True
        while queue:
            u = queue.popleft()
            for v in adj_list[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

    # Initialize adjacency list and visited list
    adj_list = defaultdict(list)
    visited = [False] * (n + 1)

    # Populate adjacency list
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Count distinct groups via BFS
    num_groups = 0
    for node in range(1, n + 1):
        if not visited[node]:
            bfs(node, adj_list, visited)
            num_groups += 1

    return num_groups

