def min_sensors(n, m, hallways):
    from collections import defaultdict

    if n == 1:
        return 1

    graph = defaultdict(list)

    for u, v in hallways:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)

    def dfs(node):
        stack = [node]
        components = []
        while stack:
            n = stack.pop()
            if not visited[n]:
                visited[n] = True
                components.append(n)
                for neigh in graph[n]:
                    if not visited[neigh]:
                        stack.append(neigh)
        return components

    components = []
    for room in range(1, n + 1):
        if not visited[room]:
            components.append(dfs(room))

    result = 0
    for component in components:
        result += 1

    return result

