from math import gcd
from functools import reduce

def can_all_trees_reach_height(t, test_cases):
    def possible_to_reach_height(n, H, heights):
        common_gcd = reduce(gcd, heights)
        max_height = max(heights)
        return max_height >= H and max_height % common_gcd == H % common_gcd

    results = []
    for i in range(t):
        n, H = test_cases[i][0]
        heights = test_cases[i][1]
        if possible_to_reach_height(n, H, heights):
            results.append("YES")
        else:
            results.append("NO")
    return results

