import heapq

def shortest_path(n, m, edges):
    def dijkstra(graph, start):
        distances = {node: float('inf') for node in range(1, n + 1)}
        distances[start] = 0
        priorityQueue = [(0, start)]
        parents = {start: None}

        while priorityQueue:
            current_distance, current_node = heapq.heappop(priorityQueue)

            if current_distance > distances[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    parents[neighbor] = current_node
                    heapq.heappush(priorityQueue, (distance, neighbor))

        return distances, parents

    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    distances, parents = dijkstra(graph, 1)

    if distances[n] == float('inf'):
        return -1, []

    # Reconstruct path
    path = []
    node = n
    while node is not None:
        path.append(node)
        node = parents[node]
    path.reverse()

    return distances[n], path

