def count_pairs_with_sum(n, k, arr):
    """
    Returns the number of distinct pairs (i, j) (1 ≤ i < j ≤ n) such that the sum of elements
    at these positions is equal to k.
    """
    count = 0
    seen = {}

    for i in range(n):
        complement = k - arr[i]
        if complement in seen:
            count += seen[complement]

        if arr[i] in seen:
            seen[arr[i]] += 1
        else:
            seen[arr[i]] = 1

    return count

