def find_pair_with_sum(n, arr, target):
    """
    Returns the first pair of indices (1-based) such that the sum of elements at these indices equals the target value.
    If no such pair exists, returns -1.
    """
    value_to_index = {}
    for i in range(n):
        complement = target - arr[i]
        if complement in value_to_index:
            return (value_to_index[complement] + 1, i + 1)
        value_to_index[arr[i]] = i
    return -1

