from itertools import combinations

def count_unique_necklaces(n, k, gemstones):
    # Get unique gemstones
    unique_gemstones = list(set(gemstones))

    # If there are less unique gemstones than k, return 0
    if len(unique_gemstones) < k:
        return 0

    # Count the number of ways to choose k unique gemstones
    return len(list(combinations(unique_gemstones, k)))

