def longest_consecutive_sequence(n, s):
    if n == 1:
        return 1  # Only one character means max sequence is 1

    def max_consecutive_length(s):
        max_len = curr_len = 1
        for i in range(1, len(s)):
            if s[i] == s[i - 1]:
                curr_len += 1
            else:
                max_len = max(max_len, curr_len)
                curr_len = 1
        return max(max_len, curr_len)

    # Check original sequence's max consecutive length
    original_max = max_consecutive_length(s)

    # Check by flipping each character
    flipped_max = original_max
    for i in range(n):
        # Flip character at position i
        if s[i] == 'A':
            flipped_seq = s[:i] + 'B' + s[i+1:]
        else:
            flipped_seq = s[:i] + 'A' + s[i+1:]

        # Check max consecutive length with the flipped character
        flipped_max = max(flipped_max, max_consecutive_length(flipped_seq))

    return flipped_max

