def wiggle_sort(nums):
    """
    Rearrange the array such that nums[1] > nums[0] < nums[2] > nums[3] < nums[4] > nums[5]...
    :param nums: List[int]
    :return: List[int]
    """
    for i in range(len(nums)):
        if (i % 2 == 1 and nums[i] < nums[i - 1]) or (i % 2 == 0 and i > 0 and nums[i] > nums[i - 1]):
            nums[i], nums[i - 1] = nums[i - 1], nums[i]
    return nums

