def min_flips(binary_string):
    """
    Returns the minimum number of flips needed to turn every segment of consecutive '1's into '0's.
    """
    one_segments = 0
    in_segment = False

    for char in binary_string:
        if char == '1':
            if not in_segment:
                one_segments += 1
                in_segment = True
        else:
            in_segment = False

    return one_segments

