def find(parent, i):
    if parent[i] == i:
        return i
    else:
        return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def minimum_cost_to_connect_houses(n, m, roads):
    if n == 1:
        return 0

    roads.sort(key=lambda x: x[2])

    parent = []
    rank = []

    for node in range(n):
        parent.append(node)
        rank.append(0)

    result = 0
    e = 0
    i = 0

    while e < n - 1 and i < m:
        u, v, w = roads[i]
        i = i + 1
        x = find(parent, u - 1)
        y = find(parent, v - 1)

        if x != y:
            e = e + 1
            result = result + w
            union(parent, rank, x, y)

    if e != n - 1:
        return -1

    return result

def max_file_depth(directory):
    def dfs(subdir, depth):
        max_depth = depth
        for item in subdir:
            if isinstance(item, list):
                max_depth = max(max_depth, dfs(item, depth + 1))
            else:
                max_depth = max(max_depth, depth + 1)
        return max_depth

    return dfs(directory, 0)

