from collections import defaultdict

def settle_expenses(transactions):
    balance = defaultdict(float)

    for payer, amount, recipient in transactions:
        balance[payer] -= amount
        balance[recipient] += amount

    debts = list(balance.values())
    return settle(debts, 0)

def settle(debts, index):
    while index < len(debts) and abs(debts[index]) < 1e-9:
        index += 1

    if index == len(debts):
        return 0

    min_trans = float('inf')

    for i in range(index + 1, len(debts)):
        if debts[i] * debts[index] < 0:
            debts[i] += debts[index]
            min_trans = min(min_trans, 1 + settle(debts, index + 1))
            debts[i] -= debts[index]

    return min_trans

def longest_subarray_with_k_distinct(n, k, arr):
    from collections import defaultdict

    if k == 0 or n == 0:
        return 0

    max_len = 0
    left = 0
    distinct_count = 0
    freq = defaultdict(int)

    for right in range(n):
        if freq[arr[right]] == 0:
            distinct_count += 1
        freq[arr[right]] += 1

        # Shrink the window from the left if the number of distinct integers > k
        while distinct_count > k:
            freq[arr[left]] -= 1
            if freq[arr[left]] == 0:
                distinct_count -= 1
            left += 1

        # Update the maximum length if the number of distinct integers equals k
        if distinct_count == k:
            max_len = max(max_len, right - left + 1)

    return max_len

