def count_k_palindromic_substrings(s):
    n = len(s)
    result = [0] * n

    # Process for each length from 1 to n
    for k in range(1, n + 1):
        count = 0
        for i in range(n - k + 1):
            substr = s[i:i + k]
            if substr == substr[::-1]:
                count += 1
        result[k - 1] = count

    return result

def process_test_cases(test_cases):
    results = []
    for s in test_cases:
        results.append(count_k_palindromic_substrings(s))
    return results

def number_of_connected_components(n, m, edges):
    from collections import defaultdict, deque

    # Create an adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Function to perform BFS and mark visited nodes
    def bfs(node):
        queue = deque([node])
        visited[node] = True
        while queue:
            current = queue.popleft()
            for neighbor in adj_list[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    visited = [False] * (n + 1)
    connected_components = 0

    for i in range(1, n + 1):
        if not visited[i]:
            bfs(i)
            connected_components += 1

    return connected_components

