def max_adjacent_buildings(arr, k):
    """
    Returns the maximum number of adjacent buildings with a height difference of at most k.
    """
    max_count = 1
    current_count = 1

    for i in range(1, len(arr)):
        if abs(arr[i] - arr[i - 1]) <= k:
            current_count += 1
        else:
            current_count = 1

        max_count = max(max_count, current_count)

    return max_count

def max_subarray_sum(arr):
    """
    Returns the maximum sum of a contiguous subarray in an array of integers.
    """
    if not arr:
        return 0

    max_current = max_global = arr[0]

    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

