def does_robot_return(commands):
    """
    Determines if the robot returns to the origin after executing all commands.

    Parameters:
    commands (str): The string consisting of commands 'U', 'D', 'L', 'R'.

    Returns:
    str: "YES" if the robot returns to the origin, "NO" otherwise.
    """
    x, y = 0, 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return "YES" if x == 0 and y == 0 else "NO"

