def find_pair_sum_k(arr, k):
    """
    Returns "YES" if there exists a pair of elements in the array whose sum equals k, otherwise "NO".
    """
    seen_numbers = set()
    for number in arr:
        if k - number in seen_numbers:
            return "YES"
        seen_numbers.add(number)
    return "NO"

