def find_safe_path(n, m, grid):
    from collections import deque

    # Define directions: right and down
    directions = [(0, 1), (1, 0)]

    # BFS Queue with initial point (0,0), initial score 0, and the path
    queue = deque([(0, 0, 0, [(1, 1)])])
    visited = set([(0, 0)])

    while queue:
        x, y, score, path = queue.popleft()

        # Check if we reached the bottom-right corner
        if x == n - 1 and y == m - 1:
            return "YES", path

        # Explore neighbours
        for dx, dy in directions:
            new_x, new_y = x + dx, y + dy

            # Check boundaries
            if 0 <= new_x < n and 0 <= new_y < m:
                new_score = score + grid[new_x][new_y]

                # Ensure the score never goes negative
                if new_score >= 0 and (new_x, new_y) not in visited:
                    visited.add((new_x, new_y))
                    new_path = path + [(new_x + 1, new_y + 1)]  # adjust path to 1-indexed
                    queue.append((new_x, new_y, new_score, new_path))

    return "NO", []

def treasure_hunt(n, m, grid):
    result, path = find_safe_path(n, m, grid)
    if result == "YES":
        return f"YES\n" + " -> ".join(map(str, path))
    else:
        return "NO"

