import heapq

def dijkstra(graph, start, n):
    """ Returns the shortest distance from start to all other nodes using Dijkstra's algorithm """
    distances = [float('inf')] * (n + 1)
    distances[start] = 0
    priority_queue = [(0, start)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        # If current distance is greater than the stored one, skip it
        if current_distance > distances[current_node]:
            continue

        # Explore neighbors
        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            # Only consider this new path if it's better
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def find_shortest_paths(n, edges, queries):
    # Create adjacency list for the graph
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))

    results = []
    for s, t in queries:
        distances = dijkstra(graph, s, n)
        if distances[t] == float('inf'):
            results.append("Unreachable")
        else:
            results.append(distances[t])

    return results

