def simulateFileSystem(commands):
    filesystem = set()
    results = []

    for command in commands:
        parts = command.split()
        action = parts[0]
        if action == "CREATE":
            path = parts[1]
            if path in filesystem:
                results.append(f"ERROR: {path} already exists")
            else:
                filesystem.add(path)
                results.append("SUCCESS")
        elif action == "DELETE":
            path = parts[1]
            if path not in filesystem:
                results.append(f"ERROR: {path} does not exist")
            else:
                filesystem.remove(path)
                results.append("SUCCESS")
        elif action == "MOVE":
            srcPath = parts[1]
            destPath = parts[2]
            if srcPath not in filesystem:
                results.append(f"ERROR: {srcPath} does not exist")
            elif destPath in filesystem:
                results.append(f"ERROR: {destPath} already exists")
            else:
                filesystem.remove(srcPath)
                filesystem.add(destPath)
                results.append("SUCCESS")

    return results

def shortest_flower_bed_segment(n, k, t):
    required_types = set(range(1, k+1))
    found_types = {}
    min_length = float('inf')
    best_L, best_R = -1, -1

    start = 0
    for end in range(n):
        if t[end] in found_types:
            found_types[t[end]] += 1
        else:
            found_types[t[end]] = 1

        while len(found_types) == k:
            if end - start + 1 < min_length:
                min_length = end - start + 1
                best_L, best_R = start + 1, end + 1
            found_types[t[start]] -= 1
            if found_types[t[start]] == 0:
                del found_types[t[start]]
            start += 1

    return (best_L, best_R)

