def max_manhattan_distance(n, commands, k):
    """
    Calculates the maximum Manhattan distance the robot can reach from the starting point (0, 0)
    within k steps following the given command sequence.
    """
    x, y = 0, 0
    steps = min(n, k)  # The robot cannot take more steps than either the length of the commands or k

    for i in range(steps):
        command = commands[i]
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return abs(x) + abs(y)

