def calculate_max_thrill(n, m, roller_coasters, s):
    max_thrill = 0

    for u, v, x, p in roller_coasters:
        if p > 0:
            # Calculate the total thrill for consecutive rides until thrill becomes zero
            rides = x // p + 1  # Number of rides before thrill reaches zero
            total_thrill = (rides * (x + (x - (rides - 1) * p))) // 2   # Sum of arithmetic series
            max_thrill += total_thrill

    return max_thrill

