def max_subgrid_value(n, m, grid):
    max_value = float('-inf')

    def subgrid_sum(x1, y1, x2, y2):
        total = 0
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                total += grid[i][j]
        return total

    for x1 in range(n):
        for y1 in range(m):
            for x2 in range(x1, n):
                for y2 in range(y1, m):
                    cells_count = (x2 - x1 + 1) * (y2 - y1 + 1)
                    total = subgrid_sum(x1, y1, x2, y2)
                    current_value = total / cells_count
                    if current_value > max_value:
                        max_value = current_value

    return round(max_value, 6)

