from collections import deque

def tree_levels(n, edges):
    levels = [-1] * (n + 1)
    adj_list = [[] for _ in range(n + 1)]

    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    queue = deque([1])
    levels[1] = 0

    while queue:
        node = queue.popleft()
        current_level = levels[node]

        for neighbor in adj_list[node]:
            if levels[neighbor] == -1:
                levels[neighbor] = current_level + 1
                queue.append(neighbor)

    return levels

def are_on_same_level(levels, a, b):
    return levels[a] == levels[b]

def process_queries(n, edges, queries):
    levels = tree_levels(n, edges)
    results = []
    for a, b in queries:
        if are_on_same_level(levels, a, b):
            results.append("YES")
        else:
            results.append("NO")
    return results

