from collections import deque

def solve_maze(n, m, grid):
    """
    Solves the maze problem, returning the shortest path length if present.
    """
    # Directions for moving in the grid (down, up, right, left)
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # Breadth-First Search (BFS) method
    def bfs(start, end):
        queue = deque([(*start, 0)])  # cells to visit, with their distance from the start
        visited = set([start])

        while queue:
            x, y, dist = queue.popleft()

            if (x, y) == end:
                return dist

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] == '.':
                    visited.add((nx, ny))
                    queue.append((nx, ny, dist + 1))

        return -1

    start = (0, 0)
    end = (n - 1, m - 1)

    if grid[0][0] == '.' and grid[n - 1][m - 1] == '.':
        shortest_path_length = bfs(start, end)
        if shortest_path_length == -1:
            return "NO"
        else:
            return f"YES {shortest_path_length}"
    else:
        return "NO"

import heapq

def dijkstra(n, edges, src):
    graph = [[] for _ in range(n + 1)]
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = [float('inf')] * (n + 1)
    dist[src] = 0
    pq = [(0, src)]

    while pq:
        d, node = heapq.heappop(pq)
        if d > dist[node]:
            continue
        for neighbor, weight in graph[node]:
            new_dist = dist[node] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                heapq.heappush(pq, (new_dist, neighbor))

    return dist

def shortest_paths(n, m, edges, q, queries):
    all_pairs = {}
    for u in range(1, n + 1):
        dist = dijkstra(n, edges, u)
        for v in range(1, n + 1):
            all_pairs[(u, v)] = dist[v] if dist[v] != float('inf') else -1

    results = []
    for a, b in queries:
        results.append(all_pairs[(a, b)])
    return results

from typing import List

def find_peak_element(nums: List[int]) -> int:
    """
    Returns the index of a peak element in the list nums.
    """
    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[mid + 1]:
            right = mid
        else:
            left = mid + 1
    return left

