def find_unique_pairs(nums, target):
    """
    Finds all unique pairs of integers in the list that sum up to the target number.
    """
    seen = set()
    output = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            output.add(tuple(sorted((num, complement))))
        seen.add(num)

    return list(output)

def apply_operations(n, q, array, operations):
    for operation in operations:
        op_type, l, r, v = operation
        if op_type == 'add':
            for i in range(l-1, r):
                array[i] += v
        elif op_type == 'multiply':
            for i in range(l-1, r):
                array[i] *= v
    return array

from typing import List, Tuple, Union

def restore_graph(n: int, m: int, edges: List[Tuple[int, int, int]]) -> Union[List[Tuple[int, int, int]], int]:
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    edges.sort(key=lambda x: x[2])
    mst_edges = []
    for u, v, w in edges:
        if find(u) != find(v):
            union(u, v)
            mst_edges.append((u, v, w))
        if len(mst_edges) == n - 1:
            break

    if len(mst_edges) != n - 1:
        return -1

    return mst_edges

def find_subsequence_sum(n, s, q, queries):
    def has_subarray_with_sum(k):
        current_sum = 0
        prefix_sums = {0}

        for num in s:
            current_sum += num
            if (current_sum - k) in prefix_sums:
                return True
            prefix_sums.add(current_sum)

        return False

    results = []
    for k in queries:
        if has_subarray_with_sum(k):
            results.append("YES")
        else:
            results.append("NO")

    return results

