def rearrange_array(n, k, arr):
    arr.sort()
    result = [arr[0]]

    for i in range(1, n):
        if abs(result[-1] - arr[i]) >= k:
            result.append(arr[i])
        else:
            for j in range(i+1, n):
                if abs(result[-1] - arr[j]) >= k:
                    arr[i], arr[j] = arr[j], arr[i]
                    result.append(arr[i])
                    break
            else:
                return "Not possible"

    return result

