def determine_election_winner(test_cases):
    results = []

    for cities in test_cases:
        count_A_wins = 0
        count_B_wins = 0

        for city in cities:
            city_name, A_vote, B_vote = city
            if A_vote > B_vote:
                count_A_wins += 1
            elif B_vote > A_vote:
                count_B_wins += 1

        if count_A_wins > count_B_wins:
            results.append("A")
        elif count_B_wins > count_A_wins:
            results.append("B")
        else:
            results.append("Tie")

    return results

