def maxSubstringLength(s: str) -> int:
    def longest_with_one_change(char):
        max_len = 1  # because single character will be the minimum when not all elements are same
        left = 0
        changes = 0

        for right in range(len(s)):
            if s[right] != char:
                changes += 1
            while changes > 1:
                if s[left] != char:
                    changes -= 1
                left += 1
            max_len = max(max_len, right - left + 1)
        return max_len

    max_len_overall = 1
    unique_chars = set(s)

    for char in unique_chars:
        max_len_overall = max(max_len_overall, longest_with_one_change(char))

    return max_len_overall

