from itertools import permutations

def find_hamiltonian_cycle(n, m, paths):
    if n == 1:
        return "NO"

    adj_matrix = [[0] * n for _ in range(n)]
    for u, v, w in paths:
        adj_matrix[u-1][v-1] = w
        adj_matrix[v-1][u-1] = w

    # Generate all permutations of the nodes
    nodes = list(range(1, n))
    for perm in permutations(nodes):
        cycle = [0] + list(perm) + [0]
        valid = True
        for i in range(n):
            if adj_matrix[cycle[i]][cycle[i + 1]] == 0:
                valid = False
                break
        if valid:
            return "YES"

    return "NO"

