import sys

def floyd_warshall(n, graph):
    dist = [[sys.maxsize] * n for _ in range(n)]

    for u in range(n):
        dist[u][u] = 0

    for u in range(n):
        for v, w in graph[u]:
            dist[u][v] = w

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][k] != sys.maxsize and dist[k][j] != sys.maxsize:
                    dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    return dist

def process_queries(n, edges, queries):
    graph = [[] for _ in range(n)]
    for u, v, w in edges:
        graph[u-1].append((v-1, w))
        graph[v-1].append((u-1, w))

    shortest_paths = floyd_warshall(n, graph)
    results = []

    for x, y in queries:
        distance = shortest_paths[x-1][y-1]
        results.append(distance if distance != sys.maxsize else -1)

    return results

