def count_paths(grid):
    MOD = 10**9 + 7
    n = len(grid)
    m = len(grid[0])

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return 0

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD

    return dp[n-1][m-1]

def remove_unnecessary_words(text: str) -> str:
    """
    Removes unnecessary words from the text, keeping only the first occurrence of each word.
    """
    seen_words = set()
    result = []
    words = text.split()

    for word in words:
        if word not in seen_words:
            result.append(word)
            seen_words.add(word)

    return ' '.join(result)

def construct_grid(n, S):
    if S < n or S > n * (n ** 2):
        return "NO"

    grid = [[0] * n for _ in range(n)]
    num = 1

    for i in range(n):
        for j in range(n):
            grid[i][j] = num
            num += 1

    current_diagonal_sum = sum(grid[i][i] for i in range(n))

    if current_diagonal_sum == S:
        result = "YES\n"
        result += "\n".join(" ".join(str(grid[i][j]) for j in range(n)) for i in range(n))
        return result
    else:
        return "NO"

