def calculate_active_duration(logs):
    """
    Calculate the total active duration for each user from the log entries.

    Args:
    logs (list of tuples): List containing log entries as tuples (user_id, action, timestamp).

    Returns:
    dict: Dictionary where keys are user IDs and values are their respective active durations.
    """
    # Dictionary to store the minimum and maximum timestamps for each user
    user_times = {}

    for user_id, action, timestamp in logs:
        if user_id in user_times:
            user_times[user_id].append(timestamp)
        else:
            user_times[user_id] = [timestamp]

    # Calculate the active duration for each user
    active_durations = {}
    for user_id, times in user_times.items():
        active_durations[user_id] = max(times) - min(times)

    return active_durations

