def min_absolute_difference(t, test_cases):
    def min_partition_sum_difference(tasks):
        total_sum = sum(tasks)
        n = len(tasks)
        dp = [[False] * (total_sum + 1) for _ in range(n + 1)]

        for i in range(n + 1):
            dp[i][0] = True

        for i in range(1, n + 1):
            for j in range(1, total_sum + 1):
                dp[i][j] = dp[i - 1][j]
                if tasks[i - 1] <= j:
                    dp[i][j] = dp[i][j] or dp[i - 1][j - tasks[i - 1]]

        min_diff = float('inf')
        for j in range(total_sum // 2, -1, -1):
            if dp[n][j]:
                min_diff = min(min_diff, total_sum - 2 * j)
                break
        return min_diff

    results = []
    for case in test_cases:
        n, tasks = case
        result = min_partition_sum_difference(tasks)
        results.append(result)

    return results

