def robot_returns(commands: str) -> str:
    """
    Determines if the robot returns to the origin after executing all commands.

    Args:
    commands (str): A string of 'U', 'D', 'L', 'R' commands.

    Returns:
    str: "YES" if the robot returns to the origin, otherwise "NO".
    """
    x, y = 0, 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
    return "YES" if x == 0 and y == 0 else "NO"

