def distinct_paths(n, m, grid):
    # If the starting or ending cell has an obstacle, no path is possible
    if grid[0][0] == '1' or grid[n-1][m-1] == '1':
        return 0

    # Initialize DP table with all zeros
    dp = [[0] * m for _ in range(n)]

    # Set the start position to 1 if it is not an obstacle
    dp[0][0] = 1

    # Fill the DP table
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '1':
                dp[i][j] = 0  # No path through obstacles
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]  # Add paths from above
                if j > 0:
                    dp[i][j] += dp[i][j - 1]  # Add paths from the left

    return dp[n-1][m-1]

