def min_difference_partition(n, weights):
    total_sum = sum(weights)
    dp = [False] * (total_sum + 1)
    dp[0] = True

    for weight in weights:
        for j in range(total_sum, weight - 1, -1):
            if dp[j - weight]:
                dp[j] = True

    min_diff = float('inf')
    for i in range(total_sum // 2 + 1):
        if dp[i]:
            min_diff = min(min_diff, total_sum - 2 * i)

    return min_diff

