def longest_beauty(s, k):
    """
    Returns the length of the longest subsequence of identical consecutive characters
    after performing exactly k operations.
    """
    from collections import defaultdict

    def max_length_with_replacements(char):
        left = 0
        num_replacements = 0
        max_len = 0

        for right in range(len(s)):
            if s[right] != char:
                num_replacements += 1

            while num_replacements > k:
                if s[left] != char:
                    num_replacements -= 1
                left += 1

            max_len = max(max_len, right - left + 1)

        return max_len

    max_beauty = 0
    for char in set(s):
        max_beauty = max(max_beauty, max_length_with_replacements(char))

    return max_beauty

