def longest_fever_streak(n, records):
    longest_streak = 0
    current_streak = 0

    for record in records:
        temperature, presence = record
        if temperature >= 100.4 and presence == 'P':
            current_streak += 1
            if current_streak > longest_streak:
                longest_streak = current_streak
        else:
            current_streak = 0

    return longest_streak

def min_distance(source, target):
    """
    Returns the minimum number of operations required to convert source into target.
    Operations include insertion, deletion, and substitution of characters.
    """
    m, n = len(source), len(target)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If source is empty, insert all characters of target
            elif j == 0:
                dp[i][j] = i  # If target is empty, remove all characters of source
            elif source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # If characters are equal, no operation needed
            else:
                dp[i][j] = 1 + min(dp[i][j - 1],  # Insert
                                   dp[i - 1][j],  # Remove
                                   dp[i - 1][j - 1])  # Replace

    return dp[m][n]

