def attendance_system(operations):
    attendance = set()
    results = []
    for operation in operations:
        action, student_id = operation[0], operation[2:]
        if action == '+':
            attendance.add(student_id)
        elif action == '-':
            attendance.discard(student_id)
        elif action == '?':
            results.append(len(attendance))
    return results

def encrypt_message(k, s):
    """
    Encrypts the message s by shifting each letter k positions forward in the alphabet.
    :param k: Number of positions to shift (1 <= k <= 25).
    :param s: The message to be encrypted, consisting of lowercase letters and spaces.
    :return: The encrypted message.
    """
    encrypted_message = []

    for char in s:
        if char == ' ':
            encrypted_message.append(char)
        else:
            new_char = chr((ord(char) - ord('a') + k) % 26 + ord('a'))
            encrypted_message.append(new_char)

    return ''.join(encrypted_message)

