from typing import List, Tuple

def find_target(grid: List[List[int]], target: int) -> Tuple[int, int]:
    """
    Finds the coordinates of the target integer in a strictly increasing 2D grid.
    If the target is not found, returns (-1, -1).

    :param grid: List[List[int]] - A 2D list representing the grid.
    :param target: int - The target integer to find.

    :return: Tuple[int, int] - The coordinates of the target or (-1, -1).
    """
    if not grid or not grid[0]:
        return (-1, -1)

    rows = len(grid)
    columns = len(grid[0])

    # Start from the top right of the grid
    row = 0
    col = columns - 1

    while row < rows and col >= 0:
        if grid[row][col] == target:
            return (row, col)
        elif grid[row][col] > target:
            col -= 1
        else:
            row += 1

    return (-1, -1)

from typing import List

def find_min_sum_subarray(nums: List[int], k: int) -> List[int]:
    min_sum = float('inf')
    current_sum = sum(nums[:k])
    min_start_index = 0

    for i in range(len(nums) - k + 1):
        if i == 0:
            current_sum = sum(nums[:k])
        else:
            current_sum = current_sum - nums[i - 1] + nums[i + k - 1]

        if current_sum < min_sum:
            min_sum = current_sum
            min_start_index = i

    return nums[min_start_index:min_start_index + k]

