def can_form_word(S, words):
    results = []
    for word in words:
        index_s = 0
        index_w = 0
        while index_s < len(S) and index_w < len(word):
            if S[index_s] == word[index_w]:
                index_w += 1
            index_s += 1
        if index_w == len(word):
            results.append("YES")
        else:
            results.append("NO")
    return results

