from collections import deque, defaultdict

def min_messages_to_communicate(n, m, edges):
    def bfs(start):
        queue = deque([start])
        visited = set([start])
        count = 0

        while queue:
            node = queue.popleft()
            count += 1
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return count == n

    if n == 1:
        return 0

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Iterate through each vertex, if it can communicate with all other vertices
    for i in range(1, n + 1):
        if bfs(i):
            return 1

    return -1

