def count_paths(grid):
    """
    Returns the number of distinct paths from the top-left corner to the bottom-right corner of the grid.
    """
    if not grid or not grid[0] or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    M = len(grid)
    N = len(grid[0])

    dp = [[0] * N for _ in range(M)]

    dp[0][0] = 1  # Start point

    # Initialize first row
    for j in range(1, N):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]

    # Initialize first column
    for i in range(1, M):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]

    for i in range(1, M):
        for j in range(1, N):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[M-1][N-1]

