def min_insertions_to_palindrome(s):
    """
    Returns the minimum number of character insertions needed to make a string a palindrome.
    """
    n = len(s)
    dp = [[0]*n for _ in range(n)]

    # Fill the table
    for gap in range(1, n):
        l = 0
        for h in range(gap, n):
            if s[l] == s[h]:
                dp[l][h] = dp[l+1][h-1]
            else:
                dp[l][h] = min(dp[l][h-1], dp[l+1][h]) + 1
            l += 1

    return dp[0][n-1]

