import heapq

def dijkstra(n, edges, s):
    graph = [[] for _ in range(n+1)]
    for u, v, w in edges:
        graph[u].append((w, v))

    dist = [float('inf')] * (n+1)
    dist[s] = 0
    pq = [(0, s)]

    while pq:
        current_dist, u = heapq.heappop(pq)
        if current_dist > dist[u]:
            continue
        for weight, v in graph[u]:
            if dist[u] + weight < dist[v]:
                dist[v] = dist[u] + weight
                heapq.heappush(pq, (dist[v], v))

    return [d if d != float('inf') else -1 for d in dist[1:]]

def maximal_rectangle(matrix):
    if not matrix:
        return 0

    n = len(matrix)
    m = len(matrix[0])
    heights = [0] * m
    max_area = 0

    for row in matrix:
        for i in range(m):
            if row[i] == '1':
                heights[i] += 1
            else:
                heights[i] = 0

        max_area = max(max_area, largest_rectangle_area(heights))

    return max_area

def largest_rectangle_area(heights):
    stack = []
    max_area = 0
    heights.append(0)  # Add a zero to make sure all elements are processed
    for i in range(len(heights)):
        while stack and heights[i] < heights[stack[-1]]:
            h = heights[stack.pop()]
            w = i if not stack else i - stack[-1] - 1
            max_area = max(max_area, h * w)
        stack.append(i)
    heights.pop()  # Restore the original list
    return max_area

def shortest_path_to_destination(x, y, N_max, S_max, E_max, W_max):
    """
    Given the destination coordinates (x, y) and maximum allowed movements in each direction,
    compute the shortest time in minutes the drone takes to travel from (0,0) to (x,y).
    """
    if x >= 0:
        if x > E_max:
            return -1  # Exceeds maximum east bound
        east_moves = x
    else:
        if -x > W_max:
            return -1  # Exceeds maximum west bound
        east_moves = x

    if y >= 0:
        if y > N_max:
            return -1  # Exceeds maximum north bound
        north_moves = y
    else:
        if -y > S_max:
            return -1  # Exceeds maximum south bound
        north_moves = y

    return abs(east_moves) + abs(north_moves)

