def top_students_per_subject(test_cases):
    result = []

    for idx, case in enumerate(test_cases):
        student_grades = {}

        for student, grade in case:
            if grade in student_grades:
                student_grades[grade].append(student)
            else:
                student_grades[grade] = [student]

        # Sort grades in descending order and names lexicographically within the same grade
        sorted_grades = sorted(student_grades.items(), key=lambda x: (-x[0], sorted(x[1])))

        result.append(f"Case #{idx + 1}:")
        for grade, students in sorted_grades:
            students.sort()
            result.append(f"{grade}: {', '.join(students)}")

    return result

def find_string_placement(n, m, grid, t):
    directions = [
        (1, 0), (0, 1), (1, 1), (1, -1),  # Down, Right, Diagonal Down-Right, Diagonal Down-Left
        (-1, 0), (0, -1), (-1, -1), (-1, 1)  # Up, Left, Diagonal Up-Left, Diagonal Up-Right
    ]

    def is_valid_position(positions):
        for pi, pj in positions:
            if grid[pi][pj] == '*':
                return False
        return True

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                for di, dj in directions:
                    positions = []
                    for k in range(len(t)):
                        ni = (i + k * di) % n
                        nj = (j + k * dj) % m
                        positions.append((ni, nj))
                    if is_valid_position(positions):
                        result = [(pi + 1, pj + 1) for pi, pj in positions]
                        return result
    return -1

