def extract_document_content(library: str, title: str) -> str:
    start_title = f'[{title}]'
    start_index = library.find(start_title)
    if start_index == -1:
        return ""  # Title not found
    start_index += len(start_title)
    end_index = library.find('[', start_index)
    if end_index == -1:
        end_index = len(library)
    return library[start_index:end_index].strip()

