def calculate_bill(customer_type, usage):
    """
    Calculate the total bill for a customer based on their type and usage.
    """
    if customer_type == 'Residential':
        base_rate = 15.00
        rate_per_unit = 0.05
        total_cost = base_rate + (rate_per_unit * usage)
    elif customer_type == 'Commercial':
        base_rate = 100.00
        rate_per_unit = 0.02
        total_cost = base_rate + (rate_per_unit * usage)
    elif customer_type == 'Industrial':
        if usage <= 1000:
            total_cost = usage * 0.01
        else:
            total_cost = (1000 * 0.01) + ((usage - 1000) * 0.005)
    return round(total_cost, 2)

def generate_bills(customers):
    """
    Generate bills for a list of customers.
    """
    bills = []
    for customer in customers:
        customer_type, usage = customer
        bill = calculate_bill(customer_type, int(usage))
        bills.append(bill)
    return bills

from typing import List

def max_elevation_sum(grid: List[List[int]]) -> int:
    n = len(grid)
    dp = [[0] * n for _ in range(n)]

    # Initialize the dp array with the first row of the grid
    for j in range(n):
        dp[0][j] = grid[0][j]

    # Fill the dp array
    for i in range(1, n):
        for j in range(n):
            dp[i][j] = grid[i][j]
            max_prev = dp[i-1][j]
            if j > 0:
                max_prev = max(max_prev, dp[i-1][j-1])
            if j < n - 1:
                max_prev = max(max_prev, dp[i-1][j+1])
            dp[i][j] += max_prev

    # The result is the maximum value in the last row
    return max(dp[n-1])

def can_form_palindrome(t, test_cases):
    results = []
    for i in range(t):
        n, s = test_cases[i]
        char_count = {}
        for char in s:
            char_count[char] = char_count.get(char, 0) + 1

        odd_count = sum(1 for count in char_count.values() if count % 2 != 0)

        if odd_count > 1:
            results.append("NO")
        else:
            results.append("YES")
    return results

def additional_cables_to_connect(n, m, k, connections):
    from collections import defaultdict, deque

    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)

    # Function to perform BFS and find all nodes in a connected component
    def bfs(start, visited):
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    # Find all disconnected components
    visited = set()
    num_components = 0
    for node in range(1, n+1):
        if node not in visited:
            num_components += 1
            bfs(node, visited)

    # To connect all components, we need at least (num_components - 1) cables
    min_required_cables = num_components - 1

    # If we have enough additional cables, return the number of required cables
    if min_required_cables <= k:
        return min_required_cables
    else:
        return -1

