def check_indices(arr, k, l):
    """
    Determines if there are two distinct indices i and j in the array such that:
    - The absolute difference between the values at these indices is at least k
    - The absolute difference between these indices is at most l
    """
    n = len(arr)
    for i in range(n):
        for j in range(i+1, min(i+l+1, n)):
            if abs(arr[i] - arr[j]) >= k:
                return "YES"
    return "NO"

def optimize_contest(n, m, participants, problems):
    # Create a list of problem lists
    problem_index = {}
    for idx, topic in enumerate(problems):
        if topic not in problem_index:
            problem_index[topic] = []
        problem_index[topic].append(idx + 1)

    # List to store the result assignment
    assignments = [-1] * n

    # Iterate through each participant and assign the best possible problem
    for i in range(n):
        ei, xi = participants[i]
        if xi in problem_index and problem_index[xi]:
            assignments[i] = problem_index[xi].pop(0)

    return assignments

