def maximize_sequence(n, moves):
    sequence = []
    max_elem = -1

    for move in moves:
        if move == 0:
            if sequence:
                sequence.pop()
        else:
            if move > max_elem:
                sequence.append(move)
                max_elem = move

    return sequence

