def longest_instability(h, recordings):
    """
    This function finds the longest period of unstable voltage (consecutive '0's) in the given recordings.
    If the longest period is less than 2 hours or all periods are stable, it returns 'NO'.

    :param h: Number of hours the voltage was recorded.
    :param recordings: A string of '1's and '0's representing stable and unstable voltage readings respectively.
    :return: Length of the longest period of instability or 'NO'.
    """
    max_instability = 0
    current_instability = 0

    for record in recordings:
        if record == '0':
            current_instability += 1
        else:
            if current_instability > max_instability:
                max_instability = current_instability
            current_instability = 0

    if current_instability > max_instability:
        max_instability = current_instability

    if max_instability < 2:
        return "NO"
    return max_instability

