def calculate_word_value(word):
    return sum(ord(char) - ord('a') + 1 for char in word)

def count_special_synonym_pairs(words):
    from collections import defaultdict

    word_value_counts = defaultdict(int)

    for word in words:
        value = calculate_word_value(word)
        word_value_counts[value] += 1

    total_pairs = 0
    for count in word_value_counts.values():
        if count > 1:
            # Combination count for pairs is count choose 2.
            # Which is count * (count - 1) / 2
            total_pairs += count * (count - 1) // 2

    return total_pairs

