def largest_available_block(t, test_cases):
    results = []
    for test_case in test_cases:
        r, c, grid = test_case
        max_length = 0
        max_row_index = -1

        for i in range(r):
            current_length = 0
            best_length = 0
            for j in range(c):
                if grid[i][j] == '0':
                    current_length += 1
                    best_length = max(best_length, current_length)
                else:
                    current_length = 0
            if best_length > max_length:
                max_length = best_length
                max_row_index = i

        if max_length == 0:
            results.append((-1, 0))
        else:
            results.append((max_row_index, max_length))

    return results

