def can_partition_sequence(n, sequence):
    total_sum = sum(sequence)
    if total_sum % 2 != 0:
        return "NO"

    target = total_sum // 2
    current_sum = 0

    seen_sums = set()
    for num in sequence:
        current_sum += num
        if current_sum == target or (current_sum - target) in seen_sums:
            return "YES"
        seen_sums.add(current_sum)

    return "NO"

