def count_quasi_primes(n):
    """
    Returns the count of Quasi-Primes up to number n.
    Quasi-Primes are numbers of the form p^2 where p is a prime number.
    """
    if n < 2:
        return 0

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    quasi_primes_count = 0
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i] and i*i <= n:
            quasi_primes_count += 1

    return quasi_primes_count

def process_queries(T, queries):
    results = []
    for n in queries:
        results.append(count_quasi_primes(n))
    return results

