def find_MST(n, m, d, edges):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    valid_edges = [edge for edge in edges if edge[2] % d == 0]
    valid_edges.sort(key=lambda x: x[2])

    mst_weight = 0
    mst_edges = 0

    for u, v, w in valid_edges:
        if find(u) != find(v):
            union(u, v)
            mst_weight += w
            mst_edges += 1
            if mst_edges == n - 1:
                break

    if mst_edges == n - 1:
        return mst_weight
    else:
        return -1

# Example usage:
# edges = [(1, 2, 3), (1, 3, 6), (2, 3, 3), (2, 4, 9), (3, 4, 5)]
# print(find_MST(4, 5, 3, edges))  # Output should be 15

def isValidSequence(s: str) -> bool:
    """
    Determines if the input string s is a valid sequence of brackets.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

