def max_worker_units(m, n, grid):
    """
    Returns the maximum number of worker units that can be placed in the warehouse grid without adjacent placements.
    """
    max_units = 0
    for i in range(m):
        for j in range(n):
            if (i % 2 == 0 and j % 2 == 0) or (i % 2 == 1 and j % 2 == 1):
                if grid[i][j] == '.':
                    max_units += 1
    return max_units

def get_grid_input(m, n, rows):
    """
    Helper function to convert row list input into grid.
    """
    return [list(row) for row in rows]

def min_operations_to_make_equal(n, sequence):
    """
    Determines the minimum number of operations required to make all elements of the sequence equal.

    Args:
    n : int : the length of the sequence
    sequence : list of int : the elements of the sequence

    Returns:
    int : the minimum number of operations required to make all elements equal
    """
    if n == 1:
        return 0

    frequency = {}
    for num in sequence:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    max_freq = max(frequency.values())
    return n - max_freq

