from typing import List, Tuple, Dict

def find_cut_vertices(n: int, edges: List[Tuple[int, int]]) -> List[int]:
    def dfs(at, parent, visited, tin, low, graph, timer, cut_vertices):
        visited[at] = True
        tin[at] = low[at] = timer[0]  # timestamp
        timer[0] += 1
        children = 0

        for to in graph[at]:
            if to == parent:
                continue
            if visited[to]:
                # update the low time of current node 'at'
                low[at] = min(low[at], tin[to])
            else:
                dfs(to, at, visited, tin, low, graph, timer, cut_vertices)
                low[at] = min(low[at], low[to])

                if low[to] >= tin[at] and parent != -1:
                    cut_vertices.add(at)

                children += 1

        if parent == -1 and children > 1:
            cut_vertices.add(at)

    graph = {i: [] for i in range(1, n + 1)}
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    visited = [False] * (n + 1)
    tin = [-1] * (n + 1)
    low = [-1] * (n + 1)
    cut_vertices = set()
    timer = [0]

    for i in range(1, n + 1):
        if not visited[i]:
            dfs(i, -1, visited, tin, low, graph, timer, cut_vertices)

    return sorted(list(cut_vertices))

