def robot_return_to_origin(commands):
    """
    Determines if the robot returns to the original starting position after executing all commands.

    :param commands: str, commands consisting of 'U', 'D', 'L', 'R'
    :return: str, "YES" if the robot returns to the starting position, "NO" otherwise
    """
    x, y = 0, 0

    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return "YES" if x == 0 and y == 0 else "NO"

