def count_land_clusters(n, m, grid):
    def dfs(x, y):
        if x < 0 or x >= n or y < 0 or y >= m or grid[x][y] == 'W':
            return
        grid[x][y] = 'W'  # Mark as visited by changing 'L' to 'W'
        # Move in all four possible directions
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    clusters = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'L':
                dfs(i, j)
                clusters += 1

    return clusters

