def max_teams(n, t, strengths):
    # Sort the strengths array to facilitate team formation
    strengths.sort()

    teams_count = 0
    i = 0
    while i <= n - 3:
        if strengths[i + 2] - strengths[i] <= t:
            teams_count += 1
            i += 3
        else:
            i += 1

    return teams_count

