from typing import List

def can_travel(elevation_grid: List[List[int]]) -> bool:
    n = len(elevation_grid)
    m = len(elevation_grid[0])
    visited = [[False for _ in range(m)] for _ in range(n)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y, prev_value):
        return 0 <= x < n and 0 <= y < m and not visited[x][y] and abs(elevation_grid[x][y] - prev_value) <= 1

    def dfs(x, y):
        if x == n - 1 and y == m - 1:
            return True
        visited[x][y] = True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, elevation_grid[x][y]) and dfs(nx, ny):
                return True
        return False

    return dfs(0, 0)

