def schedule_tasks(n, m, k, tasks):
    if n != m * k:
        return -1

    tasks.sort()
    schedule = []
    for i in range(m):
        day_tasks = tasks[i * k : (i + 1) * k]
        schedule.append(day_tasks)

    return schedule

