from collections import deque

def min_jumps(pillars, k):
    n = len(pillars)

    if n == 1:
        return 0

    # Use a deque for BFS
    queue = deque([(0, 0)])  # (current position, number of jumps)
    visited = [False] * n
    visited[0] = True

    while queue:
        position, jumps = queue.popleft()

        # Check from the current position to the farthest jumpable position
        for next_position in range(position + 1, n):
            if abs(pillars[next_position] - pillars[position]) <= k:
                if next_position == n - 1:
                    return jumps + 1
                if not visited[next_position]:
                    visited[next_position] = True
                    queue.append((next_position, jumps + 1))
            else:
                # We can break early since further pillars will also be un-jumpable
                break

    return -1

# Example usage;
# You can uncomment these lines to test the function manually.
# n, k = 5, 2
# pillars = [1, 3, 1, 4, 6]
# print(min_jumps(pillars, k))  # Output: 3

