def is_balanced_expression(expr: str) -> bool:
    """
    Returns True if the brackets in the mathematical expression `expr` are balanced, otherwise False.
    """
    stack = []
    matching_bracket = {')': '(', ']': '['}

    for char in expr:
        if char in '([':
            stack.append(char)
        elif char in ')]':
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return not stack

