def handle_queries(n, q, array, queries):
    results = []
    for query in queries:
        q_type = query[0]
        if q_type == 1:
            i, x = query[1], query[2]
            array[i-1] = x
        elif q_type == 2:
            k = query[1]
            results.append(sum(array[:k]))
    return results

