def find_central_hub(n, cities):
    def weighted_distance(x1, y1):
        return sum(p * (abs(x1 - x2) + abs(y1 - y2)) for x2, y2, p in cities)

    min_distance = float('inf')
    central_hub_index = 0

    for i in range(n):
        x, y, _ = cities[i]
        distance = weighted_distance(x, y)

        if distance < min_distance:
            min_distance = distance
            central_hub_index = i

    return central_hub_index + 1

