def min_non_decreasing_subarrays(n, numbers):
    """
    This function takes an integer n and a list of n integers, and returns the
    minimum number of contiguous subarrays such that each subarray is non-decreasing.
    """
    if n == 1:
        return 1

    count = 1  # At least one subarray exists
    for i in range(1, n):
        if numbers[i] < numbers[i - 1]:
            count += 1
    return count

