import heapq

def dijkstra(n, m, edges, start, dest):
    graph = [[] for _ in range(n)]
    for u, v, t in edges:
        graph[u-1].append((t, v-1))
        graph[v-1].append((t, u-1))

    distances = [float('inf')] * n
    distances[start-1] = 0
    priority_queue = [(0, start-1)]

    while priority_queue:
        current_distance, u = heapq.heappop(priority_queue)
        if u == dest-1:
            return current_distance
        if current_distance > distances[u]:
            continue
        for weight, v in graph[u]:
            distance = current_distance + weight
            if distance < distances[v]:
                distances[v] = distance
                heapq.heappush(priority_queue, (distance, v))

    return -1 if distances[dest-1] == float('inf') else distances[dest-1]

def shortest_travel_time(n, m, edges, s, d):
    return dijkstra(n, m, edges, s, d)

