def find_unsorted_subarray(arr):
    """
    Finds the smallest subarray which when sorted sorts the entire array.
    Returns (l, r) where l and r are 1-based starting and ending indices of the subarray.
    If the entire array is already sorted, returns "Already Sorted".
    """
    n = len(arr)
    start, end = 0, -1
    sorted_arr = sorted(arr)

    for i in range(n):
        if arr[i] != sorted_arr[i]:
            start = i
            break

    for j in range(n-1, -1, -1):
        if arr[j] != sorted_arr[j]:
            end = j
            break

    if end == -1:
        return "Already Sorted"
    else:
        return (start + 1, end + 1)

