def optimal_hamiltonian_path(n, m, edges):
    from itertools import permutations

    if n == 1:
        return 0

    graph = [[float('inf')] * n for _ in range(n)]
    for u, v, w in edges:
        u -= 1
        v -= 1
        graph[u][v] = w
        graph[v][u] = w

    def calculate_path_cost(path):
        cost = 0
        for i in range(1, len(path)):
            if graph[path[i-1]][path[i]] == float('inf'):
                return float('inf')
            cost += graph[path[i-1]][path[i]]
        return cost

    min_cost = float('inf')
    for perm in permutations(range(n)):
        cost = calculate_path_cost(perm)
        if cost < min_cost:
            min_cost = cost

    return min_cost if min_cost != float('inf') else -1

