def is_beautiful_cityscape(n, heights):
    """
    Determines if the given cityscape is already beautiful or can be made
    beautiful by modifying at most one building's height.

    Parameters:
    n (int): the number of buildings
    heights (list of int): the heights of the buildings

    Returns:
    str: "YES" if the cityscape can be made beautiful, "NO" otherwise.
    """
    def check_beautiful(heights):
        for i in range(n - 1):
            if heights[i] == heights[i + 1]:
                return False
        return True

    if check_beautiful(heights):
        return "YES"

    for i in range(n):
        original_height = heights[i]

        for delta in [-1, 1]:
            heights[i] += delta
            if check_beautiful(heights):
                return "YES"
            heights[i] = original_height

    return "NO"

