def infix_to_postfix(expr):
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    associativity = {'+': 'L', '-': 'L', '*': 'L', '/': 'L', '^': 'R'}

    def higher_precedence(op1, op2):
        return precedence[op1] > precedence[op2] or (precedence[op1] == precedence[op2] and associativity[op1] == 'L')

    output = []
    stack = []

    for char in expr:
        if char.isalpha():
            output.append(char)
        elif char == '(':
            stack.append(char)
        elif char == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # Remove '(' from stack
        else:  # Operator
            while stack and stack[-1] != '(' and higher_precedence(stack[-1], char):
                output.append(stack.pop())
            stack.append(char)

    while stack:
        output.append(stack.pop())

    return ''.join(output)

