from collections import deque

def shortest_path(m, n, startRow, startCol, endRow, endCol, grid):
    if (startRow, startCol) == (endRow, endCol):
        return 0

    directions = [(1,0), (-1,0), (0,1), (0,-1)]
    queue = deque([(startRow, startCol, 0)])
    visited = set()
    visited.add((startRow, startCol))

    while queue:
        current_row, current_col, dist = queue.popleft()

        for d in directions:
            nr, nc = current_row + d[0], current_col + d[1]

            if 0 <= nr < m and 0 <= nc < n and grid[nr][nc] == '0' and (nr, nc) not in visited:
                if (nr, nc) == (endRow, endCol):
                    return dist + 1
                queue.append((nr, nc, dist+1))
                visited.add((nr, nc))

    return -1

