import heapq
from collections import defaultdict

def logistics_planner(n, m, roads, warehouse):
    def dijkstra(start):
        distance = [float("inf")] * (n + 1)
        distance[start] = 0
        priority_queue = [(0, start)]  # (distance, node)
        while priority_queue:
            current_distance, u = heapq.heappop(priority_queue)
            if current_distance > distance[u]:
                continue

            for edge in graph[u]:
                v, weight = edge
                new_distance = current_distance + weight

                if new_distance < distance[v]:
                    distance[v] = new_distance
                    heapq.heappush(priority_queue, (new_distance, v))

        return distance

    # Build the graph
    graph = defaultdict(list)
    for u, v, t in roads:
        graph[u].append((v, t))

    # Get the minimum travel times using Dijkstra's algorithm
    min_travel_times = dijkstra(warehouse)

    # Convert unreachable distances to -1 and ignore the 0-th index
    result = []
    for i in range(1, n + 1):
        if min_travel_times[i] == float('inf'):
            result.append(-1)
        else:
            result.append(min_travel_times[i])

    return result

