import bisect

def min_removals_to_make_increasing(heights):
    """
    Returns the minimum number of students to remove to make the heights strictly increasing.
    """
    if not heights:
        return 0

    # Helper to find LIS using binary search.
    def lis_length(seq):
        lis = []
        for height in seq:
            pos = bisect.bisect_left(lis, height)
            if pos == len(lis):
                lis.append(height)
            else:
                lis[pos] = height
        return len(lis)

    n = len(heights)
    lis_len = lis_length(heights)

    return n - lis_len

