def final_position(commands):
    """
    Returns the final coordinates of the robot after executing the given commands.

    Args:
    commands (str): A string containing 'U', 'D', 'L', 'R' commands.

    Returns:
    tuple: A tuple (x, y) representing the final coordinates.
    """
    x, y = 0, 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return x, y

