def can_create_continuous_segment_with_one_removal(n, floats):
    if n == 1:
        return "YES"

    floats = sorted(floats, key=lambda x: (x[0], x[1]))
    common_segments = []

    current_start = floats[0][0]
    current_end = floats[0][1]

    for i in range(1, n):
        if floats[i][0] > current_end + 1:
            common_segments.append((current_start, current_end))
            current_start = floats[i][0]
        current_end = max(current_end, floats[i][1])

    common_segments.append((current_start, current_end))

    if len(common_segments) == 1:
        return "YES"

    for i in range(1, len(common_segments)):
        if common_segments[i][0] > common_segments[i - 1][1] + 1:
            if len(common_segments) == 2:
                return "YES"
            else:
                return "NO"

    return "YES"

