def is_prime(num):
    if num < 2:
        return False
    if num in (2, 3):
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def max_prime_tax(gold):
    for tax in range(gold, 1, -1):
        if is_prime(tax):
            return tax
    return 0

def compute_taxes(golds):
    taxes = []
    for gold in golds:
        taxes.append(max_prime_tax(gold))
    return taxes

def find_conflicts(n, m, workshops):
    # Dictionary to store the schedule of each employee
    employee_schedules = {}

    for workshop in workshops:
        d, s, e, k, *ids = workshop
        for emp_id in ids:
            if emp_id not in employee_schedules:
                employee_schedules[emp_id] = []
            employee_schedules[emp_id].append((d, s, e))

    # Check for conflicts
    for emp_id, schedule in employee_schedules.items():
        # Sorting the schedule based on the day and start time
        schedule.sort()
        for i in range(len(schedule) - 1):
            d1, s1, e1 = schedule[i]
            d2, s2, e2 = schedule[i + 1]
            if d1 == d2 and e1 > s2:
                return f"{emp_id} {d1} {s1} {e1} {d2} {s2} {e2}"

    return "No conflict"

def fib_tree_fruits(d):
    """
    Returns the number of fruits produced by the FibTree on day `d` following the Fibonacci sequence.
    Efficiently computes the result using matrix exponentiation to handle large `d`.
    """
    if d == 1 or d == 2:
        return 1

    def matrix_mult(A, B):
        return [[A[0][0]*B[0][0] + A[0][1]*B[1][0], A[0][0]*B[0][1] + A[0][1]*B[1][1]],
                [A[1][0]*B[0][0] + A[1][1]*B[1][0], A[1][0]*B[0][1] + A[1][1]*B[1][1]]]

    def matrix_pow(M, power):
        result = [[1, 0], [0, 1]]  # Identity matrix
        base = M

        while power:
            if power % 2 == 1:
                result = matrix_mult(result, base)
            base = matrix_mult(base, base)
            power //= 2

        return result

    F = [[1, 1], [1, 0]]
    result_matrix = matrix_pow(F, d - 1)

    # The number of fruits on the d-th day is F(n) which is present in F(0,1) index of result matrix
    return result_matrix[0][0]

