def construct_b(n, m, a):
    from collections import Counter

    # Count the frequency of each value in array a
    counter = Counter(a)

    # Check if there is an element with frequency greater than or equal to m
    for key, value in counter.items():
        if value >= m:
            return [key] * m

    # Otherwise, construct b with (a[i % n]) % m for 0 <= i < m
    b = [(a[i % n]) % m for i in range(m)]
    return b

def solve(test_cases):
    results = []
    for n, m, a in test_cases:
        results.append(construct_b(n, m, a))
    return results

