def count_unique_pairs(n, k, arr):
    """
    Returns the number of unique pairs of integers in the array that add up to the target value k.
    """
    pairs = set()
    seen = set()

    for number in arr:
        complement = k - number
        if complement in seen:
            pairs.add(tuple(sorted((number, complement))))
        seen.add(number)

    return len(pairs)

