def max_gcd_subarray_length(arr):
    def calculate_gcd(subarr):
        return reduce(gcd, subarr)

    n = len(arr)
    max_length = 0

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            subarr = arr[i:i + length]
            if calculate_gcd(subarr) > 1:
                max_length = max(max_length, length)

    return max_length

def solve(test_cases):
