def findFirstMissingPositive(nums):
    """
    Returns the smallest positive integer that is missing from the array.
    """
    n = len(nums)

    # Mark numbers out of range and negative numbers with a placeholder (n + 1)
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Use the index as a hash key using absolute values
    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            nums[num - 1] = -abs(nums[num - 1])

    # Find the first missing positive integer
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

