def min_distance(s1, s2):
    """
    Calculate the minimum number of operations required to transform s1 into s2.
    """
    m, n = len(s1), len(s2)

    # Create a DP table of size (m+1)x(n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the DP table
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If s1 is empty, insert all characters of s2
            elif j == 0:
                dp[i][j] = i  # If s2 is empty, delete all characters of s1
            elif s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # Characters match, no operation needed
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],  # Delete
                                   dp[i][j - 1],  # Insert
                                   dp[i - 1][j - 1])  # Replace

    return dp[m][n]

