def longest_consecutive_subarray(nums):
    def is_consecutive(sub):
        sub_sorted = sorted(sub)
        for i in range(1, len(sub_sorted)):
            if sub_sorted[i] != sub_sorted[i - 1] + 1:
                return False
        return True

    max_length = 0
    n = len(nums)
    for i in range(n):
        for j in range(i, n):
            if is_consecutive(nums[i:j+1]):
                max_length = max(max_length, j - i + 1)

    return max_length

