def process_commands(commands):
    words = []
    results = []

    for command in commands:
        parts = command.split()
        action = parts[0]

        if action == "ADD":
            word = parts[1]
            words.append(word)

        elif action == "REMOVE":
            index = int(parts[1])
            words.pop(index)

        elif action == "COUNT":
            prefix = parts[1]
            count = sum(1 for word in words if word.startswith(prefix))
            results.append(str(count))

        elif action == "PRINT":
            results.append(" ".join(words))

    return results

