def find_movie_sequence(n, m, relationships, q, queries):
    from collections import defaultdict, deque

    # Create a graph from relationships
    graph = defaultdict(list)
    for u, v in relationships:
        graph[u].append(v)

    # Use BFS to determine the reachability for each query
    def is_reachable(x, y):
        if x == y:
            return True
        visited = set()
        queue = deque([x])

        while queue:
            current = queue.popleft()
            if current == y:
                return True
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    results = []
    for x, y in queries:
        if is_reachable(x, y):
            results.append("Yes")
        else:
            results.append("No")

    return results

