from math import isqrt

def is_prime(num):
    """
    Determines if a number is prime.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def subarray_sum_and_prime(n, q, arr, queries):
    """
    Determines the sum of elements in a subarray and whether the sum is a prime number.
    """
    # Create prefix sum array
    prefix_sum = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + arr[i - 1]

    results = []
    for l, r in queries:
        total_sum = prefix_sum[r] - prefix_sum[l - 1]
        results.append(f"{total_sum} {'Yes' if is_prime(total_sum) else 'No'}")

    return results

