def can_visit_all_locations(n, locations):
    visited = set()
    current = 0  # start from the first location

    for _ in range(n):
        if current in visited:
            return "NO"
        visited.add(current)
        current = locations[current] - 1  # move to the next location

    return "YES" if len(visited) == n else "NO"

