def min_operations(n, k, m, initial, final, operations):
    dp = [-1] * n
    if initial[0] == final[0]:
        dp[0] = 0
    else:
        for l, r, f in operations:
            if l == 1 and r == 1 and f == final[0]:
                dp[0] = 1

    for i in range(1, n):
        if initial[i] == final[i]:
            dp[i] = dp[i-1]
        else:
            min_operations_i = float('inf')
            for l, r, f in operations:
                if l <= i+1 <= r and f == final[i]:
                    if l == 1:
                        min_operations_i = min(min_operations_i, 1)
                    elif dp[l-2] != -1:
                        min_operations_i = min(min_operations_i, dp[l-2]+1)
            if min_operations_i == float('inf'):
                dp[i] = -1
            else:
                dp[i] = min_operations_i

    return dp[-1]

from typing import List

def max_benefit(B: int, C: List[int], V: List[int]) -> int:
    N = len(C)
    dp = [0] * (B + 1)

    for i in range(N):
        for b in range(B, C[i] - 1, -1):
            dp[b] = max(dp[b], dp[b - C[i]] + V[i])

    return dp[B]

