def longest_increasing_path(G):
    if not G or not G[0]:
        return 0

    m, n = len(G), len(G[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    cache = [[-1] * n for _ in range(m)]

    def dfs(x, y):
        if cache[x][y] != -1:
            return cache[x][y]

        max_length = 1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and G[nx][ny] > G[x][y]:
                max_length = max(max_length, 1 + dfs(nx, ny))

        cache[x][y] = max_length
        return cache[x][y]

    max_path = 0
    for i in range(m):
        for j in range(n):
            max_path = max(max_path, dfs(i, j))

    return max_path

def is_power_of_2(x):
    """
    Check if a number is a power of 2.
    """
    return x > 0 and (x & (x - 1)) == 0

def longest_power_of_2_subsequence(test_cases):
    results = []
    for case in test_cases:
        n, array = case
        max_length = 0
        current_length = 0

        for num in array:
            if is_power_of_2(num):
                current_length += 1
            else:
                max_length = max(max_length, current_length)
                current_length = 0

        max_length = max(max_length, current_length)
        results.append(max_length)

    return results

