def two_sum(numbers, target):
    """
    Returns a tuple of indices of the two elements in the array that add up to the target.
    If no such pair exists, returns an empty tuple.
    """
    num_to_index = {}
    for i, num in enumerate(numbers):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], i)
        num_to_index[num] = i
    return ()

