def length_of_lis(priorities):
    """
    Returns the length of the longest increasing subsequence
    given a list of message priorities.

    :param priorities: List of integers representing message priorities
    :return: Integer representing the length of the longest strictly increasing subsequence
    """
    if not priorities:
        return 0

    n = len(priorities)
    lis = [1] * n

    for i in range(1, n):
        for j in range(i):
            if priorities[i] > priorities[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    return max(lis)

