def min_repaints(n, sequence):
    """
    Returns the minimum number of repaints required so that no two adjacent blocks have the same color.
    """
    if n == 1:
        return 0

    repaints = 0
    last_color = sequence[0]

    for i in range(1, n):
        if sequence[i] == last_color:
            repaints += 1
            # Choose a different color for the next block assuming only three colors ('R', 'G', 'B')
            for color in 'RGB':
                if color != last_color and (i + 1 == n or color != sequence[i + 1]):
                    last_color = color
                    break
        else:
            last_color = sequence[i]

    return repaints

