from collections import deque

def min_transformations(n, words, start, end):
    """
    Returns the minimum number of transformations needed to change start into end
    by changing exactly one letter at a time with each intermediate word being valid.
    If no transformation is possible, returns -1.
    """
    word_set = set(words)
    if end not in word_set:
        return -1

    word_set.add(start)
    queue = deque([(start, 0)])

    while queue:
        current_word, steps = queue.popleft()
        if current_word == end:
            return steps

        for i in range(len(current_word)):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                next_word = current_word[:i] + c + current_word[i+1:]
                if next_word in word_set:
                    word_set.remove(next_word)
                    queue.append((next_word, steps + 1))
    return -1

