from collections import deque

def min_moves(n, grid, start, target):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n and grid[x][y] == '.'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    x1, y1 = start
    x2, y2 = target
    x1, y1, x2, y2 = x1 - 1, y1 - 1, x2 - 1, y2 - 1

    # If start or target is an asteroid, return -1
    if grid[x1][y1] == '#' or grid[x2][y2] == '#':
        return -1

    queue = deque([(x1, y1, 0)]) # (x, y, distance)
    visited = set((x1, y1))

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == (x2, y2):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

