def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def nth_alternating_prime_sum(n):
    """
    Calculates the n-th term of Frank's "alternating prime sum" sequence.

    Args:
    n (int): The term number to compute (1 ≤ n ≤ 1000).

    Returns:
    int: The value of the alternating prime sum sequence at the n-th term.
    """
    count = 0
    num = 2
    prime_sum = 0

    while count < n:
        if is_prime(num):
            if count % 2 == 0:
                prime_sum += num
            else:
                prime_sum -= num
            count += 1
        num += 1

    return prime_sum

