def is_possible(books, n, k, max_pages):
    students_required = 1
    current_pages = 0

    for pages in books:
        if current_pages + pages > max_pages:
            students_required += 1
            current_pages = pages
            if students_required > k:
                return False
        else:
            current_pages += pages

    return True

def find_min_max_pages(books, n, k):
    if n < k:
        return -1

    low, high = max(books), sum(books)
    result = high

    while low <= high:
        mid = (low + high) // 2
        if is_possible(books, n, k, mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return result

