def detect_negative_cycle(t, test_cases):
    def bellman_ford(n, edges):
        dist = [float('inf')] * (n + 1)
        dist[1] = 0

        for _ in range(n - 1):
            for u, v, w in edges:
                if dist[u] != float('inf') and dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w

        for u, v, w in edges:
            if dist[u] != float('inf') and dist[u] + w < dist[v]:
                return True
        return False

    results = []
    for case in test_cases:
        n, m = case[0]
        edges = case[1]
        if bellman_ford(n, edges):
            results.append("YES")
        else:
            results.append("NO")

    return results

