from itertools import combinations

def find_slots(n, k, T, chisels):
    """
    Determine if it's possible to select k chisels such that the sum of their widths equals T.
    :param n: Number of chisels
    :param k: Required number of slots
    :param T: Target width
    :param chisels: List of chisels' widths
    :return: Tuple containing "YES" or "NO" and the indices of selected chisels if possible
    """
    for comb in combinations(range(n), k):
        if sum(chisels[i] for i in comb) == T:
            return "YES", [i + 1 for i in comb]
    return "NO",

def chisels_solution(input_str):
    lines = input_str.strip().split('\n')
    n, k, T = map(int, lines[0].split())
    chisels = list(map(int, lines[1].split()))
    result = find_slots(n, k, T, chisels)
    if result[0] == "YES":
        return result[0] + "\n" + " ".join(map(str, result[1]))
    else:
        return result[0]

def longest_beautiful_view(heights):
    n = len(heights)
    if n < 3:
        return 0

    max_length = 0
    i = 1

    while i < n:
        while i < n and heights[i] == heights[i - 1]:
            i += 1

        increasing = 0
        while i < n and heights[i] > heights[i - 1]:
            increasing += 1
            i += 1

        decreasing = 0
        while i < n and heights[i] < heights[i - 1]:
            decreasing += 1
            i += 1

        if increasing > 0 and decreasing > 0:
            max_length = max(max_length, increasing + decreasing + 1)

    return max_length

