def process_commands(N, M, initial_statuses, commands):
    statuses = initial_statuses[:]
    active_count = sum(statuses)
    results = []

    for command in commands:
        parts = command.split()
        if parts[0] == "QUERY":
            results.append(active_count)
        elif parts[0] == "UPDATE":
            idx = int(parts[1]) - 1
            new_status = int(parts[2])
            if statuses[idx] != new_status:
                if new_status == 1:
                    active_count += 1
                else:
                    active_count -= 1
                statuses[idx] = new_status
    return results

def is_possible(n, m, denominations):
    """
    Determines if it's possible to provide exact change for amount m using at least two different denominations.

    Parameters:
        n (int): Number of different denominations.
        m (int): Total amount.
        denominations (list of int): Values of each denomination.

    Returns:
        str: "Possible" if it's possible, otherwise "Impossible".
    """
    def can_make_amount_with_two_denominations(m, denominations):
        # Check all pairs of denominations to see if their combination can make up the amount m
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(m // denominations[i] + 1):
                    if (m - k * denominations[i]) % denominations[j] == 0:
                        return True
        return False

    if n < 2:
        return "Impossible"

    if can_make_amount_with_two_denominations(m, denominations):
        return "Possible"
    return "Impossible"

