def count_subsequences(banner, pattern):
    """
    Returns the number of times the pattern appears as a subsequence in the banner.
    """
    m = len(banner)
    n = len(pattern)

    # Create a 2D dp array with (m+1) x (n+1) filled with zeros
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Every string includes the empty subsequence
    for i in range(m + 1):
        dp[i][0] = 1

    # Fill the dp array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if banner[i - 1] == pattern[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[m][n]

