def process_queries(n, q, array, queries):
    # Precompute prefix sums
    prefix_sums = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix_sums[i] = prefix_sums[i - 1] + array[i - 1]

    results = []
    for l, r in queries:
        sum_subarray = prefix_sums[r] - prefix_sums[l - 1]
        results.append(sum_subarray)

    return results

