def max_unique_substrings(s, k):
    """
    Returns the maximum number of unique substrings of length k from the input string s.
    """
    seen = set()
    n = len(s)

    for i in range(n - k + 1):
        substring = s[i:i+k]
        seen.add(substring)

    return len(seen)

