def max_sub_grid_sum(grid):
    def kadane_1d(arr):
        max_current = max_global = arr[0]
        for num in arr[1:]:
            max_current = max(num, max_current + num)
            max_global = max(max_global, max_current)
        return max_global

    n = len(grid)
    m = len(grid[0])

    max_sum = float('-inf')

    for left in range(m):
        temp = [0] * n
        for right in range(left, m):
            for i in range(n):
                temp[i] += grid[i][right]
            current_kadane_sum = kadane_1d(temp)
            max_sum = max(max_sum, current_kadane_sum)

    return max_sum

