def tallest_stack(n, heights):
    """
    Determines the height of the tallest stack of boxes that can be formed.

    Args:
    n     : int      : the number of boxes
    heights : list of int : the heights of the boxes

    Returns:
    int : height of the tallest stack that can be formed
    """
    if n == 0:
        return 0

    # Initialize an array to store the maximum height at each position
    dp = [1] * n  # Each box alone is a stack of height 1

    # Compute the optimal stack using a dynamic programming approach
    for i in range(1, n):
        for j in range(i):
            if heights[j] >= heights[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    # Return the maximum value from the dp array which represents the tallest stack
    return max(dp)

