def max_treasures(n, m, grid):
    """
    Returns the maximum number of treasures Marina can collect while reaching the bottom-right corner of the grid.
    If there's no valid path, returns -1.
    """
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return -1

    dp = [[-1 for _ in range(m)] for _ in range(n)]
    dp[0][0] = 0 if grid[0][0] == '.' else 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                continue

            if i > 0 and dp[i-1][j] != -1:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + (1 if grid[i][j] == 'T' else 0))

            if j > 0 and dp[i][j-1] != -1:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + (1 if grid[i][j] == 'T' else 0))

    return dp[n-1][m-1] if dp[n-1][m-1] != -1 else -1

def min_operations(s):
    """
    Returns the minimum number of operations needed to minimize the number of distinct
    characters in the string, considering uppercase and lowercase letters as distinct.
    """
    seen = set(s)
    return len(seen)

def process_test_cases(t, cases):
    results = []
    for s in cases:
        results.append(min_operations(s))
    return results

