def unique_paths_with_obstacles(n, m, grid):
    MOD = 1000000007

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return 0

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[n-1][m-1]

from collections import deque

def min_steps_to_exit(n, m, maze):
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_in_bounds(x, y):
        return 0 <= x < n and 0 <= y < m

    # 3D visited array to track state with 0 walls broken and 1 wall broken
    visited = [[[False, False] for _ in range(m)] for _ in range(n)]
    queue = deque([(0, 0, 0, 0)])  # (x, y, steps, walls_broken)
    visited[0][0][0] = True

    while queue:
        x, y, steps, walls_broken = queue.popleft()
        if x == n - 1 and y == m - 1:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_in_bounds(nx, ny):
                if maze[nx][ny] == '.' and not visited[nx][ny][walls_broken]:
                    visited[nx][ny][walls_broken] = True
                    queue.append((nx, ny, steps + 1, walls_broken))

                if maze[nx][ny] == '#' and walls_broken == 0 and not visited[nx][ny][1]:
                    visited[nx][ny][1] = True
                    queue.append((nx, ny, steps + 1, 1))

    return -1  # If no path found

def parse_input(input_str):
    input_lines = input_str.strip().split('\n')
    n, m = map(int, input_lines[0].strip().split())
    maze = [line.strip() for line in input_lines[1:]]
    return n, m, maze

