def min_operations_to_transform(str1: str, str2: str) -> int:
    """
    Returns the minimum number of operations required to transform str1 into str2.
    Operations allowed are insertions, deletions, and replacements.
    """
    m, n = len(str1), len(str2)

    # Create a DP table to store the minimal operations required to reach each position
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the first row and column
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the rest of the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(
                    dp[i - 1][j],    # Deletion
                    dp[i][j - 1],    # Insertion
                    dp[i - 1][j - 1] # Replacement
                ) + 1

    return dp[m][n]

