def contains_cycle(grid):
    def dfs(x, y, parent_x, parent_y):
        if visited[x][y]:
            return True
        visited[x][y] = True
        for direction in directions:
            nx, ny = x + direction[0], y + direction[1]
            if 0 <= nx < m and 0 <= ny < n and (nx, ny) != (parent_x, parent_y) and grid[nx][ny] == grid[x][y]:
                if dfs(nx, ny, x, y):
                    return True
        return False

    m = len(grid)
    n = len(grid[0])
    visited = [[False] * n for _ in range(m)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    for i in range(m):
        for j in range(n):
            if not visited[i][j]:
                if dfs(i, j, -1, -1):
                    return "Yes"
    return "No"

