def flip(matrix, i, j):
    """
    Flip the submatrix with top-left corner at (i, j).
    """
    flip_count = sum(matrix[i][j:j+2] + matrix[i+1][j:j+2])
    if flip_count == 3:
        for x in range(2):
            for y in range(2):
                matrix[i + x][j + y] ^= 1

def can_be_uniform(matrix, n, m):
    """
    Check if the matrix can be made all 1s or all 0s.
    """
    for i in range(n - 1):
        for j in range(m - 1):
            flip(matrix, i, j)

    count_zeros = sum(row.count(0) for row in matrix)
    count_ones = n * m - count_zeros
    return count_zeros == 0 or count_ones == 0

def is_uniform_possible(test_cases):
    """
    Evaluates all the test cases and returns the results.
    """
    results = []
    for matrix in test_cases:
        n, m, mat = matrix
        mat = [list(map(int, list(row))) for row in mat]
        if can_be_uniform(mat, n, m):
            results.append("YES")
        else:
            results.append("NO")
    return results

def is_subsequence(arr, seq):
    """
    Determine if `seq` is a subsequence of `arr`.
    """
    seq_index = 0
    for num in arr:
        if seq_index < len(seq) and num == seq[seq_index]:
            seq_index += 1
    return seq_index == len(seq)

