from typing import List

def max_popularity_score(n: int, durations: List[int], popularity_scores: List[int], D: int) -> int:
    # Initialize a DP array where dp[j] represents the maximum popularity score for duration j
    dp = [0] * (D + 1)

    # Iterate over each song
    for i in range(n):
        duration = durations[i]
        popularity = popularity_scores[i]

        # Update the DP array from back to front to avoid overwriting results
        for j in range(D, duration - 1, -1):
            dp[j] = max(dp[j], dp[j - duration] + popularity)

    # The answer is the maximum value in the DP array
    return max(dp)

