def max_animals_captured(grid):
    """
    Calculate the maximum number of different animal types that can be captured from
    the top-left to the bottom-right corner of the grid.
    """
    r = len(grid)
    c = len(grid[0])

    # Use dynamic programming to keep track of maximum unique animals encountered so far
    # at each cell. We will store sets of animals.
    dp = [[set() for _ in range(c)] for _ in range(r)]
    dp[0][0] = {grid[0][0]} if grid[0][0] != '.' else set()

    for i in range(r):
        for j in range(c):
            if i > 0:
                cell_below = dp[i-1][j].copy()
                if grid[i][j] != '.':
                    cell_below.add(grid[i][j])
                dp[i][j] = max(dp[i][j], cell_below, key=len)
            if j > 0:
                cell_right = dp[i][j-1].copy()
                if grid[i][j] != '.':
                    cell_right.add(grid[i][j])
                dp[i][j] = max(dp[i][j], cell_right, key=len)

    # The maximum unique animals in the bottom-right cell is our answer
    return len(dp[r-1][c-1])

