def smallest_fibonacci_greater_than_or_equal_to(N):
    """
    Returns the smallest Fibonacci number that is greater than or equal to N.
    """
    if N <= 0:
        return 0

    a, b = 0, 1
    while b < N:
        a, b = b, a + b

    return b

