def min_operations_to_non_decreasing(n, arr):
    """
    Returns the minimum number of operations needed to make the array non-decreasing.
    """
    operations = 0
    for i in range(1, n):
        if arr[i] < arr[i-1]:
            operations += arr[i-1] - arr[i]
            arr[i] = arr[i-1]
    return operations

