def count_palindromic_substrings(s):
    """
    Returns the number of contiguous palindromic substrings in the string s.
    """
    n = len(s)
    count = 0
    dp = [[False]*n for _ in range(n)]

    for length in range(1, n+1):  # length of substring
        for i in range(n-length+1):
            j = i + length - 1
            if length == 1:
                dp[i][j] = True
            elif length == 2:
                dp[i][j] = (s[i] == s[j])
            else:
                dp[i][j] = (s[i] == s[j] and dp[i+1][j-1])

            if dp[i][j]:
                count += 1

    return count

