def number_of_valid_sequences(n, m):
    """
    Returns the number of valid sequences of length m that can be formed from n elements.
    """
    MOD = 10**9 + 7

    def nCr(n, r):
        if r > n:
            return 0
        if r == 0 or r == n:
            return 1
        num = 1
        denom = 1
        for i in range(r):
            num = num * (n - i) % MOD
            denom = denom * (i + 1) % MOD
        return num * pow(denom, MOD-2, MOD) % MOD

    return nCr(n, m)

