# Let's model the problem as a grid traversal with BFS, alongside checking obstacles.
from collections import deque

def can_reach(start, destination, grid, n, m):
    if start == destination:
        return True

    queue = deque([start])
    visited = set([start])

    while queue:
        x, y = queue.popleft()

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] == 0:
                if (nx, ny) == destination:
                    return True
                visited.add((nx, ny))
                queue.append((nx, ny))

    return False

def solver(n, m, robots, obstacles):
    grid = [[0] * m for _ in range(n)]

    # Mark obstacles on the grid
    for (x, y) in obstacles:
        grid[x-1][y-1] = -1

    # Check if each robot can reach its destination.
    for robot in robots:
        start, dest = robot
        sx, sy = start
        dx, dy = dest

        if not can_reach((sx-1, sy-1), (dx-1, dy-1), grid, n, m):
            return "NO"

        # Mark the destination as an obstacle for subsequent robots since they can't overlap.
        grid[dx-1][dy-1] = -1

    return "YES"

def robots_sequence(n, m, robots_info, obstacles_info):
    robots = [(robots_info[i], robots_info[i+1]) for i in range(0, len(robots_info), 2)]
    return solver(n, m, robots, obstacles_info)

from collections import deque

def is_within_bounds(x, y, n, m):
    return 0 <= x < n and 0 <= y < m

def bfs_to_treasure(grid, n, m):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start = (0, 0)

    if grid[0][0] == '#' or grid[0][0] == 'T':  # Start is blocked or start is the treasure
        return -1 if grid[0][0] == '#' else 0

    queue = deque([(start, 0)])  # (position, steps)
    visited = set([start])

    while queue:
        (x, y), steps = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_within_bounds(nx, ny, n, m) and (nx, ny) not in visited and grid[nx][ny] != '#':
                if grid[nx][ny] == 'T':
                    return steps + 1
                queue.append(((nx, ny), steps + 1))
                visited.add((nx, ny))

    return -1

def min_steps_to_treasure(n, m, k, grid):
    return bfs_to_treasure(grid, n, m)

