def evaluate_expression(expression):
    elements = expression.split()

    def eval_tokens(tokens):
        token = tokens.pop(0)

        if token == "TRUE":
            return True
        elif token == "FALSE":
            return False
        elif token == "AND":
            return eval_tokens(tokens) and eval_tokens(tokens)
        elif token == "OR":
            return eval_tokens(tokens) or eval_tokens(tokens)
        elif token == "NOT":
            return not eval_tokens(tokens)

    return "TRUE" if eval_tokens(elements) else "FALSE"

def evaluate_logical_expressions(expressions):
    results = []
    for expression in expressions:
        results.append(evaluate_expression(expression))
    return results

def longest_common_subsequence(X, Y):
    """
    Returns the length of the longest common subsequence of X and Y.
    """
    m = len(X)
    n = len(Y)

    # Create a (m+1) x (n+1) DP table initialized to 0
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if X[i - 1] == Y[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # The answer is in the bottom-right corner of the DP table
    return dp[m][n]

