def count_unique_dominoes(dominoes):
    """
    Returns the number of unique dominoes.
    """
    unique_dominoes = set()

    for domino in dominoes:
        # Sort tuple to ensure (a, b) is the same as (b, a)
        normalized_domino = tuple(sorted(domino))
        unique_dominoes.add(normalized_domino)

    return len(unique_dominoes)

