def longest_simple_path(N, M, S, edges):
    from collections import defaultdict
    import itertools

    # Initialize graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    visited = [False] * (N + 1)
    dp = {}

    def dfs(node):
        if node in dp:
            return dp[node]

        visited[node] = True

        max_length = 0
        for neighbor, weight in graph[node]:
            if not visited[neighbor]:
                max_length = max(max_length, weight + dfs(neighbor))

        visited[node] = False
        dp[node] = max_length
        return max_length

    return dfs(S)

