def count_subarrays_with_sum_k(n, k, arr):
    """
    Counts the number of subarrays whose sum is exactly k.

    :param n: int - Number of elements in the array.
    :param k: int - Desired sum of subarrays.
    :param arr: List[int] - List of non-negative integers.
    :return: int - Number of subarrays with sum exactly equal to k.
    """
    count_map = {0: 1}
    current_sum = 0
    count = 0

    for num in arr:
        current_sum += num
        if current_sum - k in count_map:
            count += count_map[current_sum - k]

        if current_sum in count_map:
            count_map[current_sum] += 1
        else:
            count_map[current_sum] = 1

    return count

