def max_treasure(n, m, grid):
    """
    Returns the maximum amount of treasure the player can collect.
    """
    # Initialize a dp array with -1
    dp = [[-1] * m for _ in range(n)]
    dp[0][0] = 0 if grid[0][0] != 'T' else 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                continue  # If it's an obstacle, skip it
            if i > 0 and dp[i-1][j] != -1:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + (1 if grid[i][j] == 'T' else 0))
            if j > 0 and dp[i][j-1] != -1:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + (1 if grid[i][j] == 'T' else 0))
            if i > 0 and j > 0 and dp[i-1][j-1] != -1:
                dp[i][j] = max(dp[i][j], dp[i-1][j-1] + (1 if grid[i][j] == 'T' else 0))

    return dp[n-1][m-1] if dp[n-1][m-1] != -1 else 0

import heapq

def shortest_simple_path(n, m, edges, S, T):
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u].append((v, w))

    def dijkstra(S, T):
        pq = [(0, S, set())]
        while pq:
            cost, node, visited = heapq.heappop(pq)
            if node == T:
                return cost
            for neighbor, weight in graph[node]:
                if neighbor not in visited:
                    heapq.heappush(pq, (cost + weight, neighbor, visited | {neighbor}))
        return -1

    return dijkstra(S, T)

def max_diversity(n, k, fruit_types):
    """
    Returns the maximum diversity of fruits Alice can gather
    over any k consecutive trees.

    :param n: int, the number of trees
    :param k: int, the number of consecutive trees Alice can collect from
    :param fruit_types: list of int, the types of fruits on each tree
    :return: int, the maximum diversity of fruits
    """
    if k > n:
        return 0

    max_diversity = 0
    current_window = {}

    for i in range(n):
        if fruit_types[i] in current_window:
            current_window[fruit_types[i]] += 1
        else:
            current_window[fruit_types[i]] = 1

        if i >= k:
            old_fruit = fruit_types[i - k]
            if current_window[old_fruit] == 1:
                del current_window[old_fruit]
            else:
                current_window[old_fruit] -= 1

        if i >= k - 1:
            max_diversity = max(max_diversity, len(current_window))

    return max_diversity

