def subset_sum_exists(n, arr, t):
    """
    Determines whether there exists a subset of the array whose sum equals the target value.

    :param n: Integer, the number of elements in the array
    :param arr: List of integers, the elements of the array
    :param t: Integer, the target value
    :return: String, "YES" if such a subset exists, otherwise "NO"
    """
    def is_subset_sum(idx, current_sum):
        if current_sum == t:
            return True
        if idx == n:
            return False
        return is_subset_sum(idx + 1, current_sum + arr[idx]) or is_subset_sum(idx + 1, current_sum)

    return "YES" if is_subset_sum(0, 0) else "NO"

