from heapq import heappop, heappush
import math

def find_minimum_maximum_risk(n, m, s, t, paths):
    graph = {i: [] for i in range(1, n + 1)}

    for u, v, w in paths:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dijkstra_minimax(start, end, n):
        max_risks = [math.inf] * (n + 1)
        max_risks[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_max_risk, node = heappop(priority_queue)

            if node == end:
                return current_max_risk

            for neighbor, risk in graph[node]:
                new_risk = max(current_max_risk, risk)
                if new_risk < max_risks[neighbor]:
                    max_risks[neighbor] = new_risk
                    heappush(priority_queue, (new_risk, neighbor))

        return -1 if max_risks[end] == math.inf else max_risks[end]

    return dijkstra_minimax(s, t, n)

def max_length_subarray_sum(n, s, a):
    """
    Finds the length of the longest subarray with sum equal to s.
    """
    prefix_sum = {}
    current_sum = 0
    max_length = -1

    for i in range(n):
        current_sum += a[i]

        if current_sum == s:
            max_length = i + 1

        if (current_sum - s) in prefix_sum:
            max_length = max(max_length, i - prefix_sum[current_sum - s])

        if current_sum not in prefix_sum:
            prefix_sum[current_sum] = i

    return max_length

