def is_prime(num):
    """
    Utility function to check if a number is prime.
    """
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_matrix(n):
    """
    Generate an n x n matrix filled with prime numbers in increasing order.
    """
    prime_numbers = []
    current_num = 2

    while len(prime_numbers) < n * n:
        if is_prime(current_num):
            prime_numbers.append(current_num)
        current_num += 1

    matrix = []
    for i in range(n):
        row = prime_numbers[i * n:(i + 1) * n]
        matrix.append(row)

    return matrix

