def process_commands(n, commands):
    score = 0

    for command in commands:
        parts = command.split()
        op = parts[0]

        if op == "A":
            X = int(parts[1])
            score += X

        elif op == "D":
            X = int(parts[1])
            score -= X
            if score < 0:
                score = 0

        elif op == "M":
            X = int(parts[1])
            Y = int(parts[2])
            score *= X
            if score > Y:
                score = Y

    return score

