from typing import List
from collections import Counter

def find_matching_records(records: List[str], query: str) -> List[str]:
    """
    Returns a list of all strings from the input list that can be formed by
    reordering the letters in the query string followed by removing some letters.
    """
    def is_subsequence(counter_small, counter_large):
        for char, count in counter_small.items():
            if counter_large[char] < count:
                return False
        return True

    query_counter = Counter(query)
    result = []

    for record in records:
        record_counter = Counter(record)
        if is_subsequence(record_counter, query_counter):
            result.append(record)

    return result

