def collaboration(N, M, pairs):
    from collections import defaultdict, deque

    def bfs(start, adj, visited):
        queue = deque([start])
        visited[start] = True
        size = 0

        while queue:
            node = queue.popleft()
            size += 1
            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return size

    # Create an adjacency list
    adj = defaultdict(list)
    for a, b in pairs:
        adj[a].append(b)
        adj[b].append(a)

    visited = [False] * (N + 1)
    largest_group_size = 0

    for i in range(1, N + 1):
        if not visited[i]:
            group_size = bfs(i, adj, visited)
            largest_group_size = max(largest_group_size, group_size)

    return largest_group_size

def shortest_palindromic_subsequence(s: str) -> str:
    """
    Find the shortest palindromic subsequence of the given string `s` with a length greater than 1.
    If no such subsequence exists, return -1.
    """
    n = len(s)
    # Generate all pairs of letters in the string
    for i in range(n):
        for j in range(i + 1, n):
            if s[i] == s[j]:
                return s[i] * 2
    # If no such pair is found, return -1
    return -1

