def min_adjacent_swaps(n, s, t):
    """
    Determines the minimum number of adjacent swaps required to transform string s into string t.
    If it is impossible, returns -1.
    """
    # If the sorted versions of both strings are not the same, it's impossible to transform
    if sorted(s) != sorted(t):
        return -1

    swaps = 0
    s_list = list(s)

    for i in range(n):
        if s_list[i] != t[i]:
            j = i
            while j < n and s_list[j] != t[i]:
                j += 1

            while j > i:
                s_list[j], s_list[j - 1] = s_list[j - 1], s_list[j]
                swaps += 1
                j -= 1

    return swaps

