def city_road_connectivity(n, m, edges):
    import collections

    def bfs(start_node, graph, n):
        visited = [False] * (n + 1)
        queue = collections.deque([start_node])
        visited[start_node] = True
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return visited.count(True) == n

    graph = collections.defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    is_connected_initially = bfs(1, graph, n)

    if not is_connected_initially:
        return "No"

    for u, v in edges:
        graph[u].remove(v)
        graph[v].remove(u)

        if not bfs(1, graph, n):
            return "No"

        graph[u].append(v)
        graph[v].append(u)

    return "Yes"

