    for case in test_cases:
        n, stock, k, demands = case
        remaining_stock = stock[:]

        possible = True
        for day in demands:
            for i in range(n):
                if remaining_stock[i] < day[i]:
                    possible = False
                    break
                remaining_stock[i] -= day[i]
            if not possible:
                break

        if possible:
            results.append("YES")
            results.append(' '.join(map(str, remaining_stock)))
        else:
            results.append("NO")

    return results

