def can_travel_with_max_toll(n, roads, max_toll):
    from collections import deque, defaultdict

    graph = defaultdict(list)
    for u, v, w in roads:
        if w <= max_toll:
            graph[u].append(v)
            graph[v].append(u)

    visited = set()
    queue = deque([1])
    visited.add(1)

    while queue:
        city = queue.popleft()

        for next_city in graph[city]:
            if next_city not in visited:
                visited.add(next_city)
                queue.append(next_city)

    return len(visited) == n

def min_max_toll(n, m, roads):
    roads.sort(key=lambda x: x[2])

    low, high = 0, len(roads) - 1
    best_toll = float('inf')

    while low <= high:
        mid = (low + high) // 2
        max_toll = roads[mid][2]
        if can_travel_with_max_toll(n, roads, max_toll):
            best_toll = max_toll
            high = mid - 1
        else:
            low = mid + 1

    return best_toll if best_toll != float('inf') else -1

def longestIncreasingPath(matrix):
    if not matrix:
        return 0

    n = len(matrix)
    m = len(matrix[0])

    def dfs(x, y, prev_val, memo):
        if not (0 <= x < n and 0 <= y < m) or matrix[x][y] <= prev_val:
            return 0

        if memo[x][y] != -1:
            return memo[x][y]

        result = 0
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            result = max(result, dfs(x + dx, y + dy, matrix[x][y], memo))

        memo[x][y] = result + 1
        return memo[x][y]

    memo = [[-1] * m for _ in range(n)]
    max_length = 0
    for i in range(n):
        for j in range(m):
            max_length = max(max_length, dfs(i, j, -1, memo))

    return max_length

