from collections import deque

def min_moves(grid):
    """
    Calculate the minimum number of moves required to reach the bottom-right cell from the top-left cell.
    """
    n = len(grid)
    m = len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(start, end):
        queue = deque([start])
        visited = set()
        visited.add(start)
        moves = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()
                if (x, y) == end:
                    return moves
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] == '.':
                        visited.add((nx, ny))
                        queue.append((nx, ny))
            moves += 1

        return -1

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return -1

    return bfs((0, 0), (n-1, m-1))

def process_test_cases(t, test_cases):
    results = []
    for grid in test_cases:
        results.append(min_moves(grid))
    return results

