def min_operations_to_homogeneous(n, m, matrix):
    """
    Returns the minimum number of operations needed to make the matrix homogeneous.
    """
    counts = [0, 0]

    # Count the number of 0s and 1s in the matrix
    for row in matrix:
        for cell in row:
            counts[cell] += 1

    return min(counts)

