def count_special_elements(arr):
    """
    Returns the count of special elements in the array.
    An element is considered special if it is greater than the sum of the previous two elements.
    """
    count = 0
    for i in range(2, len(arr)):
        if arr[i] > arr[i-1] + arr[i-2]:
            count += 1
    return count

