def is_almost_non_decreasing(n, seq):
    """
    Determines if sequenece is almost non-decreasing by removing at most one element.
    """
    def is_non_decreasing(seq):
        for i in range(len(seq) - 1):
            if seq[i] > seq[i + 1]:
                return False
        return True

    for i in range(n):
        if is_non_decreasing(seq[:i] + seq[i+1:]):
            return True
    return False

def almost_non_decreasing_sequences(t, test_cases):
    results = []
    for i in range(t):
        n, seq = test_cases[i]
        result = is_almost_non_decreasing(n, seq)
        results.append("YES" if result else "NO")
    return results

