def longest_ap_subsequence(n, sequence):
    if n == 1:
        return 1

    dp = {}
    max_len = 1

    for i in range(n):
        for j in range(i + 1, n):
            diff = sequence[j] - sequence[i]
            if (i, diff) in dp:
                dp[(j, diff)] = dp[(i, diff)] + 1
            else:
                dp[(j, diff)] = 2
            max_len = max(max_len, dp[(j, diff)])

    return max_len

from collections import deque

def is_valid_move(x, y, n, m, grid, visited):
    return 0 <= x < n and 0 <= y < m and grid[x][y] == '.' and not visited[x][y]

def bfs(grid, start, end, n, m):
    queue = deque([start])
    visited = [[False] * m for _ in range(n)]
    visited[start[0]][start[1]] = True

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            return True

        for dx, dy in directions:
            new_x, new_y = x + dx, y + dy
            if is_valid_move(new_x, new_y, n, m, grid, visited):
                visited[new_x][new_y] = True
                queue.append((new_x, new_y))

    return False

def path_exists(grid, n, m, queries):
    results = []
    for query in queries:
        x1, y1, x2, y2 = query
        start = (x1 - 1, y1 - 1)
        end = (x2 - 1, y2 - 1)
        if bfs(grid, start, end, n, m):
            results.append("YES")
        else:
            results.append("NO")
    return results

def count_paths(n, m, grid):
    # Create a 2D dp array with dimensions (n x m)
    dp = [[0] * m for _ in range(n)]

    # If the starting point has an obstacle, return 0
    if grid[0][0] == '#':
        return 0

    # Initialize the starting point
    dp[0][0] = 1

    # Fill the dp array
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    # Return the number of ways to reach the bottom-right corner
    return dp[n-1][m-1]

def can_fence_garden(n, m, garden):
    """
    Determines whether it is possible to build a fence around the boundary of the garden.
    """
    for i in range(n):
        if garden[i][0] == 'T' or garden[i][m-1] == 'T':
            return "NO"

    for j in range(m):
        if garden[0][j] == 'T' or garden[n-1][j] == 'T':
            return "NO"

    return "YES"

def min_possible_max_value(t, test_cases):
    results = []
    for case in test_cases:
        n, arr = case
        prefix_max = arr[0]

        for i in range(1, n):
            if arr[i] < prefix_max:
                arr[i] += prefix_max - arr[i]
            prefix_max = max(prefix_max, arr[i])

        results.append(prefix_max)
    return results

