def max_sum_path(grid):
    n, m = len(grid), len(grid[0])
    # Create a dp array with the same dimensions as the grid
    dp = [[0]*m for _ in range(n)]

    # Initialize the dp array with the max sums
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, m):
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp array
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]

    return dp[n-1][m-1]

# Helper function to parse input and provide output
def max_sum_path_from_input(n, m, grid_lines):
    grid = [[int(num) for num in line.split()] for line in grid_lines]
    return max_sum_path(grid)

