def longest_subarray_with_average_at_least_T(n, T, apples):
    left = 0
    current_sum = 0
    max_length = 0

    for right in range(n):
        current_sum += apples[right]

        while left <= right and current_sum < T * (right - left + 1):
            current_sum -= apples[left]
            left += 1

        if current_sum >= T * (right - left + 1):
            max_length = max(max_length, right - left + 1)

    return max_length

