def can_sort_with_one_swap(n, array):
    """
    Returns "YES" if the array can be sorted with at most one swap of two adjacent elements, otherwise "NO".
    """
    if n <= 1:
        return "YES"

    swapped = False
    for i in range(n - 1):
        if array[i] > array[i + 1]:
            if swapped:  # If a swap has already been made, return NO
                return "NO"
            if (i > 0 and array[i - 1] > array[i + 1]) and (i < n - 2 and array[i] > array[i + 2]):
                return "NO"
            swapped = True

    return "YES"

