def min_subarray_shuffle_operations(n, A):
    """
    Returns the minimum number of subarray shuffle operations required to sort the array.
    """
    sorted_A = sorted(A)

    if A == sorted_A:
        return 0

    # Tracking the longest sorted subsequence length
    longest_sorted = 1
    current_length = 1

    for i in range(1, n):
        if A[i] > A[i - 1]:
            current_length += 1
            if current_length > longest_sorted:
                longest_sorted = current_length
        else:
            current_length = 1

    return n - longest_sorted

