def collect_max_carrots(grid):
    from collections import deque

    n = len(grid)
    m = len(grid[0])

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    queue = deque([(0, 0, 0)])  # (x, y, carrots)
    visited = [[False] * m for _ in range(n)]
    visited[0][0] = True

    max_carrots = -1

    while queue:
        x, y, carrots = queue.popleft()

        if x == n-1 and y == m-1:
            if carrots > max_carrots:
                max_carrots = carrots

        for dx, dy in directions:
            nx, ny, nc = x + dx, y + dy, carrots
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] != 'F':
                if grid[nx][ny] == 'C':
                    nc += 1
                visited[nx][ny] = True
                queue.append((nx, ny, nc))

    if max_carrots == -1:
        return -1

    return max_carrots

