def detect_cycles_in_directed_graph(n, m, edges):
    from collections import defaultdict, deque

    def find_cycle(v):
        stack.append(v)
        visited[v] = True
        rec_stack[v] = True

        for neighbor in adjacency_list[v]:
            if not visited[neighbor]:
                if find_cycle(neighbor):
                    return True
            elif rec_stack[neighbor]:
                cycle_start_index = stack.index(neighbor)
                cycle.extend(stack[cycle_start_index:])
                return True

        rec_stack[v] = False
        stack.pop()
        return False

    adjacency_list = defaultdict(list)
    for u, v in edges:
        adjacency_list[u].append(v)

    visited = [False] * (n + 1)
    rec_stack = [False] * (n + 1)
    stack = []
    cycle = []

    for node in range(1, n + 1):
        if not visited[node]:
            if find_cycle(node):
                return f"CYCLE DETECTED {' '.join(map(str, cycle))}"

    return "NO CYCLE"

