def minimize_max_subarray_sum(arr, k):
    def can_split_with_max_sum(mid):
        current_sum = 0
        subarrays = 1
        for num in arr:
            current_sum += num
            if current_sum > mid:
                subarrays += 1
                current_sum = num
                if subarrays > k:
                    return False
        return True

    left, right = max(arr), sum(arr)
    result = right

    while left <= right:
        mid = (left + right) // 2
        if can_split_with_max_sum(mid):
            result = mid
            right = mid - 1
        else:
            left = mid + 1

    return result

