def minDistance(word1, word2):
    """
    Returns the minimum number of operations required to convert word1 to word2.
    """
    n = len(word1)
    m = len(word2)

    # Create a 2D array to store the conversion costs
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Initialize the first row and column of the dp table
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j] + 1,   # Delete
                               dp[i][j - 1] + 1,   # Insert
                               dp[i - 1][j - 1] + 1)  # Replace

    return dp[n][m]

def maximum_wealth(n, m, wealth, edges):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for a, b in edges:
        graph[a].append(b)

    # Initialize distance and wealth array
    max_wealth = [-1] * (n + 1)
    max_wealth[1] = wealth[0]

    queue = deque([1])

    while queue:
        curr = queue.popleft()
        for neighbor in graph[curr]:
            if max_wealth[neighbor] < max_wealth[curr] + wealth[neighbor - 1]:
                max_wealth[neighbor] = max_wealth[curr] + wealth[neighbor - 1]
                queue.append(neighbor)

    return max_wealth[n] if max_wealth[n] != -1 else -1

def process_queries(n, q, arr, queries):
    results = []
    for query in queries:
        parts = query.split()
        if parts[0] == 'UPDATE':
            index = int(parts[1]) - 1
            value = int(parts[2])
            arr[index] = value
        elif parts[0] == 'SUM':
            l = int(parts[1]) - 1
            r = int(parts[2])
            results.append(sum(arr[l:r]))
    return results

