from typing import List

def combinationSum(arr: List[int], s: int) -> List[List[int]]:
    result = []
    arr.sort()

    def backtrack(remaining_sum, current_combination, start):
        if remaining_sum == 0:
            result.append(list(current_combination))
            return
        for i in range(start, len(arr)):
            if arr[i] > remaining_sum:
                break
            current_combination.append(arr[i])
            backtrack(remaining_sum - arr[i], current_combination, i)
            current_combination.pop()

    backtrack(s, [], 0)
    return result

