def is_path_possible(n, m, k, construction_zones):
    from collections import deque

    grid = [[0 for _ in range(m)] for _ in range(n)]

    # Mark construction zones on the grid
    for r1, c1, r2, c2 in construction_zones:
        for r in range(r1, r2+1):
            for c in range(c1, c2+1):
                grid[r][c] = 1

    # BFS to find a path from (0, 0) to (n-1, m-1)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0)])
    visited = set((0, 0))

    while queue:
        r, c = queue.popleft()

        if (r, c) == (n-1, m-1):
            return "YES"

        for dr, dc in directions:
            rr, cc = r + dr, c + dc

            if 0 <= rr < n and 0 <= cc < m and grid[rr][cc] == 0 and (rr, cc) not in visited:
                queue.append((rr, cc))
                visited.add((rr, cc))

    return "NO"

def can_reach_bottom_right(grid):
    n = len(grid)
    m = len(grid[0])
    start_char = grid[0][0]

    if start_char == '.':
        return "NO"

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == start_char

    visited = [[False]*m for _ in range(n)]
    queue = [(0, 0)]
    visited[0][0] = True

    while queue:
        x, y = queue.pop(0)

        if (x == n-1 and y == m-1):
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny) and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny))

    return "NO"

