def plan_trip(n, a, alice_cities, b, bob_cities, c, charlie_cities):
    """
    Determines the optimal visiting sequence for Alice, Bob, and Charlie with given priorities.
    """
    # Create a city to visitor map
    city_to_visitor = {}

    # Alice's cities (highest priority)
    for city in alice_cities:
        city_to_visitor[city] = 'A'

    # Bob's cities (second highest priority)
    for city in bob_cities:
        if city not in city_to_visitor:
            city_to_visitor[city] = 'B'

    # Charlie's cities (lowest priority)
    for city in charlie_cities:
        if city not in city_to_visitor:
            city_to_visitor[city] = 'C'

    # Prepare the output in a sorted manner based on city numbers
    output = [(city, city_to_visitor[city]) for city in range(1, n+1)]

    return output

def reorder_list(t, test_cases):
    """
    Reorders the lists such that the sum of every two adjacent numbers is not divisible by k.

    Args:
    t (int): The number of test cases.
    test_cases (list): A list containing tuples with (n, k) and the list of integers for each test case.

    Returns:
    list: A list of lists containing the reordered lists for each test case or -1 if not possible.
    """
    results = []
    for n, k, arr in test_cases:
        arr.sort()

        i, j = 0, n - 1
        reordered = []
        while i <= j:
            if i == j:
                reordered.append(arr[i])
            else:
                reordered.append(arr[j])
                if i != j:
                    reordered.append(arr[i])
            i += 1
            j -= 1

        valid = True
        for i in range(1, n):
            if (reordered[i-1] + reordered[i]) % k == 0:
                valid = False
                break

        if valid:
            results.append(reordered)
        else:
            results.append(-1)

    return results

