def is_return_to_origin(transform_string: str) -> bool:
    """
    Returns True if the movements described by transform_string return to the origin (0, 0),
    otherwise returns False.
    """
    horizontal = 0
    vertical = 0

    for move in transform_string:
        if move == "L":
            horizontal -= 1
        elif move == "R":
            horizontal += 1
        elif move == "U":
            vertical += 1
        elif move == "D":
            vertical -= 1

    return horizontal == 0 and vertical == 0

