def is_tree(n, m, edges):
    from collections import defaultdict

    if m != n - 1:
        return "NO (contains cycle)" if m > n - 1 else "NO (not connected)"

    adjacency_list = defaultdict(list)
    for u, v in edges:
        adjacency_list[u].append(v)
        adjacency_list[v].append(u)

    visited = set()

    def dfs(node, parent):
        visited.add(node)
        for neighbor in adjacency_list[node]:
            if neighbor not in visited:
                if not dfs(neighbor, node):
                    return False
            elif neighbor != parent:
                return False
        return True

    # Start DFS from node 1 (assuming nodes are 1-indexed and given graph is connected)
    if not dfs(1, -1):
        return "NO (contains cycle)"

    # Check if all nodes are visited (graph is connected)
    if len(visited) != n:
        return "NO (not connected)"

    return "YES"

