def longest_consecutive_team_sequence(n, participants):
    """
    This function takes number of participants and their corresponding team numbers and returns
    the length of the longest consecutive sequence of participants from the same team.
    """
    if n == 0:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, n):
        if participants[i] == participants[i-1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
            current_length = 1

    # Check for the last sequence
    if current_length > max_length:
        max_length = current_length

    return max_length

