def is_prime(num):
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i != 0:
            continue
        return False
    return True

def longest_palindromic_prime_subsequence(n, arr):
    primes = [num for num in arr if is_prime(num)]

    if not primes:
        return 0

    def longest_palindromic_subseq_length(sequence):
        length = len(sequence)
        dp = [[0] * length for _ in range(length)]

        for i in range(length):
            dp[i][i] = 1

        for sub_len in range(2, length + 1):
            for i in range(length - sub_len + 1):
                j = i + sub_len - 1
                if sequence[i] == sequence[j]:
                    dp[i][j] = dp[i + 1][j - 1] + 2
                else:
                    dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

        return dp[0][-1]

    return longest_palindromic_subseq_length(primes)

