def find_largest_sum_contiguous_subarray(grid):
    def kadane(arr):
        max_ending_here = max_so_far = arr[0]
        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    def max_sum_grid(grid):
        n = len(grid)
        m = len(grid[0])
        max_sum = float('-inf')

        for left in range(m):
            temp = [0] * n
            for right in range(left, m):
                for i in range(n):
                    temp[i] += grid[i][right]
                max_sum = max(max_sum, kadane(temp))

        return max_sum

    return max_sum_grid(grid)

from typing import List

def shortest_segment(article: str, keywords: List[str]) -> str:
    # Helper function to check if all keywords are in a substring
    def contains_keywords(substring, keywords):
        return all(kw in substring for kw in keywords)

    words = article.split()
    n = len(words)
    shortest = ""
    shortest_length = float('inf')

    for i in range(n):
        for j in range(i, n):
            substring = ' '.join(words[i:j+1])
            if contains_keywords(substring, keywords):
                if j - i + 1 < shortest_length:
                    shortest = substring
                    shortest_length = j - i + 1

    return shortest

