def max_distinct_char_substring(s, k):
    """
    Finds a substring of length k which contains the maximum number of distinct characters.
    If there are multiple such substrings, return the lexicographically smallest one.
    """
    from collections import defaultdict

    n = len(s)

    if k == 1:
        return min(s)

    max_distinct_count = 0
    best_substring = s[0:k]

    for i in range(n - k + 1):
        current_substr = s[i:i+k]
        distinct_count = len(set(current_substr))

        if distinct_count > max_distinct_count:
            max_distinct_count = distinct_count
            best_substring = current_substr
        elif distinct_count == max_distinct_count:
            best_substring = min(best_substring, current_substr)

    return best_substring

