def possible_new_roads(n, roads):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start):
        visited = set()
        q = deque([start])
        while q:
            node = q.popleft()
            if node in visited:
                continue
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    q.append(neighbor)
        return visited

    all_nodes = set(range(1, n + 1))
    components = []
    visited_nodes = set()

    for node in range(1, n + 1):
        if node not in visited_nodes:
            component = bfs(node)
            components.append(component)
            visited_nodes |= component

    possible_edges = []
    for i in range(1, n):
        for j in range(i + 1, n + 1):
            if j not in graph[i]:
                possible_edges.append((i, j))

    return possible_edges

def count_special_substrings(s):
    n = len(s)
    count = 0

    for i in range(n):
        # Count single letter substrings
        count += 1

        # Count substrings with the same start and end character
        for j in range(i + 1, n):
            if s[i] == s[j]:
                count += 1

    return count

