def can_divide_in_k_groups_with_max_sum(max_sum, times, k):
    current_sum = 0
    group_count = 1
    for time in times:
        if current_sum + time > max_sum:
            group_count += 1
            current_sum = time
            if group_count > k:
                return False
        else:
            current_sum += time
    return True

def minimum_maximum_running_time(n, k, times):
    left, right = max(times), sum(times)

    while left < right:
        mid = (left + right) // 2
        if can_divide_in_k_groups_with_max_sum(mid, times, k):
            right = mid
        else:
            left = mid + 1

    return left

