def make_palindrome(s):
    """
    Append the minimum number of characters to the end of the string to make it a palindrome.
    Return the number of characters added and the resulting palindrome string.
    """
    def is_palindrome(substring):
        return substring == substring[::-1]

    n = len(s)
    if is_palindrome(s):
        return 0, s

    for i in range(n):
        if is_palindrome(s[i:]):
            to_add = s[:i][::-1]
            return len(to_add), s + to_add

    return len(s), s[::-1]

