def judge_circle(commands: str) -> bool:
    # Initialize starting position
    x, y = 0, 0

    # Loop through each command
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    # Check if the robot is back at the origin
    return x == 0 and y == 0

