def count_similar_positions(n, s):
    """
    Counts the number of pairs of indices (i, j) (1 ≤ i < j ≤ n) that are similar.

    A pair of indices (i, j) is similar if the character at position i can replace the character
    at position j to make the string a palindrome.

    :param n: Length of the string s
    :param s: The string of lowercase Latin letters
    :return: The number of similar pairs
    """
    if n == 1:
        return 0

    count = 0
    counter = {}

    for char in s:
        if char in counter:
            counter[char] += 1
        else:
            counter[char] = 1

    for char, freq in counter.items():
        if freq > 1:
            count += freq * (freq - 1) // 2

    return count

