def longest_palindromic_subsequence(n):
    """
    Function to determine the length of the longest palindromic subsequence of an integer n.
    """
    def lps(seq):
        n = len(seq)
        # Create a 2D table to store results of subproblems
        L = [[0 for x in range(n)]for y in range(n)]

        # Strings of length 1 are palindrome of length 1
        for i in range(n):
            L[i][i] = 1

        # Build the table. Note that the lower diagonal values
        # of table are useless and not filled in the process.
        for cl in range(2, n+1):
            for i in range(n-cl+1):
                j = i + cl - 1
                if seq[i] == seq[j] and cl == 2:
                    L[i][j] = 2
                elif seq[i] == seq[j]:
                    L[i][j] = L[i+1][j-1] + 2
                else:
                    L[i][j] = max(L[i][j-1], L[i+1][j])

        return L[0][n-1]

    # Convert integer to string
    s = str(n)
    return lps(s)

