def can_partition_into_k_equal_sum_groups(n, k, arr):
    total_sum = sum(arr)
    if total_sum % k != 0:
        return "NO"

    target_sum = total_sum // k
    visited = [False] * n

    def backtrack(start, k_remaining, current_sum):
        if k_remaining == 0:
            return True
        if current_sum == target_sum:
            return backtrack(0, k_remaining - 1, 0)

        for i in range(start, n):
            if not visited[i] and current_sum + arr[i] <= target_sum:
                visited[i] = True
                if backtrack(i + 1, k_remaining, current_sum + arr[i]):
                    return True
                visited[i] = False
        return False

    return "YES" if backtrack(0, k, 0) else "NO"

def solve(t, test_cases):
    results = []
    for i in range(t):
        n, k = test_cases[i][0]
        arr = test_cases[i][1]
        results.append(can_partition_into_k_equal_sum_groups(n, k, arr))
    return results

