from collections import defaultdict, deque

def max_sum_at_depth(n, labels, edges):
    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    depth_sum = defaultdict(int)
    visited = set()

    queue = deque([(1, 0)])  # Start from node 1 with depth 0
    visited.add(1)

    while queue:
        node, depth = queue.popleft()
        depth_sum[depth] += labels[node-1]
        for neighbor in tree[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, depth+1))

    return max(depth_sum.values())

def minimum_additional_roads_needed(m, regions):
    def dfs(node, visited, graph):
        stack = [node]
        while stack:
            v = stack.pop()
            if v not in visited:
                visited.add(v)
                for neighbor in graph[v]:
                    if neighbor not in visited:
                        stack.append(neighbor)

    results = []
    for f, r, roads in regions:
        graph = {i: [] for i in range(1, f + 1)}
        for u, v in roads:
            graph[u].append(v)
            graph[v].append(u)

        visited = set()
        components = 0
        for i in range(1, f + 1):
            if i not in visited:
                components += 1
                dfs(i, visited, graph)

        results.append(components - 1)

    return results

