def max_profit(prices):
    """
    Returns the maximum profit that can be achieved from the given stock prices.
    If no profit can be made, returns 0.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

