from collections import deque

def min_moves(n, m, grid):
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return -1

    directions = [(1, 0), (0, 1)]  # down, right
    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set([(0, 0)])

    while queue:
        x, y, dist = queue.popleft()
        if (x, y) == (n-1, m-1):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] == 0:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

def process_input(t, cases):
    results = []
    for case in cases:
        n, m, grid = case['dimensions'][0], case['dimensions'][1], case['grid']
        results.append(min_moves(n, m, grid))
    return results

