def find_paragraph_with_sequence(k, books, m, search_sequence):
    search_sequence = " ".join(search_sequence)

    for book_index in range(k):
        paragraphs = books[book_index]
        for paragraph_index in range(len(paragraphs)):
            if search_sequence in paragraphs[paragraph_index]:
                return book_index + 1, paragraph_index + 1
    return "Sequence not found"


# Transformation of input for testing purposes
def transform_input(input_text):
    input_lines = input_text.strip().split('\n')
    k = int(input_lines[0])
    books = []
    current_line = 1
    for _ in range(k):
        p_j = int(input_lines[current_line])
        paragraphs = input_lines[current_line + 1: current_line + 1 + p_j]
        books.append(paragraphs)
        current_line += p_j + 1
    m = int(input_lines[current_line])
    search_sequence = input_lines[current_line + 1].split()
    return k, books, m, search_sequence

# Combined function to handle input and output (for isolation in test cases)
def find_paragraph(input_text):
    k, books, m, search_sequence = transform_input(input_text)
    return find_paragraph_with_sequence(k, books, m, search_sequence)

def longest_palindromic_substring(s):
    """
    This function returns the longest palindromic substring in the given string `s`.
    """
    if len(s) == 0:
        return ""
    n = len(s)
    start, maxlen = 0, 1  # starting index and length of longest palindrome

    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            if substr == substr[::-1]:  # check if the substring is a palindrome
                if len(substr) > maxlen:
                    start, maxlen = i, len(substr)

    return s[start:start + maxlen]

