import heapq

def minimum_travel_time(n, m, roads):
    graph = [[] for _ in range(n+1)]

    for u, v, t in roads:
        graph[u].append((v, t))
        graph[v].append((u, t))

    def dijkstra(start, end):
        min_times = [float('inf')] * (n + 1)
        min_times[start] = 0
        priority_queue = [(0, start)]

        while priority_queue:
            current_time, u = heapq.heappop(priority_queue)

            if current_time > min_times[u]:
                continue

            for v, time in graph[u]:
                new_time = current_time + time
                if new_time < min_times[v]:
                    min_times[v] = new_time
                    heapq.heappush(priority_queue, (new_time, v))

        return min_times[end] if min_times[end] != float('inf') else -1

    return dijkstra(1, n)

def longest_zigzag_sequence(trees):
    n = len(trees)
    if n == 1:
        return 1

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        for j in range(i):
            if trees[i] > trees[j]:
                up[i] = max(up[i], down[j] + 1)
            elif trees[i] < trees[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(max(up), max(down))

