def max_sum_subarray_with_length_not_exceeding_k(arr, K):
    n = len(arr)
    max_sum = float('-inf')
    for curr_length in range(1, K+1):
        current_sum = sum(arr[:curr_length])
        max_sum = max(max_sum, current_sum)
        for i in range(curr_length, n):
            current_sum += arr[i] - arr[i - curr_length]
            max_sum = max(max_sum, current_sum)
    return max_sum

