def longest_equal_subsequence(t, sequences):
    """
    This function takes the number of test cases t and a list of binary string sequences.
    It returns a list of integers representing the length of the longest contiguous subsequence
    with an equal number of 0s and 1s for each string.
    """
    results = []

    for s in sequences:
        n = len(s)
        max_len = 0
        prefix_sum = 0
        prefix_sum_map = {0: -1}

        for i in range(n):
            if s[i] == '0':
                prefix_sum -= 1
            else:
                prefix_sum += 1

            if prefix_sum in prefix_sum_map:
                current_len = i - prefix_sum_map[prefix_sum]
                if current_len > max_len:
                    max_len = current_len
            else:
                prefix_sum_map[prefix_sum] = i

        results.append(max_len)

    return results

