def can_form_equal_stacks(n, books):
    blue_books = []
    red_books = []

    # Separate the books into blue and red stacks
    for height, color in books:
        if color == 0:
            blue_books.append(height)
        else:
            red_books.append(height)

    sum_blue = sum(blue_books)
    sum_red = sum(red_books)

    # If the total heights of blue and red stacks are already equal
    if sum_blue == sum_red:
        return "YES"

    # Determine all possible sums from the blue books
    def possible_sums(books):
        possible = {0}
        for book in books:
            new_possible = set()
            for ps in possible:
                new_possible.add(ps + book)
            possible.update(new_possible)
        return possible

    possible_blue_sums = possible_sums(blue_books)
    possible_red_sums = possible_sums(red_books)

    # Check if there is a possible sum in blue stack and red stack that is the same
    for blue_sum in possible_blue_sums:
        if (sum_blue - blue_sum) == (sum_red + blue_sum):
            return "YES"

    return "NO"

