def isUniquePath(n, m, grid):
    from collections import deque

    def bfs(start, end):
        queue = deque([start])
        visited = set()
        directions = [(0, 1), (1, 0)]
        path_count = 0

        while queue:
            x, y = queue.popleft()
            if (x, y) == end:
                path_count += 1
                if path_count > 1:
                    return path_count
            visited.add((x, y))
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] == '0':
                    queue.append((nx, ny))

        return path_count

    # Checking the edge cases where the start or end is blocked
    if grid[0][0] == '1' or grid[n-1][m-1] == '1':
        return False

    start = (0, 0)
    end = (n-1, m-1)

    # Check the number of unique paths
    path_count = bfs(start, end)

    return path_count == 1

