def count_paths_with_one(n, m, grid):
    def dfs(x, y, contains_one):
        if x == n - 1 and y == m - 1:
            return 1 if contains_one or grid[x][y] == 1 else 0
        if (x, y) in memo:
            if contains_one:
                return memo[(x, y)][1]
            return memo[(x, y)][0]

        paths = 0
        if x + 1 < n:
            paths += dfs(x + 1, y, contains_one or grid[x + 1][y] == 1)
        if y + 1 < m:
            paths += dfs(x, y + 1, contains_one or grid[x][y + 1] == 1)

        memo[(x, y)] = (memo.get((x, y), (0, 0))[0], memo.get((x, y), (0, 0))[1])
        if contains_one:
            memo[(x, y)] = (memo[(x, y)][0], paths)
        else:
            memo[(x, y)] = (paths, memo[(x, y)][1])

        return paths

    memo = {}
    return dfs(0, 0, grid[0][0] == 1)

