def moveZeroes(nums):
    """
    Moves all 0's in the nums list to the end while maintaining the relative order of non-zero elements.
    """
    non_zero_index = 0  # Pointer to place the next non-zero element

    # Move all non-zero elements to the front
    for i in range(len(nums)):
        if nums[i] != 0:
            nums[non_zero_index] = nums[i]
            non_zero_index += 1

    # Fill the rest of the list with zeros
    for i in range(non_zero_index, len(nums)):
        nums[i] = 0

