import sys
import math

def preprocess(arr, n):
    # Initialize sparse table for range minimum query
    log = math.ceil(math.log2(n))
    sparse_table = [[0] * (log + 1) for _ in range(n)]

    # Initialize all minimum values for the intervals of length 1
    for i in range(n):
        sparse_table[i][0] = arr[i]

    # Compute values from smaller to bigger intervals
    j = 1
    while (1 << j) <= n:
        i = 0
        while (i + (1 << j) - 1) < n:
            if sparse_table[i][j - 1] < sparse_table[i + (1 << (j - 1))][j - 1]:
                sparse_table[i][j] = sparse_table[i][j - 1]
            else:
                sparse_table[i][j] = sparse_table[i + (1 << (j - 1))][j - 1]
            i += 1
        j += 1

    return sparse_table

def query(sparse_table, l, r):
    j = int(math.log2(r - l + 1))
    if sparse_table[l][j] <= sparse_table[r - (1 << j) + 1][j]:
        return sparse_table[l][j]
    else:
        return sparse_table[r - (1 << j) + 1][j]

def solve(n, q, arr, queries):
    sparse_table = preprocess(arr, n)
    results = []
    for query_pair in queries:
        l, r = query_pair
        results.append(query(sparse_table, l - 1, r - 1))
    return results

from collections import deque

def level_order_tree(tree, n, queries):
    # Dictionary to store the left and right children for each node
    children = {i: (-1, -1) for i in range(1, n + 1)}

    # Filling the child information
    for vi, li, ri in tree:
        children[vi] = (li, ri)

    # Level-order traversal
    level_order = []
    queue = deque([1])

    while queue:
        node = queue.popleft()
        level_order.append(node)

        left, right = children[node]
        if left != -1:
            queue.append(left)
        if right != -1:
            queue.append(right)

    # Responding to the queries
    result = []
    for k in queries:
        result.append(level_order[k - 1])

    return result

