def longest_unique_subarray(n, a):
    """
    Returns the length of the longest subarray where all elements are distinct.
    """
    max_length = 0
    start = 0
    seen = {}

    for end in range(n):
        if a[end] in seen:
            start = max(start, seen[a[end]] + 1)
        seen[a[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

