import heapq

def min_cost_to_reach_bottom_right(grid):
    n = len(grid)
    m = len(grid[0])

    if grid[0][0] == -1 or grid[n-1][m-1] == -1:
        return -1

    directions = [(1, 0), (0, 1)]  # Only right or down directions
    min_heap = [(grid[0][0], 0, 0)]  # (cost, row, col)
    costs = {(0, 0): grid[0][0]}

    while min_heap:
        current_cost, x, y = heapq.heappop(min_heap)

        if (x, y) == (n-1, m-1):
            return current_cost

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] != -1:
                next_cost = current_cost + grid[nx][ny]

                if (nx, ny) not in costs or next_cost < costs[(nx, ny)]:
                    costs[(nx, ny)] = next_cost
                    heapq.heappush(min_heap, (next_cost, nx, ny))

    return -1

def process_grids(num_tests, test_cases):
    results = []
    for i in range(num_tests):
        n, m, grid = test_cases[i]
        result = min_cost_to_reach_bottom_right(grid)
        results.append(result)
    return results

def length_of_lis_with_limit(sequence, k):
    """
    Returns the length of the longest increasing subsequence that can be achieved with
    the selected subset of elements limited by k.

    :param sequence: List of integers representing the sequence.
    :param k: Maximum number of elements that can be included in the LIS.
    :return: Length of the longest increasing subsequence with at most k elements.
    """
    n = len(sequence)

    # If k is 0, return 0 because no element can be chosen
    if k == 0:
        return 0

    # dp[i] will hold the length of the longest increasing subsequence that ends with sequence[i]
    dp = [1] * n

    # calculate the longest increasing subsequence length for each element
    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # Find the longest subsequence length from dp array that doesn't exceed k
    max_lis = 0
    for length in dp:
        if length <= k:
            max_lis = max(max_lis, length)

    # The result
    return max_lis

def parse_input_and_solve(n, k, sequence):
    return length_of_lis_with_limit(sequence, k)

