def simulate_game(n, checkpoints, queries):
    result = []
    current_position = 0

    for query in queries:
        if query[0] == "M":
            steps = int(query[1])
            current_position = (current_position + steps) % n
        elif query[0] == "R":
            result.append(checkpoints[current_position])

    return result

def max_disjoint_trees(n, m, edges):
    """
    Returns the maximum number of disjoint trees (connected components without cycles)
    that can be formed in the reef with n sections and m potential paths.
    """

    # Helper function to perform DFS and mark all reachable nodes.
    def dfs(node, visited, adj):
        stack = [node]
        while stack:
            curr = stack.pop()
            for neighbor in adj[curr]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    if m == 0:
        return n  # If there are no edges, each node is its own disjoint tree

    # Create adjacency list
    adj = {i: [] for i in range(1, n + 1)}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find all disjoint trees using DFS
    visited = set()
    num_trees = 0

    for node in range(1, n + 1):
        if node not in visited:
            num_trees += 1
            visited.add(node)
            dfs(node, visited, adj)

    return num_trees

