import math

def count_perfect_squares_between(n, m):
    """
    Returns the count of perfect squares between n and m, inclusive.
    """
    start = math.ceil(math.sqrt(n))
    end = math.floor(math.sqrt(m))
    return max(0, end - start + 1)

