from typing import List

def is_path_exists(n: int, m: int, grid: List[str]) -> str:
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return "NO"

    def dfs(x, y):
        if x < 0 or y < 0 or x >= n or y >= m or grid[x][y] == '#' or visited[x][y]:
            return False
        if x == n - 1 and y == m - 1:
            return True

        visited[x][y] = True

        # Visit neighbors (up, down, left, right)
        if (dfs(x + 1, y) or dfs(x - 1, y) or dfs(x, y + 1) or dfs(x, y - 1)):
            return True

        return False

    visited = [[False for _ in range(m)] for _ in range(n)]
    return "YES" if dfs(0, 0) else "NO"

def longest_ap_length(n, artifacts):
    """
    Returns the length of the longest subsequence that forms an arithmetic progression.
    """
    if n == 1:
        return 1

    artifacts.sort()
    dp = [{} for _ in range(n)]
    max_length = 1

    for i in range(n):
        for j in range(i):
            diff = artifacts[i] - artifacts[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2
            max_length = max(max_length, dp[i][diff])

    return max_length

