def can_sort_with_k_operations(t, test_cases):
    results = []

    for i in range(t):
        n, k = test_cases[i][0]
        sequence = test_cases[i][1]

        sorted_sequence = sorted(sequence)
        diff_count = 0

        # Count differences between the given sequence and the sorted sequence
        for j in range(n):
            if sequence[j] != sorted_sequence[j]:
                diff_count += 1

        # Each operation can fix about 2 differences (swap two elements)
        # Therefore, in k operations, we can fix up to 2 * k differences
        if diff_count <= 2 * k:
            results.append("YES")
        else:
            results.append("NO")

    return results

def search_insert(nums, target):
    """
    Determines the index of the target in the sorted array `nums` using binary search.
    If the target is not found, returns the index where it would be inserted
    to maintain the sorted order.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left

