def find_feeders(t, cases):
    results = []
    for i in range(t):
        n = cases[i][0]
        beehives = cases[i][1]
        feeders = set()

        for x, y, r in beehives:
            found_feeder = False
            for xi in range(x - r, x + r + 1):
                if found_feeder:
                    break
                for yi in range(y - r, y + r + 1):
                    if (xi - x)**2 + (yi - y)**2 <= r**2:
                        feeders.add((xi, yi))
                        found_feeder = True
                        break

        results.append(list(feeders))
    return results

def min_moves_to_gather_haystacks(n, m, grid):
    haystacks = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 'H']

    def total_moves_to_target(target_i, target_j):
        return sum(abs(hi - target_i) + abs(hj - target_j) for hi, hj in haystacks)

    min_moves = float('inf')

    for i in range(n):
        for j in range(m):
            min_moves = min(min_moves, total_moves_to_target(i, j))

    return min_moves

