def filter_and_sort_employees(n, employees, sort_by, order, filter_criteria):
    def apply_filter(employee, filter_criteria):
        if filter_criteria == 'none':
            return True
        if '>' in filter_criteria:
            field, value = filter_criteria.split('>')
            return int(employee[field]) > int(value)
        elif '<' in filter_criteria:
            field, value = filter_criteria.split('<')
            return int(employee[field]) < int(value)
        return False

    employees_list = []
    for emp in employees:
        emp_dict = {
            'id': int(emp[0]),
            'name': emp[1],
            'age': int(emp[2]),
            'salary': int(emp[3])
        }
        employees_list.append(emp_dict)

    filtered_employees = [emp for emp in employees_list if apply_filter(emp, filter_criteria)]

    if order == 'asc':
        sorted_employees = sorted(filtered_employees, key=lambda x: x[sort_by])
    else:
        sorted_employees = sorted(filtered_employees, key=lambda x: x[sort_by], reverse=True)

    if not sorted_employees:
        return ["NO EMPLOYEES"]

    return [emp['name'] for emp in sorted_employees]

