def simulate_caves(n, q, initial_creatures, events):
    caves = initial_creatures.copy()
    result = []

    for event in events:
        parts = event.split()
        event_type = int(parts[0])

        if event_type == 1:
            l, r = int(parts[1]) - 1, int(parts[2]) - 1
            for i in range(l, r + 1):
                caves[i] *= 2
        elif event_type == 2:
            l, r = int(parts[1]) - 1, int(parts[2]) - 1
            caves[r] += caves[l]
            caves[l] = 0
        elif event_type == 3:
            l = int(parts[1]) - 1
            result.append(caves[l])

    return result

