def longest_chain_length(arr):
    """
    Given an array of unique integers, returns the length of the longest chain
    where each integer in the chain is a multiple of the previous integer.
    """
    arr.sort()
    longest_chain = [1] * len(arr)

    for i in range(len(arr)):
        for j in range(i):
            if arr[i] % arr[j] == 0:
                longest_chain[i] = max(longest_chain[i], longest_chain[j] + 1)

    return max(longest_chain)

def solve_cases(t, cases):
    results = []
    for i in range(t):
        n = cases[i][0]
        arr = cases[i][1]
        result = longest_chain_length(arr)
        results.append(result)
    return results

