def count_unique_partitions(n):
    """
    Returns the number of unique ways to partition n stars into groups where each group has at least 2 stars.
    """
    if n < 4:
        return 0

    # Dictionary to store unique pairs, to ensure order does not matter
    partitions = {}

    # Iterate over each possible group size
    for i in range(2, n):
        for j in range(i, n):
            if i + j == n:
                partitions[(i, j)] = True

    return len(partitions)

