def max_sum_with_constraints(n, d, sequence):
    dp = [0] * n

    for i in range(n):
        dp[i] = sequence[i]
        if i >= d:
            dp[i] += max(dp[:i-d+1])

    return max(dp)

def max_sum_of_subsequences(t, test_cases):
