def longest_vowel_substring(s):
    """
    This function returns the length of the longest substring in the given
    string 's' that contains only vowels. Vowels are 'a', 'e', 'i', 'o', 'u'.
    """
    vowels = {'a', 'e', 'i', 'o', 'u'}
    max_length = 0
    current_length = 0

    for char in s:
        if char in vowels:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
            current_length = 0

    # Check one last time in case the longest substring ends at the end of the string
    if current_length > max_length:
        max_length = current_length

    return max_length

