def can_form_hill_sequence(n, sequence):
    """
    Determines if the given sequence can be rearranged to form exactly one Hill Sequence.
    """
    if n == 1:
        return "YES"

    sequence.sort()
    for i in range(n-1):
        if sequence[i] == sequence[i+1]:
            return "NO"

    return "YES"

