def convert_to_base(n, k):
    """
    Convert a decimal (base 10) number n to a given base k (2 <= k <= 36).
    """
    if n == 0:
        return "0"

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []

    while n > 0:
        remainder = n % k
        result.append(digits[remainder])
        n //= k

    return ''.join(result[::-1])

