def code_breaking_power(arr):
    """
    Returns the code-breaking power for each integer in the array,
    defined as the length of the longest increasing subsequence ending at that integer.
    """
    n = len(arr)
    lis = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    return lis

