def max_path_sum(n, values, passages):
    from collections import defaultdict
    import sys

    sys.setrecursionlimit(10001)

    def dfs(node, parent):
        current_sum = values[node]
        max_sum = 0
        for neighbor in tree[node]:
            if neighbor == parent:
                continue
            max_sum = max(max_sum, dfs(neighbor, node))
        return current_sum + max_sum

    if n == 1:
        return values[0]

    tree = defaultdict(list)
    for u, v in passages:
        tree[u-1].append(v-1)
        tree[v-1].append(u-1)

    max_sum = -sys.maxsize
    for i in range(n):
        max_sum = max(max_sum, dfs(i, -1))
    return max_sum

