def maximal_rectangle(matrix):
    if not matrix:
        return 0

    m, n = len(matrix), len(matrix[0])
    # Transform the input matrix to a heights matrix
    heights = [0] * n
    max_area = 0

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 0:
                heights[j] += 1
            else:
                heights[j] = 0
        # Calculate the maximum area for each row of heights
        max_area = max(max_area, largest_rectangle_area(heights))

    return max_area


def largest_rectangle_area(heights):
    stack = []
    max_area = 0
    heights.append(0)

    for i in range(len(heights)):
        while stack and heights[i] < heights[stack[-1]]:
            h = heights[stack.pop()]
            w = i if not stack else i - stack[-1] - 1
            max_area = max(max_area, h * w)
        stack.append(i)

    heights.pop()
    return max_area

