def min_changes_to_distinct_elements(n, k, a):
    """
    Returns the minimum number of changes needed to make the array `a`
    contain exactly `k` distinct elements or -1 if it is impossible.
    """
    from collections import Counter

    unique_elements = set(a)

    if len(unique_elements) == k:
        return 0

    if len(unique_elements) > k:
        return 0

    if len(unique_elements) < k:
        if n >= k:
            return k - len(unique_elements)
        else:
            return -1

    return -1

