def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while (i * i) <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def count_special_pairs(arr):
    count = 0
    n = len(arr)
    for i in range(n):
        if is_prime(arr[i]):
            for j in range(i+1, n):
                if arr[i] < arr[j]:
                    count += 1
    return count

def longest_substring_identical_chars(s):
    """
    Returns the length of the longest substring with identical characters.
    """
    if not s:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            current_len += 1
        else:
            max_len = max(max_len, current_len)
            current_len = 1

    max_len = max(max_len, current_len)
    return max_len

