def longest_1_run(sequences):
    """
    Given a list of binary sequences, compute the length of the longest 1-run for each sequence.
    """
    results = []
    for sequence in sequences:
        max_run = 0
        current_run = 0

        for char in sequence:
            if char == '1':
                current_run += 1
                if current_run > max_run:
                    max_run = current_run
            else:
                current_run = 0

        results.append(max_run)

    return results

