import heapq

def dijkstra(graph, start, n):
    """
    Runs Dijkstra's algorithm to find the shortest path from the
    start node to all other nodes in the graph.
    """
    distances = {i: float('inf') for i in range(1, n+1)}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def zelda_cave(n, m, q, tunnels, queries):
    results = []

    graph = {i: [] for i in range(1, n+1)}
    for vi, ui, wi in tunnels:
        graph[vi].append((ui, wi))
        graph[ui].append((vi, wi))

    for si, ti, dvr in queries:
        distances = dijkstra(graph, si, n)
        if distances[ti] <= dvr:
            results.append("Yes")
        else:
            results.append("No")

    return results

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes(l, r):
    """Return the sum of all prime numbers in the range [l, r]."""
    return sum(n for n in range(l, r + 1) if is_prime(n))

