def find_longest_binary_subarray(t, test_cases):
    results = []
    for s in test_cases:
        max_length = 1
        current_length = 1
        for i in range(1, len(s)):
            if s[i] == s[i-1]:
                current_length += 1
            else:
                max_length = max(max_length, current_length)
                current_length = 1
        max_length = max(max_length, current_length)
        results.append(max_length)
