def valid_mountain_array(arr):
    """
    Check if the given list of integers is a valid mountain array.
    """
    if len(arr) < 3:
        return False

    i = 1

    # Walk up
    while i < len(arr) and arr[i] > arr[i - 1]:
        i += 1

    # Peak can't be first or last
    if i == 1 or i == len(arr):
        return False

    # Walk down
    while i < len(arr) and arr[i] < arr[i - 1]:
        i += 1

    return i == len(arr)

