def smallest_palindrome(s):
    n = len(s)
    s = list(s)

    for i in range(n // 2):
        if s[i] == '?' and s[n - 1 - i] == '?':
            s[i] = s[n - 1 - i] = 'a'
        elif s[i] == '?':
            s[i] = s[n - 1 - i]
        elif s[n - 1 - i] == '?':
            s[n - 1 - i] = s[i]
        elif s[i] != s[n - 1 - i]:
            return -1

    if n % 2 == 1 and s[n // 2] == '?':
        s[n // 2] = 'a'

    return ''.join(s)

