def lis_lds(arr):
    """
    Returns the length of the longest increasing subsequence (LIS)
    and the length of the longest decreasing subsequence (LDS)
    of the given array.
    """
    N = len(arr)

    if N == 0:
        return (0, 0)

    # Calculate LIS
    lis_dp = [1] * N
    for i in range(1, N):
        for j in range(i):
            if arr[i] > arr[j]:
                lis_dp[i] = max(lis_dp[i], lis_dp[j] + 1)

    # Calculate LDS
    lds_dp = [1] * N
    for i in range(1, N):
        for j in range(i):
            if arr[i] < arr[j]:
                lds_dp[i] = max(lds_dp[i], lds_dp[j] + 1)

    # The longest lengths
    lis_length = max(lis_dp)
    lds_length = max(lds_dp)

    return (lis_length, lds_length)

