def rearrange_slots(n, slots):
    odds = [num for num in slots if num % 2 != 0]
    evens = [num for num in slots if num % 2 == 0]

    if abs(len(odds) - len(evens)) > 1:
        return "NO", []

    result = []
    if len(odds) >= len(evens):
        turn = 'odd'
    else:
        turn = 'even'

    while odds or evens:
        if turn == 'odd' and odds:
            result.append(odds.pop())
            turn = 'even'
        elif turn == 'even' and evens:
            result.append(evens.pop())
            turn = 'odd'

    return "YES", result

def can_reach_end(grid):
    n, m = len(grid), len(grid[0])
    if grid[0][0] == '*' or grid[n-1][m-1] == '*':
        return False

    # Use Dynamic Programming to mark reachable cells
    dp = [[False for _ in range(m)] for _ in range(n)]
    dp[0][0] = True

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if i > 0:
                    dp[i][j] = dp[i][j] or dp[i-1][j]
                if j > 0:
                    dp[i][j] = dp[i][j] or dp[i][j-1]

    return dp[n-1][m-1]

