def preprocess_count(s):
    count = [[0] * 26 for _ in range(len(s) + 1)]
    for i, char in enumerate(s):
        count[i + 1] = count[i][:]  # Create a copy of the previous counts
        count[i + 1][ord(char) - ord('a')] += 1
    return count

def solve_queries(n, s1, s2, queries):
    count_s1 = preprocess_count(s1)
    count_s2 = preprocess_count(s2)

    results = []
    for l1, r1, k in queries:
        found = False
        for c in range(26):
            count_c_s1 = count_s1[r1][c] - count_s1[l1 - 1][c]
            count_c_s2 = count_s2[r1][c] - count_s2[l1 - 1][c]
            if count_c_s1 > 0 and count_c_s2 >= k:
                found = True
                break
        if found:
            results.append("YES")
        else:
            results.append("NO")

    return results

