from collections import deque

def max_customers(n, m, grid):
    """
    Determines the maximum number of customers that can receive a package
    from the nearest warehouse.
    """

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(warehouses):
        distance = [[float('inf')]*m for _ in range(n)]
        queue = deque(warehouses)

        for wx, wy in warehouses:
            distance[wx][wy] = 0

        while queue:
            x, y = queue.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and distance[nx][ny] > distance[x][y] + 1:
                    distance[nx][ny] = distance[x][y] + 1
                    queue.append((nx, ny))

        return distance

    warehouses = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 'W']
    customers = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 'C']

    if not warehouses or not customers:
        return 0

    min_distance = bfs(warehouses)

    count = 0
    for cx, cy in customers:
        if min_distance[cx][cy] != float('inf'):
            count += 1

    return count

