def illuminate_grid(n, m, q, grid, operations):
    for operation in operations:
        r1, c1, r2, c2, k = operation
        for i in range(r1 - 1, r2):
            for j in range(c1 - 1, c2):
                grid[i][j] += k
    return grid

# We can define a function to parse input and encapsulate the entire process:
def process_illumination(input_str):
    lines = input_str.strip().split('\n')
    n, m, q = map(int, lines[0].split())
    grid = []
    for i in range(1, n + 1):
        grid.append(list(map(int, lines[i].split())))
    operations = []
    for i in range(n + 1, n + 1 + q):
        operations.append(list(map(int, lines[i].split())))

    result_grid = illuminate_grid(n, m, q, grid, operations)

    output = '\n'.join(' '.join(map(str, row)) for row in result_grid)
    return output

