def count_subarrays_with_sum_between(arr, l, r):
    """
    Returns the number of subarrays where the sum of elements is between `l` and `r` inclusive.
    """
    n = len(arr)
    count = 0

    for start in range(n):
        current_sum = 0
        for end in range(start, n):
            current_sum += arr[end]
            if l <= current_sum <= r:
                count += 1
            elif current_sum > r:
                break
    return count

