def max_subarray_sum(arr):
    """
    Returns the maximum subarray sum of the given array using Kadane's algorithm.
    """
    if not arr:
        return 0

    max_ending_here = max_so_far = arr[0]
    for x in arr[1:]:
        max_ending_here = max(x, max_ending_here + x)
        max_so_far = max(max_so_far, max_ending_here)
    return max_so_far

def process_operations(n, operations):
    """
    Processes a sequence of operations and returns the results of the QUERY operations.
    """
    result = []
    arr = []

    for operation in operations:
        if operation.startswith("ADD"):
            _, x = operation.split()
            x = int(x)
            arr.append(x)
        elif operation == "REMOVE":
            if arr:
                arr.pop()
        elif operation == "QUERY":
            result.append(max_subarray_sum(arr))

    return result

