def find_minimum_cost(m, combo_meals, n, customer_orders):
    combos = {}
    for combo in combo_meals:
        price = int(combo[0])
        items = tuple(sorted(combo[1:]))
        if items not in combos or combos[items] > price:
            combos[items] = price

    results = []
    for order in customer_orders:
        sorted_order = tuple(sorted(order))
        if sorted_order in combos:
            results.append(combos[sorted_order])
        else:
            results.append(-1)

    return results

def unique_paths_with_obstacles(n, m, blocked):
    """
    Returns the number of unique paths from top-left to bottom-right of a grid
    with given dimensions `n x m` while avoiding blocked cells.
    """

    # Create a grid initialized to 0s
    grid = [[0] * m for _ in range(n)]

    # Block the cells
    for (x, y) in blocked:
        grid[x-1][y-1] = -1  # convert to 0-indexed and mark as blocked

    # Start point should be 1 if it's not blocked
    if grid[0][0] == -1:
        return 0
    else:
        grid[0][0] = 1

    # Fill the first column
    for i in range(1, n):
        if grid[i][0] == -1:
            grid[i][0] = 0
        else:
            grid[i][0] = grid[i-1][0]

    # Fill the first row
    for j in range(1, m):
        if grid[0][j] == -1:
            grid[0][j] = 0
        else:
            grid[0][j] = grid[0][j-1]

    # Fill the rest of the grid
    for i in range(1, n):
        for j in range(1, m):
            if grid[i][j] == -1:
                grid[i][j] = 0
            else:
                if grid[i-1][j] != -1:
                    grid[i][j] += grid[i-1][j]
                if grid[i][j-1] != -1:
                    grid[i][j] += grid[i][j-1]

    return grid[n-1][m-1]

