import math

def calculate_mst_length(n, coordinates):
    def distance(coord1, coord2):
        return math.sqrt((coord1[0] - coord2[0]) ** 2 + (coord1[1] - coord2[1]) ** 2)

    edges = []

    for i in range(n):
        for j in range(i + 1, n):
            dist = distance(coordinates[i], coordinates[j])
            edges.append((dist, i, j))

    edges.sort()

    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootX] = rootY

    total_length = 0
    for edge in edges:
        dist, u, v = edge
        if find(u) != find(v):
            union(u, v)
            total_length += dist

    return round(total_length)

def main(data):
    lines = data.strip().split('\n')
    n = int(lines[0])
    coordinates = [tuple(map(int, line.split())) for line in lines[1:]]
    return calculate_mst_length(n, coordinates)

