def theater_seating(n, m, requests):
    # Initialize the seating arrangement
    seats = [[0] * m for _ in range(n)]
    results = []

    for request in requests:
        request = request.split()
        operation = int(request[0])

        if operation == 1:  # Reserve seats
            x1, y1, x2, y2 = map(int, request[1:])
            for i in range(x1 - 1, x2):
                for j in range(y1 - 1, y2):
                    seats[i][j] = 1

        elif operation == 2:  # Release seats
            x1, y1, x2, y2 = map(int, request[1:])
            for i in range(x1 - 1, x2):
                for j in range(y1 - 1, y2):
                    seats[i][j] = 0

        elif operation == 3:  # Query seat
            x, y = map(int, request[1:])
            if seats[x-1][y-1] == 1:
                results.append('Yes')
            else:
                results.append('No')

    return results

def min_manhattan_distance(n, d, sensors):
    def manhattan_dist(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    if n == 1:
        return 2 * d

    sensors.sort()

    max_min_dist = 0
    for i in range(n):
        x1, y1 = sensors[i]
        for j in range(i + 1, n):
            x2, y2 = sensors[j]

            covered = True
            for k in range(n):
                xk, yk = sensors[k]
                if manhattan_dist((x1, y1), (xk, yk)) > d and manhattan_dist((x2, y2), (xk, yk)) > d:
                    covered = False
                    break

            if covered:
                max_min_dist = max(max_min_dist, manhattan_dist((x1, y1), (x2, y2)))

    if max_min_dist > 0:
        return max_min_dist
    else:
        return -1

