def count_paths_to_destination(grid):
    n = len(grid)
    m = len(grid[0])

    # Handle the start point if it's an obstacle
    if grid[0][0] == -1:
        return 0

    # Create a dp array with the same size as the grid
    dp = [[0] * m for _ in range(n)]

    # Initialize the start point
    dp[0][0] = 1

    # Fill the dp array
    for i in range(n):
        for j in range(m):
            if grid[i][j] == -1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    # The value at the bottom-right corner will be our answer
    return dp[n-1][m-1]

