def min_edges_to_connect_graph(n, m, edges):
    from collections import defaultdict, deque

    if n == 1:
        return 0

    # Create adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    def bfs(start):
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    visited = set()
    components = 0

    for vertex in range(1, n + 1):
        if vertex not in visited:
            bfs(vertex)
            components += 1

    # To connect all components into a single connected graph we need (components - 1) edges
    return components - 1

