def can_plant_flowers(n, m, k, special_intersections):
    """
    Determine if flowers can be planted on all special intersections without forming a rectangle.
    """
    if k < 4:
        return "YES"

    # Create a dictionary to keep track of columns in each row where flowers exist
    row_to_columns = {}

    for (x, y) in special_intersections:
        if x not in row_to_columns:
            row_to_columns[x] = set()
        row_to_columns[x].add(y)

    # Check for any combination of 4 points forming a rectangle
    columns_checked = set()
    for row in row_to_columns:
        columns_in_row = list(row_to_columns[row])
        columns_in_row.sort()

        for i in range(len(columns_in_row)):
            for j in range(i + 1, len(columns_in_row)):
                col1 = columns_in_row[i]
                col2 = columns_in_row[j]
                if (col1, col2) in columns_checked:
                    return "NO"
                columns_checked.add((col1, col2))
    return "YES"

