def num_paths(n, m, grid):
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return 0

    dp = [[0]*m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

def reachable_stones_to_n(n):
    """
    Determines the stones from which a frog can start and reach the last stone n.

    :param n: The total number of stones.
    :return: A list of stone numbers that can reach stone n or -1 if none can.
    """
    if n == 1:
        return [1]

    result = []
    for i in range(1, n + 1):
        if n % i == 0:
            result.append(i)

    return result if result else [-1]

