def find_maximum_toll_revenue(tolls):
    n = len(tolls)

    # Prepare edges from the toll matrix
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            edges.append((tolls[i][j], i, j))

    # Sort edges by toll in descending order
    edges.sort(reverse=True, key=lambda edge: edge[0])

    # Helper function to find the parent of a node (with path compression)
    def find(parent, i):
        if parent[i] == i:
            return i
        else:
            return find(parent, parent[i])

    # Helper function to do union of two subsets
    def union(parent, rank, x, y):
        rootX = find(parent, x)
        rootY = find(parent, y)

        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1

    # Kruskal's Algorithm to select the maximum toll edges in descending order
    parent = [i for i in range(n)]
    rank = [0] * n

    max_revenue = 0
    edges_used = 0

    for toll, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            max_revenue += toll
            edges_used += 1
            if edges_used == n - 1:
                break

    return max_revenue

