def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i ** 2 <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def can_make_move(array):
    n = len(array)
    for i in range(n):
        for j in range(i, n):
            if is_prime(sum(array[i:j+1])):
                return True
    return False

def optimal_game_winner(n, array):
    turn = 0  # 0 for Player1, 1 for Player2
    while can_make_move(array):
        found_move = False
        for i in range(n):
            for j in range(i, n):
                if is_prime(sum(array[i:j+1])):
                    array = array[:i] + array[j+1:]
                    found_move = True
                    break
            if found_move:
                break
        turn = 1 - turn  # Switch turns
    return "Player2" if turn == 0 else "Player1"

# Example usage:
# n = 4
# array = [2, 3, 4, 5]
# print(optimal_game_winner(n, array))  # Output: Player1

