def rotate_matrix_90_degrees(matrix):
    n = len(matrix)
    rotated_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            rotated_matrix[j][n-1-i] = matrix[i][j]
    return rotated_matrix

def row_differences(rotated_matrix):
    differences = []
    for row in rotated_matrix:
        row_max = max(row)
        row_min = min(row)
        differences.append(row_max - row_min)
    return differences

def matrix_operations(n, matrix):
    rotated_matrix = rotate_matrix_90_degrees(matrix)
    return row_differences(rotated_matrix)

