def find_min_repairs(t, test_cases):
    """
    Determines the minimum number of edges to repair to make the tree fully connected.

    :param t: Number of test cases
    :param test_cases: List of test cases
    :return: List of results for each test case
    """
    def dfs(node, graph, visited):
        stack = [node]
        visited[node] = True
        while stack:
            u = stack.pop()
            for v in graph.get(u, []):
                if not visited[v]:
                    visited[v] = True
                    stack.append(v)

    results = []
    for case in test_cases:
        n, edges, m, damaged = case
        graph = {i: [] for i in range(1, n + 1)}
        damaged_set = set(damaged)

        for u, v in edges:
            if (u, v) not in damaged_set and (v, u) not in damaged_set:
                graph[u].append(v)
                graph[v].append(u)

        visited = {i: False for i in range(1, n + 1)}
        components = 0

        for i in range(1, n + 1):
            if not visited[i]:
                components += 1
                dfs(i, graph, visited)

        if components == 1:
            results.append(0)
        elif components - 1 <= m:
            results.append(components - 1)
        else:
            results.append(-1)

    return results

