def is_possible(donations):
    last_end = -1

    for s1, e1, s2, e2 in donations:
        if e1 < s2 or e2 < s1:
            chosen_interval = min(e1, e2)
        elif last_end < s1 and last_end < s2:  # Ensure no overlap
            chosen_interval = min([e for e in [e1, e2] if e > last_end] + [float('inf')])
        else:
            return "Impossible"

        last_end = chosen_interval

    return "Possible"

