def has_subarray_with_sum(arr, n, k):
    """
    Returns 'YES' if there exists a subarray that adds up to k, otherwise 'NO'
    """
    current_sum = 0
    sums_dict = {}

    for num in arr:
        current_sum += num

        if current_sum == k:
            return "YES"

        if (current_sum - k) in sums_dict:
            return "YES"

        sums_dict[current_sum] = True

    return "NO"

