from collections import defaultdict, deque

def is_strongly_connected(n, provinces):
    def bfs(start, graph):
        visited = set()
        queue = deque([start])
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                queue.extend(graph[node])
        return len(visited) == len(graph)

    def transpose(graph):
        transposed = defaultdict(list)
        for u in graph:
            for v in graph[u]:
                transposed[v].append(u)
        return transposed

    results = []
    for province in provinces:
        v, e, c, edges = province
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)

        forward_check = bfs(c, graph)
        if not forward_check:
            results.append("NO")
            continue

        transposed_graph = transpose(graph)
        backward_check = bfs(c, transposed_graph)

        if forward_check and backward_check:
            results.append("YES")
        else:
            results.append("NO")

    return results

