def length_of_lis(sequence):
    """
    Returns the length of the longest increasing subsequence in the given sequence of integers.

    :param sequence: List of integers
    :return: Length of the longest increasing subsequence
    """
    if not sequence:
        return 0

    from bisect import bisect_left

    lis = []
    for num in sequence:
        pos = bisect_left(lis, num)
        if pos == len(lis):
            lis.append(num)
        else:
            lis[pos] = num

    return len(lis)

