def longest_unique_path(grid):
    n, m = len(grid), len(grid[0])
    def dfs(x, y, visited):
        max_length = len(visited)
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] not in visited:
                max_length = max(max_length, dfs(nx, ny, visited | {grid[nx][ny]}))
        return max_length

    max_path = 0
    for i in range(n):
        for j in range(m):
            max_path = max(max_path, dfs(i, j, {grid[i][j]}))
    return max_path

