def dfs(node, graph, visited):
    """
    Depth-First Search (DFS) to traverse the graph and mark all nodes in the same connected component.
    """
    stack = [node]
    while stack:
        current = stack.pop()
        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                stack.append(neighbor)

