def count_connected_components(n, m, grid):
    def dfs(r, c):
        if r < 0 or r >= n or c < 0 or c >= m or grid[r][c] == '#' or visited[r][c]:
            return
        visited[r][c] = True
        dfs(r-1, c)
        dfs(r+1, c)
        dfs(r, c-1)
        dfs(r, c+1)

    visited = [[False for _ in range(m)] for _ in range(n)]
    count = 0

    for r in range(n):
        for c in range(m):
            if grid[r][c] == '.' and not visited[r][c]:
                dfs(r, c)
                count += 1

    return count

def min_operations_to_zero(matrix):
    """
    Returns the minimum number of operations to make all elements of the matrix 0.
    If it's not possible, return -1.
    """
    n = len(matrix)
    m = len(matrix[0])
    operations = 0

    # Iterate over every 2x2 submatrix in the grid
    for i in range(n - 1):
        for j in range(m - 1):
            # If there is '1' in the 2x2 submatrix starting at (i, j)
            if matrix[i][j] == 1:
                # Perform operation, i.e., flip the 2x2 submatrix starting at (i, j)
                for x in range(2):
                    for y in range(2):
                        if i + x < n and j + y < m:
                            matrix[i + x][j + y] ^= 1
                operations += 1

    # Check if the entire matrix is now zero
    for i in range(n):
        for j in range(m):
            if matrix[i][j] == 1:
                return -1

    return operations

