def can_travel_in_order(n, m, roads, k, travel_plan):
    from collections import defaultdict, deque

    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    for road in roads:
        u, v, p = road
        graph[u].append(v)
        graph[v].append(u)

    # Function to run BFS
    def bfs(start, end):
        queue = deque([start])
        visited = set()
        while queue:
            current_city = queue.popleft()
            if current_city == end:
                return True
            for neighbor in graph[current_city]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    # Check if each consecutive pair in the travel plan can be traveled
    for i in range(k - 1):
        if not bfs(travel_plan[i], travel_plan[i + 1]):
            return "NO"

    return "YES"

