from datetime import datetime, timedelta

def parse_time(time_str):
    return datetime.strptime(time_str, "%H:%M")

def total_working_time(n, logs):
    work_times = {}
    break_times = {}

    for log in logs:
        parts = log.split()
        date = parts[0]
        employee_id = parts[1]
        time_type = parts[2]

        if time_type.startswith("start"):
            start_time = parse_time(parts[2].split(":")[1] + ":" + parts[2].split(":")[2])
            stop_time = parse_time(parts[3].split(":")[1] + ":" + parts[3].split(":")[2])
            duration = stop_time - start_time

            if employee_id not in work_times:
                work_times[employee_id] = timedelta()
            work_times[employee_id] += duration

        elif time_type.startswith("break_start"):
            break_start_time = parse_time(parts[2].split(":")[1] + ":" + parts[2].split(":")[2])
            break_stop_time = parse_time(parts[3].split(":")[1] + ":" + parts[3].split(":")[2])
            break_duration = break_stop_time - break_start_time

            if employee_id not in break_times:
                break_times[employee_id] = timedelta()
            break_times[employee_id] += break_duration

    result = []

    for employee_id, work_time in work_times.items():
        total_break_time = break_times.get(employee_id, timedelta())
        actual_work_time = work_time - total_break_time

        hours, remainder = divmod(actual_work_time.seconds, 3600)
        minutes = remainder // 60
        result.append(f"{employee_id}: {hours:02}:{minutes:02}")

    return result

def generate_spiral_order_matrix(n):
    matrix = [[0] * n for _ in range(n)]
    current_number = 1

    top, bottom = 0, n - 1
    left, right = 0, n - 1

    while top <= bottom and left <= right:
        for col in range(left, right + 1):
            matrix[top][col] = current_number
            current_number += 1
        top += 1

        for row in range(top, bottom + 1):
            matrix[row][right] = current_number
            current_number += 1
        right -= 1

        if top <= bottom:
            for col in range(right, left - 1, -1):
                matrix[bottom][col] = current_number
                current_number += 1
            bottom -= 1

        if left <= right:
            for row in range(bottom, top - 1, -1):
                matrix[row][left] = current_number
                current_number += 1
            left += 1

    return matrix

def convert(s: str, numRows: int) -> str:
    if numRows == 1 or numRows >= len(s):
        return s

    # Create an array to hold strings for each row
    rows = [""] * numRows
    current_row = 0
    going_down = False

    # Iterate over each character and place it in the correct row
    for char in s:
        rows[current_row] += char
        if current_row == 0 or current_row == numRows - 1:
            going_down = not going_down
        current_row += 1 if going_down else -1

    # Concatenate all row strings and return
    return "".join(rows)

