def can_reach_with_k_steps(n, m, k, grid):
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return "NO"

    def dfs(x, y, remaining_k):
        if x == n-1 and y == m-1:
            return remaining_k == 0

        if remaining_k < 0:
            return False

        if (x, y) in visited:
            return False

        visited.add((x, y))

        if x + 1 < n and grid[x + 1][y] == '.' and dfs(x + 1, y, remaining_k - 1):
            return True

        if y + 1 < m and grid[x][y + 1] == '.' and dfs(x, y + 1, remaining_k - 1):
            return True

        visited.remove((x, y))
        return False

    visited = set()
    if dfs(0, 0, k - 1):
        return "YES"
    else:
        return "NO"

