def find_road_to_build(n, adjacency_matrix):
    import itertools

    def floyd_warshall(n, dist):
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]
        return dist

    # Initialize the distance matrix
    dist = [[float('inf')] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if adjacency_matrix[i][j] == 1:
                dist[i][j] = 1
            if i == j:
                dist[i][j] = 0

    # Perform Floyd-Warshall algorithm to find all-pairs shortest paths
    dist = floyd_warshall(n, dist)

    # Find the missing edge
    for u, v in itertools.combinations(range(n), 2):
        if adjacency_matrix[u][v] == 0:
            missing_edge = (u, v)
            break

    # Add the missing edge and recompute distances
    u, v = missing_edge
    new_dist = [[dist[i][j] for j in range(n)] for i in range(n)]
    new_dist[u][v] = new_dist[v][u] = 1
    new_dist = floyd_warshall(n, new_dist)

    # Find the longest shortest path in the new distance matrix
    longest_path = max(max(row) for row in dist)

    return (u + 1, v + 1)

