def minimum_difference(n, skill_levels):
    total_sum = sum(skill_levels)
    target = total_sum // 2
    dp = [0] * (target + 1)

    for skill in skill_levels:
        for j in range(target, skill - 1, -1):
            dp[j] = max(dp[j], dp[j - skill] + skill)

    sum1 = dp[target]
    sum2 = total_sum - sum1
    return abs(sum1 - sum2)

