def longest_continuous_sequence(n, readings):
    # Edge case: if n is 0, there are no readings
    if n == 0:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, n):
        if readings[i] == readings[i - 1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    max_length = max(max_length, current_length)
    return max_length

