def has_pair_with_sum(n, t, arr):
    """
    Returns "YES" if there are two distinct elements in the array whose sum is exactly t, otherwise "NO".
    """
    seen = set()
    for num in arr:
        if t - num in seen:
            return "YES"
        seen.add(num)
    return "NO"

