from collections import deque

def shortest_path(n, m, grid):
    def is_in_bounds(x, y):
        return 0 <= x < n and 0 <= y < m

    def is_traversable(x, y):
        return grid[x][y] in '.L'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    if not is_traversable(0, 0) or not is_traversable(n-1, m-1):
        return -1

    queue = deque([(0, 0, 1)])  # (x, y, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == (n-1, m-1):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_in_bounds(nx, ny) and is_traversable(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

def min_steps_to_transform(s, t):
    """
    Calculates the minimal number of steps required to transform string s into string t.
    """
    # Ensure both strings have the same length
    if len(s) != len(t):
        raise ValueError("The lengths of s and t should be equal")

    # Count the differences between corresponding characters of s and t
    steps = 0
    for char_s, char_t in zip(s, t):
        if char_s != char_t:
            steps += 1

    return steps

