def min_max_distance(n, k, cities):
    cities.sort()

    def feasible(distance):
        stops = 1
        last_stop = cities[0]
        for i in range(1, n):
            if cities[i] - last_stop >= distance:
                stops += 1
                last_stop = cities[i]
            if stops >= k:
                return True
        return False

    low, high = 0, cities[-1] - cities[0]

    while low < high:
        mid = (low + high) // 2
        if feasible(mid + 1):
            low = mid + 1
        else:
            high = mid

    return low

