def card_game(n, cards):
    """
    Returns the sum of the values of the cards collected by Alice and Bob, respectively.
    """
    cards.sort(reverse=True)
    alice_sum = 0
    bob_sum = 0

    for i in range(n):
        if i % 2 == 0:
            alice_sum += cards[i]
        else:
            bob_sum += cards[i]

    return alice_sum, bob_sum

