def find_common_point(t, cases):
    result = []
    for i in range(t):
        n, intervals = cases[i]
        case_result = []
        for interval in intervals:
            a_i, b_i, c_i, d_i = interval
            if max(a_i, c_i) <= min(b_i, d_i):
                case_result.append(str(min(b_i, d_i)))
            else:
                case_result.append("-1")
        result.append("\n".join(case_result))
    return "\n".join(result)

