def longest_increasing_chain(n, lanterns):
    """
    Returns the length of the longest strictly increasing chain of lanterns.
    """
    if n == 0:
        return 0

    from bisect import bisect_left

    # List to maintain the increasing subsequence
    lis = []

    for brightness in lanterns:
        pos = bisect_left(lis, brightness)
        if pos < len(lis):
            lis[pos] = brightness
        else:
            lis.append(brightness)

    return len(lis)

