import math

def count_flower_arrangements(n):
    """
    Returns the number of valid flower arrangements such that no two adjacent flowers are of the same type.
    This is equivalent to finding the number of permutations of n unique items.
    """
    if n == 1:
        return 1
    return math.factorial(n)

