def is_subgrid_sum_divisible_by_k(H, W, K, grid):
    def get_subgrid_sum(x1, y1, x2, y2):
        return prefix_sum[x2+1][y2+1] - prefix_sum[x1][y2+1] - prefix_sum[x2+1][y1] + prefix_sum[x1][y1]

    # Initialize the prefix sum array
    prefix_sum = [[0] * (W + 1) for _ in range(H + 1)]

    # Compute the prefix sum array
    for i in range(1, H + 1):
        for j in range(1, W + 1):
            prefix_sum[i][j] = (grid[i-1][j-1]
                                + prefix_sum[i-1][j]
                                + prefix_sum[i][j-1]
                                - prefix_sum[i-1][j-1])

    # Check all possible subgrids
    for x1 in range(H):
        for y1 in range(W):
            for x2 in range(x1, H):
                for y2 in range(y1, W):
                    subgrid_sum = get_subgrid_sum(x1, y1, x2, y2)
                    if subgrid_sum % K == 0:
                        return "YES"

    return "NO"

def can_cover_exactly(L, ri, si):
    """
    Checks if Alice can exactly cover the length L using the running and resting pattern (ri, si).
    """
    if L % ri == 0:
        return "Yes"
    session_length = 2 * ri + si
    k = (L - ri) // session_length
    if k >= 0 and k * session_length + ri == L:
        return "Yes"
    return "No"

def check_patterns(t, patterns):
    results = []
    for L, ri, si in patterns:
        results.append(can_cover_exactly(L, ri, si))
    return results

def count_divisible_pairs(n, k, arr):
    """
    Returns the number of unique pairs (i, j) such that arr[i] + arr[j] is divisible by k and i < j.
    """
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if (arr[i] + arr[j]) % k == 0:
                count += 1
    return count

