def num_ways_to_fill_2xn_grid(n):
    MOD = 1000000007

    if n == 1:
        return 1
    elif n == 2:
        return 2

    dp = [0] * (n + 1)
    dp[1], dp[2] = 1, 2

    for i in range(3, n + 1):
        dp[i] = (dp[i-1] + dp[i-2]) % MOD

    return dp[n]

def min_difference_partition(heights):
    """
    Function to find the minimum possible difference between the sum of
    heights of the towers in the two groups.

    :param heights: List of integers representing the heights of the towers
    :returns: Minimum possible difference between the sums of two groups
    """
    total_sum = sum(heights)
    n = len(heights)

    # DP array to keep track of possible sums
    dp = [False] * (total_sum + 1)
    dp[0] = True

    for height in heights:
        for j in range(total_sum, height-1, -1):
            if dp[j - height]:
                dp[j] = True

    max_possible_sum = total_sum // 2
    for i in range(max_possible_sum, -1, -1):
        if dp[i]:
            return total_sum - 2 * i

