def can_split_coins(n, coins):
    total_sum = sum(coins)
    if total_sum % 2 != 0:
        return "NO"

    target_sum = total_sum // 2
    dp = [False] * (target_sum + 1)
    dp[0] = True

    for coin in coins:
        for j in range(target_sum, coin - 1, -1):
            dp[j] = dp[j] or dp[j - coin]

    return "YES" if dp[target_sum] else "NO"

