def transform_array(arr):
    """
    For each element in the array, if it is an even number, divide it by 2.
    If it is an odd number, multiply it by 3 and add 1.
    Returns the resulting array after all operations are performed.
    """
    result = []
    for num in arr:
        if num % 2 == 0:
            result.append(num // 2)
        else:
            result.append(num * 3 + 1)
    return result

