def count_cycles(n, permutation):
    visited = [False] * n
    cycle_count = 0

    for i in range(n):
        if not visited[i]:
            cycle_count += 1
            current = i
            while not visited[current]:
                visited[current] = True
                current = permutation[current] - 1

    return cycle_count

