def num_paths(n, m, board):
    MOD = 10**9 + 7
    dp = [[0] * m for _ in range(n)]

    if board[0][0] == '#':
        return 0
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if board[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]
                dp[i][j] %= MOD

    return dp[n-1][m-1]

