from typing import List

def count_above_median(tasks: List[int]) -> int:
    """
    Returns the number of members who have completed more tasks than the median.
    """
    n = len(tasks)
    sorted_tasks = sorted(tasks)

    if n % 2 == 1:
        median = sorted_tasks[n // 2]
    else:
        median = (sorted_tasks[n // 2 - 1] + sorted_tasks[n // 2]) / 2

    return len([task for task in tasks if task > median])

