def min_insertions_to_palindrome(s):
    """
    Returns the minimum number of insertions needed to make the given string a palindrome.
    """
    n = len(s)
    # Create a DP table to store the minimum insertions
    dp = [[0] * n for _ in range(n)]

    # Fill the DP table
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = min(dp[i][j-1], dp[i+1][j]) + 1

    return dp[0][n-1]

