def manage_inventory(C, M, operations):
    current_inventory = 0

    for operation in operations:
        action, quantity = operation

        if action == "enter":
            current_inventory += quantity
        elif action == "exit":
            current_inventory -= quantity

        if current_inventory > C:
            return "Overflow"

    return current_inventory

def max_complexity_sum(n, m, initial_scores, operations):
    complexity_scores = initial_scores[:]

    for operation in operations:
        t, k, x = operation
        if t == 1:
            complexity_scores[k - 1] += x
        elif t == 2:
            complexity_scores[k - 1] -= x
        elif t == 3:
            complexity_scores[k - 1] = 0

    return sum(complexity_scores)

def knapsack(n, W, items):
    dp = [[0] * (W + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        wi, vi = items[i - 1]
        for w in range(W + 1):
            if wi <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - wi] + vi)
            else:
                dp[i][w] = dp[i - 1][w]

    return dp[n][W]

