def max_increasing_buildings(heights):
    if not heights:
        return 0

    n = len(heights)
    dp = [1] * n  # dp[i] will store the length of the longest increasing subsequence ending at index i

    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

