def max_total_sales(n, k, sales):
    max_sum = float('-inf')

    # Sliding window for all lengths up to k
    for window_size in range(1, k + 1):
        current_sum = sum(sales[:window_size])
        max_sum = max(max_sum, current_sum)

        for i in range(window_size, n):
            current_sum += sales[i] - sales[i - window_size]
            max_sum = max(max_sum, current_sum)

    return max_sum

