def is_subset_sum_possible(n, P, arr):
    # Create a boolean DP array to store the possible sums
    dp = [False] * (P + 1)
    dp[0] = True  # Sum of 0 is always possible

    # Process each element in the array
    for num in arr:
        # Update the DP array from back to front
        for i in range(P, num - 1, -1):
            if dp[i - num]:
                dp[i] = True

    # The answer is whether the target sum P is achievable
    return "YES" if dp[P] else "NO"

