from collections import deque

def min_hash_to_dot(grid, n, m):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == '.'

    def bfs():
        queue = deque([(0, 0)])
        visited = [[False] * m for _ in range(n)]
        visited[0][0] = True
        steps = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()
                if x == n - 1 and y == m - 1:
                    return steps
                for dx, dy in [(1, 0), (0, 1)]:
                    nx, ny = x + dx, y + dy
                    if is_valid(nx, ny) and not visited[nx][ny]:
                        queue.append((nx, ny))
                        visited[nx][ny] = True

            steps += 1
        return float('inf')

    if is_valid(0, 0) and is_valid(n - 1, m - 1):
        initial_steps = bfs()
        if initial_steps != float('inf'):
            return 0

    min_flips = float('inf')

    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                grid[i][j] = '.'
                steps = bfs()
                if steps != float('inf'):
                    min_flips = min(min_flips, 1)
                grid[i][j] = '#'

    return min_flips

def solve(n, m, grid):
    return min_hash_to_dot([list(row) for row in grid], n, m)

