def max_flower_beds(n, garden):
    def is_valid(x, y):
        if x < 0 or x >= n or y < 0 or y >= n:
            return False
        if garden[x][y] != '.':
            return False
        for dx in [-1, 0, 1]:
            for dy in [-1, 0, 1]:
                if dx == 0 and dy == 0:
                    continue
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n and garden[nx][ny] == 'F':
                    return False
        return True

    def place_flower_beds():
        count = 0
        for i in range(n):
            for j in range(j_start_index[i], n, 2):
                if is_valid(i, j):
                    garden[i][j] = 'F'
                    count += 1
        return count

    # This offset helps us try a checkboard pattern from different starting points
    chessboard_offsets = [0, 1]
    max_flowers = 0
    for offset in chessboard_offsets:
        j_start_index = [i % 2 ^ offset for i in range(n)]
        current_flowers = place_flower_beds()
        max_flowers = max(max_flowers, current_flowers)
        # Clean the garden
        garden = [[cell if cell != 'F' else '.' for cell in row] for row in garden]

    return max_flowers

