def min_difference(n, difficulties):
    """
    Returns the minimum possible absolute difference between the sums of two groups of problems.
    """
    total_sum = sum(difficulties)
    # We need to find the subset with sum closest to total_sum // 2
    half_sum = total_sum // 2
    dp = [False] * (half_sum + 1)
    dp[0] = True

    for difficulty in difficulties:
        for j in range(half_sum, difficulty - 1, -1):
            dp[j] = dp[j] or dp[j - difficulty]

    for i in range(half_sum, -1, -1):
        if dp[i]:
            return abs(total_sum - 2 * i)

