def subset_sum_exists(n, d, sequence):
    def find_subset(sequence, d):
        dp = [False] * (d + 1)
        dp[0] = True
        for num in sequence:
            for j in range(d, num - 1, -1):
                if dp[j - num]:
                    dp[j] = True

        if not dp[d]:
            return "NO", []

        subset = []
        for num in reversed(sequence):
            if d >= num and dp[d - num]:
                subset.append(num)
                d -= num

        return "YES", subset

    result, subset = find_subset(sequence, d)
    if result == "YES":
        return f"YES\n{' '.join(map(str, subset))}"
    else:
        return "NO"

def process_test_cases(test_cases):
    results = []
    for n, d, sequence in test_cases:
        results.append(subset_sum_exists(n, d, sequence))
    return results

def main(input_data):
