from typing import List

def combinationSum2(nums: List[int], target: int) -> List[List[int]]:
    def backtrack(start, end, temp_list, target):
        if target == 0:
            result.append(list(temp_list))
            return
        if target < 0:
            return
        for i in range(start, end):
            if i > start and nums[i] == nums[i-1]:
                continue
            temp_list.append(nums[i])
            backtrack(i + 1, end, temp_list, target - nums[i])
            temp_list.pop()

    nums.sort()
    result = []
    backtrack(0, len(nums), [], target)
    return result

def count_distinct_substrings(s, k):
    """
    Counts the number of distinct substrings of length k that appear at least twice in the string s.
    """
    substring_count = {}
    n = len(s)

    for i in range(n - k + 1):
        substring = s[i:i+k]
        if substring in substring_count:
            substring_count[substring] += 1
        else:
            substring_count[substring] = 1

    result = sum(1 for count in substring_count.values() if count > 1)
    return result

