def dungeon_path_finder(n, m, grid):
    # Create a 2D array to store the number of ways to reach each cell
    dp = [[0] * m for _ in range(n)]

    # If the start or end is an obstacle, return 0
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return 0

    # Start at the top-left corner
    dp[0][0] = 1

    # Fill the dp table
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                if i > 0:
                    dp[i][j] += dp[i-1][j] # Add paths from the top
                if j > 0:
                    dp[i][j] += dp[i][j-1] # Add paths from the left

    # The number of ways to reach the bottom-right corner
    return dp[n-1][m-1]

def generate_sequence(a, b):
    if a > b:
        return -1

    base_value = b // a
    remainder = b % a

    sequence = [base_value] * a
    for i in range(remainder):
        sequence[i] += 1

    return sequence

