def merge_packages(packages):
    def find(i):
        if parents[i] != i:
            parents[i] = find(parents[i])
        return parents[i]

    def union(i, j):
        root_i = find(i)
        root_j = find(j)
        if root_i != root_j:
            parents[root_i] = root_j
            merged[root_j].update(merged[root_i])
            merged[root_i].clear()

    from collections import defaultdict

    # Packages count
    n = len(packages)

    # Dictionary to hold merged sets
    merged = defaultdict(set)

    # Map to keep track of which index holds each destination
    destination_to_index = {}

    parents = list(range(n))

    # Initialize each package in merged dict
    for i, package in enumerate(packages):
        merged[i] = set(package)
        for destination in package:
            if destination in destination_to_index:
                union(i, destination_to_index[destination])
            else:
                destination_to_index[destination] = i

    # Collect the final merged packages
    result = []
    for key, value in merged.items():
        if value:
            result.append(sorted(value))

    return result

