def is_prime(number):
    if number < 2:
        return False
    for i in range(2, int(number ** 0.5) + 1):
        if number % i == 0:
            return False
    return True

def find_min_prime_subarrays(n, arr):
    # Create a prefix sum array
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + arr[i]

    # Dynamic Programming table where dp[i] will be minimum number of subarrays
    # with prime sum for the first i elements
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            if is_prime(prefix_sum[i] - prefix_sum[j]):
                dp[i] = min(dp[i], dp[j] + 1)

    if dp[n] == float('inf'):
        return -1
    else:
        return dp[n]

