def min_subgrid_selections(t, test_cases):
    results = []
    for case in test_cases:
        m, n, garden = case
        min_row, max_row = m, -1
        min_col, max_col = n, -1

        # Find the bounds of the rectangular subgrid that includes all plants
        for i in range(m):
            for j in range(n):
                if garden[i][j] == '1':
                    if i < min_row: min_row = i
                    if i > max_row: max_row = i
                    if j < min_col: min_col = j
                    if j > max_col: max_col = j

        # If no plants are found, min_row and max_row would not be updated correctly.
        if min_row <= max_row and min_col <= max_col:
            results.append(1)  # A single subgrid can be selected to irrigate all plants
        else:
            results.append(0)  # No plants in the garden

    return results

