from typing import List, Tuple

def two_colorable(n: int, edges: List[Tuple[int, int]]) -> List[int]:
    def dfs(v, c):
        color[v] = c
        for neighbor in adj_list[v]:
            if color[neighbor] == -1:
                if not dfs(neighbor, 1 - c):
                    return False
            elif color[neighbor] == color[v]:
                return False
        return True

    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    color = [-1] * n
    for i in range(n):
        if color[i] == -1:
            if not dfs(i, 0):
                return []

    return color

