def can_travel_all_empty_cells(m, n, grid):
    def is_valid(x, y):
        return 0 <= x < m and 0 <= y < n and grid[x][y] == "."

    def dfs(x, y):
        stack = [(x, y)]
        visited.add((x, y))
        while stack:
            cx, cy = stack.pop()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    stack.append((nx, ny))

    # Find an empty cell to start the DFS
    start = None
    for i in range(m):
        for j in range(n):
            if grid[i][j] == ".":
                start = (i, j)
                break
        if start:
            break

    if start is None:
        return "No"

    visited = set()
    dfs(start[0], start[1])

    # Check if all empty cells are visited
    for i in range(m):
        for j in range(n):
            if grid[i][j] == "." and (i, j) not in visited:
                return "No"

    return "Yes"

