def game_scores(n, sequence):
    """
    Returns the final scores of Alice and Bob in the game.
    """
    sequence.sort(reverse=True)  # Sort the sequence in descending order

    alice_score = 0
    bob_score = 0

    for i in range(n):
        if i % 2 == 0:
            alice_score += sequence[i]  # Alice's turn
        else:
            bob_score += sequence[i]    # Bob's turn

    return alice_score, bob_score

