from collections import deque

def shortest_path_labyrinth(n, m, labyrinth):
    if labyrinth[0][0] == '#' or labyrinth[n-1][m-1] == '#':
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (x, y, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if x == n - 1 and y == m - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and labyrinth[nx][ny] == '.':
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

