def find_largest_rectangle(n, m, T, grid):
    def get_prefix_sum(grid):
        prefix_sum = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                prefix_sum[i][j] = grid[i-1][j-1] + prefix_sum[i][j-1] + prefix_sum[i-1][j] - prefix_sum[i-1][j-1]
        return prefix_sum

    def get_sum(prefix_sum, r1, c1, r2, c2):
        return prefix_sum[r2+1][c2+1] - prefix_sum[r1][c2+1] - prefix_sum[r2+1][c1] + prefix_sum[r1][c1]

    prefix_sum = get_prefix_sum(grid)
    max_area = 0
    min_sum = float('inf')

    for r1 in range(n):
        for c1 in range(m):
            for r2 in range(r1, n):
                for c2 in range(c1, m):
                    current_sum = get_sum(prefix_sum, r1, c1, r2, c2)
                    area = (r2 - r1 + 1) * (c2 - c1 + 1)
                    if current_sum <= T:
                        if area > max_area or (area == max_area and current_sum < min_sum):
                            max_area = area
                            min_sum = current_sum

    if max_area == 0:
        return 0, 0
    else:
        return max_area, min_sum

