def min_operations_to_sort_array(n, arr):
    """
    Returns the minimum number of operations required to sort the array by reversing subarrays.
    """
    sorted_arr = sorted(arr)
    if arr == sorted_arr:
        return 0

    l = 0
    while l < n and arr[l] == sorted_arr[l]:
        l += 1

    r = n - 1
    while r >= 0 and arr[r] == sorted_arr[r]:
        r -= 1

    reversed_section = arr[l:r+1][::-1]
    if sorted_arr[l:r+1] == reversed_section:
        return 1
