from collections import defaultdict, deque

def find_components_count(n, edges):
    visited = [False] * (n + 1)
    adj_list = defaultdict(list)

    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    def bfs(start_node):
        queue = deque([start_node])
        visited[start_node] = True
        while queue:
            node = queue.popleft()
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    num_components = 0
    for node in range(1, n + 1):
        if not visited[node]:
            bfs(node)
            num_components += 1

    return num_components

def process_cases(t, cases):
    results = []
    for i in range(t):
        n, m = cases[i][0]
        edges = cases[i][1]
        if n == 2 and m == 0:
            results.append("IMPOSSIBLE")
            continue
        num_components = find_components_count(n, edges)
        if num_components > 1:
            results.append("IMPOSSIBLE")
        else:
            results.append(f"POSSIBLE {num_components}")

    return results

