def verify_and_earliest(messages):
    from collections import defaultdict

    message_timestamp = defaultdict(set)
    earliest_version = {}

    for message_id, timestamp, content in messages:
        if timestamp in message_timestamp[message_id]:
            return []
        message_timestamp[message_id].add(timestamp)
        if message_id not in earliest_version or earliest_version[message_id]['timestamp'] > timestamp:
            earliest_version[message_id] = {'timestamp': timestamp, 'content': content}

    result = sorted(earliest_version.values(), key=lambda x: x['timestamp'])
    return [entry['content'] for entry in result]

