import bisect

def process_operations(operations):
    sequence = []
    results = []

    for operation in operations:
        op = operation.split()
        if op[0] == "I":
            x = int(op[1])
            bisect.insort(sequence, x)
        elif op[0] == "D":
            x = int(op[1])
            index = bisect.bisect_left(sequence, x)
            if index < len(sequence) and sequence[index] == x:
                sequence.pop(index)
        elif op[0] == "K":
            k = int(op[1])
            results.append(sequence[k - 1])

    return results

def can_traverse_all_planets(n, C, m, planets):
    from queue import Queue

    def distance(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    # Create adjacency list where an edge exists if distance is <= C
    adjacency_list = {i: [] for i in range(n)}
    for i in range(n):
        for j in range(i + 1, n):
            if distance(planets[i], planets[j]) <= C:
                adjacency_list[i].append(j)
                adjacency_list[j].append(i)

    # Check if all nodes are connected using BFS/DFS from each starting point
    def is_connected(start):
        visited = set()
        q = Queue()
        q.put(start)
        initial_fuel = m if distance((0, 0), planets[start]) <= m else C  # Initial fuel consideration
        if initial_fuel < distance((0, 0), planets[start]):
            return False

        visited.add(start)
        while not q.empty():
            current = q.get()
            for neighbor in adjacency_list[current]:
                if neighbor not in visited:
                    q.put(neighbor)
                    visited.add(neighbor)
        return len(visited) == n

    # Try to start from any planet
    for i in range(n):
        if is_connected(i):
            return "YES"
    return "NO"

