from collections import deque

def time_to_receive_all_messages(n, connections):
    if n == 1:
        return 0

    graph = {i: [] for i in range(1, n+1)}

    for a, b in connections:
        graph[a].append(b)
        graph[b].append(a)

    def bfs(start):
        visited = [False] * (n + 1)
        queue = deque([(start, 0)])
        visited[start] = True
        max_depth = 0

        while queue:
            node, depth = queue.popleft()
            max_depth = max(max_depth, depth)

            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append((neighbor, depth + 1))

        return max_depth

    return bfs(1)

def encrypt_string(s):
    """
    Encrypts the string s by replacing every character with the next one in the alphabet.

    Args:
    s (str): A string consisting of lowercase Latin letters (1 ≤ |s| ≤ 1000).

    Returns:
    str: The encrypted string.
    """
    encrypted = []
    for char in s:
        if char == 'z':
            encrypted.append('a')
        else:
            encrypted.append(chr(ord(char) + 1))
    return ''.join(encrypted)

