def count_islands(grid):
    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] != '#':
            return
        grid[x][y] = '.'  # Mark this cell as visited
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    if not grid or not grid[0]:
        return 0

    m = len(grid)
    n = len(grid[0])
    island_count = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '#':
                island_count += 1
                dfs(i, j)

    return island_count

def find_minimum_roads_to_connect_villages(n, m, roads):
    from collections import defaultdict, deque

    def bfs(start, visited):
        queue = deque([start])
        visited[start] = True
        while queue:
            node = queue.popleft()
            for neighbor in adjacency_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    if n == 1:
        return 0

    # Create adjacency list from the list of roads
    adjacency_list = defaultdict(list)
    for u, v in roads:
        adjacency_list[u].append(v)
        adjacency_list[v].append(u)

    # Check how many connected components there are
    visited = [False] * (n + 1)
    components = 0

    for i in range(1, n + 1):
        if not visited[i]:
            bfs(i, visited)
            components += 1

    # If number of components is greater than one, we need (components - 1) roads to connect them
    if components == 1:
        return 0
    return components - 1

