def decode_message(encoded_message):
    """
    Decodes the given encoded message by following the given rules:
    - Numbers (0 through 9) remain unchanged.
    - Alphabetic characters ('a' through 'z') are shifted to the next letter
      (with 'z' wrapping around to 'a').
    - Special characters are replaced by the given sequence.
    """
    special_chars_map = {'@': '#', '#': '$', '$': '%', '%': '&', '&': '@'}

    decoded_message = []

    for char in encoded_message:
        if 'a' <= char <= 'z':
            # Shift to the next letter, wrap around z to a
            if char == 'z':
                decoded_message.append('a')
            else:
                decoded_message.append(chr(ord(char) + 1))
        elif '0' <= char <= '9':
            # Numbers remain unchanged
            decoded_message.append(char)
        elif char in special_chars_map:
            # Replace special characters with the given sequence
            decoded_message.append(special_chars_map[char])
        else:
            # This handles unexpected characters, which are left unchanged.
            decoded_message.append(char)

    return ''.join(decoded_message)

def max_candy_collected(n, candies):
    if n == 0:
        return 0
    elif n == 1:
        return candies[0]
    elif n == 2:
        return max(candies[0], candies[1])

    prev1 = candies[0]
    prev2 = max(candies[0], candies[1])

    for i in range(2, n):
        current = max(prev1 + candies[i], prev2)
        prev1 = prev2
        prev2 = current

    return prev2

