def min_difference_partition(t, test_cases):
    def find_min_partition(yields):
        n = len(yields)
        total_sum = sum(yields)
        dp = [False] * (total_sum // 2 + 1)
        dp[0] = True

        for y in yields:
            for j in range(total_sum // 2, y - 1, -1):
                dp[j] = dp[j] or dp[j - y]

        for j in range(total_sum // 2, -1, -1):
            if dp[j]:
                return total_sum - 2 * j

    results = []
    for case in test_cases:
        n, yields = case
        results.append(find_min_partition(yields))

    return results

