def min_ticket_cost(t, test_cases):
    results = []
    for case in test_cases:
        n, k = case['n'], case['k']
        vendors = case['vendors']

        min_cost = float('inf')
        possible = False

        for price, available in vendors:
            if available >= k:
                min_cost = min(min_cost, price * k)
                possible = True

        if possible:
            results.append(min_cost)
        else:
            results.append(-1)

    return results

