def longest_increasing_subsequence(heights):
    """
    Returns the length of the longest strictly increasing subsequence in the given list of heights.

    Args:
    heights (list of int): The list of heights

    Returns:
    int: length of the longest strictly increasing subsequence
    """
    if not heights:
        return 0

    n = len(heights)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

