def sieve(max_num):
    """
    Create a list to determine prime numbers up to max_num using the Sieve of Eratosthenes.
    """
    is_prime = [True] * (max_num + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(max_num**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start * start, max_num + 1, start):
                is_prime[multiple] = False

    primes = []
    for num in range(max_num + 1):
        if is_prime[num]:
            primes.append(num)

    return primes

def count_primes_in_range(l, r, primes):
    """
    Given a range [l, r] and a list of primes, count how many primes are within the range.
    """
    count = 0
    for prime in primes:
        if prime > r:
            break
        if prime >= l:
            count += 1
    return count

def find_prime_counts(queries):
    max_limit = 10**6
    primes = sieve(max_limit)

    results = []
    for l, r in queries:
        results.append(count_primes_in_range(l, r, primes))

    return results

def has_even_palindrome_subsequence(arr):
    """
    Determines if there is an even-length palindrome subsequence in the array.
    """
    n = len(arr)
    # Check if there's a pair of identical adjacent elements, this forms an even palindrome of length 2
    for i in range(n-1):
        if arr[i] == arr[i+1]:
            return "YES"
    # Check for longer even-length palindromes (length 4, 6, ...)
    for length in range(4, n+1, 2):
        for start in range(n - length + 1):
            end = start + length - 1
            if arr[start:end+1] == arr[start:end+1][::-1]:
                return "YES"
    return "NO"

