def can_visit_all_rooms(rooms):
    """
    Determines if all rooms can be visited starting from room 0.

    Args:
    rooms (list of list of int): 2D array where each sublist represents keys in that room.

    Returns:
    bool: True if all rooms can be visited, False otherwise.
    """
    visited = [False] * len(rooms)
    stack = [0]

    while stack:
        room = stack.pop()
        if not visited[room]:
            visited[room] = True
            for key in rooms[room]:
                if not visited[key]:
                    stack.append(key)

    return all(visited)

