def reconstruct_path(n, records):
    # Create dictionaries to store incoming and outgoing paths
    out_paths = {}
    in_paths = {}

    for a, b in records:
        if b != -1:
            out_paths[a] = b
            in_paths[b] = a

    # Find the starting point (no incoming paths)
    start = None
    for a, b in records:
        if a not in in_paths:
            start = a
            break

    # Reconstruct the path from start
    path = []
    current = start
    while current != -1:
        path.append(current)
        current = out_paths.get(current, -1)

    return path

# Example Usage
