def determine_winner(t, test_cases):
    results = []
    for case in test_cases:
        n, m, x, y, f, forbidden_cells = case
        # Any move to a forbidden or already visited cell loses the game immediately for optimal players
        # This means optimal players will avoid these cells and try to force the other into them

        # Initial moves available for Alice are four directions
        initial_moves = 0
        if (x - 1 > 0) and ((x - 1, y) not in forbidden_cells):
            initial_moves += 1
        if (x + 1 <= n) and ((x + 1, y) not in forbidden_cells):
            initial_moves += 1
        if (y - 1 > 0) and ((x, y - 1) not in forbidden_cells):
            initial_moves += 1
        if (y + 1 <= m) and ((x, y + 1) not in forbidden_cells):
            initial_moves += 1

        # If Alice has no initial moves, Bob wins immediately
        if initial_moves == 0:
            results.append("Bob")
        else:
            results.append("Alice")
    return results

# Parsing and preparing input
def main(input_string):
    lines = input_string.strip().split("\n")
    t = int(lines[0])
    test_cases = []
    line_index = 1
    for _ in range(t):
        n, m = map(int, lines[line_index].split())
        x, y = map(int, lines[line_index + 1].split())
        f = int(lines[line_index + 2])
        forbidden_cells = set()
        for i in range(f):
            a, b = map(int, lines[line_index + 3 + i].split())
            forbidden_cells.add((a, b))
        test_cases.append((n, m, x, y, f, forbidden_cells))
        line_index += 3 + f

    result = determine_winner(t, test_cases)
    return "\n".join(result)

def longest_palindromic_subsequence(arr):
    """
    Returns the length of the longest palindromic subsequence in the array.
    """
    n = len(arr)
    dp = [[0] * n for _ in range(n)]

    # Each single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the dp table
    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if arr[i] == arr[j] and cl == 2:
                dp[i][j] = 2
            elif arr[i] == arr[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    # The result is in dp[0][n-1]
    return dp[0][n-1]

