def min_partition_substrings(t, strings):
    results = []

    for s in strings:
        used_chars = set()
        partition_count = 1

        for char in s:
            if char in used_chars:
                partition_count += 1
                used_chars = set()
            used_chars.add(char)

        results.append(partition_count)

    return results

