def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest increasing subsequence in the given array.
    """
    if not arr:
        return 0

    n = len(arr)
    lis = [1] * n  # Initialize LIS array with 1s

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)

