def largest_square_submatrix_of_ones(m, n, matrix_list):
    # Convert the flat list of matrix elements into a 2D matrix
    matrix = []
    for i in range(m):
        matrix.append(matrix_list[i*n:(i+1)*n])

    # Initialize a DP array to store the size of square sub-matrix ending at (i, j)
    dp = [[0]*n for _ in range(m)]
    max_side_length = 0

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1  # The first row and first column can only be 1 if it's 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side_length = max(max_side_length, dp[i][j])

    return max_side_length

def can_form_by_repeating_substring(s):
    """
    Determine if the string can be constructed by repeating a substring.
    """
    n = len(s)
    for i in range(1, n//2 + 1):
        if n % i == 0:
            substring = s[:i]
            if substring * (n // i) == s:
                return True
    return False

