from collections import deque

def bfs_shortest_path(grid, start, end):
    n, m = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start = (start[0] - 1, start[1] - 1)
    end = (end[0] - 1, end[1] - 1)

    if grid[start[0]][start[1]] == 1 or grid[end[0]][end[1]] == 1:
        return -1

    queue = deque([(start, 0)])
    visited = set()
    visited.add(start)

    while queue:
        (current, dist) = queue.popleft()

        if current == end:
            return dist

        for direction in directions:
            next_cell = (current[0] + direction[0], current[1] + direction[1])

            if 0 <= next_cell[0] < n and 0 <= next_cell[1] < m:
                if grid[next_cell[0]][next_cell[1]] == 0 and next_cell not in visited:
                    visited.add(next_cell)
                    queue.append((next_cell, dist + 1))

    return -1

def delivery_requests(grid, requests):
    results = []
    for request in requests:
        start = (request[0], request[1])
        end = (request[2], request[3])
        result = bfs_shortest_path(grid, start, end)
        results.append(result)
    return results

