def find_highest_power_in_largest_component(n, m, power_levels, edges):
    from collections import defaultdict, deque

    if m == 0:  # No edges, return the vertex with the highest power level
        return power_levels.index(max(power_levels)) + 1

    graph = defaultdict(list)

    for u, v in edges:
        graph[u-1].append(v-1)
        graph[v-1].append(u-1)

    def bfs(start):
        visited = set()
        queue = deque([start])
        component = []

        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                component.append(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return component

    visited_global = set()
    largest_component = []

    for vertex in range(n):
        if vertex not in visited_global:
            component = bfs(vertex)
            if len(component) > len(largest_component):
                largest_component = component
            visited_global.update(component)

    largest_component.sort(key=lambda x: (-power_levels[x], x))
    return largest_component[0] + 1

