from collections import defaultdict

def dfs(node, visited, adj_list):
    stack = [node]
    while stack:
        current = stack.pop()
        for neighbor in adj_list[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                stack.append(neighbor)

def count_isolated_groups(n, edges):
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    visited = set()
    num_groups = 0
    for node in range(1, n + 1):
        if node not in visited:
            visited.add(node)
            dfs(node, visited, adj_list)
            num_groups += 1

    # Minimum additional direct flights needed is (num_groups - 1)
    return num_groups - 1

def minimum_additional_flights(test_cases):
    results = []
    for case in test_cases:
        n, m, edges = case
        results.append(count_isolated_groups(n, edges))
    return results

