from collections import deque

def min_moves_to_reach_target(n, m, grid, r1, c1, r2, c2):
    # Convert 1-based index to 0-based index
    r1, c1, r2, c2 = r1-1, c1-1, r2-1, c2-1

    if (r1, c1) == (r2, c2):
        return 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(r1, c1, 0)])  # Store current row, col, and distance
    visited = set((r1, c1))

    while queue:
        x, y, dist = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                if grid[nx][ny] == grid[x][y]:  # Move only if the characters match
                    if (nx, ny) == (r2, c2):
                        return dist + 1  # Return distance if target is reached
                    queue.append((nx, ny, dist + 1))
                    visited.add((nx, ny))

    return -1  # Return -1 if target is not reachable

