def can_store_artworks(n, artworks, m, queries):
    # Determine the maximum width and height needed for artworks
    max_width = 0
    max_height = 0

    for a, b in artworks:
        max_width = max(max_width, max(a, b))
        max_height = max(max_height, min(a, b))

    results = []
    # Check each storage query to see if it fits max_width and max_height
    for h, w in queries:
        if (max_width <= h and max_height <= w) or (max_width <= w and max_height <= h):
            results.append("YES")
        else:
            results.append("NO")

    return results

