def count_integer_occurrences(n, initial_sequence, m, operations, q):
    from collections import Counter

    # Create a counter for the initial sequence
    sequence_counter = Counter(initial_sequence)

    # Process each operation
    for operation in operations:
        op, x = operation.split()
        x = int(x)

        if op == "add":
            sequence_counter[x] += 1
        elif op == "remove":
            if sequence_counter[x] > 0:
                sequence_counter[x] -= 1

    # Return the count of q in the sequence
    return sequence_counter[q]

