def evaluate_rpn(expression: str) -> int:
    stack = []
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Python division is float by default, use // for integer division
                # and manually correct the result for negative numbers
                stack.append(int(a / b))
        else:
            stack.append(int(token))

    return stack.pop()

