def minimum_rounds(n, k):
    """
    Calculate the minimum number of rounds required for Borya to determine the initial
    positions of all n cards by flipping any k cards in each round.
    """
    if k == 1:
        return n
    if n <= k:
        return 1
    return (n + k - 1) // k

