def count_segment_changes(n, m, k, t, t1, t2):
    segment_changes = {
        "0": 6, "1": 2, "2": 5, "3": 5,
        "4": 4, "5": 5, "6": 6, "7": 3,
        "8": 7, "9": 6
    }

    def count_changes(digit1, digit2):
        changes = sum(1 for d1, d2 in zip(digit1, digit2) if d1 != d2)
        return changes

    def str_padded(num, length):
        return str(num).zfill(length)

    count = 0

    for second in range(t1 + 1, t2 + 1):
        prev = str_padded(second - 1, n)
        curr = str_padded(second, n)
        changes = 0
        for p, c in zip(prev, curr):
            if p != c:
                changes += abs(segment_changes[p] - segment_changes[c])
        if changes >= k:
            count += 1

    return count

