def max_energy_sum(n, energies):
    if n == 0:
        return 0
    elif n == 1:
        return energies[0]

    include = energies[0]
    exclude = 0
    for i in range(1, n):
        new_exclude = max(include, exclude)
        include = exclude + energies[i]
        exclude = new_exclude

    return max(include, exclude)

