def check_inventory(entries, required):
    """
    Check if required quantities can be met from available inventory.

    :param entries: List of tuples, where each tuple contains a string (category) and an integer (quantity available).
    :param required: List of tuples, where each tuple contains a string (category) and an integer (required quantity).
    :return: List of strings, "Available" or "Out of stock" for each required product.
    """
    inventory = {}

    # Process the available inventory.
    for category, quantity in entries:
        if category in inventory:
            inventory[category] += quantity
        else:
            inventory[category] = quantity

    result = []
    # Process the required products to check.
    for req_cat, req_qty in required:
        if req_cat in inventory and inventory[req_cat] >= req_qty:
            result.append("Available")
        else:
            result.append("Out of stock")

    return result

def average_uptime(binary_string):
    """
    Calculate the average length of all contiguous sequences of '1's in the binary string.

    :param binary_string: str, a binary string representing system up-times and failures
    :return: float, average length of all up-times
    """
    if not binary_string:
        return 0.0

    up_lengths = []
    current_length = 0

    for char in binary_string:
        if char == '1':
            current_length += 1
        else:
            if current_length > 0:
                up_lengths.append(current_length)
                current_length = 0

    if current_length > 0:
        up_lengths.append(current_length)

    if not up_lengths:
        return 0.0

    average_length = sum(up_lengths) / len(up_lengths)
    return average_length

