def smallest_missing_integer(array):
    """
    Finds the smallest positive integer that is not present in any subarray of the given array.
    """
    n = len(array)
    present = [False] * (n + 2)

    # Marking the numbers present in the array
    for num in array:
        if 1 <= num <= n + 1:
            present[num] = True

    # Finding the smallest number not marked
    for i in range(1, n + 2):
        if not present[i]:
            return i

