def can_assign_seats(n, rows, preferences):
    """
    Determines if seats can be assigned to students based on their preferences.

    :param n: Number of rows
    :param rows: List of lists where each list has seat numbers in each row
    :param preferences: List of tuples where each tuple has (ri, si) indicating the student's desired row and seat
    :return: "YES" if seats can be assigned as per preferences, "NO" otherwise
    """
    # Create a dictionary to keep track of seat availability
    seat_dict = {}
    for row_index in range(n):
        for seat in rows[row_index]:
            seat_dict[(row_index + 1, seat)] = False  # False means the seat is available

    # Attempt to assign seats
    for (r, s) in preferences:
        if (r, s) in seat_dict and not seat_dict[(r, s)]:  # Check if the seat is available
            seat_dict[(r, s)] = True  # Mark the seat as occupied
        else:
            return "NO"  # Seat is already occupied or does not exist

    return "YES"  # All preferences were satisfied

def largest_non_symmetric_subset(n, points):
    """
    Returns the size of the largest subset of points such that no two points are symmetric with respect to the Y-axis.
    """
    unique_points = set()

    for x, y in points:
        normalized_point = (min(x, -x), y)
        unique_points.add(normalized_point)

    return len(unique_points)

