def find_pair_with_difference(n, k, arr):
    """
    Finds if there are two integers in the array whose absolute difference is exactly k.
    Returns "YES" if such a pair exists, otherwise "NO".
    """
    arr_set = set(arr)
    for num in arr:
        if (num + k) in arr_set or (num - k) in arr_set:
            return "YES"
    return "NO"

