def contains_cycle(n, m, edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)

    def dfs(v, parent):
        visited[v] = True
        for neighbor in graph[v]:
            if not visited[neighbor]:
                if dfs(neighbor, v):
                    return True
            elif neighbor != parent:
                return True
        return False

    for i in range(1, n + 1):
        if not visited[i]:
            if dfs(i, -1):
                return "YES"
    return "NO"

def solve(test_cases):
    results = []
    for n, m, edges in test_cases:
        results.append(contains_cycle(n, m, edges))
    return results

