def minEncodedLength(s: str) -> int:
    def encode_length(start, end):
        if end - start < 1:
            return 0
        if end - start == 1:
            return 1

        min_len = end - start  # worst case: no encoding possible, original length
        sub = s[start:end]

        # Try every possible partition of sub into two
        for mid in range(start + 1, end):
            left_encoded = encode_length(start, mid)
            right_encoded = encode_length(mid, end)
            min_len = min(min_len, left_encoded + right_encoded)

        # Now try to find repeating patterns within the substring
        n = end - start
        for l in range(1, n):
            if n % l == 0:
                repeat_pattern = sub[:l]
                if repeat_pattern * (n // l) == sub:
                    num_repeats = n // l
                    pattern_length = encode_length(start, start + l)
                    min_len = min(min_len, len(f'{num_repeats}[{repeat_pattern}]'))

        return min_len

    return encode_length(0, len(s))

