from collections import deque

def minimum_steps(m, n, grid):
    """
    Calculate the minimum number of steps required for the robot to reach the destination
    with the ability to remove at most one obstacle on its path.
    """
    if grid[0][0] == 1 and grid[m-1][n-1] == 1:
        return -1  # Robot cannot start or end in an obstacle

    directions = [(1, 0), (0, 1)]  # Only move right or down
    visited = [[[False, False] for _ in range(n)] for _ in range(m)]
    visited[0][0][0] = True

    queue = deque([(0, 0, 0, False)]) # (x, y, distance, used_obstacle_removal)

    while queue:
        x, y, dist, used_obstacle_removal = queue.popleft()

        if x == m - 1 and y == n - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n:
                if grid[nx][ny] == 0 and not visited[nx][ny][used_obstacle_removal]:
                    visited[nx][ny][used_obstacle_removal] = True
                    queue.append((nx, ny, dist + 1, used_obstacle_removal))
                elif grid[nx][ny] == 1 and not used_obstacle_removal and not visited[nx][ny][1]:
                    visited[nx][ny][1] = True
                    queue.append((nx, ny, dist + 1, True))

    return -1

