def min_drones(n, W, weights):
    # Sort the weights in non-increasing order
    weights.sort(reverse=True)

    # Initialize a list to store the remaining capacity of each drone
    drones = []

    for weight in weights:
        placed = False
        # Try to place the package in an existing drone
        for i in range(len(drones)):
            if drones[i] >= weight:
                drones[i] -= weight
                placed = True
                break
        # If the package couldn't be placed in any existing drone, use a new drone
        if not placed:
            drones.append(W - weight)

    return len(drones)

