from typing import List, Tuple

def find_inconsistent_entries(logs: List[Tuple[int, int, str]]) -> List[int]:
    employee_status = {}
    inconsistent_employees = set()

    for timestamp, employee_id, action in logs:
        if employee_id not in employee_status:
            if action == "exit":
                inconsistent_employees.add(employee_id)
            employee_status[employee_id] = action
        else:
            if (employee_status[employee_id] == "enter" and action == "enter") or \
               (employee_status[employee_id] == "exit" and action == "exit"):
                inconsistent_employees.add(employee_id)
            employee_status[employee_id] = action

    return sorted(inconsistent_employees)

import math

def factorial_sum(n):
    """
    Calculates the sum of factorials of the digits of the given number n.
    """
    return sum(math.factorial(int(digit)) for digit in str(n))

def steps_to_repeating_number(n):
    """
    Generates the Factorial Sum Sequence starting from n and returns the number of steps
    to reach the first repeating number.
    """
    sequence = []
    while n not in sequence:
        sequence.append(n)
        n = factorial_sum(n)
    return len(sequence)

