from itertools import combinations

def is_clique(graph, nodes):
    """
    Check if a given set of nodes forms a clique.
    """
    for u, v in combinations(nodes, 2):
        if v not in graph[u]:
            return False
    return True

def largest_clique_size(n, m, friendships):
    """
    Finds the size of the largest clique in the friendship graph.
    n: number of members
    m: number of friendships
    friendships: list of tuples representing friendships
    """
    if m == 0:
        return 1

    graph = {i: set() for i in range(1, n + 1)}
    for u, v in friendships:
        graph[u].add(v)
        graph[v].add(u)

    max_clique_size = 1
    for size in range(2, n + 1):
        for nodes in combinations(range(1, n + 1), size):
            if is_clique(graph, nodes):
                max_clique_size = size

    return max_clique_size

