from itertools import combinations

def maximize_playlist_rating(n, k, T, songs):
    if k == 0 or T == 0:
        return 0

    max_rating = 0

    # Iterate over all combinations of songs of size k
    for combo in combinations(songs, k):
        total_playtime = sum(song[0] for song in combo)
        if total_playtime <= T:
            total_rating = sum(song[1] for song in combo)
            max_rating = max(max_rating, total_rating)

    return max_rating

def currently_borrowed_books(log: list) -> list:
    """
    Takes a list of borrow and return logs and returns a sorted list of currently borrowed books' ids.
    If no books are currently borrowed, returns "No books are currently borrowed".
    """
    borrowed_books = set()

    for entry in log:
        action, book_id = entry.split()
        book_id = int(book_id)

        if action == 'B':
            borrowed_books.add(book_id)
        elif action == 'R':
            if book_id in borrowed_books:
                borrowed_books.remove(book_id)

    if not borrowed_books:
        return "No books are currently borrowed"

    return sorted(borrowed_books)

