def max_hourglass_sum(n, m, grid):
    max_sum = float('-inf')
    for i in range(n - 2):
        for j in range(m - 2):
            current_sum = (grid[i][j] + grid[i][j+1] + grid[i][j+2] +
                           grid[i+1][j+1] +
                           grid[i+2][j] + grid[i+2][j+1] + grid[i+2][j+2])
            max_sum = max(max_sum, current_sum)
    return max_sum

def find_deleted_char(s, t):
    """
    Returns the character deleted from string s to form string t. If no character was deleted, returns an empty string.
    """
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in t:
        if char in char_count:
            char_count[char] -= 1

    for char in char_count:
        if char_count[char] > 0:
            return char

    return ''

