def process_input_output(input_data):
    lines = input_data.strip().split('\n')
    t = int(lines[0])
    index = 1
    test_cases = []
    for _ in range(t):
        k = int(lines[index])
        array = list(map(int, lines[index + 1].split()))
        test_cases.append((k, array))
        index += 2
    return sum_of_digital_roots(test_cases)

