def is_palindrome(s):
    """
    Check if a given string s is a palindrome.
    """
    return s == s[::-1]

def can_form_k_palindrome(k, s):
    """
    Check if the string s can be divided into k palindromic parts.
    """
    n = len(s)
    if k > n:
        return "NO"

    # dp[i][j] is True if s[i:j+1] is a palindrome
    dp = [[False] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = True

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                dp[i][j] = length == 2 or dp[i + 1][j - 1]

    # min cuts to make each part a palindrome
    min_cuts = [float('inf')] * (n + 1)
    min_cuts[0] = 0

    for i in range(1, n + 1):
        for j in range(i):
            if dp[j][i - 1]:
                min_cuts[i] = min(min_cuts[i], min_cuts[j] + 1)

    return "YES" if min_cuts[n] <= k else "NO"

def process(t, test_cases):
    """
    Process the input test cases and return the results.
    """
    results = []
    for i in range(t):
        k, s = test_cases[i]
        results.append(can_form_k_palindrome(k, s))
    return results

