from collections import deque

def shortest_transformation(n, dictionary, start, end):
    def differ_by_one(word1, word2):
        """
        Helper function to check if two words differ by exactly one character.
        """
        if len(word1) != len(word2):
            return False
        differences = sum(1 for a, b in zip(word1, word2) if a != b)
        return differences == 1

    if start not in dictionary or end not in dictionary:
        return -1

    queue = deque([(start, 0)])
    visited = set(start)

    while queue:
        current_word, transformation_count = queue.popleft()

        if current_word == end:
            return transformation_count

        for word in dictionary:
            if word not in visited and differ_by_one(current_word, word):
                visited.add(word)
                queue.append((word, transformation_count + 1))

    return -1

