def min_steps_to_equal_elements(n, k, nums):
    min_num = min(nums)
    steps = 0

    for num in nums:
        if (num - min_num) % k != 0:
            return -1
        steps += (num - min_num) // k

    return steps

def solve_min_steps(T, test_cases):
    results = []
    for case in test_cases:
        n, k = case[0]
        nums = case[1]
        result = min_steps_to_equal_elements(n, k, nums)
        results.append(result)
    return results

def count_firefly_pairs(n, target, durations):
    pairs_count = 0
    # Using a dictionary to count occurrences of each duration
    duration_count = {}

    for duration in durations:
        complement = target - duration
        if complement in duration_count:
            pairs_count += duration_count[complement]

        if duration in duration_count:
            duration_count[duration] += 1
        else:
            duration_count[duration] = 1

    return pairs_count

