    """
    Returns 'YES' if there exists a subsequence of length at least three
    where each number is the sum of its immediate next two numbers,
    otherwise returns 'NO'.
    """
    n = len(arr)
    # Checking all combinations of triplets in the array
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if arr[i] == arr[j] + arr[k]:
                    return "YES"
                if arr[j] == arr[i] + arr[k]:
                    return "YES"
                if arr[k] == arr[i] + arr[j]:
                    return "YES"
    return "NO"

