def can_cover_wall(m, n, t, c):
    """
    Determines if it's possible to cover a wall of length m using exactly n tiles
    such that no two adjacent tiles have the same color.
    """
    def backtrack(index, current_length, last_color, arrangement):
        if current_length == m and index == n:
            return True, arrangement

        if index >= len(t) or current_length > m:
            return False, []

        for i in range(len(t)):
            if c[i] != last_color:
                result, seq = backtrack(index + 1, current_length + t[i], c[i], arrangement + [c[i]])
                if result:
                    return result, seq

        return False, []

    result, arrangement = backtrack(0, 0, "", [])

    if result:
        return "YES\n" + " ".join(arrangement)
    else:
        return "NO"

def solve(m, n, t, c):
    """
    Parses the input and delegates to the `can_cover_wall` function.
    """
    return can_cover_wall(m, n, t, c)

