from collections import deque

def is_one_letter_difference(word1, word2):
    """
    Helper function to check if two words differ by exactly one letter.
    """
    count = 0
    for a, b in zip(word1, word2):
        if a != b:
            count += 1
        if count > 1:
            return False
    return count == 1

def min_word_morph(start_word, target_word, words_dict):
    """
    Returns the minimum number of moves required to transform
    the start_word into the target_word using the given words_dict.
    """
    if start_word == target_word:
        return 0

    words_dict = set(words_dict)
    if target_word not in words_dict:
        return -1

    queue = deque([(start_word, 0)])  # (current_word, steps)
    visited = set([start_word])

    while queue:
        current_word, steps = queue.popleft()

        for word in list(words_dict):
            if is_one_letter_difference(current_word, word):
                if word == target_word:
                    return steps + 1
                if word not in visited:
                    visited.add(word)
                    queue.append((word, steps + 1))

    return -1

