def longest_palindromic_subsequence_length(S):
    """
    Returns the length of the longest palindromic subsequence in string S.
    """
    n = len(S)
    # Create a 2D table to store the results of subproblems
    dp = [[0]*n for _ in range(n)]

    # A single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the table. The outer loop is length of the substring.
    for cl in range(2, n+1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if S[i] == S[j] and cl == 2:
                dp[i][j] = 2
            elif S[i] == S[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])

    # Length of the longest palindromic subsequence is dp[0][n-1]
    return dp[0][n-1]

