from typing import List

def largest_island(grid: List[List[str]]) -> int:
    def dfs(x, y):
        if x < 0 or x >= n or y < 0 or y >= m or grid[x][y] == 'W':
            return 0
        grid[x][y] = 'W'  # mark as visited
        size = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            size += dfs(x + dx, y + dy)
        return size

    n = len(grid)
    m = len(grid[0])
    max_size = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'L':
                max_size = max(max_size, dfs(i, j))

    return max_size

