def process_events(n, q, events):
    inventory = [0] * (n + 1)
    results = []

    for event in events:
        parts = event.split()
        action = int(parts[0])
        product_id = int(parts[1])

        if action == 1:
            units = int(parts[2])
            inventory[product_id] += units
        elif action == 2:
            units = int(parts[2])
            inventory[product_id] = max(inventory[product_id] - units, 0)
        elif action == 3:
            results.append(inventory[product_id])

    return results

def is_isomorphic(s: str, t: str) -> bool:
    """
    Determine if two strings s and t are isomorphic.

    Args:
    s (str): The first string.
    t (str): The second string.

    Returns:
    bool: True if the strings are isomorphic, False otherwise.
    """
    if len(s) != len(t):
        return False

    s_to_t_mapping = {}
    t_to_s_mapping = {}

    for char_s, char_t in zip(s, t):
        if char_s in s_to_t_mapping and s_to_t_mapping[char_s] != char_t:
            return False
        if char_t in t_to_s_mapping and t_to_s_mapping[char_t] != char_s:
            return False
        s_to_t_mapping[char_s] = char_t
        t_to_s_mapping[char_t] = char_s

    return True

