def min_operations_to_equal_elements(n, arr):
    """
    Returns the minimum number of operations needed to make all elements in the array equal.
    """
    if n == 0:
        return 0

    arr.sort()

    # The optimal target value is the median of the array
    median = arr[n // 2]

    return sum(abs(x - median) for x in arr)

