def longest_arith_seq_length(nums):
    """
    Function to find the length of the longest arithmetic subsequence.

    Parameters:
    nums (list): list of integers

    Returns:
    int: length of the longest arithmetic subsequence
    """
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    # Dictionary to store the length of the longest arithmetic subsequence ending at index i with a given difference
    dp = {}
    max_length = 1

    for i in range(n):
        for j in range(i):
            diff = nums[i] - nums[j]
            if (j, diff) in dp:
                dp[(i, diff)] = dp[(j, diff)] + 1
            else:
                dp[(i, diff)] = 2
            max_length = max(max_length, dp[(i, diff)])

    return max_length

