from collections import deque

def shortest_path(grid):
    n = len(grid)
    m = len(grid[0])

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(0, 0, 1)])  # (row, col, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == (n-1, m-1):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] == '.':
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

import heapq

def prims_min_vertex_weight_sum(n, m, weights, edges):
    if n == 1:
        return weights[0]

    adj_list = {i: [] for i in range(n)}

    for u, v, c in edges:
        adj_list[u-1].append((c, v-1))
        adj_list[v-1].append((c, u-1))

    visited = [False] * n
    min_heap = [(0, 0)]
    total_weight_sum = 0
    vertices_count = 0

    while min_heap:
        cost, current_vertex = heapq.heappop(min_heap)

        if visited[current_vertex]:
            continue

        visited[current_vertex] = True
        total_weight_sum += weights[current_vertex]
        vertices_count += 1

        for edge_cost, neighbor in adj_list[current_vertex]:
            if not visited[neighbor]:
                heapq.heappush(min_heap, (edge_cost, neighbor))

    if vertices_count == n:
        return total_weight_sum
    else:
        return -1

def find_mst_vertex_weight_sum(n, m, weights, edges):
    return prims_min_vertex_weight_sum(n, m, weights, edges)

