def trending_hashtag(n, posts):
    from collections import defaultdict

    hashtag_freq = defaultdict(int)

    for post in posts:
        words = post.split()
        for word in words:
            if word.startswith('#'):
                hashtag_freq[word] += 1

    max_frequency = max(hashtag_freq.values())
    trending_hashtags = [tag for tag, freq in hashtag_freq.items() if freq == max_frequency]

    return min(trending_hashtags)

