def process_matrix_queries(n, m, matrix, queries):
    # Initialize the prefix sum matrix with an extra row and column of zeros
    prefix_sum = [[0] * (m + 1) for _ in range(n + 1)]

    # Function to build the prefix sum matrix
    def build_prefix_sum():
        for i in range(n):
            for j in range(m):
                prefix_sum[i + 1][j + 1] = matrix[i][j] + prefix_sum[i + 1][j] + prefix_sum[i][j + 1] - prefix_sum[i][j]

    # Function to update the prefix sum matrix
    def update_prefix_sum(x, y, value):
        delta = value - matrix[x - 1][y - 1]
        matrix[x - 1][y - 1] = value
        for i in range(x, n + 1):
            for j in range(y, m + 1):
                prefix_sum[i][j] += delta

    # Build the initial prefix sum matrix
    build_prefix_sum()

    results = []

    for query in queries:
        parts = list(map(int, query.split()))
        if parts[0] == 1:
            # Update query
            x, y, v = parts[1], parts[2], parts[3]
            update_prefix_sum(x, y, v)
        elif parts[0] == 2:
            # Sum query
            x1, y1, x2, y2 = parts[1], parts[2], parts[3], parts[4]
            sum_result = (prefix_sum[x2][y2] -
                          prefix_sum[x1 - 1][y2] -
                          prefix_sum[x2][y1 - 1] +
                          prefix_sum[x1 - 1][y1 - 1])
            results.append(sum_result)

    return results

