from collections import deque

def min_steps_to_infect(n, m, grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque()
    steps = [[-1] * m for _ in range(n)]
    healthy_count = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'I':
                queue.append((i, j))
                steps[i][j] = 0
            elif grid[i][j] == 'H':
                healthy_count += 1

    if healthy_count == 0:
        return 0

    min_steps = 0
    while queue:
        x, y = queue.popleft()
        current_step = steps[x][y]

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == 'H' and steps[nx][ny] == -1:
                steps[nx][ny] = current_step + 1
                min_steps = max(min_steps, steps[nx][ny])
                queue.append((nx, ny))
                healthy_count -= 1

    return min_steps if healthy_count == 0 else -1

