def max_total_productivity(n, productivity_levels):
    odd_present = any(p % 2 != 0 for p in productivity_levels)
    if not odd_present:
        raise ValueError("No valid teams possible as there are no odd productivity levels.")

    total_productivity = 0
    current_team_productivity = 0
    for p in productivity_levels:
        if p % 2 != 0:
            if current_team_productivity > 0:
                total_productivity += current_team_productivity
                current_team_productivity = 0
            total_productivity += p
        else:
            current_team_productivity += p

    total_productivity += current_team_productivity  # adding the leftover team at the end if any
    return total_productivity

