def handle_operations(operations):
    """
    Handles the operations related to user access and permissions.

    Args:
        operations (List[str]): A list of operations to be processed.

    Returns:
        List[str]: A list of results for 'check_permission' operations.
    """
    users = {}
    results = []

    for operation in operations:
        parts = operation.split()
        command = parts[0]

        if command == "add_user":
            user_id = int(parts[1])
            if user_id not in users:
                users[user_id] = set()

        elif command == "grant_permission":
            user_id = int(parts[1])
            perm_name = parts[2]
            if user_id in users:
                users[user_id].add(perm_name)

        elif command == "revoke_permission":
            user_id = int(parts[1])
            perm_name = parts[2]
            if user_id in users and perm_name in users[user_id]:
                users[user_id].remove(perm_name)

        elif command == "check_permission":
            user_id = int(parts[1])
            perm_name = parts[2]
            if user_id in users and perm_name in users[user_id]:
                results.append("yes")
            else:
                results.append("no")

    return results

def count_unique_substrings_with_distinct_chars(k, s):
    """
    Returns the number of unique substrings of length k
    with all distinct characters.
    """
    if k > len(s):
        return 0

    unique_substrings = set()

    for i in range(len(s) - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == k:
            unique_substrings.add(substring)

    return len(unique_substrings)

