def migration_conflict(r, n, routes):
    # A set to keep track of cells that have been visited by any bird
    visited_cells = set()

    for route in routes:
        x1, y1, x2, y2 = route
        if x1 == x2:  # vertical route
            for y in range(min(y1, y2), max(y1, y2) + 1):
                if (x1, y) in visited_cells:
                    return "Yes"
                visited_cells.add((x1, y))
        else:  # horizontal route
            for x in range(min(x1, x2), max(x1, x2) + 1):
                if (x, y1) in visited_cells:
                    return "Yes"
                visited_cells.add((x, y1))

    return "No"

