def longest_arith_seq_length(nums):
    """
    Returns the length of the longest subsequence where the difference between consecutive elements is the same.
    """
    if len(nums) == 1:
        return 1

    dp = {}
    max_len = 1

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            diff = nums[j] - nums[i]
            if (i, diff) in dp:
                dp[(j, diff)] = dp[(i, diff)] + 1
            else:
                dp[(j, diff)] = 2
            max_len = max(max_len, dp[(j, diff)])

    return max_len

