def count_subsequences(planets, glider_sequence):
    """
    Returns the number of different subsequences in the planet list that match the glider sequence.
    """
    n, m = len(planets), len(glider_sequence)
    dp = [0] * (m + 1)
    dp[0] = 1

    for planet in planets:
        for j in range(m - 1, -1, -1):
            if planet == glider_sequence[j]:
                dp[j + 1] += dp[j]

    return dp[m]

def rearrange_pearls(n, pearls):
    from collections import Counter
    import heapq

    if n == 1:
        return ("Possible", pearls)

    # Count the frequency of each pearl type
    count = Counter(pearls)
    max_count = max(count.values())

    # If any pearl type appears more than (n + 1) // 2 times, it's impossible to rearrange
    if max_count > (n + 1) // 2:
        return ("No solution",)

    heap = [(-freq, pearl) for pearl, freq in count.items()]
    heapq.heapify(heap)

    result = [0] * n
    index = 0

    while heap:
        freq, pearl = heapq.heappop(heap)
        freq = -freq

        for _ in range(freq):
            if index >= n:
                index = 1
            result[index] = pearl
            index += 2

    return ("Possible", result)

