import heapq

def dijkstra(n, graph, start):
    """
    Uses Dijkstra's algorithm to find the shortest path from start to all other nodes in the graph.
    """
    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node].items():
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def shortest_path_queries(n, m, q, streets, queries):
    """
    Determines the shortest travel time from a start intersection to a destination intersection.
    """
    graph = {i: {} for i in range(1, n + 1)}

    for u, v, w in streets:
        graph[u][v] = w

    result = []
    for s, d in queries:
        distances = dijkstra(n, graph, s)
        result.append(distances[d] if distances[d] != float('inf') else -1)

    return result

from collections import deque, defaultdict
import sys

def min_time_traversal(n, m, roads, A, B):
    # Construct the graph
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)

    # Handle edge case
    if A == B:
        return 0

    # Breadth-First-Search to find shortest distance in a directed graph
    def bfs(start):
        distances = {i: sys.maxsize for i in range(1, n+1)}
        queue = deque([(start, 0)])
        distances[start] = 0
        while queue:
            current, dist = queue.popleft()
            for neighbor in graph[current]:
                if dist + 1 < distances[neighbor]:
                    distances[neighbor] = dist + 1
                    queue.append((neighbor, dist + 1))
        return distances

    dist_from_A = bfs(A)
    dist_from_B = bfs(B)

    min_distance = dist_from_A[B]

    # Try making use of the teleportation ability once
    for u in range(1, n + 1):
        for v in graph[u]:
            if dist_from_A[u] + 1 + dist_from_B[v] < min_distance:
                min_distance = dist_from_A[u] + 1 + dist_from_B[v]

    return min_distance if min_distance != sys.maxsize else -1

def max_histogram_area(histogram):
    stack = []
    max_area = 0
    index = 0
    while index < len(histogram):
        if not stack or histogram[stack[-1]] <= histogram[index]:
            stack.append(index)
            index += 1
        else:
            top_of_stack = stack.pop()
            area = (histogram[top_of_stack] *
                    ((index - stack[-1] - 1) if stack else index))
            max_area = max(max_area, area)

    while stack:
        top_of_stack = stack.pop()
        area = (histogram[top_of_stack] *
                ((index - stack[-1] - 1) if stack else index))
        max_area = max(max_area, area)

    return max_area

def max_rectangle(grid):
    if not grid:
        return 0

    n = len(grid)
    m = len(grid[0])
    max_area = 0

    heights = [0] * m
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 0:
                heights[j] = 0
            else:
                heights[j] += 1

        max_area = max(max_area, max_histogram_area(heights))

    return max_area

