def can_form_palindrome_directories(filenames):
    from collections import Counter

    def is_palindrome_possible(counter):
        odd_count = sum(v % 2 for v in counter.values())
        return odd_count <= 1

    overall_counter = Counter()

    for filename in filenames:
        overall_counter.update(filename)

    if is_palindrome_possible(overall_counter):
        return "YES"
    else:
        return "NO"

