def largest_uniform_subgrid(n, m, grid):
    max_size = 0
    top_left = (0, 0)
    bottom_right = (0, 0)

    # Create auxiliary arrays to store the size of largest uniform rectangular area ending at (i, j)
    same_value_count = [[[None, None] for _ in range(m)] for _ in range(n)]

    for i in range(n):
        for j in range(m):
            same_value_count[i][j] = [1, 1]
            if i > 0 and grid[i][j] == grid[i - 1][j]:
                same_value_count[i][j][0] = same_value_count[i - 1][j][0] + 1
            if j > 0 and grid[i][j] == grid[i][j - 1]:
                same_value_count[i][j][1] = same_value_count[i][j - 1][1] + 1

            min_size = float('inf')
            for k in range(same_value_count[i][j][1]):
                min_size = min(min_size, same_value_count[i][j - k][0])
                curr_size = min_size * (k + 1)
                if curr_size > max_size:
                    max_size = curr_size
                    top_left = (i - min_size + 1, j - k)
                    bottom_right = (i, j)

    return (top_left[0], top_left[1], bottom_right[0], bottom_right[1])

