from collections import deque

def min_steps_to_reach_end(n, m, grid):
    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return -1

    directions = [(1, 0), (0, 1)]
    visited = [[False] * m for _ in range(n)]
    queue = deque([(0, 0, 0)])  # (row, col, steps)
    visited[0][0] = True

    while queue:
        r, c, steps = queue.popleft()

        if r == n-1 and c == m-1:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < m and not visited[nr][nc] and grid[nr][nc] == '.':
                visited[nr][nc] = True
                queue.append((nr, nc, steps + 1))

    return -1

def max_consecutive_identical(nums):
    """
    Determines the maximum count of consecutive identical integers in the list.
    """
    if not nums:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    max_length = max(max_length, current_length)

    return max_length

