def largest_square_subgrid(grid, n):
    """
    Returns the size of the largest square sub-grid consisting entirely of 1s in the given grid.
    """
    if not grid:
        return 0

    # Create a 2D dp array initialized to 0s
    dp = [[0] * n for _ in range(n)]
    max_size = 0

    # Loop through the grid to fill dp array
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '1':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_size = max(max_size, dp[i][j])

    return max_size

def parse_input_and_find_largest_square(input_data):
    data = input_data.split('\n')
    n = int(data[0])
    grid = data[1:n+1]
    return largest_square_subgrid(grid, n)

