def longest_common_substring_length(games):
    """
    Returns the length of the longest common substring found between any pair of games.
    """
    def common_substring(s1, s2):
        """
        Returns the length of the longest common substring between two strings s1 and s2.
        """
        len1, len2 = len(s1), len(s2)
        dp = [[0] * (len2 + 1) for _ in range(len1 + 1)]
        longest = 0

        for i in range(1, len1 + 1):
            for j in range(1, len2 + 1):
                if s1[i - 1] == s2[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                    longest = max(longest, dp[i][j])
        return longest

    m = len(games)
    max_length = 0

    for i in range(m):
        for j in range(i + 1, m):
            max_length = max(max_length, common_substring(games[i], games[j]))

    return max_length

