def is_valid_parentheses(sequence):
    """
    Determines if the sequence of parentheses is valid.
    """
    stack = []
    for char in sequence:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return "NO"
            stack.pop()

    return "YES" if not stack else "NO"

