def process_numbers(numbers):
    """
    Returns a tuple where the first element is the sum of all even numbers
    and the second element is the product of all odd numbers in the list.
    """
    sum_even = 0
    product_odd = 1
    odd_found = False

    for num in numbers:
        if num % 2 == 0:
            sum_even += num
        else:
            odd_found = True
            product_odd *= num

    if not odd_found:
        product_odd = 0  # Since no odd number present

    return (sum_even, product_odd)

