import heapq

def find_mst_weight(n, weights):
    def prim():
        total_weight = 0
        visited = [False] * n
        min_heap = [(0, 0)]

        while min_heap:
            weight, current = heapq.heappop(min_heap)

            if visited[current]:
                continue

            visited[current] = True
            total_weight += weight

            for neighbor in range(n):
                if not visited[neighbor] and weights[current][neighbor] != 0:
                    heapq.heappush(min_heap, (weights[current][neighbor], neighbor))

        return total_weight

    return prim()

