def unique_paths_with_obstacles(grid):
    """
    Returns the number of unique paths from top-left corner
    to bottom-right corner in the grid while avoiding obstacles.
    """
    n = len(grid)
    m = len(grid[0])

    # If starting or ending point is an obstacle, return 0
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return 0

    # Initialize the DP table
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1  # Start position

    # Fill the DP table
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dp[i][j] = 0 # Obstacle cell
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j] # From top
                if j > 0:
                    dp[i][j] += dp[i][j-1] # From left

    return dp[n-1][m-1]

