import sys
from collections import deque

def dfs(node, parent, depth, values, adj, path_sum, parent_table):
    parent_table[node] = parent
    path_sum[node] = values[node]
    if parent != -1:
        path_sum[node] += path_sum[parent]
    depth[node] = 0 if parent == -1 else depth[parent] + 1

    for neighbor in adj[node]:
        if neighbor != parent:
            dfs(neighbor, node, depth, values, adj, path_sum, parent_table)

def lca(u, v, parent, depth):
    if depth[u] < depth[v]:
        u, v = v, u

    while depth[u] > depth[v]:
        u = parent[u]

    while u != v:
        u = parent[u]
        v = parent[v]

    return u

def find_dominant_path_sum(n, values, edges, queries):
    sys.setrecursionlimit(200000)
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    depth = [-1] * (n + 1)
    path_sum = [-1] * (n + 1)
    parent_table = [-1] * (n + 1)

    dfs(1, -1, depth, values, adj, path_sum, parent_table)

    result = []
    for u, v in queries:
        ancestor = lca(u, v, parent_table, depth)
        result.append(path_sum[u] + path_sum[v] - 2 * path_sum[ancestor] + values[ancestor])

    return result

def count_pairs_with_sum(arr, target):
    """
    Returns the number of unique pairs of integers in the array that sum up to the target value.
    """
    seen = set()
    pairs = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            pairs.add((min(num, complement), max(num, complement)))
        seen.add(num)

    return len(pairs)

