def find_hamiltonian_cycle(N, M, A, edges):
    from collections import defaultdict

    # Create the adjacency list of the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Helper function to check for Hamiltonian cycle using backtracking
    def backtrack(path):
        current = path[-1]

        # If path length equals N and there's an edge back to the start node
        if len(path) == N:
            if A in graph[current]:
                path.append(A)
                return path
            else:
                return None

        for neighbor in graph[current]:
            if neighbor not in path:
                result = backtrack(path + [neighbor])
                if result:
                    return result

        return None

    cycle = backtrack([A])

    if cycle:
        return f"Cycle found: {' '.join(map(str, cycle))}"
    else:
        return "No Hamiltonian Cycle"

