from collections import Counter
import heapq

def rearrange_string(s: str, k: int) -> str:
    if k == 1:
        return s  # Any string satisfies this condition trivially

    counter = Counter(s)
    max_heap = [(-freq, ch) for ch, freq in counter.items()]
    heapq.heapify(max_heap)

    result = []
    queue = []

    while max_heap:
        freq, ch = heapq.heappop(max_heap)
        result.append(ch)
        queue.append((ch, freq + 1))

        if len(queue) >= k:
            prev_ch, prev_freq = queue.pop(0)
            if -prev_freq > 0:
                heapq.heappush(max_heap, (prev_freq, prev_ch))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return "Not possible"

