def max_tasks_on_time(durations, deadlines):
    tasks = sorted(zip(durations, deadlines), key=lambda x: x[1])  # Sort tasks by deadline
    current_time = 0
    completed_tasks = 0

    for duration, deadline in tasks:
        if current_time + duration <= deadline:
            current_time += duration
            completed_tasks += 1

    return completed_tasks

