def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while (i * i) <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def is_valid_grid(grid, n):
    elements = set()
    for row in grid:
        elements.update(row)

    for i in range(n):
        for j in range(n):
            num = grid[i][j]
            if is_prime(num):
                continue
            valid = False
            for a in elements:
                if num % a == 0 and (num // a) in elements:
                    valid = True
                    break
            if not valid:
                return "Invalid"
    return "Valid"

def validate_bacterial_growth_grid(n, grid):
    return is_valid_grid(grid, n)

