def max_subarray(arr: list[int]) -> tuple[int, int, int]:
    # Initialize variables
    max_sum = curr_sum = arr[0]
    start = end = s = 0

    for i in range(1, len(arr)):
        if curr_sum < 0:
            curr_sum = arr[i]
            s = i
        else:
            curr_sum += arr[i]

        if curr_sum > max_sum or (curr_sum == max_sum and (i - s > end - start)):
            max_sum = curr_sum
            start = s
            end = i

    return (max_sum, start, end)

