def is_valid_expression(expression: str) -> bool:
    if not expression:
        return False

    valid_chars = set("0123456789+-*/()")
    stack = []

    last_char = ""

    for char in expression:
        if char not in valid_chars:
            return False

        if char in "0123456789":
            if last_char in "0123456789":
                last_char = "0" # continue, valid scenario
            else:
                last_char = "0"
        elif char in "+-*/":
            if last_char in "+-*/(" or last_char == "":
                return False
            last_char = char
        elif char == "(":
            stack.append(char)
            last_char = char
        elif char == ")":
            if not stack or last_char in "+-*/(":
                return False
            stack.pop()
            last_char = char

    if stack:
        return False

    if last_char in "+-*/(":
        return False

    return True

