def longest_non_decreasing_subsequence_length(s: str) -> int:
    """
    Returns the length of the longest non-decreasing subsequence in the string.
    """
    # If the string is empty, the longest subsequence is 0.
    if not s:
        return 0

    # Dynamic programming array to store lengths of longest non-decreasing subsequence
    dp = [1] * len(s)

    for i in range(1, len(s)):
        for j in range(i):
            if s[i] >= s[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

