def largest_square_submatrix(matrix):
    """
    Returns the size of the largest square sub-matrix consisting entirely of '1's.
    """
    if not matrix or not matrix[0]:
        return 0

    n = len(matrix)
    dp = [[0] * n for _ in range(n)]
    max_side = 0

    for i in range(n):
        for j in range(n):
            if matrix[i][j] == '1':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

