from typing import List

def maxSumWithConstraint(arr: List[int]) -> int:
    """
    Returns the maximum possible sum of a subsequence of the array
    such that no two elements in the subsequence are adjacent in
    the original array.
    """
    n = len(arr)

    if n == 0:
        return 0
    elif n == 1:
        return max(0, arr[0])

    # Initialize DP array
    dp = [0] * n
    dp[0] = max(0, arr[0])
    if n > 1:
        dp[1] = max(dp[0], arr[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], dp[i-2] + arr[i])

    return dp[-1]

