def validate_and_format_date(s):
    if len(s) != 8:
        return "INVALID"

    year = s[:4]
    month = s[4:6]
    day = s[6:]

    try:
        year = int(year)
        month = int(month)
        day = int(day)
    except ValueError:
        return "INVALID"

    # Check year range
    if year < 1000 or year > 9999:
        return "INVALID"

    # Check month range
    if month < 1 or month > 12:
        return "INVALID"

    # Check day range
    if day < 1 or day > 31:
        return "INVALID"

    # Additional check for days in each month
    # April, June, September and November have 30 days
    if month in [4, 6, 9, 11] and day > 30:
        return "INVALID"

    # February has 28 days in common years and 29 days in leap years
    if month == 2:
        if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):  # Check for leap year
            if day > 29:
                return "INVALID"
        else:
            if day > 28:
                return "INVALID"

    return f"{str(day).zfill(2)}-{str(month).zfill(2)}-{year}"

import re

def extract_mobile_numbers(T, messages):
    valid_mobile_pattern = re.compile(r'\b[2-9]\d{9}\b')

    results = []
    for i in range(T):
        message = messages[i]
        found_numbers = set(valid_mobile_pattern.findall(message))
        if found_numbers:
            sorted_numbers = sorted(found_numbers)
            results.append(" ".join(sorted_numbers))
        else:
            results.append("None")

    return results

