def max_crops_planted(m, n, grid):
    def is_safe(x, y):
        # Check if placing crop at (x, y) violates any constraints
        if x > 0 and grid[x-1][y] == 'P':
            return False
        if y > 0 and grid[x][y-1] == 'P':
            return False
        if x < m-1 and grid[x+1][y] == 'P':
            return False
        if y < n-1 and grid[x][y+1] == 'P':
            return False
        return True

    def place_crops():
        count = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 'E' and is_safe(i, j):
                    grid[i][j] = 'P'  # Plant crop
                    count += 1
        return count

    grid = [list(row) for row in grid]
    return place_crops()

