import heapq
from collections import defaultdict
import sys

def least_cost_path(n, m, edges, s, t):
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    min_heap = [(0, s)] # (cost, vertex)
    distances = {i: sys.maxsize for i in range(1, n+1)}
    distances[s] = 0

    while min_heap:
        current_cost, vertex = heapq.heappop(min_heap)

        if vertex == t:
            return current_cost

        if current_cost > distances[vertex]:
            continue

        for neighbor, weight in graph[vertex]:
            distance = current_cost + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(min_heap, (distance, neighbor))

    return -1 if distances[t] == sys.maxsize else distances[t]

def max_repeating_substring(s, k):
    from collections import defaultdict
    max_repeats = 0

    for i in range(0, 10**k):
        candidate = str(i).zfill(k)
        j, n = 0, len(s)
        new_string = []
        while j < n:
            if s[j] == '?' or s[j] == candidate[0]:
                match = True
                temp = candidate
                for m in range(k):
                    if j + m >= n or (s[j + m] != '?' and s[j + m] != temp[m]):
                        match = False
                        break
                if match:
                    new_string.extend(temp)
                    j += k
                else:
                    new_string.append(s[j])
                    j += 1
            else:
                new_string.append(s[j])
                j += 1

        count_dict = defaultdict(int)
        new_s = ''.join(new_string)
        for l in range(len(new_s) - k + 1):
            substring = new_s[l:l + k]
            count_dict[substring] += 1

        max_repeats = max(max_repeats, max(count_dict.values(), default=0))

    return max_repeats

