from collections import deque

def min_moves_to_reach_destination(grid):
    n = len(grid)
    m = len(grid[0])

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return "Impossible"

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    queue = deque([(0, 0, 0)])  # row, column, distance
    visited = set((0, 0))

    while queue:
        r, c, dist = queue.popleft()

        if r == n-1 and c == m-1:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == '.' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return "Impossible"

def length_of_shortest_balanced_substring(t, test_cases):
    results = []

    for s in test_cases:
        n = len(s)
        min_len = float('inf')
        count_a = count_b = count_c = 0
        left = 0

        for right in range(n):
            if s[right] == 'a':
                count_a += 1
            elif s[right] == 'b':
                count_b += 1
            elif s[right] == 'c':
                count_c += 1

            while count_a > 0 and count_b > 0 and count_c > 0:
                min_len = min(min_len, right - left + 1)

                if s[left] == 'a':
                    count_a -= 1
                elif s[left] == 'b':
                    count_b -= 1
                elif s[left] == 'c':
                    count_c -= 1

                left += 1

        results.append(min_len if min_len != float('inf') else -1)

    return results

