def find_road(grid, n):
    def is_valid(x, y, visited):
        return 0 <= x < n and 0 <= y < n and grid[x][y] == 'E' and (x, y) not in visited

    def backtrack(x, y, path):
        if (x, y) == (n - 1, n - 1):
            return True

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, path):
                path.append((nx, ny))
                if backtrack(nx, ny, path):
                    return True
                path.pop()
        return False

    path = [(0, 0)]
    if backtrack(0, 0, path):
        return ["Possible"] + [(x + 1, y + 1) for x, y in path]
    else:
        return ["Impossible"]

def solve(n, grid):
    output = find_road(grid, n)
    if output[0] == "Impossible":
        print("Impossible")
    else:
        print("Possible")
        for x, y in output[1:]:
            print(x, y)

def increment_submatrices(n, m, queries):
    # Initialize the matrix with zeroes
    matrix = [[0] * m for _ in range(n)]

    # Process each query
    for query in queries:
        i1, j1, i2, j2, k = query
        for i in range(i1 - 1, i2):
            for j in range(j1 - 1, j2):
                matrix[i][j] += k

    return matrix

