import heapq
from collections import defaultdict

def min_distribution_hubs(n, m, roads, d):
    def dijkstra(graph, start):
        distances = {i: float('inf') for i in range(1, n+1)}
        distances[start] = 0
        priority_queue = [(0, start)]
        while priority_queue:
            current_distance, current_node = heapq.heappop(priority_queue)
            if current_distance > distances[current_node]:
                continue
            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    heapq.heappush(priority_queue, (distance, neighbor))
        return distances

    graph = defaultdict(list)
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    covered = set()
    hubs = 0

    while len(covered) < n:
        max_cover = 0
        best_city = None
        for i in range(1, n+1):
            if i not in covered:
                distances = dijkstra(graph, i)
                cover = sum(1 for city, dist in distances.items() if dist <= d and city not in covered)
                if cover > max_cover:
                    max_cover = cover
                    best_city = i
        distances = dijkstra(graph, best_city)
        for city, dist in distances.items():
            if dist <= d:
                covered.add(city)
        hubs += 1

    return hubs

