def minPages(arr, n, m):
    def isPossible(arr, n, m, curr_min):
        studentsRequired = 1
        curr_sum = 0

        for i in range(n):
            if arr[i] > curr_min:
                return False

            if curr_sum + arr[i] > curr_min:
                studentsRequired += 1
                curr_sum = arr[i]

                if studentsRequired > m:
                    return False
            else:
                curr_sum += arr[i]

        return True

    if n < m:
        return -1

    total_pages = sum(arr)
    start, end = 0, total_pages
    result = float('inf')

    while start <= end:
        mid = (start + end) // 2
        if isPossible(arr, n, m, mid):
            result = min(result, mid)
            end = mid - 1
        else:
            start = mid + 1

    return result

from typing import List
from collections import deque

def find_shortest_path(n: int, maze: List[str]) -> int:
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])
    visited = set((0, 0))

    # Check the initial and final positions are open
    if maze[0][0] == '#' or maze[n-1][n-1] == '#':
        return -1

    while queue:
        x, y, steps = queue.popleft()

        if x == n - 1 and y == n - 1:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and maze[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1

