import heapq

def minimum_spanning_tree_cost(n, matrix):
    def prim(cost_matrix, start):
        min_cost = 0
        visited = [False] * n
        min_heap = [(0, start)]  # (cost, to_node)
        while min_heap:
            cost, node = heapq.heappop(min_heap)
            if visited[node]:
                continue
            min_cost += cost
            visited[node] = True
            for adjacent in range(n):
                if cost_matrix[node][adjacent] != -1 and not visited[adjacent]:
                    heapq.heappush(min_heap, (cost_matrix[node][adjacent], adjacent))
        # If not all nodes are visited, it means the graph isn't fully connected
        if not all(visited):
            return -1
        return min_cost

    return prim(matrix, 0)

