def is_possible_to_connect(n, m, edges):
    from collections import defaultdict, deque

    def bfs(start, visited, adj):
        q = deque([start])
        visited.add(start)
        while q:
            node = q.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append(neighbor)

    if n == 1:
        return "YES"

    # Create adjacency list
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Find all connected components
    visited = set()
    components = 0
    for i in range(1, n + 1):
        if i not in visited:
            bfs(i, visited, adj)
            components += 1

    # Check if it is possible to connect the graph by adding at most one edge
    if components <= 2:
        return "YES"
    else:
        return "NO"

