def count_increasing_triplets(arr):
    """
    Returns the number of increasing triplets (i, j, k) such that 0 <= i < j < k < n and arr[i] < arr[j] < arr[k].
    """
    n = len(arr)
    if n < 3:
        return 0

    count = 0

    # We will use a nested loop to count the number of valid triplets
    for j in range(1, n-1):
        left_count = 0
        right_count = 0
        for i in range(j):
            if arr[i] < arr[j]:
                left_count += 1
        for k in range(j+1, n):
            if arr[j] < arr[k]:
                right_count += 1
        count += left_count * right_count

    return count

