def is_strong_password(s):
    """
    Check if the password s is a strong password.
    A strong password contains at least one lowercase letter, one digit,
    and does not have three consecutive identical characters.
    """
    has_lowercase = False
    has_digit = False

    # Check for at least one lowercase letter and one digit
    for char in s:
        if char.islower():
            has_lowercase = True
        if char.isdigit():
            has_digit = True

    # Check for three consecutive identical characters
    for i in range(len(s) - 2):
        if s[i] == s[i + 1] == s[i + 2]:
            return "NO"

    if has_lowercase and has_digit:
        return "YES"
    else:
        return "NO"

