from typing import List

def find_two_sum(nums: List[int], target: int) -> List[int]:
    """
    Find two distinct elements in the array that add up to the target sum.
    Return their indices in non-decreasing order. If no such pair exists, return an empty list.
    """
    num_to_index = {}

    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], index]
        num_to_index[num] = index

    return []

