def number_of_balanced_sequences(n):
    MOD = 998244353

    # Helper to compute modular inverse
    def mod_inverse(a, p):
        return pow(a, p - 2, p)

    # Compute the nth Catalan number
    C = [0] * (n + 1)
    C[0] = 1
    for i in range(1, n + 1):
        C[i] = C[i - 1] * (4 * i - 2) * mod_inverse(i + 1, MOD) % MOD

    return C[n]

