def smallest_duplicate(n, arr):
    """
    Returns the smallest registration number that appears more than once.
    If all numbers are unique, returns -1.
    """
    seen = {}
    smallest_dup = float('inf')

    for num in arr:
        if num in seen:
            seen[num] += 1
            if num < smallest_dup:
                smallest_dup = num
        else:
            seen[num] = 1

    if smallest_dup == float('inf'):
        return -1
    return smallest_dup

