def largest_rectangle_area(heights):
    """
    Given a list of integers representing the height of vertical lines in a histogram,
    return the area of the largest rectangle that can be formed within the histogram.
    """
    stack = []
    max_area = 0
    for i, h in enumerate(heights):
        while stack and heights[stack[-1]] > h:
            height = heights[stack.pop()]
            if stack:
                width = i - stack[-1] - 1
            else:
                width = i
            max_area = max(max_area, height * width)
        stack.append(i)

    while stack:
        height = heights[stack.pop()]
        if stack:
            width = len(heights) - stack[-1] - 1
        else:
            width = len(heights)
        max_area = max(max_area, height * width)

    return max_area

def get_input_and_solve(n, heights):
    """
    Helper function to parse input and return the result for largest_rectangle_area.
    """
    return largest_rectangle_area(heights)

