def can_select_three_baskets(n, S, apples):
    """
    Determines if there are exactly three baskets whose apples sum up to S.

    Parameters:
    n (int): Number of baskets.
    S (int): Target sum.
    apples (List[int]): Number of apples in each basket.

    Returns:
    str: "YES" if there is a combination of three baskets that sum to S, otherwise "NO".
    """
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if apples[i] + apples[j] + apples[k] == S:
                    return "YES"
    return "NO"

