def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def is_valid_user_list(user_ids):
    """
    Check if the list of user IDs is valid based on the given criteria.
    """
    if not all(isinstance(id, int) and id > 0 for id in user_ids):
        return False

    if len(user_ids) != len(set(user_ids)):
        return False

    return is_prime(sum(user_ids))

