def smallest_k_chars(k, s):
    """
    Returns the lexicographically smallest string that can be formed by selecting k different characters
    from the given string. If it is not possible to select k different characters, returns an empty string.
    """
    unique_chars = sorted(set(s))
    if len(unique_chars) < k:
        return ""
    return ''.join(unique_chars[:k])

