def is_path_possible(h, w, grid):
    def is_in_bounds(x, y):
        return 0 <= x < h and 0 <= y < w

    def dfs(x, y):
        if x == h - 1 and y == w - 1:
            return True
        for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx, ny = x + dx, y + dy
            if is_in_bounds(nx, ny) and grid[nx][ny] == '.' and not visited[nx][ny]:
                visited[nx][ny] = True
                if dfs(nx, ny):
                    return True
        return False

    if grid[0][0] == '#' or grid[h - 1][w - 1] == '#':
        return "NO"

    visited = [[False] * w for _ in range(h)]
    visited[0][0] = True
    return "YES" if dfs(0, 0) else "NO"

# Function to receive input and return result
def grid_path(h, w, grid):
    return is_path_possible(h, w, grid)

def count_unique_sequences(n):
    """
    Calculate the number of unique sequences of non-negative integers that sum up to n.
    """
    dp = [1] + [0] * n

    for i in range(1, n+1):
        for j in range(i, n+1):
            dp[j] += dp[j-i]

    return dp[n]

