def smallest_prime_factors(m, primes):
    def sieve(n):
        spf = list(range(n+1))  # Smallest Prime Factor for each number
        for p in range(2, int(n**0.5) + 1):
            if spf[p] == p:  # p is a prime number
                for k in range(p * p, n + 1, p):
                    if spf[k] == k:
                        spf[k] = p
        return spf

    results = []
    max_prime = max(primes)
    spf = sieve(max_prime)

    for prime in primes:
        results.append(spf[1:prime+1])

    return results

