from typing import List

def minCostClimbingStairs(cost: List[int]) -> int:
    n = len(cost)
    if n == 1:
        return cost[0]
    elif n == 2:
        return min(cost[0], cost[1])

    # Initialize the min cost for the first two steps
    min_cost = [0] * n
    min_cost[0] = cost[0]
    min_cost[1] = cost[1]

    # Calculate the min cost to reach each step
    for i in range(2, n):
        min_cost[i] = cost[i] + min(min_cost[i-1], min_cost[i-2])

    # The minimum cost to reach the top of the stairs will be the minimum of the last two steps
    return min(min_cost[n-1], min_cost[n-2])

