from collections import deque

def within_bounds(x, y, n, m):
    return 0 <= x < n and 0 <= y < m

def bfs_minimum_time(grid, n, m, sx, sy, dx, dy):
    if grid[sx][sy] == '#' or grid[dx][dy] == '#':
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * m for _ in range(n)]
    queue = deque([(sx, sy, 0)])  # (x, y, distance)
    visited[sx][sy] = True

    while queue:
        x, y, distance = queue.popleft()
        if x == dx and y == dy:
            return distance

        for direction in directions:
            nx, ny = x + direction[0], y + direction[1]

            if within_bounds(nx, ny, n, m) and not visited[nx][ny] and grid[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny, distance + 1))

    return -1

def maze_runner(n, m, grid, queries):
    results = []
    for sx, sy, dx, dy in queries:
        results.append(bfs_minimum_time(grid, n, m, sx, sy, dx, dy))
    return results

def longest_increasing_subarray(n, temperatures):
    if n == 0:
        return 0, []

    max_length = 1
    current_length = 1
    start_index = 0
    best_start_index = 0

    for i in range(1, n):
        if temperatures[i] > temperatures[i - 1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                best_start_index = start_index
            current_length = 1
            start_index = i

    if current_length > max_length:
        max_length = current_length
        best_start_index = start_index

    return max_length, temperatures[best_start_index:best_start_index + max_length]

def schedule_festivals(t, test_cases):
    results = []
    for regions, days, neighborhoods in test_cases:
        schedules = []
        possible = True
        for n in neighborhoods:
            if days < n:
                possible = False
                break
            cycle = []
            for i in range(days):
                cycle.append((i % n) + 1)
            schedules.append(cycle)

        if possible:
            results.append("YES")
            for sch in schedules:
                results.append(" ".join(map(str, sch)))
        else:
            results.append("NO")
    return results

def min_operations(source: str, target: str) -> int:
    """
    Returns the minimum number of operations required to transform the source string into the target string.
    """
    m, n = len(source), len(target)

    # Create a DP table where dp[i][j] represents the minimum number of operations
    # required to convert source[0:i] to target[0:j]
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the DP table
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If source is empty, insert all characters of target
            elif j == 0:
                dp[i][j] = i  # If target is empty, delete all characters of source
            elif source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # If last characters are same, ignore
            else:
                # Consider all three operations and find minimum
                dp[i][j] = 1 + min(dp[i][j - 1],     # Insert
                                   dp[i - 1][j],     # Delete
                                   dp[i - 1][j - 1]) # Replace

    return dp[m][n]

import heapq

def dijkstra(n, graph, distribution_centers):
    """
    Performs Dijkstra's algorithm from multiple sources (distribution centers).
    Returns the minimum delivery times from any distribution center to each intersection.
    """
    dist = {i: float('inf') for i in range(1, n + 1)}
    pq = []

    # Initialize the priority queue with all distribution centers
    for center in distribution_centers:
        heapq.heappush(pq, (0, center))
        dist[center] = 0

    while pq:
        current_time, u = heapq.heappop(pq)

        # If the current delivery time is greater than the recorded time, skip this entry
        if current_time > dist[u]:
            continue

        for v, time in graph[u]:
            new_time = current_time + time
            if new_time < dist[v]:
                dist[v] = new_time
                heapq.heappush(pq, (new_time, v))

    return dist

def minimum_delivery_time(n, m, k, roads, distribution_centers):
    graph = {i: [] for i in range(1, n + 1)}

    for u, v, t in roads:
        graph[u].append((v, t))

    # If there are no distribution centers
    if k == 0:
        return -1

    dist = dijkstra(n, graph, distribution_centers)

    min_delivery_time = float('inf')

    for intersection in range(1, n + 1):
        if intersection not in distribution_centers:
            min_delivery_time = min(min_delivery_time, dist[intersection])

    return min_delivery_time if min_delivery_time != float('inf') else -1

def min_operations_to_palindrome(s):
    """
    Returns the minimum number of operations required to make the string s a palindrome.
    """
    n = len(s)
    operations = 0

    for i in range(n // 2):
        if s[i] != s[n - i - 1]:
            operations += 1

    return operations

