import sys

def range_minimum_query(prices, ranges):
    """
    Returns the minimum price in the given range for each query.
    """
    n = len(prices)
    st = [[0] * (n + 1) for _ in range(20)]
    LOG = [0] * (n + 1)

    def build_sparse_table():
        for i in range(n):
            st[0][i] = prices[i]
        j = 1
        while (1 << j) <= n:
            i = 0
            while (i + (1 << j) - 1) < n:
                st[j][i] = min(st[j - 1][i], st[j - 1][i + (1 << (j - 1))])
                i += 1
            j += 1

    def query(L, R):
        j = LOG[R - L + 1]
        return min(st[j][L], st[j][R - (1 << j) + 1])

    # Precompute the log table
    for i in range(2, n + 1):
        LOG[i] = LOG[i // 2] + 1

    # Build the sparse table
    build_sparse_table()

    results = []
    for l, r in ranges:
        results.append(query(l - 1, r - 1))

    return results

