def contains_nearby_duplicate(nums, k):
    """
    Determines whether there exist two distinct indices i and j in the array such that nums[i] = nums[j]
    and the absolute difference between i and j is at most k.
    """
    value_indices = {}

    for i, num in enumerate(nums):
        if num in value_indices and i - value_indices[num] <= k:
            return True
        value_indices[num] = i

    return False

def is_path_possible(grid):
    m = len(grid)
    n = len(grid[0])

    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] == '#':
            return False
        if x == m-1 and y == n-1:
            return True
        grid[x][y] = '#'  # Marking the cell as visited by changing it to '#'
        return dfs(x+1, y) or dfs(x-1, y) or dfs(x, y+1) or dfs(x, y-1)

    if grid[0][0] == '#' or grid[m-1][n-1] == '#':
        return "NO"

    return "YES" if dfs(0, 0) else "NO"

