def find_max_min_edge(n, m, edges):
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    def is_connected():
        # Check if all nodes are connected
        root = find(1)
        for i in range(2, n + 1):
            if find(i) != root:
                return False
        return True

    edges.sort(key=lambda x: -x[2])

    for u, v, w in edges:
        union(u, v)
        if is_connected():
            return w

    return -1

