from collections import deque

def min_steps_to_destination(grid, start, destination):
    n = len(grid)
    m = len(grid[0])
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    start = (start[0] - 1, start[1] - 1)
    destination = (destination[0] - 1, destination[1] - 1)

    if start == destination:
        return 0

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == 0

    queue = deque([(start[0], start[1], 0)])
    visited = set([(start[0], start[1])])

    while queue:
        x, y, steps = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if (nx, ny) == destination:
                return steps + 1

            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1  # should never reach here since it is guaranteed there is a valid path

def parse_input(input_string):
    lines = input_string.strip().split("\n")
    n, m = map(int, lines[0].split())
    grid = [list(map(int, lines[i + 1].split())) for i in range(n)]
    x1, y1, x2, y2 = map(int, lines[n + 1].split())
    return grid, (x1, y1), (x2, y2)

def solve(city_grid_input):
    grid, start, end = parse_input(city_grid_input)
    return min_steps_to_destination(grid, start, end)

