def max_difficulty(n, matches):
    # Sort the matches by end time for easier processing
    matches.sort(key=lambda x: x[1])

    # dp array to store the maximum difficulty up to each match
    dp = [0] * n
    dp[0] = matches[0][2]

    for i in range(1, n):
        include = matches[i][2]
        # Find the latest match that doesn't overlap with current match[i]
        for j in range(i - 1, -1, -1):
            if matches[j][1] <= matches[i][0]:
                include += dp[j]
                break
        dp[i] = max(include, dp[i - 1])

    return max(dp)

