def process_queries(n, m, S, queries):
    S = list(S)  # Convert the string to a list for mutability

    results = []

    for query in queries:
        query_type, x, y = query

        # Convert 1-indexed to 0-indexed
        x -= 1
        y -= 1

        if query_type == 1:
            # Reverse the substring S[x:y+1]
            S[x:y+1] = S[x:y+1][::-1]
        elif query_type == 2:
            # Check if substring S[x:y+1] is a palindrome
            substring = S[x:y+1+1]
            if substring == substring[::-1]:
                results.append("YES")
            else:
                results.append("NO")

    return results

