from typing import List
from collections import deque

def min_moves(m: int, n: int, grid: List[List[int]]) -> int:
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set()
    visited.add((0, 0))

    while queue:
        r, c, dist = queue.popleft()

        if r == m - 1 and c == n - 1:
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited and grid[nr][nc] == 0:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return -1

def longest_substring_with_k_distinct_chars(s, k):
    """
    Returns the length of the longest substring with at most k distinct characters.
    """
    n = len(s)
    if n * k == 0:
        return 0

    left, right = 0, 0
    max_length = 1
    char_frequency = {}

    while right < n:
        char_frequency[s[right]] = char_frequency.get(s[right], 0) + 1
        while len(char_frequency) > k:
            char_frequency[s[left]] -= 1
            if char_frequency[s[left]] == 0:
                del char_frequency[s[left]]
            left += 1
        max_length = max(max_length, right - left + 1)
        right += 1

    return max_length

