def count_valid_subsequences(n, k, array):
    """
    Returns the number of distinct subsequences whose sum is divisible by k.
    """
    import itertools

    count = 0
    for r in range(1, n + 1):
        for subseq in itertools.combinations(array, r):
            if sum(subseq) % k == 0:
                count += 1

    return count

