def is_valid_license(key: str) -> bool:
    """
    Checks if a license key is valid.
    A license key is valid if:
    - It is exactly 16 characters long.
    - It contains at least one uppercase letter, one lowercase letter, and one digit.
    - All characters in the key are alphanumeric.
    """
    if len(key) != 16:
        return False

    has_upper = False
    has_lower = False
    has_digit = False

    for char in key:
        if char.isupper():
            has_upper = True
        elif char.islower():
            has_lower = True
        elif char.isdigit():
            has_digit = True
        else:
            return False

    return has_upper and has_lower and has_digit

def longest_distinct_subarray_length(n, arr):
    """
    Returns the length of the longest contiguous subarray with all distinct elements.
    """
    if n == 0:
        return 0

    max_length = 0
    start = 0
    seen = {}

    for end in range(n):
        if arr[end] in seen and seen[arr[end]] >= start:
            start = seen[arr[end]] + 1
        seen[arr[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

