import math
from itertools import permutations

def max_towers_charged(n, E, towers):
    def euclidean_distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    max_charged = 0

    for perm in permutations(towers):
        energy = E
        charged = 0
        for i in range(len(perm)):
            if i == 0:
                energy -= perm[i][2]
            else:
                energy -= euclidean_distance((perm[i-1][0], perm[i-1][1]), (perm[i][0], perm[i][1]))
                energy -= perm[i][2]

            if energy >= 0:
                charged += 1
            else:
                break
        max_charged = max(max_charged, charged)

    return max_charged

