def is_balanced(n, edges):
    from collections import defaultdict

    def height_and_balance(node):
        if node not in children:
            return 0, True
        left_height, right_height = 0, 0
        left_balanced, right_balanced = True, True

        if children[node][0] != -1:
            left_height, left_balanced = height_and_balance(children[node][0])

        if children[node][1] != -1:
            right_height, right_balanced = height_and_balance(children[node][1])

        height = max(left_height, right_height) + 1
        balanced = left_balanced and right_balanced and abs(left_height - right_height) <= 1
        return height, balanced

    children = defaultdict(lambda: [-1, -1])
    for u, v in edges:
        if children[u][0] == -1:
            children[u][0] = v
        else:
            children[u][1] = v

    return "YES" if height_and_balance(1)[1] else "NO"

