def min_flags_to_place(n, heights):
    if n == 0:
        return 0

    left_max = [0] * n
    right_max = [0] * n
    flags_set = set()

    # Traverse from left to right to find increasing max heights.
    left_max[0] = heights[0]
    flags_set.add(heights[0])  # Place flag on the first building
    for i in range(1, n):
        left_max[i] = max(left_max[i-1], heights[i])
        if heights[i] > left_max[i-1]:
            flags_set.add(heights[i])  # Place flag if it's the highest so far

    # Traverse from right to left to find increasing max heights.
    right_max[-1] = heights[-1]
    flags_set.add(heights[-1])  # Place flag on the last building
    for i in range(n-2, -1, -1):
        right_max[i] = max(right_max[i+1], heights[i])
        if heights[i] > right_max[i+1]:
            flags_set.add(heights[i])  # Place flag if it's the highest so far

    # The number of flags needed is the size of the set of unique flagged buildings
    return len(flags_set)

