    Returns a list of integers where each integer is the minimum number of operations required
    for the corresponding test case to make the string have no two adjacent characters that are the same.
    """
    results = []
    for s in test_cases:
        operations = 0
        for i in range(1, len(s)):
            if s[i] == s[i-1]:
                operations += 1
        results.append(operations)
    return results

