def kth_distinct_integer(n, k, array):
    """
    Returns the k-th distinct integer in the sorted list of distinct integers from the array
    or -1 if there are fewer than k distinct integers.
    """
    distinct_integers = sorted(set(array))  # Get distinct integers and sort them.
    if k <= len(distinct_integers):
        return distinct_integers[k - 1]  # k is 1-based index.
    else:
        return -1

