def is_subsequence(s, t):
    """
    Checks if t can be formed by deleting some characters of s.
    """
    t_index = 0
    t_length = len(t)

    if t_length == 0:
        return "Yes"

    for char in s:
        if char == t[t_index]:
            t_index += 1
        if t_index == t_length:
            return "Yes"

    return "No"

