def longest_divisible_subsequence(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Sort the array
    arr.sort()

    # dp[i] will store the length of the longest divisible subsequence ending with arr[i]
    dp = [1] * n

    # Compute the lengths of LDS
    for i in range(1, n):
        for j in range(i):
            if arr[i] % arr[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest divisible subsequence
    return max(dp)

