from math import sqrt

def min_euclidean_distance(n, a):
    min_distance = float('inf')

    for i in range(n - 1):
        for j in range(i + 1, n):
            distance = sqrt((i - j)**2 + (a[i] - a[j])**2)
            if distance < min_distance:
                min_distance = distance

    return round(min_distance, 6)

