def sum_of_connected_components_values(n, m, node_values, edges):
    from collections import defaultdict, deque

    # Create adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u - 1].append(v - 1)
        adj_list[v - 1].append(u - 1)

    def bfs(start_node):
        q = deque([start_node])
        max_value = node_values[start_node]
        visited[start_node] = True
        while q:
            node = q.popleft()
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    q.append(neighbor)
                    max_value = max(max_value, node_values[neighbor])
        return max_value

    visited = [False] * n
    total_sum = 0

    for i in range(n):
        if not visited[i]:
            total_sum += bfs(i)

    return total_sum

