def min_steps_to_reach_end(n, m, grid):
    from collections import deque

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return "No"

    directions = [(0, 1), (1, 0)]  # right, down
    queue = deque([(0, 0)])
    steps = [[float('inf')] * m for _ in range(n)]
    steps[0][0] = 0

    while queue:
        x, y = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and steps[nx][ny] > steps[x][y] + 1:
                steps[nx][ny] = steps[x][y] + 1
                queue.append((nx, ny))

    return steps[n-1][m-1] if steps[n-1][m-1] != float('inf') else "No"

