def can_transform_to_palindrome(test_cases):
    results = []

    for s in test_cases:
        counts = {}

        # Count frequency of each character
        for char in s:
            if char in counts:
                counts[char] += 1
            else:
                counts[char] = 1

        # Count characters with odd frequencies
        odd_count = sum(1 for count in counts.values() if count % 2 == 1)

        # A string can be rearranged into a palindrome if:
        # - At most one character has an odd count
        if odd_count <= 1:
            results.append("YES")
        else:
            results.append("NO")

    return results

