def max_sum_submatrix(matrix):
    def kadane(arr):
        max_sum = float('-inf')
        current_sum = 0
        for x in arr:
            current_sum = max(current_sum + x, x)
            max_sum = max(max_sum, current_sum)
        return max_sum

    n = len(matrix)
    m = len(matrix[0])
    max_sum = float('-inf')

    for left in range(m):
        temp = [0] * n

        for right in range(left, m):
            for i in range(n):
                temp[i] += matrix[i][right]

            max_sum = max(max_sum, kadane(temp))

    return max_sum

def max_sum_submatrices(test_cases):
    results = []
    for case in test_cases:
        n, m, matrix = case
        results.append(max_sum_submatrix(matrix))
    return results

