def longest_subsequence(nums):
    """
    Function to find the longest subsequence where the difference between
    consecutive elements is either 1 or -1.

    Args:
    nums (list of int): The input list of integers

    Returns:
    int: The length of the longest valid subsequence
    """
    if not nums:
        return 0

    n = len(nums)
    longest = [1] * n

    for i in range(1, n):
        for j in range(i):
            if abs(nums[i] - nums[j]) == 1:
                longest[i] = max(longest[i], longest[j] + 1)

    return max(longest)

