def largest_rectangle(grid):
    m, n = len(grid), len(grid[0])
    max_area = 0

    def get_heights(grid, color):
        heights = [0] * n
        for row in grid:
            for j in range(n):
                if row[j] == color:
                    heights[j] += 1
                else:
                    heights[j] = 0
        return heights

    def largest_histogram_area(heights):
        stack = []
        max_area = 0
        heights.append(0)

        for i in range(len(heights)):
            while stack and heights[stack[-1]] > heights[i]:
                h = heights[stack.pop()]
                width = i if not stack else i - stack[-1] - 1
                max_area = max(max_area, h * width)
            stack.append(i)

        heights.pop()  # remove the appended 0
        return max_area

    unique_colors = set()
    for row in grid:
        unique_colors.update(row)

    for color in unique_colors:
        heights = get_heights(grid, color)
        max_area = max(max_area, largest_histogram_area(heights))

    return max_area

