def is_valid_bracket_sequence(s: str) -> str:
    """
    Determines if the input string `s` is a valid bracket sequence.
    Returns "YES" if it is valid, otherwise returns "NO".
    """
    stack = []
    matching_bracket = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack.pop() != matching_bracket[char]:
                return "NO"

    return "YES" if not stack else "NO"

