def find_subgrid_with_sum(n, m, grid, k):
    def get_prefix_sum_2d(matrix):
        prefix_sum = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            for j in range(1, m + 1):
                prefix_sum[i][j] = (
                    grid[i-1][j-1] +
                    prefix_sum[i-1][j] +
                    prefix_sum[i][j-1] -
                    prefix_sum[i-1][j-1]
                )
        return prefix_sum

    prefix_sum = get_prefix_sum_2d(grid)

    for top in range(n):
        for left in range(m):
            for bottom in range(top, n):
                for right in range(left, m):
                    subgrid_sum = (
                        prefix_sum[bottom + 1][right + 1]
                        - prefix_sum[top][right + 1]
                        - prefix_sum[bottom + 1][left]
                        + prefix_sum[top][left]
                    )
                    if subgrid_sum == k:
                        return True
    return False

from datetime import datetime

def calculate_inactive_time(log_entries):
    inactive_time = 0
    previous_timestamp = None
    inactive_start = None

    for entry in log_entries.splitlines():
        timestamp_str, status = entry.split(': ')
        timestamp = datetime.strptime(timestamp_str, '%Y-%m-%d %H:%M:%S')

        if status == "inactive":
            inactive_start = timestamp
        elif status == "active" and inactive_start is not None:
            inactive_time += (timestamp - inactive_start).total_seconds()
            inactive_start = None

    return int(inactive_time)

