def alternate_case_concatenation(strings):
    """
    Concatenates list of strings and modifies the result to alternate between upper
    and lower case characters, starting with upper case.

    :param strings: List of input strings
    :return: Modified string with alternating case characters
    """
    concatenated_string = ''.join(strings)
    result = []

    for i, char in enumerate(concatenated_string):
        if i % 2 == 0:
            result.append(char.upper())
        else:
            result.append(char.lower())

    return ''.join(result)

