def plate_stack(operations):
    stack = []

    for op in operations:
        if op.startswith("push"):
            _, value = op.split()
            stack.append(int(value))
        elif op == "pop":
            if stack:
                stack.pop()

    return ' '.join(map(str, stack[::-1])) if stack else "empty"

