def apply_operations(n, m, k, operations):
    # Initialize the matrix with zeros
    matrix = [[0] * m for _ in range(n)]

    # Apply each operation
    for op in operations:
        i, j, x = op
        for row in range(i-1, j):
            for col in range(m):
                matrix[row][col] += x

    # Find the maximum value in the matrix
    max_value = max(max(row) for row in matrix)

    return max_value

import math

def minimize_g(n):
    x = int(math.sqrt(n))
    if abs(x**2 - n) <= abs((x+1)**2 - n):
        return x
    else:
        return x + 1

def solve(test_cases):
    results = []
    for n in test_cases:
        results.append(minimize_g(n))
    return results

