def are_friends(n, requests, queries):
    parent = list(range(n + 1))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    for a, b in requests:
        union(a, b)

    result = []
    for x, y in queries:
        result.append(find(x) == find(y))

    return result

