def distribute_coins(s, n, coin_values):
    # Check whether each coin value can be evenly distributed among subjects
    for a in coin_values:
        if a % s != 0:
            return "NO"

    # Calculate the distribution
    distribution = [[a // s for a in coin_values] for _ in range(s)]

    # Generate the output
    result = ["YES"]
    for row in distribution:
        result.append(" ".join(map(str, row)))

    return "\n".join(result)

