def count_paths(T, test_cases):
    results = []

    for t in range(T):
        H, W, grid = test_cases[t]

        if grid[0][0] == '#' or grid[H-1][W-1] == '#':
            results.append(0)
            continue

        dp = [[0] * W for _ in range(H)]
        dp[0][0] = 1

        for i in range(H):
            for j in range(W):
                if grid[i][j] == '#':
                    dp[i][j] = 0
                else:
                    if i > 0:
                        dp[i][j] += dp[i-1][j]
                    if j > 0:
                        dp[i][j] += dp[i][j-1]

        results.append(dp[H-1][W-1])

    return results

def chain_messages(n, preferences):
    sequence = [-1] * n
    used = [False] * n

    def dfs(friend):
        for next_friend in range(n):
            rank = preferences[friend][next_friend] - 1
            if not used[rank]:
                used[rank] = True
                sequence[friend] = rank + 1
                return

    for friend in range(n):
        dfs(friend)

    return sequence

