def find_scrambled_codes(codes):
    """
    Given a list of strings `codes`, the function returns a list of tuples where each tuple `(i, j)`
    indicates that `codes[i]` is a scrambled version of `codes[j]`.
    """
    scrambled_pairs = []

    # Create a dictionary to store sorted codes with their indices
    sorted_dict = {}

    for idx, code in enumerate(codes):
        sorted_code = ''.join(sorted(code))
        if sorted_code in sorted_dict:
            sorted_dict[sorted_code].append(idx)
        else:
            sorted_dict[sorted_code] = [idx]

    # Generate scrambled pairs from the dictionary
    for indices in sorted_dict.values():
        if len(indices) > 1:
            for i in indices:
                for j in indices:
                    if i != j:
                        scrambled_pairs.append((i, j))

    return scrambled_pairs

def can_make_all_zero(n, m, A, B):
    """
    Determines if it's possible to make all elements of A zero using the operation described.
    """
    from math import gcd
    from functools import reduce

    # Find the greatest common divisor (GCD) of all elements in B
    def find_gcd_list(lst):
        return reduce(gcd, lst)

    gcd_B = find_gcd_list(B)

    # If each element in A is divisible by the GCD of B, we can make all elements zero
    for a in A:
        if a % gcd_B != 0:
            return "NO"

    return "YES"

