def max_rectangle_area(n, points):
    from collections import defaultdict

    x_dict = defaultdict(list)
    y_dict = defaultdict(list)

    # Group points by their x and y coordinates
    for x, y in points:
        x_dict[x].append(y)
        y_dict[y].append(x)

    max_area = 0

    # For each x in x_dict, sort the y list and calculate the possible rectangle areas
    for x in x_dict:
        y_list = sorted(x_dict[x])
        for i in range(len(y_list) - 1):
            height = y_list[i + 1] - y_list[i]
            for j in range(i + 1, len(y_list)):
                height = y_list[j] - y_list[i]
                if height <= 0:
                    continue
                width = 0
                for k in x_dict:
                    if k != x and y_list[i] in x_dict[k] and y_list[j] in x_dict[k]:
                        width = abs(k - x)
                        max_area = max(max_area, width * height)

    return max_area

