def max_min_after_operations(n, k, A):
    def can_achieve_min_value(mid):
        required_operations = 0
        for value in A:
            if value < mid:
                required_operations += (mid - value)
        return required_operations <= k

    low, high = min(A), min(A) + k
    answer = low

    while low <= high:
        mid = (low + high) // 2
        if can_achieve_min_value(mid):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1

    return answer

