def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    last_seen = {}
    start = 0
    max_length = 0

    for i, char in enumerate(s):
        if char in last_seen and start <= last_seen[char]:
            start = last_seen[char] + 1
        else:
            max_length = max(max_length, i - start + 1)

        last_seen[char] = i

    return max_length

def process_test_cases(test_cases):
    """
    Processes multiple test cases and returns the results.
    """
    return [length_of_longest_substring(test_case) for test_case in test_cases]

def count_interesting_pairs(n, b):
    MOD = 1000000007
    interesting_count = 0

    for i in range(n):
        for j in range(i+1, n):
            if (b[i] | b[j]) > (b[i] & b[j]):
                interesting_count = (interesting_count + 1) % MOD

    return interesting_count

