def canPartitionKSubsets(nums, k):
    totalSum = sum(nums)
    if totalSum % k != 0:
        return "NO"
    target = totalSum // k
    used = [False] * len(nums)

    def backtrack(k, start, currentSum):
        if k == 1:
            return True
        if currentSum == target:
            return backtrack(k - 1, 0, 0)

        for i in range(start, len(nums)):
            if not used[i] and currentSum + nums[i] <= target:
                used[i] = True
                if backtrack(k, i + 1, currentSum + nums[i]):
                    return True
                used[i] = False
        return False

    nums.sort(reverse=True)
    if nums[0] > target:
        return "NO"
    return "YES" if backtrack(k, 0, 0) else "NO"

