def apply_discounts(N, products, M, discounts):
    discount_dict = {category: rate for category, rate in discounts}

    updated_products = []
    for name, category, price in products:
        if category in discount_dict:
            discount = discount_dict[category]
            new_price = price * (1 - discount / 100)
        else:
            new_price = price

        updated_products.append((name, category, round(new_price, 2)))

    return updated_products

def is_valid_preorder_sequence(n, sequence):
    """
    Returns "YES" if the given sequence is a valid Pre-Order traversal of a BST, "NO" otherwise.
    """
    stack = []
    root = float('-inf')

    for value in sequence:
        if value < root:
            return "NO"

        while stack and stack[-1] < value:
            root = stack.pop()

        stack.append(value)

    return "YES"

