def longest_necklace(pebbles):
    """
    Function to determine the length of the longest subsequence of pebbles
    that can be arranged to form a necklace where no two adjacent pebbles have the same color.
    """
    if not pebbles:
        return 0

    # Initialize the count of each color
    color_count = {}
    for pebble in pebbles:
        if pebble in color_count:
            color_count[pebble] += 1
        else:
            color_count[pebble] = 1

    # Find the longest valid subsequence
    longest_length = len(color_count)

    return longest_length

# Function to parse input and use the longest_necklace function
def process_input(n, pebbles_list):
    return longest_necklace(pebbles_list)

