def manage_cargo_operations(operations):
    """
    Manages the cargo operations on a stack and returns the state of the stack after each operation.

    :param operations: List of string operations (e.g., ['ADD 5', 'REMOVE'])
    :return: List of strings representing the state of the stack after each operation
    """
    stack = []
    results = []

    for operation in operations:
        if operation.startswith('ADD'):
            _, x = operation.split()
            stack.append(int(x))
            results.append(' '.join(map(str, stack)))
        elif operation == 'REMOVE':
            if stack:
                stack.pop()
                if stack:
                    results.append(' '.join(map(str, stack)))
                else:
                    results.append('')
            else:
                results.append('ERROR')

    return results

def max_intersections_covered(n, m, B, roads):
    """
    Returns the maximum number of intersections that can be monitored within the budget.
    """

    # Sort the roads based on their cost
    roads.sort(key=lambda x: x[2])

    parent = list(range(n))

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            parent[root_v] = root_u

    total_cost = 0
    max_intersections = 0

    for u, v, cost in roads:
        if total_cost + cost <= B:
            if find(u - 1) != find(v - 1):
                union(u - 1, v - 1)
                total_cost += cost
                max_intersections += 2

    return min(max_intersections, n)

# Example usage
# n = 4, m = 5, B = 10
# roads = [[1, 2, 3], [1, 3, 2], [2, 3, 1], [3, 4, 4], [2, 4, 6]]
# Should output 4 as we can cover all intersections with the selected roads.

