def max_f_of_subarray(T, cases):
    def count_greater_than_median(subarray):
        sorted_sub = sorted(subarray)
        n = len(sorted_sub)
        median = sorted_sub[(n - 1) // 2]
        return len([num for num in subarray if num > median])

    results = []
    for case in cases:
        n, array = case
        max_f = 0
        for l in range(n):
            for r in range(l+1, n+1):
                f_value = count_greater_than_median(array[l:r])
                max_f = max(max_f, f_value)
        results.append(max_f)
    return results

