from collections import defaultdict, deque

def can_communicate(n, m, edges):
    if n == 1:
        return "YES"

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()

    def bfs(node):
        queue = deque([node])
        visited.add(node)
        while queue:
            current = queue.popleft()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    bfs(1)

    if len(visited) == n:
        return "YES"
    else:
        return "NO"

