def longest_descending_period(n, altitudes):
    if n == 1:
        return 0

    max_descend = 0
    current_descend = 0

    for i in range(1, n):
        if altitudes[i] < altitudes[i - 1]:
            current_descend += 1
            max_descend = max(max_descend, current_descend)
        else:
            current_descend = 0

    return max_descend

