def count_paths(n, m, grid):
    MOD = 10**9 + 7

    # dp table to store the number of paths to reach each cell
    dp = [[0] * m for _ in range(n)]

    # Initial position start at top-left corner
    dp[0][0] = 1

    # Fill dp table
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] = (dp[i][j] + dp[i-1][j]) % MOD
                if j > 0:
                    dp[i][j] = (dp[i][j] + dp[i][j-1]) % MOD

    return dp[n-1][m-1]

