def list_primes_up_to(m):
    """
    Returns a list of all prime numbers up to and including m using the Sieve of Eratosthenes.
    """
    if m < 2:
        return []

    sieve = [True] * (m + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not prime numbers

    for start in range(2, int(m**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, m + 1, start):
                sieve[multiple] = False

    return [num for num in range(2, m + 1) if sieve[num]]

