from typing import List

def max_circular_subarray_sum(arr: List[int]) -> int:
    def kadane(arr):
        current_sum = max_sum = arr[0]
        for num in arr[1:]:
            current_sum = max(num, current_sum + num)
            max_sum = max(max_sum, current_sum)
        return max_sum

    max_kadane = kadane(arr)

    total_sum = sum(arr)
    max_wrap = total_sum + kadane([-x for x in arr])

    # If all elements are negative, max_wrap would be zero; in this case we return max_kadane.
    if max_wrap == 0:
        return max_kadane

    return max(max_kadane, max_wrap)

