def compute_directory_size(n, items, initial_directory):
    from collections import defaultdict, deque

    # Parse input into a tree structure
    directories = defaultdict(list)
    files = {}

    for item in items:
        tokens = item.split()
        if tokens[0] == 'file':
            _, file_path, file_size = tokens
            file_size = int(file_size)
            path_parts = file_path.split('/')
            file_name = path_parts[-1]
            if len(path_parts) == 1:
                # It's a file directly under the root
                files[file_path] = file_size
            else:
                dir_path = '/'.join(path_parts[:-1])
                directories[dir_path].append(file_path)
                files[file_path] = file_size
        elif tokens[0] == 'dir':
            _, dir_path = tokens
            # Process this dir under the directories list
            if '/' in dir_path:
                parent_dir = '/'.join(dir_path.split('/')[:-1])
                directories[parent_dir].append(dir_path)
            # Else it is a root-level dir and doesn't need specific handling here

    # Recursive function to compute directory size
    def get_total_size(directory):
        total_size = 0
        if directory in files:
            total_size += files[directory]
        for item in directories[directory]:
            total_size += get_total_size(item)
        return total_size

    return get_total_size(initial_directory)

