from collections import deque

def is_path_exist(n, m, city_map, x1, y1, x2, y2):
    direction_vectors = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and city_map[x][y] == 'E'

    queue = deque([(x1-1, y1-1)])
    visited = [[False] * m for _ in range(n)]
    visited[x1-1][y1-1] = True

    while queue:
        x, y = queue.popleft()
        if (x, y) == (x2-1, y2-1):
            return "YES"
        for dx, dy in direction_vectors:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and not visited[nx][ny]:
                visited[nx][ny] = True
                queue.append((nx, ny))

    return "NO"

