def greatest_good_letter(s):
    """
    Returns the greatest "good" letter in uppercase that appears in both
    uppercase and lowercase in the given string.
    """
    good_letters = set()
    for char in s:
        if char.isupper() and char.lower() in s:
            good_letters.add(char)
        elif char.islower() and char.upper() in s:
            good_letters.add(char.upper())

    return max(good_letters, default="")

