import math
from typing import Union

def find_unknown_side(opposite: Union[str, float], adjacent: Union[str, float], hypotenuse: Union[str, float]) -> str:
    if opposite == "?":
        if isinstance(adjacent, (float, int)) and isinstance(hypotenuse, (float, int)):
            opposite_value = math.sqrt(hypotenuse ** 2 - adjacent ** 2)
            return f"Opposite = {round(opposite_value, 2)}"
    elif adjacent == "?":
        if isinstance(opposite, (float, int)) and isinstance(hypotenuse, (float, int)):
            adjacent_value = math.sqrt(hypotenuse ** 2 - opposite ** 2)
            return f"Adjacent = {round(adjacent_value, 2)}"
    elif hypotenuse == "?":
        if isinstance(opposite, (float, int)) and isinstance(adjacent, (float, int)):
            hypotenuse_value = math.sqrt(opposite ** 2 + adjacent ** 2)
            return f"Hypotenuse = {round(hypotenuse_value, 2)}"
    else:
        raise ValueError("One side must be unknown represented by '?'")

    raise ValueError("Invalid input values provided")

