from typing import List, Tuple
from collections import defaultdict, deque

def is_strongly_connected(vertex_count: int, edges: List[Tuple[int, int]]) -> bool:
    if vertex_count == 0:
        return True

    def bfs(start_node, graph):
        visited = set()
        queue = deque([start_node])
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return visited

    # Create the adjacency list
    graph = defaultdict(list)
    reverse_graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        reverse_graph[v].append(u)

    # Check from any node if all nodes are reachable
    all_nodes = bfs(0, graph)
    if len(all_nodes) != vertex_count:
        return False

    # Check from any node in the reverse graph if all nodes are reachable
    all_nodes_reverse = bfs(0, reverse_graph)
    if len(all_nodes_reverse) != vertex_count:
        return False

    return True

