def pattern_match(pattern: str, string: str) -> bool:
    def is_match(p_idx: int, s_idx: int, mapping: dict, used: set) -> bool:
        # If both pattern and string are fully matched
        if p_idx == len(pattern) and s_idx == len(string):
            return True
        # If either of them is exhausted
        if p_idx == len(pattern) or s_idx == len(string):
            return False

        char = pattern[p_idx]

        if char in mapping:
            substr = mapping[char]
            if not string.startswith(substr, s_idx):
                return False
            return is_match(p_idx + 1, s_idx + len(substr), mapping, used)

        for end in range(s_idx + 1, len(string) + 1):
            substr = string[s_idx:end]
            if substr in used:
                continue

            mapping[char] = substr
            used.add(substr)

            if is_match(p_idx + 1, s_idx + len(substr), mapping, used):
                return True

            del mapping[char]
            used.remove(substr)

        return False

    return is_match(0, 0, {}, set())

