from typing import List

def counting_sort_for_radix(arr: List[int], exp: int, base: int = 10) -> List[int]:
    n = len(arr)
    output = [0] * n
    count = [0] * base

    for i in range(n):
        index = (arr[i] // exp) % base
        count[index] += 1

    for i in range(1, base):
        count[i] += count[i - 1]

    i = n - 1
    while i >= 0:
        index = (arr[i] // exp) % base
        output[count[index] - 1] = arr[i]
        count[index] -= 1
        i -= 1

    for i in range(n):
        arr[i] = output[i]

    return arr

def radix_sort(arr: List[int], simulation: bool = False) -> List[int]:
    if len(arr) == 0:
        return arr

    max_element = max(arr)
    exp = 1
    while max_element // exp > 0:
        arr = counting_sort_for_radix(arr, exp)
        if simulation:
            print(f"After sorting with exp={exp}: {arr}")
        exp *= 10

    return arr

