from typing import List

def cycle_sort(arr: List[int]) -> List[int]:
    """
    Sorts the array using Cycle Sort algorithm.
    This method minimizes the number of writes to the memory.
    """
    n = len(arr)

    # Traverse the array to find cycles to rotate.
    for cycle_start in range(n - 1):
        item = arr[cycle_start]

        # Find the position where we put the element
        pos = cycle_start
        for i in range(cycle_start + 1, n):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item to the right position
        while item == arr[pos]:
            pos += 1

        arr[pos], item = item, arr[pos]

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            arr[pos], item = item, arr[pos]

    return arr

