def int_to_bytes(num, endianness):
    """
    Converts an integer to a byte array with a specified endianness.

    Args:
    num (int): The integer to convert.
    endianness (str): The byte order ('big' or 'little').

    Returns:
    bytearray: The byte array representing the integer.
    """
    if endianness not in ('big', 'little'):
        raise ValueError("Endianness must be either 'big' or 'little'")

    if num == 0:
        return bytearray([0])

    num_bytes = (num.bit_length() + 7) // 8  # Determine the minimum number of bytes needed
    if num < 0:
        # Calculate the minimum bytes needed for negative number with sign extension
        num_bytes = (num.bit_length() + 8) // 8

    return num.to_bytes(num_bytes, byteorder=endianness, signed=True)


def bytes_to_int(bytestr, endianness):
    """
    Converts a byte array back to an integer with a specified endianness.

    Args:
    bytestr (bytearray): The byte array to convert.
    endianness (str): The byte order ('big' or 'little').

    Returns:
    int: The integer reconstructed from the byte array.
    """
    if endianness not in ('big', 'little'):
        raise ValueError("Endianness must be either 'big' or 'little'")

    return int.from_bytes(bytestr, byteorder=endianness, signed=True)

