from typing import List

def insertion_sort(arr: List[int], simulation: bool = False) -> List[int]:
    if simulation:
        print(f"iteration 0 : {' '.join(map(str, arr))}")

    for i in range(1, len(arr)):
        key = arr[i]
        j = i - 1
        while j >= 0 and key < arr[j]:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = key

        if simulation:
            print(f"iteration {i} : {' '.join(map(str, arr))}")

    return arr

def join_url_paths(base: str, suffix: str) -> str:
    """
    Joins two parts of a URL into a single well-formatted URL.
    """
    if base.endswith('/'):
        base = base.rstrip('/')
    if suffix.startswith('/'):
        suffix = suffix.lstrip('/')
    if base == '':
        return suffix
    if suffix == '':
        return base
    return f"{base}/{suffix}"

