def factorial_iterative(n: int, mod: int = None) -> int:
    """
    Computes the factorial of a given integer n using an iterative method.
    If mod is provided, returns n! % mod.
    """
    factorial = 1
    for i in range(2, n+1):
        factorial *= i
        if mod:
            factorial %= mod
    return factorial

def factorial_recursive(n: int, mod: int = None, computed: int = 1) -> int:
    """
    Computes the factorial of a given integer n using a recursive method.
    If mod is provided, returns n! % mod.
    """
    if n == 0 or n == 1:
        return computed if not mod else computed % mod
    next_computed = computed * n
    return factorial_recursive(n - 1, mod, next_computed % mod if mod else next_computed)

from collections import deque

def ladder_length(begin_word, end_word, word_list):
    if end_word not in word_list:
        return -1

    word_set = set(word_list)
    begin_set = set([begin_word])
    end_set = set([end_word])
    visited = set()
    transformed = set()
    length = 1

    while begin_set and end_set:
        # Always expand the smaller set for better performance
        if len(begin_set) > len(end_set):
            begin_set, end_set = end_set, begin_set

        next_level_set = set()
        for word in begin_set:
            for i in range(len(word)):
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    transformed = word[:i] + c + word[i+1:]
                    if transformed in end_set:
                        return length + 1
                    if transformed in word_set and transformed not in visited:
                        next_level_set.add(transformed)
                        visited.add(transformed)
        begin_set = next_level_set
        length += 1

    return -1

