from typing import List

def get_factor_combinations(n: int) -> List[List[int]]:
    def backtrack(remain, start, path, results):
        if remain == 1:
            if len(path) > 1:
                results.append(path[:])
            return

        for i in range(start, remain + 1):
            if remain % i == 0:
                path.append(i)
                backtrack(remain // i, i, path, results)
                path.pop()

    results = []
    backtrack(n, 2, [], results)
    return results

def improved_comb_sort(arr):
    def get_next_gap(gap):
        gap = (gap * 10) // 13
        if gap < 1:
            return 1
        return gap

    n = len(arr)
    if n < 2:
        return arr

    gap = n
    swapped = True

    while gap != 1 or swapped:
        gap = get_next_gap(gap)
        swapped = False
        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True
    return arr

