from typing import List

def optimized_interpolation_search(array: List[int], search_key: int) -> int:
    """
    Returns the index of search_key in array using an optimized interpolation search.
    Returns -1 if the search_key is not present in the array.
    """
    if not array:
        return -1

    low = 0
    high = len(array) - 1

    while low <= high and array[low] <= search_key <= array[high]:
        if array[low] == array[high]:
            if array[low] == search_key:
                return low
            else:
                return -1

        # Estimate the position of search_key using the interpolation formula
        pos = low + ((search_key - array[low]) * (high - low) // (array[high] - array[low]))

        # If the estimated position goes out of bounds
        if pos < low or pos > high:
            return -1

        if array[pos] == search_key:
            return pos
        elif array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

