from typing import List

def selection_sort(arr: List[int], simulation: bool=False) -> List[int]:
    n = len(arr)
    for i in range(n):
        if simulation:
            print(f"iteration {i} : {' '.join(map(str, arr))}")
        min_index = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j
        arr[i], arr[min_index] = arr[min_index], arr[i]
    return arr

