def frequency_counter(input_list: list) -> dict:
    """
    Returns a dictionary with the frequency of each unique element in the input list.
    """
    frequency_dict = {}
    for elem in input_list:
        if elem in frequency_dict:
            frequency_dict[elem] += 1
        else:
            frequency_dict[elem] = 1
    return frequency_dict

