def count_partitions(n: int) -> int:
    # Initialize a table to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    # Base case: There's exactly one way to partition 0, which is not to use any number
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the table in a bottom-up manner
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if j >= i:
                dp[i][j] = dp[i - 1][j] + dp[i][j - i]
            else:
                dp[i][j] = dp[i - 1][j]

    # The result is in dp[n][n], which is the number of partitions of n using numbers up to n
    return dp[n][n]

