def rabin_karp_dna(pattern: str, text: str) -> list:
    """
    Function to implement Rabin-Karp algorithm to find all starting positions of
    substring `pattern` in the given `text`.
    """
    from typing import List

    def hash_function(s: str) -> int:
        return sum(ord(c) - ord('A') + 1 for c in s)

    pattern_length = len(pattern)
    text_length = len(text)

    if pattern_length > text_length:
        return []

    pattern_hash = hash_function(pattern)
    current_hash = hash_function(text[:pattern_length])

    result = []

    for i in range(text_length - pattern_length + 1):
        if current_hash == pattern_hash and text[i:i + pattern_length] == pattern:
            result.append(i)

        if i < text_length - pattern_length:
            current_hash = current_hash - (ord(text[i]) - ord('A') + 1) + (ord(text[i + pattern_length]) - ord('A') + 1)

    return result

