def judge_circle(moves: str) -> bool:
    """
    Determine if the robot returns to the origin (0, 0) after completing the sequence of moves.
    """
    x, y = 0, 0

    for move in moves:
        if move == 'R':
            x += 1
        elif move == 'L':
            x -= 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    return x == 0 and y == 0

