def is_valid_expression(s: str) -> bool:
    """
    Returns True if the input string is a valid bracket expression, otherwise False.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def robot_climb_stairs(n: int) -> int:
    """
    Returns the number of distinct ways the robot can climb to the nth step,
    where it can take either 1-step or 2-step moves.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    elif n == 2:
        return 2

    first, second = 1, 2
    for _ in range(3, n + 1):
        first, second = second, first + second

    return second

