from typing import List

def custom_sort(arr: List[int]) -> List[int]:
    def stooge_sort(sub_arr, l, h):
        if l >= h:
            return

        if sub_arr[l] > sub_arr[h]:
            sub_arr[l], sub_arr[h] = sub_arr[h], sub_arr[l]

        if h - l + 1 > 2:
            t = (h - l + 1) // 3
            stooge_sort(sub_arr, l, h - t)
            stooge_sort(sub_arr, l + t, h)
            stooge_sort(sub_arr, l, h - t)

    if arr:
        array_copy = arr[:]
        stooge_sort(array_copy, 0, len(array_copy) - 1)
        return array_copy
    return []

# Example usage:
# sorted_arr = custom_sort([5, 2, 9, 1, 6])
