def rotate_matrix(image: List[List[int]]) -> None:
    """
    Rotates the given n x n image matrix 90 degrees clockwise in-place.
    """
    n = len(image)

    # Step 1: Transpose the matrix
    for i in range(n):
        for j in range(i + 1, n):
            image[i][j], image[j][i] = image[j][i], image[i][j]

    # Step 2: Reverse each row
    for i in range(n):
        image[i].reverse()

from typing import List

def limit_occurrences(lst: List[int], N: int) -> List[int]:
    """
    Limits the occurrence of each element in lst to at most N times,
    while maintaining the original order of elements.
    """
    if N == 0:
        return []

    counts = {}
    result = []

    for number in lst:
        if counts.get(number, 0) < N:
            result.append(number)
            counts[number] = counts.get(number, 0) + 1

    return result

