import heapq

def prime_minimum_spanning_optimized(graph):
    if not graph:
        return 0

    # Start from an arbitrary node, here we choose the first node from the dictionary.
    start_node = next(iter(graph))
    visited = set([start_node])
    min_heap = [(weight, start_node, to) for weight, to in graph[start_node]]
    heapq.heapify(min_heap)

    mst_weight = 0
    while min_heap:
        weight, frm, to = heapq.heappop(min_heap)
        if to not in visited:
            visited.add(to)
            mst_weight += weight
            for next_weight, neighbor in graph[to]:
                if neighbor not in visited:
                    heapq.heappush(min_heap, (next_weight, to, neighbor))

    return mst_weight

