def min_distance_dp(word1: str, word2: str) -> int:
    """
    Returns the minimum number of deletions required to make both words identical.
    """
    m, n = len(word1), len(word2)

    # Create a DP table with (m+1) x (n+1) dimensions
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If word1 is empty, remove all characters from word2
            elif j == 0:
                dp[i][j] = i  # If word2 is empty, remove all characters from word1
            elif word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # Characters match, no deletion needed
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])  # Min deletion from either word1 or word2

    return dp[m][n]

def gcd_bitwise(a: int, b: int) -> int:
    """
    Compute the greatest common divisor (GCD) of two non-negative integers using bitwise operations.
    If either a or b is 0, the GCD is the other number.
    """
    if a == 0:
        return b
    if b == 0:
        return a

    # Count the number of trailing zeros in both a and b
    shift = 0
    while ((a | b) & 1) == 0:
        a >>= 1
        b >>= 1
        shift += 1

    # Remove all factors of 2 in a
    while (a & 1) == 0:
        a >>= 1

    while b != 0:
        while (b & 1) == 0:
            b >>= 1
        if a > b:
            a, b = b, a
        b -= a

    # Restore common factors of 2
    return a << shift

def rotate_180(matrix):
    """
    Rotates the given matrix 180 degrees in place.
    """
    n = len(matrix)
    for i in range(n // 2):
        for j in range(n):
            matrix[i][j], matrix[n-i-1][n-j-1] = matrix[n-i-1][n-j-1], matrix[i][j]
    if n % 2 == 1:
        mid = n // 2
        for j in range(n // 2):
            matrix[mid][j], matrix[mid][n-j-1] = matrix[mid][n-j-1], matrix[mid][j]

