def multiply_matrices(multiplicand: list[list[int]], multiplier: list[list[int]]) -> list[list[int]]:
    m = len(multiplicand)
    n = len(multiplicand[0])
    p = len(multiplier[0])

    # Initialize the result matrix with zeros
    result = [[0] * p for _ in range(m)]

    # Perform matrix multiplication
    for i in range(m):
        for j in range(p):
            for k in range(n):
                result[i][j] += multiplicand[i][k] * multiplier[k][j]

    return result

def cycle_sort(arr):
    """
    Sorts the array using cycle sort to minimize the number of write operations.
    """
    n = len(arr)
    writes = 0

    for cycle_start in range(n - 1):
        item = arr[cycle_start]

        pos = cycle_start
        for i in range(cycle_start + 1, n):
            if arr[i] < item:
                pos += 1

        if pos == cycle_start:
            continue

        while item == arr[pos]:
            pos += 1

        if pos != cycle_start:
            arr[pos], item = item, arr[pos]
            writes += 1

        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            if item != arr[pos]:
                arr[pos], item = item, arr[pos]
                writes += 1

    return arr

