def generate_abbreviations(word: str) -> list:
    def backtrack(pos, current, count):
        if pos == len(word):
            if count > 0:
                current += str(count)
            result.append(current)
        else:
            # Option 1: Abbreviate the current character
            backtrack(pos + 1, current, count + 1)
            # Option 2: Keep the current character
            if count > 0:
                current += str(count)
            backtrack(pos + 1, current + word[pos], 0)

    result = []
    backtrack(0, "", 0)
    return result

