def gcd(a, b):
    """
    Computes the greatest common divisor of two integers a and b using Euclid's algorithm.
    """
    while b:
        a, b = b, a % b
    return abs(a)

def trailing_zero(x):
    """
    Calculates the number of trailing zeros in the binary representation of a given positive integer x.
    """
    if x == 0:
        raise ValueError("Input must be a positive integer.")

    count = 0
    while (x & 1) == 0:
        x >>= 1
        count += 1
    return count

def gcd_bit(a, b):
    """
    Computes the greatest common divisor using bitwise operations.
    """
    if a == 0:
        return b
    if b == 0:
        return a

    shift = trailing_zero(a | b)
    a >>= trailing_zero(a)

    while b != 0:
        b >>= trailing_zero(b)
        if a > b:
            a, b = b, a
        b -= a

    return a << shift

from typing import List

def multiply(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    m, l = len(A), len(A[0])
    l_b, n = len(B), len(B[0])

    if l != l_b:
        raise ValueError("Number of columns in A must be equal to number of rows in B")

    # Resultant matrix C
    C = [[0] * n for _ in range(m)]

    # Optimized multiplication leveraging sparsity
    for i in range(m):
        for k in range(l):
            if A[i][k] != 0:
                for j in range(n):
                    if B[k][j] != 0:
                        C[i][j] += A[i][k] * B[k][j]

    return C

