from typing import List

def binary_search_iterative(array: List[int], target: int) -> int:
    low, high = 0, len(array) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if array[mid] == target:
            result = mid
            high = mid - 1
        elif array[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return result

def binary_search_recursive(array: List[int], low: int, high: int, target: int) -> int:
    if low > high:
        return -1
    mid = (low + high) // 2
    if array[mid] == target:
        result_left = binary_search_recursive(array, low, mid - 1, target)
        return mid if result_left == -1 else result_left
    elif array[mid] < target:
        return binary_search_recursive(array, mid + 1, high, target)
    else:
        return binary_search_recursive(array, low, mid - 1, target)

