def encode_rle(input_str: str) -> str:
    """
    Compress the input string using Run-Length Encoding (RLE).
    """
    if not input_str:
        return ""

    encoded_str = []
    count = 1

    for i in range(1, len(input_str)):
        if input_str[i] == input_str[i - 1]:
            count += 1
        else:
            encoded_str.append(f"{count}{input_str[i - 1]}")
            count = 1

    encoded_str.append(f"{count}{input_str[-1]}")

    return ''.join(encoded_str)

def decode_rle(encoded_str: str) -> str:
    """
    Decompress the RLE-encoded string back to its original form.
    """
    if not encoded_str:
        return ""

    decoded_str = []
    count = 0

    for char in encoded_str:
        if char.isdigit():
            count = count * 10 + int(char)
        else:
            decoded_str.append(char * count)
            count = 0

    return ''.join(decoded_str)

