def efficient_combination(n: int, r: int) -> int:
    """
    Computes the number of ways to choose r items from n items without repetition and irrespective of the order.
    Efficient computation using dynamic programming.
    """
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    if r == 1:
        return n

    # Create a table to store intermediate results
    dp = [[0] * (r + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(min(i, r) + 1):
            if j == 0 or j == i:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i-1][j-1] + dp[i-1][j]

    return dp[n][r]

from typing import List

def generate_investment_combinations(investments: List[int], target: int) -> List[List[int]]:
    def backtrack(remain, comb, start):
        if remain == 0:
            result.append(list(comb))
            return
        elif remain < 0:
            return

        for i in range(start, len(investments)):
            comb.append(investments[i])
            backtrack(remain - investments[i], comb, i)
            comb.pop()

    result = []
    investments.sort()
    backtrack(target, [], 0)
    return result

