def count_islands(grid):
    """
    Returns the number of distinct islands in the grid.
    """
    if not grid:
        return 0

    def dfs(grid, i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == '0':
            return
        grid[i][j] = '0'  # mark as visited by turning land into water
        dfs(grid, i+1, j)  # down
        dfs(grid, i-1, j)  # up
        dfs(grid, i, j+1)  # right
        dfs(grid, i, j-1)  # left

    num_islands = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                num_islands += 1
                dfs(grid, i, j)

    return num_islands

def enhanced_linear_search(array: list, queries: list) -> dict:
    """
    Given an array and a list of queries, this function returns a dictionary where
    the keys are the query values and the values are lists of indices where each
    query value appears in the array.
    """
    result = {query: [] for query in queries}

    for index, value in enumerate(array):
        if value in result:
            result[value].append(index)

    return result

