def generalized_counting_sort(arr):
    if not arr:
        return []

    min_value = min(arr)
    max_value = max(arr)

    range_of_elements = max_value - min_value + 1
    count = [0] * range_of_elements
    output = [0] * len(arr)

    for number in arr:
        count[number - min_value] += 1

    for i in range(1, range_of_elements):
        count[i] += count[i - 1]

    for number in reversed(arr):
        output[count[number - min_value] - 1] = number
        count[number - min_value] -= 1

    return output

