from typing import List, Tuple
from collections import deque

def maze_search(maze: List[List[int]]) -> int:
    def is_valid(r, c):
        return 0 <= r < len(maze) and 0 <= c < len(maze[0]) and maze[r][c] == 1

    if maze[0][0] == 0 or maze[-1][-1] == 0:
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(0, 0)])  # store (row, col) positions
    steps = 0

    while queue:
        for _ in range(len(queue)):
            r, c = queue.popleft()
            if r == len(maze) - 1 and c == len(maze[0]) - 1:
                return steps
            for dr, dc in directions:
                rr, cc = r + dr, c + dc
                if is_valid(rr, cc):
                    maze[rr][cc] = 0  # mark as visited
                    queue.append((rr, cc))
        steps += 1

    return -1

def contains_cycle(graph: dict) -> bool:
    def dfs(node):
        if node in stack:
            return True
        if node in visited:
            return False

        visited.add(node)
        stack.add(node)

        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        stack.remove(node)
        return False

    visited = set()
    stack = set()

    for node in graph.keys():
        if node not in visited:
            if dfs(node):
                return True

    return False

