from typing import List

def limit_frequency(lst: List[int], N: int) -> List[int]:
    frequency = {}
    result = []

    for num in lst:
        if num not in frequency:
            frequency[num] = 0
        if frequency[num] < N:
            result.append(num)
            frequency[num] += 1

    return result

