from typing import List, Tuple, Union

def fizzbuzz_plus_plus(n: int, additional_conditions: List[Tuple[int, str]]) -> List[Union[int, str]]:
    result = []
    for i in range(1, n + 1):
        output = ""

        if i % 3 == 0:
            output += "Fizz"
        if i % 5 == 0:
            output += "Buzz"
        for divisor, word in additional_conditions:
            if i % divisor == 0:
                output += word

        result.append(output if output else i)

    return result

