import random

def is_sorted(arr):
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False
    return True

def bogo_sort_bracket(participants_list):
    """
    Sorts the list using the Bogo Sort algorithm.

    :param participants_list: List of integers representing the skill ratings
    :return: Sorted list of integers
    """
    while not is_sorted(participants_list):
        random.shuffle(participants_list)
    return participants_list

