def find_difference(s: str, t: str) -> str:
    """
    Identifies the letter added to t which is not present in s.
    """
    # Initialize a dictionary to keep track of character frequencies in s
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Iterate through t and find the extra character
    for char in t:
        if char not in char_count or char_count[char] == 0:
            return char
        else:
            char_count[char] -= 1

