def hamming_weight_recur(n: int) -> int:
    """
    Computes the Hamming weight of a number using recursion.
    """
    if n == 0:
        return 0
    else:
        # Turn off the rightmost 1-bit and count the number of operations
        return 1 + hamming_weight_recur(n & (n - 1))

def hamming_weight_iter(n: int) -> int:
    """
    Computes the Hamming weight of a number using iteration.
    """
    count = 0
    while n:
        # Turn off the rightmost 1-bit and count the number of operations
        n = n & (n - 1)
        count += 1
    return count

def bitwise_sum(a: int, b: int) -> int:
    """
    Computes the sum of the Hamming weights of two numbers.
    """
    return hamming_weight_recur(a) + hamming_weight_recur(b)

