def is_bipartite(graph):
    """
    Check if the given graph is bipartite using BFS.

    Args:
    graph (List[List[int]]): Adjacency matrix representing the graph.

    Returns:
    bool: True if the graph is bipartite, False otherwise.
    """
    n = len(graph)
    colors = [-1] * n  # -1 means uncolored, 0 and 1 are the two colors

    def bfs(start):
        queue = [start]
        colors[start] = 0  # Start coloring the first node with color 0

        while queue:
            node = queue.pop(0)
            current_color = colors[node]

            for neighbor in range(n):
                if graph[node][neighbor] == 1:
                    if colors[neighbor] == -1:
                        colors[neighbor] = 1 - current_color
                        queue.append(neighbor)
                    elif colors[neighbor] == current_color:
                        return False

        return True

    for i in range(n):
        if colors[i] == -1:  # For an unvisited node
            if not bfs(i):
                return False

    return True

def filter_within_range(arr, min_lim=None, max_lim=None):
    """
    Returns a list of integers from arr that fall between min_lim and max_lim, inclusive.

    If min_lim is None, it's assumed to be the smallest value in arr.
    If max_lim is None, it's assumed to be the largest value in arr.
    """
    if not arr:
        return []

    if min_lim is None:
        min_lim = min(arr)
    if max_lim is None:
        max_lim = max(arr)

    return [x for x in arr if min_lim <= x <= max_lim]

