from typing import List

def optimized_bubble_sort(arr: List[int], debug: bool = False) -> List[int]:
    n = len(arr)
    for i in range(n):
        swapped = False
        if debug:
            print(f"iteration {i}: {' '.join(map(str, arr))}")

        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
                if debug:
                    print(f"swap {arr[j]} {arr[j+1]}")

        if not swapped:
            break

    if debug:
        print(f"sorted list: {' '.join(map(str, arr))}")

    return arr

