def highlight_symbols(words, symbols):
    def find_best_symbol(word, symbols):
        best_symbol = None
        for symbol in symbols:
            if symbol in word:
                if best_symbol is None or len(symbol) > len(best_symbol):
                    best_symbol = symbol
        return best_symbol

    result = []
    for word in words:
        best_symbol = find_best_symbol(word, symbols)
        if best_symbol:
            word = word.replace(best_symbol, f'[{best_symbol}]', 1)
        result.append(word)

    return result

def tree_traversal(tree):
    def traverse(node, indent=0):
        if isinstance(node, str):
            print(" " * indent + node)
        elif isinstance(node, dict):
            for key, value in node.items():
                print(" " * indent + key + " -> ")
                traverse(value, indent + 4)
        elif isinstance(node, list):
            for item in node:
                traverse(item, indent)
        else:
            print(" " * indent + str(node))

    for key, value in tree.items():
        print(key + " -> ")
        traverse(value, 4)

