from collections import defaultdict

def find_modes(arr):
    if not arr:
        return []

    count_dict = defaultdict(int)
    max_count = 0
    for num in arr:
        count_dict[num] += 1
        if count_dict[num] > max_count:
            max_count = count_dict[num]

    modes = [num for num, count in count_dict.items() if count == max_count]
    return modes

