from typing import List

def stooge_sort(arr: List[int]) -> List[int]:
    def stoogesort(arr, l, h):
        if l >= h:
            return

        if arr[l] > arr[h]:
            arr[l], arr[h] = arr[h], arr[l]

        if h - l + 1 > 2:
            t = (h - l + 1) // 3
            stoogesort(arr, l, h - t)
            stoogesort(arr, l + t, h)
            stoogesort(arr, l, h - t)

    stoogesort(arr, 0, len(arr) - 1)
    return arr

