def fib_efficient(n: int) -> int:
    """
    Compute the nth Fibonacci number efficiently using matrix exponentiation.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1

    def matrix_mult(A, B):
        return [
            [A[0][0]*B[0][0] + A[0][1]*B[1][0], A[0][0]*B[0][1] + A[0][1]*B[1][1]],
            [A[1][0]*B[0][0] + A[1][1]*B[1][0], A[1][0]*B[0][1] + A[1][1]*B[1][1]]
        ]

    def matrix_exponentiation(A, power):
        result = [[1, 0], [0, 1]]  # Identity matrix
        base = A

        while power > 0:
            if power % 2 == 1:
                result = matrix_mult(result, base)
            base = matrix_mult(base, base)
            power //= 2

        return result

    F = [[1, 1], [1, 0]]
    result_matrix = matrix_exponentiation(F, n-1)

    return result_matrix[0][0]

from typing import List

def find_range(nums: List[int], target: int) -> List[int]:
    def find_left(nums, target):
        """
        Binary search helper function to find leftmost (first) index of target.
        """
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_right(nums, target):
        """
        Binary search helper function to find rightmost (last) index of target.
        """
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    left_index = find_left(nums, target)
    right_index = find_right(nums, target)

    if left_index <= right_index and left_index < len(nums) and nums[left_index] == target:
        return [left_index, right_index]
    else:
        return [-1, -1]

