from typing import List

def is_sorted(nums: List[int]) -> bool:
    """
    Helper function to check if the list is sorted.
    """
    for i in range(len(nums) - 1):
        if nums[i] > nums[i + 1]:
            return False
    return True

def bogo_sort(nums: List[int], simulation: bool = False) -> List[int]:
    """
    Function to sort the array using the Bogo Sort algorithm.
    It shuffles the array until it gets sorted.
    """
    while not is_sorted(nums):
        if simulation:
            print(nums)
        random.shuffle(nums)
    return nums

