def count_unique_elements(input_list: list) -> int:
    """
    Count the number of unique elements that appear exactly once.
    :param input_list: list of integers
    :return: count of unique elements
    """
    frequency = {}

    # Build frequency dictionary
    for num in input_list:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Count elements that appear exactly once
    unique_count = 0
    for count in frequency.values():
        if count == 1:
            unique_count += 1

    return unique_count

