from typing import List
from collections import defaultdict

def frequency_capping(arr: List[int], n: int) -> List[int]:
    if n == 0:
        return []

    count = defaultdict(int)
    result = []

    for element in arr:
        if count[element] < n:
            result.append(element)
            count[element] += 1

    return result

def has_cycle(graph_dict: dict) -> bool:
    def visit(node):
        if node in visiting:
            return True
        if node in visited:
            return False

        visiting.add(node)
        for neighbour in graph_dict.get(node, []):
            if visit(neighbour):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    visited = set()
    visiting = set()

    for node in graph_dict:
        if visit(node):
            return True
    return False

