from typing import List

def bitonic_sort(arr: List[int], reverse: bool = False) -> List[int]:
    def compare_and_swap(arr, i, j, dir):
        if (dir == (arr[i] > arr[j])):
            arr[i], arr[j] = arr[j], arr[i]

    def bitonic_merge(arr, low, cnt, dir):
        if cnt > 1:
            k = cnt // 2
            for i in range(low, low + k):
                compare_and_swap(arr, i, i + k, dir)
            bitonic_merge(arr, low, k, dir)
            bitonic_merge(arr, low + k, k, dir)

    def bitonic_sort_recursive(arr, low, cnt, dir):
        if cnt > 1:
            k = cnt // 2
            bitonic_sort_recursive(arr, low, k, True)
            bitonic_sort_recursive(arr, low + k, k, False)
            bitonic_merge(arr, low, cnt, dir)

    n = len(arr)
    if n & (n - 1) != 0:
        raise ValueError("Size of input array must be a power of two.")

    bitonic_sort_recursive(arr, 0, n, reverse)
    return arr

