def longest_common_subsequence(s1: str, s2: str) -> int:
    """
    Finds the length of the longest common subsequence (not necessarily contiguous)
    between two strings, s1 and s2, where s2 contains all distinct characters.
    """
    # Create a dictionary to store the positions of characters in s2
    position = {char: index for index, char in enumerate(s2)}

    # Transform s1 based on the positions from s2
    seq_indices = [position[char] for char in s1 if char in position]

    # Helper function to find the length of the longest increasing subsequence
    def length_of_lis(seq):
        if not seq:
            return 0

        import bisect
        lis = []
        for num in seq:
            pos = bisect.bisect_left(lis, num)
            if pos == len(lis):
                lis.append(num)
            else:
                lis[pos] = num

        return len(lis)

    return length_of_lis(seq_indices)

