def efficient_selection_sort(arr):
    """
    Perform an efficient selection sort on the list `arr` such that the number of swaps and comparisons
    are minimized when possible.
    """
    n = len(arr)
    for i in range(n):
        min_index = i
        for j in range(i+1, n):
            if arr[j] < arr[min_index]:
                min_index = j
        if min_index != i:
            arr[i], arr[min_index] = arr[min_index], arr[i]
    return arr

