def validate_roman(s: str) -> bool:
    valid_chars = {'I', 'V', 'X', 'L', 'C', 'D', 'M'}
    if not s:
        return False

    if any(char not in valid_chars for char in s):
        return False

    invalid_repeats = ["IIII", "VV", "XXXX", "LL", "CCCC", "DD", "MMMM"]
    for repeat in invalid_repeats:
        if repeat in s:
            return False

    # Regex pattern to validate Roman numeral rules
    import re
    pattern = "^M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})$"
    if not re.match(pattern, s):
        return False

    return True


def roman_to_int(s: str) -> int:
    if not validate_roman(s):
        return -1

    roman_numerals = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    result = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_numerals[char]
        if value < prev_value:
            result -= value
        else:
            result += value
        prev_value = value

    return result

def cycle_sort(arr):
    """
    Sorts the input list `arr` using cycle sort algorithm.

    Returns the sorted list.
    """
    n = len(arr)

    # Loop through the array to find cycles to rotate.
    for start in range(n - 1):
        item = arr[start]
        pos = start

        # Find where to put the item.
        for i in range(start + 1, n):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == start:
            continue

        # Skip duplicates.
        while item == arr[pos]:
            pos += 1

        # Put the item to its right position
        arr[pos], item = item, arr[pos]

        # Rotate the rest of the cycle
        while pos != start:
            pos = start

            for i in range(start + 1, n):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            arr[pos], item = item, arr[pos]

    return arr

