def find_difference(s: str, t: str) -> str:
    """
    Finds the extra character added to t.

    :param s: Original string
    :param t: Shuffled string with one additional character
    :return: The extra character
    """
    char_count = {}

    # Count characters in s
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Subtract counts based on characters in t
    for char in t:
        if char not in char_count or char_count[char] == 0:
            return char
        else:
            char_count[char] -= 1

# Example Usage:
# s = "abcd"
# t = "abecd"
# print(find_difference(s, t))  # -> "e"

def remove_duplicates(s: str) -> str:
    seen = set()
    result = []

    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)

    return ''.join(result)

