from typing import List

def longest_common_prefix_horizontal(strs: List[str]) -> str:
    if not strs:
        return ""
    prefix = strs[0]
    for s in strs[1:]:
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
    return prefix

def longest_common_prefix_vertical(strs: List[str]) -> str:
    if not strs:
        return ""
    for i in range(len(strs[0])):
        char = strs[0][i]
        for string in strs[1:]:
            if i == len(string) or string[i] != char:
                return strs[0][:i]
    return strs[0]

def longest_common_prefix_divide_and_conquer(strs: List[str]) -> str:
    def lcp(strs, l, r):
        if l == r:
            return strs[l]
        else:
            mid = (l + r) // 2
            lcpLeft = lcp(strs, l, mid)
            lcpRight = lcp(strs, mid + 1, r)
            return common_prefix(lcpLeft, lcpRight)

    def common_prefix(left, right):
        min_length = min(len(left), len(right))
        for i in range(min_length):
            if left[i] != right[i]:
                return left[:i]
        return left[:min_length]

    if not strs:
        return ""
    return lcp(strs, 0, len(strs) - 1)

