def max_subarray_with_indices(array):
    if not array:
        return (0, -1, -1)

    max_sum = current_sum = array[0]
    start = end = temp_start = 0

    for i in range(1, len(array)):
        if current_sum + array[i] > array[i]:
            current_sum += array[i]
        else:
            current_sum = array[i]
            temp_start = i

        if current_sum > max_sum:
            max_sum = current_sum
            start = temp_start
            end = i

    return (max_sum, start, end)

