def adaptive_selection_sort(arr):
    n = len(arr)
    for i in range(n):
        min_index = i
        is_sorted = True
        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j
            if arr[j] < arr[j - 1]:
                is_sorted = False
        if is_sorted:
            break
        arr[i], arr[min_index] = arr[min_index], arr[i]
    return arr

