def get_factors(n):
    """
    Returns all possible combinations of factors of n (excluding 1 and n itself),
    such that the factors in each combination are in non-decreasing order.
    """
    def backtrack(start, num, path, result):
        while start * start <= num:
            if num % start == 0:
                result.append(path + [start, num // start])
                backtrack(start, num // start, path + [start], result)
            start += 1

    result = []
    backtrack(2, n, [], result)
    return result

def recursive_get_factors(n):
    def find_factors(start, num):
        factors = []
        while start * start <= num:
            if num % start == 0:
                factors.append([start, num // start])
                for sub in find_factors(start, num // start):
                    factors.append([start] + sub)
            start += 1
        return factors

    return find_factors(2, n)

