def find_transitive_closure(n, edges):
    # Initialize the adjacency matrix
    closure = [[0] * n for _ in range(n)]

    # Populate the adjacency matrix with the given edges
    for a, b in edges:
        closure[a][b] = 1

    # Each node is reachable from itself
    for i in range(n):
        closure[i][i] = 1

    # Use Floyd-Warshall algorithm to compute the transitive closure
    for k in range(n):
        for i in range(n):
            for j in range(n):
                closure[i][j] = closure[i][j] or (closure[i][k] and closure[k][j])

    return closure

