def matrix_multiply(multiplicand: list, multiplier: list) -> list:
    """
    Multiplies two matrices and returns their product.

    :param multiplicand: List[List[int]] -- The first matrix in the multiplication.
    :param multiplier: List[List[int]] -- The second matrix in the multiplication.
    :return: List[List[int]] -- The resulting matrix after multiplication.
    """
    if len(multiplicand[0]) != len(multiplier):
        raise ValueError("Number of columns in the multiplicand must be equal to the number of rows in the multiplier.")

    result = [[0] * len(multiplier[0]) for _ in range(len(multiplicand))]

    for i in range(len(multiplicand)):
        for j in range(len(multiplier[0])):
            for k in range(len(multiplier)):
                result[i][j] += multiplicand[i][k] * multiplier[k][j]

    return result

