def find_longest_path(graph, start, end):
    def dfs(node, path):
        if node == end:
            path.append(node)
            return path
        if node in visited:
            return []
        visited.add(node)
        max_path = []
        for neighbor in graph.get(node, []):
            candidate_path = dfs(neighbor, path + [node])
            if len(candidate_path) > len(max_path):
                max_path = candidate_path
        visited.remove(node)
        return max_path

    visited = set()
    return dfs(start, [])

def pattern_match(pattern, string):
    def backtrack(p_index, s_index, mapping, mapped):
        if p_index == len(pattern) and s_index == len(string):
            return True
        if p_index == len(pattern) or s_index == len(string):
            return False

        pattern_char = pattern[p_index]
        if pattern_char in mapping:
            substr = mapping[pattern_char]
            if string.startswith(substr, s_index):
                return backtrack(p_index + 1, s_index + len(substr), mapping, mapped)
            else:
                return False

        for end in range(s_index + 1, len(string) + 1):
            substr = string[s_index:end]
            if substr in mapped:
                continue

            mapping[pattern_char] = substr
            mapped.add(substr)
            if backtrack(p_index + 1, end, mapping, mapped):
                return True
            del mapping[pattern_char]
            mapped.remove(substr)

        return False

    return backtrack(0, 0, {}, set())

