from typing import List

def stooge_sort(arr: List[int]) -> List[int]:
    def stooge_sort_rec(arr: List[int], l: int, h: int):
        if l >= h:
            return

        # Swap if the first element is larger than the last element
        if arr[l] > arr[h]:
            arr[l], arr[h] = arr[h], arr[l]

        # If there are more than 2 elements in the array
        if h - l + 1 > 2:
            t = (h - l + 1) // 3
            stooge_sort_rec(arr, l, h - t)
            stooge_sort_rec(arr, l + t, h)
            stooge_sort_rec(arr, l, h - t)

    stooge_sort_rec(arr, 0, len(arr) - 1)
    return arr

