from typing import List

def add_operators(num: str, target: int) -> List[str]:
    def dfs(pos, expr, prev_op, curr_value):
        if pos == len(num):
            if curr_value == target:
                result.append(expr)
            return

        for i in range(pos, len(num)):
            if i != pos and num[pos] == '0':
                break

            curr_str = num[pos:i + 1]
            curr_num = int(curr_str)

            if pos == 0:
                dfs(i + 1, curr_str, curr_num, curr_num)
            else:
                dfs(i + 1, expr + '+' + curr_str, curr_num, curr_value + curr_num)
                dfs(i + 1, expr + '-' + curr_str, -curr_num, curr_value - curr_num)
                dfs(i + 1, expr + '*' + curr_str, prev_op * curr_num, curr_value - prev_op + (prev_op * curr_num))

    result = []
    dfs(0, "", 0, 0)
    return result

