def custom_fizzbuzz(n, replacements):
    """
    Generates a list of numbers from 1 to n with custom replacements.

    Args:
    n (int): The upper limit of the list.
    replacements (list): A list of dictionaries with "divisor" and "string" keys.

    Returns:
    list: A list where numbers are replaced according to the given rules.
    """
    result = []

    for i in range(1, n + 1):
        replacement_str = ""
        for rule in replacements:
            if i % rule["divisor"] == 0:
                replacement_str += rule["string"]

        if replacement_str:
            result.append(replacement_str)
        else:
            result.append(i)

    return result

