def insert_one_bit(num: int, bit: int, pos: int) -> int:
    """
    Insert a single bit at the specified position of the number.
    """
    mask = 1 << pos
    return (num & ~mask) | ((bit & 1) << pos)

def insert_mult_bits(num: int, bits: int, length: int, pos: int) -> int:
    """
    Insert multiple bits at the specified position of the number.
    """
    mask = ((1 << length) - 1) << pos
    return (num & ~mask) | ((bits & ((1 << length) - 1)) << pos)

def bit_insertion_handler(num: int, action: str, bits_or_bit: int, length: int, pos: int) -> int:
    """
    Handles the bit insertion by determining if single or multiple bits operation should be performed.
    """
    if action == "single":
        return insert_one_bit(num, bits_or_bit, pos)
    elif action == "multiple":
        return insert_mult_bits(num, bits_or_bit, length, pos)
    else:
        raise ValueError("Invalid action specified")

from typing import List

def find_unique_numbers(nums: List[int]) -> List[int]:
    # XOR all numbers to get a^b, where a and b are the unique numbers
    ab = 0
    for n in nums:
        ab ^= n

    # Find the rightmost set bit
    right_most = ab & -ab

    # Divide numbers into two groups based on the rightmost set bit
    a, b = 0, 0
    for n in nums:
        if n & right_most:
            a ^= n
        else:
            b ^= n

    return [a, b]

