def custom_flatten(input_arr):
    """
    Flatten a nested list into a single list containing all the elements in depth-first order.

    Parameters:
    input_arr (list): A potentially nested list containing integers, floats, strings, or other lists.

    Returns:
    list: A flat list with all elements ordered in depth-first traversal.
    """
    def flatten_helper(arr):
        for item in arr:
            if isinstance(item, list):
                yield from flatten_helper(item)
            else:
                yield item

    return list(flatten_helper(input_arr))

