def contains_cycle(graph: dict) -> bool:
    def dfs(vertex, visited, stack):
        visited[vertex] = True
        stack[vertex] = True

        for neighbor in graph.get(vertex, []):
            if not visited[neighbor]:
                if dfs(neighbor, visited, stack):
                    return True
            elif stack[neighbor]:
                return True

        stack[vertex] = False
        return False

    visited = {vertex: False for vertex in graph}
    stack = {vertex: False for vertex in graph}

    for vertex in graph:
        if not visited[vertex]:
            if dfs(vertex, visited, stack):
                return True

    return False

