from typing import List

def ternary_search(arr: List[int], target: int) -> int:
    """
    Perform a ternary search on a sorted list to find the target value.

    Parameters:
    arr (List[int]): A sorted list of integers.
    target (int): The integer value to search for in the array.

    Returns:
    int: The index of the target in the array if found, otherwise -1.
    """
    def search(left: int, right: int) -> int:
        if left > right:
            return -1

        one_third = left + (right - left) // 3
        two_thirds = right - (right - left) // 3

        if arr[one_third] == target:
            return one_third
        if arr[two_thirds] == target:
            return two_thirds

        if target < arr[one_third]:
            return search(left, one_third - 1)
        elif target > arr[two_thirds]:
            return search(two_thirds + 1, right)
        else:
            return search(one_third + 1, two_thirds - 1)

    return search(0, len(arr) - 1)

