from typing import List

def delete_nth(array: List[int], n: int) -> List[int]:
    """
    Returns a list such that each element appears at most n times without reordering.
    """
    count_dict = {}
    result = []

    for item in array:
        current_count = count_dict.get(item, 0)
        if current_count < n:
            result.append(item)
            count_dict[item] = current_count + 1

    return result

