def highlight_phrases(product_names, key_phrases):
    def find_longest_phrase(product, phrases):
        longest_phrase = ""
        for phrase in phrases:
            if phrase in product:
                if (len(phrase) > len(longest_phrase)) or (
                    len(phrase) == len(longest_phrase) and phrase < longest_phrase
                ):
                    longest_phrase = phrase
        return longest_phrase

    highlighted_products = []
    for product in product_names:
        longest_phrase = find_longest_phrase(product, key_phrases)
        if longest_phrase:
            highlighted_product = product.replace(longest_phrase, f"[{longest_phrase}]")
            highlighted_products.append(highlighted_product)
        else:
            highlighted_products.append(product)

    return highlighted_products

def insertion_sort_unique(arr):
    """
    Returns a new list containing the elements of arr sorted in ascending
    order with duplicates removed.
    """
    if not arr:
        return []

    unique_list = []
    for element in arr:
        if element not in unique_list:
            unique_list.append(element)

    # Insertion sort
    for i in range(1, len(unique_list)):
        key = unique_list[i]
        j = i - 1
        while j >= 0 and key < unique_list[j]:
            unique_list[j + 1] = unique_list[j]
            j -= 1
        unique_list[j + 1] = key

    return unique_list

