from typing import List

def summarize_ranges(temperatures: List[int]) -> List[str]:
    """
    Returns a list of strings summarizing continuous ranges of temperatures.

    Parameters:
    temperatures (List[int]): A sorted list of unique integers representing temperature readings.

    Returns:
    List[str]: A list of strings where each string represents a continuous range of readings.
    """
    if not temperatures:
        return []

    ranges = []
    start = temperatures[0]
    end = temperatures[0]

    for temp in temperatures[1:]:
        if temp == end + 1:
            end = temp
        else:
            if start == end:
                ranges.append(f"{start}")
            else:
                ranges.append(f"{start}-{end}")
            start = temp
            end = temp

    if start == end:
        ranges.append(f"{start}")
    else:
        ranges.append(f"{start}-{end}")

    return ranges

