def analyze_hailstone(n: int) -> (int, int):
    length = 1
    max_value = n
    while n > 1:
        if n % 2 != 0:
            n = 3 * n + 1
        else:
            n = n // 2
        if n > max_value:
            max_value = n
        length += 1
    return (length, max_value)

