def recursive_binomial_coefficient(n: int, k: int) -> int:
    """
    Calculate the binomial coefficient C(n, k) using a recursive approach with memoization.
    """
    memo = {}

    def recurse(n, k):
        # Base cases
        if k == 0 or k == n:
            return 1

        # Check if result is already calculated
        if (n, k) in memo:
            return memo[(n, k)]

        # Using the properties of binomial coefficients
        result = recurse(n - 1, k - 1) + recurse(n - 1, k)
        memo[(n, k)] = result
        return result

    return recurse(n, k)

