from typing import List
import bisect

def find_lis_length(prices: List[int]) -> int:
    """
    Returns the length of the longest increasing subsequence.
    """
    if not prices:
        return 0

    lis = []

    for price in prices:
        pos = bisect.bisect_left(lis, price)

        if pos == len(lis):
            lis.append(price)
        else:
            lis[pos] = price

    return len(lis)

