def rabin_karp_search(word, text):
    if not word or not text:
        return -1

    word_len = len(word)
    text_len = len(text)

    if word_len > text_len:
        return -1

    base = 256
    prime_mod = 101

    def compute_hash(s, length):
        h = 0
        for i in range(length):
            h = (h * base + ord(s[i])) % prime_mod
        return h

    word_hash = compute_hash(word, word_len)
    text_hash = compute_hash(text[:word_len], word_len)

    highest_base = pow(base, word_len - 1, prime_mod)

    for i in range(text_len - word_len + 1):
        if word_hash == text_hash:
            if text[i:i + word_len] == word:
                return i

        if i < text_len - word_len:
            text_hash = (text_hash - ord(text[i]) * highest_base) * base + ord(text[i + word_len])
            text_hash = text_hash % prime_mod
            if text_hash < 0:
                text_hash += prime_mod

    return -1

from typing import List

def modified_radix_sort(arr: List[int], simulation: bool = False) -> List[int]:
    if len(arr) <= 1:
        return arr

    max_val = max(arr)
    exp = 1

    def counting_sort(arr, exp):
        n = len(arr)
        output = [0] * n
        count = [0] * 10

        for i in range(n):
            index = (arr[i] // exp) % 10
            count[index] += 1

        for i in range(1, 10):
            count[i] += count[i - 1]

        for i in range(n - 1, -1, -1):
            index = (arr[i] // exp) % 10
            output[count[index] - 1] = arr[i]
            count[index] -= 1

        for i in range(n):
            arr[i] = output[i]

    while max_val // exp > 0:
        counting_sort(arr, exp)
        if simulation:
            print(f"iteration {exp // 10}: {arr}")
        exp *= 10

    return arr

