def atbash_cipher(s: str) -> str:
    """
    Encodes the given string s using the Atbash cipher.
    """
    result = []

    for char in s:
        if 'A' <= char <= 'Z':
            result.append(chr(90 - (ord(char) - 65)))
        elif 'a' <= char <= 'z':
            result.append(chr(122 - (ord(char) - 97)))
        else:
            result.append(char)

    return ''.join(result)

