from typing import List, Dict

def build_prefix_dict(words: List[str]) -> Dict[str, List[str]]:
    prefix_dict = {}
    for word in words:
        for i in range(len(word)):
            prefix = word[:i]
            if prefix in prefix_dict:
                prefix_dict[prefix].append(word)
            else:
                prefix_dict[prefix] = [word]
    return prefix_dict

def backtrack(index: int, word_square: List[str], results: List[List[str]], prefix_dict: Dict[str, List[str]]):
    if index == len(word_square[0]):
        results.append(word_square[:])
        return

    prefix = ''.join(word[index] for word in word_square)
    if prefix in prefix_dict:
        for candidate in prefix_dict[prefix]:
            word_square.append(candidate)
            backtrack(index + 1, word_square, results, prefix_dict)
            word_square.pop()

def generate_word_squares(words: List[str]) -> List[List[str]]:
    if not words:
        return []

    prefix_dict = build_prefix_dict(words)
    results = []

    for word in words:
        backtrack(1, [word], results, prefix_dict)

    return results

