from typing import List

def selection_sort(arr: List[int], simulation: bool=False) -> List[int]:
    n = len(arr)
    if n == 0:
        return []

    # We create a copy of the array to not mutate the input array
    sorted_arr = arr[:]

    for i in range(n):
        # Find the minimum element in unsorted array
        min_idx = i
        for j in range(i + 1, n):
            if sorted_arr[j] < sorted_arr[min_idx]:
                min_idx = j

        # Swap the found minimum element with the first element
        sorted_arr[i], sorted_arr[min_idx] = sorted_arr[min_idx], sorted_arr[i]

        if simulation:
            print(f"Iteration {i} : {' '.join(map(str, sorted_arr))}")

    return sorted_arr

