from typing import List

def sparse_vector_dot_product(vector1: List[float], vector2: List[float]) -> float:
    if len(vector1) != len(vector2):
        return 0.0

    sparse_vector1 = [(i, v) for i, v in enumerate(vector1) if v != 0]
    sparse_vector2 = [(i, v) for i, v in enumerate(vector2) if v != 0]

    dict_vector2 = dict(sparse_vector2)

    dot_product = 0.0
    for i, v in sparse_vector1:
        if i in dict_vector2:
            dot_product += v * dict_vector2[i]

    return dot_product

def int_to_base(num, base: int) -> str:
    """
    Converts an integer to its string representation in a specified base.
    """
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36, inclusive.")

    if num == 0:
        return "0"

    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    is_negative = num < 0
    num = abs(num)

    result = []
    while num:
        result.append(digits[num % base])
        num //= base

    if is_negative:
        result.append('-')

    return ''.join(reversed(result))


def base_to_int(str_to_convert: str, base: int) -> int:
    """
    Converts a string representation of a number in a specified base back to an integer.
    """
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36, inclusive.")

    digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    str_to_convert = str_to_convert.upper()
    is_negative = str_to_convert[0] == '-'

    if is_negative:
        str_to_convert = str_to_convert[1:]

    num = 0
    for char in str_to_convert:
        num = num * base + digits.index(char)

    return -num if is_negative else num

