from typing import List

def warehouse_sort(serial_numbers: List[int]) -> List[int]:
    """
    Sort a list of serial numbers using Cycle Sort algorithm to minimize write operations.
    """
    n = len(serial_numbers)

    # Loop through the array to determine the cycle starting point
    for cycle_start in range(0, n - 1):
        item = serial_numbers[cycle_start]

        # Find the position where we put the element
        pos = cycle_start
        for i in range(cycle_start + 1, n):
            if serial_numbers[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item there or right after any duplicates
        while item == serial_numbers[pos]:
            pos += 1
        serial_numbers[pos], item = item, serial_numbers[pos]

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, n):
                if serial_numbers[i] < item:
                    pos += 1

            while item == serial_numbers[pos]:
                pos += 1
            serial_numbers[pos], item = item, serial_numbers[pos]

    return serial_numbers

