from typing import List

def find_unique_numbers(nums: List[int]) -> List[int]:
    # XOR all the numbers. After this step, the result will be the XOR of the two unique numbers.
    xor_result = 0
    for num in nums:
        xor_result ^= num

    # Get the rightmost set bit in xor_result. This bit will differ between the two unique numbers.
    rightmost_set_bit = xor_result & -xor_result

    # Divide the numbers into two groups and XOR separately.
    num1, num2 = 0, 0
    for num in nums:
        if num & rightmost_set_bit:
            num1 ^= num
        else:
            num2 ^= num

    return [num1, num2]

