from typing import List, Tuple

def find_transitive_closure(num_vertices: int, edges: List[Tuple[int, int]]) -> List[List[int]]:
    # Initialize the transitive closure matrix with 0s
    closure = [[0] * num_vertices for _ in range(num_vertices)]

    # Every vertex can reach itself, so set the diagonal to 1s
    for i in range(num_vertices):
        closure[i][i] = 1

    # Populate the closure matrix based on direct edges
    for (u, v) in edges:
        closure[u][v] = 1

    # Apply Floyd-Warshall algorithm to compute transitive closure
    for k in range(num_vertices):
        for i in range(num_vertices):
            for j in range(num_vertices):
                closure[i][j] = closure[i][j] or (closure[i][k] and closure[k][j])

    return closure

from typing import List

def interpolation_search_price(prices: List[int], target_price: int) -> int:
    low = 0
    high = len(prices) - 1

    while low <= high and target_price >= prices[low] and target_price <= prices[high]:
        if low == high:
            if prices[low] == target_price:
                return low
            return -1

        pos = low + int(((float(high - low) / (prices[high] - prices[low])) * (target_price - prices[low])))

        if prices[pos] == target_price:
            return pos

        if prices[pos] < target_price:
            low = pos + 1
        else:
            high = pos - 1

    return -1

