def constrained_dfs(graph, start, constraint):
    visited = set()
    result = set()

    def dfs(node):
        if node in visited:
            return
        visited.add(node)
        if constraint(node):
            result.add(node)
        for neighbor in graph.get(node, []):
            dfs(neighbor)

    dfs(start)
    return result


def constrained_bfs(graph, start, constraint):
    visited = set()
    result = set()
    queue = [start]

    while queue:
        node = queue.pop(0)
        if node in visited:
            continue
        visited.add(node)
        if constraint(node):
            result.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                queue.append(neighbor)

    return result

