from typing import List, Tuple

def matrix_chain_order(arr: List[int]) -> Tuple[int, List[List[int]]]:
    n = len(arr) - 1
    m = [[0 for _ in range(n)] for _ in range(n)]
    s = [[0 for _ in range(n)] for _ in range(n)]

    for L in range(2, n + 1):
        for i in range(n - L + 1):
            j = i + L - 1
            m[i][j] = float('inf')
            for k in range(i, j):
                q = m[i][k] + m[k + 1][j] + arr[i] * arr[k + 1] * arr[j + 1]
                if q < m[i][j]:
                    m[i][j] = q
                    s[i][j] = k

    return m[0][n-1], s

def reconstruct_optimal_order(s: List[List[int]], i: int, j: int) -> str:
    if i == j:
        return f"A{i+1}"
    else:
        k = s[i][j]
        left_order = reconstruct_optimal_order(s, i, k)
        right_order = reconstruct_optimal_order(s, k + 1, j)
        return f"({left_order} x {right_order})"

def detect_cycle_in_tasks(tasks):
    """
    Detects if there is a cycle in the given set of tasks.

    Parameters:
    tasks (Dict[str, List[str]]): A dictionary representing the task dependencies.

    Returns:
    bool: True if there is at least one cycle, otherwise False.
    """
    visited = set()
    rec_stack = set()

    def is_cyclic(v):
        # Mark the current node as visited and put it in the recursion stack
        visited.add(v)
        rec_stack.add(v)

        # Recur for all tasks it depends on
        for neighbor in tasks.get(v, []):
            if neighbor not in visited:
                if is_cyclic(neighbor):
                    return True
            elif neighbor in rec_stack:
                return True

        # Remove the node from recursion stack
        rec_stack.remove(v)
        return False

    # Check for each task if it is part of a cycle
    for task in tasks:
        if task not in visited:
            if is_cyclic(task):
                return True

    return False

