import math
from typing import List

def find_primitive_root(n: int) -> List[int]:
    if n <= 1:
        return [0] if n == 1 else []

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def is_primitive_root(candidate, n, required_set):
        seen = set()
        power = candidate
        for _ in range(1, n):
            if power in seen or power == 0:
                return False
            seen.add(power)
            power = (power * candidate) % n
        return seen == required_set

    phi_n = n - 1
    required_set = set(range(1, n))
    primitive_roots = []

    for candidate in range(2, n):
        if gcd(candidate, n) == 1 and is_primitive_root(candidate, n, required_set):
            primitive_roots.append(candidate)

    return primitive_roots

