from typing import List, Dict, Set

def optimal_set_cover(universe: List[int], subsets: Dict[str, Set[int]], costs: Dict[str, int]) -> List[str]:
    from itertools import combinations

    n = len(universe)
    best_cost = float('inf')
    best_set_cover = []

    # Iterate through all combinations of subsets to find the optimal cover
    for r in range(1, len(subsets) + 1):
        for combo in combinations(subsets.keys(), r):
            covered = set()
            cost = 0
            for subset in combo:
                covered.update(subsets[subset])
                cost += costs[subset]
            if covered == set(universe) and cost < best_cost:
                best_cost = cost
                best_set_cover = list(combo)

    return best_set_cover

def greedy_set_cover(universe: Set[int], subsets: Dict[str, Set[int]], costs: Dict[str, int]) -> List[str]:
    uncovered = set(universe)
    selected_subsets = []

    while uncovered:
        best_subset = None
        best_cost_effectiveness = float('inf')

        for subset_name, subset in subsets.items():
            covered_elements = uncovered & subset
            if covered_elements:
                cost_effectiveness = costs[subset_name] / len(covered_elements)
                if cost_effectiveness < best_cost_effectiveness:
                    best_cost_effectiveness = cost_effectiveness
                    best_subset = subset_name

        if best_subset is None:
            return [] # No cover found

        uncovered -= subsets[best_subset]
        selected_subsets.append(best_subset)

    return selected_subsets

