def word_pattern(pattern, str):
    """
    Determines if the string follows the same pattern.

    Parameters:
    pattern (str): The pattern string.
    str (str): The input string containing words.

    Returns:
    bool: True if the string follows the pattern, False otherwise.
    """
    word_to_pattern = {}
    pattern_to_word = {}
    words = str.split()

    if len(words) != len(pattern):
        return False

    for p, w in zip(pattern, words):
        if p in pattern_to_word and pattern_to_word[p] != w:
            return False
        if w in word_to_pattern and word_to_pattern[w] != p:
            return False
        pattern_to_word[p] = w
        word_to_pattern[w] = p

    return True

