def is_match(str_a: str, str_b: str) -> bool:
    len_a, len_b = len(str_a), len(str_b)

    # Initialize a DP table with False
    dp = [[False] * (len_b + 1) for _ in range(len_a + 1)]

    # Empty string matches empty pattern
    dp[0][0] = True

    # Handles patterns like a*, a*b*, a*b*c* etc
    for j in range(1, len_b + 1):
        if str_b[j-1] == '*':
            dp[0][j] = dp[0][j-2]

    # Fill the DP table
    for i in range(1, len_a + 1):
        for j in range(1, len_b + 1):
            if str_b[j-1] == str_a[i-1] or str_b[j-1] == '.':
                dp[i][j] = dp[i-1][j-1]
            elif str_b[j-1] == '*':
                dp[i][j] = dp[i][j-2] or (dp[i-1][j] and (str_b[j-2] == str_a[i-1] or str_b[j-2] == '.'))

    return dp[len_a][len_b]

