from typing import List

def match_and_bracket_words(words: List[str], symbols: List[str]) -> List[str]:
    """
    Surrounds matched symbols in words with square brackets.
    If a word matches more than one symbol, choose the one with the longest length.
    """
    result = []

    for word in words:
        match = ""
        for symbol in symbols:
            if symbol in word and len(symbol) > len(match):
                match = symbol
        if match:
            transformed_word = word.replace(match, f"[{match}]")
            result.append(transformed_word)
        else:
            result.append(word)

    return result

