def cycle_sort(arr):
    """
    Perform cycle sort on the list `arr` and return the sorted list.
    """
    writes = 0     # Number of write operations

    # Cycle through each element and perform the sorting
    for start in range(len(arr) - 1):
        item = arr[start]

        # Find the position where we put the element
        pos = start
        for i in range(start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == start:
            continue

        # Otherwise, put the item to its correct position
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle
        while pos != start:
            pos = start
            for i in range(start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

