def encode_rle(input: str) -> str:
    if not input:
        return ""

    encoded = []
    count = 1
    current_char = input[0]

    for char in input[1:]:
        if char == current_char:
            count += 1
        else:
            encoded.append(f"{count}{current_char}")
            current_char = char
            count = 1
    encoded.append(f"{count}{current_char}")

    return "".join(encoded)

def decode_rle(input: str) -> str:
    if not input:
        return ""

    decoded = []
    count = 0

    for char in input:
        if char.isdigit():
            count = count * 10 + int(char)
        else:
            decoded.append(char * count)
            count = 0

    return "".join(decoded)

def cycle_sort(arr):
    writes = 0

    # Traverse the entire array
    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find the position where we put the element
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position, continue
        if pos == cycle_start:
            continue

        # Skip duplicates
        while item == arr[pos]:
            pos += 1

        # Put the item to the right position
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

