from typing import List
import math

def gcd(a: int, b: int) -> int:
    while b:
        a, b = b, a % b
    return a

def find_primitive_root(n: int) -> List[int]:
    def is_primitive_root(root: int, n: int, totient: int) -> bool:
        required = set(range(1, n))
        seen = set()
        current = root
        for _ in range(totient):
            if current in seen or gcd(current, n) != 1:
                return False
            seen.add(current)
            current = current * root % n
        return seen == required

    if n <= 1:
        return [] if n == 0 else [0]

    phi = n - 1  # assuming n is prime; this might need modification for non-prime n
    primitive_roots = []

    for candidate in range(1, n):
        if is_primitive_root(candidate, n, phi):
            primitive_roots.append(candidate)

    return primitive_roots

