def calculate_third_side(opposite, adjacent, hypotenuse):
    """
    Given two sides and identifying one side as unknown ("?"), compute the length of the unknown side.
    If all three sides are provided, return "You already know the answer!".
    Raise ValueError for invalid inputs.
    """
    if opposite != "?" and isinstance(opposite, (int, float)) and opposite < 0:
        raise ValueError("Invalid inputs")
    if adjacent != "?" and isinstance(adjacent, (int, float)) and adjacent < 0:
        raise ValueError("Invalid inputs")
    if hypotenuse != "?" and isinstance(hypotenuse, (int, float)) and hypotenuse < 0:
        raise ValueError("Invalid inputs")

    if opposite != "?" and adjacent != "?" and hypotenuse != "?":
        return "You already know the answer!"

    try:
        if hypotenuse == "?":
            return (opposite**2 + adjacent**2) ** 0.5
        elif adjacent == "?":
            if hypotenuse <= opposite:
                raise ValueError("Invalid inputs")
            return (hypotenuse**2 - opposite**2) ** 0.5
        elif opposite == "?":
            if hypotenuse <= adjacent:
                raise ValueError("Invalid inputs")
            return (hypotenuse**2 - adjacent**2) ** 0.5
    except:
        raise ValueError("Invalid inputs")

    raise ValueError("Invalid inputs")

