def extended_gcd(a, b):
    """
    Returns the Bézout coefficients (s, t) and gcd of a and b
    such that a * s + b * t = gcd(a, b).
    """
    if a == 0:
        return (0, 1, b)
    else:
        s1, t1, gcd = extended_gcd(b % a, a)
        s = t1 - (b // a) * s1
        t = s1
        return (s, t, gcd)

from typing import List

def count_islands(grid: List[List[int]]) -> int:
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])

    def dfs(row, col):
        if row < 0 or row >= rows or col < 0 or col >= cols or grid[row][col] == 0:
            return
        # Mark the cell as visited
        grid[row][col] = 0
        # Recursively explore the neighbors
        dfs(row - 1, col)
        dfs(row + 1, col)
        dfs(row, col - 1)
        dfs(row, col + 1)

    island_count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                island_count += 1
                dfs(r, c)

    return island_count

from typing import List, Dict
from collections import deque, defaultdict

def topological_sort(graph: Dict[int, List[int]]) -> List[int]:
    """
    Perform topological sort on a directed acyclic graph (DAG).

    :param graph: Dictionary representing the graph where keys are task IDs and values are lists of dependent task IDs.
    :return: List of integers representing the topologically sorted order of task IDs.
    :raises ValueError: If a cycle is detected in the graph.
    """
    in_degree = {u: 0 for u in graph}  # Initialize in-degree of all vertices to 0
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1  # Calculate in-degree

    queue = deque([u for u in graph if in_degree[u] == 0])  # Collect all nodes with in-degree 0
    topological_order = []

    while queue:
        u = queue.popleft()  # Remove a node with in-degree 0
        topological_order.append(u)

        for v in graph[u]:
            in_degree[v] -= 1  # Decrease in-degree for all adjacent nodes
            if in_degree[v] == 0:
                queue.append(v)  # If in-degree becomes 0, add to queue

    if len(topological_order) == len(graph):
        return topological_order
    else:
        raise ValueError("cycle")  # If topological order doesn't include all nodes, a cycle must exist

