def smart_reverse(s: str, method: str) -> str:
    def reverse_recursive(s):
        if len(s) == 0:
            return s
        return s[-1] + reverse_recursive(s[:-1])

    def reverse_iterative(s):
        reversed_str = []
        for char in s:
            reversed_str.insert(0, char)
        return ''.join(reversed_str)

    def reverse_pythonic(s):
        return s[::-1]

    def reverse_ultra_pythonic(s):
        return ''.join(reversed(s))

    if method == "recursive":
        return reverse_recursive(s)
    elif method == "iterative":
        return reverse_iterative(s)
    elif method == "pythonic":
        return reverse_pythonic(s)
    elif method == "ultra_pythonic":
        return reverse_ultra_pythonic(s)
    else:
        raise ValueError("Unknown method specified")

