from typing import List, Union

def optimized_comb_sort(arr: List[Union[int, str]]) -> List[Union[int, str]]:
    def next_gap(gap):
        gap = int(gap / 1.3)
        return max(1, gap)

    n = len(arr)
    gap = n
    swapped = True

    while gap != 1 or swapped:
        gap = next_gap(gap)
        swapped = False

        for i in range(0, n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

