def combination(n, r):
    """
    Plain recursive approach to calculate nCr.
    """
    if r == 0 or n == r:
        return 1
    return combination(n-1, r-1) + combination(n-1, r)

def combination_memo(n, r, memo=None):
    """
    Recursive approach with memoization to calculate nCr.
    """
    if memo is None:
        memo = {}
    if r == 0 or n == r:
        return 1
    if (n, r) in memo:
        return memo[(n, r)]
    memo[(n, r)] = combination_memo(n-1, r-1, memo) + combination_memo(n-1, r, memo)
    return memo[(n, r)]

from typing import Dict, List, Set

def reachable_via_dfs(graph: Dict[int, List[int]], start: int) -> Set[int]:
    """
    Returns the set of reachable nodes from the start node using Depth First Search (DFS).
    """
    visited = set()
    stack = [start]

    while stack:
        node = stack.pop()

        if node not in visited:
            visited.add(node)
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    stack.append(neighbor)

    return visited


def reachable_via_bfs(graph: Dict[int, List[int]], start: int) -> Set[int]:
    """
    Returns the set of reachable nodes from the start node using Breadth First Search (BFS).
    """
    visited = set()
    queue = [start]

    while queue:
        node = queue.pop(0)

        if node not in visited:
            visited.add(node)
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    queue.append(neighbor)

    return visited

