from typing import List, Tuple

def count_isolated_groups(node_count: int, edges: List[Tuple[int, int]]) -> int:
    def dfs(node, visited, adjacency_list):
        stack = [node]
        while stack:
            current = stack.pop()
            for neighbor in adjacency_list[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)

    # Create an adjacency list
    adjacency_list = {i: [] for i in range(1, node_count + 1)}
    for u, v in edges:
        adjacency_list[u].append(v)
        adjacency_list[v].append(u)

    visited = [False] * (node_count + 1)
    isolated_groups = 0

    for node in range(1, node_count + 1):
        if not visited[node]:
            visited[node] = True
            isolated_groups += 1
            dfs(node, visited, adjacency_list)

    return isolated_groups

