def matrix_mult(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def matrix_power(mat, power):
    n = len(mat)
    result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
    base = mat

    while power:
        if power % 2 == 1:
            result = matrix_mult(result, base)
        base = matrix_mult(base, base)
        power //= 2

    return result

def state_transition(mat, state, transitions):
    n = len(mat)
    powered_matrix = matrix_power(mat, transitions)
    result_state = [0] * n

    for i in range(n):
        for j in range(n):
            result_state[i] += powered_matrix[i][j] * state[j]

    return result_state

def are_anagrams(s1: str, s2: str) -> bool:
    """
    Returns True if s1 and s2 are anagrams, otherwise False.
    """
    # If the lengths are not the same, they can't be anagrams
    if len(s1) != len(s2):
        return False

    # Count characters in each string
    from collections import Counter
    return Counter(s1) == Counter(s2)

