def cycle_sort(arr):
    """
    Sorts the given list using Cycle Sort algorithm which minimizes the
    number of write operations.
    """
    writes = 0
    # Traverse the array and sort elements cycle by cycle
    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find the position where we put the element
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item to the right position
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

