def compute_histogram(data):
    """
    Constructs a histogram that represents the frequency of each element in the list.

    Parameters:
    data (list): List of integers or strings.

    Returns:
    dict: Dictionary where keys are unique elements of the list and values are their frequency counts.
    """
    histogram = {}
    for item in data:
        if item in histogram:
            histogram[item] += 1
        else:
            histogram[item] = 1
    return histogram

