from typing import List

def sparse_matrix_multiply(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    """
    Multiplies two sparse matrices A and B, returning the resulting sparse matrix.
    Assumes number of columns in A equals number of rows in B.
    """
    # Dimensions
    m, n = len(A), len(A[0])
    p = len(B[0])

    # Step 1: Create dictionary for non-zero elements of A and B
    non_zero_A = {}
    non_zero_B = {}

    for i in range(m):
        for j in range(n):
            if A[i][j] != 0:
                if i not in non_zero_A:
                    non_zero_A[i] = {}
                non_zero_A[i][j] = A[i][j]

    for i in range(n):
        for j in range(p):
            if B[i][j] != 0:
                if i not in non_zero_B:
                    non_zero_B[i] = {}
                non_zero_B[i][j] = B[i][j]

    # Step 2: Initialize result matrix with zeros
    result = [[0] * p for _ in range(m)]

    # Step 3: Compute multiplication using only non-zero elements
    for i in non_zero_A:
        for j in non_zero_A[i]:
            if j in non_zero_B:
                for k in non_zero_B[j]:
                    result[i][k] += non_zero_A[i][j] * non_zero_B[j][k]

    return result

