def heapify(arr, n, i, order='asc', simulation=False):
    if order == 'asc':
        largest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and arr[i] < arr[left]:
            largest = left

        if right < n and arr[largest] < arr[right]:
            largest = right

        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]
            if simulation:
                print("Step:", arr)
            heapify(arr, n, largest, order, simulation)

    elif order == 'desc':
        smallest = i
        left = 2 * i + 1
        right = 2 * i + 2

        if left < n and arr[i] > arr[left]:
            smallest = left

        if right < n and arr[smallest] > arr[right]:
            smallest = right

        if smallest != i:
            arr[i], arr[smallest] = arr[smallest], arr[i]
            if simulation:
                print("Step:", arr)
            heapify(arr, n, smallest, order, simulation)

def heap_sort(arr, order='asc', simulation=False):
    n = len(arr)

    for i in range(n // 2 - 1, -1, -1):
        heapify(arr, n, i, order, simulation)

    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]
        if simulation:
            print("Step:", arr)
        heapify(arr, i, 0, order, simulation)

    return arr

def selection_sort_simulation(arr):
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j

        arr[i], arr[min_idx] = arr[min_idx], arr[i]
        print(f"iteration {i}: {' '.join(map(str, arr))}")
    return arr

