def sanitize_string(input_string: str) -> str:
    """
    Removes all reoccurring characters and returns a string with only the first occurrences
    of each character, preserving their original order.
    """
    seen = set()
    result = []
    for char in input_string:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

