def digit_power_sum(n):
    """
    Function to calculate the sum of digits raised to their respective positions.
    """
    return sum(int(digit)**(index + 1) for index, digit in enumerate(str(n)))

def sum_digit_powers(low: int, high: int) -> list:
    """
    Function to find all numbers between low and high (inclusive)
    that can be written as the sum of their digits raised to their respective positions.
    """
    result = []
    for number in range(low, high + 1):
        if number == digit_power_sum(number):
            result.append(number)
    return result

