def extended_gcd(a, b):
    """
    Returns the gcd of a and b, and coefficients x and y satisfying a*x + b*y = gcd(a, b)
    """
    if b == 0:
        return (1, 0, a) if a >= 0 else (-1, 0, -a)

    x1, y1, g = extended_gcd(b, a % b)
    x = y1
    y = x1 - (a // b) * y1
    return x, y, g

def walls_and_gates(rooms):
    if not rooms or not rooms[0]:
        return

    m, n = len(rooms), len(rooms[0])
    INF = 2147483647

    from collections import deque

    # Initialize a queue with all gate positions.
    queue = deque()
    for row in range(m):
        for col in range(n):
            if rooms[row][col] == 0:
                queue.append((row, col))

    # Directions for traversal: right, left, down, up
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue:
        row, col = queue.popleft()

        for dr, dc in directions:
            new_row, new_col = row + dr, col + dc

            # Skip if out of bounds or not an empty room.
            if (0 <= new_row < m and 0 <= new_col < n and
                rooms[new_row][new_col] == INF):
                rooms[new_row][new_col] = rooms[row][col] + 1
                queue.append((new_row, new_col))

