def longest_common_suffix(strs):
    if not strs:
        return ""

    def common_suffix(s1, s2):
        "Return suffix common of 2 strings"
        if not s1 or not s2:
            return ""
        k = 0
        min_len = min(len(s1), len(s2))
        while k < min_len and s1[-(k + 1)] == s2[-(k + 1)]:
            k += 1
        return s1[-k:] if k > 0 else ""

    suffix = strs[0]
    for i in range(1, len(strs)):
        suffix = common_suffix(suffix, strs[i])
        if suffix == "":
            break
