from typing import List

def interpolation_search_enhanced(array: List[int], search_key: int) -> int:
    """
    Implements enhanced Interpolation Search.

    :param array: Sorted list of integers to be searched.
    :param search_key: Integer value to be searched within the list.

    :returns: Index of search_key if found, otherwise -1.
    """

    if not array:
        return -1

    low, high = 0, len(array) - 1

    while low <= high and array[low] <= search_key <= array[high]:
        # Avoid division by zero errors.
        if array[low] == array[high]:
            if array[low] == search_key:
                return low
            else:
                return -1

        # Interpolation formula
        pos = low + ((search_key - array[low]) * (high - low) // (array[high] - array[low]))

        # If the calculated position is out of range
        if pos < low or pos > high:
            return -1

        if array[pos] == search_key:
            return pos
        elif array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

