from typing import Dict, List, Optional

def two_color_graph(graph: Dict[int, List[int]]) -> Optional[Dict[int, int]]:
    color = {}

    def dfs(node, c):
        if node in color:
            return color[node] == c
        color[node] = c
        return all(dfs(nei, 1 - c) for nei in graph[node])

    for node in graph:
        if node not in color:
            if not dfs(node, 0):
                return None

    return color

