def robust_base_conversion(value: str, from_base: int, to_base: int) -> str:
    """
    Convert a number represented as a string from one base to another base.

    :param value: The number as a string to be converted.
    :param from_base: The original base of the number.
    :param to_base: The base to convert the number to.
    :return: The string representation of the converted number in the target base.
    """

    if from_base < 2 or from_base > 36 or to_base < 2 or to_base > 36:
        raise ValueError(f"Bases must be between 2 and 36, inclusive.")

    # Checking if the input value is negative
    is_negative = value.startswith("-")

    # Remove the negative sign for conversion if present
    if is_negative:
        value = value[1:]

    # Convert the 'value' from 'from_base' to decimal (base 10)
    try:
        decimal_value = int(value, from_base)
    except ValueError:
        raise ValueError(f"Invalid number '{value}' for base {from_base}")

    # Convert the decimal value to 'to_base'
    def from_decimal_to_base(number: int, base: int) -> str:
        if number == 0:
            return "0"

        digits = []
        while number:
            digits.append(int_to_char(number % base))
            number //= base
        return ''.join(digits[::-1])

    def int_to_char(digit: int) -> str:
        if digit >= 0 and digit <= 9:
            return str(digit)
        else:
            return chr(ord('a') + digit - 10)

    converted_value = from_decimal_to_base(decimal_value, to_base)

    # Apply the negative sign back if the input was negative
    if is_negative:
        converted_value = '-' + converted_value

    return converted_value

