def atbash(s: str) -> str:
    def transform(char):
        if 'A' <= char <= 'Z':
            return chr(ord('Z') - (ord(char) - ord('A')))
        elif 'a' <= char <= 'z':
            return chr(ord('z') - (ord(char) - ord('a')))
        else:
            return char

    return ''.join(transform(char) for char in s)

