def enhanced_reverse(s: str) -> str:
    """
    Reverse the input string without using built-in reverse methods.
    Efficiently handles up to 10^6 characters.
    """
    n = len(s)
    reversed_list = [''] * n
    for i in range(n):
        reversed_list[n - i - 1] = s[i]
    return ''.join(reversed_list)

def cycle_sort(arr):
    """
    Sort the array in place using Cycle Sort algorithm.
    """
    writes = 0

    # Loop through the list to find cycles to rotate
    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find where to place the item
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already at the correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item there or right after any duplicates
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1
    return arr

