def are_anagrams(s1: str, s2: str) -> bool:
    """
    Determine if two strings are anagrams, considering non-alphabetic characters
    and treating lower and uppercase letters as the same.
    """
    if len(s1) != len(s2):
        return False

    from collections import defaultdict

    # Normalizing both strings to lowercase and counting characters
    count = defaultdict(int)

    for char in s1.lower():
        count[char] += 1

    for char in s2.lower():
        count[char] -= 1
        if count[char] < 0:
            return False

    return all(value == 0 for value in count.values())

