def binary_search_iterative(array, query):
    """
    :param array: List[int] - a sorted list of integers
    :param query: int - target value to search for
    :return: int - the index of the target value, or -1 if not found
    """
    low, high = 0, len(array) - 1
    while low <= high:
        mid = (low + high) // 2
        if array[mid] == query:
            return mid
        elif array[mid] < query:
            low = mid + 1
        else:
            high = mid - 1
    return -1


def binary_search_recursive(array, query, low, high):
    """
    :param array: List[int] - a sorted list of integers
    :param query: int - target value to search for
    :param low: int - the lower index of the array to consider
    :param high: int - the upper index of the array to consider
    :return: int - the index of the target value, or -1 if not found
    """
    if low > high:
        return -1
    mid = (low + high) // 2
    if array[mid] == query:
        return mid
    elif array[mid] < query:
        return binary_search_recursive(array, query, mid + 1, high)
    else:
        return binary_search_recursive(array, query, low, mid - 1)

