from typing import List

def min_cost(cost: List[List[int]]) -> int:
    N = len(cost)
    # Initialize a list to store the minimum cost to reach each station
    min_cost = [float('inf')] * N
    min_cost[0] = 0  # The cost to reach the first node is 0

    # Traverse the matrix to calculate the minimum cost for each station
    for i in range(N):
        for j in range(i + 1, N):
            # Update the minimum cost to reach station j if the current path is cheaper
            if min_cost[j] > min_cost[i] + cost[i][j]:
                min_cost[j] = min_cost[i] + cost[i][j]

    return min_cost[N - 1]

from typing import List

def matrix_multiply(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] += A[i][k] * B[k][j]
    return result

def matrix_identity(n: int) -> List[List[int]]:
    I = [[0] * n for _ in range(n)]
    for i in range(n):
        I[i][i] = 1
    return I

def matrix_power(mat: List[List[int]], exp: int) -> List[List[int]]:
    n = len(mat)
    result = matrix_identity(n)
    base = mat

    while exp > 0:
        if exp % 2 == 1:
            result = matrix_multiply(result, base)
        base = matrix_multiply(base, base)
        exp //= 2

    return result

def combination(n: int, r: int) -> int:
    """
    Returns the number of ways to choose r items from n items using simple recursion.
    """
    if r == 0 or r == n:
        return 1
    return combination(n-1, r-1) + combination(n-1, r)


from functools import lru_cache

@lru_cache(maxsize=None)
def combination_memo(n: int, r: int) -> int:
    """
    Returns the number of ways to choose r items from n items using memoization.
    """
    if r == 0 or r == n:
        return 1
    return combination_memo(n-1, r-1) + combination_memo(n-1, r)

