def optimized_linear_search(array, query, sorted=False):
    """
    Performs an optimized linear search to find the index of `query` in `array`.

    If `sorted` is True, it attempts to use a more efficient search for sorted arrays.
    For multiple identical elements, the function returns the first occurrence.

    Args:
    - array (list of int): The list of integers to search through.
    - query (int): The integer to search for.
    - sorted (bool): Whether the array is sorted or not.

    Returns:
    - int: Index of the `query` element if found, otherwise -1.
    """
    if sorted:
        # For a sorted array, we can stop early if we find an element greater
        # than the query since the rest of the array will also be greater.
        for index, element in enumerate(array):
            if element == query:
                return index
            elif element > query:
                break
    else:
        # For an unsorted array, we have to check every element.
        for index, element in enumerate(array):
            if element == query:
                return index
    return -1

