def iterative_power(a, n, mod=None):
    result = 1
    base = a if mod is None else a % mod
    while n > 0:
        if n % 2 == 1:  # If n is odd, multiply the current base to the result
            result = result * base if mod is None else (result * base) % mod
        base = base * base if mod is None else (base * base) % mod
        n //= 2
    return result

def recursive_power(a, n, mod=None):
    if n == 0:
        return 1
    half = recursive_power(a, n // 2, mod)
    half = half if mod is None else half % mod
    half = half * half if mod is None else (half * half) % mod
    if n % 2 == 1:
        return half * a if mod is None else (half * a) % mod
    else:
        return half

def modular_exponentiation(a: int, n: int, mod: int = None) -> tuple:
    iter_result = iterative_power(a, n, mod)
    recur_result = recursive_power(a, n, mod)
    return (iter_result, recur_result)

