def largest_scc_size(dict_graph):
    """
    Finds the size of the largest strongly connected component in the given directed graph.

    :param dict_graph: A dictionary representing the adjacency list of the directed graph.
    :return: An integer, representing the size of the largest strongly connected component.
    """
    index = 0
    stack = []
    indices = {}
    lowlink = {}
    on_stack = {}
    sccs = []

    def strongconnect(v):
        nonlocal index
        indices[v] = index
        lowlink[v] = index
        index += 1
        stack.append(v)
        on_stack[v] = True

        for w in dict_graph[v]:
            if w not in indices:
                strongconnect(w)
                lowlink[v] = min(lowlink[v], lowlink[w])
            elif on_stack[w]:
                lowlink[v] = min(lowlink[v], indices[w])

        if lowlink[v] == indices[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            sccs.append(scc)

    for v in dict_graph:
        if v not in indices:
            strongconnect(v)

    largest_scc = max(sccs, key=len, default=[])
    return len(largest_scc)

