from typing import List

def find_primes(m: int) -> List[int]:
    """
    Returns a list of all prime numbers less than m.
    """
    if m <= 2:
        return []

    sieve = [True] * m
    sieve[0] = sieve[1] = False  # 0 and 1 are not primes
    for start in range(2, int(m ** 0.5) + 1):
        if sieve[start]:
            for multiple in range(start * start, m, start):
                sieve[multiple] = False

    return [num for num in range(2, m) if sieve[num]]

