def decode_string(s: str) -> str:
    def helper(idx):
        decoded = ""
        while idx < len(s) and s[idx] != ']':
            if s[idx].isdigit():
                k = 0
                while s[idx].isdigit():
                    k = k * 10 + int(s[idx])
                    idx += 1
                idx += 1  # to skip the '['
                sub_str, idx = helper(idx)
                decoded += sub_str * k
                idx += 1  # to skip the ']'
            else:
                decoded += s[idx]
                idx += 1
        return decoded, idx

    decoded_string, _ = helper(0)
    return decoded_string

