from typing import List

def cycle_sort(arr: List[int]) -> List[int]:
    """
    Function to sort an array using Cycle Sort algorithm,
    which minimizes the number of write operations.
    """
    writes = 0

    # Traverse array elements
    for cycle_start in range(len(arr) - 1):
        item = arr[cycle_start]

        # Find where to put the item
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == cycle_start:
            continue

        # Skip duplicates
        while item == arr[pos]:
            pos += 1

        # Put the item to the correct position
        if pos != cycle_start:
            arr[pos], item = item, arr[pos]
            writes += 1

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1

            if item != arr[pos]:
                arr[pos], item = item, arr[pos]
                writes += 1

    return arr

