def convert_endian(num, is_big_endian=True, to_bytes=True):
    """
    Convert an integer to its byte representation or vice versa, considering the endianness.

    :param num: An integer if `to_bytes` is True, a bytes object if `to_bytes` is False.
    :param is_big_endian: Boolean flag indicating if the conversion should use big-endian format.
    :param to_bytes: Boolean flag indicating conversion direction. True for integer to bytes, False otherwise.
    :return: A bytes object if `to_bytes` is True, an integer if `to_bytes` is False.
    """
    if to_bytes:
        hex_string = hex(num)[2:]
        if len(hex_string) % 2:
            hex_string = '0' + hex_string

        byte_array = bytes.fromhex(hex_string)
        if is_big_endian:
            return byte_array
        else:
            return byte_array[::-1]
    else:
        if not is_big_endian:
            num = num[::-1]
        return int.from_bytes(num, 'big')

