def integer_decompositions(n):
    """
    Returns the number of ways n can be decomposed into sums of non-negative integers.
    """
    dp = [1] + [0] * n
    for i in range(1, n + 1):
        for j in range(i, n + 1):
            dp[j] += dp[j - i]
    return dp[n]

