def custom_exchange_sort(arr):
    """
    Sorts a list of integers using the Exchange Sort algorithm.
    """
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

