from typing import List, Callable, Optional

def k_sum(k: int, arr: List[int], target: int,
          sum_func: Optional[Callable[[int, int], int]] = None,
          compare_func: Optional[Callable[[int, int], int]] = None) -> List[List[int]]:
    if sum_func is None:
        sum_func = lambda x, y: x + y

    if compare_func is None:
        compare_func = lambda x, y: -1 if x < y else (1 if x > y else 0)

    def find_k_sum(start, end, k, target):
        if k == 2:
            return two_sum(start, end, target)
        else:
            res = []
            for i in range(start, end - k + 2):
                if i > start and compare_func(arr[i], arr[i - 1]) == 0:
                    continue
                for subset in find_k_sum(i + 1, end, k - 1, target - arr[i]):
                    res.append([arr[i]] + subset)
            return res

    def two_sum(start, end, target):
        res = []
        l, r = start, end
        while l < r:
            current_sum = sum_func(arr[l], arr[r])
            cmp = compare_func(current_sum, target)
            if cmp == 0:
                res.append([arr[l], arr[r]])
                l += 1
                r -= 1
                while l < r and compare_func(arr[l], arr[l - 1]) == 0:
                    l += 1
                while l < r and compare_func(arr[r], arr[r + 1]) == 0:
                    r -= 1
            elif cmp < 0:
                l += 1
            else:
                r -= 1
        return res

    arr.sort()
    return find_k_sum(0, len(arr) - 1, k, target)

def pattern_match(pattern: str, string: str) -> bool:
    def backtrack(p_idx, s_idx, p_to_s, s_to_p):
        if p_idx == len(pattern) and s_idx == len(string):
            return True
        if p_idx == len(pattern) or s_idx == len(string):
            return False

        p_char = pattern[p_idx]

        for end in range(s_idx + 1, len(string) + 1):
            sub_str = string[s_idx:end]

            if p_char not in p_to_s and sub_str not in s_to_p:
                p_to_s[p_char] = sub_str
                s_to_p[sub_str] = p_char

                if backtrack(p_idx + 1, s_idx + len(sub_str), p_to_s, s_to_p):
                    return True

                del p_to_s[p_char]
                del s_to_p[sub_str]
            elif p_char in p_to_s and p_to_s[p_char] == sub_str:
                if backtrack(p_idx + 1, s_idx + len(sub_str), p_to_s, s_to_p):
                    return True

        return False

    return backtrack(0, 0, {}, {})

