def match_words_with_symbols(words, symbols):
    """
    Matches words with their corresponding symbols and encloses the matched symbol in square brackets.

    If a word matches more than one symbol, the longest symbol is selected.

    Args:
    words: List[str] - List of words to be matched.
    symbols: List[str] - List of symbols to match against the words.

    Returns:
    List[str] - List of words with the matched symbols surrounded by square brackets.
    """
    def find_longest_symbol(word, symbols_by_length):
        for length in sorted(symbols_by_length.keys(), reverse=True):
            for symbol in symbols_by_length[length]:
                if symbol in word:
                    return symbol
        return None

    # Group symbols by their length for efficient searching
    symbols_by_length = {}
    for symbol in symbols:
        symbols_by_length.setdefault(len(symbol), []).append(symbol)

    result = []
    for word in words:
        matched_symbol = find_longest_symbol(word, symbols_by_length)
        if matched_symbol:
            word = word.replace(matched_symbol, f'[{matched_symbol}]', 1)
        result.append(word)

    return result

