def calculate_histogram(input_list: list) -> dict:
    """
    Returns the histogram of the input list as a dictionary where keys are unique
    numbers and values are their respective counts.
    """
    histogram = {}
    for number in input_list:
        if number in histogram:
            histogram[number] += 1
        else:
            histogram[number] = 1
    return histogram

