def optimized_gcd(a, b):
    """
    Compute the greatest common divisor of a and b using the Euclidean algorithm.
    Handles negative inputs and ensures at least one of the numbers is non-zero.
    """
    if a == 0 and b == 0:
        raise ValueError("At least one of the integers must be non-zero")
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def advanced_lcm(a, b):
    """
    Compute the least common multiple of a and b using the relationship between GCD and LCM.
    Both a and b must be non-zero.
    """
    if a == 0 or b == 0:
        raise ValueError("Both integers must be non-zero")
    return abs(a * b) // optimized_gcd(a, b)

def count_trailing_zeros(n):
    """
    Count the number of trailing zeros in the binary representation of a non-negative integer n.
    """
    if n == 0:
        return 0
    count = 0
    while n & 1 == 0:
        n >>= 1
        count += 1
    return count

