def find_n_sum(n, nums, target, sum_closure=None, compare_closure=None):
    def two_sum(nums, start, target, result, results):
        lo, hi = start, len(nums) - 1
        while lo < hi:
            curr_sum = nums[lo] + nums[hi]
            if curr_sum < target:
                lo += 1
            elif curr_sum > target:
                hi -= 1
            else:
                results.append(result + [nums[lo], nums[hi]])
                lo += 1
                hi -= 1
                while lo < hi and nums[lo] == nums[lo - 1]:
                    lo += 1
                while lo < hi and nums[hi] == nums[hi + 1]:
                    hi -= 1

    def k_sum(nums, start, k, target, result, results):
        if k == 2:
            two_sum(nums, start, target, result, results)
            return
        for i in range(start, len(nums) - k + 1):
            if i > start and nums[i] == nums[i - 1]:
                continue
            k_sum(nums, i + 1, k - 1, target - nums[i], result + [nums[i]], results)

    nums.sort()
    results = []
    k_sum(nums, 0, n, target, [], results)
    return results

