def find_cycles(edges):
    """
    Given an undirected graph represented as a list of edges, detects if there is a cycle in the graph using
    the Union-Find data structure.
    """
    def find(parent, i):
        if parent[i] == i:
            return i
        else:
            return find(parent, parent[i])

    def union(parent, rank, x, y):
        root_x = find(parent, x)
        root_y = find(parent, y)

        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    parent = {}
    rank = {}

    # Initialize parent and rank for each vertex
    for edge in edges:
        u, v = edge
        if u not in parent:
            parent[u] = u
            rank[u] = 0
        if v not in parent:
            parent[v] = v
            rank[v] = 0

    # Process each edge
    for edge in edges:
        u, v = edge
        if find(parent, u) == find(parent, v):
            return True
        union(parent, rank, u, v)

    return False

