from typing import List

def optimized_interpolation_search(array: List[int], search_key: int) -> int:
    """
    Perform an optimized interpolation search on a given sorted array.

    Args:
    array: List of integers in increasing order.
    search_key: The integer value to be searched in the array.

    Returns:
    The index of the search_key if found, else -1.
    """
    if not array:
        return -1

    low = 0
    high = len(array) - 1

    while low <= high and array[low] <= search_key <= array[high]:
        if low == high:
            if array[low] == search_key:
                return low
            return -1

        # Estimation of position using interpolation formula
        pos = low + int(((search_key - array[low]) * (high - low)) / (array[high] - array[low]))

        if pos < low or pos > high:
            return -1

        if array[pos] == search_key:
            return pos
        if array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

