def calculate_histogram(readings):
    """
    Returns a histogram for the input list of readings.

    :param readings: List of integers
    :return: Dictionary where keys are unique integers from the input list, and values are their frequencies
    """
    histogram = {}
    for reading in readings:
        if reading in histogram:
            histogram[reading] += 1
        else:
            histogram[reading] = 1
    return histogram

