from typing import List, Tuple

def find_strongly_connected_components(V: int, edges: List[Tuple[int, int]]) -> List[List[int]]:
    index = [0]  # single mutable integer to keep track of the index
    stack = []
    indices = [-1] * V
    lowlink = [-1] * V
    on_stack = [False] * V
    sccs = []

    def strongconnect(v):
        indices[v] = index[0]
        lowlink[v] = index[0]
        index[0] += 1
        stack.append(v)
        on_stack[v] = True

        for (u, w) in edges:
            if u == v:
                if indices[w] == -1:
                    strongconnect(w)
                    lowlink[v] = min(lowlink[v], lowlink[w])
                elif on_stack[w]:
                    lowlink[v] = min(lowlink[v], indices[w])

        if lowlink[v] == indices[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            sccs.append(scc)

    for v in range(V):
        if indices[v] == -1:
            strongconnect(v)

    return sccs

def gcd_lcm_trailing_zeros(a: int, b: int) -> tuple:
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def lcm(x, y):
        return (x * y) // gcd(x, y) if x and y else 0

    def count_trailing_zeros(n):
        count = 0
        while n > 0 and (n & 1) == 0:
            count += 1
            n >>= 1
        return count

    if a == 0 and b == 0:
        return (0, 0, 0, 0)

    gcd_result = gcd(a, b)
    lcm_result = lcm(a, b)

    trailing_zeros_gcd = count_trailing_zeros(gcd_result)
    trailing_zeros_lcm = count_trailing_zeros(lcm_result)

    return (gcd_result, lcm_result, trailing_zeros_gcd, trailing_zeros_lcm)

