from typing import List

def wiggle_sort(nums: List[int]) -> None:
    """
    Reorders nums in-place to satisfy the wiggle property.
    """
    for i in range(1, len(nums)):
        if (i % 2 == 1 and nums[i] < nums[i - 1]) or (i % 2 == 0 and nums[i] > nums[i - 1]):
            nums[i], nums[i - 1] = nums[i - 1], nums[i]

from typing import List

def last_occurrence(array: List[int], query: int) -> int:
    low, high = 0, len(array) - 1
    result = -1

    while low <= high:
        mid = (low + high) // 2

        if array[mid] == query:
            result = mid
            low = mid + 1  # Continue searching in right half
        elif array[mid] < query:
            low = mid + 1
        else:
            high = mid - 1

    return result

from typing import List

def generate_abbreviations(word: str) -> List[str]:
    result = []

    def backtrack(index: int, current: str, count: int):
        if index == len(word):
            if count > 0:
                current += str(count)
            result.append(current)
        else:
            # Option 1: Abbreviate this character
            backtrack(index + 1, current, count + 1)

            # Option 2: Keep this character, abbreviate previous characters (if any)
            if count > 0:
                current += str(count)
            backtrack(index + 1, current + word[index], 0)

    backtrack(0, "", 0)
    return result

def contains_cycle(graph):
    """
    Detect if the given directed graph contains a cycle.

    :param graph: dict - A dictionary where the keys are nodes and the values
                         are lists of nodes representing directed edges.
    :return: bool - True if there is a cycle in the graph, False otherwise.
    """
    def visit(node):
        if node in visiting:
            return True
        if node in visited:
            return False

        visiting.add(node)
        for neighbor in graph.get(node, []):
            if visit(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)
        return False

    visited = set()
    visiting = set()

    for node in graph:
        if visit(node):
            return True
    return False

