def counting_sort(arr, exp, simulation, iteration):
    n = len(arr)

    output = [0] * n  # output array
    count = [0] * 10  # count array for digits 0-9

    for i in range(n):
        index = arr[i] // exp
        count[index % 10] += 1

    for i in range(1, 10):
        count[i] += count[i - 1]

    for i in range(n-1, -1, -1):
        index = arr[i] // exp
        output[count[index % 10] - 1] = arr[i]
        count[index % 10] -= 1

    for i in range(n):
        arr[i] = output[i]

    if simulation:
        print(f"iteration {iteration} : {' '.join(map(str, arr))}")

def radix_sort(arr, simulation=False):
    max1 = max(arr) if arr else 0

    exp = 1
    iteration = 0
    while max1 // exp > 0:
        counting_sort(arr, exp, simulation, iteration)
        exp *= 10
        iteration += 1

    return arr

