def cycle_sort(arr):
    """
    Sorts an array in place using the Cycle Sort algorithm.
    """

    # Loop through the array to find cycles
    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find the position where we put the element
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in the correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item in the correct position, or right after any duplicates
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]

        # Rotate other elements in the current cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]

    return arr

def fibonacci_recursive(n):
    """
    Returns the n-th Fibonacci number using a recursive approach.
    """
    if n <= 1:
        return n
    return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)

def fibonacci_dynamic(n):
    """
    Returns the n-th Fibonacci number using a dynamic programming approach.
    """
    if n <= 1:
        return n
    fib = [0, 1]
    for i in range(2, n + 1):
        fib.append(fib[i - 1] + fib[i - 2])
    return fib[n]

def fibonacci_iterative(n):
    """
    Returns the n-th Fibonacci number using an iterative approach.
    """
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

