def transitive_closure(n: int, edges: List[Tuple[int, int]]) -> List[List[bool]]:
    # Initialize a matrix with False values
    closure = [[False] * n for _ in range(n)]

    # Each vertex is reachable from itself
    for i in range(n):
        closure[i][i] = True

    # Mark the given edges in the closure matrix
    for u, v in edges:
        closure[u][v] = True

    # Apply the Floyd-Warshall algorithm to find the transitive closure
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if closure[i][k] and closure[k][j]:
                    closure[i][j] = True

    return closure

def matrix_chain_order(p):
    n = len(p) - 1
    m = [[0 for _ in range(n)] for _ in range(n)]
    s = [[0 for _ in range(n)] for _ in range(n)]

    for L in range(2, n + 1):
        for i in range(n - L + 1):
            j = i + L - 1
            m[i][j] = float('inf')
            for k in range(i, j):
                q = m[i][k] + m[k + 1][j] + p[i] * p[k + 1] * p[j + 1]
                if q < m[i][j]:
                    m[i][j] = q
                    s[i][j] = k

    def build_order(s, i, j):
        if i == j:
            return f"M{i+1}"
        return f"({build_order(s, i, s[i][j])} x {build_order(s, s[i][j] + 1, j)})"

    order = build_order(s, 0, n - 1)
    return m[0][n - 1], order

def optimized_matrix_exponentiation(mat, n):
    def matrix_mult(A, B):
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                C[i][j] = sum(A[i][k] * B[k][j] for k in range(size))
        return C

    def matrix_power(mat, exp):
        size = len(mat)
        result = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        base = mat
        while exp > 0:
            if exp % 2 == 1:
                result = matrix_mult(result, base)
            base = matrix_mult(base, base)
            exp //= 2
        return result

    return matrix_power(mat, n)

