def generate_parentheses(n):
    """
    Generate all valid combinations of n pairs of parentheses.
    """
    def backtrack(current, open_count, close_count, n, result):
        if len(current) == 2 * n:
            result.append(current)
            return
        if open_count < n:
            backtrack(current + "(", open_count + 1, close_count, n, result)
        if close_count < open_count:
            backtrack(current + ")", open_count, close_count + 1, n, result)

    result = []
    backtrack("", 0, 0, n, result)
    return result

def longest_simple_path(graph, start, end):
    def dfs(node, current_path):
        # If we reached the end node, return the current path
        if node == end:
            return current_path

        # Mark the node as visited
        visited.add(node)
        max_path = []

        # Explore each neighbor
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                candidate_path = dfs(neighbor, current_path + [neighbor])
                if len(candidate_path) > len(max_path):
                    max_path = candidate_path

        # Unmark the node as visited for other paths
        visited.remove(node)
        return max_path

    visited = set()
    return dfs(start, [start])

