from typing import List

def exchange_sort(arr: List[int]) -> List[int]:
    """
    Perform exchange sort on the input list of integers.
    """
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

