def ternary_search(left: int, right: int, key: int, arr: list) -> int:
    if right >= left:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        if key < arr[mid1]:
            return ternary_search(left, mid1 - 1, key, arr)
        elif key > arr[mid2]:
            return ternary_search(mid2 + 1, right, key, arr)
        else:
            return ternary_search(mid1 + 1, mid2 - 1, key, arr)

    return -1

def is_match(s: str, p: str) -> bool:
    m, n = len(s), len(p)

    # dp[i][j] will be True if s[:i] matches p[:j], else False
    dp = [[False] * (n + 1) for _ in range(m + 1)]

    # An empty string matches an empty pattern
    dp[0][0] = True

    # Handle patterns like a*, a*b*, a*b*c* etc.
    for j in range(1, n + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Populate the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if p[j - 1] == s[i - 1] or p[j - 1] == '.':
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or ((p[j - 2] == s[i - 1] or p[j - 2] == '.') and dp[i - 1][j])

    return dp[m][n]

