from typing import List

def max_robbery(houses: List[int]) -> int:
    if not houses:
        return 0

    n = len(houses)

    if n == 1:
        return houses[0]

    if n == 2:
        return max(houses)

    # Dynamic programming table
    dp = [0] * n

    # Base cases
    dp[0] = houses[0]
    dp[1] = max(houses[0], houses[1])

    # Fill the dp table
    for i in range(2, n):
        dp[i] = max(dp[i - 1], dp[i - 2] + houses[i])

    return dp[n - 1]

from typing import List

def highlight_keywords(products: List[str], keywords: List[str]) -> List[str]:
    def find_longest_keyword(product, keywords):
        max_length = 0
        longest_keyword = ""
        position = -1
        for keyword in keywords:
            index = product.find(keyword)
            if index != -1:
                if len(keyword) > max_length:
                    max_length = len(keyword)
                    longest_keyword = keyword
                    position = index
        return longest_keyword, position

    highlighted_products = []
    for product in products:
        longest_keyword, position = find_longest_keyword(product, keywords)
        if position != -1:
            highlighted_product = (f"{product[:position]}[{longest_keyword}]{product[position+len(longest_keyword):]}")
        else:
            highlighted_product = product
        highlighted_products.append(highlighted_product)

    return highlighted_products

