from typing import List, Union

def linear_search_enhanced(array: List[int], query: int) -> Union[int, List[int]]:
    """
    Perform a linear search for `query` in `array`.

    - If the array is empty, return -1.
    - If the query is found once, return its index.
    - If the query is found multiple times, return a list of all indices where the query appears.
    - If the query is not found, return -1.
    """
    if not array:
        return -1

    indices = []
    for i, value in enumerate(array):
        if value == query:
            indices.append(i)

    if not indices:
        return -1
    if len(indices) == 1:
        return indices[0]
    return indices

