from itertools import chain, combinations

def generate_subsets(nums):
    """
    Returns all possible subsets of the given list of distinct integers.
    """
    # Generate all subsets using combinations from itertools
    def subsets(nums):
        return list(chain.from_iterable(combinations(nums, r) for r in range(len(nums)+1)))

    return [list(subset) for subset in subsets(nums)]

import random
from typing import Tuple

def extended_gcd(a: int, b: int) -> Tuple[int, int, int]:
    if a == 0:
        return b, 0, 1
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def modular_inverse(e: int, phi: int) -> int:
    gcd, x, y = extended_gcd(e, phi)
    if gcd != 1:
        raise ValueError('Modular inverse does not exist')
    return x % phi

def generate_rsa_keys(p: int, q: int) -> Tuple[Tuple[int, int], Tuple[int, int]]:
    if p == q:
        raise ValueError('The prime numbers p and q must be distinct')

    n = p * q
    phi = (p - 1) * (q - 1)

    e = random.randrange(2, phi)
    g = extended_gcd(e, phi)[0]
    while g != 1:
        e = random.randrange(2, phi)
        g = extended_gcd(e, phi)[0]

    d = modular_inverse(e, phi)

    return (n, e), (n, d)

