from typing import List

def ternary_search(arr: List[int], key: int) -> int:
    def search(l, r):
        if r >= l:
            mid1 = l + (r - l) // 3
            mid2 = r - (r - l) // 3

            if arr[mid1] == key:
                return mid1
            if arr[mid2] == key:
                return mid2

            if key < arr[mid1]:
                return search(l, mid1 - 1)
            elif key > arr[mid2]:
                return search(mid2 + 1, r)
            else:
                return search(mid1 + 1, mid2 - 1)
        return -1

    return search(0, len(arr) - 1)

