from typing import List

def enhanced_gnome_sort(arr: List[int]) -> List[int]:
    """
    Sorts an array using an enhanced version of the Gnome Sort algorithm with preprocessing.
    """
    n = len(arr)

    # Early exit for empty or single-element lists
    if n <= 1:
        return arr

    # Preprocessing step: count and skip already sorted segments
    index = 0
    while index < n - 1:
        if arr[index] <= arr[index + 1]:
            index += 1
        else:
            break

    # Gnome sort with pointer starting from the end of the sorted segment
    while index < n:
        if index == 0 or arr[index] >= arr[index - 1]:
            index += 1
        else:
            arr[index], arr[index - 1] = arr[index - 1], arr[index]
            index -= 1

    return arr

