def is_match(s: str, p: str) -> bool:
    """
    Returns True if the input string s matches the pattern p, otherwise False.
    The pattern p supports '.' which matches any single character and '*' which
    matches zero or more of the preceding element.
    """
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True  # Both strings are empty

    # Fill for patterns like a*, a*b*, a*b*c* etc.
    for j in range(2, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] if (p[j - 2] == s[i - 1] or p[j - 2] == '.') else False)

    return dp[len(s)][len(p)]

