def edit_distance(word_a: str, word_b: str) -> int:
    """
    Returns the minimum number of operations required to transform `word_a` into `word_b`.
    Operations can be insertions, deletions, or substitutions.
    """
    len_a, len_b = len(word_a), len(word_b)

    # If one of the strings is empty
    if len_a == 0:
        return len_b
    if len_b == 0:
        return len_a

    # Create a (len_a + 1) x (len_b + 1) distance matrix
    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]

    # Initialize the distance matrix
    for i in range(len_a + 1):
        dp[i][0] = i
    for j in range(len_b + 1):
        dp[0][j] = j

    # Compute the distances
    for i in range(1, len_a + 1):
        for j in range(1, len_b + 1):
            if word_a[i - 1] == word_b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j] + 1,    # Deletion
                               dp[i][j - 1] + 1,    # Insertion
                               dp[i - 1][j - 1] + 1) # Substitution

    return dp[len_a][len_b]

