from typing import Iterable

def flatten(input_list: list) -> list:
    """
    Recursively flattens a nested list into a single-dimensional list.
    """
    result = []
    for element in input_list:
        if isinstance(element, list):
            result.extend(flatten(element))
        else:
            result.append(element)
    return result

def flatten_iter(input_list: list) -> Iterable:
    """
    Flattens a nested list into a single-dimensional sequence one element at a time using a generator.
    """
    for element in input_list:
        if isinstance(element, list):
            yield from flatten_iter(element)
        else:
            yield element

