from typing import List

def count_occurrences(array: List[int], target: int) -> int:
    """
    Counts the occurrences of the target value in the sorted array using binary search.
    """
    def find_leftmost(array, target):
        left, right = 0, len(array) - 1
        while left <= right:
            mid = (left + right) // 2
            if array[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_rightmost(array, target):
        left, right = 0, len(array) - 1
        while left <= right:
            mid = (left + right) // 2
            if array[mid] <= target:
                left = mid + 1
            else:
                right = mid - 1
        return right

    leftmost = find_leftmost(array, target)
    rightmost = find_rightmost(array, target)

    # Check if the target is actually present in the array.
    if leftmost < len(array) and array[leftmost] == target:
        return rightmost - leftmost + 1
    else:
        return 0

