from typing import List

def optimized_linear_search(array: List[int], query: int) -> int:
    def is_sorted(arr):
        """Check if the array is sorted in ascending order."""
        return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1))

    def binary_search(arr, q):
        """Binary search implementation."""
        low, high = 0, len(arr) - 1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == q:
                return mid
            elif arr[mid] < q:
                low = mid + 1
            else:
                high = mid - 1
        return -1

    if is_sorted(array):
        return binary_search(array, query)
    else:
        for index, value in enumerate(array):
            if value == query:
                return index
        return -1

from typing import List

def optimized_bubble_sort(arr: List[int], simulation: bool = False) -> List[int]:
    n = len(arr)
    for i in range(n):
        swapped = False
        if simulation:
            print(f"Start of iteration {i}: {' '.join(map(str, arr))}")
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]  # Swap
                swapped = True
        if simulation:
            print(f"End of iteration {i}: {' '.join(map(str, arr))}")
        # If no elements were swapped during the traversal, the array is already sorted
        if not swapped:
            break
    return arr

