def num_decodings(enc_mes: str) -> int:
    if not enc_mes or enc_mes[0] == '0':
        return 0

    n = len(enc_mes)
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1

    for i in range(2, n + 1):
        one_digit = int(enc_mes[i-1])
        two_digits = int(enc_mes[i-2:i])

        if 1 <= one_digit <= 9:
            dp[i] += dp[i-1]

        if 10 <= two_digits <= 26:
            dp[i] += dp[i-2]

    return dp[n]

from typing import List

def adaptive_interpolation_search(arr: List[int], search_key: int) -> int:
    """
    An adaptive interpolation search function to find the index of search_key in a sorted array.
    """
    low = 0
    high = len(arr) - 1

    while low <= high and arr[low] <= search_key <= arr[high]:
        # Avoid division by zero and ensure search_key is within range
        if arr[low] == arr[high]:
            if arr[low] == search_key:
                return low
            else:
                return -1

        # Calculate the interpolation position
        pos = low + int(((search_key - arr[low]) * (high - low)) / (arr[high] - arr[low]))

        # Check if pos is in the allowed range
        if pos < low or pos > high:
            return -1

        if arr[pos] == search_key:
            return pos
        if arr[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

