from typing import List

def optimized_shell_sort(arr: List[int]) -> List[int]:
    n = len(arr)
    gaps = _sedgewick_sequence(n)

    for gap in gaps:
        for i in range(gap, n):
            temp = arr[i]
            j = i
            while j >= gap and arr[j - gap] > temp:
                arr[j] = arr[j - gap]
                j -= gap
            arr[j] = temp

    return arr

def _sedgewick_sequence(n: int) -> List[int]:
    seq = []
    k = 0
    while True:
        gap1 = 9 * (4**k) - 9 * (2**k) + 1
        gap2 = (2**(k+2)) * (2**(k+2) - 3) + 1

        if gap1 < n:
            seq.append(gap1)
        if gap2 < n:
            seq.append(gap2)

        if gap1 >= n and gap2 >= n:
            break
        k += 1

    seq.sort(reverse=True)
    return seq

