from typing import List

def solve_sudoku(board: List[List[str]]) -> None:
    """
    Solves the Sudoku puzzle by filling the empty cells in-place.

    Args:
    board (List[List[str]]): 2D list representing the Sudoku board with '1'-'9' and '.' for empty cells.

    Returns:
    None: The function modifies the input 'board' in-place to reflect the solved Sudoku.
    """
    def is_valid(board, row, col, num):
        # Check if num is not in the current row
        for x in range(9):
            if board[row][x] == num:
                return False
        # Check if num is not in the current column
        for x in range(9):
            if board[x][col] == num:
                return False
        # Check if num is not in the current 3x3 sub-grid
        start_row, start_col = 3 * (row // 3), 3 * (col // 3)
        for i in range(3):
            for j in range(3):
                if board[i + start_row][j + start_col] == num:
                    return False
        return True

    def solve():
        for i in range(9):
            for j in range(9):
                if board[i][j] == '.':
                    for num in '123456789':
                        if is_valid(board, i, j, num):
                            board[i][j] = num
                            if solve():
                                return True
                            board[i][j] = '.'
                    return False
        return True

    solve()

