from collections import deque

def robot_navigation(warehouse):
    def is_valid(x, y):
        return 0 <= x < len(warehouse) and 0 <= y < len(warehouse[0]) and warehouse[x][y] == 1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 0)])  # (row, col, distance)
    warehouse[0][0] = 0  # mark as visited by setting it to 0

    while queue:
        x, y, dist = queue.popleft()

        if x == len(warehouse) - 1 and y == len(warehouse[0]) - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                warehouse[nx][ny] = 0
                queue.append((nx, ny, dist + 1))

    return -1

