def multi_query_search(array, queries):
    """
    Returns the index of each query element in array. If a query element is not found, returns -1.
    """
    # Create a dictionary to store the first occurrence index of each element in the array
    index_map = {}
    for idx, num in enumerate(array):
        if num not in index_map:
            index_map[num] = idx

    # For each query, use the index map to find the index or return -1 if not found
    result = []
    for query in queries:
        result.append(index_map.get(query, -1))

    return result

from typing import List, Iterable, Iterator, Union

def flatten(input_arr: Union[list, tuple]) -> list:
    """
    Flattens a nested array into a single-level array.
    """
    flat_list = []
    for item in input_arr:
        if isinstance(item, (list, tuple)):
            flat_list.extend(flatten(item))
        else:
            flat_list.append(item)
    return flat_list

def flatten_iter(iterable: Iterable) -> Iterator:
    """
    Flattens a nested iterable using a generator.
    """
    for item in iterable:
        if isinstance(item, (list, tuple)):
            yield from flatten_iter(item)
        else:
            yield item

