def binary_search_iterative(array, target):
    """
    Perform a binary search using iterative approach.
    :param array: List[int] - Sorted list of integers
    :param target: int - Target integer to find
    :return: int - Index of the target in array or -1 if not found
    """
    low, high = 0, len(array) - 1
    while low <= high:
        mid = (low + high) // 2
        if array[mid] == target:
            return mid
        elif array[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_recursive(array, target, low, high):
    """
    Perform a binary search using recursive approach.
    :param array: List[int] - Sorted list of integers
    :param target: int - Target integer to find
    :param low: int - Starting index of the current subarray
    :param high: int - Ending index of the current subarray
    :return: int - Index of the target in array or -1 if not found
    """
    if low > high:
        return -1

    mid = (low + high) // 2
    if array[mid] == target:
        return mid
    elif array[mid] < target:
        return binary_search_recursive(array, target, mid + 1, high)
    else:
        return binary_search_recursive(array, target, low, mid - 1)

def find_difference(s: str, t: str) -> str:
    """
    Returns the character that was added to string t compared to string s.
    """
    # XOR all characters of both strings
    result = 0
    for char in s:
        result ^= ord(char)
    for char in t:
        result ^= ord(char)

    # Convert the result back to a character
    return chr(result)

