def get_primes(n):
    """
    Return a list of all prime numbers less than n
    """
    if n <= 2:
        return []

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for i in range(start*start, n, start):
                sieve[i] = False

    return [num for num, is_prime in enumerate(sieve) if is_prime]

def count_primes(n):
    """
    Returns the count of prime numbers less than n
    """
    primes = get_primes(n)
    return len(primes)

def sum_primes(n):
    """
    Returns the sum of all prime numbers less than n
    """
    primes = get_primes(n)
    return sum(primes)

