from typing import List

def counting_sort_for_radix(arr, exp, simulation=False):
    n = len(arr)
    output = [0] * n
    count = [0] * 10

    for i in range(n):
        index = arr[i] // exp
        count[index % 10] += 1

    for i in range(1, 10):
        count[i] += count[i - 1]

    for i in range(n - 1, -1, -1):
        index = arr[i] // exp
        output[count[index % 10] - 1] = arr[i]
        count[index % 10] -= 1

    for i in range(n):
        arr[i] = output[i]

    if simulation:
        print(f"Sorting with exp={exp}, intermediate array: {arr}")

def radix_sort(arr: List[int], simulation=False) -> List[int]:
    if len(arr) == 0:
        return arr

    max_val = max(arr)
    exp = 1

    while max_val // exp > 0:
        counting_sort_for_radix(arr, exp, simulation)
        exp *= 10

    return arr

