def enhanced_optimal_set_cover(universe: set, subsets: dict, costs: dict) -> tuple:
    from functools import lru_cache

    # Convert subsets dictionary to a list for better indexing
    subset_list = list(subsets.items())

    @lru_cache(None)
    def dp(current_cover, index):
        # If universe is covered, return an empty set and cost 0
        if current_cover == universe:
            return [], 0
        if index >= len(subset_list):
            return None

        # Subset and cost for current index
        subset_name, subset_elements = subset_list[index]
        subset_cost = costs[subset_name]

        # Option 1: Skip current subset
        skip_solution = dp(current_cover, index + 1)

        # Option 2: Include current subset
        new_cover = current_cover | subset_elements
        include_solution = dp(new_cover, index + 1)

        if include_solution is not None:
            include_solution = ([subset_name] + include_solution[0], subset_cost + include_solution[1])

        # Determine the better option
        if skip_solution is None:
            return include_solution
        if include_solution is None:
            return skip_solution
        if skip_solution[1] < include_solution[1]:
            return skip_solution
        else:
            return include_solution

    result = dp(frozenset(), 0)
    return result

