def encode_rle(input):
    if not input:
        return ""

    encoded_string = []
    current_char = input[0]
    count = 1

    for char in input[1:]:
        if char == current_char:
            count += 1
        else:
            encoded_string.append(f"{count}{current_char}")
            current_char = char
            count = 1

    encoded_string.append(f"{count}{current_char}")
    return "".join(encoded_string)

def decode_rle(input):
    if not input:
        return ""

    decoded_string = []
    count = 0

    for char in input:
        if char.isdigit():
            count = count * 10 + int(char)
        else:
            decoded_string.append(char * count)
            count = 0

    return "".join(decoded_string)

