def multiply(A, B):
    """
    Multiplies two sparse matrices A and B.

    A: List[List[int]], a sparse matrix where len(A[0]) == len(B)
    B: List[List[int]], a sparse matrix where len(B[0])

    Returns a matrix representing the result of AB.
    """
    # Dimensions of the result matrix
    m, n, l = len(A), len(B[0]), len(A[0])

    # Initialize the result matrix with zeros
    C = [[0] * n for _ in range(m)]

    # Only non-zero elements are stored in a more compact form
    nonzero_A = {}
    for i in range(m):
        for k in range(l):
            if A[i][k] != 0:
                if i not in nonzero_A:
                    nonzero_A[i] = {}
                nonzero_A[i][k] = A[i][k]

    nonzero_B = {}
    for k in range(l):
        for j in range(n):
            if B[k][j] != 0:
                if k not in nonzero_B:
                    nonzero_B[k] = {}
                nonzero_B[k][j] = B[k][j]

    # Perform the multiplication using non-zero elements
    for i in nonzero_A:
        for k in nonzero_A[i]:
            if k in nonzero_B:
                for j in nonzero_B[k]:
                    C[i][j] += nonzero_A[i][k] * nonzero_B[k][j]

    return C

def custom_factorial(n: int, approach: str, mod: int = None) -> int:
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer.")

    if mod is not None and (not isinstance(mod, int) or mod <= 0):
        raise ValueError("mod must be a positive integer.")

    if approach not in ["iterative", "recursive"]:
        raise ValueError("approach must be either 'iterative' or 'recursive'.")

    if approach == "iterative":
        return _factorial_iterative(n, mod)
    else:
        return _factorial_recursive(n, mod)

def _factorial_iterative(n: int, mod: int = None) -> int:
    result = 1
    for i in range(2, n + 1):
        result *= i
        if mod:
            result %= mod
    return result

def _factorial_recursive(n: int, mod: int = None) -> int:
    if n == 0 or n == 1:
        return 1
    if mod:
        return (n * _factorial_recursive(n - 1, mod)) % mod
    else:
        return n * _factorial_recursive(n - 1)

