from itertools import chain, combinations

def generate_subsets(options):
    """
    Generates all subsets of the input list of options.

    Parameters:
    options (list): A list of distinct integers.

    Returns:
    set: A set containing all subsets represented as tuples.
    """
    def all_subsets(options):
        return chain.from_iterable(combinations(options, r) for r in range(len(options) + 1))

    return set(all_subsets(options))

