def contains_cycle(graph):
    """
    Detects if a directed graph contains a cycle.

    :param graph: Dict[str, List[str]] - A dictionary representing an adjacency list where the keys are nodes,
                 and the values are lists of nodes to which the key has directed edges.
    :return: bool - True if the graph contains a cycle, False otherwise.
    """
    WHITE, GRAY, BLACK = 0, 1, 2

    # Initialize all nodes to the 'unvisited' state
    color = {node: WHITE for node in graph}

    def dfs(node):
        if color[node] == GRAY:
            return True
        if color[node] == BLACK:
            return False

        color[node] = GRAY

        for neighbor in graph[node]:
            if dfs(neighbor):
                return True

        color[node] = BLACK
        return False

    for node in graph:
        if color[node] == WHITE:
            if dfs(node):
                return True

    return False

