def binary_search_iterative(array, target):
    """
    Perform binary search iteratively.
    Args:
    array : List[int]: A list of integers sorted in ascending order.
    target : int: An integer value to search for in the array.

    Returns:
    int: The index of the target if found, otherwise -1.
    """
    low, high = 0, len(array) - 1

    while low <= high:
        mid = (low + high) // 2
        if array[mid] == target:
            return mid
        elif array[mid] < target:
            low = mid + 1
        else:
            high = mid - 1

    return -1

def binary_search_recursive(array, low, high, target):
    """
    Perform binary search recursively.
    Args:
    array : List[int]: A list of integers sorted in ascending order.
    low : int: The starting index of the array/subarray to be searched.
    high : int: The ending index of the array/subarray to be searched.
    target : int: An integer value to search for in the array.

    Returns:
    int: The index of the target if found, otherwise -1.
    """
    if low > high:
        return -1

    mid = (low + high) // 2
    if array[mid] == target:
        return mid
    elif array[mid] < target:
        return binary_search_recursive(array, mid + 1, high, target)
    else:
        return binary_search_recursive(array, low, mid - 1, target)

def is_circle(moves: str) -> bool:
    """
    Determine if the robot returns to the origin (0, 0) after a series of moves.

    Args:
    moves (str): A string of moves consisting of characters 'R', 'L', 'U', 'D'.

    Returns:
    bool: True if the robot returns to the origin, False otherwise.
    """
    x, y = 0, 0

    for move in moves:
        if move == 'R':
            x += 1
        elif move == 'L':
            x -= 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    return x == 0 and y == 0

