from typing import Union

def pythagoras(opposite: Union[float, str], adjacent: Union[float, str], hypotenuse: Union[float, str]) -> str:
    if opposite == '?' and isinstance(adjacent, float) and isinstance(hypotenuse, float):
        if hypotenuse <= adjacent:
            raise ValueError("Hypotenuse must be the longest side.")
        opposite_length = (hypotenuse ** 2 - adjacent ** 2) ** 0.5
        return f"Opposite = {opposite_length:.1f}"

    if adjacent == '?' and isinstance(opposite, float) and isinstance(hypotenuse, float):
        if hypotenuse <= opposite:
            raise ValueError("Hypotenuse must be the longest side.")
        adjacent_length = (hypotenuse ** 2 - opposite ** 2) ** 0.5
        return f"Adjacent = {adjacent_length:.1f}"

    if hypotenuse == '?' and isinstance(opposite, float) and isinstance(adjacent, float):
        hypotenuse_length = (opposite ** 2 + adjacent ** 2) ** 0.5
        return f"Hypotenuse = {hypotenuse_length:.1f}"

    if all(isinstance(x, float) for x in [opposite, adjacent, hypotenuse]):
        return "You already know the answer!"

    raise ValueError("Invalid input.")

