def is_prime(n: int) -> bool:
    """
    Check if a given number is prime.

    Parameters:
    n (int): The number to check for primality.

    Returns:
    bool: True if n is a prime number, else False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

