def longest_increasing_subsequence(sequence):
    """
    Returns the length of the longest increasing subsequence in the given list of integers.
    """
    if not sequence:
        return 0

    # List to store the length of the LIS ending at each index
    n = len(sequence)
    lis = [1] * n

    # Build the LIS length array
    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in the lis array
    return max(lis)

