from typing import List

def generate_abbreviations(word: str) -> List[str]:
    def backtrack(pos: int, cur: str, count: int):
        if pos == len(word):
            if count > 0:
                cur += str(count)
            res.append(cur)
        else:
            # Abbreviate the current character
            backtrack(pos + 1, cur, count + 1)
            # Keep the current character
            backtrack(pos + 1, cur + (str(count) if count > 0 else '') + word[pos], 0)

    res = []
    backtrack(0, "", 0)
    return res

def rotate_image(image):
    """
    Rotate the input N x N matrix by 90 degrees clockwise in-place.
    """
    n = len(image)
    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            image[i][j], image[j][i] = image[j][i], image[i][j]

    # Reverse each row
    for i in range(n):
        image[i].reverse()

