from typing import List, Tuple

def find_transitive_closure(vertices: int, edges: List[Tuple[int, int]]) -> List[List[int]]:
    def dfs(start: int, u: int):
        for v in adjacency_list[u]:
            if closure[start][v] == 0:
                closure[start][v] = 1
                dfs(start, v)

    # Initialize adjacency list
    adjacency_list = [[] for _ in range(vertices)]
    for (src, dst) in edges:
        adjacency_list[src].append(dst)

    # Initialize the closure matrix
    closure = [[0] * vertices for _ in range(vertices)]

    # For each vertex, run DFS to find all reachable vertices
    for i in range(vertices):
        closure[i][i] = 1
        dfs(i, i)

    return closure

