def is_palindrome_recursive(s: str) -> bool:
    cleaned_s = ''.join(char.lower() for char in s if char.isalnum())

    def helper(sub_s):
        if len(sub_s) <= 1:
            return True
        if sub_s[0] != sub_s[-1]:
            return False
        return helper(sub_s[1:-1])

    return helper(cleaned_s)


def is_palindrome_iterative(s: str) -> bool:
    cleaned_s = ''.join(char.lower() for char in s if char.isalnum())
    left, right = 0, len(cleaned_s) - 1

    while left < right:
        if cleaned_s[left] != cleaned_s[right]:
            return False
        left += 1
        right -= 1

    return True


def is_palindrome_pythonic(s: str) -> bool:
    cleaned_s = ''.join(char.lower() for char in s if char.isalnum())
    return cleaned_s == cleaned_s[::-1]

def atbash_cipher(s: str) -> str:
    """
    Applies the Atbash cipher to the input string `s`.
    """
    result = []

    for char in s:
        if char.isalpha():
            if char.islower():
                result.append(chr(219 - ord(char)))  # 'a' + 'z' = 219
            elif char.isupper():
                result.append(chr(155 - ord(char)))  # 'A' + 'Z' = 155
        else:
            result.append(char)

    return ''.join(result)

