from typing import List

def rotated_search(rotated_array: List[int], search_key: int) -> int:
    """
    Returns the index of search_key in the rotated_array or -1 if not found.
    """
    if not rotated_array:
        return -1

    left, right = 0, len(rotated_array) - 1

    while left <= right:
        mid = (left + right) // 2

        if rotated_array[mid] == search_key:
            return mid

        # Determine which side is properly sorted
        if rotated_array[left] <= rotated_array[mid]: # Left side is sorted
            if rotated_array[left] <= search_key < rotated_array[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else: # Right side is sorted
            if rotated_array[mid] < search_key <= rotated_array[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

from typing import List, Tuple, Optional

def one_sparse(stream: List[Tuple[int, str]]) -> Optional[int]:
    count_map = {}

    for value, sign in stream:
        if sign == '+':
            count_map[value] = count_map.get(value, 0) + 1
        elif sign == '-':
            count_map[value] = count_map.get(value, 0) - 1

    non_zero_counts = [key for key, count in count_map.items() if count != 0]

    if len(non_zero_counts) == 1:
        return non_zero_counts[0]

    return None

