from typing import List

def generate_permutations(nums: List[int]) -> List[List[int]]:
    def permute(prefix, remaining):
        if not remaining:
            result.append(prefix)
            return
        for i in range(len(remaining)):
            permute(prefix + [remaining[i]], remaining[:i] + remaining[i+1:])

    result = []
    permute([], nums)
    return result

def atbash(s: str) -> str:
    """
    Encrypts the input string using the Atbash cipher.

    Args:
    s (str): The input string to be encrypted.

    Returns:
    str: The encrypted string using the Atbash cipher.
    """

    def atbash_char(c):
        if 'a' <= c <= 'z':
            return chr(219 - ord(c))
        elif 'A' <= c <= 'Z':
            return chr(155 - ord(c))
        else:
            return c

    return ''.join(atbash_char(c) for c in s)

