def precise_square_root(n: int, epsilon: float = 0.001) -> float:
    """
    Return square root of n, with maximum absolute error epsilon using Newton's method.
    """
    if n == 1:
        return 1.0

    guess = n / 2.0  # Initial guess
    while True:
        new_guess = (guess + n / guess) / 2.0
        if abs(new_guess - guess) < epsilon:
            return new_guess
        guess = new_guess

