def limit(arr: list, min_lim: int = None, max_lim: int = None) -> list:
    """
    Filters values in an array based on specified minimum and maximum boundaries.
    """
    if min_lim is None:
        min_lim = min(arr) if arr else float('-inf')
    if max_lim is None:
        max_lim = max(arr) if arr else float('inf')

    # Ensure min_lim <= max_lim
    if min_lim > max_lim:
        return []

    return [x for x in arr if min_lim <= x <= max_lim]

