def enhanced_interpolation_search(array, search_key):
    """
    Perform a search for search_key in a sorted array using an enhanced interpolation search algorithm.
    Returns the index of search_key if found, otherwise returns -1.
    """
    low = 0
    high = len(array) - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        if low == high:
            if array[low] == search_key:
                return low
            return -1

        # To prevent division by zero
        if array[high] == array[low]:
            pos = low
        else:
            # Probing the position with keeping uniform distribution in mind
            pos = low + ((high - low) // (array[high] - array[low]) * (search_key - array[low]))

        # Condition of target found
        if array[pos] == search_key:
            return pos

        # If search_key is larger, search in the upper part
        if array[pos] < search_key:
            low = pos + 1
        # If search_key is smaller, search in the lower part
        else:
            high = pos - 1

    return -1

