def binary_search(prices, target):
    """
    Iterative version of binary search to find the index of target in the sorted list prices.
    Returns the index of target if found, else returns -1.
    """
    low, high = 0, len(prices) - 1
    while low <= high:
        mid = (high + low) // 2
        val = prices[mid]
        if val == target:
            return mid
        if val < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def binary_search_recursive(prices, low, high, target):
    """
    Recursive version of binary search to find the index of target in the sorted list prices.
    Returns the index of target if found, else returns -1.
    """
    if low > high:
        return -1
    mid = low + (high - low) // 2
    if prices[mid] == target:
        return mid
    if prices[mid] > target:
        return binary_search_recursive(prices, low, mid - 1, target)
    return binary_search_recursive(prices, mid + 1, high, target)

