def matrix_multiply(A, B):
    """
    Multiplies two square matrices A and B.
    """
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            result[i][j] = sum(A[i][k] * B[k][j] for k in range(n))
    return result

def matrix_power(mat, power):
    """
    Raises the square matrix `mat` to the power `power` using exponentiation by squaring.
    """
    n = len(mat)

    # Identity matrix of size n
    def identity_matrix(n):
        return [[1 if i == j else 0 for j in range(n)] for i in range(n)]

    def power_helper(mat, power):
        if power == 0:
            return identity_matrix(n)
        elif power == 1:
            return mat
        else:
            half = power_helper(mat, power // 2)
            half_square = matrix_multiply(half, half)
            return matrix_multiply(half_square, mat) if power % 2 else half_square

    return power_helper(mat, power)

def move_zeros(array: list) -> list:
    """
    Moves all zeros in the list to the end while preserving the order of other elements.
    """
    result = []
    zero_count = 0

    for element in array:
        if element == 0 and not isinstance(element, bool):
            zero_count += 1
        else:
            result.append(element)

    result.extend([0] * zero_count)

    return result

