def custom_fizzbuzz(n: int, rules: dict, replacements: dict) -> list:
    """
    Generates a list of length n where numbers are replaced according to given rules and replacements.

    :param n: Upper limit integer (inclusive).
    :param rules: Dictionary with integers as keys and their replacement strings as values.
    :param replacements: Dictionary with tuples of integers as keys and their replacement strings as values.
    :return: List with numbers replaced as per the defined rules and replacements.
    """
    result = []

    for i in range(1, n + 1):
        replaced = False
        for key, value in replacements.items():
            if all(i % k == 0 for k in key):
                result.append(value)
                replaced = True
                break

        if not replaced:
            for key, value in rules.items():
                if i % key == 0:
                    result.append(value)
                    replaced = True
                    break

        if not replaced:
            result.append(i)

    return result

