from collections import deque

def walls_and_gates(rooms):
    if not rooms:
        return

    rows, cols = len(rooms), len(rooms[0])
    GATE = 0
    INF = 2147483647
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if rooms[r][c] == GATE:
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and rooms[nr][nc] == INF:
                rooms[nr][nc] = rooms[r][c] + 1
                queue.append((nr, nc))

def has_valid_shortest_path(graph, source):
    # Step 1: Initialization
    distance = {node: float('inf') for node in graph}
    distance[source] = 0

    # Step 2: Relax edges repeatedly |V| - 1 times
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if distance[u] != float('inf') and distance[u] + graph[u][v] < distance[v]:
                    distance[v] = distance[u] + graph[u][v]

    # Step 3: Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if distance[u] != float('inf') and distance[u] + graph[u][v] < distance[v]:
                return False  # Negative weight cycle found

    return True  # No negative weight cycle found

