def delete_reoccurring_characters_optimized(string: str) -> str:
    """
    Returns a new string with all duplicate characters removed, retaining only the first occurrence of each character.
    """
    seen = set()
    result = []
    for char in string:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

from typing import List

def edit_distance(word_a, word_b):
    length_a, length_b = len(word_a) + 1, len(word_b) + 1

    edit = [[0 for _ in range(length_b)] for _ in range(length_a)]

    for i in range(1, length_a):
        edit[i][0] = i

    for j in range(1, length_b):
        edit[0][j] = j

    for i in range(1, length_a):
        for j in range(1, length_b):
            cost = 0 if word_a[i - 1] == word_b[j - 1] else 1
            edit[i][j] = min(edit[i - 1][j] + 1, edit[i][j - 1] + 1, edit[i - 1][j - 1] + cost)

    return edit[-1][-1]

def find_closest_word(dictionary: List[str], query: str) -> str:
    min_distance = float('inf')
    closest_word = ""

    for word in dictionary:
        distance = edit_distance(word, query)
        if distance < min_distance:
            min_distance = distance
            closest_word = word
        elif distance == min_distance:
            closest_word = closest_word if dictionary.index(closest_word) < dictionary.index(word) else word

    return closest_word

