from typing import List

def find_book_id(book_ids: List[int], book_id: int) -> int:
    """
    Locate the position of a given book ID in the sorted database using ternary search.
    If the book ID is not found, return -1.
    """
    def ternary_search(l, r, key, arr):
        if r >= l:
            mid1 = l + (r - l) // 3
            mid2 = r - (r - l) // 3

            if arr[mid1] == key:
                return mid1
            if arr[mid2] == key:
                return mid2

            if key < arr[mid1]:
                return ternary_search(l, mid1 - 1, key, arr)
            elif key > arr[mid2]:
                return ternary_search(mid2 + 1, r, key, arr)
            else:
                return ternary_search(mid1 + 1, mid2 - 1, key, arr)

        return -1

    return ternary_search(0, len(book_ids) - 1, book_id, book_ids)

