def transform_matrix(matrix, transformation_type):
    """
    Transforms the given matrix based on the specified transformation type.

    :param matrix: A 2D list of integers representing the matrix.
    :param transformation_type: A string specifying the transformation type.
    :return: A new 2D list of integers representing the transformed matrix.
    """

    if transformation_type == "clockwise":
        return [list(row) for row in zip(*matrix[::-1])]

    elif transformation_type == "counterclockwise":
        return [list(row) for row in zip(*matrix)][::-1]

    elif transformation_type == "top_left_invert":
        return [list(row) for row in zip(*matrix)]

    elif transformation_type == "bottom_left_invert":
        return [list(row) for row in zip(*matrix[::-1])][::-1]

    else:
        raise ValueError("Invalid transformation type provided")

def binomial_coefficient(n: int, k: int, memo=None) -> int:
    if memo is None:
        memo = {}

    # Base cases
    if k == 0 or k == n:
        return 1

    # Check if value is already computed
    if (n, k) in memo:
        return memo[(n, k)]

    # Using the property C(n, k) = C(n-1, k-1) + C(n-1, k)
    memo[(n, k)] = binomial_coefficient(n - 1, k - 1, memo) + binomial_coefficient(n - 1, k, memo)

    return memo[(n, k)]

def min_edit_distance(word_a, word_b):
    len_a = len(word_a)
    len_b = len(word_b)

    # Create a 2D array to store the edit distances
    dp = [[0] * (len_b + 1) for _ in range(len_a + 1)]

    # Initialize the first row and first column
    for i in range(1, len_a + 1):
        dp[i][0] = i
    for j in range(1, len_b + 1):
        dp[0][j] = j

    # Fill the dp table
    for i in range(1, len_a + 1):
        for j in range(1, len_b + 1):
            if word_a[i - 1] == word_b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1

    return dp[len_a][len_b]

