def repeat_substring(s: str) -> bool:
    """
    Returns True if the string can be constructed by repeating a substring,
    otherwise False.
    """
    n = len(s)
    for i in range(1, n//2 + 1):
        if n % i == 0:
            if s[:i] * (n // i) == s:
                return True
    return False

