def count_sentences(s: str, dictionary: set) -> int:
    """
    Returns the total number of ways to segment the string into valid words present in the dictionary.
    """
    # Initialize an array to hold the computed results (dp array)
    dp = [0] * (len(s) + 1)
    dp[0] = 1 # There's exactly one way to segment an empty substring

    for i in range(1, len(s) + 1):
        for j in range(i):
            if s[j:i] in dictionary:
                dp[i] += dp[j]

    return dp[len(s)]

