from typing import List, Tuple

def optimal_matrix_chain_order(dimensions: List[int]) -> Tuple[int, List[List[int]]]:
    n = len(dimensions)
    # Initialize DP tables
    m = [[0 for _ in range(n)] for _ in range(n)]
    s = [[0 for _ in range(n)] for _ in range(n)]

    # l is chain length
    for l in range(2, n):
        for i in range(1, n - l + 1):
            j = i + l - 1
            m[i][j] = float('inf')
            for k in range(i, j):
                q = m[i][k] + m[k + 1][j] + dimensions[i - 1] * dimensions[k] * dimensions[j]
                if q < m[i][j]:
                    m[i][j] = q
                    s[i][j] = k

    return m[1][n - 1], s

def retrieve_order(split_points: List[List[int]], i: int, j: int) -> str:
    if i == j:
        return f"A{i-1}"
    else:
        k = split_points[i][j]
        left_order = retrieve_order(split_points, i, k)
        right_order = retrieve_order(split_points, k + 1, j)
        return f"({left_order}{right_order})"

