from itertools import combinations

def optimal_set_allocation(universe, subsets, costs):
    # Initialize the minimum cost and the corresponding covering sets
    min_cost = float('inf')
    best_combination = []

    # Check all possible combinations of the subsets
    for r in range(1, len(subsets) + 1):
        for combo in combinations(subsets.keys(), r):
            # Combine the elements and the costs of the current combination
            combined_elements = set.union(*[subsets[c] for c in combo])
            combined_cost = sum([costs[c] for c in combo])

            # If it covers the universe and is cheaper, update the best combination
            if combined_elements == universe and combined_cost < min_cost:
                min_cost = combined_cost
                best_combination = combo

    return list(best_combination)

