from typing import List

def advanced_binary_search(array: List[int], target: int) -> int:
    """
    Perform a binary search to find the exact index of a timestamp or the nearest timestamp.

    :param array: List[int] : List of sorted timestamps
    :param target: int : The timestamp you are searching for
    :return: int : The index of the exact timestamp or the nearest timestamp
    """
    if not array:
        return -1  # Return -1 if the array is empty

    left, right = 0, len(array) - 1
    best_index = -1
    best_diff = float('inf')

    while left <= right:
        mid = left + (right - left) // 2

        if array[mid] == target:
            return mid
        elif array[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

        # Check if the current middle element is closer to the target
        if abs(array[mid] - target) < best_diff:
            best_diff = abs(array[mid] - target)
            best_index = mid
        # If two distances to target are equal, choose the smaller value
        elif abs(array[mid] - target) == best_diff:
            if array[mid] < array[best_index]:
                best_index = mid

    return best_index

