def enhanced_pigeonhole_sort(arr):
    if not arr:
        return []

    min_val = min(arr)
    max_val = max(arr)
    size = max_val - min_val + 1

    holes = [0] * size

    for x in arr:
        holes[x - min_val] += 1

    sorted_arr = []
    for i in range(size):
        sorted_arr.extend([i + min_val] * holes[i])

    return sorted_arr

