from typing import List

def multiply(matA: List[List[int]], matB: List[List[int]]) -> List[List[int]]:
    n = len(matA)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] += matA[i][k] * matB[k][j]
    return result

def identity(n: int) -> List[List[int]]:
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1
    return result

def matrix_exponentiation(mat: List[List[int]], p: int) -> List[List[int]]:
    n = len(mat)
    result = identity(n)
    base = mat

    while p > 0:
        if p % 2 == 1:
            result = multiply(result, base)
        base = multiply(base, base)
        p //= 2

    return result

