from typing import List, Tuple

def is_prime(n: int) -> bool:
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def selection_sort_and_count_primes(arr: List[int]) -> Tuple[List[int], int]:
    """
    Sorts the list using Selection Sort and counts the prime numbers in the list.
    """
    n = len(arr)
    prime_count = 0

    for i in range(n):
        # Find the minimum element in remaining unsorted array
        min_idx = i
        for j in range(i+1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        # Swap the found minimum element with the first element
        arr[i], arr[min_idx] = arr[min_idx], arr[i]

        # Count prime if this is the final position assignment of the element
        if is_prime(arr[i]):
            prime_count += 1

    return (arr, prime_count)

