from typing import List

def find_combination_sum_topdown(nums: List[int], target: int) -> int:
    memo = {}

    def recurse(current_target):
        if current_target in memo:
            return memo[current_target]
        if current_target == 0:
            return 1
        if current_target < 0:
            return 0

        combination_count = 0
        for num in nums:
            combination_count += recurse(current_target - num)

        memo[current_target] = combination_count
        return combination_count

    return recurse(target)

def find_combination_sum_bottom_up(nums: List[int], target: int) -> int:
    dp = [0] * (target + 1)
    dp[0] = 1

    for i in range(1, target + 1):
        for num in nums:
            if i - num >= 0:
                dp[i] += dp[i - num]

    return dp[target]

from typing import List

def generate_parenthesis(n: int) -> List[str]:
    """
    Function to generate all combinations of well-formed parentheses.
    """
    def backtrack(s='', left=0, right=0):
        if len(s) == 2 * n:
            res.append(s)
            return
        if left < n:
            backtrack(s + '(', left + 1, right)
        if right < left:
            backtrack(s + ')', left, right + 1)

    res = []
    backtrack()
    return res

