def reverse_string(s: str) -> str:
    """
    Reverses the input string s without using built-in reversed() or slicing.
    """
    n = len(s)
    result = [''] * n  # allocation for the result string

    for i in range(n):
        result[i] = s[n - i - 1]

    return ''.join(result)

