def factorial_iter(n: int, mod: int = None) -> int:
    """
    Calculate the factorial of n iteratively. If mod is provided, return the result modulo mod.
    """
    result = 1
    for i in range(2, n+1):
        result *= i
        if mod:
            result %= mod
    return result

def factorial_recur(n: int, mod: int = None) -> int:
    """
    Calculate the factorial of n recursively. If mod is provided, return the result modulo mod.
    """
    if n == 0 or n == 1:
        return 1
    else:
        result = n * factorial_recur(n - 1, mod)
        if mod:
            result %= mod
        return result

