def binomial_coefficient(n: int, k: int, memo=None) -> int:
    """
    Calculate the binomial coefficient C(n, k) using memoization.

    Args:
    n (int): The total number of items.
    k (int): The number of items to choose.

    Returns:
    int: The binomial coefficient C(n, k).
    """
    if memo is None:
        memo = {}

    if (n, k) in memo:
        return memo[(n, k)]

    if k == 0 or k == n:
        return 1

    if k > n:
        raise ValueError('Invalid inputs, ensure that n >= k')

    if k > n // 2:
        k = n - k

    result = binomial_coefficient(n - 1, k - 1, memo) + binomial_coefficient(n - 1, k, memo)
    memo[(n, k)] = result

    return result

