from typing import List, Optional, Tuple

def search_key_in_matrix(matrix: List[List[int]], key: int) -> Optional[Tuple[int, int]]:
    if not matrix or not matrix[0]:
        return None

    rows = len(matrix)
    cols = len(matrix[0])

    # Start from the top-right corner
    row = 0
    col = cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == key:
            return (row, col)
        elif matrix[row][col] > key:
            col -= 1
        else:
            row += 1

    return None

from typing import List

def selection_sort(videos: List[int], simulation: bool=False) -> List[int]:
    n = len(videos)
    for i in range(n):
        min_index = i
        for j in range(i+1, n):
            if videos[j] < videos[min_index]:
                min_index = j
        videos[i], videos[min_index] = videos[min_index], videos[i]
        if simulation:
            print(f"iteration {i} : {' '.join(map(str, videos))}")
    return videos

