def is_reachable(graph, vertex_count, source, target):
    from collections import deque, defaultdict

    if source == target:
        return True

    adj_list = defaultdict(list)
    for u, v in graph:
        adj_list[u].append(v)

    visited = [False] * vertex_count
    queue = deque([source])

    while queue:
        current = queue.popleft()
        if current == target:
            return True
        if not visited[current]:
            visited[current] = True
            for neighbor in adj_list[current]:
                if not visited[neighbor]:
                    queue.append(neighbor)

    return False

def find_pattern(pattern: str, text: str) -> int:
    if not pattern or not text or len(pattern) > len(text):
        return -1

    base = 256  # The number of characters in the input alphabet (a-z).
    prime = 101  # A prime number to mod the hash values.

    def get_hash(s: str, end: int) -> int:
        """
        Calculate hash value for the string `s` up to `end` (exclusive).
        """
        h = 0
        for i in range(end):
            h = (h * base + ord(s[i])) % prime
        return h

    n, m = len(text), len(pattern)
    pattern_hash = get_hash(pattern, m)
    text_hash = get_hash(text, m)
    highest_base = pow(base, m-1, prime)  # highest_base = base^(m-1) % prime

    for i in range(n - m + 1):
        if pattern_hash == text_hash:
            # Double check to avoid hash collision
            if text[i:i+m] == pattern:
                return i

        if i < n - m:
            # Calculate hash for the next substring
            text_hash = (text_hash - ord(text[i]) * highest_base) % prime
            text_hash = (text_hash * base + ord(text[i + m])) % prime
            # We might get negative value of t, converting it to positive
            if text_hash < 0:
                text_hash += prime

    return -1

