from typing import List

def letter_combinations(digits: str) -> List[str]:
    if not digits:
        return []

    # Mapping of digits to corresponding letters on telephone buttons.
    digit_to_char = {
        '2': 'abc', '3': 'def',
        '4': 'ghi', '5': 'jkl', '6': 'mno',
        '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    }

    def backtrack(index: int, path: str):
        # If the path length is the same as digits, we have a complete combination
        if index == len(digits):
            combinations.append(path)
            return

        # Get the letters corresponding to the current digit
        possible_letters = digit_to_char[digits[index]]
        for letter in possible_letters:
            backtrack(index + 1, path + letter)

    combinations = []
    backtrack(0, "")
    return combinations

