from typing import List, Set

def find_words(board: List[List[str]], words: List[str]) -> List[str]:
    def backtrack(i, j, node, prefix):
        char = board[i][j]
        curr_node = node[char]
        word_match = curr_node.pop('#', False)

        if word_match:
            found_words.add(prefix + char)

        board[i][j] = '#'
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < len(board) and 0 <= nj < len(board[0]) and board[ni][nj] in curr_node:
                backtrack(ni, nj, curr_node, prefix + char)
        board[i][j] = char

        if not curr_node:
            node.pop(char)

    def build_trie(words):
        root = {}
        for word in words:
            node = root
            for char in word:
                node = node.setdefault(char, {})
            node['#'] = word
        return root

    found_words = set()
    trie = build_trie(words)

    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] in trie:
                backtrack(i, j, trie, "")

    return list(found_words)

def simplify_path(path: str) -> str:
    """
    Simplifies a given Unix-style absolute path.
    """
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return '/' + '/'.join(stack)

