from typing import List

def filter_words_by_keyboard_row(words: List[str]) -> List[str]:
    row1 = set("qwertyuiop")
    row2 = set("asdfghjkl")
    row3 = set("zxcvbnm")

    def can_be_typed_on_one_row(word):
        lower_word = set(word.lower())
        return (lower_word <= row1) or (lower_word <= row2) or (lower_word <= row3)

    result = [word for word in words if can_be_typed_on_one_row(word)]
    return result

def int_divide(n):
    """
    Returns the number of ways n can be partitioned into sums of positive integers.
    """
    # Initialize a 2D array to hold the number of partitions for each combination
    dp = [[0 for _ in range(n + 1)] for _ in range(n + 1)]

    # There is exactly one way to partition 0 (using no parts)
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the table using dynamic programming approach
    for num in range(1, n + 1):
        for sum_val in range(1, n + 1):
            if sum_val >= num:
                dp[num][sum_val] = dp[num - 1][sum_val] + dp[num][sum_val - num]
            else:
                dp[num][sum_val] = dp[num - 1][sum_val]

    return dp[n][n]

