def distinct_ways_to_move(carriages: int) -> int:
    """
    Returns the number of distinct ways to move to the last carriage.
    """
    if carriages == 1:
        return 1
    elif carriages == 2:
        return 2

    prev2, prev1 = 1, 2

    for _ in range(3, carriages + 1):
        curr = prev1 + prev2
        prev2, prev1 = prev1, curr

    return prev1

