def exchange_sort(arr):
    """
    Sort the list of integers `arr` using the Exchange Sort algorithm.

    :param List[int] arr: The list of integers to sort.
    :return: The sorted list.
    :rtype: List[int]
    """
    n = len(arr)
    for i in range(n - 1):
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
    return arr

