def is_match(s: str, p: str) -> bool:
    """
    Returns True if the string `s` matches the pattern `p`.
    """

    # Create a DP table with dimensions (len(s)+1) x (len(p)+1)
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Empty string and empty pattern match
    dp[0][0] = True

    # Handle patterns with '*' that can match zero previous characters
    for j in range(2, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the DP table
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2]
                if p[j - 2] == '.' or p[j - 2] == s[i - 1]:
                    dp[i][j] = dp[i][j] or dp[i - 1][j]

    return dp[-1][-1]

from typing import List

def is_strongly_connected_graph(V: int, edges: List[List[int]]) -> bool:
    # Helper function to perform DFS
    def dfs(graph, start, visited):
        stack = [start]
        while stack:
            node = stack.pop()
            if not visited[node]:
                visited[node] = True
                for neighbor in graph[node]:
                    if not visited[neighbor]:
                        stack.append(neighbor)

    # Build the graph and the reverse graph
    graph = [[] for _ in range(V)]
    reverse_graph = [[] for _ in range(V)]
    for u, v in edges:
        graph[u].append(v)
        reverse_graph[v].append(u)

    # Check if all nodes are reachable from node 0 in the original graph
    visited = [False] * V
    dfs(graph, 0, visited)
    if not all(visited):
        return False

    # Check if all nodes are reachable from node 0 in the reversed graph
    visited = [False] * V
    dfs(reverse_graph, 0, visited)
    if not all(visited):
        return False

    return True

def find_in_priority_queue(priority_queue, query):
    """
    Returns the index of the first occurrence of the query element in the max-heap priority queue.
    """
    def find_in_heap(index):
        if index >= len(priority_queue):
            return -1
        if priority_queue[index] == query:
            return index

        # Given the max-heap property, if the current element is smaller than the query,
        # there's no use to look further since no child can be larger than the current element.
        if priority_queue[index] < query:
            return -1

        # Recursively check the left and right children
        left_child_index = 2 * index + 1
        right_child_index = 2 * index + 2

        left_result = find_in_heap(left_child_index)
        if left_result != -1:
            return left_result

        return find_in_heap(right_child_index)

    return find_in_heap(0)

