def next_bigger(num: int) -> int:
    """
    Returns the next higher permutation of the digits of the given number.
    If no such permutation exists, returns -1.
    """
    digits = list(map(int, str(num)))

    # Step 1: Find the pivot, the point (from right) where digits decrease
    for i in range(len(digits) - 2, -1, -1):
        if digits[i] < digits[i + 1]:
            break
    else:
        return -1  # If no pivot, it's the last permutation

    # Step 2: Find the smallest digit on right side of pivot which is larger than digits[i]
    for j in range(len(digits) - 1, i, -1):
        if digits[j] > digits[i]:
            break

    # Step 3: Swap the found digit with pivot
    digits[i], digits[j] = digits[j], digits[i]

    # Step 4: Reverse the digits after the pivot point
    digits = digits[:i+1] + digits[i+1:][::-1]

    # Convert back to number
    return int(''.join(map(str, digits)))

