def combination_dp(n, r):
    if r > n or r < 0:
        return 0
    if r == 0 or r == n:
        return 1

    # Reduce r to be the smaller of r and n-r for efficiency
    r = min(r, n - r)

    # Initialize a 1D DP array
    dp = [0] * (r + 1)
    dp[0] = 1  # nC0 is always 1

    # Iterate over the range of n
    for i in range(1, n + 1):
        # Traverse backwards to avoid overwriting values needed for calculations
        for j in range(min(i, r), 0, -1):
            dp[j] += dp[j - 1]

    return dp[r]

