from typing import List

def transform_matrix(matrix: List[List[int]], transformation: str) -> List[List[int]]:
    n = len(matrix)

    if transformation == 'rotate_clockwise':
        return [[matrix[n - j - 1][i] for j in range(n)] for i in range(n)]

    elif transformation == 'rotate_counterclockwise':
        return [[matrix[j][n - i - 1] for j in range(n)] for i in range(n)]

    elif transformation == 'invert_top_left':
        return matrix  # No change needed

    elif transformation == 'invert_bottom_left':
        return [row[::-1] for row in matrix[::-1]]

    else:
        raise ValueError("Invalid transformation type")

