def count_sentences(input_string, word_dict):
    """
    Counts the number of different ways the input_string can be segmented
    into words contained in word_dict.
    """
    n = len(input_string)
    dp = [0] * (n + 1)
    dp[0] = 1  # Base case: one way to segment an empty string

    for i in range(1, n + 1):
        for j in range(i):
            if input_string[j:i] in word_dict:
                dp[i] += dp[j]

    return dp[n]

