from typing import List

def multiply_matrices(A: List[List[int]], B: List[List[int]]) -> List[List[int]]:
    n = len(A)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                result[i][j] += A[i][k] * B[k][j]
    return result

def identity_matrix(size: int) -> List[List[int]]:
    I = [[0] * size for _ in range(size)]
    for i in range(size):
        I[i][i] = 1
    return I

def power_matrix(mat: List[List[int]], exp: int) -> List[List[int]]:
    n = len(mat)
    result = identity_matrix(n)
    base = mat

    while exp > 0:
        if exp % 2 == 1:
            result = multiply_matrices(result, base)
        base = multiply_matrices(base, base)
        exp //= 2

    return result

from typing import List

def binary_insertion_sort(arr: List[int]) -> List[int]:
    def search_insert(subarr: List[int], val: int) -> int:
        """
        Use binary search to find the index to insert val in subarr.
        """
        low, high = 0, len(subarr) - 1
        while low <= high:
            mid = (low + high) // 2
            if subarr[mid] < val:
                low = mid + 1
            else:
                high = mid - 1
        return low

    for i in range(1, len(arr)):
        val = arr[i]
        j = search_insert(arr[:i], val)
        arr = arr[:j] + [val] + arr[j:i] + arr[i+1:]

    return arr

