from typing import List

def is_bipartite_graph(adj_list: List[List[int]]) -> bool:
    """
    Determines whether the given undirected graph is bipartite.

    Parameters:
    adj_list (List[List[int]]): Adjacency matrix of the graph.

    Returns:
    bool: True if the graph is bipartite, False otherwise.
    """
    V = len(adj_list)
    colors = [-1] * V  # -1 means uncolored

    def bfs(start: int) -> bool:
        queue = [start]
        colors[start] = 0  # Start coloring with 0

        while queue:
            u = queue.pop(0)
            for v in range(V):
                if adj_list[u][v] == 1:  # There's an edge between u and v
                    if colors[v] == -1:
                        colors[v] = 1 - colors[u]  # Assign alternate color
                        queue.append(v)
                    elif colors[v] == colors[u]:
                        return False  # Same color adjacent nodes detected

        return True

    for i in range(V):
        if colors[i] == -1:
            if not bfs(i):
                return False

    return True

def find_difference(s: str, t: str) -> str:
    xor_result = 0

    # XOR all characters in s
    for char in s:
        xor_result ^= ord(char)

    # XOR all characters in t
    for char in t:
        xor_result ^= ord(char)

    # The remaining result is the ASCII value of the different character
    return chr(xor_result)

