def find_special_numbers(low, high):
    """
    Finds the special numbers between low and high (inclusive) where
    the sum of the digits raised to consecutive powers equals the number itself.
    """
    def is_special_number(n):
        return n == sum(int(digit) ** (i + 1) for i, digit in enumerate(str(n)))

    return [n for n in range(low, high + 1) if is_special_number(n)]

