def optimized_comb_sort(arr: list, order: str='asc') -> list:
    """
    Enhanced Comb Sort with order parameter to sort in ascending ('asc') or descending ('desc') order.
    """
    def get_next_gap(gap):
        # Shrink gap by the shrink factor which is found from empirical studies to be 1.3 for best performance
        gap = (gap * 10) // 13
        return max(1, gap)

    if order not in ['asc', 'desc']:
        # Default to ascending if the order argument is invalid
        order = 'asc'

    n = len(arr)
    gap = n
    swapped = True

    while gap != 1 or swapped:
        gap = get_next_gap(gap)
        swapped = False

        for i in range(n - gap):
            if (order == 'asc' and arr[i] > arr[i + gap]) or (order == 'desc' and arr[i] < arr[i + gap]):
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

