def change_bit(num, bit, pos, length):
    """
    Modifies the bits of a number by either inserting or toggling.

    Parameters:
    - num (int): A given number
    - bit (int): The bit or bits to be inserted
    - pos (int): Position where the bits/bit should be modified.
    - length (int): Length of bits to be modified.

    Returns:
    - int: The modified number
    """
    if length == 1:
        # Insert a single bit
        if bit == 1:
            # Set the bit at position pos
            return num | (1 << pos)
        else:
            # Clear the bit at position pos
            return num & ~(1 << pos)
    elif length > 1:
        # Insert multiple bits
        # Clear the positions before setting them
        mask = ((1 << length) - 1) << pos
        num = num & ~mask
        num = num | (bit << pos)
        return num
    else:
        # Assuming length of 0 means toggle bits
        return num ^ (1 << pos)

    return num

