from typing import List, Tuple

def get_maximum_value(items: List[Tuple[int, int]], capacity: int) -> int:
    n = len(items)

    # Create a 2D dp array with (n+1) rows and (capacity+1) columns
    dp = [[0] * (capacity + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        value, weight = items[i-1]
        for w in range(capacity + 1):
            if weight <= w:
                dp[i][w] = max(dp[i-1][w], dp[i-1][w-weight] + value)
            else:
                dp[i][w] = dp[i-1][w]

    return dp[n][capacity]

from typing import List

def circular_binary_search(array: List[int], target: int) -> int:
    left, right = 0, array.__len__() - 1

    while left <= right:
        mid = (left + right) // 2

        if array[mid] == target:
            return mid

        if array[left] <= array[mid]:  # Left half is sorted
            if array[left] <= target < array[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:  # Right half is sorted
            if array[mid] < target <= array[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

