def combination_dp(n: int, r: int) -> int:
    if r > n:
        return 0
    if r == 0 or n == r:
        return 1

    # Initialize a table to store results
    dp = [0] * (r + 1)
    dp[0] = 1

    # Fill the dp array using bottom-up approach
    for i in range(1, n + 1):
        for j in range(min(i, r), 0, -1):
            dp[j] = dp[j] + dp[j - 1]

    return dp[r]

def atbash_transform(s):
    def transform_char(c):
        if 'A' <= c <= 'Z':
            return chr(ord('Z') - (ord(c) - ord('A')))
        elif 'a' <= c <= 'z':
            return chr(ord('z') - (ord(c) - ord('a')))
        else:
            return c

    return ''.join(transform_char(c) for c in s)

