def bucket_sort(arr):
    if not arr:
        return arr

    num_buckets = len(arr)
    max_value = max(arr)
    buckets = [[] for _ in range(num_buckets)]

    for value in arr:
        index = value * num_buckets // (max_value + 1)
        buckets[index].append(value)

    sorted_list = []
    for i in range(num_buckets):
        sorted_list.extend(optimized_sort(buckets[i]))

    return sorted_list

