def get_factors(n: int):
    def backtrack(start, target, path, res):
        if target == 1 and len(path) > 1:
            res.append(path[:])
            return

        for i in range(start, target+1):
            if target % i == 0:
                path.append(i)
                backtrack(i, target // i, path, res)
                path.pop()

    result = []
    backtrack(2, n, [], result)
    return result

