def encrypt_atbash(message: str) -> str:
    """
    Encodes the input message using the Atbash cipher.

    Parameters:
    message (str): The input message to be encoded.

    Returns:
    str: The encoded message.
    """
    def atbash_char(c):
        if 'a' <= c <= 'z':
            return chr(219 - ord(c))
        elif 'A' <= c <= 'Z':
            return chr(155 - ord(c))
        return c

    return ''.join(atbash_char(c) for c in message)

