import heapq
from typing import List

def get_skyline(buildings: List[List[int]]) -> List[List[int]]:
    if not buildings:
        return []

    # Events are the critical points
    events = []
    for L, R, H in buildings:
        events.append((L, -H, R))  # Start point
        events.append((R, 0, 0))   # End point
    # Sort events, prioritizing by x, then height descending, then R ascending
    events.sort()

    # Result list and an active invisible heap (height, end)
    result = [[0, 0]]
    live_heap = [(0, float('inf'))]

    for x, h_neg, R in events:
        while live_heap[0][1] <= x:
            heapq.heappop(live_heap)
        if h_neg != 0:
            heapq.heappush(live_heap, (h_neg, R))
        if result[-1][1] != -live_heap[0][0]:
            result.append([x, -live_heap[0][0]])

    return result[1:]

