import math

def enhanced_gcd(a: int, b: int) -> int:
    """
    Calculate the greatest common divisor (GCD) of two non-negative integers a and b.
    """
    if a == 0:
        return b
    if b == 0:
        return a
    return math.gcd(a, b)

def enhanced_lcm(a: int, b: int) -> int:
    """
    Calculate the least common multiple (LCM) of two non-negative integers a and b.
    Using the property LCM(a, b) * GCD(a, b) = a * b
    """
    if a == 0 or b == 0:
        return 0
    gcd = enhanced_gcd(a, b)
    return abs(a * b) // gcd

from typing import List, Tuple

def matrix_chain_order(array: List[int]) -> Tuple[List[List[int]], List[List[int]]]:
    n = len(array)
    # m[i][j] is the minimum number of scalar multiplications needed to compute the matrix A[i]A[i+1]...A[j] = A[i..j]
    m = [[0 for _ in range(n)] for _ in range(n)]
    # s[i][j] is the index that achieved the optimal cost in m[i][j]
    s = [[0 for _ in range(n)] for _ in range(n)]

    # l is chain length.
    for l in range(2, n):  # length from 2 to n-1
        for i in range(1, n-l+1):
            j = i+l-1
            m[i][j] = float('inf')
            for k in range(i, j):
                q = m[i][k] + m[k+1][j] + array[i-1]*array[k]*array[j]
                if q < m[i][j]:
                    m[i][j] = q
                    s[i][j] = k

    return m, s

def print_optimal_solution(s: List[List[int]], i: int, j: int) -> str:
    if i == j:
        return f"A{i}"
    else:
        return f"({print_optimal_solution(s, i, s[i][j])} x {print_optimal_solution(s, s[i][j]+1, j)})"

from itertools import combinations

def n_sum(n, nums, target, sum_closure=None, compare_closure=None, same_closure=None):
    if sum_closure is None:
        sum_closure = lambda a, b: a + b
    if compare_closure is None:
        compare_closure = lambda sum_value, target: (sum_value > target) - (sum_value < target)
    if same_closure is None:
        same_closure = lambda a, b: a == b

    nums.sort()
    result = []

    def find_n_sum(start, n, target, path):
        if n == 2:  # two-pointer splitting
            left, right = start, len(nums) - 1
            while left < right:
                current_sum = sum_closure(nums[left], nums[right])
                comparison_result = compare_closure(current_sum, target)
                if comparison_result == 0:
                    result.append(path + [nums[left], nums[right]])
                    left_temp, right_temp = nums[left], nums[right]
                    while left < right and same_closure(nums[left], left_temp):
                        left += 1
                    while left < right and same_closure(nums[right], right_temp):
                        right -= 1
                elif comparison_result < 0:
                    left += 1
                else:
                    right -= 1
        else:  # n > 2.
            for i in range(start, len(nums) - n + 1):
                if i > start and same_closure(nums[i], nums[i - 1]):
                    continue
                if sum_closure(nums[i], nums[i]) * n > target:
                    break
                if sum_closure(nums[i], nums[-1]) * n < target:
                    continue
                find_n_sum(i + 1, n - 1, sum_closure(target, -nums[i]), path + [nums[i]])

    find_n_sum(0, n, target, [])
    return result

