def remove_reoccurring_characters(s: str) -> str:
    """
    Removes reoccurring characters while preserving the order of their first appearance.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            result.append(char)
            seen.add(char)
    return ''.join(result)

