def optimized_power(a: int, n: int, mod: int = None) -> int:
    """
    Computes a^n % mod using iterative binary exponentiation.

    Parameters:
    a (int): The base integer.
    n (int): The exponent, a non-negative integer.
    mod (Optional[int]): The modulus.

    Returns:
    int: The result of a^n (or (a^n) % mod if mod is provided).
    """

    def iterative_exponentiation(base, exp, modulus):
        result = 1
        base = base % modulus if modulus else base

        while exp > 0:
            if exp % 2 == 1:
                result = (result * base) % modulus if modulus else result * base
            exp = exp // 2
            base = (base * base) % modulus if modulus else base * base

        return result

    if mod:
        return iterative_exponentiation(a, n, mod)
    else:
        return iterative_exponentiation(a, n, None)

def roman_to_int(s: str) -> int:
    if not s:
        return -1

    # Map of Roman numeral characters to integer values
    roman_map = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    # Valid subtraction patterns
    valid_subtractions = {
        'IV', 'IX', 'XL', 'XC', 'CD', 'CM'
    }

    # Check for invalid patterns
    i = 0
    while i < len(s):
        if i < len(s) - 1:
            pair = s[i] + s[i + 1]
            if s[i] not in roman_map or s[i+1] not in roman_map:
                return -1
            if pair not in valid_subtractions and roman_map[s[i]] < roman_map[s[i+1]]:
                return -1
        elif s[i] not in roman_map:
            return -1
        i += 1

    # Calculating the integer value of the Roman numeral
    total = 0
    prev_value = 0

    for char in reversed(s):
        value = roman_map[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value

    return total

from heapq import heappush, heappop
from collections import defaultdict

def get_skyline(buildings):
    events = []
    for L, R, H in buildings:
        events.append((L, -H, R))
        events.append((R, 0, 0))
    events.sort()

    res = [[0, 0]]
    pq = [(0, float('inf'))]

    for x, negH, R in events:
        while pq[0][1] <= x:
            heappop(pq)
        if negH != 0:
            heappush(pq, (negH, R))
        maxH = -pq[0][0]
        if res[-1][1] != maxH:
            res.append([x, maxH])

    return res[1:]

