def interpolation_search(arr, target):
    """
    Returns the index of the target in the sorted array arr using interpolation search.
    Returns -1 if the target is not found.
    """
    low = 0
    high = len(arr) - 1

    while low <= high and target >= arr[low] and target <= arr[high]:
        if low == high:
            if arr[low] == target:
                return low
            return -1

        pos = low + ((high - low) // (arr[high] - arr[low]) * (target - arr[low]))

        if arr[pos] == target:
            return pos

        if arr[pos] < target:
            low = pos + 1
        else:
            high = pos - 1

    return -1

from collections import deque
from typing import List

def dinic(capacity: List[List[int]], source: int, sink: int) -> int:
    n = len(capacity)
    flow = [[0] * n for _ in range(n)]
    level = [-1] * n
    queue = deque()

    def bfs():
        nonlocal level, queue
        level = [-1] * n
        level[source] = 0
        queue.clear()
        queue.append(source)

        while queue:
            u = queue.popleft()
            for v in range(n):
                if level[v] < 0 and flow[u][v] < capacity[u][v]:
                    level[v] = level[u] + 1
                    queue.append(v)
        return level[sink] >= 0

    def dfs(u, f):
        if u == sink:
            return f
        total_flow = 0
        for v in range(n):
            if level[v] == level[u] + 1 and flow[u][v] < capacity[u][v]:
                current_flow = min(f, capacity[u][v] - flow[u][v])
                temp_flow = dfs(v, current_flow)
                if temp_flow > 0:
                    flow[u][v] += temp_flow
                    flow[v][u] -= temp_flow
                    total_flow += temp_flow
                    f -= temp_flow
                    if f == 0:
                        break
        return total_flow

    max_flow = 0
    while bfs():
        max_flow += dfs(source, float('Inf'))

    return max_flow

