def first_occurrence(array, query):
    low, high = 0, len(array) - 1
    result = -1

    while low <= high:
        mid = low + (high - low) // 2
        if array[mid] == query:
            result = mid
            high = mid - 1  # look on the left side for the first occurrence
        elif array[mid] < query:
            low = mid + 1
        else:
            high = mid - 1

    return result

