from typing import List, Tuple, Optional

def one_sparse(array: List[Tuple[int, str]]) -> Optional[int]:
    # Dictionary to count occurrences of each number
    counter = {}

    for number, sign in array:
        if sign == '+':
            if number in counter:
                counter[number] += 1
            else:
                counter[number] = 1
        elif sign == '-':
            if number in counter:
                counter[number] -= 1
                # Remove the number from counter if its count becomes zero
                if counter[number] == 0:
                    del counter[number]
            else:
                counter[number] = -1

    # Only return the number if there is exactly one number left with a non-zero count
    if len(counter) == 1:
        for key in counter:
            if counter[key] != 0:
                return key
    return None

