from typing import List

def find_permutations(nums: List[int]) -> List[List[int]]:
    if len(nums) == 0:
        return [[]]
    elif len(nums) == 1:
        return [nums]

    result = []
    for i in range(len(nums)):
        num = nums[i]
        rem_nums = nums[:i] + nums[i+1:]
        for perm in find_permutations(rem_nums):
            result.append([num] + perm)

    return result

def optimized_combination(n: int, r: int) -> int:
    """
    Computes the combination C(n, r) efficiently using memoization.
    """
    memo = {}

    def combination(n, r):
        if r == 0 or r == n:
            return 1
        if (n, r) in memo:
            return memo[(n, r)]
        memo[(n, r)] = combination(n - 1, r - 1) + combination(n - 1, r)
        return memo[(n, r)]

    return combination(n, r)

def is_anagram(s: str, t: str) -> bool:
    """
    Determines if `t` is an anagram of `s`.
    """
    if len(s) != len(t):
        return False

    char_count = [0] * 26  # There are 26 lowercase English letters

    for char in s:
        char_count[ord(char) - ord('a')] += 1

    for char in t:
        char_count[ord(char) - ord('a')] -= 1
        if char_count[ord(char) - ord('a')] < 0:
            return False

    return True

from typing import List, Tuple

def improved_selection_sort(arr: List[int], simulation: bool = False) -> Tuple[List[int], int]:
    n = len(arr)
    swap_count = 0

    for i in range(n - 1):
        min_index = i
        sorted_flag = True

        for j in range(i + 1, n):
            if arr[j] < arr[min_index]:
                min_index = j
                sorted_flag = False

        if sorted_flag:
            break

        if min_index != i:
            arr[i], arr[min_index] = arr[min_index], arr[i]
            swap_count += 1

        if simulation:
            print(f'Iteration {i} : {arr}')

    return arr, swap_count

