def friends_log(events):
    parent = {}
    rank = {}

    def find(u):
        if u != parent[u]:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)

        if root_u != root_v:
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            elif rank[root_u] < rank[root_v]:
                parent[root_u] = root_v
            else:
                parent[root_v] = root_u
                rank[root_u] += 1

    results = []

    for event in events:
        action, user1, user2 = event
        if user1 not in parent:
            parent[user1] = user1
            rank[user1] = 0
        if user2 not in parent:
            parent[user2] = user2
            rank[user2] = 0

        if action == "friend":
            union(user1, user2)
        elif action == "check":
            results.append(find(user1) == find(user2))

    return results

