from typing import List

def annotate_words(words: List[str], symbols: List[str]) -> List[str]:
    def find_longest_match(word, symbols):
        longest_match = ""
        for symbol in symbols:
            if symbol in word and len(symbol) > len(longest_match):
                longest_match = symbol
            elif symbol in word and len(symbol) == len(longest_match):
                if word.index(symbol) < word.index(longest_match):
                    longest_match = symbol
        return longest_match

    annotated_words = []
    for word in words:
        longest_match = find_longest_match(word, symbols)
        if longest_match:
            word = word.replace(longest_match, f'[{longest_match}]', 1)
        annotated_words.append(word)

    return annotated_words

from typing import List

def permute_with_constraints(elements: List[int], k: int) -> List[List[int]]:
    def backtrack(path, remaining):
        if not remaining:
            permutations.append(path)
            return
        for i in range(len(remaining)):
            backtrack(path + [remaining[i]], remaining[:i] + remaining[i+1:])

    if k in elements:
        elements.remove(k)
        permutations = []
        backtrack([k], elements)
    else:
        permutations = []
        backtrack([], elements)

    return permutations

def is_reachable(vertex_count: int, edges: list, source: int, target: int) -> bool:
    from collections import defaultdict

    # Build the adjacency list for the graph
    graph = defaultdict(list)
    for src, dst in edges:
        graph[src].append(dst)

    # Helper function for DFS traversal
    def dfs(v, visited):
        if v == target:
            return True
        visited.add(v)
        for neighbor in graph[v]:
            if neighbor not in visited:
                if dfs(neighbor, visited):
                    return True
        return False

    # Start DFS from the source node
    return dfs(source, set())

