def single_source_shortest_path(graph: dict, source: str) -> bool:
    """
    Determines whether a single-source shortest path from the specified source to all other vertices exists.
    Returns False if there is any reachable negative weight cycle, otherwise True.
    """
    import math

    # Step 1: Initialize distances and predecessors
    dist = {node: math.inf for node in graph}
    dist[source] = 0

    # Step 2: Relax edges repeatedly
    for _ in range(len(graph) - 1):
        for u in graph:
            for v, weight in graph[u].items():
                if dist[u] + weight < dist[v]:
                    dist[v] = dist[u] + weight

    # Step 3: Check for negative weight cycles
    for u in graph:
        for v, weight in graph[u].items():
            if dist[u] + weight < dist[v]:
                return False  # Negative weight cycle found

    return True

