def efficient_stoogesort(arr, l, h):
    """
    Performs an efficient variant of the Stooge Sort on the given array segment.
    """
    if l >= h:
        return

    if arr[l] > arr[h]:
        arr[l], arr[h] = arr[h], arr[l]

    if h - l + 1 > 2:
        t = (h - l + 1) // 3
        efficient_stoogesort(arr, l, h - t)
        efficient_stoogesort(arr, l + t, h)
        efficient_stoogesort(arr, l, h - t)

