def square_root(n, epsilon):
    """
    Approximates the square root of a positive number n using Newton's method,
    with an error margin of epsilon.
    """
    if n < 0:
        raise ValueError("Cannot compute square root of a negative number.")
    if n == 0 or n == 1:
        return n  # The square root of 0 and 1 are trivial

    guess = n / 2.0

    while abs(guess * guess - n) > epsilon:
        guess = (guess + (n / guess)) / 2.0

    return guess

