from typing import List

def generate_permutations(lst: List[int]) -> List[List[int]]:
    if len(lst) == 0:
        return [[]]
    if len(lst) == 1:
        return [lst]

    permutations = []
    for i in range(len(lst)):
        rest = lst[:i] + lst[i+1:]
        for p in generate_permutations(rest):
            permutations.append([lst[i]] + p)

    return permutations

import math

def enhanced_cosine_similarity(vec1: list, vec2: list) -> float:
    if len(vec1) != len(vec2):
        raise ValueError('Vectors must be of the same length')
    if not vec1 or not vec2:
        raise ValueError('Vectors must not be empty')

    dot_product = sum(x * y for x, y in zip(vec1, vec2))
    norm_vec1 = math.sqrt(sum(x ** 2 for x in vec1))
    norm_vec2 = math.sqrt(sum(x ** 2 for x in vec2))

    if norm_vec1 == 0.0 or norm_vec2 == 0.0:
        return 0.0

    return dot_product / (norm_vec1 * norm_vec2)

