def range_binary_search(array, val):
    """
    Enhanced binary search that finds the start and end indices of a specified value in a sorted array.

    :param array: List of integers, sorted in ascending order.
    :param val: Integer value to find the range for.
    :return: Tuple containing start and end indices of the specified range (start_index, end_index).
             If the value is not found, return (-1, -1).
    """

    def find_leftmost_index(array, val):
        left, right = 0, len(array) - 1
        leftmost_index = -1
        while left <= right:
            mid = left + (right - left) // 2
            if array[mid] < val:
                left = mid + 1
            elif array[mid] > val:
                right = mid - 1
            else:
                leftmost_index = mid
                right = mid - 1  # Move left to find the leftmost index
        return leftmost_index

    def find_rightmost_index(array, val):
        left, right = 0, len(array) - 1
        rightmost_index = -1
        while left <= right:
            mid = left + (right - left) // 2
            if array[mid] < val:
                left = mid + 1
            elif array[mid] > val:
                right = mid - 1
            else:
                rightmost_index = mid
                left = mid + 1  # Move right to find the rightmost index
        return rightmost_index

    start_index = find_leftmost_index(array, val)
    end_index = find_rightmost_index(array, val)

    if start_index == -1 or end_index == -1:
        return (-1, -1)

    return (start_index, end_index)

