from typing import List

def bitonic_merge(arr: List[int], low: int, cnt: int, direction: bool):
    if cnt > 1:
        k = cnt // 2
        for i in range(low, low + k):
            if (direction and arr[i] > arr[i + k]) or (not direction and arr[i] < arr[i + k]):
                arr[i], arr[i + k] = arr[i + k], arr[i]
        bitonic_merge(arr, low, k, direction)
        bitonic_merge(arr, low + k, k, direction)

def bitonic_sort_rec(arr: List[int], low: int, cnt: int, direction: bool):
    if cnt > 1:
        k = cnt // 2
        bitonic_sort_rec(arr, low, k, True)
        bitonic_sort_rec(arr, low + k, k, False)
        bitonic_merge(arr, low, cnt, direction)

def bitonic_sort(arr: List[int], reverse: bool = False) -> List[int]:
    bitonic_sort_rec(arr, 0, len(arr), not reverse)
    return arr

