def judge_circle(moves: str) -> bool:
    """
    Determines if the robot returns to the origin after executing the given moves.

    Parameters:
    - moves (str): A string representing the sequence of moves (each character 'R', 'L', 'U', 'D').

    Returns:
    - bool: True if the robot returns to the starting point (0, 0), False otherwise.
    """
    x, y = 0, 0  # Starting position at the origin (0, 0)

    for move in moves:
        if move == 'R':
            x += 1
        elif move == 'L':
            x -= 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    return x == 0 and y == 0

