from collections import deque
from typing import List

def shortest_distance(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return -1

    rows, cols = len(grid), len(grid[0])
    total_buildings = sum(val == 1 for row in grid for val in row)

    hit = [[0] * cols for _ in range(rows)]
    dist_sum = [[0] * cols for _ in range(rows)]

    def bfs(start_row, start_col):
        visited = [[False] * cols for _ in range(rows)]
        queue = deque([(start_row, start_col, 0)])
        dirs = [(1,0), (-1,0), (0,1), (0,-1)]
        buildings_reached = 0

        while queue:
            row, col, dist = queue.popleft()
            for dr, dc in dirs:
                r, c = row + dr, col + dc
                if 0 <= r < rows and 0 <= c < cols and not visited[r][c]:
                    visited[r][c] = True
                    if grid[r][c] == 0:
                        queue.append((r, c, dist + 1))
                        hit[r][c] += 1
                        dist_sum[r][c] += dist + 1
                    elif grid[r][c] == 1:
                        buildings_reached += 1

        return buildings_reached == total_buildings

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                if not bfs(r, c):
                    return -1

    result = float('inf')
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and hit[r][c] == total_buildings:
                result = min(result, dist_sum[r][c])

    return result if result != float('inf') else -1

def can_reach_all_dfs(graph, start):
    """
    Determines if all nodes in the graph are reachable from the start node using DFS.
    """
    def dfs(node, visited):
        visited.add(node)
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                dfs(neighbor, visited)

    visited = set()
    dfs(start, visited)

    return len(visited) == len(graph)

def can_reach_all_bfs(graph, start):
    """
    Determines if all nodes in the graph are reachable from the start node using BFS.
    """
    from collections import deque

    visited = set()
    queue = deque([start])

    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    queue.append(neighbor)

    return len(visited) == len(graph)

