def generate_abbreviations(word):
    def backtrack(result, word, pos, count, cur):
        if pos == len(word):
            if count > 0:
                cur += str(count)
            result.append(cur)
            return

        # Option 1: Add the current character to the abbreviation (and reset count)
        if count > 0:
            backtrack(result, word, pos+1, 0, cur + str(count) + word[pos])
        else:
            backtrack(result, word, pos+1, 0, cur + word[pos])

        # Option 2: Skip the current character (increment count)
        backtrack(result, word, pos+1, count+1, cur)

    result = []
    backtrack(result, word, 0, 0, "")
    return result

import random

def improved_is_prime(n: int, k: int) -> bool:
    """
    Returns True if n is probably prime, otherwise False.
    The test runs k iterations to reduce the probability of false positives.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as d*2^r
    d = n - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1

    # Test the base a to see whether it is a witness for the compositeness of n
    def is_composite(a):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return False
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                return False
        return True

    # Perform k trials of the test with randomly chosen bases
    for _ in range(k):
        a = random.randrange(2, n - 1)
        if is_composite(a):
            return False
    return True

def max_heap_sort(arr, simulation=False):
    def max_heapify(arr, n, i):
        largest = i  # Initialize largest as root
        left = 2 * i + 1  # left = 2*i + 1
        right = 2 * i + 2  # right = 2*i + 2

        # See if left child of root exists and is greater than root
        if left < n and arr[i] < arr[left]:
            largest = left

        # See if right child of root exists and is greater than root
        if right < n and arr[largest] < arr[right]:
            largest = right

        # Change root, if needed
        if largest != i:
            arr[i], arr[largest] = arr[largest], arr[i]  # swap

            # Heapify the root
            max_heapify(arr, n, largest)

    n = len(arr)

    # Build a maxheap.
    for i in range(n // 2 - 1, -1, -1):
        max_heapify(arr, n, i)
        if simulation:
            print(arr)

    # One by one extract elements
    for i in range(n - 1, 0, -1):
        arr[i], arr[0] = arr[0], arr[i]  # swap
        max_heapify(arr, i, 0)
        if simulation:
            print(arr)

    return arr

