def is_sorted(stack):
    """
    Returns True if the elements in the stack are sorted in ascending order
    from bottom to top, otherwise returns False.
    """
    # Edge cases: if the stack is empty or has only one element, it is sorted
    if len(stack) < 2:
        return True

    # Traverse the stack from bottom to top and check the order
    for i in range(1, len(stack)):
        if stack[i-1] > stack[i]:
            return False

    return True

