from typing import List

def num_islands(grid: List[List[int]]) -> int:
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0])
    num_of_islands = 0

    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] == 0:
            return
        grid[r][c] = 0  # Mark as visited
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                num_of_islands += 1
                dfs(r, c)

    return num_of_islands

def is_prime_optimized(n: int) -> bool:
    """
    Determine whether a given number `n` is prime using the Miller-Rabin primality test.

    Parameters:
    n (int): An integer to be checked for primality.

    Returns:
    bool: True if `n` is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    # Miller-Rabin test with a predetermined set of bases
    def miller_rabin_test(d, n):
        import random
        a = random.randint(2, n - 2)
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return True

        while d != n - 1:
            x = (x * x) % n
            d *= 2
            if x == 1:
                return False
            if x == n - 1:
                return True
        return False

    # Find d such that n-1 = d * 2^r
    d = n - 1
    while d % 2 == 0:
        d //= 2

    # Perform the Miller-Rabin test multiple times
    k = 5  # Number of iterations
    for _ in range(k):
        if not miller_rabin_test(d, n):
            return False
    return True

from typing import List, Tuple, Optional

def feature_flag_manager(flags: int, operations: List[Tuple[str, int, Optional[int]]]) -> Tuple[List[bool], int]:
    results = []

    def get_bit(value, bit_index):
        return (value >> bit_index) & 1

    def set_bit(value, bit_index):
        return value | (1 << bit_index)

    def clear_bit(value, bit_index):
        return value & ~(1 << bit_index)

    def update_bit(value, bit_index, bit_value):
        return (value & ~(1 << bit_index)) | (bit_value << bit_index)

    for operation in operations:
        op_type = operation[0]
        bit_index = operation[1]

        if op_type == "get":
            results.append(bool(get_bit(flags, bit_index)))
        elif op_type == "set":
            flags = set_bit(flags, bit_index)
        elif op_type == "clear":
            flags = clear_bit(flags, bit_index)
        elif op_type == "update":
            bit_value = operation[2]
            flags = update_bit(flags, bit_index, bit_value)

    return (results, flags)

def euler_totient(n):
    """
    Computes Euler's Totient function for a given integer n.
    """
    if n == 1:
        return 1

    result = n
    p = 2

    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1

    if n > 1:
        result -= result // n

    return result

