def first_occurrence(array, query):
    """
    Returns the index of the first occurrence of the query in the sorted array.
    If the query is not found, returns -1.
    """
    low, high = 0, len(array) - 1

    while low <= high:
        mid = (low + high) // 2
        if array[mid] == query:
            if mid == 0 or array[mid - 1] != query:
                return mid
            high = mid - 1
        elif array[mid] > query:
            high = mid - 1
        else:
            low = mid + 1

    return -1

