def find_difference(s: str, t: str) -> str:
    """
    Identifies and returns the additional letter in string `t`.
    """
    from collections import Counter

    s_counter = Counter(s)
    t_counter = Counter(t)

    for char in t_counter:
        if t_counter[char] != s_counter[char]:
            return char

