from typing import List, Dict

def detect_cycle(graph: Dict[str, List[str]]) -> bool:
    '''
    This function determines if there is a cycle in the given directed graph.

    Parameters:
    graph (Dict[str, List[str]]): A directed graph represented as a dictionary.

    Returns:
    bool: True if there is a cycle, False otherwise.
    '''

    def dfs(node, visited, stack):
        """
        A helper function that uses Depth-First Search to detect a cycle in the graph.
        """
        visited[node] = True
        stack[node] = True

        for neighbor in graph.get(node, []):
            if not visited[neighbor]:
                if dfs(neighbor, visited, stack):
                    return True
            elif stack[neighbor]:
                return True

        stack[node] = False
        return False

    visited = {key: False for key in graph}
    stack = {key: False for key in graph}

    for node in graph:
        if not visited[node]:
            if dfs(node, visited, stack):
                return True

    return False

