from typing import List

def search_in_rotated_array(arr: List[int], target: int) -> int:
    """
    Searches for a target value in a rotated sorted array and returns its index.
    If the target is not found, returns -1.

    :param arr: List[int] - Rotated sorted array
    :param target: int - Target value to search for
    :return: int - Index of target if found, otherwise -1
    """
    if not arr:
        return -1

    left, right = 0, len(arr) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if arr[mid] == target:
            return mid

        # Check if the left half is sorted
        if arr[left] <= arr[mid]:
            if arr[left] <= target < arr[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Right half must be sorted
        else:
            if arr[mid] < target <= arr[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

