from typing import List

def wiggle_sort(nums: List[int]) -> None:
    """
    Modify nums to follow the wiggle pattern in place.

    Args:
    nums (List[int]): The input list of integers to be reordered.

    Returns:
    None: This function should modify the list in place.
    """

    for i in range(len(nums) - 1):
        if i % 2 == 0:
            if nums[i] > nums[i + 1]:
                nums[i], nums[i + 1] = nums[i + 1], nums[i]
        else:
            if nums[i] < nums[i + 1]:
                nums[i], nums[i + 1] = nums[i + 1], nums[i]

def custom_limit(arr, min_lim=None, max_lim=None):
    if not arr:
        return []

    if min_lim is None:
        min_lim = min(arr)
    if max_lim is None:
        max_lim = max(arr)

    if min_lim > max_lim:
        return []

    return [x for x in arr if min_lim <= x <= max_lim]

