def find_word(pattern: str, text: str) -> int:
    """
    Implements the Rabin-Karp algorithm to find the first occurrence of a pattern in the given text.
    Returns the starting index of the first occurrence of the pattern in the text, or None if not found.
    """
    if not pattern or not text or len(pattern) > len(text):
        return None

    base = 256
    prime = 101
    pattern_len = len(pattern)
    text_len = len(text)

    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(pattern_len - 1):
        h = (h * base) % prime

    for i in range(pattern_len):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(text_len - pattern_len + 1):
        if pattern_hash == text_hash:
            if text[i:i + pattern_len] == pattern:
                return i

        if i < text_len - pattern_len:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + pattern_len])) % prime
            if text_hash < 0:
                text_hash += prime

    return None

