def delete_reoccurring_characters(string: str) -> str:
    """
    Remove reoccurring characters from the given string while maintaining the order
    of their first appearance.
    """
    seen = set()
    output = []

    for char in string:
        if char not in seen:
            seen.add(char)
            output.append(char)

    return ''.join(output)

