from typing import Dict, List, Set
from collections import deque

def dfs_traverse(graph: Dict[int, List[int]], start: int) -> Set[int]:
    visited = set()
    stack = [start]

    while stack:
        node = stack.pop()
        if node not in visited:
            visited.add(node)
            stack.extend(neighbor for neighbor in graph[node] if neighbor not in visited)

    return visited


def bfs_traverse(graph: Dict[int, List[int]], start: int) -> Set[int]:
    visited = set()
    queue = deque([start])

    while queue:
        node = queue.popleft()
        if node not in visited:
            visited.add(node)
            queue.extend(neighbor for neighbor in graph[node] if neighbor not in visited)

    return visited

