def is_prime(n):
    """
    Check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def sum_of_primes(numbers):
    """
    Given a list of integers, return the sum of all prime numbers in the list.

    :param numbers: List of integers
    :return: Sum of prime numbers
    """
    return sum(n for n in numbers if is_prime(n))

