def decode_string(s):
    def helper(index):
        decoded_string = ""
        while index < len(s) and s[index] != ']':
            if s[index].isdigit():
                k = 0
                while s[index].isdigit():
                    k = k * 10 + int(s[index])
                    index += 1
                index += 1  # skip '['
                encoded_string, index = helper(index)
                index += 1  # skip ']'
                decoded_string += encoded_string * k
            else:
                decoded_string += s[index]
                index += 1
        return decoded_string, index

    decoded_string, _ = helper(0)
    return decoded_string

