from typing import List, Tuple

def is_path_exist(vertex_count: int, edges: List[Tuple[int, int]], source: int, target: int) -> bool:
    if source == target:
        return True

    graph = {i: [] for i in range(vertex_count)}
    for u, v in edges:
        graph[u].append(v)

    def dfs(node, visited):
        if node == target:
            return True
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, visited):
                    return True
        return False

    return dfs(source, set())

def matrix_multiply(A, B):
    """
    Multiplies two matrices A and B
    """
    d = len(A)
    result = [[0] * d for _ in range(d)]
    for i in range(d):
        for j in range(d):
            for k in range(d):
                result[i][j] += A[i][k] * B[k][j]
    return result

def identity_matrix(d):
    """
    Returns an identity matrix of size d x d
    """
    I = [[0] * d for _ in range(d)]
    for i in range(d):
        I[i][i] = 1
    return I

def matrix_power(mat, n):
    """
    Computes the power of a matrix mat to the nth power using exponentiation by squaring
    """
    if n == 0:
        return identity_matrix(len(mat))
    if n == 1:
        return mat

    half_power = matrix_power(mat, n // 2)
    half_power_squared = matrix_multiply(half_power, half_power)

    if n % 2 == 0:
        return half_power_squared
    else:
        return matrix_multiply(half_power_squared, mat)

def has_cycle(graph):
    def dfs(node):
        if node in visited:
            return False
        if node in visiting:
            return True

        visiting.add(node)
        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True
        visiting.remove(node)
        visited.add(node)

        return False

    visiting = set()
    visited = set()

    for node in graph:
        if dfs(node):
            return True

    return False

