def is_balanced_parentheses(sequence: str) -> bool:
    """
    Returns True if the sequence of parentheses is balanced, False otherwise.
    """
    stack = []
    opening_brackets = {'(': ')', '{': '}', '[': ']'}

    for char in sequence:
        if char in opening_brackets:
            stack.append(char)
        else:
            if not stack:
                return False
            top = stack.pop()
            if opening_brackets[top] != char:
                return False

    return len(stack) == 0

