def letter_combinations(digits):
    """
    Given a string consisting of digits from 2 to 9, returns all possible letter combinations
    that the number could represent based on the classic phone keypad layout.
    """
    if not digits:
        return []

    # Mapping of digit to corresponding letters
    phone_map = {
        '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
        '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    }

    # Initial list with the empty string to facilitate the combination process
    combinations = ['']

    for digit in digits:
        letters = phone_map[digit]
        new_combinations = []
        for combination in combinations:
            for letter in letters:
                new_combinations.append(combination + letter)
        combinations = new_combinations

    return combinations

