def find_substring(haystack: str, needle: str) -> int:
    """
    Returns the index of the first occurrence of `needle` in `haystack`, or -1 if `needle` is not found.
    """
    len_h = len(haystack)
    len_n = len(needle)

    if len_n == 0:
        return 0

    for i in range(len_h - len_n + 1):
        if haystack[i:i + len_n] == needle:
            return i

    return -1

