from typing import List

def trimmed_mean(scores: List[float], trim_percent: float) -> float:
    if not scores:
        return 0.0

    n = len(scores)
    trim_count = int(n * (trim_percent / 100) / 2)

    if trim_count == 0:
        return round(sum(scores) / n, 2)

    trimmed_scores = sorted(scores)[trim_count:-trim_count]

    if not trimmed_scores:
        return 0.0

    return round(sum(trimmed_scores) / len(trimmed_scores), 2)

