def linear_search(array: list[int], query: int) -> int:
    """
    Perform a linear search to find the index of the query in the array.
    Return the index of the first occurrence of the query, or -1 if not found.
    """
    for index, value in enumerate(array):
        if value == query:
            return index
    return -1

