def deduplicate_string(input: str) -> str:
    """
    Function to remove duplicate characters, keeping only the first occurrence of each character.
    """
    seen = set()
    result = []

    for char in input:
        if char not in seen:
            seen.add(char)
            result.append(char)

    return ''.join(result)

