def has_cycle(graph: dict) -> bool:
    """
    Determine if the graph has a cycle.
    :param graph: dictionary representing the adjacency list of the graph
    :return: True if there's a cycle, False otherwise
    """
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {node: WHITE for node in graph}

    def dfs(node):
        if color[node] == GRAY:
            return True
        if color[node] == BLACK:
            return False

        color[node] = GRAY

        for neighbor in graph[node]:
            if dfs(neighbor):
                return True

        color[node] = BLACK
        return False

    for node in graph:
        if color[node] == WHITE:
            if dfs(node):
                return True

    return False

