def mixed_endian_to_bytes(num, order):
    """
    Convert an integer to a byte array where the byte order can be 'big' for big-endian or 'little' for little-endian.
    """
    if order == 'big':
        return num.to_bytes((num.bit_length() + 7) // 8, byteorder='big') or b'\x00'
    elif order == 'little':
        return num.to_bytes((num.bit_length() + 7) // 8, byteorder='little') or b'\x00'
    else:
        raise ValueError("Order must be either 'big' or 'little'")

def bytes_to_mixed_endian(bytestr, order):
    """
    Convert a byte array back to an integer given the byte order ('big' or 'little').
    """
    if order == 'big':
        return int.from_bytes(bytestr, byteorder='big')
    elif order == 'little':
        return int.from_bytes(bytestr, byteorder='little')
    else:
        raise ValueError("Order must be either 'big' or 'little'")

