from typing import List

def counting_sort_for_radix(arr: List[int], exp: int) -> None:
    n = len(arr)
    output = [0] * n
    count = [0] * 10

    for i in range(n):
        index = arr[i] // exp
        count[(index % 10)] += 1

    for i in range(1, 10):
        count[i] += count[i - 1]

    i = n - 1
    while i >= 0:
        index = arr[i] // exp
        output[count[(index % 10)] - 1] = arr[i]
        count[(index % 10)] -= 1
        i -= 1

    for i in range(n):
        arr[i] = output[i]

def radix_sort(arr: List[int]) -> None:
    max1 = max(arr)

    exp = 1
    while max1 // exp > 0:
        counting_sort_for_radix(arr, exp)
        exp *= 10

def enhanced_radix_sort(arr: List[int]) -> List[int]:
    if not arr:
        return arr

    positives = [num for num in arr if num >= 0]
    negatives = [-num for num in arr if num < 0]

    if positives:
        radix_sort(positives)
    if negatives:
        radix_sort(negatives)
        negatives = [-num for num in reversed(negatives)]

    return negatives + positives

