def improved_linear_search(array, query):
    """
    Find the index of the last occurrence of the given element in the array.
    If the element couldn't be found, returns -1.
    """
    last_index = -1
    for i in range(len(array)):
        if array[i] == query:
            last_index = i
    return last_index

def is_one_edit_away(s: str, t: str) -> bool:
    """
    Function to check if two strings are exactly one edit distance away.
    """
    m, n = len(s), len(t)
    if abs(m - n) > 1:
        return False

    if m > n:  # Ensure s is the shorter one
        return is_one_edit_away(t, s)

    i, j, edit = 0, 0, 0

    while i < m and j < n:
        if s[i] != t[j]:
            if edit == 1:
                return False
            edit += 1
            if m == n:
                i += 1
            # If not the same length move only in the longer string
        else:
            i += 1
        j += 1

    # If one char left in the longer string
    return edit == 1 or m != n

