from typing import List, Tuple

def matrix_search(matrix: List[List[int]], target: int) -> Tuple[int, int]:
    """
    This function searches for a target value in a given 2D matrix and returns
    the position as a tuple (row_index, col_index). If the target is not found,
    it returns (-1, -1).
    """
    for row_index, row in enumerate(matrix):
        for col_index, value in enumerate(row):
            if value == target:
                return (row_index, col_index)
    return (-1, -1)

def is_strobogrammatic(num: str) -> bool:
    """
    Checks if the given number string is strobogrammatic,
    meaning it looks the same when rotated 180 degrees.
    """
    strobogrammatic_pairs = {'0': '0', '1': '1', '8': '8', '6': '9', '9': '6'}
    left, right = 0, len(num) - 1

    while left <= right:
        if num[left] not in strobogrammatic_pairs or strobogrammatic_pairs[num[left]] != num[right]:
            return False
        left += 1
        right -= 1

    return True

from typing import List, Tuple

def transitive_closure(vertices: int, edges: List[Tuple[int, int]]) -> List[List[int]]:
    # Initialize closure matrix with 0s
    closure = [[0] * vertices for _ in range(vertices)]

    # Set self-loops
    for i in range(vertices):
        closure[i][i] = 1

    # Set direct edges
    for (i, j) in edges:
        closure[i][j] = 1

    # Compute transitive closure using Floyd Warshall algorithm
    for k in range(vertices):
        for i in range(vertices):
            for j in range(vertices):
                closure[i][j] = closure[i][j] or (closure[i][k] and closure[k][j])

    return closure

