from typing import List, Union, Tuple

def enhanced_interpolation_search(array: List[int], search_key: int) -> Union[int, Tuple[int, int]]:
    low = 0
    high = len(array) - 1

    while low <= high and search_key >= array[low] and search_key <= array[high]:
        if low == high:
            if array[low] == search_key:
                return low
            return -1

        pos = low + ((high - low) // (array[high] - array[low]) * (search_key - array[low]))

        if array[pos] == search_key:
            start = pos
            end = pos

            while start > low and array[start - 1] == search_key:
                start -= 1
            while end < high and array[end + 1] == search_key:
                end += 1

            if start == end:
                return start
            else:
                return (start, end)

        if array[pos] < search_key:
            low = pos + 1
        else:
            high = pos - 1

    return -1

