def generate_abbr(word: str) -> list:
    result = []

    def backtrack(pos, cur, count):
        if pos == len(word):
            if count > 0:
                cur += str(count)
            result.append(cur)
            return

        # Option 1: Skip the current character (increase count)
        backtrack(pos + 1, cur, count + 1)

        # Option 2: Add the current character
        if count > 0:
            cur += str(count)
        backtrack(pos + 1, cur + word[pos], 0)

    backtrack(0, "", 0)
    return result

