import random

def bogo_sort(arr: list) -> list:
    def is_sorted(arr):
        for i in range(len(arr) - 1):
            if arr[i] > arr[i + 1]:
                return False
        return True

    max_iterations = 10000
    iterations = 0

    while not is_sorted(arr):
        if iterations >= max_iterations:
            print("Max iterations reached, returning best effort sort.")
            arr.sort()
            return arr
        random.shuffle(arr)
        iterations += 1

    return arr

