from typing import List, Tuple
import heapq

def dijkstra(vertex_count: int, graph: List[List[Tuple[int, int]]], start: int) -> List[float]:
    distances = [float('inf')] * vertex_count
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_vertex = heapq.heappop(priority_queue)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in graph[current_vertex]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances

def all_pairs_shortest_path(vertex_count: int, edges: List[Tuple[int, int, int]]) -> List[List[float]]:
    # Graph representation: adjacency list
    graph = [[] for _ in range(vertex_count)]
    for u, v, w in edges:
        graph[u].append((v, w))

    shortest_paths = []
    for i in range(vertex_count):
        shortest_paths.append(dijkstra(vertex_count, graph, i))

    return shortest_paths

def binary_search_recursive(array, low, high, target):
    """
    :param array: List[int] - a list of integers sorted in ascending order
    :param low: int - the starting index of the subarray to search
    :param high: int - the ending index of the subarray to search
    :param target: int - the value to search for
    :return: int - the index of the target if found, otherwise -1
    """
    if low > high:
        return -1

    mid = (low + high) // 2

    if array[mid] == target:
        return mid
    elif array[mid] > target:
        return binary_search_recursive(array, low, mid - 1, target)
    else:
        return binary_search_recursive(array, mid + 1, high, target)

