from typing import List

def find_two_sum(numbers: List[int], target: int) -> List[int]:
    """
    Finds two indices of the numbers in a sorted list that add up to the target.
    The indices are returned as 1-based.
    """
    left, right = 0, len(numbers) - 1

    while left < right:
        current_sum = numbers[left] + numbers[right]
        if current_sum == target:
            return [left + 1, right + 1]
        elif current_sum < target:
            left += 1
        else:
            right -= 1

    return []  # Just a fallback, guaranteed there is exactly one solution.

