def unique_filter(string: str) -> str:
    """
    Returns a string with only the first occurrence of each character in the order they appear.
    """
    seen = set()
    result = []

    for char in string:
        if char not in seen:
            seen.add(char)
            result.append(char)

    return ''.join(result)

