def two_sum(array, target):
    """
    Given an array of integers, return a tuple of two indices of the numbers such that they add up to a specific target.
    """
    dic = {}
    for i, num in enumerate(array):
        if num in dic:
            return (dic[num], i)
        dic[target - num] = i
    return None

