from typing import List, Tuple

def is_path_exists(n: int, edges: List[Tuple[int, int]], source: int, target: int) -> bool:
    """
    Determines if there is a path from the source node to the target node in a directed graph.
    """
    if source == target:
        return True

    # Create adjacency list
    adj_list = [[] for _ in range(n)]
    for u, v in edges:
        adj_list[u].append(v)

    # Use DFS to check for the path
    visited = [False] * n

    def dfs(node):
        if node == target:
            return True
        visited[node] = True
        for neighbor in adj_list[node]:
            if not visited[neighbor] and dfs(neighbor):
                return True
        return False

    return dfs(source)

