import bisect

def longest_increasing_subsequence(sequence):
    """
    Function to find the length of the longest increasing subsequence.
    The function uses binary search and dynamic programming to achieve an O(n log n) time complexity.

    Parameters:
    sequence (list of int): The input list of integers

    Returns:
    int: The length of the longest increasing subsequence
    """
    if not sequence:
        return 0

    dp = []

    for num in sequence:
        idx = bisect.bisect_left(dp, num)
        if idx == len(dp):
            dp.append(num)
        else:
            dp[idx] = num

    return len(dp)

