def hailstone(n):
    """
    Generate the hailstone sequence for a given starting number n.
    """
    sequence = []
    while n != 1:
        sequence.append(n)
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
    sequence.append(1)
    return sequence

def longest_hailstone_sequence(limit):
    """
    Find the starting number below a given limit that produces
    the longest hailstone sequence.
    """
    max_length = 0
    starting_number = 0
    lengths = {}

    for i in range(1, limit):
        n = i
        count = 0

        while n != 1 and n >= i:
            if n % 2 == 0:
                n //= 2
            else:
                n = 3 * n + 1
            count += 1

        lengths[i] = count + (lengths[n] if n != 1 else 1)

        if lengths[i] > max_length:
            max_length = lengths[i]
            starting_number = i

    return (starting_number, max_length)

