def cycle_sort(arr):
    """
    In-place cycle sort function that sorts a list with minimal write operations.
    """
    writes = 0

    # Traverse the array to find cycles to rearrange
    for cycle_start in range(0, len(arr) - 1):
        item = arr[cycle_start]

        # Find the position where we put the element
        pos = cycle_start
        for i in range(cycle_start + 1, len(arr)):
            if arr[i] < item:
                pos += 1

        # If the item is already in correct position
        if pos == cycle_start:
            continue

        # Otherwise, put the item at its correct position
        while item == arr[pos]:
            pos += 1
        arr[pos], item = item, arr[pos]
        writes += 1

        # Rotate the rest of the cycle
        while pos != cycle_start:
            pos = cycle_start
            for i in range(cycle_start + 1, len(arr)):
                if arr[i] < item:
                    pos += 1

            while item == arr[pos]:
                pos += 1
            arr[pos], item = item, arr[pos]
            writes += 1

    return arr

