def count_sentences(string: str, dictionary: set) -> int:
    def dfs(s, memo):
        if s in memo:
            return memo[s]
        if not s:
            return 1
        count = 0
        for i in range(1, len(s) + 1):
            if s[:i] in dictionary:
                count += dfs(s[i:], memo)
        memo[s] = count
        return count

    memo = {}
    return dfs(string, memo)

