def enhanced_quick_sort(arr, use_median_pivot=False):
    """
    Sorts the input list using an enhanced Quick Sort algorithm.
    Uses median-of-three for pivot selection if use_median_pivot is True.

    Parameters:
    arr (list): List of integers to be sorted.
    use_median_pivot (bool, optional): Flag to use median-of-three pivot selection. Default is False.

    Returns:
    list: A new list containing the sorted integers.
    """
    if len(arr) <= 1:
        return arr

    def median_of_three(lst):
        first = lst[0]
        middle = lst[len(lst) // 2]
        last = lst[-1]
        return sorted([first, middle, last])[1]

    def quicksort_internal(lst):
        if len(lst) <= 1:
            return lst
        if use_median_pivot:
            pivot = median_of_three(lst)
        else:
            pivot = lst[len(lst) // 2]

        left = [x for x in lst if x < pivot]
        middle = [x for x in lst if x == pivot]
        right = [x for x in lst if x > pivot]

        return quicksort_internal(left) + middle + quicksort_internal(right)

    return quicksort_internal(arr)

