import random

def is_prime(n: int, k: int) -> bool:
    """
    Returns True if n is probably prime with k iterations of the Rabin-Miller test.
    Returns False if n is definitely not prime.
    """

    # Handle edge cases
    if n in (2, 3):
        return True
    if n % 2 == 0 or n < 2:
        return False

    # Write n as d * 2^r + 1 with d odd
    def decompose(n):
        r = 0
        d = n - 1
        while d % 2 == 0:
            d //= 2
            r += 1
        return r, d

    def is_composite(a, d, n, r):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return False
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                return False
        return True

    r, d = decompose(n)
    for _ in range(k):
        a = random.randint(2, n - 2)
        if is_composite(a, d, n, r):
            return False
    return True

