def insert_in_sorted_array(array: list, target: int) -> list:
    """
    Inserts the target value into the sorted array while maintaining the sorted order.
    """
    if not array:
        return [target]

    left, right = 0, len(array) - 1

    while left <= right:
        mid = (left + right) // 2
        if array[mid] == target:
            return array  # Target already in array, no need to insert
        elif array[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    array.insert(left, target)
    return array

