def find_factorial(n):
    """Calculates the factorial of a given number n."""
    if n == 0 or n == 1:
        return 1
    factorial = 1
    for i in range(2, n + 1):
        factorial *= i
    return factorial

def krishnamurthy_number(n):
    """Checks if n is a Krishnamurthy number."""
    def compute_digit_factorials(number):
        # Define a lookup table for factorial values of digits 0-9
        factorial_lookup = {i: find_factorial(i) for i in range(10)}

        sum_factorials = 0
        while number > 0:
            digit = number % 10
            sum_factorials += factorial_lookup[digit]
            number //= 10
        return sum_factorials

    return n == compute_digit_factorials(n)

def decode_string(s: str) -> str:
    stack = []
    current_string = ""
    current_num = 0

    for char in s:
        if char.isdigit():
            current_num = current_num * 10 + int(char)
        elif char == '[':
            stack.append(current_string)
            stack.append(current_num)
            current_string = ""
            current_num = 0
        elif char == ']':
            num = stack.pop()
            prev_string = stack.pop()
            current_string = prev_string + num * current_string
        else:
            current_string += char

    return current_string

