from typing import List, Tuple

def matrix_chain_order(array: List[int]) -> Tuple[List[List[int]], List[List[int]]]:
    n = len(array) - 1
    # m[i][j] stores the minimum number of scalar multiplications needed to compute the product of matrices A[i]...A[j]
    m = [[0 for _ in range(n + 1)] for _ in range(n + 1)]
    # s[i][j] stores the index of the matrix after which the optimal split occurs in the product of matrices A[i]...A[j]
    s = [[0 for _ in range(n + 1)] for _ in range(n + 1)]

    # l is the chain length
    for l in range(2, n + 1):
        for i in range(1, n - l + 2):
            j = i + l - 1
            m[i][j] = float('inf')
            for k in range(i, j):
                q = m[i][k] + m[k + 1][j] + array[i - 1] * array[k] * array[j]
                if q < m[i][j]:
                    m[i][j] = q
                    s[i][j] = k

    return m, s

def print_optimal_solution(s: List[List[int]], i: int, j: int) -> None:
    if i == j:
        print(f"A{i}", end="")
    else:
        print("(", end="")
        print_optimal_solution(s, i, s[i][j])
        print_optimal_solution(s, s[i][j] + 1, j)
        print(")", end="")

