def convert_to_bytes(num: int, endian: str) -> bytes:
    """
    Convert an integer to a byte array in the specified byte order.

    :param num: A non-negative integer to convert to byte array.
    :param endian: A string specifying the byte order, either "big" or "little".
    :return: A byte array representing the integer in the specified byte order.
    """
    if num == 0:
        return b'\x00'

    num_bytes = (num.bit_length() + 7) // 8  # Calculate the number of bytes needed

    if endian not in ['big', 'little']:
        raise ValueError("endian must be either 'big' or 'little'")

    return num.to_bytes(num_bytes, byteorder=endian)

def convert_to_int(bytestr: bytes, endian: str) -> int:
    """
    Convert a byte array to an integer in the specified byte order.

    :param bytestr: A byte array to convert to an integer.
    :param endian: A string specifying the byte order, either "big" or "little".
    :return: An integer represented by the byte array in the specified byte order.
    """
    if endian not in ['big', 'little']:
        raise ValueError("endian must be either 'big' or 'little'")

    return int.from_bytes(bytestr, byteorder=endian)

def decrypt_caesar_cipher(s: str, k: int) -> str:
    def decrypt_char(c, k):
        if 'a' <= c <= 'z':
            return chr((ord(c) - ord('a') - k) % 26 + ord('a'))
        elif 'A' <= c <= 'Z':
            return chr((ord(c) - ord('A') - k) % 26 + ord('A'))
        else:
            return c

    k = k % 26  # Normalize k to be within the range 0-25
    return ''.join(decrypt_char(c, k) for c in s)

