def misras_gries(array, k=2):
    """
    Identifies elements that appear at least n/k times in the array using the Misra-Gries algorithm.

    Params:
    - array: List[int] : list of integers with possible repetition
    - k: int: An integer determining the frequency threshold (default 2)

    Returns:
    - dict: dictionary with elements as keys and their frequencies as values if they appear at least n/k times
    - None: if no elements qualify the condition
    """

    n = len(array)
    if k < 2 or n == 0:
        return None

    # Step 1: Initialize a counter dictionary with size k-1
    counter = {}

    # Step 2: Use the Misra-Gries algorithm to find potential candidates
    for num in array:
        if num in counter:
            counter[num] += 1
        elif len(counter) < k - 1:
            counter[num] = 1
        else:
            for key in list(counter.keys()):
                counter[key] -= 1
                if counter[key] == 0:
                    del counter[key]

    # Step 3: Verify these candidates
    for key in counter.keys():
        counter[key] = 0  # Reset counts

    for num in array:
        if num in counter:
            counter[num] += 1

    # Step 4: Collect and return qualified candidates
    result = {key: count for key, count in counter.items() if count >= n / k}
    return result if result else None

