def count_sentences(s: str, word_dict: set) -> int:
    # Define a memoization dictionary.
    memo = {}

    def dfs(index):
        # If we have reached the end of the string, that's a valid way to segment it.
        if index == len(s):
            return 1

        # If this computation has already been done, return the stored result.
        if index in memo:
            return memo[index]

        # Explore further segmentations
        count = 0
        for end in range(index + 1, len(s) + 1):
            if s[index:end] in word_dict:
                count += dfs(end)

        # Store the result in memoization dictionary before returning it.
        memo[index] = count
        return count

    # Start the DFS from the beginning of the string.
    return dfs(0)

