from typing import List

def logistics_selection_sort(weights: List[int], simulation: bool=False) -> List[int]:
    n = len(weights)
    for i in range(n):
        min_index = i
        for j in range(i+1, n):
            if weights[j] < weights[min_index]:
                min_index = j
        weights[i], weights[min_index] = weights[min_index], weights[i]

        if simulation:
            print(f"iteration {i} :", ' '.join(map(str, weights)))

    return weights

