from typing import List

def count_components(adjacency_list: List[List[int]], size: int) -> int:
    """
    Count the number of connected components in an undirected graph.

    :param adjacency_list: List of lists where adjacency_list[i] contains the nodes connected to node i
    :param size: Total number of nodes in the graph
    :return: Number of connected components
    """
    def dfs(node: int):
        stack = [node]
        while stack:
            current = stack.pop()
            for neighbor in adjacency_list[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    visited = set()
    count = 0

    for node in range(size):
        if node not in visited:
            dfs(node)
            count += 1

    return count

from typing import List

def find_narcissistic_numbers(low: int, high: int) -> List[int]:
    def is_narcissistic(num: int) -> bool:
        digits = list(map(int, str(num)))
        return num == sum(dig ** (i+1) for i, dig in enumerate(digits))

    return [num for num in range(low, high + 1) if is_narcissistic(num)]

