from typing import List, Dict

def rabin_karp_multiple_substrings(patterns: List[str], text: str) -> Dict[str, List[int]]:
    def hash_function(s, base, mod):
        hash_value = 0
        for char in s:
            hash_value = (hash_value * base + ord(char)) % mod
        return hash_value

    def rolling_hash(old_hash, old_char, new_char, base, mod, power):
        new_hash = (old_hash - ord(old_char) * power) * base + ord(new_char)
        return new_hash % mod

    base = 256
    mod = 2**61 - 1
    n = len(text)
    result = {pattern: [] for pattern in patterns}

    for pattern in patterns:
        m = len(pattern)
        pattern_hash = hash_function(pattern, base, mod)
        text_hash = hash_function(text[:m], base, mod)
        power = pow(base, m - 1, mod)

        if pattern_hash == text_hash and text[:m] == pattern:
            result[pattern].append(0)

        for i in range(m, n):
            text_hash = rolling_hash(text_hash, text[i - m], text[i], base, mod, power)
            if pattern_hash == text_hash and text[i - m + 1:i + 1] == pattern:
                result[pattern].append(i - m + 1)

    return result

