from collections import deque
from typing import List

def walls_and_gates(grid: List[List[int]]) -> None:
    if not grid or not grid[0]:
        return

    m, n = len(grid), len(grid[0])
    INF = 2147483647
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    queue = deque()

    # Initialize queue with all gates
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                queue.append((i, j))

    # Perform BFS from all gates
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == INF:
                grid[nx][ny] = grid[x][y] + 1
                queue.append((nx, ny))

