from bisect import bisect_right
from typing import List

def smallest_greater_letter_bisect(letters: List[str], target: str) -> str:
    """
    Finds the smallest letter in the list which is greater than the target using bisect.
    """
    idx = bisect_right(letters, target)
    if idx == len(letters):
        return letters[0]
    return letters[idx]

def smallest_greater_letter_binary_search(letters: List[str], target: str) -> str:
    """
    Finds the smallest letter in the list which is greater than the target using manual binary search.
    """
    low, high = 0, len(letters) - 1

    while low <= high:
        mid = (low + high) // 2
        if letters[mid] <= target:
            low = mid + 1
        else:
            high = mid - 1

    return letters[low % len(letters)]

def smallest_greater_letter_brute_force(letters: List[str], target: str) -> str:
    """
    Finds the smallest letter in the list which is greater than the target using brute force approach.
    """
    for letter in letters:
        if letter > target:
            return letter
    return letters[0]

from typing import List

def count_combinations(nums: List[int], target: int) -> int:
    # Create a memoization dictionary to store results of subproblems
    memo = {0: 1}  # There is one way to get the target sum 0 (by picking nothing)

    def helper(t: int) -> int:
        # Check if the result is already in the memo dictionary
        if t in memo:
            return memo[t]

        # Initialize the count of combinations for the current target
        count = 0

        # Iterate through each number in nums and compute the number of combinations
        for num in nums:
            if t >= num:
                count += helper(t - num)

        # Store the computed result in the memo dictionary
        memo[t] = count

        return count

    # Call the helper function with the initial target
    return helper(target)

