from heapq import heappop, heappush
from typing import List

def shortest_path_with_weights(grid: List[List[int]]) -> int:
    if not grid or not grid[0]:
        return -1

    n, m = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    pq = [(grid[0][0], 0, 0)]

    min_cost = [[float('inf')] * m for _ in range(n)]
    min_cost[0][0] = grid[0][0]

    while pq:
        cost, x, y = heappop(pq)

        if (x, y) == (n-1, m-1):
            return cost

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m:
                new_cost = cost + grid[nx][ny]
                if new_cost < min_cost[nx][ny]:
                    min_cost[nx][ny] = new_cost
                    heappush(pq, (new_cost, nx, ny))

    return -1 if min_cost[n-1][m-1] == float('inf') else min_cost[n-1][m-1]

def detect_cycle_in_directed_graph(graph: dict) -> bool:
    """
    Determines if the given directed graph contains a cycle.

    Parameters:
    graph (dict): A dictionary where the key is a node and the value is a list of its adjacent nodes.

    Returns:
    bool: True if the graph contains a cycle, False otherwise.
    """

    WHITE, GRAY, BLACK = 0, 1, 2

    def dfs(node):
        stack = [node]
        while stack:
            node = stack.pop()
            if color[node] == WHITE:
                color[node] = GRAY
                stack.append(node)
                for neighbor in graph.get(node, []):
                    if color[neighbor] == WHITE:
                        stack.append(neighbor)
                    elif color[neighbor] == GRAY:
                        return True
            elif color[node] == GRAY:
                color[node] = BLACK
        return False

    color = {node: WHITE for node in graph}

    for node in graph:
        if color[node] == WHITE:
            if dfs(node):
                return True
    return False

