def atbash_cipher(input_text: str) -> str:
    """
    Encodes the input text using the Atbash cipher.

    Parameters:
    - input_text (str): The input string to be encoded

    Returns:
    - str: The encoded string with each alphabet character replaced
           by its reversed counterpart in the alphabet
    """
    def transform_char(c):
        if 'A' <= c <= 'Z':
            return chr(ord('Z') - (ord(c) - ord('A')))
        elif 'a' <= c <= 'z':
            return chr(ord('z') - (ord(c) - ord('a')))
        else:
            return c

    return ''.join(transform_char(c) for c in input_text)

