from typing import List

def limit_occurrences(lst: List[int], N: int) -> List[int]:
    """
    Modifies the list such that each integer appears at most N times without changing the order of elements.
    """
    if N == 0:
        return []

    count_dict = {}
    result = []

    for number in lst:
        if number not in count_dict:
            count_dict[number] = 0

        if count_dict[number] < N:
            result.append(number)
            count_dict[number] += 1

    return result

def is_one_edit_distance(s: str, t: str) -> bool:
    len_s, len_t = len(s), len(t)

    if abs(len_s - len_t) > 1:
        return False

    if len_s > len_t:
        return is_one_edit_distance(t, s)  # Ensure s is the shorter one

    # After the above check, we know len_s <= len_t
    for i in range(len_s):
        if s[i] != t[i]:
            if len_s == len_t:
                return s[i+1:] == t[i+1:]  # Check replace operation
            else:
                return s[i:] == t[i+1:]  # Check insert operation in t or delete in s

    return len_s + 1 == len_t  # Check append operation

