def find_longest_path(graph, start, end):
    def topological_sort(graph):
        def dfs(node):
            visited.add(node)
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
                    dfs(neighbor)
            ordering.append(node)

        visited = set()
        ordering = []
        for node in graph:
            if node not in visited:
                dfs(node)
        return ordering[::-1]

    def longest_path_dag(graph, start, end, ordering):
        dist = {node: float('-inf') for node in graph}
        dist[start] = 0
        path = {node: [] for node in graph}
        path[start] = [start]

        for node in ordering:
            if dist[node] != float('-inf'):
                for neighbor in graph.get(node, []):
                    if dist[node] + 1 > dist[neighbor]:
                        dist[neighbor] = dist[node] + 1
                        path[neighbor] = path[node] + [neighbor]

        return path[end] if dist[end] != float('-inf') else []

    if start not in graph or end not in graph:
        return []

    ordering = topological_sort(graph)
    return longest_path_dag(graph, start, end, ordering)

def tree_search(tree, target):
    """
    Recursively searches through a nested dictionary to find the target string.

    Args:
    tree (dict): The nested dictionary representing the organizational roles and tasks.
    target (str): The target string to search within the tree.

    Returns:
    bool: True if the target string is found, False otherwise.
    """
    target = target.lower()  # Case-insensitive search

    def search_subtree(subtree):
        if isinstance(subtree, dict):
            for key in subtree:
                if search_subtree(subtree[key]):
                    return True
        elif isinstance(subtree, list):
            for item in subtree:
                if isinstance(item, str) and item.lower() == target:
                    return True
                elif isinstance(item, (dict, list)):
                    if search_subtree(item):
                        return True
        return False

    return search_subtree(tree)

