def atbash_cipher(input_string: str) -> str:
    """
    Encrypts the input string using the Atbash cipher.
    """
    def translate(char):
        if 'a' <= char <= 'z':
            return chr(219 - ord(char))
        elif 'A' <= char <= 'Z':
            return chr(155 - ord(char))
        return char

    return ''.join(translate(char) for char in input_string)

