from typing import List

def find_factor_combinations(n: int) -> List[List[int]]:
    """
    Returns all unique combinations of factors of the given positive integer n.
    Each combination consists of factors greater than 1 and less than n that multiply to n.
    """
    def helper(start, n):
        results = []
        i = start
        while i * i <= n:
            if n % i == 0:
                results.append([i, n // i])
                for rest in helper(i, n // i):
                    results.append([i] + rest)
            i += 1
        return results

    if n <= 1:
        return []
    return helper(2, n)

