import math

def find_next_square(n):
    """
    Returns the next perfect square if n is a perfect square, otherwise returns -1.
    """
    if n < 0:
        return -1

    sqrt_n = math.isqrt(n)

    if sqrt_n * sqrt_n == n:
        return (sqrt_n + 1) * (sqrt_n + 1)
    else:
        return -1

