def custom_comb_sort(arr, shrink_factor, order):
    def get_next_gap(gap):
        gap = int(gap / shrink_factor)
        if gap < 1:
            return 1
        return gap

    def should_swap(a, b):
        if order == 'asc':
            return a > b
        elif order == 'desc':
            return a < b

    n = len(arr)
    gap = n
    swapped = True

    while gap != 1 or swapped:
        gap = get_next_gap(gap)
        swapped = False

        for i in range(0, n - gap):
            if should_swap(arr[i], arr[i + 1]):
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
                swapped = True

    return arr

