def word_pattern_match(pattern: str, input_string: str) -> bool:
    """
    Function to determine if input_string follows the same pattern as the pattern string.
    """
    words = input_string.split()
    if len(words) != len(pattern):
        return False

    char_to_word = {}
    word_to_char = {}

    for p, w in zip(pattern, words):
        if p in char_to_word:
            if char_to_word[p] != w:
                return False
        else:
            if w in word_to_char:
                return False
            char_to_word[p] = w
            word_to_char[w] = p

    return True

