def gnome_sort_descending(arr: list[int]) -> list[int]:
    """
    Sorts the list in descending order using the Gnome Sort algorithm.
    """
    pos = 0
    while pos < len(arr):
        if pos == 0 or arr[pos] <= arr[pos - 1]:
            pos += 1
        else:
            arr[pos], arr[pos - 1] = arr[pos - 1], arr[pos]
            pos -= 1
    return arr

