def simplify_path(path: str) -> str:
    """
    Simplifies the given Unix-style absolute path.

    Args:
    path (str): The input Unix-style path.

    Returns:
    str: The simplified canonical path.
    """
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return '/' + '/'.join(stack)

