def pattern_match(pattern, string):
    def backtrack(p_index, s_index, p_map, used):
        if p_index == len(pattern) and s_index == len(string):
            return True
        if p_index == len(pattern) or s_index == len(string):
            return False

        pattern_char = pattern[p_index]

        for end in range(s_index + 1, len(string) + 1):
            substr = string[s_index:end]

            if pattern_char not in p_map:
                if substr in used:
                    continue

                p_map[pattern_char] = substr
                used.add(substr)

                if backtrack(p_index + 1, end, p_map, used):
                    return True

                del p_map[pattern_char]
                used.remove(substr)
            elif p_map[pattern_char] == substr:
                if backtrack(p_index + 1, end, p_map, used):
                    return True

        return False

    return backtrack(0, 0, {}, set())

def efficient_binary_search(array, query):
    """
    This function implements an enhanced binary search to find all occurrences
    of 'query' in the sorted list 'array'.

    :param array: List[int] - A sorted list of integers.
    :param query: int - The target value to search for.
    :return: List[int] - A list of indices where 'query' is found in 'array'.
                         Returns an empty list if 'query' is not found.
    """
    def binary_search_left(array, query):
        left, right = 0, len(array)
        while left < right:
            mid = (left + right) // 2
            if array[mid] < query:
                left = mid + 1
            else:
                right = mid
        return left

    def binary_search_right(array, query):
        left, right = 0, len(array)
        while left < right:
            mid = (left + right) // 2
            if array[mid] <= query:
                left = mid + 1
            else:
                right = mid
        return left

    left_index = binary_search_left(array, query)
    right_index = binary_search_right(array, query)

    if left_index >= len(array) or array[left_index] != query:
        return []
    return list(range(left_index, right_index))

