from typing import List

def delimited_frequency_filter(arr: List[int], N: int) -> List[int]:
    """
    Returns a new List where each number in the input List `arr` appears at most `N` times,
    maintaining the original order.
    """
    count = {}
    result = []

    for num in arr:
        if count.get(num, 0) < N:
            result.append(num)
            count[num] = count.get(num, 0) + 1

    return result

from typing import List, Dict, Set

def find_all_cliques(edges: Dict[str, Set[str]]) -> List[List[int]]:
    def bron_kerbosch(R, P, X):
        if not P and not X:
            cliques.append(R)
        while P:
            v = P.pop()
            bron_kerbosch(R.union({v}), P.intersection(edges[v]), X.intersection(edges[v]))
            X.add(v)

    cliques = []
    vertices = set(edges.keys())
    bron_kerbosch(set(), vertices, set())
    return [list(clique) for clique in cliques]

