def combination_optimized(n, r):
    """
    Computes the binomial coefficient, nCr, using dynamic programming for efficiency.
    """
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1
    r = min(r, n - r)  # Take advantage of symmetry

    C = [0] * (r + 1)
    C[0] = 1

    for i in range(1, n + 1):
        for j in range(min(i, r), 0, -1):
            C[j] = C[j] + C[j - 1]

    return C[r]

from typing import List

def build_pi_table(pattern: str) -> List[int]:
    """
    Builds the partial match (pi) table for KMP algorithm.
    """
    m = len(pattern)
    pi = [0] * m
    j = 0

    for i in range(1, m):
        while j > 0 and pattern[i] != pattern[j]:
            j = pi[j - 1]
        if pattern[i] == pattern[j]:
            j += 1
            pi[i] = j
        else:
            pi[i] = 0

    return pi

def knuth_morris_pratt(text: str, pattern: str) -> List[int]:
    """
    Given two strings 'text' and 'pattern', return a list of starting indices in 'text' where 'pattern' is found.
    """
    n = len(text)
    m = len(pattern)

    if m == 0 or n == 0 or m > n:
        return []

    pi = build_pi_table(pattern)
    indices = []
    j = 0

    for i in range(n):
        while j > 0 and text[i] != pattern[j]:
            j = pi[j - 1]
        if text[i] == pattern[j]:
            if j == m - 1:
                indices.append(i - m + 1)
                j = pi[j]
            else:
                j += 1

    return indices

