def combination(n: int, r: int) -> int:
    """
    Calculate the number of ways to choose r items from n items using memoization.
    """
    # Memoization storage
    memo = {}

    def nCr(n, r):
        # Base cases
        if r == 0 or r == n:
            return 1
        if r == 1:
            return n

        # Check if value is already computed
        if (n, r) in memo:
            return memo[(n, r)]

        # Recursive calculation with memoization
        result = nCr(n - 1, r - 1) + nCr(n - 1, r)
        memo[(n, r)] = result
        return result

    return nCr(n, r)

