def check_robot_circle(moves: str) -> bool:
    """
    Determines if the robot returns to the starting position
    after executing all the given moves.
    """
    # Initialize the position of the robot
    x, y = 0, 0

    # Move the robot according to the commands
    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    # Check if the robot is at the starting position
    return x == 0 and y == 0

