def encode_rle(input: str) -> str:
    if not input:
        return ""

    encoded_str = ""
    count = 1

    for i in range(1, len(input)):
        if input[i] == input[i - 1]:
            count += 1
        else:
            encoded_str += f"{count}{input[i - 1]}"
            count = 1
    encoded_str += f"{count}{input[-1]}"

    return encoded_str

def decode_rle(input: str) -> str:
    if not input:
        return ""

    decoded_str = ""
    i = 0
    while i < len(input):
        j = i
        # Extract the number part
        while j < len(input) and input[j].isdigit():
            j += 1
        count = int(input[i:j])
        char = input[j]
        decoded_str += char * count
        i = j + 1

    return decoded_str

def limit(arr: list[int], min_lim: int = None, max_lim: int = None) -> list[int]:
    """
    Filters the elements of a given list to remain within the specified inclusive range [min_lim, max_lim].
    """
    if not arr:
        return []

    if min_lim is None:
        min_lim = min(arr)
    if max_lim is None:
        max_lim = max(arr)

    return [x for x in arr if min_lim <= x <= max_lim]

