def improved_exchange_sort(arr):
    """
    Sorts an array of integers using an improved version of the exchange sort.
    """
    n = len(arr)
    for i in range(n - 1):
        swapped = False
        for j in range(i + 1, n):
            if arr[i] > arr[j]:
                arr[i], arr[j] = arr[j], arr[i]
                swapped = True
        if not swapped:
            break
    return arr

