def encode_rle_advanced(input: str) -> str:
    if not input:
        return ""

    encoded_str = []
    count = 1
    prev_char = input[0]

    for char in input[1:]:
        if char == prev_char:
            count += 1
        else:
            encoded_str.append(f"{count}{prev_char}")
            prev_char = char
            count = 1

    encoded_str.append(f"{count}{prev_char}")

    return ''.join(encoded_str)

def decode_rle_advanced(input: str) -> str:
    if not input:
        return ""

    decoded_str = []
    count = 0

    for char in input:
        if char.isdigit():
            count = count * 10 + int(char)
        else:
            decoded_str.append(char * count)
            count = 0

    return ''.join(decoded_str)

