from typing import List

def first_occurrence(array: List[int], query: int) -> int:
    left, right = 0, len(array) - 1

    while left <= right:
        mid = (left + right) // 2

        if array[mid] == query:
            if mid == 0 or array[mid - 1] < query:
                return mid
            right = mid - 1
        elif array[mid] < query:
            left = mid + 1
        else:
            right = mid - 1

    return -1

