from typing import List

def generate_abbreviations(word: str) -> List[str]:
    def backtrack(pos, curr):
        if pos == len(word):
            abbreviations.append(curr)
        else:
            # Option 1: Keep the current character
            backtrack(pos + 1, curr + word[pos])

            # Option 2: Abbreviate current or following characters
            if not curr or curr[-1].isalpha():
                for i in range(1, len(word) - pos + 1):
                    backtrack(pos + i, curr + str(i))

    abbreviations = []
    backtrack(0, "")
    return abbreviations

