from typing import List

def find_patient_id(patient_ids: List[int], target_id: int) -> int:
    """
    Returns the index of the target_id in the sorted list patient_ids using binary search.
    If the target_id is not found, returns -1.
    """
    left, right = 0, len(patient_ids) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if patient_ids[mid] == target_id:
            return mid
        elif patient_ids[mid] < target_id:
            left = mid + 1
        else:
            right = mid - 1

    return -1

