def rabin_karp_search(pattern, text):
    """
    Finds the first occurrence of the pattern string within the text string using the Rabin-Karp algorithm.
    """
    if not pattern or not text or len(pattern) > len(text):
        return None

    base = 256  # Number of characters in the input alphabet
    prime = 101  # A prime number

    def hash_value(s, end, base, prime):
        h = 0
        for i in range(end):
            h = (h * base + ord(s[i])) % prime
        return h

    m = len(pattern)
    n = len(text)
    pattern_hash = hash_value(pattern, m, base, prime)
    text_hash = hash_value(text, m, base, prime)

    # Pre-compute base^(m-1) % prime
    base_m_1 = pow(base, m - 1, prime)

    for i in range(n - m + 1):
        if pattern_hash == text_hash:
            if text[i:i + m] == pattern:
                return i

        if i < n - m:
            text_hash = (text_hash - ord(text[i]) * base_m_1) * base + ord(text[i + m])
            text_hash %= prime
            if text_hash < 0:
                text_hash += prime

    return None

