from collections import defaultdict, deque

def is_strongly_connected(N, from_edges, to_edges):
    def dfs(graph, vertex, visited, stack=None):
        visited.add(vertex)
        for neighbour in graph[vertex]:
            if neighbour not in visited:
                dfs(graph, neighbour, visited, stack)
        if stack is not None:
            stack.append(vertex)

    # Create the original graph
    graph = defaultdict(list)
    for u, v in zip(from_edges, to_edges):
        graph[u].append(v)

    # Perform DFS to get the finish order of vertices
    visited = set()
    stack = []
    for vertex in range(N):
        if vertex not in visited:
            dfs(graph, vertex, visited, stack)

    # Create the reversed graph
    reversed_graph = defaultdict(list)
    for u, v in zip(from_edges, to_edges):
        reversed_graph[v].append(u)

    # Perform DFS in the order of decreasing finish time on reversed graph
    visited.clear()
    while stack:
        vertex = stack.pop()
        if vertex not in visited:
            component_stack = []
            dfs(reversed_graph, vertex, visited, component_stack)
            if len(visited) != N:
                return False
    return True

def is_match(s: str, p: str) -> bool:
    """
    Returns whether the input string s matches the pattern p. The pattern supports
    '.' which matches any single character and '*' which matches zero or more of
    the preceding element.
    """
    # Initialize a DP table with False values
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]

    # Empty string and empty pattern are a match
    dp[0][0] = True

    # Handle patterns like a*, a*b*, a*b*c* etc -> empty string
    for j in range(2, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the dp table
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (p[j - 2] == s[i - 1] or p[j - 2] == '.') and dp[i - 1][j]

    return dp[len(s)][len(p)]

