def generate_primes(n: int) -> list:
    """
    Generates all prime numbers less than or equal to `n`.
    """
    if n < 2:
        return []

    sieve = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if sieve[p] == True:
            for i in range(p * p, n + 1, p):
                sieve[i] = False
        p += 1

    primes = [p for p in range(2, n + 1) if sieve[p]]
    return primes

