def power_with_mod(base: int, exponent: int) -> int:
    MOD = 10**9 + 7

    if base == 0 and exponent == 0:
        return 1  # conventionally 0^0 is considered as 1 in many programming problems

    result = 1
    base = base % MOD

    while exponent > 0:
        if (exponent % 2) == 1:
            result = (result * base) % MOD
        exponent = exponent >> 1
        base = (base * base) % MOD

    return result

