from typing import List

def comb_sort_strings(arr: List[str]) -> List[str]:
    """
    Implement comb sort algorithm for sorting a list of strings in ascending order.
    """
    def getNextGap(gap):
        # Shrink gap by shrink factor of 1.3
        gap = (gap * 10) // 13
        if gap < 1:
            return 1
        return int(gap)

    n = len(arr)
    gap = n
    swapped = True

    while gap != 1 or swapped:
        gap = getNextGap(gap)
        swapped = False

        for i in range(n - gap):
            if arr[i] > arr[i + gap]:
                arr[i], arr[i + gap] = arr[i + gap], arr[i]
                swapped = True

    return arr

