from typing import List, Union

def validate_and_invert_matrix(matrix: List[List[Union[int, float]]]) -> List[List[Union[int, float]]]:
    import numpy as np

    # Check if input is a list of lists
    if not all(isinstance(row, list) for row in matrix):
        return [[-1]]

    # Check if matrix is empty or less than 2x2
    if len(matrix) < 2 or any(len(row) < 2 for row in matrix):
        return [[-3]]

    # Check if matrix is square
    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return [[-2]]

    try:
        matrix_np = np.array(matrix)
        # Check if matrix is singular
        if np.linalg.det(matrix_np) == 0:
            return [[-4]]
        # Compute inverse
        inverse = np.linalg.inv(matrix_np)
        return inverse.tolist()
    except:
        return [[-1]]  # In case of any unforeseen error

