from collections import deque

def switch_pairs(stack, use_stack: bool, use_queue: bool) -> list:
    """
    Switch successive pairs starting from the bottom of the stack.

    Parameters:
    - stack: List[int] -> A list of integers representing the stack.
    - use_stack: bool -> Whether to use a stack (list) as auxiliary storage.
    - use_queue: bool -> Whether to use a queue (collections.deque) as auxiliary storage.

    Returns:
    - List[int] -> A list representing the modified stack after pair switching.
    """
    if not stack:
        return []

    size = len(stack)
    aux = []

    if use_stack:
        while stack:
            aux.append(stack.pop(0))
    elif use_queue:
        aux = deque()
        while stack:
            aux.append(stack.pop(0))

    result = []

    for i in range(0, size, 2):
        if i + 1 < size:
            result.append(aux[i + 1]) # push the next element first
            result.append(aux[i])     # then push the current element
        else:
            result.append(aux[i])     # push the last element if odd size

    return result

from typing import List

def spiral_traversal(matrix: List[List[int]]) -> List[int]:
    """
    Returns a list of matrix elements in spiral order.
    """
    if not matrix:
        return []

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right along the top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # Traverse from top to bottom along the right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        if top <= bottom:
            # Traverse from right to left along the bottom row
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        if left <= right:
            # Traverse from bottom to top along the left column
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result

