from typing import List

def generate_abbreviations(word: str) -> List[str]:
    def backtrack(pos, current, count):
        if pos == len(word):
            if count > 0:
                current += str(count)
            result.append(current)
        else:
            # Abbreviate current character
            backtrack(pos + 1, current, count + 1)
            # Do not abbreviate current character
            new_current = current + (str(count) if count > 0 else '') + word[pos]
            backtrack(pos + 1, new_current, 0)

    result = []
    backtrack(0, "", 0)
    return result

