def pattern_match(pattern: str, string: str) -> bool:
    def is_match(s, p, bijection):
        if not p:
            return not s
        if p[0] in bijection:
            match = bijection[p[0]]
            if s.startswith(match):
                return is_match(s[len(match):], p[1:], bijection)
            else:
                return False
        else:
            for i in range(1, len(s) - len(p) + 2):
                match = s[:i]
                if match not in bijection.values():
                    bijection[p[0]] = match
                    if is_match(s[i:], p[1:], bijection):
                        return True
                    del bijection[p[0]]
            return False

    return is_match(string, pattern, {})

