def rabin_karp_search(pattern: str, text: str) -> int:
    """
    Implements Rabin-Karp algorithm to find the first occurrence of `pattern` in `text`.
    Returns -1 if the pattern is not found.
    """
    if not pattern or not text or len(pattern) > len(text):
        return -1

    base = 256
    prime = 101  # A prime number for modulo operation

    m = len(pattern)
    n = len(text)
    pattern_hash = 0
    text_hash = 0
    h = 1

    for i in range(m - 1):
        h = (h * base) % prime

    for i in range(m):
        pattern_hash = (base * pattern_hash + ord(pattern[i])) % prime
        text_hash = (base * text_hash + ord(text[i])) % prime

    for i in range(n - m + 1):
        if pattern_hash == text_hash:
            if text[i:i + m] == pattern:
                return i
        if i < n - m:
            text_hash = (base * (text_hash - ord(text[i]) * h) + ord(text[i + m])) % prime
            if text_hash < 0:
                text_hash += prime

    return -1

