def modified_radix_sort(arr):
    from itertools import chain

    def counting_sort(arr, exp):
        n = len(arr)
        output = [0] * n
        count = [0] * 10

        for i in range(n):
            index = abs(arr[i]) // exp
            count[index % 10] += 1

        for i in range(1, 10):
            count[i] += count[i - 1]

        for i in range(n-1, -1, -1):
            index = abs(arr[i]) // exp
            output[count[index % 10] - 1] = arr[i]
            count[index % 10] -= 1

        for i in range(n):
            arr[i] = output[i]

    def radix_sort(arr):
        max1 = max(arr, key=abs)

        exp = 1
        while abs(max1) // exp > 0:
            counting_sort(arr, exp)
            exp *= 10

    if not arr:
        return []

    positive_numbers = [num for num in arr if num >= 0]
    negative_numbers = [-num for num in arr if num < 0]

    if positive_numbers:
        radix_sort(positive_numbers)
    if negative_numbers:
        radix_sort(negative_numbers)
        negative_numbers = [-num for num in reversed(negative_numbers)]

    return list(chain(negative_numbers, positive_numbers))

