def is_valid_brackets(s: str) -> bool:
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping.values():
            stack.append(char)
        elif char in mapping:
            if not stack or stack[-1] != mapping[char]:
                return False
            stack.pop()
        else:
            return False

    return not stack

from typing import List, Tuple

def find_two_sum(nums: List[int], target: int) -> Tuple[int, int]:
    """
    This function finds two distinct indices i and j such that nums[i] + nums[j] equals the target.
    """
    num_to_index = {}
    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], index)
        num_to_index[num] = index
    return (-1, -1) # This line should never be reached given the problem constraints.

