from typing import List

def ternary_search(sorted_array: List[int], key: int) -> int:
    def recursive_search(left: int, right: int) -> int:
        if left > right:
            return -1

        third_size = (right - left) // 3
        mid1 = left + third_size
        mid2 = right - third_size

        if sorted_array[mid1] == key:
            return mid1
        if sorted_array[mid2] == key:
            return mid2

        if key < sorted_array[mid1]:
            return recursive_search(left, mid1 - 1)
        elif key > sorted_array[mid2]:
            return recursive_search(mid2 + 1, right)
        else:
            return recursive_search(mid1 + 1, mid2 - 1)

    return recursive_search(0, len(sorted_array) - 1)

import random
from typing import Tuple

def enhanced_is_prime(n: int, k: int) -> Tuple[bool, int]:
    if n % 2 == 0 or n <= 1:
        return False, 0

    # Find d such that d * 2^r = n-1 with d odd by factoring powers of 2 from n-1
    d = n - 1
    r = 0
    while d % 2 == 0:
        d //= 2
        r += 1

    def is_composite(a):
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            return False
        for _ in range(r - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                return False
        return True

    total_witnesses = 0
    for _ in range(k):
        a = random.randrange(2, n - 1)
        if not is_composite(a):
            total_witnesses += 1
        else:
            return False, 0  # Immediately return if a composite witness is found.

    return True, total_witnesses

