def enhanced_square_root(n, epsilon=0.001):
    """
    Returns the approximate square root of n and the number of iterations it took to reach the desired precision.
    """
    if n == 0:
        return (0, 0)

    guess = n / 2.0
    iterations = 0

    while True:
        iterations += 1
        new_guess = (guess + n / guess) / 2.0
        if abs(new_guess - guess) < epsilon:
            return (new_guess, iterations)
        guess = new_guess

def is_strongly_connected(vertex_count, edges):
    from collections import defaultdict

    def dfs(graph, start_vertex):
        visited = [False] * vertex_count
        stack = [start_vertex]
        while stack:
            vertex = stack.pop()
            if not visited[vertex]:
                visited[vertex] = True
                for neighbor in graph[vertex]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return visited

    if vertex_count == 0:
        return True

    graph = defaultdict(list)
    reverse_graph = defaultdict(list)

    for u, v in edges:
        graph[u].append(v)
        reverse_graph[v].append(u)

    visited_from_start = dfs(graph, 0)
    if not all(visited_from_start):
        return False

    visited_from_start_reverse = dfs(reverse_graph, 0)
    if not all(visited_from_start_reverse):
        return False

    return True

