def compute_combinations(n: int, r: int) -> int:
    """
    Calculates the number of ways to choose r items from n items (nCr) using an iterative dynamic programming approach.
    """
    if r > n:
        return 0

    if r == 0 or r == n:
        return 1

    # Create a table to store intermediate results, initialized to zero
    C = [[0 for _ in range(r + 1)] for _ in range(n + 1)]

    # Populate the table using the bottom-up approach
    for i in range(n + 1):
        for j in range(min(i, r) + 1):
            if j == 0 or j == i:
                C[i][j] = 1
            else:
                C[i][j] = C[i-1][j-1] + C[i-1][j]

    return C[n][r]

from typing import List

def optimized_sieve(n: int) -> List[int]:
    """
    Returns a list of all prime numbers less than n using an optimized Sieve of Eratosthenes
    that only considers odd numbers.
    """
    if n <= 2:
        return []

    sieve = [True] * (n // 2)
    sieve[0] = False  # 1 is not a prime number

    for i in range(3, int(n**0.5) + 1, 2):
        if sieve[i // 2]:
            for j in range(i * i, n, 2 * i):
                sieve[j // 2] = False

    primes = [2] + [2 * i + 1 for i in range(1, n // 2) if sieve[i]]
    return primes

