    ranges = []
    start = array[0]
    end = array[0]

    for i in range(1, len(array)):
        if array[i] == end + 1:
            end = array[i]
        else:
            ranges.append((start, end))
            start = array[i]
            end = array[i]

    ranges.append((start, end))
    return ranges

