from typing import List, Iterator

def permute(elements: List[int]) -> List[List[int]]:
    """
    Returns all possible permutations of the list of elements.
    """
    result = []
    if len(elements) == 0:
        return [[]]
    for i in range(len(elements)):
        # Select the current element
        current_element = elements[i]
        # Recursively find the permutations of the remaining elements
        remaining_elements = elements[:i] + elements[i + 1:]
        for p in permute(remaining_elements):
            result.append([current_element] + p)
    return result

def permute_iter(elements: List[int]) -> Iterator[List[int]]:
    """
    Yields all possible permutations of the list of elements one at a time.
    """
    if len(elements) == 0:
        yield []
    else:
        for i in range(len(elements)):
            current_element = elements[i]
            remaining_elements = elements[:i] + elements[i + 1:]
            for p in permute_iter(remaining_elements):
                yield [current_element] + p

