def power_hybrid(a: int, n: int, mod: int = None, threshold: int = 1000) -> int:
    def power_recursive(base, exp, modulo):
        if exp == 0:
            return 1
        half = power_recursive(base, exp // 2, modulo)
        half = (half * half) % modulo if modulo else half * half
        if exp % 2 != 0:
            half = (half * base) % modulo if modulo else half * base
        return half

    def power_iterative(base, exp, modulo):
        result = 1
        while exp >= threshold:
            if exp % 2 != 0:
                result = (result * base) % modulo if modulo else result * base
            base = (base * base) % modulo if modulo else base * base
            exp //= 2
        return result, base, exp

    result, base, exp = power_iterative(a, n, mod)
    if exp < threshold:
        result = (result * power_recursive(base, exp, mod)) % mod if mod else result * power_recursive(base, exp, None)
    return result

def contain_string(haystack: str, needle: str) -> int:
    """
    Returns the index of the first occurrence of `needle` in `haystack`,
    or -1 if `needle` is not part of `haystack`.

    Implements Knuth-Morris-Pratt (KMP) algorithm for efficient pattern searching.
    """
    if not needle:
        return 0

    # Generate the KMP partial match table (also known as "failure function")
    def kmp_table(needle):
        table = [0] * len(needle)
        j = 0
        for i in range(1, len(needle)):
            if needle[i] == needle[j]:
                j += 1
                table[i] = j
            else:
                if j != 0:
                    j = table[j-1]
                    i -= 1
                else:
                    table[i] = 0
        return table

    lps = kmp_table(needle)

    i = j = 0
    while i < len(haystack):
        if haystack[i] == needle[j]:
            i += 1
            j += 1

        if j == len(needle):
            return i - j

        elif i < len(haystack) and haystack[i] != needle[j]:
            if j != 0:
                j = lps[j-1]
            else:
                i += 1

    return -1

