def contains_cycle(graph: dict) -> bool:
    WHITE, GRAY, BLACK = 0, 1, 2

    def dfs(vertex):
        if state[vertex] == GRAY:
            return True
        if state[vertex] == BLACK:
            return False

        state[vertex] = GRAY
        for neighbor in graph.get(vertex, []):
            if dfs(neighbor):
                return True

        state[vertex] = BLACK
        return False

    state = {vertex: WHITE for vertex in graph}

    for vertex in graph:
        if state[vertex] == WHITE:
            if dfs(vertex):
                return True

    return False

