def highlight_terms(words, symbols):
    """
    Highlight key terms in a list of words with the longest matching symbol within square brackets.
    """
    # Sort symbols by length in descending order to prioritize longer symbols
    symbols.sort(key=len, reverse=True)

    def find_and_replace(word):
        for symbol in symbols:
            if symbol in word:
                # Replace the first occurrence of the symbol surrounded by square brackets
                return word.replace(symbol, f'[{symbol}]', 1)
        return word

    return [find_and_replace(word) for word in words]

