def move_zeros_inplace(array):
    """
    Moves all zeros to the end of the list while preserving the order of non-zero elements.
    """
    # Write index for non-zero elements
    write_index = 0

    for read_index in range(len(array)):
        if array[read_index] != 0 or type(array[read_index]) is bool:
            array[write_index] = array[read_index]
            write_index += 1

    for i in range(write_index, len(array)):
        array[i] = 0

def efficient_combination(n: int, r: int, memo=None) -> int:
    if memo is None:
        memo = {}

    # Base cases
    if r == 0 or r == n:
        return 1

    if (n, r) in memo:
        return memo[(n, r)]

    # Recursive calculation with memoization
    memo[(n, r)] = efficient_combination(n-1, r-1, memo) + efficient_combination(n-1, r, memo)
    return memo[(n, r)]

