def is_exactly_one_edit_away(s: str, t: str) -> bool:
    len_s = len(s)
    len_t = len(t)

    # If the length difference is greater than 1, they can't be one edit away
    if abs(len_s - len_t) > 1:
        return False

    # Identify shorter and longer string
    if len_s > len_t:
        s, t = t, s
        len_s, len_t = len_t, len_s

    i = 0
    j = 0
    found_difference = False

    # Traverse both strings
    while i < len_s and j < len_t:
        if s[i] != t[j]:
            if found_difference:
                return False
            found_difference = True

            if len_s == len_t:
                i += 1
        else:
            i += 1
        j += 1

    return True if found_difference or len_s != len_t else False

