from typing import List

def generate_expressions(num: str, target: int) -> List[str]:
    res = []

    def backtrack(index: int, path: str, value: int, prev: int):
        if index == len(num):
            if value == target:
                res.append(path)
            return

        for i in range(index, len(num)):
            if i != index and num[index] == '0':
                break
            current_str = num[index:i + 1]
            current_num = int(current_str)

            if index == 0:
                backtrack(i + 1, current_str, current_num, current_num)
            else:
                backtrack(i + 1, path + '+' + current_str, value + current_num, current_num)
                backtrack(i + 1, path + '-' + current_str, value - current_num, -current_num)
                backtrack(i + 1, path + '*' + current_str, value - prev + prev * current_num, prev * current_num)

    backtrack(0, '', 0, 0)
    return res

