import math

def find_next_square(sq: int) -> int:
    """
    Returns the next perfect square if the input is a perfect square.
    If the input is not a perfect square, returns -1.
    """
    if sq < 0:
        return -1

    root = int(math.sqrt(sq))
    if root * root == sq:
        return (root + 1) ** 2
    else:
        return -1

def enhanced_bubble_sort(arr, ascending=True, simulation=False):
    """
    Enhanced bubble sort that sorts an array in ascending or descending order
    with early termination if no swaps are made in a full pass.

    Args:
        arr (list): A list of comparable elements.
        ascending (bool): If True, sort in ascending order, else descending.
        simulation (bool): If True, print iterations steps for simulation.

    Returns:
        list: The sorted array.
    """
    if not isinstance(arr, list):
        raise TypeError("Input should be a list")

    n = len(arr)
    if n < 2:
        return arr  # no need to sort if array has 0 or 1 element

    for i in range(n):
        swapped = False
        if simulation: print(f"Pass {i+1}: {arr}")
        # Last i elements are already sorted
        for j in range(1, n - i):
            if (ascending and arr[j - 1] > arr[j]) or (not ascending and arr[j - 1] < arr[j]):
                arr[j - 1], arr[j] = arr[j], arr[j - 1]
                swapped = True

        if simulation: print(f"    After swap: {arr}")
        if not swapped:
            break  # Stop iteration if the array is already sorted

    return arr

