def fizzbuzz(n: int) -> list:
    """
    Generates a list of values from 1 to n with specific substitutions for multiples of 3 and 5.

    Parameters:
    n (int): The upper limit of the range starting from 1.

    Returns:
    list: A list containing numbers with substitutions based on the given rules.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append('FizzBuzz')
        elif i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        else:
            result.append(i)
    return result

