from typing import List

def dynamic_ternary_search(arr: List[int], key: int) -> int:
    """
    Performs a ternary search on a sorted array to find the key.
    Returns the index of the key if found, otherwise returns -1.
    """
    def ternary_search(l, r):
        if r >= l:
            third = (r - l) // 3
            mid1 = l + third
            mid2 = r - third

            if arr[mid1] == key:
                return mid1
            if arr[mid2] == key:
                return mid2

            if key < arr[mid1]:
                return ternary_search(l, mid1 - 1)
            elif key > arr[mid2]:
                return ternary_search(mid2 + 1, r)
            else:
                return ternary_search(mid1 + 1, mid2 - 1)
        return -1

    return ternary_search(0, len(arr) - 1)

