from typing import List

def custom_selection_sort(arr: List[int], trace: bool) -> List[int]:
    n = len(arr)
    for i in range(n):
        min_idx = i
        if trace:
            print(f"iteration {i}: {' '.join(map(str, arr))}")
        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]
    if trace:
        print(f"iteration {n-1}: {' '.join(map(str, arr))}")
    return arr

