def iterative_binomial_coefficient(n: int, k: int) -> int:
    if k > n:
        raise ValueError("k should not be greater than n")
    if k == 0 or k == n:
        return 1
    k = min(k, n - k)  # Take advantage of symmetry properties
    c = 1
    for i in range(k):
        c = c * (n - i) // (i + 1)
    return c

