def custom_caesar_cipher(s: str, k: int) -> str:
    """
    Encrypts the input string `s` by shifting each letter by `k` positions in the alphabet.
    If `k` is negative, shifts the letters to the left. Non-alphabetic characters remain unchanged.
    Handles both uppercase and lowercase letters appropriately by shifting them within their respective ranges.
    """
    result = []
    k = k % 26  # Reduce k to be within the range of 0-25

    for char in s:
        if 'a' <= char <= 'z':
            new_char = chr((ord(char) - ord('a') + k) % 26 + ord('a'))
            result.append(new_char)
        elif 'A' <= char <= 'Z':
            new_char = chr((ord(char) - ord('A') + k) % 26 + ord('A'))
            result.append(new_char)
        else:
            result.append(char)

    return ''.join(result)

