def simplify_path(path):
    """
    Simplifies the given Unix-style file path.

    Args:
    path (str): The Unix-style file path

    Returns:
    str: The simplified canonical path
    """
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        elif part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    return '/' + '/'.join(stack)

