from typing import List

def filter_list_by_occurrence(input_list: List[int], max_occurrences: int) -> List[int]:
    """
    Filters the input list to ensure that each number appears at most max_occurrences times,
    while retaining the original order of appearance.
    """
    if max_occurrences == 0:
        return []

    occurrence_count = {}
    filtered_list = []

    for num in input_list:
        if num in occurrence_count:
            if occurrence_count[num] < max_occurrences:
                filtered_list.append(num)
                occurrence_count[num] += 1
        else:
            filtered_list.append(num)
            occurrence_count[num] = 1

    return filtered_list

