from typing import List, Union
import math

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_safe_prime_with_primitive_roots(p: int) -> Union[List[int], str]:
    if not is_prime(p):
        return "Not a Safe Prime"
    q = (p - 1) // 2
    if not is_prime(q):
        return "Not a Safe Prime"

    # To find primitive roots of p
    def primitive_roots(p):
        roots = []
        required_set = set(num for num in range(1, p) if math.gcd(num, p) == 1)
        for g in range(1, p):
            actual_set = set(pow(g, powers, p) for powers in range(1, p))
            if required_set == actual_set:
                roots.append(g)
        return roots

    return primitive_roots(p)

