from typing import List

def determinant(matrix: List[List[float]]) -> float:
    if len(matrix) == 1:
        return matrix[0][0]
    if len(matrix) == 2:
        return matrix[0][0] * matrix[1][1] - matrix[0][1] * matrix[1][0]
    det = 0
    for c in range(len(matrix)):
        submatrix = [row[:c] + row[c + 1:] for row in matrix[1:]]
        det += ((-1) ** c) * matrix[0][c] * determinant(submatrix)
    return det

def get_matrix_minor(matrix: List[List[float]], i: int, j: int) -> List[List[float]]:
    return [row[:j] + row[j + 1:] for row in (matrix[:i] + matrix[i + 1:])]

def invert_matrix(matrix: List[List[float]]) -> List[List[float]]:
    if not (isinstance(matrix, list) and all(isinstance(row, list) for row in matrix)):
        return [[-1]]

    n = len(matrix)
    if any(len(row) != n for row in matrix):
        return [[-2]]

    if n == 1:
        return [[-3]]

    det = determinant(matrix)
    if det == 0:
        return [[-4]]

    cofactors = []
    for r in range(n):
        cofactorRow = []
        for c in range(n):
            minor = get_matrix_minor(matrix, r, c)
            cofactorRow.append(((-1) ** (r + c)) * determinant(minor))
        cofactors.append(cofactorRow)

    cofactors = list(map(list, zip(*cofactors)))
    for r in range(n):
        for c in range(n):
            cofactors[r][c] = cofactors[r][c] / det

    return cofactors

