from typing import List, Tuple
from collections import deque

def shortest_distance(grid: List[List[int]]) -> int:
    # Helper function to perform BFS from any building
    def bfs(start_row: int, start_col: int) -> Tuple[List[List[int]], List[List[int]]]:
        rows, cols = len(grid), len(grid[0])
        visited = [[False for _ in range(cols)] for _ in range(rows)]
        distances = [[0 for _ in range(cols)] for _ in range(rows)]
        q = deque([(start_row, start_col, 0)])

        while q:
            row, col, dist = q.popleft()
            for d_row, d_col in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                n_row, n_col = row + d_row, col + d_col
                if 0 <= n_row < rows and 0 <= n_col < cols and not visited[n_row][n_col] and grid[n_row][n_col] == 0:
                    visited[n_row][n_col] = True
                    distances[n_row][n_col] = dist + 1
                    q.append((n_row, n_col, dist + 1))

        return visited, distances

    rows, cols = len(grid), len(grid[0])
    total_distances = [[0 for _ in range(cols)] for _ in range(rows)]
    total_reachability = [[0 for _ in range(cols)] for _ in range(rows)]
    building_count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                building_count += 1
                visited, distances = bfs(r, c)
                for i in range(rows):
                    for j in range(cols):
                        if visited[i][j]:
                            total_distances[i][j] += distances[i][j]
                            total_reachability[i][j] += 1

    min_distance = float('inf')
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and total_reachability[r][c] == building_count:
                min_distance = min(min_distance, total_distances[r][c])

    return min_distance if min_distance != float('inf') else -1

