def prime_check(n: int) -> bool:
    """Returns True if n is a prime number, False otherwise."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_prime_digit_sum(n: int) -> bool:
    """
    Returns True if the sum of the digits of n is a prime number, False otherwise.
    """
    digit_sum = sum(int(digit) for digit in str(n))
    return prime_check(digit_sum)

def is_merge(s: str, part1: str, part2: str) -> bool:
    """
    Returns True if s can be formed by interleaving part1 and part2 while maintaining
    the order of characters in part1 and part2.
    """
    if len(s) != len(part1) + len(part2):
        return False

    # Create a memoization table to store results of subproblems
    memo = {}

    def dfs(i, j, k):
        if k == len(s):
            return i == len(part1) and j == len(part2)

        if (i, j) in memo:
            return memo[(i, j)]

        if i < len(part1) and part1[i] == s[k] and dfs(i + 1, j, k + 1):
            memo[(i, j)] = True
            return True

        if j < len(part2) and part2[j] == s[k] and dfs(i, j + 1, k + 1):
            memo[(i, j)] = True
            return True

        memo[(i, j)] = False
        return False

    return dfs(0, 0, 0)

