def two_sum_optimized(numbers, target):
    """
    This function uses two-pointers technique to find the indices of the two numbers
    that add up to the target. The input list is sorted in ascending order.
    """
    left, right = 0, len(numbers) - 1
    while left < right:
        current_sum = numbers[left] + numbers[right]
        if current_sum == target:
            return [left + 1, right + 1]
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return []

