from typing import List, Tuple

def find_sccs(graph: List[Tuple[int, int]], n: int) -> List[List[int]]:
    def tarjan_scc(v):
        nonlocal index
        index_map[v] = lowlink_map[v] = index
        index += 1
        stack.append(v)
        on_stack[v] = True

        for neighbor in adjacency_list[v]:
            if index_map[neighbor] is None:
                tarjan_scc(neighbor)
                lowlink_map[v] = min(lowlink_map[v], lowlink_map[neighbor])
            elif on_stack[neighbor]:
                lowlink_map[v] = min(lowlink_map[v], index_map[neighbor])

        if lowlink_map[v] == index_map[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack[w] = False
                scc.append(w)
                if w == v:
                    break
            sccs.append(sorted(scc))

    adjacency_list = [[] for _ in range(n)]
    for u, v in graph:
        adjacency_list[u].append(v)

    index = 0
    index_map = [None] * n
    lowlink_map = [None] * n
    stack = []
    on_stack = [False] * n
    sccs = []

    for v in range(n):
        if index_map[v] is None:
            tarjan_scc(v)

    return sccs

def longest_common_subsequence(s_1: str, s_2: str) -> int:
    """
    Returns the length of the longest common subsequence between two strings s_1 and s_2.
    """
    m, n = len(s_1), len(s_2)
    # Create a 2D array to store the lengths of longest common subsequence
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s_1[i - 1] == s_2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

def enhanced_magic_number(n: int):
    """
    Checks if a number is a magic number and returns details about the process.

    Parameters:
    n (int): The number to check.

    Returns:
    tuple: (is_magic: bool, iterations: int, sums: list)
    """

    # Handle cases where n is not an integer or it's a negative number
    if not isinstance(n, int) or n < 0:
        return (False, 0, [])

    # Helper function to sum the digits of a number
    def sum_digits(num):
        return sum(int(digit) for digit in str(num))

    sums = []
    iterations = 0

    while n >= 10:
        n = sum_digits(n)
        sums.append(n)
        iterations += 1

    is_magic = (n == 1)

    return (is_magic, iterations, sums)

