def pattern_match(pattern: str, string: str) -> bool:
    def backtrack(p_idx, s_idx, mapping, used):
        if p_idx == len(pattern) and s_idx == len(string):
            return True
        if p_idx == len(pattern) or s_idx == len(string):
            return False

        pattern_char = pattern[p_idx]

        for end in range(s_idx + 1, len(string) + 1):
            sub_str = string[s_idx:end]

            if pattern_char not in mapping and sub_str not in used:
                mapping[pattern_char] = sub_str
                used.add(sub_str)

                if backtrack(p_idx + 1, end, mapping, used):
                    return True

                del mapping[pattern_char]
                used.remove(sub_str)
            elif pattern_char in mapping and mapping[pattern_char] == sub_str:
                if backtrack(p_idx + 1, end, mapping, used):
                    return True

        return False

    return backtrack(0, 0, {}, set())

