from typing import List

def summarize_ranges(arr: List[int]) -> List[str]:
    """
    Summarizes all the continuous intervals in a sorted list of integers.
    """
    if not arr:
        return []

    ranges = []
    start = arr[0]
    end = arr[0]

    for i in range(1, len(arr)):
        if arr[i] == end + 1:
            end = arr[i]
        else:
            if start == end:
                ranges.append(str(start))
            else:
                ranges.append(f"{start}-{end}")
            start = arr[i]
            end = arr[i]

    if start == end:
        ranges.append(str(start))
    else:
        ranges.append(f"{start}-{end}")

    return ranges

