def combination_dp(n: int, r: int) -> int:
    """
    Computes the combination nCr using dynamic programming.

    :param n: Total number of items
    :param r: Number of items to be chosen
    :return: Number of ways to choose r items from n
    """
    if r > n:
        return 0
    if r == 0 or r == n:
        return 1

    dp = [[0 for _ in range(r + 1)] for _ in range(n + 1)]

    for i in range(n + 1):
        for j in range(min(i, r) + 1):
            # Base cases
            if j == 0 or j == i:
                dp[i][j] = 1
            else:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - 1][j]

    return dp[n][r]

