from typing import List

def gcd(a: int, b: int) -> int:
    """
    Computes the greatest common divisor using the bitwise Stein's algorithm.
    """
    if a == 0:
        return b
    if b == 0:
        return a

    # both a and b are nonzero
    if a < 0:
        a = -a
    if b < 0:
        b = -b

    # find common factors of 2
    shift = 0
    while (a | b) & 1 == 0:
        a >>= 1
        b >>= 1
        shift += 1

    while a & 1 == 0:
        a >>= 1

    while b != 0:
        while b & 1 == 0:
            b >>= 1
        if a > b:
            a, b = b, a
        b = b - a

    return a << shift

def optimized_gcd(nums: List[int]) -> int:
    """
    Computes the greatest common divisor of a list of integers using bitwise operations.
    """
    result = nums[0]
    for num in nums[1:]:
        result = gcd(result, num)
        if result == 1:
            break
    return result

