def reverse_sentence(sentence: str) -> str:
    """
    Returns a sentence with the words in reversed order,
    keeping the internal order of characters within each word unchanged.
    """
    # Split the sentence by whitespace while keeping the spaces
    words_with_spaces = []
    current_word = ''
    in_space = False

    for char in sentence:
        if char == ' ':
            if not in_space:
                if current_word:
                    words_with_spaces.append(current_word)
                current_word = ''
                in_space = True
            current_word += char
        else:
            if in_space:
                if current_word:
                    words_with_spaces.append(current_word)
                current_word = ''
                in_space = False
            current_word += char

    if current_word:
        words_with_spaces.append(current_word)

    # Reverse the collected list of words and spaces
    words_with_spaces.reverse()

    # Join the reversed list back into a single string
    return ''.join(words_with_spaces)

