def flatten(arr):
    """
    Flattens a nested list of integers into a single level list.
    """
    result = []
    for element in arr:
        if isinstance(element, list):
            result.extend(flatten(element))
        else:
            result.append(element)
    return result

def flatten_iter(arr):
    """
    Flattens a nested list of integers into a single level list using an iterator.
    """
    for element in arr:
        if isinstance(element, list):
            yield from flatten_iter(element)
        else:
            yield element

