def enhanced_fizzbuzz(n: int) -> tuple:
    """
    Generate a FizzBuzz sequence from 1 to N and count the occurrences of each unique output.

    :param n: int - The upper limit of the sequence.
    :return: tuple - A tuple containing the FizzBuzz list and a dictionary of occurrences.
    """

    fizzbuzz_list = []
    counts = {}

    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            value = "FizzBuzz"
        elif i % 3 == 0:
            value = "Fizz"
        elif i % 5 == 0:
            value = "Buzz"
        else:
            value = i

        fizzbuzz_list.append(value)
        if value in counts:
            counts[value] += 1
        else:
            counts[value] = 1

    return (fizzbuzz_list, counts)

