def flatten_array(nested_list: list) -> list:
    """
    Flattens a nested list into a single-level list.
    """
    def _flatten(arr, result):
        for item in arr:
            if isinstance(item, list):
                _flatten(item, result)
            else:
                result.append(item)
        return result

    return _flatten(nested_list, [])

# Optional: Generator version to produce a flat list lazily
def flatten_array_iter(nested_list: list):
    """
    Flattens a nested list into a single-level iterator.
    """
    for item in nested_list:
        if isinstance(item, list):
            yield from flatten_array_iter(item)
        else:
            yield item

