def is_magic_number(n: int) -> bool:
    """
    Determines if a number is a Magic Number.
    A Magic Number reduces to 1 after repeated summation of its digits.

    :param n: Integer number to check.
    :return: True if n is a Magic Number, False otherwise.
    """
    def sum_of_digits(num):
        """Helper function to sum the digits of a number."""
        return sum(int(digit) for digit in str(num))

    while n >= 10:
        n = sum_of_digits(n)

    return n == 1

def find_longest_unique_substring(input_string: str):
    """
    Function to find the longest substring without repeating characters.
    Returns a tuple with the length of the longest substring and the substring itself.
    """
    if not input_string:
        return (0, "")

    max_length = 0
    longest_substring = ""
    start_index = 0
    char_index_map = {}

    for i, char in enumerate(input_string):
        if char in char_index_map and char_index_map[char] >= start_index:
            start_index = char_index_map[char] + 1
        char_index_map[char] = i
        current_length = i - start_index + 1
        if current_length > max_length:
            max_length = current_length
            longest_substring = input_string[start_index:i + 1]

    return (max_length, longest_substring)

