def find_longest_common_prefix(strs):
    """
    Finds the longest common prefix string amongst an array of strings.
    If there is no common prefix, return an empty string.
    """

    if not strs:
        return ""

    # The longest possible prefix is the first string itself
    prefix = strs[0]

    for string in strs[1:]:
        while prefix and not string.startswith(prefix):
            # Reduce the prefix by one character at a time
            prefix = prefix[:-1]
        if not prefix:
            break

    return prefix

