def summarize_ranges(array: List[int]) -> List[str]:
    res = []
    if not array:
        return res

    start, end = array[0], array[0]

    for num in array[1:]:
        if num == end + 1:
            end = num
        else:
            if start == end:
                res.append(f"{start}")
            else:
                res.append(f"{start}-{end}")
            start, end = num, num

    if start == end:
        res.append(f"{start}")
    else:
        res.append(f"{start}-{end}")

    return res

