from typing import List

def ternary_search(arr: List[int], left: int, right: int, key: int) -> int:
    """
    Uses ternary search to find the index of key in the sorted list arr.
    If the key is found, returns its index. Otherwise, returns -1.
    """
    while left <= right:
        mid1 = left + (right - left) // 3
        mid2 = right - (right - left) // 3

        if arr[mid1] == key:
            return mid1
        if arr[mid2] == key:
            return mid2

        if key < arr[mid1]:
            right = mid1 - 1
        elif key > arr[mid2]:
            left = mid2 + 1
        else:
            left = mid1 + 1
            right = mid2 - 1

    return -1

