import math

def prime_check(n: int) -> bool:
    """
    Determine if `n` is a prime number.

    :param n: An integer number to check for primality.
    :return: True if `n` is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

from typing import List

def is_sorted_stack(stack: List[int]) -> bool:
    """
    Returns True if the stack is sorted in strictly ascending order from bottom to top,
    otherwise returns False. The stack is represented by a list, where index 0 is the bottom.
    """
    if not stack:
        return True

    for i in range(1, len(stack)):
        if stack[i - 1] >= stack[i]:
            return False

    return True

