from typing import List, Tuple

def search_in_matrix(matrix: List[List[int]], key: int) -> Tuple[int, int]:
    """
    Searches for a given key in a matrix where each row and each column are sorted in non-decreasing order.
    """
    if not matrix or not matrix[0]:
        return (-1, -1)

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1  # Start from the top-right corner

    while row < rows and col >= 0:
        if matrix[row][col] == key:
            return (row, col)
        elif matrix[row][col] > key:
            col -= 1
        else:
            row += 1

    return (-1, -1)

def hailstone_length(n: int) -> tuple:
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer")

    sequence = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        sequence.append(n)

    return len(sequence) - 1, sequence

