def find_difference(s: str, t: str) -> str:
    """
    Finds the letter that was added to t which is not in s.
    """
    # Initialize a variable to store the XOR result
    result = 0
    # Iterate over both strings and perform XOR operation on every character
    for char in s:
        result ^= ord(char)
    for char in t:
        result ^= ord(char)
    # The result will be the ASCII value of the added letter
    return chr(result)

