def min_deletion_steps(word1: str, word2: str) -> int:
    n = len(word1)
    m = len(word2)

    # dp[i][j] will be the length of the longest common subsequence of word1[:i] and word2[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    longest_common_subsequence_length = dp[n][m]

    return n + m - 2 * longest_common_subsequence_length

