def find_unique_numbers(nums: list[int]) -> list[int]:
    # Step 1: Perform XOR of all the elements. The result will be the XOR of the two unique numbers.
    xor_sum = 0
    for num in nums:
        xor_sum ^= num

    # Step 2: Find any set bit in the xor_sum (we can use the rightmost set bit).
    rightmost_set_bit = xor_sum & -xor_sum

    # Step 3: Divide the numbers into two groups based on the rightmost_set_bit and XOR the numbers in each group.
    unique1, unique2 = 0, 0
    for num in nums:
        if num & rightmost_set_bit:
            unique1 ^= num
        else:
            unique2 ^= num

    return [unique1, unique2]

