    # Step 2: Find the rightmost set bit in xor_all
    rightmost_set_bit = xor_all & -xor_all

    # Step 3: Divide elements into two groups and XOR separately
    num1, num2 = 0, 0
    for num in nums:
        if (num & rightmost_set_bit) == 0:
            num1 ^= num
        else:
            num2 ^= num

    return [num1, num2]

