def optimized_two_sum(nums: list[int], target: int) -> tuple[int, int]:
    """
    Function to find the indices of two numbers in a list that add up to a given target.
    This function assumes that there is exactly one solution and no element can be used twice.
    It uses a hash map to track the indices of the elements.
    """
    num_to_index = {}
    for i, num in enumerate(nums):
        # Calculate the complement of the current number
        complement = target - num
        # Check if the complement is already in the hashmap
        if complement in num_to_index:
            return (num_to_index[complement], i)
        # Add the number and its index to the hashmap
        num_to_index[num] = i
    # In case there is no solution, just to have a return although constraints dictate there is exactly one solution
    # But since the return type has to be of tuple[int, int], to avoid type errors:
    return (-1, -1)

