def min_cost_travel(matrix):
    """
    Returns the minimum cost to travel from station 0 to station N-1.
    """
    N = len(matrix)
    inf = float('inf')

    # Replace -1 with inf for easier calculation
    for i in range(N):
        for j in range(N):
            if matrix[i][j] == -1:
                matrix[i][j] = inf

    # Initialize a list to store the minimum cost to reach each station
    min_cost = [inf] * N
    min_cost[0] = 0  # Cost to reach the starting station is 0

    # Compute minimum costs
    for i in range(N):
        for j in range(i + 1, N):
            if min_cost[i] + matrix[i][j] < min_cost[j]:
                min_cost[j] = min_cost[i] + matrix[i][j]

    return min_cost[N - 1]

