def delete_nth(array, n):
    """
    Returns a new list containing each number of the given list at most N times without reordering the elements.
    """
    result = []
    counts = {}

    for num in array:
        if counts.get(num, 0) < n:
            result.append(num)
            counts[num] = counts.get(num, 0) + 1

    return result

