def summarize_ranges(array):
    """
    Takes a sorted list of integers and returns a list of strings representing the contiguous ranges found in the array.
    """
    if not array:
        return []

    result = []
    start = array[0]
    end = array[0]

    for i in range(1, len(array)):
        if array[i] == end + 1:
            end = array[i]
        else:
            if start == end:
                result.append(f"{start}")
            else:
                result.append(f"{start}-{end}")
            start = array[i]
            end = array[i]

    if start == end:
        result.append(f"{start}")
    else:
        result.append(f"{start}-{end}")

    return result

