def has_negative_cycle(graph, source):
    """
    Determines if the graph contains any negative weight cycles reachable from the given source vertex.
    """
    # Initialize distances from the source to all vertices as infinity and source to itself as 0
    dist = {vertex: float('inf') for vertex in graph}
    dist[source] = 0

    # Relax edges |V| - 1 times
    for _ in range(len(graph) - 1):
        for u in graph:
            for v in graph[u]:
                if dist[u] != float('inf') and dist[u] + graph[u][v] < dist[v]:
                    dist[v] = dist[u] + graph[u][v]

    # Check for negative-weight cycles
    for u in graph:
        for v in graph[u]:
            if dist[u] != float('inf') and dist[u] + graph[u][v] < dist[v]:
                return True

    return False

