from typing import List, Tuple, Dict
from collections import defaultdict, deque

def is_strongly_connected(n: int, edges: List[Tuple[int, int]]) -> bool:
    def build_graph(n: int, edges: List[Tuple[int, int]]) -> Dict[int, List[int]]:
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
        return graph

    def bfs(start: int, graph: Dict[int, List[int]]) -> bool:
        visited = set()
        queue = deque([start])
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        return len(visited) == n

    graph = build_graph(n, edges)
    reverse_graph = build_graph(n, [(v, u) for u, v in edges])

    # Check the graph is reachable from any node
    if not bfs(0, graph):
        return False

    # Check if the reverse graph is reachable from any node
    if not bfs(0, reverse_graph):
        return False

    return True

