def gcd_optimal(a, b):
    """
    Computes the GCD of two non-negative integers using bitwise operations.
    """
    if a == 0:
        return b
    if b == 0:
        return a

    # Both a and b are even
    if (a & 1) == 0 and (b & 1) == 0:
        return gcd_optimal(a >> 1, b >> 1) << 1

    # a is even, b is odd
    if (a & 1) == 0:
        return gcd_optimal(a >> 1, b)

    # a is odd, b is even
    if (b & 1) == 0:
        return gcd_optimal(a, b >> 1)

    # Both a and b are odd, a >= b
    if a >= b:
        return gcd_optimal((a - b) >> 1, b)

    # Both a and b are odd, b > a
    return gcd_optimal((b - a) >> 1, a)

def lcm_using_gcd(a, b):
    """
    Computes the LCM of two non-negative integers using the GCD calculated from gcd_optimal.
    """
    if a == 0 or b == 0:
        return 0
    return (a * b) // gcd_optimal(a, b)

def trailing_zero_bits(x):
    """
    Computes the number of trailing zero bits in the binary representation of a positive integer.
    """
    count = 0
    while (x & 1) == 0:
        x >>= 1
        count += 1
    return count

