def is_prime(n):
    """
    Check if a number is prime.
    Returns True if n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_primes(M):
    """
    Generate a list of all prime numbers up to a given number M (inclusive).
    """
    primes = []
    for num in range(2, M + 1):
        if is_prime(num):
            primes.append(num)
    return primes

