def find_added_letter(s: str, t: str) -> str:
    """
    Finds the additional letter in t that is not present in s.
    Both strings consist of lowercase letters.
    """
    result = 0
    for ch in s:
        result ^= ord(ch)
    for ch in t:
        result ^= ord(ch)
    return chr(result)

