def search_queries(arr, queries):
    """
    Searches for each query in arr and returns a dictionary with the index of each query in arr
    if found, otherwise -1.

    :param arr: List of integers to search within.
    :param queries: Set of integers to search for in arr.
    :return: Dictionary with each query and its index in arr or -1 if not found.
    """
    result = {}
    for q in queries:
        try:
            result[q] = arr.index(q)
        except ValueError:
            result[q] = -1
    return result

