def is_balanced(expression: str) -> bool:
    """
    Determine if the given expression has balanced parentheses.

    Args:
    expression (str): The input string containing parentheses.

    Returns:
    bool: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    matching_parenthesis = {')': '(', '}': '{', ']': '['}

    for char in expression:
        if char in "({[":
            stack.append(char)
        elif char in ")}]":
            if not stack or stack[-1] != matching_parenthesis[char]:
                return False
            stack.pop()

    return len(stack) == 0

