from typing import List

def search_range(nums: List[int], target: int) -> List[int]:
    """
    Finds the starting and ending positions of the target in the sorted array nums.
    If the target does not exist, returns [-1, -1].
    """
    def find_bound(is_first):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                if is_first:
                    # Continue searching in the left half
                    if mid == left or nums[mid - 1] < target:
                        return mid
                    right = mid - 1
                else:
                    # Continue searching in the right half
                    if mid == right or nums[mid + 1] > target:
                        return mid
                    left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    start = find_bound(True)
    if start == -1:
        return [-1, -1]  # Target not found
    end = find_bound(False)

    return [start, end]

