from typing import List, Tuple

def num_islands_after_operations(m: int, n: int, positions: List[Tuple[int, int]]) -> List[int]:
    if not m or not n:
        return []

    parent = {}
    rank = {}
    count = 0

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        nonlocal count
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                parent[rootY] = rootX
            elif rank[rootX] < rank[rootY]:
                parent[rootX] = rootY
            else:
                parent[rootY] = rootX
                rank[rootX] += 1
            count -= 1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    res = []

    for r, c in positions:
        if (r, c) in parent:
            res.append(count)
            continue

        parent[(r, c)] = (r, c)
        rank[(r, c)] = 0
        count += 1

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and (nr, nc) in parent:
                union((r, c), (nr, nc))

        res.append(count)

    return res

