def gnome_sort_extended(arr, ascending=True):
    pos = 0
    while pos < len(arr):
        if pos == 0 or (ascending and arr[pos] >= arr[pos - 1]) or (not ascending and arr[pos] <= arr[pos - 1]):
            pos += 1
        else:
            arr[pos], arr[pos - 1] = arr[pos - 1], arr[pos]
            pos -= 1
    return arr

