def sum_dig_pow(low, high):
    """
    Finds and returns all numbers within the range [low, high] that can be expressed
    as the sum of their digits each raised to the power of its position.
    """
    def is_eureka_number(n):
        digits = list(map(int, str(n)))
        return n == sum(d ** (i + 1) for i, d in enumerate(digits))

    result = []
    for number in range(low, high + 1):
        if is_eureka_number(number):
            result.append(number)

    return result

