from collections import deque

def bfs(level, capacity, source, sink, n):
    visited = [False] * n
    queue = deque([source])
    visited[source] = True
    level[source] = 0

    while queue:
        node = queue.popleft()
        for i in range(n):
            if not visited[i] and capacity[node][i]:
                queue.append(i)
                visited[i] = True
                level[i] = level[node] + 1

    return visited[sink]

def dfs(flow, capacity, level, start, sink, n):
    if start == sink:
        return flow
    for i in range(n):
        if level[i] == level[start] + 1 and capacity[start][i] > 0:
            min_flow_through_node = min(flow, capacity[start][i])
            flow_through_path = dfs(min_flow_through_node, capacity, level, i, sink, n)
            if flow_through_path > 0:
                capacity[start][i] -= flow_through_path
                capacity[i][start] += flow_through_path
                return flow_through_path
    return 0

def compute_max_flow(capacity, source, sink):
    n = len(capacity)
    level = [0] * n
    max_flow = 0

    while bfs(level, capacity, source, sink, n):
        while True:
            flow = dfs(float('Inf'), capacity, level, source, sink, n)
            if flow == 0:
                break
            max_flow += flow

    return max_flow

