from typing import List

def combination_sum(nums: List[int], target: int) -> int:
    # Create a list to store the number of combinations for each value up to target
    dp = [0] * (target + 1)

    # There is one combination to make a sum of 0, which is to use none of the elements
    dp[0] = 1

    # Iterate through all possible targets from 1 to target
    for t in range(1, target + 1):
        for num in nums:
            if t - num >= 0:
                dp[t] += dp[t - num]

    return dp[target]

