def detect_cycle(graph):
    """
    Function to detect a cycle in a directed graph using DFS.
    :param graph: Dict[str, List[str]] - The directed graph represented as an adjacency list
    :return: bool - True if there is a cycle, False otherwise
    """
    visited = set()
    rec_stack = set()

    def dfs(node):
        if node in rec_stack:
            return True
        if node in visited:
            return False

        visited.add(node)
        rec_stack.add(node)

        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        rec_stack.remove(node)
        return False

    for node in graph:
        if node not in visited:
            if dfs(node):
                return True

    return False

