def find_special_numbers(N: int):
    def sum_of_digits_raised_to_consecutive_powers(num):
        str_num = str(num)
        return sum(int(str_num[i]) ** (i + 1) for i in range(len(str_num)))

    special_numbers = []
    for i in range(1, N + 1):
        if i == sum_of_digits_raised_to_consecutive_powers(i):
            special_numbers.append(i)

    return special_numbers

