import importlib
import sys

def import_module_custom(module_name, reload=False):
    """
    Imports a module by its name. Optionally reloads the module if it is already imported.

    Parameters:
    - module_name (str): The name of the module to be imported.
    - reload (bool): A boolean flag indicating whether to reload the module if it's already imported.

    Returns:
    - module: The imported or reloaded module object, or None if the import/reload failed.
    """
    try:
        if module_name in sys.modules and reload:
            # Reload the module if it is already imported
            return importlib.reload(sys.modules[module_name])
        else:
            # Import the module
            return importlib.import_module(module_name)
    except Exception:
        return None

import contextvars

def record_user_action(initial_context, actions):
    context_vars = {}
    tokens = {}

    # Initialize context variables with the initial context.
    for key, value in initial_context.items():
        context_vars[key] = contextvars.ContextVar(key, default=value)

    # Perform actions.
    for action_name, context_var_name, value in actions:
        if action_name == 'set':
            tokens[context_var_name] = context_vars[context_var_name].set(value)
        elif action_name == 'reset':
            context_vars[context_var_name].reset(tokens[context_var_name])

    # Generate the final context state.
    final_state = {key: var.get() for key, var in context_vars.items()}

    return final_state

