def merge_dictionaries(dict1: dict, dict2: dict) -> dict:
    merged_dict = dict1.copy()

    for key, value in dict2.items():
        if key in merged_dict:
            if isinstance(merged_dict[key], (int, float)) and isinstance(value, (int, float)):
                merged_dict[key] += value
            elif isinstance(merged_dict[key], list) and isinstance(value, list):
                merged_dict[key].extend(value)
            elif isinstance(merged_dict[key], str) and isinstance(value, str):
                merged_dict[key] += value
            elif isinstance(merged_dict[key], list) and not isinstance(value, list):
                merged_dict[key].append(value)
            elif not isinstance(merged_dict[key], list) and isinstance(value, list):
                if merged_dict[key] is not None:
                    value.insert(0, merged_dict[key])
                merged_dict[key] = value
            else:
                merged_dict[key] = value
        else:
            merged_dict[key] = value

    return merged_dict

