def summarize_items(data, n):
    """
    Returns a summary of the top n items based on their occurrences, after filtering
    out items containing the letter 'a'.
    """
    # Filter items and flatten the list
    flattened_items = [
        item for person in data for item in person['items'] if 'a' not in item
    ]

    # Count occurrences of each item
    item_counts = {}
    for item in flattened_items:
        if item in item_counts:
            item_counts[item] += 1
        else:
            item_counts[item] = 1

    # Convert to list of tuples and sort by count (descending) and then by item (alphabetical)
    sorted_items = sorted(item_counts.items(), key=lambda x: (-x[1], x[0]))

    # Extract top n items
    return sorted_items[:n]

