from email import message_from_string
from email.message import Message
from email.policy import default

def parse_and_modify_email(raw_email: str) -> str:
    msg = message_from_string(raw_email, policy=default)

    # Change the subject of the email to "Modified Subject"
    msg['Subject'] = 'Modified Subject'

    # Function to modify each part
    def modify_part(part):
        part.add_header('X-Modified', 'True')
        if part.get_content_type() == 'text/plain':
            part.set_payload(part.get_payload() + "\nThis is modified")

    # Check if the message is multipart
    if msg.is_multipart():
        for part in msg.iter_parts():
            modify_part(part)
    else:
        modify_part(msg)

    # Return the modified message as a string
    return msg.as_string()

import traceback

def analyze_traceback(code: str) -> dict:
    """
    Executes the given code and analyzes any traceback if an exception occurs.

    Parameters:
    code (str): The python code to execute.

    Returns:
    dict: A dictionary containing type, message, traceback, and formatted exception details.
    """
    try:
        exec(code)
        return {"type": None, "message": None, "traceback": None, "formatted": None}
    except Exception as e:
        tb_str = traceback.format_exc()
        return {
            "type": type(e).__name__,
            "message": str(e),
            "traceback": ''.join(traceback.format_tb(e.__traceback__)),
            "formatted": tb_str
        }

