def set_operations(commands: list) -> set:
    """
    Executes a series of set operations based on the given commands.

    Parameters:
    commands (list): A list of tuples, where each tuple represents a command and its arguments.

    Returns:
    set: The final state of the set after all operations are performed.
    """
    s = set()

    for command in commands:
        operation = command[0]

        try:
            if operation == "add":
                s.add(command[1])
            elif operation == "discard":
                s.discard(command[1])
            elif operation == "pop":
                s.pop()
            elif operation == "clear":
                s.clear()
            elif operation == "contains":
                if command[1] in s:
                    print(f"{command[1]} is in the set")
                else:
                    print(f"{command[1]} is not in the set")
            else:
                raise ValueError("Invalid operation")

        except TypeError as e:
            print(f"TypeError: {e}")
        except MemoryError as e:
            print(f"MemoryError: {e}")
        except KeyError as e:
            print(f"KeyError: {e}")

    return s

tests:
def test_set_operations():
    commands = [
        ("add", 1),
        ("add", 2),
        ("contains", 2),
        ("discard", 1),
        ("add", 3),
        ("pop",),
    ]
    result = set_operations(commands)
    assert result == {2, 3} or result == {3}  # Popping may vary

    commands = [
        ("add", "a"),
        ("add", "b"),
        ("clear",),
        ("add", "c"),
    ]
    result = set_operations(commands)
    assert result == {"c"}

    commands = [
        ("add", 1),
        ("discard", 2),
        ("pop",),
    ]
    result = set_operations(commands)
    assert result == set()  # Popping the only element results in an empty set

    commands = [
        ("add", 1),
        ("discard", 1),
        ("discard", 1),
    ]
    result = set_operations(commands)
    assert result == set()

def test_set_operations_with_invalid_operation():
    commands = [
        ("add", 1),
        ("invalid", 2),
    ]
    try:
        result = set_operations(commands)
    except ValueError as e:
        assert str(e) == "Invalid operation"

def test_set_operations_with_TypeErrors():
    commands = [
        ("add", None),
    ]
