    global sum_data
    sum_data = 0
    if not data:
        raise ValueError("The data list cannot be empty.")
    if not all(isinstance(i, int) for i in data):
        raise ValueError("All elements in the data list must be integers.")
    for num in data:
        sum_data += num
    assert sum_data > 5, "The sum of data elements is not greater than the threshold."
    import math
    return math.sqrt(sum_data)

