from email.charset import Charset

def encode_email_content(input_string: str, input_charset: str, is_header: bool, is_body: bool) -> str:
    """
    Encode the input string based on the character set and flags for header or body.
    """
    charset = Charset(input_charset)

    if is_body:
        return charset.body_encode(input_string)
    elif is_header:
        return charset.header_encode(input_string)

    return input_string  # Default case if no flags are set; this should not happen based on the constraints.

def generate_setup_cfg(config: dict) -> str:
    """
    Converts a given dictionary to the setup.cfg file format.

    Args:
    config (dict): A dictionary containing sections and their options.

    Returns:
    str: A string representation of the setup.cfg file.
    """
    lines = []
    for section, options in config.items():
        lines.append(f'[{section}]')
        for option, value in options.items():
            if isinstance(value, list):
                lines.append(f'{option}={value[0]}')
                for item in value[1:]:
                    lines.append(f' {" " * len(option)} {item}')
            else:
                lines.append(f'{option}={value}')
        lines.append('')  # Blank line between sections

    return '\n'.join(lines)

