def custom_int_conversion(value, target_type):
    """
    Convert various integer types to Python integers.

    Args:
        value (int): The integer value to be converted.
        target_type (str): The target C type, e.g., "long", "unsigned_long", etc.

    Returns:
        int: The converted Python integer.

    Raises:
        OverflowError: If the value is out of range for the specified target type.
        ValueError: If the target_type is not recognized.
    """
    import sys

    if target_type == "long":
        return int(value)
    elif target_type == "unsigned_long":
        if value < 0:
            raise OverflowError("value cannot be negative for unsigned_long")
        return int(value)
    elif target_type == "long_long":
        return int(value)
    elif target_type == "unsigned_long_long":
        if value < 0:
            raise OverflowError("value cannot be negative for unsigned_long_long")
        return int(value)
    elif target_type == "ssize_t":
        if value < -sys.maxsize - 1 or value > sys.maxsize:
            raise OverflowError("value out of range for ssize_t")
        return int(value)
    elif target_type == "size_t":
        if value < 0 or value > sys.maxsize * 2 + 1:
            raise OverflowError("value out of range for size_t")
        return int(value)
    else:
        raise ValueError(f"unrecognized target_type: {target_type}")

def process_list_operations(lst, operations):
    """
    Processes a list of operations on the given list.

    Args:
    lst: The list to be manipulated.
    operations: A list of operations where each operation is a tuple.

    Returns:
    The modified list after performing all operations, or None if any operation fails.
    """
    try:
        for op in operations:
            if op[0] == 'append':
                lst.append(op[1])
            elif op[0] == 'insert':
                lst.insert(op[1], op[2])
            elif op[0] == 'set_item':
                lst[op[1]] = op[2]
            elif op[0] == 'get_item':
                _ = lst[op[1]]  # We're ignoring the value here as mentioned
            elif op[0] == 'sort':
                lst.sort()
            elif op[0] == 'reverse':
                lst.reverse()
            elif op[0] == 'set_slice':
                lst[op[1]:op[2]] = op[3]
            elif op[0] == 'get_slice':
                _ = lst[op[1]:op[2]]  # We're ignoring the value here as mentioned
            else:
                return None  # Unknown operation
        return lst
    except:
        return None

