def process_data(data: str) -> dict:
    """
    Process a string of assignments and return a dictionary of variable values.
    """
    variables = {}

    for line in data.split('\n'):
        line = line.split('#')[0].strip()  # Remove comments and whitespace
        if not line:
            continue

        try:
            var, expr = line.split('=')
            var = var.strip()
            expr = expr.strip()

            # Evaluate the expression in the context of the variables dictionary
            # Using eval is risky, however we assume input is given as problem constraints.
            variables[var] = eval(expr, {}, variables)
        except Exception as e:
            print(f"Error processing line: {line}\n{e}")

    return variables

import xml.parsers.expat

def parse_books_xml(xml_string):

    def start_element(name, attrs):
        nonlocal current_element
        if name == 'book':
            current_book['title'] = ''
            current_book['author'] = ''
        current_element = name

    def end_element(name):
        nonlocal current_element
        if name == 'book':
            books.append(current_book.copy())
        current_element = None

    def char_data(data):
        if current_element == 'title':
            current_book['title'] += data
        elif current_element == 'author':
            current_book['author'] += data

    books = []
    current_book = {'title': '', 'author': ''}
    current_element = None

    try:
        parser = xml.parsers.expat.ParserCreate()
        parser.StartElementHandler = start_element
        parser.EndElementHandler = end_element
        parser.CharacterDataHandler = char_data

        parser.buffer_size = 4096
        parser.buffer_text = True

        parser.Parse(xml_string, True)

    except xml.parsers.expat.ExpatError:
        # If there is a parsing error, return an empty list
        return []

    return books

import dbm

def manage_users_db(action: str, username: str = None, email: str = None, db_filename: str = "users_db"):
    try:
        with dbm.open(db_filename, 'c') as db:
            if action == "add":
                if username and email:
                    db[username.encode()] = email.encode()
                    return "User added or updated successfully."
                else:
                    return "Username and email required for adding or updating a user."

            elif action == "get":
                if username:
                    return db.get(username.encode()).decode() if username.encode() in db else None
                else:
                    return "Username required for retrieving email."

            elif action == "delete":
                if username:
                    if username.encode() in db:
                        del db[username.encode()]
                        return "User deleted successfully."
                    else:
                        return "User not found."
                else:
                    return "Username required for deleting a user."

            elif action == "list":
                return [key.decode() for key in db.keys()]

            else:
                return "Invalid action."

    except Exception as e:
        return str(e)

