def custom_set_utility(commands):
    results = []
    sets_map = {}

    for command in commands:
        if command[0] == 'create_set':
            new_set = set(command[1])
            set_id = id(new_set)
            sets_map[set_id] = new_set
            results.append((set_id, len(new_set)))

        elif command[0] == 'create_frozenset':
            new_frozenset = frozenset(command[1])
            frozenset_id = id(new_frozenset)
            sets_map[frozenset_id] = new_frozenset
            results.append((frozenset_id, len(new_frozenset)))

        elif command[0] == 'add':
            set_obj = sets_map[command[1]]
            set_obj.add(command[2])
            results.append(len(set_obj))

        elif command[0] == 'discard':
            set_obj = sets_map[command[1]]
            result = command[2] in set_obj
            set_obj.discard(command[2])
            results.append(result)

        elif command[0] == 'contains':
            set_obj = sets_map[command[1]]
            result = command[2] in set_obj
            results.append(result)

        elif command[0] == 'pop':
            set_obj = sets_map[command[1]]
            try:
                result = set_obj.pop()
                results.append(result)
            except KeyError:
                results.append(KeyError)

        elif command[0] == 'clear':
            set_obj = sets_map[command[1]]
            set_obj.clear()
            results.append(len(set_obj))

    return results

