def complex_data_parser(data: list) -> tuple:
    """
    Parses a list of mixed data types and categorizes them into different formats.

    Args:
    data (list): A list containing various data types such as strings, integers, floats, and bytes.

    Returns:
    tuple: A tuple containing the parsed data categorized into strings, integers, floats, and bytes-like objects.
    """
    strings = []
    integers = []
    floats = []
    bytes_objects = []

    for item in data:
        if isinstance(item, str):
            strings.append(item)
        elif isinstance(item, int):
            integers.append(item)
        elif isinstance(item, float):
            floats.append(item)
        elif isinstance(item, bytes):
            bytes_objects.append(item)

    return (strings, integers, floats, bytes_objects)

def uppercase_first_last_name(first_name, last_name):
    """
    Returns the first and last names with the first letter uppercase.
    """
    if not first_name or not isinstance(first_name, str):
        raise ValueError("Invalid first name")
    if not last_name or not isinstance(last_name, str):
        raise ValueError("Invalid last name")
    return first_name.capitalize(), last_name.capitalize()

