def sum_list(int_list):
    """
    Returns the sum of the integers in the list.
    """
    if not isinstance(int_list, list):
        raise TypeError("Argument must be a list")

    total = 0
    for item in int_list:
        if not isinstance(item, int):
            raise ValueError("List items must all be integers")
        total += item

    return total

def custom_slice(sequence, start, stop, step):
    """
    Mimic slice behavior for a custom sequence.

    :param sequence: List or similar sequence type.
    :param start: Starting index of the slice.
    :param stop: Stopping index of the slice.
    :param step: Step/increment of the slice.
    :return: A sliced portion of the sequence based on start, stop, and step.
    """
    if step is None:
        step = 1
    if step == 0:
        raise ValueError("slice step cannot be zero")

    n = len(sequence)

    if start is None:
        start = 0 if step > 0 else n - 1
    if stop is None:
        stop = n if step > 0 else -1 if n == 0 else -n - 1

    if start < 0:
        start += n
    if stop < 0:
        stop += n

    result = []
    index = start

    if step > 0:
        while index < stop and index < n:
            if index >= 0:
                result.append(sequence[index])
            index += step
    else:
        while index > stop and index >= 0:
            if index < n:
                result.append(sequence[index])
            index += step

    return result

