import sys
import io

def interpret_python_input(input_type: str, input_content: str) -> str:
    try:
        # Redirect standard output to capture print statements
        old_stdout = sys.stdout
        sys.stdout = io.StringIO()

        if input_type == "complete_program":
            exec(input_content)
        elif input_type == "file_input":
            exec(input_content)
        elif input_type == "interactive_input":
            lines = input_content.splitlines()
            for line in lines:
                if line.strip():
                    exec(line)
        elif input_type == "expression_input":
            result = eval(input_content)
            return str(result)
        else:
            return "Invalid input type"

        # Capture all printed output
        sys.stdout.seek(0)
        output = sys.stdout.read()
        return output.strip()

    except Exception as e:
        return f"Error: {e}"

    finally:
        # Reset standard output to its original value
        sys.stdout = old_stdout

