import importlib.metadata
from typing import List, Dict

def analyze_installed_packages(requirement: str) -> dict:
    result = {}

    for dist in importlib.metadata.distributions():
        try:
            dist_name = dist.metadata['Name']
            dist_version = dist.version
            requires = dist.metadata.get_all('Requires-Dist', [])
            if any(requirement in req for req in requires):
                # Entry points
                entry_points = [
                    ep.name for ep in dist.entry_points if ep.group == 'console_scripts'
                ]
                # Total file size
                total_file_size = sum(
                    file.size for file in dist.files if file.size is not None
                )

                result[dist_name] = {
                    "version": dist_version,
                    "entry_points": entry_points,
                    "total_file_size": total_file_size
                }
        except Exception as e:
            # Handle the exception gracefully, which could occur in the distributed metadata load.
            continue

    return result

