from typing import List, Dict, Any
from collections import Counter

def http_status_analyzer(status_codes: List[int]) -> Dict[str, Any]:
    categories = {
        "Informational": range(100, 200),
        "Success": range(200, 300),
        "Redirection": range(300, 400),
        "Client Error": range(400, 500),
        "Server Error": range(500, 600),
    }

    summary = {}

    for category in categories:
        filtered_codes = [code for code in status_codes if code in categories[category]]
        count = len(filtered_codes)
        most_frequent = None if count == 0 else Counter(filtered_codes).most_common(1)[0][0]

        summary[category] = {
            "count": count,
            "most_frequent": most_frequent
        }

    return summary

