import cmath

def complex_operations(c1, c2, operation, convert_to_python=True):
    """
    Perform operations on complex numbers and convert between Python and C-style representations.

    Parameters:
    c1: tuple of floats (representing a complex number)
    c2: tuple of floats (representing a complex number)
    operation: str ("sum", "diff", "prod", "quot", "pow")
    convert_to_python: bool (if True, return Python complex number object; otherwise, return C struct)

    Returns:
    complex number in the desired representation
    """

    def to_python_complex(c):
        """Convert C-style complex number to Python complex type."""
        return complex(c[0], c[1])

    def to_c_complex(z):
        """Convert Python complex type to C-style complex number."""
        return (z.real, z.imag)

    # Convert to Python complex types for easier arithmetic operation
    z1 = to_python_complex(c1)
    z2 = to_python_complex(c2)

    if operation == "sum":
        result = z1 + z2
    elif operation == "diff":
        result = z1 - z2
    elif operation == "prod":
        result = z1 * z2
    elif operation == "quot":
        if z2 == 0:
            raise ZeroDivisionError("Cannot divide by zero")
        result = z1 / z2
    elif operation == "pow":
        result = z1 ** z2
    else:
        raise ValueError("Invalid operation")

    if convert_to_python:
        return result
    else:
        return to_c_complex(result)

