import getopt

def parse_command_line_arguments(args):
    options = {
        'help': False,
        'verbose': False,
        'logfile': None
    }
    try:
        opts, _ = getopt.getopt(args, 'hvl:', ['help', 'verbose', 'logfile='])
        for opt, arg in opts:
            if opt in ('-h', '--help'):
                options['help'] = True
            elif opt in ('-v', '--verbose'):
                options['verbose'] = True
            elif opt in ('-l', '--logfile'):
                options['logfile'] = arg
    except getopt.GetoptError as err:
        raise getopt.GetoptError(f"Error parsing arguments: {err}")
    return options

