import pwd

def get_user_info(parameter):
    try:
        if isinstance(parameter, int):
            user_info = pwd.getpwuid(parameter)
        elif isinstance(parameter, str):
            user_info = pwd.getpwnam(parameter)
        else:
            return None
        return {
            'name': user_info.pw_name,
            'passwd': user_info.pw_passwd,
            'uid': user_info.pw_uid,
            'gid': user_info.pw_gid,
            'gecos': user_info.pw_gecos,
            'dir': user_info.pw_dir,
            'shell': user_info.pw_shell
        }
    except KeyError:
        return None

