import traceback

def custom_traceback_handler(code_block: callable) -> str:
    try:
        code_block()
        return ""
    except Exception as e:
        tb = e.__traceback__
        tb_exc = traceback.TracebackException(type(e), e, tb, capture_locals=True)

        formatted_traceback = "".join(tb_exc.format())
        return formatted_traceback

