def create_distributions(setup_path, formats):
    for fmt in formats:
        try:
            print(f"Creating {fmt} distribution...", end=' ')
            result = subprocess.run(
                ["python", setup_path, "sdist", "--formats", fmt],
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                text=True
            )
            print("Success")
