import keyword

def analyze_keywords(words):
    """
    Analyzes a list of strings to determine if they are Python keywords, soft keywords, or neither.
    """
    result = {}

    for word in words:
        is_kw = keyword.iskeyword(word)
        is_skw = keyword.issoftkeyword(word)

        if is_kw:
            kw_type = "keyword"
        elif is_skw:
            kw_type = "soft_keyword"
        else:
            kw_type = "neither"

        result[word] = {
            "is_keyword": is_kw,
            "is_soft_keyword": is_skw,
            "keyword_type": kw_type
        }

    return result

