def process_data(students: dict, increment: int, threshold: int, remove_student: str = None) -> dict:
    # Increase each student's grade by the specified increment
    for student in students:
        students[student] += increment

    # Remove students whose grades fall below the threshold
    students = {student: grade for student, grade in students.items() if grade >= threshold}

    # If a student's name is specified, remove this student from the dictionary
    if remove_student:
        if remove_student in students:
            del students[remove_student]

    # Use assert statement to ensure dictionary is not empty
    if not students:
        raise ValueError("No students left after processing")

    return students

