import math

def is_prime(n: int) -> bool:
    """
    Returns True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def prime_generator(numbers: list):
    """
    Generator that yields prime numbers from the given list of numbers.
    """
    for number in numbers:
        if is_prime(number):
            yield number

def sum_of_primes(numbers: list, N: int) -> int:
    """
    Returns the sum of the first N prime numbers generated from the numbers list.
    """
    primes = prime_generator(numbers)
    total = 0
    count = 0
    for prime in primes:
        total += prime
        count += 1
        if count == N:
            break
    return total

def process_nested_dict(data: dict) -> list:
    """
    Transforms a nested dictionary into a list of tuples, where each tuple contains a key path
    and an integer value.
    """
    result = []

    def recurse(current, path):
        if isinstance(current, dict):
            for k, v in current.items():
                if v is not None:  # Ignore None values
                    recurse(v, path + '.' + k if path else k)
        else:
            result.append((path, current))

    recurse(data, '')
    return result

