import secrets
import string

def generate_password(length: int, criteria: str) -> str:
    if not (8 <= length <= 128):
        raise ValueError("Password length must be between 8 and 128.")
    if criteria not in ["alphanumeric", "complex"]:
        raise ValueError("Invalid criteria. Must be 'alphanumeric' or 'complex'.")

    if criteria == "alphanumeric":
        characters = string.ascii_letters + string.digits
    elif criteria == "complex":
        characters = string.ascii_letters + string.digits + string.punctuation

    while True:
        password = ''.join(secrets.choice(characters) for _ in range(length))
        if criteria == "complex":
            if (any(c.islower() for c in password) and
                any(c.isupper() for c in password) and
                any(c.isdigit() for c in password) and
                any(c in string.punctuation for c in password)):
                break
        else:
            break

    return password

def generate_security_token(token_type: str, nbytes: int = None) -> str:
    if nbytes is not None and not (1 <= nbytes <= 64):
        raise ValueError("Number of bytes must be between 1 and 64.")

    if token_type == "hex":
        return secrets.token_hex(nbytes if nbytes else 32)
    elif token_type == "urlsafe":
        return secrets.token_urlsafe(nbytes if nbytes else 32)
    else:
        raise ValueError("Invalid token type. Must be 'hex' or 'urlsafe'.")

