from typing import List, Dict, Any, Tuple
from functools import reduce

def student_statistics(records: List[Dict[str, Any]], threshold: int) -> Dict[str, Tuple[float, List[int]]]:
    def calculate_average(scores):
        return reduce(lambda x, y: x + y, scores) / len(scores)

    def filter_and_sort(scores):
        return sorted(score for score in scores if score >= threshold)

    result = {}
    for record in records:
        name = record['name']
        scores = record['scores']
        average = calculate_average(scores)
        filtered_sorted_scores = filter_and_sort(scores)
        result[name] = (average, filtered_sorted_scores)

    return result

