    return {user.pw_uid: user.pw_name for user in pwd.getpwall()}

def process_objects(sequence):
    from collections import defaultdict

    # Initialize the results dictionary
    results = {
        "type_count": defaultdict(int),
        "integers": [],
        "upper_strings": [],
        "any_float_above_100": False
    }

    # Define a function to return the type name as string
    def get_type_name(obj):
        return type(obj).__name__

    # Process each object in the sequence
    for obj in sequence:
        type_name = get_type_name(obj)
        results["type_count"][type_name] += 1

        if type_name == "int":
            results["integers"].append(obj)
        elif type_name == "str":
            results["upper_strings"].append(obj.upper())
        elif type_name == "float" and obj > 100.0:
            results["any_float_above_100"] = True

    return results

