import urllib.request
import urllib.error

def fetch_html_content(url: str, user_agent: str) -> str:
    """
    Fetches the HTML content of a given URL with a custom User-Agent header.

    Args:
    url (str): The URL of the web resource to fetch.
    user_agent (str): The user agent string to add in the request headers.

    Returns:
    str: The HTML content of the URL or an error message.
    """
    req = urllib.request.Request(url, headers={'User-Agent': user_agent})

    try:
        with urllib.request.urlopen(req) as response:
            return response.read().decode('utf-8')
    except urllib.error.HTTPError as e:
        if e.code == 404:
            return "Error 404: The resource could not be found."
        elif e.code == 403:
            return "Error 403: Access to the resource is forbidden."
        elif e.code == 401:
            return "Error 401: Authorization required."
        else:
            return f"HTTP Error: {e.code}"
    except urllib.error.URLError as e:
        return f"URL Error: {e.reason}"

import hashlib

def generate_hash(message: str, algorithm: str, salt: str = '', key: str = '', digest_size: int = None) -> str:
    """
    Generates a hash for the given message using the specified algorithm, with optional salt, key, and digest size.

    Parameters:
    - message (str): The input message to be hashed.
    - algorithm (str): The name of the hashing algorithm (e.g., 'sha256', 'sha512', 'md5', 'blake2b').
    - salt (str, optional): A salt value to randomize the hash output (default is an empty string).
    - key (str, optional): A key for keyed hashing (default is an empty string).
    - digest_size (int, optional): The size of the output digest in bytes (default is None).

    Returns:
    - str: The hexadecimal digest of the hash.
    """
    message_bytes = message.encode()
    salt_bytes = salt.encode()
    key_bytes = key.encode()

    if algorithm in hashlib.algorithms_guaranteed:
        if algorithm.startswith('blake2'):
            if digest_size is not None:
                if digest_size <= 0 or digest_size > hashlib.blake2b.MAX_DIGEST_SIZE:
                    raise ValueError('Invalid digest size')
            digest_size = digest_size or hashlib.blake2b().digest_size
            hash_obj = hashlib.new(algorithm, message_bytes, salt=salt_bytes, key=key_bytes, digest_size=digest_size)
        else:
            if key or salt:
                raise ValueError(f"The {algorithm} algorithm does not support salt or key.")
            if digest_size:
                raise ValueError(f"The {algorithm} algorithm does not support custom digest size.")
            hash_obj = hashlib.new(algorithm, message_bytes)
    else:
        raise ValueError(f"Unsupported algorithm: {algorithm}")

    return hash_obj.hexdigest()

