import difflib

def generate_diff_report(fromfile: str, tofile: str, format: str) -> str:
    try:
        with open(fromfile, 'r', encoding='utf-8') as f:
            fromlines = f.readlines()
        with open(tofile, 'r', encoding='utf-8') as f:
            tolines = f.readlines()
    except (FileNotFoundError, IOError) as e:
        return f"Error: {str(e)}"

    if format == 'context':
        diff = difflib.context_diff(fromlines, tolines, fromfile=fromfile, tofile=tofile, n=3)
    elif format == 'unified':
        diff = difflib.unified_diff(fromlines, tolines, fromfile=fromfile, tofile=tofile, n=3)
    elif format == 'html':
        diff = difflib.HtmlDiff().make_file(fromlines, tolines, fromfile, tofile)
        return diff
    else:
        return "Error: Unsupported format specified."

    return ''.join(diff)

