from typing import List, Dict, Union
import ipaddress

def summarize_ip_info(ip_addresses: List[str]) -> Dict[str, Union[str, int]]:
    ipv4_count = 0
    ipv6_count = 0
    network_dict = {}

    for ip in ip_addresses:
        ip_obj = ipaddress.ip_address(ip)
        if ip_obj.version == 4:
            ipv4_count += 1
            network = ipaddress.IPv4Network(ip + "/24", strict=False)
        else:
            ipv6_count += 1
            network = ipaddress.IPv6Network(ip + "/96", strict=False)

        network_str = str(network)
        if network_str in network_dict:
            network_dict[network_str] += 1
        else:
            network_dict[network_str] = 1

    # Find the largest network
    largest_network = max(network_dict, key=network_dict.get)

    return {
        "total_ipv4": ipv4_count,
        "total_ipv6": ipv6_count,
        "networks": list(network_dict.keys()),
        "largest_network": largest_network
    }

import xml.parsers.expat

def parse_library(xml_data: str) -> dict:
    """
    Parse the given XML data and return a dictionary mapping genres to lists of books.
    """
    parsed_data = {}
    current_book = {}
    current_element = None
    current_genre = None

    def start_element(name, attrs):
        nonlocal current_element
        if name == 'book':
            current_book.clear()
        current_element = name

    def end_element(name):
        nonlocal current_genre, current_element
        if name == 'book' and current_genre:
            if current_genre not in parsed_data:
                parsed_data[current_genre] = []
            parsed_data[current_genre].append(current_book.copy())
        current_element = None

    def char_data(data):
        nonlocal current_genre, current_element
        if current_element == 'isbn':
            current_book['isbn'] = data.strip()
        elif current_element == 'title':
            current_book['title'] = data.strip()
        elif current_element == 'author':
            current_book['author'] = data.strip()
        elif current_element == 'genre':
            current_genre = data.strip()

    parser = xml.parsers.expat.ParserCreate()
    parser.StartElementHandler = start_element
    parser.EndElementHandler = end_element
    parser.CharacterDataHandler = char_data

    parser.Parse(xml_data, True)
    return parsed_data

import secrets
import string

def generate_secure_password(length, require_uppercase, require_lowercase, require_digits, require_special_chars):
    if length < 8:
        raise ValueError("Password length must be at least 8")

    alphabet = ''
    if require_uppercase:
        alphabet += string.ascii_uppercase
    if require_lowercase:
        alphabet += string.ascii_lowercase
    if require_digits:
        alphabet += string.digits
    if require_special_chars:
        alphabet += string.punctuation

    required_count = sum([require_uppercase, require_lowercase, require_digits, require_special_chars])

    if not alphabet or length < required_count:
        raise ValueError("Cannot meet the requirements with the given length")

    # Ensuring requirements are met
    password = []
    if require_uppercase:
        password.append(secrets.choice(string.ascii_uppercase))
    if require_lowercase:
        password.append(secrets.choice(string.ascii_lowercase))
    if require_digits:
        password.append(secrets.choice(string.digits))
    if require_special_chars:
        password.append(secrets.choice(string.punctuation))

    # Fill the rest of the password length with random choices
    password.extend(secrets.choice(alphabet) for _ in range(length - len(password)))

    # Shuffle the resulting password list to ensure randomness
    secrets.SystemRandom().shuffle(password)

    return ''.join(password)

import pkgutil
import importlib

def list_submodules(package_name: str) -> list:
    try:
        package = importlib.import_module(package_name)
    except ModuleNotFoundError:
        return []

    submodules = []
    for module_info in pkgutil.iter_modules(package.__path__, package.__name__ + "."):
        submodules.append(module_info.name)

    return sorted(submodules)

