def factorial(n):
    """
    Computes the factorial of a non-negative integer n.
    If n is out of the range [0, 12], a ValueError is raised.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0 or n > 12:
        raise ValueError("Invalid input, n must be between 0 and 12, inclusive.")

    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

