import colorsys

def adjust_hue(image_rgb, delta_hue):
    def adjust_pixel_hue(pixel, delta_hue):
        r, g, b = pixel
        h, l, s = colorsys.rgb_to_hls(r, g, b)
        h = (h + delta_hue) % 1.0  # Adjust hue and make sure it wraps around within [0, 1]
        r, g, b = colorsys.hls_to_rgb(h, l, s)
        return (r, g, b)

    return [[adjust_pixel_hue(pixel, delta_hue) for pixel in row] for row in image_rgb]

