def analyze_memory_usage(code: str) -> str:
    import tracemalloc
    import sys

    # Function to execute passed code safely
    def execute_code(code):
        exec_globals = {}
        exec_locals = {}
        exec(code, exec_globals, exec_locals)

    tracemalloc.start()

    try:
        execute_code(code)
    except Exception as e:
        tracemalloc.stop()
        return f"Error during code execution: {e}"

    snapshot = tracemalloc.take_snapshot()
    top_stats = snapshot.statistics('lineno')

    report_lines = []
    for stat in top_stats[:5]:
        report_lines.append(
            f"File {stat.traceback[0].filename}, Line {stat.traceback[0].lineno}: {stat.size} bytes"
        )

    tracemalloc.stop()

    if not report_lines:
        return "No significant memory allocations detected."

    return "\n".join(report_lines)

