def execute_dynamic_code(code_str: str, start_symbol: int, globals_dict: dict, locals_dict: dict):
    import builtins
    try:
        # Compile the code string using the provided start symbol
        code = compile(code_str, '<string>', 'eval' if start_symbol == eval("builtins.eval") else 'exec')

        # Execute the compiled code in the provided global and local contexts
        if start_symbol == eval("builtins.eval"):
            return eval(code, globals_dict, locals_dict)
        else:
            exec(code, globals_dict, locals_dict)
            return locals_dict.get('result', None)
    except Exception as e:
        return str(e)

