def process_grades(grades):
    """
    Processes a list of tuples representing student grades and returns
    a dictionary that organizes the grades by student.

    :param grades: List[Tuple[str, int]]
    :return: Dict[str, List[int]]
    :raises TypeError: If input is not a list of tuples with (str, int)
    """
    if not isinstance(grades, list):
        raise TypeError("Input must be a list of tuples")

    for grade in grades:
        if not isinstance(grade, tuple):
            raise TypeError("Each item in the list must be a tuple")
        if len(grade) != 2:
            raise TypeError("Each tuple must have exactly 2 elements")
        if not isinstance(grade[0], str):
            raise TypeError("The first element of each tuple must be a string")
        if not isinstance(grade[1], int):
            raise TypeError("The second element of each tuple must be an integer")

    result = {}
    for name, grade in grades:
        if name in result:
            result[name].append(grade)
        else:
            result[name] = [grade]

    return result

