def extract_text_lines(msg, maintype='text', subtype=None, decode=False):
    """
    Extract all lines of text from the payloads of an email message object.

    Parameters:
    - msg: An email message object to process.
    - maintype (str): The main MIME type to filter subparts. Defaults to 'text'.
    - subtype (str): The MIME subtype to filter subparts. Optional.
    - decode (bool): Whether to decode the payloads. Defaults to False.

    Returns:
    - List[str]: A list of strings, where each string is a line of text from the filtered subparts' payloads.
    """
    text_lines = []

    if msg.is_multipart():
        for part in msg.walk():
            if part.get_content_maintype() == maintype and (subtype is None or part.get_content_subtype() == subtype):
                if decode:
                    payload = part.get_payload(decode=True)
                    if payload is not None:
                        payload = payload.decode(part.get_content_charset() or 'utf-8')
                else:
                    payload = part.get_payload(decode=False)

                if isinstance(payload, str):
                    lines = payload.splitlines()
                    text_lines.extend(lines)
    else:
        if msg.get_content_maintype() == maintype and (subtype is None or msg.get_content_subtype() == subtype):
            if decode:
                payload = msg.get_payload(decode=True)
                if payload is not None:
                    payload = payload.decode(msg.get_content_charset() or 'utf-8')
            else:
                payload = msg.get_payload(decode=False)

            if isinstance(payload, str):
                lines = payload.splitlines()
                text_lines.extend(lines)

    return text_lines

