import gc

def gc_diagnostics() -> dict:
    """
    Returns a diagnostic report of the current state of the garbage collector.
    """
    # Check if garbage collection is enabled
    enabled = gc.isenabled()

    # Retrieve the collection statistics
    stats = {
        f"generation_{i}": {
            "collections": gc.get_count()[i],
            "collected": gc.get_stats()[i]["collected"],
            "uncollectable": gc.get_stats()[i]["uncollectable"]
        }
        for i in range(gc.get_count().__len__() )
    }

    # Retrieve the number of objects tracked by the garbage collector
    tracked_objects = {
        f"generation_{i}": len(gc.get_objects(i))
        for i in range(gc.get_count().__len__())
    }
    tracked_objects["total"] = sum(tracked_objects.values())

    # Retrieve the list of uncollectible objects
    garbage = gc.garbage

    return {
        "enabled": enabled,
        "stats": stats,
        "tracked_objects": tracked_objects,
        "garbage": garbage
    }

