def is_prime(number):
    """Return True if number is a prime, else False."""
    if number <= 1:
        return False
    if number <= 3:
        return True
    if number % 2 == 0 or number % 3 == 0:
        return False
    i = 5
    while i * i <= number:
        if number % i == 0 or number % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_generator():
    """Generates an infinite sequence of prime numbers."""
    number = 2
    while True:
        if is_prime(number):
            yield number
        number += 1

import threading
from queue import PriorityQueue

def process_tasks(tasks: list[tuple[int, int]], num_workers: int) -> None:
    def worker():
        while True:
            priority, task_id = pq.get()
            if task_id is None:
                break
            print(f"Processing task {task_id} with priority {priority}")
            pq.task_done()

    pq = PriorityQueue()
    for task_id, priority in tasks:
        pq.put((priority, task_id))

    threads = []
    for _ in range(num_workers):
        t = threading.Thread(target=worker)
        t.start()
        threads.append(t)

    pq.join()

    for _ in range(num_workers):
        pq.put((None, None))
    for t in threads:
        t.join()

