import ast

def format_function_signatures(source_code: str) -> str:
    class FunctionSignatureVisitor(ast.NodeVisitor):
        def __init__(self):
            self.signatures = []
            self.current_class = None

        def visit_FunctionDef(self, node):
            if self.current_class:
                func_name = f"{self.current_class}.{node.name}"
            else:
                func_name = node.name

            # Extract function signature
            args_list = []
            for arg in node.args.args:
                if arg.annotation:
                    args_list.append(f"{arg.arg}: {ast.unparse(arg.annotation)}")
                else:
                    args_list.append(arg.arg)

            # Generate formatted arguments string
            args_str = ', '.join(args_list)

            # Handle return annotation if it exists
            if node.returns:
                ret_annotation = f" -> {ast.unparse(node.returns)}"
            else:
                ret_annotation = ""

            signature = f"{func_name}({args_str}){ret_annotation}"
            self.signatures.append(signature)

        def visit_ClassDef(self, node):
            self.current_class = node.name
            self.generic_visit(node)
            self.current_class = None

    tree = ast.parse(source_code)
    visitor = FunctionSignatureVisitor()
    visitor.visit(tree)
    return "\n".join(visitor.signatures)

