import calendar

def custom_yearly_calendar(year: int, width: int = 3) -> str:
    cal = calendar.Calendar(firstweekday=0)
    months = [calendar.month_name[i] for i in range(1, 13)]
    result = ""

    for m in range(1, 13, width):
        for row in range(7):  # Maximum of 6 rows and 1 row for month names
            for w in range(width):
                if m + w <= 12:
                    month_days = cal.monthdayscalendar(year, m + w)
                    if row == 0:
                        result += months[m + w - 1].center(20)
                    else:
                        try:
                            week = month_days[row - 1]
                            formatted_week = [
                                (day, day == 1 and calendar.weekday(year, m + w, day) == 0)
                                if day != 0 else (0, False) for day in week
                            ]
                            result += str(formatted_week).ljust(20)
                        except IndexError:
                            result += " " * 20
            result += "\n"
        result += "\n"

    return result.strip()

