import html

def entities_to_unicode(html_string: str) -> str:
    """
    Converts HTML entities in the input string to their corresponding Unicode characters.
    """
    return html.unescape(html_string)

def unicode_to_entities(unicode_string: str) -> str:
    """
    Converts Unicode characters in the input string to their corresponding HTML entities.
    """
    entity_map = html.entities.codepoint2name
    result = []

    for char in unicode_string:
        if ord(char) in entity_map:
            result.append(f"&{entity_map[ord(char)]};")
        else:
            result.append(char)

    return ''.join(result)

