def simulate_integer_conversion(input_value, convert_to):
    """
    Simulates integer conversion based on the specified type.
    """
    try:
        if convert_to == 'long':
            if isinstance(input_value, int):
                return input_value
            else:
                raise ValueError("input_value should be an int for 'long' conversion")

        elif convert_to == 'unsigned_long':
            if isinstance(input_value, int) and input_value >= 0:
                return input_value
            else:
                raise ValueError("input_value should be a non-negative int for 'unsigned_long' conversion")

        elif convert_to == 'double':
            if isinstance(input_value, (float, int)):
                return int(input_value)
            else:
                raise ValueError("input_value should be a float or int for 'double' conversion")

        elif convert_to == 'string':
            if isinstance(input_value, str):
                return int(input_value)
            else:
                raise ValueError("input_value should be a string for 'string' conversion")

        elif convert_to == 'void_ptr':
            if isinstance(input_value, int):
                return input_value
            else:
                raise ValueError("input_value should be an int for 'void_ptr' conversion")

        else:
            return None  # Unsupported conversion type
    except (ValueError, TypeError):
        return None

def safe_divide_and_access(a: int, b: int, lst: list, index: int) -> dict:
    """
    Perform division and access list element safely, handling various exceptions.

    Parameters:
        a (int): The numerator.
        b (int): The denominator.
        lst (list): The list from which an element is to be accessed.
        index (int): The index of the element to be accessed.

    Returns:
        dict: A dictionary with the results of the division and element access,
              and any errors encountered.
    """
    result = {
        'division_result': None,
        'element': None,
        'errors': {}
    }

    # Handle division with exception handling.
    try:
        result['division_result'] = a / b
    except ZeroDivisionError as e:
        result['errors']['ZeroDivisionError'] = str(e)
    except TypeError as e:
        result['errors']['TypeError'] = str(e)

    # Handle list index access with exception handling.
    try:
        result['element'] = lst[index]
    except IndexError as e:
        result['errors']['IndexError'] = str(e)
    except TypeError as e:
        result['errors']['TypeError'] = str(e)

    return result

