from collections import ChainMap

def configure_hierarchy(command: str, *args, **kwargs) -> ChainMap:
    if command == "create":
        if len(args) == 0:
            return ChainMap({})
        else:
            return ChainMap({}, *args)

    elif command == "update":
        config = args[0]
        config.maps[0].update(kwargs)
        return config

    elif command == "retrieve":
        config, key = args
        return config.get(key)

    elif command == "effective":
        config = args[0]
        result = {}
        for mapping in reversed(config.maps):
            result.update(mapping)
        return result

