import sys

def frame_introspection() -> dict:
    """
    Gathers and returns detailed information about the current execution frame
    and its environment.
    """
    frame = sys._getframe()

    builtins = frame.f_builtins
    locals_ = frame.f_locals
    globals_ = frame.f_globals

    current_frame_info = {
        "code": str(frame.f_code),
        "line_number": frame.f_lineno,
    }

    back_frame = frame.f_back
    if back_frame is not None:
        back_frame_info = {
            "code": str(back_frame.f_code),
            "line_number": back_frame.f_lineno
        }
    else:
        back_frame_info = None

    current_frame_info["back_frame"] = back_frame_info

    return {
        "builtins": builtins,
        "locals": locals_,
        "globals": globals_,
        "current_frame": current_frame_info
    }

