def convert_to_pyint(value, dtype):
    """
    Converts the given value into a Python Integer (PyLongObject) based on the specified dtype.

    Parameters:
    value : int, float, or int (if pointer)
    dtype : str (one of 'long', 'unsigned long', 'long long', 'unsigned long long', 'double', or 'void pointer')

    Returns:
    int : PyLongObject or
    str : Error message if conversion fails
    """
    try:
        if dtype == 'long':
            return int(value)
        elif dtype == 'unsigned long':
            if value < 0:
                return "OverflowError: value cannot be negative for unsigned long"
            return int(value)
        elif dtype == 'long long':
            return int(value)
        elif dtype == 'unsigned long long':
            if value < 0:
                return "OverflowError: value cannot be negative for unsigned long long"
            return int(value)
        elif dtype == 'double':
            return int(value)
        elif dtype == 'void pointer':
            return int(value)  # Assuming the value is already a pointer (integer format)
        else:
            return "TypeError: Invalid dtype provided"
    except OverflowError:
        return "OverflowError: value too large to convert to PyLongObject"
    except ValueError:
        return "ValueError: Invalid value provided"
    except TypeError:
        return "TypeError: Invalid type for value provided"

