import os

def modify_and_fetch_env(to_add: dict, to_fetch: list) -> tuple:
    try:
        # Set the environment variables from to_add
        for key, value in to_add.items():
            os.environ[key] = value

        # Fetch the environment variables specified in to_fetch
        result = {}
        for key in to_fetch:
            result[key] = os.environ.get(key)

        return (result, 'Success')
    except Exception as e:
        return ({}, f'Error: {str(e)}')

