from fnmatch import fnmatch
from typing import List

def process_files(file_paths: List[str], include_patterns: List[str], exclude_patterns: List[str]) -> List[str]:
    if include_patterns:
        included_files = [file for file in file_paths if any(fnmatch(file, pat) for pat in include_patterns)]
    else:
        included_files = file_paths

    final_files = [file for file in included_files if not any(fnmatch(file, pat) for pat in exclude_patterns)]

    return final_files

from threading import Thread, Lock

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def worker(start, end, result, lock):
    count = 0
    for num in range(start, end):
        if is_prime(num):
            count += 1
    with lock:
        result.append(count)

def count_primes_in_range(n, m, thread_count):
    threads = []
    result = []
    lock = Lock()

    interval = (m - n) // thread_count
    for i in range(thread_count):
        start = n + i * interval
        end = n + (i + 1) * interval if i != thread_count - 1 else m
        thread = Thread(target=worker, args=(start, end, result, lock))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return sum(result)

