from importlib.metadata import version, metadata, PackageNotFoundError

def package_metadata_summary(packages):
    """
    Returns metadata summary (version, summary, author) for the given list of packages.

    Parameters:
    packages (list): List of package names as strings.

    Returns:
    dict: Dictionary containing metadata summary for each package.
    """
    result = {}

    for package in packages:
        try:
            package_version = version(package)
            package_metadata = metadata(package)
            result[package] = {
                'version': package_version,
                'summary': package_metadata.get('Summary', 'No summary available'),
                'author': package_metadata.get('Author', 'Unknown author')
            }
        except PackageNotFoundError:
            # Skip the package if it's not found
            continue

    return result

import chunk

def process_aiff(file_path: str) -> dict:
    metadata = {}
    with open(file_path, 'rb') as file:
        while True:
            try:
                ch = chunk.Chunk(file, bigendian=True, align=True)
                chunk_id = ch.getname().decode('ascii')
                chunk_size = ch.getsize()
                metadata[chunk_id] = chunk_size
                ch.skip()  # Skip the data part as we are only interested in the size
            except EOFError:
                break
    return metadata

from email.message import Message

def create_and_modify_email(headers: dict, payload: str, modifications: dict) -> dict:
    msg = Message()

    # Set the headers
    for key, value in headers.items():
        msg[key] = value

    # Set the initial payload
    msg.set_payload(payload)

    # Perform modifications
    if "add_header" in modifications:
        header_name, header_value = modifications["add_header"]
        msg[header_name] = header_value

    if "delete_header" in modifications:
        del msg[modifications["delete_header"]]

    if "replace_header" in modifications:
        header_name, header_value = modifications['replace_header']
        msg.replace_header(header_name, header_value)

    if "change_payload" in modifications:
        msg.set_payload(modifications["change_payload"])

    updated_headers = dict(msg.items())
    updated_payload = msg.get_payload()

    return {
        "headers": updated_headers,
        "payload": updated_payload
    }

