import xml.parsers.expat

def parse_books(xml_string: str) -> list:
    books = []
    current_book = {}
    current_element = ""

    def start_element(name, attrs):
        nonlocal current_element
        if name == 'book':
            current_book.clear()
        current_element = name

    def end_element(name):
        nonlocal current_element
        if name == 'book':
            books.append(current_book.copy())
        current_element = ""

    def char_data(data):
        if current_element == 'title':
            current_book['title'] = data.strip()
        elif current_element == 'author':
            current_book['author'] = data.strip()
        elif current_element == 'year':
            current_book['year'] = data.strip()

    parser = xml.parsers.expat.ParserCreate()
    parser.StartElementHandler = start_element
    parser.EndElementHandler = end_element
    parser.CharacterDataHandler = char_data

    parser.Parse(xml_string)

    return books

def process_data(file_path: str, data: list) -> float:
    if not data:
        raise ValueError("Data list is empty")

    for item in data:
        if not isinstance(item, (int, float)):
            raise TypeError("All items in the data list must be numbers")

    try:
        with open(file_path, 'r') as file:
            try:
                file_value = float(file.readline().strip())
            except ValueError:
                raise ValueError("Could not convert file data to a float.")
    except FileNotFoundError:
        raise FileNotFoundError("File not found.")

    avg_data = sum(data) / len(data)
    return avg_data + file_value

