import inspect

def get_function_frame_info(target_func):
    """
    Executes target_func and captures frame information during its execution.
    """
    frame_info = {}

    def wrapper_func():
        nonlocal frame_info
        try:
            target_func()
        except Exception as e:
            pass
        current_frame = inspect.currentframe()
        outer_frame = current_frame.f_back

        frame_info = {
            "builtins": outer_frame.f_builtins,
            "locals": outer_frame.f_locals,
            "globals": outer_frame.f_globals,
            "previous_frame": None,
            "code_object": target_func.__code__,
            "current_line_number": outer_frame.f_lineno,
        }

        if outer_frame.f_back:
            prev_frame = outer_frame.f_back
            frame_info["previous_frame"] = {
                "file_name": prev_frame.f_code.co_filename,
                "line_number": prev_frame.f_lineno,
                "code_name": prev_frame.f_code.co_name,
            }

    wrapper_func()  # Execute the wrapper which captures the frame info
    return frame_info

import fnmatch

def count_matches(filenames, patterns):
    """
    This function takes in a list of filenames and a list of patterns, and returns a dictionary
    where each key is a pattern and the value is the number of filenames matching that pattern.
    """
    result = {pattern: 0 for pattern in patterns}

    for pattern in patterns:
        for filename in filenames:
            if fnmatch.fnmatch(filename.lower(), pattern.lower()):
                result[pattern] += 1

    return result

