from typing import List, Tuple, Union

def evaluate_operations(start: int, operations: List[Tuple[str, Union[int, Tuple[int, int]]]]) -> int:
    import operator

    for op, operand in operations:
        func = getattr(operator, op)

        if isinstance(operand, tuple):
            start = func(start, *operand)
        else:
            start = func(start, operand)

    return start

from array import array
from typing import List

def process_numeric_array(data_list: List[int], value: int, index: int, swap_bytes: bool) -> List[int]:
    # Step 1: Initialize the array
    arr = array('i', data_list)

    # Step 2: Insert the value
    if index < 0:
        index = max(0, len(arr) + index)
    elif index >= len(arr):
        index = len(arr)
    arr.insert(index, value)

    # Step 3: Perform byteswap if required
    if swap_bytes:
        arr.byteswap()

    # Step 4: Convert array back to list
    return arr.tolist()

