import os
import pwd
import grp
import resource
import syslog

def create_user_with_limits(username, groupname, cpu_limit, memory_limit):
    try:
        # Create a new group
        if not group_exists(groupname):
            os.system(f"groupadd {groupname}")
        else:
            raise Exception(f"Group {groupname} already exists.")

        # Create a new user and add to newly created group
        if not user_exists(username):
            os.system(f"useradd -g {groupname} {username}")
        else:
            raise Exception(f"User {username} already exists.")

        # Set resource limits
        # This is usually done in the user's session itself, but here it's demonstrated as root
        os.system(f"prlimit --pid $(pgrep {username}) --cpu={cpu_limit} --as={memory_limit}")

        # Log the creation activity
        syslog.syslog(syslog.LOG_INFO, f"Created user {username} with group {groupname}")

    except Exception as e:
        syslog.syslog(syslog.LOG_ERR, str(e))
        raise

def group_exists(groupname):
    try:
        grp.getgrnam(groupname)
        return True
    except KeyError:
        return False

def user_exists(username):
    try:
        pwd.getpwnam(username)
        return True
    except KeyError:
        return False

import crypt
from hmac import compare_digest as compare_hash

def register_user(username, password, method=None, rounds=None):
    if method:
        salt = crypt.mksalt(getattr(crypt, method), rounds=rounds)
    else:
        salt = crypt.mksalt()
    hashed_password = crypt.crypt(password, salt)
    return {'username': username, 'hashed_password': hashed_password}

def validate_login(username, password, user_db):
    if username not in user_db:
        return False
    stored_hashed_password = user_db[username]['hashed_password']
    hashed_password = crypt.crypt(password, stored_hashed_password)
    return compare_hash(hashed_password, stored_hashed_password)

