import fcntl
import os

def safe_file_operation(file_path, operation, data=None):
    """
    Perform a safe file operation with proper locking using `fcntl`.

    Args:
    file_path (str): The path to the file on which the operations are performed.
    operation (str): The type of operation to perform. It can be either 'read' or 'write'.
    data (str, optional): The data to write to the file. Required if the operation is 'write'.

    Returns:
    str or None: The contents of the file if the operation is 'read'. None for 'write' operations.
    """
    if operation not in ['read', 'write']:
        raise ValueError("Operation must be 'read' or 'write'")

    try:
        if operation == 'read':
            with open(file_path, 'r') as file:
                fcntl.flock(file.fileno(), fcntl.LOCK_SH)
                try:
                    return file.read()
                finally:
                    fcntl.flock(file.fileno(), fcntl.LOCK_UN)
        elif operation == 'write':
            if data is None:
                raise ValueError("Data must be provided for write operation")
            with open(file_path, 'w') as file:
                fcntl.flock(file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
                try:
                    file.write(data)
                finally:
                    fcntl.flock(file.fileno(), fcntl.LOCK_UN)
            return None
    except BlockingIOError:
        raise OSError("Failed to acquire the lock, file is being used by another process")
    except Exception as e:
        raise e

