def generate_triangle_numbers(n: int) -> str:
    """
    Generates the first n triangle numbers and returns them as a single string separated by commas.
    """
    triangle_numbers = []
    for i in range(1, n + 1):
        triangle_number = int(i * (i + 1) / 2)
        triangle_numbers.append(str(triangle_number))
    return ", ".join(triangle_numbers)

from email.headerregistry import HeaderRegistry, BaseHeader, UnstructuredHeader
from typing import Dict, List

def create_headers(headers_dict: Dict[str, str]) -> List[BaseHeader]:
    hr = HeaderRegistry()
    headers = []
    for name, value in headers_dict.items():
        header = hr(name, value)
        headers.append(header)
    return headers

def parse_headers(header_strings: List[str]) -> List[BaseHeader]:
    hr = HeaderRegistry()
    headers = []
    for header_string in header_strings:
        name, value = header_string.split(':', 1)
        header = hr(name.strip(), value.strip())
        headers.append(header)
    return headers

def display_headers(headers: List[BaseHeader]) -> str:
    header_strings = []
    for header in headers:
        header_strings.append(f"{header.name}: {header}")
    return '\n'.join(header_strings)

