from typing import List, Dict

def normalize_grades(grades: List[float]) -> List[float]:
    return [min(max(grade, 0), 100) for grade in grades]

def grade_summary(grades: List[float]) -> Dict[str, int]:
    summary = {'0-59': 0, '60-69': 0, '70-79': 0, '80-89': 0, '90-100': 0}
    for grade in grades:
        if grade <= 59:
            summary['0-59'] += 1
        elif grade <= 69:
            summary['60-69'] += 1
        elif grade <= 79:
            summary['70-79'] += 1
        elif grade <= 89:
            summary['80-89'] += 1
        else:
            summary['90-100'] += 1
    return summary

def top_n_students(grades: List[float], n: int) -> List[float]:
    sorted_grades = sorted(grades, reverse=True)
    top_grades = sorted_grades[:n]
    if len(sorted_grades) > n:
        last_top_grade = top_grades[-1]
        top_grades.extend(grade for grade in sorted_grades[n:] if grade == last_top_grade)
    return top_grades

from keyword import iskeyword, issoftkeyword

def classify_words(words):
    """
    Classifies words into 'keywords', 'soft_keywords', and 'neither'.

    Args:
        words (list of str): List of words to classify.

    Returns:
        dict: Dictionary with keys 'keywords', 'soft_keywords', and 'neither'.
    """
    result = {
        "keywords": [],
        "soft_keywords": [],
        "neither": []
    }

    for word in words:
        if iskeyword(word):
            result["keywords"].append(word)
        elif issoftkeyword(word):
            result["soft_keywords"].append(word)
        else:
            result["neither"].append(word)

    return result

def parse_arguments(arguments: list) -> dict:
    """
    Parses command-line style arguments into a dictionary.
    Positional arguments are put into a list under the 'positional' key,
    optional flags are set as keys with `None` as their values,
    and options with values are set as key-value pairs.
    """
    result = {'positional': []}
    i = 0

    while i < len(arguments):
        arg = arguments[i]
        if arg.startswith('--'):
            if '=' in arg:
                key, value = arg[2:].split('=', 1)
                result[key] = value
            else:
                if i + 1 < len(arguments) and not arguments[i + 1].startswith('-'):
                    result[arg[2:]] = arguments[i + 1]
                    i += 1
                else:
                    result[arg[2:]] = None
        elif arg.startswith('-'):
            result[arg[1:]] = None
        else:
            result['positional'].append(arg)
        i += 1

    return result

