def custom_encodestring(s: bytes, quotetabs: bool = False, header: bool = False) -> bytes:
    result = bytearray()
    for b in s:
        if b == ord(' '):
            if header:
                result.extend(b'_')
            elif quotetabs:
                result.extend(b'=20')
            else:
                result.append(b)
        elif b == ord('\t'):
            if quotetabs:
                result.extend(b'=09')
            else:
                result.append(b)
        elif 33 <= b <= 60 or 62 <= b <= 126:  # ASCII printable characters except '='
            result.append(b)
        else:
            result.extend(f'={b:02X}'.encode())
    return bytes(result)

def custom_decodestring(s: bytes, header: bool = False) -> bytes:
    result = bytearray()
    i = 0
    while i < len(s):
        b = s[i]
        if header and b == ord('_'):
            result.append(ord(' '))
        elif b == ord('='):
            hex_str = s[i+1:i+3].decode()
            result.append(int(hex_str, 16))
            i += 2
        else:
            result.append(b)
        i += 1
    return bytes(result)

import zlib

def compress_data(data: bytes, level: int = zlib.Z_DEFAULT_COMPRESSION, use_dict: bool = False) -> bytes:
    try:
        # Create a compressor object with the specified compression level
        compressor = zlib.compressobj(level=level)
        compressed_data = compressor.compress(data)
        compressed_data += compressor.flush(zlib.Z_FINISH)
    except zlib.error as e:
        raise zlib.error(f"Compression failed: {e}")
    return compressed_data

def decompress_data(compressed_data: bytes, use_dict: bool = False) -> bytes:
    try:
        # Create a decompressor object
        decompressor = zlib.decompressobj()
        decompressed_data = decompressor.decompress(compressed_data)
        decompressed_data += decompressor.flush()
    except zlib.error as e:
        raise zlib.error(f"Decompression failed: {e}")
    return decompressed_data

