import quopri

def bi_directional_conversion(operation, data, quotetabs=False, header=False):
    """
    Perform bidirectional conversion using the quopri module.

    Parameters:
    - operation: 'encode' or 'decode'
    - data: bytes to be encoded or decoded
    - quotetabs: controls encoding of spaces and tabs (only for encoding)
    - header: controls if spaces are encoded/decoded as underscores

    Returns:
    - Encoded or decoded bytes based on the operation
    """
    if operation == 'encode':
        return quopri.encodestring(data, quotetabs=quotetabs, header=header)
    elif operation == 'decode':
        return quopri.decodestring(data, header=header)
    else:
