import py_compile
from py_compile import PycInvalidationMode

def compile_files(file_list, optimize=-1, invalidation_mode='TIMESTAMP', quiet=1):
    if invalidation_mode not in ['TIMESTAMP', 'CHECKED_HASH', 'UNCHECKED_HASH']:
        raise ValueError("Invalid invalidation_mode. Must be 'TIMESTAMP', 'CHECKED_HASH', or 'UNCHECKED_HASH'")

    invalidation_mapping = {
        'TIMESTAMP': PycInvalidationMode.TIMESTAMP,
        'CHECKED_HASH': PycInvalidationMode.CHECKED_HASH,
        'UNCHECKED_HASH': PycInvalidationMode.UNCHECKED_HASH
    }

    results = {}
    for file in file_list:
        try:
            py_compile.compile(file, cfile=None, dfile=None, doraise=True,
                         optimize=optimize, invalidation_mode=invalidation_mapping[invalidation_mode], quiet=quiet)
            results[file] = "success"
        except FileNotFoundError:
            results[file] = "file_error"
        except py_compile.PyCompileError:
            results[file] = "compile_error"

    return results

