import pwd

def query_password_db(user_query=None, uid_query=None, shell_query=None, home_dir_contains=None):
    """
    Queries the Unix password database for specific information.

    Parameters:
    - user_query (str or None): Username to query.
    - uid_query (int or None): User ID to query.
    - shell_query (str or None): Shell string to query.
    - home_dir_contains (str or None): Substring to search for in home directories.

    Returns:
    - A Unix password database entry, or lists of usernames, based on the query.
    """

    if user_query is not None and uid_query is not None:
        raise ValueError("Provide either user_query or uid_query, not both.")

    if user_query is not None:
        try:
            return pwd.getpwnam(user_query)
        except KeyError:
            return None

    if uid_query is not None:
        try:
            return pwd.getpwuid(uid_query)
        except KeyError:
            return None

    if shell_query is not None:
        return [entry.pw_name for entry in pwd.getpwall() if entry.pw_shell == shell_query]

    if home_dir_contains is not None:
        return [entry.pw_name for entry in pwd.getpwall() if home_dir_contains in entry.pw_dir]

    raise ValueError("At least one query parameter must be provided.")

import io

def process_data(data):
    """
    Args:
        data: Can be either a string (text or file path) or bytes (binary).
    Returns:
        - If input is text, return the text in uppercase.
        - If input is binary, return the reversed sequence of bytes.
    """
    # If input is a file path, determine if it's a text file or binary file
    if isinstance(data, str):
        if data.endswith('.txt'):
            with io.open(data, 'r', encoding='utf-8') as f:
                data = f.read()
        elif data.endswith('.bin'):
            with io.open(data, 'rb') as f:
                data = f.read()

    # Process text and binary data accordingly
    if isinstance(data, str):
        return data.upper()
    elif isinstance(data, bytes):
        return data[::-1]
    else:
        raise ValueError('Unsupported data type')

