import array

def process_arrays(int_list: list, search_int: int) -> dict:
    signed_array = array.array('i')  # signed integer array
    unsigned_array = array.array('I')  # unsigned integer array

    for item in int_list:
        signed_array.append(item)
        if item >= 0:
            unsigned_array.append(item)

    signed_count = signed_array.count(search_int)
    unsigned_count = unsigned_array.count(search_int)

    signed_array.reverse()
    unsigned_array.reverse()

    return {
        'signed': {
            'typecode': 'i',
            'reversed_list': signed_array.tolist(),
            'count': signed_count
        },
        'unsigned': {
            'typecode': 'I',
            'reversed_list': unsigned_array.tolist(),
            'count': unsigned_count
        }
    }

