def process_sequence(sequence, operation):
    """
    Processes the given sequence based on its type and the specified operation.

    Args:
    sequence (bytes or bytearray or str): The sequence object which could be of type bytes, bytearray, or str.
    operation (str): The operation to perform. It can be one of the following:
                     - 'reverse' : Reverse the sequence.
                     - 'capitalize' : Capitalize all elements (only applicable for Unicode/str objects).
                     - 'append' : Append a predefined element to the sequence.

    Returns:
    bytes or bytearray or str: The processed sequence as per the operation.

    Raises:
    TypeError: If the sequence is not one of the expected types.
    ValueError: If the operation is not recognized.
    """
    if not isinstance(sequence, (bytes, bytearray, str)):
        raise TypeError("Expected a sequence of type bytes, bytearray or str")

    if operation == 'reverse':
        return sequence[::-1]

    elif operation == 'capitalize':
        if isinstance(sequence, str):
            return sequence.upper()
        else:
            raise ValueError("Capitalize operation is only applicable to Unicode/str objects")

    elif operation == 'append':
        if isinstance(sequence, bytes):
            return sequence + b'x'
        elif isinstance(sequence, bytearray):
            return sequence + bytearray(b'x')
        elif isinstance(sequence, str):
            return sequence + 'x'

    else:
        raise ValueError("Operation not recognized")

