def execute_dynamic_function(module_name, function_name, parameters):
    import importlib

    # Dynamically import the module
    module = importlib.import_module(module_name)

    # Retrieve the function using reflection
    func = getattr(module, function_name)

    # Parse the parameters
    parsed_params = []
    for param in parameters.split(','):
        if '.' in param:
            parsed_params.append(float(param))
        else:
            parsed_params.append(int(param))

    # Call the function with parsed parameters and return the result
    return func(*parsed_params)

import io

def custom_text_filter(input_text: str, filter_word: str) -> str:
    input_stream = io.StringIO(input_text)
    output_stream = io.StringIO()

    filter_word_len = len(filter_word)
    word_boundary_chars = set(' \t\n\r.,!?;:"\'()[]{}<>')

    while True:
        char = input_stream.read(1)
        if not char:
            break

        if char in word_boundary_chars:
            output_stream.write(char)
            continue

        buffer = char

        while True:
            next_char = input_stream.read(1)
            if not next_char or next_char in word_boundary_chars:
                break
            buffer += next_char

        if buffer == filter_word:
            if next_char and next_char in word_boundary_chars:
                output_stream.write(next_char)
        else:
            output_stream.write(buffer)
            if next_char:
                output_stream.write(next_char)

    return output_stream.getvalue()

import base64

def encode_file_to_base64(input_file_path: str, output_file_path: str) -> None:
    with open(input_file_path, "rb") as input_file:
        binary_data = input_file.read()
    base64_encoded_data = base64.b64encode(binary_data)
    with open(output_file_path, "wb") as output_file:
        output_file.write(base64_encoded_data)

def decode_base64_to_file(input_file_path: str, output_file_path: str) -> None:
    with open(input_file_path, "rb") as input_file:
        base64_encoded_data = input_file.read()
    try:
        binary_data = base64.b64decode(base64_encoded_data)
    except (base64.binascii.Error, ValueError):
        raise ValueError("Invalid Base64 input.")
    with open(output_file_path, "wb") as output_file:
        output_file.write(binary_data)

def encode_and_decode_string(data: str, operation: str, url_safe: bool = False) -> str:
    if operation == "encode":
        if url_safe:
            encoded_data = base64.urlsafe_b64encode(data.encode()).decode()
        else:
            encoded_data = base64.b64encode(data.encode()).decode()
        return encoded_data
    elif operation == "decode":
        try:
            if url_safe:
                decoded_data = base64.urlsafe_b64decode(data.encode()).decode()
            else:
                decoded_data = base64.b64decode(data.encode()).decode()
        except (base64.binascii.Error, ValueError):
            raise ValueError("Invalid Base64 input.")
        return decoded_data
    else:
        raise ValueError("Invalid operation. Use 'encode' or 'decode'.")

def create_memoryview_from_buffer(input_string: str) -> memoryview:
    """
    Takes an input string and returns a read-only memoryview of its bytes.
    """
    byte_data = input_string.encode('utf-8')
    mem_view = memoryview(byte_data)
    return mem_view.toreadonly()

def is_memoryview(obj: object) -> bool:
    """
    Takes any Python object and returns True if the object is a memoryview, otherwise False.
    """
    return isinstance(obj, memoryview)

def memoryview_to_contiguous(mv_obj: memoryview, order: str) -> memoryview:
    """
    Takes a memoryview object and a format option ('C' or 'F').
    Returns a new contiguous memoryview of the original object using the specified format.
    """
    if order not in ('C', 'F'):
        raise ValueError("Order must be 'C' or 'F'")
    return mv_obj.tobytes() if order == 'C' else mv_obj.tobytes(order='F')

def evaluate_expression(expression: str, local_vars: dict, global_vars: dict) -> any:
    try:
        result = eval(expression, global_vars, local_vars)
        return result
    except (NameError, UnboundLocalError):
        return "Error: Undefined variable"
    except Exception:
        return "Error: Invalid expression"

