import nntplib
from typing import List, Tuple, Dict

def connect_and_get_newsgroups(host: str, port: int = 119) -> List[Tuple[str, int, int, str]]:
    try:
        with nntplib.NNTP(host, port) as server:
            response, newsgroups = server.list()
            return newsgroups
    except (nntplib.NNTPError, OSError) as e:
        print(f"Error: {e}")
        return []

def get_and_decode_latest_article_header(host: str, newsgroup: str) -> Dict[str, str]:
    try:
        with nntplib.NNTP(host) as server:
            resp, count, first, last, name = server.group(newsgroup)
            if count == 0:
                raise ValueError(f"The newsgroup '{newsgroup}' has no articles.")
            resp, id, message_id = server.stat(last)
            resp, article_info = server.head(id)
            decoded_headers = {}
            for header in article_info.lines:
                key, value = header.decode('utf-8').split(': ', 1)
                decoded_headers[key] = nntplib.decode_header(value)
            return decoded_headers
    except (nntplib.NNTPError, OSError, ValueError) as e:
        print(f"Error: {e}")
        return {}

