def detect_image_format(file_path):
    """
    Detect the image format based on the header bytes of the image file.

    :param file_path: str, path to the image file
    :return: str, image format or None if unrecognized
    """
    try:
        with open(file_path, 'rb') as f:
            header = f.read(16)

        if header.startswith(b'\xff\xd8\xff'):
            return 'jpeg'
        elif header.startswith(b'\x89PNG'):
            return 'png'
        elif header.startswith(b'GIF87a') or header.startswith(b'GIF89a'):
            return 'gif'
        elif header.startswith(b'II*\x00') or header.startswith(b'MM\x00*'):
            return 'tiff'
        elif header.startswith(b'BM'):
            return 'bmp'
        elif header.startswith(b'RIFF') and b'WEBP' in header[8:16]:
            return 'webp'
        else:
            return None
    except (FileNotFoundError, IOError):
        return None

from email.parser import BytesFeedParser
from email.policy import default

def parse_email_incrementally(email_parts):
    parser = BytesFeedParser(policy=default)

    for part in email_parts:
        parser.feed(part)

    msg = parser.close()

    email_data = {
        "Subject": msg.get("Subject", ""),
        "From": msg.get("From", ""),
        "To": msg.get("To", "")
    }

    if msg.is_multipart():
        parts = [part.get_payload(decode=True).decode(part.get_content_charset() or "utf-8")
                 for part in msg.iter_parts() if part.get_content_type() == 'text/plain']
        email_data["Body"] = "\n".join(parts)
    else:
        email_data["Body"] = msg.get_payload(decode=True).decode(msg.get_content_charset() or "utf-8")

    return email_data

