import fnmatch
import os

def create_manifest(include_patterns: list, exclude_patterns: list, directory_structure: dict) -> list:
    all_files = []

    # Collect all files based on the directory structure
    for dir_path, files in directory_structure.items():
        for file_name in files:
            full_path = os.path.join(dir_path, file_name)
            all_files.append(full_path)

    # Filter the files based on include patterns
    included_files = set()
    for pattern in include_patterns:
        for file in all_files:
            if fnmatch.fnmatch(file, pattern):
                included_files.add(file)

    # Exclude files based on exclude patterns
    final_files = set(included_files)
    for pattern in exclude_patterns:
        for file in included_files:
            if fnmatch.fnmatch(file, pattern):
                if file in final_files:
                    final_files.remove(file)

    return list(final_files)

