import getopt

def parse_arguments(argv: list) -> dict:
    options = {
        "help": False,
        "verbose": False,
        "output": None,
        "files": []
    }

    try:
        opts, files = getopt.getopt(argv, "hvo:", ["help", "verbose", "output="])

        for opt, arg in opts:
            if opt in ("-h", "--help"):
                options["help"] = True
                return options
            elif opt in ("-v", "--verbose"):
                options["verbose"] = True
            elif opt in ("-o", "--output"):
                options["output"] = arg
        options["files"] = files

    except getopt.GetoptError as err:
        raise ValueError(str(err))

    return options

