def manipulate_bytes(operations):
    """
    Manipulates a bytes object based on given operations.
    The initial bytes object is created from the string "initial".
    """
    result = []
    current_bytes = b"initial"

    for operation in operations:
        op_type = operation[0]
        op_value = operation[1]

        if op_type == "from_string":
            current_bytes = bytes(op_value, 'utf-8')

        elif op_type == "concat":
            current_bytes += bytes(op_value, 'utf-8')

        elif op_type == "query":
            result.append(len(current_bytes))

        elif op_type == "resize":
            new_size = op_value
            if new_size < len(current_bytes):
                raise ValueError("Cannot resize to a smaller size.")
            current_bytes = current_bytes.ljust(new_size, b'\x00')

    return result

