import email
from email.parser import BytesParser, Parser
from email.policy import default
import io
from typing import Union

def parse_email_content(source: Union[bytes, str, io.IOBase]) -> email.message.EmailMessage:
    """
    Parses the email content from the given source.

    Parameters:
        source (Union[bytes, str, io.IOBase]): The source of the email content, which can be a bytes-like object,
                                               a string, or a file-like object.
    Returns:
        email.message.EmailMessage: The parsed EmailMessage object.
    """
    if isinstance(source, bytes):
        return BytesParser(policy=default).parsebytes(source)
    elif isinstance(source, str):
        return Parser(policy=default).parsestr(source)
    elif isinstance(source, io.IOBase):
        if isinstance(source, io.TextIOBase):
            return Parser(policy=default).parse(source)
        elif isinstance(source, io.BufferedIOBase):
            return BytesParser(policy=default).parse(source)
    raise TypeError("Unsupported input type")

def analyze_email(email_object: email.message.EmailMessage) -> None:
    """
    Analyzes the parsed email object and prints the analysis results.

    Parameters:
        email_object (email.message.EmailMessage): The email object to analyze.
    Returns:
        None
    """
    is_multipart = email_object.is_multipart()
    defects = email_object.defects
    headers = email_object.items()

    print("Is Multipart:", is_multipart)
    print("Headers:")
    for header, value in headers:
        print(f"{header}: {value}")

    print("Defects:", defects)

