import array

def array_operations(operations):
    """
    Perform various operations on a numeric array.
    """
    arr = None
    results = []

    for operation in operations:
        op = operation[0]

        if op == "create":
            typecode, initializer = operation[1]
            arr = array.array(typecode, initializer)
            results.append(('print', arr[:]))  # '[:]' to create a copy
        elif arr is None:
            raise ValueError("Array not initialized. Please call 'create' first.")
        elif op == "append":
            arr.append(operation[1])
            results.append(('print', arr[:]))
        elif op == "extend":
            arr.extend(operation[1])
            results.append(('print', arr[:]))
        elif op == "byteswap":
            arr.byteswap()
            results.append(('print', arr[:]))
        elif op == "count":
            count_res = arr.count(operation[1])
            results.append(('count', count_res))
        elif op == "tobytes":
            bytes_res = arr.tobytes()
            results.append(('tobytes', bytes_res))
        elif op == "tolist":
            list_res = arr.tolist()
            results.append(('tolist', list_res))
        elif op == "print":
            results.append(('print', arr[:]))
        else:
            raise ValueError(f"Unsupported operation: {op}")

    return results

from typing import Iterator, List
from itertools import tee, groupby, islice

def find_heatwaves(temperatures: Iterator[int]) -> List[List[int]]:
    temperatures, temperatures_copy = tee(temperatures)

    def is_heatwave(seq):
        return all(t > 30 for t in seq)

    def heatwave_sequences():
        current_wave = []
        for temp in temperatures_copy:
            if temp > 30:
                current_wave.append(temp)
            else:
                if len(current_wave) >= 3:
                    yield current_wave
                current_wave = []
        if len(current_wave) >= 3:
            yield current_wave

    return list(heatwave_sequences())

