from xml.sax.saxutils import escape, unescape

def escape_xml_data(data: str, entities: dict = None) -> str:
    """
    Escapes special XML characters in the provided data using xml.sax.saxutils.escape.
    Additional characters to be escaped can be specified in the entities dictionary.
    """
    if entities is None:
        entities = {}
    return escape(data, entities)

def unescape_xml_data(data: str, entities: dict = None) -> str:
    """
    Unescapes special XML characters in the provided data using xml.sax.saxutils.unescape.
    Additional characters to be unescaped can be specified in the entities dictionary.
    """
    if entities is None:
        entities = {}
    return unescape(data, entities)

