def custom_xml_parser(xml_data: str) -> dict:
    import xml.parsers.expat

    parsed_data = {}
    stack = []

    def start_element(name, attrs):
        stack.append(name)
        if name not in parsed_data:
            parsed_data[name] = []
        parsed_data[name].append((attrs, ''))

    def end_element(name):
        stack.pop()

    def char_data(data):
        data = data.strip()  # strip blanks/newlines
        if not data:
            return  # ignore pure whitespace
        if stack:
            cur_element = stack[-1]
            if parsed_data[cur_element][-1][1] == '':
                parsed_data[cur_element][-1] = (parsed_data[cur_element][-1][0], data)
            else:  # append additional text to the existing value
                parsed_data[cur_element][-1] = (parsed_data[cur_element][-1][0], parsed_data[cur_element][-1][1] + data)

    parser = xml.parsers.expat.ParserCreate()
    parser.StartElementHandler = start_element
    parser.EndElementHandler = end_element
    parser.CharacterDataHandler = char_data

    try:
        parser.Parse(xml_data, True)
    except xml.parsers.expat.ExpatError as e:
        print(f"Error parsing XML: {e}")
        return {}

    return parsed_data

