import syslog

def custom_syslog(log_level: str, category: str, message: str) -> None:
    log_levels = {
        'INFO': syslog.LOG_INFO,
        'WARNING': syslog.LOG_WARNING,
        'ERROR': syslog.LOG_ERR
    }

    categories = {
        'AUTH': syslog.LOG_AUTH,
        'SYS': syslog.LOG_SYSLOG,
        'CFG': syslog.LOG_DAEMON
    }

    if log_level not in log_levels:
        raise ValueError(f"Invalid log level: {log_level}. Valid options: {', '.join(log_levels.keys())}")

    if category not in categories:
        raise ValueError(f"Invalid category: {category}. Valid options: {', '.join(categories.keys())}")

    priority = log_levels[log_level]
    facility = categories[category]

    syslog.openlog(facility=facility)
    syslog.syslog(priority, message)
    syslog.closelog()

