import xml.etree.ElementTree as ET

def modify_books(xml_string):
    root = ET.fromstring(xml_string)

    for book in root.findall('book'):
        # Add a default review if not present
        reviews = book.find('reviews')
        if reviews is None:
            reviews = ET.SubElement(book, 'reviews')
        if not list(reviews):
            new_review = ET.SubElement(reviews, 'review', rating="4")
            new_review.text = "No initial review"

        # Increase price for books before 2000
        year = int(book.find('year').text)
        if year < 2000:
            price = float(book.find('price').text)
            new_price = price * 1.10
            book.find('price').text = f"{new_price:.3f}"

        # Remove reviews with rating < 3
        for review in reviews.findall('review'):
            rating = int(review.attrib['rating'])
            if rating < 3:
                reviews.remove(review)

    return ET.tostring(root, encoding='unicode', method='xml')

import colorsys

def convert_to_rgb(colors):
    converted_colors = []
    for color in colors:
        color_space = color[0]
        values = color[1:]

        if color_space == "YIQ":
            y, i, q = values
            rgb = colorsys.yiq_to_rgb(y, i, q)
        elif color_space == "HLS":
            h, l, s = values
            rgb = colorsys.hls_to_rgb(h, l, s)
        elif color_space == "HSV":
            h, s, v = values
            rgb = colorsys.hsv_to_rgb(h, s, v)
        else:
            raise ValueError("Unknown color space: {}".format(color_space))

        converted_colors.append((color_space, *values, rgb))

    return converted_colors

