def slice_and_adjust(seq: list, start: int, stop: int, step: int) -> list:
    # Handle edge cases for step size
    if step == 0:
        raise ValueError("Step cannot be zero.")
    if step < 0:
        raise ValueError("Step cannot be negative.")

    # Adjust start and stop indices
    n = len(seq)
    if start < 0:
        start = max(0, start + n)
    if stop < 0:
        stop = max(0, stop + n)

    # Ensure start and stop are within sequence bounds
    start = min(max(start, 0), n)
    stop = min(max(stop, 0), n)

    # Collect the result using manually adjusted indices
    result = []
    for i in range(start, stop, step):
        if 0 <= i < n:
            result.append(seq[i])

    return result

