def summarize_transactions(input_string: str) -> dict:
    summary = {
        "total_expense": 0,
        "total_income": 0,
        "categories": {}
    }

    transactions = input_string.strip().split(';')

    for transaction in transactions:
        fields = transaction.split(',')

        # Handle invalid entries gracefully
        if len(fields) != 4:
            # Invalid transaction format
            continue

        transaction_id, type_, category, amount = fields

        # Validate transaction type
        if type_ not in ["income", "expense"]:
            # Invalid transaction type
            continue

        # Check if amount is a valid number
        try:
            amount = float(amount)
        except ValueError:
            # Invalid amount
            continue

        # Update the summary
        if type_ == "income":
            summary["total_income"] += amount
        else:
            summary["total_expense"] += amount

        if category not in summary["categories"]:
            summary["categories"][category] = 0
        summary["categories"][category] += amount

    return summary

