from typing import List, Dict

def extract_books(xml_data: str) -> List[Dict[str, str]]:
    # Initialize the parser
    parser = xml.parsers.expat.ParserCreate()
    books = []
    current_book = {}
    current_element = ""

    # Handler for start element
    def start_element(name, attrs):
        nonlocal current_element
        current_element = name
        if name == "book":
            current_book.clear()

    # Handler for end element
    def end_element(name):
        nonlocal current_element
        if name == "book":
            books.append(current_book.copy())
        current_element = ""

    # Handler for character data
    def char_data(data):
        if current_element in ["title", "author"]:
            current_book[current_element] = data.strip()

    # Setting handlers
    parser.StartElementHandler = start_element
    parser.EndElementHandler = end_element
    parser.CharacterDataHandler = char_data

    try:
        parser.Parse(xml_data)
    except xml.parsers.expat.ExpatError:
        return []

    return books

import array

def process_integer_array(init_list: list, actions: list) -> dict:
    arr = array.array('i', init_list)

    for action in actions:
        if action[0] == 'append':
            arr.append(action[1])
        elif action[0] == 'extend':
            arr.extend(action[1])
        elif action[0] == 'insert':
            arr.insert(action[1], action[2])
        elif action[0] == 'remove':
            arr.remove(action[1])
        elif action[0] == 'reverse':
            arr.reverse()

    count_7 = arr.count(7)
    try:
        index_7 = arr.index(7)
    except ValueError:
        index_7 = -1

    return {
        'array': list(arr),
        'stats': {
            'count_7': count_7,
            'index_7': index_7
        }
    }

