import pwd

def get_user_info(username_or_uid):
    """
    Returns user information dictionary for a given username or user ID.

    :param username_or_uid: User name (string) or user ID (integer)
    :return: Dictionary containing user information
    :raises: KeyError if the user or user ID is not found
    """
    try:
        if isinstance(username_or_uid, int):
            pw_record = pwd.getpwuid(username_or_uid)
        elif isinstance(username_or_uid, str):
            pw_record = pwd.getpwnam(username_or_uid)
        else:
            raise KeyError(f"Invalid type for username_or_uid: {username_or_uid}")
    except KeyError:
        raise KeyError(f"User '{username_or_uid}' not found")

