from xml.dom import pulldom

def process_books(xml_string: str) -> list:
    titles_before_2000 = []
    events = pulldom.parseString(xml_string)

    for event, node in events:
        if event == pulldom.START_ELEMENT and node.tagName == 'book':
            year = int(node.getAttribute('year'))
            price = float(node.getAttribute('price'))

            if year < 2000:
                titles_before_2000.append(node.getAttribute('title'))

            if price > 20:
                events.expandNode(node)
                print(node.toxml())

    return titles_before_2000

