def is_prime(n: int) -> bool:
    """
    Returns True if n is a prime number, else False.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def analyze_numbers(numbers):
    """
    Analyzes a list of integers returning a dictionary with prime, even and odd numbers.
    """
    if not numbers:
        return {'prime_numbers': [], 'even_numbers': [], 'odd_numbers': []}

    primes = []
    evens = []
    odds = []

    for number in numbers:
        if is_prime(number):
            primes.append(number)
        else:
            match number % 2:
                case 0:
                    evens.append(number)
                case 1:
                    odds.append(number)

    return {
        'prime_numbers': primes,
        'even_numbers': evens,
        'odd_numbers': odds
    }

