import os

def get_fs_path(path):
    """
    Returns the filesystem path representation of path.
    """
    if isinstance(path, (str, bytes)):
        # If path is of type string or bytes, convert bytes to string and return
        return path.decode() if isinstance(path, bytes) else path
    elif isinstance(path, os.PathLike):
        # If path is an object implementing os.PathLike, use its __fspath__ method
        return path.__fspath__()
    else:
        # Raise TypeError if path is of an unexpected type
        raise TypeError(f"Expected str, bytes, or os.PathLike object, not {type(path).__name__}")

