from typing import List, Dict, Union
from email import message_from_bytes, message_from_string
from email.message import EmailMessage
from email.policy import default

def analyze_email_messages(messages: List[Union[str, bytes]]) -> List[Dict[str, Union[str, bool, int, List[str]]]]:
    result = []
    for message in messages:
        if isinstance(message, bytes):
            msg = message_from_bytes(message, policy=default)
        else:
            msg = message_from_string(message, policy=default)

        summary = {
            "subject": msg.get('subject', ''),
            "is_multipart": msg.is_multipart(),
            "part_count": 0,
            "defects": [str(defect) for defect in msg.defects]
        }

        if msg.is_multipart():
            summary["part_count"] = len(msg.get_payload())

        result.append(summary)

    return result

