import plistlib

def merge_plists(plist1: bytes, plist2: bytes, output_format: str) -> bytes:
    """
    Merges two plist files and returns the result in the specified format.

    Parameters:
        plist1 (bytes): The first plist file in bytes format.
        plist2 (bytes): The second plist file in bytes format.
        output_format (str): The format of the output plist file ("FMT_XML" or "FMT_BINARY").

    Returns:
        bytes: The merged plist file in the specified format.

    Raises:
        ValueError: If the plist cannot be parsed or if the format is invalid.
    """
    try:
        dict1 = plistlib.loads(plist1)
        dict2 = plistlib.loads(plist2)

        if not isinstance(dict1, dict) or not isinstance(dict2, dict):
            raise ValueError("Both plist files must contain dictionaries at the top level.")

        # Merge the dictionaries, with dict2 values overwriting dict1 values for duplicate keys
        merged_dict = {**dict1, **dict2}

        if output_format == "FMT_XML":
            return plistlib.dumps(merged_dict, fmt=plistlib.FMT_XML)
        elif output_format == "FMT_BINARY":
            return plistlib.dumps(merged_dict, fmt=plistlib.FMT_BINARY)
        else:
            raise ValueError("Invalid output_format. Must be 'FMT_XML' or 'FMT_BINARY'.")
    except Exception as e:
        raise ValueError(f"An error occurred while processing the plists: {e}")

