def parse_and_build(inputs: Tuple[Union[str, bytes, int], ...]) -> Tuple:
    result = []
    for item in inputs:
        if isinstance(item, str):
            result.append(item.encode('utf-8'))
        elif isinstance(item, bytes):
            result.append(item)
        elif isinstance(item, int):
            result.append(hex(item))
    return tuple(result)

def process_data(data: list, transformations: dict) -> list:
    processed_data = []

    for record in data:
        new_record = record.copy()

        for field, transform in transformations.items():
            if field in new_record:
                try:
                    new_record[field] = transform(new_record[field])
                except Exception as e:
                    # Log errors but continue processing
                    print(f"Error processing field '{field}' with value '{new_record[field]}': {e}")

        processed_data.append(new_record)

    return processed_data

