def process_dict_sequences(data: dict) -> dict:
    """
    Processes a dictionary of sequences and returns a new dictionary where:
    - Each key maps to the sum of its sequence if non-empty,
    - Or "EMPTY" if the sequence is empty.
    """
    output = {}
    for key, sequence in data.items():
        if len(sequence) > 0:
            output[key] = sum(sequence)
        else:
            output[key] = "EMPTY"
    return output

