import zlib

def compress_data(data: bytes, level: int) -> bytes:
    """
    Compresses the provided data using the specified compression level.
    """
    if not (0 <= level <= 9):
        raise ValueError("Compression level must be between 0 and 9.")
    return zlib.compress(data, level)

def decompress_data(data: bytes) -> bytes:
    """
    Decompresses the provided compressed data.
    """
    try:
        return zlib.decompress(data)
    except zlib.error:
        raise ValueError("Decompression failed due to invalid data.")

def verify_data(original: bytes, decompressed: bytes) -> bool:
    """
    Verifies that the original data and the decompressed data are identical.
    """
    return original == decompressed

