import random

def simulate_game():
    random.seed(12345)

    # Initialize positions and the turn counter
    position_A = 0
    position_B = 0
    turns = 0

    while True:
        turns += 1

        # Player A's turn
        roll_A = random.randint(1, 6)
        position_A += roll_A
        if position_A >= 100:
            return ('A', turns)

        turns += 1

        # Player B's turn
        roll_B = random.randint(1, 6)
        position_B += roll_B
        if position_B >= 100:
            return ('B', turns)

