def process_none_object(*args) -> (bool, int):
    """
    Processes a variable number of arguments. Returns a tuple where:
    - The first element is True if all arguments are None, otherwise False.
    - The second element is the count of None values if not all arguments are None, otherwise 0.
    """
    if len(args) == 0:
        return (True, 0)

    none_count = args.count(None)

    if none_count == len(args):
        return (True, 0)
    elif none_count == 0:
        return (False, 0)
    else:
        return (False, none_count)

def process_data(data, operations):
    results = []
    errors = []

    for operation in operations:
        try:
            # Using a safe_eval function to avoid using eval directly for security reasons
            result = safe_eval(operation, data)
            results.append(result)
        except ZeroDivisionError as e:
            errors.append(f"ZeroDivisionError: {e}")
        except IndexError as e:
            errors.append(f"IndexError: {e}")
        except NameError as e:
            errors.append(f"NameError: {e}")

    return {'results': results, 'errors': errors}

def safe_eval(expression, data):
    allowed_names = {"data": data}

    code = compile(expression, "<string>", "eval")

    for name in code.co_names:
        if name not in allowed_names:
            raise NameError(f"Use of name '{name}' is not allowed")

    return eval(code, {"__builtins__": {}}, allowed_names)

