def custom_exception_handler(n: int) -> str:
    import sys
    import ctypes
    import errno

    try:
        if n < 0:
            raise ValueError("Negative value error.")
        elif 0 <= n <= 10:
            raise MemoryError("Memory allocation failed.")
        elif 10 < n <= 20:
            ctypes.set_errno(errno.EIO)
            raise OSError(ctypes.get_errno(), "Simulated system call failure.")
        elif n > 20:
            # Python 3.9+ has no `sys.exc_clear`, handle with sys.exc_info()
            if sys.exc_info()[0] is not None:
                e_type = sys.exc_info()[0]
                sys.exc_info()  # Clear the exception
                return f"Cleared error of type {e_type.__name__}"
            return "No Error"
        else:
            import traceback
            traceback.print_exc()
            return "Error Handled"
    except Exception as e:
        import traceback
        traceback.print_exc()
        return f"Exception Handled with message: {str(e)}"

