def parse_and_convert_args(*args, **kwargs):
    """
    Parses a tuple of arguments and a dictionary of keyword arguments.
    Returns a dictionary with keys "str", "int", "bytes", and "float" representing the parsed values.
    """
    if len(args) != 3:
        raise ValueError("Expected exactly three arguments")

    str_arg = args[0]
    int_arg = args[1]
    bytes_arg = args[2]
    float_arg = kwargs.get("float", 1.0)

    if not isinstance(str_arg, str):
        raise TypeError("First argument must be a string")
    if not isinstance(int_arg, int):
        raise TypeError("Second argument must be an integer")
    if not isinstance(bytes_arg, (bytes, bytearray)):
        raise TypeError("Third argument must be bytes-like")
    if not isinstance(float_arg, float):
        raise TypeError("Keyword argument 'float' must be a float")

    return {
        "str": str_arg,
        "int": int_arg,
        "bytes": bytes(bytes_arg),
        "float": float_arg
    }

