from typing import Iterator, List
import itertools

def generate_primes() -> Iterator[int]:
    """
    A generator that yields an infinite sequence of prime numbers.
    """
    D = {}
    q = 2

    while True:
        if q not in D:
            # q is a prime number
            yield q
            D[q * q] = [q]
        else:
            # q is not a prime number
            for p in D[q]:
                D.setdefault(p + q, []).append(p)
            del D[q]
        q += 1

def filter_primes_below(n: int) -> List[int]:
    """
    Filters out all prime numbers below a given integer n.
    """
    primes = []
    for prime in generate_primes():
        if prime >= n:
            break
        primes.append(prime)
    return primes

