import unicodedata

def process_unicode_string(unistr: str) -> str:
    try:
        # Analyze properties and reverse based on bidirectional properties
        processed_chars = []
        for char in unistr:
            bidi_category = unicodedata.bidirectional(char)
            if bidi_category in ('R', 'AL'):
                processed_chars.append(char[::-1])
            else:
                processed_chars.append(char)

        # Reconstructing final string
        result = ''.join(processed_chars)
        return result

    except Exception as e:
        raise ValueError(f"Error processing the Unicode string: {e}")

