import tty
import sys
import termios

def process_terminal_input(mode: str) -> str:
    if mode not in ['raw', 'cbreak']:
        raise ValueError("Invalid mode. Use 'raw' or 'cbreak'.")

    fd = sys.stdin.fileno()
    original_attributes = termios.tcgetattr(fd)

    try:
        if mode == 'raw':
            tty.setraw(fd)
        elif mode == 'cbreak':
            tty.setcbreak(fd)

        result = []
        while True:
            ch = sys.stdin.read(1)  # Read a single character
            if ch == '.':
                break
            result.append(ch)

        return ''.join(result)

    finally:
        # Reset terminal to original settings
        termios.tcsetattr(fd, termios.TCSADRAIN, original_attributes)

def process_data(data):
    """
    Takes a list of integers and returns their sum.
    Raises TypeError if input is not a list of integers.
    """
    if data is None or not isinstance(data, list):
        raise TypeError("Input must be a list of integers.")
    for element in data:
        if not isinstance(element, int):
            raise TypeError("All elements in the list must be integers.")
    return sum(data)

