import hmac
import hashlib

def send_message(message: str, key: bytes) -> tuple:
    hmac_obj = hmac.new(key, message.encode(), hashlib.sha256)
    message_hmac = hmac_obj.hexdigest()
    return message, message_hmac

def verify_message(received_message: str, received_hmac: str, key: bytes) -> bool:
    hmac_obj = hmac.new(key, received_message.encode(), hashlib.sha256)
    expected_hmac = hmac_obj.hexdigest()
    return hmac.compare_digest(received_hmac, expected_hmac)

import getopt

def process_args(args):
    """
    Process the command-line arguments passed to the script.

    Args:
    - args (list): Command-line arguments to be parsed.

    Returns:
    - dict: Parsed options and their values.
    """
    options = "hvo:"
    long_options = ["help", "verbose", "output="]

    parsed_options = {}
    try:
        opts, _ = getopt.getopt(args, options, long_options)
    except getopt.GetoptError as err:
        raise ValueError(f"Invalid option or missing argument: {err}")

    for opt, arg in opts:
        if opt in ('-h', '--help'):
            parsed_options["help"] = "Help: Usage instructions..."
        elif opt in ('-v', '--verbose'):
            parsed_options["verbose"] = True
        elif opt in ('-o', '--output'):
            parsed_options["output"] = arg
        else:
            raise ValueError(f"Unrecognized option: {opt}")

    return parsed_options

