def custom_arg_parser_formatter(arguments: list[str], format_rules: dict[str, str]) -> str:
    arg_dict = {}
    i = 0
    while i < len(arguments):
        if arguments[i].startswith("-"):
            if arguments[i].startswith("--"):
                flag = arguments[i][2:]
            else:
                flag = arguments[i][1:]
            if i + 1 < len(arguments) and not arguments[i + 1].startswith("-"):
                arg_dict[flag] = arguments[i + 1]
                i += 1
            else:
                raise ValueError(f"Flag {arguments[i]} is not followed by a value.")
        i += 1

    result_list = []
    for flag, format_rule in format_rules.items():
        if flag in arg_dict:
            value = arg_dict[flag]
            formatted_str = format_rule.format(value)
            result_list.append(formatted_str)
        else:
            raise ValueError(f"Flag {flag} specified in format_rules is not found in arguments.")

    return "\n".join(result_list)

