import math
import statistics

def is_prime(n):
    """
    Returns True if n is a prime number, else False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def analyze_numbers(data):
    """
    Analyzes the input list of integers.
    """
    primes = [is_prime(num) for num in data]
    mean = statistics.mean(data)
    variance = statistics.variance(data) if len(data) > 1 else 0.0

    result = {
        "primes": primes,
        "mean": mean,
        "variance": variance
    }
    return result

