def create_cell(value):
    """Create a cell object with the given value."""
    def cell_func():
        return value

    return cell_func.__closure__[0]

def get_cell_value(cell):
    """Get the value from the cell object."""
    return cell.cell_contents

def set_cell_value(cell, value):
    """Set a new value in the cell object."""
    cell.cell_contents = value

def add_item(inventory, item, quantity):
    """
    Adds a specified quantity of an item to the inventory.
    """
    for i in range(len(inventory)):
        if inventory[i][0].lower() == item.lower():
            inventory[i][1] += quantity
            return inventory
    inventory.append([item, quantity])
    return inventory

def remove_item(inventory, item, quantity):
    """
    Removes a specified quantity of an item from the inventory.
    """
    for i in range(len(inventory)):
        if inventory[i][0].lower() == item.lower():
            if inventory[i][1] > quantity:
                inventory[i][1] -= quantity
            else:
                inventory.pop(i)
            return inventory
    return inventory

def view_inventory(inventory):
    """
    Displays the current inventory in a human-readable format.
    """
    for item, quantity in inventory:
        print(f"{item}: {quantity}")

