def longestValidParentheses(s):
    """
    Determines the length of the longest valid parentheses substring in the given string s.
    """
    max_length = 0
    stack = [-1]

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

