def is_prime(num):
    """
    Helper function to determine if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def filter_non_primes(numbers):
    """
    Returns a list of integers with all prime numbers filtered out.
    """
    return [num for num in numbers if not is_prime(num)]

