def isValidParentheses(s: str) -> bool:
    """
    Checks whether the given string of parentheses is valid.

    Args:
    s (str): The string to check.

    Returns:
    bool: True if the string is valid, False otherwise.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            if char not in mapping.values():
                return False
            stack.append(char)

    return not stack

def shift_characters(input_str: str) -> str:
    """
    Returns a new string where every character in the input string is replaced
    with the next character in the alphabet. Non-alphabetical characters remain the same.
    """
    shifted_str = []

    for char in input_str:
        if 'a' <= char <= 'z':
            shifted_str.append(chr(((ord(char) - ord('a') + 1) % 26) + ord('a')))
        elif 'A' <= char <= 'Z':
            shifted_str.append(chr(((ord(char) - ord('A') + 1) % 26) + ord('A')))
        else:
            shifted_str.append(char)

    return ''.join(shifted_str)

