def most_frequent(strings):
    """
    Returns a dictionary with the frequency count of each unique string in the input list.
    """
    frequency_dict = {}
    for string in strings:
        if string in frequency_dict:
            frequency_dict[string] += 1
        else:
            frequency_dict[string] = 1
    return frequency_dict

