from typing import List
import re
from collections import defaultdict

def find_anagrams(words: List[str]) -> List[str]:
    def preprocess(word: str) -> str:
        cleaned_word = ''.join(re.findall(r'[a-z]', word.lower()))
        return ''.join(sorted(cleaned_word))

    anagram_groups = defaultdict(list)
    for word in words:
        key = preprocess(word)
        anagram_groups[key].append(word)

    result = []
    for group in anagram_groups.values():
        if len(group) > 1:
            result.extend(group)

    return result

