def is_prime(n):
    """
    Helper function to determine if a number is prime.
    Returns True if prime, otherwise False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def get_prime_numbers(lst):
    """
    Accepts a list of integers and returns a new list containing only the prime numbers.
    Raises TypeError if a non-integer is encountered.
    Raises ValueError if a negative number is encountered.
    """
    if not all(isinstance(x, int) for x in lst):
        raise TypeError("All elements must be integers.")
    if any(x < 0 for x in lst):
        raise ValueError("Negative numbers are not allowed.")

    return [x for x in lst if is_prime(x)]

