def is_valid_sudoku(board):
    """
    Determines if a given 9x9 Sudoku board is valid.

    Args:
    board (list of list of str): A 2D list representing the Sudoku board.

    Returns:
    bool: True if the board is valid, False otherwise.
    """
    def is_valid_unit(unit):
        unit = [num for num in unit if num != '.']
        return len(unit) == len(set(unit))

    def is_valid_row(board):
        return all(is_valid_unit(row) for row in board)

    def is_valid_col(board):
        return all(is_valid_unit([board[row][col] for row in range(9)]) for col in range(9))

    def is_valid_box(board):
        return all(is_valid_unit([board[r][c] for r in range(box_row, box_row+3) for c in range(box_col, box_col+3)])
                   for box_row in range(0, 9, 3) for box_col in range(0, 9, 3))

    return is_valid_row(board) and is_valid_col(board) and is_valid_box(board)

def compress_list(lst):
    """
    Compresses a list of integers into a string where consecutive, identical elements
    are represented by the element followed by the count.
    """
    if not lst:
        return ""

    compressed = []
    current = lst[0]
    count = 1

    for num in lst[1:]:
        if num == current:
            count += 1
        else:
            compressed.append(f"{current}*{count}")
            current = num
            count = 1
    compressed.append(f"{current}*{count}")

    return "".join(compressed)

