def longest_contiguous_subarray(nums):
    """
    Find the length of the longest contiguous subarray with an equal number of even and odd integers.

    Args:
        nums (list): List of non-negative integers

    Returns:
        int: Length of the longest contiguous subarray with an equal number of even and odd integers.
    """
    max_length = 0
    count = 0
    count_map = {0: -1}

    for i, num in enumerate(nums):
        if num % 2 == 0:
            count += 1
        else:
            count -= 1

        if count in count_map:
            max_length = max(max_length, i - count_map[count])
        else:
            count_map[count] = i

    return max_length

