def longest_arithmetic_subarray(arr):
    """
    Returns the longest contiguous subarray that forms an arithmetic sequence.
    If multiple subarrays with the same length exist, returns the first one.
    If no such subarray exists, returns an empty array.
    """
    if len(arr) < 2:
        return []

    longest_start, longest_end = 0, 0
    current_start = 0
    current_diff = arr[1] - arr[0]

    for i in range(1, len(arr)):
        if arr[i] - arr[i - 1] == current_diff:
            continue
        else:
            if i - current_start > longest_end - longest_start + 1:
                longest_start, longest_end = current_start, i - 1
            current_start = i - 1
            current_diff = arr[i] - arr[i - 1]

    if len(arr) - current_start > longest_end - longest_start + 1:
        longest_start, longest_end = current_start, len(arr) - 1

    return arr[longest_start:longest_end + 1]

