def generate_primes(n):
    """
    Generate a list of the first n prime numbers using the Sieve of Eratosthenes algorithm.
    """
    if n <= 0:
        return []

    primes = []
    sieve = [True] * (2 * n * int(n ** 0.5) + 1) # Large upper bound to find the first n primes
    sieve[0] = sieve[1] = False # 0 and 1 are not prime numbers

    for i in range(2, len(sieve)):
        if sieve[i]:
            primes.append(i)
            for j in range(i*i, len(sieve), i):
                sieve[j] = False

        if len(primes) == n:
            break

    return primes

