def find_unique_elements(arr1, arr2):
    """
    Find elements that are unique to each list (appear in either arr1 or arr2, but not in both).
    """
    unique_elements = []
    element_count = {}

    # Count occurrences in both lists
    for num in arr1 + arr2:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    # Collect elements that appear exactly once
    for num, count in element_count.items():
        if count == 1:
            unique_elements.append(num)

    return unique_elements

