def min_add_to_make_valid(s):
    """
    Determine the minimum number of insertions and deletions to make a string of parentheses valid.

    Args:
    s (str): The input string of parentheses.

    Returns:
    int: The minimum number of insertions and deletions needed.
    """
    left_balance = 0
    right_balance = 0

    for char in s:
        if char == '(':
            left_balance += 1
        elif char == ')':
            if left_balance > 0:
                left_balance -= 1
            else:
                right_balance += 1

    return left_balance + right_balance

