def longest_digit_substring(input_str: str) -> str:
    max_digits = ""
    curr_digits = ""
    for char in input_str:
        if char.isdigit():
            curr_digits += char
        else:
            if len(curr_digits) > len(max_digits):
                max_digits = curr_digits
            curr_digits = ""

    # Final check to see if the last segment of digits is the longest
    if len(curr_digits) > len(max_digits):
        max_digits = curr_digits

    return max_digits

