def square_of_digit_sums(numbers):
    """
    Returns a new list where each integer is replaced by the square of its digit sum.

    :param numbers: List of integers
    :return: List of integers
    """
    def digit_sum(n):
        return sum(int(digit) for digit in str(n))

    return [digit_sum(num) ** 2 for num in numbers]

