def longest_even_odd_subarray(nums):
    """
    Returns the length of the longest contiguous subarray
    containing equal numbers of even and odd integers.
    """
    n = len(nums)
    max_len = 0
    sum_map = {0: -1}
    curr_sum = 0

    for i in range(n):
        # Increment or decrement curr_sum based on even or odd number
        if nums[i] % 2 == 0:
            curr_sum += 1
        else:
            curr_sum -= 1

        if curr_sum in sum_map:
            max_len = max(max_len, i - sum_map[curr_sum])
        else:
            sum_map[curr_sum] = i

    return max_len

