def longest_even_subarray(lst):
    longest_subarray = []
    current_subarray = []

    for num in lst:
        if num % 2 == 0:
            current_subarray.append(num)
        else:
            if len(current_subarray) > len(longest_subarray):
                longest_subarray = current_subarray
            current_subarray = []

    # Check at the end of the list
    if len(current_subarray) > len(longest_subarray):
        longest_subarray = current_subarray

    return longest_subarray

