def longest_strings(strings):
    """
    Returns a dictionary with the longest string(s) and their length(s) from the list of strings.
    """
    if not strings:
        return {}

    max_length = max(len(s) for s in strings)
    longest = {s: len(s) for s in strings if len(s) == max_length}

    return longest

