def rearrange_string(s: str) -> str:
    """
    Transforms a given string by moving all alphabetic characters to the start of
    the string, maintaining their relative order, followed by all digits, maintaining
    their relative order. Any other characters are removed.
    """
    letters = []
    digits = []

    for char in s:
        if char.isalpha():
            letters.append(char)
        elif char.isdigit():
            digits.append(char)

    return ''.join(letters) + ''.join(digits)

