def reverse_words_in_sentence(sentence):
    """
    Reverses each word in the sentence while maintaining the order of the words
    and keeping attached punctuation marks intact.

    Args:
    sentence (str): The input sentence to process.

    Returns:
    str: A new sentence with each word reversed.
    """
    def reverse_word(word):
        """Helper function to reverse a single word, keeping punctuation intact."""
        start, end = 0, len(word) - 1
        word_list = list(word)

        while start < end:
            if not word_list[start].isalpha():
                start += 1
            elif not word_list[end].isalpha():
                end -= 1
            else:
                word_list[start], word_list[end] = word_list[end], word_list[start]
                start += 1
                end -= 1
        return "".join(word_list)

    words = sentence.split()
    reversed_words = [reverse_word(word) for word in words]
    return " ".join(reversed_words)

