def product_except_self(nums):
    """
    This function takes a list of integers and returns a list where each element is the
    product of all elements in the list except the element at the same position.
    """
    length = len(nums)

    if length == 0:
        raise ValueError("The list should not be empty.")
    if length == 1:
        raise ValueError("The list should contain at least two elements.")

    left_products = [1] * length
    right_products = [1] * length
    output = [1] * length

    for i in range(1, length):
        left_products[i] = left_products[i - 1] * nums[i - 1]

    for i in range(length - 2, -1, -1):
        right_products[i] = right_products[i + 1] * nums[i + 1]

    for i in range(length):
        output[i] = left_products[i] * right_products[i]

    return output

