def calculate_average_grades(data):
    """
    Returns a dictionary with names as keys and the average of grades as values.
    If the list of grades is empty for a particular name, the average grade is reported as None.

    Args:
    data (list of tuples): Each tuple contains a name (string) and a list of grades (floats)

    Returns:
    dict: names as keys and average grades as values
    """
    average_grades = {}
    for name, grades in data:
        if grades:
            average_grades[name] = sum(grades) / len(grades)
        else:
            average_grades[name] = None
    return average_grades

