def find_substring_indices(s: str, t: str) -> list:
    """
    Returns a list of all start indices in `s` where the substring `t` occurs.
    """
    indices = []
    sub_len = len(t)

    for i in range(len(s) - sub_len + 1):
        if s[i:i + sub_len] == t:
            indices.append(i)

    return indices

