def diagonal_wave(matrix):
    if not matrix or not matrix[0]:
        return []

    n, m = len(matrix), len(matrix[0])
    result = []

    for wave in range(n + m - 1):
        if wave % 2 == 0:
            # For even wave index, move diagonally down-left
            row = min(wave, n - 1)
            col = max(0, wave - n + 1)
            while row >= 0 and col < m:
                result.append(matrix[row][col])
                row -= 1
                col += 1
        else:
            # For odd wave index, move diagonally up-right
            col = min(wave, m - 1)
            row = max(0, wave - m + 1)
            while col >= 0 and row < n:
                result.append(matrix[row][col])
                row += 1
                col -= 1

    return result

