    for transaction in transactions:
        if len(transaction) != 4:
            raise ValueError("Each transaction must be a tuple of the form (action, stock_name, stock_price, quantity)")

        action, stock_name, stock_price, quantity = transaction

        if action not in {'buy', 'sell'}:
            raise ValueError(f"Unknown transaction type: {action}")

        if stock_name not in portfolio:
            portfolio[stock_name] = 0

        if action == 'buy':
            portfolio[stock_name] += quantity
        elif action == 'sell':
            if portfolio[stock_name] < quantity:
                raise ValueError(f"Not enough shares to sell for stock: {stock_name}")
            portfolio[stock_name] -= quantity

    # Remove stocks with 0 shares from the portfolio
    portfolio = {stock: shares for stock, shares in portfolio.items() if shares > 0}

    return portfolio

