def square_integers(int_list):
    """
    Returns a new list containing the square of each integer from the original list.
    Excludes any non-integer elements from the original list. Raises ValueError
    if the list contains any negative integers.
    """
    if not isinstance(int_list, list):
        raise ValueError("Input must be a list")

    squared_list = []
    for item in int_list:
        if isinstance(item, int):
            if item < 0:
                raise ValueError("Negative integers are not allowed")
            squared_list.append(item ** 2)

    return squared_list

