def run_length_encoding(s):
    """
    Returns the run-length encoding of the input string s.
    """
    if not s:
        return ""

    encoded = []
    count = 1
    prev_char = s[0]

    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            encoded.append(f"{count}{prev_char}")
            count = 1
            prev_char = char

    encoded.append(f"{count}{prev_char}") # append the last run

    return ''.join(encoded)

