def bubble_sort(lst):
    """
    Returns a new list with the integers sorted in non-decreasing order using the bubble sort algorithm.
    """
    n = len(lst)
    sorted_list = lst[:]
    for i in range(n):
        for j in range(0, n-i-1):
            if sorted_list[j] > sorted_list[j+1]:
                sorted_list[j], sorted_list[j+1] = sorted_list[j+1], sorted_list[j]
    return sorted_list

