from typing import List, Dict

def count_strings(strings: List[str]) -> Dict[str, int]:
    """
    Returns a dictionary with the count of each string in the list, case-insensitively.
    """
    count_dict = {}
    for s in strings:
        lower_s = s.lower()
        if lower_s in count_dict:
            count_dict[lower_s] += 1
        else:
            count_dict[lower_s] = 1
    return count_dict

