def search_matrix(matrix, target):
    """
    Searches for the target value in the given matrix. Each row in the matrix is sorted in ascending order.
    Returns the position (row_index, col_index) if found, otherwise returns (-1, -1).

    :param matrix: List of List of integers
    :param target: Integer value to be searched
    :return: Tuple (row_index, col_index) or (-1, -1)
    """
    if not matrix or not matrix[0]:
        return (-1, -1)

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1  # Start from the top-right corner

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return (row, col)
        elif matrix[row][col] > target:
            col -= 1  # Move left
        else:
            row += 1  # Move down

    return (-1, -1)  # Target not found

