def is_valid_parenthesis(s):
    """
    Determines if the string containing parenthesis is valid. A string is
    considered valid if the parenthesis are balanced and properly closed.

    Parameters:
    s (str): The input string containing parenthesis.

    Returns:
    bool: True if the string is valid, False otherwise.
    """
    stack = []
    matching_parenthesis = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in matching_parenthesis:
            if stack and stack[-1] == matching_parenthesis[char]:
                stack.pop()
            else:
                return False
        else:
            stack.append(char)

    return len(stack) == 0

