def has_zero_sum_subarray(nums, k):
    """
    Checks if the list contains a subarray of at least length k that has a sum equal to zero.
    """
    n = len(nums)
    for i in range(n):
        curr_sum = 0
        for j in range(i, n):
            curr_sum += nums[j]
            if j - i + 1 >= k and curr_sum == 0:
                return True
    return False

def length_of_longest_substring_two_distinct(s):
    """
    Returns the length of the longest substring that contains at most two distinct characters.
    """
    if len(s) == 0:
        return 0

    char_count = {}
    left = 0
    max_len = 0

    for right in range(len(s)):
        char_count[s[right]] = char_count.get(s[right], 0) + 1

        while len(char_count) > 2:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

