def count_distinct_vertical_lines(points):
    """
    Determines the number of distinct vertical lines that can be formed using given points,
    where each line contains at least two distinct points.

    Parameters:
    points (list of list of ints): Each point is represented as [x, y]

    Returns:
    int: Number of distinct vertical lines
    """
    x_coords = {}

    for point in points:
        x = point[0]
        if x in x_coords:
            x_coords[x] += 1
        else:
            x_coords[x] = 1

    vertical_lines = 0
    for count in x_coords.values():
        if count >= 2:
            vertical_lines += 1

    return vertical_lines

