import heapq

def k_largest_elements(nums, k):
    """
    Returns the k largest elements in the list `nums` in descending order.
    """
    if k <= 0:
        return []
    # Use a heap to find the k largest elements efficiently
    largest_elements = heapq.nlargest(k, nums)
    return sorted(largest_elements, reverse=True)

def sequential_calculator(operations):
    """
    Processes a list of mathematical operations sequentially and returns the final result.

    operations: List of tuples, each containing a string ('+', '-', '*', '/') and an integer.

    Returns the final result after processing all operations.
    """
    result = 0

    for operation, value in operations:
        if operation == '+':
            result += value
        elif operation == '-':
            result -= value
        elif operation == '*':
            result *= value
        elif operation == '/':
            if value == 0:
                print("Error: Division by zero. Stopping further operations.")
                return result
            result /= value

    return result

