def count_occurrences(nums):
    """
    Returns a dictionary where the keys are unique integers from the list,
    and the values are the number of times each integer appears in the list.
    """
    occurrence_dict = {}
    for num in nums:
        if num in occurrence_dict:
            occurrence_dict[num] += 1
        else:
            occurrence_dict[num] = 1
    return occurrence_dict

