def words_by_length(words):
    """
    Returns a dictionary where the keys are lengths of words and the values are lists of words of that length.

    Parameters:
    words (list): List of words.

    Returns:
    dict: Dictionary with word lengths as keys and lists of words as values.
    """
    length_dict = {}
    for word in words:
        length = word.__len__()
        if length in length_dict:
            length_dict[length].append(word)
        else:
            length_dict[length] = [word]
    return length_dict

