def median(nums):
    nums.sort()  # Sorting the list

    # Check if the length of the list is odd or even
    if len(nums) % 2 == 1:
        median_value = nums[len(nums) // 2]  # Middle value for odd length lists
    else:
        middle1 = nums[len(nums) // 2 - 1]  # Middle left value for even length lists
        middle2 = nums[len(nums) // 2]  # Middle right value for even length lists
        median_value = (middle1 + middle2) / 2.0  # Average of middle values

    return median_value

