def longest_contiguous_subarray(arrays):
    """
    Returns the length of the longest subarray with a contiguous set of elements for each input array.
    """
    def find_longest(arr):
        if not arr:
            return 0

        arr = sorted(arr)
        max_len = 1
        current_len = 1

        for i in range(1, len(arr)):
            if arr[i] == arr[i - 1] + 1:
                current_len += 1
            elif arr[i] != arr[i - 1]:
                max_len = max(max_len, current_len)
                current_len = 1

        return max(max_len, current_len)

    return [find_longest(arr) for arr in arrays]

