def word_frequencies(sentences):
    """
    Returns a dictionary with word frequencies from the input list of sentences.
    Also prints the word with the highest frequency and its count.
    """
    word_count = {}

    for sentence in sentences:
        words = sentence.lower().split()
        for word in words:
            if word.endswith(".") or word.endswith(",") or word.endswith("!"):
                word = word[:-1]
            word_count[word] = word_count.get(word, 0) + 1

    max_word = max(word_count, key=word_count.get)
    print(f"The word with the highest frequency is: '{max_word}' with count: {word_count[max_word]}")

    return word_count

