def navigate_robot(movements):
    """
    Simulates a simple version of a navigation system for a robot on a 2D grid.

    Parameters:
        movements (list of str): List of movements (e.g., ["up", "down", "left", "right"]).

    Returns:
        tuple: Final coordinates of the robot (x, y).
    """
    x, y = 0, 0  # Start at the origin (0, 0)
    for move in movements:
        if move == "up":
            y += 1
        elif move == "down":
            y -= 1
        elif move == "left":
            x -= 1
        elif move == "right":
            x += 1
        # Invalid moves are ignored
    return (x, y)

