def two_sum(nums, target):
    """
    Returns indices of the two numbers that add up to the target value.

    :param nums: List of integers
    :param target: Target sum
    :return: List of indices of the two numbers
    """
    num_map = {}
    for i, num in enumerate(nums):
        if target - num in num_map:
            return [num_map[target - num], i]
        num_map[num] = i
    return []

def is_prime(num):
    """
    Helper function to check if a number is prime.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def filter_primes(lst):
    """
    Returns a list containing only the prime numbers from the input list.
    """
    return [x for x in lst if is_prime(x)]

