def count_characters(s):
    """
    Returns a dictionary where the keys are the characters from the string,
    and the values are the number of times each character appears.
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return char_count

