from typing import List, Optional

def find_majority_element(arr: List[int]) -> Optional[int]:
    """
    Returns the majority element if it exists, or None otherwise.
    A majority element is the element that appears more than n/2 times in the list.
    """
    candidate = None
    count = 0

    # Boyer-Moore Voting Algorithm to find potential majority element
    for num in arr:
        if count == 0:
            candidate = num
        if num == candidate:
            count += 1
        else:
            count -= 1

    # Verify if candidate is actually the majority
    if arr.count(candidate) > len(arr) // 2:
        return candidate
    return None

