def is_fibonacci_number(n):
    """
    Check if a number is a Fibonacci number by checking if one of
    (5*n*n + 4) or (5*n*n - 4) is a perfect square.
    """
    if n < 0:
        return False

    def is_perfect_square(x):
        s = int(x ** 0.5)
        return s * s == x

    return is_perfect_square(5 * n * n + 4) or is_perfect_square(5 * n * n - 4)

def filter_fibonacci_numbers(lst):
    """
    Returns a list of elements from the original list that are Fibonacci numbers.
    """
    return [x for x in lst if is_fibonacci_number(x)]

