def longest_substring_k_distinct(s, k):
    if k == 0:
        return 0

    n = len(s)
    if n == 0:
        return 0

    if k >= n:
        return n

    left = 0
    right = 0
    max_len = 0
    char_count = {}

    while right < n:
        char = s[right]
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

        while len(char_count) > k:
            left_char = s[left]
            if char_count[left_char] == 1:
                del char_count[left_char]
            else:
                char_count[left_char] -= 1
            left += 1

        max_len = max(max_len, right - left + 1)
        right += 1

    return max_len

