def manage_queue(operations, capacity):
    """
    Manages a limited capacity queue system based on the given operations.

    Parameters:
    operations (list): A list of operations to be performed on the queue.
    capacity (int): The maximum capacity of the queue.

    Returns:
    list: The state of the queue after all operations have been performed.
    """
    queue = []
    for operation in operations:
        if operation.startswith("ENQUEUE"):
            _, x = operation.split()
            if len(queue) < capacity:
                queue.append(int(x))
        elif operation == "DEQUEUE":
            if queue:
                queue.pop(0)
        elif operation == "LIST":
            return queue
    return queue

