def reverse_bracketed_words(input_string: str) -> str:
    def reverse_word_in_brackets(s):
        stack, res, word = [], "", ""
        for char in s:
            if char == '[':
                if word:
                    stack.append(word)
                stack.append('[')
                word = ""
            elif char == ']':
                if word:
                    stack.append(word[::-1])
                    word = ""
                temp = []
                while stack and stack[-1] != '[':
                    temp.append(stack.pop())
                stack.pop()  # pop '['
                stack.append('[' + ''.join(temp[::-1]) + ']')
            else:
                word += char
        return ''.join(stack) + word

    return reverse_word_in_brackets(input_string)

