def decode_message(encoded_message, shift):
    """
    Decodes a message encoded using a Caesar cipher.

    Parameters:
        encoded_message (str): the encoded message
        shift (int): the fixed number of places each letter was shifted

    Returns:
        str: the original, decoded message
    """
    if not isinstance(encoded_message, str) or not isinstance(shift, int):
        raise ValueError("Invalid input: encoded_message must be a string and shift must be an integer.")
    if shift < 0 or shift > 25:
        raise ValueError("Invalid shift value: must be between 0 and 25.")

    decoded_message = []
    for char in encoded_message:
        if 'A' <= char <= 'Z':
            decoded_message.append(chr((ord(char) - ord('A') - shift) % 26 + ord('A')))
        elif 'a' <= char <= 'z':
            decoded_message.append(chr((ord(char) - ord('a') - shift) % 26 + ord('a')))
        else:
            decoded_message.append(char)
    return "".join(decoded_message)

