    """
    Simulates a basic ATM based on the input commands and returns the resulting balance or appropriate messages.

    :param commands: List of command strings for the ATM operations.
    :return: The resulting balance or appropriate messages after executing all commands.
    """
    balance = 0
    results = []

    for command in commands:
        parts = command.split()
        if len(parts) == 0:
            results.append("Invalid command")
            continue

        action = parts[0].upper()

        if action == "DEPOSIT":
            if len(parts) != 2 or not parts[1].isdigit() or int(parts[1]) <= 0:
                results.append("Invalid deposit amount")
            else:
                amount = int(parts[1])
                balance += amount
                results.append(f"Deposited {amount}")

        elif action == "WITHDRAW":
            if len(parts) != 2 or not parts[1].isdigit() or int(parts[1]) <= 0:
                results.append("Invalid withdrawal amount")
            else:
                amount = int(parts[1])
                if amount > balance:
                    results.append("Insufficient funds")
                else:
                    balance -= amount
                    results.append(f"Withdrew {amount}")

        elif action == "BALANCE":
            results.append(balance)

        else:
            results.append("Invalid command")

    return results, balance

