def maxBalancedLength(s):
    """
    Returns the maximum length of a substring that consists of balanced parentheses.
    """
    max_len = 0
    stack = [-1]  # Initialize stack with -1 to handle edge case of balanced substring at the start

    for i in range(len(s)):
        if s[i] == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_len = max(max_len, i - stack[-1])

    return max_len

def sum_of_unique_multiples(lst, n):
    """
    Returns the sum of all unique multiples of n found within the list lst.
    """
    if n == 0:
        return 0

    multiples = set(x for x in lst if x % n == 0)
    return sum(multiples)

