def find_most_frequent(numbers):
    """
    Returns the integer that appears most frequently in the list.
    If there is a tie, returns any one of the most frequent integers.
    """
    frequency = {}
    for num in numbers:
        frequency[num] = frequency.get(num, 0) + 1

    most_frequent = max(frequency, key=frequency.get)
    return most_frequent

