def get_common_elements(list1, list2):
    """
    Returns a list of common elements between list1 and list2 without duplicates,
    in the order they appeared in list1.
    """
    if not isinstance(list1, list) or not isinstance(list2, list):
        raise ValueError("Both inputs must be lists.")
    if any(not isinstance(x, int) for x in list1 + list2):
        raise ValueError("Both lists must contain only integers.")

    set2 = set(list2)
    common_elements = []
    for element in list1:
        if element in set2 and element not in common_elements:
            common_elements.append(element)

    return common_elements

