def unique_subsets(nums):
    """
    Returns all unique subsets of the list of integers.
    """
    result = []
    nums = sorted(nums)  # Sort the list to handle duplicates
    for i in range(len(nums) + 1):
        for combo in combinations(nums, i):
            if combo not in result:
                result.append(combo)
    return result

from typing import List, Tuple

def solve_maze(maze: List[List[int]]) -> List[Tuple[int, int]]:
    n = len(maze)
    m = len(maze[0])
    path = []

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and maze[x][y] == 0

    def find_path(x, y):
        if x == n-1 and y == m-1:
            path.append((x, y))
            return True

        if is_valid(x, y):
            path.append((x, y))
            maze[x][y] = -1  # mark as visited

            if find_path(x + 1, y):
                return True
            if find_path(x, y + 1):
                return True

            path.pop()  # backtrack
            maze[x][y] = 0  # unmark as visited

        return False

    if find_path(0, 0):
        return path
    else:
        return []

import re

def eval_expression(expression):
    """
    Evaluates a mathematical expression containing integers and the operators '+', '*' following the
    standard order of operations (multiplication before addition).

    Args:
    expression (str): The input mathematical expression as a string.

    Returns:
    int/str: The result of the evaluated expression or an error message if the input is invalid.
    """
    if not expression:
        return "Empty expression"

    # Check for invalid characters
    if not re.match(r'^[0-9+\*\s]+$', expression):
        return "Invalid characters in expression"

    try:
        parts = re.split(r'(\+)', expression.replace(' ', ''))

        for i in range(len(parts)):
            if '*' in parts[i]:
                parts[i] = str(eval(parts[i]))

        return eval(''.join(parts))

    except (SyntaxError, TypeError, ValueError):
        return "Invalid expression"

