def atm_machine():
    balance = 0

    while True:
        print("\nChoose an operation:")
        print("1. Deposit")
        print("2. Withdraw")
        print("3. Check Balance")
        print("4. Exit")

        choice = input("Enter choice (1/2/3/4): ")

        if choice == '1':
            try:
                amount = float(input("Enter amount to deposit: "))
                if amount < 0:
                    print("Error: Invalid deposit amount.")
                else:
                    balance += amount
                    print(f"Deposited {amount}. New balance is {balance}.")
            except ValueError:
                print("Error: Invalid input. Please enter a numeric value.")

        elif choice == '2':
            try:
                amount = float(input("Enter amount to withdraw: "))
                if amount < 0:
                    print("Error: Invalid withdraw amount.")
                elif amount > balance:
                    print("Error: Insufficient funds.")
                else:
                    balance -= amount
                    print(f"Withdrew {amount}. New balance is {balance}.")
            except ValueError:
                print("Error: Invalid input. Please enter a numeric value.")

        elif choice == '3':
            print(f"Current balance: {balance}")

        elif choice == '4':
            print("Exiting the ATM machine. Have a great day!")
            break

        else:
            print("Error: Invalid choice. Please select a valid option.")

def celsius_to_fahrenheit(celsius):
    return (celsius * 9/5) + 32

def process_temperatures(temperatures):
    if not temperatures:
        raise ValueError("No temperatures provided")

    fahrenheit_temps = [celsius_to_fahrenheit(temp) for temp in temperatures]

    highest_temp = max(fahrenheit_temps)
    lowest_temp = min(fahrenheit_temps)
    average_temp = sum(fahrenheit_temps) / len(fahrenheit_temps)

    return highest_temp, lowest_temp, average_temp

