from typing import List, Union, Any

def find_prime_numbers(nums: List[Union[int, Any]]) -> List[int]:
    """
    Return a list of all prime numbers from the input list while handling exceptions.
    Raises a ValueError if any non-integer or negative integer is found in the list.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = []
    for num in nums:
        if not isinstance(num, int):
            raise ValueError("Input contains non-integer element(s).")
        if num < 0:
            raise ValueError("Input contains negative integer value(s).")
        if is_prime(num):
            primes.append(num)
    return primes

