def rearrange_string(s):
    """
    Rearranges the digits in non-decreasing order while leaving the letters in their original positions.

    :param s: String containing digits and letters
    :return: Newly formed string with digits sorted
    """
    digits = sorted([c for c in s if c.isdigit()])
    digit_index = 0
    result = []

    for char in s:
        if char.isdigit():
            result.append(digits[digit_index])
            digit_index += 1
        else:
            result.append(char)

    return ''.join(result)

