def find_primes(numbers):
    """
    Returns a list of prime numbers from the given list of integers using the Sieve of Eratosthenes algorithm.
    """
    if not numbers:
        return []

    max_number = max(numbers)
    is_prime = [True] * (max_number + 1)
    is_prime[0] = is_prime[1] = False

    for start in range(2, int(max_number**0.5) + 1):
        if is_prime[start]:
            for multiple in range(start*start, max_number + 1, start):
                is_prime[multiple] = False

    primes = [num for num in numbers if is_prime[num]]
    return primes

