def process_instructions(instructions):
    num_set = set()

    for instruction in instructions:
        action, value = instruction.split()
        value = int(value)

        if action == "add":
            num_set.add(value)
        elif action == "remove":
            num_set.discard(value)

    return sum(num_set)

