from collections import defaultdict, deque

def alienOrder(words):
    # Create a graph
    graph = defaultdict(set)
    indegree = {char: 0 for word in words for char in word}

    # Build the graph
    for i in range(len(words) - 1):
        first_word, second_word = words[i], words[i + 1]
        min_length = min(len(first_word), len(second_word))

        if first_word[:min_length] == second_word[:min_length] and len(first_word) > len(second_word):
            return ""  # Case when order is invalid

        for j in range(min_length):
            if first_word[j] != second_word[j]:
                if second_word[j] not in graph[first_word[j]]:
                    graph[first_word[j]].add(second_word[j])
                    indegree[second_word[j]] += 1
                break

    # Perform Topological Sort
    zero_indegree = deque([char for char in indegree if indegree[char] == 0])
    result = []

    while zero_indegree:
        current_char = zero_indegree.popleft()
        result.append(current_char)

        for neighbor in graph[current_char]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                zero_indegree.append(neighbor)

    if len(result) != len(indegree):
        return ""  # There's a cycle in the graph

    return "".join(result)

