def find_second_largest(nums):
    """
    Finds the second largest number in a list of numbers.
    """
    if len(nums) < 2:
        raise ValueError("列表中应至少有两个不同的数字")
    first, second = float('-inf'), float('-inf')
    for number in nums:
        if number > first:
            second = first
            first = number
        elif first > number > second:
            second = number
    if second == float('-inf'):
        raise ValueError("列表中应至少有两个不同的数字")
    return second

