def longest_substring_k_distinct(s, k):
    """
    Returns the length of the longest substring with at most k distinct characters and the substring itself.
    """
    if k == 0 or not s:
        return 0, ""

    start = 0
    max_len = 0
    max_substr = ""
    char_map = {}

    for end in range(len(s)):
        char_map[s[end]] = char_map.get(s[end], 0) + 1

        while len(char_map) > k:
            char_map[s[start]] -= 1
            if char_map[s[start]] == 0:
                del char_map[s[start]]
            start += 1

        if end - start + 1 > max_len:
            max_len = end - start + 1
            max_substr = s[start:end+1]

    return max_len, max_substr

