import re

def validate_emails(email_list):
    """
    Validates a list of emails according to the specified rules.

    Args:
    email_list (list): List of email addresses to validate.

    Returns:
    list: List of invalid email addresses.
    """
    if not isinstance(email_list, list):
        raise ValueError("Input must be a list.")
    if len(email_list) > 1000:
        raise ValueError("List cannot contain more than 1000 email addresses.")

    invalid_emails = []
    email_regex = re.compile(
        r'^([^@\s]+)@(([a-zA-Z0-9-]+\.)+[a-zA-Z]{2,})$'
    )

    for email in email_list:
        if not isinstance(email, str) or not email_regex.match(email):
            invalid_emails.append(email)
        else:
            domain = email.split("@")[1]
            domain_parts = domain.split(".")
            for part in domain_parts:
                if len(part) < 2 or part.startswith("-") or part.endswith("-"):
                    invalid_emails.append(email)
                    break

    return invalid_emails

def alternating_sequence(str1, str2, str3):
    """
    Returns a single string that alternates characters from the three input strings.
    """
    result = []
    max_len = max(len(str1), len(str2), len(str3))

    for i in range(max_len):
        if i < len(str1):
            result.append(str1[i])
        if i < len(str2):
            result.append(str2[i])
        if i < len(str3):
            result.append(str3[i])

    return "".join(result)

