import re

def reverse_words(sentence):
    if not sentence:
        raise ValueError("Input sentence cannot be empty")

    pattern = re.compile(r'(\w+|\W+)')
    tokens = pattern.findall(sentence)

    words = [token for token in tokens if token.isalnum()]
    reversed_words = list(reversed(words))

    reversed_sentence = []
    word_index = 0

    for token in tokens:
        if token.isalnum():
            reversed_sentence.append(reversed_words[word_index])
            word_index += 1
        else:
            reversed_sentence.append(token)

    return ''.join(reversed_sentence)

# Example usage:
# print(reverse_words("Hello, world! How are you?"))

