def highest_scorers(scores):
    """
    Returns a tuple containing the highest score and a list of indices of players with that score.

    Parameters:
    scores (list of int): List of player scores

    Returns:
    tuple: A tuple containing the highest score and list of indices of players with that score
    """
    if not scores:
        return (0, [])

    max_score = max(scores)
    if max_score <= 0:
        return (0, [])

    indices = [index for index, score in enumerate(scores) if score == max_score]
    return (max_score, indices)

