from typing import List

def longest_increasing_subsequence(arr: List[int]) -> int:
    """
    Finds the length of the longest subsequence such that
    all elements of the subsequence are sorted in strictly increasing order.
    """
    if not arr:
        return 0

    # DP array initialized with 1s as the minimum length of increasing subsequence will be 1
    dp = [1] * len(arr)

    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

