def max_profit_days(prices):
    """
    Given a list of stock prices, return a tuple of the best days (indices) to
    buy and sell the stock for maximum profit. If no profit can be made,
    return (None, None).
    """
    if len(prices) < 2:
        return (None, None)

    min_price_index = 0
    max_profit = 0
    buy_day = None
    sell_day = None

    for i in range(1, len(prices)):
        if prices[i] < prices[min_price_index]:
            min_price_index = i

        current_profit = prices[i] - prices[min_price_index]

        if current_profit > max_profit:
            max_profit = current_profit
            buy_day = min_price_index
            sell_day = i

    if max_profit == 0:
        return (None, None)

    return (buy_day, sell_day)

