def max_product(nums):
    """
    Returns the highest product of two unique elements from the list of integers.
    Returns None if the list has fewer than two elements.
    """
    if len(nums) < 2:
        return None

    nums = sorted(nums, reverse=True)
    # The highest product can be from the two largest positive or the two smallest (most negative) numbers.
    return max(nums[0] * nums[1], nums[-1] * nums[-2])

