def is_prime(n):
    """
    Determines if the given integer n is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sort_primes(lst):
    """
    Given an unsorted list of integers, returns a list of prime numbers sorted in ascending order.
    """
    primes = [x for x in lst if is_prime(x)]
    return sorted(primes)

