def first_non_repeated_char(s):
    """
    Returns the first non-repeated character in the string `s`.
    If all characters are repeated or the string is empty, returns a message indicating such.
    """
    char_count = {}

    # Count occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first non-repeated character
    for char in s:
        if char_count[char] == 1:
            return char

    return "All characters are repeated or the string is empty."

