def distribute_tasks(tasks):
    """
    Distributes tasks between two machines to minimize the total workload difference.
    """
    total_workload = sum(tasks)
    target = total_workload // 2

    dp = [[False] * (target + 1) for _ in range(len(tasks) + 1)]
    dp[0][0] = True

    for i in range(1, len(tasks) + 1):
        for j in range(target + 1):
            if j >= tasks[i - 1]:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - tasks[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    for i in range(target, -1, -1):
        if dp[len(tasks)][i]:
            closest_sum = i
            break

    machine1 = []
    machine2 = []
    w = closest_sum
    for i in range(len(tasks), 0, -1):
        if dp[i-1][w]:
            machine2.append(tasks[i-1])
        else:
            machine1.append(tasks[i-1])
            w -= tasks[i-1]

    return machine1, machine2

def count_unique_vowels(s):
    """
    Returns the number of unique vowels in the given string.
    Handles cases where input is not a string.
    """
    if not isinstance(s, str):
        return "Input must be a string"

    vowels = set('aeiou')
    s = s.lower()
    unique_vowels = {char for char in s if char in vowels}

    return len(unique_vowels)

