from typing import List

def longest_common_prefix(strings: List[str]) -> List[str]:
    def common_prefix(str1: str, str2: str) -> str:
        min_length = min(len(str1), len(str2))
        i = 0
        while i < min_length and str1[i] == str2[i]:
            i += 1
        return str1[:i]

    result = []
    n = len(strings)
    for i in range(n):
        for j in range(i + 1, n):
            result.append(common_prefix(strings[i], strings[j]))

    return result

def find_substring(s, k):
    if k == 0 or not s:
        return ""

    n = len(s)
    max_length = 0
    max_substring = ""
    left = 0
    char_dict = {}

    for right in range(n):
        char_dict[s[right]] = char_dict.get(s[right], 0) + 1

        while len(char_dict) > k:
            char_dict[s[left]] -= 1
            if char_dict[s[left]] == 0:
                del char_dict[s[left]]
            left += 1

        if len(char_dict) == k:
            if right - left + 1 > max_length:
                max_length = right - left + 1
                max_substring = s[left:right + 1]

    return max_substring

