def find_duplicates(nums):
    """
    Returns a list of integers that are duplicates in the input list,
    maintaining their order of first occurrence.
    """
    seen = {}
    duplicates = []

    for num in nums:
        if num in seen:
            if seen[num] == 1:
                duplicates.append(num)
            seen[num] += 1
        else:
            seen[num] = 1

    return duplicates

