def simulate_banking_system(operations: list) -> list:
    accounts = {}
    results = []

    for op in operations:
        if op['operation'] == 'create_account':
            accounts[op['account_id']] = op['initial_balance']

        elif op['operation'] == 'deposit':
            if op['account_id'] in accounts:
                accounts[op['account_id']] += op['amount']

        elif op['operation'] == 'withdraw':
            if op['account_id'] in accounts:
                if accounts[op['account_id']] >= op['amount']:
                    accounts[op['account_id']] -= op['amount']
                else:
                    print("Insufficient funds")

        elif op['operation'] == 'transfer':
            if (op['from_account_id'] in accounts and
                op['to_account_id'] in accounts):
                if accounts[op['from_account_id']] >= op['amount']:
                    accounts[op['from_account_id']] -= op['amount']
                    accounts[op['to_account_id']] += op['amount']
                else:
                    print("Insufficient funds")

        elif op['operation'] == 'get_balance':
            if op['account_id'] in accounts:
                results.append(accounts[op['account_id']])

    return results

