    Raises ValueError if the input list contains non-string items.
    """
    if not all(isinstance(item, str) for item in lst):
        raise ValueError("List must contain only strings")

    # Count occurrences of each string in a case-insensitive manner
    counts = {}
    for item in lst:
        item_lower = item.lower()
        if item_lower in counts:
            counts[item_lower] += 1
        else:
            counts[item_lower] = 1

    # Select only those items that appear more than once
    duplicates = {item: count for item, count in counts.items() if count > 1}
    return duplicates

