def are_anagrams(s1, s2):
    """
    Check if two strings are anagrams of each other.

    Two strings are anagrams if they can be written using the exact same characters
    (whitespace and punctuation included), just with a different arrangement.
    The solution does not use any libraries or helper functions for sorting or counting.
    """
    if len(s1) != len(s2):
        return False

    # Initialize a dictionary to count characters
    char_count = {}

    # Count characters in s1
    for char in s1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Subtract the count of characters in s2
    for char in s2:
        if char in char_count:
            char_count[char] -= 1
        else:
            return False

    # Check if all counts are zero
    for count in char_count.values():
        if count != 0:
            return False

    return True

