def find_duplicates(nums):
    """
    Returns a list of duplicated integers, ordered by their first occurrence.
    """
    seen = set()
    duplicates = set()
    result = []

    for num in nums:
        if num in seen:
            if num not in duplicates:
                duplicates.add(num)
                result.append(num)
        else:
            seen.add(num)

    return result

