def find_second_largest(arr):
    """
    Returns the second largest number in a list, or None if there are fewer than two distinct numbers.
    """
    if len(arr) < 2:
        return None

    first_max = second_max = None

    for num in arr:
        if first_max is None or num > first_max:
            second_max = first_max
            first_max = num
        elif num != first_max and (second_max is None or num > second_max):
            second_max = num

    return second_max

