def findOceanFlowPoints(matrix):
    if not matrix:
        return []

    m, n = len(matrix), len(matrix[0])
    pacific = [[False] * n for _ in range(m)]
    atlantic = [[False] * n for _ in range(m)]

    def dfs(x, y, ocean_matrix):
        stack = [(x, y)]
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        while stack:
            cx, cy = stack.pop()
            ocean_matrix[cx][cy] = True
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < m and 0 <= ny < n and not ocean_matrix[nx][ny] and matrix[nx][ny] >= matrix[cx][cy]:
                    stack.append((nx, ny))

    for i in range(m):
        dfs(i, 0, pacific)
        dfs(i, n-1, atlantic)
    for j in range(n):
        dfs(0, j, pacific)
        dfs(m-1, j, atlantic)

    result = []
    for i in range(m):
        for j in range(n):
            if pacific[i][j] and atlantic[i][j]:
                result.append((i, j))

    return result

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def nearest_smaller_prime(n):
    """
    If n is prime, returns the nearest prime number that is smaller than n.
    If n is not prime, returns n itself.
    """
    if not is_prime(n):
        return n
    candidate = n - 1
    while candidate > 1:
        if is_prime(candidate):
            return candidate
        candidate -= 1
    return -1  # Return -1 if no smaller prime is found, which should not happen for n > 2

def find_indices(nums, target):
    """
    Returns the indices of the two numbers in the array that add up to the target.
    Uses a hash map to achieve O(n) time complexity.
    """
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], i]
        num_to_index[num] = i
    return None

