def manage_inventory(transactions):
    """
    Takes a list of transactions and outputs the remaining inventory for each item.

    transactions: list of tuples (item_name, quantity, transaction_type)
    transaction_type: "purchase" or "sale"
    """
    inventory = {}

    for item_name, quantity, transaction_type in transactions:
        if item_name not in inventory:
            inventory[item_name] = 0

        if transaction_type == "purchase":
            inventory[item_name] += quantity
        elif transaction_type == "sale":
            if inventory[item_name] < quantity:
                raise ValueError(f"Cannot sell more {item_name} than available in inventory")
            inventory[item_name] -= quantity
        else:
            raise ValueError("Invalid transaction type. Expected 'purchase' or 'sale'")

    return inventory

