from typing import List, Dict, Any, Union

def highest_average_grade(students: List[Dict[str, Any]]) -> Union[str, List[str]]:
    """
    Returns the name of the student with the highest average grade.
    If there is a tie, returns a list of names sorted alphabetically.
    """
    highest_avg = -1
    res = []
    for student in students:
        avg_grade = sum(student["grades"]) / len(student["grades"])
        if avg_grade > highest_avg:
            highest_avg = avg_grade
            res = [student["name"]]
        elif avg_grade == highest_avg:
            res.append(student["name"])

    if len(res) == 1:
        return res[0]
    else:
        return sorted(res)

