def process_orders(N, items, M, orders):
    updated_items = items[:]

    for k, q in orders:
        item_index = k - 1
        item_price, item_stock = updated_items[item_index]
        if item_stock >= q:
            updated_items[item_index] = (item_price, item_stock - q)
        else:
            updated_items[item_index] = (item_price, 0)

    return updated_items

