def letter_combinations(digits):
    """
    Given a string containing digits from 2-9 inclusive, return all possible letter combinations
    that the number could represent on a traditional phone keypad.
    """
    if not digits:
        return []

    phone_mapping = {
        '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl', '6': 'mno',
        '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    }

    def backtrack(index, path):
        if index == len(digits):
            combinations.append("".join(path))
            return

        possible_letters = phone_mapping[digits[index]]
        for letter in possible_letters:
            path.append(letter)
            backtrack(index + 1, path)
            path.pop()

    combinations = []
    backtrack(0, [])
    return combinations

def process_strings(strings):
    """
    This function receives a list of strings and returns a new list with the strings reversed and in uppercase
    if the original string length is greater than 4. If the string length is 4 or less, the string is returned
    unchanged. Non-string inputs are ignored.

    :param strings: List of strings
    :return: New list with processed strings
    """
    result = []
    for s in strings:
        if isinstance(s, str):
            if len(s) > 4:
                result.append(s[::-1].upper())
            else:
                result.append(s)
        else:
            result.append(s)
    return result

