def char_frequency(s):
    """
    Return a dictionary containing the frequency of each character in the string,
    ignoring spaces and case-insensitive.
    """
    freq_dict = {}
    for char in s.lower():
        if char.isalpha():
            if char in freq_dict:
                freq_dict[char] += 1
            else:
                freq_dict[char] = 1
    return freq_dict

