def is_prime(num):
    """Helper function to determine if a number is prime."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while (i * i) <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def first_n_primes(n):
    """
    Returns a list of the first n prime numbers.

    Parameters:
    n (int): The number of prime numbers to generate.

    Returns:
    list of int: A list containing the first n prime numbers.
    """
    if n <= 0:
        return []

    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1

    return primes

