def fibonacci(n: int) -> int:
    """
    Compute the nth Fibonacci number using an efficient approach.
    """
    if n < 0:
        raise ValueError("The input n should be a non-negative integer.")

    if n == 0:
        return 0
    elif n == 1:
        return 1

    fib = [0, 1]
    for i in range(2, n + 1):
        fib.append(fib[-1] + fib[-2])
    return fib[-1]

