def word_length_count(words):
    """
    Returns a dictionary with word lengths as keys and the number of words of those lengths as values.
    The function is case-insensitive.
    """
    word_length_dict = {}
    for word in words:
        word_length = len(word)
        if word_length in word_length_dict:
            word_length_dict[word_length] += 1
        else:
            word_length_dict[word_length] = 1
    return word_length_dict

