def is_anagram(s1, s2):
    """
    Determines whether s2 is an anagram of s1.

    :param s1: First string
    :param s2: Second string
    :return: True if s2 is an anagram of s1, False otherwise
    """
    # If lengths of s1 and s2 aren't the same, s2 can't be an anagram of s1
    if len(s1) != len(s2):
        return False

    # Count frequencies of each character in both strings
    char_count_s1 = {}
    char_count_s2 = {}

    for char in s1:
        char_count_s1[char] = char_count_s1.get(char, 0) + 1

    for char in s2:
        char_count_s2[char] = char_count_s2.get(char, 0) + 1

    # Compare the frequency dictionaries
    return char_count_s1 == char_count_s2

