def consecutive_character_count(s):
    """
    Returns a list of tuples, where each tuple contains a character from the string and
    the number of consecutive occurrences of that character, excluding spaces.
    """
    if not s:
        return []

    result = []
    prev_char = ''
    count = 0

    for char in s:
        if char == ' ':
            continue
        if char == prev_char:
            count += 1
        else:
            if prev_char:
                result.append((prev_char, count))
            prev_char = char
            count = 1

    if prev_char:
        result.append((prev_char, count))

    return result

