def sum_primes(n):
    """
    Returns the sum of all prime numbers up to and including n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return 0

    sieve = [True] * (n + 1)
    sieve[0], sieve[1] = False, False

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start * start, n + 1, start):
                sieve[multiple] = False

    return sum(idx for idx, is_prime in enumerate(sieve) if is_prime)

def two_sum(nums, target):
    """
    Returns the indices of the two numbers in the list that add up to the target value.
    If no such pair exists, the function returns an empty list.
    """
    num_dict = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_dict:
            # Return sorted indices
            return sorted([num_dict[complement], i])
        num_dict[num] = i

    return []

