def four_sum(nums, target):
    """
    Returns a list of all unique quadruplets [a, b, c, d] such that a + b + c + d equals the target.
    """
    nums.sort()
    results = []
    n = len(nums)

    if n < 4:
        return results

    for i in range(n - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue

            left, right = j + 1, n - 1
            while left < right:
                sum_ = nums[i] + nums[j] + nums[left] + nums[right]
                if sum_ == target:
                    results.append([nums[i], nums[j], nums[left], nums[right]])
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif sum_ < target:
                    left += 1
                else:
                    right -= 1

    return results

def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    max_divisor = int(n**0.5) + 1
    for d in range(3, max_divisor, 2):
        if n % d == 0:
            return False
    return True

def prime_counts(numbers):
    """
    Returns a dictionary where the keys are the prime integers from the list,
    and the values are the number of times each prime integer appears in the list.
    """
    prime_count_dict = {}

    for num in numbers:
        if is_prime(num):
            if num in prime_count_dict:
                prime_count_dict[num] += 1
            else:
                prime_count_dict[num] = 1

    return prime_count_dict

def longest_zero_sum_subarray(arr):
    """
    Returns the length of the longest subarray with a sum of zero.
    """
    sum_to_index = {}
    max_length = 0
    current_sum = 0

    for i, num in enumerate(arr):
        current_sum += num

        if current_sum == 0:
            max_length = i + 1

        if current_sum in sum_to_index:
            max_length = max(max_length, i - sum_to_index[current_sum])
        else:
            sum_to_index[current_sum] = i

    return max_length

