def fibonacci(n):
    """
    Returns the n-th Fibonacci number.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def find_largest_palindromic_substring(s):
    """
    Returns the largest palindromic substring within the input string s.
    """
    def expand_around_center(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    if not s:
        return ""

    largest_palindrome = ""

    for i in range(len(s)):
        # Odd length palindromes:
        odd_palindrome = expand_around_center(s, i, i)
        if len(odd_palindrome) > len(largest_palindrome):
            largest_palindrome = odd_palindrome

        # Even length palindromes:
        even_palindrome = expand_around_center(s, i, i + 1)
        if len(even_palindrome) > len(largest_palindrome):
            largest_palindrome = even_palindrome

    return largest_palindrome

