def find_quadruplets(lst, k):
    """
    Returns a list of unique quadruplets from the input list that sum up to k.
    """
    lst.sort()
    quadruplets = set()
    n = len(lst)

    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            left, right = j + 1, n - 1
            while left < right:
                total = lst[i] + lst[j] + lst[left] + lst[right]
                if total == k:
                    quadruplets.add((lst[i], lst[j], lst[left], lst[right]))
                    left += 1
                    right -= 1
                elif total < k:
                    left += 1
                else:
                    right -= 1

    return [list(quad) for quad in sorted(quadruplets)]

