def longest_subarray_with_sum_k(arr, k):
    """
    Returns the length of the longest subarray with sum equal to k.
    """
    # Dictionary to store the cumulative sum up to all indices
    cum_sum_map = {}
    max_length = 0
    cum_sum = 0

    for i in range(len(arr)):
        cum_sum += arr[i]

        if cum_sum == k:
            max_length = i + 1

        if cum_sum - k in cum_sum_map:
            max_length = max(max_length, i - cum_sum_map[cum_sum - k])

        if cum_sum not in cum_sum_map:
            cum_sum_map[cum_sum] = i

    return max_length

