def calculate_average_scores(student_scores):
    """
    Calculate the average score for each student.

    :param student_scores: Dictionary where the keys are student names and values are lists of scores.
    :return: Dictionary with student names as keys and their average scores as values.
    """
    average_scores = {}
    for student, scores in student_scores.items():
        if scores:  # Check if the list is not empty
            average_scores[student] = sum(scores) / len(scores)
        else:
            average_scores[student] = 0.0  # Define behavior for students with no scores
    return average_scores

