def longest_subarray_with_sum(arr, S):
    """
    Returns the longest contiguous subarray that sums up to a given number S.
    """
    max_length = 0
    start_index = 0
    curr_sum = 0
    sum_dict = {}

    for i in range(len(arr)):
        curr_sum += arr[i]

        if curr_sum == S:
            if i + 1 > max_length:
                max_length = i + 1
                start_index = 0

        if curr_sum - S in sum_dict:
            if i - sum_dict[curr_sum - S] > max_length:
                max_length = i - sum_dict[curr_sum - S]
                start_index = sum_dict[curr_sum - S] + 1

        if curr_sum not in sum_dict:
            sum_dict[curr_sum] = i

    if max_length == 0:
        return []

    return arr[start_index:start_index + max_length]

