def split_into_pairs(nums, target):
    """
    Splits the given list into pairs such that the sum of each pair is equal to the target sum.
    If it is not possible, return an empty list.
    """
    from collections import Counter

    count = Counter(nums)
    result = []

    for num in nums:
        if count[num] > 0:
            complement = target - num
            if count[complement] > 0:
                if num == complement and count[num] < 2:
                    continue
                result.append((num, complement))
                count[num] -= 1
                count[complement] -= 1

    # Check if all counts are zero
    for num in nums:
        if count[num] > 0:
            return []

    return result

