from typing import List
from itertools import permutations

def generate_words(words: List[str], target_length: int) -> List[str]:
    # Concatenate all the words into one string of characters
    all_chars = ''.join(words)

    # Use permutations to get all possible combinations of the given length
    possible_words = {''.join(p) for p in permutations(all_chars, target_length)}

    # Return the sorted list of unique possible words
    return sorted(possible_words)

