def max_profit(sales):
    """
    Returns the maximum difference between any two sales figures where the
    lower sales figure comes earlier in the list than the higher sales figure.
    """
    if not sales or len(sales) < 2:
        return 0

    min_price = sales[0]
    max_diff = 0

    for price in sales[1:]:
        if price < min_price:
            min_price = price
        else:
            max_diff = max(max_diff, price - min_price)

    return max_diff

