def is_valid_parentheses(input_str):
    """
    Determines if the input_str contains valid arrangements of parentheses, brackets, and braces.

    Args:
    input_str (str): The input string containing parentheses, brackets, and braces.

    Returns:
    bool: True if the string is valid, otherwise False.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in input_str:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

from typing import List

def find_elements_appearing_twice(arr: List[int]) -> List[int]:
    """
    Identifies and returns a list of all unique elements that appear exactly twice in the array.

    :param arr: List of integers (input array)
    :return: List of integers containing all unique elements that appear exactly twice
    """
    element_count = {}
    result = []

    # Step 1: Count the occurrences of each element
    for num in arr:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    # Step 2: Collect elements that appear exactly twice
    for num, count in element_count.items():
        if count == 2:
            result.append(num)

    return result

