def multifaceted_sum(input_structure):
    """
    Sums all numeric values from a nested data structure that can include lists, dictionaries, and tuples.
    """
    total = 0

    if isinstance(input_structure, (list, tuple)):
        for element in input_structure:
            total += multifaceted_sum(element)
    elif isinstance(input_structure, dict):
        for key, value in input_structure.items():
            total += multifaceted_sum(value)
    elif isinstance(input_structure, (int, float)):
        total += input_structure

    return total

