def find_pair_with_sum(numbers, target_sum):
    """
    Returns a tuple of two integers from the list that add up to the target sum,
    or None if no such pair exists. This function has a time complexity of O(n).
    """
    seen_numbers = {}
    for number in numbers:
        complement = target_sum - number
        if complement in seen_numbers:
            return (complement, number)
        seen_numbers[number] = True
    return None

