def process_scores(data):
    import logging
    logging.basicConfig(level=logging.ERROR)

    if not data:
        raise ValueError("Input list is empty")

    scores = {}
    for entry in data:
        if len(entry) != 3:
            raise ValueError(f"Invalid tuple (does not contain exactly three elements): {entry}")

        first_name, last_name, score = entry
        full_name = f"{first_name} {last_name}"

        try:
            score = float(score)
        except ValueError:
            logging.error(f"Invalid score for {full_name}: {score}")
            continue

        if full_name not in scores:
            scores[full_name] = []
        scores[full_name].append(score)

    averages = [(name, sum(score_list) / len(score_list)) for name, score_list in scores.items()]
    averages.sort(key=lambda x: (x[1], x[0]))

    return averages

