from typing import List

def can_reach_end(steps: List[int]) -> bool:
    max_reachable = 0
    for i, step in enumerate(steps):
        if i > max_reachable:
            return False
        max_reachable = max(max_reachable, i + step)
        if max_reachable >= len(steps) - 1:
            return True
    return False

