def is_prime(n):
    """
    Helper function to determine if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def next_prime(n):
    """
    Helper function to find the next prime number greater than n.
    """
    candidate = n + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

def replace_with_next_prime(lst):
    """
    This function replaces each prime number in the list with the next higher prime number.
    """
    return [next_prime(x) if is_prime(x) else x for x in lst]

def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers less than n using the Sieve of Eratosthenes algorithm.
    """
    if n <= 2:
        return []

    sieve = [True] * n
    sieve[0] = sieve[1] = False

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n, start):
                sieve[multiple] = False

    return [num for num in range(n) if sieve[num]]

