def transform_string(s):
    """
    Transforms a string by replacing each letter with the next letter
    in the alphabet (wrapping 'z' to 'a') and each digit with the
    next digit (wrapping '9' to '0').
    """
    transformed = []

    for char in s:
        if char.isalpha():
            if char == 'z':
                transformed.append('a')
            else:
                transformed.append(chr(ord(char) + 1))
        elif char.isdigit():
            if char == '9':
                transformed.append('0')
            else:
                transformed.append(chr(ord(char) + 1))
        else:  # For non-alphanumeric characters, keep the same character
            transformed.append(char)

    return ''.join(transformed)

