def is_valid_ipv4(ip):
    """
    Determine if a given string is a valid IPv4 address.
    """
    parts = ip.split('.')
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True

