def find_pair_with_sum(integers, target_sum):
    """
    Finds the pair of integers in the array that add up to the target sum.
    Returns the pair as a tuple (a, b) such that a <= b. If no such pair exists,
    returns an empty tuple.
    """
    nums = {}
    result = []

    # Traverse the list
    for num in integers:
        complement = target_sum - num

        # Check if the complement exists in the dictionary
        if complement in nums:
            result.append((min(num, complement), max(num, complement)))

        # Add the number to the dictionary
        nums[num] = True

    # Sort the result based on the conditions mentioned
    if result:
        result.sort()
        return result[0]
    else:
        return ()

