def count_integers(numbers):
    """
    Processes a list of integers and returns a dictionary with the count of each unique integer in the list.
    Handles invalid inputs by returning an error message, and logs the error details into a separate list.
    """
    error_log = []
    try:
        if not isinstance(numbers, list):
            raise ValueError("Input must be a list.")
        if not all(isinstance(n, int) for n in numbers):
            raise ValueError("List must contain only integers.")

        count_dict = {}
        for num in numbers:
            if num in count_dict:
                count_dict[num] += 1
            else:
                count_dict[num] = 1
        return count_dict, error_log

    except ValueError as e:
        error_log.append(str(e))
        return "Invalid Input", error_log
    finally:
        if error_log:
            print("Errors occurred. Check error_log for details.")
        else:
            print("Processing completed without errors.")

