def fibonacci_sequence(n):
    """
    Returns a list of the first n numbers in the Fibonacci sequence.
    """
    if n <= 0:
        return []

    sequence = [0, 1]
    for i in range(2, n):
        sequence.append(sequence[-1] + sequence[-2])

    return sequence[:n]

