def calculate(s: str) -> int:
    """
    Evaluate a mathematical expression string involving non-negative integers
    and the operators +, -, *, and / (without parentheses).

    Parameters:
    s (str): The input string representing the expression.

    Returns:
    int: The result of evaluating the expression.
    """
    s = s.replace(" ", "")
    num_stack = []
    num = 0
    sign = '+'
    i = 0

    while i < len(s):
        char = s[i]

        if char.isdigit():
            num = num * 10 + int(char)

        if char in '+-*/' or i == len(s) - 1:
            if sign == '+':
                num_stack.append(num)
            elif sign == '-':
                num_stack.append(-num)
            elif sign == '*':
                num_stack.append(num_stack.pop() * num)
            elif sign == '/':
                top = num_stack.pop()
                if top < 0:
                    num_stack.append(-(-top // num))
                else:
                    num_stack.append(top // num)
            sign = char
            num = 0

        i += 1

    return sum(num_stack)

