def character_frequency(text):
    """
    Returns the frequency of each character in the given text, ignoring spaces and considering
    uppercase and lowercase versions of a character as the same character.
    """
    frequency = {}
    for char in text:
        if char != ' ':
            char = char.lower()
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1
    return frequency

