def get_users_with_transactions_over_threshold(transactions, threshold):
    """
    Returns the IDs of the users who have made transactions over the given threshold.
    """
    user_ids = set()
    for transaction in transactions:
        if transaction['amount'] > threshold:
            user_ids.add(transaction['user_id'])
