def count_occurrences(lst):
    """
    Returns a dictionary with the counts of each unique integer in the list.
    """
    counts = {}
    for num in lst:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1
    return counts

def filter_and_sort_odd_counts(count_dict):
    """
    Takes a dictionary of integer counts and returns a sorted list of tuples
    (integer, count) for integers that appear an odd number of times.
    """
    odd_count_tuples = [(num, count) for num, count in count_dict.items() if count % 2 != 0]
    odd_count_tuples.sort(key=lambda x: x[1], reverse=True)
    return odd_count_tuples

