def transform_list(nums: list) -> list:
    """
    Transforms the list such that elements at even indices are multiplied by two
    and elements at odd indices are replaced by their negation.
    """
    transformed = []
    for i, num in enumerate(nums):
        if i % 2 == 0:
            transformed.append(num * 2)
        else:
            transformed.append(-num)
    return transformed

