def is_prime(n):
    """
    Checks if a number n is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def filter_primes(numbers):
    """
    Filters out the prime numbers from the given list of numbers.
    """
    return [num for num in numbers if is_prime(num)]

