def find_single_number(nums: list) -> int:
    """
    Finds the element in the list that appears exactly once.

    Args:
    nums (list): A list of integers where each element appears twice except for one.

    Returns:
    int: The single number that appears only once.
    """
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    for num in nums:
        if count[num] == 1:
            return num

