from typing import List

def can_construct(target: str, word_bank: List[str]) -> bool:
    """
    Determine if the target string can be constructed from the word bank elements.
    """
    memo = {}

    def can_construct_memo(target):
        if target in memo:
            return memo[target]
        if target == "":
            return True

        for word in word_bank:
            if target.startswith(word):
                suffix = target[len(word):]
                if can_construct_memo(suffix):
                    memo[target] = True
                    return True

        memo[target] = False
        return False

    return can_construct_memo(target)

