def transform_string(s: str) -> str:
    transformed = []
    for char in s:
        if char.isupper():
            transformed.append(char.lower())
        elif char.islower():
            transformed.append(char.upper())
        elif char.isdigit():
            transformed.append('#')
        else:
            transformed.append(char)

    return ''.join(transformed)

