def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest strictly increasing subsequence in the array.

    :param arr: List[int] - The input array of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not arr:
        return 0

    # Initialize the dp array where dp[i] represents the length of the longest
    # increasing subsequence that ends with arr[i]
    dp = [1] * len(arr)

    # Construct the dp array
    for i in range(1, len(arr)):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in dp array
    return max(dp)

