def find_closest_pair(nums, target):
    if not nums or len(nums) < 2:
        return None

    nums.sort()
    closest_pair = (None, None)
    min_diff = float('inf')

    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]
        current_diff = abs(current_sum - target)

        if current_diff < min_diff:
            min_diff = current_diff
            closest_pair = (nums[left], nums[right])

        if current_sum < target:
            left += 1
        else:
            right -= 1

    return closest_pair

def max_profit(stock_prices):
    """
    Returns the maximum profit that can be achieved by buying and selling one share of stock.
    If no profit can be made, returns 0.
    """
    if not stock_prices or len(stock_prices) < 2:
        return 0

    min_price = stock_prices[0]
    max_profit = 0

    for price in stock_prices[1:]:
        profit = price - min_price
        if profit > max_profit:
            max_profit = profit
        if price < min_price:
            min_price = price

    return max_profit

