def is_prime(num):
    """
    Check if a number is prime.
    """
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def filter_primes(arr):
    """
    Returns an array containing only the prime numbers from the original array in the same order.
    """
    return [x for x in arr if is_prime(x)]

