def longest_increasing_span(temperatures):
    """
    Returns the length of the longest span of consecutive days with increasing temperatures.
    """
    if not temperatures:
        return 0

    max_span = 1
    current_span = 1

    for i in range(1, len(temperatures)):
        if temperatures[i] > temperatures[i - 1]:
            current_span += 1
            max_span = max(max_span, current_span)
        else:
            current_span = 1

    return max_span

