def group_dictionaries(dict_list: list, key: str, include_none: bool = True) -> dict:
    """
    The function takes a list of dictionaries and groups them by a specified key.
    :param dict_list: List of dictionaries to be grouped.
    :param key: Key by which the dictionaries should be grouped.
    :param include_none: Boolean flag to include or exclude None or missing key values.
    :return: Dictionary with grouped lists of dictionaries.
    """
    if not isinstance(dict_list, list):
        raise TypeError("First argument must be a list of dictionaries.")
    if not isinstance(key, str):
        raise TypeError("Second argument must be a string representing the key.")

    grouped_dict = {}
    for dictionary in dict_list:
        if not isinstance(dictionary, dict):
            raise TypeError("Elements of the list must be dictionaries.")

        value = dictionary.get(key, None)

        if not include_none and (value is None):
            continue

        if value not in grouped_dict:
            grouped_dict[value] = []
        grouped_dict[value].append(dictionary)

    return grouped_dict

