def can_be_palindrome(s: str) -> bool:
    """
    Return whether the string can be transformed into a palindrome by
    removing at most one character. The function should account for:
    - strings containing only lowercase letters.
    - strings containing a mix of uppercase and lowercase letters.
    """
    def is_palindrome_range(i, j):
        return all(s[k] == s[j - k + i] for k in range(i, j))

    s = s.lower()
    left, right = 0, len(s) - 1

    while left < right:
        if s[left] != s[right]:
            return is_palindrome_range(left + 1, right) or is_palindrome_range(left, right - 1)
        left += 1
        right -= 1

    return True

