def longest_divisible_subsequence(arr):
    if not arr:
        return 0

    n = len(arr)
    # Initialize the dp array where dp[i] will store the length of the longest divisible subsequence ending at index i
    dp = [1] * n

    max_length = 1

    # Fill dp array in a bottom-up manner
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] % arr[j] == 0 and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                max_length = max(max_length, dp[i])

    return max_length

