def next_greater_element(nums1, nums2):
    """
    Finds the next greater element for each element in nums1 within the list nums2.
    """
    result = []
    nums2_map = {num: -1 for num in nums2}
    stack = []

    for num in nums2:
        while stack and stack[-1] < num:
            smaller_num = stack.pop()
            nums2_map[smaller_num] = num
        stack.append(num)

    for num in nums1:
        result.append(nums2_map[num])

    return result

def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string s.
    If no such character exists, returns an underscore '_'.
    """
    for char in s:
        if s.count(char) == 1:
            return char
    return '_'

