def is_balanced_parentheses(s):
    """
    Checks if the string of parentheses is balanced.
    Returns True if balanced, False if not balanced, and "Invalid input" if input is invalid.
    """
    # Check if input contains invalid characters
    if not all(c in '()' for c in s):
        return "Invalid input"

    # Initialize counter for balance checking
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1

        # If balance goes negative, parentheses are not balanced
        if balance < 0:
            return False

    # If balance is zero, parentheses are balanced
    return balance == 0

