def evaluate_expression(expression):
    """
    Evaluates a string containing an algebraic expression comprised of single-digit integers
    and the four basic operations (addition, subtraction, multiplication, and division)
    with proper operator precedence.
    """
    import re
    tokens = re.findall(r'\d+|[*/+-]', expression)

    def apply_operator(operators, values):
        operator = operators.pop()
        right = values.pop()
        left = values.pop()

        if operator == '+':
            values.append(left + right)
        elif operator == '-':
            values.append(left - right)
        elif operator == '*':
            values.append(left * right)
        elif operator == '/':
            values.append(left / right)

    values = []
    operators = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    for token in tokens:
        if token.isdigit():
            values.append(int(token))
        else:
            while (operators and
                   precedence[operators[-1]] >= precedence[token]):
                apply_operator(operators, values)
            operators.append(token)

    while operators:
        apply_operator(operators, values)

    return values[0]

