def first_non_repeated_character(s):
    """
    Returns the first non-repeated character in a given string s. If no such character exists, returns an empty string.
    """
    # Dictionary to store character counts
    char_count = {}

    # First pass to count occurrences
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass to find the first non-repeated character
    for char in s:
        if char_count[char] == 1:
            return char

    return ""

# Time complexity: O(n) - where n is the length of the string

