def calculate_total_spending(transactions):
    """
    Given a list of transactions, calculate the total spending per user.

    :param transactions: List of dictionaries, each containing 'user_id', 'item', and 'amount'.
    :return: Dictionary with user_id as keys and total spending as values.
    """
    spending = {}

    for transaction in transactions:
        # Validate transaction format
        if not isinstance(transaction, dict):
            raise ValueError("Each transaction must be a dictionary.")
        if not all(key in transaction for key in ["user_id", "item", "amount"]):
            raise ValueError("Each transaction must contain 'user_id', 'item', and 'amount'.")
        if not isinstance(transaction['user_id'], int):
            raise ValueError("'user_id' must be an integer.")
        if not isinstance(transaction['amount'], (int, float)):
            raise ValueError("'amount' must be a number.")

        user_id = transaction['user_id']
        amount = transaction['amount']

        if user_id in spending:
            spending[user_id] += amount
        else:
            spending[user_id] = amount

    return spending

