def is_prime(num):
    """
    Checks if a number is prime.
    """
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def squares_of_primes(numbers):
    """
    Returns a list of squares of prime numbers from the input list.
    """
    return [num ** 2 for num in numbers if is_prime(num)]

