def evalRPN(tokens):
    """
    Evaluate the value of an arithmetic expression in Reverse Polish Notation (postfix notation).

    Args:
    tokens (List[str]): List of strings representing the postfix expression.

    Returns:
    int: The result of the expression.
    """
    stack = []

    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = int(stack.pop())
            a = int(stack.pop())
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # int(a / b) truncates towards zero in Python 3
                stack.append(int(a / b))
        else:
            stack.append(int(token))

    return stack[0]

