def shift_string(s):
    """
    Shifts each letter in the string by one position in the alphabet and each digit by its successor.
    Non-alphanumeric characters remain unchanged.
    """
    shifted_str = []
    for char in s:
        if char.isalpha():
            if char == 'z':
                shifted_str.append('a')
            elif char == 'Z':
                shifted_str.append('A')
            else:
                shifted_str.append(chr(ord(char) + 1))
        elif char.isdigit():
            if char == '9':
                shifted_str.append('0')
            else:
                shifted_str.append(str(int(char) + 1))
        else:
            shifted_str.append(char)
    return ''.join(shifted_str)

