def valid_brackets(string: str) -> bool:
    def check(s, opening="([{", closing=")]}", match=dict(zip("([{", ")]}"))):
        stack = []
        for char in s:
            if char in opening:
                stack.append(char)
            elif char in closing:
                if not stack or match[stack.pop()] != char:
                    return False
        return not stack

    return check(string)


def longest_valid_brackets_substring(string: str) -> str:
    n = len(string)
    max_len = 0
    start_index = 0

    dp = [0] * n

    for i in range(1, n):
        if string[i] == ')':
            if i - dp[i-1] - 1 >= 0 and string[i - dp[i-1] - 1] == '(':
                dp[i] = dp[i-1] + 2 + (dp[i - dp[i-1] - 2] if i - dp[i-1] - 2 >= 0 else 0)
                if dp[i] > max_len:
                    max_len = dp[i]
                    start_index = i - dp[i] + 1
        elif string[i] == '}':
            if i - dp[i-1] - 1 >= 0 and string[i - dp[i-1] - 1] == '{':
                dp[i] = dp[i-1] + 2 + (dp[i - dp[i-1] - 2] if i - dp[i-1] - 2 >= 0 else 0)
                if dp[i] > max_len:
                    max_len = dp[i]
                    start_index = i - dp[i] + 1
        elif string[i] == ']':
            if i - dp[i-1] - 1 >= 0 and string[i - dp[i-1] - 1] == '[':
                dp[i] = dp[i-1] + 2 + (dp[i - dp[i-1] - 2] if i - dp[i-1] - 2 >= 0 else 0)
                if dp[i] > max_len:
                    max_len = dp[i]
                    start_index = i - dp[i] + 1

    return string[start_index:start_index + max_len]

