def first_missing_positive(nums):
    """
    Finds the smallest missing positive integer in an unsorted array.

    Parameters:
    nums (List[int]): The input list of integers

    Returns:
    int: The smallest missing positive integer
    """
    n = len(nums)

    # Step 1: Replace negative numbers, zeros, and numbers larger than n with n+1
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Step 2: Use the index as a hash and mark the presence of an element
    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            nums[num - 1] = -abs(nums[num - 1])

    # Step 3: The first index that is positive is the smallest missing positive number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

