def valid_bracket_sequence(s):
    """
    Determine whether the given string s is a valid sequence of brackets.

    :param s: String composed of brackets '()', '[]', '{}'
    :return: True if the sequence is valid, False otherwise
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map:
            if not stack or bracket_map[char] != stack.pop():
                return False
        else:
            # Invalid character
            return False

    return not stack

def is_prime(num):
    """
    Helper function to check if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def prime_diff(lst, n):
    """
    Given a list lst and its length n, returns the difference between the smallest
    prime number and the largest prime number in the list. If there are no prime numbers, return -1.
    """
    primes = [num for num in lst if is_prime(num)]
    if not primes:
        return -1
    return max(primes) - min(primes)

