def get_grade(scores):
    """
    Returns a dictionary with exam scores as keys and corresponding letter grades as values.

    :param scores: List of exam scores
    :return: Dictionary with scores and their corresponding grades
    """
    grade_dict = {}
    for score in scores:
        if 90 <= score <= 100:
            grade_dict[score] = 'A'
        elif 80 <= score <= 89:
            grade_dict[score] = 'B'
        elif 70 <= score <= 79:
            grade_dict[score] = 'C'
        elif 60 <= score <= 69:
            grade_dict[score] = 'D'
        else:
            grade_dict[score] = 'F'
    return grade_dict

