def find_substring_positions(string, substring):
    """
    Returns a list of starting positions where substring is found in string.
    """
    positions = []
    for i in range(len(string) - len(substring) + 1):
        if string[i:i + len(substring)] == substring:
            positions.append(i)
    return positions

