def is_balanced(s):
    """
    Determines whether a given string of parentheses is balanced.

    :param s: str - input string containing only characters '(' and ')'
    :return: bool - True if the parentheses are balanced, otherwise False
    """
    stack = []
    for char in s:
        if char == '(':
            # Push the character onto the stack
            stack.append(char)
        elif char == ')':
            # Pop the stack if it's not empty
            if stack:
                stack.pop()
            else:
                # More closing parentheses than opening ones
                return False
    # Stack should be empty if all parentheses are balanced
    return not stack

