def longest_common_prefix(words):
    if not words:
        return ""

    # Sort the list
    words.sort()

    # The longest common prefix must be a prefix of the first and last word after sorting
    first_word = words[0]
    last_word = words[-1]
    common_prefix_length = 0

    for i in range(min(len(first_word), len(last_word))):
        if first_word[i] == last_word[i]:
            common_prefix_length += 1
        else:
            break

    return first_word[:common_prefix_length]

