import random

def select_random_exercise(exercises, user_level):
    """
    Selects a random exercise from the exercises dictionary that is
    at or below the user's level.

    Parameters:
    exercises (dict): A dictionary where keys are types of exercises and values are lists of exercise dictionaries.
    user_level (int): The user's current level of skill.

    Returns:
    dict: A randomly selected exercise that meets the level requirement.
    """
    eligible_exercises = []

    for exercise_list in exercises.values():
        for exercise in exercise_list:
            if exercise['level'] <= user_level:
                eligible_exercises.append(exercise)

    if eligible_exercises:
        return random.choice(eligible_exercises)
    else:
        return None

