def find_first_duplicate(A, B):
    """
    Finds the first duplicate element in B that is also present in A.
    """
    count_dict = {}
    for num in A:
        count_dict[num] = 0

    for num in B:
        if num in count_dict:
            count_dict[num] += 1
            if count_dict[num] > 1:
                return num

    return None

def twoSum(nums, target):
    """
    Returns True if there is at least one pair of numbers in the list
    that adds up to the target sum, otherwise returns False.
    """
    hash_table = {}
    for num in nums:
        if (target - num) in hash_table:
            return True
        hash_table[num] = 1
    return False

