def word_frequency(string):
    frequency = {}
    words = string.split()
    for word in words:
        # Remove non-alphanumeric characters
        cleaned_word = ''.join(e for e in word if e.isalnum()).lower()
        if cleaned_word in frequency:
            frequency[cleaned_word] += 1
        else:
            frequency[cleaned_word] = 1
    return frequency

