def longest_common_subsequence(seq1, seq2):
    """
    Returns the longest common subsequence between two sequences.
    """
    n = len(seq1)
    m = len(seq2)

    # Create a table to store lengths of longest common subsequence
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Build the dp matrix
    for i in range(n):
        for j in range(m):
            if seq1[i] == seq2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    # Length of the longest common subsequence
    lcs_length = dp[n][m]

    # Reconstruct the longest common subsequence
    i, j = n, m
    lcs = []
    while i > 0 and j > 0:
        if seq1[i - 1] == seq2[j - 1]:
            lcs.append(seq1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # The lcs array will be in reverse order
    lcs.reverse()

    # Return as string if inputs are strings, else return as appropriate sequence type
    if isinstance(seq1, str) and isinstance(seq2, str):
        return ''.join(lcs)
    elif isinstance(seq1, (list, tuple)) and isinstance(seq2, (list, tuple)):
        return type(seq1)(lcs)
    else:
        return lcs

def fizz_buzz(n):
    """
    Returns a list of strings representing the FizzBuzz sequence from 1 to n.
    For multiples of 3, the string "Fizz" is used.
    For multiples of 5, the string "Buzz" is used.
    For multiples of both 3 and 5, the string "FizzBuzz" is used.
    """
    result = []
    for i in range(1, n+1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def get_permutations(seq):
    """
    Return a list of all possible permutations of the given sequence.
    """
    if len(seq) == 0:
        return [[]]
    if len(seq) == 1:
        return [seq]
    else:
        permutations = []
        for i in range(len(seq)):
            element = seq[i]
            rest = seq[:i] + seq[i + 1:]
            for p in get_permutations(rest):
                permutations.append([element] + p)
        return permutations

def three_sum(nums):
    """
    Given an array of integers, find all unique triplets in the array that sum to 0.

    Args:
        nums (list): A list of integers.

    Returns:
        list: A list of lists, where each sublist contains three integers that sum to 0.
    """
    nums.sort()
    res = []
    for i in range(len(nums)-2):
        if i > 0 and nums[i] == nums[i-1]:
            continue
        left, right = i+1, len(nums)-1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total < 0:
                left += 1
            elif total > 0:
                right -= 1
            else:
                res.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left+1]:
                    left += 1
                while left < right and nums[right] == nums[right-1]:
                    right -= 1
                left += 1
                right -= 1
    return res

def find_pairs(numbers, target_sum):
    """
    Returns a list of unique pairs of numbers from the input list that add up to the target sum.
    Each pair is a tuple and the pairs are sorted in ascending order.
    """
    pairs = set()
    seen = set()

    for number in numbers:
        complement = target_sum - number
        if complement in seen:
            pairs.add(tuple(sorted((number, complement))))
        seen.add(number)

    return sorted(list(pairs))

