def search_rotated_sorted_array(nums, target):
    """
    Searches for a target value in a rotated sorted array.
    :param nums: List[int], the rotated sorted array
    :param target: int, the target value to search for
    :return: int, the index of the target value in the array if found, else -1
    """
    if not nums:
        return -1

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if nums[mid] == target:
            return mid

        # Determine which part is properly sorted
        if nums[left] <= nums[mid]:
            # Left part is sorted
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right part is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

