def max_subarray_with_pos_neg(nums):
    """
    Returns the maximum sum of a contiguous subarray within the given list of integers
    that contains at least one negative number and at least one positive number.

    The function uses a modified Kadane's algorithm to achieve this.
    """
    n = len(nums)
    if n == 0:
        return 0

    max_sum = float('-inf')
    current_sum = 0
    has_positive = False
    has_negative = False

    for num in nums:
        current_sum += num
        max_sum = max(max_sum, current_sum)
        if current_sum < 0:
            current_sum = 0

        if num > 0:
            has_positive = True
        if num < 0:
            has_negative = True

    if has_positive and has_negative:
        return max_sum
    else:
        return max(nums)  # Fallback in case there is no valid subarray

