def hex_to_rgb(hex_color):
    """Convert hexadecimal color to RGB"""
    hex_color = hex_color.lstrip('#')
    return tuple(int(hex_color[i:i+2], 16) for i in (0, 2, 4))

def rgb_to_hex(rgb_color):
    """Convert RGB color to hexadecimal"""
    return '#{:02x}{:02x}{:02x}'.format(*rgb_color)

def average_color(hex_color1, hex_color2):
    """Calculate the average color of two colors in hexadecimal"""
    rgb1 = hex_to_rgb(hex_color1)
    rgb2 = hex_to_rgb(hex_color2)
    avg_rgb = [(c1 + c2) // 2 for c1, c2 in zip(rgb1, rgb2)]
    return rgb_to_hex(avg_rgb)

