def find_divisor(n):
    """
    Returns the smallest divisor of n.
    If n is less than 1, return None.
    """
    if n < 1:
        return None
    for i in range(2, n + 1):
        if n % i == 0:
            return i
    return n  # In case n is prime or 1, return n itself

