def min_values_in_subarrays(arr, subarrays):
    min_values = []
    for subarray in subarrays:
        start, end = subarray
        subarray_values = arr[start:end+1]
        # Check if the subarray is ascending
        if subarray_values == sorted(subarray_values):
            min_value = subarray_values[0]
        # Check if the subarray is descending
        elif subarray_values == sorted(subarray_values, reverse=True):
            min_value = subarray_values[-1]
        else:
            raise ValueError("Subarrays should be either ascending or descending")
        min_values.append(min_value)
    return min_values

