def bellman_ford(graph, source):
    """
    This function implements the Bellman-Ford algorithm to find the shortest path from the source vertex
    to all other vertices in the graph.

    Parameters:
    graph (dict): A dictionary representing the graph, where each key is a vertex and its corresponding
                  value is a list of tuples containing the neighboring vertex and the edge weight.
    source (str): The source vertex.

    Returns:
    distance (dict): A dictionary containing the shortest distance from the source vertex to all other vertices.
    predecessor (dict): A dictionary containing the predecessor of each vertex in the shortest path.
    """
    # Initialize distance and predecessor
    distance = {vertex: float('inf') for vertex in graph}
    predecessor = {vertex: None for vertex in graph}

    # The distance from the source to itself is 0
    distance[source] = 0

    # Relaxation step (|V| - 1 times)
    for _ in range(len(graph) - 1):
        for u in graph:
            for v, weight in graph[u]:
                if distance[u] + weight < distance[v]:
                    distance[v] = distance[u] + weight
                    predecessor[v] = u

    # Check for negative-weight cycles
    for u in graph:
        for v, weight in graph[u]:
            if distance[u] + weight < distance[v]:
                raise ValueError("Graph contains a negative-weight cycle")

    return distance, predecessor

