        'B': [('C', 2), ('D', 2)],
        'C': [('D', 3)],
        'D': []
    }
    source = 'A'
    distance, predecessor = bellman_ford(graph, source)
    assert distance == {'A': 0, 'B': 1, 'C': 3, 'D': 3}
    assert predecessor == {'A': None, 'B': 'A', 'C': 'B', 'D': 'B'}

def test_bellman_ford_with_negative_weight_edges():
