        'B': [('C', 3), ('D', 2), ('E', 2)],
        'D': [('B', 1), ('C', 5)],
        'E': [('D', -3)],
        'C': []
    }
    source = 'A'
    distance, predecessor = bellman_ford(graph, source)
    assert distance == {'A': 0, 'B': -1, 'C': 2, 'D': -2, 'E': 1}
    assert predecessor == {'A': None, 'B': 'A', 'C': 'B', 'D': 'E', 'E': 'B'}

