def find_key_by_value(data, target_value):
    """
    Recursively searches for the target_value in the JSON-like dictionary (can include nested objects and arrays)
    and returns the key associated with the target_value. If the target_value is not found, returns None.
    """
    if isinstance(data, dict):
        for key, value in data.items():
            if value == target_value:
                return key
            elif isinstance(value, (dict, list)):
                found_key = find_key_by_value(value, target_value)
                if found_key:
                    return found_key
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, (dict, list)):
                found_key = find_key_by_value(item, target_value)
                if found_key:
                    return found_key
    return None

