def find_common_elements(list_a, list_b):
    """
    Returns a list of common elements between list_a and list_b.
    """
    # Convert list_a to a set for O(1) average time complexity lookups
    set_a = set(list_a)
    # Using set comprehension to find common elements
    common_elements = {element for element in list_b if element in set_a}
    return list(common_elements)

def max_subarray_sum(arr):
    """
    Returns the maximum sum of a contiguous subarray within a one-dimensional array of numbers.
    Uses Kadane's Algorithm to solve the problem efficiently.
    """
    if not arr:
        return 0

    max_current = max_global = arr[0]

    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

