def find_dna_sequence(n):
    """
    Returns a DNA sequence of length n, where the sequence is made up of 'A', 'C', 'G', 'T'
    cycled in that order.
    """
    dna_sequence = ''
    for i in range(n):
        if i % 4 == 0:
            dna_sequence += "A"
        elif i % 4 == 1:
            dna_sequence += "C"
        elif i % 4 == 2:
            dna_sequence += "G"
        else:
            dna_sequence += "T"
    return dna_sequence

