def combine_users(active_users, inactive_users):
    combined_users = {}

    # Adding active users with status "active"
    for user_id, user_info in active_users.items():
        user_info['status'] = 'active'
        combined_users[user_id] = user_info

    # Adding inactive users with status "inactive"
    for user_id, user_info in inactive_users.items():
        user_info['status'] = 'inactive'
        combined_users[user_id] = user_info

    return combined_users

