def fibonacci(n):
    """
    Returns the nth number in the Fibonacci sequence.
    """
    if n < 0:
        raise ValueError("Input cannot be negative")
    elif n <= 1:
        return n
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

