def sieve_of_eratosthenes(a, b):
    """
    Returns a list of all prime numbers in the range [a, b].
    """
    # Create a boolean array "prime[0..b]" and initialize all entries it as true
    prime = [True for _ in range(b + 1)]
    p = 2
    while p * p <= b:
        # If prime[p] is not changed, then it is a prime
        if prime[p]:
            # Update all multiples of p to not prime
            for i in range(p * p, b + 1, p):
                prime[i] = False
        p += 1

    # Collect all prime numbers in range [a, b]
    primes = []
    for p in range(max(a, 2), b + 1):
        if prime[p]:
            primes.append(p)

    return primes

