def check_collisions(objects):
    """
    Checks for collisions between multiple objects.
    The objects parameter is a list of dictionaries where each dictionary represents an object's position.
    Each dictionary should have 'x' and 'y' keys for the position.

    Returns a list of tuples where each tuple contains the indices of two colliding objects.
    """
    collisions = []
    for i in range(len(objects)):
        for j in range(i + 1, len(objects)):
            if objects[i]['x'] == objects[j]['x'] and objects[i]['y'] == objects[j]['y']:
                collisions.append((i, j))
    return collisions

