import re

def check_phone_number_format(phone_number):
    """
    Check if the phone number has a valid format and add country code if not present.
    """
    valid_pattern = r'^\+1 \d{3}-\d{3}-\d{4}$'
    basic_pattern = r'\d{3}-\d{3}-\d{4}'

    if re.match(valid_pattern, phone_number):
        return phone_number
    elif re.match(basic_pattern, phone_number):
        return "+1 " + phone_number
    else:
        digits_pattern = r'\d{10}'
        if re.match(digits_pattern, phone_number):
            return "+1 " + phone_number[:3] + "-" + phone_number[3:6] + "-" + phone_number[6:]

    return None

def format_phone_numbers(phone_numbers):
    """
    Takes a list of phone numbers and returns a list of formatted phone numbers.
    """
    formatted_numbers = []
    for number in phone_numbers:
        formatted_number = check_phone_number_format(number)
        if formatted_number:
            formatted_numbers.append(formatted_number)
    return formatted_numbers

