def has_increasing_subsequence(sequence):
    if len(sequence) < 4:
        return False

    first = second = third = float('inf')

    for num in sequence:
        if num <= first:
            first = num
        elif num <= second:
            second = num
        elif num <= third:
            third = num
        else:
            return True

    return False

