import json

def extract_values(data):
    """
    Recursively extracts all values from a nested JSON object or array.

    Parameters:
    data (dict or list): The JSON object or array to extract values from.

    Returns:
    list: A list of all values found in the JSON object or array.
    """
    values = []
    if isinstance(data, dict):
        for key, value in data.items():
            if isinstance(value, (dict, list)):
                values.extend(extract_values(value))
            else:
                values.append(value)
    elif isinstance(data, list):
        for item in data:
            if isinstance(item, (dict, list)):
                values.extend(extract_values(item))
            else:
                values.append(item)
    return values

