    """
    Returns the number of flat integers in a nested list.

    A flat integer is one which is not in any sublist, or is directly inside any of the sublists.
    """
    def count_flat(lst):
        count = 0
        for item in lst:
            if isinstance(item, int):
                count += 1
            elif isinstance(item, list):
                count += count_flat(item)
        return count

    return count_flat(nested_list)

