def matrix_multiply(A, B):
    """
    Multiplies two square matrices A and B.
    """
    n = len(A)
    # Initialize result matrix with zeros
    C = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]

    return C

def calculate_vowel_percentage(input_string):
    if not isinstance(input_string, str):
        raise TypeError(f"Expected a string, but received {type(input_string).__name__} instead.")
    vowels = 'aeiou'
    vowel_count = sum(1 for char in input_string.lower() if char in vowels)
    total_count = sum(1 for char in input_string.lower() if char.isalpha())
    percentage = (vowel_count / total_count) * 100 if total_count != 0 else 0
    return round(percentage, 2)

