def valid_ipv4_address(ip):
    """
    Determines whether a given string is a valid IPv4 address.

    Args:
    ip (str): The IPv4 address in string format.

    Returns:
    bool: True if the string is a valid IPv4 address, False otherwise.
    """
    parts = ip.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit():
            return False
        if len(part) > 1 and part[0] == "0":
            return False
        if not 0 <= int(part) <= 255:
            return False
    return True

