def is_prime(n):
    """
    Returns True if n is a prime number, otherwise returns False.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def first_n_primes(n):
    """
    Returns the first n prime numbers as a list.
    """
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes

def first_10_primes():
    """
    Returns the first 10 prime numbers.
    """
    return first_n_primes(10)

import math

def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

