from collections import defaultdict

def findItinerary(routes, source, dest):
    """
    Reconstructs the flight itinerary using the given routes.

    Args:
    routes (list): A list of lists containing two strings representing the departure and arrival airports.
    source (str): The source airport.
    dest (str): The destination airport.

    Returns:
    list: A list of strings representing the flight itinerary.
    """
    graph = defaultdict(list)
    for start, end in routes:
        graph[start].append(end)

    # Function to perform Depth First Search
    def dfs(current, itinerary):
        if current == dest:
            return itinerary
        if current in graph:
            for next_stop in graph[current]:
                result = dfs(next_stop, itinerary + [next_stop])
                if result:
                    return result
        return None

    return dfs(source, [source])

