def convert_to_base(number, base):
    convertString = "0123456789ABCDEF"
    if number < base:
        return convertString[number]
    else:
        return convert_to_base(number // base, base) + convertString[number % base]

def int_to_base(number):
    return convert_to_base(number, 2), convert_to_base(number, 8), convert_to_base(number, 16)

