def longest_subsequence_with_no_repeats(nums):
    if not nums:
        return []

    seen = set()
    start = 0
    max_length = 0
    max_subsequence = []

    for i, num in enumerate(nums):
        while num in seen:
            seen.remove(nums[start])
            start += 1
        seen.add(num)
        if i - start + 1 > max_length:
            max_length = i - start + 1
            max_subsequence = nums[start:i+1]

    return max_subsequence

