def is_prime(num):
    """
    Check if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num ** 0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def n_largest_primes(n):
    """
    Return the n largest prime numbers.
    """
    if n <= 0:
        return []

    primes = []
    current = 2
    while len(primes) < n:
        if is_prime(current):
            primes.append(current)
        current += 1

    return primes[-n:][::-1]

def find_similar_pairs(lst):
    """
    Finds all pairs of strings that have the same digits but possibly in a different order.
    """
    from collections import defaultdict

    # Dictionary to store lists of similar strings classified by the sorted tuple of characters
    similar_dict = defaultdict(list)

    # Classify the strings by their sorted tuple of characters
    for string in lst:
        key = tuple(sorted(string))
        similar_dict[key].append(string)

    # Generate pairs from the classified lists
    pairs = []
    for values in similar_dict.values():
        if len(values) > 1:
            for i in range(len(values)):
                for j in range(i + 1, len(values)):
                    pairs.append([values[i], values[j]])

    return pairs

