def first_duplicate_index(nums):
    """
    Returns the index of the first duplicate in the list.
    If no duplicate is found, returns -1.
    """
    seen = {}
    for index, num in enumerate(nums):
        if num in seen:
            return index
        seen[num] = True
    return -1

