def print_numbers(n):
    """
    Prints numbers from 1 to n, with substitutions for multiples of 3 and 5.
    For multiples of 3, print 'Three'.
    For multiples of 5, print 'Five'.
    For multiples of both, print 'ThreeFive'.
    """
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            print('ThreeFive')
        elif i % 3 == 0:
