def fizz_buzz(n):
    """
    Returns a list of strings representing the FizzBuzz sequence up to n.

    :param n: A positive integer
    :return: A list of strings
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

