def find_max_and_min(lst):
    """
    Given a list 'lst' of objects of any type,
    returns a tuple containing the maximum and minimum values in the list
    based on the type of the values.
    """
    if not lst:
        return (None, None)

    max_val = max(lst)
    min_val = min(lst)
    return (max_val, min_val)

