import math

def gym(*args):
    """
    Returns the number of permutations of the input arguments.
    If there are repeated numbers, returns 0.
    If no arguments are provided, returns 1.
    """
    if len(args) != len(set(args)):
        return 0
    return math.factorial(len(args))

