def first_duplicate(nums):
    def recursive_func(nums, seen):
        if not nums:
            return None
        elif nums[0] in seen:
            return nums[0]
        else:
            seen.add(nums[0])  # Use set instead of list for O(1) lookups
            return recursive_func(nums[1:], seen)
    return recursive_func(nums, set())

