def parse_transactions(transactions):
    portfolio = {}
    for t in transactions:
        # Parse the transaction
        ty, quantity, symbol, price = parse_transaction(t)

        # Add or subtract the shares and cost accordingly
        if ty == 'Buy':
            if symbol not in portfolio:
                portfolio[symbol] = {'quantity': 0, 'total_cost': 0}
            portfolio[symbol]['quantity'] += quantity
            portfolio[symbol]['total_cost'] += quantity * price
        elif ty == 'Sell':
            if symbol in portfolio:
                portfolio[symbol]['quantity'] -= quantity
                portfolio[symbol]['total_cost'] -= quantity * price

    # Convert the portfolio dictionary to a list of dictionaries
    portfolio_list = []
    for symbol, details in portfolio.items():
        portfolio_list.append({
            'symbol': symbol,
            'quantity': details['quantity'],
            'average_price': details['total_cost'] / details['quantity'] if details['quantity'] != 0 else 0
        })

    return portfolio_list

# Helper function to parse a single transaction
def parse_transaction(t):
    import re
    match = re.match(r'(Buy|Sell) (\d+) shares? of (\w+) stock at \$(\d+\.\d+)', t)
    if match:
        ty = match.group(1)
        quantity = int(match.group(2))
        symbol = match.group(3)
        price = float(match.group(4))
        return ty, quantity, symbol, price
    else:
        raise ValueError("Transaction format is incorrect.")

def maxInWindow(E, k):
    """
    Compute the maximum of each kxk window in the 2D array E.
    """
    n = len(E)
    m = len(E[0])
    if k <= 0:
        raise ValueError("Window size k must be greater than 0")

    F = []
    for i in range(n - k + 1):
        row = []
        for j in range(m - k + 1):
            window_max = float('-inf')
            for x in range(i, min(i + k, n)):
                for y in range(j, min(j + k, m)):
                    window_max = max(window_max, E[x][y])
            row.append(window_max)
        F.append(row)
    return F

