def find_first_and_last(nums, target):
    """
    Returns the indices of the first and last occurrence of target in the sorted array nums.
    If target is not found, returns [-1, -1].
    """
    def find_first(nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return left

    def find_last(nums, target):
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] > target:
                right = mid - 1
            else:
                left = mid + 1
        return right

    first = find_first(nums, target)
    last = find_last(nums, target)

    if first <= last and first < len(nums) and nums[first] == target:
        return [first, last]
    else:
        return [-1, -1]

