def are_arrays_identical(array1, array2):
    """
    Returns True if array1 and array2 are identical, i.e., they have
    the same elements in the same order, otherwise returns False.
    """
    if len(array1) != len(array2):
        return False

    for str1, str2 in zip(array1, array2):
        if str1 != str2:
            return False

    return True

