def min_rooms_meetings(intervals):
    """
    Returns the minimum number of meeting rooms required for the given intervals.
    """
    if not intervals:
        return 0

    intervals.sort(key=lambda x: x[0])
    rooms = [intervals[0][1]]

    for i in range(1, len(intervals)):
        for j in range(len(rooms)):
            if intervals[i][0] >= rooms[j]:
                rooms[j] = intervals[i][1]
                break
        else:
            rooms.append(intervals[i][1])

    return len(rooms)

