def binary_search(numbers, target):
    """
    Perform binary search on a sorted list of numbers to find the target value.
    Returns the index of the target if found, otherwise returns -1.
    Raises ValueError if the input list is not sorted.
    """
    if not all(numbers[i] <= numbers[i + 1] for i in range(len(numbers) - 1)):
        raise ValueError("Input list is not sorted.")

    left = 0
    right = len(numbers) - 1
    while left <= right:
        mid = (left + right) // 2
        if numbers[mid] == target:
            return mid
        elif numbers[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

