from datetime import datetime

def parse_date(date_str):
    """
    Takes a date string and returns the date in 'mm/dd/yyyy' format.
    If the string is invalid, returns None.
    """
    if '/' in date_str:
        delimiter = '/'
        date_format = '%m/%d/%Y'
    elif '-' in date_str:
        delimiter = '-'
        date_format = '%m-%d-%y'
    else:
        return None

    components = date_str.split(delimiter)

    if len(components) != 3:
        return None

    month, day, year = components

    # If year is two digits, convert it to 4 digits in the 2000s
    if len(year) == 2:
        year = '20' + year

    # Adjust date format for standardized parsing
    date_format = date_format.replace('-y', '-%Y') if len(year) == 4 else date_format

    # Combine everything back into a 'mm/dd/yyyy' format string for parsing
    reformatted_date_str = f"{month}/{day}/{year}"

    try:
        date_obj = datetime.strptime(reformatted_date_str, '%m/%d/%Y')
    except ValueError:
        return None

    return date_obj.strftime('%m/%d/%Y')

def fibonacci(A, B, n):
    """
    Returns the nth number in the Fibonacci sequence starting with A and B.
    """
    if n == 1:
        return A
    elif n == 2:
        return B

    prev, curr = A, B
    for i in range(3, n + 1):
        prev, curr = curr, prev + curr
    return curr

def find_max_value(arr):
    """
    Returns the maximum value in the array.
