def last_appearance(arr):
    """
    Given a sorted array of integers, remove duplicates and return the index
    of the last appearance of each unique number in the array.
    """
    last_seen = {}
    result = []

    for i, num in enumerate(arr):
        last_seen[num] = i

    for key in sorted(last_seen.keys()):
        result.append(last_seen[key])

    return result

