def find_max_substring(s, word_list):
    """
    This function finds the longest substring of `s` that is a substring of any of the strings in `word_list`.

    Parameters:
    s (str): The input string.
    word_list (list): A list of strings.

    Returns:
    str: The longest substring of `s` that is a substring of any of the strings in `word_list`.
    """

    def is_substring(sub, word_list):
        return any(sub in word for word in word_list)

    max_substring = ""
    n = len(s)

    for length in range(n, 0, -1):
        for start in range(n - length + 1):
            substring = s[start:start + length]
            if is_substring(substring, word_list):
                return substring

    return max_substring

def length_of_longest_substring(s: str) -> int:
    """
    Finds the length of the longest substring without repeating characters.
    """
    if not s:
        return 0

    char_index_map = {}
    longest = 0
    start = 0

    for end, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = end
        longest = max(longest, end - start + 1)

    return longest

