def remove_duplicates_by_youngest(records):
    """
    Removes duplicate names from the list, keeping only the record with the youngest age.
    :param records: List of dictionaries containing 'id', 'name', and 'age'.
    :return: List of dictionaries with duplicates removed by choosing the youngest age.
    """
    name_to_min_age_record = {}
    for record in records:
        name = record['name']
        if name not in name_to_min_age_record or record['age'] < name_to_min_age_record[name]['age']:
            name_to_min_age_record[name] = record
    return list(name_to_min_age_record.values())

def count_unique_paths(matrix):
    """
    Returns the number of unique paths from the top-left to the bottom-right of the input matrix.
    The function uses dynamic programming to count the paths.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])
    dp = [[0] * n for _ in range(m)]

    # Initialize the starting point
    dp[0][0] = 1

    # Fill the DP table
    for i in range(m):
        for j in range(n):
            if i > 0:
                dp[i][j] += dp[i-1][j]
            if j > 0:
                dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

