def rock_paper_scissors(player1, player2):
    """
    Determines the winner of a Rock, Paper, Scissors game.

    Args:
    player1: str, one of "rock", "paper", "scissors".
    player2: str, one of "rock", "paper", "scissors".

    Returns:
    str, result of the game - "Player 1 wins", "Player 2 wins", or "It's a tie".
    """
    winning_combinations = {
        'rock': 'scissors',
        'scissors': 'paper',
        'paper': 'rock'
    }

    if player1 == player2:
        return "It's a tie"
    elif winning_combinations[player1] == player2:
        return "Player 1 wins"
    else:
        return "Player 2 wins"

def ternary_search(lst, target):
    """
    Perform ternary search on a sorted list to find the target value.

    Parameters:
        lst (list): A sorted list of elements.
        target : The element to search for in the list.

    Returns:
        int: The index of the target if found, otherwise -1.
    """
    def search(left, right):
        if left > right:
            return -1

        third1 = left + (right - left) // 3
        third2 = right - (right - left) // 3

        if lst[third1] == target:
            return third1
        if lst[third2] == target:
            return third2

        if target < lst[third1]:
            return search(left, third1 - 1)
        elif target > lst[third2]:
            return search(third2 + 1, right)
        else:
            return search(third1 + 1, third2 - 1)

    return search(0, len(lst) - 1)

def pair_sum(nums, target):
    """
    Returns all pairs of distinct elements in the list that add up to the target sum.

    :param nums: List of integers.
    :param target: Target sum.
    :return: List of tuples containing pairs of distinct elements that add up to the target sum.
    """
    seen = {}
    pairs = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            pairs.add((min(num, complement), max(num, complement)))
        seen[num] = True

    return list(pairs)

