def count_primes(n):
    """
    Returns the count of prime numbers less than n.

    Parameters:
    n (int): The upper limit (non-inclusive) to count prime numbers.

    Returns:
    int: The number of prime numbers less than n.
    """
    if n < 2:
        return 0
    prime = [True] * n
    prime[0] = prime[1] = False
    p = 2
    while p * p < n:
        if prime[p]:
            for i in range(p * p, n, p):
                prime[i] = False
        p += 1
    return sum(prime)

