def func(arr):
    """
    Returns the number of duplicate values in the array.
    Time Complexity: O(n^2)
    """
    count = 0
    for i in range(0, len(arr)):
        for j in range(i+1, len(arr)):
            if arr[i] == arr[j]:
                count += 1
    return count

