def count_digits(s):
    """
    Returns a dictionary with the count of each digit from 0 to 9 in the input string.

    Parameters:
    s (str): The input string which may contain non-digit characters.

    Returns:
    dict: A dictionary with keys as digits (0-9) and values as their counts in the string.
    """
    counts = {str(digit): 0 for digit in range(10)}
    for char in s:
        if char.isdigit():
            counts[char] += 1
    return counts

