def evalRPN(tokens):
    stack = []
    for token in tokens:
        if token in {'+', '-', '*', '/'}:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # token == '/'
                stack.append(int(a / b))  # Use int() to truncate towards zero
        else:
            stack.append(int(token))
    return stack[-1]  # The result is the last element in the stack

