def check_winner(board):
    """
    Determines the winner of the Tic-Tac-Toe game.

    :param board: dict containing 'rows', 'columns', and 'diagonals' as keys
    :return: str 'X' or 'O' if there is a winner, otherwise None
    """
    # Check rows for winner
    for row in board['rows']:
        if row[0] == row[1] == row[2] and row[0] in ['X', 'O']:
            return row[0]

    # Check columns for winner
    for column in board['columns']:
        if column[0] == column[1] == column[2] and column[0] in ['X', 'O']:
            return column[0]

    # Check diagonals for winner
    for diagonal in board['diagonals']:
        if diagonal[0] == diagonal[1] == diagonal[2] and diagonal[0] in ['X', 'O']:
            return diagonal[0]

    # No winner
    return None

