import random

def quickselect_median(lst):
    if len(lst) % 2 == 1:
        return quickselect(lst, len(lst) // 2)
    else:
        return 0.5 * (quickselect(lst, len(lst) // 2 - 1) +
                      quickselect(lst, len(lst) // 2))

def quickselect(lst, k):
    if len(lst) == 1:
        return lst[0]

    pivot_index = random.randint(0, len(lst) - 1)

    pivot = lst[pivot_index]

    left = [x for i, x in enumerate(lst) if x < pivot and i != pivot_index]
    middle = [x for x in lst if x == pivot]
    right = [x for i, x in enumerate(lst) if x > pivot and i != pivot_index]

    if k < len(left):
        return quickselect(left, k)
    elif k < len(left) + len(middle):
        return lst[pivot_index]
    else:
        return quickselect(right, k - len(left) - len(middle))

def check_median(lst):
    median = quickselect_median(lst)
    return median < 5

def find_max(numbers):
    """
    Returns the maximum value in the list of numbers.

    Raises:
        ValueError: If the input list is empty.
    """
    if not numbers:
        raise ValueError("The list is empty.")
    max_num = numbers[0]
    for num in numbers:
        if num > max_num:
            max_num = num
    return max_num

