def find_or_create(arr, fn):
    """
    Iterates over the array `arr` and applies the callback function `fn` to each element.
    Returns the first element that satisfies the callback function.
    If no element satisfies the callback function, returns a new object with default values.
    """
    for element in arr:
        if fn(element):
            return element
    return {"default_key": "default_value"}

