from math import gcd

def find_lcm(num1, num2):
    """
    Returns the LCM (Least Common Multiple) of two numbers.
    """
    return num1 * num2 // gcd(num1, num2)

def find_lcm_general(*args):
    """
    Returns the LCM (Least Common Multiple) of multiple numbers.
    """
    if len(args) < 2:
        raise ValueError("At least two numbers must be provided")

    lcm_result = args[0]
    for num in args[1:]:
        lcm_result = find_lcm(lcm_result, num)

    return lcm_result

