def find_first_duplicate(nums):
    """
    This function finds the first duplicate element in the list of numbers.

    :param nums: List of integers
    :return: The first duplicate integer or None if no duplicates are found
    """
    if not nums:
        return None

    seen = {}
    for num in nums:
        if num in seen:
            return num
        seen[num] = True

    return None

