def is_palindrome(n):
    # Convert the number to string to easily access its digits
    num_str = str(n)
    length = len(num_str)

    # Comparing digits from the start and end moving towards the center
    for i in range(length // 2):
        # If at any point the characters don't match, it's not a palindrome
        if num_str[i] != num_str[length - 1 - i]:
            return False
    return True

