def count_divisions_by_two(num, counter=1):
    """
    Recursively divides the number by 2 until it equals 1 and counts the steps.
    :param num: The number to be divided.
    :param counter: The step counter, initialized to 1.
    :return: The number of steps taken to divide the number down to 1.
    """
    if num == 1:
        return counter
    else:
        return count_divisions_by_two(num / 2, counter + 1)

