def parse_message(message):
    """
    Parse the given message and return a dictionary with the relevant information.

    Parameters:
    message (str): The message to be parsed.

    Returns:
    dict: A dictionary with the relevant information extracted from the message.
    """
    if message.startswith("SUCCESS: "):
        return {
            'type': 'success',
            'message': message[len("SUCCESS: "):]
        }
    elif message.startswith("ERROR: "):
        # Split after "ERROR: "
        error_part = message[len("ERROR: "):]
        error_code, error_message = error_part.split(" - ", 1)
        return {
            'type': 'error',
            'error_code': int(error_code),
            'error_message': error_message
        }
    elif message.startswith("INFO: "):
        return {
            'type': 'info',
            'message': message[len("INFO: "):]
        }
    else:
        return {
            'type': 'unknown',
            'message': message
        }

