def bitwise_all(number):
    """
    Checks if all bits of the number are set to 1.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")
    return number != 0 and not (number & (number + 1))

def bitwise_any(number):
    """
    Checks if any bits of the number are set to 1.
    """
    if number < 0:
        raise ValueError("Number must be non-negative")
    return number != 0

