def solution(board, num):
    """
    Finds the position of the given number in a 2D board.

    Args:
    board (list of list of int): The 2D board to search within.
    num (int): The number to find.

    Returns:
    tuple: A tuple containing the row and column indices of the number if found, otherwise None.
    """
    for r, row in enumerate(board):
        if num in row:
            return (r, row.index(num))
    return None

