def find_first_duplicate(arr):
    """
    Finds the first duplicate in the list. If no duplicates are found, returns -1.
    The provided approach modifies the input array to achieve O(1) space complexity.
    """
    for i in range(len(arr)):
        index = abs(arr[i]) - 1
        if arr[index] < 0:
            return abs(arr[i])
        arr[index] *= -1
    return -1

