def intersection_of_lists(list1, list2):
    """
    Finds the intersection of two lists and returns it as a list.
    """
    # Convert each list to a dictionary to remove duplicates and for faster lookup
    dict1 = {item: True for item in list1}
    dict2 = {item: True for item in list2}

    # Find intersection by checking dictionary keys
    intersection = [item for item in dict1 if item in dict2]

    return intersection

