def is_prime(n):
    """
    Returns True if the number n is a prime number, else False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p**2 <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def print_primes_in_range(a, b):
    """
    Prints all prime numbers in the range [a, b] inclusive.
    Also checks if a and b are valid integers and if a <= b.
    """
    if not isinstance(a, int) or not isinstance(b, int):
        return "Error: Both a and b must be integers."
    if a > b:
        return "Error: a should be less than or equal to b."

    primes = []
    for num in range(a, b + 1):
        if is_prime(num):
            primes.append(num)

    return primes

