def longest_palindrome_substring(s):
    """
    Finds the longest palindromic substring in s.

    Parameters:
        s (str): The input string.

    Returns:
        tuple: A tuple containing the length of the longest palindromic substring and the substring itself.
    """
    n = len(s)
    if n == 0:
        return (0, "")

    longest_start = 0
    longest_length = 1

    dp = [[False] * n for _ in range(n)]

    for i in range(n):
        dp[i][i] = True

    for start in range(n-1, -1, -1):  # from n-1 to 0
        for end in range(start + 1, n):
            if s[start] == s[end]:
                if end - start == 1 or dp[start + 1][end - 1]:
                    dp[start][end] = True
                    if (end - start + 1) > longest_length:
                        longest_start = start
                        longest_length = end - start + 1

    longest_palindromic_substr = s[longest_start:longest_start + longest_length]
    return (longest_length, longest_palindromic_substr)

