def separate_even_odd(numbers):
    """
    Takes a list of integers and returns a dictionary with two keys - 'even' and 'odd'.
    'even' maps to a list of even numbers and 'odd' maps to a list of odd numbers from the input list.
    """
    result = {'even': [], 'odd': []}
    for number in numbers:
        if number % 2 == 0:
            result['even'].append(number)
        else:
            result['odd'].append(number)
    return result

