def longest_common_prefix_length(strs):
    """
    Returns the length of the longest common prefix among the strings in strs.
    """
    if not strs:
        return 0

    # Find the shortest string in strs
    shortest_str = min(strs, key=len)

    for i in range(len(shortest_str)):
        # Compare characters at position i in all strings
        for string in strs:
            if string[i] != shortest_str[i]:
                return i  # Return the length of common prefix found

    return len(shortest_str)  # All characters of the shortest string are part of the common prefix

