def is_anagram(str1, str2):
    """
    Returns True if str1 and str2 are anagrams, False otherwise.
    Uses a hash table (dictionary) to count character occurrences.
    """
    if len(str1) != len(str2):
        return False

    char_count = {}

    # Count the characters in str1
    for char in str1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Subtract the count with characters in str2
    for char in str2:
        if char in char_count:
            char_count[char] -= 1
        else:
            return False

    # Check if all counts are zero
    for count in char_count.values():
        if count != 0:
            return False

    return True

