def determine_quadrants(coordinates):
    """
    Determines the quadrant for each coordinate in a list of coordinates.

    Arguments:
    coordinates -- A list of lists, where each inner list represents the (x, y) coordinates of a point.

    Returns:
    A list of dictionaries, where each dictionary contains the quadrant number and the point itself.
    """
    result = []

    for point in coordinates:
        x, y = point
        if x > 0 and y > 0:
            quadrant = 1
        elif x < 0 and y > 0:
            quadrant = 2
        elif x < 0 and y < 0:
            quadrant = 3
        elif x > 0 and y < 0:
            quadrant = 4
        elif x == 0 and y != 0:
            quadrant = 1 if y > 0 else 4
        elif y == 0 and x != 0:
            quadrant = 1 if x > 0 else 2
        else:
            quadrant = None

        result.append({"quadrant": quadrant, "point": point})

    return result

