def maxLength(arr):
    def has_unique_chars(s):
        return len(s) == len(set(s))

    def backtrack(start, current):
        nonlocal max_length
        if has_unique_chars(current):
            max_length = max(max_length, len(current))
        else:
            return

        for i in range(start, len(arr)):
            backtrack(i + 1, current + arr[i])

    max_length = 0
    backtrack(0, "")
