def count_characters(s):
    """
    Counts the occurrences of each character in a string and returns the results as a dictionary.

    Args:
    s (str): The input string.

    Returns:
    dict: A dictionary with characters as keys and their counts as values.
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return char_count

