def count_good_pairs(arr):
    """
    Returns the count of good pairs in the array.
    A pair (i, j) is considered "good" if arr[i] * arr[j] is odd.
    """
    count = 0
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            if (arr[i] * arr[j]) % 2 == 1:
                count += 1
    return count

