def min_operations_to_transform(s1, s2):
    """
    Returns the minimum number of operations required to transform string s1 into string s2.
    The allowed operations are insertions, deletions, and substitutions.
    """
    m = len(s1)
    n = len(s2)

    # Create a DP table to memoize results
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # Minimum operations = j (all insertions)
            elif j == 0:
                dp[i][j] = i  # Minimum operations = i (all deletions)
            elif s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i][j-1],       # Insert
                                   dp[i-1][j],       # Remove
                                   dp[i-1][j-1])     # Replace

    return dp[m][n]

