def city_hemisphere(city):
    """
    Returns the hemisphere of a given city based on its latitude.
    """
    city_latitude_mapping = {
        'Paris': 48.8567,
        'Sydney': -33.8688,
        'New York': 40.7128,
        'Beijing': 39.9042,
        'London': 51.5074,
        'Santiago': -33.4378,
        'Tokyo': 35.6895
    }

    if city not in city_latitude_mapping:
        raise ValueError(f"City '{city}' not found in the database.")

    latitude = city_latitude_mapping[city]
    if latitude > 0:
        return f"{city} is in the Northern Hemisphere"
    else:
        return f"{city} is in the Southern Hemisphere"

