def find_path(matrix):
    def dfs(i, j, path):
        # Base case: if we reach the bottom-right corner, return the path
        if i == len(matrix) - 1 and j == len(matrix[0]) - 1:
            return path + [(i, j)]

        # Mark current cell as visited by setting it to 0
        temp = matrix[i][j]
        matrix[i][j] = 0

        directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
        for direction in directions:
            ni, nj = i + direction[0], j + direction[1]
            if 0 <= ni < len(matrix) and 0 <= nj < len(matrix[0]) and matrix[ni][nj] == 1:
                result = dfs(ni, nj, path + [(i, j)])
                if result:
                    return result

        # Restore the matrix cell (backtrack)
        matrix[i][j] = temp
        return None

    return dfs(0, 0, []) if matrix[0][0] == 1 else None

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters in the given string s.
    """
    char_index_map = {}
    longest = start = 0

    for index, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = index
        longest = max(longest, index - start + 1)

    return longest

