def find_all_palindrome(s):
    result = []
    def expand_around_center(i, j):
        while i >= 0 and j < len(s) and s[i] == s[j]:
            result.append((i, j))
            i -= 1
            j += 1

    for i in range(len(s)):
        # odd length palindrome
        expand_around_center(i, i)
        # even length palindrome
        expand_around_center(i, i + 1)
    return result

