def is_balanced(s):
    """
    Function to determine whether the parentheses in the query string are balanced.
    :param s: String containing only parentheses.
    :return: True if the string is balanced, False otherwise.
    """
    stack = []
    for c in s:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

