def replace_non_divisible_by_3(lst):
    """
    Replaces every integer in the list that is not divisible by 3 with the sum of its digits.

    :param lst: List of integers
    :return: Modified list with the required replacements
    """
    def sum_of_digits(num):
        return sum(int(digit) for digit in str(num))

    return [num if num % 3 == 0 else sum_of_digits(num) for num in lst]

