def sum_last_two_or_all(*args):
    """
    Returns the sum of the last two arguments if they are both integers;
    otherwise, returns the sum of all integer arguments.
    """
    if len(args) >= 2 and isinstance(args[-1], int) and isinstance(args[-2], int):
        return args[-1] + args[-2]
    return sum(arg for arg in args if isinstance(arg, int))

