def is_prime(n):
    """
    Checks if a number n is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def primes_up_to_for_loop(n):
    """
    Returns a list of prime numbers up to n using a for loop.
    """
    primes = []
    for i in range(2, n + 1):
        if is_prime(i):
            primes.append(i)
    return primes

def primes_up_to_recursive(n, current=2, primes=None):
    """
    Returns a list of prime numbers up to n using recursion.
    """
    if primes is None:
        primes = []
    if current > n:
        return primes
    if is_prime(current):
        primes.append(current)
    return primes_up_to_recursive(n, current + 1, primes)

