def moveZeroes(nums):
    """
    Moves all zeros in the list to the end while maintaining order of non-zero elements.

    :param nums: List[int]
    """
    non_zero_index = 0

    for i in range(len(nums)):
        if nums[i] != 0:
            nums[non_zero_index] = nums[i]
            if non_zero_index != i:
                nums[i] = 0
            non_zero_index += 1

