def identify_holes(grid):
    m, n = len(grid), len(grid[0])

    def dfs(row, col, marker):
        if row < 0 or row >= m or col < 0 or col >= n or grid[row][col] != ' ':
            return
        grid[row][col] = marker
        dfs(row-1, col, marker)
        dfs(row+1, col, marker)
        dfs(row, col-1, marker)
        dfs(row, col+1, marker)

    for col in range(n):
        if grid[0][col] == ' ':
            dfs(0, col, 'B')
        if grid[m-1][col] == ' ':
            dfs(m-1, col, 'B')

    for row in range(m):
        if grid[row][0] == ' ':
            dfs(row, 0, 'B')
        if grid[row][n-1] == ' ':
            dfs(row, n-1, 'B')

    for row in range(m):
        for col in range(n):
            if grid[row][col] == ' ':
                dfs(row, col, 'H')

    for row in range(m):
        for col in range(n):
            if grid[row][col] == 'B':
                grid[row][col] = '0'

    return grid

