def find_positions(S):
    """
    Finds all positions in the string S where S[i] is not a letter and S[i+1] is a letter.
    Returns an array with unique positions as the first element of each tuple and the number of times
    the condition is true.
    """
    results = {}

    for i in range(len(S) - 1):
        if not S[i].isalpha() and S[i+1].isalpha():
            if i in results:
                results[i] += 1
            else:
                results[i] = 1

    result_list = [[key, value] for key, value in results.items()]
    return sorted(result_list)

