import random

def generate_unique_uniform_random_numbers(n, start, end):
    """
    Returns a list of n unique uniform random numbers between start and end.
    """
    random_numbers = set()
    while len(random_numbers) < n:
        random_numbers.add(random.uniform(start, end))
    return list(random_numbers)

def generate_unique_gaussian_random_numbers(n, mean, stddev):
    """
    Returns a list of n unique Gaussian random numbers with specified mean and standard deviation.
    """
    random_numbers = set()
    while len(random_numbers) < n:
        random_numbers.add(round(random.gauss(mean, stddev), 8))  # Rounding to ensure uniqueness
    return list(random_numbers)

def generate_unique_lognormal_random_numbers(n, mean, sigma):
    """
    Returns a list of n unique lognormal random numbers with specified mean and sigma.
    """
    random_numbers = set()
    while len(random_numbers) < n:
        random_numbers.add(round(random.lognormvariate(mean, sigma), 8))  # Rounding to ensure uniqueness
    return list(random_numbers)

def get_notification_message(priority, time_of_day):
    """
    Returns the appropriate notification message based on priority and time of day.

    Parameters:
    - priority (str): The priority of the notification, should be one of "Critical", "Low", "Medium".
    - time_of_day (str): The time of day, should be one of "Morning", "Afternoon", "Evening", "Night".

    Returns:
    - str: The notification message.
    """
    if priority == "Critical":
        return "CRITICAL: Notification received."
    elif priority == "Medium":
        if time_of_day in {"Morning", "Afternoon"}:
            return f"Medium Priority: Notification received in the {time_of_day}."
        elif time_of_day == "Evening":
            return f"Medium Priority: Notification received in the {time_of_day}. Please review as soon as possible."
        elif time_of_day == "Night":
            return "Medium Priority: Notification received at night. Please review as soon as possible in the morning."
    elif priority == "Low":
        return "Low Priority: Notification received."

