def pair_with_sum(numbers, target_sum):
    """
    Returns the first pair of elements that add up to a given sum.

    Args:
    numbers: List of integers.
    target_sum: Integer, the target sum.

    Returns:
    A tuple of the first pair of elements that add up to the target sum, or None if no pair is found.
    """
    seen = {}

    for number in numbers:
        complement = target_sum - number
        if complement in seen:
            return (complement, number)
        seen[number] = True

    return None

