from collections import deque

def shortest_path(grid):
    if not grid or grid[0][0] != 1 or grid[-1][-1] != 1:
        return -1

    n = len(grid)
    directions = [(1, 0), (0, 1)]  # down, right
    queue = deque([(0, 0, 1)])  # (x, y, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if x == n - 1 and y == n - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] == 1:
                queue.append((nx, ny, dist + 1))
                visited.add((nx, ny))

    return -1

def calculator(a, b, operation):
    """
    A simple calculator that can handle addition, subtraction, multiplication, and division.

    :param a: first number
    :param b: second number
    :param operation: operation to perform - 'add', 'subtract', 'multiply', 'divide'
    :return: result of the operation
    :raises ValueError: if an unknown operation is provided or division by zero is attempted
    """
    if operation == 'add':
        return a + b
    elif operation == 'subtract':
        return a - b
    elif operation == 'multiply':
        return a * b
    elif operation == 'divide':
        if b == 0:
            raise ValueError("Cannot divide by zero")
        return a / b
    else:
        raise ValueError("Invalid operation")

def intersection(lines):
    def cross_product(a1, b1, a2, b2):
        return a1 * b2 - a2 * b1

    x1, y1, x2, y2 = lines[0]
    x3, y3, x4, y4 = lines[1]

    # Line AB represented as a1x + b1y = c1
    a1 = y2 - y1
    b1 = x1 - x2
    c1 = a1 * x1 + b1 * y1

    # Line CD represented as a2x + b2y = c2
    a2 = y4 - y3
    b2 = x3 - x4
    c2 = a2 * x3 + b2 * y3

    determinant = cross_product(a1, b1, a2, b2)

    if determinant == 0:
        return None  # The lines are parallel or coincident

    x = (cross_product(c1, b1, c2, b2)) / determinant
    y = (cross_product(a1, c1, a2, c2)) / determinant

    def is_between(x, a, b):
        return min(a, b) <= x <= max(a, b)

    # Check if the intersection point lies on both segments
    if is_between(x, x1, x2) and is_between(x, x3, x4) and is_between(y, y1, y2) and is_between(y, y3, y4):
        return (x, y)
    else:
        return None

