def print_numbers(n):
    """
    Prints all numbers from n to 1 in descending order if n is a positive integer.
    Prints an error message if n is not a positive integer or if n is not an integer.
    """
    # Check if n is an integer
    if not isinstance(n, int):
        print("Invalid input: n must be an integer.")
    else:
        # Check if n is less than 1
        if n < 1:
            print("Invalid input: n must be a positive integer.")
        else:
            # Print numbers from n to 1
            for i in range(n, 0, -1):
                print(i)

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring without repeating characters.
    """
    char_index_map = {}
    max_length = 0
    start_index = 0

    for index, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start_index:
            start_index = char_index_map[char] + 1

        char_index_map[char] = index
        max_length = max(max_length, index - start_index + 1)

    return max_length

