def binary_search(data, target):
    """
    Performs binary search on a sorted list `data` to find the index of `target`.
    Returns the index of `target` if found, otherwise returns -1.
    """
    left, right = 0, len(data) - 1
    while left <= right:
        mid = (left + right) // 2
        if data[mid] == target:
            return mid
        elif data[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

