def longest_common_prefix(str1, str2):
    """
    Returns the longest common prefix between two strings.
    """
    min_len = min(len(str1), len(str2))
    common_prefix = []

    for i in range(min_len):
        if str1[i] == str2[i]:
            common_prefix.append(str1[i])
        else:
            break

    return ''.join(common_prefix)

