def findFirstUnmatch(s):
    """
    Finds the first unmatched bracket in the given string.

    Parameters:
    s (str): The input string containing brackets.

    Returns:
    int: The index of the first unmatched bracket or -1 if all brackets are matched.
    """
    stack = []
    pair = {')':'(', '}':'{', ']':'['}
    for i, char in enumerate(s):
        if char in ['(', '{', '[']:
            stack.append((char, i))  # Store the character and its index
        elif char in [')', '}', ']']:
            if not stack:
                return i  # Unmatched closing bracket
            elif pair[char] != stack[-1][0]:
                return i  # Unmatched closing bracket
            else:
                stack.pop()  # Matched, remove from stack
    # If the stack is not empty after going through the entire string,
    # it means that there are unmatched opening brackets
    if stack:
        return stack[0][1]  # Return index of first unmatched opening bracket
    return -1

