from urllib.parse import urlparse

def normalize_url(url):
    parsed_url = urlparse(url)
    # Remove query parameters and fragments
    normalized_url = f"{parsed_url.scheme}://{parsed_url.netloc}{parsed_url.path}"
    # Remove trailing slashes and enforce lowercase for comparison
    normalized_url = normalized_url.rstrip('/').lower()
    return normalized_url

def find_similar_urls(list1, list2, exact=False):
    if exact:
        # Returning only identical URLs
        set1 = set(list1)
        set2 = set(list2)
        return list(set1 & set2)
    else:
        # Returning "similar" URLs
        normalized_map1 = {url: normalize_url(url) for url in list1}
        normalized_map2 = {url: normalize_url(url) for url in list2}

        similar_urls = []
        for url1, norm_url1 in normalized_map1.items():
            for url2, norm_url2 in normalized_map2.items():
                if norm_url1 == norm_url2:
                    similar_urls.append((url1, url2))

        return similar_urls

def generate_powers_of_two():
    """
    Generate a list of powers of 2 up to 100 using recursion.
    """
    def generate(num, max_num):
        if num > max_num:
            return []
        return [num] + generate(num * 2, max_num)

    return generate(1, 100)

