def two_sum(nums, target):
    """
    Returns two elements from the sorted array that add up to the given target sum.
    If no such pair exists, returns an empty list.
    """
    if len(nums) <= 1:
        return []
    left, right = 0, len(nums) - 1
    while left < right:
        current_sum = nums[left] + nums[right]
        if current_sum == target:
            return [nums[left], nums[right]]
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return []

def is_valid_parentheses(s):
    """
    Evaluates the validity of a string of parentheses.

    A string containing only '(', ')', '{', '}', '[' and ']' is valid
    if all types of brackets are closed in the correct order.

    Args:
    s (str): The string containing the parentheses.

    Returns:
    bool: True if the string is valid, False otherwise.
    """
    stack = []
    pairs = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in pairs.values():
            stack.append(char)
        elif char in pairs.keys():
            if stack == [] or pairs[char] != stack.pop():
                return False
        else:
            return False

    return len(stack) == 0

