from typing import List, Optional

def first_duplicate_builtin(arr: List[int]) -> Optional[int]:
    """
    Returns the first duplicate element in the list using built-in functions.
    If no duplicate is found, returns None.
    """
    seen = set()
    for num in arr:
        if num in seen:
            return num
        seen.add(num)
    return None

def first_duplicate_dict(arr: List[int]) -> Optional[int]:
    """
    Returns the first duplicate element in the list using a dictionary to track elements.
    If no duplicate is found, returns None.
    """
    count = {}
    for num in arr:
        if num in count:
            return num
        count[num] = 1
    return None

