def find_position(tup_list, target):
    """
    Finds the position and elements of the first tuple where the first element matches the target.

    Parameters:
    tup_list (list): A list of tuples.
    target : The target to search for in the first element of the tuples.

    Returns:
    tuple or int: A tuple containing the index and elements of the matched tuple or -1 if no match is found.
    """
    for index, tup in enumerate(tup_list):
        if tup[0] == target:
            return (index, *tup)
    return -1

