def find_longest_unique_string(strings):
    """
    Finds the longest string in the list that is not a substring of any other string.

    :param strings: List of strings
    :return: Longest string that is not a substring of any other string
    """
    strings = sorted(strings, key=len, reverse=True)

    for i in range(len(strings)):
        is_unique = True
        for j in range(len(strings)):
            if i != j and strings[i] in strings[j]:
                is_unique = False
                break
        if is_unique:
            return strings[i]
    return None  # If no unique longest string is found

