def calculate_parking_charge(hours):
    """
    Calculates the parking charge based on the firm's rate structure.

    Args:
    hours (float): The number of hours the customer parked.

    Returns:
    float: The total charge for parking.
    """
    if hours < 2:
        return hours * 2
    elif 2 <= hours < 4:
        return hours * 1.50
    elif 4 <= hours < 6:
        return hours * 1
    else:
        return 6

def find_two_smallest(lst):
    """
    Returns the two smallest distinct elements from the list. If the list
    contains fewer than 2 elements, None is returned.
    """
    if len(lst) < 2:
        return None

    min1 = min2 = float('inf')

    for num in lst:
        if num <= min1:
            min1, min2 = num, min1
        elif num < min2:
            min2 = num

    return min1, min2

