def longest_increasing_subsequence(sequence):
    if not sequence:
        return [], 0

    dp = [1] * len(sequence)
    prev = [None] * len(sequence)
    max_length_idx = 0

    for i in range(1, len(sequence)):
        for j in range(i):
            if sequence[i] > sequence[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1
                prev[i] = j
        if dp[i] > dp[max_length_idx]:
            max_length_idx = i

    lis = []
    while max_length_idx is not None:
        lis.append(sequence[max_length_idx])
        max_length_idx = prev[max_length_idx]

    return lis[::-1], max(dp)

def is_valid(s: str) -> bool:
    dictionary = {')': '(', '}': '{', ']': '['}

    def recursive_check(s, stack):
        if not s:
            return not stack
        char = s[0]
        if char in dictionary.values():
            stack.append(char)
            return recursive_check(s[1:], stack)
        elif char in dictionary:
            if not stack or stack.pop() != dictionary[char]:
                return False
            return recursive_check(s[1:], stack)
        else:
            return False

    return recursive_check(s, [])

