def check_score(score):
    """
    Checks if the score is within the valid range of 1 to 100.
    """
    if score < 1 or score > 100:
        return False
    return True

def determine_grade(score):
    """
    Determines the letter grade based on the given score.
    """
    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

def get_grade(score):
    """
    Returns the letter grade for a given score after validation.
    """
    if check_score(score):
        return determine_grade(score)
    else:
        return "Error: Score must be between 1 and 100."

