def count_parens(open_count, close_count):
    memo = {}  # Dictionary to memoize previously computed results

    def count_parens_helper(open_count, close_count):
        if open_count == 0 and close_count == 0:
            return 1
        if open_count < 0 or close_count < 0 or open_count > close_count:
            return 0
        if (open_count, close_count) in memo:
            return memo[(open_count, close_count)]

        result = count_parens_helper(open_count - 1, close_count) + count_parens_helper(open_count, close_count - 1)
        memo[(open_count, close_count)] = result
        return result

    return count_parens_helper(open_count, close_count)

