def is_subsequence(s1, s2):
    """
    Determines if s1 is a subsequence of s2.

    :param s1: str, the smaller string to check as subsequence
    :param s2: str, the larger string in which to check for subsequence
    :return: bool, True if s1 is a subsequence of s2, else False
    """
    i = j = 0
    while i < len(s1) and j < len(s2):
        if s1[i] == s2[j]:
            i += 1
        j += 1
    return i == len(s1)

