def binary_search(arr, x, left=0):
    """
    Finds the index of `x` in the sorted array `arr` using binary search.
    If `x` is not found, returns -1.
    """
    if not arr:
        return -1

    mid = len(arr) // 2
    mid_val = arr[mid]

    if mid_val == x:
        return left + mid
    elif mid_val < x:
        return binary_search(arr[mid + 1:], x, left + mid + 1)
    else:
        return binary_search(arr[:mid], x, left)

