import math

def binary_search(arr, target):
    """
    Perform a binary search on a sorted array to find the target.
    Returns the index of the target if found, otherwise returns -1.
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = math.floor((left + right) / 2)  # calculate the middle index
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

from functools import cmp_to_key

def compare(x, y):
    if x + y > y + x:
        return -1
    elif x + y < y + x:
        return 1
    else:
        return 0

def create_largest_number(nums):
    """
    Given a list of non-negative integers nums, arrange them such that they form the largest number.
    """
    nums = list(map(str, nums))
    nums.sort(key=cmp_to_key(compare))
    largest_number = ''.join(nums)
    return '0' if largest_number[0] == '0' else largest_number

