import json

def extract_mobile_number(data, email):
    """
    Extracts the mobile phone number from a given contact based on the email address.

    Parameters:
        data (list): A list of contact dictionaries.
        email (str): The email address to find the contact by.

    Returns:
        str or None: The mobile phone number of the contact or None if not found.
    """
    for contact in data:
        if contact['email'] == email:
            for phone in contact['phones']:
                if phone['type'] == 'mobile':
                    return phone['number']
    return None

