def levenshtein_distance(str1, str2):
    """
    Computes the Levenshtein distance between two strings.
    """
    if len(str1) < len(str2):
        return levenshtein_distance(str2, str1)

    if len(str2) == 0:
        return len(str1)

    previous_row = range(len(str2) + 1)
    for i, c1 in enumerate(str1):
        current_row = [i + 1]
        for j, c2 in enumerate(str2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def find_one_edit_away(words, target):
    """
    Finds all words in the list that are one edit away from the target word.
    """
    result = []
    for word in words:
        if levenshtein_distance(word, target) == 1:
            result.append(word)
    return result

import datetime

def generate_date_ranges(start_date, end_date):
    date_ranges = []
    start = datetime.datetime.strptime(start_date, '%Y-%m-%d')
    end = datetime.datetime.strptime(end_date, '%Y-%m-%d')
    while start <= end:
        week_end = start + datetime.timedelta(days=6)
        if week_end > end:
            week_end = end
        data_range = {
            'start': start.strftime('%Y-%m-%d'),
            'end': week_end.strftime('%Y-%m-%d')
        }
        date_ranges.append(data_range)
        start += datetime.timedelta(days=7)
    return date_ranges

