def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.
    A prime number is a number greater than 1 that has no divisors other than 1 and itself.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    max_divisor = int(n ** 0.5) + 1
    for i in range(3, max_divisor, 2):
        if n % i == 0:
            return False
    return True

