def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers up to a given number n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return []

    prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (prime[p] == True):
            for i in range(p * p, n + 1, p):
                prime[i] = False
        p += 1

    return [p for p in range(2, n + 1) if prime[p]]

