def predict_weather(current_temperature, forecasted_rainfall):
    """
    Predicts the weather for the next day based on the current temperature and forecasted rainfall.

    Args:
    current_temperature (float): The current temperature in degrees Celsius.
    forecasted_rainfall (float): The forecasted amount of rainfall in millimeters.

    Returns:
    str: The predicted weather for the next day.
    """

    # Validate the input to ensure that it's a number
    if not isinstance(current_temperature, (int, float)) or not isinstance(forecasted_rainfall, (int, float)):
        raise ValueError("Current temperature and forecasted rainfall must be numbers")

    # If there is any forecasted rainfall, the predicted weather is "Rainy"
    if forecasted_rainfall > 0:
        return "Rainy"

    # Predict the weather based on the current temperature
    if current_temperature < 0:
        return "Freezing"
    elif 0 <= current_temperature <= 10:
        return "Cold"
    elif 11 <= current_temperature <= 20:
        return "Mild"
    elif 21 <= current_temperature <= 30:
        return "Warm"
    else:
        return "Hot"

