def search_first(nums, target):
    """
    Returns the index of the first occurrence of the target in the sorted array nums.
    If the target is not found, returns -1.
    """
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    if left < len(nums) and nums[left] == target:
        return left
    else:
        return -1

