import random
import string

def generate_random_string(length: int, case_type: str = 'upper') -> str:
    """
    Generates a random string of the specified length and case type.

    :param length: Length of the random string.
    :param case_type: Case type ('lower' or 'upper'). Default is 'upper'.
    :return: Random string.
    """
    if case_type not in ['lower', 'upper']:
        raise ValueError("case_type must be 'lower' or 'upper'")

    if case_type == 'lower':
        characters = string.ascii_lowercase
    else:
        characters = string.ascii_uppercase

    return ''.join(random.choices(characters, k=length))

