def validIPAddress(IP):
    """
    Determine if the input string is a valid IPv4 or IPv6 address, or neither.

    :param IP: string, which we need to validate as IPv4 or IPv6 address.
    :return: "IPv4" if the input is a valid IPv4 address,
             "IPv6" if the input is a valid IPv6 address,
             "Neither" if the input is neither.
    """
    def isIPv4(IP):
        parts = IP.split(".")
        if len(parts) != 4:
            return False
        for part in parts:
            if not part.isdigit() or not 0 <= int(part) <= 255 or (part[0] == '0' and len(part) > 1):
                return False
        return True

    def isIPv6(IP):
        parts = IP.split(":")
        if len(parts) != 8:
            return False
        for part in parts:
            if not (1 <= len(part) <= 4) or not all(c in "0123456789abcdefABCDEF" for c in part):
                return False
        return True

    if IP.count('.') == 3 and isIPv4(IP):
        return "IPv4"
    if IP.count(':') == 7 and isIPv6(IP):
        return "IPv6"
    return "Neither"

