def strange_function(my_list):
    """
    Processes a list of items, where nested lists are added to a call stack
    and other items are appended to the most recent nested list in the stack.

    Params:
    my_list (list): The input list containing items or nested lists.

    Returns:
    list: The modified call stack or error message if the stack is accessed
          while empty.
    """
    call_stack = []
    for item in my_list:
        if isinstance(item, list):
            call_stack.append(item)
        else:
            try:
                if not call_stack:
                    raise IndexError("Call stack is empty")
                current_list = call_stack[-1]  # Access the most recent list
                current_list.append(item)
            except IndexError:
                return "Error: Call stack is empty"
    return call_stack

