def has_cycle(graph):
    """
    Determine if a directed graph has a cycle.

    :param graph: A dictionary representing an adjacency list of a DAG.
    :return: True if there is a cycle, False otherwise.
    """
    def visit(vertex):
        if vertex in temporary_mark:
            return True
        if vertex in visited:
            return False

        temporary_mark.add(vertex)
        for neighbor in graph.get(vertex, []):
            if visit(neighbor):
                return True

        temporary_mark.remove(vertex)
        visited.add(vertex)

        return False

    visited = set()
    temporary_mark = set()

    for vertex in graph:
        if visit(vertex):
            return True
    return False

