def edit_distance_with_operations(str1, str2):
    m = len(str1)
    n = len(str2)
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]
    operations = [[[] for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
        if i > 0:
            operations[i][0] = operations[i-1][0] + [("delete", str1[i-1])]

    for j in range(n + 1):
        dp[0][j] = j
        if j > 0:
            operations[0][j] = operations[0][j-1] + [("insert", str2[j-1])]

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
                operations[i][j] = operations[i - 1][j - 1]
            else:
                choices = [
                    (dp[i - 1][j], ("delete", str1[i - 1])),
                    (dp[i][j - 1], ("insert", str2[j - 1])),
                    (dp[i - 1][j - 1], ("replace", str1[i - 1], str2[j - 1]))
                ]
                dp[i][j], operation = min(choices, key=lambda x: x[0])
                dp[i][j] += 1
                if operation[0] == "delete":
                    operations[i][j] = operations[i - 1][j] + [operation]
                elif operation[0] == "insert":
                    operations[i][j] = operations[i][j - 1] + [operation]
                else:  # replace
                    operations[i][j] = operations[i - 1][j - 1] + [operation]

    return dp[m][n], operations[m][n]

import random

def play_game(user_choice, computer_choice=None):
    """
    Plays a game of rock, paper, scissors between a user and the computer.
    The function receives the user's choice and optionally the computer's choice and returns the result.
    """
    possible_choices = ['rock', 'paper', 'scissors']

    if user_choice not in possible_choices:
        return "Invalid input. Please enter a valid choice (rock, paper, scissors)."

    if computer_choice is None:
        computer_choice = random.choice(possible_choices)

    result = ""
    if user_choice == computer_choice:
        result = f"Both players selected {user_choice}. It's a tie!"
    elif user_choice == 'rock':
        if computer_choice == 'scissors':
            result = "Rock smashes scissors! You win!"
        else:
            result = "Paper covers rock! You lose."
    elif user_choice == 'paper':
        if computer_choice == 'rock':
            result = "Paper covers rock! You win!"
        else:
            result = "Scissors cuts paper! You lose."
    elif user_choice == 'scissors':
        if computer_choice == 'paper':
            result = "Scissors cuts paper! You win!"
        else:
            result = "Rock smashes scissors! You lose."

    return result

