def grid_traversal_paths(m, n):
    def backtrack(i, j, path, result):
        if i == m - 1 and j == n - 1:
            result.append(''.join(path))
            return

        if j + 1 < n:
            path.append('R')
            backtrack(i, j + 1, path, result)
            path.pop()

        if i + 1 < m:
            path.append('D')
            backtrack(i + 1, j, path, result)
            path.pop()

    result = []
    backtrack(0, 0, [], result)
    return result

