def longest_substring_with_k_distinct(s, k):
    """
    Returns the length of the longest substring that contains no more than k distinct characters.
    """
    if k == 0:
        return 0

    n = len(s)
    if n == 0:
        return 0

    left, right = 0, 0
    max_len = 0
    char_count = {}

    while right < n:
        if s[right] in char_count:
            char_count[s[right]] += 1
        else:
            char_count[s[right]] = 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_len = max(max_len, right - left + 1)
        right += 1

    return max_len

