def relu(x):
    """
    Applies the rectifier linear unit activation function, which returns
    the input if it is positive, and 0 otherwise.

    Parameters:
    x (float or list of floats): Input value or list of input values to the activation function.

    Returns:
    float or list of floats: Output of the ReLU activation function applied to the input.
    """
    if isinstance(x, list):
        return [max(0, xi) for xi in x]
    else:
        return max(0, x)

