def largest_consecutive_parity_with_indices(lst):
    if not lst:
        return 0, []

    max_count = 1
    current_count = 1
    max_indices = []
    current_start_index = 0

    for i in range(1, len(lst)):
        if (lst[i] % 2 == 0 and lst[i-1] % 2 == 0) or (lst[i] % 2 != 0 and lst[i-1] % 2 != 0):
            current_count += 1
        else:
            if current_count > max_count:
                max_count = current_count
                max_indices = [(current_start_index, i-1)]
            elif current_count == max_count:
                max_indices.append((current_start_index, i-1))
            current_count = 1
            current_start_index = i

    if current_count > max_count:
        max_count = current_count
        max_indices = [(current_start_index, len(lst)-1)]
    elif current_count == max_count:
        max_indices.append((current_start_index, len(lst)-1))

    return max_count, max_indices

