def is_valid_expression(expression):
    valid_chars = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ+*/()-"
    for char in expression:
        if char not in valid_chars:
            return False

    opening_count = 0
    closing_count = 0
    for char in expression:
        if char == "(":
            opening_count += 1
        elif char == ")":
            closing_count += 1

    if opening_count != closing_count:
        return False

    return True

def char_type(s):
    """
    This function processes each character in the input string based on its type:
    - If the character is a digit, it converts it to an integer, doubles it, and prints the doubled value.
    - If the character is a letter, it converts it to lowercase and prints it.
    - If the character is neither a digit nor a letter, it prints "Neither a digit nor a letter".
    """
    for char in s:
        if char.isdigit():
            digit = int(char)
            print(digit * 2)
        elif char.isalpha():
            print(char.lower())
        else:
            print("Neither a digit nor a letter")

