def diameterOfBinaryTree(root):
    """
    Returns the length of the longest path in a binary tree.
    """
    def dfs(node):
        if not node:
            return 0, 0  # (depth, best_diameter)
        left_depth, left_diameter = dfs(node.left)
        right_depth, right_diameter = dfs(node.right)
        path_length = left_depth + right_depth
        best_diameter = max(left_diameter, right_diameter, path_length)
        return 1 + max(left_depth, right_depth), best_diameter

    return dfs(root)[1]

def categorize_leave(days):
    """
    Categorizes the type of leave based on the number of days.

    Parameters:
    days (int): The number of days of leave.

    Returns:
    str: The category of leave.
    """
    if days == 1:
        return "Short leave"
    elif 2 <= days <= 5:
        return "Long leave"
    elif days > 5:
        return "Extended leave"
    else:
        return "Invalid number of days"

