def count_equal_pairs(lst):
    result = {}
    if not lst:
        return result

    length = min(len(s) for s in lst)
    for i in range(length):
        column_chars = [s[i] for s in lst]
        if all(c == column_chars[0] for c in column_chars):
            char = column_chars[0]
            if char in result:
                result[char] += len(lst)
            else:
                result[char] = len(lst)

    return result

