def intersect(nums1, nums2):
    """
    Returns a list of common elements between nums1 and nums2.
    """
    count_nums1 = {}
    result = []

    # Count the frequency of elements in nums1
    for num in nums1:
        if num in count_nums1:
            count_nums1[num] += 1
        else:
            count_nums1[num] = 1

    # Find common elements and reduce the count accordingly
    for num in nums2:
        if num in count_nums1 and count_nums1[num] > 0:
            result.append(num)
            count_nums1[num] -= 1
    return result

