def count_gaps(arr):
    """
    Returns the number of gaps (subarrays of zeroes surrounded by ones or array boundaries) in the array.
    """
    gap_count = 0
    in_gap = False

    for num in arr:
        if num == 0:
            if not in_gap:
                in_gap = True
                gap_count += 1
        else:
            in_gap = False

    return gap_count

