def max_clear_course(grid):
    if not grid:
        return 0

    rows = len(grid)
    cols = len(grid[0])

    # Create a 2D array to store the width of continuous zeros ending at (i, j)
    width = [[0] * cols for _ in range(rows)]

    max_area = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0:
                width[i][j] = width[i][j-1] + 1 if j > 0 else 1

                min_width = width[i][j]

                # Check for the largest rectangle ending at (i, j)
                for k in range(i, -1, -1):
                    if grid[k][j] != 0:
                        break
                    min_width = min(min_width, width[k][j])
                    max_area = max(max_area, min_width * (i - k + 1))

    return max_area

