def parse_fits_table(fits_file_content):
    """
    Parses the given FITS file content and returns a list of rows, where each row is a list of parsed numbers.

    Args:
    - fits_file_content: str, content of the FITS file.

    Returns:
    - list of rows where each row is a list of parsed numbers.
    """
    import re

    def parse_value(value):
        # Check for scientific notation
        if 'E' in value or 'e' in value:
            return float(value)
        # Check for comma-separated flush left decimal
        elif ',' in value:
            return float(value.replace(',', ''))
        # Otherwise, it's a simple float or integer
        else:
            try:
                return int(value)
            except ValueError:
                return float(value)

    lines = fits_file_content.strip().split("\n")
    parsed_rows = []
    for line in lines:
        parsed_row = []
        values = line.split()
        for value in values:
            parsed_row.append(parse_value(value))
        parsed_rows.append(parsed_row)

    return parsed_rows

