from itertools import permutations

def generate_combinations(lst):
    """
    Generates all possible combinations (permutations) of a list using recursion.
    """
    if len(lst) == 0:
        return []
    elif len(lst) == 1:
        return [lst]
    else:
        result = []
        for i in range(len(lst)):
            rest = lst[:i] + lst[i+1:]
            for p in generate_combinations(rest):
                result.append([lst[i]] + p)
        return result

