def find_primes(N):
    """
    Finds all prime numbers up to and including N using the Sieve of Eratosthenes algorithm.

    :param N: int - the upper limit to find primes up to (inclusive).
    :return: list - a list of prime numbers up to and including N.
    """
    if N < 2:
        return []

    sieve = [True] * (N + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not prime numbers

    for start in range(2, int(N**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, N + 1, start):
                sieve[multiple] = False

    return [num for num in range(2, N + 1) if sieve[num]]

