def is_hamiltonian_cycle(matrix):
    if len(matrix) == 0:
        return False
    num_vertices = len(matrix)
    # Start from vertex 0 and try to find a Hamiltonian cycle
    path = [0]
    visited = [False] * num_vertices

    def is_hamiltonian_cycle_helper(path, visited):
        current_vertex = path[-1]
        # If all vertices are visited and there's an edge back to the start vertex
        if len(path) == num_vertices:
            return matrix[current_vertex][path[0]] == 1

        for neighbor in get_neighbors(matrix, current_vertex):
            if not visited[neighbor]:
                visited[neighbor] = True
                path.append(neighbor)
                if is_hamiltonian_cycle_helper(path, visited):
                    return True
                visited[neighbor] = False
                path.pop()
        return False

    visited[0] = True
    return is_hamiltonian_cycle_helper(path, visited)

def get_neighbors(matrix, vertex):
    neighbors = []
    for i in range(len(matrix)):
        if matrix[vertex][i] == 1:
            neighbors.append(i)
    return neighbors

