def searchRange(nums, target):
    """
    Find the first and last occurrence of the target in a sorted array using binary search.
    Returns a list of two integers.
    """
    def findFirst(nums, target):
        left, right = 0, len(nums) - 1
        first = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                first = mid
                right = mid - 1  # Keep searching to the left
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return first

    def findLast(nums, target):
        left, right = 0, len(nums) - 1
        last = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                last = mid
                left = mid + 1  # Keep searching to the right
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return last

    first_occurrence = findFirst(nums, target)
    if first_occurrence == -1:
        return [-1, -1]
    last_occurrence = findLast(nums, target)
    return [first_occurrence, last_occurrence]

