def findFirstPair(nums, target):
    """
    Finds the first pair of elements in the sorted list that add up to the target sum.

    Args:
    nums (list): A sorted list of integers.
    target (int): The target sum.

    Returns:
    tuple: A tuple containing the first pair of elements that add up to the target sum, or None if no such pair exists.
    """
    left, right = 0, len(nums) - 1
    while left < right:
        current_sum = nums[left] + nums[right]
        if current_sum == target:
            return (nums[left], nums[right])
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return None

