def switch_case_math(operation, a, b):
    """
    Perform basic math operations based on the given operation.

    Parameters:
    operation (str): The operation to perform ('add', 'subtract', 'multiply', 'divide').
    a (float): The first number.
    b (float): The second number.

    Returns:
    float: The result of the operation.
    """

    def add(x, y):
        return x + y

    def subtract(x, y):
        return x - y

    def multiply(x, y):
        return x * y

    def divide(x, y):
        if y == 0:
            raise ValueError("Cannot divide by zero.")
        return x / y

    switch = {
        'add': add,
        'subtract': subtract,
        'multiply': multiply,
        'divide': divide
    }

    if operation not in switch:
        raise ValueError("Invalid operation.")

    func = switch[operation]
    return func(a, b)

