def start_new_game():
    """
    Starts a new game.
    """
    print("Starting a new game...")
    return "new_game_started"

def load_game(save_files, save_file_name):
    """
    Loads a game from the list of save files if the save_file_name exists.

    Parameters:
    save_files (list): List of available save files.
    save_file_name (str): The name of the save file to load.

    Returns:
    str: A message indicating the result of the load operation.
    """
    if save_file_name in save_files:
        print(f"Loading game from save file: {save_file_name}")
        return "game_loaded"
    else:
        print(f"Save file {save_file_name} not found.")
        return "save_file_not_found"

def user_choice(operation, save_files=None, save_file_name=None):
    """
    Allows the user to start a new game or load a previous game.

    Parameters:
    operation (str): The operation to execute ('new' or 'load').
    save_files (list, optional): List of available save files if operation is 'load'.
    save_file_name (str, optional): The name of the save file to load if operation is 'load'.

    Returns:
    str: Result of the chosen operation.
    """
    if operation == 'new':
        return start_new_game()
    elif operation == 'load':
        if save_files is not None and save_file_name is not None:
            return load_game(save_files, save_file_name)
        else:
            raise ValueError("For the 'load' operation, save_files and save_file_name must be provided.")
    else:
        raise ValueError("Invalid operation. Please choose 'new' or 'load'.")

