def find_next_color(seq):
    def find_pattern_length(seq):
        n = len(seq)
        for l in range(2, n // 2 + 1):  # start with smallest pattern length of 2
            if all(seq[i] == seq[i + l] for i in range(n - l)):
                return l
        return n

    pattern_length = find_pattern_length(seq)
    next_index = len(seq) % pattern_length
    return seq[next_index]

