def generate_rules(tree, current_rule=None):
    if current_rule is None:
        current_rule = []

    # Check if we have reached a leaf node
    if tree['left'] is None and tree['right'] is None:
        return [current_rule + [(tree['feature'], 'leaf')]]

    rules = []

    # Recursive DFS traversal and rule creation
    if tree['left'] is not None:
        left_rule = current_rule + [(tree['feature'], 'left')]
        rules.extend(generate_rules(tree['left'], left_rule))

    if tree['right'] is not None:
        right_rule = current_rule + [(tree['feature'], 'right')]
        rules.extend(generate_rules(tree['right'], right_rule))

    return rules

