import random

def get_winner(player1_choice, player2_choice):
    """
    Determine the winner of a Rock, Paper, Scissors game.

    :param player1_choice: str - Player 1's choice ("rock", "paper", or "scissors")
    :param player2_choice: str - Player 2's choice ("rock", "paper", or "scissors")
    :return: str - Result message indicating who won or if it's a tie.
    """
    choices = ["rock", "paper", "scissors"]

    if player1_choice not in choices or player2_choice not in choices:
        return "Invalid choice(s)."

    if player1_choice == player2_choice:
        return "It's a tie!"

    win_conditions = {
        "rock": "scissors",
        "scissors": "paper",
        "paper": "rock"
    }

    if win_conditions[player1_choice] == player2_choice:
        return "Player 1 wins!"
    else:
        return "Player 2 wins!"

def computer_choice():
    """
    Generate a random choice for the computer.

    :return: str - Computer's choice ("rock", "paper", or "scissors")
    """
    return random.choice(["rock", "paper", "scissors"])

