def is_potential_palindrome(s):
    """
    Returns True if the input string can become a palindrome by removing exactly one character.
    """
    def is_palindrome(sub):
        return sub == sub[::-1]

    for i in range(len(s)):
        # Create a new string with the ith character removed
        new_s = s[:i] + s[i+1:]
        if is_palindrome(new_s):
            return True
    return False

def get_keras_callbacks_info(model):
    """
    Given a Keras model, returns a dictionary of all the callbacks where each callback
    is represented as a dictionary containing the class name and fully qualified class name.
    """
    callbacks_info = {}
    for i, callback in enumerate(model.callbacks):
        class_name = callback.__class__.__name__
        fully_qualified_class_name = f'{callback.__module__}.{class_name}'
        callbacks_info[f'callback{i+1}'] = {
            'class_name': class_name,
            'fully_qualified_class_name': fully_qualified_class_name
        }
    return callbacks_info

