def create_dict(keys, values):
    """
    Creates a dictionary from the provided keys and values lists.
    If a key or value is an empty string, it should be skipped.
    """
    if len(keys) != len(values):
        raise ValueError("Length of keys and values lists must be the same.")

    return {key: value for key, value in zip(keys, values) if key and value}

