def longest_substring_without_repeating_characters(s):
    max_len = 0
    max_str = ""
    window_start = 0
    char_dict = {}

    for window_end in range(len(s)):
        right_char = s[window_end]
        if right_char in char_dict:
            window_start = max(window_start, char_dict[right_char] + 1)

        char_dict[right_char] = window_end
        if window_end - window_start + 1 > max_len:
            max_len = window_end - window_start + 1
            max_str = s[window_start:window_end + 1]

    return max_str

