def solve(a, b):
    """
    Returns the greatest common divisor (GCD) of a and b using the Euclidean algorithm.
    """
    if a == 0:
        return b
    elif b == 0:
        return a
    else:
        return solve(a - b, b) if a >= b else solve(a, b - a)

