def reorder_string(s):
    # Dictionary to store the frequency of each character
    char_counts = {}
    for char in s:
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    # Sort the dictionary by frequency (values) and then alphabetically by character (keys)
    sorted_char_counts = sorted(char_counts.items(), key=lambda item: (-item[1], item[0]))

    # Construct the result string based on the sorted characters
    result = ""
    for char, count in sorted_char_counts:
        result += char * count

    return result

