def find_max_in_matrix(matrix):
    """
    Finds the maximum value in the matrix and its indices.

    Parameters:
    matrix (list of lists): 2D list representing the matrix

    Returns:
    tuple: (max_value, (row_index, column_index))
    """
    if not matrix or not matrix[0]:
        return None, (-1, -1)

    max_value = matrix[0][0]
    max_indices = (0, 0)

    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            if matrix[i][j] > max_value:
                max_value = matrix[i][j]
                max_indices = (i, j)

    return max_value, max_indices

