def find_numbers(string):
    """
    This function finds all unique numbers in a given string.
    """
    numbers = set()
    current_num = ""
    for char in string:
        if char.isdigit():
            current_num += char
        elif current_num:
            numbers.add(int(current_num))
            current_num = ""
    if current_num:
        numbers.add(int(current_num))
    return list(numbers)

