def lengthOfLastWord(s: str) -> int:
    """
    Returns the length of the last word in the string s.

    A word is defined as a maximal substring consisting of non-space characters only.
    """
    i = len(s) - 1
    length = 0
    while i >= 0:
        if s[i] != ' ':
            length += 1
            i -= 1
        else:
            if length > 0:
                break
            else:
                i -= 1
    return length

