def has_adjacent_duplicates(nums):
    """
    Returns True if the array contains at least one pair of adjacent
    duplicate integers and False otherwise.
    """
    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1]:
            return True
    return False

