def test_solve_eight_queens_no_attack():
    configs = solve_eight_queens()
    for config in configs:
        for r in range(8):
            for c in range(8):
                if config[r][c] == 'Q':
                    for direction in [(1, 0), (0, 1), (1, 1), (1, -1)]:
                        x, y = r, c
                        while 0 <= x < 8 and 0 <= y < 8:
                            x += direction[0]
                            y += direction[1]
                            if 0 <= x < 8 and 0 <= y < 8:
                                assert config[x][y] != 'Q'

