import re

def parse_contact(file_path):
    contacts = []
    contact = {}
    with open(file_path, 'r') as file:
        for line in file:
            line = line.strip()
            if not line:
                continue  # Ignore empty lines
            if line.startswith("Name: "):
                if contact:
                    contacts.append(contact)
                    contact = {}
                contact["name"] = line.replace("Name: ", "").strip()
            elif line.startswith("Email: "):
                contact["email"] = line.replace("Email: ", "").strip()
            elif line.startswith("Phone: "):
                contact["phone"] = line.replace("Phone: ", "").strip()
            elif line.startswith("Address: "):
                contact["address"] = line.replace("Address: ", "").strip()
    if contact:
        contacts.append(contact)
    return contacts

