import random

def quickSort(arr):
    if len(arr) <= 1:
        return arr
    pivot = random.choice(arr)
    less = [x for x in arr if x < pivot]
    equal = [x for x in arr if x == pivot]
    greater = [x for x in arr if x > pivot]
    return quickSort(less) + equal + quickSort(greater)

def mergeSort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = mergeSort(arr[:mid])
    right = mergeSort(arr[mid:])
    return merge(left, right)

def merge(left, right):
    result = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] < right[j]:
            result.append(left[i])
            i += 1
        else:
            result.append(right[j])
            j += 1
    result.extend(left[i:])
    result.extend(right[j:])
    return result

def count_votes(voters):
    """
    Returns the total number of votes for each choice in the list of voters.

    Parameters:
    voters (list): A list of dictionaries where each dictionary contains 'voter_id' and 'choice'.

    Returns:
    dict: A dictionary with choices as keys and their respective vote counts as values.
    """
    vote_counts = {}

    for voter in voters:
        choice = voter['choice']
        if choice in vote_counts:
            vote_counts[choice] += 1
        else:
            vote_counts[choice] = 1

    return vote_counts

