def flatten_2d_array(arr):
    """
    Flattens a 2D array into a 1D array using recursion.

    :param arr: List[List[Any]] The 2D array to be flattened.
    :return: List[Any] The flattened 1D array.
    """
    flat_list = []

    def flatten(sub_arr):
        for item in sub_arr:
            if isinstance(item, list):
                flatten(item)
            else:
                flat_list.append(item)

    flatten(arr)
    return flat_list

def fruit_list_transformation(my_list):
    """
    Transforms the input list of lists into another list where each sublist contains a unique string
    and the sum of the corresponding numbers.
    """
    fruit_dict = {}
    for fruit, count in my_list:
        if fruit in fruit_dict:
            fruit_dict[fruit] += count
        else:
            fruit_dict[fruit] = count

    output_list = []
    for fruit, count in fruit_dict.items():
        output_list.append([fruit, count])

    return output_list

import json

def factorial(n):
    """Calculates the factorial of a given integer n."""
    if n < 0:
        raise ValueError("Factorial of negative number does not exist")
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

def to_json(n):
    """Converts the factorial result of n to a JSON string."""
    result = factorial(n)
    data = {
        "n": n,
        "result": result
    }
    return json.dumps(data)

def from_json(json_str, new_n):
    """Parses a JSON string and calculates the factorial of a new number."""
    data = json.loads(json_str)
    return factorial(new_n)

