def convert_to_adj_list(vec_of_vecs):
    adj_list = {}
    for edge in vec_of_vecs:
        u, v = edge
        if u not in adj_list:
            adj_list[u] = []
        if v not in adj_list:
            adj_list[v] = []
        adj_list[u].append(v)
        adj_list[v].append(u)
    return adj_list

def dfs(vertex, adj_list, visited):
    visited.add(vertex)
    for neighbor in adj_list[vertex]:
        if neighbor not in visited:
            dfs(neighbor, adj_list, visited)

def is_connected(vec_of_vecs):
    if not vec_of_vecs:
        return False
    adj_list = convert_to_adj_list(vec_of_vecs)
    start_vertex = next(iter(adj_list.keys()))
    visited = set()
    dfs(start_vertex, adj_list, visited)
    return len(visited) == len(adj_list)

