def max_operations(maxlength, cost):
    """
    Generate the longest sequence of operations with a total length of maxlength and each operation costing cost.

    """
    memo = {}

    def helper(remaining_length, current_sequence):
        if remaining_length == 0:
            return current_sequence

        if remaining_length in memo:
            return memo[remaining_length]

        operations_sequence = []

        for i in range(1, remaining_length + 1):
            if remaining_length >= i * cost:
                new_sequence = helper(remaining_length - i * cost, current_sequence + [i * cost])
                if len(new_sequence) > len(operations_sequence):
                    operations_sequence = new_sequence

        memo[remaining_length] = operations_sequence
        return operations_sequence

    return helper(maxlength, [])

