import functools

def decorator_curry_arg(arg1):
    def real_decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(arg1, *args, **kwargs)
        return wrapper
    return real_decorator

@decorator_curry_arg('Jeong')
def introduce(name, country, **other_info):
    result = f"{name} from {country}"
    for key, value in other_info.items():
        result += f", {key}: {value}"
    return result

