def set_operation(set1, set2, operation):
    """
    Perform the specified set operation on two sets.

    Args:
    set1 (set): The first set of elements.
    set2 (set): The second set of elements.
    operation (str): The set operation to perform. Supported operations are 'union',
                     'intersection', 'difference', 'symmetric_difference'.

    Returns:
    set: The result of the specified set operation.

    Raises:
    ValueError: If an unsupported operation is specified.
    """
    if operation == 'union':
        return set1.union(set2)
    elif operation == 'intersection':
        return set1.intersection(set2)
    elif operation == 'difference':
        return set1.difference(set2)
    elif operation == 'symmetric_difference':
        return set1.symmetric_difference(set2)
    else:
        raise ValueError(f"Unsupported operation: {operation}")

