def parse_integer(s):
    """
    Parses the given string `s` and returns either an integer or a float.
    If parsing is not possible, raises a ValueError.
    """
    try:
        value = int(s)
    except ValueError:
        try:
            value = float(s)
        except ValueError:
            raise ValueError(f"Cannot parse '{s}' as int or float")
    return value

