def solve_problem(a, b):
    """
    Solves the problem as described by checking if 'x' exists in list `b` and handling accordingly.
    """
    # Check if 'x' exists in list `b`
    if 'x' in b:
        index_x = b.index('x')
        # Check if the index of 'x' exists in list `a`
        if index_x in a:
            return index_x
        else:
            return None
    else:
        # Return the highest value in list `a`
        return max(a)

