def replace_vowels_with_position(s):
    """
    Replaces all vowels in the input string with their corresponding alphabet position.
    """
    vowels = {'a': '1', 'e': '5', 'i': '9', 'o': '15', 'u': '21',
              'A': '1', 'E': '5', 'I': '9', 'O': '15', 'U': '21'}

    def recursive_replace(s, index):
        if index >= len(s):
            return ""
        current_char = s[index]
        replacement = vowels.get(current_char, current_char)
        return replacement + recursive_replace(s, index + 1)

    return recursive_replace(s, 0)

