def wordBreak(s, wordDict):
    """
    A function that returns all possible ways to break a given string into a list of words from the word dictionary.
    """
    result = []
    def backtrack(start, path):
        if start == len(s):
            result.append(" ".join(path))
            return
        for end in range(start + 1, len(s) + 1):
            word = s[start:end]
            if word in wordDict:
                backtrack(end, path + [word])

    backtrack(0, [])
    return result

