import math

def log_e_factorial(n):
    """
    Returns the factorial of n using the natural logarithm.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    elif n == 0:
        return 1
    else:
        fact = 0
        for i in range(1, n + 1):
            fact += math.log(i)
        return math.exp(fact)

