def search(nums, target):
    """
    Searches for an element in a sorted array that may have been rotated.

    Args:
    - nums: A sorted list of integers that may have been rotated.
    - target: The target integer to be found.

    Returns:
    - The index of the target element if found; -1 otherwise.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        # Check if left part is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Right part must be sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

