def compare_list(A, B):
    """
    Returns a list of integers from both lists only if the corresponding indices are the same.
    """
    common_elements_at_same_index = []
    for i in range(len(A)):
        if i < len(B):
            if A[i] == B[i]:
                common_elements_at_same_index.append(A[i])
    return common_elements_at_same_index

