def recursive_binary_search(arr, target, low, high):
    """
    Perform a binary search on a sorted list using recursion.

    :param arr: List of sorted elements.
    :param target: Element to search for.
    :param low: Lower index of the sublist to search.
    :param high: Upper index of the sublist to search.
    :return: Index of the target element if found, otherwise -1.
    """
    if low > high:
        return -1

    mid = (low + high) // 2

    if arr[mid] == target:
        return mid
    elif arr[mid] > target:
        return recursive_binary_search(arr, target, low, mid - 1)
    else:
        return recursive_binary_search(arr, target, mid + 1, high)

