import random

def guessing_game(input_func=input, rand_func=random.randint):
    """
    Conducts the guessing game.
    Asks the user for a number between 1-10 and compares it with a randomly generated number.
    """
    while True:
        print("Welcome to the Guessing Game!")
        num = rand_func(1, 10)
        user_num = int(input_func("Please enter a number between 1 and 10: "))
        if user_num > num:
            return "You went too high!"
        elif user_num < num:
            return "You went too low!"
        elif user_num == num:
            return "You got it right!"

