def count_islands(matrix):
    """
    Returns the number of islands in the given boolean matrix.
    An island is a group of adjacent 1s connected horizontally or vertically.
    """
    def is_valid(matrix, visited, row, col):
        return (row >= 0 and row < len(matrix) and
                col >= 0 and col < len(matrix[0]) and
                not visited[row][col] and
                matrix[row][col] == 1)

    def dfs(matrix, visited, row, col):
        row_nbr = [-1, 1, 0, 0]
        col_nbr = [0, 0, -1, 1]

        visited[row][col] = True

        for k in range(4):
            if is_valid(matrix, visited, row + row_nbr[k], col + col_nbr[k]):
                dfs(matrix, visited, row + row_nbr[k], col + col_nbr[k])

    def count_islands_in_matrix(matrix):
        visited = [[False for j in range(len(matrix[0]))] for i in range(len(matrix))]
        count = 0
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                if matrix[i][j] == 1 and not visited[i][j]:
                    dfs(matrix, visited, i, j)
                    count += 1
        return count

    return count_islands_in_matrix(matrix)

def pad_string(input_string, target_length):
    """
    Pads the input_string with zeros at the beginning until it reaches target_length.
    Returns an error message for erroneous input.
    """
    if not isinstance(input_string, str):
        return "Error: input_string should be a string"

    if not isinstance(target_length, int):
        return "Error: target_length should be an integer"

    if target_length < len(input_string):
        return "Error: target_length is less than the length of input_string"

    return input_string.zfill(target_length)

def tuples_to_dict(tuples):
    """
    Converts a list of tuples into a dictionary where keys are the first elements of the tuples
    and values are lists of the second elements of the tuples that share the same key.

    :param tuples: List of tuples (key, value)
    :return: Dictionary {key: [values]}
    """
    result = {}
    for k, v in tuples:
        if k not in result:
            result[k] = []
        result[k].append(v)
    return result

