def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def primes_in_list(lst):
    """
    Returns a sorted list of prime numbers present in the input list.
    Negative numbers and zero are excluded as they are not primes.
    Duplicates are retained according to their occurrence in the input list.
    """
    primes = [num for num in lst if is_prime(num)]
    return sorted(primes)

