def int_to_binary(n):
    """
    Converts an integer to its binary representation as a string.
    Handles both positive and negative numbers.
    """
    if n == 0:
        return '0'

    is_negative = n < 0
    if is_negative:
        n = (1 << 32) + n  # Convert to two's complement 32-bit representation for negative numbers

    binary_str = ''
    while n > 0:
        binary_str = str(n % 2) + binary_str
        n = n // 2

    return binary_str if not is_negative else binary_str.zfill(32)

