def find_triplet_with_sum(arr, target):
    """
    Returns True if there exists a triplet in the list whose sum is
    equal to the given number (target). Otherwise, returns False.
    """
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

