def is_prime(n):
    """
    Returns True if the number n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_prime_pairs(pairs):
    """
    Finds all pairs whose sum is even and both numbers are prime.

    :param pairs: List of tuples, where each tuple contains two integers.
    :return: List of tuples with the conditions satisfied.
    """
    result = []
    for (a, b) in pairs:
        if (a + b) % 2 == 0 and is_prime(a) and is_prime(b):
            result.append((a, b))
    return result

