def power(base, exponent):
    """
    Computes the power of a given base raised to a given exponent.
    It handles both positive and negative exponents by using recursion.
    """
    if exponent == 0:
        return 1
    elif exponent > 0:
        return base * power(base, exponent - 1)
    else:
        return 1 / power(base, -exponent)

def third_largest(nums):
    """
    Returns the third largest number in a given list.
    If the list has fewer than three distinct numbers, return None.
    """
    if len(nums) < 3:
        return None

    first = second = third = float('-inf')

    for num in nums:
        if num > first:
            third = second
            second = first
            first = num
        elif num > second and num != first:
            third = second
            second = num
        elif num > third and num != second and num != first:
            third = num

    return third if third != float('-inf') else None

def sieve_of_eratosthenes(n):
    """
    Generates all prime numbers up to n using the Sieve of Eratosthenes algorithm.
    Returns a list of prime numbers and their count.
    """
    if n < 2:
        return [], 0

    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not prime numbers.

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, n + 1, start):
                sieve[multiple] = False

    primes = [num for num, is_prime in enumerate(sieve) if is_prime]
    return primes, len(primes)

