def remove_consecutive_and_record(s):
    """
    Removes consecutive repeating characters, records the characters removed and their counts.
    If a character is removed once, it should not be removed again even if it repeats consecutively.

    :param s: Input string
    :return: Tuple containing the modified string and a dictionary of removed characters and their counts
    """
    if not s:
        return s, {}

    modified_string = [s[0]]
    removed_chars = {}

    i = 1
    while i < len(s):
        if s[i] == modified_string[-1]:
            if s[i] not in removed_chars:
                removed_chars[s[i]] = 1
            else:
                removed_chars[s[i]] += 1
        else:
            modified_string.append(s[i])
        i += 1

    return ''.join(modified_string), removed_chars

