import math

def is_prime(n):
    """Check if a number is a prime."""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(math.sqrt(n)) + 1
    for d in range(3, max_divisor, 2):
        if n % d == 0:
            return False
    return True

def create_prime_sqrt_dict():
    """Create a dictionary of prime numbers and their square roots from 1 to 15."""
    prime_sqrt_dict = {}
    for i in range(1, 16):
        if is_prime(i):
            prime_sqrt_dict[i] = math.sqrt(i)
    return prime_sqrt_dict

def check_prime_sqrt_dict(prime_sqrt_dict):
    """Check the integrity of the prime square roots dictionary."""
    for k, v in prime_sqrt_dict.items():
        if not is_prime(k):
            return False
        if not math.isclose(v, math.sqrt(k), rel_tol=1e-9):
            return False
    return True

def validate_dates(dates, ascending=True):
    """
    Validates that the input dates are in increasing order if ascending is True.
    If ascending is False, validates that the dates are in descending order.

    Args:
    dates: List of dates as strings in 'YYYY-MM-DD' format.
    ascending: Boolean, if True checks for increasing order, if False checks for descending order.

    Returns:
    bool: True if dates are in correct order, otherwise False.
    """
    from datetime import datetime
    try:
        date_objects = [datetime.strptime(date, '%Y-%m-%d') for date in dates]
        if ascending:
            return all(earlier <= later for earlier, later in zip(date_objects, date_objects[1:]))
        else:
            return all(earlier >= later for earlier, later in zip(date_objects, date_objects[1:]))
    except ValueError:
        return False

