import subprocess
import os

def find_firefox_executable():
    try:
        result = subprocess.run(['which', 'firefox'], capture_output=True, text=True)
    except Exception as e:
        return f"An error occurred while trying to execute 'which': {str(e)}"

    if result.returncode != 0:
        return "Firefox is not installed or not found in the system's PATH."

    firefox_path = result.stdout.strip()

    if not os.path.isfile(firefox_path) or not os.access(firefox_path, os.X_OK):
        return f"Located path '{firefox_path}' is not a valid executable."

    return firefox_path

