def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.
    """
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def filter_primes(numbers):
    """
    Takes a list of integers and returns a new list containing only the prime numbers from the original list.
    Also returns the count of prime numbers in the resulting list.
    Validates that all input integers are positive before processing.
    """
    if not all(isinstance(num, int) and num > 0 for num in numbers):
        raise ValueError("All numbers must be positive integers")

    prime_numbers = [num for num in numbers if is_prime(num)]
    return prime_numbers, len(prime_numbers)

