def count_keys(d):
    """
    Returns the count of elements in dictionary d,
    excluding entries where keys are numbers or values are dictionaries.
    """
    def is_number(n):
        try:
            float(n)
            return True
        except ValueError:
            return False

    def is_dict(val):
        return isinstance(val, dict)

    def count_recursively(d):
        count = 0
        for key, value in d.items():
            if not is_number(key) and not is_dict(value):
                count += 1
        return count

    return count_recursively(d)

