def is_rotation(s1, s2):
    """
    Returns True if s2 is a rotation of s1, otherwise returns False.
    """
    if len(s1) != len(s2):
        return False
    return is_substring(s1 + s1, s2)

def is_substring(s1, s2):
    """
    Checks if s2 is a substring of s1.
    """
    return s2 in s1

