def power(base, exp):
    """
    Calculate the power of a number using recursion.
    Handles negative exponents and returns "Not a number" for float('inf') when the power is less than 0.
    """
    if base == float('inf') and exp < 0:
        return "Not a number"

    # Base case for exponent 0
    if exp == 0:
        return 1

    # Base case for exponent 1
    if exp == 1:
        return base

    # Handle negative exponent
    if exp < 0:
        return 1 / power(base, -exp)

    # Recursive call for positive exponent
    return base * power(base, exp - 1)

