def generate_primes(start, end):
    """
    Generates a list of all prime numbers within a given range.

    :param start: The starting integer of the range.
    :param end: The ending integer of the range.
    :return: A list of prime numbers within the specified range.
    """
    if start > end:
        return "Invalid range: start should be less than or equal to end"

    if end < 2:
        return []

    sieve = [True] * (end + 1)
    sieve[0] = sieve[1] = False

    for num in range(2, int(end**0.5) + 1):
        if sieve[num]:
            for multiple in range(num*num, end + 1, num):
                sieve[multiple] = False

    return [num for num in range(max(2, start), end + 1) if sieve[num]]

