def longest_common_subsequence(str1, str2):
    """
    Returns the longest common subsequence between two strings str1 and str2.
    """
    m, n = len(str1), len(str2)
    # Create a 2D array to store lengths of longest common subsequence.
    dp = [[None] * (n + 1) for i in range(m + 1)]

    # Building the dp array bottom up approach.
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Now dp[m][n] contains the length of LCS.
    index = dp[m][n]

    # Create a list to store the LCS.
    lcs = [""] * (index + 1)
    lcs[index] = ""

    i, j = m, n
    while i > 0 and j > 0:
        # If current characters in both strings are the same, then it's part of LCS.
        if str1[i - 1] == str2[j - 1]:
            lcs[index - 1] = str1[i - 1]
            i -= 1
            j -= 1
            index -= 1
        # If not, find the larger value and move accordingly.
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return ''.join(lcs)

