def find_anagrams(setA, setB):
    """
    Finds all strings in setA that are anagrams of any strings in setB.
    """
    def sort_string(s):
        return "".join(sorted(s))

    sorted_setB = {sort_string(word) for word in setB}
    return {word for word in setA if sort_string(word) in sorted_setB}

