def custom_round(number):
    """
    Rounds a float number to two decimal places without using built-in rounding functions.
    """
    factor = 10**2
    if number >= 0:
        result = (int(number * factor + 0.5)) / factor
    else:
        result = (int(number * factor - 0.5)) / factor

    return result

