import json

def extract_values(json_obj, key):
    """
    Extract all values of specified key from a nested JSON object.

    Parameters:
    - json_obj (dict or list): The JSON object or array to search through.
    - key (str): The key to search for and extract values.

    Returns:
    - list: A list of values corresponding to the specified key.
    """
    def extract(obj, key):
        """Recursively search for values of key in JSON tree."""
        values = []
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == key:
                    values.append(v)
                else:
                    values.extend(extract(v, key))
        elif isinstance(obj, list):
            for item in obj:
              values.extend(extract(item, key))
        return values

    return extract(json_obj, key)

