from collections import defaultdict

def most_frequent_integer(lst):
    """
    Returns the most frequent integer in the list.
    If there are multiple integers with the same highest frequency, return the one that appears first in the list.
    """
    if not lst:
        return None

    frequency = defaultdict(int)
    for num in lst:
        frequency[num] += 1

    max_freq = max(frequency.values())
    for num in lst:
        if frequency[num] == max_freq:
            return num

