def fibonacci(n, memo={}):
    """
    Returns the nth Fibonacci number using recursion with memoization.
    """
    if n in memo:
        return memo[n]
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

def factorial(n):
    """
    Returns the factorial of n using recursion.
    """
    if n == 0 or n == 1:
        return 1
    return n * factorial(n-1)

def factorial_of_fibonacci_up_to_n(N):
    """
    Returns a list of factorials of all Fibonacci numbers between 1 and N.
    """
    fibs = []
    i = 1
    while True:
        fib = fibonacci(i)
        if fib > N:
            break
        fibs.append(fib)
        i += 1
    return [factorial(fib) for fib in fibs]

