def combine_strings(s1, s2, s3):
    """
    Combines three strings s1, s2, and s3 in a specific pattern:
    - If s3 appears alphabetically before s2, insert s3 between s1 and s2.
    - Otherwise, concatenate s3 at the end of the resulting string.
    """
    if s3 < s2:
        return s1 + s3 + s2
    else:
        return s1 + s2 + s3

