def reverse_digits(number):
    """
    Returns the digits of the number in reverse order.
    """
    # Ensure the input number is a string to handle its digits.
    number_str = str(number)

    # Reverse the string and convert to integer if needed.
    reversed_str = number_str[::-1]

    # Handle negative numbers by preserving the negative sign at the beginning.
    if number_str[0] == '-':
        # Move the negative sign to the beginning of the reversed string.
        return int('-' + reversed_str[:-1])
    else:
        return int(reversed_str)

