def is_prime(num):
    """
    Helper function to check if a number is prime.
    """
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def is_prime_between_5_and_10(n):
    """
    Checks if an integer is both prime and between 5 and 10 (inclusive).
    Returns:
        True if the number is prime and within the range
        False if the number is within the range but not prime
        Error message for invalid inputs
    """
    if not isinstance(n, int):
        return "Error: Input is not an integer."
    if n < 5 or n > 10:
        return False
    return is_prime(n)

def character_count(s):
    """
    Returns a dictionary containing the counts of each character in the given string.

    Parameters:
    s (str): The input string.

    Returns:
    dict: A dictionary with characters as keys and their counts as values.
    """
    count_dict = {}
    for char in s:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1
    return count_dict

