    elif numOfLegs == 2:
        return "A bipedal creature" + (" with a tail." if hasTail else " without a tail.")
    elif numOfLegs == 4:
        return "A quadrupedal creature" + (" with a tail." if hasTail else " without a tail.")
    else:
        return f"A creature with {numOfLegs} legs" + (" and a tail." if hasTail else " without a tail.")

