def is_ugly_number(num):
    """
    Returns True if the given number is an ugly number, else returns False.
    An ugly number is a number whose only prime factors are 2, 3, or 5.
    """
    if num <= 0:
        return False

    for p in [2, 3, 5]:
        while num % p == 0:
            num //= p

    return num == 1

def factorial(n):
    """
    Computes the factorial of a positive integer.
    Raises a ValueError if n is a negative integer.
    Returns None if n is not an integer.
    """
    if not isinstance(n, int):
        return None
    if n < 0:
        raise ValueError("Factorial is not defined for negative integers")
    if n == 0:
        return 1
    return n * factorial(n - 1)

def levenshtein_distance(s1, s2):
    """
    Calculate the Levenshtein distance between two strings.

    :param s1: first string
    :param s2: second string
    :return: Levenshtein distance
    """
    # If one of the strings is empty
    if len(s1) == 0:
        return len(s2)
    if len(s2) == 0:
        return len(s1)

    # Create a 2D array to store the distances
    m = len(s1) + 1
    n = len(s2) + 1
    dp = [[0] * n for _ in range(m)]

    # Initialize the first row and column
    for i in range(m):
        dp[i][0] = i
    for j in range(n):
        dp[0][j] = j

    # Compute the distances
    for i in range(1, m):
        for j in range(1, n):
            if s1[i-1] == s2[j-1]:
                cost = 0
            else:
                cost = 1

            dp[i][j] = min(dp[i-1][j] + 1,  # Deletion
                           dp[i][j-1] + 1,  # Insertion
                           dp[i-1][j-1] + cost)  # Substitution

    return dp[-1][-1]

