def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in a given string.
    If all characters are repeating or the string is empty, returns None.
    """
    char_count = {}

    # First pass: count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass: find the first non-repeating character
    for char in s:
        if char_count[char] == 1:
            return char

    return None

