def gcd(a, b):
    """
    Helper function to calculate the Greatest Common Divisor (GCD) of two numbers.
    """
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    """
    Helper function to calculate the Least Common Multiple (LCM) of two numbers.
    """
    return abs(a * b) // gcd(a, b)

def lcm_list(numbers):
    """
    Recursive function to calculate the LCM of a list of numbers.
    """
    if not isinstance(numbers, list) or not all(isinstance(x, int) and x > 0 for x in numbers):
        raise ValueError("Input must be a list of positive integers.")

    if len(numbers) == 0:
        return 1
    elif len(numbers) == 1:
        return numbers[0]
    else:
        first = numbers[0]
        rest = lcm_list(numbers[1:])
        return lcm(first, rest)

