from collections import OrderedDict

def string_indexes(arr):
    """
    Returns an ordered dictionary where each key is a string from the array and the value
    is a list of indexes (ordered from greatest to least) where the string appears in the array.
    """
    index_dict = {}

    for idx, val in enumerate(arr):
        if val not in index_dict:
            index_dict[val] = []
        index_dict[val].append(idx)

    for key in index_dict.keys():
        index_dict[key].sort(reverse=True)

    sorted_keys = sorted(index_dict.keys())
    ordered_dict = OrderedDict()

    for key in sorted_keys:
        ordered_dict[key] = index_dict[key]

    return ordered_dict

