def bubble_sort_desc(array):
    """
    Sorts an array of numbers in descending order using bubble sort algorithm.
    The time complexity is O(n^2).
    """
    n = len(array)

    for i in range(n - 1):
        # Traverse through array from 0 to n-i-1
        for j in range(0, n - i - 1):
            # Swap if the element found is smaller than the next element
            if array[j] < array[j + 1]:
                array[j], array[j + 1] = array[j + 1], array[j]
    return array

