def filter_and_sort_dicts(dict_list, key):
    """
    Filters a list of dictionaries to return unique dictionaries based on a specified key
    and sorts them in ascending order of the values corresponding to that key.

    Args:
    - dict_list (list of dict): List containing dictionaries.
    - key (str): The key on which to base uniqueness and sort order.

    Returns:
    - List of dictionaries sorted by the specified key with unique values.
    """
    if not isinstance(dict_list, list) or not all(isinstance(d, dict) for d in dict_list):
        raise TypeError("Input must be a list of dictionaries.")

    unique_dict = {}
    for d in dict_list:
        if key in d and d[key] not in unique_dict:
            unique_dict[d[key]] = d

    return sorted(unique_dict.values(), key=lambda x: x[key])

