def find_common_elements(list1, list2):
    """
    Find common elements between two lists without using set and
    ensures a time complexity of O(n).
    """
    # Empty dictionary to store the counts of elements in list1
    element_counts = {}

    # Iterate through list1 and count elements
    for elem in list1:
        if elem in element_counts:
            element_counts[elem] += 1
        else:
            element_counts[elem] = 1

    # List to store common elements
    common_elements = []

    # Iterate through list2 and check for common elements
    for elem in list2:
        if elem in element_counts and element_counts[elem] > 0:
            common_elements.append(elem)
            element_counts[elem] -= 1

    return common_elements

