def sum_even_numbers(nums):
    """
    Returns the sum of even numbers from the given list.
    Raises ValueError if any element in the list is negative.
    Raises TypeError if any element is not an integer.
    """
    total = 0
    for num in nums:
        if not isinstance(num, int):
            raise TypeError("All elements must be integers")
        if num < 0:
            raise ValueError("All elements must be non-negative")
        if num % 2 == 0:
            total += num
    return total

