def is_prime(n):
    """
    Returns True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def prime_square_or_self(nested_list):
    """
    Generator that yields the square of a number if it is prime, otherwise the number itself,
    for each number in the nested list.
    """
    for sublist in nested_list:
        for num in sublist:
            yield num**2 if is_prime(num) else num

