import random

def generate_random_number():
    """
    Generates a 15-digit number where the first 3 digits are 9,
    the last 2 digits are not 0, and the remaining digits are randomly generated.
    """
    first_three = '999'
    middle_ten = ''.join([str(random.randint(0, 9)) for _ in range(10)])
    last_two = random.randint(1, 9) * 10 + random.randint(1, 9)
    return int(first_three + middle_ten + f'{last_two:02d}')

def is_prime(n):
    """
    Checks if a given number n is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def validate_data(name, age):
    """
    Validates if the 'name' is a valid string and 'age' is a positive integer.
    """
    if not isinstance(name, str) or not name.isalpha():
        raise ValueError("Invalid name: must be a string containing only alphabetical characters.")

    if not isinstance(age, int) or age <= 0:
        raise ValueError("Invalid age: must be a positive integer.")

def convert_input_to_list_of_dicts(input_list):
    """
    Converts the input list of strings into a list of dictionaries with 'name', 'age', and 'id' keys.
    """
    result = []
    for i, item in enumerate(input_list):
        try:
            name, age = item.split(',')
            name = name.strip()
            age = int(age.strip())
            validate_data(name, age)
        except ValueError as e:
            raise ValueError(f"Invalid format or data in input: {item}. Error: {e}")

        result.append({'name': name, 'age': age, 'id': i + 1})
    return result

