def permute(s, step=0, result=None):
    """
    Returns a list of all permutations of the input string s.
    """
    if result is None:
        result = []

    if step == len(s):
        result.append("".join(s))

    for i in range(step, len(s)):
        s_copy = [c for c in s]
        s_copy[step], s_copy[i] = s_copy[i], s_copy[step]
        permute(s_copy, step + 1, result)

    return result

