def copy_special_elements(lst):
    """
    Copies elements of lst into another list if they are multiples of 3
    and are not divisible by any prime number less than or equal to 10.
    """
    primes_up_to_10 = [2, 3, 5, 7]

    def is_valid(x):
        if x % 3 != 0:
            return False
        for prime in primes_up_to_10:
            if prime != 3 and x % prime == 0:
                return False
        return True

    return [x for x in lst if is_valid(x)]

