def max_value_index(arr):
    """
    Returns the index of the item with the maximum value in the array.
    """
    if not arr:
        return None

    max_index = 0
    max_value = arr[0]

    for i in range(1, len(arr)):
        if arr[i] > max_value:
            max_value = arr[i]
            max_index = i

    return max_index

