def is_prime(n):
    """
    Helper function to check if a number is a prime number.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_numbers_info(numbers):
    """
    This function takes a collection of integers and returns a tuple consisting of:
    - A list of prime numbers in ascending order
    - The product of all prime numbers
    - The sum of all prime numbers
    """
    primes = []

    for n in numbers:
        if isinstance(n, int) and is_prime(n):
            primes.append(n)

    primes = sorted(primes)

    product = 1
    for prime in primes:
        product *= prime

    total_sum = sum(primes)

    if primes == []:  # handle edge case of empty prime list
        product = 0

    return (primes, product, total_sum)

