def text_to_binary(text):
    """
    Converts a text string into its equivalent string of binary representation of the ASCII values.
    """
    if not all(32 <= ord(char) <= 126 for char in text):
        raise ValueError("Input text contains non-printable ASCII characters.")
    return ' '.join(format(ord(char), '08b') for char in text)

def binary_to_text(binary):
    """
    Converts a binary representation string back to its original text string.
    """
    try:
        binary_values = binary.split()
        text = ''.join(chr(int(b, 2)) for b in binary_values)
        if not all(32 <= ord(char) <= 126 for char in text):
            raise ValueError("Decoded text contains non-printable ASCII characters.")
        return text
    except ValueError as e:
        raise ValueError("Input binary string is invalid or contains non-printable ASCII characters.") from e

