def is_prime(n):
    """
    Helper function to determine if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_primes_in_range(lower, upper):
    """
    Function to find prime numbers in a given range.
    """
    if not isinstance(lower, int) or not isinstance(upper, int):
        raise ValueError("Both lower and upper bounds must be integers")

    if lower < 0 or upper < 0:
        raise ValueError("Both lower and upper bounds must be non-negative integers")

    if lower > upper:
        raise ValueError("Lower bound must be less than or equal to the upper bound")

    primes = []
    for num in range(lower, upper + 1):
        if is_prime(num):
            primes.append(num)

    return primes

