def is_valid_sudoku(board):
    """
    Returns True if the board is a valid Sudoku solution, False otherwise.
    """
    def is_valid_group(group):
        return sorted(group) == list(range(1, 10))

    def get_subgrid(board, row, col):
        return [board[r][c] for r in range(row, row + 3) for c in range(col, col + 3)]

    for i in range(9):
        row = [board[i][j] for j in range(9)]
        col = [board[j][i] for j in range(9)]

        if not is_valid_group(row) or not is_valid_group(col):
            return False

    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            subgrid = get_subgrid(board, i, j)
            if not is_valid_group(subgrid):
                return False

    return True

