def lucas(n):
    """
    Returns the nth term in the Lucas sequence using recursion.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        return lucas(n - 1) + lucas(n - 2)

def lucas_sequence(n):
    """
    Returns a list of Lucas sequence numbers up to the nth term.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")
    return [lucas(i) for i in range(n+1)]

