def gcd(a, b):
    """
    Returns the Greatest Common Divisor of a and b.
    """
    while b != 0:
        a, b = b, a % b
    return a

def lcm(a, b):
    """
    Returns the Least Common Multiple of a and b using the Euclidean algorithm for GCD.
    """
    return a * b // gcd(a, b)

def find_duplicates(matrix):
    """
    Finds and returns the coordinates of duplicate elements in a 2D list.

    Arguments:
    matrix -- the 2D list (list of lists) to check for duplicates

    Returns:
    List of tuples where each tuple contains the coordinates (row, column) of duplicates
    """
    if not isinstance(matrix, list):
        raise ValueError("Input must be a list")

    seen = {}
    duplicates = []
    for i, row in enumerate(matrix):
        if not isinstance(row, list):
            raise ValueError("Each row in the matrix must be a list")

        for j, value in enumerate(row):
            if not isinstance(value, (int, float)):
                continue  # If the current value is not an integer or float, we skip it

            if value in seen:
                duplicates.append((i, j))
                duplicates.append(seen[value])
            else:
                seen[value] = (i, j)

    return duplicates

def safe_find_duplicates(matrix):
    """
    Safely finds and returns the coordinates of duplicate elements in a 2D list.
    Handles non-list matrices and non-integer/float values within the matrix.

    Arguments:
    matrix -- the 2D list (list of lists) to check for duplicates

    Returns:
    List of tuples where each tuple contains the coordinates (row, column) of duplicates
    """
    try:
        return find_duplicates(matrix)
    except ValueError as e:
        print(f"ValueError: {e}")
        return []

