def intersperse(arr, delimiter, n):
    """
    Injects a specified delimiter into the array at every n-th position.
    Handles negative n for reverse operation.

    :param arr: List of elements to intersperse delimiter into.
    :param delimiter: The element to insert into the array.
    :param n: The position interval to insert the delimiter. Can be negative.
    :return: A new list with the delimiter interspersed.
    """
    if not isinstance(arr, list):
        raise ValueError("The first argument should be a list.")
    if not isinstance(n, int) or n == 0:
        raise ValueError("The interval 'n' should be a non-zero integer.")

    if n < 0:
        interval = -n
        arr.reverse()
    else:
        interval = n

    result = []
    for i in range(1, len(arr) + 1):
        result.append(arr[i - 1])
        if i % interval == 0 and i != len(arr):
            result.append(delimiter)

    if n < 0:
        result.reverse()

    return result

