def unique_char_string(strings):
    """
    Returns the alphanumeric string that has the largest number of unique characters.
    In case of a tie, returns the one that comes first lexicographically.
    """
    if not strings:
        return ""

    def count_unique_chars(s):
        return len(set(s))

    # Sort first to handle lexicographical tie breaker automatically
    strings.sort()
    return max(strings, key=count_unique_chars)

