def factorial(n):
    """
    Returns the factorial of a non-negative integer. Raises ValueError for negative integers
    and TypeError for non-integer values.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer.")
    if n < 0:
        raise ValueError("Factorial is not defined for negative integers.")

    if n == 0 or n == 1:
        return 1

    result = 1
    for i in range(2, n + 1):
        result *= i

    return result

