def is_prime(n):
    """
    Returns True if n is a prime number, else False.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_of_primes(lst):
    """
    Returns the sum of all prime numbers in the list lst.
    Considers only positive integers.
    """
    return sum(num for num in lst if num > 0 and is_prime(num))

