def check_brackets_parentheses(s):
    """
    Checks whether the string `s` contains correctly matched brackets and parentheses.

    Parameters:
    s (str): The input string to check.

    Returns:
    str: "Correct string" if all brackets and parentheses are correctly matched; otherwise,
         a string specifying the type of bracket or parenthesis that was misplaced.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}

    for index, char in enumerate(s):
        if char in bracket_map.values():
            stack.append((char, index))
        elif char in bracket_map.keys():
            if stack == []:
                return f"Misplaced {char} at index {index}"
            top_element = stack.pop()
            if bracket_map[char] != top_element[0]:
                return f"Misplaced {char} at index {index}"

    if stack:
        last_unmatched = stack[-1]
        return f"Misplaced {last_unmatched[0]} at index {last_unmatched[1]}"

    return "Correct string"

