def is_strictly_sorted(lst):
    """
    Verify if a list of numerical values is sorted in strictly rising order.

    Args:
    lst (list): List of numeric values.

    Returns:
    bool: True if the list is strictly sorted, otherwise False.
    """
    if not isinstance(lst, list):
        raise ValueError("Input must be a list.")

    for element in lst:
        if not isinstance(element, (int, float)):
            raise ValueError("All elements in the list must be numeric.")

    for i in range(1, len(lst)):
        if lst[i-1] >= lst[i]:
            return False

    return True

