from math import sqrt

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    elif n <= 3:
        return True
    elif n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_fibonacci(max_value):
    """Generates all Fibonacci numbers up to a maximum value."""
    fibonacci_set = set()
    a, b = 0, 1
    while a <= max_value:
        fibonacci_set.add(a)
        a, b = b, a + b
    return fibonacci_set

def extract_prime_fib_numbers(nums):
    """Extract prime numbers that are also in the Fibonacci sequence."""
    max_value = max(nums)
    fibonacci_set = generate_fibonacci(max_value)
    return [num for num in nums if is_prime(num) and num in fibonacci_set]

def custom_encrypt(user_input, shift_values):
    """
    Encrypts the given string based on the provided shift values.

    Args:
    - user_input (str): The string to be encrypted.
    - shift_values (dict): A dictionary mapping each letter to its shift value.

    Returns:
    - str: The encrypted string with swapped case letters.
    """
    encrypted_str = []
    for char in user_input:
        if char.isalpha():
            is_upper = char.isupper()
            shifted_char = shift_values[char.lower()]
            if is_upper:
                encrypted_str.append(shifted_char.upper())
            else:
                encrypted_str.append(shifted_char.lower())
        else:
            encrypted_str.append(char)

    return ''.join(encrypted_str)

