def lists_to_dict(lists):
    """
    Given a list of lists of equal length, creates a dictionary where the i-th list
    is the value for the key given in the first list at index i.

    Args:
    lists (List[List[any]]): A list containing sub-lists of equal length.

    Returns:
    dict: A dictionary where the keys are the elements of the first list, and the values
          are the corresponding sub-lists.
    """
    if not lists:
        return {}

    keys = lists[0]
    result = {key: [] for key in keys}

    for other_list in lists[1:]:
        for key, value in zip(keys, other_list):
            result[key].append(value)

    return result

