def sum_of_absolute_values(numbers):
    """
    Returns the sum of the absolute values of the numbers in the list.
    """
    total = 0
    for num in numbers:
        if num < 0:
            total += -num
        else:
            total += num
    return total

def sum_of_absolute_values_above_threshold(numbers, threshold):
    """
    Returns the sum of the absolute values of the numbers in the list
    that are greater than the threshold.
    """
    total = 0
    for num in numbers:
        abs_value = -num if num < 0 else num
        if abs_value > threshold:
            total += abs_value
    return total

def word_count(words, case_sensitive=True):
    """
    Returns a dictionary with the count of each word in the list.

    :param words: List of strings, each string being a word.
    :param case_sensitive: Specifies whether the counting should be case-sensitive. Default is True.
    :return: Dictionary with words as keys and their counts as values.
    """
    count_dict = {}

    for word in words:
        if not case_sensitive:
            word = word.lower()

        if word in count_dict:
            count_dict[word] += 1
        else:
            count_dict[word] = 1

    return count_dict

