def count_frequencies(arr):
    """
    This function takes an array of integers and prints the frequencies
    of even and odd numbers, and the frequencies of negative and positive numbers.
    """
    even_count = 0
    odd_count = 0
    positive_count = 0
    negative_count = 0

    for num in arr:
        if num % 2 == 0:
            even_count += 1
        else:
            odd_count += 1

        if num > 0:
            positive_count += 1
        elif num < 0:
            negative_count += 1

    # Returning the counts instead of printing for testing purposes
    return {
        'even_count': even_count,
        'odd_count': odd_count,
        'positive_count': positive_count,
        'negative_count': negative_count
    }

