def int_to_binary(n):
    """
    Converts an integer to its binary representation as a string.
    """
    if n == 0:
        return "0"
    binary_str = ""
    is_negative = n < 0
    n = abs(n)

    while n > 0:
        binary_str = str(n % 2) + binary_str
        n = n // 2

    if is_negative:
        return "-" + binary_str

    return binary_str

def is_valid_binary_string(binary_str):
    """
    Checks if the given string is a valid binary representation, containing only '0's and '1's.
    """
    for char in binary_str:
        if char not in ['0', '1', '-']:
            return False
    return True

def divide(dividend, divisor):
    if divisor == 0:
        raise ValueError("The divisor cannot be zero.")

    if dividend == 0:
        return 0

    # Determine the sign of the result
    negative = (dividend < 0) ^ (divisor < 0)

    # Work with absolute values
    dividend = abs(dividend)
    divisor = abs(divisor)

    quotient = 0
    the_sum = 0

    # 32 because we are using 32-bit integers
    for i in range(31, -1, -1):
        if (the_sum + (divisor << i)) <= dividend:
            the_sum += (divisor << i)
            quotient |= (1 << i)

    if negative:
        return -quotient
    else:
        return quotient

