def second_largest(nums):
    """
    Returns the second largest element in the list.
    If the list has less than two elements, return a specific message.
    """
    if len(nums) < 2:
        return "List should have at least two elements"

    first = second = float('-inf')
    for num in nums:
        if num > first:
            second = first
            first = num
        elif num > second and num != first:
            second = num

    return second if second != float('-inf') else "All elements are the same"

