def reverse_words_with_more_than_three_vowels(s):
    """
    Returns a string with all words that contain more than three vowels reversed.
    Vowels are 'a', 'e', 'i', 'o', 'u' (case-insensitive).

    :param s: input string consisting of words separated by commas and spaces
    :return: transformed string with specific words reversed
    """
    def count_vowels(word):
        vowels = set('aeiouAEIOU')
        return sum(1 for char in word if char in vowels)

    words = s.split(',')
    result = []
    for word in words:
        stripped_word = word.strip()
        if count_vowels(stripped_word) > 3:
            result.append(stripped_word[::-1])
        else:
            result.append(stripped_word)

    return ', '.join(result)

