def find_deeply_nested_key(data, key="deeply_nested_key"):
    """
    Recursively searches for the specified key in the nested dictionary and returns its value.

    Args:
    data (dict): The nested dictionary to search within.
    key (str): The key to search for. Defaults to 'deeply_nested_key'.

    Returns:
    The value corresponding to the specified key if found, otherwise None.
    """
    if isinstance(data, dict):
        if key in data:
            return data[key]
        for k, v in data.items():
            result = find_deeply_nested_key(v, key)
            if result is not None:
                return result
    elif isinstance(data, list):
        for item in data:
            result = find_deeply_nested_key(item, key)
            if result is not None:
                return result
    return None

