def longest_word(s):
    """
    Returns the longest word in the given string s.
    If there are multiple words with the same length, the first one encountered is returned.
    """
    words = s.split()
    if not words:
        return ""

    longest = words[0]
    for word in words[1:]:
        if len(word) > len(longest):
            longest = word

    return longest

