def sort_nested_dict(d):
    """
    Returns a list of keys and values sorted by the values.
    Numeric values are sorted in ascending order,
    while string values are sorted in descending lexicographic order.
    """
    flat_dict = {}

    def flatten_dict(d, parent_key=''):
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                flatten_dict(v, new_key)
            else:
                flat_dict[new_key] = v

    flatten_dict(d)

    int_values = {k: v for k, v in flat_dict.items() if isinstance(v, int)}
    str_values = {k: v for k, v in flat_dict.items() if isinstance(v, str)}

    sorted_int_values = sorted(int_values.items(), key=lambda item: item[1])
    sorted_str_values = sorted(str_values.items(), key=lambda item: item[1], reverse=True)

    return sorted_int_values + sorted_str_values

