def generate_palindromic_primes():
    """
    Generate palindromic prime numbers between 1 and 1000.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    palindromic_primes = []
    for num in range(1, 1001):
        if is_prime(num) and is_palindrome(num):
            palindromic_primes.append(num)

    return palindromic_primes

