def find_second_smallest(arr):
    """
    This function returns the second smallest number in the given list of integers.
    It ignores non-numeric values and treats all numbers as integers.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two numeric elements")

    # Filter out non-integer values
    cleaned_arr = [int(x) for x in arr if str(x).lstrip('-').isdigit()]

    if len(cleaned_arr) < 2:
        raise ValueError("Array must contain at least two numeric elements")

    first_min = second_min = float('inf')

    for num in cleaned_arr:
        if num < first_min:
            second_min = first_min
            first_min = num
        elif first_min < num < second_min:
            second_min = num

    if second_min == float('inf'):
        raise ValueError("Array must contain at least two numeric elements")

    return second_min

