def filter_strings(string_list):
    """
    Returns a new list of all strings from the input list which have a length greater than 4,
    contain at least one vowel, and contain at least one uppercase letter.
    """
    vowels = 'aeiouAEIOU'

    def has_vowel(s):
        return any(char in vowels for char in s)

    def has_uppercase(s):
        return any(char.isupper() for char in s)

    result = []
    for s in string_list:
        if len(s) > 4 and has_vowel(s) and has_uppercase(s):
            result.append(s)

    return result

