def contains_substring(main_string, sub_string):
    """
    Determines if the main_string contains the sub_string as a substring
    without using any built-in search or substring methods.
    """
    if sub_string == "":
        return True
    if main_string == "":
        return False

    main_length = len(main_string)
    sub_length = len(sub_string)

    for i in range(main_length - sub_length + 1):
        match = True
        for j in range(sub_length):
            if main_string[i + j] != sub_string[j]:
                match = False
                break
        if match:
            return True

    return False

