import math

def is_palindrome(num):
    """
    Checks if a number is a palindrome.
    """
    return str(num) == str(num)[::-1]

def is_prime(num):
    """
    Checks if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(num))+1, 2):
        if num % i == 0:
            return False
    return True

def next_palindrome_prime(n):
    """
    Finds the next number that is both a palindrome and a prime number.
    """
    candidate = n + 1
    while True:
        if is_palindrome(candidate) and is_prime(candidate):
            return candidate
        candidate += 1

