import math

def divisor_properties(n):
    """
    Returns a tuple where the first element is a string stating "Odd Number of Divisors" or "Even Number of Divisors"
    and the second element is a boolean value that is True if the integer is a perfect square and False otherwise.
    """
    is_perfect_square = (math.isqrt(n) ** 2 == n)
    num_divisors = 0

    for i in range(1, math.isqrt(n) + 1):
        if n % i == 0:
            if i * i == n:
                # Square root divisor counts as one
                num_divisors += 1
            else:
                # Pair of divisors
                num_divisors += 2

    if num_divisors % 2 == 0:
        divisor_type = "Even Number of Divisors"
    else:
        divisor_type = "Odd Number of Divisors"

    return (divisor_type, is_perfect_square)

