def nonagonal_number(n, memo=None):
    """
    Returns the nth nonagonal number using recursion and memoization.
    """
    if memo is None:
        memo = {}

    if not isinstance(n, int) or n <= 0 or n > 1000:
        raise ValueError("Input should be a positive integer between 1 and 1000.")

    if n in memo:
        return memo[n]

    if n == 1:
        return 1

    result = (7 * n * (n - 1)) // 2 + n
    memo[n] = result

    return result

def nonagonal_sequence_up_to(n):
    """
    Returns a list containing the nonagonal numbers up to the nth number.
    """
    return [nonagonal_number(i) for i in range(1, n+1)]

