def is_substring(A, B):
    """
    Returns True if B is a substring of A considering case sensitivity.
    """
    if B == "":
        return True

    if A == "" or len(B) > len(A):
        return False

    len_A = len(A)
    len_B = len(B)

    for i in range(len_A - len_B + 1):
        if A[i:i + len_B] == B:
            return True

    return False

