def find_max_min(arr):
    """
    Find the maximum and minimum elements in a list using a divide-and-conquer approach.

    Parameters:
    arr (list): List of numbers.

    Returns:
    tuple: A tuple containing the minimum and maximum element from the list.
    """
    if len(arr) == 1:
        return arr[0], arr[0]

    if len(arr) == 2:
        if arr[0] < arr[1]:
            return arr[0], arr[1]
        else:
            return arr[1], arr[0]

    mid = len(arr) // 2
    left_min, left_max = find_max_min(arr[:mid])
    right_min, right_max = find_max_min(arr[mid:])

    return min(left_min, right_min), max(left_max, right_max)

