def is_prime(num):
    """
    Checks if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True

def find_smallest_prime_index(lst):
    """
    Returns the index of the first occurrence of the smallest prime number in the list.
    If there are no prime numbers in the list, returns -1.
    """
    smallest_prime = None
    smallest_prime_index = -1
    for index, num in enumerate(lst):
        if is_prime(num):
            if smallest_prime is None or num < smallest_prime:
                smallest_prime = num
                smallest_prime_index = index
    return smallest_prime_index

