def min_jumps(arr):
    """
    Returns the minimum number of jumps required to reach the last index of the array.
    """
    n = len(arr)

    # If the array has 1 or zero elements, no jumps are needed
    if n <= 1:
        return 0

    # If the first element is 0, we can't move anywhere
    if arr[0] == 0:
        return float('inf')

    jumps = 0
    max_reach = arr[0]
    step = arr[0]

    for i in range(1, n):
        # Check if we have reached the end of the array
        if i == n - 1:
            return jumps + 1

        # Update the maximum reach
        max_reach = max(max_reach, i + arr[i])

        # We use a step to get to the current index
        step -= 1

        # If no steps are remaining
        if step == 0:
            # We need to jump
            jumps += 1

            # Check if the current index/position or lesser index is the furthest we can reach
            if i >= max_reach:
                return float('inf')

            # Re-initialize the steps to the amount of steps to reach maxReach from position i
            step = max_reach - i

    return float('inf')

