import random

def generate_random_list(n):
    """
    Generates a list of n unique random numbers between 0 and 10.
    """
    if n > 11:
        raise ValueError("n must be less than or equal to 11 to avoid duplicates in range 0-10")
    return random.sample(range(11), n)

def binary_search(sorted_list, target):
    """
    Perform binary search on sorted_list to find the target.
    Returns the index of target if found, otherwise returns -1.
    """
    left, right = 0, len(sorted_list) - 1

    while left <= right:
        mid = left + (right - left) // 2
        if sorted_list[mid] == target:
            return mid
        elif sorted_list[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def split_and_reverse_string(s):
    """
    Splits the input string into a list of words, removes punctuation, and returns the list in reverse order.
    """
    import string
    words = []
    word = ''

    for char in s:
        if char in string.whitespace:
            if word:
                words.append(word)
                word = ''
        elif char not in string.punctuation:
            word += char

    if word:
        words.append(word)

    return words[::-1]

