def fibonacci(n, memo={}):
    """
    Returns the nth Fibonacci number using memoization to optimize recursion.
    """
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)
    return memo[n]

def get_fibonacci_numbers(n1, n2):
    """
    Returns the n1-th and n2-th Fibonacci numbers.
    """
    return fibonacci(n1), fibonacci(n2)

def longest_increasing_subsequence(nums):
    """
    Returns the length of the longest strictly increasing subsequence in the list of positive integers.
    """
    if not nums:
        return 0

    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(0, i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

