def find_min_max_divisible(nums, n):
    """
    Finds the minimum and maximum numbers in the list which are divisible by n.

    Parameters:
    nums (list): List of numbers.
    n (int): The number to divide by.

    Returns:
    tuple: A tuple containing the minimum and maximum numbers divisible by n.
    """
    min_num = None
    max_num = None

    for num in nums:
        if num % n == 0:
            if min_num is None or num < min_num:
                min_num = num
            if max_num is None or num > max_num:
                max_num = num

    return (min_num, max_num)

