def calculate_factorial(n):
    """
    Returns the factorial of n if n is a non-negative integer and the factorial does not exceed 1,000,000.
    If n is not an integer or the factorial exceeds 1,000,000, returns None.
    """
    if not isinstance(n, int) or n < 0:
        return None

    factorial = 1
    for i in range(1, n + 1):
        factorial *= i
        if factorial > 1000000:
            return None

    return factorial

