def is_prime(num):
    """
    Checks if a number is prime.
    """
    if num <= 1:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def even_numbers_and_avg(start, end):
    """
    Finds even numbers in the range [start, end], calculates their average, and identifies prime numbers among them.
    Returns a tuple (even_numbers, average, prime_numbers).
    """
    even_numbers = [num for num in range(start, end + 1) if num % 2 == 0]
    if even_numbers:
        average = sum(even_numbers) / len(even_numbers)
    else:
        average = 0
    prime_numbers = [num for num in even_numbers if is_prime(num)]

    return even_numbers, average, prime_numbers

