import bisect

def LongestIncreasingSubsequence(arr):
    """
    Returns the length of the longest increasing subsequence in arr.
    """
    if not arr:
        return 0

    temp = []
    for num in arr:
        pos = bisect.bisect_left(temp, num)
        if pos < len(temp):
            temp[pos] = num
        else:
            temp.append(num)

    return len(temp)

