def add_n(lst, n):
    """
    Recursively adds n to each element in lst.
    If lst contains nested lists, the function applies the addition recursively.
    """
    result = []
    for item in lst:
        if isinstance(item, list):
            result.append(add_n(item, n))
        else:
            result.append(item + n)
    return result

