def detect_all_lowercase_letters(s):
    """
    Detect if a given string contains all lowercase English alphabet letters
    and return the count of unique lowercase letters present in the string.
    """
    unique_letters = set()
    for char in s:
        if 'a' <= char <= 'z':
            unique_letters.add(char)
    return len(unique_letters)

