# solution.py
def factorial(n):
    """
    Returns the factorial of a non-negative integer n.
    The factorial of n is the product of all positive integers less than or equal to n.
    For n = 0, factorial is 1 by definition.

    :param n: int, non-negative integer whose factorial is to be computed
    :return: int, factorial of n
    :raises: ValueError if n is a negative integer
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative integers")
    elif n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def are_anagrams(word1, word2):
    """
    Check if two words are anagrams of each other.
    """
    return sorted(word1) == sorted(word2)

def find_anagram_pair(words):
    """
    Determine if there exists a pair of distinct indices (i, j) in the array
    such that the words at those indices are anagrams of each other.
    Returns True if such a pair exists, otherwise False.
    """
    for i in range(len(words)):
        for j in range(i + 1, len(words)):
            if are_anagrams(words[i], words[j]):
                return True
    return False

