def reverse_end_characters(s, n):
    """
    Returns the last n characters from string s in reverse order.
    If n is larger than the length of the string, return the entire string in reverse order.
    """
    if n > len(s):
        return s[::-1]
    else:
        return s[:-n-1:-1]

