from collections import deque

def min_moves_to_20():
    """
    Return the minimum number of moves required for the robot to move from position 0 to 20.
    The robot can jump at positions 5 and 15.
    """
    target = 20
    jumps = {5, 15}
    queue = deque([(0, 0)])  # (current_position, current_moves)
    visited = set()

    while queue:
        pos, moves = queue.popleft()
        if pos == target:
            return moves
        visited.add(pos)

        # Move left and right
        for next_pos in (pos + 1, pos - 1):
            if 0 <= next_pos <= target and next_pos not in visited:
                queue.append((next_pos, moves + 1))

        # Jump if on a jump point
        if pos in jumps:
            next_pos = pos + 1
            if next_pos <= target and next_pos not in visited:
                queue.append((next_pos, moves + 1))

    return -1  # Should never reach here if target position is reachable

