def is_prime(num):
    """
    Returns True if the number is prime, otherwise False.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def twin_primes(N):
    """
    Generates a list of twin primes (pairs of prime numbers that differ by two) between 1 and N.
    Returns the list of twin primes, the total number of twin prime pairs, and the largest twin prime pair.
    """
    twin_prime_list = []
    for num in range(2, N-1):
        if is_prime(num) and is_prime(num + 2):
            twin_prime_list.append((num, num + 2))

    total_twin_primes = len(twin_prime_list)
    largest_twin_prime = twin_prime_list[-1] if twin_prime_list else None

    return twin_prime_list, total_twin_primes, largest_twin_prime

