def create_zero_matrix(n, m):
    """
    Create an n x m matrix initialized with zeros using a recursive algorithm.
    """
    if n == 0:
        return []
    else:
        return [create_zero_matrix_row(m)] + create_zero_matrix(n - 1, m)

def create_zero_matrix_row(m):
    """
    Create a row with m zeros.
    """
    if m == 0:
        return []
    else:
        return [0] + create_zero_matrix_row(m - 1)

# Function to create a 3x3 matrix of zeros
def create_3x3_zero_matrix():
    return create_zero_matrix(3, 3)

