import math

def is_prime(n):
    """
    Returns True if n is a prime number, else False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def extract_primes(matrix):
    """
    Given a 2D array (matrix), return all prime numbers in the matrix.
    Only consider arrays (sub-arrays) that contain only integers.
    """
    primes = []
    for sublist in matrix:
        if all(isinstance(x, int) for x in sublist):
            primes.extend([x for x in sublist if is_prime(x)])
    return primes

def replace_vowels_with_next(s):
    """
    Replaces each vowel in the input string with the next vowel in sequence.

    Parameters:
    s (str): The input string

    Returns:
    str: The string with each vowel replaced by the next vowel in sequence
    """
    next_vowel = {'a': 'e', 'e': 'i', 'i': 'o', 'o': 'u', 'u': 'a', 'A': 'E', 'E': 'I', 'I': 'O', 'O': 'U', 'U': 'A'}
    result = []

    for char in s:
        if char in next_vowel:
            result.append(next_vowel[char])
        else:
            result.append(char)

    return ''.join(result)

