import time

def is_prime(num):
    """
    Check if the number is a prime.
    """
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def product_of_primes(n):
    """
    Returns the product of all prime numbers less than or equal to n.
    If n is less than 2 or not an integer, raises ValueError.
    Also returns the time taken to calculate the product.
    """
    if not isinstance(n, int):
        raise ValueError("Input must be an integer")
    if n < 2:
        raise ValueError("There are no prime numbers less than 2")

    start_time = time.time()

    product = 1
    for num in range(2, n+1):
        if is_prime(num):
            product *= num

    end_time = time.time()
    time_taken = end_time - start_time

    return product, time_taken

