def flatten_array(nested_array):
    """
    Flattens a nested array into a single array.

    :param nested_array: List that may contain sublists or elements of various data types
    :return: A single flattened list
    """
    flat_list = []

    def _flatten(sub_list):
        for element in sub_list:
            if isinstance(element, list):
                _flatten(element)
            else:
                flat_list.append(element)

    _flatten(nested_array)
    return flat_list

