def sieve_of_eratosthenes(n):
    """
    Generate a list of prime numbers up to n using the Sieve of Eratosthenes algorithm.
    """
    is_prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    primes = [p for p in range(2, n + 1) if is_prime[p]]
    return primes

def prime_factors(n):
    """
    Find the prime factors of a given number n along with their exponents.
    """
    primes = sieve_of_eratosthenes(n)
    factors = {}
    for prime in primes:
        count = 0
        while n % prime == 0:
            n //= prime
            count += 1
        if count > 0:
            factors[prime] = count
        if n == 1:
            break
    return factors

