def reverse_words_manual(s):
    """
    Reverses the order of words in the given string s without using
    built-in string reversal or manipulation functions.
    """
    words = []
    length = len(s)
    word_start = None

    # Traverse the string and extract words manually
    for i in range(length):
        if s[i] != ' ':
            if word_start is None:
                word_start = i
        else:
            if word_start is not None:
                words.append(s[word_start:i])
                word_start = None

    # Add the last word if any
    if word_start is not None:
        words.append(s[word_start:length])

    # Rebuild the string with words in reverse order
    # Initialize an empty result variable
    result = ""
    for i in range(len(words) - 1, -1, -1):
        result += words[i]
        if i != 0:
            result += " "

    return result

