def count_unique_words(sentence):
    """
    Returns the number of unique words in the given sentence.
    Ignores case sensitivity and punctuation marks.
    """
    # Helper function to check if a character is a letter
    def is_letter(char):
        return 'a' <= char <= 'z' or 'A' <= char <= 'Z'

    # Normalize the case of the sentence to lowercase
    sentence = sentence.lower()

    word_set = set()
    word = ""
    for char in sentence:
        if is_letter(char):
            word += char
        else:
            if word:
                word_set.add(word)
                word = ""

    if word:
        word_set.add(word)

    return len(word_set)

