def validate_string(s):
    """
    Validate the string based on the specified conditions:
    1. The string's length must be greater than 2.
    2. Every digit from the 3rd to the end must be divisible by the 2nd digit.
    3. Every digit from the 4th to the end must also be divisible by the 1st digit.

    Additionally, the string must only contain digits and its length must be between 2 to 1000.
    """
    if not (2 <= len(s) <= 1000 and s.isdigit()):
        return False

    if len(s) < 3:
        return False

    second_digit = int(s[1])
    if second_digit == 0:
        return False

    for i in range(2, len(s)):
        if int(s[i]) % second_digit != 0:
            return False

    first_digit = int(s[0])
    if first_digit == 0:
        return False

    for i in range(3, len(s)):
        if int(s[i]) % first_digit != 0:
            return False

    return True

