def generate_hierarchical_dict(prim_keys, sec_keys, values):
    """
    Generate a hierarchical dictionary structure given three arrays:
    prim_keys: List of primary keys.
    sec_keys: List of secondary keys.
    values: List of values corresponding to each (primary key, secondary key) pair.

    Returns:
        A dictionary with format {primary_key: {secondary_key: value}}
    """
    if len(prim_keys) != len(sec_keys) or len(sec_keys) != len(values):
        raise ValueError("All input lists must have the same length")

    hierarchical_dict = {}

    for p_key, s_key, val in zip(prim_keys, sec_keys, values):
        if p_key not in hierarchical_dict:
            hierarchical_dict[p_key] = {}
        hierarchical_dict[p_key][s_key] = val

    return hierarchical_dict

