def find_median(arr):
    """
    Returns the median of an array of integers.
    """
    arr.sort()
    n = len(arr)
    if n % 2 == 1:
        return arr[n // 2]
    else:
        return (arr[n // 2 - 1] + arr[n // 2]) / 2

def parse_string(s):
    """
    Returns a dictionary where each consonant in the string is mapped to its frequency.
    Excludes vowels from the dictionary.
    """
    vowels = set('aeiou')
    frequency_dict = {}

    for char in s:
        if char not in vowels:
            if char in frequency_dict:
                frequency_dict[char] += 1
            else:
                frequency_dict[char] = 1

    return frequency_dict

