    elif hair_type == 'straight':
        if problem == 'dryness':
            return "Use hydrating shampoos and conditioners, and avoid over-washing your hair."
        elif problem == 'dandruff':
            return "Opt for a gentle, sulfate-free anti-dandruff shampoo and avoid products that can cause buildup."
        elif problem == 'hairloss':
            return "Incorporate scalp massages into your routine and use products that strengthen hair from the root."
        else:
            return "Consult a professional stylist for other straight hair problems."

    elif hair_type == 'wavy':
