def classify_even_odd(numbers):
    """
    Classifies the elements of a given list of integers into even or odd.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    dict: A dictionary with two keys 'even' and 'odd' where the values are
    lists of even and odd numbers from the input list respectively.
    """
    classified = {'even': [], 'odd': []}
    for number in numbers:
        if number % 2 == 0:
            classified['even'].append(number)
        else:
            classified['odd'].append(number)
    return classified

