def max_subarray_sum(nums):
    """
    Returns the maximum subarray sum along with the starting and ending indices using a modified Kadane's algorithm.
    Returns an empty list if the input list is empty or all elements are negative.
    """
    if not nums or all(n < 0 for n in nums):
        return []

    max_sum = curr_sum = nums[0]
    start = end = temp_start = 0

    for i in range(1, len(nums)):
        if curr_sum < 0:
            curr_sum = nums[i]
            temp_start = i
        else:
            curr_sum += nums[i]

        if curr_sum > max_sum:
            max_sum = curr_sum
            start = temp_start
            end = i

    return [max_sum, start, end]

