def filter_consecutive_duplicates(words):
    """
    Given a list of words, remove all consecutive duplicate letters
    from each word and return the new list.

    :param words: List of strings
    :return: List of strings with consecutive duplicates removed
    """
    def remove_consecutive_duplicates(word):
        if not word:
            return word
        result = [word[0]]
        for char in word[1:]:
            if char != result[-1]:  # Only add the character if it is different from the last one added to result
                result.append(char)
        return ''.join(result)

    return [remove_consecutive_duplicates(word) for word in words]

