def two_largest_numbers(numbers):
    """
    Returns the two largest numbers in the list.

    If the list has less than 2 numbers, it raises a ValueError.
    """
    if len(numbers) < 2:
        raise ValueError("List must contain at least two numbers")

    first, second = float('-inf'), float('-inf')

    for number in numbers:
        if number > first:
            first, second = number, first
        elif number > second:
            second = number

    return first, second

