def bubble_sort_strings(arr, reverse=False):
    """
    Implements bubble sort to sort an array of strings lexicographically.
    If reverse is True, sorts in reverse lexicographical order.
    """
    n = len(arr)
    for i in range(n-1):
        for j in range(n-1-i):
            if reverse:
                if arr[j] < arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
            else:
                if arr[j] > arr[j+1]:
                    arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

