def has_unique_chars(s):
    """
    Check if a string has all unique characters.
    """
    return len(s) == len(set(s))

def bubble_sort_by_length(strings):
    """
    Bubble sort a list of strings based on their length,
    only including strings with unique characters.
    """
    # Filter the strings to only include those with unique characters
    unique_strings = [s for s in strings if has_unique_chars(s)]

    n = len(unique_strings)
    for i in range(n):
        for j in range(0, n - i - 1):
            if len(unique_strings[j]) > len(unique_strings[j + 1]):
                unique_strings[j], unique_strings[j + 1] = unique_strings[j + 1], unique_strings[j]

    return unique_strings

def count_odd_xor_pairs(arr):
    """
    Returns the count of pairs in the list 'arr' whose XOR value is odd.
    """
    count_even = count_odd = 0

    for number in arr:
        if number % 2 == 0:
            count_even += 1
        else:
            count_odd += 1

    # Every even-odd pair will have an odd XOR
    return count_even * count_odd

