def add_matrices_recursive(matrix1, matrix2):
    """
    Adds two matrices of the same size using recursion.

    :param matrix1: First matrix (list of lists of integers).
    :param matrix2: Second matrix (list of lists of integers).
    :return: Sum of the two matrices (list of lists of integers).
    """
    if not matrix1 or not matrix2:
        return []

    def add_rows(row1, row2):
        if not row1 or not row2:
            return []
        return [row1[0] + row2[0]] + add_rows(row1[1:], row2[1:])

    return [add_rows(matrix1[0], matrix2[0])] + add_matrices_recursive(matrix1[1:], matrix2[1:])

