def count_and_identify_numbers(a, b, c):
    """
    Counts the number of equal numbers from three given integers,
    identifies the unique numbers and their frequencies.
    """
    try:
        # Validate the inputs are integers
        if not (isinstance(a, int) and isinstance(b, int) and isinstance(c, int)):
            raise ValueError("All inputs must be integers")

        # Create a list of the input numbers
        numbers = [a, b, c]

        # Count the frequency of each number using dictionary comprehension
        frequency = {number: numbers.count(number) for number in set(numbers)}

        # Calculate the count of equal numbers
        count_of_equal_numbers = max(frequency.values())

        return count_of_equal_numbers, frequency

    except Exception as e:
        return str(e)

