def find_triplet(nums, target):
    """
    Find a triplet in the list `nums` that adds up to the `target` number.

    Args:
    nums: List of integers.
    target: Target integer number for the sum.

    Returns:
    A triplet (a, b, c) that adds up to the target number, or None if no such triplet exists.
    """
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left = i + 1
        right = n - 1

        while left < right:
            triplet_sum = nums[i] + nums[left] + nums[right]

            if triplet_sum == target:
                return (nums[i], nums[left], nums[right])
            elif triplet_sum < target:
                left += 1
            else:
                right -= 1

    return None

