import random

def generate_random_integers(n, a, b):
    if not isinstance(n, int) or not isinstance(a, int) or not isinstance(b, int):
        raise ValueError("All inputs must be integers")
    if n <= 0:
        raise ValueError("The number of random integers to generate must be greater than 0")
    if a > b:
        raise ValueError("The value of 'a' must be less than or equal to 'b'")
    if b - a + 1 < n:
        raise ValueError("The range (b - a + 1) must be at least as large as n to generate unique integers")

    random_integers = random.sample(range(a, b + 1), n)
    total_sum = sum(random_integers)
    return random_integers, total_sum

