def test_funny_cache_mechanism():
    results = []

    def side_effect(a):
        nonlocal results
        results.append(a)
        return a

    decorated_side_effect = funny(side_effect)

    # First call, should not hit the cache.
    assert decorated_side_effect(10) == 10
    assert len(results) == 1  # results should have one entry

    # Second call, should hit the cache and not execute the function.
    assert decorated_side_effect(10) == 10
    assert len(results) == 1  # results should still have one entry because of caching

