def convert_number(value, command):
    """
    Converts the given number to binary or hexadecimal based on the user command.
    :param value: The decimal number to be converted (integer).
    :param command: The conversion command ('binary' or 'hexadecimal').
    :return: The converted number as a string.
    """
    try:
        num = int(value)  # Ensure the input is a valid integer
    except ValueError:
        return "Error: Invalid numerical input"

    if command == 'binary':
        return bin(num)[2:]  # Convert to binary and remove the '0b' prefix
    elif command == 'hexadecimal':
        return hex(num)[2:]  # Convert to hexadecimal and remove the '0x' prefix
    else:
        return "Error: Invalid conversion command"

# Example usage:
