def find_second_largest(nums):
    """
    Returns the second largest number in the array nums.
    """
    if len(nums) < 2:
        raise ValueError("Array should have at least two elements.")

    first_largest = second_largest = float('-inf')

    for num in nums:
        if num > first_largest:
            second_largest = first_largest
            first_largest = num
        elif first_largest > num > second_largest:
            second_largest = num

    if second_largest == float('-inf'):
        raise ValueError("There is no second distinct largest element.")

    return second_largest

def is_prime(n):
    """Check if a number is prime."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def fibonacci_numbers(limit):
    """Generate Fibonacci numbers up to a given limit."""
    fib_sequence = []
    a, b = 0, 1
    while a < limit:
        fib_sequence.append(a)
        a, b = b, a + b
    return fib_sequence

def fibonacci_primes(limit):
    """Find all Fibonacci prime numbers less than given limit."""
    fib_sequence = fibonacci_numbers(limit)
    fib_primes = [num for num in fib_sequence if is_prime(num)]
    return fib_primes

def factorial(n):
    """
    Returns the factorial of a non-negative integer n.
    If n is 0, the factorial is 1 by definition.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        return 1
    return n * factorial(n - 1)

