def generate_permutations(lst):
    if len(lst) == 1:
        return [lst]
    permutations = []
    for obj in lst:
        remaining = lst[:lst.index(obj)] + lst[lst.index(obj)+1:]
        for perm in generate_permutations(remaining):
            permutations.append([obj] + perm)
    return permutations

def generate_permutations_iterative(lst):
    permutations = []
    stack = [(lst, [])]
    while stack:
        current, perm = stack.pop()
        if len(current) == 1:
            permutations.append([current[0]] + perm)
        else:
            for obj in current:
                remaining = current[:current.index(obj)] + current[current.index(obj) + 1:]
                stack.append((remaining, [obj] + perm))
    return permutations

def fibonacci(n):
    """
    Generate and return the Fibonacci sequence up to the n-th number.

    The function uses a memoization technique to handle large values of n efficiently.
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input should be a positive integer.")

    memo = {0: 0, 1: 1}

    def _fibonacci(k):
        if k in memo:
            return memo[k]
        memo[k] = _fibonacci(k - 1) + _fibonacci(k - 2)
        return memo[k]

    result = [_fibonacci(i) for i in range(n)]
    return result

