def is_prime(num):
    """
    Determines if a number is a prime.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def nearest_prime(n):
    """
    Returns the nearest prime number.
    If n is already a prime number, it returns n.
    If n is not a prime number, it returns the next highest prime number.
    """
    if is_prime(n):
        return n
    next_prime = n + 1
    while not is_prime(next_prime):
        next_prime += 1
    return next_prime

