def bubble_sort_strings_by_length(arr):
    """
    Sorts an array of strings in ascending order based on their length
    using bubble sort, and returns the number of swaps performed.
    """
    n = len(arr)
    swaps = 0
    for i in range(n):
        for j in range(0, n-i-1):
            if len(arr[j]) > len(arr[j+1]):
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swaps += 1
    return arr, swaps

def longest_subarray_with_equal_0s_1s(arr):
    """
    Find the longest subarray with equal number of 0's and 1's in a binary array.
    """
    n = len(arr)
    hash_map = {}

    max_len = 0
    curr_sum = 0

    for i in range(n):
        if arr[i] == 0:
            curr_sum -= 1
        else:
            curr_sum += 1

        if curr_sum == 0:
            max_len = i + 1

        if curr_sum in hash_map:
            max_len = max(max_len, i - hash_map[curr_sum])
        else:
            hash_map[curr_sum] = i

    return max_len

