def generate_combinations(str1, str2, str3):
    """
    Generate a list of all possible combinations of characters from the three input strings.
    Ensure no character duplication in any single combination.
    """
    combinations = []
    for char1 in str1:
        for char2 in str2:
            for char3 in str3:
                if char1 != char2 and char1 != char3 and char2 != char3:
                    combinations.append(char1 + char2 + char3)
    return combinations

