def reverse_and_sort_dict(input_dict):
    """
    Reverses the keys and values in a dictionary and sorts the new pairs by the alphabetical order of the values.

    :param input_dict: Dictionary with strings as keys and values
    :return: A new dictionary with reversed and sorted (by new keys) pairs
    """
    if not all(isinstance(k, str) and isinstance(v, str) for k, v in input_dict.items()):
        raise ValueError("Only dictionaries with strings as keys and values are supported.")

    reversed_dict = {v: k for k, v in input_dict.items()}
    sorted_keys = sorted(reversed_dict.keys())
    sorted_dict = {key: reversed_dict[key] for key in sorted_keys}

    return sorted_dict

