def longest_increasing_subsequence(sequence):
    """
    Returns the longest increasing subsequence (LIS) of the input sequence.

    :param sequence: A list of distinct integers.
    :return: The longest increasing subsequence as a list.
    """
    if not sequence:
        return []

    n = len(sequence)
    lis = []  # This will hold the longest increasing subsequence found
    for i in range(n):
        current_lis = []
        current_lis.append(sequence[i])
        for j in range(i+1, n):
            if sequence[j] > current_lis[-1]:
                current_lis.append(sequence[j])
        if len(current_lis) > len(lis):
            lis = current_lis
    return lis

