def find_smallest_number(numbers):
    """
    Returns the smallest number in the given list without using any built-in functions.
    """
    if not numbers:
        raise ValueError("The list is empty")

    smallest = numbers[0]
    for number in numbers[1:]:
        if number < smallest:
            smallest = number
    return smallest

