import csv

def read_fibonacci_number_from_csv(filename):
    """
    Reads the first element from a CSV file and returns it as an integer.
    """
    with open(filename, mode='r') as file:
        reader = csv.reader(file)
        for row in reader:
            return int(row[0])

def fibonacci(n):
    """
    Returns the nth Fibonacci number using a recursive approach.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def calculate_fibonacci_from_csv(filename):
    """
    Reads Fibonacci number index from a CSV file and calculates the Fibonacci number.
    """
    n = read_fibonacci_number_from_csv(filename)
    return fibonacci(n)

def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers from 2 to n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return []

    sieve = [True] * (n + 1)
    p = 2
    while (p ** 2 <= n):
        if sieve[p]:
            for i in range(p ** 2, n + 1, p):
                sieve[i] = False
        p += 1

    prime_numbers = [p for p in range(2, n + 1) if sieve[p]]
    return prime_numbers

