def check_vowels_in_order(s):
    """
    Checks if the string contains all vowels in alphabetical order without duplicates and
    ignoring case. Returns the length of the substring that meets the criteria or 0 if none exists.
    """
    vowels = "aeiou"
    found_vowels = []
    s = s.lower()

    for char in s:
        if char in vowels:
            if not found_vowels or char > found_vowels[-1]:
                found_vowels.append(char)
            elif char == found_vowels[-1]:
                continue
            else:
                return 0

    if len(found_vowels) == len(vowels):
        return len(found_vowels)
    return 0

