def print_numbers(upper_limit, print_even):
    """
    Prints all even or odd numbers from 0 up to but not including the upper limit
    depending on the value of the boolean parameter print_even.

    Parameters:
        upper_limit (int): The upper limit (exclusive) for the number range.
        print_even (bool): A flag determining whether to print even or odd numbers.
    """
    if not isinstance(upper_limit, int) or upper_limit <= 0:
        raise ValueError("Upper limit must be a positive integer greater than 0.")

    if not isinstance(print_even, bool):
        raise ValueError("The print_even parameter must be boolean.")

    for i in range(upper_limit):
        if print_even and i % 2 == 0:
            print(i)
        elif not print_even and i % 2 != 0:
            print(i)

