def analyze_structure(data):
    """
    Recursively analyzes a nested data structure and applies specific operations based on type:
    - int: returns the square of the integer.
    - str: returns the length of the string.
    - list: returns the sum of the analyzed elements.
    - dict: returns the number of keys.

    Args:
    data: A nested data structure which can be an int, str, list or dict.

    Returns:
    The analysis result based on the type.
    """
    if isinstance(data, int):
        return data ** 2
    elif isinstance(data, str):
        return len(data)
    elif isinstance(data, list):
        return sum(analyze_structure(item) for item in data)
    elif isinstance(data, dict):
        return len(data.keys())
    else:
        raise ValueError("Unsupported data type")

