def find_second_largest(nums):
    """
    Returns the second largest number in the list.
    Assumes that the list has at least two unique numbers.
    """
    if len(nums) < 2:
        raise ValueError("The list must contain at least two unique numbers")

    largest = second_largest = float('-inf')

    for number in nums:
        if number > largest:
            second_largest, largest = largest, number
        elif number > second_largest and number < largest:
            second_largest = number

    return second_largest

