import base64
import json

def encode_to_base64_json(data):
    """
    Encodes data structure (including complex types such as tuples and dictionaries)
    to a JSON string and then to a base64 encoded string.
    """

    # Helper function to convert tuples to lists for JSON serialization
    def convert(data):
        if isinstance(data, tuple):
            return {'__tuple__': True, 'items': [convert(i) for i in data]}
        elif isinstance(data, dict):
            return {key: convert(value) for key, value in data.items()}
        elif isinstance(data, list):
            return [convert(element) for element in data]
        return data

    json_string = json.dumps(convert(data))
    base64_bytes = base64.b64encode(json_string.encode('utf-8'))
    return base64_bytes.decode('utf-8')

def decode_from_base64_json(encoded_data):
    """
    Decodes a base64 encoded JSON string back to its original form, handling
    complex types like tuples and dictionaries.
    """

    # Helper function to revert the conversion
    def revert(data):
        if isinstance(data, dict):
            if '__tuple__' in data:
                return tuple(revert(item) for item in data['items'])
            return {key: revert(value) for key, value in data.items()}
        elif isinstance(data, list):
            return [revert(element) for element in data]
        return data

    base64_bytes = encoded_data.encode('utf-8')
    json_string = base64.b64decode(base64_bytes).decode('utf-8')
    data = json.loads(json_string)
    return revert(data)

