def median_score_advanced(students, average_duplicates=False):
    """
    Calculate the median score from an array of student scores.

    Parameters:
    students (list of dict): Array of objects, each containing a student's ID number and their test score.
    average_duplicates (bool): If true, average the duplicate scores.

    Returns:
    float: The median of all unique scores.

    Raises:
    ValueError: If the input list is empty or contains non-numeric scores.
    """
    if not students:
        raise ValueError("The input list is empty")

    scores = [student['score'] for student in students if isinstance(student['score'], (int, float))]

    if len(scores) != len(students):
        raise ValueError("All scores must be numeric")

    if average_duplicates:
        score_dict = {}
        for score in scores:
            if score not in score_dict:
                score_dict[score] = [score]
            else:
                score_dict[score].append(score)

        averaged_scores = [sum(values)/len(values) for values in score_dict.values()]
        unique_scores = averaged_scores
    else:
        unique_scores = list(set(scores))

    unique_scores.sort()

    n = len(unique_scores)
    if n == 0:
        raise ValueError("No unique scores to process")

    mid = n // 2
    if n % 2 == 0:
        median = (unique_scores[mid - 1] + unique_scores[mid]) / 2.0
    else:
        median = unique_scores[mid]

    return median

def is_prime(n):
    """
    Check if a number is prime.
    Returns True if n is a prime number, otherwise False.
    """
    if not isinstance(n, int) or n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def find_smallest_prime_greater_than(n):
    """
    Find the smallest prime number greater than the given number.
    """
    if not isinstance(n, int) or n < 1:
        return None
    candidate = n + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

def flatten_and_sort(lst):
    """
    Flattens a nested list, removes duplicates, and sorts it in descending order.

    :param lst: The list to be flattened.
    :type lst: list
    :return: Flattened, sorted (in descending order) list without duplicates.
    :rtype: list
    """
    def flatten(nested_lst):
        for item in nested_lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    # Flatten the list
    flattened_list = list(flatten(lst))

    # Remove duplicates and sort in descending order
    return sorted(set(flattened_list), reverse=True)

