from itertools import permutations

def is_balanced(sequence):
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{'}
    for char in sequence:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
    return stack == []

def generate_bracket_sequences(S, n):
    if n % len(S) != 0:
        return "It is impossible to generate such sequences of length n."

    combinations = set()
    S = ''.join([char for char in S])
    required_length = n // len(S)

    for perm in permutations(S * required_length):
        seq = ''.join(perm)
        if is_balanced(seq):
            combinations.add(seq)

    if not combinations:
        return "It is impossible to generate such sequences of length n."

    return list(combinations)

