def merge_sorted_lists(list1, list2):
    """
    Takes two sorted lists of equal length and combines them into a single sorted list.
    """
    combined_list = []
    i, j = 0, 0
    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            combined_list.append(list1[i])
            i += 1
        else:
            combined_list.append(list2[j])
            j += 1

    while i < len(list1):
        combined_list.append(list1[i])
        i += 1

    while j < len(list2):
        combined_list.append(list2[j])
        j += 1

    return combined_list

