def print_primes_up_to_n(n):
    """
    Prints all prime numbers less than or equal to n.
    """
    if n < 2:
        return []

    primes = []

    for num in range(2, n + 1):
        is_prime = True
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    return primes

