def remove_duplicates(arr):
    """
    Removes duplicate elements from an array without using any built-in functions or additional data structures.
    """
    write_index = 0

    for i in range(len(arr)):
        is_duplicate = False
        for j in range(write_index):
            if arr[i] == arr[j]:
                is_duplicate = True
                break
        if not is_duplicate:
            arr[write_index] = arr[i]
            write_index += 1

    return arr[:write_index]

