def largest_prime_factor(n):
    """
    Returns the largest prime factor of the given number n.
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while (i * i) <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    def largest_factor(n, factor=2):
        while n % factor == 0:
            n //= factor
        if n == 1:
            return factor
        next_factor = factor + 1
        while not is_prime(next_factor):
            next_factor += 1
        return largest_factor(n, next_factor)

    return largest_factor(n)

