def linear_search_2d(array, target):
    """
    Performs a linear search for a target value in a 2D array.

    Args:
    array (list of list of int): The 2D array to search in.
    target (int): The value to search for.

    Returns:
    tuple: A tuple (x, y) representing the coordinates of the target value
           if found, otherwise (-1, -1).
    """
    for x in range(len(array)):
        for y in range(len(array[x])):
            if array[x][y] == target:
                return (x, y)
    return (-1, -1)

def is_prime(n):
    """
    Returns True if n is a prime number, else returns False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def smallest_prime(numbers):
    """
    Returns the smallest prime number in the given list of positive integers.
    If no prime number is found in the list, returns -1.
    """
    smallest = float('inf')
    found_prime = False

    for number in numbers:
        if is_prime(number):
            found_prime = True
            if number < smallest:
                smallest = number

    return smallest if found_prime else -1

