def sum_reverse(num1, num2):
    """
    Returns the sum of the reversed digits of num1 and num2.
    If the sum is a palindrome, it returns the sum.
    Otherwise, it returns the negative of the sum.
    """
    def reverse_number(num):
        return int(str(num)[::-1])

    def is_palindrome(num):
        s = str(num)
        return s == s[::-1]

    rev_num1 = reverse_number(num1)
    rev_num2 = reverse_number(num2)

    total = rev_num1 + rev_num2

    if is_palindrome(total):
        return total
    else:
        return -total

def play_game(guesses):
    score = 10
    num_list = [42, 7, 11, 13]
    guess_index = 0

    for num in num_list:
        while True:
            if guess_index >= len(guesses):
                raise ValueError("Not enough guesses provided")
            guess = guesses[guess_index]
            guess_index += 1

            if 1 <= guess <= 100:
                if guess == num:
                    score += 10
                    break
                elif abs(guess - num) <= 10:
                    score += 5
                else:
                    score -= 7
                break
            else:
                raise ValueError("Guesses must be between 1 and 100")

    return score

