def longest_increasing_sequence(nums):
    """
    Returns the longest continuous increasing sequence of numbers in a given list.
    """
    if not nums:
        return []

    max_length = 1
    current_length = 1
    start_index = 0
    max_start_index = 0

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                max_start_index = start_index
            current_length = 1
            start_index = i

    if current_length > max_length:
        max_length = current_length
        max_start_index = start_index

    return nums[max_start_index:max_start_index + max_length]

