def find_pair(nums, target):
    """
    Returns the first pair of elements from the nums list that adds up to the target.
    :param nums: List of integers
    :param target: Target sum
    :return: Tuple containing the first pair of integers that add up to the target or None if no such pair exists
    """
    seen = {}
    for num in nums:
        complement = target - num
        if complement in seen:
            return (complement, num)
        seen[num] = True
    return None

