def find_max_element(matrix):
    """
    Finds the maximum element in a given 2D array (matrix).

    :param matrix: List of lists where each inner list has the same length.
    :return: The maximum element in the 2D array.
    """
    max_element = None
    for row in matrix:
        for elem in row:
            if max_element is None or elem > max_element:
                max_element = elem
    return max_element

