def matches_pattern(s, p):
    """
    Checks whether string s matches the pattern p.
    '?' in s can be replaced by any character to match p.
    """
    if len(s) != len(p):
        return False
    for sc, pc in zip(s, p):
        if sc != '?' and sc != pc:
            return False
    return True

def count_matching_strings(strings, patterns):
    """
    Counts the number of strings in strings that match their respective patterns in patterns.
    """
    count = 0
    for s, p in zip(strings, patterns):
        if matches_pattern(s, p):
            count += 1
    return count

def int_to_hex(value):
    """
    Converts an integer to its hexadecimal representation.
    For negative numbers, two's complement form is used.
    """
    if not isinstance(value, int):
        raise ValueError("Input must be an integer")

    if value < 0:
        value = (1 << 32) + value

    return hex(value)

def sequence_to_hex(sequence):
    """
    Converts a sequence of integers to their hexadecimal representations.
    """
    if not all(isinstance(x, int) for x in sequence):
        raise ValueError("All values in the sequence must be integers")

    return [int_to_hex(x) for x in sequence]

