def longest_common_prefix(strs):
    """
    Returns the longest common prefix string amongst an array of strings.
    """
    if not strs:
        return ""

    # Assume the first string is the common prefix completely
    prefix = strs[0]

    # Iterate over the other strings
    for s in strs[1:]:
        # Reduce the prefix one character at a time until it matches the start of the current string
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""

    return prefix

