def fibonacci_series(n):
    """
    Generates the Fibonacci series up to the nth number.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]

    series = [0, 1]
    while len(series) < n:
        next_value = series[-1] + series[-2]
        series.append(next_value)

    return series

