def is_prime(n):
    """
    Helper function to determine if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_check_list(numbers):
    """
    Returns a list where each element is True if the corresponding element
    in the input list is prime, and False otherwise.
    """
    return [is_prime(num) for num in numbers]

