def generate_3d_array(x, y, z):
    """
    Generates a 3D array of dimensions x by y by z filled with zeros using recursion.
    """
    if x == 0:
        return []
    if y == 0:
        return generate_3d_array(x - 1, 3, z)
    if z == 0:
        return generate_3d_array(x, y - 1, 3)
    return [0] + generate_3d_array(x, y, z - 1)

def reshape_3d_array(arr, x, y, z):
    """
    Reshapes the flat array generated into a 3D array using the given dimensions.
    """
    return [[[arr[i * y * z + j * z + k] for k in range(z)] for j in range(y)] for i in range(x)]

# Function to generate a 3x3x3 array
def generate_3x3x3():
    flat_array = generate_3d_array(2, 3, 3)
    return reshape_3d_array(flat_array, 2, 3, 3)

