def factorial(n, memo={}):
    """
    Returns the factorial of a given positive integer n using recursion and memoization.
    Raises a ValueError if n is negative or not an integer.
    """
    if not isinstance(n, int):
        raise ValueError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n in memo:
        return memo[n]

    if n == 0 or n == 1:
        result = 1
    else:
        result = n * factorial(n - 1, memo)

    memo[n] = result

    return result

