import random

def number_guessing_game(tries=6):
    number_to_guess = random.randint(1, 100)
    print("Let's play the number guessing game!")
    print(f"You have {tries} tries to guess the number between 1 and 100.")

    for i in range(tries):
        try:
            player_guess = int(input(f"Attempt {i + 1}/{tries}: Enter your guess: "))
        except ValueError:
            print("Please enter a valid number.")
            continue

        if player_guess < 1 or player_guess > 100:
            print("Your guess should be between 1 and 100. Try again.")
            continue

        if player_guess < number_to_guess:
            print("Your guess is too low.")
        elif player_guess > number_to_guess:
            print("Your guess is too high.")
        else:
            print(f"Congratulations! You've guessed the number {number_to_guess} correctly.")
            return

    print(f"Sorry, you've used all your tries. The number was {number_to_guess}.")

