def invert_string_and_categorize(s):
    """
    Returns the inverted string and categorizes the entities within the string.

    Parameters:
        s (str): Input string to be inverted and categorized.

    Returns:
        dict: A dictionary with the inverted string and the counts of various entities
    """
    # Define the result dictionary to hold the inverted string and categories
    result = {
        'inverted_string': s[::-1],
        'alphabets': 0,
        'numbers': 0,
        'punctuation': 0,
        'whitespace': 0
    }

    for char in s:
        if char.isalpha():
            result['alphabets'] += 1
        elif char.isdigit():
            result['numbers'] += 1
        elif char.isspace():
            result['whitespace'] += 1
        else:
            result['punctuation'] += 1

    return result

