def unique_elements(lst):
    """
    Returns a list of unique elements from the given list, maintaining order of first occurrence.
    """
    result = []
    for item in lst:
        is_unique = True
        for unique_item in result:
            if item == unique_item:
                is_unique = False
                break
        if is_unique:
            result.append(item)
    return result

