def concatenate_and_remove_duplicates(arr1, arr2):
    """
    Concatenates two arrays without using built-in array concatenation methods.
    Removes duplicate elements from the resulting concatenated array.
    """
    result = []
    seen = set()

    for item in arr1:
        if item not in seen:
            result.append(item)
            seen.add(item)

    for item in arr2:
        if item not in seen:
            result.append(item)
            seen.add(item)

    return result

