def sort_three_numbers(a, b, c):
    """
    This function sorts three numbers in ascending order.
    It returns a tuple containing the sorted numbers.
    """
    if a > b:
        a, b = b, a
    if b > c:
        b, c = c, b
    if a > b:
        a, b = b, a
    return (a, b, c)

