def bubble_sort_visual(arr):
    """
    Sorts an array of numbers in ascending order using the bubble sort algorithm.
    Prints visual representation of intermediate steps using asterisks (*) for each value in the array.
    """
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
            print_visual(arr)
    return arr

def print_visual(arr):
    """
    Prints the array with each value represented by a number of asterisks (*) equal to its value.
    """
    for num in arr:
        print('*' * num)
    print()

