import random

def is_prime(n):
    """
    Check if a number n is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_random_prime():
    """
    Generates a random prime number between 1 and 1000.
    """
    primes = [i for i in range(1, 1001) if is_prime(i)]
    return random.choice(primes)

def lookup(dictionary, key):
    """
    Retrieves the value from the dictionary given a specific key
    without using any built-in dictionary methods or direct key access.
    """
    for k, v in dictionary.items():
        if k == key:
            return v
    return None  # Or raise an exception if key is not found

