def is_prime(n):
    """
    Check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def print_primes_between(start, end):
    """
    Print all prime numbers between two given values.
    """
    try:
        start = int(start)
        end = int(end)

        if start < 0 or end < 0:
            raise ValueError("Negative values are not allowed.")

        if start > end:
            start, end = end, start

        prime_numbers = [num for num in range(start, end + 1) if is_prime(num)]

        if prime_numbers:
            print(f"Prime numbers between {start} and {end}: {prime_numbers}")
        else:
            print(f"There are no prime numbers between {start} and {end}.")
    except ValueError as e:
        print(f"Invalid input: {e}")

