def is_prime(n):
    """
    Helper function to check if a number n is a prime number.
    """
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_not_same_prime(num1, num2):
    """
    Returns True if either num1 or num2 is not a prime number.
    Returns False if both num1 and num2 are prime numbers.
    """
    return not (is_prime(num1) and is_prime(num2))

