from collections import deque
from typing import List

def updateMatrix(matrix: List[List[int]]) -> List[List[int]]:
    m, n = len(matrix), len(matrix[0])
    dist = [[float('inf')] * n for _ in range(m)]
    queue = deque()

    # Initialize the queue with all 0's
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 0:
                dist[i][j] = 0
                queue.append((i, j))

    # Directions for moving up, down, left, right
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    # BFS to update the distances
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n:
                if dist[nx][ny] > dist[x][y] + 1:
                    dist[nx][ny] = dist[x][y] + 1
                    queue.append((nx, ny))

    return dist

def counter(reset=False, max_count=None, reset_after=None, threshold=1):
    def decorator(func):
        func._number_of_calls = 0
        func._max_calls_in_row = 0
        func._current_consecutive_calls = 0

        def wrapper(*args, **kwargs):
            if reset:
                func._number_of_calls = 0
                func._current_consecutive_calls = 0

            func._number_of_calls += 1
            func._current_consecutive_calls += 1

            # Check threshold and apply reset if required
            if func._current_consecutive_calls < threshold:
                func._current_consecutive_calls = 0
            else:
                if func._current_consecutive_calls > func._max_calls_in_row:
                    func._max_calls_in_row = func._current_consecutive_calls

                if max_count and func._current_consecutive_calls > max_count:
                    raise Exception('Exceeded max number of consecutive calls')

            # Reset counter if reset_after condition met
            if reset_after and func._number_of_calls >= reset_after:
                func._number_of_calls = 0
                func._current_consecutive_calls = 0

            return func(*args, **kwargs)

        return wrapper
    return decorator

