def sort_dicts_by_keys(dict_list, primary_key, secondary_key=None):
    """
    Sorts a list of dictionaries alphabetically based on a specific key.
    If two dictionaries have the same value for the specific key, sorts them
    based on another key in the dictionaries.

    :param dict_list: List of dictionaries to be sorted.
    :param primary_key: The key to sort the dictionaries by primarily.
    :param secondary_key: The key to sort the dictionaries by secondarily if the
                          primary key values are the same. Default is None.
    :return: A new list of sorted dictionaries.
    """
    if secondary_key:
        return sorted(dict_list, key=lambda x: (x[primary_key], x[secondary_key]))
    else:
        return sorted(dict_list, key=lambda x: x[primary_key])

def knapsack_recursive(values, weights, capacity, n):
    """
    A function to solve the 0/1 Knapsack problem using recursion.

    :param values: List of values of the items.
    :param weights: List of weights of the items.
    :param capacity: Maximum weight capacity of the knapsack.
    :param n: Number of items.
    :return: Maximum value that can be accommodated in the knapsack.
    """
    # Base Case: If no items are left or capacity is 0
    if n == 0 or capacity == 0:
        return 0

    # If weight of the nth item is more than Knapsack capacity, it cannot be included
    if weights[n-1] > capacity:
        return knapsack_recursive(values, weights, capacity, n-1)
    else:
        # Return the maximum of two cases:
        # (1) nth item included
        # (2) not included
        return max(
            values[n-1] + knapsack_recursive(values, weights, capacity - weights[n-1], n-1),
            knapsack_recursive(values, weights, capacity, n-1)
        )

