def is_leap_year(year):
    """
    Check if a given year is a leap year.
    """
    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    else:
        return False

def days_in_month(month, year):
    """
    Return the number of days in a given month of a given year.
    """
    if month not in range(1, 13):
        raise ValueError("Month must be between 1 and 12.")

    if year < 1:
        raise ValueError("Year must be a positive integer.")

    # Days in each month. February has 28 days by default.
    month_days = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    # Check for leap year and adjust February days.
    if month == 2 and is_leap_year(year):
        return 29
    else:
        return month_days[month - 1]

def get_days_in_month(month, year):
    """
    Wrapper function to get user input and return days in month.
    """
    try:
        days = days_in_month(month, year)
        return f"Number of days in month {month}, year {year}: {days}"
    except ValueError as e:
        return str(e)

