def create_nested_dict(keys, default=None, values=None):
    """
    Creates a nested dictionary from a list of keys.

    Parameters:
    - keys (list): List of keys for the nested dictionary.
    - default: The default value if values list is not provided or exhausted.
    - values (list, optional): List of values to rotate through for each level.

    Returns:
    - dict: The nested dictionary.
    """
    if not keys:
        return default if values is None else values[0]

    if values:
        values_len = len(values)
    else:
        values_len = 0

    nested_dict = current = {}
    for i, key in enumerate(keys):
        if i + 1 == len(keys):
            if values:
                value = values[i % values_len] if i < values_len else values[-1]
            else:
                value = default
            current[key] = value
        else:
            next_dict = {}
            current[key] = next_dict
            current = next_dict

    return nested_dict

