def longest_palindromic_substring(s):
    """
    Returns the longest palindromic substring in a timeseries format.
    """
    n = len(s)
    if n == 0:
        return ""

    dp = [[False] * n for _ in range(n)]
    start = 0
    max_length = 1

    for i in range(n):
        dp[i][i] = True

    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = True
            start = i
            max_length = 2

    for length in range(3, n+1):
        for i in range(n-length+1):
            j = i+length-1
            if s[i] == s[j] and dp[i+1][j-1]:
                dp[i][j] = True
                if length > max_length:
                    start = i
                    max_length = length

    # To convert the substring to time-series format
    longest_palindrome = s[start:start+max_length]
    time_series_format = "->".join(longest_palindrome)
    return time_series_format

