def map_indices(list1, list2):
    """
    Maps elements from list2 as keys to their indices in list1 as values.

    :param list1: The list in which to search for the indices.
    :param list2: The list whose elements will be used as keys in the resulting dictionary.
    :return: A dictionary with elements from list2 as keys and a list of their indices in list1 as values.
    """
    index_map = {element: [] for element in list2}
    for index, element in enumerate(list1):
        if element in index_map:
            index_map[element].append(index)
    return index_map

