def grade_to_letter(grade):
    """
    Translates a numeric grade to a letter grade with + or - where appropriate.

    Parameters:
        grade (float): A numeric grade between 0 and 100.

    Returns:
        str: The letter grade with + or -.

    Raises:
        ValueError: If grade is not within the 0-100 range.
    """
    if not (0 <= grade <= 100):
        raise ValueError("Grade must be between 0 and 100")

    if grade >= 97:
        return "A+"
    elif grade >= 93:
        return "A"
    elif grade >= 90:
        return "A-"
    elif grade >= 87:
        return "B+"
    elif grade >= 83:
        return "B"
    elif grade >= 80:
        return "B-"
    elif grade >= 77:
        return "C+"
    elif grade >= 73:
        return "C"
    elif grade >= 70:
        return "C-"
    elif grade >= 67:
        return "D+"
    elif grade >= 63:
        return "D"
    elif grade >= 60:
        return "D-"
    else:
        return "F"

