def kadane_algorithm(arr):
    """
    Returns the maximum subarray sum using Kadane's algorithm.
    """
    max_current = max_global = arr[0]
    for num in arr[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current
    return max_global

def kadane_algorithm_min(arr):
    """
    Returns the minimum subarray sum using a variation of Kadane's algorithm.
    """
    min_current = min_global = arr[0]
    for num in arr[1:]:
        min_current = min(num, min_current + num)
        if min_current < min_global:
            min_global = min_current
    return min_global

def kadane_algorithm_max_and_min(arr):
    """
    Returns a tuple containing the maximum and minimum subarray sums using Kadane's algorithm.
    """
    return (kadane_algorithm(arr), kadane_algorithm_min(arr))

