def lcs(X, Y):
    """
    Returns the length of the Longest Common Subsequence (LCS) of sequences X and Y.
    """
    m = len(X)
    n = len(Y)
    L = [[None] * (n + 1) for i in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                L[i][j] = 0
            elif X[i-1] == Y[j-1]:
                L[i][j] = L[i-1][j-1] + 1
            else:
                L[i][j] = max(L[i-1][j], L[i][j-1])

    return L[m][n]

def is_cheerful_string(s):
    """
    Determines if a string is cheerful.
    A string is cheerful if its length is at least 3, no three consecutive characters are the same,
    and it does not contain any numerical digits.
    """
    # Check if the string contains any numerical digits:
    if any(char.isdigit() for char in s):
        return False

    # Check the length of the string:
    if len(s) < 3:
        return False

    # Check for three consecutive same characters:
    for i in range(len(s) - 2):
        if s[i] == s[i+1] and s[i+1] == s[i+2]:
            return False

    return True

import random

def guess_number(target):
    """
    Guess a number between 1 and 1000 given hints of 'hot' and 'cold'.
    """
    low = 1
    high = 1000
    tries = 0

    while True:
        guess = (low + high) // 2
        tries += 1
        if guess == target:
            return (guess, tries)
        elif abs(guess - target) <= 10:
            feedback = 'hot'
        else:
            feedback = 'cold'

        if feedback == 'hot':
            if guess < target:
                low = guess + 1
            elif guess > target:
                high = guess - 1
        elif feedback == 'cold':
            if guess > target:
                high = guess - 1
            else:
                low = guess + 1

