import json

def parse_names_from_json(json_str):
    """
    Parses a JSON string and extracts 'name' fields, handling nested structures.
    Unescapes escaped characters and prints the names in reverse alphabetical order.
    """

    def extract_names(obj, names):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == "name" and isinstance(value, str):
                    names.add(value.replace("\\'", "'"))
                if isinstance(value, (dict, list)):
                    extract_names(value, names)
        elif isinstance(obj, list):
            for item in obj:
                extract_names(item, names)

    json_obj = json.loads(json_str)
    names = set()
    extract_names(json_obj, names)

    for name in sorted(names, reverse=True):
        print(name)

