def set_intersection(set1, set2):
    """
    Returns the intersection of two sets using loops and recursion.
    """
    def intersection_recursive(lst1, lst2, start):
        if start == len(lst1):
            return []
        if lst1[start] in lst2:
            return [lst1[start]] + intersection_recursive(lst1, lst2, start + 1)
        return intersection_recursive(lst1, lst2, start + 1)

    list_set1 = list(set1)
    list_set2 = list(set2)

    return set(intersection_recursive(list_set1, list_set2, 0))

