def factorial(n):
    """
    Computes the factorial of a given non-negative integer using a loop structure.
    Handles errors for negative, non-integer values, and values greater than 20.
    """
    if not isinstance(n, int) or n < 0:
        return "Input should be a positive integer."
    if n > 20:
        return "Factorial result too large to be computed."

    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

