def is_palindrome(s):
    """
    Checks if the input string is a palindrome, ignoring non-alphanumeric characters and case-insensitivity.
    """
    clean_s = []
    for char in s:
        if char.isalnum():
            clean_s.append(char.lower())

    left, right = 0, len(clean_s) - 1
    while left < right:
        if clean_s[left] != clean_s[right]:
            return False
        left += 1
        right -= 1

    return True

