def decimal_to_binary(n):
    """
    Converts a decimal number to its binary representation as a string.
    Handles zero and negative numbers as well.
    """
    if n == 0:
        return "0"
    elif n < 0:
        return "-" + bin(n)[3:]  # Skip the first three characters ('-0b')
    else:
        return bin(n)[2:]  # Skip the first two characters ('0b')

