def rotate_90_clockwise(matrix):
    """
    Rotates the given n x n matrix by 90 degrees clockwise in place.
    Assumption: The input is a non-empty square 2D matrix (n x n).
    """
    n = len(matrix)
    if n == 0 or len(matrix[0]) == 0:
        return

    # Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row
    for i in range(n):
        matrix[i].reverse()

