def sieve_of_eratosthenes(n):
    """
    Returns a list of all primes less than or equal to n.
    """
    is_prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if (is_prime[p] == True):
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1
    primes = []
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
    return primes

def unique_prime_squares(nums):
    """
    Returns a set containing the squares of unique prime numbers from the input list.
    """
    if not nums:
        return set()

    max_num = max(nums)
    primes = sieve_of_eratosthenes(max_num)
    prime_set = set(primes)

    result = {num ** 2 for num in nums if num in prime_set}
    return result

