def transform_to_set(data):
    """
    Transforms a list into a set, ensuring the final output maintains
    the set data structure. It also manages nested lists, converting
    them into nested sets.
    """
    if isinstance(data, list):
        transformed_set = set()
        for item in data:
            transformed_set.add(transform_to_set(item))
        return frozenset(transformed_set)
    elif isinstance(data, set):
        return frozenset(data)
    else:
        return data

