def max_depth(d):
    """
    Recursively finds the maximum depth of a nested dictionary or list.
    """
    if isinstance(d, dict):
        return 1 + max((max_depth(v) for v in d.values()), default=0)
    elif isinstance(d, list):
        return 1 + max((max_depth(item) for item in d), default=0)
    else:
        return 0

