def are_anagrams(s1, s2):
    """
    Determine if two strings are anagrams of each other.
    """
    return sorted(s1) == sorted(s2)

def minimum_swaps_to_anagram(s1, s2):
    """
    Finds the minimum number of swaps required to turn s1 into s2, given that s1 and s2 are anagrams.
    """
    if not are_anagrams(s1, s2):
        raise ValueError("Strings are not anagrams")

    if s1 == s2:
        return 0

    n = len(s1)
    s1 = list(s1)
    s2 = list(s2)
    swaps = 0

    for i in range(n):
        if s1[i] != s2[i]:
            swap_idx = s1.index(s2[i], i)
            s1[i], s1[swap_idx] = s1[swap_idx], s1[i]
            swaps += 1

    return swaps

