def largest_or_smallest_negative(numbers):
    """
    Returns the largest number in the list if there are no negative numbers.
    If the list contains any negative numbers, returns the smallest negative number instead.
    If the list is empty or has no negative numbers, returns None.
    """
    if not numbers:
        return None

    smallest_negative = None
    largest_number = None

    for num in numbers:
        if num < 0:
            if smallest_negative is None or num < smallest_negative:
                smallest_negative = num
        else:
            if largest_number is None or num > largest_number:
                largest_number = num

    if smallest_negative is not None:
        return smallest_negative
    return largest_number

