def find_median(arr):
    """
    Returns the median of the input list of integers.
    """
    arr_sorted = sorted(arr)
    n = len(arr_sorted)

    if n % 2 == 1:
        return arr_sorted[n // 2]
    else:
        return (arr_sorted[n // 2 - 1] + arr_sorted[n // 2]) / 2

