def even_prime_fibonacci(n):
    """
    Generates a list of even prime integers alongside their respective Fibonacci index, which are below 'n'.
    Returns the list and the sum of these even primes.
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    fib_sequence = [0, 1]
    while True:
        next_fib = fib_sequence[-1] + fib_sequence[-2]
        if next_fib >= n:
            break
        fib_sequence.append(next_fib)

    even_prime_fibs = [(i, fib) for i, fib in enumerate(fib_sequence) if fib < n and fib % 2 == 0 and is_prime(fib)]
    sum_even_primes = sum(fib for _, fib in even_prime_fibs)

    return even_prime_fibs, sum_even_primes

