def fibonacci_reverse(n):
    """
    Prints the first n Fibonacci numbers in reverse order if n is a prime number.
    Returns an error message if n is not a prime number or not a positive integer.
    """
    if not isinstance(n, int) or n <= 0:
        return "Input must be a positive integer."

    if not is_prime(n):
        return f"{n} is not a prime number."

    fib_sequence = [0, 1]
    for _ in range(2, n):
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])

    return fib_sequence[::-1]

