def is_prime(n):
    """
    Checks if a number n is a prime number.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def filter_non_primes(numbers):
    """
    Filters out the prime numbers from a list of numbers.
    """
    return [num for num in numbers if not is_prime(num)]

def average_of_non_primes(numbers):
    """
    Computes the average of non-prime numbers in a list.
    """
    non_prime_numbers = filter_non_primes(numbers)
    if not non_prime_numbers:
        return 0
    return sum(non_prime_numbers) / len(non_prime_numbers)

def are_anagrams(str1, str2):
    """
    Returns True if str1 and str2 are anagrams of each other, considering spaces and special characters.
    If either of the strings is empty or contains only spaces, returns False.
    Function is case-sensitive.
    """
    def clean_string(s):
        # Filter out spaces and special characters and return the character counts
        char_count = {}
        for char in s:
            if char.isalnum():
                char_count[char] = char_count.get(char, 0) + 1
        return char_count

    # Remove leading and trailing whitespace to check if the strings are empty or contain only spaces
    if not str1.strip() or not str2.strip():
        return False

    return clean_string(str1) == clean_string(str2)

