def is_rotation(s1, s2):
    """
    Checks if one string is a rotation of another, ignoring case and non-alphanumeric characters.
    """
    def sanitize_string(s):
        return ''.join(c.lower() for c in s if c.isalnum())

    s1 = sanitize_string(s1)
    s2 = sanitize_string(s2)

    if len(s1) != len(s2):
        return False

    return s2 in (s1 + s1)

