def find_max_length_custom_case_insensitive_substring(s, custom_alphabet):
    """
    Returns the length of the longest substring in s that consists only of characters
    present in custom_alphabet, ignoring case sensitivity.
    """
    custom_set = set(char.lower() for char in custom_alphabet)
    max_length = 0
    current_length = 0

    for char in s:
        if char.lower() in custom_set:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
        else:
            current_length = 0

    return max_length

def calculate_sum_max_min(lst):
    """
    Returns a tuple containing the sum of all elements,
    the maximum value, and the minimum value in the given list.
    """
    total_sum = 0
    if not lst:
        return (0, None, None)

    max_value = lst[0]
    min_value = lst[0]

    for num in lst:
        total_sum += num
        if num > max_value:
            max_value = num
        if num < min_value:
            min_value = num

    return (total_sum, max_value, min_value)

