import re

def evaluate_expression(expression):
    try:
        # Replace '^' with '**' for exponentiation
        expression = expression.replace('^', '**')

        # Validate the expression to allow only numbers and valid operators
        valid_chars = re.compile(r'^[\d\+\-\*/\^\(\)\. ]*$')
        if not valid_chars.match(expression):
            raise ValueError("Invalid characters in the expression.")

        # Evaluate the expression
        result = eval(expression)

        return result
    except ZeroDivisionError:
        return "Error: Division by zero."
    except ValueError as ve:
        return f"Error: {ve}"
    except Exception:
        return "Error: Invalid expression."

# For demonstration purpose, treating this function like doing I/O.
def text_calculator(input_text):
    return evaluate_expression(input_text)

