def reverse_and_swap_case(s):
    """
    Reverses the input string and swaps the case of all characters.

    :param s: The input string
    :return: A new string where the input is reversed and the case of all characters is swapped
    """
    n = len(s)
    result = [''] * n  # Create a list of the same length as s

    for i in range(n):
        char = s[n - 1 - i]
        if 'a' <= char <= 'z':
            result[i] = chr(ord(char) - 32)  # convert to uppercase
        elif 'A' <= char <= 'Z':
            result[i] = chr(ord(char) + 32)  # convert to lowercase
        else:
            result[i] = char

    return ''.join(result)

