def factorial(n, d):
    """
    Calculates the factorial of each integer from 1 to n, skipping the calculation for
    any integer that, when divided by d, does not leave a remainder.
    Returns a dictionary with integers and their respective factorial values.
    """
    # Error handling for invalid inputs
    if not isinstance(n, int) or not isinstance(d, int):
        raise ValueError("Both n and d must be valid integers.")
    if n < 1 or d < 1:
        raise ValueError("Both n and d must be positive integers.")

    def calculate_factorial(num):
        """Helper function to calculate factorial of a given number."""
        factorial = 1
        for i in range(1, num + 1):
            factorial *= i
        return factorial

    result = {}
    for i in range(1, n + 1):
        if i % d != 0:
            result[i] = calculate_factorial(i)

    return result

