def is_hamiltonian_circuit(graph):
    num_nodes = len(graph)
    path = [-1] * num_nodes
    path[0] = 0

    def is_valid(vertex, pos):
        # Check if this vertex is an adjacent vertex of the previously added vertex.
        if graph[path[pos - 1]][vertex] == 0:
            return False
        # Check if the vertex has already been included.
        if vertex in path:
            return False
        return True

    def hamiltonian_circuit(pos):
        # Base case: All vertices are included in the path
        if pos == num_nodes:
            # And if there is an edge from the last included vertex to the first vertex
            return graph[path[pos - 1]][path[0]] == 1

        # Try different vertices as the next candidate in the Hamiltonian Circuit.
        for vertex in range(1, num_nodes):
            if is_valid(vertex, pos):
                path[pos] = vertex
                if hamiltonian_circuit(pos + 1):
                    return True
                path[pos] = -1  # Backtrack
        return False

    return hamiltonian_circuit(1)

