def get_odd_index_value(nums, vals):
    """
    Returns the value from nums or vals at the same index if the index is odd.
    Only one item should be returned from a single index where the index is odd.
    """
    for idx in range(len(nums)):
        if idx % 2 != 0:
            return nums[idx]  # or return vals[idx]

    return None  # If no odd index is found

