def evaluate_expression(expression):
    """
    Evaluates a mathematical expression string and returns the result.
    Supports +, -, *, /, and parentheses for operation order.
    Accounts for divide by zero errors.
    """
    try:
        result = eval(expression)
        if isinstance(result, (int, float)):
            return result
        else:
            raise ValueError("Expression did not evaluate to a number")
    except ZeroDivisionError:
        raise ValueError("Division by zero error")
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")

# Helper function to check the validity of characters
def is_valid_expression(expression):
    import re
    pattern = r'^[\d\s\+\-\*/\(\)]+$'
    return re.match(pattern, expression) is not None

# Main wrapper function to include validation
def process_expression(expression):
    if not is_valid_expression(expression):
        raise ValueError("Expression contains invalid characters")
    return evaluate_expression(expression)

