def caesar_cipher_shift_3(input_string):
    """
    Shifts each alphabet character in the input_string by 3 positions in the alphabet, wrapping around if necessary.
    Non-alphabet characters remain unchanged.
    """
    result = []
    for char in input_string:
        if char.isalpha():
            shift = 3
            if char.islower():
                new_char = chr(((ord(char) - ord('a') + shift) % 26) + ord('a'))
            else:
                new_char = chr(((ord(char) - ord('A') + shift) % 26) + ord('A'))
            result.append(new_char)
        else:
            result.append(char)
    return ''.join(result)

