def calculate(expression):
    """
    Evaluates a mathematical expression involving complex numbers and returns the result rounded to 3 decimal places.

    Parameters:
    expression (str): The mathematical expression to evaluate.

    Returns:
    str: The result of the expression rounded to 3 decimal places.
    """
    try:
        result = eval(expression, {"__builtins__": None}, {"complex": complex})
        if isinstance(result, complex):
            result_str = f"{result.real:.3f}{'+' if result.imag >= 0 else ''}{result.imag:.3f}j"
        else:
            result_str = f"{result:.3f}"
        return result_str
    except Exception as e:
        return str(e)

