def words_binary_representation(words, longest_word_length):
    """
    Returns a list of 0s and 1s for each word in the input words list.
    1 indicates the start of a word and 0 for every following word position up to the length specified.

    :param words: List of words
    :param longest_word_length: Length of the longest word

    :return: List of binary representations
    """
    result = []
    for word in words:
        for i in range(longest_word_length):
            if i == 0:
                result.append(1)
            else:
                result.append(0)
    return result

