def is_prime(num):
    """
    Check if a given number is prime.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_desc_array(n):
    """
    Returns an array of size n, where the elements are prime numbers in descending order.
    """
    primes = []
    current_num = 2
    # Find primes until we have n primes in the list
    while len(primes) < n:
        if is_prime(current_num):
            primes.append(current_num)
        current_num += 1
    return sorted(primes, reverse=True)

