def generate_strings(n):
    """
    Generates all possible strings of length n using the characters '0', '1', and '?'.
    """
    if n == 0:
        return ['']

    shorter_strings = generate_strings(n - 1)
    result = []

    for string in shorter_strings:
        for char in '01?':
            result.append(string + char)

    return result

