def longest_common_subsequence(s1, s2):
    """
    Finds the longest common subsequence of two strings consisting of only alphabetical characters.
    """
    def is_alpha(char):
        return char.isalpha()

    # Filter only alphabetical characters
    s1_alpha = ''.join(filter(is_alpha, s1))
    s2_alpha = ''.join(filter(is_alpha, s2))

    m, n = len(s1_alpha), len(s2_alpha)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Building the DP table
    for i in range(m):
        for j in range(n):
            if s1_alpha[i] == s2_alpha[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    # Reconstructing the longest common subsequence from the DP table
    lcs = []
    while m > 0 and n > 0:
        if dp[m][n] == dp[m-1][n]:
            m -= 1
        elif dp[m][n] == dp[m][n-1]:
            n -= 1
        else:
            lcs.append(s1_alpha[m-1])
            m -= 1
            n -= 1

    return ''.join(reversed(lcs))

