def count_pattern_occurrences(text, pattern):
    """
    Returns the number of times the pattern appears in the text, including overlapping occurrences.
    """
    if not text or not pattern:
        return 0

    count = 0
    len_text = len(text)
    len_pattern = len(pattern)

    for i in range(len_text - len_pattern + 1):
        if text[i:i + len_pattern] == pattern:
            count += 1

    return count

