def remove_duplicates_sorted(lst):
    """
    Takes a sorted list and returns a new list with duplicate elements removed,
    maintaining the original sorted order.
    """
    if not lst:
        return []

    result = [lst[0]]
    for i in range(1, len(lst)):
        if lst[i] != lst[i - 1]:
            result.append(lst[i])

    return result

