def is_unique_anagram(word1, word2):
    """
    Determines if word2 is an anagram of word1 and has no repeated characters with a unique arrangement.
    """
    # Check if both words have the same length
    if len(word1) != len(word2):
        return False

    # Check if both words have unique characters
    if len(set(word1)) != len(word1) or len(set(word2)) != len(word2):
        return False

    # Check if word2 is an anagram of word1
    return sorted(word1) == sorted(word2)

