def char_frequency(text):
    """
    Returns a dictionary with the frequency of each character in the text.

    Args:
    text (str): The input string.

    Returns:
    dict: A dictionary with characters as keys and their frequencies as values.
    """
    frequency = {}
    for char in text:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency

