def to_alternating_case(s):
    """
    Transforms the input string so that every even index character is in uppercase
    and every odd index character is in lowercase using ASCII value manipulation.
    """
    result = []
    for i, char in enumerate(s):
        if 'A' <= char <= 'Z' or 'a' <= char <= 'z':  # only transform alphabetic characters
            if i % 2 == 0:
                # convert to uppercase
                if 'a' <= char <= 'z':
                    result.append(chr(ord(char) - ord('a') + ord('A')))
                else:
                    result.append(char)
            else:
                # convert to lowercase
                if 'A' <= char <= 'Z':
                    result.append(chr(ord(char) - ord('A') + ord('a')))
                else:
                    result.append(char)
        else:
            result.append(char)
    return ''.join(result)

