def convert_list_to_nested_dict(lst):
    def build_nested_dict(items):
        if not items:
            return None
        head, *tail = items
        if not tail:
            return head
        return {head: build_nested_dict(tail)}

    numbers = [x for x in lst if isinstance(x, (int, float))]
    words = [x for x in lst if isinstance(x, str) and x.isalpha()]

    nested_numbers = build_nested_dict(numbers)
    nested_words = build_nested_dict(words)

    return nested_numbers, nested_words

