def swap_first_last(lst):
    """
    Swaps the first and last elements of the list.

    If the list is empty or has only one element, no swap is needed.
    """
    if len(lst) == 0:
        return "List is empty, no swap needed."
    elif len(lst) == 1:
        return "Only one element in the list, no swap needed."
    else:
        lst[0], lst[-1] = lst[-1], lst[0]
        return lst

