def sort_and_classify_tuple(tup):
    """
    Sorts the elements within a tuple alphabetically in reverse order and classifies them as vowels or consonants.
    """
    vowels = {'a', 'e', 'i', 'o', 'u'}

    try:
        # Validate the tuple to ensure all elements are alphabets
        for item in tup:
            if not item.isalpha():
                raise ValueError(f"The tuple contains non-alphabetical characters: {item}")

        # Sort the tuple elements alphabetically in reverse order
        sorted_tup = tuple(sorted(tup, reverse=True, key=lambda x: x.lower()))

        # Classify them as vowels or consonants
        classification = {item: ('vowel' if item.lower() in vowels else 'consonant') for item in sorted_tup}

        return sorted_tup, classification

    except Exception as e:
        return str(e)

