def count_words_with_vowels(filename):
    """
    Reads a text file and returns the total number of words that contain at least one vowel.
    """
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    word_count = 0

    with open(filename, 'r') as file:
        for line in file:
            words = line.split()
            for word in words:
                if any(char in vowels for char in word):
                    word_count += 1

    return word_count

