def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_factors(n):
    factors = []
    i = 2
    while i * i <= n:
        while (n % i) == 0:
            factors.append(i)
            n //= i
        i += 1
    if n > 1:
        factors.append(n)
    return factors

def is_almost_prime(n):
    factors = prime_factors(n)
    prime_count = 0

    # Count unique primes
    unique_primes = set(factors)
    for prime in unique_primes:
        if is_prime(prime):
            prime_count += 1

    return prime_count == 2

