def count_with_twist(n):
    """
    Counts from 0 to n, outputs only numbers that are divisible by 3 and sum of their digits is also divisible by 3.

    :param n: The upper limit number (inclusive).
    :return: A list of numbers fulfilling the criteria.
    """
    def sum_of_digits(num):
        return sum(int(digit) for digit in str(num))

    result = []
    for number in range(n + 1):
        if number % 3 == 0 and sum_of_digits(number) % 3 == 0:
            result.append(number)

    return result

