def count_subsets_with_sum(nums, target):
    """
    Returns the count of subsets whose sum is equal to the target value.
    Uses recursion and memoization for efficiency.
    """
    memo = {}

    def recurse(i, current_sum):
        if i == len(nums):
            return 1 if current_sum == target else 0
        if (i, current_sum) in memo:
            return memo[(i, current_sum)]

        # include nums[i] in the subset
        include = recurse(i + 1, current_sum + nums[i])
        # exclude nums[i] from the subset
        exclude = recurse(i + 1, current_sum)

        memo[(i, current_sum)] = include + exclude
        return memo[(i, current_sum)]

    return recurse(0, 0)

