def recursive_search(lst, element, index=0, count=0, first_index=-1):
    """
    Recursively searches for an element in the list.

    Parameters:
    - lst: List in which to search for the element.
    - element: Element to search for.
    - index: Current index in recursion (default is 0).
    - count: Current count of occurrences found (default is 0).
    - first_index: Index of the first occurrence of element (default is -1).

    Returns:
    - A tuple (index of first occurrence, total count of occurrences).
      If the element is not found, the index of first occurrence should be -1.
    """
    if index == len(lst):
        return (first_index, count)

    if lst[index] == element:
        count += 1
        if first_index == -1:
            first_index = index

    return recursive_search(lst, element, index + 1, count, first_index)

