import json

def is_polygon_or_multipolygon(geometry):
    """
    Checks if the geometry type is either Polygon or MultiPolygon.
    """
    return geometry.get('type') in ['Polygon', 'MultiPolygon']

def validate_geojson(geojson_data):
    """
    Validates that the GeoJSON file is a valid feature collection for "Riverdale".
    Each feature must contain a valid Polygon or MultiPolygon geometry.
    """
    try:
        data = json.loads(geojson_data) if isinstance(geojson_data, str) else geojson_data
        if data.get('type') != 'FeatureCollection':
            return False

        features = data.get('features', [])
        if not features or not isinstance(features, list):
            return False

        for feature in features:
            geometry = feature.get('geometry')
            if not geometry or not is_polygon_or_multipolygon(geometry):
                return False

        return True
    except (json.JSONDecodeError, TypeError):
        return False

