def remove_value(data, value_to_remove):
    """
    Removes all occurrences of a specified value from a nested dictionary.
    It also removes any empty dictionaries or lists that are left behind.

    :param data: The nested dictionary to be processed.
    :param value_to_remove: The value to remove.
    :return: The cleaned dictionary.
    """

    if isinstance(data, dict):
        keys_to_remove = []
        for key, val in data.items():
            cleaned_val = remove_value(val, value_to_remove)
            if cleaned_val is None:
                keys_to_remove.append(key)
            else:
                data[key] = cleaned_val

        for key in keys_to_remove:
            del data[key]

        return data if data else None

    elif isinstance(data, list):
        cleaned_list = [remove_value(item, value_to_remove) for item in data]
        cleaned_list = [item for item in cleaned_list if item is not None]

        return cleaned_list if cleaned_list else None

    else:
        return None if data == value_to_remove else data

