def count_uppercase(input_data):
    """
    This function takes a single character or a string as input and returns:
    - True if the input is a single uppercase character.
    - False if the input is a single non-uppercase character.
    - The count of uppercase characters if the input is a string with multiple characters.

    Args:
    input_data (str): A single character or a string.

    Returns:
    bool or int: True/False for single character input, or the count of uppercase letters for string input.
    """
    if len(input_data) == 1:
        return input_data.isupper()
    elif len(input_data) > 1:
        return sum(1 for char in input_data if char.isupper())
    else:
        raise ValueError("Input should be a non-empty string.")

