def char_frequency(text):
    """
    Returns a dictionary with the occurrence rate of each unique character in the text.
    """
    frequency_dict = {}
    for char in text:
        if char in frequency_dict:
            frequency_dict[char] += 1
        else:
            frequency_dict[char] = 1
    return frequency_dict

