def generate_binary_strings(n):
    """
    Returns a list of all binary strings of length n.
    """
    if n <= 0:
        return []

    result = []

    def generate(current):
        if len(current) == n:
            result.append(current)
        else:
            generate(current + '0')
            generate(current + '1')

    generate('')
    return result

