def bubble_sort(words):
    """
    Sorts a list of words in alphabetical order using the bubble sort algorithm.
    """
    n = len(words)
    for i in range(n):
        for j in range(0, n-i-1):
            if words[j] > words[j+1]:
                words[j], words[j+1] = words[j+1], words[j]
    return words

