def is_prime(n, divisor = None):
    """
    Recursive function to check if a number is prime.
    """
    if n <= 1:
        return False
    if divisor is None:
        divisor = n - 1
    if divisor == 1:
        return True
    if n % divisor == 0:
        return False
    return is_prime(n, divisor - 1)

def adjust_element(arr):
    """
    Adjust the element at index 4: multiply by 2 if it's prime, add 1 otherwise.
    """
    if len(arr) < 6:
        raise ValueError("Array must have at least 6 elements")

    if is_prime(arr[4]):
        arr[4] *= 2
    else:
        arr[4] += 1

    return arr

