def deep_reverse(data):
    """
    Deeply reverses the input data, including any nested lists, tuples, and sets.
    """
    if isinstance(data, list):
        return [deep_reverse(item) for item in reversed(data)]
    elif isinstance(data, tuple):
        return tuple(deep_reverse(list(data)))
    elif isinstance(data, set):
        return {deep_reverse(item) for item in data}
    else:
        return data

