def wrap_text(text, width):
    """
    Wraps the input text into lines of specified width.

    :param text: The input string to be wrapped.
    :param width: The width of each line.
    :return: List of lines within the specified width.
    """
    if width <= 0:
        raise ValueError("Width must be a positive integer")

    result = []
    words = text.split()
    current_line = ''

    for word in words:
        while len(word) > width:  # Handle words longer than the width
            if len(current_line) > 0:
                result.append(current_line)
                current_line = ''
            result.append(word[:width])
            word = word[width:]

        if len(current_line) + len(word) + 1 <= width:
            if current_line:
                current_line += ' ' + word
            else:
                current_line = word
        else:
            if current_line:
                result.append(current_line)
            current_line = word

    if current_line:
        result.append(current_line)

    return result

