def swap_values(variable1, variable2):
    """
    Swaps the values of two variables and returns the swapped values along with their original data types.
    """

    # Determine the original data types
    type_var1 = type(variable1)
    type_var2 = type(variable2)

    # Handle the case where variables are stored as dictionaries
    if isinstance(variable1, dict) and isinstance(variable2, dict):
        variable1, variable2 = variable2, variable1
    # Handle the case where variables are stored as lists
    elif isinstance(variable1, list) and isinstance(variable2, list):
        variable1, variable2 = variable2, variable1
    # Handle the case where variables are stored as tuples
    elif isinstance(variable1, tuple) and isinstance(variable2, tuple):
        variable1, variable2 = variable2, variable1
    # Handle complex numbers and strings
    elif isinstance(variable1, complex) or isinstance(variable2, str):
        variable1, variable2 = variable2, variable1
    else:
        variable1, variable2 = variable2, variable1

    return (variable1, variable2), (type_var1, type_var2)

