def edit_distance(s1, s2):
    """
    Returns the minimum number of operations required to edit s1 to become s2.
    Operations allowed: insert a character, remove a character, replace a character.
    """
    m, n = len(s1), len(s2)

    # Create a 2D array to store the minimum edit distance of substrings
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the dp array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j    # If s1 is empty, insert all characters of s2
            elif j == 0:
                dp[i][j] = i    # If s2 is empty, remove all characters of s1
            elif s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]  # Characters match, no operation required
            else:
                dp[i][j] = 1 + min(dp[i-1][j],    # Remove
                                   dp[i][j-1],    # Insert
                                   dp[i-1][j-1])  # Replace

    return dp[m][n]

