def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def is_palindrome(n):
    return str(n) == str(n)[::-1]

def fibonacci_primes_palindromes():
    fibs = [0, 1]
    primes = []
    while len(primes) < 10:
        next_fib = fibs[-1] + fibs[-2]
        fibs.append(next_fib)
        if is_prime(next_fib):
            primes.append(next_fib)

    result = {prime: is_palindrome(prime) for prime in primes[:10]}
    return result

