def count_letters(input_string):
    """
    Counts the number of alphabetic characters in the input string
    and returns a dictionary with each letter's count.
    """
    letter_count = {}
    for char in input_string:
        if char.isalpha():
            char = char.lower()
            if char in letter_count:
                letter_count[char] += 1
            else:
                letter_count[char] = 1
    return letter_count

