from functools import reduce
import operator

def flatten_and_multiply(nested_list):
    """
    Flattens a nested list and calculates the product of all integers.
    """
    def flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flattened_list = list(flatten(nested_list))
    product = reduce(operator.mul, flattened_list, 1)

    return flattened_list, product

