def find_second_maximum(arr):
    """
    Finds the second maximum element in the given array.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements")

    max_val = float('-inf')
    second_max = float('-inf')

    for number in arr:
        if number > max_val:
            second_max = max_val
            max_val = number
        elif number > second_max and number != max_val:
            second_max = number

    if second_max == float('-inf'):
        raise ValueError("Array does not contain a second maximum element")

    return second_max

