def is_anagram(s1, s2):
    """
    Check if two strings s1 and s2 are anagrams, including Unicode characters.
    """
    # Remove any white spaces and convert to lower case
    s1 = ''.join(s1.split()).lower()
    s2 = ''.join(s2.split()).lower()

    # Sort both the strings and compare
    return sorted(s1) == sorted(s2)

def interactive_mode():
    print("Enter pairs of strings to check if they are anagrams (Type 'exit' to quit):")
    while True:
        pair = input("Enter two strings separated by a comma: ")
        if pair.lower() == 'exit':
            break
        s1, s2 = map(str.strip, pair.split(','))
        if is_anagram(s1, s2):
            print(f'"{s1}" and "{s2}" are anagrams.')
        else:
            print(f'"{s1}" and "{s2}" are not anagrams.')

