import heapq

def mst_kruskal(edges, nodes):
    """
    Compute the Minimum Spanning Tree (MST) using Kruskal's algorithm.

    :param edges: List of tuples (node1, node2, weight)
    :param nodes: Number of nodes in the graph
    :return: List of tuples representing the MST edges
    """
    parent = list(range(nodes))
    rank = [0] * nodes

    def find(node):
        if parent[node] != node:
            parent[node] = find(parent[node])
        return parent[node]

    def union(node1, node2):
        root1 = find(node1)
        root2 = find(node2)
        if root1 != root2:
            if rank[root1] > rank[root2]:
                parent[root2] = root1
            elif rank[root1] < rank[root2]:
                parent[root1] = root2
            else:
                parent[root2] = root1
                rank[root1] += 1

    edges = sorted(edges, key=lambda edge: edge[2])
    mst = []

    for edge in edges:
        node1, node2, weight = edge
        if find(node1) != find(node2):
            union(node1, node2)
            mst.append(edge)

    return mst

