def extract_ingredients(recipe):
    """
    Parses ingredients from a recipe and returns a dictionary where keys are ingredients and values are quantities.
    """
    ingredients = {}
    for line in recipe.split('\n'):
        if line.strip() and ':' in line:
            item, qty = map(str.strip, line.split(':'))
            ingredients[item] = qty
    return ingredients

def generate_shopping_list(recipe_name, database):
    """
    Generates a shopping list based on a recipe name and a recipe database.
    """
    if recipe_name not in database:
        return "Recipe not found."

    recipe = database[recipe_name]
    ingredients = extract_ingredients(recipe)
    shopping_list = "\n".join([f"{item}: {qty}" for item, qty in ingredients.items()])
    return shopping_list

