def second_largest_number(lst):
    """
    Returns the second largest number in the given list without using
    any built-in sorting or max functions.
    """
    if len(lst) < 2:
        return None  # Not enough elements to determine the second largest

    first = second = float('-inf')
    for number in lst:
        if number > first:
            second = first
            first = number
        elif number > second and number != first:
            second = number
    return second if second != float('-inf') else None

