def reverse_vowels(s):
    """
    Returns a string with the vowels reversed.

    :param s: input string
    :return: string with vowels reversed
    """
    vowels = "aeiouAEIOU"
    s = list(s)
    i, j = 0, len(s) - 1

    while i < j:
        if s[i] in vowels and s[j] in vowels:
            s[i], s[j] = s[j], s[i]
            i += 1
            j -= 1
        if s[i] not in vowels:
            i += 1
        if s[j] not in vowels:
            j -= 1

    return ''.join(s)

