def is_prime(n):
    """
    Determines if the input number n is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def check_prime():
    """
    Checks if a user-input number is prime and prints the result.
    """
    n = int(input("Enter a positive integer: "))
    if is_prime(n):
        print("The number is prime.")
    else:
        print("The number is not prime.")

