def min_window(s, t):
    """
    Finds the smallest window in string `s` that contains all characters of string `t` with frequency.
    """
    from collections import Counter

    if not s or not t:
        return ""

    dict_t = Counter(t)
    required = len(dict_t)
    l, r = 0, 0
    formed = 0
    window_counts = {}
    min_len = float("inf")
    min_window = (0, 0)

    while r < len(s):
        character = s[r]
        window_counts[character] = window_counts.get(character, 0) + 1

        if character in dict_t and window_counts[character] == dict_t[character]:
            formed += 1

        while l <= r and formed == required:
            character = s[l]

            if r - l + 1 < min_len:
                min_len = r - l + 1
                min_window = (l, r)

            window_counts[character] -= 1
            if character in dict_t and window_counts[character] < dict_t[character]:
                formed -= 1

            l += 1

        r += 1

    if min_len == float("inf"):
        return ""
    else:
        return s[min_window[0]: min_window[1] + 1]

