def list_to_tuple(data):
    """
    Transmutes a list into a tuple. Handles nested lists and tuples, converting them to nested tuples.

    Parameters:
    data (list): The input list to be converted.

    Returns:
    tuple: The converted tuple.

    Raises:
    TypeError: If the input is not a list or tuple.
    """
    if not isinstance(data, (list, tuple)):
        raise TypeError("Input must be a list or a tuple")

    result = []
    for item in data:
        if isinstance(item, (list, tuple)):
            result.append(list_to_tuple(item))
        else:
            result.append(item)

    return tuple(result)

