def sort_strings_descending(strings):
    """
    Sort the given list of strings alphabetically in descending order.
    The sorted list shouldn't include strings with duplicate characters.
    """
    def has_unique_characters(s):
        return len(s) == len(set(s))

    unique_strings = [s for s in strings if has_unique_characters(s)]
    sorted_strings = sorted(unique_strings, reverse=True)

    return sorted_strings

def distinct_elements_with_counts(arr):
    """
    Returns a dictionary with distinct elements of the array as keys and their counts as values.
    """
    element_count = {}
    for element in arr:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1
    return element_count

