def closest_midpoint_to_origin(points):
    """
    Given a list of point coordinates, find the pair of points whose midpoint lies closest to the origin
    and return their midpoint coordinates rounded to 2 decimal points.
    :param points: List of tuples, where each tuple (x, y) represents a point's coordinates.
    :return: Tuple representing the coordinates of the midpoint rounded to 2 decimal points.
    """
    import math

    def midpoint(p1, p2):
        return ((p1[0] + p2[0]) / 2, (p1[1] + p2[1]) / 2)

    def distance_to_origin(point):
        return math.sqrt(point[0]**2 + point[1]**2)

    if not points or len(points) < 2:
        raise ValueError("At least two points are required")

    min_distance = float('inf')
    closest_midpoint = None

    for i in range(len(points)):
        for j in range(i + 1, len(points)):
            p1, p2 = points[i], points[j]
            mid = midpoint(p1, p2)
            dist = distance_to_origin(mid)
            if dist < min_distance:
                min_distance = dist
                closest_midpoint = mid

    return (round(closest_midpoint[0], 2), round(closest_midpoint[1], 2))

