def add_with_type_check(a, b):
    """
    Returns the sum of a and b with type checking.

    If the sum is a whole number, it returns as an integer.
    If the sum is not a whole number, it returns as a float.
    If a or b are not numbers, it raises a TypeError.
    """
    if not (isinstance(a, (int, float)) and isinstance(b, (int, float))):
        raise TypeError("Both a and b must be numbers.")

    total = a + b
    if total.is_integer():
        return int(total)
    else:
        return total

def is_balanced(s):
    """
    Returns True if the string of parentheses is balanced, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0

