def first_recurring_char(text):
    """
    Identifies the first recurring alphabetic character in the text string.
    Returns the first recurring alphabetic character or None if there is none.
    """
    seen = set()
    for char in text:
        if char.isalpha():
            if char in seen:
                return char
            seen.add(char)
    return None

def to_uppercase(strings):
    """
    Converts each item in a given list of strings to uppercase.
    This function ensures a time complexity of O(n) by directly manipulating ASCII values.
    Note: This implementation assumes the input characters are only in the range [a-z] and [A-Z].
    """
    result = []
    for string in strings:
        new_string = []
        for ch in string:
            if 'a' <= ch <= 'z':
                new_string.append(chr(ord(ch) - 32))
            else:
                new_string.append(ch)
        result.append(''.join(new_string))
    return result

