def find_value_in_dict(d, value_to_find, key_name=None):
    """
    Checks for the presence of a specific value in a dictionary.
    If found, returns the key associated with it.

    Parameters:
        d (dict): The dictionary to search.
        value_to_find: The value to search for.
        key_name (str, optional): The name to use for the key in the return message.

    Returns:
        str: The key associated with the found value, or a message if not found.
    """
    if not isinstance(d, dict):
        raise TypeError("Provided input is not a dictionary")

    try:
        if isinstance(value_to_find, dict):
            raise TypeError("Value provided is a dictionary, which cannot be searched as a single value.")
    except TypeError:
        raise TypeError("Provided value is not hashable")

    def search_nested_dict(d, value_to_find):
        for k, v in d.items():
            if v == value_to_find:
                return k
            elif isinstance(v, dict):
                nested_result = search_nested_dict(v, value_to_find)
                if nested_result:
                    return k + ' -> ' + nested_result
        return None

    result = search_nested_dict(d, value_to_find)
    if result:
        return f"{key_name or 'Key'}: {result}"
    else:
        return "Value not found"

