import math

def compute_factorial(a, b):
    """
    Returns the factorial of a, and if b is 0, returns the square root of the factorial.
    """
    try:
        if not isinstance(a, int) or not isinstance(b, int):
            raise TypeError("Both a and b must be integers.")
        if a < 0:
            raise ValueError("a must be a non-negative integer.")

        c = math.factorial(a)
        if b == 0:
            return math.sqrt(c)
        return c
    except (ValueError, TypeError) as e:
        return str(e)

def check_divisibility_by_5(numbers):
    """
    Returns a new list where each number divisible by 5 is replaced by 'Five',
    and numbers not divisible by 5 are kept as they are.
    """
    result = []
    for number in numbers:
        if number % 5 == 0:
            result.append('Five')
        else:
            result.append(number)
    return result

