from typing import List

def is_prime(n: int) -> bool:
    """
    Check if a number is a prime number.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    p = 3
    while p * p <= n:
        if n % p == 0:
            return False
        p += 2
    return True

def product_of_primes_below(n: int) -> int:
    """
    Find the product of all prime numbers below the given positive integer n.
    """
    product = 1
    for i in range(2, n):
        if is_prime(i):
            product *= i
    return product

def find_second_largest(lists):
    def find_second(lst):
        unique_elements = list(set(lst))
        if len(unique_elements) < 2:
            return None
        unique_elements.sort(reverse=True)
        return unique_elements[1]

    return [find_second(lst) for lst in lists]

