def is_safe(board, row, col):
    """
    Check if a queen can be safely placed at board[row][col].
    """
    for i in range(col):
        if board[row][i] == 1:
            return False

    for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
        if board[i][j] == 1:
            return False

    for i, j in zip(range(row, len(board), 1), range(col, -1, -1)):
        if board[i][j] == 1:
            return False

    return True

def solve_n_queens_util(board, col, n):
    """
    Utilizes backtracking to solve the N-queens problem.
    """
    if col >= n:
        return True

    for i in range(len(board)):
        if is_safe(board, i, col):
            board[i][col] = 1
            if solve_n_queens_util(board, col + 1, n):
                return True
            board[i][col] = 0

    return False

def solve_n_queens(x, y, n):
    """
    Solves the N-queens problem for a given grid size (x, y) and number of queens (n).
    Returns a list of lists representing the queen positions on the grid.
    """
    if n > x or n > y:
        return "Not possible to place more queens than rows or columns"

    board = [[0] * y for _ in range(x)]

    if not solve_n_queens_util(board, 0, n):
        return "No solution exists"

    return board

import json

def extract_kv_pairs(json_str):
    """
    Extract top-level key-value pairs from a JSON string.
    For arrays, return their length as the value.
    """
    data = json.loads(json_str)
    result = {}

    for key, value in data.items():
        if isinstance(value, list):
            result[key] = len(value)
        else:
            result[key] = value

    return result

