def compute_sum(arr):
    """
    Computes the sum of an array of integers.
    Ensures the input is a list and all elements are integers.

    :param arr: list of integers
    :return: sum of integers in arr
    """
    if not isinstance(arr, list):
        raise ValueError("Input should be a list")
    for element in arr:
        if not isinstance(element, int):
            raise ValueError("All elements in the list should be integers")

    total = 0
    for number in arr:
        total += number

    return total

