def intersection_of_sublists(list_of_lists):
    """
    Returns the intersection of all sublists.
    """
    if not list_of_lists:
        return []

    # Initialize intersection result with the first sublist converted to a set
    intersection_result = set(list_of_lists[0])

    # Intersect with each subsequent sublist
    for lst in list_of_lists[1:]:
        intersection_result.intersection_update(lst)

    # Return the result as a list
    return list(intersection_result)

