def extract_parentheses_values(s):
    """
    Extracts values between parentheses, including nested ones,
    from the provided string.
    """
    stack = []
    result = []
    current = ''

    for char in s:
        if char == '(':
            if stack:
                stack.append(current)
                current = ''
            stack.append(char)
        elif char == ')':
            if stack:
                result.append(current)
                stack.pop()
                if stack and stack[-1] != '(':
                    current = stack.pop() + '(' + current + ')'
                else:
                    current = ''
            else:
                continue
        elif stack:
            current += char

    return result

