def is_one_edit_distance(s: str, t: str) -> bool:
    """
    Returns True if strings s and t are one edit distance apart, else False.
    An edit is defined as inserting, deleting, or replacing a character.
    """
    len_s = len(s)
    len_t = len(t)

    if abs(len_s - len_t) > 1:
        return False

    if len_s > len_t:  # Make s the shorter string
        return is_one_edit_distance(t, s)

    # Now len_s <= len_t
    for i in range(len_s):
        if s[i] != t[i]:
            if len_s == len_t:
                return s[i+1:] == t[i+1:]  # Replace
            else:
                return s[i:] == t[i+1:]    # Insert/Delete

    return len_s + 1 == len_t  # Check if the additional character is at the end

def longest_non_repeated_substring(s):
    """
    Returns the longest substring without repeating characters.
    """
    char_map = {}
    left = 0
    longest = 0
    start = 0

    for right, char in enumerate(s):
        if char in char_map and char_map[char] >= left:
            left = char_map[char] + 1
        char_map[char] = right
        if right - left + 1 > longest:
            longest = right - left + 1
            start = left

    return s[start:start + longest]

