def transformer(arg):
    """
    Returns a tuple where the first element is the argument multiplied by 2,
    and the second element is the argument squared if the argument is a negative
    integer whose absolute value does not exceed 1000. Otherwise, returns None.
    """
    if isinstance(arg, int) and arg < 0 and abs(arg) <= 1000:
        return (arg * 2, arg ** 2)
    return None

def remove_recurrent_characters(s):
    """
    Removes all recurring sequential characters from the input string.
    """
    if not s:
        return ""

    result = [s[0]]
    for char in s[1:]:
        if char != result[-1]:
            result.append(char)
    return ''.join(result)

