def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def factorial_of_prime(n):
    """
    Returns the factorial of a prime number n.
    If n is not prime, raises a ValueError.
    """
    if not is_prime(n):
        raise ValueError("Input must be a prime number")

    factorial = 1
    for i in range(2, n + 1):
        factorial *= i
    return factorial

