import random

def generate_sequence(length):
    """
    Generates a sequence of the provided length using the characters 'a', 'c', 'g', and 't'
    without repeating any consecutive "tridental" patterns.
    """
    characters = ['a', 'c', 'g', 't']
    sequence = [random.choice(characters) for _ in range(length)]

    # Ensure that no consecutive tridental patterns are repeated
    for i in range(2, length - 3, 3):
        while sequence[i] == sequence[i+3]:
            sequence[i+3] = random.choice([ch for ch in characters if ch != sequence[i]])

    return ''.join(sequence)

def generate_three_sequences():
    sequences = []
    for _ in range(3):
        sequences.append(generate_sequence(10))
    return sequences

