import random
import string

def generate_random_password(length=12):
    """
    Generate a random password of at least 'length' characters including:
    - At least 2 capital letters
    - At least 2 numbers
    - At least 2 special characters
    - No consecutive repeating characters
    """
    if length < 12:
        raise ValueError("Password length must be at least 12 characters")

    while True:
        password_characters = [
            random.choice(string.ascii_uppercase) for _ in range(2)
        ] + [
            random.choice(string.digits) for _ in range(2)
        ] + [
            random.choice(string.punctuation) for _ in range(2)
         ]

        remaining_length = length - len(password_characters)
        password_characters += [
            random.choice(string.ascii_letters + string.digits + string.punctuation) for _ in range(remaining_length)
        ]

        random.shuffle(password_characters)

        password = ''.join(password_characters)

        if has_no_consecutive_repeating_characters(password):
            return password

def has_no_consecutive_repeating_characters(password):
    """
    Verify that the password has no consecutive repeating characters.
    """
    for i in range(len(password) - 1):
        if password[i] == password[i + 1]:
            return False
    return True

def construct_hierarchic_dict(keys, default_value):
    """
    Constructs a hierarchic dictionary from a list of keys and a default value.

    Parameters:
    keys (list): A list of keys to create the hierarchy.
    default_value (any): The value to assign at the deepest level of the hierarchy.

    Returns:
    dict: A nested dictionary where keys are at each level, leading to the default value.
    """
    result = current_level = {}

    for key in keys[:-1]:
        current_level[key] = {}
        current_level = current_level[key]

    if keys:
        current_level[keys[-1]] = default_value

    return result

