def eliminate_and_sort(arr):
    """
    Eliminates successive identical elements and returns the array sorted in ascending order.
    """
    if not arr:
        return []

    # Eliminate successive identical elements
    reduced_arr = [arr[0]]
    for item in arr[1:]:
        if item != reduced_arr[-1]:
            reduced_arr.append(item)

    # Implementing a simple custom sort (Insertion Sort for demonstrative purposes)
    for i in range(1, len(reduced_arr)):
        key = reduced_arr[i]
        j = i - 1
        while j >= 0 and key < reduced_arr[j]:
            reduced_arr[j + 1] = reduced_arr[j]
            j -= 1
        reduced_arr[j + 1] = key

    return reduced_arr

