def maximal_square(matrix):
    if not matrix or not matrix[0]:
        return 0

    rows = len(matrix)
    cols = len(matrix[0])
    dp = [[0] * cols for _ in range(rows)]
    max_square_length = 0

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_square_length = max(max_square_length, dp[i][j])

    return max_square_length ** 2  # area of the largest square

def feedback(score, system):
    """
    Returns feedback based on the score and the grading system specified.

    Args:
    score: The score to be evaluated.
    system: The grading system being used ('A-F', 'percentage', 'Pass/Fail').

    Returns:
    str: Feedback message based on the score and the system.
    """
    if system == 'A-F':
        return 'Excellent' if score in ('A', 'A+', 'A-') else (
               'Good' if score in ('B', 'B+', 'B-') else (
               'Average' if score in ('C', 'C+', 'C-') else (
               'Poor' if score in ('D', 'D+') else 'Fail')))
    elif system == 'percentage':
        return 'Excellent' if score >= 90 else (
               'Good' if score >= 75 else (
               'Average' if score >= 50 else 'Poor' if score >= 40 else 'Fail'))
    elif system == 'Pass/Fail':
        return 'Pass' if score == 'Pass' else 'Fail'
    else:
        raise ValueError(f"Unsupported grading system: {system}")

def longest_substring(s: str, k: int) -> int:
    """
    Returns the length of the longest substring that contains k distinct characters.
    """
    if k == 0 or len(s) == 0:
        return 0

    start, max_length = 0, 0
    char_count = {}

    for end in range(len(s)):
        char_count[s[end]] = char_count.get(s[end], 0) + 1

        while len(char_count) > k:
            char_count[s[start]] -= 1
            if char_count[s[start]] == 0:
                del char_count[s[start]]
            start += 1

        max_length = max(max_length, end - start + 1)

    return max_length

