def find_max_and_min(lst):
    """
    Returns the maximum and minimum value from the list.
    """
    if not lst:
        return None, None

    max_number = lst[0]
    min_number = lst[0]

    for number in lst[1:]:
        if number > max_number:
            max_number = number
        if number < min_number:
            min_number = number

    return max_number, min_number

