def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % i + 2 == 0:
            return False
        i += 6
    return True

def prime_generator():
    """
    Generator function to yield prime numbers one by one.
    """
    n = 2
    while True:
        if is_prime(n):
            yield n
        n += 1

def first_n_primes(n):
    """
    Function to return the first 'n' prime numbers.
    """
    gen = prime_generator()
    primes = []
    for _ in range(n):
        primes.append(next(gen))
    return primes

