def extract_tuples(nested_dict):
    """
    Extracts a list of tuples from a nested dictionary.
    The result is sorted by dictionary keys.
    """
    extracted = []

    def recursive_extraction(d):
        for key, value in d.items():
            if isinstance(value, dict):
                recursive_extraction(value)
            else:
                extracted.append((key, value))

    recursive_extraction(nested_dict)
    return sorted(extracted)

