def search_in_different_pairs(arr_of_pairs, x, y):
    """
    Returns 1 if x and y are found in different pairs, otherwise returns 0.
    """
    x_found = None
    y_found = None

    for pair in arr_of_pairs:
        if x in pair:
            x_found = pair
        if y in pair:
            y_found = pair
        if x_found is not None and y_found is not None:
            break

    if x_found is None or y_found is None:
        return 0

    return 1 if x_found != y_found else 0

def merge_sort(arr):
    """
    Sorts the input array in ascending order using the merge sort algorithm.
    """
    if len(arr) <= 1:
        return arr

    def merge(left, right):
        merged = []
        left_idx, right_idx = 0, 0
        while left_idx < len(left) and right_idx < len(right):
            if left[left_idx] < right[right_idx]:
                merged.append(left[left_idx])
                left_idx += 1
            else:
                merged.append(right[right_idx])
                right_idx += 1

        merged.extend(left[left_idx:])
        merged.extend(right[right_idx:])
        return merged

    mid = len(arr) // 2
    left_half = merge_sort(arr[:mid])
    right_half = merge_sort(arr[mid:])
    return merge(left_half, right_half)

