def alternate_combine(s1, s2):
    """
    Combines two strings by alternating their characters,
    ensuring the combined string has balanced character frequencies from both strings.
    """
    if not s1.isalpha() or not s2.isalpha() or len(s1) != len(s2):
        raise ValueError("Input strings must be alphabetic and of the same length")

    combined = []
    for i in range(len(s1)):
        combined.append(s1[i])
        combined.append(s2[i])

    return ''.join(combined)

