def find_duplicates(arr):
    """
    Returns a list of duplicate values in the given array using recursion.
    """
    def recurse(index, seen, duplicates):
        if index >= len(arr):
            return duplicates

        current_value = arr[index]
        if current_value in seen:
            if current_value not in duplicates:
                duplicates.append(current_value)
        else:
            seen.append(current_value)

        return recurse(index + 1, seen, duplicates)

    return recurse(0, [], [])

