def length_of_lis(sequence):
    """
    Returns the length of the longest strictly increasing subsequence in the given sequence of numbers.
    """
    if not sequence:
        return 0

    n = len(sequence)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

