def minimum_total(triangle):
    """
    Returns the minimum path sum from top to bottom in a given triangle using memoization.
    """
    def helper(row, col, memo):
        if row == len(triangle):
            return 0
        if (row, col) in memo:
            return memo[(row, col)]

        minimum_path_sum = triangle[row][col] + min(helper(row+1, col, memo), helper(row+1, col+1, memo))
        memo[(row, col)] = minimum_path_sum
        return minimum_path_sum

    memo = {}
    return helper(0, 0, memo)

def separate_even_odd(numbers):
    """
    Takes a list of integers and separates them into even and odd numbers.
    Returns two lists: one for even numbers and one for odd numbers.
    """
    evens = []
    odds = []

    for num in numbers:
        if num % 2 == 0:
            evens.append(num)
        else:
            odds.append(num)

    return evens, odds

