def find_unique_triplets(arr):
    """
    Returns a sorted list of sorted unique triplets in `arr` that sum up to zero.
    """
    arr.sort()  # Sorting the list
    n = len(arr)
    triplets = []

    for i in range(n - 2):
        # Avoid duplicate triplets
        if i > 0 and arr[i] == arr[i - 1]:
            continue

        left, right = i + 1, n - 1

        while left < right:
            s = arr[i] + arr[left] + arr[right]

            if s == 0:
                triplets.append([arr[i], arr[left], arr[right]])

                # Avoid duplicate triplets
                while left < right and arr[left] == arr[left + 1]:
                    left += 1
                while left < right and arr[right] == arr[right - 1]:
                    right -= 1

                left += 1
                right -= 1
            elif s < 0:
                left += 1
            else:
                right -= 1

    return triplets

