def find_anagram_pairs(words):
    """
    Returns a list of tuples where each tuple contains a pair of anagram words.
    """
    from collections import defaultdict

    # A dictionary to map sorted word to its anagrams
    anagram_map = defaultdict(list)

    # Group words by their sorted character tuple
    for word in words:
        sorted_word_tuple = tuple(sorted(word))
        anagram_map[sorted_word_tuple].append(word)

    # Collect all anagram pairs from the grouped dictionary
    anagram_pairs = []

    for anagram_group in anagram_map.values():
        if len(anagram_group) > 1:
            for i in range(len(anagram_group)):
                for j in range(i + 1, len(anagram_group)):
                    anagram_pairs.append((anagram_group[i], anagram_group[j]))

    return anagram_pairs

