from functools import reduce

def sum_of_list(numbers):
    """
    Returns the sum of all numbers in the list using a higher-order function.
    """
    return reduce(lambda x, y: x + y, numbers)

def product_of_list(numbers):
    """
    Returns the product of all numbers in the list using a higher-order function.
    """
    return reduce(lambda x, y: x * y, numbers)

def average_of_list(numbers):
    """
    Returns the average of all numbers in the list using higher-order functions.
    """
    total_sum = sum_of_list(numbers)
    return total_sum / len(numbers)

# Explanation:
# - Higher-order functions like `reduce` allow for concise and readable code by abstracting the iterative logic.
# - Using `reduce`, we can implement complex operations like sum and product in a single line, enhancing code clarity.

def sort_descending(arr):
    """
    Sorts a list of integers in descending order.
    """
    return sorted(arr, reverse=True)

def is_strictly_monotonic(arr):
    """
    Checks if a list is strictly monotonic.
    A list is strictly monotonic if each element is either less than or greater than its predecessor.
    """
    if not arr:
        return True

    for i in range(1, len(arr)):
        if arr[i] >= arr[i - 1]:
            return False
    return True

