def reverse_string(s):
    """
    Reverses the input string s without using any built-in functions or additional data structures.
    """
    rev_s = [''] * len(s)  # Create a placeholder list with the same length as s
    n = len(s)

    for i in range(n):
        rev_s[n - 1 - i] = s[i]

    return ''.join(rev_s)

