def largeint_multiply(num1, num2):
    """
    Multiplies two arbitrarily long integers represented as strings and returns the result as a string.
    """
    if num1 == "0" or num2 == "0":
        return "0"

    len1, len2 = len(num1), len(num2)
    result = [0] * (len1 + len2)

    # Reverse the strings to start multiplication from least significant digit
    num1, num2 = num1[::-1], num2[::-1]

    for i in range(len1):
        for j in range(len2):
            result[i + j] += int(num1[i]) * int(num2[j])
            result[i + j + 1] += result[i + j] // 10
            result[i + j] %= 10

    # Remove leading zeros from the result
    while len(result) > 1 and result[-1] == 0:
        result.pop()

    return ''.join(map(str, result[::-1]))

def create_pairs(a, b):
    """
    Takes two lists, a and b, of equal length and returns a list of tuples,
    where each tuple contains the corresponding elements from a and b.
    """
    if len(a) != len(b):
        raise ValueError("Both lists must have the same length")
    return list(zip(a, b))

