def check_order_with_spaces(s1, s2):
    """
    Checks if the characters in s1 appear in the same order in s2 with at least two space characters
    between each character in s2.
    """
    i, j = 0, 0
    n, m = len(s1), len(s2)

    while i < n and j < m:
        if s1[i] == s2[j]:
            i += 1
            if i < n:
                if j + 3 >= m or s2[j + 1] != ' ' or s2[j + 2] != ' ':
                    return False
            j += 3
        else:
            j += 1

    return i == n

