def find_max(arr):
    """
    Returns the maximum element in the array using a recursive algorithm.
    If the array is empty, returns None.
    """
    n = len(arr)

    # Handle empty array
    if n == 0:
        return None

    return _find_max_recursive(arr, n)

def _find_max_recursive(arr, n):
    # Base case: Only one element left
    if n == 1:
        return arr[0]

    # Recursive Case: Find max in the rest of the array
    max_in_rest = _find_max_recursive(arr, n-1)

    # Return the maximum between the last element and maximum of the rest
    return max(arr[n-1], max_in_rest)

