import random

def caesar_cipher_encrypt(text, key=None):
    """
    Encrypts the given text using the Caesar cipher with the provided key.
    If no key is provided, a random key between 1 and 25 is generated.

    :param text: The input text to encrypt.
    :param key: The key to encrypt the text with (1-25).
    :return: A tuple containing the encrypted text and the key used.
    """
    if key is None:
        key = random.randint(1, 25)

    encrypted_text = []

    for char in text:
        if char.isupper():
            encrypted_text.append(chr((ord(char) - ord('A') + key) % 26 + ord('A')))
        elif char.islower():
            encrypted_text.append(chr((ord(char) - ord('a') + key) % 26 + ord('a')))
        else:
            encrypted_text.append(char)

    return ''.join(encrypted_text), key

