def calculate_median(input_tuple):
    """
    This function returns the median value of a tuple containing unique values.
    It does not use built-in sorting functions but relies on a custom comparison function.
    """
    def quickselect(arr, k):
        """
        Quickselect algorithm to find the k-th smallest element.
        """
        if len(arr) == 1:
            return arr[0]

        pivot = arr[len(arr) // 2]

        lows = [el for el in arr if el < pivot]
        highs = [el for el in arr if el > pivot]
        pivots = [el for el in arr if el == pivot]

        if k < len(lows):
            return quickselect(lows, k)
        elif k < len(lows) + len(pivots):
            return pivots[0]
        else:
            return quickselect(highs, k - len(lows) - len(pivots))

    n = len(input_tuple)
    if n % 2 == 1:
        return quickselect(list(input_tuple), n // 2)
    else:
        return (quickselect(list(input_tuple), n // 2 - 1) + quickselect(list(input_tuple), n // 2)) / 2

