def rotate(matrix, rotations):
    def rotate_list(lst, k):
        n = len(lst)
        k = k % n  # To handle cases where k > n
        return lst[-k:] + lst[:-k]

    # Rotate innermost dimension
    for i in range(len(matrix)):
        for j in range(len(matrix[i])):
            matrix[i][j] = rotate_list(matrix[i][j], rotations[2])

    # Rotate middle dimension
    for i in range(len(matrix)):
        matrix[i] = rotate_list(matrix[i], rotations[1])

    # Rotate outermost dimension
    matrix = rotate_list(matrix, rotations[0])

    return matrix

