def generate_permutations(lst):
    if not isinstance(lst, list):
        raise ValueError("Input must be a list")
    if not lst:
        return []

    def _permute(data, start, end, result):
        if start == end:
            result.append(data[:])
        else:
            for i in range(start, end+1):
                data[start], data[i] = data[i], data[start]
                _permute(data, start+1, end, result)
                data[start], data[i] = data[i], data[start]

    result = []
    _permute(lst, 0, len(lst)-1, result)
    return result

def generate_combinations(lst):
    if not isinstance(lst, list):
        raise ValueError("Input must be a list")
    if not lst:
        return []

    def _combine(data, start, end, result, temp_list):
        for i in range(start, end):
            temp_list.append(data[i])
            result.append(temp_list[:])
            _combine(data, i + 1, end, result, temp_list)
            temp_list.pop()

    result = []
    _combine(lst, 0, len(lst), result, [])
    return result

def generate_permutations_or_combinations(lst, mode):
    if mode not in ['permutations', 'combinations']:
        raise ValueError("Mode must be 'permutations' or 'combinations'")

    if mode == 'permutations':
        return generate_permutations(lst)
    else:
        return generate_combinations(lst)

