def move_on_board(dimensions, movements):
    """
    Moves a piece on a board based on the given dimensions and list of movements.
    """
    # Initialize starting position
    x, y = 0, 0
    rows, columns = dimensions

    # Define the movement dictionary
    movement_dict = {'Right': (0, 1), 'Down': (1, 0), 'Left': (0, -1), 'Up': (-1, 0)}

    # Perform movements
    for move in movements:
        if move in movement_dict:
            dx, dy = movement_dict[move]
            x += dx
            y += dy

            # Check if out of bounds
            if x < 0 or x >= rows or y < 0 or y >= columns:
                return "Position out of board"
        else:
            return "Invalid movement"

    return (x, y)

