def find_pairs_with_difference(arr, k):
    """
    Returns a list of pairs (i, j) such that the absolute difference
    | arr[i] - arr[j] | is equal to k.
    """
    pairs = []
    n = len(arr)

    for i in range(n):
        for j in range(i + 1, n):
            if abs(arr[i] - arr[j]) == k:
                pairs.append((arr[i], arr[j]))

    return pairs

