def find_longest_subarray_with_equal_0_1(arr):
    """
    Returns the length of the longest contiguous subarray with equal number of 0 and 1.
    """
    count_map = {}
    max_len = 0
    count = 0

    for i in range(len(arr)):
        count += -1 if arr[i] == 0 else 1

        if count == 0:
            max_len = i + 1

        if count in count_map:
            max_len = max(max_len, i - count_map[count])
        else:
            count_map[count] = i

    return max_len

