def lucas(n):
    """
    Returns the nth term in the Lucas sequence.
    """
    if n == 0:
        return 2
    elif n == 1:
        return 1

    a, b = 2, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

