def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def fibonacci_with_primes(n):
    if n <= 0:
        return []
    sequence = []
    a, b = 0, 1
    count = 0
    while count < n:
        if is_prime(a):
            sequence.append(a)
            count += 1
        a, b = b, a + b
    return sequence

