def power(a, b):
    """
    Returns a to the power of b without using any library functions.
    Handles edge cases for 0^0 and 0 raised to a negative power.
    """
    # Handling edge cases
    if a == 0 and b == 0:
        return 1  # By mathematical convention
    if a == 0 and b < 0:
        raise ValueError("0 cannot be raised to a negative power")

    result = 1
    for _ in range(abs(b)):
        result *= a

    if b < 0:
        result = 1 / result

    return result

