def selection_sort(arr):
    """
    Sorts the list arr using selection sort and returns the sorted list along with the swap count.
    """
    swap_count = 0
    n = len(arr)

    for i in range(n):
        min_index = i
        for j in range(i+1, n):
            if arr[j] < arr[min_index]:
                min_index = j
        if i != min_index:
            arr[i], arr[min_index] = arr[min_index], arr[i]
            swap_count += 1

    return arr, swap_count

def find_median(arr):
    """
    Finds and returns the median of the given list arr.
    """
    sorted_arr, _ = selection_sort(arr.copy())
    n = len(sorted_arr)

    if n % 2 == 1:
        return sorted_arr[n // 2]
    else:
        return (sorted_arr[(n // 2) - 1] + sorted_arr[n // 2]) / 2

