def max_value(collection):
    """
    Identifies and returns the maximum numerical value from a provided collection
    of elements. The collection can contain different types of data, such as
    integers, floating-point numbers, or strings that can be converted to numbers.
    """
    max_val = None
    for item in collection:
        try:
            num = float(item)
            if max_val is None or num > max_val:
                max_val = num
        except (ValueError, TypeError):
            continue
    return max_val

