def invert_factors(nested_tuple, factors):
    """
    Invert the placement of specified numerical factors within a nested tuple.

    Parameters:
    nested_tuple (tuple): The nested tuple structure.
    factors (set): The set of numerical factors to be inverted.

    Returns:
    tuple: The new tuple with the factors inverted.
    """
    def helper(nested):
        if isinstance(nested, tuple):
            return tuple(helper(item) for item in nested)
        elif nested in factors:
            return -nested
        else:
            return nested

    return helper(nested_tuple)

