def first_distinct_char(s):
    """
    Returns the index of the first distinct character in the string s.
    If no such character exists, return -1.
    """
    char_count = {}

    # First pass to count occurrences
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass to find the first distinct character
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    return -1

