def xor_strings(str1, str2):
    """
    Returns a string where each character is the XOR of the corresponding characters
    in the two input strings. If the strings are not of equal length, inserts '_'
    at the end of the shorter string.
    """

    # Ensure the strings are of equal length
    if len(str1) != len(str2):
        if len(str1) < len(str2):
            str1 += '_' * (len(str2) - len(str1))
        else:
            str2 += '_' * (len(str1) - len(str2))

    # Generate the XOR-ed string
    xor_result = []
    for a, b in zip(str1, str2):
        xor_result.append(chr(ord(a) ^ ord(b)))

    return ''.join(xor_result)

