def generate_neologisms(list1, list2):
    """
    Generates a list of neologisms from two input lists of words.
    The final list will not contain repeated neologisms.
    """
    result = set()

    for word1 in list1:
        for word2 in list2:
            neologism1 = word1 + word2
            neologism2 = word2 + word1
            result.add(neologism1)
            result.add(neologism2)

    return list(result)

