def generate_primes(n):
    """
    Generates the first n prime numbers.
    """
    primes = []
    candidate = 2
    while len(primes) < n:
        for prime in primes:
            if candidate % prime == 0:
                break
        else:
            primes.append(candidate)
        candidate += 1
    return primes

def sieve_of_eratosthenes(max_number):
    """
    Implements the Sieve of Eratosthenes to check for prime numbers up to max_number.
    """
    is_prime = [True] * (max_number + 1)
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not primes

    p = 2
    while (p * p <= max_number):
        if is_prime[p] == True:
            for i in range(p * p, max_number + 1, p):
                is_prime[i] = False
        p += 1

    primes = [p for p in range(max_number + 1) if is_prime[p]]
    return primes

def is_prime(n):
    """
    Check if n is prime using the Sieve of Eratosthenes algorithm.
    """
    if n <= 1:
        return False

    primes = sieve_of_eratosthenes(n)
    return n in primes

