def fibonacci(n):
    """
    Computes the nth Fibonacci number recursively with O(n) time complexity and O(1) space complexity.
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    a, b = 0, 1
    for _ in range(2, n):
        a, b = b, a + b
    return b

