def recursive_add_arrays(arr1, arr2, fillvalue=0):
    """
    Recursively adds corresponding elements of two multidimensional arrays of potentially different depths.
    If corresponding elements do not exist in both arrays, fill with fillvalue.
    """
    if isinstance(arr1, list) and isinstance(arr2, list):
        max_length = max(len(arr1), len(arr2))
        result = []
        for i in range(max_length):
            val1 = arr1[i] if i < len(arr1) else fillvalue
            val2 = arr2[i] if i < len(arr2) else fillvalue
            result.append(recursive_add_arrays(val1, val2, fillvalue))
        return result
    elif isinstance(arr1, list):
        return [recursive_add_arrays(val, arr2, fillvalue) for val in arr1]
    elif isinstance(arr2, list):
        return [recursive_add_arrays(arr1, val, fillvalue) for val in arr2]
    else:
        return arr1 + arr2

def find_max_number(L):
    """
    Returns the maximum number from the list L.
    Raises ValueError if the list is empty or contains non-numeric values.
    """
    if not L:
        raise ValueError("List is empty")

    max_number = None
    for item in L:
        if not isinstance(item, (int, float)):
            raise ValueError(f"List contains non-numeric value: {item}")

        if max_number is None or item > max_number:
            max_number = item

    return max_number

