def factorial(n):
    """
    Returns the factorial of a number n using recursion.
    If n is 0 or 1, returns 1.
    If n < 0, raises ValueError.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

