def first_non_repeating_character(string):
    """
    Returns the first non-repeating character in the given string.
    If no non-repeating character exists, returns None.
    """
    frequency = {}

    # Count the frequency of each character
    for char in string:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    # Find the first non-repeating character
    for char in string:
        if frequency[char] == 1:
            return char

    return None

def reverse_string(s):
    """
    Returns the input string in reverse order.
    """
    reversed_chars = []
    for char in s:
        reversed_chars.insert(0, char)
    return ''.join(reversed_chars)

