def find_element(arr, element, start=0, end=None):
    """
    Uses recursive binary search to find the element in the sorted array `arr`.
    Returns the index of the element if found, otherwise returns -1.
    """
    if end is None:
        end = len(arr) - 1

    if start > end:
        return -1

    mid = (start + end) // 2

    if arr[mid] == element:
        return mid
    elif arr[mid] > element:
        return find_element(arr, element, start, mid - 1)
    else:
        return find_element(arr, element, mid + 1, end)

