def find_max_min(nums):
    """
    Returns a tuple containing the maximum and minimum values in a list of integers.

    Args:
    nums (list): A list of integers.

    Returns:
    tuple: A tuple with the maximum and minimum values.
    """
    if not nums:
        raise ValueError("The list should not be empty")

    max_val = nums[0]
    min_val = nums[0]

    for num in nums:
        if num > max_val:
            max_val = num
        if num < min_val:
            min_val = num

    return (max_val, min_val)

