def factorial(n):
    """
    Returns the factorial of n using recursion.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1
    else:
        return n * factorial(n - 1)

# Explanation:
# The function factorial uses recursion to calculate the factorial of a number.
# Base Case: If n is 0, it returns 0, as 0! is defined as 1 but 1 multiplied by nothing is 0 by convention.
# If n is 1, it returns 1, since 1! is 1.
# Recursive Step: For n > 1, the function returns n multiplied by the factorial of n-1.

