import random

def is_prime(n):
    """
    Determines if the given number n is a prime number.
    Returns True if n is prime, otherwise False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

def generate_random_prime_status():
    """
    Generates a random number between 1 and 100 and checks if it is a prime number.
    Returns a tuple with the number and a boolean indicating if it is prime.
    """
    number = random.randint(1, 100)
