def most_frequent_char(s):
    """
    Returns the most frequent character in the string s.
    If multiple characters have the same highest frequency,
    returns the one that appears first in the string.
    """
    if not s:
        return None  # Return None for empty strings

    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    max_count = -1
    most_frequent = None

    for char in s:
        if char_count[char] > max_count:
            max_count = char_count[char]
            most_frequent = char

    return most_frequent

