import random
import string

def generate_random_string(length, use_lowercase=True, use_uppercase=True, use_digits=True, use_special_chars=True):
    """
    Generates a random string based on the specified criteria.

    :param length: length of the string to be generated.
    :param use_lowercase: if True, include lowercase letters.
    :param use_uppercase: if True, include uppercase letters.
    :param use_digits: if True, include digits.
    :param use_special_chars: if True, include special characters.
    :return: generated random string.
    """
    if length <= 0:
        return ""

    character_pool = ""
    if use_lowercase:
        character_pool += string.ascii_lowercase
    if use_uppercase:
        character_pool += string.ascii_uppercase
    if use_digits:
        character_pool += string.digits
    if use_special_chars:
        character_pool += string.punctuation

    if not character_pool:
        raise ValueError("At least one character type must be selected.")

    return ''.join(random.choice(character_pool) for _ in range(length))

