def sum_of_primes(n):
    """
    Returns the sum of all prime numbers less than n.
    """
    if n <= 2:
        return 0

    sieve = [True] * n
    sieve[0], sieve[1] = False, False

    p = 2
    while p * p < n:
        if sieve[p]:
            for i in range(p * p, n, p):
                sieve[i] = False
        p += 1

    return sum(i for i, is_prime in enumerate(sieve) if is_prime)

