def longest_common_subsequence(str1, str2):
    """
    Returns the longest common subsequence of str1 and str2.
    """
    m = len(str1)
    n = len(str2)

    # Create a 2D array to store the lengths of longest common subsequence.
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp array in bottom-up manner
    for i in range(m):
        for j in range(n):
            if str1[i] == str2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    # Reconstruct the LCS from the dp array
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if dp[i][j] == dp[i - 1][j]:
            i -= 1
        elif dp[i][j] == dp[i][j - 1]:
            j -= 1
        else:
            lcs.append(str1[i - 1])
            i -= 1
            j -= 1

    return ''.join(reversed(lcs))

