def fibonacci(n, memo=None):
    """
    Returns the Fibonacci sequence up to the nth term as a list.

    :param n: The number of terms in the Fibonacci sequence to generate.
    :param memo: Dictionary used to store previously computed Fibonacci numbers for memoization.
    :return: A list containing the first n terms of the Fibonacci sequence.
    """
    if memo is None:
        memo = {}

    def fib(k):
        if k in memo:
            return memo[k]
        if k <= 1:
            memo[k] = k
        else:
            memo[k] = fib(k - 1) + fib(k - 2)
        return memo[k]

    sequence = [fib(i) for i in range(n)]
    return sequence

