def calculate_even_average(nums):
    """
    Calculates the average of all even numbers in the provided list of integers.

    :param nums: List of integers.
    :return: The average of even numbers or a message if no even numbers were found.
    """
    if not all(isinstance(num, int) for num in nums):
        raise ValueError("All elements in the list must be integers.")

    even_nums = [num for num in nums if num % 2 == 0]

    if not even_nums:
        return "No even numbers found."

    return sum(even_nums) / len(even_nums)

