def find_max_min(numbers):
    """
    Returns the maximum and minimum numbers from the list of integers.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    tuple: A tuple containing the maximum and minimum numbers (max_num, min_num).
    """
    if not numbers:
        raise ValueError("The list should not be empty")

    max_num = numbers[0]
    min_num = numbers[0]

    for num in numbers[1:]:
        if num > max_num:
            max_num = num
        if num < min_num:
            min_num = num

    return (max_num, min_num)

