from itertools import combinations, combinations_with_replacement

def generate_combinations(char_list, length, allow_repetition):
    """
    Generates all possible combinations of a given set of characters with a specified length.

    Parameters:
    char_list (list): List of characters.
    length (int): Length of each combination.
    allow_repetition (bool): If True, repetitions are allowed in the combinations.

    Returns:
    List of tuples containing combinations.
    """
    if allow_repetition:
        return list(combinations_with_replacement(char_list, length))
    else:
        return list(combinations(char_list, length))

