def read_numbers_from_file(file_path):
    """
    Reads a list of numbers from a file, where each number is on a separate line.
    Handles file not found and non-numeric values exceptions gracefully.
    Returns a list of valid numbers.
    """
    numbers = []
    try:
        with open(file_path, 'r') as file:
            for line in file:
                try:
                    number = float(line.strip())
                    numbers.append(number)
                except ValueError:
                    print(f"Warning: Non-numeric value found and skipped: {line.strip()}")
    except FileNotFoundError:
        print(f"Error: File not found: {file_path}")
        return None
    return numbers

def calculate_average(numbers):
    """
    Calculates the average of a list of numbers.
    Returns the average if the list is not empty, or a message if it is.
    """
    if numbers:
        return sum(numbers) / len(numbers)
    else:
        return "No valid numbers to calculate average."

def main(file_path):
    numbers = read_numbers_from_file(file_path)
    if numbers is None or not numbers:
        print("No valid numbers to calculate average.")
    else:
        average = calculate_average(numbers)
        print(f"The average is: {average}")

