def two_sum(nums, target):
    """
    Find two numbers in the list `nums` that add up to the `target` and return their indices.

    :param nums: List of integers.
    :param target: Integer target sum.
    :return: A tuple of two integers indicating the indices of the two numbers that add up to the target.
    """
    num_to_index = {}
    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], index)
        num_to_index[num] = index

