def is_valid_ipv4(address):
    """
    Checks if the given string is a valid IPv4 address.

    :param address: str : the string to check
    :return: str : "Valid IPv4" or "Invalid IPv4"
    """
    parts = address.split('.')
    if len(parts) != 4:
        return "Invalid IPv4"

    for part in parts:
        if not part.isdigit() or not 0 <= int(part) <= 255 or (part[0] == '0' and len(part) > 1):
            return "Invalid IPv4"

    return "Valid IPv4"

