def find_max_min(lst):
    """
    Returns a tuple containing the maximum and minimum values in a list of integers.
    """
    if not lst:
        raise ValueError("The list must not be empty")

    max_val = lst[0]
    min_val = lst[0]

    for num in lst[1:]:
        if num > max_val:
            max_val = num
        if num < min_val:
            min_val = num

    return max_val, min_val

