def flatten(lst):
    def go(list_, idx, dict_):
        for el in list_:
            if isinstance(el, list):
                dict_, idx = go(el, idx, dict_)
            else:
                dict_[str(idx)] = el
                idx += 1
        return dict_, idx

    flattened_dict, _ = go(lst, 1, {})
    return flattened_dict

