def is_leap_year(year):
    """
    Checks if the given year is a leap year.
    Returns True if the year is a leap year, False otherwise.
    Handles non-integer inputs by returning False.
    """
    if not isinstance(year, int):
        return False
    if year % 4 == 0:
        if year % 100 == 0:
            if year % 400 == 0:
                return True
            else:
                return False
        else:
            return True
    return False

