import random

def number_guessing_game():
    """
    A simple number guessing game where the player has to guess the secret number between 1 and 100.
    """
    secret_number = random.randint(1, 100)
    attempts = 0
    max_attempts = 10

    print("Welcome to the Number Guessing Game!")
    print(f"You have {max_attempts} attempts to guess the number between 1 and 100.")

    while attempts < max_attempts:
        try:
            guess = int(input("Enter your guess: "))
            attempts += 1

            if guess < secret_number:
                print("Your guess is too low.")
            elif guess > secret_number:
                print("Your guess is too high.")
            else:
                print(f"Congratulations! You've guessed the correct number {secret_number} in {attempts} attempts.")
                break
        except ValueError:
            print("Please enter a valid number.")

    if attempts == max_attempts and guess != secret_number:
        print(f"Sorry, you've used all your attempts. The secret number was {secret_number}.")

