def sum_of_primes(n):
    """
    Returns the sum of all prime numbers up to and including n.
    """
    if n < 2:
        return 0

    primes = [True] * (n + 1)
    primes[0], primes[1] = False, False

    p = 2
    while p * p <= n:
        if primes[p]:
            for i in range(p * p, n + 1, p):
                primes[i] = False
        p += 1

    return sum(i for i in range(n + 1) if primes[i])

