def max_product(nums):
    """
    Returns the maximum product of any two numbers in the input array.
    """
    if len(nums) < 2:
        raise ValueError("Array must contain at least two elements")

    # Sort the array to get the maximum and second maximum values efficiently
    nums.sort()

    # Compare product of two largest numbers and two smallest numbers
    return max(nums[-1] * nums[-2], nums[0] * nums[1])

