def longest_unique_substring(s):
    """
    Finds the longest unique or non-repeating substring from a given string.

    Args:
    s (str): The input string.

    Returns:
    str: The longest unique or non-repeating substring.
    """
    start = maxLength = 0
    usedChar = {}
    maxSubstring = ""

    for i in range(len(s)):
        if s[i] in usedChar and start <= usedChar[s[i]]:
            start = usedChar[s[i]] + 1
        else:
            if maxLength < i - start + 1:
                maxLength = i - start + 1
                maxSubstring = s[start:i+1]

        usedChar[s[i]] = i

    return maxSubstring

