def merge_lists(list1, list2):
    """
    Merges two lists of tuples, keeping tuples where the first elements match.

    Parameters:
        list1 (list): The first list of tuples.
        list2 (list): The second list of tuples.

    Returns:
        list: A merged list of tuples with matching first elements.
    """
    combined_dict = {}

    for tpl in list1 + list2:
        key, value = tpl
        if key not in combined_dict:
            combined_dict[key] = [value]
        else:
            if value not in combined_dict[key]:
                combined_dict[key].append(value)

    merged_list = [(key, value) for key, values in combined_dict.items() for value in values]

    return merged_list

