def convert(s, numRows):
    """
    Convert a given string s to a zigzag pattern with numRows and return the string reading row-by-row.
    """
    if numRows == 1 or numRows >= len(s):
        return s

    answer = [""] * numRows
    index, step = 0, -1

    for c in s:
        answer[index] += c

        if index == 0:
            step = 1
        elif index == numRows - 1:
            step = -1

        index += step

    return "".join(answer)

