def is_palindrome_recursive(s):
    """
    Checks if the given string s is a palindrome using recursion.
    """
    # Base case: an empty string or a single character string is a palindrome
    if len(s) <= 1:
        return True
    # Check if the first and last characters are the same
    if s[0] != s[-1]:
        return False
    # Recursively check the substring excluding the first and last characters
    return is_palindrome_recursive(s[1:-1])

