import random

def is_prime(n):
    """
    Returns True if n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_and_check_prime():
    """
    Generates a random number between 1 and 100 and checks if it is a prime number.
    Returns the number if it is a prime; otherwise returns "Not a prime number".
    """
    num = random.randint(1, 100)
    if is_prime(num):
        return num
    else:
        return "Not a prime number"

