def factorial(n):
    """
    Returns the factorial of a non-negative integer n.
    Raises a ValueError if n is negative.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n == 0:
        return 1
    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

