def parse_string(s):
    """
    Parses the input string and returns the count of numbers, letters, and special characters.

    Args:
    s (str): The input string to be parsed.

    Returns:
    dict: A dictionary with keys 'numbers', 'letters', and 'special_characters' with their respective counts.
    """
    counts = {'numbers': 0, 'letters': 0, 'special_characters': 0}

    for char in s:
        if char.isdigit():
            counts['numbers'] += 1
        elif char.isalpha():
            counts['letters'] += 1
        else:
            counts['special_characters'] += 1

    return counts

