def fibonacci(n):
    """
    Returns the nth Fibonacci number using an iterative approach.
    If n is 0, returns 0. If n is negative, returns an appropriate message.
    """
    if n < 0:
        return "Invalid input: n should be a non-negative integer."
    elif n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

