def celsius_to_fahrenheit(celsius):
    """
    Converts Celsius to Fahrenheit.
    """
    return (celsius * 9/5) + 32

def fahrenheit_to_celsius(fahrenheit):
    """
    Converts Fahrenheit to Celsius.
    """
    return (fahrenheit - 32) * 5/9

def convert_temperature(value, direction):
    """
    Converts a given temperature from Celsius to Fahrenheit and vice versa.
    direction: 'CtoF' for Celsius to Fahrenheit, 'FtoC' for Fahrenheit to Celsius
    """
    if direction == 'CtoF':
        return celsius_to_fahrenheit(value)
    elif direction == 'FtoC':
        return fahrenheit_to_celsius(value)
    else:
        raise ValueError("Invalid direction. Use 'CtoF' for Celsius to Fahrenheit or 'FtoC' for Fahrenheit to Celsius.")

def fibonacci_sequence(n):
    """
    Returns a list of Fibonacci sequence up to the n-th number.
    """
    if n < 1:
        return []

    fib_seq = [0, 1]
    for i in range(2, n):
        fib_seq.append(fib_seq[-1] + fib_seq[-2])

    return fib_seq[:n]

