def fizz_buzz(n):
    """
    Returns a list of numbers from 1 to n, but with substitutions:
    - "Fizz" for multiples of 3
    - "Buzz" for multiples of 5
    - "FizzBuzz" for multiples of both 3 and 5
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(i)
    return result

def find_second_largest(nums):
    """
    Returns the second largest number in a list of integers.
    If there is no second largest number, returns None.
    """
    if len(nums) < 2:
        return None

    first = second = float('-inf')
    for num in nums:
        if num > first:
            second = first
            first = num
        elif first > num > second:
            second = num

    return second if second != float('-inf') else None

