def delete_key_from_dict(dictionary):
    """
    Function to iterate over the keys of a dictionary and allow
    the user to select a key to delete.
    """
    keys = list(dictionary.keys())

    for idx, key in enumerate(keys):
        print(f"{idx}: {key}")

    try:
        key_index = int(input("Select the number corresponding to the key you want to delete: "))
        if 0 <= key_index < len(keys):
            key_to_delete = keys[key_index]
            del dictionary[key_to_delete]
        else:
            print("Invalid selection. No key deleted.")
    except (ValueError, IndexError):
        print("Invalid input. No key deleted.")

    return dictionary

