import re

def reverse_string(s):
    """
    Reverse a string, but if it's a palindrome return the original string in uppercase.
    If not, return the reversed string in lowercase.
    """
    # Normalize string: remove non-alphanumeric characters and convert to lowercase
    normalized = re.sub(r'[^a-zA-Z0-9]', '', s).lower()

    # Check if the normalized string is a palindrome
    is_palindrome = normalized == normalized[::-1]

    if is_palindrome:
        return s.upper()
    else:
        return s[::-1].lower()

