def infix_to_postfix(expression):
    """
    Convert an infix expression to a postfix expression using the Shunting Yard algorithm.
    """
    # Define operator precedence and associativity
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    right_associative = set()

    output = []
    operators = []

    for char in expression:
        if char.isalnum():  # Operand (numbers/variables)
            output.append(char)
        elif char == '(':
            operators.append(char)
        elif char == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()  # pop '('
        else:  # Operator
            while (operators and operators[-1] != '(' and
                   (operators[-1] in right_associative and precedence[char] < precedence[operators[-1]] or
                    precedence[char] <= precedence[operators[-1]])):
                output.append(operators.pop())
            operators.append(char)

    while operators:
        output.append(operators.pop())

    return ''.join(output)

