import random

def randommove(list_of_properties):
    getRandom = list_of_properties[random.randint(0,len(list_of_properties) - 1)]
    return getRandom

def allPlayersrandmove(list_of_players, list_of_properties):
    newListOfProperties = list_of_properties.copy()
    player_properties = {}
    for player in list_of_players:
        if newListOfProperties:
            removeProperty = randommove(newListOfProperties)
            newListOfProperties.remove(removeProperty)
            player_properties[player] = removeProperty
        else:
            player_properties[player] = None  # When no properties left
    return newListOfProperties, player_properties

