def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def first_n_primes(n):
    """
    Generate a list of the first n prime numbers.
    """
    primes = []
    candidate = 2
    while len(primes) < n:
        if is_prime(candidate):
            primes.append(candidate)
        candidate += 1
    return primes

def first_10_primes():
    """
    Generates a list of the first 10 prime numbers.
    """
    return first_n_primes(10)

def largest_prime_factor(n):
    """
    Returns the largest prime factor of the given number n.
    """
    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    largest_factor = -1
    factor = 2

    while factor * factor <= n:
        if n % factor == 0:
            while n % factor == 0:
                n //= factor
            largest_factor = factor
        factor += 1

    if n > 1:
        largest_factor = n

    return largest_factor

