def calculate_stats(numbers):
    """
    Given a list of numbers, returns a tuple containing the maximum, minimum, and average.
    """
    if not numbers:
        raise ValueError("The list is empty.")

    try:
        max_num = max(numbers)
        min_num = min(numbers)
        avg_num = sum(numbers) / len(numbers)

        return max_num, min_num, avg_num

    except TypeError:
        raise ValueError("The list contains non-numeric values.")

