def power(base, exponent):
    """
    Returns the result of raising base to the power of exponent.
    """
    if exponent == 0:
        return 1
    elif exponent < 0:
        base = 1 / base
        exponent = -exponent

    result = 1
    for _ in range(exponent):
        result *= base

    return result

