def fibonacci(n):
    """
    Returns the n-th Fibonacci number using recursion.

    The Fibonacci sequence is a sequence of numbers where each number is the sum of the two preceding ones,
    usually starting with 0 and 1. That is,
    F(n) = F(n-1) + F(n-2) with seed values F(0) = 0, F(1) = 1

    Parameters:
    n (int): The position in the Fibonacci sequence to retrieve (0-based index).

    Returns:
    int: The n-th Fibonacci number.
    """
    if n < 0:
        raise ValueError("Input n should be a non-negative integer")
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

