def group_employees_by_department(employee_list):
    """
    Groups employees by department and sorts them alphabetically within each department.

    Arguments:
    employee_list -- a list of tuples where each tuple contains an employee name and their department.

    Returns:
    A dictionary where the keys are departments and the values are lists of employee names sorted alphabetically.
    """
    department_dict = {}

    for employee, department in employee_list:
        if department not in department_dict:
            department_dict[department] = []
        department_dict[department].append(employee)

    for department in department_dict:
        department_dict[department].sort()

    return department_dict

