def longest_common_subsequence(str1, str2):
    """
    Returns the longest common subsequence of str1 and str2.
    """
    m, n = len(str1), len(str2)
    # Creating a 2D array to store the lengths of longest common subsequence
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Building the dp array from bottom up
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif str1[i-1] == str2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    # Reconstructing the LCS from the dp array
    i, j = m, n
    lcs = []
    while i > 0 and j > 0:
        if str1[i-1] == str2[j-1]:
            lcs.append(str1[i-1])
            i -= 1
            j -= 1
        elif dp[i-1][j] > dp[i][j-1]:
            i -= 1
        else:
            j -= 1

    # The lcs array will contain the LCS in reverse order
    return ''.join(reversed(lcs))

