def char_frequency(s):
    """
    Returns a dictionary with the frequency of each character in the input string s.

    Args:
    s (str): The input string.

    Returns:
    dict: A dictionary with characters as keys and their frequencies as values.
    """
    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1
    return frequency

