def prime_numbers_upto_n(n):
    """
    Returns a list of prime numbers less than or equal to n.
    """
    if n < 2:
        return []

    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False
    p = 2

    while p * p <= n:
        if sieve[p]:
            for i in range(p * p, n + 1, p):
                sieve[i] = False
        p += 1

    return [number for number, is_prime in enumerate(sieve) if is_prime]

