def factorial(n):
    """
    Returns the factorial of a non-negative integer n using recursion.
    Factorial of a non-negative integer n is the product of all positive
    integers less than or equal to n. It is denoted by n!.

    For example, 5! = 5 * 4 * 3 * 2 * 1 = 120
    """
    if n == 0:
        return 1
    else:
        return n * factorial(n-1)

