def is_prime(n):
    """
    Checks if a given integer is a prime number.

    Parameters:
    n (int): The integer to check.

    Returns:
    bool: True if the integer is a prime number, False otherwise.
    """
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

