def most_frequent_element(lst):
    """
    This function returns the most frequent element in a list. If there are multiple elements
    with the same highest frequency, it returns the one that appears first in the list.

    :param lst: List of elements
    :return: The most frequent element in the list
    """
    if not lst:
        return None

    frequency = {}
    max_count = 0
    most_frequent_elem = None

    for elem in lst:
        if elem in frequency:
            frequency[elem] += 1
        else:
            frequency[elem] = 1

        if frequency[elem] > max_count:
            max_count = frequency[elem]
            most_frequent_elem = elem

    return most_frequent_elem

