def encode_string(s, key):
    """
    Encodes the string by shifting each character by key value.
    Non-alphabet characters remain unchanged.
    """
    def shift_char(c, key):
        if c.isalpha():
            start = ord('A') if c.isupper() else ord('a')
            return chr((ord(c) - start + key) % 26 + start)
        return c

    return ''.join(shift_char(c, key) for c in s)

def decode_string(s, key):
    """
    Decodes the string by shifting each character by key value in reverse.
    Non-alphabet characters remain unchanged.
    """
    return encode_string(s, -key)

def is_prime(n):
    """
    Returns True if n is a prime number, and False otherwise.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False

    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6

    return True

