def find_min_max(numbers):
    """
    Returns a tuple containing the smallest and largest number from the given list.
    If the list is empty, returns (None, None).
    """
    if not numbers:
        return (None, None)

    min_value = numbers[0]
    max_value = numbers[0]

    for num in numbers[1:]:
        if num < min_value:
            min_value = num
        if num > max_value:
            max_value = num

    return (min_value, max_value)

