def word_pattern(pattern, s):
    """
    Checks if the given string s matches the pattern.

    Parameters:
    pattern (str): The pattern to match.
    s (str): The string to match the pattern against.

    Returns:
    bool: True if the string matches the pattern, False otherwise.
    """
    words = s.split()
    if len(pattern) != len(words):
        return False

    pattern_to_word = {}
    word_to_pattern = {}

    for p, word in zip(pattern, words):
        if p in pattern_to_word:
            if pattern_to_word[p] != word:
                return False
        else:
            pattern_to_word[p] = word

        if word in word_to_pattern:
            if word_to_pattern[word] != p:
                return False
        else:
            word_to_pattern[word] = p

    return True

