def find_first_peak(nums):
    """
    Returns the index of the first element which is greater than the element
    that comes after it. If no such element exists, return -1.
    """
    if not nums or len(nums) < 2:
        return -1

    for i in range(len(nums) - 1):
        if nums[i] > nums[i + 1]:
            return i

    return -1

