def sum_of_primes(n):
    """
    Returns the sum of all prime numbers up to and including n.
    """
    if n < 2:
        return 0

    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not primes

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i * i, n + 1, i):
                sieve[j] = False

    prime_sum = sum(i for i in range(n + 1) if sieve[i])
    return prime_sum

