def factorial(n):
    """
    Returns the factorial of a non-negative integer n using recursion.
    Handles error cases for negative numbers and non-integer values.
    """
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n < 0:
        raise ValueError("Input must be a non-negative integer")
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

# Brief explanation:
# Recursion is a method where the solution to a problem depends on solutions to smaller instances of the same problem.
# In this context, the factorial of `n` (`n!`) is defined as `n * (n-1)!`.
# The base case for the recursion is `0! = 1`.
# The recursive case involves repeatedly applying the formula `n! = n * (n-1)!` until reaching the base case.

