def maximum_sum_submatrix(matrix):
    if not matrix or not matrix[0]:
        return 0

    num_rows = len(matrix)
    num_cols = len(matrix[0])

    # Step 1: Calculate prefix sums for each column
    prefix_sums = [[0] * num_cols for _ in range(num_rows + 1)]
    for r in range(1, num_rows + 1):
        for c in range(num_cols):
            prefix_sums[r][c] = prefix_sums[r-1][c] + matrix[r-1][c]

    max_sum = float('-inf')

    # Step 2: Apply Kadane's algorithm on all possible row pairs
    for i in range(num_rows):
        for j in range(i, num_rows):
            current_sum = 0
            temp_max = float('-inf')
            for c in range(num_cols):
                col_sum = prefix_sums[j+1][c] - prefix_sums[i][c]
                current_sum = max(col_sum, current_sum + col_sum)
                temp_max = max(temp_max, current_sum)

            max_sum = max(max_sum, temp_max)

    return max_sum

