def caesar_cipher_encrypt(text, shift):
    """
    Encrypts the given text using the Caesar cipher algorithm.

    :param text: The input string to be encrypted.
    :param shift: The number of positions to shift each character.
    :return: The encrypted string.
    """
    encrypted_text = []
    for char in text:
        if char.isalpha():
            shift_base = 65 if char.isupper() else 97
            encrypted_text.append(chr((ord(char) - shift_base + shift) % 26 + shift_base))
        else:
            encrypted_text.append(char)
    return ''.join(encrypted_text)

def caesar_cipher_decrypt(encrypted_text, shift):
    """
    Decrypts the given text encrypted using the Caesar cipher algorithm.

    :param encrypted_text: The encrypted string to be decrypted.
    :param shift: The number of positions to shift each character.
    :return: The decrypted string.
    """
    return caesar_cipher_encrypt(encrypted_text, -shift)

