def is_prime(n):
    """
    Returns True if the number n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True  # 2 is the only even prime number
    if n % 2 == 0:
        return False  # exclude even numbers greater than 2
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

