def find_max_length(arr):
    """
    Finds the length of the longest contiguous subarray of even numbers.
    """
    max_length = 0
    current_length = 0
    for num in arr:
        if num % 2 == 0:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 0
    return max_length

