import random

def is_prime(n):
    """
    Check if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_random_number(start=1, end=100):
    """
    Generate a random number between start and end (inclusive).
    """
    return random.randint(start, end)

def generate_and_check_prime(start=1, end=100):
    """
    Generate a random number between start and end (inclusive) and check if it's prime.
    """
    num = generate_random_number(start, end)
    return num, is_prime(num)

