def replace_vowels(s, char, ignore_case=True):
    """
    Replace all vowels in the input string `s` with the specified character `char`.
    If `ignore_case` is True, the function ignores case sensitivity.
    """
    vowels = "aeiou"
    if ignore_case:
        s = s.lower()
        vowels = vowels.lower() + vowels.upper()

    return ''.join([char if c in vowels else c for c in s])

