def is_prime(n):
    """
    Checks if the given number is prime.
    If not prime, returns False and a list of its divisors.

    Args:
    n (int): The number to check

    Returns:
    (bool, list): A tuple with a boolean indicating if the number is prime,
                  and a list of divisors if the number is not prime.
    """
    if n <= 1:
        return False, []

    divisors = []
    for i in range(2, n):
        if n % i == 0:
            divisors.append(i)

    if len(divisors) == 0:
        return True, []
    else:
        return False, divisors

