def selective_merge(dicts_list, keys_to_keep):
    """
    Merges a list of dictionaries, keeping only specified keys in the merged dictionary.

    Parameters:
    - dicts_list: List[Dict], list of dictionaries to merge.
    - keys_to_keep: List, keys to retain in the merged dictionary.

    Returns:
    - merged_dict: Dict, the resulting merged dictionary.
    """
    merged_dict = {}
    for d in dicts_list:
        for key in keys_to_keep:
            if key in d:
                merged_dict[key] = d[key]
    return merged_dict

