def convert_to_number(s):
    """
    Tries to convert a string to an integer or float.
    If the conversion is not possible, returns the original string.
    Handles leading and trailing whitespaces.
    """
    s = s.strip()
    try:
        if '.' in s or 'e' in s or 'E' in s:
            return float(s)
        else:
            return int(s)
    except ValueError:
        return s

