def fibonacci(N):
    """
    Generates the first N numbers of the Fibonacci sequence.
    """
    if N <= 0:
        return []
    elif N == 1:
        return [0]
    elif N == 2:
        return [0, 1]

    fib_sequence = [0, 1]
    while len(fib_sequence) < N:
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])

    return fib_sequence

