def reverse_string_ignore_digits(s):
    """
    Reverses the string s, ignoring any digits.
    If the string is empty or contains only digits, returns an empty string.
    """
    if not s or s.isdigit():
        return ""

    non_digit_chars = [ch for ch in s if not ch.isdigit()]

    return ''.join(non_digit_chars[::-1])

