def find_largest_common_factor(numbers):
    """
    Recursively finds the greatest common divisor (GCD) of a list of numbers.
    """
    def gcd(a, b):
        if a == 0:
            return b
        return gcd(b % a, a)

    if len(numbers) == 1:
        return numbers[0]

    head, *tail = numbers
    largest_factor = gcd(head, tail[0])

    if len(tail) == 1:
        return largest_factor

    return find_largest_common_factor([largest_factor] + tail[1:])

