def length_of_lis_ending_with(nums, target):
    """
    Returns the length of the longest increasing subsequence ending with target.
    """
    if target not in nums:
        return 0

    n = len(nums)
    lis = [1] * n  # Initialize LIS length array

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    max_length = 0
    for i in range(n):
        if nums[i] == target:
            max_length = max(max_length, lis[i])

    return max_length

