def calculator(a, b, operator):
    """
    Perform basic arithmetic operations.

    Parameters:
    - a (float): First number
    - b (float): Second number
    - operator (str): Operator, one of '+', '-', '*', '/'

    Returns:
    - result (float): Result of the arithmetic operation
    """
    if operator == '+':
        return a + b
    elif operator == '-':
        return a - b
    elif operator == '*':
        return a * b
    elif operator == '/':
        if b == 0:
            raise ValueError("Division by zero is not allowed")
        return a / b
    else:
        raise ValueError("Invalid operator. Operator must be one of '+', '-', '*', '/'")

