def count_characters(s):
    """
    Returns a dictionary with the count of each character in the string, excluding spaces.

    Parameters:
    s (str): The input string.

    Returns:
    dict: A dictionary where the keys are characters and the values are their respective counts.
    """
    result = {}
    for char in s:
        if char != ' ':
            if char in result:
                result[char] += 1
            else:
                result[char] = 1
    return result

