def most_frequent_integer(a, b, c):
    """
    Returns the integer that appears most frequently among the three inputs.
    In case of a tie, returns the smallest integer.
    """
    freq = {}

    # Count the frequency of each integer
    for number in [a, b, c]:
        if number in freq:
            freq[number] += 1
        else:
            freq[number] = 1

    # Find the most frequent integer
    most_frequent = min(freq, key=lambda x: (-freq[x], x))

    return most_frequent

