def find_max(lst):
    """
    Returns the maximum value in the given list of integers and floating-point numbers.
    Returns None if the list is empty.
    """
    if not lst:
        return None

    max_value = lst[0]
    for num in lst:
        if num > max_value:
            max_value = num

    return max_value

