import itertools

def is_prime(n):
    """
    Checks if a number is a prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def prime_generator(limit):
    """
    Generates prime numbers up to a given limit.
    """
    for num in itertools.count(start=2):
        if num > limit:
            return
        if is_prime(num):
            yield num

def primes_with_digit_5(limit):
    """
    Returns a list of prime numbers up to 'limit' that contain the digit '5'.
    """
    return [prime for prime in prime_generator(limit) if '5' in str(prime)]

