def char_frequency(s):
    """
    Returns a dictionary with the frequency of each character in the string, excluding spaces.

    Parameters:
    s (str): The input string.

    Returns:
    dict: A dictionary with characters as keys and their frequency as values.
    """
    frequency = {}
    for char in s:
        if char != ' ':
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1
    return frequency

