def second_largest(numbers):
    """
    Returns the second largest number in the list.
    If the list has less than 2 distinct numbers, raises a ValueError.
    """
    if len(numbers) < 2:
        raise ValueError("List must contain at least two distinct numbers.")

    first = second = float('-inf')
    for number in numbers:
        if number > first:
            second = first
            first = number
        elif number > second and number != first:
            second = number

    if second == float('-inf'):
        raise ValueError("List must contain at least two distinct numbers.")

    return second

