def count_characters(s):
    """
    Counts the occurrences of each character in the string s,
    including spaces and punctuation.

    Parameters:
    s (str): A string in which to count character occurrences.

    Returns:
    dict: A dictionary where keys are characters and values are their counts.
    """
    result = {}
    for char in s:
        if char in result:
            result[char] += 1
        else:
            result[char] = 1
    return result

