def find_target_index(nums, target):
    """
    Returns the index of the first occurrence of the target in the list,
    or -1 if the target is not present.

    :param nums: List of integers
    :param target: Target integer to find
    :return: Index of first occurrence of target or -1 if not found
    """
    try:
        return nums.index(target)
    except ValueError:
        return -1

