import random

def guess_number():
    """
    Generates a random number between 1 and 100, and allows the user to guess the number.
    Provides feedback on whether the guess is too high, too low, or correct.
    Keeps track of the number of guesses.
    """
    number_to_guess = random.randint(1, 100)
    attempts = 0
    guessed_correctly = False

    while not guessed_correctly:
        try:
            user_guess = int(input("Enter your guess (between 1 and 100): "))
            attempts += 1

            if user_guess < 1 or user_guess > 100:
                print("Please enter a number between 1 and 100.")
            elif user_guess < number_to_guess:
                print("Too low! Try again.")
            elif user_guess > number_to_guess:
                print("Too high! Try again.")
            else:
                print(f"Correct! The number was {number_to_guess}. You guessed it in {attempts} attempts.")
                guessed_correctly = True
        except ValueError:
            print("That's not a valid number. Please enter an integer.")

def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string s.
    If all characters are repeating, returns 'No non-repeating character found'.
    """
    char_count = {}

    # Count the occurrence of each character
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Find the first non-repeating character
    for char in s:
        if char_count[char] == 1:
            return char

    return "No non-repeating character found"

