def complementary_dna(dna):
    """
    Returns the complementary DNA string for the given DNA string.
    If the input contains invalid characters, returns None.

    Args:
    dna (str): A string containing the DNA sequence.

    Returns:
    str or None: The complementary DNA sequence or None if invalid input.
    """
    if not dna or not all(c in 'ATCG' for c in dna):
        return None

    comp = {'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G'}
    return ''.join(comp[c] for c in dna)

