def tokenize_string(s):
    """
    Tokenizes a string into words and punctuation.

    Arguments:
    s -- The input string to tokenize.

    Returns:
    A list of tokens where each token is either a word or a punctuation.
    """
    tokens = []
    word = ''
    for char in s:
        if char.isalnum():
            word += char
        else:
            if word:
                tokens.append(word)
                word = ''
            if char.isspace() == False:
                tokens.append(char)
    if word:
        tokens.append(word)
    return tokens

