    Merge a list of dictionaries in the order they appear.
    If there are overlapping keys, the values from the later dictionaries override those from earlier ones.
    If the values of both dictionaries for the same key are dictionaries, merge them recursively.

    Parameters:
    dicts (list): List of dictionaries to merge.

    Returns:
    dict: The merged dictionary.
    """
    def merge_two_dicts(d1, d2):
        merged = d1.copy()
        for key, value in d2.items():
            if key in merged and isinstance(merged[key], dict) and isinstance(value, dict):
                merged[key] = merge_two_dicts(merged[key], value)
            else:
                merged[key] = value
        return merged

    result = {}
    for dictionary in dicts:
        result = merge_two_dicts(result, dictionary)
    return result

