def list_divisors(nums):
    """
    Returns a dictionary where each integer from nums is a key and the value is a list of its divisors.

    Parameters:
    nums (list): A list of integers.

    Returns:
    dict: A dictionary of integers and their corresponding divisors.
    """
    def get_divisors(n):
        divisors = []
        for i in range(1, n + 1):
            if n % i == 0:
                divisors.append(i)
        return divisors

    result = {}
    for num in nums:
        result[num] = get_divisors(num)

    return result

