def print_diamond(rows):
    """
    Prints a diamond shape with the given number of rows.

    Arguments:
    rows -- a positive odd integer indicating the number of rows in the diamond.
    """
    if rows < 1 or rows % 2 == 0:
        raise ValueError("Number of rows must be a positive odd integer.")

    n = (rows // 2) + 1

    for i in range(1, n+1):
        print(' ' * (n-i) + '*' * (2*i-1))

    for i in range(n-1, 0, -1):
        print(' ' * (n-i) + '*' * (2*i-1))

def length_of_lis(nums):
    """
    Calculate the length of the longest strictly increasing subsequence.
    :param nums: List of integers.
    :return: Length of the longest strictly increasing subsequence.
    """
    if not nums:
        return 0

    # Initialize the dp array with 1s. Each number is its own LIS initially.
    dp = [1] * len(nums)

    # Loop through each element and update dp array based on previous elements.
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The longest increasing subsequence length is the maximum value in the dp array.
    return max(dp)

