import re

def extract_max_num_from_string(s):
    """
    Extracts the maximum numerical value from a given string that contains digits and letters.
    If the string contains only negative numbers, returns the smallest negative number (closest to zero).
    If the string does not contain any numerical values, returns 0.
    """
    numbers = re.findall(r'-?\d+\.?\d*', s)

    if not numbers:
        return 0

    numbers = [float(num) for num in numbers]

    if all(num < 0 for num in numbers):
        return max(numbers)

    return max([num for num in numbers if num >= 0])

