def bubble_sort(arr):
    """
    Sorts a list of numbers in ascending order using the bubble sort technique.
    """
    n = len(arr)
    for i in range(n):
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

