def simple_calculator(a, b, operator):
    """
    Simulates a simple command-line calculator that performs basic arithmetic operations.

    :param a: First number
    :param b: Second number
    :param operator: A string representing the arithmetic operation ('+', '-', '*', '/')
    :return: The result of the arithmetic operation
    :raises: ValueError for invalid operators or division by zero
    """
    if operator == '+':
        return a + b
    elif operator == '-':
        return a - b
    elif operator == '*':
        return a * b
    elif operator == '/':
        if b == 0:
            raise ValueError("Division by zero is not allowed.")
        return a / b
    else:
        raise ValueError("Invalid operator. Use one of '+', '-', '*', '/'")

