def validate_tsp_matrix(matrix):
    """
    Validate that each city in the TSP matrix is visited only once,
    is visited from exactly one city, and visits exactly one city.
    """
    n = len(matrix)

    # Check each row and column sum to ensure only one `1` is present in each.
    for i in range(n):
        if sum(matrix[i]) != 1:
            return False
        if sum(row[i] for row in matrix) != 1:
            return False

    # Use DFS to ensure a cycle exists visiting each node exactly once.
    visited = [False] * n

    def dfs(node):
        if visited[node]:
            return 0
        visited[node] = True
        for next_node in range(n):
            if matrix[node][next_node] == 1:
                return 1 + dfs(next_node)
        return 1

    # Start DFS from the first city to see if we visit all cities
    if dfs(0) != n:
        return False

    # Check if all cities were visited
    for node in range(n):
        if not visited[node]:
            return False

    return True

