def is_prime(n):
    """
    Determines if a number is a prime number.

    A prime number is a number greater than 1 that has no divisors other than 1 and itself.

    :param n: int, the number to check
    :return: bool, True if n is prime, otherwise False
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

