def find_largest_and_smallest(nums):
    """
    Returns a tuple containing the largest and smallest numbers in a list.
    If the list is empty, returns None.
    """
    if not nums:
        return None

    smallest = float('inf')
    largest = float('-inf')

    for num in nums:
        if num > largest:
            largest = num
        if num < smallest:
            smallest = num

    return (largest, smallest)

