def find_max_recursive(lst):
    """
    Returns the maximum value in a list using recursion.
    """
    if len(lst) == 1:
        return lst[0]
    else:
        max_of_rest = find_max_recursive(lst[1:])
        return lst[0] if lst[0] > max_of_rest else max_of_rest

