def first_missing_positive(nums):
    """
    Returns the first missing positive integer from the list of integers.
    """
    n = len(nums)

    for i in range(n):
        # Place each number in its right place, that is, number 3 at index 2
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

