def unpack_and_modify(data, modifier):
    """
    Traverses a nested structure and applies the modifier function to integers.

    :param data: A nested structure (dictionaries, lists, and integer values).
    :param modifier: A function that takes an integer and returns a modified integer.
    :return: A new nested structure with modified integers.
    """
    if isinstance(data, dict):
        return {key: unpack_and_modify(val, modifier) for key, val in data.items()}
    elif isinstance(data, list):
        return [unpack_and_modify(element, modifier) for element in data]
    elif isinstance(data, int):
        return modifier(data)
    else:
        return data

