def factorial(n):
    """
    Returns the factorial of a positive integer n using recursion.
    """
    if n == 0:
        return 1
    return n * factorial(n - 1)

def fibonacci(n):
    """
    Returns the n-th term in the Fibonacci sequence using recursion.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

def find_max_and_index(lst):
    """
    Returns a tuple containing the maximum value in the list and its index.
    """
    if not lst:
        raise ValueError("The list is empty")

    max_value = lst[0]
    max_index = 0

    for index, value in enumerate(lst):
        if value > max_value:
            max_value = value
            max_index = index

    return max_value, max_index

