def list_to_dict(pairs):
    """
    Converts a list of key-value pairs into a dictionary.
    If there are duplicate keys, the values are aggregated into a list.

    Args:
    pairs (list): List of tuples where each tuple contains a key and a value.

    Returns:
    dict: A dictionary with keys and aggregated values.
    """
    result = {}
    for key, value in pairs:
        if key in result:
            result[key].append(value)
        else:
            result[key] = [value]
    return result

