def second_smallest(numbers):
    """
    Returns the second smallest number in the list.
    If the list has fewer than 2 distinct elements, return None.
    """
    if len(numbers) < 2:
        return None

    first = second = float('inf')
    for num in numbers:
        if num < first:
            second = first
            first = num
        elif first < num < second:
            second = num

    return second if second < float('inf') else None

def second_largest(numbers):
    """
    Returns the second largest number in the list.
    If the list has fewer than 2 distinct elements, return None.
    """
    if len(numbers) < 2:
        return None

    first = second = float('-inf')
    for num in numbers:
        if num > first:
            second = first
            first = num
        elif first > num > second:
            second = num

    return second if second > float('-inf') else None

