def flatten_and_convert(nested_list):
    """
    Flattens a nested list of lists containing strings and integers up to two levels deep
    and converts it into a single string, with each element separated by a comma.

    Parameters:
    nested_list (list): A list which may contain other lists with strings and integers.

    Returns:
    str: The flattened and converted list as a single string.
    """
    result = []
    for element in nested_list:
        if isinstance(element, list):
            for sub_element in element:
                result.append(str(sub_element))
        else:
            result.append(str(element))
    return ','.join(result)

