def is_prime(num):
    """
    Determines if num is a prime number.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def filter_primes(numbers):
    """
    Returns a list of prime numbers from the input list.
    """
    return [num for num in numbers if is_prime(num)]

