def custom_lowercase(input_string):
    """
    Converts all uppercase letters in the input string to lowercase without
    using built-in `lower()` method or any direct string manipulation methods.
    """
    result = []
    for char in input_string:
        if 'A' <= char <= 'Z':
            # Calculate corresponding lowercase character by reversing the ASCII shift
            new_char = chr(ord(char) + 32)
            result.append(new_char)
        else:
            result.append(char)
    return ''.join(result)

