def first_unique_char(s):
    """
    Returns the index of the first unique character in the string s.
    If there are no unique characters, returns -1.
    """
    # Create a dictionary to store the count of each character
    char_count = {}

    # Populate the dictionary with character counts
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Iterate through the string and find the first unique character
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    return -1

