def frequency_counter(numbers):
    """
    Takes a list of numbers and returns a dictionary with the frequency of each number.

    Parameters:
    numbers (list): A list of numbers.

    Returns:
    dict: A dictionary where keys are the numbers from the list and values are the frequencies of these numbers.
