def factorial(n):
    """
    Returns the factorial of a positive integer n.
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("Input must be a non-negative integer.")

    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

