def tuple_keys_to_nested_dict(d):
    """
    Converts a dictionary with tuple keys into a multi-level nested dictionary.

    Args:
        d: A dictionary with tuple keys.

    Returns:
        A multi-level nested dictionary.

    Raises:
        ValueError: If duplicate keys are encountered at the same level.
    """
    nested_dict = {}

    for key_tuple, value in d.items():
        current_level = nested_dict

        for key in key_tuple[:-1]:
            if key not in current_level:
                current_level[key] = {}
            elif not isinstance(current_level[key], dict):
                raise ValueError(f"Duplicate key encountered: {key_tuple}")

            current_level = current_level[key]

        last_key = key_tuple[-1]
        if last_key in current_level:
            raise ValueError(f"Duplicate key encountered: {key_tuple}")
        current_level[last_key] = value

    return nested_dict

