def convert_list_to_dict(tuples_list):
    """
    Converts a list of tuples into a dictionary, summing the scores for duplicate names.

    Parameters:
        tuples_list (list of tuples): Each tuple contains a name and a score.

    Returns:
        dict: A dictionary with names as keys and summed scores as values.
    """
    result_dict = {}
    for name, score in tuples_list:
        if name in result_dict:
            result_dict[name] += score
        else:
            result_dict[name] = score
    return result_dict

