import random

def is_prime(num):
    """
    Returns True if num is a prime number, otherwise False.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while (i * i) <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_random_prime_check():
    """
    Generates a random integer between 1 and 1000, and checks if it is prime.
    Returns a tuple of the random integer and a boolean indicating primality.
    """
    random_number = random.randint(1, 1000)
    return random_number, is_prime(random_number)

def convert_temperature(temp_celsius, target_unit):
    """
    Converts the given temperature from Celsius to either Fahrenheit or Kelvin.

    Parameters:
    temp_celsius (float): Temperature in Celsius.
    target_unit (str): Target unit for conversion ('F' for Fahrenheit, 'K' for Kelvin).

    Returns:
    float: Converted temperature rounded to two decimal places.

    Raises:
    ValueError: If the target unit is neither 'F' nor 'K'.
    """
    if target_unit == 'F':
        return round((temp_celsius * 9/5) + 32, 2)
    elif target_unit == 'K':
        return round(temp_celsius + 273.15, 2)
    else:
        raise ValueError("Invalid target unit. Use 'F' for Fahrenheit or 'K' for Kelvin.")

