def find_missing_positive(arr):
    """
    Returns the smallest positive integer that is missing from the given array.
    """
    if not arr:
        return 1

    n = len(arr)

    # Step 1: Segregate positive numbers from non-positive numbers
    # Move all non-positive numbers to the left side
    j = 0
    for i in range(n):
        if arr[i] <= 0:
            arr[i], arr[j] = arr[j], arr[i]
            j += 1

    # Step 2: Mark the presence of positive numbers in the positive segment
    # Use the indices of the array as a hash to mark the presence.
    for i in range(j, n):
        val = abs(arr[i])
        if val - 1 < n - j and arr[j + val - 1] > 0:
            arr[j + val - 1] = -arr[j + val - 1]

    # Step 3: Find the first positive integer that is missing
    for i in range(j, n):
        if arr[i] > 0:
            return i - j + 1

    # If all positive numbers from 1 to n-j are present, return n-j+1
    return n - j + 1

