def fruit_quantity_description(fruit_list, category_list, quantity_list, fruit, category):
    """
    Returns a string describing the total quantity of a specific fruit type in a given category.
    If the fruit is not found in the specified category, return "Fruit not found in category".
    """
    total_quantity = 0
    found = False
    for f, c, q in zip(fruit_list, category_list, quantity_list):
        if f == fruit and c == category:
            total_quantity += q
            found = True
    if found:
        return f"Total quantity of {fruit} in {category} category is {total_quantity}"
    else:
        return "Fruit not found in category"

