def max_non_adjacent_sum(nums):
    """
    Calculate the maximum sum of non-adjacent elements in a list of integers.

    :param nums: List of integers
    :return: Maximum sum of non-adjacent elements
    """
    if not nums:
        return 0

    if len(nums) == 1:
        return max(0, nums[0])

    if len(nums) == 2:
        return max(0, max(nums[0], nums[1]))

    incl = 0  # Sum including the current element
    excl = 0  # Sum excluding the current element

    for num in nums:
        # Current max excluding this element
        new_excl = max(incl, excl)

        # Current max including this element
        incl = excl + num

        excl = new_excl

    return max(incl, excl)

