import math

def is_fibonacci(n):
    """
    Returns True if n is a Fibonacci number, else False.
    """
    if n < 0:
        return False

    def is_perfect_square(x):
        s = int(math.sqrt(x))
        return s * s == x

    test1 = 5 * n * n + 4
    test2 = 5 * n * n - 4

    return is_perfect_square(test1) or is_perfect_square(test2)

def find_minimum(lst):
    """
    Returns the minimum value in a list of numerical values.
    If the list is empty, returns None.
    """
    if not lst:
        return None

    min_value = lst[0]
    for num in lst[1:]:
        if num < min_value:
            min_value = num
    return min_value

