def fibonacci(n):
    """
    Generates a list of Fibonacci numbers up to n (inclusive).
    """
    if n < 0:
        return "Input should be a non-negative integer"

    fib_sequence = [0, 1]

    if n == 0:
        return [0]
    elif n == 1:
        return [0, 1]

    while True:
        next_value = fib_sequence[-1] + fib_sequence[-2]
        if next_value > n:
            break
        fib_sequence.append(next_value)
    return fib_sequence

