def find_max_value(numbers):
    """
    Returns the maximum value in a list of numbers without using built-in max function.
    """
    if not numbers:
        raise ValueError("The numbers list cannot be empty")

    max_value = numbers[0]
    for num in numbers[1:]:
        if num > max_value:
            max_value = num

    return max_value

