def rotate_matrix_90_clockwise(matrix):
    """
    Rotates an n x n matrix 90 degrees clockwise in-place.
    """
    n = len(matrix)

    # First, transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Second, reverse each row
    for i in range(n):
        matrix[i].reverse()

