def reversed_string_indices(strings):
    """
    Returns a dictionary where each key is a reversed string from the input list,
    and the value is a list of original indices where the reversed version of the string appears.
    """
    reversed_indices = {}
    for i, string in enumerate(strings):
        reversed_str = string[::-1]
        if reversed_str not in reversed_indices:
            reversed_indices[reversed_str] = []
        reversed_indices[reversed_str].append(i)

    # Ensure all possible reversed strings have an empty list if they do not exist
    for string in strings:
        rev_str = string[::-1]
        if rev_str not in reversed_indices:
            reversed_indices[rev_str] = []

    return reversed_indices

