def find_common_free_time(schedules):
    """
    Find common free time intervals from multiple schedules.

    :param schedules: List of schedules. Each schedule is a list of (start, end) tuples.
    :return: List of non-overlapping intervals representing common free time.
    """
    if not schedules:
        return []

    flattened_intervals = []
    for schedule in schedules:
        for interval in schedule:
            flattened_intervals.append(interval)

    flattened_intervals.sort()

    merged_intervals = []
    for interval in flattened_intervals:
        if not merged_intervals or merged_intervals[-1][1] < interval[0]:
            merged_intervals.append(interval)
        else:
            merged_intervals[-1] = (merged_intervals[-1][0], max(merged_intervals[-1][1], interval[1]))

    full_day_interval = (0, 24)
    common_busy_times = set(tuple(interval) for interval in merged_intervals)
    common_free_times = []

    last_end = full_day_interval[0]
    for interval in merged_intervals:
        if interval[0] > last_end:
            common_free_times.append((last_end, interval[0]))
        last_end = max(last_end, interval[1])
    if last_end < full_day_interval[1]:
        common_free_times.append((last_end, full_day_interval[1]))

    return common_free_times

