from collections import Counter
import math

def prime_factors(n):
    """Returns the list of prime factors of a given number n."""
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def most_frequent_prime_factor(numbers):
    """
    Returns the most frequent prime factor among all the integers in the list.
    If there are multiple prime factors with the same highest frequency, returns the smallest one.
    If the list contains no prime factors, returns -1.
    """
    if not numbers:
        return -1

    factor_counter = Counter()
    for number in numbers:
        factors = prime_factors(number)
        factor_counter.update(factors)

    if not factor_counter:
        return -1

    max_count = max(factor_counter.values())
    most_frequent_primes = [prime for prime, count in factor_counter.items() if count == max_count]

    return min(most_frequent_primes)

