def power(b, e):
    """
    Returns b raised to the power of e using recursion.
    """
    if e == 0:
        return 1
    elif e < 0:
        return 1 / power(b, -e)
    elif e % 2 == 0:
        half_power = power(b, e // 2)
        return half_power * half_power
    else:
        return b * power(b, e - 1)

