def find_second_smallest(numbers):
    """
    Find the second smallest number in a list without using any built-in functions or sorting.
    The list will contain at least two distinct numbers.
    """
    if len(numbers) < 2:
        raise ValueError("The list must contain at least two distinct numbers")

    # Initialize the smallest and second smallest with infinity
    inf = float('inf')
    smallest = inf
    second_smallest = inf

    for number in numbers:
        if number < smallest:
            second_smallest = smallest
            smallest = number
        elif smallest < number < second_smallest:
            second_smallest = number

    if second_smallest == inf:
        raise ValueError("The list must contain at least two distinct numbers")

    return second_smallest

