def longest_sequence(bits):
    if not bits:
        return 0

    max_count = 1
    current_count = 1

    for i in range(1, len(bits)):
        if bits[i] == bits[i - 1]:
            current_count += 1
        else:
            max_count = max(max_count, current_count)
            current_count = 1

    return max(max_count, current_count)

