def is_palindrome(n):
    return str(n) == str(n)[::-1]

def is_lychrel(n, max_iterations=50):
    for _ in range(max_iterations):
        n += int(str(n)[::-1])
        if is_palindrome(n):
            return False
    return True

def create_intersection_set(list1, list2):
    """
    Returns a sorted list representing the intersection of the two input lists,
    including duplicate elements appropriately.
    """
    intersection = []
    count1 = {}
    count2 = {}

    # Count occurrences of each element in list1
    for num in list1:
        if num in count1:
            count1[num] += 1
        else:
            count1[num] = 1

    # Count occurrences of each element in list2
    for num in list2:
        if num in count2:
            count2[num] += 1
        else:
            count2[num] = 1

    # Find common elements and add the minimum occurrences to the intersection
    for num in count1:
        if num in count2:
            intersection.extend([num] * min(count1[num], count2[num]))

    # Return the sorted intersection list
    return sorted(intersection)

