def bankers_rounding(n):
    """
    Rounds a floating-point number to the nearest integer.
    If the fractional part is exactly 0.5, it rounds to the nearest even integer.
    """
    # Get integer part
    integer_part = int(n)
    # Get fractional part
    fractional_part = n - integer_part

    # Handle fractional part exactly 0.5
    if fractional_part == 0.5 or fractional_part == -0.5:
        if integer_part % 2 == 0:
            return integer_part
        else:
            return integer_part + 1 if n > 0 else integer_part - 1
    else:
        # Handle regular rounding
        return round(n)

