def sort_words_by_char_freq(input_string):
    """
    Sort words in the string based on the frequency of their characters.
    Words with same character frequency are sorted based on their original order.
    """
    def char_freq(word):
        return sum(word.count(char) for char in set(word))

    words = input_string.split()
    return " ".join(sorted(words, key=char_freq))

