import random

def roll_dice():
    """
    Simulates rolling a six-sided die.
    """
    return random.randint(1, 6)

def dice_game():
    """
    Simulates a dice roll game between a user and the computer over five rounds.
    """
    user_score = 0
    computer_score = 0

    for _ in range(5):
        user_roll = roll_dice()
        computer_roll = roll_dice()

        if user_roll > computer_roll:
            user_score += 1
        elif computer_roll > user_roll:
            computer_score += 1

    if user_score > computer_score:
        return "User wins!"
    elif computer_score > user_score:
        return "Computer wins!"
    else:
        return "It's a tie!"

