def simple_calculator(num1, num2, operator):
    """
    Perform basic arithmetic operations.

    Args:
    num1 (float): The first number.
    num2 (float): The second number.
    operator (str): The operation to perform, one of '+', '-', '*', '/'.

    Returns:
    float: The result of the arithmetic operation.
    str: Error message in case of invalid operator or division by zero.
    """
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 == 0:
            return "Error: Division by zero"
        return num1 / num2
    else:
        return "Error: Invalid operator"

