def min_insertions(source, target):
    """
    Returns the minimum number of insertions required to convert the source string to the target string.
    """
    m, n = len(source), len(target)

    # Create a DP table to store the minimum number of insertions needed
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # If source string is empty, we need to insert all characters of the target string
    for j in range(n + 1):
        dp[0][j] = j

    # Process each character of source and target strings
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if source[i - 1] == target[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = dp[i][j - 1] + 1

    return dp[m][n]

