def compute_frequencies(lst):
    """
    Computes the frequency of each unique value in the given list and returns a dictionary
    where the keys are the unique values and the values are their respective counts.

    Args:
    lst (list): The input list containing values.

    Returns:
    dict: A dictionary with the frequencies of each unique value.
    """
    frequency_dict = {}
    for item in lst:
        if item in frequency_dict:
            frequency_dict[item] += 1
        else:
            frequency_dict[item] = 1
    return frequency_dict

