def tuples_to_dict(tuples_list):
    """
    Converts a list of tuples into a dictionary with the strings as keys
    and the sum of the integers for each key as values.

    :param tuples_list: List of tuples, where each tuple contains a string and an integer.
    :return: Dictionary with strings as keys and the sum of integers as values.
    """
    result = {}
    for key, value in tuples_list:
        if key in result:
            result[key] += value
        else:
            result[key] = value
    return result

