def is_arithmetic_sequence(seq):
    """
    Checks if the given list of numbers forms an arithmetic sequence.

    Parameters:
    seq (list): A list of numbers.

    Returns:
    tuple: (boolean, str) where the boolean indicates if the list forms an arithmetic sequence,
           and the str indicates "Increasing", "Decreasing", or "Neutral".
    """
    if len(seq) < 2:
        return (True, "Neutral")

    differences = [seq[i+1] - seq[i] for i in range(len(seq) - 1)]

    if all(d == differences[0] for d in differences):
        if differences[0] > 0:
            return (True, "Increasing")
        elif differences[0] < 0:
            return (True, "Decreasing")
        else:
            return (True, "Neutral")
    else:
        return (False, "Neutral")

