def hex_char_frequency(hex_string):
    """
    Returns a dictionary with the frequency of each unique character in the hexadecimal string.
    The function ignores case and handles an empty string.
    """
    # Convert the string to uppercase to ignore case
    hex_string = hex_string.upper()
    frequency_dict = {}

    for char in hex_string:
        if char in frequency_dict:
            frequency_dict[char] += 1
        else:
            frequency_dict[char] = 1

    return frequency_dict

