def is_palindrome(s):
    """
    Helper function to check if a given string is a palindrome.
    """
    return s == s[::-1]

def largest_palindrome(s):
    """
    Function to detect the largest palindrome in a given string.
    """
    n = len(s)
    if n == 0:
        return ""

    max_palindrome = ""

    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            if is_palindrome(substr) and len(substr) > len(max_palindrome):
                max_palindrome = substr

    return max_palindrome

