def is_leap_year(year):
    """
    Checks if the given year is a leap year. Returns True for leap years and False for non-leap years.
    Validates input to check if the year is an integer and within the range 1-9999.
    """
    if not isinstance(year, int):
        raise ValueError("Year must be an integer")
    if year < 1 or year > 9999:
        raise ValueError("Year must be in the range 1-9999")

    if (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0):
        return True
    return False

