def sqrt(x):
    """
    Calculate the square root of x using the Babylonian method (also known as Heron's method).
    """
    if x < 0:
        raise ValueError("Cannot calculate the square root of a negative number.")

    if x == 0:
        return 0

    # Initial guess will be half of x
    guess = x / 2.0
    tolerance = 1e-10  # Precision tolerance
    while True:
        new_guess = (guess + x / guess) / 2
        if abs(new_guess - guess) < tolerance:
            return new_guess
        guess = new_guess

