def find_largest(numbers):
    """
    Finds the largest number in a list of integers.
    Returns None if the list is empty.
    """
    if not numbers:
        return None

    largest = numbers[0]
    for number in numbers[1:]:
        if number > largest:
            largest = number
    return largest

