def number_to_words(n):
    """
    Converts a number into its textual representation in English.
    """
    if n == 0:
        return "zero"

    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "ten", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"]

    words = []

    # Hundreds place
    if n >= 100:
        words.append(units[n // 100])
        words.append("hundred")
        n %= 100

    # Tens and units place
    if 10 < n < 20:
        words.append(teens[n - 10])
    else:
        if n >= 10:
            words.append(tens[n // 10])
            n %= 10
        if n > 0:
            words.append(units[n])

    return " ".join(word for word in words if word)

def convert_list_to_words(numbers):
    """
    Convert a list of numbers to their corresponding textual representations.
    """
    return [number_to_words(number) for number in numbers]

