def basic_calculator(a, b, operator):
    """
    Performs a basic mathematical operation between two numbers based on the given operator.

    Parameters:
    a (float): The first number.
    b (float): The second number.
    operator (str): The operator, one of '+', '-', '*', '/'.

    Returns:
    float: The result of the operation.
    str: Error message if the operation is invalid or results in division by zero.
    """
    if operator == '+':
        return a + b
    elif operator == '-':
        return a - b
    elif operator == '*':
        return a * b
    elif operator == '/':
        if b == 0:
            return "Error: Division by zero."
        return a / b
    else:
        return "Error: Invalid operator."

