def find_element(list_of_lists, element):
    """
    Checks if a given element exists in a list of lists.
    If found, returns the index of the sublist and the index of the element within that sublist.
    If not found, returns a message indicating that the element is not present.
    """
    for i, sublist in enumerate(list_of_lists):
        if element in sublist:
            return i, sublist.index(element)
    return "Element not found."

