def count_vowels_and_consonants(sentence):
    """
    Takes a sentence as input and counts the number of consonants and vowels in it.
    Also, displays the frequency of each vowel and consonant in the sentence.
    """
    vowels = "aeiou"
    consonants = "bcdfghjklmnpqrstvwxyz"

    sentence = sentence.lower()

    vowel_count = {}
    consonant_count = {}
    num_vowels = 0
    num_consonants = 0

    for char in sentence:
        if char in vowels:
            num_vowels += 1
            if char in vowel_count:
                vowel_count[char] += 1
            else:
                vowel_count[char] = 1
        elif char in consonants:
            num_consonants += 1
            if char in consonant_count:
                consonant_count[char] += 1
            else:
                consonant_count[char] = 1

    return {
        "num_vowels": num_vowels,
        "num_consonants": num_consonants,
        "vowel_frequency": vowel_count,
        "consonant_frequency": consonant_count
    }

