def create_inverted_list(input_list):
    """
    Create a dictionary where each unique element from the input list
    is a key, and the corresponding value is a list of indices
    where that element occurs in the input list.
    """
    inverted_list = {}
    for index, element in enumerate(input_list):
        if element not in inverted_list:
            inverted_list[element] = []
        inverted_list[element].append(index)
    return inverted_list

