import math

def sqrt_rounded(nums):
    """
    Returns a list where each element is the square root of the corresponding element in the input list, rounded to
    two decimal places. Raises ValueError if any element in the list is negative.
    """
    def compute_sqrt(num):
        if num < 0:
            raise ValueError("Negative number encountered. Square root not possible.")
        return round(math.sqrt(num), 2)

    return list(map(compute_sqrt, nums))

