def parse_key_value_string(input_string):
    """
    Parses a string formatted as "Key1=Value1;Key2=Value2;...;KeyN=ValueN" and returns a dictionary.

    Arguments:
    input_string (str): The input string containing key-value pairs.

    Returns:
    dict: A dictionary containing keys and their corresponding values from the input string.
    """
    if not input_string:
        return {}

    pairs = input_string.split(';')
    result = {}
    for pair in pairs:
        if '=' in pair:
            key, value = pair.split('=', 1)
            result[key] = value
    return result

