def merge_dicts(dict1, dict2):
    """
    Merges two dictionaries. If there's an overlap in keys, the value from dict2 is used.
    If both values are dictionaries, they are merged recursively.
    """
    result = dict1.copy()  # Make a copy of dict1 to avoid modifying it

    for key, value in dict2.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = merge_dicts(result[key], value)  # Recursive merge for nested dictionaries
        else:
            result[key] = value  # Overwrite or add value from dict2

    return result

