def binary_search(arr, T):
    """
    Returns the index of the target value T in the sorted array arr.
    If T is not present, returns -1.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == T:
            return mid
        elif arr[mid] < T:
            left = mid + 1
        else:
            right = mid - 1

    return -1

