def second_largest(nums):
    """
    Returns the second largest value in a list of integers, or None if not applicable.
    """
    if len(nums) < 2:
        return None

    first, second = float('-inf'), float('-inf')

    for num in nums:
        if num > first:
            second = first
            first = num
        elif first > num > second:
            second = num

    return second if second > float('-inf') else None

