def generate_primes(n):
    """
    Returns a list of the first n prime numbers.
    """
    if n < 1:
        return []

    primes = []
    candidate = 2

    while len(primes) < n:
        is_prime = True
        for prime in primes:
            if candidate % prime == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1

    return primes

