def decimal_to_binary(decimal_number):
    """
    Converts a given decimal number to a binary string.

    Parameters:
    decimal_number (int): The decimal number to be converted.

    Returns:
    str: The binary string representation of the decimal number.
    """
    if decimal_number == 0:
        return '0'
    else:
        return format(decimal_number, 'b')

