import hashlib
from solution import tensor_shape_from_string

def test_tensor_shape_from_string():
    # Known 10-character string and its expected shape
    input_string = "abcdefghij"
    expected_shape = tensor_shape_from_bytes(hashlib.sha256(input_string.encode()).digest()[:4])
    assert tensor_shape_from_string(input_string) == expected_shape

def tensor_shape_from_bytes(bytes_array):
    shape = []
    for byte in bytes_array:
        shape.append(256 if byte == 0 else byte)
    return tuple(shape)

def test_input_string_length_validation():
    try:
        tensor_shape_from_string("short")
    except ValueError as e:
        assert str(e) == "Input string must be exactly 10 characters long."

    try:
        tensor_shape_from_string("thisstringistoolong")
    except ValueError as e:
        assert str(e) == "Input string must be exactly 10 characters long."

def test_hash_output_interpretation():
    input_string = "0123456789"
    hash_bytes = hashlib.sha256(input_string.encode()).digest()[:4]
    expected_shape = tensor_shape_from_bytes(hash_bytes)
    assert tensor_shape_from_string(input_string) == expected_shape

def test_zero_byte_interpretation():
    input_string = "0000000000"
    hash_bytes = hashlib.sha256(input_string.encode()).digest()[:4]
    expected_shape = tuple(256 if b == 0 else b for b in hash_bytes)
    assert tensor_shape_from_string(input_string) == expected_shape

