def find_single_occurrence_character(string):
    """
    Returns the single occurrence character in the string, case-insensitive.
    Assumes all other characters appear twice.
    """
    string = string.lower()
    char_count = {}

    for char in string:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char, count in char_count.items():
        if count == 1:
            return char

    return None  # If no single occurrence character is found

