def simple_arithmetic_operation(num1, num2, operation):
    """
    Perform simple arithmetic operations and return the result.

    Parameters:
    num1 (int): First number
    num2 (int): Second number
    operation (str): The operation to be performed ('+', '-', '*', '/')

    Returns:
    float or str: The result of the arithmetic operation, or an error message if invalid input or division by zero.
    """
    if operation == '+':
        return num1 + num2
    elif operation == '-':
        return num1 - num2
    elif operation == '*':
        return num1 * num2
    elif operation == '/':
        if num2 == 0:
            return "Error: Division by zero"
        else:
            return num1 / num2
    else:
        return "Error: Invalid operation"

