def bubble_sort_students(students, key):
    """
    Sorts a list of student dictionaries based on a specified key using the bubble sort algorithm.

    :param students: List[Dict[str, any]] - List of student dictionaries to sort
    :param key: str - The key in the dictionary to sort by
    :return: List[Dict[str, any]] - Sorted list of student dictionaries
    """
    n = len(students)
    for i in range(n):
        for j in range(0, n - i - 1):
            if students[j][key] > students[j + 1][key]:
                students[j], students[j + 1] = students[j + 1], students[j]
    return students

