def count_unique_pairs_with_sum(arr, target_sum):
    """
    Counts the number of unique pairs (i, j) in the array such that arr[i] + arr[j] == target_sum.
    Each pair (i, j) is considered unique and should not be doubled by (j, i).
    """
    seen = set()
    pairs = set()

    for num in arr:
        complement = target_sum - num
        if complement in seen:
            pairs.add((min(num, complement), max(num, complement)))
        seen.add(num)

    return len(pairs)

