def fibonacci(n):
    """
    Returns the nth term of the Fibonacci sequence using recursion.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def char_count(s):
    """
    Takes a string s and returns a dictionary where each key is a unique character from the string
    and the value is the count of how many times the character appears in the string.
    """
    char_dict = {}
    for char in s:
        if char in char_dict:
            char_dict[char] += 1
        else:
            char_dict[char] = 1
    return char_dict

