def is_perfect_square(n):
    """
    Returns True if n is a perfect square, otherwise False.
    """
    if n < 0:
        return False

    left, right = 0, n
    while left <= right:
        mid = (left + right) // 2
        guessed_square = mid * mid

        if guessed_square == n:
            return True
        elif guessed_square < n:
            left = mid + 1
        else:
            right = mid - 1

    return False

