def max_subarray_sum(arr):
    """
    Finds the maximum sum of a contiguous subsequence in an array.

    Parameters:
    arr (list): A list of integers

    Returns:
    tuple: A tuple containing the maximum sum and the start and end indices of the subsequence
    """
    if not arr:
        return (0, 0, 0)

    max_sum = current_sum = arr[0]
    start = end = s = 0

    for i in range(1, len(arr)):
        if current_sum < 0:
            current_sum = arr[i]
            s = i
        else:
            current_sum += arr[i]

        if current_sum > max_sum:
            max_sum = current_sum
            start = s
            end = i

    return max_sum, start, end

