def find_second_highest(numbers):
    """
    Returns the second highest number in the list of unique integers.
    If the list is empty or contains only one element, returns None.
    """
    if len(numbers) < 2:
        return None

    first, second = float('-inf'), float('-inf')
    for number in numbers:
        if number > first:
            first, second = number, first
        elif first > number > second:
            second = number

    return second if second != float('-inf') else None

