def longest_increasing_subsequence(array):
    if not array:
        return [], 0

    # Initialize a table to store lengths of longest increasing subsequences
    lengths = [1] * len(array)
    # Initialize a table to store predecessors in the longest increasing subsequences
    predecessors = [None] * len(array)

    for i in range(1, len(array)):
        for j in range(i):
            if array[i] > array[j] and lengths[i] < lengths[j] + 1:
                lengths[i] = lengths[j] + 1
                predecessors[i] = j

    # Find the index of the last element in the longest increasing subsequence
    max_length_idx = max(range(len(lengths)), key=lambda i: lengths[i])

    # Reconstruct the longest increasing subsequence
    sequence = []
    while max_length_idx is not None:
        sequence.append(array[max_length_idx])
        max_length_idx = predecessors[max_length_idx]

    # Return the longest increasing subsequence in the correct order and its length
    sequence.reverse()
    return sequence, len(sequence)

