def min_steps_to_palindrome(s):
    """
    Returns the minimum number of steps required to transform string s
    into a palindrome by adding characters to the end of the string.
    """
    def is_palindrome(st):
        return st == st[::-1]

    n = len(s)
    for i in range(n):
        if is_palindrome(s[i:]):
            return i
    return n  # In the worst case, you need to add n-1 characters

