def longest_increasing_subsequence(nums):
    """
    Returns the length of the longest increasing subsequence in the given array of integers.
    """
    if not nums:
        return 0

    # Initialize the dp array with 1s, as the smallest increasing subsequence for any element is the element itself
    dp = [1] * len(nums)

    # Iterate through the array
    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest increasing subsequence will be the maximum value in the dp array
    return max(dp)

