import math

def is_prime(n):
    """
    Check if a number n is prime.

    :param n: Integer - the number to check
    :return: Boolean - True if n is prime, False otherwise
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

