def count_seeds(fruit_list):
    """
    Returns a dictionary with fruit names as keys and the total number of seeds
    for each fruit as values.

    :param fruit_list: List of tuples, where each tuple contains a fruit name (str) and
    its corresponding number of seeds (int).
    :return: Dictionary with fruit names as keys and total number of seeds as values.
    """
    seed_count = {}

    for fruit, seeds in fruit_list:
        if fruit in seed_count:
            seed_count[fruit] += seeds
        else:
            seed_count[fruit] = seeds

    return seed_count

