def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    max_divisor = int(n**0.5) + 1
    for d in range(3, max_divisor, 2):
        if n % d == 0:
            return False
    return True

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def example_function(a, b, c):
    if not (is_prime(a) and is_prime(b) and is_prime(c)):
        raise ValueError("All inputs must be prime numbers")
    return gcd(a, b) + gcd(b, c) + gcd(c, a)

