def fizzbuzz():
    """
    Prints numbers from 1 to 100, replacing multiples of 3 with 'Fizz',
    multiples of 5 with 'Buzz', and multiples of both 3 and 5 with 'FizzBuzz'.
    """
    results = []
    for i in range(1, 101):
        if i % 3 == 0 and i % 5 == 0:
            results.append("FizzBuzz")
        elif i % 3 == 0:
            results.append("Fizz")
        elif i % 5 == 0:
            results.append("Buzz")
        else:
            results.append(str(i))
    return results

