def count_word_frequencies(filename):
    """
    Reads a text file and counts the frequency of each word in the file.

    :param filename: Path to the text file.
    :return: A dictionary with words as keys and their frequencies as values.
    """
    word_frequencies = {}
    with open(filename, 'r') as file:
        for line in file:
            words = line.strip().split()
            for word in words:
                word = word.lower()  # Convert to lowercase to ensure case-insensitivity
                if word in word_frequencies:
                    word_frequencies[word] += 1
                else:
                    word_frequencies[word] = 1
    return word_frequencies

