def find_substrings(s, words):
    """
    Returns the starting indices of all substrings in `s` that are a concatenation of each word in `words`
    exactly once and without any intervening characters. The order of the words in the resulting substrings
    can be any permutation of `words`.

    Args:
    s (str): The string to search in.
    words (list of str): The list of words to concatenate.

    Returns:
    list of int: List of starting indices of the substrings in `s`.
    """
    if not s or not words or not all(words):
        return []

    word_len = len(words[0])
    words_len = len(words)
    total_len = word_len * words_len
    word_count = {word: words.count(word) for word in words}

    def is_concatenation(start):
        seen = {}
        for i in range(start, start + total_len, word_len):
            word = s[i:i+word_len]
            if word in word_count:
                seen[word] = seen.get(word, 0) + 1
                if seen[word] > word_count[word]:
                    return False
            else:
                return False
        return True

    result = []
    for i in range(len(s) - total_len + 1):
        if is_concatenation(i):
            result.append(i)

    return result

