def calculate_max_xor(L, R, k):
    """
    Calculate the maximum XOR value for a given range [L, R] such that the XOR value is less than k.
    """
    max_xor = 0
    for a in range(L, R + 1):
        for b in range(a, R + 1):
            xor_value = a ^ b
            if xor_value < k:
                max_xor = max(max_xor, xor_value)
    return max_xor

