def boyer_moore(text, pattern):
    """
    Returns a list of starting indices where the pattern is found within the text using the Boyer-Moore algorithm.
    """
    def build_last_occurrence(pattern):
        """
        Builds the last occurrence dictionary for the given pattern.
        """
        last = {}
        for i in range(len(pattern)):
            last[pattern[i]] = i
        return last

    n, m = len(text), len(pattern)

    if m == 0:
        return []

    # Edge case: If the pattern is longer than the text
    if m > n:
        return []

    last = build_last_occurrence(pattern)
    i = m - 1
    k = m - 1
    result = []

    while i < n:
        if text[i] == pattern[k]:
            if k == 0:
                result.append(i)
                i += m - min(k, 1 + last.get(text[i], -1))
                k = m - 1
            else:
                i -= 1
                k -= 1
        else:
            skip = m - min(k, 1 + last.get(text[i], -1))
            i += skip
            k = m - 1

    return result

