from collections import defaultdict

def word_squares(words):
    """
    Returns all word squares that can be formed using the words in the list.
    """
    def build_prefix_dict(words):
        prefix_dict = defaultdict(list)
        for word in words:
            for i in range(len(word)):
                prefix_dict[word[:i]].append(word)
        return prefix_dict

    def backtracking(step, word_square):
        if step == len(words[0]):
            output.append(word_square[:])
            return

        prefix = ''.join([word_square[i][step] for i in range(step)])
        for candidate in prefix_dict[prefix]:
            word_square.append(candidate)
            backtracking(step + 1, word_square)
            word_square.pop()

    prefix_dict = build_prefix_dict(words)
    output = []

    for word in words:
        backtracking(1, [word])

    return output

