def decimal_to_binary(n):
    """
    Convert a decimal number to an 8-bit binary number.
    For negative numbers, use two's complement representation.

    Parameters:
    n (int): A decimal integer

    Returns:
    str: Binary string representation of the input integer
    """
    if n >= 0:
        return format(n, '08b')
    else:
        return format((1 << 8) + n, '08b')

def longest_common_subsequence(str1, str2):
    """
    Returns the length of the longest common subsequence between two strings.
    """
    m = len(str1)
    r = len(str2)

    # Create a 2D array to store lengths of longest common subsequence
    dp = [[0] * (r + 1) for _ in range(m + 1)]

    # Fill dp array in bottom-up manner
    for i in range(m + 1):
        for j in range(r + 1):
            if i == 0 or j == 0:
                dp[i][j] = 0
            elif str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][r]

