import json

def compare_json(json1, json2):
    """
    Compares two JSON objects and returns the differences as a dictionary.

    Args:
    json1: First JSON object.
    json2: Second JSON object.

    Returns:
    Dictionary containing the differences between the JSON objects.
    """
    def find_diff(d1, d2, path=""):
        diffs = {}
        for key in d1.keys() | d2.keys():
            value1 = d1.get(key)
            value2 = d2.get(key)
            new_path = f"{path}.{key}" if path else key
            if value1 != value2:
                if isinstance(value1, dict) and isinstance(value2, dict):
                    nested_diff = find_diff(value1, value2, new_path)
                    if nested_diff:
                        diffs.update(nested_diff)
                else:
                    diffs[new_path] = (value1, value2)
        return diffs

    diff = find_diff(json1, json2)
    return diff

