def generate_primes(n):
    """
    Returns a list of prime numbers up to a given number n.
    """
    if n < 2:
        return []
    primes = []
    sieve = [True] * (n + 1)
    for p in range(2, n + 1):
        if sieve[p]:
            primes.append(p)
            for i in range(p * p, n + 1, p):
                sieve[i] = False
    return primes

