def find_duplicates(nums):
    """
    Returns a list of duplicate numbers from the given list.

    Parameters:
    nums (list): A list of integers

    Returns:
    list: A list of duplicate integers, or an empty list if none are found
    """
    seen = set()
    duplicates = set()

    for num in nums:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)

    return list(duplicates)

