def find_first_greater_than(arr, x):
    """
    Finds the index of the first element in a sorted array that is greater than x.

    Parameters:
    arr (list): A sorted list of integers.
    x (int): The specified value to compare against.

    Returns:
    int: The index of the first element greater than x, or -1 if no such element exists.
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] <= x:
            left = mid + 1
        else:
            right = mid - 1

    if left < len(arr):
        return left
    else:
        return -1

def is_prime(num):
    """
    Checks if a number is a prime number.
    """
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def generate_primes(n):
    """
    Generates a list of prime numbers up to the given number n (inclusive).
    """
    primes = []
    for i in range(2, n + 1):
        if is_prime(i):
            primes.append(i)
    return primes

