    Args:
        timestamp: The input timestamp (can be float or int).
        source: The source of the timestamp. Can be 'unix', 'windows_file_time', or 'dotnet_ticks'.
                Default is 'unix'.

    Returns:
        str: Number of milliseconds since Unix epoch as a string.
    """
    unix_epoch = datetime(1970, 1, 1)

    if source == 'unix':
        if isinstance(timestamp, (int, float)):
            milliseconds = int(timestamp * 1000)
        else:
            raise ValueError("Invalid timestamp type.")

    elif source == 'windows_file_time':
        if isinstance(timestamp, (int, float)):
            windows_epoch = datetime(1601, 1, 1)
            delta = (windows_epoch - unix_epoch).total_seconds()
            milliseconds = int((timestamp / 1e7) * 1000 + delta * 1000)
        else:
            raise ValueError("Invalid timestamp type.")

    elif source == 'dotnet_ticks':
        if isinstance(timestamp, (int, float)):
            dotnet_epoch = datetime(1, 1, 1)
            delta = (dotnet_epoch - unix_epoch).total_seconds()
            milliseconds = int((timestamp / 1e4) + delta * 1000)
        else:
            raise ValueError("Invalid timestamp type.")

    else:
        raise ValueError("Unsupported source type.")

    return str(milliseconds)

