def generate_primes(n):
    """
    Returns a list of prime numbers up to and including n.
    """
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    p = 2
    while p * p <= n:
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    prime_numbers = [p for p in range(2, n + 1) if is_prime[p]]

    return prime_numbers

