def is_prime(num):
    """Check if a number is a prime number."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_fibonacci_sequence():
    """Generate an infinite sequence of Fibonacci numbers."""
    a, b = 0, 1
    while True:
        yield b
        a, b = b, a + b

def find_fibonacci_prime(n):
    """
    Returns the nth Fibonacci number that is also prime.

    :param n: The position of the prime Fibonacci number to find.
    :type n: int
    :return: The nth prime Fibonacci number.
    :rtype: int
    """
    if n <= 0:
        raise ValueError("The input must be a positive integer.")

    prime_count = 0
    for fibonacci_number in generate_fibonacci_sequence():
        if is_prime(fibonacci_number):
            prime_count += 1
            if prime_count == n:
                return fibonacci_number

