def find_min_in_circular_sorted_array(arr):
    """
    Returns the minimum element in a circularly sorted array.

    A circularly sorted array is an array that was originally sorted in ascending order
    but then rotated.
    """
    if not arr:
        raise ValueError("Array must not be empty")

    left, right = 0, len(arr) - 1

    while left < right:
        mid = (left + right) // 2

        if arr[mid] > arr[right]:
            left = mid + 1
        else:
            right = mid

    return arr[left]

