    elif player2_roll > player1_roll:
        return 0, 1
    else:
        return 0, 0

def play_game(rounds):
    score_player1 = 0
    score_player2 = 0
    for _ in range(rounds):
        round_result = play_round()
        score_player1 += round_result[0]
        score_player2 += round_result[1]

