def wordBreak(s, wordDict):
    """
    Determines if the string s can be formed by concatenating a sequence of dictionary words.
    Each word in the dictionary can be used at most once.
    """
    def backtrack(start, memo):
        if start == len(s):
            return True
        if start in memo:
            return memo[start]

        for word in wordDict:
            end = start + len(word)
            if end <= len(s) and s[start:end] == word:
                if backtrack(end, memo):
                    memo[start] = True
                    return True

        memo[start] = False
        return False

    return backtrack(0, {})

