def apply_operator_to_list(numbers, operator):
    """
    Applies the given operator to the list of numbers sequentially.

    :param numbers: List of numbers
    :param operator: A string representing the operator ('+', '-', '*', '/')
    :return: Result of applying the operator sequentially to the numbers
    :raises ValueError: If the operator is not supported or if the list is empty
    :raises ZeroDivisionError: If division by zero occurs
    """
    if not numbers:
        raise ValueError("The list of numbers cannot be empty.")

    if operator not in ['+', '-', '*', '/']:
        raise ValueError("Unsupported operator. Choose from '+', '-', '*', '/'.")

    result = numbers[0]
    for num in numbers[1:]:
        if operator == '+':
            result += num
        elif operator == '-':
            result -= num
        elif operator == '*':
            result *= num
        elif operator == '/' and num != 0:
            result /= num
        elif operator == '/' and num == 0:
            raise ZeroDivisionError("Division by zero is not allowed.")

    return result

