def binary_search(arr, target):
    """
    Performs binary search to find the index of target in a sorted list arr.
    Returns the index of the target if found, otherwise returns -1.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

