def filter_numbers(numbers):
    """
    Filters a list of numbers, returning only those that are strictly greater than 10
    and have both their first and last digits as odd numbers.
    """
    def is_odd_digit(digit):
        return digit % 2 != 0

    def first_and_last_digits_odd(number):
        str_num = str(number)
        first_digit = int(str_num[0])
        last_digit = int(str_num[-1])
        return is_odd_digit(first_digit) and is_odd_digit(last_digit)

    return [number for number in numbers if number > 10 and first_and_last_digits_odd(number)]

