def longest_palindromic_substring(s):
    """
    Returns the longest palindromic substring in a given string.
    If there are multiple such substrings, one of them is returned.
    """
    def expand_around_center(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left+1:right]

    if not s or len(s) == 1:
        return s

    longest = ""
    for i in range(len(s)):
        # Odd length palindromes
        substring1 = expand_around_center(s, i, i)
        if len(substring1) > len(longest):
            longest = substring1

        # Even length palindromes
        substring2 = expand_around_center(s, i, i+1)
        if len(substring2) > len(longest):
            longest = substring2

    return longest

