def is_balanced(parentheses_string):
    """
    Checks if the given string of parentheses is balanced.

    :param parentheses_string: A string containing parentheses.
    :return: True if the string is balanced, False otherwise.
    """
    stack = []
    for char in parentheses_string:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

