def find_min_max(lst):
    """
    Finds the minimum and maximum of a list of integers.
    Returns a tuple (min, max). If the list is empty, returns None.
    """
    if not lst:
        return None

    min_val = max_val = lst[0]

    for num in lst:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num

    return (min_val, max_val)

