def evaluate_expression(expression_list):
    """
    Evaluates an expression defined by a list of strings.

    Parameters:
    expression_list (list): A list of strings containing numbers and operators ("+", "-", "*", "/")

    Returns:
    float: The result of the evaluated expression
    """
    stack = []
    operators = {"+", "-", "*", "/"}

    for token in expression_list:
        if token not in operators:
            stack.append(float(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                stack.append(a / b)

    return stack[0]

