def word_count(words):
    """
    Returns a dictionary where the keys are words and the values are the number of times each word
    appears in the list.

    :param words: list of words
    :return: dictionary with word frequency
    """
    word_freq = {}
    for word in words:
        if word in word_freq:
            word_freq[word] += 1
        else:
            word_freq[word] = 1
    return word_freq

