    """
    def is_prime(num):
        """ Check if a number is prime """
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    # Handle small cases separately
    if n <= 1:
        return None

    # Start from the largest possible factor n and check if it's prime
    largest_factor = 1

    # Step 1: Remove the factors of 2
    while n % 2 == 0:
        largest_factor = 2
        n //= 2

    # Step 2: Remove the factors of odd numbers from 3 onwards
    factor = 3
    max_possible_factor = int(n**0.5) + 1
    while factor <= max_possible_factor:
        while n % factor == 0:
            largest_factor = factor
            n //= factor
        factor += 2

    # If n becomes a prime number and is greater than 1, then it itself is the largest prime factor
    if n > 1 and is_prime(n):
        largest_factor = n

    return largest_factor

