def count_characters(s):
    """
    Returns a dictionary with the count of each alphanumeric character in the string s, ignoring case.
    Non-alphanumeric characters are ignored.
    """
    from collections import defaultdict

    counts = defaultdict(int)

    for char in s:
        if char.isalnum():
            counts[char.lower()] += 1

    return dict(counts)

