def fibonacci_sequence(n):
    """
    Generates a Fibonacci sequence up to a given number `n` (inclusive).
    Returns it as a list.
    """
    if n < 0:
        return []
    elif n == 0:
        return [0]
    elif n == 1:
        return [0, 1]

    fib_sequence = [0, 1]
    while True:
        next_val = fib_sequence[-1] + fib_sequence[-2]
        if next_val > n:
            break
        fib_sequence.append(next_val)

    return fib_sequence

