def piecewise_linear_interpolation(x_data, y_data, query_points):
    """
    Performs piecewise linear interpolation for the given data points and query points.

    :param x_data: List of x-coordinates of the data points
    :param y_data: List of y-coordinates of the data points
    :param query_points: List of x-coordinates where interpolation is required
    :return: List of interpolated y-values at the query points
    """
    def interpolate(x0, y0, x1, y1, x):
        """
        Linear interpolation formula between two points (x0, y0) and (x1, y1)
        to find the y value at x.
        """
        return y0 + (y1 - y0) * ((x - x0) / (x1 - x0))

    interpolated_values = []
    for qp in query_points:
        if qp <= x_data[0]:
            interpolated_values.append(y_data[0])
        elif qp >= x_data[-1]:
            interpolated_values.append(y_data[-1])
        else:
            for i in range(1, len(x_data)):
                if x_data[i-1] <= qp <= x_data[i]:
                    interpolated_values.append(interpolate(x_data[i-1], y_data[i-1], x_data[i], y_data[i], qp))
                    break
    return interpolated_values

