def count_letters(s):
    """
    Counts the frequency of each alphabet character in the given string s, ignoring case and non-alphabetic characters.

    Parameters:
    s (str): The input string.

    Returns:
    dict: A dictionary where the keys are characters and the values are the counts.
    """
    s = s.lower()
    letter_counts = {}
    for char in s:
        if char.isalpha():
            if char in letter_counts:
                letter_counts[char] += 1
            else:
                letter_counts[char] = 1

    return letter_counts

