def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest increasing subsequence in the list `arr`.
    Uses dynamic programming to solve the problem.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

