import random

def roll_die():
    """
    Simulates rolling a six-sided die.
    Returns a number between 1 and 6.
    """
    return random.randint(1, 6)

def play_round():
    """
    Simulates a round of the dice game where two players roll a die.
    Returns the winner of the round: 1 if player 1 wins, 2 if player 2 wins, 0 if it's a draw.
    """
    player1_roll = roll_die()
    player2_roll = roll_die()

    if player1_roll > player2_roll:
        return 1
    elif player2_roll > player1_roll:
        return 2
    else:
        return 0

def play_game():
    """
    Simulates a dice game where two players play until one wins three rounds.
    Returns the winner of the game: 1 if player 1 wins, 2 if player 2 wins.
    """
    player1_wins = 0
    player2_wins = 0

    while player1_wins < 3 and player2_wins < 3:
        result = play_round()
        if result == 1:
            player1_wins += 1
        elif result == 2:
            player2_wins += 1

    if player1_wins == 3:
        return 1
    else:
        return 2

