def find_max_recursive(numbers):
    """
    Returns the maximum number in the list using recursion.
    If numbers is empty, returns None.
    """
    if not numbers:
        return None
    if len(numbers) == 1:
        return numbers[0]
    else:
        max_of_rest = find_max_recursive(numbers[1:])
        return numbers[0] if numbers[0] > max_of_rest else max_of_rest

