def parse_interval(interval_str):
    """
    Takes a string representing a numerical interval and converts it into a tuple of integers.

    Parameters:
    interval_str (string): A string in the format "start-end" where both start and end are non-negative integers.

    Returns:
    tuple: A tuple of two integers (start, end).

    Raises:
    ValueError: If the input string does not match the expected format or contains negative integers.
    TypeError: If the input is not a string.
    """
    if not isinstance(interval_str, str):
        raise TypeError("Input must be a string")

    parts = interval_str.split('-')
    if len(parts) != 2:
        raise ValueError("Input string must be in the format 'start-end'")

    try:
        start = int(parts[0])
        end = int(parts[1])
    except ValueError:
        raise ValueError("Start and end must be non-negative integers")

    if start < 0 or end < 0:
        raise ValueError("Start and end must be non-negative integers")

    return (start, end)

