def count_characters_in_file(filename):
    """
    Counts the occurrences of each character in the specified file.

    :param filename: The name of the file to read.
    :return: A dictionary with characters as keys and their counts as values.
    """
    char_count = {}
    try:
        with open(filename, 'r') as file:
            content = file.read()
            for char in content:
                if char in char_count:
                    char_count[char] += 1
                else:
                    char_count[char] = 1
    except FileNotFoundError:
        return None
    return char_count

