def count_vowels_and_consonants(s):
    """
    Returns the count of vowels and consonants in the given string.
    Non-alphabetic characters are ignored.

    Parameters:
    s (str): input string

    Returns:
    tuple: (number of vowels, number of consonants)
    """
    vowels = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    vowel_count = 0
    consonant_count = 0

    for char in s:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1

    return vowel_count, consonant_count

