import random

def roll_die():
    """
    Simulates rolling a six-sided die and returns the result.
    """
    return random.randint(1, 6)

def play_round():
    """
    Simulates a round of dice for two players and returns the winner.
    Returns 'Player 1', 'Player 2', or 'Tie'.
    """
    player1_roll = roll_die()
    player2_roll = roll_die()

    if player1_roll > player2_roll:
        return 'Player 1'
    elif player2_roll > player1_roll:
        return 'Player 2'
    else:
        return 'Tie'

def play_game(rounds):
    """
    Simulates a multiple round dice game.

    Parameters:
    rounds (int): Number of rounds to play

    Returns:
    dict: The number of rounds won by each player and ties
    """
    scores = {'Player 1': 0, 'Player 2': 0, 'Tie': 0}

    for _ in range(rounds):
        winner = play_round()
        scores[winner] += 1
        print(f'Round result: {winner}')

    print(f'Final scores: {scores}')

    if scores['Player 1'] > scores['Player 2']:
        return 'Player 1 wins the game'
    elif scores['Player 2'] > scores['Player 1']:
        return 'Player 2 wins the game'
    else:
        return 'The game is a tie'

