def first_missing_positive(nums):
    """
    Returns the smallest positive integer that does not appear in the list nums.
    """
    n = len(nums)

    # Replace numbers out of the range [1, n] with a placeholder (n+1)
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Use the indices to record the presence of numbers in the range [1, n]
    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            nums[num - 1] = -abs(nums[num - 1])

    # The first index with a positive value indicates the missing number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If all numbers from 1 to n are present, the next missing number is n + 1
    return n + 1

