def calculate_average(numbers):
    """
    Calculate and return the average of a list of numbers.
    Handles non-numeric values by ignoring them.
    Raises ValueError if the list is empty or contains no valid numbers.
    """
    if not numbers:
        raise ValueError("List is empty")

    valid_numbers = [num for num in numbers if isinstance(num, (int, float))]

    if not valid_numbers:
        raise ValueError("No valid numeric values in list")

    return sum(valid_numbers) / len(valid_numbers)

