def longest_common_prefix(strs):
    """
    Returns the longest common prefix string amongst an array of strings.
    If there is no common prefix, return an empty string "".
    """
    if not strs:
        return ""

    # Start by assuming the whole first string is the common prefix
    prefix = strs[0]

    for s in strs[1:]:
        while s[:len(prefix)] != prefix and prefix:
            # Reduce the prefix length by one until a common prefix is found
            prefix = prefix[:-1]

        if not prefix:
            break

    return prefix

