def first_missing_positive(nums):
    """
    Returns the first missing positive integer in the list of nums.
    """
    if not nums:
        return 1

    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i]-1] != nums[i]:
            nums[nums[i]-1], nums[i] = nums[i], nums[nums[i]-1]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

