import math

def check_perfect_square(n):
    """
    Checks if the given number n is a perfect square.
    Returns the square root if it is, otherwise returns -1.
    """
    if n < 0:
        return -1
    sqrt = int(math.sqrt(n))
    if sqrt * sqrt == n:
        return sqrt
    else:
        return -1

