def int_to_binary(n):
    """
    Converts an integer to its binary representation using recursion.

    Args:
        n (int): The integer to convert.

    Returns:
        str: The binary representation of the integer.
    """
    if n == 0:
        return "0"
    elif n == 1:
        return "1"
    else:
        return int_to_binary(n // 2) + str(n % 2)

