def permute(s):
    """
    Returns all permutations of a given string s.
    """
    if len(s) == 0:
        return ['']

    permutations = []
    stack = [(s, '')]

    while stack:
        remaining, permutation = stack.pop()

        if len(remaining) == 0:
            permutations.append(permutation)
        else:
            for i in range(len(remaining)):
                next_step_remaining = remaining[:i] + remaining[i+1:]
                next_step_permutation = permutation + remaining[i]
                stack.append((next_step_remaining, next_step_permutation))

    return permutations

