def count_unique_values(data_list, key):
    """
    Returns a dictionary with counts of unique values for a specific key in the list of dictionaries.

    Parameters:
    - data_list: List[Dict], list of dictionaries containing the data.
    - key: str, the key whose unique values should be counted.

    Returns:
    - Dict, a dictionary where the keys are the unique values found at the specified key in the
      input dictionaries and the values are their respective counts.
    """
    value_counts = {}
    for item in data_list:
        if key in item:
            value = item[key]
            if value in value_counts:
                value_counts[value] += 1
            else:
                value_counts[value] = 1
    return value_counts

