def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers up to a given number n.
    """
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    p = 2
    while (p * p <= n):
        if is_prime[p]:
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    prime_numbers = [p for p in range(2, n + 1) if is_prime[p]]
    return prime_numbers

