def sum_of_squares(numbers_str):
    """
    Returns the sum of squares of the numbers provided in the string input.
    """
    if not numbers_str:
        return 0

    numbers_list = numbers_str.split(',')
    sum_squares = 0
    for number in numbers_list:
        try:
            num = int(number)
            sum_squares += num ** 2
        except ValueError:
            pass
    return sum_squares

