def find_first_and_last(arr, x):
    """
    Returns the index of the first and last occurrence of x in a sorted list arr.
    If x is not found, returns (-1, -1).
    """
    def binary_search(arr, x, find_first):
        """
        Helper function to perform binary search to find the first or last occurrence of x.
        If find_first is True, finds the first occurrence. Otherwise, finds the last occurrence.
        """
        low, high = 0, len(arr) - 1
        result = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == x:
                result = mid
                if find_first:
                    high = mid - 1
                else:
                    low = mid + 1
            elif arr[mid] < x:
                low = mid + 1
            else:
                high = mid - 1
        return result

    first = binary_search(arr, x, True)
    last = binary_search(arr, x, False)

    return (first, last)

