def frequency_dict(lst):
    """
    Takes a list of integers and returns a dictionary where the keys are the unique integers
    in the list and the values are their respective frequencies.
    """
    freq_dict = {}
    for item in lst:
        if item in freq_dict:
            freq_dict[item] += 1
        else:
            freq_dict[item] = 1
    return freq_dict

