def fibonacci_sequence(n):
    """
    Returns the Fibonacci sequence up to the number n using recursion.
    If n is less than 0, it returns an error message.
    """
    if n < 0:
        return "Error: n should be a non-negative integer."

    def fib_recursive(x):
        if x <= 1:
            return x
        else:
            return fib_recursive(x-1) + fib_recursive(x-2)

    sequence = []
    for i in range(n + 1):
        sequence.append(fib_recursive(i))

    return sequence

