def find_longest_path(graph):
    def dfs(node, visited):
        visited.add(node)
        max_length = 0

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                max_length = max(max_length, 1 + dfs(neighbor, visited))

        visited.remove(node)
        return max_length

    longest_path = 0
    for node in graph:
        longest_path = max(longest_path, dfs(node, set()))

    return longest_path

