def unique_prime_factors(n):
    """
    Returns the unique prime factors of a given number n in a sorted list.

    Parameters:
    n (int): The number to find the unique prime factors of.

    Returns:
    List[int]: A sorted list of unique prime factors.
    """
    def is_prime(p):
        if p <= 1:
            return False
        for i in range(2, int(p**0.5) + 1):
            if p % i == 0:
                return False
        return True

    factors = set()
    for i in range(2, n + 1):
        if n % i == 0 and is_prime(i):
            factors.add(i)

    return sorted(factors)

