def fibonacci_series(n):
    """
    Returns the Fibonacci series up to the nth term using recursion.
    """
    def fibonacci_recursive(m):
        if m <= 0:
            return []
        elif m == 1:
            return [0]
        elif m == 2:
            return [0, 1]
        else:
            series = fibonacci_recursive(m - 1)
            return series + [series[-1] + series[-2]]

    return fibonacci_recursive(n)

