def count_unique_words(filepath):
    """
    Returns the total number of unique words in the given text file.
    """
    unique_words = set()

    with open(filepath, 'r') as file:
        for line in file:
            words = line.split()
            for word in words:
                unique_words.add(word.lower().strip(".,!?:;\"'"))

    return len(unique_words)

