def decimal_to_binary(n):
    """
    Converts a given decimal number to its binary representation.
    If the number is negative, returns its two's complement representation for an 8-bit number.
    """
    if n >= 0:
        return bin(n)[2:].zfill(8)
    else:
        return bin(n & 0b11111111)[2:].zfill(8)

