def group_by_suffix(words):
    """
    Groups words by their suffix.

    Parameters:
    words (list): A list of words to be grouped by suffix.

    Returns:
    dict: A dictionary where keys are suffixes and values are lists of words with that suffix.
    """
    suffix_dict = {}
    for word in words:
        for i in range(len(word)):
            suffix = word[i:]
            if suffix in suffix_dict:
                suffix_dict[suffix].append(word)
            else:
                suffix_dict[suffix] = [word]
    return suffix_dict

