import random

def roll_dice():
    """Simulates rolling two dice and returns the sum of their values."""
    return random.randint(1, 6) + random.randint(1, 6)

def simulate_game(rounds=1000):
    """
    Simulate a dice game between two players for a given number of rounds.
    Returns the results as a dictionary containing wins, losses, and ties for both players.
    """
    results = {
        "Player 1 Wins": 0,
        "Player 2 Wins": 0,
        "Ties": 0
    }

    for _ in range(rounds):
        player1_roll = roll_dice()
        player2_roll = roll_dice()

        if player1_roll > player2_roll:
            results["Player 1 Wins"] += 1
        elif player2_roll > player1_roll:
            results["Player 2 Wins"] += 1
        else:
            results["Ties"] += 1

    return results

