def int_to_hex(n):
    """
    Converts a given integer to its hexadecimal representation as a string,
    handling both positive and negative integers.
    """
    hex_chars = "0123456789abcdef"
    if n == 0:
        return "0"
    if n < 0:
        return "-" + int_to_hex(-n)

    hex_str = ""
    while n > 0:
        hex_str = hex_chars[n % 16] + hex_str
        n //= 16

    return hex_str

def is_prime(num):
    """
    Determines whether a given number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def primes_in_range(n, m):
    """
    Returns a list of all prime numbers within the range [n, m].
    """
    return [num for num in range(n, m + 1) if is_prime(num)]

