def fibonacci_sequence(n):
    """
    Returns a list of Fibonacci numbers up to a given number n.
    """
    if n <= 0:
        return []
    sequence = [0, 1]
    while True:
        next_value = sequence[-1] + sequence[-2]
        if next_value >= n:
            break
        sequence.append(next_value)
    return sequence

