def parallel_resistance(*resistances):
    """
    Calculate the total resistance of resistors connected in parallel.

    :param resistances: A list of resistor values in ohms.
    :return: The total parallel resistance in ohms.
    """
    if not resistances:
        return 0

    reciprocal_sum = sum(1 / r for r in resistances if r != 0)
    if reciprocal_sum == 0:
        return float('inf')

    return 1 / reciprocal_sum

