def char_count(s):
    """
    Takes a string input and returns a dictionary with the unique characters
    as keys and the counts of how many times each character appears in the string as values.
    """
    count_dict = {}
    for char in s:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1
    return count_dict

