def first_duplicate(nums):
    """
    Finds the first duplicate number in a list of integers.
    Returns the first duplicate number encountered or None if there are no duplicates.
    """
    seen = set()
    for num in nums:
        if num in seen:
            return num
        else:
            seen.add(num)
    return None

