def remove_nested_parentheses(s):
    """
    Removes all nested parentheses and their contents from the string s.
    """
    stack = []
    result = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
        elif not stack:
            result.append(char)

    return ''.join(result)

