def outer_function(a, b):
    """
    Returns the product of a and b if both are positive. Otherwise, returns the sum of a and b.

    This function demonstrates the use of a local function defined within an outer function.
    """

    def inner_function(x, y):
        return x * y

    if a > 0 and b > 0:
        return inner_function(a, b)
    else:
        return a + b

