def check_int(func):
    def wrapper(*args, **kwargs):
        if len(args) > 0:
            first_arg = args[0]
        elif 'x' in kwargs:
            first_arg = kwargs['x']
        else:
            raise TypeError("First argument missing")

        if not isinstance(first_arg, int):
            raise TypeError("First argument must be an integer")
        return func(*args, **kwargs)
    return wrapper

