def custom_split(s):
    """
    Converts a string into a list of words considering spaces, commas, and periods as delimiters.

    :param s: The input string
    :return: A list of words
    """
    delimiters = {' ', ',', '.'}
    word = ""
    words = []

    for char in s:
        if char in delimiters:
            if word:
                words.append(word)
                word = ""
        else:
            word += char

    if word:
        words.append(word)

    return words

