def city_population(tuples_list):
    """
    Takes a list of tuples where each tuple contains a city name and its population.
    Returns a dictionary where the keys are the city names and the values are the total populations.
    """
    population_dict = {}
    for city, population in tuples_list:
        if city in population_dict:
            population_dict[city] += population
        else:
            population_dict[city] = population
    return population_dict

