def snake_to_camel(snake_str):
    """
    Helper function to convert a snake_case string to camelCase.
    """
    components = snake_str.split('_')
    return components[0] + ''.join(x.title() for x in components[1:])

def convert_dict_key_to_camel_case(d):
    """
    Function to convert all string keys in a nested dictionary from snake_case to camelCase.
    """
    if isinstance(d, dict):
        new_dict = {}
        for k, v in d.items():
            new_key = snake_to_camel(k) if isinstance(k, str) else k
            new_dict[new_key] = convert_dict_key_to_camel_case(v)
        return new_dict
    elif isinstance(d, list):
        return [convert_dict_key_to_camel_case(e) for e in d]
    else:
        return d

