def count_string_occurrences(strings):
    """
    Takes a list of strings and returns a dictionary with the count of occurrences
    of each unique string.

    Args:
    strings (list): A list of strings.

    Returns:
    dict: A dictionary with strings as keys and their counts as values.
    """
    counts = {}
    for string in strings:
        if string in counts:
            counts[string] += 1
        else:
            counts[string] = 1
    return counts

