def is_prime(n):
    """
    Checks if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True


def sum_of_primes(start, end):
    """
    Returns the sum of all prime numbers within the given range [start, end].
    """
    if start > end:
        raise ValueError("Start of the range should not be greater than the end of the range")
    return sum(n for n in range(start, end + 1) if is_prime(n))

