def sum_list(numbers):
    """
    Returns the sum of a list of numbers. Handles both integers and floating-point numbers.
    Raises a ValueError for non-numeric inputs.
    """
    total = 0
    for number in numbers:
        if isinstance(number, (int, float)):
            total += number
        else:
            raise ValueError(f"Non-numeric input found: {number}")
    return total

