def sort_by_vowels(strings):
    """
    Sorts the given list of strings based on the number of vowels in each string.

    :param strings: List of strings to be sorted.
    :return: List of strings sorted based on the number of vowels in each string.
    """
    def count_vowels(s):
        return sum(1 for char in s.lower() if char in 'aeiou')

    return sorted(strings, key=count_vowels)

