    """
    if operator == '+':
        return num1 + num2
    elif operator == '-':
        return num1 - num2
    elif operator == '*':
        return num1 * num2
    elif operator == '/':
        if num2 != 0:
            return num1 / num2
        else:
            return "Error: Division by zero"
    else:
        return "Error: Invalid operator"

def linear_search(arr, target):
    """
    Perform a linear search to find the index of target in the list arr.
    If the target is not found in the list, return -1.

    Time Complexity: O(n), where n is the number of elements in the input list.
    """
    for i in range(len(arr)):
        if arr[i] == target:
            return i
    return -1

