def max_profit_with_k_transactions(n, prices):
    if not prices or n == 0:
        return [0] * len(prices)

    profits = [[0] * len(prices) for _ in range(n + 1)]

    for k in range(1, n + 1):
        max_diff = -prices[0]
        for i in range(1, len(prices)):
            profits[k][i] = max(profits[k][i - 1], prices[i] + max_diff)
            max_diff = max(max_diff, profits[k - 1][i] - prices[i])

    return [profits[n][i] for i in range(len(prices))]

