def character_count(s):
    """
    Returns a dictionary with the count of each character in string s,
    ignoring spaces and case sensitivity.
    """
    s = s.replace(" ", "").lower()
    count_dict = {}
    for char in s:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1
    return count_dict

