def count_special_words(words):
    """
    Returns the count of strings that start and end with a digit after stripping leading and trailing whitespaces.
    """
    count = 0
    for word in words:
        stripped_word = word.strip()
        if stripped_word and stripped_word[0].isdigit() and stripped_word[-1].isdigit():
            count += 1
    return count

