import re

def can_be_palindrome(s):
    """
    Determine if a given input string can be rearranged into a palindrome.
    The function is case insensitive and ignores spaces and punctuation.
    """
    # Remove spaces and non-alphanumeric characters, and convert to lowercase
    clean_s = re.sub(r'[^a-zA-Z0-9]', '', s).lower()

    char_counts = {}
    for c in clean_s:
        if c in char_counts:
            char_counts[c] += 1
        else:
            char_counts[c] = 1

    odd_count = 0
    for c in char_counts:
        if char_counts[c] % 2 != 0:
            odd_count += 1
        if odd_count > 1:
            return False
    return True

