def sum_nested_list(nested_list):
    """
    This function takes a nested list structure which can contain integers, floats,
    and other lists nested at any depth, and returns the sum of all integers in that structure.
    """
    total_sum = 0

    for element in nested_list:
        if isinstance(element, int):
            total_sum += element
        elif isinstance(element, float):
            continue  # skip the floats
        elif isinstance(element, list):
            total_sum += sum_nested_list(element)  # recursive call for nested list

    return total_sum

