def count_vowels(s):
    """
    Counts the number of each vowel in the string s.
    Returns a dictionary mapping each vowel to its count.
    """
    vowels = 'aeiouAEIOU'
    vowel_count = {v: 0 for v in vowels}

    for char in s:
        if char in vowel_count:
            vowel_count[char] += 1

    return {v: count for v, count in vowel_count.items() if count > 0}

