def is_prime(num):
    """
    Checks if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    p = 3
    while p * p <= num:
        if num % p == 0:
            return False
        p += 2
    return True

def first_n_primes(n):
    """
    Returns a list containing the first n prime numbers.
    """
    primes = []
    current_number = 2
    while len(primes) < n:
        if is_prime(current_number):
            primes.append(current_number)
        current_number += 1
    return primes

