def caesar_cipher(s, shift):
    """
    Encrypts the string 's' using a Caesar cipher with a shift of 'shift'.
    Non-letter characters are not changed.
    """
    result = []

    for char in s:
        if char.isupper():
            # Encrypt uppercase characters
            result.append(chr(((ord(char) - 65 + shift) % 26) + 65))
        elif char.islower():
            # Encrypt lowercase characters
            result.append(chr(((ord(char) - 97 + shift) % 26) + 97))
        else:
            # Non-letter characters are unchanged
            result.append(char)

    return ''.join(result)

def categorize_palindromes(strings):
    """
    Categorizes palindromes from a list of strings into 'even' and 'odd' length groups.

    Args:
    strings (list): A list of strings to be categorized.

    Returns:
    dict: A dictionary with keys 'even' and 'odd' containing lists of palindromes with corresponding lengths.
    """
    result = {'even': [], 'odd': []}

    for s in strings:
        if s == s[::-1]:  # Check if string is a palindrome
            if len(s) % 2 == 0:
                result['even'].append(s)
            else:
                result['odd'].append(s)

    return result

