def count_occurrences(lst):
    """
    Takes a list of integers and returns a dictionary with the counts of those integers.

    Args:
    lst (list): List of integers.

    Returns:
    dict: A dictionary where keys are integers and values are their respective counts.
    """
    if not all(isinstance(x, int) for x in lst):
        raise ValueError("All elements in the list must be integers")

    occurrence_dict = {}
    for number in lst:
        if number in occurrence_dict:
            occurrence_dict[number] += 1
        else:
            occurrence_dict[number] = 1
    return occurrence_dict

