def create_sierpinski_triangle(height):
    """
    Generates a Sierpinski triangle pattern up to the given height.
    """
    def sierpinski(n):
        if n == 0:
            return ["*"]
        else:
            prev = sierpinski(n - 1)
            space = " " * (2 ** (n - 1))
            return [space + line + space for line in prev] + [line + " " + line for line in prev]

    return "\n".join(sierpinski(height))

def longest_common_subsequence(seq1, seq2):
    """
    Returns the length of the longest common subsequence between two sequences.
    """
    # Create a 2D array to store the LCS lengths
    dp = [[0] * (len(seq2) + 1) for _ in range(len(seq1) + 1)]

    # Fill the dp array based on previous computed results
    for i in range(1, len(seq1) + 1):
        for j in range(1, len(seq2) + 1):
            if seq1[i - 1] == seq2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[len(seq1)][len(seq2)]

