def recursive_divide(a, b):
    """
    Divides a by b using recursion to avoid the direct use of the division operator.
    Returns the quotient.
    """
    if b == 0:
        raise ValueError("Division by zero is not allowed")

    def helper(a, b, count):
        if a < b:
            return count
        return helper(a - b, b, count + 1)

    # Handle sign difference for division result
    sign = -1 if (a < 0) ^ (b < 0) else 1
    a, b = abs(a), abs(b)

    return sign * helper(a, b, 0)

