def find_max(numbers):
    """
    Returns the maximum value in the list of numbers.

    :param numbers: List of numbers.
    :return: Maximum value in the list.
    """
    if not numbers:
        return None
    max_value = numbers[0]
    for number in numbers:
        if number > max_value:
            max_value = number
    return max_value

