def shorten_name(name):
    if not isinstance(name, str):
        raise ValueError("Input must be a string")

    words = name.split()

    if len(words) == 0:
        return ""
    elif len(words) == 1:
        return words[0][:3]
    else:
        return ''.join(word[0] for word in words)

