def is_cyclic_util(v, visited, recStack, graph):
    """
    Helper function for detecting cycle using DFS.
    """
    visited[v] = True
    recStack[v] = True

    for neighbor in graph[v]:
        if not visited[neighbor]:
            if is_cyclic_util(neighbor, visited, recStack, graph):
                return True
        elif recStack[neighbor]:
            return True

    recStack[v] = False
    return False

def is_cyclic(graph):
    """
    Function to detect cycle in a directed graph.
    Returns True if there is a cycle, False otherwise.
    """
    visited = [False] * len(graph)
    recStack = [False] * len(graph)

    for node in range(len(graph)):
        if not visited[node]:
            if is_cyclic_util(node, visited, recStack, graph):
                return True
    return False

