def fibonacci(n, memo={}):
    """
    Returns the nth term of the Fibonacci sequence using memoization.
    """
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

