def nth_fibonacci(n):
    """
    Returns the Nth term of the Fibonacci sequence using recursion.
    """
    # Base cases
    if n == 0:
        return 0
    elif n == 1:
        return 1
    # Recursive case
    else:
        return nth_fibonacci(n-1) + nth_fibonacci(n-2)

