def collect_user_input(questionnaire):
    """
    Collects user input for a given questionnaire.

    Parameters:
    questionnaire (list of dict): A list of questions where each question is a dictionary with 'question' and 'type'.

    Returns:
    dict: A dictionary containing the user's responses.
    """
    responses = {}
    for item in questionnaire:
        question = item['question']
        qtype = item['type']
        if qtype == 'text':
            response = input(question + " ")
        elif qtype == 'number':
            while True:
                try:
                    response = float(input(question + " "))
                    break
                except ValueError:
                    print("Please enter a valid number.")
        responses[question] = response
    return responses

