def powercheck(x, b):
    """
    Checks if x is a power of base b and returns a tuple of (True, exponent) if it is.
    If x is not a power of b, returns False.

    :param x: int - the number to check.
    :param b: int - the base.
    :return: tuple (bool, int) or bool
    """
    if x < 1:
        return False
    elif x == 1:
        return True, 0
    elif x == b:
        return True, 1
    elif x % b != 0:
        return False
    else:
        result = powercheck(x // b, b)
        if result == False:
            return False
        return True, result[1] + 1

