def next_integer(value):
    """
    Returns the next integer in the sequence for the given input.
    If the input is a string, it converts it to an integer first.
    If the input is neither an integer nor a string, raises a ValueError.
    """
    if isinstance(value, str):
        try:
            value = int(value)
        except ValueError:
            raise ValueError("Input string must be convertible to an integer.")
    elif not isinstance(value, int):
        raise ValueError("Input must be an integer or a string convertible to an integer.")

    return value + 1

