import math

def count_divisors(n):
    """
    Returns the number of divisors of n.
    """
    count = 0
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            if i == n // i:
                count += 1
            else:
                count += 2
    return count

def smallest_number_with_k_divisors(k):
    """
    Returns the smallest number with exactly k divisors.
    """
    n = 1
    while True:
        if count_divisors(n) == k:
            return n
        n += 1

