import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def nearest_prime_less_than(n):
    """
    Finds the nearest prime number less than the given number n.
    Returns None if no such prime number exists.
    """
    for num in range(n - 1, 1, -1):
        if is_prime(num):
            return num
    return None

def sum_of_squares(lst):
    """
    Takes a list of integers as input and returns the sum of the squares of those integers.
    If there is a non-integer in the list, a ValueError is raised.
    """
    if not all(isinstance(x, int) for x in lst):
        raise ValueError("All elements in the list must be integers")

    return sum(x ** 2 for x in lst)

