def find_anagrams(words):
    """
    Returns groups of anagrams from the list of words.

    Args:
    words (list of str): The list of words to be checked for anagrams.

    Returns:
    list of lists: A list containing groups of anagrams.
    """
    anagram_dict = {}

    for word in words:
        sorted_word = ''.join(sorted(word))
        if sorted_word in anagram_dict:
            anagram_dict[sorted_word].append(word)
        else:
            anagram_dict[sorted_word] = [word]

    return [group for group in anagram_dict.values() if len(group) > 1]

def print_perimeter_elements(arr):
    """
    Given a 2D square array, return the elements in the order of
    the perimeter, starting from the top-left corner, moving right,
    then down, then left, then up, and so on.

    :param arr: List[List[int]]
    :return: List[int]
    """
    result = []

    if not arr or not arr[0]:
        return result

    n = len(arr)

    for i in range(n):
        result.append(arr[0][i])

    for i in range(1, n):
        result.append(arr[i][n-1])

    for i in range(n-2, -1, -1):
        result.append(arr[n-1][i])

    for i in range(n-2, 0, -1):
        result.append(arr[i][0])

    if n > 2:
        for i in range(1, n-1):
            result.append(arr[1][i])

        for i in range(2, n-1):
            result.append(arr[i][n-2])

        for i in range(n-3, 0, -1):
            result.append(arr[n-2][i])

        for i in range(n-3, 1, -1):
            result.append(arr[i][1])

    return result

import subprocess
import platform

def run_ls_or_dir():
    """
    Run the 'ls' command on Unix systems and the 'dir' command on Windows systems,
    then returns the output or the error that occurred.
    """
    try:
        if platform.system() == 'Windows':
            result = subprocess.run(['dir'], shell=True, check=True, capture_output=True, text=True)
        else:
            result = subprocess.run(['ls'], check=True, capture_output=True, text=True)
        return result.stdout
    except subprocess.CalledProcessError as e:
        return f"Command failed with error: {e.stderr}"
    except Exception as e:
        return f"An unexpected error occurred: {str(e)}"

def find_minimum(numbers):
    """
    Returns the minimum value in a list of numbers.
    """
    if not numbers:
        raise ValueError("The list cannot be empty")

    min_value = numbers[0]
    for number in numbers:
        if number < min_value:
            min_value = number

    return min_value

