def word_frequency(text):
    """
    Returns a dictionary where the keys are words and the values are the frequency of those words in the input text.
    """
    words = text.split()
    frequency = {}

    for word in words:
        word = word.lower().strip('.,!?()[]{}<>":;`~')  # Normalize the word by lowercasing and stripping punctuation
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    return frequency

