import math

def has_perfect_square(numbers):
    """
    Returns True if any number in the list is a perfect square, otherwise False.
    """
    for num in numbers:
        if num >= 0:
            sqrt_num = math.isqrt(num)
            if sqrt_num * sqrt_num == num:
                return True
    return False

