from collections import deque

def can_reorder_dominoes(dominoes):
    """
    Reorders a list of dominoes such that they can be lined up in a valid sequence
    where each domino's end matches the start of the next domino.

    :param dominoes: List of tuples representing the dominoes.
    :return: The reordered list or an empty list if no valid sequence exists.
    """
    if not dominoes:
        return []

    def backtrack(path, remaining):
        if not remaining:
            return path

        last_domino = path[-1]
        for i, domino in enumerate(remaining):
            if last_domino[1] == domino[0]:
                result = backtrack(path + [domino], remaining[:i] + remaining[i+1:])
                if result:
                    return result
            elif last_domino[1] == domino[1]:
                result = backtrack(path + [(domino[1], domino[0])], remaining[:i] + remaining[i+1:])
                if result:
                    return result
        return None

    for i in range(len(dominoes)):
        result = backtrack([dominoes[i]], dominoes[:i] + dominoes[i+1:])
        if result:
            return result

    return []

