def find_left_position(nums, target):
    """
    Finds the position to insert a new number in a sorted list to maintain the sorted order.
    If the target number is already present, returns the index of the first occurrence.
    """
    low, high = 0, len(nums)
    while low < high:
        mid = (low + high) // 2
        if nums[mid] < target:
            low = mid + 1
        else:
            high = mid
    return low

