def fibonacci(n):
    """
    Returns the n-th Fibonacci number.

    :param n: non-negative integer index to calculate the Fibonacci number for.
    :return: The n-th Fibonacci number.
    """
    if n < 0:
        raise ValueError("Input cannot be negative")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

def caesar_cipher_encrypt(text, shift):
    """
    Encrypts the given text using Caesar cipher with the specified shift.
    """
    encrypted_text = []
    for char in text:
        if char.isalpha():
            shift_amount = shift % 26
            if char.islower():
                start = ord('a')
            else:
                start = ord('A')
            encrypted_text.append(chr((ord(char) - start + shift_amount) % 26 + start))
        else:
            encrypted_text.append(char)
    return ''.join(encrypted_text)

def caesar_cipher_decrypt(text, shift):
    """
    Decrypts the given text using Caesar cipher with the specified shift.
    """
    return caesar_cipher_encrypt(text, -shift)

def bubble_sort_by_length(strings):
    """
    Sorts a list of strings by their lengths using the bubble sort algorithm.

    :param strings: List of strings to sort.
    :return: List of strings sorted by length.
    """
    n = len(strings)
    for i in range(n):
        for j in range(0, n-i-1):
            if len(strings[j]) > len(strings[j+1]):
                # Swap if the element found is greater by length than the next element
                strings[j], strings[j+1] = strings[j+1], strings[j]
    return strings

