import random

def get_computer_choice():
    """
    Randomly selects rock, paper, or scissors and returns the choice.
    """
    return random.choice(['rock', 'paper', 'scissors'])

def determine_winner(player_choice, computer_choice):
    """
    Determines the winner of a rock-paper-scissors game.

    Parameters:
        player_choice (str): The player's choice.
        computer_choice (str): The computer's choice.

    Returns:
        str: The result of the game ('win', 'lose', 'draw').
    """
    winning_combinations = {
        'rock': 'scissors',
        'scissors': 'paper',
        'paper': 'rock'
    }

    if player_choice == computer_choice:
        return 'draw'
    elif winning_combinations[player_choice] == computer_choice:
        return 'win'
    else:
        return 'lose'

