def generate_product_price_dict():
    """
    Dynamically generates a dictionary where keys are product names and values are their prices,
    based on user input.

    Returns:
        dict: A dictionary with product names as keys and their prices as values.
    """
    products = {}

    while True:
        product_name = input("Enter the product name (or 'done' to finish): ")
        if product_name.lower() == 'done':
            break

        try:
            price = float(input(f"Enter the price for {product_name}: "))
        except ValueError:
            print("Invalid price. Please enter a numerical value.")
            continue

        products[product_name] = price

    return products

