def max_product_of_two(lst):
    """
    Returns the maximum product of any two numbers in the list.
    Assume the list has at least two integers.
    """
    if len(lst) < 2:
        raise ValueError("List must contain at least two integers")

    # Initialize the two largest and two smallest numbers
    max1, max2 = float('-inf'), float('-inf')
    min1, min2 = float('inf'), float('inf')

    for num in lst:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    # The maximum product can be the product of the two largest numbers or the two smallest numbers
    return max(max1 * max2, min1 * min2)

