def extract_min_max_coordinates(geo_json):
    """
    Extracts and returns the minimum and maximum values from a given JSON object
    that represents a geographical area with nested structures for different regions.

    Args:
    geo_json (dict): The JSON object representing the geographical area.

    Returns:
    tuple: A tuple containing two elements - minimum and maximum values of the geographical coordinates.
    """
    min_val = float('inf')
    max_val = float('-inf')

    def extract_values(data):
        nonlocal min_val, max_val
        if isinstance(data, dict):
            for value in data.values():
                extract_values(value)
        elif isinstance(data, list):
            for item in data:
                extract_values(item)
        elif isinstance(data, float):  # Checking for float which is used for coordinates
            if data < min_val:
                min_val = data
            if data > max_val:
                max_val = data

    extract_values(geo_json)

    return min_val, max_val

