def encrypt_message(message, shift=3):
    """
    Encrypt the given message by shifting each letter by a fixed number of positions.
    Letters wrap around if they go past 'z'. Spaces are not shifted.

    :param message: String to be encrypted
    :param shift: Number of positions each letter should be shifted (default is 3)
    :return: Encrypted string
    """
    encrypted_message = []
    for char in message:
        if char == ' ':
            encrypted_message.append(char)
        else:
            new_char = chr(((ord(char) - ord('a') + shift) % 26) + ord('a'))
            encrypted_message.append(new_char)

    return ''.join(encrypted_message)

