def count_strings(lst):
    """
    Returns a dictionary with the count of each unique string in the list.

    Args:
    lst (list): A list of strings.

    Returns:
    dict: A dictionary where keys are unique strings from the list and values are their counts.
    """
    counts = {}
    for string in lst:
        if string in counts:
            counts[string] += 1
        else:
            counts[string] = 1
    return counts

