def is_prime(num):
    """
    Helper function to check if a number is prime.
    """
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def next_prime(n):
    """
    Returns the smallest prime number greater than the given integer n.
    """
    candidate = n + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

