def longest_common_substring(strings):
    if not strings:
        return []

    # Step 1: Sort the strings to have the shortest string first
    strings.sort(key=len)
    shortest_string = strings[0]
    strings = strings[1:]

    def is_common(sub):
        for s in strings:
            if sub not in s:
                return False
        return True

    # Step 2: Use the binary search on substring lengths
    def search_length(length):
        substrings = set(shortest_string[i:i + length] for i in range(len(shortest_string) - length + 1))
        common_substrings = [s for s in substrings if is_common(s)]
        return common_substrings

    low, high = 0, len(shortest_string)
    result = []

    while low <= high:
        mid = (low + high) // 2
        current_common = search_length(mid)

        if current_common:
            result = current_common
            low = mid + 1
        else:
            high = mid - 1

    if not result:
        return [""]

    return result

