def character_frequency(s):
    """
    Returns a dictionary with the frequency of each character in the given string s.
    """
    freq_dict = {}
    for char in s:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1
    return freq_dict

