def test_generate_unique_color_collision():
    existing_colors = ["#ff0000", "#ff0001", "#ff0002", "#ff0003"]

    # To test the collision handling, we mock random.randint to generate an existing color first
    import random
    class RandomMock:
        def __init__(self):
            self.calls = 0

        def randint(self, a, b):
            self.calls += 1
            # On the first call, return a value that generates an existing color
            if self.calls == 1:
                return int('ff0000', 16)
            elif self.calls == 2:
                return int('ff0001', 16)
            elif self.calls == 3:
                return int('ff0002', 16)
            elif self.calls == 4:
                return int('ff0003', 16)
            else:
                # Then return a new color
                return int('abcdef', 16)

    random_backup = random.randint
    random.randint = RandomMock().randint
    try:
        new_color = generate_unique_color(existing_colors)
        assert new_color == "#abcdef"
    finally:
        random.randint = random_backup

