def add_without_plus(a, b):
    """
    Adds two numbers without using the + or - operators via bit manipulation.
    """
    MAX_INT = 0xFFFFFFFF
    MASK = 0x100000000

    while b != 0:
        a, b = (a ^ b) & MAX_INT, ((a & b) << 1) & MAX_INT

    return a if a <= 0x7FFFFFFF else ~(a ^ MAX_INT)

