def error_check(vector1, vector2):
    """
    Check if both vectors have the same length and contain only integers.
    """
    if len(vector1) != len(vector2):
        return False

    for v in vector1 + vector2:
        if not isinstance(v, int):
            return False

    return True

def calculate_dot_product(vector1, vector2):
    """
    Calculate the dot product of two vectors.
    """
    if not error_check(vector1, vector2):
        raise ValueError("Vectors must be of the same length and contain only integers.")

    return sum(a * b for a, b in zip(vector1, vector2))

