def is_palindrome(num):
    return str(num) == str(num)[::-1]

def nearest_palindrome(num):
    if num < 0:
        return None  # Negative numbers are not considered for palindromes

    # Initially check the closest number itself
    if is_palindrome(num):
        return num

    lower = num - 1
    upper = num + 1

    while True:
        if is_palindrome(lower):
            return lower
        if is_palindrome(upper):
            return upper
        lower -= 1
        upper += 1

