def fibonacci(n):
    """
    Computes the Fibonacci sequence up to a number n using a loop.

    Returns a list of Fibonacci numbers.
    """
    if n <= 0:
        return []
    if n == 1:
        return [0]

    fib_sequence = [0, 1]
    while len(fib_sequence) < n:
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])

    return fib_sequence

