def count_characters(s):
    """
    Returns a dictionary with keys as unique characters and values as their respective counts in the string.
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    return char_count

