def length_of_LIS(nums):
    """
    Returns the length of the longest increasing subsequence in the list of integers nums.

    :param nums: List of integers
    :return: Length of the longest increasing subsequence
    """
    if not nums:
        return 0

    # dp array that will store the longest increasing subsequence length at each index
    dp = [1] * len(nums)

    for i in range(1, len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

