def find_maximum(numbers):
    """
    Returns the maximum value in a list of numbers without using any built-in functions.
    """
    if not numbers:
        raise ValueError("The list is empty")

    max_value = numbers[0]
    for number in numbers[1:]:
        if number > max_value:
            max_value = number
    return max_value

