def memo_fibonacci(n, memo={}):
    """
    Returns the nth Fibonacci number using memoization.
    """
    if n in memo:
        return memo[n]
    if n <= 1:
        return n
    memo[n] = memo_fibonacci(n-1, memo) + memo_fibonacci(n-2, memo)
    return memo[n]

