def chatbot_response(message):
    """
    A simple rule-based chatbot response function.
    """
    responses = {
        "hello": "Hi there! How can I help you?",
        "how are you": "I'm just a bunch of codes, but thanks for asking!",
        "bye": "Goodbye! Have a great day!"
