def generate_json_response(data, status_code):
    """
    Generates a JSON response for a given dictionary and status code.
    Returns the response as a JSON string.
    Handles errors by returning a JSON error response with a 500 status code if any exceptions occur.
    """
    try:
        response = {
            "status_code": status_code,
            "data": data
        }
        return json.dumps(response)
    except Exception as e:
        error_response = {
            "status_code": 500,
            "error": str(e)
        }
        return json.dumps(error_response)

