def find_ranges(nums):
    """
    Takes a list of integers and returns a list of strings representing the integer ranges found in the list.
    Each string in the output list should represent a range in the format "start-end" if the range contains
    more than one consecutive integer, or just "number" if the range contains only one integer.
    """
    if not nums:
        return []

    nums.sort()
    ranges = []
    start = prev = nums[0]

    for num in nums[1:]:
        if num != prev + 1:
            if start == prev:
                ranges.append(f"{start}")
            else:
                ranges.append(f"{start}-{prev}")
            start = num
        prev = num

    if start == prev:
        ranges.append(f"{start}")
    else:
        ranges.append(f"{start}-{prev}")

    return ranges

