def string_frequencies(strings):
    """
    Returns a tuple containing the frequency of each unique string in the list.
    The tuples are in the order of their first appearance in the list.

    :param strings: List of strings
    :return: Tuple of tuples (string, frequency)
    """
    frequency_dict = {}
    for string in strings:
        if string in frequency_dict:
            frequency_dict[string] += 1
        else:
            frequency_dict[string] = 1
    return tuple((string, frequency_dict[string]) for string in frequency_dict)

