def decimal_to_hexadecimal(n):
    """
    Converts a decimal number to its hexadecimal representation.

    Parameters:
    n (int): decimal number to convert

    Returns:
    str: hexadecimal representation of the decimal number
    """
    if n == 0:
        return "0x0"
    elif n > 0:
        return hex(n)
    else:
        return "-0x" + hex(-n)[2:]

