from collections import deque, defaultdict

def topological_sort_kahn(graph):
    """
    Perform a topological sort on a directed acyclic graph (DAG) using Kahn's algorithm.

    :param graph: A dictionary representing the adjacency list of the graph.
    :return: A list representing the topological order of the nodes.
    """
    in_degree = {node: 0 for node in graph}
    for nodes in graph.values():
        for node in nodes:
            in_degree[node] += 1

    queue = deque([node for node in graph if in_degree[node] == 0])
    topo_order = []

    while queue:
        current = queue.popleft()
        topo_order.append(current)
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(topo_order) == len(graph):
        return topo_order
    else:
        raise Exception("The graph is not acyclic and cannot be topologically sorted.")

