def sort_descending(lst):
    """
    Sorts a list of integers in descending order without using built-in sort functions.
    """
    # Implementing Bubble Sort for sorting in descending order
    n = len(lst)
    for i in range(n - 1):
        for j in range(0, n - i - 1):
            if lst[j] < lst[j + 1]:
                # Swap the elements
                lst[j], lst[j + 1] = lst[j + 1], lst[j]
    return lst

