def find_max(numbers):
    """
    Returns the maximum number in a list of numbers.
    """
    if not numbers:
        return None  # Or raise an exception if empty list check is needed
    max_num = numbers[0]
    for num in numbers[1:]:
        if num > max_num:
            max_num = num
    return max_num

