def flatten_json(nested_json, parent_key='', sep='_'):
    """
    Flatten a deeply nested JSON structure where keys are concatenated to form new keys with a given separator.

    :param nested_json: Dictionary to be flattened
    :param parent_key: Prefix for the keys (used for recursion)
    :param sep: Separator character for concatenated keys
    :return: Flattened dictionary
    """
    items = []
    if isinstance(nested_json, dict):
        for k, v in nested_json.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            items.extend(flatten_json(v, new_key, sep=sep).items())
    elif isinstance(nested_json, list):
        for i, v in enumerate(nested_json):
            new_key = f"{parent_key}{sep}{i}" if parent_key else str(i)
            items.extend(flatten_json(v, new_key, sep=sep).items())
    else:
        items.append((parent_key, nested_json))
    return dict(items)

