def operate_on_list(numbers, operation, value=None):
    """
    Performs various operations on a list of numbers.

    Parameters:
    - numbers: list of integers or floats
    - operation: str, operation to perform ('add', 'multiply', 'filter')
    - value: int or float, the value to use in the operation (mandatory for 'add' and 'multiply', optional for 'filter')

    Returns:
    - list of integers or floats after the operation
    """
    if operation == 'add':
        if value is None:
            raise ValueError("Value must be provided for add operation")
        return [x + value for x in numbers]

    elif operation == 'multiply':
        if value is None:
            raise ValueError("Value must be provided for multiply operation")
        return [x * value for x in numbers]

    elif operation == 'filter':
        if value is None:
            raise ValueError("Value must be provided for filter operation")
        return [x for x in numbers if x > value]

    else:
        raise ValueError("Unsupported operation")

