def find_largest_number(arr):
    """
    Returns the largest number in the array 'arr'.

    :param arr: list of integers
    :return: the largest integer in the list
    """
    if not arr:
        raise ValueError("The array should not be empty")

    largest = arr[0]
    for number in arr[1:]:
        if number > largest:
            largest = number
    return largest

