def longest_increasing_subsequence(arr):
    """
    Function to determine the length of the longest increasing subsequence in a list of integers.
    """
    if not arr:
        return 0

    n = len(arr)
    # DP array to store the length of increasing subsequence end at each position
    lis = [1] * n

    # Calculate LIS values from arr[0] to arr[n-1]
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Return the maximum from lis array
    return max(lis)

