def fibonacci(n):
    """
    Returns the nth Fibonacci number using a recursive approach.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer.")
    if n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

