def flatten(nested_list):
    """
    Flattens a nested list of arbitrary depth.
    Example: [[1, 2, [3]], 4] -> [1, 2, 3, 4]
    """
    flattened_list = []

    def _flatten(sublist):
        for item in sublist:
            if isinstance(item, list):
                _flatten(item)
            else:
                flattened_list.append(item)

    _flatten(nested_list)
    return flattened_list

