def most_frequent_element(numbers):
    """
    Returns the most frequent element in a list of numbers.
    If there are multiple elements with the same frequency, one of them is returned.
    """
    frequency = {}

    # Count occurrences of each number
    for number in numbers:
        if number in frequency:
            frequency[number] += 1
        else:
            frequency[number] = 1

    # Find the element with the maximum frequency
    max_frequency = max(frequency.values(), default=0)
    for number, count in frequency.items():
        if count == max_frequency:
            return number

    return None  # In case the list is empty

