def nested_dict_to_tuples(nested_dict):
    """
    Converts a nested dictionary into a list of tuples where each tuple is a key-value pair.
    The tuples are ordered by the order they are encountered in the dictionary.
    """
    def extract_items(d):
        items = []
        for key, value in d.items():
            if isinstance(value, dict):
                items.extend(extract_items(value))
            else:
                items.append((key, value))
        return items

    return extract_items(nested_dict)

