def has_valid_difference(lst, k):
    """
    Returns True if the absolute difference between any two elements of the list is less than or equal to k,
    and there is at least one pair of elements with an absolute difference greater than 0.
    """
    n = len(lst)
    if n < 2:
        return False

    has_difference_greater_than_0 = False

    for i in range(n):
        for j in range(i + 1, n):
            diff = abs(lst[i] - lst[j])
            if diff > 0:
                has_difference_greater_than_0 = True
            if diff > k:
                return False

    return has_difference_greater_than_0

def count_words(text):
    """
    Takes a string as input and returns a dictionary where the keys are
    the unique words in the string and the values are the number of times
    each word appears in the string. Words are counted in a case-insensitive
    manner and common stop words are ignored.
    """
    stop_words = {"the", "and", "is", "in", "it", "of", "to", "a", "an"}
    words = text.lower().split()
    word_count = {}

    for word in words:
        word = word.strip(",.!?;:")
        if word and word not in stop_words:
            word_count[word] = word_count.get(word, 0) + 1

    return word_count

