def max_subarray_sum(nums):
    """
    Returns the maximum sum of a contiguous subarray within the list using Kadane's Algorithm.
    """
    if not nums:
        return 0

    max_current = max_global = nums[0]

    for num in nums[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

