from math import factorial

def smallest_number_with_fac(n):
    """
    Returns the smallest number whose factorial is greater than or equal to n.
    """
    def fact(x):
        return factorial(x)

    left, right = 0, n
    while left <= right:
        mid = (left + right) // 2
        if fact(mid) >= n:
            right = mid - 1
        else:
            left = mid + 1
    return left

