def max_product_of_two(arr):
    """
    Returns the maximum product of any two numbers in the list.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements")

    # Initialize the maximum and minimum variables
    max1 = max2 = float('-inf')
    min1 = min2 = float('inf')

    for num in arr:
        # Update the maximum values
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

        # Update the minimum values
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    return max(max1 * max2, min1 * min2)

