def sum_tuples(lst):
    """
    Returns a list with one tuple containing the sum of the corresponding elements of the tuples in the input list.
    """
    if not lst:
        return [(0,)]

    tuple_length = len(lst[0])
    sums = [0] * tuple_length

    for t in lst:
        for i in range(tuple_length):
            sums[i] += t[i]

    return [tuple(sums)]

