def extract_th_words_and_frequencies(file_name):
    """
    Read the file, extract words containing 'th', and calculate their frequency.

    :param file_name: Name of the file to read
    :return: A tuple containing a list of words with 'th' and a dictionary with word frequencies
    """
    try:
        with open(file_name, 'r') as file:
            text = file.read()

        words = text.split()
        th_words = [word for word in words if 'th' in word]
        word_freq = {}

        for word in th_words:
            word_freq[word] = word_freq.get(word, 0) + 1

        return th_words, word_freq

    except FileNotFoundError:
        print(f"File {file_name} not found.")
        return [], {}
    except Exception as e:
        print(f"An error occurred: {e}")
        return [], {}

