import string

def word_frequency(file_path):
    """
    Reads a file and returns a dictionary containing the frequency of each unique word.
    The function ignores common punctuation and is case-insensitive.
    """
    word_freq = {}

    with open(file_path, 'r') as file:
        for line in file:
            # Removing punctuation and converting to lower case
            translator = str.maketrans('', '', string.punctuation)
            line = line.translate(translator).lower()
            words = line.split()
            for word in words:
                if word in word_freq:
                    word_freq[word] += 1
                else:
                    word_freq[word] = 1

    return word_freq

