def char_frequency(s):
    """
    Calculates the frequency of each character in a given string, ignoring case and spaces.

    Args:
    s (str): The input string.

    Returns:
    dict: A dictionary with the frequency of each character.
    """
    frequency = {}
    for char in s.lower():
        if char.isalpha():
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1
    return frequency

