def get_grade(score):
    """
    Returns the grade corresponding to the given score.
    """
    if not 0 <= score <= 100:
        return 'Invalid score'

    ranges = {
        'A': range(85, 101),
        'B': range(70, 85),
        'C': range(55, 70),
        'D': range(40, 55),
        'F': range(0, 40)
    }

    for grade, score_range in ranges.items():
        if score in score_range:
            return grade

