import json

def custom_date_parser(date_str):
    """
    Parses a date string in the format 'YYYY-MM-DD' and returns a dictionary with year, month, and day.
    """
    year, month, day = map(int, date_str.split('-'))
    return {
        "year": year,
        "month": month,
        "day": day
    }

def custom_json_parser(input_json, custom_decoders=None):
    """
    Parses the input JSON string with custom decoders.

    :param input_json: JSON string that needs to be parsed
    :param custom_decoders: Dictionary with key as custom key and value as custom parsing function
    :return: custom parsed dictionary
    """
    def custom_decoder(obj):
        if custom_decoders:
            for key, func in custom_decoders.items():
                if key in obj:
                    obj[key] = func(obj[key])
        return obj

    return json.loads(input_json, object_hook=custom_decoder)

