def find_first_occurrence(lst, word):
    """
    Finds the first occurrence of a specific word in a list of strings.

    Parameters:
    lst (list): List of strings.
    word (str): The word to find.

    Returns:
    int: The index of the first occurrence of the word, or -1 if not found.
    """
    if not isinstance(lst, list) or not isinstance(word, str):
        raise TypeError("lst must be a list and word must be a string")

    try:
        return lst.index(word)
    except ValueError:
        return -1

