def is_power_of_four(n):
    """
    Returns True if the given integer is a power of four, False otherwise.
    """
    if n <= 0:
        return False
    while n % 4 == 0:
        n /= 4
    return n == 1

import math

def is_perfect_power(n):
    if n < 2:
        return False
    for base in range(2, int(math.sqrt(n)) + 1):
        exponent = 2
        while True:
            power = base ** exponent
            if power == n:
                return True
            if power > n:
                break
            exponent += 1
    return False

def find_all_perfect_powers(up_to):
    perfect_powers = []
    for i in range(2, up_to + 1):
        if is_perfect_power(i):
            perfect_powers.append(i)
    return perfect_powers

