import itertools

def find_missing_permutation(odds, evens):
    original_list = sorted(odds + evens)
    seen_permutations = set()

    for p in itertools.permutations(original_list):
        if p not in seen_permutations:
            seen_permutations.add(p)

            if list(p) != original_list:
                return p
    return None

