def sum_even_numbers(lst):
    """
    Returns the sum of all even numbers in the given list using recursion.
    """
    if not lst:
        return 0
    head = lst[0]
    if head % 2 == 0:
        return head + sum_even_numbers(lst[1:])
    else:
        return sum_even_numbers(lst[1:])

