def is_balanced(s):
    """
    Determines if the given string contains a balanced set of parentheses.

    Args:
    s (str): The string containing parentheses.

    Returns:
    bool: True if the parentheses are balanced, False otherwise.
    """
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if stack == [] or matching_bracket[char] != stack.pop():
                return False
        else:
            continue

    return stack == []

