def min_jumps(arr):
    """
    Returns the minimum number of jumps to reach the end of the array.
    Each element in the array represents the maximum jump length from that position.

    :param arr: List[int] - The list of integers representing the maximum jump lengths.
    :return: int - The minimum number of jumps to reach the end of the array.
    """
    n = len(arr)
    if n <= 1:
        return 0
    if arr[0] == 0:
        return float('inf')

    max_reach = arr[0]
    step = arr[0]
    jump = 1

    for i in range(1, n):
        if i == n - 1:
            return jump

        max_reach = max(max_reach, i + arr[i])
        step -= 1

        if step == 0:
            jump += 1
            if i >= max_reach:
                return float('inf')
            step = max_reach - i
    return float('inf')

