def election():
    """
    Conduct an election with a running total of votes for each candidate.
    """
    candidates = {}
    num_candidates = int(input("Enter the number of candidates: "))

    for _ in range(num_candidates):
        name = input("Enter candidate name: ")
        candidates[name] = 0

    while True:
        vote = input("Enter the candidate you wish to vote for (or 'done' to finish): ")
        if vote == 'done':
            break
        elif vote in candidates:
            candidates[vote] += 1
        else:
            print("Invalid candidate name. Please try again.")

    for candidate, votes in candidates.items():
        print(f"{candidate}: {votes} votes")

