def is_valid_sudoku(board):
    """
    Check if a partially filled Sudoku board is valid.

    :param board: 2D list representing the Sudoku board.
    :return: Boolean indicating whether the board is valid.
    """
    def is_valid_unit(unit):
        unit = [num for num in unit if num != '.']
        return len(unit) == len(set(unit))

    # Check rows
    for row in board:
        if not is_valid_unit(row):
            return False

    # Check columns
    for col in zip(*board):
        if not is_valid_unit(col):
            return False

    # Check 3x3 subgrids
    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            subgrid = [board[x][y] for x in range(i, i+3) for y in range(j, j+3)]
            if not is_valid_unit(subgrid):
                return False

    return True

