def sort_strings(string_list):
    """
    Sorts a list of strings in ascending order based on alphabetical order.

    Parameters:
    string_list (list): List of strings to be sorted.

    Returns:
    list: Sorted list of strings if input is valid.
    str: Error message if input is invalid.
    """
    if not isinstance(string_list, list):
        return "Error: Input is not a list."

    for item in string_list:
        if not isinstance(item, str):
            return "Error: All elements in the list should be strings."

    return sorted(string_list)

