def tribonacci_sequence(n):
    """
    Returns the first n terms of the Tribonacci sequence.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    elif n == 2:
        return [0, 1]
    elif n == 3:
        return [0, 1, 1]

    tribonacci = [0, 1, 1]
    for i in range(3, n):
        next_term = tribonacci[-1] + tribonacci[-2] + tribonacci[-3]
        tribonacci.append(next_term)

    return tribonacci

