def identify_shape(sides):
    """
    Identifies the geometric shape based on the number and lengths of sides.

    Parameters:
    sides (list of int): List of integers representing the lengths of the sides.

    Returns:
    str: The type of geometric shape.
    """
    if not sides:
        return "Unknown"

    # Check for square
    if len(sides) == 4 and len(set(sides)) == 1:
        return "Square"

    # Check for equilateral triangle
    if len(sides) == 3 and len(set(sides)) == 1:
        return "Equilateral Triangle"

    # Check for rectangle
    if len(sides) == 4 and len(set(sides)) == 2:
        if sides.count(sides[0]) == 2 and sides.count(sides[1]) == 2:
            return "Rectangle"

    # Check for triangle
    if len(sides) == 3 and len(set(sides)) == 2:
        return "Isosceles Triangle"

    if len(sides) == 3:
        return "Scalene Triangle"

    return "Unknown"

