def binary_search(sorted_list, target):
    """
    Perform a binary search for target in sorted_list.
    If found, returns the index of target, otherwise returns -1.
    """
    left, right = 0, len(sorted_list) - 1

    while left <= right:
        mid = left + (right - left) // 2

        if sorted_list[mid] == target:
            return mid
        elif sorted_list[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

