def multiply_values(d):
    """
    Multiplies all numeric values in the dictionary by 2.
    Handles nested dictionaries and lists recursively.
    """
    if isinstance(d, dict):
        for k, v in d.items():
            d[k] = multiply_values(v)
    elif isinstance(d, list):
        return [multiply_values(item) for item in d]
    elif isinstance(d, (int, float)):
        return d * 2
    return d

