import random

def roll_dice():
    """
    Simulates rolling a dice and returns a number between 1 and 6.
    """
    return random.randint(1, 6)

def guess_number(guess, actual):
    """
    Compares the player's guess with the actual dice roll result.
    """
    if guess == actual:
        return "Congratulations! You guessed it right."
    else:
        return f"Sorry, you guessed wrong. It was {actual}."

def play_game(guess):
    """
    Plays a game of rolling dice and guessing the number.
    """
    actual = roll_dice()
    return guess_number(guess, actual)

