def recursive_sum(n):
    """
    Returns the sum of all integers from 1 to n using recursion.

    Parameters:
    n (int): The positive integer up to which the sum is calculated.

    Returns:
    int: The sum of all integers from 1 to n.
    """
    if n <= 1:
        return n
    else:
        return n + recursive_sum(n-1)

