def first_non_repeating_char(s):
    """
    Returns the first non-repeating character in the string s.
    If no such character exists, return an empty string.
    """
    # Dictionary to store count of each character
    char_count = {}

    # Counting each character's frequency
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Finding the first character with a count of 1
    for char in s:
        if char_count[char] == 1:
            return char

    # If no non-repeating character is found, return an empty string
    return ""

