def iterative_fibonacci(n):
    """
    Returns the nth Fibonacci number using an iterative approach.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer")
    elif n == 1 or n == 2:
        return 1
    fib_1, fib_2 = 1, 1
    for i in range(3, n + 1):
        fib_1, fib_2 = fib_2, fib_1 + fib_2
    return fib_2

