def get_string_with_highest_integer(tuple_list):
    """
    Returns the string with the highest integer value from a list of tuples.

    :param tuple_list: List of tuples, where each tuple contains a string and an integer.
    :return: The string with the highest integer value, or None if the list is empty.
    """
    if not tuple_list:
        return None

    max_tuple = tuple_list[0]
    for item in tuple_list[1:]:
        if item[1] > max_tuple[1]:
            max_tuple = item

    return max_tuple[0]

