def strcmp(s1, s2):
    """
    Compares two strings lexicographically.

    Returns:
    - a negative integer if s1 < s2
    - zero if s1 == s2
    - a positive integer if s1 > s2
    """
    for c1, c2 in zip(s1, s2):
        if c1 != c2:
            return ord(c1) - ord(c2)

    # In case one string is a prefix of the other
    return len(s1) - len(s2)

