import json

def convert_list_to_json(lst):
    """
    Converts a list of strings in the format "key:value" into a JSON object.
    The values can be strings, numbers, or booleans.
    """
    result = {}
    for item in lst:
        key, value = item.split(":", 1)
        # Remove any extraneous whitespace
        key = key.strip()
        value = value.strip()

        # Try to convert to int, float, or bool
        if value.lower() in ["true", "false"]:
            value = value.lower() == "true"
        else:
            try:
                value = int(value)
            except ValueError:
                try:
                    value = float(value)
                except ValueError:
                    pass

        # Add to result dictionary
        result[key] = value

    return json.dumps(result)

import random

def is_prime(n):
    """
    Check if a number is a prime number.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def generate_prime_in_range(start, end):
    """
    Generates and returns a prime number within a given range [start, end].
    If no prime number is found within the range, returns None.
    """
    if start > end:
        return None

    primes = [num for num in range(start, end + 1) if is_prime(num)]
    if not primes:
        return None
    return random.choice(primes)

