def find_pair_with_sum(nums, target):
    """
    Returns the first pair of numbers in the list that add up to the target sum.

    :param nums: List of integers
    :param target: Target sum
    :return: A tuple containing the first pair of numbers that add up to the target sum
    """
    seen = {}
    for num in nums:
        complement = target - num
        if complement in seen:
            return (complement, num)
        seen[num] = True
    return None  # This line should not be reached as per the problem assumption

