def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def next_prime(n):
    """
    Returns the next prime number after the given number n.
    """
    if n < 2:
        return 2
    next_num = n + 1
    while not is_prime(next_num):
        next_num += 1
    return next_num

