def min_steps_to_sort(nums):
    """
    Returns the minimum number of steps required to sort the list of integers in ascending order.
    One step is defined as removing one integer from the list and inserting it anywhere in the list.
    """
    if not nums:
        return 0

    # Find the longest increasing subsequence (LIS)
    def lis_length(sequence):
        from bisect import bisect_left
        lis = []
        for num in sequence:
            pos = bisect_left(lis, num)
            if pos == len(lis):
                lis.append(num)
            else:
                lis[pos] = num
        return len(lis)

    # Calculate LIS of the list
    lis_len = lis_length(nums)

    # The minimum steps to sort the array is the total number of elements
    # minus the length of the longest increasing subsequence
    return len(nums) - lis_len

