def length_of_lis(nums):
    """
    Returns the length of the longest strictly increasing subsequence in a given list of integers.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # dp[i] will be the length of the longest increasing subsequence ending with nums[i]

    for i in range(1, n):
        for j in range(0, i):
            if nums[i] > nums[j]:  # strictly increasing condition
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

