def shortest_distance(words_list, word1, word2):
    """
    Returns the shortest distance between word1 and word2 in the list of words.
    """
    if word1 == word2:
        return 0

    min_distance = float('inf')
    index1 = index2 = -1

    for i, word in enumerate(words_list):
        if word == word1:
            index1 = i
        elif word == word2:
            index2 = i
        if index1 != -1 and index2 != -1:
            min_distance = min(min_distance, abs(index1 - index2))

    return min_distance if min_distance != float('inf') else -1

