def substring_match(a, b):
    """
    Returns the number of positions where two strings contain the same length 2 substring.
    """
    count = 0
    min_length = min(len(a), len(b))
    for i in range(min_length - 1):
        if a[i:i+2] == b[i:i+2]:
            count += 1
    return count

