def first_unique(lst):
    """
    Returns the first unique (non-repeating) element in the list.
    """
    counts = {}
    for item in lst:
        if item in counts:
            counts[item] += 1
        else:
            counts[item] = 1

    for item in lst:
        if counts[item] == 1:
            return item
    return None

