def max_non_adjacent_sum(arr):
    """
    Returns the maximum sum of a subarray where no two elements are adjacent.
    """
    n = len(arr)
    if n == 0:
        return 0
    elif n == 1:
        return max(0, arr[0])

    incl = arr[0]  # Max sum including the first element
    excl = 0       # Max sum excluding the first element

    for i in range(1, n):
        new_excl = max(incl, excl)
        incl = excl + arr[i]
        excl = new_excl

    return max(incl, excl)

