from itertools import permutations

def nth_permutation(elements, n):
    """
    Returns the nth permutation (0-indexed) of the list of elements.
    """
    sorted_elements = sorted(elements)
    all_permutations = list(permutations(sorted_elements))

    if n >= len(all_permutations):
        raise ValueError("n is out of range for the number of permutations.")

    return list(all_permutations[n])

