def find_min_in_rotated_sorted_array(nums):
    """
    Returns the minimum value in a rotated sorted array that may contain duplicates.
    """
    if not nums:
        raise ValueError("Empty list does not have a minimum value.")

    left, right = 0, len(nums) - 1
    while left < right:
        mid = (left + right) // 2

        if nums[mid] < nums[right]:
            right = mid
        elif nums[mid] > nums[right]:
            left = mid + 1
        else:
            right -= 1

    return nums[left]

