def number_to_words(n):
    """
    Convert a number into words.

    :param n: An integer number less than 1000.
    :return: A string representing the number in words.
    """
    if not 0 <= n < 1000:
        raise ValueError("The number must be between 0 and 999 inclusive.")

    under_20 = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine',
                'ten', 'eleven', 'twelve', 'thirteen', 'fourteen', 'fifteen', 'sixteen',
                'seventeen', 'eighteen', 'nineteen']
    tens = ['', '', 'twenty', 'thirty', 'forty', 'fifty', 'sixty', 'seventy', 'eighty', 'ninety']

    def two_digit_number_to_words(n):
        if n < 20:
            return under_20[n]
        else:
            return tens[n // 10] + ('' if n % 10 == 0 else '-' + under_20[n % 10])

    if n < 20:
        return under_20[n]
    if n < 100:
        return two_digit_number_to_words(n)
    return under_20[n // 100] + ' hundred' + ('' if n % 100 == 0 else ' ' + two_digit_number_to_words(n % 100))

