def common_elements(list1, list2):
    """
    Returns a list of case-insensitive common elements between list1 and list2.
    """
    set1 = {item.lower() for item in list1}
    set2 = {item.lower() for item in list2}
    common = set1.intersection(set2)
    return [item for item in list1 if item.lower() in common]

