def has_zero_sum_subsequence(nums):
    """
    Returns True if there is a subsequence of adjacent numbers that sums up to zero.
    """
    for i in range(len(nums)):
        current_sum = 0
        for j in range(i, len(nums)):
            current_sum += nums[j]
            if current_sum == 0:
                return True
    return False

