def count_factors(n):
    """
    Returns the number of distinct positive integer factors of n.
    """
    if n <= 0:
        raise ValueError("Input must be a positive integer")

    count = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            count += 1
            if i != n // i:  # To avoid counting the square root twice
                count += 1
    return count

