import math
from collections import defaultdict

def max_points_on_line(points):
    """
    Given a set of points in a 2D plane, find the number of points that lie on a straight line
    with the maximum number of points.

    :param points: List of tuples, where each tuple (x, y) represents the coordinates of a point.
    :return: Integer, maximum number of points that lie on a single straight line.
    """
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def slope(p1, p2):
        dy = p2[1] - p1[1]
        dx = p2[0] - p1[0]
        if dx == 0:
            return (0, p1[0])
        if dy == 0:
            return (p1[1], 0)
        d = gcd(dy, dx)
        return (dy // d, dx // d)

    n = len(points)
    if n <= 2:
        return n

    max_points = 0

    for i in range(n):
        slopes = defaultdict(int)
        same_point = 0
        cur_max = 0
        for j in range(n):
            if i != j:
                if points[i] == points[j]:
                    same_point += 1
                else:
                    s = slope(points[i], points[j])
                    slopes[s] += 1
                    cur_max = max(cur_max, slopes[s])
        max_points = max(max_points, cur_max + same_point + 1)

    return max_points

