def first_non_palindrome(strings):
    """
    Returns the first string that is not a palindrome, or None if all strings
    in the list are palindromes.
    """
    def is_palindrome(s):
        return s == s[::-1]

    for string in strings:
        if not is_palindrome(string):
            return string
    return None

