def find_min_max(values):
    """
    Returns a tuple containing the minimum and maximum values in the list `values`
    without using the built-in `min` and `max` functions.
    """
    if not values:
        raise ValueError("The input list is empty.")

    min_val = values[0]
    max_val = values[0]

    for value in values[1:]:
        if value < min_val:
            min_val = value
        if value > max_val:
            max_val = value

    return (min_val, max_val)

