def sum_of_primes(limit):
    """
    Returns the sum of all prime numbers up to the given limit.
    """
    if limit < 2:
        return 0

    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False
    p = 2
    while p * p <= limit:
        if sieve[p]:
            for i in range(p * p, limit + 1, p):
                sieve[i] = False
        p += 1

    return sum(p for p, is_prime in enumerate(sieve) if is_prime)

