def is_prime(n):
    """
    Determines if a given number n is a prime number.
    """
    if n <= 1:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def find_first_n_primes(n):
    """
    Finds the first n prime numbers and returns them as a list.
    """
    primes = []
    number = 2
    while len(primes) < n:
        if is_prime(number):
            primes.append(number)
        number += 1
    return primes

def first_10_primes():
    """
    Returns the first 10 prime numbers.
    """
    return find_first_n_primes(10)

def two_sum(nums, target):
    """
    Returns the indices of the two numbers in the list that add up to the target value.

    :param nums: List of integers
    :param target: Integer target value
    :return: List containing two indices
    """
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], i]
        num_to_index[num] = i

