def count_pairs_with_sum(int_list, target_sum):
    """
    Returns the number of unique pairs of integers in the list that add up to the target sum.
    """
    seen = set()
    pairs = set()

    for num in int_list:
        complement = target_sum - num
        if complement in seen:
            pairs.add(tuple(sorted((num, complement))))
        seen.add(num)

    return len(pairs)

