from typing import List

def levenshtein_distance(a: str, b: str) -> int:
    """
    Compute the Levenshtein distance between two strings a and b.
    """
    if len(a) < len(b):
        return levenshtein_distance(b, a)

    if len(b) == 0:
        return len(a)

    previous_row = range(len(b) + 1)
    for i, c1 in enumerate(a):
        current_row = [i + 1]
        for j, c2 in enumerate(b):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def find_most_similar_word(words: List[str], target: str) -> str:
    """
    Given a list of words, find the word most similar to the target word based on Levenshtein distance.
    """
    most_similar = words[0]
    min_distance = levenshtein_distance(words[0], target)

    for word in words[1:]:
        distance = levenshtein_distance(word, target)
        if distance < min_distance:
            most_similar, min_distance = word, distance

    return most_similar

