def longest_substring_with_k_distinct_chars(s, k):
    """
    Returns the length of the longest substring with at most k distinct characters.

    :param s: Input string
    :param k: Number of distinct characters allowed
    :return: Length of the longest substring with at most k distinct characters
    """
    if k == 0 or not s:
        return 0

    char_count = {}
    max_len = 0
    left = 0

    for right in range(len(s)):
        if s[right] in char_count:
            char_count[s[right]] += 1
        else:
            char_count[s[right]] = 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_len = max(max_len, right - left + 1)

    return max_len

