def max_subarray_sum(nums):
    """
    This function takes an array of integers and returns the sum of the contiguous subarray
    which has the largest sum.
    """
    if not nums:
        return 0  # Assuming that for an empty array, the maximum sum is 0.

    max_current = max_global = nums[0]

    for num in nums[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

