def first_missing_positive(nums):
    """
    Returns the first missing positive integer from the given list of integers.
    """
    n = len(nums)

    # First phase: Ensure all the numbers which are out of the range [1, n] are ignored
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Second phase: Use the index of the array to record availability of numbers in range [1, n]
    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            # Mark the presence of a number by negating the value at its corresponding index
            nums[num - 1] = -abs(nums[num - 1])

    # Third phase: The first index with a positive value indicates the missing number
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

