def two_sum(nums, target):
    """
    Given a list of integers (`nums`) and an integer (`target`),
    Returns the indices of the two numbers in `nums` that add up to `target`.
    Assumes that each input will have exactly one solution and does not use the same element twice.
    """
    num_to_index = {}
    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], index]
        num_to_index[num] = index

