def sum_list_tail_recursive(lst, accumulator=0):
    """
    Calculate the sum of all elements in the list using tail recursion.

    Parameters:
    lst (list): List of numbers to be summed.
    accumulator (int): The accumulated sum (default is 0).

    Returns:
    int: The sum of the elements in the list.
    """
    if not lst:
        return accumulator
    else:
        return sum_list_tail_recursive(lst[1:], accumulator + lst[0])

