def sieve_of_eratosthenes(max_num):
    """
    Generates a list of prime numbers up to the maximum number using the Sieve of Eratosthenes algorithm.
    """
    sieve = [True] * (max_num + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not prime numbers

    for start in range(2, int(max_num ** 0.5) + 1):
        if sieve[start]:  # If the number is prime
            for multiple in range(start*start, max_num + 1, start):
                sieve[multiple] = False

    return [num for num in range(max_num + 1) if sieve[num]]

def sum_of_primes(nums):
    """
    Returns the sum of all prime numbers in the given list of integers.
    """
    if not nums:
        return 0

    max_num = max(nums)
    primes = set(sieve_of_eratosthenes(max_num))

    return sum(num for num in nums if num in primes)

