def max_subarray_cross_sum(nums, left, mid, right):
    left_sum = float('-inf')
    right_sum = float('-inf')

    sum_temp = 0
    for i in range(mid, left - 1, -1):
        sum_temp += nums[i]
        if sum_temp > left_sum:
            left_sum = sum_temp

    sum_temp = 0
    for i in range(mid + 1, right + 1):
        sum_temp += nums[i]
        if sum_temp > right_sum:
            right_sum = sum_temp

    return left_sum + right_sum

def max_subarray_recursive(nums, left, right):
    if left == right:
        return nums[left]

    mid = (left + right) // 2

    left_sum = max_subarray_recursive(nums, left, mid)
    right_sum = max_subarray_recursive(nums, mid + 1, right)
    cross_sum = max_subarray_cross_sum(nums, left, mid, right)

    return max(left_sum, right_sum, cross_sum)

def max_subarray(nums):
    if not nums:
        return 0
    return max_subarray_recursive(nums, 0, len(nums) - 1)

