def find_duplicates(nums):
    """
    Finds the duplicate elements in an array of integers.

    Args:
        nums: A list of integers.

    Returns:
        A new list containing only the duplicate elements.
    """
    seen = set()
    duplicates = set()
    for num in nums:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)
    return list(duplicates)

