def min_nodes_to_switch_on(edges):
    from collections import defaultdict

    def dfs(node):
        visited.add(node)
        for neighbour in graph[node]:
            if neighbour not in visited:
                dfs(neighbour)

    # Construct the graph
    graph = defaultdict(list)
    nodes = set()
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
        nodes.add(u)
        nodes.add(v)

    visited = set()
    components = []

    # Find all connected components
    for node in nodes:
        if node not in visited:
            component = set()
            dfs(node)
            components.append(component)

    return len(components)

