def is_prime(n):
    """
    Helper function to determine if n is a prime number.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def prime_numbers_in_range(start, end):
    """
    Returns a list of all prime numbers between start and end (inclusive).
    """
    return [i for i in range(start, end + 1) if is_prime(i)]

