def find_substring(s, words):
    from collections import Counter

    if not s or not words:
        return []

    word_length = len(words[0])
    word_count = len(words)
    substring_length = word_length * word_count
    word_map = Counter(words)
    result = []

    for i in range(len(s) - substring_length + 1):
        seen = {}
        for j in range(word_count):
            word_index = i + j * word_length
            current_word = s[word_index : word_index + word_length]
            if current_word in word_map:
                seen[current_word] = seen.get(current_word, 0) + 1
                if seen[current_word] > word_map[current_word]:
                    break
            else:
                break
        else:
            result.append(i)

    return result

