def first_occurrence(nums, target):
    """
    Returns the index of the first occurrence of target in nums, or -1 if target is not found.
    Uses binary search for an optimized solution.
    """
    low, high = 0, len(nums) - 1

    while low <= high:
        mid = (low + high) // 2

        if nums[mid] == target:
            # Check if this is the first occurrence
            if mid == 0 or nums[mid - 1] != target:
                return mid
            else:
                high = mid - 1 # Look on the left side for the first occurrence

        elif nums[mid] < target:
            low = mid + 1

        else:
            high = mid - 1

    return -1

