def longest_valid_parentheses(s):
    """
    Returns the longest valid (well-formed) parentheses substring.

    :param s: Input string containing sequence of parentheses
    :return: Longest valid parentheses substring
    """
    max_length = 0
    stack = [-1]
    for i in range(len(s)):
        if s[i] == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    longest = ''
    valid_length = max_length

    for i in range(len(s) - max_length + 1):
        substring = s[i:i + max_length]
        if is_valid(substring):
            longest = substring
            break

    return longest

def is_valid(s):
    """
    Check if the given string is a valid parentheses string.

    :param s: String of parentheses
    :return: True if the string is valid, else False
    """
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        else:
            balance -= 1
            if balance < 0:
                return False
    return balance == 0

