def remove_duplicates(s: str) -> str:
    """
    Given a string, return a new string with all the consecutive duplicate characters removed.

    Parameters:
    s (str): The input string.

    Returns:
    str: A new string with all consecutive duplicate characters removed.
    """
    if not s:
        return s

    # Use list for efficient string concatenation
    result = [s[0]]

    for i in range(1, len(s)):
        if s[i] != s[i - 1]:
            result.append(s[i])

    return ''.join(result)

