import math

def is_prime(number):
    """
    Checks if a given number is prime.

    Args:
        number: An integer.

    Returns:
        True if the number is prime, False otherwise.
    """
    if number <= 1:
        return False
    if number == 2:
        return True  # 2 is a prime number
    if number % 2 == 0:
        return False  # handle even numbers greater than 2
    for i in range(3, int(math.sqrt(number)) + 1, 2):
        if number % i == 0:
            return False
    return True

