def calculate_grade(score, scale="standard"):
    """
    Calculate the grade based on score and the given grading scale.

    :param score: Numeric score.
    :param scale: Grading scale to use; default is "standard".
    :return: Grade as a string.
    :raises ValueError: If an invalid scale is provided.
    """
    if scale == "standard":
        if score >= 90:
            return "A"
        elif score >= 80:
            return "B"
        elif score >= 70:
            return "C"
        elif score >= 60:
            return "D"
        else:
            return "F"
    elif scale == "lenient":
        if score >= 80:
            return "A"
        elif score >= 70:
            return "B"
        elif score >= 60:
            return "C"
        else:
            return "D"
    else:
        raise ValueError("Invalid grading scale provided.")

