def count_vowels(word):
    vowels = "aeiouAEIOU"
    return sum(1 for char in word if char in vowels)

def longest_most_vowels(words):
    if not words:
        return []

    max_vowels = -1
    max_length = -1
    result = []

    for word in words:
        vowel_count = count_vowels(word)
        word_length = len(word)

        if vowel_count > max_vowels or (vowel_count == max_vowels and word_length > max_length):
            max_vowels = vowel_count
            max_length = word_length
            result = [word]
        elif vowel_count == max_vowels and word_length == max_length:
            result.append(word)

    return result

