def collatz_sequence(n):
    if not isinstance(n, int):
        raise TypeError("Input must be an integer")
    if n <= 0:
        return []
    sequence = [n]
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        sequence.append(n)
    return sequence

