def are_anagrams(strings):
    """
    Determine if the list of strings contains anagrams of each other.

    :type strings: list
    :rtype: bool
    """
    if len(strings) < 2:
        return False

    # Create a function to generate a sorted signature of a string
    def signature(s):
        return ''.join(sorted(s))

    # Generate the signature for the first string
    expected_signature = signature(strings[0])

    # Compare the signature of all strings to the expected signature
    for s in strings:
        if signature(s) != expected_signature:
            return False

    return True

