def prime_numbers_in_range(start, end):
    """
    Returns a list of all prime numbers within the range from start (inclusive) to end (inclusive).
    """
    if start < 2:
        start = 2
    primes = []
    for num in range(start, end+1):
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

