def find_first_and_last(nums, target):
    """
    Finds the first and last occurrences of a target number in a given array using binary search.

    Args:
      nums: A sorted array of integers.
      target: The target number to search for.

    Returns:
      A list containing the first and last indices of the target number,
      or [-1, -1] if the target is not found.
    """
    def binary_search_left(nums, target):
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    def binary_search_right(nums, target):
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid
        return left

    left_index = binary_search_left(nums, target)
    right_index = binary_search_right(nums, target) - 1

    if left_index <= right_index and left_index < len(nums) and nums[left_index] == target:
        return [left_index, right_index]
    else:
        return [-1, -1]

