def find_anagrams(word_list):
    """
    Takes a list of words and returns a list of lists where each inner list contains
    a pair of words that are anagrams of each other.

    :param word_list: List of words (strings)
    :return: List of lists containing pairs of anagram words
    """
    anagrams = []

    for i in range(len(word_list)):
        for j in range(i + 1, len(word_list)):
            if sorted(word_list[i]) == sorted(word_list[j]):
                anagrams.append([word_list[i], word_list[j]])
    return anagrams

import math

def calculate_area(shape, **kwargs):
    if shape == "square":
        side = kwargs.get('side')
        if side is None:
            return "Missing side length"
        area = side * side
        return area
    elif shape == "rectangle":
        length = kwargs.get('length')
        width = kwargs.get('width')
        if length is None or width is None:
            return "Missing length or width"
        area = length * width
        return area
    elif shape == "triangle":
        base = kwargs.get('base')
        height = kwargs.get('height')
        if base is None or height is None:
            return "Missing base or height"
        area = 0.5 * base * height
        return area
    elif shape == "circle":
        radius = kwargs.get('radius')
        if radius is None:
            return "Missing radius"
        area = math.pi * radius**2
        return area
    else:
        return "Invalid shape!"

