import random

def get_max_number_for_difficulty(difficulty):
    """
    Returns the max number for the specified difficulty level.
    """
    if difficulty == "easy":
        return 50
    elif difficulty == "medium":
        return 100
    elif difficulty == "hard":
        return 200
    else:
        return 100  # default to medium if invalid input

def play_game():
    """Plays a number guessing game with the user."""

    difficulty = input("Choose a difficulty level (easy, medium, hard): ")
    max_number = get_max_number_for_difficulty(difficulty)

    number = random.randint(1, max_number)
    guesses_left = 7
    print(f"Welcome to the Number Guessing Game!")
    print(f"I'm thinking of a number between 1 and {max_number}.")

    while guesses_left > 0:
        print(f"You have {guesses_left} guesses left.")
        try:
            guess = int(input("Enter your guess: "))
        except ValueError:
            print("Invalid input. Please enter a number.")
            continue

        if guess < number:
            print("Too low!")
        elif guess > number:
            print("Too high!")
        else:
            print(f"Congratulations! You guessed the number in {7-guesses_left} tries!")
            return

        guesses_left -= 1

    print(f"You ran out of guesses. The number was {number}.")

