def binary_search_recursive(arr, target, left=0, right=None):
    """
    Perform a binary search on a sorted array using recursion.

    Parameters:
    - arr: List[int] - The sorted array in which to search for the target.
    - target: int - The value to search for.
    - left: int - The left index of the search range.
    - right: int - The right index of the search range.

    Returns:
    - int: The index of the target in the array if found, otherwise -1.
    """
    if right is None:
        right = len(arr) - 1

    if left > right:
        return -1

    mid = (left + right) // 2

    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return binary_search_recursive(arr, target, mid + 1, right)
    else:
        return binary_search_recursive(arr, target, left, mid - 1)

