def is_valid_parentheses(s):
    """
    Determine if the input string of parentheses is valid.

    :param s: A string consisting of parentheses "(", ")", "[", "]", "{", "}"
    :return: True if the input string is valid, False otherwise
    """
    stack = []
    parentheses_map = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in parentheses_map:
            top_element = stack.pop() if stack else '#'
            if parentheses_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def longest_consecutive_zeros(binary_string):
    """
    Returns the length of the longest consecutive sequence of zeros in a binary string.
    """
    if not binary_string:
        return 0

    max_zeros = 0
    current_zeros = 0

    for char in binary_string:
        if char == '0':
            current_zeros += 1
            max_zeros = max(max_zeros, current_zeros)
        else:
            current_zeros = 0

    return max_zeros

