def reverse_words_iterative(s):
    """
    Returns the input string with the words in reverse order using an iterative approach.
    """
    words = s.split()
    reversed_words = words[::-1]
    return " ".join(reversed_words)

def reverse_words_recursive(s):
    """
    Returns the input string with the words in reverse order using a recursive approach.
    """
    words = s.split()

    def helper(words):
        if not words:
            return []
        return helper(words[1:]) + [words[0]]

    return " ".join(helper(words))

