from functools import lru_cache

def lcs(X, Y):
    """
    Returns the longest common subsequence of sequences X and Y.
    """
    @lru_cache(maxsize=None)
    def lcs_helper(m, n):
        if m == 0 or n == 0:
            return []
        elif X[m-1] == Y[n-1]:
            return lcs_helper(m-1, n-1) + [X[m-1]]
        else:
            left = lcs_helper(m, n-1)
            right = lcs_helper(m-1, n)
            return left if len(left) > len(right) else right

    return lcs_helper(len(X), len(Y))

def find_lcs_of_sequences(sequences):
    """
    Returns the longest common subsequence among all the input sequences.
    """
    if not sequences:
        return []

    common_lcs = sequences[0]

    for seq in sequences[1:]:
        common_lcs = lcs(common_lcs, seq)

    return common_lcs

