def findMedianSortedArrays(nums1, nums2):
    # Ensure nums1 is the smaller array, which optimizes our approach.
    if len(nums1) > len(nums2):
        nums1, nums2 = nums2, nums1

    m, n = len(nums1), len(nums2)
    if m == 0:
        # If nums1 is empty, directly find the median of nums2
        if n % 2 == 0:
            return (nums2[n//2 - 1] + nums2[n//2]) / 2
        else:
            return nums2[n//2]

    imin, imax, half_len = 0, m, (m + n + 1) // 2
    while imin <= imax:
        i = (imin + imax) // 2
        j = half_len - i
        if i < m and nums1[i] < nums2[j - 1]:
            imin = i + 1
        elif i > 0 and nums1[i - 1] > nums2[j]:
            imax = i - 1
        else:
            if i == 0:
                max_of_left = nums2[j - 1]
            elif j == 0:
                max_of_left = nums1[i - 1]
            else:
                max_of_left = max(nums1[i - 1], nums2[j - 1])

            if (m + n) % 2 == 1:
                return max_of_left

            if i == m:
                min_of_right = nums2[j]
            elif j == n:
                min_of_right = nums1[i]
            else:
                min_of_right = min(nums1[i], nums2[j])

            return (max_of_left + min_of_right) / 2

def smallest_missing_non_negative_integer(nums):
    """
    Returns the smallest non-negative integer that is not present in the list.
    """
    nums = sorted(nums)
    smallest_missing = 0
    for num in nums:
        if num == smallest_missing:
            smallest_missing += 1
    return smallest_missing

