def word_frequencies(input_string):
    """
    Returns a dictionary with words as keys and their frequencies as values.
    """
    words = input_string.split()
    frequency = {}

    for word in words:
        word = word.lower()
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    return frequency

