def longest_repetition_length(s):
    """
    Returns the length of the longest consecutive repetition of a substring in the string s.
    The length of a repetition is defined as the number of times a substring consecutively repeats itself in the string.
    """
    n = len(s)
    if n == 0:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, n):
        if s[i] == s[i - 1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
            current_length = 1

    if current_length > max_length:
        max_length = current_length

    return max_length

