def prime_factors(n):
    """
    This function takes a positive integer n and
    returns a list of its prime factors.
    """
    factors = []
    for i in range(2, int(n**0.5) + 1):
        while n % i == 0:
            factors.append(i)
            n //= i
    if n > 1:
        factors.append(n)
    return factors

