def longest_distinct_substring(s):
    """
    Returns the longest substring with distinct characters in the given string.
    """
    n = len(s)
    if n == 0:
        return ""

    start = 0
    max_length = 0
    longest_substring_start = 0
    seen = {}

    for end in range(n):
        if s[end] in seen and seen[s[end]] >= start:
            start = seen[s[end]] + 1

        seen[s[end]] = end

        if end - start + 1 > max_length:
            max_length = end - start + 1
            longest_substring_start = start

    return s[longest_substring_start:longest_substring_start + max_length]

