def simplify_path(path):
    """
    Given an absolute path, simplify it and return the canonical path.
    """
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '..':
            if stack:
                stack.pop()
        elif part and part != '.':
            stack.append(part)

    return '/' + '/'.join(stack)

