def fibonacci_recursive(n):
    """
    Returns the n-th number in the Fibonacci sequence using recursion.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n-1) + fibonacci_recursive(n-2)


def fibonacci_iterative(n):
    """
    Returns the n-th number in the Fibonacci sequence using iteration.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n+1):
            a, b = b, a + b
        return b

def binary_search(nums, target):
    """
    Performs binary search to find the index of target in nums.
    Returns the index if found, otherwise returns -1.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

def count_unique_vowels(input_string):
    """
    Returns the count of unique vowels in the given string.
    Unique vowels are a, e, i, o, u (both uppercase and lowercase are considered the same).
    """
    vowels = {'a', 'e', 'i', 'o', 'u'}
    found_vowels = set()

    for char in input_string.lower():
        if char in vowels:
            found_vowels.add(char)

    return len(found_vowels)

