def find_largest_prime(numbers):
    """
    Returns the largest prime number in the list.
    If no prime number is found, returns -1.
    """
    largest_prime = -1
    for num in numbers:
        if is_prime(num) and num > largest_prime:
            largest_prime = num
    return largest_prime

