def first_repeating_index(nums):
    """
    Returns the index of the first repeating element in the list.
    If there are no repeating elements, returns -1.
    """
    seen = {}
    for index, num in enumerate(nums):
        if num in seen:
            return index
        seen[num] = True
    return -1

def second_largest(numbers):
    """
    Returns the second-largest number in the list.
    """
    if len(numbers) < 2:
        raise ValueError("The list must contain at least two numbers.")

    first_largest = second_largest = float('-inf')

    for number in numbers:
        if number > first_largest:
            second_largest = first_largest
            first_largest = number
        elif number > second_largest and number != first_largest:
            second_largest = number

    if second_largest == float('-inf'):
        raise ValueError("The list must contain at least two unique numbers.")

    return second_largest

