def fibonacci(n):
    """
    Returns the nth Fibonacci number iteratively.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

def longest_increasing_subsequence(arr):
    """
    Finds the length of the longest increasing subsequence (LIS) in the given array.

    Args:
    arr (list): A list of positive integers.

    Returns:
    int: The length of the LIS.
    """
    if not arr:
        return 0

    n = len(arr)
    lis = [1] * n  # Initialize LIS values for all indexes to 1

    # Compute optimized LIS values in a bottom-up manner
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Return maximum value in lis[]
    return max(lis)

