def fibonacci(n):
    """
    This function returns a list containing the first n Fibonacci numbers using recursion.

    Args:
      n: An integer representing the number of Fibonacci numbers to generate.

    Returns:
      A list containing the first n Fibonacci numbers.
    """
    def fib_recur(m):
        if m <= 0:
            return 0
        elif m == 1:
            return 1
        else:
            return fib_recur(m - 1) + fib_recur(m - 2)

    fib_list = []
    for i in range(n):
        fib_list.append(fib_recur(i))

    return fib_list

def calculate_discount(price, discount):
    """
    Calculate the discounted price given the original price and discount percentage.

    :param price: original price (must be non-negative)
    :param discount: discount percentage (must be between 0 and 100)
    :return: discounted price
    """
    if price < 0 or discount < 0 or discount > 100:
        raise ValueError("Invalid price or discount value")

    return price - (price * discount / 100)

