def are_permutations(str1, str2):
    """
    Checks if two strings are permutations of each other.

    Args:
    str1 (str): First string to compare.
    str2 (str): Second string to compare.

    Returns:
    bool: True if str1 and str2 are permutations of each other, False otherwise.
    """
    # If the lengths of the strings are not the same, they can't be permutations.
    if len(str1) != len(str2):
        return False

    # Count the characters in both strings and compare the counts.
    char_count1 = {}
    char_count2 = {}

    for char in str1:
        char_count1[char] = char_count1.get(char, 0) + 1

    for char in str2:
        char_count2[char] = char_count2.get(char, 0) + 1

    return char_count1 == char_count2

