def find_path(grid):
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def dfs(row, col):
        if row == rows - 1:
            return True

        # Temporarily mark the cell as visited
        grid[row][col] = 'V'

        # Directions: Down, Right, Left, Up
        for dr, dc in [(1, 0), (0, 1), (0, -1), (-1, 0)]:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col) and dfs(new_row, new_col):
                return True

        # Backtrack: Unmark this cell
        grid[row][col] = '.'
        return False

    for col in range(cols):
        if is_valid(0, col) and dfs(0, col):
            return True

    return False

