def do_overlap(rect1, rect2):
    """
    Check if two rectangles overlap.
    """
    (x1, y1, x2, y2) = rect1
    (a1, b1, a2, b2) = rect2

    # If one rectangle is on the left side of the other
    if x1 >= a2 or a1 >= x2:
        return False

    # If one rectangle is above the other
    if y1 >= b2 or b1 >= y2:
        return False

    return True

def count_overlapping_rectangles(rectangles):
    """
    Count the number of overlapping rectangles in the given list.
    """
    count = 0
    n = len(rectangles)
    overlap_set = set()

    for i in range(n):
        for j in range(i + 1, n):
            if do_overlap(rectangles[i], rectangles[j]):
                overlap_set.add(i)
                overlap_set.add(j)

    return len(overlap_set)

