def calculate_grade(score):
    """
    Returns the letter grade for a given numerical score.

    Args:
    score (int): Numerical score

    Returns:
    str: Letter grade based on the given score
    """
    if score < 0 or score > 100:
        raise ValueError("Score must be between 0 and 100.")

    if score >= 90:
        return 'A'
    elif score >= 80:
        return 'B'
    elif score >= 70:
        return 'C'
    elif score >= 60:
        return 'D'
    else:
        return 'F'

