def min_distance(s1, s2):
    """
    Calculates the minimum number of operations required to convert s1 to s2.
    Allowed operations are insert, delete, and replace.

    :param s1: First string
    :param s2: Second string
    :return: Minimum number of operations
    """
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j
            elif j == 0:
                dp[i][j] = i
            elif s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],  # Delete
                                   dp[i][j-1],  # Insert
                                   dp[i-1][j-1])  # Replace

    return dp[m][n]

