def longest_palindromic_substring_length(s):
    """
    Returns the length of the longest palindromic substring.
    """
    if not s:
        return 0

    n = len(s)
    dp = [[False] * n for _ in range(n)]

    longest_length = 1

    for i in range(n):
        dp[i][i] = True

    start = 0

    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = True
                else:
                    dp[i][j] = dp[i + 1][j - 1]

                if dp[i][j] and length > longest_length:
                    start = i
                    longest_length = length

    return longest_length

