def fibonacci(n, memo=None):
    """
    Returns the n-th Fibonacci number using dynamic programming with memoization.
    """
    if memo is None:
        memo = {}

    # Base cases
    if n <= 1:
        return n

    # Check if already computed
    if n in memo:
        return memo[n]

    # Compute the n-th Fibonacci number recursively
    memo[n] = fibonacci(n-1, memo) + fibonacci(n-2, memo)

    return memo[n]

