def list_primes(n):
    """
    Returns a list of all prime numbers less than or equal to n.
    """
    if n < 2:
        return []

    primes = []
    for possible_prime in range(2, n + 1):
        is_prime = True
        for num in range(2, int(possible_prime ** 0.5) + 1):
            if possible_prime % num == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(possible_prime)

    return primes

