def categorize_items(lst):
    """
    Categorizes items in the provided list into their respective data types.

    Parameters:
        lst (list): The list of items to categorize.

    Returns:
        dict: Dictionary where keys are the data type names and values are lists of items of those types.
    """
    categorized = {}
    for item in lst:
        item_type = type(item).__name__
        if item_type in categorized:
            categorized[item_type].append(item)
        else:
            categorized[item_type] = [item]
    return categorized

