def unique_characters(s):
    """
    Returns a new string that contains only the unique characters in the input string
    while maintaining their original order.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

