def find_duplicates(nums):
    """
    Given a list of numbers, return a list of duplicates.

    Args:
    nums (List[int]): List of integers.

    Returns:
    List[int]: List of integers that are duplicates in the input list.
    """
    num_count = {}
    duplicates = []

    for num in nums:
        if num in num_count:
            num_count[num] += 1
        else:
            num_count[num] = 1

    for num, count in num_count.items():
        if count > 1:
            duplicates.append(num)

    return duplicates

