def solve_maze(maze):
    rows, cols = len(maze), len(maze[0])
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def dfs(row, col, path):
        if maze[row][col] == 3:
            return path + [(row, col)]
        maze[row][col] = 1
        for dr, dc in directions:
            nr, nc = row + dr, col + dc
            if (0 <= nr < rows and 0 <= nc < cols and
                maze[nr][nc] != 1 and (nr, nc) not in path):
                result = dfs(nr, nc, path + [(row, col)])
                if result:
                    return result
        maze[row][col] = 0
        return None

    for row in range(rows):
        for col in range(cols):
            if maze[row][col] == 2:
                result = dfs(row, col, [])
                if result:
                    return result

    return None

