import random

def get_user_guess(input_fn=input):
    """
    Prompts the user to guess a number between 1 and 100 using the input_fn and returns the valid guess.
    """
    while True:
        try:
            guess = int(input_fn("Guess a number between 1 and 100: "))
            if 1 <= guess <= 100:
                return guess
            else:
                print("Invalid number. Please guess a number between 1 and 100.")
        except ValueError:
            print("Invalid input. Please enter a number.")

def generate_number():
    """
    Generates and returns a random number between 1 and 100.
    """
    return random.randint(1, 100)

def compare_numbers(user_guess, secret_number):
    """
    Compares the user's guess with the secret number and returns a feedback string.
    """
    if user_guess == secret_number:
        return "You got it!"
    elif user_guess < secret_number:
        return "Too low!"
    else:
        return "Too high!"

