def is_valid_parentheses(s):
    """
    Determine if the input string containing just the characters '(', ')', '{', '}', '[' and ']'
    is valid. A string is valid if open brackets are closed by the same type of brackets and
    in the correct order.

    Args:
    s (str): The input string containing the characters.

    Returns:
    bool: True if the string is valid, False otherwise.
    """
    stack = []
    mapping = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

