def print_primes(n):
    """
    Prints all prime numbers less than or equal to n.
    """
    if n < 2:
        print('')
        return

    primes = []
    for num in range(2, n + 1):
        is_prime = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)

    print(' '.join(map(str, primes)))

