def aggregate_dicts(data):
    """
    Aggregates dictionaries based on the 'name' key.
    For each unique name, combines the values from corresponding dictionaries.
    """
    result = {}
    for item in data:
        name = item['name']
        if name not in result:
            result[name] = {'age': [], 'city': []}

        if 'age' in item:
            result[name]['age'].append(item['age'])

        if 'city' in item:
            result[name]['city'].append(item['city'])

    return result

