def longest_repeating_substring(s):
    def search_substring(length):
        seen = {}
        for i in range(len(s) - length + 1):
            substring = s[i:i+length]
            if substring in seen:
                return substring
            seen[substring] = True
        return ""

    left, right = 1, len(s)
    result = ""

    while left <= right:
        mid = (left + right) // 2
        substring = search_substring(mid)
        if substring:
            result = substring
            left = mid + 1
        else:
            right = mid - 1

    return result

