def decrypt_caesar(ciphertext, shift):
    """Decrypts a Caesar cipher with the given shift."""
    plaintext = ''
    for char in ciphertext:
        if char.isalpha():
            start = ord('a') if char.islower() else ord('A')
            shifted_char = chr((ord(char) - start - shift) % 26 + start)
        else:
            shifted_char = char
        plaintext += shifted_char
    return plaintext

def brute_force_caesar(ciphertext):
    """Performs a brute-force attack on the given Caesar cipher ciphertext."""
    decryptions = {}
    for shift in range(1, 26):
        plaintext = decrypt_caesar(ciphertext, shift)
        decryptions[shift] = plaintext
        print(f"Shift {shift}: {plaintext}")
    return decryptions

def factorial(n):
    """
    Returns the factorial of a given integer n.
    :param n: Non-negative integer whose factorial is to be calculated
    :return: Factorial of the integer n
    """
    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n - 1)

