def unique_subsequences(s):
    """
    Returns a list of all unique subsequences of the input string s, including the empty subsequence.
    """
    subsequences = set()

    def generate_subsequences(current, index):
        if index == len(s):
            subsequences.add(current)
            return
        generate_subsequences(current, index + 1)
        generate_subsequences(current + s[index], index + 1)

    generate_subsequences("", 0)
    return list(subsequences)

