def count_vowels(text):
    """
    Counts the number of vowels (a, e, i, o, u) in a given string of text. Case insensitivity is enforced.
    """
    vowels = "aeiou"
    return sum(1 for char in text.lower() if char in vowels)

def word_lengths(text):
    """
    Takes a string of text and returns a dictionary where the keys are the words in
    the text and the values are the lengths of those words.
    """
    words = text.split()
    return {word: len(word) for word in words}

def word_lengths_and_counts(text):
    """
    Takes a string of text and returns a dictionary where the keys are the words in
    the text and the values are tuples containing the lengths of the words and their counts.
    """
    words = text.split()
    word_counts = {}
    for word in words:
        if word in word_counts:
            word_counts[word] = (len(word), word_counts[word][1] + 1)
        else:
            word_counts[word] = (len(word), 1)
    return word_counts

