def sum_digits(n):
    """
    Returns the sum of the digits of the integer n.
    If n is negative, the digits of the absolute value of n are summed.
    """
    n = abs(n)
    if n < 10:
        return n
    else:
        return n % 10 + sum_digits(n // 10)

