def stack_blocks(blocks):
    """
    This function takes a list of blocks represented by their colors and returns
    the height of the tallest tower that can be created by stacking blocks of the same color.

    Args:
    blocks (list): A list of strings representing blocks of different colors.

    Returns:
    int: The height of the tallest tower.
    """
    if not blocks:
        return 0

    color_count = {}

    for color in blocks:
        if color in color_count:
            color_count[color] += 1
        else:
            color_count[color] = 1

    tallest_tower_height = max(color_count.values())

    return tallest_tower_height

