def create_password(words):
    """
    Concatenate a list of words to create a password.

    :param words: List of words to concatenate
    :return: Concatenated password
    """
    return "".join(words)


def check_password(password, words):
    """
    Verify if the password can be formed by concatenating words from the list.

    :param password: The password string to verify
    :param words: List of words that can be used to form the password
    :return: True if the password can be formed by concatenating words, else False
    """
    def can_form_password(remaining, words_set):
        if not remaining:
            return True
        for word in words_set:
            if remaining.startswith(word):
                if can_form_password(remaining[len(word):], words_set):
                    return True
        return False

    words_set = set(words)
    return can_form_password(password, words_set)

def my_range(start, stop, step):
    """
    Generates a sequence of numbers from start to stop with a step increment.
    If the step is positive, the sequence will be an increasing sequence.
    If the step is negative, the sequence will be a decreasing sequence.
    If the step is zero, it will raise a ValueError.
    """
    if step == 0:
        raise ValueError("step must be non-zero")

    current = start
    result = []

    if step > 0:
        while current < stop:
            result.append(current)
            current += step
    else:
        while current > stop:
            result.append(current)
            current += step

    return result

