def binary_search(array, target):
    """
    Perform a binary search on the sorted array to find the target.
    Returns the index of the target if found, otherwise returns -1.
    """
    left = 0
    right = len(array) - 1

    while left <= right:
        mid = (left + right) // 2

        if array[mid] == target:
            return mid
        elif array[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

