def find_largest_smallest(nums):
    """
    Returns a tuple (largest, smallest) from the list of integers.

    Args:
    nums (list): A list of integers.

    Returns:
    tuple: A tuple containing the largest and smallest integer.
    """
    # Edge case if list contains only one element
    if len(nums) == 1:
        return (nums[0], nums[0])

    # Initialize largest and smallest with the first element
    largest = nums[0]
    smallest = nums[0]

    # Iterate through the list to find the largest and smallest values
    for num in nums[1:]:
        if num > largest:
            largest = num
        elif num < smallest:
            smallest = num

    return (largest, smallest)

