def shortest_subarray(arr, target):
    min_len = float('inf')
    current_sum = 0
    start = 0
    for end in range(len(arr)):
        current_sum += arr[end]

        while current_sum >= target:
            min_len = min(min_len, end - start + 1)
            current_sum -= arr[start]
            start += 1

    if min_len == float('inf'):
        return 0
    return min_len

