def bubble_sort(list_):
    """
    Takes a list as input and sorts it in ascending order using the bubble sort algorithm.

    Args:
        list_: A list of elements to be sorted.

    Returns:
        None
    """
    n = len(list_)
    for i in range(n - 1):
        for j in range(n - i - 1):
            if list_[j] > list_[j + 1]:
                list_[j], list_[j + 1] = list_[j + 1], list_[j]

def word_frequencies(strings):
