def robot_position(commands: str) -> tuple[int, int]:
    """
    This function calculates the final position of a robot after executing a sequence of commands.

    Args:
    commands (str): A string representing the sequence of commands. Each command is 'U', 'D', 'L', or 'R'.

    Returns:
    tuple[int, int]: The final position of the robot as a tuple of two integers.
    """
    x, y = 0, 0

    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1

    return x, y

