def fibonacci(n):
    """
    Returns the Fibonacci number at index n.
    """
    if not isinstance(n, int) or n < 0:
        return "Invalid input"

    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

