def find_median(n, nums):
    """
    Given an integer n and a list of integers nums, return the median.
    """
    nums = sorted(nums)
    if n % 2 != 0:
        return nums[n // 2]
    else:
        mid_index = n // 2
        return (nums[mid_index - 1] + nums[mid_index]) / 2

