# Solution for Problem 1
def shortest_substring_containing_all_colors(s):
    required_colors = {'R', 'B', 'G'}
    n = len(s)
    if not required_colors.issubset(set(s)):
        return -1  # No valid substring exists

    min_length = n + 1
    for i in range(n):
        colors_seen = set()
        for j in range(i, n):
            if s[j] in required_colors:
                colors_seen.add(s[j])
            if colors_seen == required_colors:
                min_length = min(min_length, j - i + 1)
                break
    return min_length if min_length <= n else -1

# Solution for Problem 2
def max_subarray_sum(nums):
    if not nums:
        return 0

    current_sum = max_sum = nums[0]

    for num in nums[1:]:
        current_sum = max(num, current_sum + num)
        max_sum = max(max_sum, current_sum)

    return max_sum

