def find_duplicate_numbers(nums):
    """
    Finds all duplicate numbers in the list.

    :param nums: List of integers
    :return: List of unique duplicate integers
    """

    # To store unique duplicate numbers
    duplicates = set()
    # To store seen numbers
    seen = set()

    for num in nums:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)

    return list(duplicates)

