def find_min_cost(num_nodes, edges):
    """
    Computes the minimum cost of constructing the MST using Kruskal's algorithm.

    :param num_nodes: The number of nodes in the graph.
    :param edges: A list of edges where each edge is represented as (u, v, cost).
    :return: The minimum cost to construct the MST.
    """
    edges.sort(key=lambda x: x[2])
    parent = list(range(num_nodes))
    rank = [0] * num_nodes

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            if rank[px] > rank[py]:
                parent[py] = px
            elif rank[px] < rank[py]:
                parent[px] = py
            else:
                parent[py] = px
                rank[px] += 1

    mst_cost = 0
    for edge in edges:
        x, y, cost = edge
        if find(x) != find(y):
            union(x, y)
            mst_cost += cost

    return mst_cost

def is_valid_parentheses(s):
    """
    Returns True if the string s contains valid parentheses, otherwise False.
    """
    stack = []
    matching_parentheses = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses:
            if stack == [] or matching_parentheses[char] != stack.pop():
                return False
        else:
            return False

    return stack == []

