def search(nums, target):
    """
    This function returns the index of the first occurrence of the target value in the sorted array nums.
    If the target is not found, it returns -1.
    """
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] < target:
            left = mid + 1
        elif nums[mid] > target:
            right = mid - 1
        else:
            # If we found the target and the element before mid is not equal to target (or mid == 0)
            # That means we have found the first occurrence
            if mid == 0 or nums[mid - 1] != target:
                return mid
            # Move the right pointer to continue searching for the first occurrence in the left half
            right = mid - 1
    return -1

