def fibonacci(n):
    """
    This function returns the nth Fibonacci number.

    Args:
        n: The position of the desired Fibonacci number in the sequence.

    Returns:
        The nth Fibonacci number.
    """

    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n-1) + fibonacci(n-2)

