def find_common_prefix(str1, str2):
    """
    Returns the longest common prefix string between str1 and str2.
    """
    min_length = min(len(str1), len(str2))
    for i in range(min_length):
        if str1[i] != str2[i]:
            return str1[:i]
    return str1[:min_length]

