def firstUniqChar(s: str) -> str:
    """
    Finds the first non-repeating character in the string.

    Args:
    s (str): Input string consisting only of lowercase letters.

    Returns:
    str: The first non-repeating character or a space if all characters repeat.
    """
    char_counts = {}

    # Step 1: Count the frequency of each character
    for char in s:
        if char in char_counts:
            char_counts[char] += 1
        else:
            char_counts[char] = 1

    # Step 2: Find the first character with a count of 1
    for char in s:
        if char_counts[char] == 1:
            return char

    return " "

