import re

def count_words(filename, common_words):
    word_counts = {}
    with open(filename, 'r') as f:
        text = f.read()
        # remove punctuation
        text = re.sub(r'[^\w\s]', '', text)
        # convert to lower case
        text = text.lower()
        # split the text into words
        words = text.split()

        for word in words:
            if word not in common_words:
                if word not in word_counts:
                    word_counts[word] = 1
                else:
                    word_counts[word] += 1
    return word_counts

