def count_word_frequencies(words):
    """
    Returns a dictionary with the frequency count of each word in the input list.

    Parameters:
    words (list): A list of words (strings).

    Returns:
    dict: A dictionary where keys are words and values are their frequencies.
    """
    word_count = {}
    for word in words:
        if word in word_count:
            word_count[word] += 1
        else:
            word_count[word] = 1
    return word_count

