def basic_chatbot(input_msg):
    """
    Basic chatbot that responds to greetings and asks for the user's name.
    """
    greetings = ["hi", "hello", "hey", "good morning", "good afternoon", "good evening"]
    input_msg_lower = input_msg.lower()

    if any(greet in input_msg_lower for greet in greetings):
        return "Hello! What's your name?"
    elif "name is" in input_msg_lower:
        name = input_msg_lower.split("name is ")[-1]
        return f"Nice to meet you, {name.title()}!"
    else:
        return "I'm sorry, I can only respond to greetings and introductions."

