def check_substring(string, substring):
    """
    Checks if the substring is present in the string and
    determines if the position of the substring is within a specified range.
    """
    try:
        # Try to find the position of the substring in the string
        position = string.index(substring)
        # Check if the position is within a certain range (e.g., 5 to 10)
        if 5 <= position <= 10:
            return f"Substring '{substring}' found at position {position} within the range."
        else:
            return f"Substring '{substring}' found at position {position} but not within the range."
    except ValueError:
        # If substring is not found, index() will raise a ValueError
        return f"Substring '{substring}' not found in the string."

