def caesar_cipher(text, shift):
    """
    Encode text using a Caesar cipher, preserving the case of letters and leaving non-alphabet characters untouched.

    :param text: The input string to encode.
    :param shift: The number of positions to shift each letter by.
    :return: The encoded string.
    """
    result = []

    for char in text:
        if char.isalpha():
            offset = ord('A') if char.isupper() else ord('a')
            encoded_char = chr((ord(char) - offset + shift) % 26 + offset)
            result.append(encoded_char)
        else:
            result.append(char)

    return ''.join(result)

