def dailyTemperatures(arr):
    res = [0] * len(arr)
    stack = []

    for i, temp in enumerate(arr):
        while stack and arr[stack[-1]] < temp:
            prev_day = stack.pop()
            res[prev_day] = i - prev_day
        stack.append(i)

    return res

