def findDuplicates(nums):
    """
    Returns a list of integers which appear twice in the given list 'nums'.
    """
    result = []
    for i in range(len(nums)):
        index = abs(nums[i]) - 1
        if nums[index] < 0:
            result.append(abs(nums[i]))
        else:
            nums[index] = -nums[index]
    # Restore the array to its original state
    for i in range(len(nums)):
        nums[i] = abs(nums[i])
    return result

