def remove_consecutive_duplicates(s):
    """
    Recursively removes consecutive duplicates from the string s until no consecutive duplicates are left.
    """
    stack = []

    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return ''.join(stack)

