def minDistance(word1, word2):
    """
    Returns the minimum number of operations required to convert word1 to word2.
    Operations permitted: insert a character, delete a character, replace a character.
    """
    m, n = len(word1), len(word2)

    # Create a DP table to store the minimum edit distance
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the DP table
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Compute the minimum edit distance
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if word1[i-1] == word2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],    # Delete
                                  dp[i][j-1],    # Insert
                                  dp[i-1][j-1])  # Replace

    return dp[m][n]

