def unique_pairs(nums, target):
    """
    Returns the number of unique pairs of integers in the list whose sum equals to target.
    """
    seen = set()
    pairs = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Create a sorted tuple to avoid duplicate pairs
            pairs.add(tuple(sorted((num, complement))))
        seen.add(num)

    return len(pairs)

