def search_matrix(matrix, target):
    """
    Determines if target exists in the matrix.

    :param matrix: List of List of integers representing a 2D matrix.
    :param target: Integer to search for in the matrix.
    :return: True if target exists in the matrix, otherwise False.
    """
    if not matrix or not matrix[0]:
        return False

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1
    return False

