def three_sum(nums):
    """
    Finds all unique triplets in the array which sum to zero.

    Parameters:
    nums (List[int]): An array of integers.

    Returns:
    List[List[int]]: A list of unique triplets that sum to zero.
    """
    nums.sort()
    result = []

    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, len(nums) - 1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s < 0:
                left += 1
            elif s > 0:
                right -= 1
            else:
                result.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1

    return result

def max_subsequence_sum(nums):
    """
    Returns the maximum value obtainable from any subsequence of the given list of integers.
    """
    max_sum = 0
    current_sum = 0

    for num in nums:
        current_sum += num
        if current_sum < 0:
            current_sum = 0
        if current_sum > max_sum:
            max_sum = current_sum

    return max_sum

