def min_segments_to_remove(s: str) -> int:
    """
    Returns the minimum number of segments that need to be removed to make `s` a binary substring.
    """
    if not s:
        return 0

    current_char = s[0]
    segment_count = 1

    for char in s[1:]:
        if char != current_char:
            segment_count += 1
            current_char = char

    return segment_count - 1

