def largest_sum_of_averages(nums, k):
    """
    Returns the maximum sum of the averages when partitioning the array nums into k non-empty contiguous subarrays.
    """
    # Initialize sums array to store cumulative sums
    n = len(nums)
    sums = [0] * (n + 1)
    for i in range(n):
        sums[i + 1] = sums[i] + nums[i]

    # Initialize dp array where dp[i][k] represents the maximum sum of averages we can get by partitioning
    # the first i elements into k parts
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][1] = sums[i] / i

    for j in range(2, k + 1):
        for i in range(j, n + 1):
            for x in range(j - 1, i):
                dp[i][j] = max(dp[i][j], dp[x][j - 1] + (sums[i] - sums[x]) / (i - x))

    return round(dp[n][k], 5)

def longest_concat_substring_length(s, wordDict):
    word_set = set(wordDict)
    n = len(s)
    max_len = 0

    # Create a DP array to store the longest length
    dp = [0] * (n+1)

    for i in range(1, n+1):
        for j in range(i):
            if s[j:i] in word_set:
                dp[i] = max(dp[i], dp[j] + (i - j))

    return max(dp)

