def remove_characters_to_sort(s, k):
    n = len(s)
    if k >= n:
        return ""

    stack = []
    for i, char in enumerate(s):
        # Keep removing characters from the stack as long as we can still remove and
        # the current character is not ordered.
        while k > 0 and stack and stack[-1] > char:
            stack.pop()
            k -= 1
        stack.append(char)

    # If there are still characters to remove, remove them from the end
    while k > 0:
        stack.pop()
        k -= 1

    return ''.join(stack)

from typing import List

def is_complete_binary_tree(nums: List[int]) -> bool:
    """
    Determines if the given binary tree, represented as a list in level order traversal,
    is a complete binary tree.
    """
    n = len(nums)

    if n == 0:
        return True  # An empty tree is considered complete

    for i in range(n):
        if 2 * i + 1 < n and not nums[2 * i + 1]:
            return False
        if 2 * i + 2 < n and not nums[2 * i + 2]:
            return False

    return True

