def max_strength(grid, trapValue):
    n = len(grid)
    dp = [[-1] * n for _ in range(n)]

    if grid[0][0] == trapValue:
        return -1

    dp[0][0] = grid[0][0]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue
            if grid[i][j] == trapValue:
                dp[i][j] = -1
                continue
            up = dp[i-1][j] if i > 0 and dp[i-1][j] != -1 else -1
            left = dp[i][j-1] if j > 0 and dp[i][j-1] != -1 else -1
            dp[i][j] = max(up, left) + grid[i][j] if max(up, left) != -1 else -1

    return dp[n-1][n-1]

def longest_palindromic_substring_length(s):
    """
    Returns the length of the longest palindromic substring that can be obtained after at most one move.
    """
    def is_palindrome(s):
        return s == s[::-1]

    n = len(s)

    if is_palindrome(s):
        return n

    for i in range(n):
        if is_palindrome(s[:i] + s[i+1:]):
            return n

    return n - 1

