def smallest_lexicographical_string(s, k):
    """
    Returns the lexicographically smallest string by performing exactly k swaps of any two adjacent characters.
    """
    s = list(s)
    n = len(s)
    for i in range(n):
        for j in range(1, n):
            if k > 0 and s[j - 1] > s[j]:
                s[j - 1], s[j] = s[j], s[j - 1]
                k -= 1
    return ''.join(s)

