def min_operations_to_empty(nums):
    from collections import Counter

    num_counts = Counter(nums)
    operations = 0

    while num_counts:
        k = min(num_counts)
        operations += 1

        if k in num_counts:
            del num_counts[k]
        if k + 1 in num_counts:
            del num_counts[k + 1]

    return operations

