def min_distance_to_mailboxes(nums, k):
    """
    Returns the minimum total distance between each house and its nearest mailbox.
    The nums list is sorted and dynamic programming is used to find the best
    locations to place k mailboxes.
    """

    # Utility function to calculate distance for a segment
    def distance(start, end):
        median_index = (start + end) // 2
        median = nums[median_index]
        return sum(abs(nums[i] - median) for i in range(start, end + 1))

    n = len(nums)
    nums.sort()

    # dp[i][j]: the minimum distance to place j+1 mailboxes among the first i+1 houses
    dp = [[float('inf')] * k for _ in range(n)]

    for i in range(n):
        dp[i][0] = distance(0, i)

    for j in range(1, k):
        for i in range(n):
            for m in range(i):
                dp[i][j] = min(dp[i][j], dp[m][j-1] + distance(m + 1, i))

    return dp[-1][-1]

def canVisitAllRooms(rooms):
    """
    Returns True if all rooms can be visited, otherwise False.
    """
    visited = set()
    stack = [0]

    while stack:
        current = stack.pop()
        if current not in visited:
            visited.add(current)
            stack.extend(rooms[current])

    return len(visited) == len(rooms)

def pacific_atlantic(grid):
    if not grid or not grid[0]:
        return []

    m, n = len(grid), len(grid[0])

    def bfs(starts):
        visited = set(starts)
        queue = list(starts)
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        while queue:
            r, c = queue.pop(0)
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited and grid[nr][nc] >= grid[r][c]:
                    queue.append((nr, nc))
                    visited.add((nr, nc))

        return visited

    pacific_starts = [(i, 0) for i in range(m)] + [(0, j) for j in range(n)]
    atlantic_starts = [(i, n - 1) for i in range(m)] + [(m - 1, j) for j in range(n)]

    pacific_reachable = bfs(pacific_starts)
    atlantic_reachable = bfs(atlantic_starts)

    return list(pacific_reachable & atlantic_reachable)

