def rob(nums):
    """
    Returns the maximum amount of money that can be robbed without triggering alarm
    from circular arrangement of houses.
    """
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]
    if len(nums) == 2:
        return max(nums)

    def rob_linear(houses):
        prev, curr = 0, 0
        for amount in houses:
            prev, curr = curr, max(prev + amount, curr)
        return curr

    return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))

