def largestIsland(grid):
    """
    Returns the size of the largest island that can be formed by converting at most one 0 to a 1.
    """
    def dfs(x, y, index):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] != 1:
            return 0
        grid[x][y] = index
        return 1 + dfs(x+1, y, index) + dfs(x-1, y, index) + dfs(x, y+1, index) + dfs(x, y-1, index)

    m, n = len(grid), len(grid[0])
    index = 2
    sizes = {0: 0}

    # Step 1: Identify all islands and their sizes
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                size = dfs(i, j, index)
                sizes[index] = size
                index += 1

    # Step 2: Try converting each 0 to 1 and calculate the potential island size
    max_island = max(sizes.values())

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 0:
                seen = set()
                for x, y in [(i+1, j), (i-1, j), (i, j+1), (i, j-1)]:
                    if 0 <= x < m and 0 <= y < n and grid[x][y] > 1:
                        seen.add(grid[x][y])
                potential_size = 1 + sum(sizes[index] for index in seen)
                max_island = max(max_island, potential_size)

    return max_island

