def search_insert(nums, target):
    """
    Given a sorted array of unique integers `nums` and a target integer `target`,
    returns the index where the target should be inserted to maintain sorted order.
    If the target is already present, returns the index where it is located.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left

