def has_path(grid, start, end):
    """
    Determines if there is a path from start to end in the given maze.

    :param grid: List[List[int]] - The binary matrix representing the maze
    :param start: Tuple[int, int] - The starting position in (row, col) format
    :param end: Tuple[int, int] - The destination position in (row, col) format
    :return: bool - True if there is a path from start to end, else False
    """
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    def is_valid(x, y):
        return 0 <= x < rows and 0 <= y < cols and grid[x][y] == 0

    def dfs(x, y):
        if (x, y) == end:
            return True
        grid[x][y] = 1  # Mark the cell as visited
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and dfs(nx, ny):
                return True
        return False

    return dfs(start[0], start[1])

