def longest_common_subsequence(s1, s2):
    """
    Returns the length of the longest common subsequence that can be formed
    from the characters of s1 and s2.
    """
    m, n = len(s1), len(s2)

    # Initialize a (m+1) by (n+1) DP table filled with zeroes.
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp table using a bottom-up dynamic programming approach.
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

