def find_and_replace_pattern(words, pattern):
    def matches(word):
        mapping = {}
        reverse_mapping = {}

        for w_char, p_char in zip(word, pattern):
            if w_char not in mapping:
                if p_char in reverse_mapping:
                    return False
                mapping[w_char] = p_char
                reverse_mapping[p_char] = w_char
            elif mapping[w_char] != p_char:
                return False

        return True

    return [word for word in words if matches(word)]

def judge_circle(s):
    """
    Determine if the robot returns to the origin after a sequence of moves in a 2D grid.

    Parameters:
    s (str): A string representing the sequence of moves ('U', 'D', 'L', 'R').

    Returns:
    bool: True if the sequence of moves returns the robot to the origin, False otherwise.
    """
    x, y = 0, 0

    for move in s:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return x == 0 and y == 0

