def search_matrix(matrix, target):
    """
    Determine if target exists in a 2D matrix.
    Each row and column are sorted in ascending order.

    :param matrix: List[List[int]]
    :param target: int
    :return: bool
    """
    if not matrix or not matrix[0]:
        return False

    # Start searching from the top-right corner of the matrix
    row, col = 0, len(matrix[0]) - 1

    while row < len(matrix) and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1

    return False

def canPlaceHouses(positions, d, min_dist):
    count = 1
    last_pos = positions[0]

    for i in range(1, len(positions)):
        if positions[i] - last_pos >= min_dist:
            count += 1
            last_pos = positions[i]
            if count == d:
                return True
    return False

def maxMinDistance(positions, d):
    positions.sort()
    low = 1
    high = positions[-1] - positions[0]

    while low <= high:
        mid = (low + high) // 2
        if canPlaceHouses(positions, d, mid):
            low = mid + 1
        else:
            high = mid - 1

    return high

from bisect import bisect_left

def max_envelopes(envelopes):
    """
    Returns the maximum number of envelopes you can Russian doll
    (i.e., put one inside the other).
    """
    if not envelopes:
        return 0

    # Sort the envelopes first by width in ascending order.
    # If the width is the same, sort by height in descending order.
    # This ensures that envelopes with the same width cannot be Russian dolled.
    envelopes.sort(key=lambda x: (x[0], -x[1]))

    def longest_increasing_subsequence(nums):
        dp = []
        for num in nums:
            idx = bisect_left(dp, num)
            if idx < len(dp):
                dp[idx] = num
            else:
                dp.append(num)
        return len(dp)

    # Extract the heights and find the LIS with these heights.
    heights = [e[1] for e in envelopes]
    return longest_increasing_subsequence(heights)

