def allPathsSourceTarget(graph, start, end):
    def dfs(node, path, res):
        if node == end:
            res.append(path)
            return
        for neighbor in graph[node]:
            dfs(neighbor, path + [neighbor], res)

    result = []
    dfs(start, [start], result)
    return result

from typing import List
from collections import Counter

def max_words_formed(letters: str, words: List[str]) -> int:
    letter_count = Counter(letters)
    max_words = 0

    for word in words:
        word_count = Counter(word)
        can_form = True

        for char, count in word_count.items():
            if letter_count[char] < count:
                can_form = False
                break

        if can_form:
            max_words += 1

    return max_words

