def min_elements_greater_than_or_equal_k(a, k, operations):
    """
    Returns the minimum number of elements in the array `a` that are greater than or equal to `k`
    after performing the given operations.
    """
    # Apply the operations
    for start, end in operations:
        for i in range(start, end + 1):
            a[i] += 1

    # Count how many elements are greater than or equal to `k`
    count = 0
    for value in a:
        if value >= k:
            count += 1

    return count

def find_smallest_rectangle(park):
    """
    Find the smallest rectangle that encloses all the trees in the park.

    Parameters:
    park (list of list of int): 2D grid representing the park

    Returns:
    list: coordinates of the rectangle in the format [r1, c1, r2, c2]
    """
    if not park or not any(any(row) for row in park):
        return []

    num_rows = len(park)
    num_cols = len(park[0])

    min_row, max_row = float('inf'), float('-inf')
    min_col, max_col = float('inf'), float('-inf')

    for r in range(num_rows):
        for c in range(num_cols):
            if park[r][c] == 1:
                if r < min_row:
                    min_row = r
                if r > max_row:
                    max_row = r
                if c < min_col:
                    min_col = c
                if c > max_col:
                    max_col = c

    return [min_row, min_col, max_row, max_col]

def min_concatenations(words, target):
    """
    Returns the minimum number of concatenations needed to construct the target string using strings from words list.
    If it is impossible to construct the target string, returns -1.
    """
    n = len(target)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        for word in words:
            if i >= len(word) and target[i-len(word):i] == word:
                dp[i] = min(dp[i], dp[i-len(word)] + 1)

    return dp[n] if dp[n] != float('inf') else -1

