def check_tic_tac_toe(board):
    """
    Checks the status of a tic-tac-toe game.

    :param board: List[List[str]] - a 2D list representing the game board
    :return: str - the game result ("X", "O", "Draw", or "Pending")
    """
    n = len(board)

    # Check rows and columns
    for i in range(n):
        if board[i][0] != ' ' and all(board[i][j] == board[i][0] for j in range(n)):
            return board[i][0]
        if board[0][i] != ' ' and all(board[j][i] == board[0][i] for j in range(n)):
            return board[0][i]

    # Check diagonals
    if board[0][0] != ' ' and all(board[i][i] == board[0][0] for i in range(n)):
        return board[0][0]
    if board[0][n-1] != ' ' and all(board[i][n-1-i] == board[0][n-1] for i in range(n)):
        return board[0][n-1]

    # Check for draw or pending
    if all(board[i][j] != ' ' for i in range(n) for j in range(n)):
        return "Draw"
    else:
        return "Pending"

