def count_smaller_elements(nums):
    """
    Given an array of integers `nums`, returns an array `count` where
    `count[i]` is the number of elements less than `nums[i]` to the right of `nums[i]`.
    """
    n = len(nums)
    count = [0] * n

    for i in range(n):
        for j in range(i + 1, n):
            if nums[j] < nums[i]:
                count[i] += 1

    return count

