def rob(nums):
    """
    This function takes a list of integers representing the amount of money in each house and returns the maximum
    amount of money the robber can steal without triggering any alarms by ensuring they do not rob two adjacent houses.
    """
    if not nums:
        return 0

    if len(nums) <= 2:
        return max(nums)

    # Using bottom-up dynamic programming approach
    prev2, prev1 = nums[0], max(nums[0], nums[1])

    for i in range(2, len(nums)):
        current = max(prev1, prev2 + nums[i])
        prev2, prev1 = prev1, current

    return prev1

