def smallest_k(nums, target_sum):
    if target_sum == 0:
        return 0 if 0 in nums else -1

    nums = [num for num in nums if num > 0]
    nums.sort()
    possible_sums = {0}

    for num in nums:
        new_sums = possible_sums.copy()
        for s in possible_sums:
            new_sum = s + num
            new_sums.add(new_sum)
        possible_sums = new_sums

    k = 1
    while k * target_sum in possible_sums:
        return k
        k += 1

    return -1

