def enclose_island(grid):
    m, n = len(grid), len(grid[0])

    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] != 1:
            return
        grid[x][y] = -1  # Mark the land as visited

        # Visit all 4-directionally connected lands
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    # Find the starting point of the island and mark the entire island
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dfs(i, j)
                break
        else:
            continue
        break

    # Add a border of water (0s) around the marked island
    for i in range(m):
        for j in range(n):
            if grid[i][j] == -1:  # Part of the island
                if any([
                    i == 0, i == m-1, j == 0, j == n-1,
                    grid[i-1][j] == 0 or grid[i+1][j] == 0,
                    grid[i][j-1] == 0 or grid[i][j+1] == 0,
                ]):
                    grid[i][j] = 0
                else:
                    grid[i][j] = 1

    return grid

