def find_the_distance_value(arr1, arr2, d):
    def is_within_distance(a, arr, d):
        for b in arr:
            if abs(a - b) <= d:
                return True
        return False

    count = 0
    for a in arr1:
        if not is_within_distance(a, arr2, d):
            count += 1
    return count

