def contains_nearby_almost_duplicate(nums, k, t):
    """
    Returns true if there are two distinct indices i and j in the array such that
    the absolute difference between nums[i] and nums[j] is at most t and the absolute
    difference between i and j is at most k. Otherwise, return false.
    """
    if t < 0:
        return False

    window = {}
    for i, num in enumerate(nums):
        bucket = num // (t + 1)

        if bucket in window:
            return True

        if bucket - 1 in window and abs(num - window[bucket - 1]) <= t:
            return True

        if bucket + 1 in window and abs(num - window[bucket + 1]) <= t:
            return True

        window[bucket] = num

        if i >= k:
            del window[nums[i - k] // (t + 1)]

    return False

def num_islands(grid):
    def dfs(grid, i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == '0':
            return

        grid[i][j] = '0'  # Mark this cell as visited

        # Check all adjacent cells (left, right, up, down)
        dfs(grid, i, j - 1)
        dfs(grid, i, j + 1)
        dfs(grid, i - 1, j)
        dfs(grid, i + 1, j)

    if not grid or not grid[0]:
        return 0

    island_count = 0

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                # Start a DFS to mark all cells in this island
                dfs(grid, i, j)
                island_count += 1

    return island_count

