from collections import deque

def minimum_moves_to_full_traversable(grid):
    """
    Returns the minimum number of moves required to transform the grid into a fully traversable field with no obstacles.
    If it is not possible, returns -1.
    """
    n = len(grid)

    def neighbors(r, c):
        for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
            if 0 <= nr < n and 0 <= nc < n:
                yield nr, nc

    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return -1

    # BFS to find the shortest path from top-left to bottom-right
    def bfs():
        queue = deque([(0, 0, 0)])  # (row, column, distance)
        visited = {(0, 0)}
        while queue:
            r, c, d = queue.popleft()
            if (r, c) == (n-1, n-1):
                return d
            for nr, nc in neighbors(r, c):
                if (nr, nc) not in visited and grid[nr][nc] == 0:
                    visited.add((nr, nc))
                    queue.append((nr, nc, d+1))
        return -1

    return bfs()

