from collections import defaultdict, deque

def min_words_to_form_target(words, target):
    """
    Returns the minimum number of words from the list `words` that need to be concatenated
    in any order to form the target string exactly, or -1 if it's not possible.
    """

    word_count = defaultdict(int)
    for word in words:
        word_count[word] += 1

    # Create a queue for BFS, initialized with the target string
    queue = deque([(target, 0)])
    visited = set()

    while queue:
        current_target, steps = queue.popleft()

        if current_target == "":
            return steps

        for word in words:
            if current_target.startswith(word):
                reduced_target = current_target[len(word):]

                if word_count[word] > 0:
                    if reduced_target not in visited:
                        visited.add(reduced_target)
                        queue.append((reduced_target, steps + 1))

    return -1

