def ecommerce_system(operations, data):
    products = {}
    results = []

    for op, params in zip(operations, data):
        if op == "add_product":
            name, stock_level = params
            products[name] = stock_level
        elif op == "remove_product":
            name = params[0]
            if name in products:
                del products[name]
        elif op == "restock_product":
            name, amount = params
            if name in products:
                products[name] += amount
        elif op == "sell_product":
            name, amount = params
            if name in products and products[name] >= amount:
                products[name] -= amount
            else:
                results.append("error")
        elif op == "get_stock_level":
            name = params[0]
            if name in products:
                results.append(products[name])
            else:
                results.append("error")
        else:
            results.append("invalid operation")

    return results

