from heapq import heappop, heappush
import collections

def find_min_max_edge_path(n: int, edges: List[List[int]], start: int, end: int) -> List[int]:
    def dijkstra_modified():
        heap = [(0, start, [])]  # (max_edge_weight, current_node, path_taken)
        visited = {}

        while heap:
            max_weight, node, path = heappop(heap)
            path = path + [node]

            if node in visited and visited[node] <= max_weight:
                continue
            visited[node] = max_weight

            if node == end:
                return path

            for neighbor, weight in graph[node]:
                heappush(heap, (max(max_weight, weight), neighbor, path))

        return []

    graph = collections.defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    return dijkstra_modified()

def is_palindrome(x):
    return x == x[::-1]

def min_palindrome_partition(s):
    n = len(s)
    dp = [0] * n
    pal = [[False] * n for _ in range(n)]

    # Every single character is a palindrome
    for i in range(n):
        pal[i][i] = True

    for to in range(1, n):
        for from_ in range(to, -1, -1):
            if s[from_] == s[to] and (to - from_ <= 2 or pal[from_ + 1][to - 1]):
                pal[from_][to] = True

    for to in range(n):
        if pal[0][to]:
            dp[to] = 0
        else:
            dp[to] = float('inf')
            for from_ in range(to):
                if pal[from_ + 1][to]:
                    dp[to] = min(dp[to], dp[from_] + 1)

    return dp[n - 1] + 1

