def mySqrt(x):
    """
    Computes the integer part of the square root of x using binary search.

    :param x: An integer the square root of which is to be computed
    :return: Integer part of the square root of x
    """
    if x < 2:
        return x

    left, right = 2, x // 2

    while left <= right:
        mid = (left + right) // 2
        num = mid * mid
        if num == x:
            return mid
        elif num < x:
            left = mid + 1
        else:
            right = mid - 1

    return right

