def canReachDestination(grid):
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return False

    m, n = len(grid), len(grid[0])
    visited = [[False for _ in range(n)] for _ in range(m)]

    def dfs(x, y):
        if x < 0 or y < 0 or x >= m or y >= n or grid[x][y] == 1 or visited[x][y]:
            return False
        if x == m - 1 and y == n - 1:
            return True
        visited[x][y] = True
        return dfs(x + 1, y) or dfs(x - 1, y) or dfs(x, y + 1) or dfs(x, y - 1)

    return dfs(0, 0)

