def canBeIncreasing(arr):
    """
    Determine if it is possible to make the array strictly increasing
    by changing at most one element.
    """
    def isStrictlyIncreasing(after_removal):
        for i in range(1, len(after_removal)):
            if after_removal[i] <= after_removal[i - 1]:
                return False
        return True

    # Check the array by trying to remove each element once (simulating the modification).
    for i in range(len(arr)):
        if isStrictlyIncreasing(arr[:i] + arr[i + 1:]):
            return True
    return False

