def min_days_to_succeed(data, k, threshold):
    """
    Returns the minimum number of days within that window that needs to record more visitors than the threshold
    to consider that window a successful promotional period. If no such window exists, return -1.
    """
    n = len(data)
    if n < k:
        return -1

    def days_with_more_visitors(window):
        return sum(1 for x in window if x > threshold)

    min_days = float('inf')
    for i in range(n - k + 1):
        window = data[i:i + k]
        days = days_with_more_visitors(window)
        if days > 0:
            min_days = min(min_days, days)

    return min_days if min_days != float('inf') else -1

def count_balanced_subarrays(nums, k):
    from collections import deque

    def count_windows_subarrays(arr, k):
        min_deque, max_deque = deque(), deque()
        left = 0
        count = 0
        for right, value in enumerate(arr):
            while min_deque and arr[min_deque[-1]] >= value:
                min_deque.pop()
            while max_deque and arr[max_deque[-1]] <= value:
                max_deque.pop()
            min_deque.append(right)
            max_deque.append(right)
            while arr[max_deque[0]] - arr[min_deque[0]] > k:
                left += 1
                if min_deque[0] < left:
                    min_deque.popleft()
                if max_deque[0] < left:
                    max_deque.popleft()
            count += right - left + 1
        return count

    return count_windows_subarrays(nums, k)

