def find_and_replace_pattern(words, pattern):
    def matches(word):
        if len(word) != len(pattern):
            return False
        char_map = {}
        reverse_char_map = {}
        for w, p in zip(word, pattern):
            if w not in char_map:
                char_map[w] = p
            if p not in reverse_char_map:
                reverse_char_map[p] = w
            if char_map[w] != p or reverse_char_map[p] != w:
                return False
        return True

    return [word for word in words if matches(word)]

def longest_arithmetic_subarray(nums):
    """
    Returns the length of the longest arithmetic subarray.
    """
    if len(nums) < 2:
        return len(nums)

    max_length = 0
    current_length = 1
    last_diff = None

    for i in range(1, len(nums)):
        current_diff = nums[i] - nums[i - 1]
        if current_diff == last_diff:
            current_length += 1
        else:
            last_diff = current_diff
            current_length = 2

        max_length = max(max_length, current_length)

    return max_length

