def count_pairs_with_manhattan_distance(points, d):
    if not points:
        return 0

    count = 0
    n = len(points)

    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = points[i]
            x2, y2 = points[j]
            if abs(x1 - x2) + abs(y1 - y2) == d:
                count += 1

    return count

