def contains_arithmetic_progression(arr):
    """
    Determines if there are three indices (i, j, k) with 0 <= i < j < k < len(arr) such that
    arr[i], arr[j], and arr[k] form an arithmetic progression.

    :param arr: List of sorted integers.
    :return: Boolean indicating the existence of such an arithmetic progression.
    """
    n = len(arr)
    if n < 3:
        return False

    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if arr[j] - arr[i] == arr[k] - arr[j]:
                    return True

    return False

