def minimum_rewards(ratings):
    n = len(ratings)
    rewards = [1] * n

    # Forward pass: ensure each rating is greater than the previous one gets more rewards
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            rewards[i] = rewards[i - 1] + 1

    # Backward pass: ensure each rating is greater than the next one gets more rewards
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            rewards[i] = max(rewards[i], rewards[i + 1] + 1)

    return sum(rewards)

