def longest_arith_seq_length(nums):
    if len(nums) <= 1:
        return len(nums)

    longest = 0
    dp = [{} for _ in range(len(nums))]

    for i in range(1, len(nums)):
        for j in range(i):
            diff = nums[i] - nums[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2

            longest = max(longest, dp[i][diff])

    return longest

