def construct_array(n):
    if n == 0:
        return []

    if n == 1:
        return [1]

    arr = []
    left, right = 1, 2 * n

    for i in range(n):
        if i % 2 == 0:
            arr.append(left)
            left += 1
        else:
            arr.append(right)
            right -= 1

    return arr

