def max_subarray_length(nums, target):
    """
    Returns the length of the longest contiguous subarray that sums to target.
    If no such subarray exists, returns 0.
    """
    prefix_sum = {}
    current_sum = 0
    max_length = 0

    for i, num in enumerate(nums):
        current_sum += num

        if current_sum == target:
            max_length = i + 1

        if (current_sum - target) in prefix_sum:
            max_length = max(max_length, i - prefix_sum[current_sum - target])

        if current_sum not in prefix_sum:
            prefix_sum[current_sum] = i

    return max_length

