def reverseStr(s, k):
    """
    Reverses the order of the first k characters for every 2k characters counting from the start of the string.
    """
    result = []
    for i in range(0, len(s), 2 * k):
        result.append(s[i:i+k][::-1] + s[i+k:i+2*k])
    return ''.join(result)

