def longestValidSubstring(s, k, m):
    from collections import Counter

    def validSubstring(s, m):
        count = Counter(s)
        for char in count:
            if count[char] < m:
                return False
        return True

    n = len(s)
    max_len = 0

    for i in range(n):
        for j in range(i, n):
            substr = s[i:j+1]
            if validSubstring(substr, m):
                max_len = max(max_len, len(substr))

    return max_len

