def final_string_length(s):
    """
    Reduces the string by repeatedly deleting any two adjacent characters if they are different
    and returns the length of the final string.
    """
    stack = []

    for char in s:
        if stack and stack[-1] != char:
            stack.pop()
        else:
            stack.append(char)

    return len(stack)

