def number_of_steps(n):
    """
    Returns the number of steps required to reduce n to zero.
    In one step, if n is odd, subtract 1; if n is even, divide by 2.
    """
    steps = 0
    while n > 0:
        if n % 2 == 0:
            n //= 2
        else:
            n -= 1
        steps += 1
    return steps

