def kth_smallest_element(arr, k):
    """
    Finds the k-th smallest element in the array using the Quickselect algorithm.
    Returns -1 if the array has fewer than k elements.

    :param arr: List of integers
    :param k: Integer representing which smallest element to find (1-based)
    :return: The k-th smallest element in the array, or -1 if array has fewer than k elements.
    """
    if not arr or len(arr) < k or k <= 0:
        return -1

    def quickselect(left, right, k_smallest):
        if left == right:
            return arr[left]

        pivot_index = partition(left, right)
        if k_smallest == pivot_index:
            return arr[k_smallest]
        elif k_smallest < pivot_index:
            return quickselect(left, pivot_index - 1, k_smallest)
        else:
            return quickselect(pivot_index + 1, right, k_smallest)

    def partition(left, right):
        pivot_index = left
        pivot_value = arr[right]

        for i in range(left, right):
            if arr[i] < pivot_value:
                arr[pivot_index], arr[i] = arr[i], arr[pivot_index]
                pivot_index += 1
        arr[pivot_index], arr[right] = arr[right], arr[pivot_index]
        return pivot_index

    return quickselect(0, len(arr) - 1, k - 1)

