def circularArrayLoop(nums):
    def next_index(i):
        return (i + nums[i]) % len(nums)

    n = len(nums)

    for i in range(n):
        if nums[i] == 0:
            continue

        slow, fast = i, i

        while nums[i] * nums[next_index(slow)] > 0 and nums[i] * nums[next_index(next_index(fast))] > 0:
            slow = next_index(slow)
            fast = next_index(next_index(fast))

            if slow == fast:
                if slow == next_index(slow):
                    break
                return True

        slow = i
        val = nums[i]
        while nums[slow] * val > 0:
            next_i = next_index(slow)
            nums[slow] = 0
            slow = next_i

    return False

