def count_beautiful_words(words):
    """
    Returns the number of "beautiful" words in the array. A word is considered beautiful
    if it contains all the vowels ('a', 'e', 'i', 'o', 'u') at least once.

    Args:
    words (list of str): Array of words to be checked.

    Returns:
    int: Number of beautiful words.
    """
    vowels = set('aeiou')

    def is_beautiful(word):
        return vowels.issubset(set(word))

    return sum(1 for word in words if is_beautiful(word))

