def max_rob(nums):
    """
    Returns the maximum amount of money you can rob without robbing two consecutive houses
    in a circular list.
    """
    def rob_linear(nums):
        prev, curr = 0, 0
        for num in nums:
            prev, curr = curr, max(curr, prev + num)
        return curr

    n = len(nums)
    if n == 1:
        return nums[0]

    # Two cases: exclude first house or exclude last house
    return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))

