def findLongestConcatenatedWordLength(words):
    """
    Returns the length of the longest concatenated word that can be formed from the list words.
    """
    def can_form(word, word_set):
        if word in memo:
            return memo[word]
        for i in range(1, len(word)):
            prefix = word[:i]
            suffix = word[i:]
            if prefix in word_set and (suffix in word_set or can_form(suffix, word_set)):
                memo[word] = True
                return True
        memo[word] = False
        return False

    word_set = set(words)
    memo = {}

    max_length = 0
    for word in words:
        if can_form(word, word_set):
            max_length = max(max_length, len(word))

    return max_length

