def significant_updates(timestampsA, timestampsB, T):
    """
    Returns the user with the maximum number of significant updates or "tie" if both have the same number.

    Args:
    timestampsA: List[int] - list of timestamps for user A.
    timestampsB: List[int] - list of timestamps for user B.
    T: int - threshold for a significant update.

    Returns:
    str - "A", "B", or "tie".
    """
    def count_significant_updates(timestamps, T):
        if not timestamps:
            return 0
        count = 0
        for i in range(1, len(timestamps)):
            if timestamps[i] - timestamps[i-1] >= T:
                count += 1
        return count

    significantA = count_significant_updates(timestampsA, T)
    significantB = count_significant_updates(timestampsB, T)

    if significantA > significantB:
        return "A"
    elif significantB > significantA:
        return "B"
    else:
        return "tie"

