def kth_smallest_element(arr1, arr2, k):
    """
    Returns the k-th smallest element in the merged sorted array of arr1 and arr2.
    If k is larger than the total number of elements in the merged array, return -1.
    """
    merged = []
    i, j = 0, 0
    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            merged.append(arr1[i])
            i += 1
        else:
            merged.append(arr2[j])
            j += 1

    while i < len(arr1):
        merged.append(arr1[i])
        i += 1

    while j < len(arr2):
        merged.append(arr2[j])
        j += 1

    if k > len(merged):
        return -1
    return merged[k-1]

