def fibonacci_mod(n):
    """
    Returns the n-th Fibonacci number modulo 10^9.
    """
    if n == 0:
        return 0
    elif n == 1:
        return 1

    MOD = 10**9
    a, b = 0, 1

    for i in range(2, n + 1):
        a, b = b, (a + b) % MOD

    return b

