from bisect import bisect_left

def length_of_lis(arr):
    """
    Returns the length of the longest increasing subsequence in the given list of integers.
    """
    if not arr:
        return 0

    lis = []

    for num in arr:
        pos = bisect_left(lis, num)
        if pos < len(lis):
            lis[pos] = num
        else:
            lis.append(num)

    return len(lis)

