def max_partition_subarrays(arr):
    """
    Returns the maximum number of non-overlapping non-decreasing subarrays.
    """
    if not arr:
        return 0

    count = 1
    max_val = arr[0]

    for i in range(1, len(arr)):
        if arr[i] < max_val:
            count += 1
            max_val = arr[i]
        else:
            max_val = max(max_val, arr[i])

    return count

