def can_partition_into_palindromes(s, m):
    def is_palindrome(x):
        return x == x[::-1]

    def dfs(s, m, start):
        if m < 0:
            return False
        if start == len(s) and m == 0:
            return True
        for end in range(start + 1, len(s) + 1):
            if is_palindrome(s[start:end]) and dfs(s, m - 1, end):
                return True
        return False

    return dfs(s, m, 0)

