def max_area_of_island(grid):
    """
    Returns the maximum area of an island in the grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(r, c):
        if r < 0 or c < 0 or r >= m or c >= n or grid[r][c] == 0 or visited[r][c]:
            return 0
        visited[r][c] = True
        return 1 + dfs(r + 1, c) + dfs(r - 1, c) + dfs(r, c + 1) + dfs(r, c - 1)

    max_area = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                max_area = max(max_area, dfs(i, j))

    return max_area

def count_connected_buildings(grid):
    """
    Returns the number of separate connected buildings in the grid.

    Parameters:
    grid (List[List[int]]): A 2D list representing the grid where each element is a non-negative integer.

    Returns:
    int: The number of separate connected buildings in the grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] > 0:
                    visited[nx][ny] = True
                    stack.append((nx, ny))

    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] > 0 and not visited[i][j]:
                visited[i][j] = True
                count += 1
                dfs(i, j)

    return count

