def smallest_lexicographical_string(s, k):
    """
    Returns the lexicographically smallest string that can be obtained by performing the
    given operation at most k times.
    """
    s_list = list(s)
    n = len(s_list)

    # We will perform up to k replacements
    for i in range(n):
        if k <= 0:
            break
        # Replace s[i] with 'a' if it is not already 'a'
        if s_list[i] != 'a':
            s_list[i] = 'a'
            k -= 1

    return ''.join(s_list)

