def longest_valid_parentheses(sequence):
    """
    Returns the length of the longest valid parentheses substring.
    """
    max_length = 0
    stack = [-1]

    for i, char in enumerate(sequence):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

