def search_matrix(matrix, target):
    """
    Searches for a target in an m x n matrix where every row and column is sorted in non-decreasing order.
    Returns True if the target is found, otherwise returns False.
    """
    if not matrix or not matrix[0]:
        return False

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1  # Start from top-right corner

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] < target:
            row += 1
        else:
            col -= 1

    return False

def maxNonOverlapping(nums, k):
    """
    Returns the maximum number of non-overlapping subarrays that sum up to k.
    """
    prefix_sums = {0}
    current_sum = 0
    count = 0

    for num in nums:
        current_sum += num
        if current_sum - k in prefix_sums:
            count += 1
            prefix_sums = {0}
            current_sum = 0
        else:
            prefix_sums.add(current_sum)
    return count

