def numUniqueBST(n):
    """
    Returns the number of structurally unique BSTs that store values 1 to n.
    """
    if n == 0 or n == 1:
        return 1

    # DP array to store the number of unique BSTs for each number from 0 to n
    dp = [0] * (n + 1)
    dp[0] = dp[1] = 1

    for i in range(2, n + 1):
        for j in range(1, i + 1):
            dp[i] += dp[j - 1] * dp[i - j]

    return dp[n]

