def min_deletions_to_make_palindrome(s):
    """
    Returns the minimum number of deletions required to make the string a palindrome.
    """
    n = len(s)
    # Create a table to store results of subproblems
    dp = [[0 for x in range(n)] for y in range(n)]

    # Strings of length 1 are already palindromes
    for i in range(n):
        dp[i][i] = 0

    # Fill the table
    for length in range(2, n+1):
        for i in range(n-length+1):
            j = i+length-1
            if s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1]
            else:
                dp[i][j] = min(dp[i+1][j], dp[i][j-1]) + 1

    # The result is the minimum number of deletions for s[0...n-1]
    return dp[0][n-1]

