def count_pairs_with_sum(arr, target):
    """
    Returns the number of pairs of elements in arr that sum up to target.
    """
    count = 0
    seen = {}

    for number in arr:
        complement = target - number
        if complement in seen:
            count += seen[complement]

        if number in seen:
            seen[number] += 1
        else:
            seen[number] = 1

    return count

