def first_missing_positive(nums):
    """
    Returns the smallest positive integer that is missing from the array.
    """
    n = len(nums)

    # Mark elements out of scope by replacing them with n + 1
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Use the index to place positive numbers in their "correct" positions
    for i in range(n):
        num = abs(nums[i])
        if num <= n and nums[num - 1] > 0:
            nums[num - 1] = -nums[num - 1]

    # The first missing positive number is the first index that has a positive value
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    return n + 1

