from collections import deque

def shortest_path(grid, startRow, startCol, endRow, endCol):
    if not grid or grid[startRow][startCol] == 1 or grid[endRow][endCol] == 1:
        return -1

    m, n = len(grid), len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(startRow, startCol, 0)])
    visited = set((startRow, startCol))

    while queue:
        r, c, steps = queue.popleft()

        if (r, c) == (endRow, endCol):
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n and (nr, nc) not in visited and grid[nr][nc] == 0:
                queue.append((nr, nc, steps + 1))
                visited.add((nr, nc))

    return -1

def max_product_of_two(arr):
    """
    Returns the maximum product of two distinct elements in the array.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements.")

    max1 = max2 = 0

    # Traverse the array to find the two largest elements
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

    return max1 * max2

