def total_working_time(logs, breakStart, breakEnd):
    total_time = 0
    for log in logs:
        entry, exit = log
        # If the log period is entirely outside the break period
        if exit <= breakStart or entry >= breakEnd:
            total_time += exit - entry
        # If the log period spans the break period
        elif entry < breakStart and exit > breakEnd:
            total_time += (breakStart - entry) + (exit - breakEnd)
        # If the log period starts before the break and ends during the break
        elif entry < breakStart and exit <= breakEnd:
            total_time += breakStart - entry
        # If the log period starts during the break and ends after the break
        elif entry >= breakStart and exit > breakEnd:
            total_time += exit - breakEnd
        # If the log period is entirely within the break period
        else:
            total_time += 0

    return total_time

