def length_of_LIS(arr):
    """
    Returns the length of the longest increasing subsequence in the given array.
    """
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n  # dp[i] represents the length of the longest increasing subsequence ending at index i

    for i in range(n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

