def findMaxLength(arr):
    """
    Returns the length of the largest subarray with an equal number of 0s and 1s.
    """
    hash_map = {0: -1}
    max_length = 0
    count = 0

    for i, num in enumerate(arr):
        # Replace 0 with -1
        if num == 0:
            count -= 1
        else:
            count += 1

        if count in hash_map:
            max_length = max(max_length, i - hash_map[count])
        else:
            hash_map[count] = i

    return max_length

