def find_rectangle_coordinates(grid):
    """
    Finds the top-left and bottom-right coordinates of the rectangle formed by '1's in a 2D grid.
    :param grid: List of List of integers (0 or 1)
    :return: List of four integers [r1, c1, r2, c2] or empty list if no rectangle exists
    """
    m, n = len(grid), len(grid[0])
    top_left = None
    bottom_right = None

    for r in range(m):
        for c in range(n):
            if grid[r][c] == 1:
                if top_left is None:
                    top_left = (r, c)
                bottom_right = (r, c)

    if top_left is None:
        return []

    r1, c1 = top_left
    r2, c2 = bottom_right
    return [r1, c1, r2, c2]

def maxValue(events):
    events.sort(key=lambda x:(x[1], x[0]))
    dp = [0] * (len(events) + 1)

    def binary_search(events, end_day):
        lo, hi = 0, len(events) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if events[mid][1] <= end_day:
                lo = mid + 1
            else:
                hi = mid - 1
        return lo

    for i in range(1, len(events) + 1):
        j = binary_search(events, events[i-1][0] - 1)
        dp[i] = max(dp[i-1], dp[j] + events[i-1][2])

    return dp[-1]

