def hasPath(maze):
    """
    Determines if there is a path from any '2' to any '3' in a given maze.

    :param maze: A 2D list representing the maze
    :return: True if a path exists, False otherwise
    """
    if not maze or not maze[0]:
        return False

    rows, cols = len(maze), len(maze[0])

    def find_start():
        for r in range(rows):
            for c in range(cols):
                if maze[r][c] == 2:
                    return (r, c)
        return None

    start = find_start()
    if not start:
        return False

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or maze[r][c] == 1:
            return False
        if maze[r][c] == 3:
            return True

        maze[r][c] = 1 # mark as visited

        # explore all four possible directions
        if dfs(r+1, c) or dfs(r-1, c) or dfs(r, c+1) or dfs(r, c-1):
            return True

        return False

    return dfs(start[0], start[1])

