from collections import defaultdict, deque

def findLadders(beginWord, endWord, wordList):
    if endWord not in wordList:
        return []

    wordList = set(wordList)
    wordList.add(beginWord)

    # Create a map to store the graph
    neighbors = defaultdict(list)

    # Build the adjacency list
    def buildGraph():
        for word in wordList:
            for i in range(len(word)):
                pattern = word[:i] + '*' + word[i+1:]
                neighbors[pattern].append(word)

    buildGraph()

    # BFS to find the shortest paths
    def bfs():
        queue = deque([[beginWord]])
        visited = set([beginWord])
        found = False
        while queue and not found:
            local_visited = set()
            for _ in range(len(queue)):
                path = queue.popleft()
                word = path[-1]
                for i in range(len(word)):
                    pattern = word[:i] + '*' + word[i+1:]
                    for neighbor in neighbors[pattern]:
                        if neighbor == endWord:
                            found = True
                            results.append(path + [endWord])
                        if neighbor not in visited:
                            local_visited.add(neighbor)
                            queue.append(path + [neighbor])
            visited.update(local_visited)

    results = []
    bfs()

    return results

def min_add_to_make_valid(s):
    """
    Returns the minimum number of parentheses needed to add to make the parentheses balanced in the given string s.
    """
    open_needed = 0
    close_needed = 0

    for char in s:
        if char == '(':
            open_needed += 1
        elif char == ')':
            if open_needed > 0:
                open_needed -= 1
            else:
                close_needed += 1

    return open_needed + close_needed

