def four_sum(arr, target):
    """
    Finds all unique quadruplets [arr[a], arr[b], arr[c], arr[d]] in arr
    that sum up to the target. The quadruplets should be sorted in
    ascending order both internally and externally.

    :param arr: List of integers
    :param target: The target integer sum
    :return: List of unique quadruplets that sum up to target
    """
    arr.sort()
    quadruplets = []

    n = len(arr)
    for i in range(n - 3):
        # Avoid duplicates for the first number
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        for j in range(i + 1, n - 2):
            # Avoid duplicates for the second number
            if j > i + 1 and arr[j] == arr[j - 1]:
                continue
            left, right = j + 1, n - 1
            while left < right:
                total = arr[i] + arr[j] + arr[left] + arr[right]
                if total == target:
                    quadruplets.append([arr[i], arr[j], arr[left], arr[right]])
                    while left < right and arr[left] == arr[left + 1]:
                        left += 1
                    while left < right and arr[right] == arr[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif total < target:
                    left += 1
                else:
                    right -= 1

    return quadruplets

