def partition_array(arr, k):
    """
    Partitions the array into the minimum number of subarrays such that the sum of each subarray is at most k.
    Returns the minimum number of subarrays needed, or -1 if it's impossible to partition the array this way.
    """
    if not arr:
        return -1

    current_sum = 0
    subarray_count = 0

    for num in arr:
        if num > k:
            return -1
        if current_sum + num > k:
            subarray_count += 1
            current_sum = num
        else:
            current_sum += num

    subarray_count += 1  # Count the last subarray

    return subarray_count

