def numIslands2(m, n, positions):
    """
    Returns the number of islands after each addition of positions.
    """

    def find(parent, i):
        if parent[i] != i:
            parent[i] = find(parent, parent[i])
        return parent[i]

    def union(parent, rank, x, y):
        rootx = find(parent, x)
        rooty = find(parent, y)
        if rootx != rooty:
            if rank[rootx] > rank[rooty]:
                parent[rooty] = rootx
            elif rank[rootx] < rank[rooty]:
                parent[rootx] = rooty
            else:
                parent[rooty] = rootx
                rank[rootx] += 1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    parent = {}
    rank = {}
    island_count = 0
    result = []

    for r, c in positions:
        if (r, c) in parent:
            result.append(island_count)
            continue

        parent[(r, c)] = (r, c)
        rank[(r, c)] = 0
        island_count += 1

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if (nr, nc) in parent:
                if find(parent, (nr, nc)) != find(parent, (r, c)):
                    union(parent, rank, (nr, nc), (r, c))
                    island_count -= 1

        result.append(island_count)

    return result

