def splitArray(nums, m):
    def can_split(nums, m, max_sum):
        current_sum = 0
        required_subarrays = 1
        for num in nums:
            if current_sum + num > max_sum:
                required_subarrays += 1
                current_sum = num
                if required_subarrays > m:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(nums, m, mid):
            right = mid
        else:
            left = mid + 1

    return left

