from collections import deque

def widthOfBinaryTree(root):
    """
    Returns the maximum width of the binary tree rooted at 'root'.
    """
    if not root:
        return 0

    max_width = 0
    queue = deque([(root, 0)])  # node, index

    while queue:
        level_length = len(queue)
        _, first_index = queue[0]  # index of leftmost node in this level
        for _ in range(level_length):
            node, index = queue.popleft()
            if node.left:
                queue.append((node.left, 2 * index))
            if node.right:
                queue.append((node.right, 2 * index + 1))
        _, last_index = queue[-1] if queue else (None, first_index)  # index of rightmost node in this level
        max_width = max(max_width, last_index - first_index + 1)

    return max_width % (10**9 + 7)

def longest_increasing_subsequence_after_replacement(arr):
    """
    Returns the length of the longest possible increasing subsequence in the array 'arr'
    after performing at most one replacement.
    """
    from bisect import bisect_left

    n = len(arr)
    if n <= 1:
        return n

    # Calculate LIS ending at each index without any replacements
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    best = max(lis)

    # Try to replace each element with values that could fit into the current LIS.
    for i in range(n):
        # Prior LIS values before replacing arr[i]
        prefix = lis[:i]
        suffix = lis[i + 1:]

        # Potential maximum LIS length if we replace arr[i] with arr[j] such that lis[j] is maximized
        for j in range(n):
            if i != j:
                candidate = arr[j]
                modified_arr = arr[:i] + [candidate] + arr[i + 1:]
                modified_lis = [1] * n
                for k in range(1, n):
                    for m in range(k):
                        if modified_arr[k] > modified_arr[m]:
                            modified_lis[k] = max(modified_lis[k], modified_lis[m] + 1)
                best = max(best, max(modified_lis))

    return best

