def can_cross_river(stones):
    """
    Determine if the frog can cross the river by landing on the last stone.

    Args:
    stones (List[int]): List of unique integers representing the positions of stones.

    Returns:
    bool: True if the frog can cross the river, otherwise False.
    """
    if not stones or stones[0] != 0:
        return False

    stone_positions = set(stones)
    last_stone = stones[-1]
    memo = {}

    def can_jump(curr_pos, jump_length):
        if (curr_pos, jump_length) in memo:
            return memo[(curr_pos, jump_length)]

        if curr_pos == last_stone:
            return True

        if curr_pos > last_stone or curr_pos < 0 or curr_pos not in stone_positions:
            return False

        for new_jump in [jump_length - 1, jump_length, jump_length + 1]:
            if new_jump > 0 and can_jump(curr_pos + new_jump, new_jump):
                memo[(curr_pos, jump_length)] = True
                return True

        memo[(curr_pos, jump_length)] = False
        return False

    return can_jump(0, 0)

