def length_of_longest_non_decreasing_subsequence(nums):
    """
    Returns the length of the longest subsequence that can be derived by deleting
    some or no elements such that the elements appear in non-decreasing order.

    Parameters:
    nums (List[int]): A list of integers.

    Returns:
    int: The length of the longest non-decreasing subsequence.
    """
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n  # dp[i] will be the length of the longest subsequence that ends with nums[i]

    for i in range(1, n):
        for j in range(i):
            if nums[i] >= nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

