def num_decodings(s):
    """
    Returns the number of ways to decode a string containing only digits.
    """
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(1, n + 1):
        if s[i - 1] != '0':
            dp[i] += dp[i - 1]
        if i > 1 and s[i - 2:i] >= '10' and s[i - 2:i] <= '26':
            dp[i] += dp[i - 2]

    return dp[n]

def find_unique_triplets(nums, target):
    """
    Find all unique triplets in the array which sum to target.

    :param nums: List of integers
    :param target: Integer target sum
    :return: List of triplets that sum to target, in non-decreasing order
    """
    nums.sort()
    triplets = []
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip duplicate values for the first element
        left, right = i + 1, n - 1
        while left < right:
            curr_sum = nums[i] + nums[left] + nums[right]
            if curr_sum == target:
                triplets.append([nums[i], nums[left], nums[right]])
                left += 1
                right -= 1
                # Skip duplicates for the second and third elements
                while left < right and nums[left] == nums[left - 1]:
                    left += 1
                while left < right and nums[right] == nums[right + 1]:
                    right -= 1
            elif curr_sum < target:
                left += 1
            else:
                right -= 1

    return triplets

def process_backspaces(s):
    """
    Processes a string with backspace characters (#) and returns the final string.

    Args:
    s (str): The input string containing lowercase English letters and '#' character.

    Returns:
    str: The processed string after removing characters as specified by backspaces.
    """
    result = []
    for char in s:
        if char == '#':
            if result:
                result.pop()  # Remove the last character in result if it's not empty
        else:
            result.append(char)  # Add current character to result
    return ''.join(result)

def longest_possible_string(s):
    """
    Returns the length of the longest possible string that does not contain any consecutive identical characters.
    """
    if not s:
        return 0

    # Initialize the result with the first character
    result = [s[0]]

    # Iterate through the string starting from the second character
    for char in s[1:]:
        if result and char != result[-1]:
            result.append(char)

    return len(result)

