def closest_pair(arr, x):
    """
    Returns a pair of integers whose sum is closest to x. If multiple pairs qualify,
    the pair with the smallest integers is returned.
    """
    n = len(arr)
    if n < 2:
        return []

    left, right = 0, n - 1
    closest_pair = [arr[left], arr[right]]
    closest_diff = abs(arr[left] + arr[right] - x)

    while left < right:
        current_sum = arr[left] + arr[right]
        current_diff = abs(current_sum - x)

        if current_diff < closest_diff:
            closest_diff = current_diff
            closest_pair = [arr[left], arr[right]]
        elif current_diff == closest_diff:
            if arr[left] < closest_pair[0] or (arr[left] == closest_pair[0] and arr[right] < closest_pair[1]):
                closest_pair = [arr[left], arr[right]]

        if current_sum < x:
            left += 1
        else:
            right -= 1

    return closest_pair

