def compress_string(s):
    """
    Compress the string s such that consecutive occurrences of the same character
    are replaced with the character followed by the number of occurrences.
    Return the compressed string if it is shorter than the original string;
    otherwise, return the original string.
    """
    if not s:
        return s

    compressed = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            count += 1
        else:
            compressed.append(s[i - 1] + str(count))
            count = 1
    compressed.append(s[-1] + str(count))

    compressed_string = ''.join(compressed)

    return compressed_string if len(compressed_string) < len(s) else s

