def longest_palindrome_substring_length(s1, s2):
    """
    Computes the length of the longest possible palindromic substring
    formed by merging s1 and s2.
    """

    def lcs(X, Y):
        m = len(X)
        n = len(Y)
        # Initialize a table to store the length of LCS
        L = [[0] * (n + 1) for _ in range(m + 1)]

        # Build the L[m+1][n+1] table in bottom-up fashion
        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0 or j == 0:
                    L[i][j] = 0
                elif X[i - 1] == Y[j - 1]:
                    L[i][j] = L[i - 1][j - 1] + 1
                else:
                    L[i][j] = max(L[i - 1][j], L[i][j - 1])

        return L[m][n]

    s2_reversed = s2[::-1]
    return lcs(s1, s2_reversed)

