from collections import deque

def min_tunnel_cost(grid):
    """
    Returns the minimum cost required to connect any two buildings in the grid
    through empty spaces 'E', or -1 if it is not possible.
    """
    n, m = len(grid), len(grid[0])
    buildings = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 'B']

    if len(buildings) < 2:
        return -1

    def bfs(start):
        visited = [[False] * m for _ in range(n)]
        queue = deque([(start[0], start[1], 0)]) # (i, j, cost)
        visited[start[0]][start[1]] = True

        while queue:
            i, j, cost = queue.popleft()

            for x, y in [(i - 1, j), (i + 1, j), (i, j - 1), (i, j + 1)]:
                if 0 <= x < n and 0 <= y < m and not visited[x][y]:
                    if grid[x][y] == 'B':
                        return cost
                    if grid[x][y] == 'E':
                        visited[x][y] = True
                        queue.append((x, y, cost + 1))

        return float('inf')

    min_cost = float('inf')
    for building in buildings:
        min_cost = min(min_cost, bfs(building))

    return -1 if min_cost == float('inf') else min_cost

