def find_combinations(nums, target):
    """
    Returns a list of unique combinations that add up to a target sum.
    Each number in the list can be used only once in each combination.
    """
    def backtrack(start, target, path, result):
        if target == 0:
            result.append(path)
            return
        if target < 0:
            return
        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue
            backtrack(i + 1, target - nums[i], path + [nums[i]], result)

    nums.sort()
    result = []
    backtrack(0, target, [], result)
    return result

def three_sum(nums, target):
    nums.sort()
    res = []
    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip same result
        left, right = i + 1, len(nums) - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == target:
                res.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif total < target:
                left += 1
            else:
                right -= 1
    return res

