def maxAreaOfLandmines(grid):
    """
    Returns the size of the largest connected group of landmines (1s) in the grid.
    """
    if not grid:
        return 0

    def dfs(grid, r, c):
        if r < 0 or r >= len(grid) or c < 0 or c >= len(grid[0]) or grid[r][c] == 0:
            return 0
        grid[r][c] = 0  # Mark the landmine as visited
        size = 1  # Current cell
        size += dfs(grid, r+1, c)
        size += dfs(grid, r-1, c)
        size += dfs(grid, r, c+1)
        size += dfs(grid, r, c-1)
        return size

    max_area = 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                max_area = max(max_area, dfs(grid, r, c))

    return max_area

def length_of_longest_substring(s):
    """
    Returns the length of the longest substring with all unique characters.
    """
    char_index_map = {}
    longest = 0
    start = 0

    for index, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start:
            start = char_index_map[char] + 1
        char_index_map[char] = index
        longest = max(longest, index - start + 1)

    return longest

