def min_changes_to_sort_heights(heights):
    n = len(heights)
    if n == 0:
        return 0

    sorted_heights = sorted(heights)

    # We will find the longest common subsequence (LCS) between heights and sorted_heights.
    # The minimum number of changes required will be the length of the array minus the length of the LCS.

    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(n):
            if heights[i] == sorted_heights[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    lcs_length = dp[n][n]

    return n - lcs_length

