def final_string_length(s):
    """
    Returns the length of the final string after repeatedly removing pairs of different consecutive characters.

    Parameters:
    s (str): A binary string consisting of only '0' and '1'.

    Returns:
    int: The length of the final string.
    """
    stack = []

    for char in s:
        if stack and stack[-1] != char:
            stack.pop()
        else:
            stack.append(char)

    return len(stack)

