def flow_off_grid(grid):
    """
    Returns a list of coordinates from which water can flow off the edge of the grid.
    """
    if not grid or not grid[0]:
        return []

    m, n = len(grid), len(grid[0])
    result = []

    def dfs(i, j, visited):
        if (i, j) in visited:
            return
        visited.add((i, j))
        if i == 0 or i == m - 1 or j == 0 or j == n - 1:
            result.append((i, j))

        for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
            if 0 <= x < m and 0 <= y < n and grid[x][y] <= grid[i][j]:
                dfs(x, y, visited)

    visited = set()
    for i in range(m):
        for j in range(n):
            if (i, j) not in visited:
                dfs(i, j, visited)

    return result

