def max_length_even_subarray(arr):
    """
    Returns the maximum length of a subarray that contains only even numbers.
    If no such subarray exists, returns 0.
    """
    max_length = 0
    current_length = 0

    for num in arr:
        if num % 2 == 0:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
        else:
            current_length = 0

    return max_length

