def find_missing_positive(arr):
    n = len(arr)

    # Step 1: Move all non-positive numbers to the left part of the array
    j = 0
    for i in range(n):
        if arr[i] <= 0:
            arr[i], arr[j] = arr[j], arr[i]
            j += 1

    # Step 2: Consider the part of the array from position j onwards
    # Mark the elements present in the range 1 to n-j by negating the value at arr[index-1]
    for i in range(j, n):
        value = abs(arr[i])
        if value <= n - j and arr[j + value - 1] > 0:
            arr[j + value - 1] = -arr[j + value - 1]

    # Step 3: Scan the transformed array to find the first missing positive number
    for i in range(j, n):
        if arr[i] > 0:
            return i - j + 1

    return n - j + 1

