def rob_houses(nums, k):
    """
    Given a list of non-negative integers representing the amount of money of each house, and a non-negative integer k,
    determines the maximum amount of money that can be robbed without robbing adjacent houses and without robbing
    more than k houses in total.
    """
    n = len(nums)
    if n == 0 or k == 0:
        return 0

    # Initialize a 2D dp array where dp[i][j] represents the maximum money that can be robbed from first i houses,
    # robbing exactly j houses.
    dp = [[0] * (k + 1) for _ in range(n)]

    for i in range(n):
        for j in range(1, k + 1):
            # If j == 1, it means we are robbing the first house only if it's the highest up to that house
            if j == 1:
                dp[i][j] = max(nums[:i+1])
            else:
                for x in range(i - 1):
                    dp[i][j] = max(dp[i][j], dp[x][j - 1] + nums[i])

    # The answer is the maximum value in the last row of dp array considering any number j from 1 to k
    return max(dp[-1])

