from collections import Counter

def max_length_palin(words):
    word_freq = Counter(''.join(words))
    length = 0
    has_odd_center = False

    for freq in word_freq.values():
        if freq % 2 == 0:
            length += freq
        else:
            length += freq - 1
            has_odd_center = True

    if has_odd_center:
        length += 1

    return length

