def is_alien_sorted(words, order):
    """
    Returns true if `words` are sorted lexicographically in the given alien `order`.

    Parameters:
    words (list): List of strings representing words in the alien language.
    order (str): A string representing the order of characters in the alien language.

    Returns:
    bool: True if the words are sorted lexicographically in the given alien order, False otherwise.
    """
    order_index = {char: i for i, char in enumerate(order)}

    def is_sorted(w1, w2):
        for c1, c2 in zip(w1, w2):
            if order_index[c1] < order_index[c2]:
                return True
            elif order_index[c1] > order_index[c2]:
                return False
        return len(w1) <= len(w2)

    for i in range(len(words) - 1):
        if not is_sorted(words[i], words[i + 1]):
            return False

    return True

from itertools import combinations

def count_combinations(nums, target):
    """
    Returns the number of unique combinations that can be formed by choosing elements from the array
    where the sum equals the target. Each number in nums can be used once in each combination.
    """
    count = 0
    for r in range(1, len(nums) + 1):
        for combo in combinations(nums, r):
            if sum(combo) == target:
                count += 1
    return count

