def min_score(arr, m):
    def can_divide(max_sum):
        count, current_sum = 1, 0
        for num in arr:
            if current_sum + num > max_sum:
                count += 1
                current_sum = num
                if count > m:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(arr), sum(arr)
    while left < right:
        mid = (left + right) // 2
        if can_divide(mid):
            right = mid
        else:
            left = mid + 1

    return left

