def isAnagram(s1, s2):
    """
    Returns True if s2 is an anagram of s1, otherwise False.

    Args:
    s1 (str): First string.
    s2 (str): Second string, to check if it is an anagram of the first.

    Returns:
    bool: True if s2 is an anagram of s1, False otherwise.
    """
    if len(s1) != len(s2):
        return False

    # Use a dictionary to count the occurrences of each character in s1
    char_count = {}
    for char in s1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Decrease the count for each character found in s2
    for char in s2:
        if char in char_count:
            char_count[char] -= 1
            if char_count[char] == 0:
                del char_count[char]
        else:
            return False

    return len(char_count) == 0

