def is_heap(nums, heap_type='max'):
    """
    Checks whether the given array nums is a valid heap (max-heap or min-heap).

    Args:
    nums : List[int] : The array representing the heap.
    heap_type : str : The type of heap ('max' for max-heap, 'min' for min-heap).

    Returns:
    bool : True if the array represents a valid heap, otherwise False.
    """
    if heap_type not in ['max', 'min']:
        raise ValueError("heap_type should be either 'max' or 'min'.")

    n = len(nums)

    for i in range((n - 2) // 2 + 1):
        left = 2 * i + 1
        right = 2 * i + 2

        if heap_type == 'max':
            if (left < n and nums[i] < nums[left]) or (right < n and nums[i] < nums[right]):
                return False
        else:
            if (left < n and nums[i] > nums[left]) or (right < n and nums[i] > nums[right]):
                return False

    return True

