def max_length_concatenation(words):
    def is_unique(s):
        return len(s) == len(set(s))

    def backtrack(index, current):
        if index == len(words):
            return len(current)

        if is_unique(current + words[index]):
            option1 = backtrack(index + 1, current + words[index])
        else:
            option1 = 0

        option2 = backtrack(index + 1, current)

        return max(option1, option2)

    return backtrack(0, "")

