def longestIncreasingPath(grid):
    """
    Returns the length of the longest increasing path in the grid.
    """
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    memo = [[-1 for _ in range(cols)] for _ in range(rows)]

    def dfs(r, c):
        if memo[r][c] != -1:
            return memo[r][c]

        # The length is at least 1 (the starting cell itself)
        max_len = 1
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] > grid[r][c]:
                max_len = max(max_len, 1 + dfs(nr, nc))

        memo[r][c] = max_len
        return max_len

    max_path = 0
    for r in range(rows):
        for c in range(cols):
            max_path = max(max_path, dfs(r, c))

    return max_path

