def min_students_to_delete(heights):
    """
    Returns the minimum number of students that must be deleted to ensure
    that the heights of the remaining students are in non-decreasing order.
    """
    if not heights:
        return 0

    n = len(heights)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if heights[i] >= heights[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    longest_increasing_subsequence = max(dp)
    return n - longest_increasing_subsequence

