def can_partition_k_subsets(arr, k):
    """
    Determines if the array can be partitioned into k subsets with equal sum.

    Parameters:
    arr (list of int): The array of integers.
    k (int): The number of subsets to partition the array into.

    Returns:
    bool: True if the array can be partitioned into k subsets with equal sum, False otherwise.
    """
    def can_partition(start, k, subset_sum, target, visited):
        if k == 0:
            return True
        if subset_sum == target:
            return can_partition(0, k - 1, 0, target, visited)
        for i in range(start, len(arr)):
            if not visited[i] and subset_sum + arr[i] <= target:
                visited[i] = True
                if can_partition(i + 1, k, subset_sum + arr[i], target, visited):
                    return True
                visited[i] = False
        return False

    total_sum = sum(arr)
    if total_sum % k != 0:
        return False

    target = total_sum // k
    visited = [False] * len(arr)
    return can_partition(0, k, 0, target, visited)

