def isomorphic_strings(words, patterns):
    def is_isomorphic(s, t):
        if len(s) != len(t):
            return False
        mapping_s_t = {}
        mapping_t_s = {}
        for c1, c2 in zip(s, t):
            if c1 in mapping_s_t and mapping_s_t[c1] != c2:
                return False
            if c2 in mapping_t_s and mapping_t_s[c2] != c1:
                return False
            mapping_s_t[c1] = c2
            mapping_t_s[c2] = c1
        return True

    if len(words) != len(patterns):
        return False

    for word, pattern in zip(words, patterns):
        if not is_isomorphic(word, pattern):
            return False
    return True

def two_sum(arr, target):
    """
    Returns the indices of the two numbers such that they add up to the target.
    """
    lookup = {}
    for i, num in enumerate(arr):
        complement = target - num
        if complement in lookup:
            return [lookup[complement], i]
        lookup[num] = i

