def check_if_pair_exists(arr):
    """
    Given an array of unique integers arr, determine if there exists any pair of indices (i, j)
    such that arr[i] = 2 * arr[j] or arr[j] = 2 * arr[i].
    """
    if not arr or len(arr) < 2:
        return False

    elements_set = set(arr)
    for num in arr:
        if num * 2 in elements_set or (num % 2 == 0 and num // 2 in elements_set):
            return True

    return False

