def min_abs_difference(weights):
    """
    This function returns the minimum absolute difference that can be achieved by splitting
    the array into two non-empty subarrays.
    """
    total_sum = sum(weights)
    n = len(weights)

    # Initialize a dictionary to keep track of all possible sums
    possible_sums = {0}

    # Iterate over each weight
    for weight in weights:
        new_sums = set()
        for s in possible_sums:
            new_sums.add(s + weight)
        possible_sums.update(new_sums)

    min_difference = float('inf')

    # Find the subset with the sum closest to half of total sum
    for s in possible_sums:
        if s != 0:
            current_difference = abs(total_sum - 2 * s)
            if current_difference < min_difference:
                min_difference = current_difference

    return min_difference

