def valid_palindrome(s):
    """
    Returns True if the string can be a palindrome after deleting at most one character.
    """
    def is_palindrome_range(i, j):
        """Check if the substring s[i:j+1] is a palindrome."""
        return all(s[k] == s[j-k+i] for k in range(i, (j+i)//2 + 1))

    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            # Try to skip left or right character
            return is_palindrome_range(left + 1, right) or is_palindrome_range(left, right - 1)
        left, right = left + 1, right - 1
    return True

