def evaluate_operations(operations, operands):
    if len(operations) != len(operands):
        raise ValueError("Length of operations and operands must be equal.")

    result = 0
    for i in range(len(operations)):
        operand = int(operands[i])
        operation = operations[i]

        if operation == '+':
            result += operand
        elif operation == '-':
            result -= operand
        elif operation == '*':
            result *= operand
        elif operation == '/':
            if operand == 0:
                raise ZeroDivisionError("Division by zero is undefined.")
            result //= operand  # using floor division to get an integer result

    return result

