def judge_circle(moves):
    """
    Determines whether the robot returns to the starting position after executing the moves.

    Parameters:
    moves (str): A string where each character represents a move ('U', 'D', 'L', 'R')

    Returns:
    bool: True if the robot returns to the starting position, False otherwise.
    """
    x, y = 0, 0
    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
    return x == 0 and y == 0

