def has_cycle(n, edges):
    """
    Determines if the graph contains a cycle.

    Args:
    n (int): the number of nodes in the graph.
    edges (List[List[int]]): the list of undirected edges in the graph.

    Returns:
    bool: True if there is a cycle in the graph, False otherwise.
    """
    from collections import defaultdict

    # Create an adjacency list for the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n

    def dfs(node, parent):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    for i in range(n):
        if not visited[i]:
            if dfs(i, -1):
                return True

    return False

