def calculate_total_payroll(employees, managerId):
    def get_subordinates_payroll(managerId):
        total_payroll = employees[managerId]['salary']
        for emp_id in employees:
            if employees[emp_id]['managerId'] == managerId:
                total_payroll += get_subordinates_payroll(emp_id)
        return total_payroll

    if managerId not in employees:
        return 0

    return get_subordinates_payroll(managerId)

