def longest_alphabetical_substring(s):
    """
    Returns the length of the longest substring where characters are in alphabetical order.
    """
    max_length = 0
    current_length = 0

    for i in range(len(s)):
        if i == 0 or s[i] >= s[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

