def min_cut_to_non_decreasing(heights):
    n = len(heights)
    if n == 0:
        return 0

    left = [0] * n
    right = [0] * n

    # Compute the length of the non-decreasing subarray ending at each point
    for i in range(1, n):
        if heights[i] >= heights[i - 1]:
            left[i] = left[i - 1] + 1
        else:
            left[i] = 0

    # Compute the length of the non-decreasing subarray starting at each point
    for i in range(n - 2, -1, -1):
        if heights[i] <= heights[i + 1]:
            right[i] = right[i + 1] + 1
        else:
            right[i] = 0

    max_keep = 0

    # Check each possible cut position
    for i in range(n):
        max_keep = max(max_keep, left[i] + 1, right[i] + 1)
        if i < n - 1:
            max_keep = max(max_keep, left[i] + right[i + 1] + 1)

    return n - max_keep

