def is_balanced(s):
    """
    Determine if the brackets in the string s are balanced.

    Args:
    s (str): A string containing round and curly brackets.

    Returns:
    bool: True if the string is balanced, otherwise False.
    """
    stack = []
    bracket_map = {')': '(', '}': '{'}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if not stack or stack.pop() != bracket_map[char]:
                return False
        else:
            # If any other character, continue (although the prompt does not specify other characters)
            continue

    return not stack

def capture_regions(board):
    if not board:
        return board

    rows, cols = len(board), len(board[0])

    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or board[r][c] != 'O':
            return
        board[r][c] = 'T'
        dfs(r+1, c)
        dfs(r-1, c)
        dfs(r, c+1)
        dfs(r, c-1)

    # Step 1: Capture unsurrounded regions by marking border-connected 'O's as 'T'
    for r in range(rows):
        dfs(r, 0)
        dfs(r, cols-1)
    for c in range(cols):
        dfs(0, c)
        dfs(rows-1, c)

    # Step 2: Flip all remaining 'O's to 'X' and convert 'T' back to 'O'
    for r in range(rows):
        for c in range(cols):
            if board[r][c] == 'O':
                board[r][c] = 'X'
            elif board[r][c] == 'T':
                board[r][c] = 'O'

    return board

from collections import deque

def shortest_path(grid):
    """
    Returns the length of the shortest path from the starting point (1) to the
    bottom-right corner of the grid (m-1, n-1). Returns -1 if no valid path exists.
    """

    def bfs(start):
        queue = deque([(start[0], start[1], 0)])  # (row, col, distance)
        visited = set()
        visited.add((start[0], start[1]))

        while queue:
            r, c, dist = queue.popleft()

            if (r, c) == (len(grid) - 1, len(grid[0]) - 1):
                return dist

            directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and (nr, nc) not in visited and grid[nr][nc] == 0:
                    queue.append((nr, nc, dist + 1))
                    visited.add((nr, nc))
        return -1

    # Find the starting point
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                return bfs((i, j))

    return -1

def rob(nums):
    def rob_linear(houses):
        rob1, rob2 = 0, 0
        for house in houses:
            new_rob = max(rob1 + house, rob2)
            rob1 = rob2
            rob2 = new_rob
        return rob2

    if not nums:
        return 0
    elif len(nums) == 1:
        return nums[0]
    else:
        return max(rob_linear(nums[:-1]), rob_linear(nums[1:]))

