def min_deletions_to_beautiful(s):
    """
    Returns the minimum number of deletions required to make the binary string `s` beautiful.
    """
    deletions = 0
    i = 0

    while i < len(s) - 2:
        if s[i:i+3] == '010':
            deletions += 1
            i += 3
        else:
            i += 1

    return deletions

def three_sum(numbers):
    """
    Returns a list of all unique triplets (a, b, c) in the array `numbers`
    such that a + b + c = 0. The triplets are sorted in non-descending order and
    no triplet is repeated in the output.
    """
    numbers.sort()
    result = []
    n = len(numbers)

    for i in range(n - 2):
        if i > 0 and numbers[i] == numbers[i - 1]:
            continue

        left, right = i + 1, n - 1
        while left < right:
            total = numbers[i] + numbers[left] + numbers[right]
            if total == 0:
                result.append([numbers[i], numbers[left], numbers[right]])
                while left < right and numbers[left] == numbers[left + 1]:
                    left += 1
                while left < right and numbers[right] == numbers[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif total < 0:
                left += 1
            else:
                right -= 1

    return result

