import math

def smallest_encompassing_circle(points):
    """
    Returns the center and radius of the smallest circle that can encompass all given points.
    """

    def distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    if not points:
        return (0, 0, 0)

    # Find minimum and maximum x and y to determine initial bounds for the circle
    min_x = min(points, key=lambda p: p[0])[0]
    max_x = max(points, key=lambda p: p[0])[0]
    min_y = min(points, key=lambda p: p[1])[1]
    max_y = max(points, key=lambda p: p[1])[1]

    center_x = (min_x + max_x) / 2
    center_y = (min_y + max_y) / 2
    radius = max(distance((center_x, center_y), point) for point in points)

    return (round(center_x, 2), round(center_y, 2), round(radius, 2))

