def length_of_longest_subarray_with_two_distinct(nums):
    """
    Finds the length of the longest subarray with no more than two distinct integers.
    """
    if not nums:
        return 0

    start = 0
    max_len = 0
    freq_map = {}

    for end in range(len(nums)):
        if nums[end] in freq_map:
            freq_map[nums[end]] += 1
        else:
            freq_map[nums[end]] = 1

        while len(freq_map) > 2:
            freq_map[nums[start]] -= 1
            if freq_map[nums[start]] == 0:
                del freq_map[nums[start]]
            start += 1

        max_len = max(max_len, end - start + 1)

    return max_len

