def subarraysWithKDistinct(arr, k):
    """
    Returns the number of subarrays with exactly k different integers.
    """
    from collections import Counter

    def at_most_k(arr, k):
        count = Counter()
        res = left = 0
        for right, value in enumerate(arr):
            if count[value] == 0:
                k -= 1
            count[value] += 1
            while k < 0:
                count[arr[left]] -= 1
                if count[arr[left]] == 0:
                    k += 1
                left += 1
            res += right - left + 1
        return res

    return at_most_k(arr, k) - at_most_k(arr, k - 1)

