def can_ship(weights, days, capacity):
    current_weight = 0
    current_days = 1

    for weight in weights:
        if current_weight + weight > capacity:
            current_days += 1
            current_weight = 0
        if current_days > days:
            return False
        current_weight += weight

    return current_days <= days

def ship_within_days(weights, days):
    left = max(weights)
    right = sum(weights)

    while left < right:
        mid = (left + right) // 2
        if can_ship(weights, days, mid):
            right = mid
        else:
            left = mid + 1

    return left

