def process_operations(operations):
    """
    Processes a list of operations and returns the final state of the stack and
    the list of elements returned by peeks.

    operations: list of strings, where each string is a valid stack operation such as "push x", "pop", "peek".

    Returns: a list representing the final state of the stack and a list of peeked values, if any.
    """
    stack = []
    peeked_values = []

    for op in operations:
        if op.startswith("push "):
            _, value = op.split()
            stack.append(int(value))
        elif op == "pop":
            if stack:
                stack.pop()
        elif op == "peek":
            if stack:
                peeked_values.append(stack[-1])

    return stack, peeked_values

def longest_subarray_with_eligible_buildings(heights, k):
    """
    Returns the length of the largest contiguous subarray where all buildings are taller than or equal to k.
    """
    max_length = 0
    current_length = 0

    for height in heights:
        if height >= k:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
            current_length = 0

    return max(max_length, current_length)

