def suggest_friends(friends, user):
    """
    Suggest friends for a user based on their friends of friends but not direct friends of the user.

    Parameters:
    friends (list of list of int): List where friends[i] is a list of friends of i.
    user (int): The specific user for whom to suggest friends.

    Returns:
    list of int: List of suggested friends sorted in ascending order.
    """
    direct_friends = set(friends[user])
    suggestions = set()

    for friend in direct_friends:
        for friend_of_friend in friends[friend]:
            if friend_of_friend != user and friend_of_friend not in direct_friends:
                suggestions.add(friend_of_friend)

    return sorted(suggestions)

