def distinct_ways_to_achieve_target(coins, target):
    MOD = 10**9 + 7

    # dp array to store the number of ways to achieve each value up to target
    dp = [0] * (target + 1)
    dp[0] = 1  # There's one way to achieve a target of 0 - using no coins

    # Iterate over each coin and update the dp array
    for coin in coins:
        for i in range(coin, target + 1):
            dp[i] = (dp[i] + dp[i - coin]) % MOD

    return dp[target]

