def count_pairs_with_sum(arr, target):
    """
    Returns the number of pairs of integers in the array whose sum equals the target.
    """
    pairs_count = 0
    seen = {}

    for number in arr:
        complement = target - number
        if complement in seen:
            pairs_count += seen[complement]

        if number in seen:
            seen[number] += 1
        else:
            seen[number] = 1

    return pairs_count

