def longest_substring_with_one_unique_char(s: str, k: int) -> int:
    """
    Returns the length of the longest substring containing only one unique character after removing up to k characters.
    """
    max_length = 0
    for unique_char in set(s):
        current_k = k
        start = 0
        count_changes = 0

        for end in range(len(s)):
            if s[end] != unique_char:
                count_changes += 1

            while count_changes > current_k:
                if s[start] != unique_char:
                    count_changes -= 1
                start += 1

            max_length = max(max_length, end - start + 1)

    return max_length

