def threeSumEqualsTarget(nums, target):
    """
    Returns True if there exist three elements in nums whose sum is equal to target.
    """
    nums.sort()
    n = len(nums)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if nums[i] + nums[j] + nums[k] == target:
                    return True
    return False

