def canPartition(nums):
    """
    Returns True if it is possible to partition the list nums into two subsets
    such that the sum of elements in both subsets is equal. Otherwise, returns False.
    """
    total_sum = sum(nums)
    if total_sum % 2 != 0:
        return False

    target = total_sum // 2
    subset_sum = set([0])

    for num in nums:
        new_sums = set()
        for s in subset_sum:
            if s + num == target:
                return True
            elif s + num < target:
                new_sums.add(s + num)
        subset_sum.update(new_sums)

    return target in subset_sum

