def max_tasks(tasks, deadline, rest):
    tasks.sort()
    time_spent = 0
    completed_tasks = 0

    for task in tasks:
        if time_spent + task <= deadline:
            time_spent += task
            completed_tasks += 1
            if time_spent + rest <= deadline:
                time_spent += rest
            else:
                break
        else:
            break

    return completed_tasks

