def longest_increasing_path(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[-1] * n for _ in range(m)]

    def dfs(x, y):
        if dp[x][y] != -1:
            return dp[x][y]

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        max_length = 1

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] > grid[x][y]:
                max_length = max(max_length, 1 + dfs(nx, ny))

        dp[x][y] = max_length
        return max_length

    res = 0
    for i in range(m):
        for j in range(n):
            res = max(res, dfs(i, j))

    return res

