def maximalRectangle(matrix):
    def max_histogram_area(height):
        stack = []
        max_area = 0
        index = 0
        while index < len(height):
            if not stack or height[stack[-1]] <= height[index]:
                stack.append(index)
                index += 1
            else:
                top_of_stack = stack.pop()
                area = (height[top_of_stack] *
                       ((index - stack[-1] - 1) if stack else index))
                max_area = max(max_area, area)
        while stack:
            top_of_stack = stack.pop()
            area = (height[top_of_stack] *
                   ((index - stack[-1] - 1) if stack else index))
            max_area = max(max_area, area)
        return max_area

    if not matrix:
        return 0

    max_area = 0
    height = [0] * len(matrix[0])

    for row in matrix:
        for index, val in enumerate(row):
            if val == 0:
                height[index] = 0
            else:
                height[index] += 1
        max_area = max(max_area, max_histogram_area(height))

    return max_area

def length_of_longest_substring_k_distinct(s, k):
    """
    Given a string s and an integer k, returns the length of the longest substring
    that contains at most k distinct characters.
    """
    if k == 0:
        return 0

    n = len(s)
    if n == 0:
        return 0

    left = 0
    right = 0
    max_length = 0
    char_count = {}

    while right < n:
        if s[right] in char_count:
            char_count[s[right]] += 1
        else:
            char_count[s[right]] = 1

        while len(char_count) > k:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_length = max(max_length, right - left + 1)
        right += 1

    return max_length

