def max_non_overlapping_events(startTimes, endTimes):
    events = sorted(zip(endTimes, startTimes))
    max_events = 0
    last_end_time = float('-inf')

    for end, start in events:
        if start >= last_end_time:
            max_events += 1
            last_end_time = end

    return max_events

