def is_valid(s):
    """
    Determines if the input string containing just the characters `(`, `)`, `{`, `}`,
    `[` and `]` is valid based on the criteria:
    - Open brackets are closed by the same type of brackets.
    - Open brackets are closed in the correct order.

    :param s: str
    :return: bool
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

def capture_regions(board):
    if not board:
        return board

    rows, cols = len(board), len(board[0])

    def dfs(i, j):
        if i < 0 or i >= rows or j < 0 or j >= cols or board[i][j] != 'O':
            return
        board[i][j] = 'E'  # Mark as part of the escaped region
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for direction in directions:
            ni, nj = i + direction[0], j + direction[1]
            dfs(ni, nj)

    # Start DFS from 'O's on the border
    for i in range(rows):
        for j in [0, cols-1]:  # First and last column
            if board[i][j] == 'O':
                dfs(i, j)

    for j in range(cols):
        for i in [0, rows-1]:  # First and last row
            if board[i][j] == 'O':
                dfs(i, j)

    # After marking escape regions, flip the rest 'O' to 'X' and 'E' back to 'O'
    for i in range(rows):
        for j in range(cols):
            if board[i][j] == 'O':
                board[i][j] = 'X'
            elif board[i][j] == 'E':
                board[i][j] = 'O'

    return board

def can_make_all_chars_same(s):
    """
    Determines if it is possible to make all characters in the string the same
    with at most one move.

    Args:
    s (str): Input string of lowercase English letters.

    Returns:
    bool: True if it's possible to make all characters the same, False otherwise.
    """
    if not s:
        return False

    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # If we have more than 2 unique characters, it's not possible with at most one move
    if len(char_count) > 2:
        return False

    # If there are exactly 2 unique characters, check their counts
    if len(char_count) == 2:
        vals = list(char_count.values())
        return 1 in vals

    # If all characters are already the same
    return True

