from collections import deque

def shortest_path_with_treasures(grid):
    # Helper function to get valid neighbors
    def get_neighbors(r, c, m, n):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < m and 0 <= nc < n:
                yield nr, nc

    # Find all the treasures and grid dimensions
    m, n = len(grid), len(grid[0])
    treasures = set()
    for r in range(m):
        for c in range(n):
            if grid[r][c] == 999:
                treasures.add((r, c))

    # Use BFS for shortest path search with multi-source
    queue = deque([(0, 0, frozenset(), 0)])
    visited = set([(0, 0, frozenset())])

    while queue:
        r, c, collected_treasures, steps = queue.popleft()

        # If we have reached the bottom-right cell and collected all treasures
        if (r == m-1 and c == n-1 and collected_treasures == treasures):
            return steps

        # Explore neighbors
        for nr, nc in get_neighbors(r, c, m, n):
            if grid[nr][nc] == -1:
                continue  # Skip obstacles

            new_collected = collected_treasures | frozenset([(nr, nc)]) if grid[nr][nc] == 999 else collected_treasures

            if (nr, nc, new_collected) not in visited:
                visited.add((nr, nc, new_collected))
                queue.append((nr, nc, new_collected, steps + 1))

    # If we exhaust the queue without finding a valid path
    return -1

