def longest_contiguous_substring(s):
    """
    Returns the length of the longest contiguous substring containing only one distinct letter.
    """
    if not s:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    max_length = max(max_length, current_length)

