def max_subarrays_with_sum_limit(arr, k):
    subarrays = []  # Initialize list to store subarrays
    current_sum = 0  # Initialize current subarray sum
    current_subarray = []  # Initialize current subarray

    for num in arr:
        if current_sum + num > k:
            # When adding num exceeds the limit, start a new subarray
            subarrays.append(current_subarray)
            current_subarray = [num]
            current_sum = num
        else:
            # Otherwise, add num to the current subarray
            current_subarray.append(num)
            current_sum += num

    # Append the last subarray
    if current_subarray:
        subarrays.append(current_subarray)

    # Return the number of subarrays formed
    return len(subarrays)

