from functools import lru_cache

def num_decodings(s):
    """
    Returns the total number of distinct decoding combinations for a given string s of digits.
    """
    if not s:
        return 0

    digit_to_char = {
        '0': ' ',
        '1': '',
        '2': 'abc',
        '3': 'def',
        '4': 'ghi',
        '5': 'jkl',
        '6': 'mno',
        '7': 'pqrs',
        '8': 'tuv',
        '9': 'wxyz'
    }

    # Caching the calculated results
    @lru_cache(None)
    def backtrack(index):
        if index == len(s):
            return 1
        if s[index] == '1':
            return backtrack(index + 1)

        total_ways = 0
        for char in digit_to_char[s[index]]:
            total_ways += backtrack(index + 1)

        return total_ways

    return backtrack(0)

