def longest_palindromic_subsequence_with_one_swap(s):
    """
    Returns the length of the longest palindromic subsequence that can be
    obtained by performing at most one swap operation.
    """
    def longest_palindromic_subsequence(s):
        n = len(s)
        dp = [[0] * n for _ in range(n)]
        for i in range(n):
            dp[i][i] = 1
        for cl in range(2, n+1):
            for i in range(n-cl+1):
                j = i + cl - 1
                if s[i] == s[j] and cl == 2:
                    dp[i][j] = 2
                elif s[i] == s[j]:
                    dp[i][j] = dp[i+1][j-1] + 2
                else:
                    dp[i][j] = max(dp[i][j-1], dp[i+1][j])
        return dp[0][n-1]

    n = len(s)
    max_length = longest_palindromic_subsequence(s)

    for i in range(n):
        for j in range(i+1, n):
            if s[i] != s[j]:
                swapped_s = list(s)
                swapped_s[i], swapped_s[j] = swapped_s[j], swapped_s[i]
                max_length = max(max_length, longest_palindromic_subsequence(''.join(swapped_s)))

    return max_length

