def count_sum_ways(num):
    """
    Returns the number of unique sets of distinct non-negative integers that sum to num.
    """
    dp = [0] * (num + 1)
    dp[0] = 1

    for i in range(1, num + 1):
        for j in range(i, num + 1):
            dp[j] += dp[j - i]

    return dp[num]

