def increasing_triplet(arr):
    """
    Determines if there exist three indices i, j, k such that
    0 <= i < j < k < len(arr) and arr[i] < arr[j] < arr[k].

    :param arr: List[int] - list of integers
    :return: bool - True if such indices exist, otherwise False
    """
    if len(arr) < 3:
        return False

    first = second = float('inf')
    for num in arr:
        if num <= first:
            first = num
        elif num <= second:
            second = num
        else:
            return True

    return False

