def evaluate_expression(expr):
    """
    Evaluate a mathematical expression and return the result as an integer.
    The expression can contain integers, +, -, *, / operators, and parentheses.
    """
    import re

    def parse_expression(tokens):
        """
        Parse and evaluate the tokens using a recursive approach to handle parentheses.
        """
        stack = []
        num = 0
        sign = '+'

        def apply_operation(stack, sign, num):
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                top = stack.pop()
                stack.append(int(top / num))  # Truncate towards zero

        while tokens:
            token = tokens.pop(0)
            if token.isdigit():
                num = int(token)
            elif token in "+-*/":
                apply_operation(stack, sign, num)
                num = 0
                sign = token
            elif token == '(':
                num = parse_expression(tokens)
            elif token == ')':
                break

        apply_operation(stack, sign, num)
        return sum(stack)

    # Tokenize the expression
    tokens = re.findall(r'\d+|[+*/()-]', expr.replace(' ', ''))

    return parse_expression(tokens)

