def minimum_subarrays(heights, k):
    if not heights:
        return 0

    subarrays = 1
    start = 0

    for i in range(1, len(heights)):
        if max(heights[start:i + 1]) - min(heights[start:i + 1]) > k:
            subarrays += 1
            start = i

    return subarrays

