def rotate(matrix):
    """
    Rotates an n x n 2D matrix by 90 degrees clockwise in-place.

    :param matrix: List[List[int]] - the n x n 2D matrix
    """
    n = len(matrix)

    # Transpose the matrix (swap rows with columns)
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row to get the rotated matrix
    for i in range(n):
        matrix[i].reverse()

