def max_distinct_elements(arr, k):
    """
    Returns the maximum number of distinct elements that can appear in any subarray of size k.
    """
    if k > len(arr):
        return len(set(arr))

    max_distinct = 0
    current_window = {}
    distinct_count = 0

    for i in range(len(arr)):
        if arr[i] not in current_window or current_window[arr[i]] == 0:
            distinct_count += 1
        current_window[arr[i]] = current_window.get(arr[i], 0) + 1

        if i >= k - 1:
            max_distinct = max(max_distinct, distinct_count)

            outgoing_element = arr[i - k + 1]
            current_window[outgoing_element] -= 1
            if current_window[outgoing_element] == 0:
                distinct_count -= 1

    return max_distinct

def find_and_replace_pattern(words, pattern):
    def match(word, pattern):
        if len(word) != len(pattern):
            return False

        char_map_word_to_pattern = {}
        char_map_pattern_to_word = {}

        for w_char, p_char in zip(word, pattern):
            if (w_char in char_map_word_to_pattern and char_map_word_to_pattern[w_char] != p_char) or \
               (p_char in char_map_pattern_to_word and char_map_pattern_to_word[p_char] != w_char):
                return False
            char_map_word_to_pattern[w_char] = p_char
            char_map_pattern_to_word[p_char] = w_char

        return True

    result = []
    for word in words:
        if match(word, pattern):
            result.append(word)

    return result

