def largest_island(grid):
    """
    Returns the size of the largest possible island after flipping one 0 to a 1.
    """
    def dfs(x, y, index):
        if 0 <= x < n and 0 <= y < n and grid[x][y] == 1:
            grid[x][y] = index
            size = 1
            for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                size += dfs(x + dx, y + dy, index)
            return size
        return 0

    n = len(grid)
    index = 2
    sizes = {0: 0}

    # Step 1: Use DFS to find all islands and their sizes
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                sizes[index] = dfs(i, j, index)
                index += 1

    # Step 2: Check all 0s to see the largest potential island if we flip one 0
    result = max(sizes.values(), default=0)
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                seen = set()
                possible_size = 1  # the new 1 we just flipped
                for dx, dy in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                    ni, nj = i + dx, j + dy
                    if 0 <= ni < n and 0 <= nj < n:
                        island_index = grid[ni][nj]
                        if island_index > 1 and island_index not in seen:
                            seen.add(island_index)
                            possible_size += sizes[island_index]
                result = max(result, possible_size)

    return result

