def to_wave_array(arr):
    """
    Modifies the given list in-place into a wave array.
    A wave array satisfies the condition:
    - arr[i] >= arr[i+1] if i is even
    - arr[i] <= arr[i+1] if i is odd
    """
    for i in range(len(arr) - 1):
        if i % 2 == 0:
            if arr[i] < arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]
        else:
            if arr[i] > arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]

    return arr

