import random

def kth_smallest(arr, k):
    """
    Find the k-th smallest element in an unsorted array using the Quickselect algorithm.
    :param arr: List[int] - List of unsorted integers.
    :param k: int - The order of the smallest element to find (1 based index).
    :return: int - The k-th smallest element.
    """
    if arr is None or len(arr) < k:
        raise ValueError("Array must have at least k elements")

    return quickselect(arr, 0, len(arr) - 1, k - 1)

def quickselect(arr, low, high, k):
    """
    Helper function to perform the quickselect algorithm.
    """
    if low == high:
        return arr[low]

    pivot_index = random.randint(low, high)
    pivot_index = partition(arr, low, high, pivot_index)

    if k == pivot_index:
        return arr[k]
    elif k < pivot_index:
        return quickselect(arr, low, pivot_index - 1, k)
    else:
        return quickselect(arr, pivot_index + 1, high, k)

def partition(arr, low, high, pivot_index):
    """
    Partition the array around the pivot.
    """
    pivot_value = arr[pivot_index]
    arr[pivot_index], arr[high] = arr[high], arr[pivot_index]
    store_index = low

    for i in range(low, high):
        if arr[i] < pivot_value:
            arr[store_index], arr[i] = arr[i], arr[store_index]
            store_index += 1

    arr[store_index], arr[high] = arr[high], arr[store_index]
    return store_index

