def smallest_subsequence(s, k):
    from collections import Counter

    count = Counter(s)
    stack = []
    seen = set()

    for char in s:
        if char not in seen:
            while stack and stack[-1] > char and count[stack[-1]] > 0 and len(seen) + 1 <= k:
                removed_char = stack.pop()
                seen.remove(removed_char)
            if len(seen) < k:
                stack.append(char)
                seen.add(char)
        count[char] -= 1

    if len(seen) != k:
        return ""

    return "".join(stack)

