def remove_duplicates(nums):
    """
    Removes duplicates from the sorted list nums in-place, fills remaining slots with -1
    and returns the new length.
    """
    if not nums:
        return 0  # If the list is empty, return 0

    write_index = 1

    for i in range(1, len(nums)):
        if nums[i] != nums[i - 1]:
            nums[write_index] = nums[i]
            write_index += 1

    # Fill the remaining slots with -1
    for i in range(write_index, len(nums)):
        nums[i] = -1

    return write_index

def count_unique_pairs(arr, k):
    """
    Returns the count of unique pairs (arr[i], arr[j]) such that i != j and arr[i] + arr[j] = k.
    """
    unique_pairs = set()
    seen = set()

    for num in arr:
        complement = k - num
        if complement in seen:
            unique_pairs.add(tuple(sorted((num, complement))))
        seen.add(num)

    return len(unique_pairs)

