def getSkyline(heights):
    """
    Returns the skyline of the given buildings represented by heights.
    """
    if not heights:
        return []

    n = len(heights)
    result = [[0, heights[0]]]

    for i in range(1, n):
        if heights[i] != heights[i - 1]:
            result.append([i, heights[i]])

    result.append([n, 0])

    return result

