def findNumberOfGroups(coordinates):
    """
    Finds the number of distinct connected groups formed by the points.
    """
    from collections import defaultdict

    def dfs(point, visited, graph):
        stack = [point]
        while stack:
            current = stack.pop()
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    stack.append(neighbor)

    graph = defaultdict(list)

    for i, (x1, y1) in enumerate(coordinates):
        for j, (x2, y2) in enumerate(coordinates):
            if i != j and (x1 == x2 or y1 == y2):
                graph[(x1, y1)].append((x2, y2))
                graph[(x2, y2)].append((x1, y1))

    visited = set()
    count = 0

    for point in coordinates:
        if tuple(point) not in visited:
            dfs(tuple(point), visited, graph)
            count += 1

    return count

