def valid_indices_count(heights, t):
    """
    Returns the number of indices i such that the absolute difference between
    heights at index i and its adjacent indices are all greater than or equal to threshold t.
    """
    n = len(heights)
    if n == 0:
        return 0
    if n == 1:
        return 1

    count = 0
    for i in range(n):
        valid = True
        if i > 0 and abs(heights[i] - heights[i-1]) < t:
            valid = False
        if i < n - 1 and abs(heights[i] - heights[i+1]) < t:
            valid = False
        if valid:
            count += 1
    return count

