def count_completely_surrounded_islands(matrix):
    def dfs(matrix, i, j, is_surrounded):
        if i < 0 or j < 0 or i >= len(matrix) or j >= len(matrix[0]):
            return False
        if matrix[i][j] == 0:
            return True
        if matrix[i][j] == -1:
            return True
        matrix[i][j] = -1
        top = dfs(matrix, i - 1, j, is_surrounded)
        bottom = dfs(matrix, i + 1, j, is_surrounded)
        left = dfs(matrix, i, j - 1, is_surrounded)
        right = dfs(matrix, i, j + 1, is_surrounded)
        return top and bottom and left and right

    if not matrix or not matrix[0]:
        return 0

    count = 0

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] == 1:
                if dfs(matrix, i, j, True):
                    count += 1

    return count

def two_sum(nums, target):
    """
    Returns the indices of the two numbers in `nums` that add up to `target`.
    The indices should be returned in ascending order. If no such pair exists,
    return an empty array.
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return sorted([num_to_index[complement], i])
        num_to_index[num] = i

    return []

