def maximalRectangle(mat):
    if not mat:
        return 0

    max_area = 0
    n = len(mat[0])
    heights = [0] * n

    for row in mat:
        for i in range(n):
            if row[i] == 0:
                heights[i] = 0
            else:
                heights[i] += 1

        max_area = max(max_area, largestRectangleArea(heights))

    return max_area

def largestRectangleArea(heights):
    heights.append(0)
    stack = [-1]
    max_area = 0

    for i in range(len(heights)):
        while heights[i] < heights[stack[-1]]:
            h = heights[stack.pop()]
            w = i - stack[-1] - 1
            max_area = max(max_area, h * w)
        stack.append(i)

    heights.pop()
    return max_area

from collections import Counter, deque
import heapq

def rearrange_string(s, k):
    if k == 0:
        return s

    count = Counter(s)
    max_heap = [(-value, key) for key, value in count.items()]
    heapq.heapify(max_heap)

    queue = deque()

    result = []

    while max_heap:
        freq, char = heapq.heappop(max_heap)
        result.append(char)

        queue.append((char, freq + 1))

        if len(queue) >= k:
            front_char, front_freq = queue.popleft()
            if front_freq < 0:
                heapq.heappush(max_heap, (front_freq, front_char))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return ""

from collections import deque

def longest_subarray(nums, limit):
    max_d = deque()
    min_d = deque()
    left = 0
    max_len = 0

    for right in range(len(nums)):
        while max_d and nums[max_d[-1]] <= nums[right]:
            max_d.pop()
        while min_d and nums[min_d[-1]] >= nums[right]:
            min_d.pop()

        max_d.append(right)
        min_d.append(right)

        while nums[max_d[0]] - nums[min_d[0]] > limit:
            left += 1
            if max_d[0] < left:
                max_d.popleft()
            if min_d[0] < left:
                min_d.popleft()

        max_len = max(max_len, right - left + 1)

    return max_len

