def num_matching_subseq(s, words):
    def is_subsequence(word, s):
        it = iter(s)
        return all(char in it for char in word)

    count = 0
    for word in words:
        if is_subsequence(word, s):
            count += 1
    return count

def count_pairs_with_sum(arr, k):
    """
    Returns the number of distinct pairs (i, j) such that arr[i] + arr[j] == k.
    """
    pair_count = 0
    seen = {}

    for num in arr:
        target = k - num
        if target in seen:
            pair_count += seen[target]

        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1

    return pair_count

