from collections import deque

def wallsAndGates(rooms):
    """
    Fill each empty room with the distance to its nearest gate.

    :param rooms: List[List[int]] - The input 2D grid.
    :return: None - The grid is modified in-place.
    """
    if not rooms or not rooms[0]:
        return

    INF = 2 ** 31 - 1
    m, n = len(rooms), len(rooms[0])
    queue = deque()

    # Find all gates and add them to the queue
    for i in range(m):
        for j in range(n):
            if rooms[i][j] == 0:
                queue.append((i, j))

    # BFS from the gates
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and rooms[nx][ny] == INF:
                rooms[nx][ny] = rooms[x][y] + 1
                queue.append((nx, ny))

