def count_quadruples(arr, target):
    """
    Returns the number of tuples (i, j, k, l) such that i < j < k < l
    and arr[i] + arr[j] + arr[k] + arr[l] == target.
    """
    n = len(arr)
    count = 0

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                for l in range(k + 1, n):
                    if arr[i] + arr[j] + arr[k] + arr[l] == target:
                        count += 1

    return count

