from collections import Counter

def wordSubsets(words1, words2):
    """
    Returns a list of words in words1 where every string in words2 is a subset of it.
    """
    def countChars(word):
        return Counter(word)

    def isSubset(word_count, words2_count):
        for char, count in words2_count.items():
            if word_count[char] < count:
                return False
        return True

    max_words2_count = Counter()
    for word in words2:
        word_count = countChars(word)
        for char, count in word_count.items():
            max_words2_count[char] = max(max_words2_count[char], count)

    result = []
    for word in words1:
        if isSubset(countChars(word), max_words2_count):
            result.append(word)

    return result

