def length_of_LDS(arr):
    """
    Returns the length of the longest decreasing subsequence in the array.
    """
    if not arr:
        return 0

    n = len(arr)
    # Initialize the list to hold the length of longest decreasing subsequence ending at each index
    lds_lengths = [1] * n

    # Compute the lengths for each index
    for i in range(1, n):
        for j in range(i):
            if arr[j] > arr[i]:
                lds_lengths[i] = max(lds_lengths[i], lds_lengths[j] + 1)

    return max(lds_lengths)

