def has_path(graph, start, end):
    """
    Determines if there is a path from start node to end node in a directed graph.
    :param graph: List[List[int]] - Adjacency matrix representation of the graph
    :param start: int - The starting node
    :param end: int - The destination node
    :return: bool - True if there is a path from start to end, otherwise False
    """
    def dfs(current, destination, visited):
        if current == destination:
            return True
        visited.add(current)
        for neighbor, is_edge in enumerate(graph[current]):
            if is_edge and neighbor not in visited:
                if dfs(neighbor, destination, visited):
                    return True
        return False

    visited = set()
    return dfs(start, end, visited)

