def three_sum(nums, target):
    """
    Determines if there exist three integers in `nums` that add up to the `target`.
    """
    nums.sort()  # Sort the array to use two-pointer technique
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip duplicate values for the first element
        left, right = i + 1, n - 1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

