def max_visible_buildings(heights1, heights2):
    """
    Returns a tuple containing the maximum number of visible buildings from left
    for each of the height arrays heights1 and heights2.
    """
    def count_visible_buildings(heights):
        max_height = 0
        visible_count = 0
        for height in heights:
            if height > max_height:
                visible_count += 1
                max_height = height
        return visible_count

