def longest_substring_with_exactly_k_repeats(s, k):
    """
    Returns the length of the longest substring of s such that the count of each character
    in that substring is exactly k.
    """
    if k == 0:
        return -1

    max_len = -1
    n = len(s)

    for l in range(n):
        freq = {}
        for r in range(l, n):
            if s[r] in freq:
                freq[s[r]] += 1
            else:
                freq[s[r]] = 1

            if all(value == k for value in freq.values()):
                max_len = max(max_len, r - l + 1)

    return max_len

