def remove_adjacent_duplicates(s):
    """
    Recursively removes adjacent duplicate characters from string s.
    """
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

