def max_difference(arr):
    """
    Returns the maximum difference between the elements in the array such that
    the larger element comes after the smaller one in the array. If no such
    elements are present, return -1.
    """
    if not arr or len(arr) < 2:
        return -1

    min_element = arr[0]
    max_diff = -1

    for i in range(1, len(arr)):
        if arr[i] > min_element:
            max_diff = max(max_diff, arr[i] - min_element)
        else:
            min_element = arr[i]

    return max_diff

