def island_perimeter(grid):
    """
    Calculate the perimeter of the island in the grid.
    """
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    perimeter = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                # Each land cell contributes 4 to the perimeter initially
                perimeter += 4

                # Check the cell above (if there's land above, subtract 2 from perimeter)
                if r > 0 and grid[r - 1][c] == 1:
                    perimeter -= 2

                # Check the cell to the left (if there's land to the left, subtract 2 from perimeter)
                if c > 0 and grid[r][c - 1] == 1:
                    perimeter -= 2

    return perimeter

