def max_sum_submatrix(grid, k):
    import itertools
    import bisect

    def max_sum_no_larger_than_k(nums, k):
        max_sum, current_sum = float('-inf'), 0
        prefix_sum = [0]
        for num in nums:
            current_sum += num
            idx = bisect.bisect_left(prefix_sum, current_sum - k)
            if idx < len(prefix_sum):
                max_sum = max(max_sum, current_sum - prefix_sum[idx])
            bisect.insort(prefix_sum, current_sum)
        return max_sum

    if not grid or not grid[0]:
        return 0

    row, col = len(grid), len(grid[0])
    max_sum = float('-inf')

    for left in range(col):
        row_sum = [0] * row
        for right in range(left, col):
            for r in range(row):
                row_sum[r] += grid[r][right]
            max_sum = max(max_sum, max_sum_no_larger_than_k(row_sum, k))

    return max_sum

