def three_sum(nums, target):
    """
    Determines if there are any three integers in the list whose sum is equal to target.
    :param nums: List of integers
    :param target: The target sum to find triplets summing to
    :return: Boolean value, True if such a triplet exists, False otherwise
    """
    nums.sort()
    n = len(nums)
    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip duplicate elements
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    return False

def find_relative_ranks(scores):
    """
    Given scores of players, returns their ranking in terms of medals and numerical rank.
    """
    n = len(scores)
    if n == 0:
        return []

    sorted_indices = sorted(range(n), key=lambda x: scores[x], reverse=True)

    ranks = [""] * n

    for i in range(n):
        if i == 0:
            ranks[sorted_indices[i]] = "Gold Medal"
        elif i == 1:
            ranks[sorted_indices[i]] = "Silver Medal"
        elif i == 2:
            ranks[sorted_indices[i]] = "Bronze Medal"
        else:
            ranks[sorted_indices[i]] = str(i + 1)

    return ranks

