from collections import deque
from typing import List, Tuple

def minKnightMoves(grid: List[List[str]], start: Tuple[int, int], target: Tuple[int, int]) -> int:
    directions = [
        (-2, -1), (-1, -2),
        (-2,  1), ( 1, -2),
        ( 2, -1), (-1,  2),
        ( 2,  1), ( 1,  2)
    ]

    n = len(grid)
    visited = [[False] * n for _ in range(n)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n and grid[x][y] != 'X'

    queue = deque([(start, 0)])
    while queue:
        (x, y), moves = queue.popleft()

        if (x, y) == target:
            return moves

        if visited[x][y]:
            continue

        visited[x][y] = True

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and not visited[nx][ny]:
                queue.append(((nx, ny), moves + 1))

    return -1

def command_handler(commands):
    current_path = ["/"]
    output = []

    def get_path():
        if len(current_path) == 1:
            return "/"
        return "/" + "/".join(current_path[1:])

    for cmd in commands:
        if cmd.startswith("cd "):
            folder = cmd.split(" ", 1)[1]
            if folder == "..":
                if len(current_path) > 1:
                    current_path.pop()
            else:
                current_path.append(folder)
        elif cmd == "pwd":
            output.append(get_path())

    return output

