def can_form_by_deleting_one(s, t):
    """
    Determines if string t can be obtained by deleting exactly one character
    from string s and rearranging the remaining characters.
    """
    if len(s) != len(t) + 1:
        return False

    s_counter = {}
    t_counter = {}

    # Count the frequency of each character in s
    for char in s:
        if char in s_counter:
            s_counter[char] += 1
        else:
            s_counter[char] = 1

    # Count the frequency of each character in t
    for char in t:
        if char in t_counter:
            t_counter[char] += 1
        else:
            t_counter[char] = 1

    # Check if t_counter matches s_counter with exactly one less character
    diff_count = 0
    for char in s_counter:
        s_count = s_counter.get(char, 0)
        t_count = t_counter.get(char, 0)
        if s_count != t_count:
            diff_count += 1
            if diff_count > 1 or t_count != s_count - 1:
                return False

    return True

def aggregate_transactions(transactions):
    """
    Aggregates transaction amounts by name.

    :param transactions: List of strings, each in the format "name amount".
    :return: Dictionary where the keys are the names and the values are the total amounts.
    """
    result = {}
    for transaction in transactions:
        name, amount = transaction.split()
        amount = int(amount)
        if name in result:
            result[name] += amount
        else:
            result[name] = amount
    return result

