def minimum_steps(heights):
    n = len(heights)
    if n == 1:
        return 0

    steps = 0
    i = 0

    while i < n - 1:
        if heights[i + 1] >= heights[i]:
            i += 1
        else:
            if i + 2 < n and heights[i + 2] >= heights[i]:
                i += 2
            else:
                return -1
        steps += 1

    return steps

