def splitArray(nums, k):
    def is_valid(mid):
        subarray_count = 1
        current_sum = 0
        for num in nums:
            if current_sum + num > mid:
                subarray_count += 1
                current_sum = num
                if subarray_count > k:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if is_valid(mid):
            right = mid
        else:
            left = mid + 1

    return left

