from collections import deque

def min_time_to_reach_target(grid, target_x, target_y):
    if not grid or not grid[0]:
        return -1

    m, n = len(grid), len(grid[0])
    target = (target_x, target_y)

    if grid[target_x][target_y] == 1:
        return -1  # Target cell is a wall

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque()
    visited = set()

    # Initialize the queue with all fire starting points
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                queue.append((i, j, 0)) # (row, col, time)
                visited.add((i, j))

    # BFS to spread the fire
    while queue:
        x, y, time = queue.popleft()

        if (x, y) == target:
            return time

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] == 0:
                queue.append((nx, ny, time + 1))
                visited.add((nx, ny))

    return -1

def max_distinct_elements(nums, k):
    """
    Returns the maximum number of distinct elements that can be selected
    from nums such that their sum is less than or equal to k.
    """
    nums = list(set(nums))  # get unique elements
    nums.sort()             # sort elements to pick the smallest ones first
    sum_of_selected = 0
    selected_elements = []

    for num in nums:
        if sum_of_selected + num <= k:
            sum_of_selected += num
            selected_elements.append(num)
        else:
            break

    return len(selected_elements)

