def min_path_sum(grid):
    """
    Returns the minimum path sum from top-left corner to bottom-right corner in a 2D grid.
    You can only move either down or right at any point in time.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize the grid's first row and first column paths
    for i in range(1, m):
        grid[i][0] += grid[i-1][0]
    for j in range(1, n):
        grid[0][j] += grid[0][j-1]

    # Populate the rest of the grid paths
    for i in range(1, m):
        for j in range(1, n):
            grid[i][j] += min(grid[i-1][j], grid[i][j-1])

    return grid[m-1][n-1]

def length_of_lis(heights):
    """
    Returns the length of the longest increasing subsequence in heights.
    """
    if not heights:
        return 0

    n = len(heights)
    # Create a list to store the length of the longest increasing subsequence ending at each index.
    lis = [1] * n

    # Iterate through the heights and compute the length of the longest increasing subsequence.
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # The maximum value in lis will be the length of the longest increasing subsequence.
    return max(lis)

