def check_subarray_sum(nums, k):
    """
    Given an array of integers 'nums' and an integer 'k',
    check if there is a continuous subarray of length at least 2 that sums up to a multiple of k.
    """
    if k == 0:
        # Special case when k is 0
        for i in range(len(nums) - 1):
            if nums[i] == 0 and nums[i + 1] == 0:
                return True
        return False

    mod_dict = {0: -1}  # Dictionary to store modulus and index
    running_sum = 0

    for i in range(len(nums)):
        running_sum += nums[i]
        if k != 0:
            running_sum %= k

        if running_sum in mod_dict:
            if i - mod_dict[running_sum] > 1:
                return True
        else:
            mod_dict[running_sum] = i

    return False

def largest_island(grid):
    """
    Returns the size of the largest island in the given grid.
    """
    if not grid or not grid[0]:
        return 0

    def dfs(x, y):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == '0':
            return 0
        grid[x][y] = '0'  # Mark the cell as visited
        size = 1
        size += dfs(x + 1, y)
        size += dfs(x - 1, y)
        size += dfs(x, y + 1)
        size += dfs(x, y - 1)
        return size

    max_size = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                max_size = max(max_size, dfs(i, j))

    return max_size

