def maxJumps(arr, d):
    """
    Returns the maximum number of indices that can be visited starting from any index in the array.
    """
    n = len(arr)

    # Memoization table.
    memo = [-1] * n

    def dfs(i):
        if memo[i] != -1:
            return memo[i]
        max_jump_count = 1
        # Move to the right
        for j in range(i + 1, min(n, i + d + 1)):
            if arr[i] > arr[j]:
                max_jump_count = max(max_jump_count, 1 + dfs(j))
            else:
                break
        # Move to the left
        for j in range(i - 1, max(-1, i - d - 1), -1):
            if arr[i] > arr[j]:
                max_jump_count = max(max_jump_count, 1 + dfs(j))
            else:
                break
        memo[i] = max_jump_count
        return max_jump_count

    max_count = 0
    for i in range(n):
        max_count = max(max_count, dfs(i))

    return max_count

def sunsetViews(heights):
    """
    Given an integer array heights representing the heights of buildings in a row,
    this function returns the indices of all "sunset view" buildings in ascending order of their indices.

    A building is considered a "sunset view" building if its height is greater than all the buildings to its right.
    """
    sunset_buildings = []
    max_height = -1

    for i in range(len(heights) - 1, -1, -1):
        if heights[i] > max_height:
            sunset_buildings.append(i)
            max_height = heights[i]

    return list(sorted(sunset_buildings))

