def longest_path_value_sum(n, edges, values):
    from collections import defaultdict, deque

    # Construct the graph
    graph = defaultdict(list)
    in_degree = [0] * n
    for u, v in edges:
        graph[u].append(v)
        in_degree[v] += 1

    # Topological Sort using Kahn's algorithm
    topo_order = []
    zero_in_degree_queue = deque([i for i in range(n) if in_degree[i] == 0])

    while zero_in_degree_queue:
        node = zero_in_degree_queue.popleft()
        topo_order.append(node)
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                zero_in_degree_queue.append(neighbor)

    # Early exit if there's a cycle and not all nodes are in topological order
    if len(topo_order) != n:
        return 0

    # Initialize distance with negative infinity
    dist = [-float('inf')] * n

    # Maximum path values starting from each vertex
    max_path_value = 0

    # Process vertices in topological order
    for node in topo_order:
        if dist[node] == -float('inf'):
            dist[node] = values[node]
        for neighbor in graph[node]:
            dist[neighbor] = max(dist[neighbor], dist[node] + values[neighbor])

    return max(dist)

def find_pairs(nums, target_sum):
    """
    Returns all unique pairs of integers from the list `nums` that add up to `target_sum`.
    Each pair is sorted in ascending order, and the list of pairs is sorted based on the
    first value of each pair.
    """
    nums.sort()
    pairs = set()
    seen = {}

    for num in nums:
        complement = target_sum - num
        if complement in seen:
            pairs.add((min(num, complement), max(num, complement)))
        seen[num] = True

    return sorted(pairs)

