def max_beautiful_subsequence_length(s, k):
    """
    Returns the maximum length of a beautiful subsequence with at least k unique characters.
    """
    if s is None or k <= 0:
        return -1

    unique_chars = set(s)
    if len(unique_chars) < k:
        return -1

    # Since we need at least k unique characters
    # we just need the length of the given string
    return len(s)

