def max_balanced_substring(s):
    """
    Returns the maximum length of a balanced substring in the given string `s`.
    A balanced substring has an equal number of '0's and '1's.

    Parameters:
    s (str): The input string containing only '0' and '1' characters.

    Returns:
    int: The length of the maximum balanced substring.
    """
    max_length = 0
    balance = 0
    balance_map = {0: -1}

    for i, char in enumerate(s):
        if char == '0':
            balance -= 1
        else:
            balance += 1

        if balance in balance_map:
            max_length = max(max_length, i - balance_map[balance])
        else:
            balance_map[balance] = i

    return max_length

