def pacificAtlantic(matrix):
    if not matrix: return []

    rows, cols = len(matrix), len(matrix[0])
    pacific_reachable = set()
    atlantic_reachable = set()

    def dfs(r, c, reachable, prev_height):
        if (r, c) in reachable or r < 0 or c < 0 or r >= rows or c >= cols or matrix[r][c] < prev_height:
            return
        reachable.add((r, c))
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            dfs(r + dr, c + dc, reachable, matrix[r][c])

    for i in range(rows):
        dfs(i, 0, pacific_reachable, matrix[i][0])
        dfs(i, cols - 1, atlantic_reachable, matrix[i][cols - 1])

    for j in range(cols):
        dfs(0, j, pacific_reachable, matrix[0][j])
        dfs(rows - 1, j, atlantic_reachable, matrix[rows - 1][j])

    result = list(pacific_reachable & atlantic_reachable)
    result.sort()  # sort by row first, then by column
    return result

def longest_increasing_subsequence(heights):
    """
    Returns the length of the longest increasing subsequence of tree heights.

    :param heights: List[int] - List of tree heights.
    :return: int - Length of the longest increasing subsequence.
    """
    if not heights:
        return 0

    # Initialize an array to store the length of the LIS ending at each index
    lis = [1] * len(heights)

    # Compute the LIS values in a bottom up manner
    for i in range(1, len(heights)):
        for j in range(i):
            if heights[i] > heights[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    # The longest increasing subsequence will be the maximum value in lis[]
    return max(lis)

