def has_cycle(graph):
    """
    Detect if the graph contains a cycle.

    :param graph: dict, representing the adjacency list of the graph
    :return: bool, True if there is a cycle, False otherwise
    """
    def dfs(node, parent, visited):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                if dfs(neighbor, node, visited):
                    return True
            elif neighbor != parent:
                return True
        return False

    visited = set()

    for node in graph:
        if node not in visited:
            if dfs(node, None, visited):
                return True

    return False

