def all_unique_in_sliding_window(nums, k):
    """
    Returns True if all numbers in each sliding window of length k are unique.
    """
    if k > len(nums):
        return False  # If k is larger than the length of the array, return false because we can't form a window.

    num_set = set()
    for i in range(len(nums)):
        if i >= k:
            num_set.remove(nums[i - k])  # Remove the element that is sliding out of the window.
        if nums[i] in num_set:
            return False  # If we encounter a duplicate, return False.
        num_set.add(nums[i])  # Add the current number to the set.

    return True

