def maximalSquare(matrix):
    """
    Given a binary matrix of size m x n, finds the largest square containing only
    1's and returns its area.

    :param matrix: List[List[int]], 2D list representing binary matrix.
    :return: int, area of the largest square containing only 1's.
    """
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])
    # Using dp to store maximum side length of square ending at (i, j)
    dp = [[0] * n for _ in range(m)]
    max_side_length = 0

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == '1':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

                max_side_length = max(max_side_length, dp[i][j])

    return max_side_length * max_side_length

