def longest_non_decreasing_subarray(temps):
    """
    Returns the length of the longest contiguous subarray where
    the temperature readings are non-decreasing.
    """
    if not temps:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(temps)):
        if temps[i] >= temps[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

