def numDistinctIslands(grid):
    """
    Counts the number of distinct islands in the grid.

    :param grid: List[List[str]], a 2D grid where '1' represents land and '0' represents water
    :return: int, number of distinct islands
    """
    def dfs(x, y, grid, seen, island, origin):
        stack = [(x, y)]
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while stack:
            cx, cy = stack.pop()
            island.add((cx - origin[0], cy - origin[1]))  # record relative position
            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and grid[nx][ny] == '1' and (nx, ny) not in seen:
                    seen.add((nx, ny))
                    stack.append((nx, ny))

    seen = set()
    unique_islands = set()

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1' and (i, j) not in seen:
                island = set()
                seen.add((i, j))
                dfs(i, j, grid, seen, island, (i, j))
                if island:
                    unique_islands.add(frozenset(island))

    return len(unique_islands)

