from itertools import combinations

def minimum_routes(routes, keys):
    n = len(routes)
    key_set = set(keys)

    def covers_all_keys(route_indices):
        covered = set()
        for i in route_indices:
            covered.update(routes[i])
        return key_set.issubset(covered)

    for i in range(1, n + 1):
        for combo in combinations(range(n), i):
            if covers_all_keys(combo):
                return i

    return -1

def closedIsland(grid):
    rows, cols = len(grid), len(grid[0])

    def dfs(x, y):
        if x < 0 or y < 0 or x >= rows or y >= cols:
            return False
        if grid[x][y] == 1:
            return True
        grid[x][y] = 1  # mark as visited
        top = dfs(x-1, y)
        bottom = dfs(x+1, y)
        left = dfs(x, y-1)
        right = dfs(x, y+1)
        return top and bottom and left and right

    closed_islands = 0
    for i in range(1, rows-1):
        for j in range(1, cols-1):
            if grid[i][j] == 0:
                if dfs(i, j):
                    closed_islands += 1
    return closed_islands

def longest_subarray_with_distinct_elements(arr):
    """
    Returns the length of the longest subarray containing only distinct elements.
    """
    seen = {}
    max_length = 0
    start = 0

    for end in range(len(arr)):
        if arr[end] in seen:
            start = max(start, seen[arr[end]] + 1)
        seen[arr[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

