def countGroups(friendships):
    from collections import defaultdict

    def dfs(user, adj_list, visited):
        stack = [user]
        while stack:
            current = stack.pop()
            for neighbor in adj_list[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    adj_list = defaultdict(list)
    for u, v in friendships:
        adj_list[u].append(v)
        adj_list[v].append(u)

    visited = set()
    groups = 0
    for user in adj_list.keys():
        if user not in visited:
            visited.add(user)
            dfs(user, adj_list, visited)
            groups += 1

    return groups

