def find_target_sum_ways(nums, target):
    """
    Returns the number of ways to place the '+' or '-' operators between numbers in nums to get the target value.
    """

    def backtrack(index, total):
        if index == len(nums):
            return 1 if total == target else 0

        add = backtrack(index + 1, total + nums[index])
        subtract = backtrack(index + 1, total - nums[index])

        return add + subtract

    return backtrack(0, 0)

def isValid(s: str) -> bool:
    """
    Determine if the input string of brackets is valid.
    """
    stack = []
    bracket_map = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

