def exist(grid, word):
    def dfs(i, j, word_index):
        if word_index == len(word):
            return True
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] != word[word_index] or (i, j) in visited:
            return False
        visited.add((i, j))
        result = (dfs(i+1, j, word_index+1) or dfs(i-1, j, word_index+1) or
                  dfs(i, j+1, word_index+1) or dfs(i, j-1, word_index+1))
        visited.remove((i, j))
        return result

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            visited = set()
            if dfs(i, j, 0):
                return True
    return False

