def largestIsland(grid):
    """
    Returns the size of the largest island of 1s in the grid.
    """
    def dfs(i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == 0:
            return 0
        grid[i][j] = 0  # Mark the cell as visited
        size = 1
        size += dfs(i+1, j)
        size += dfs(i-1, j)
        size += dfs(i, j+1)
        size += dfs(i, j-1)
        return size

    max_size = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                max_size = max(max_size, dfs(i, j))
    return max_size

def findChangeCombinations(target, coins):
    def backtrack(remainder, combination, start):
        if remainder == 0:
            result.append(list(combination))
            return
        elif remainder < 0:
            return

        for i in range(start, len(coins)):
            combination.append(coins[i])
            backtrack(remainder - coins[i], combination, i)
            combination.pop()

    result = []
    backtrack(target, [], 0)
    return result

