def is_rotationally_sorted(nums):
    """
    Check if the array is rotationally sorted.

    Parameters:
    nums (list): A list of integers.

    Returns:
    bool: True if the array can be rotated to form a non-decreasing sequence, False otherwise.
    """
    n = len(nums)
    if n == 1:
        return True

    drop_count = 0

    for i in range(1, n):
        if nums[i] < nums[i - 1]:
            drop_count += 1
            if drop_count > 1:
                return False

    if drop_count == 0:
        return True

    return nums[0] >= nums[-1]

