def matching_rows(matrix, criteria):
    """
    Returns the row indices of all rows that match all feature criteria.

    :param matrix: List of lists where each list represents an item's features.
    :param criteria: List of tuples where each tuple is (column, min_value, max_value).
    :return: List of row indices that match all criteria.
    """
    matching_indices = []
    for row_index, row in enumerate(matrix):
        match = True
        for column, min_value, max_value in criteria:
            if not (min_value <= row[column] <= max_value):
                match = False
                break
        if match:
            matching_indices.append(row_index)

    return sorted(matching_indices)

def can_form_string(s, words):
    from collections import Counter

    def can_form(s, word_counter):
        if not s:
            return True
        for word in word_counter:
            if s.startswith(word) and word_counter[word] > 0:
                word_counter[word] -= 1
                if can_form(s[len(word):], word_counter):
                    return True
                word_counter[word] += 1
        return False

    word_counter = Counter(words)
    return can_form(s, word_counter)

def count_pairs_with_xor(nums, k):
    """
    Returns the number of pairs (i, j) where 0 <= i < j < len(nums)
    and nums[i] xor nums[j] is equal to the given integer k.
    """
    count = 0
    n = len(nums)

    # Iterate through all pairs (i, j) and calculate nums[i] xor nums[j]
    for i in range(n):
        for j in range(i + 1, n):
            if nums[i] ^ nums[j] == k:
                count += 1

    return count

