from typing import List

def dfs(matrix: List[List[int]], i: int, j: int, visited: List[List[bool]]) -> int:
    if i < 0 or i >= len(matrix) or j < 0 or j >= len(matrix[0]) or visited[i][j] or matrix[i][j] == 0:
        return 0
    visited[i][j] = True
    area = 1 # include current cell
    # check all four possible directions
    area += dfs(matrix, i + 1, j, visited)
    area += dfs(matrix, i - 1, j, visited)
    area += dfs(matrix, i, j + 1, visited)
    area += dfs(matrix, i, j - 1, visited)
    return area

def largest_island(matrix: List[List[int]]) -> int:
    if not matrix or not matrix[0]:
        return 0

    visited = [[False for _ in range(len(matrix[0]))] for _ in range(len(matrix))]
    max_area = 0

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if matrix[i][j] == 1 and not visited[i][j]:
                max_area = max(max_area, dfs(matrix, i, j, visited))

    return max_area

