def four_sum(nums, target):
    """
    Returns True if there exist four integers in `nums` whose sum equals `target`, False otherwise.
    """
    nums_sorted = sorted(nums)
    n = len(nums_sorted)

    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            left, right = j + 1, n - 1
            while left < right:
                total = nums_sorted[i] + nums_sorted[j] + nums_sorted[left] + nums_sorted[right]
                if total == target:
                    return True
                elif total < target:
                    left += 1
                else:
                    right -= 1
    return False

def max_total_profit(profits, k):
    """
    Returns the maximum total profit by selecting at most k projects with non-overlapping indices.
    """
    profits.sort(reverse=True)

    if k >= len(profits):
        return sum(profits)

    return sum(profits[:k])

