def can_form_word(word, chips_count):
    word_count = {}
    for char in word:
        if char not in chips_count:
            return False
        word_count[char] = word_count.get(char, 0) + 1
        if word_count[char] > chips_count[char]:
            return False
    return True

def longest_word(words, chips):
    chips_count = {}
    for char in chips:
        chips_count[char] = chips_count.get(char, 0) + 1

    max_length = 0
    for word in words:
        if can_form_word(word, chips_count):
            max_length = max(max_length, len(word))

    return max_length

