def count_pairs(nums, target):
    """
    Returns the number of pairs of indices (i, j) such that i < j
    and nums[i] + nums[j] equals target.
    """
    count = 0
    complements = {}

    for i, num in enumerate(nums):
        complement = target - num

        if complement in complements:
            count += complements[complement]

        if num in complements:
            complements[num] += 1
        else:
            complements[num] = 1

    return count

