def can_sort_by_swaps(height, swaps):
    """
    Determines if the array can be sorted using the allowed swaps.
    :param height: List[int] - list of heights
    :param swaps: List[Tuple[int, int]] - list of index pairs that can be swapped
    :return: bool - True if the array can be sorted using allowed swaps, otherwise False
    """
    n = len(height)

    # Create an adjacency list for the swaps to represent the graph
    graph = {i: [] for i in range(n)}
    for i, j in swaps:
        graph[i].append(j)
        graph[j].append(i)

    def dfs(node, visited, group):
        stack = [node]
        while stack:
            cur = stack.pop()
            if cur not in visited:
                visited.add(cur)
                group.append(cur)
                for neighbor in graph[cur]:
                    if neighbor not in visited:
                        stack.append(neighbor)

    visited = set()
    for i in range(n):
        if i not in visited:
            group = []
            dfs(i, visited, group)
            group_heights = sorted(height[j] for j in group)
            group_indices = sorted(group)
            for idx, value in zip(group_indices, group_heights):
                height[idx] = value

    return height == sorted(height)

