def check_distance(s, distance):
    """
    Returns True if for each pair of equal letters in the string s,
    there are exactly 'distance' characters between them.
    """
    char_position = {}
    for i, c in enumerate(s):
        if c in char_position:
            if i - char_position[c] - 1 != distance:
                return False
        char_position[c] = i
    return True

