def minimum_removals(heights):
    """
    Returns the minimum number of students that need to be removed so that
    the remaining students are standing in non-decreasing order of height.
    """
    def longest_increasing_subsequence(arr):
        if not arr:
            return 0

        lis = [1] * len(arr)
        for i in range(1, len(arr)):
            for j in range(i):
                if arr[i] >= arr[j]:
                    lis[i] = max(lis[i], lis[j] + 1)
        return max(lis)

    n = len(heights)
    length_of_lis = longest_increasing_subsequence(heights)
    return n - length_of_lis

