from collections import deque

def shortest_path(grid, r1, c1, r2, c2):
    """
    Returns the length of the shortest path from (r1, c1) to (r2, c2) in a binary
    matrix grid. Returns -1 if no such path exists.
    """

    if grid[r1][c1] == 1 or grid[r2][c2] == 1:
        return -1  # Either start or end is blocked

    if (r1, c1) == (r2, c2):
        return 0  # Start and end are the same

    n = len(grid)
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    queue = deque([(r1, c1, 0)])  # (row, col, distance)
    visited = set()
    visited.add((r1, c1))

    while queue:
        cr, cc, dist = queue.popleft()
        for dr, dc in directions:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < n and 0 <= nc < n and (nr, nc) not in visited:
                if grid[nr][nc] == 0:
                    if (nr, nc) == (r2, c2):
                        return dist + 1
                    queue.append((nr, nc, dist + 1))
                    visited.add((nr, nc))

    return -1

def max_contiguous_subarray_sum(hours):
    """
    Finds the maximum sum of a contiguous subarray in hours array.
    """
    if not hours:
        return 0

    max_sum = float('-inf')
    current_sum = 0

    for hour in hours:
        current_sum += hour
        if current_sum > max_sum:
            max_sum = current_sum
        if current_sum < 0:
            current_sum = 0

    return max_sum

