    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Find the start ('S') and end ('E') positions
    start = end = None
    for i in range(rows):
        for j in range(cols):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return False

    # BFS initialization
    queue = [start]
    visited = set()
    visited.add(start)

    while queue:
        current = queue.pop(0)
        if current == end:
            return True

        for direction in directions:
            neighbor = (current[0] + direction[0], current[1] + direction[1])

            if 0 <= neighbor[0] < rows and 0 <= neighbor[1] < cols:
                if maze[neighbor[0]][neighbor[1]] != '1' and neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    return False

def largest_island(grid):
    def dfs(x, y, index):
        stack = [(x, y)]
        area = 0
        while stack:
            cx, cy = stack.pop()
            if 0 <= cx < n and 0 <= cy < n and grid[cx][cy] == 1:
                grid[cx][cy] = index
                area += 1
                for nx, ny in [(cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1)]:
                    stack.append((nx, ny))
        return area

    n = len(grid)
    if not n: return 0

    island_area = {}
    index = 2  # Start index from 2 because 0 and 1 are already in use

    # Step 1: Use DFS to paint each island and record their area
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                island_area[index] = dfs(i, j, index)
                index += 1

    if not island_area: return 1  # The grid only contains one cell as 0

    max_area = max(island_area.values(), default=0)

    # Step 2: Check each 0 cell to see if it can connect two or more islands
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                seen = set()
                new_area = 1  # Start with this cell being an island
                for ni, nj in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
                    if 0 <= ni < n and 0 <= nj < n and grid[ni][nj] > 1:
                        index = grid[ni][nj]
                        if index not in seen:
                            new_area += island_area[index]
                            seen.add(index)
                max_area = max(max_area, new_area)

    return max_area

