def fullJustify(words, maxWidth):
    def justify_line(line, maxWidth, is_last):
        if len(line) == 1 or is_last:
            # For a single word or the last line, left-justify
            return ' '.join(line).ljust(maxWidth)

        total_whitespace = maxWidth - sum(len(word) for word in line)
        spaces_between_words = len(line) - 1
        min_spaces = total_whitespace // spaces_between_words
        extra_spaces = total_whitespace % spaces_between_words

        justified = ""
        for idx, word in enumerate(line):
            justified += word
            if idx < spaces_between_words:
                justified += ' ' * (min_spaces + (1 if idx < extra_spaces else 0))

        return justified

    result = []
    current_line = []
    current_length = 0

    for word in words:
        # Check if adding the next word will exceed the maxWidth
        if current_length + len(word) + len(current_line) > maxWidth:
            result.append(justify_line(current_line, maxWidth, False))
            current_line, current_length = [], 0

        current_line.append(word)
        current_length += len(word)

    # Justify the last line
    if current_line:
        result.append(justify_line(current_line, maxWidth, True))

    return result

