def can_be_non_decreasing(arr):
    """
    Determine whether the array can be made non-decreasing with at most one replacement.

    Parameters:
    arr (List[int]): List of integers which may include positive, negative, or zero values.

    Returns:
    bool: True if the array can be made non-decreasing with at most one replacement, False otherwise.
    """
    n = len(arr)
    if n <= 1:
        return True

    count = 0
    for i in range(1, n):
        if arr[i] < arr[i - 1]:
            count += 1
            if count > 1:
                return False
            if i > 1 and arr[i] < arr[i - 2]:
                arr[i] = arr[i - 1]
    return True

