def numEnclaves(grid):
    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] == 0:
            return
        grid[x][y] = 0
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    m, n = len(grid), len(grid[0])

    # Eliminate border connected lands
    for i in range(m):
        for j in [0, n - 1]:
            if grid[i][j] == 1:
                dfs(i, j)
    for i in [0, m - 1]:
        for j in range(n):
            if grid[i][j] == 1:
                dfs(i, j)

    # Count enclave lands
    count = 0
    for i in range(1, m - 1):
        for j in range(1, n - 1):
            if grid[i][j] == 1:
                count += 1

    return count

