def can_collect_candies(candies, queries):
    prefix_sums = [0] * (len(candies) + 1)
    for i in range(len(candies)):
        prefix_sums[i + 1] = prefix_sums[i] + candies[i]

    result = []
    for start, end, k in queries:
        total_candies = prefix_sums[end + 1] - prefix_sums[start]
        result.append(total_candies == k)
    return result

def minimize_max_difference(nums, k):
    def is_valid(max_diff):
        count = 1
        min_val = nums[0]

        for num in nums:
            if num - min_val > max_diff:
                count += 1
                min_val = num
                if count > k:
                    return False
        return True

    nums.sort()
    left, right = 0, nums[-1] - nums[0]

    while left < right:
        mid = (left + right) // 2
        if is_valid(mid):
            right = mid
        else:
            left = mid + 1

    return left

