def count_balanced_subarrays(numbers, k):
    """
    Returns the number of balanced subarrays in the given list 'numbers' that sum up to 'k'.
    """
    count = 0
    n = len(numbers)

    for i in range(n):
        curr_sum = 0
        for j in range(i, n):
            curr_sum += numbers[j]
            if curr_sum == k:
                count += 1

    return count

