def largest_island(grid):
    def dfs(r, c, index):
        stack = [(r, c)]
        islands[index] = 0
        while stack:
            i, j = stack.pop()
            if 0 <= i < len(grid) and 0 <= j < len(grid[0]) and grid[i][j] == 1:
                grid[i][j] = index
                islands[index] += 1
                stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
        return islands[index]

    rows, cols = len(grid), len(grid[0])
    islands = {}
    index = 2
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                dfs(r, c, index)
                index += 1

    max_island = max(islands.values(), default=0)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                neighbors = set()
                for i, j in [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]:
                    if 0 <= i < rows and 0 <= j < cols and grid[i][j] > 1:
                        neighbors.add(grid[i][j])
                new_area = 1 + sum(islands[idx] for idx in neighbors)
                max_island = max(max_island, new_area)

    return max_island

