def longest_contiguous_sequence(nums):
    if not nums:
        return 0

    max_length = 1
    current_length = 1
    is_increasing = None

    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            if is_increasing is None or is_increasing:
                current_length += 1
            else:
                current_length = 2
            is_increasing = True
        elif nums[i] < nums[i-1]:
            if is_increasing is None or not is_increasing:
                current_length += 1
            else:
                current_length = 2
            is_increasing = False
        else:
            current_length = 1
            is_increasing = None

        max_length = max(max_length, current_length)

    return max_length

