from collections import Counter

def min_distinct_chars(s: str, t: int) -> int:
    """
    Returns the minimum number of distinct characters in the string after performing
    at most t swap operations.
    """
    freq = Counter(s)
    counts = sorted(freq.values(), reverse=True)

    while t > 0 and len(counts) > 1:
        # We will try to merge the two least frequent characters
        if t >= counts[-1]:
            t -= counts[-1]
            counts.pop()
        else:
            break

    return len(counts)

