def min_sessions(tasks, sessionTime):
    """
    Returns the minimum number of sessions needed to complete all tasks given that the sum
    of task durations in each session should not exceed sessionTime.
    """
    n = len(tasks)
    dp = [float('inf')] * (1 << n)
    dp[0] = 1

    # Calculate the sum of the tasks for each subset
    subset_sum = [0] * (1 << n)
    for mask in range(1 << n):
        total = 0
        for i in range(n):
            if mask & (1 << i):
                total += tasks[i]
        subset_sum[mask] = total

    # Dynamic programming to find the minimum number of sessions
    for mask in range(1 << n):
        if subset_sum[mask] <= sessionTime:
            dp[mask] = 1
        else:
            submask = mask
            while submask:
                if subset_sum[submask] <= sessionTime:
                    dp[mask] = min(dp[mask], dp[mask ^ submask] + 1)
                submask = (submask - 1) & mask

    return dp[(1 << n) - 1]

def rearrange_string(s):
    """
    Rearranges the characters of the input string `s` such that all the digits
    (0-9) appear before the letters (a-z) in their original relative order
    within their respective groups.

    :param s: input string
    :return: rearranged string with digits before letters
    """
    digits = []
    letters = []

    for char in s:
        if char.isdigit():
            digits.append(char)
        elif char.isalpha():
            letters.append(char)

    return ''.join(digits) + ''.join(letters)

