def count_good_buildings(heights):
    """
    Returns the total number of good buildings in the given sequence of heights.
    A building is considered good if all buildings to its left are smaller in height
    and all buildings to its right are larger in height.

    :param heights: List[int]
    :return: int
    """
    n = len(heights)
    if n == 0:
        return 0

    good_buildings_count = 0

    for i in range(n):
        is_good = True

        for j in range(i):
            if heights[j] >= heights[i]:
                is_good = False
                break

        if is_good:
            for k in range(i + 1, n):
                if heights[k] <= heights[i]:
                    is_good = False
                    break

        if is_good:
            good_buildings_count += 1

    return good_buildings_count

