def is_rotated_subgrid_possible(grid):
    m, n = len(grid), len(grid[0])

    def check_square(i, j, k):
        square = []
        for x in range(k):
            row = [grid[i + x][j + y] for y in range(k)]
            square.append(row)

        def rotate(square):
            return [list(row) for row in zip(*square[::-1])]

        for _ in range(4):
            square = rotate(square)
            if all(row == square[0] for row in square):
                return True
        return False

    for i in range(m):
        for j in range(n):
            max_size = min(m - i, n - j)
            for k in range(2, max_size + 1):
                if check_square(i, j, k):
                    return True
    return False

