def longestValidParentheses(s: str) -> int:
    """
    Returns the length of the longest valid parentheses substring.
    """
    max_len = 0
    stack = [-1]  # Stack to hold the indices

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:
            stack.pop()
            if stack:
                max_len = max(max_len, i - stack[-1])
            else:
                stack.append(i)

    return max_len

def longest_alternating_subsequence(nums):
    """
    Returns the length of the longest alternating subsequence of nums.
    """
    if not nums:
        return 0

    n = len(nums)
    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                up[i] = max(up[i], down[j] + 1)
            elif nums[i] < nums[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(max(up), max(down))

