from collections import deque

def min_moves(grid, startX, startY, targetX, targetY):
    """
    Returns the minimum number of moves required for the robot to reach the target or -1 if it is impossible.
    """

    def is_valid(x, y):
        """ Check if the cell (x, y) is valid and can be visited. """
        return 0 <= x < len(grid) and 0 <= y < len(grid[0]) and grid[x][y] == 0

    if not is_valid(startX, startY) or not is_valid(targetX, targetY):
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(startX, startY, 0)])
    visited = set((startX, startY))

    while queue:
        x, y, moves = queue.popleft()

        if (x, y) == (targetX, targetY):
            return moves

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, moves + 1))

    return -1

