def find_departments(relations):
    """
    Finds the number of distinct departments based on the given employee relations.
    """
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootX] = rootY

    employees = set()
    for emp1, emp2 in relations:
        employees.add(emp1)
        employees.add(emp2)

    parent = {emp: emp for emp in employees}

    for emp1, emp2 in relations:
        union(emp1, emp2)

    departments = len(set(find(emp) for emp in parent))
    return departments

