def distance(p1, p2):
    return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2

def is_square(p1, p2, p3, p4):
    d = [distance(p1, p2), distance(p1, p3), distance(p1, p4),
         distance(p2, p3), distance(p2, p4), distance(p3, p4)]
    d.sort()
    return d[0] > 0 and d[0] == d[1] and d[2] == d[3] and d[4] == d[5] and d[0] + d[1] == d[4]

def max_non_overlapping_squares(positions):
    from itertools import combinations

    n = len(positions)
    used = [False] * n
    count = 0

    for i, (p1, p2, p3, p4) in enumerate(combinations(positions, 4)):
        if is_square(p1, p2, p3, p4):
            indices = [positions.index(p1), positions.index(p2), positions.index(p3), positions.index(p4)]
            if all(not used[idx] for idx in indices):
                for idx in indices:
                    used[idx] = True
                count += 1

    return count

