def min_candies(ratings):
    """
    Returns the minimum number of candies needed to distribute to the students
    according to their ratings.
    """
    if not ratings:
        return 0

    n = len(ratings)
    candies = [1] * n

    # First pass to ensure right neighbor condition
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1

    # Second pass to ensure left neighbor condition
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)

    return sum(candies)

