def generate_happy_string(n):
    """
    Returns a happy string of length n. A happy string is a string that consists only of letters 'a', 'b', and 'c'
    and does not contain any substrings "aaa", "bbb", or "ccc".
    """
    if n <= 0:
        return ""

    # Initialize the string with 'a'
    happy_string = ['a']

    for i in range(1, n):
        if happy_string[-1] == 'a':
            happy_string.append('b')  # If last character was 'a', append 'b'
        elif happy_string[-1] == 'b':
            happy_string.append('c')  # If last character was 'b', append 'c'
        else:
            happy_string.append('a')  # If last character was 'c', append 'a'

    return ''.join(happy_string)

