def min_insertions_to_balance(s):
    """
    Returns the minimum number of insertions needed to make the string balanced.
    """

    left_count = 0
    right_needed = 0

    for char in s:
        if char == '(':
            left_count += 1
        elif char == ')':
            if left_count > 0:
                left_count -= 1
            else:
                right_needed += 1

    return left_count + right_needed

def largest_square_submatrix(mat):
    if not mat or not mat[0]:
        return 0

    n = len(mat)
    m = len(mat[0])

    # Initialize a DP array to store the size of the largest square submatrix ending at (i, j)
    dp = [[0] * m for _ in range(n)]
    max_side = 0

    # Iterate through the matrix to fill the DP array
    for i in range(n):
        for j in range(m):
            if mat[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

