def subarray_sum(nums, target):
    """
    Returns the number of non-empty subarrays whose sum is equal to target.
    """
    count = 0
    current_sum = 0
    sum_count = {0: 1}

    for num in nums:
        current_sum += num
        if (current_sum - target) in sum_count:
            count += sum_count[current_sum - target]
        if current_sum in sum_count:
            sum_count[current_sum] += 1
        else:
            sum_count[current_sum] = 1

    return count

