def find_triplet_with_sum(arr, k):
    """
    Determines if there exists a triplet in the sorted array `arr` that sums up to `k`.

    :param arr: List[int] - A sorted list of integers
    :param k: int - Target sum for the triplets
    :return: bool - True if such a triplet exists, otherwise False
    """
    n = len(arr)
    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]
            if current_sum == k:
                return True
            elif current_sum < k:
                left += 1
            else:
                right -= 1
    return False

