def max_profit(nums):
    """
    Returns the maximum profit the company can achieve without working two consecutive days.
    """
    if not nums:
        return 0
    n = len(nums)
    if n == 1:
        return max(0, nums[0])

    dp = [0] * n
    dp[0] = max(0, nums[0])
    dp[1] = max(dp[0], nums[1])

    for i in range(2, n):
        dp[i] = max(dp[i - 1], dp[i - 2] + nums[i])

    return dp[-1]

