def convert(s, numRows):
    if numRows == 1 or numRows >= len(s):
        return s

    # Create an array to hold the zigzag pattern
    rows = ['' for _ in range(numRows)]

    # Initialize variables to track the direction and current position
    current_row = 0
    going_down = False

    # Traverse the input string and place each character in the appropriate row
    for char in s:
        rows[current_row] += char
        if current_row == 0 or current_row == numRows - 1:
            going_down = not going_down
        current_row += 1 if going_down else -1

    # Join all rows to form the final zigzag string
    return ''.join(rows)

