def surrounded_regions(grid):
    rows, cols = len(grid), len(grid[0])

    def dfs(r, c):
        # If we're out of bounds or at a cell that isn't land, return
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] != 1:
            return
        # Mark the current cell as visited by changing it to -1
        grid[r][c] = -1
        # Perform DFS in all 4-directionally connected cells (up, down, left, right)
        dfs(r - 1, c)
        dfs(r + 1, c)
        dfs(r, c - 1)
        dfs(r, c + 1)

    # First, mark all lands connected to the boundaries as not surrounded using DFS
    for i in range(rows):
        for j in range(cols):
            if (i in [0, rows - 1] or j in [0, cols - 1]) and grid[i][j] == 1:
                dfs(i, j)

    # Now, mark all surrounded land cells with 2
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1:
                grid[i][j] = 2
            elif grid[i][j] == -1:
                grid[i][j] = 1

    return grid

def longest_subsequence(nums):
    if not nums:
        return 0

    n = len(nums)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if abs(nums[i] - nums[j]) == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

