def longest_constrained_subsequence(arr):
    """
    Function to find the longest subsequence such that the absolute difference
    between any two elements is equal to the difference between their respective indices.
    """
    n = len(arr)
    if n == 0:
        return 0

    dp = [1] * n # dp[i] will store the length of the longest valid subsequence ending at index i

    for i in range(n):
        for j in range(i):
            if abs(arr[i] - arr[j]) == i - j:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def max_jumps(arr, d):
    """
    Returns the maximum number of indices visited starting from any index in array `arr` with jump distance `d`.

    Args:
    arr (List[int]): The array of integers.
    d (int): The maximum jump distance.

    Returns:
    int: The maximum number of indices visited.
    """
    n = len(arr)
    dp = [-1] * n  # dp array to store the maximum jumps from each index

    def dfs(i):
        if dp[i] != -1:
            return dp[i]

        max_steps = 1  # At least the position itself is visited

        # Check all positions right from i within d range
        for k in range(1, d + 1):
            if i + k < n and arr[i + k] < arr[i]:
                max_steps = max(max_steps, 1 + dfs(i + k))
            else:
                break  # Since further right positions will be greater or equal

        # Check all positions left from i within d range
        for k in range(1, d + 1):
            if i - k >= 0 and arr[i - k] < arr[i]:
                max_steps = max(max_steps, 1 + dfs(i - k))
            else:
                break  # Since further left positions will be greater or equal

        dp[i] = max_steps
        return dp[i]

    max_result = 0
    for i in range(n):
        max_result = max(max_result, dfs(i))

    return max_result

def has_cycle(graph):
    """
    Function to detect a cycle in a directed graph represented as an adjacency list.

    :param graph: A dictionary where the keys are nodes and the values are lists of neighboring nodes.
    :return: True if there is a cycle, False otherwise.
    """

    def dfs(node):
        if node in visiting:
            return True
        if node in visited:
            return False

        visiting.add(node)

        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        visiting.remove(node)
        visited.add(node)
        return False

    visited = set()
    visiting = set()

    for node in graph:
        if dfs(node):
            return True

    return False

