def longest_even_subarray(arr):
    """
    Returns the length of the longest contiguous subarray consisting of only even numbers.
    """
    max_len = 0
    current_len = 0

    for num in arr:
        if num % 2 == 0:
            current_len += 1
            max_len = max(max_len, current_len)
        else:
            current_len = 0

    return max_len

