def count_distinct_substrings(s, n):
    """
    Returns the number of distinct substrings of length `n` in the given string `s`.
    """
    if n > len(s):
        return 0

    substrings = set()  # Using a set to keep track of unique substrings
    for i in range(len(s) - n + 1):
        substrings.add(s[i:i+n])

    return len(substrings)

