from math import gcd

def smallest_multiple(n):
    """
    Returns the smallest positive integer that is a multiple of both `a` and `b`,
    where `a` and `b` are integers that satisfy the conditions `1 <= a, b <= n` and `a != b`.
    If there are no valid integers `a` and `b` such that `a != b`, returns -1.
    """
    def lcm(x, y):
        return x * y // gcd(x, y)

    smallest = float('inf')
    found = False

    for a in range(1, n + 1):
        for b in range(a + 1, n + 1):  # No need to check b <= a
            found = True
            multiple = lcm(a, b)
            if multiple < smallest:
                smallest = multiple

    if found:
        return smallest
    else:
        return -1

