def longest_increasing_path(matrix):
    """
    Returns the length of the longest increasing path in the given matrix.
    Moves are allowed to the four cardinal directions (up, down, left, right).
    """
    if not matrix or not matrix[0]:
        return 0

    rows, cols = len(matrix), len(matrix[0])
    dp = [[-1] * cols for _ in range(rows)]

    def dfs(r, c):
        if dp[r][c] != -1:
            return dp[r][c]

        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        max_length = 1
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols and matrix[nr][nc] > matrix[r][c]:
                max_length = max(max_length, 1 + dfs(nr, nc))

        dp[r][c] = max_length
        return max_length

    max_path_length = 0
    for r in range(rows):
        for c in range(cols):
            max_path_length = max(max_path_length, dfs(r, c))

    return max_path_length

