def min_modifications_to_make_valid(s: str) -> int:
    """
    Returns the minimum number of parentheses that need to be added or removed to make the string valid.
    """
    open_count = 0  # Keeps track of the number of unmatched '('
    close_needed = 0  # Keeps track of how many ')' are needed to balance '('

    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count > 0:
                open_count -= 1
            else:
                close_needed += 1

    # Total modifications needed is the sum of unmatched '(' and ')' needed
    return open_count + close_needed

