def longest_increasing_subsequence_with_difference_one(nums):
    """
    Returns the length of the longest increasing subsequence such that the
    difference between consecutive elements is exactly one.

    :param nums: List[int] - list of integers
    :return: int - length of the longest increasing subsequence
    """
    if not nums:
        return 0

    n = len(nums)
    dp = {}

    longest_length = 0

    for num in nums:
        if num-1 in dp:
            dp[num] = dp[num-1] + 1
        else:
            dp[num] = 1
        longest_length = max(longest_length, dp[num])

    return longest_length

