def minimum_repaints(blocks, k):
    n = len(blocks)

    if k > n:
        return -1

    # Create initial window of size k
    repaint_count = sum(1 for block in blocks[:k] if block == 'W')
    min_repaint = repaint_count

    # Sliding window technique
    for i in range(k, n):
        if blocks[i] == 'W':
            repaint_count += 1
        if blocks[i - k] == 'W':
            repaint_count -= 1
        min_repaint = min(min_repaint, repaint_count)

    return min_repaint

