def remove_duplicates(s):
    """
    Removes all duplicate letters in the string such that each letter appears only once
    and maintains the original order of appearance.
    """
    seen = set()
    result = []

    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)

    return ''.join(result)

