def minRemoveToMakeValid(s):
    """
    Removes the minimum number of parentheses to make the string valid.

    Parameters:
    s (str): The string containing lowercase letters and parentheses.

    Returns:
    str: The resulting valid string.
    """
    to_remove = set()
    stack = []

    # Traverse the string to find misplaced parentheses.
    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                to_remove.add(i)

    # Add any remaining '(' to the set of indices to remove.
    while stack:
        to_remove.add(stack.pop())

    # Build the resulting string.
    result = []
    for i, char in enumerate(s):
        if i not in to_remove:
            result.append(char)
    return ''.join(result)

def closedIsland(grid):
    def dfs(i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]):
            return False
        if grid[i][j] == 1:
            return True

        grid[i][j] = 1   # mark it as visited (sink the island)

        top = dfs(i - 1, j)
        bottom = dfs(i + 1, j)
        left = dfs(i, j - 1)
        right = dfs(i, j + 1)

        return top and bottom and left and right

    if not grid:
        return 0

    closed_islands_count = 0

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 0 and dfs(i, j):
                closed_islands_count += 1

    return closed_islands_count

def min_difference(tasks):
    """
    Returns the minimum difference possible after distributing all the tasks between the two servers.
    """
    total_sum = sum(tasks)
    n = len(tasks)
    half_sum = total_sum // 2

    dp = [[False] * (half_sum + 1) for _ in range(n + 1)]
    dp[0][0] = True

    for i in range(1, n + 1):
        for j in range(half_sum + 1):
            dp[i][j] = dp[i-1][j]
            if j >= tasks[i-1]:
                dp[i][j] = dp[i][j] or dp[i-1][j-tasks[i-1]]

    for j in range(half_sum, -1, -1):
        if dp[n][j]:
            return total_sum - 2 * j

