def pacific_atlantic(matrix):
    if not matrix or not matrix[0]:
        return []

    m, n = len(matrix), len(matrix[0])
    pacific_reachable = set()
    atlantic_reachable = set()

    def dfs(i, j, visited, prev_height):
        if ((i, j) in visited or
            i < 0 or i >= m or
            j < 0 or j >= n or
            matrix[i][j] < prev_height):
            return
        visited.add((i, j))
        for x, y in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
            dfs(x, y, visited, matrix[i][j])

    for i in range(m):
        dfs(i, 0, pacific_reachable, matrix[i][0])
        dfs(i, n-1, atlantic_reachable, matrix[i][n-1])

    for j in range(n):
        dfs(0, j, pacific_reachable, matrix[0][j])
        dfs(m-1, j, atlantic_reachable, matrix[m-1][j])

    return list(pacific_reachable & atlantic_reachable)

