def max_noodle_pairs(lengths, m):
    lengths = sorted(lengths)
    i, j = 0, len(lengths) - 1
    count = 0

    while i < j:
        if lengths[i] + lengths[j] >= m:
            count += 1
            i += 1
            j -= 1
        else:
            i += 1

    return count

