def min_deletions(s: str) -> int:
    """
    Returns the minimum number of deletions required such that no two adjacent characters are the same.
    """
    if not s:
        return 0

    deletions = 0
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            deletions += 1

    return deletions

