def can_see_building(heights):
    """
    Returns the total number of buildings that can see at least one other building.
    """
    n = len(heights)
    visible_count = 0

    for i in range(n):
        can_see = False
        for j in range(i + 1, n):
            if heights[j] >= heights[i]:
                can_see = True
                break
        if can_see:
            visible_count += 1

    return visible_count

