def length_of_longest_multiple_subsequence(arr):
    """
    Returns the length of the longest subsequence such that every element in the subsequence
    is a multiple of the previous one.
    """
    n = len(arr)
    if n == 0:
        return 0

    dp = [1] * n

    arr.sort()

    for i in range(1, n):
        for j in range(i):
            if arr[i] % arr[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

