def min_distance(s1, s2):
    """
    Returns the minimum number of operations required to convert s1 into s2.
    Allowed operations are insert, delete, and replace a character.
    """
    m, n = len(s1), len(s2)

    # Create a 2D DP array with (m+1)x(n+1) to hold subproblem results
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the base case when one of the strings is empty
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1

    return dp[m][n]

