def is_cyclic(graph):
    """
    Function to detect if a directed graph contains a cycle.

    :param graph: adjacency list representation of the graph
    :return: True if there is a cycle in the graph, False otherwise
    """
    def dfs(vertex):
        if rec_stack[vertex]:
            return True
        if visited[vertex]:
            return False
        visited[vertex] = True
        rec_stack[vertex] = True
        for neighbor in graph[vertex]:
            if dfs(neighbor):
                return True
        rec_stack[vertex] = False
        return False

    n = len(graph)
    visited = [False] * n
    rec_stack = [False] * n

    for node in range(n):
        if not visited[node]:
            if dfs(node):
                return True
    return False

def largest_island(grid):
    def dfs(r, c, index):
        if 0 <= r < n and 0 <= c < n and grid[r][c] == 1:
            grid[r][c] = index
            size = 1
            for dr, dc in directions:
                size += dfs(r + dr, c + dc, index)
            return size
        return 0

    def get_neighbors(r, c):
        neighbors = []
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < n and 0 <= nc < n:
                neighbors.append((nr, nc))
        return neighbors

    n = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    index = 2
    sizes = {}

    for r in range(n):
        for c in range(n):
            if grid[r][c] == 1:
                sizes[index] = dfs(r, c, index)
                index += 1

    max_island = max(sizes.values(), default=0)

    for r in range(n):
        for c in range(n):
            if grid[r][c] == 0:
                seen_indices = set()
                potential_size = 1
                for nr, nc in get_neighbors(r, c):
                    if grid[nr][nc] > 1 and grid[nr][nc] not in seen_indices:
                        seen_indices.add(grid[nr][nc])
                        potential_size += sizes[grid[nr][nc]]
                max_island = max(max_island, potential_size)

    return max_island

