def min_modifications_to_distinct_substrings(s, k):
    """
    Returns the minimum number of modifications required to ensure
    all substrings of length k have exactly k distinct characters.
    """
    if not s or k <= 0 or k > len(s):
        return 0

    n = len(s)
    min_replacements = float('inf')

    def is_valid_substring(substr):
        return len(set(substr)) == len(substr)

    for i in range(n - k + 1):
        substring = s[i:i + k]
        if not is_valid_substring(substring):
            unique_chars = set(substring)
            modifications_needed = k - len(unique_chars)
            min_replacements = min(min_replacements, modifications_needed)

    return min_replacements if min_replacements != float('inf') else 0

