def find_words(board, dictionary):
    def search(board, word, row, col, path):
        if not word:
            return True

        if (row < 0 or row >= len(board) or col < 0 or col >= len(board[0])
            or word[0] != board[row][col] or (row, col) in path):
            return False

        path.add((row, col))
        result = (search(board, word[1:], row + 1, col, path) or  # down
                  search(board, word[1:], row - 1, col, path) or  # up
                  search(board, word[1:], row, col + 1, path) or  # right
                  search(board, word[1:], row, col - 1, path))    # left
        path.remove((row, col))
        return result

    def exist(board, word):
        for row in range(len(board)):
            for col in range(len(board[0])):
                if search(board, word, row, col, set()):
                    return True
        return False

    count = 0
    for word in dictionary:
        if exist(board, word):
            count += 1
    return count

