def max_consecutive_ones(s):
    """
    Returns the maximum number of consecutive '1's obtainable by flipping exactly one '0' to '1' in the string s.
    """
    # Edge case: empty string
    if not s:
        return 0

    n = len(s)
    max_ones = 0
    zero_count = 0
    left = 0

    for right in range(n):
        if s[right] == '0':
            zero_count += 1

        while zero_count > 1:
            if s[left] == '0':
                zero_count -= 1
            left += 1

        max_ones = max(max_ones, right - left + 1)

    return max_ones

