def longestEqualOddEvenSubarray(arr):
    """
    Returns the length of the longest subarray with an equal number of odd and even numbers.
    """
    max_len = 0
    prefix_sum = 0
    prefix_sum_map = {0: -1}

    for i in range(len(arr)):
        if arr[i] % 2 == 0:
            prefix_sum += 1
        else:
            prefix_sum -= 1

        if prefix_sum in prefix_sum_map:
            max_len = max(max_len, i - prefix_sum_map[prefix_sum])
        else:
            prefix_sum_map[prefix_sum] = i

    return max_len

