def median_of_matrix(mat):
    """
    Returns the median of a matrix where each row is sorted in non-decreasing order.
    The matrix does not contain duplicate elements.
    """
    m = len(mat)
    n = len(mat[0])

    # Helper function to count numbers less than or equal to mid in the matrix
    def count_less_equal(mid):
        count = 0
        for row in mat:
            # Binary search for each row
            l, r = 0, n
            while l < r:
                mid_idx = (l + r) // 2
                if row[mid_idx] <= mid:
                    l = mid_idx + 1
                else:
                    r = mid_idx
            count += l
        return count

    k = (m * n + 1) // 2
    low, high = mat[0][0], mat[-1][-1]

    while low < high:
        mid = (low + high) // 2
        if count_less_equal(mid) < k:
            low = mid + 1
        else:
            high = mid

    return low

