def splitStringIntoGroups(s):
    """
    Splits the input string `s` into as many part groups as possible such that each letter appears in at most one group.
    Returns a list of integers representing the size of these parts.
    """
    last_occurrence = {char: idx for idx, char in enumerate(s)}
    parts = []
    start, end = 0, 0

    for idx, char in enumerate(s):
        end = max(end, last_occurrence[char])
        if idx == end:
            parts.append(end - start + 1)
            start = end + 1

    return parts

