def count_pairs_with_sum(arr, target):
    """
    Returns the number of distinct pairs (a, b) in arr such that a + b = target.
    """
    seen = set()
    pairs = set()

    for num in arr:
        complement = target - num
        if complement in seen:
            pairs.add(tuple(sorted((num, complement))))
        seen.add(num)

    return len(pairs)

