def find_peak_grid(matrix):
    rows, cols = len(matrix), len(matrix[0])

    def is_peak(r, c):
        if r > 0 and matrix[r][c] <= matrix[r-1][c]:
            return False
        if r < rows - 1 and matrix[r][c] <= matrix[r+1][c]:
            return False
        if c > 0 and matrix[r][c] <= matrix[r][c-1]:
            return False
        if c < cols - 1 and matrix[r][c] <= matrix[r][c+1]:
            return False
        return True

    for r in range(rows):
        for c in range(cols):
            if is_peak(r, c):
                return [r, c]

    return []

