def longest_common_subsequence(nums1, nums2):
    """
    Returns the length of the longest common subsequence between two sorted arrays nums1 and nums2.
    """
    m = len(nums1)
    n = len(nums2)

    # Create a 2D array to store the length of LCS
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the dp array
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if nums1[i - 1] == nums2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[m][n]

