def is_interleaving(s, words):
    """
    Determine if the string `s` is an interleaving of the strings in `words`.

    Parameters:
    s (str): The target string.
    words (list of str): List of strings to interleave.

    Returns:
    bool: True if `s` is an interleaving of `words`, False otherwise.
    """
    def dfs(s, words, indices):
        if not s and all(i == len(words[j]) for j, i in enumerate(indices)):
            return True
        if not s:
            return False

        for idx, (w, i) in enumerate(zip(words, indices)):
            if i < len(w) and s[0] == w[i]:
                new_indices = indices[:]
                new_indices[idx] += 1
                if dfs(s[1:], words, new_indices):
                    return True
        return False

    return dfs(s, words, [0] * len(words))

