from collections import deque

def shortestPath(grid):
    """
    Function to find the shortest path between two land cells in a binary matrix.

    Parameters:
    grid (list of list of int): 2D binary matrix representing the grid

    Returns:
    int: Length of the shortest path between two land cells, or -1 if no such path exists
    """
    m, n = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def bfs(start_x, start_y):
        visited = [[False]*n for _ in range(m)]
        queue = deque([(start_x, start_y, 0)])
        visited[start_x][start_y] = True

        while queue:
            x, y, dist = queue.popleft()

            for dx, dy in directions:
                nx, ny = x+dx, y+dy
                if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny]:
                    if grid[nx][ny] == 1:
                        return dist + 1
                    if grid[nx][ny] == 0:
                        visited[nx][ny] = True
                        queue.append((nx, ny, dist+1))

        return float('inf')

    shortest_path = float('inf')
    found_land = False

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                found_land = True
                shortest_path = min(shortest_path, bfs(i, j))

    return -1 if shortest_path == float('inf') else shortest_path

def min_bins(products, binCapacity):
    """
    Given a list of product volumes and a bin capacity,
    returns the minimum number of bins required to store all the products.
    If it's not possible, returns -1.
    """
    products.sort(reverse=True)

    bins = []

    for volume in products:
        placed = False
        for i in range(len(bins)):
            if bins[i] + volume <= binCapacity:
                bins[i] += volume
                placed = True
                break
        if not placed:
            if volume > binCapacity:
                return -1
            bins.append(volume)

    return len(bins)

