def longest_substring_with_k_deletions(s, k):
    """
    Returns the length of the longest substring that contains only one unique character
    after making at most k deletions.
    """
    n = len(s)
    if n == 0:
        return 0

    def longest_substring_with_k_replace(char):
        max_length = 0
        left = 0
        max_count = 0
        counts = {'a': 0, 'b': 0}

        for right in range(n):
            counts[s[right]] += 1
            max_count = max(max_count, counts[s[right]])
            while (right - left + 1) - max_count > k:
                counts[s[left]] -= 1
                left += 1
            max_length = max(max_length, right - left + 1)

        return max_length

    return max(longest_substring_with_k_replace('a'), longest_substring_with_k_replace('b'))

