from collections import deque

def min_distance_to_park(city_area):
    """
    Returns a 2D grid where each cell contains the minimum distance to the nearest park.
    -1 if the cell is an obstacle or cannot reach any park.
    """
    if not city_area:
        return []

    rows, cols = len(city_area), len(city_area[0])
    result = [[-1] * cols for _ in range(rows)]
    queue = deque()

    # Enqueue all parks and mark distances for obstacles
    for r in range(rows):
        for c in range(cols):
            if city_area[r][c] == 1:
                queue.append((r, c))
                result[r][c] = 0
            elif city_area[r][c] == -1:
                result[r][c] = -1

    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]

    # BFS to find the shortest path to the nearest park
    while queue:
        x, y = queue.popleft()
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols and result[nx][ny] == -1 and city_area[nx][ny] == 0:
                result[nx][ny] = result[x][y] + 1
                queue.append((nx, ny))

    return result

