def evaluate_expression(s: str) -> int:
    def operate(a, b, op):
        if op == '+':
            return a + b
        elif op == '-':
            return a - b
        elif op == '*':
            return a * b
        elif op == '/':
            return int(a / b)  # Integer division truncating towards zero

    if not s:
        return 0

    n = len(s)
    current_num = 0
    stack = []
    operation = '+'
    i = 0

    while i < n:
        char = s[i]
        if char.isdigit():
            current_num = current_num * 10 + int(char)
        if char in "+-*/" or i == n - 1:
            if operation == '+':
                stack.append(current_num)
            elif operation == '-':
                stack.append(-current_num)
            elif operation == '*':
                stack[-1] = stack[-1] * current_num
            elif operation == '/':
                stack[-1] = int(stack[-1] / current_num)
            operation = char
            current_num = 0
        i += 1

    return sum(stack)

def longest_subarray(nums):
    from collections import defaultdict

    if not nums:
        return 0

    frequency_map = defaultdict(int)
    for num in nums:
        frequency_map[num] += 1

    max_length = 0
    for num in frequency_map:
        current_length = frequency_map[num]
        if (num + 1) in frequency_map:
            current_length += frequency_map[num + 1]
        max_length = max(max_length, current_length)

    return max_length

