def check_subarray_sum(nums, k):
    """
    Returns true if there is a continuous subarray of nums whose elements sum up to k.
    """
    n = len(nums)
    for start in range(n):
        current_sum = 0
        for end in range(start, n):
            current_sum += nums[end]
            if current_sum == k:
                return True
    return False

def stringPartition(s):
    """
    Divides the input string s into substrings such that each substring contains distinct characters only.
    Returns a list of the lengths of each substring.
    """
    if not s:
        return []

    partitions = []
    current_partition = ""

    for char in s:
        if char in current_partition:
            partitions.append(len(current_partition))
            current_partition = char
        else:
            current_partition += char

    # Append the last partition
    if current_partition:
        partitions.append(len(current_partition))

    return partitions

