def isBalanced(s):
    """
    Returns True if the parentheses in the string `s` are balanced, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack or stack.pop() != '(':
                return False
    return not stack

def findMin(nums):
    """
    This function finds the minimum element in a rotated sorted array.
    """
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    return nums[left]

def min_operations_to_remove_consecutive_duplicates(s):
    """
    Returns the minimum number of operations required to make the string have
    no two consecutive identical characters by removing all occurrences
    of chosen characters in one operation.
    """
    if not s:
        return 0

    prev_char = s[0]
    operations = 0
    consecutive_duplicates = False

    for i in range(1, len(s)):
        if s[i] == prev_char:
            consecutive_duplicates = True
        else:
            prev_char = s[i]

    if consecutive_duplicates:
        return len(set(s))
    else:
        return 0

