def containsNearbyAlmostDuplicate(nums, k):
    """
    Returns True if there are two distinct indices i and j in the array such that
    the absolute difference between nums[i] and nums[j] is at most k, and the
    absolute difference between i and j is at most k.

    Parameters:
    nums (list of ints): The integer array to be checked.
    k (int): The maximum allowed difference between i and j.

    Returns:
    bool: True if such elements exist, otherwise False.
    """
    if k < 1:
        return False

    value_indices = {}

    for i, num in enumerate(nums):
        if num in value_indices:
            for j in value_indices[num]:
                if abs(i - j) <= k:
                    return True
            value_indices[num].append(i)
        else:
            value_indices[num] = [i]

    return False

