from collections import defaultdict, deque
from typing import List, Tuple

def buildOrder(numProjects: int, dependencies: List[Tuple[int, int]]) -> List[int]:
    in_degree = {i: 0 for i in range(numProjects)}
    graph = defaultdict(list)

    for dest, src in dependencies:
        graph[src].append(dest)
        in_degree[dest] += 1

    zero_in_degree_queue = deque([k for k, v in in_degree.items() if v == 0])
    topo_order = []

    while zero_in_degree_queue:
        vertex = zero_in_degree_queue.popleft()
        topo_order.append(vertex)

        for neighbor in graph[vertex]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                zero_in_degree_queue.append(neighbor)

    if len(topo_order) == numProjects:
        return topo_order
    else:
        return []

