def reorder_string(s):
    """
    Reorders the string such that all alphabets appear first in their original order,
    followed by all the digits in their original order.

    :param s: A string consisting of digits and lowercase alphabets.
    :return: The reordered string.
    """
    alphabets = []
    digits = []

    for char in s:
        if char.isdigit():
            digits.append(char)
        elif char.isalpha():
            alphabets.append(char)

    return ''.join(alphabets) + ''.join(digits)

