def first_special_character_index(s):
    """
    Returns the index of the first special character in s.
    If there are no special characters, returns -1.
    """
    # Dictionary to store the frequency of each character
    frequency = {}

    # Count the frequency of each character in the string
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    # Find the first character with frequency of 1
    for index, char in enumerate(s):
        if frequency[char] == 1:
            return index

    # If no special character is found, return -1
    return -1

