def min_operations_to_equalize(nums):
    """
    Returns the minimum number of operations required to make all elements in the array equal.
    If it is not possible, returns -1.
    """
    if len(nums) < 2:
        return 0  # An array with one or zero elements is already equal.

    nums_even_parity = (nums[0] % 2 == 0)

    for num in nums:
        if (num % 2 == 0) != nums_even_parity:
            return -1

    return (max(nums) - min(nums)) // 2

