def min_steps_to_return_to_origin(instructions):
    """
    Returns the minimum number of steps required for the robot to return to the origin
    after executing all the given instructions.
    """
    horizontal, vertical = 0, 0

    for inst in instructions:
        if inst == 'L':
            horizontal -= 1
        elif inst == 'R':
            horizontal += 1
        elif inst == 'U':
            vertical += 1
        elif inst == 'D':
            vertical -= 1

    return abs(horizontal) + abs(vertical)

