def closest_element_position(mat, target):
    """
    Returns the position of the element in mat that is closest to target.
    If multiple elements have the same minimum distance, return the first one
    in reading order (top to bottom, left to right). If the matrix is empty, return (-1, -1).

    :param mat: List[List[int]], the input matrix
    :param target: int, the target value
    :return: Tuple[int, int], position of the closest element in the matrix
    """

    if not mat or not mat[0]:
        return (-1, -1)

    closest_pos = (-1, -1)
    min_dist = float('inf')

    for i in range(len(mat)):
        for j in range(len(mat[0])):
            dist = abs(mat[i][j] - target)
            if dist < min_dist:
                min_dist = dist
                closest_pos = (i, j)

    return closest_pos

