def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)

    if rank[rootX] < rank[rootY]:
        parent[rootX] = rootY
    elif rank[rootX] > rank[rootY]:
        parent[rootY] = rootX
    else:
        parent[rootY] = rootX
        rank[rootX] += 1

def minimum_communication_time(n, edges):
    if n == 1:
        return 0

    edges.sort(key=lambda edge: edge[2])

    parent = [i for i in range(n)]
    rank = [0] * n

    min_time = 0
    edge_count = 0

    for edge in edges:
        a, b, t = edge
        rootA = find(parent, a)
        rootB = find(parent, b)

        if rootA != rootB:
            union(parent, rank, rootA, rootB)
            min_time += t
            edge_count += 1

            if edge_count == n - 1:
                break

    if edge_count != n - 1:
        return -1

    return min_time

