def longestUniqueSubarray(nums):
    """
    Returns the length of the longest subarray with all unique elements.
    """
    if not nums:
        return 0

    seen = {}
    max_length = 0
    start = 0

    for end, value in enumerate(nums):
        if value in seen:
            start = max(start, seen[value] + 1)

        seen[value] = end
        max_length = max(max_length, end - start + 1)

    return max_length

