def max_total_profit(profits, workers, staff):
    projects = sorted(zip(profits, workers), key=lambda x: (-x[0], x[1]))
    available_staff = sorted(staff, reverse=True)

    total_profit = 0
    for profit, worker_required in projects:
        for i in range(len(available_staff)):
            if available_staff[i] >= worker_required:
                total_profit += profit
                available_staff.pop(i)
                break

    return total_profit

