def subarray_sum(nums, target):
    """
    Returns the number of continuous subarrays whose sum equals to the target.
    """
    total_count = 0
    prefix_sum = 0
    prefix_sum_counts = {0: 1}

    for num in nums:
        prefix_sum += num
        if prefix_sum - target in prefix_sum_counts:
            total_count += prefix_sum_counts[prefix_sum - target]
        if prefix_sum in prefix_sum_counts:
            prefix_sum_counts[prefix_sum] += 1
        else:
            prefix_sum_counts[prefix_sum] = 1

    return total_count

def count_subarrays_with_sum(arr, m):
    """
    Returns the number of contiguous subarrays whose sum equals m.

    :param arr: List[int] - list of integers
    :param m: int - the target sum for the subarrays
    :return: int - number of contiguous subarrays with sum equal to m
    """
    count = 0
    prefix_sum = 0
    prefix_sum_counts = {0: 1}

    for num in arr:
        prefix_sum += num
        if prefix_sum - m in prefix_sum_counts:
            count += prefix_sum_counts[prefix_sum - m]
        if prefix_sum in prefix_sum_counts:
            prefix_sum_counts[prefix_sum] += 1
        else:
            prefix_sum_counts[prefix_sum] = 1

    return count

