def longestIncreasingPath(matrix):
    if not matrix or not matrix[0]:
        return 0

    rows, cols = len(matrix), len(matrix[0])
    dp = [[-1 for _ in range(cols)] for _ in range(rows)]

    def dfs(r, c):
        if dp[r][c] != -1:
            return dp[r][c]

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        max_len = 1

        for dr, dc in directions:
            rr, cc = r + dr, c + dc
            if 0 <= rr < rows and 0 <= cc < cols and matrix[rr][cc] > matrix[r][c]:
                path_len = 1 + dfs(rr, cc)
                max_len = max(max_len, path_len)

        dp[r][c] = max_len
        return max_len

    longest_path = 0
    for r in range(rows):
        for c in range(cols):
            longest_path = max(longest_path, dfs(r, c))

    return longest_path

