from typing import List, Tuple

def can_reach_exit(maze: List[List[int]], entrance: Tuple[int, int], exit: Tuple[int, int]) -> bool:
    rows, cols = len(maze), len(maze[0])
    visited = [[False] * cols for _ in range(rows)]

    def dfs(r, c):
        if (r, c) == exit:
            return True
        if r < 0 or r >= rows or c < 0 or c >= cols or maze[r][c] == 1 or visited[r][c]:
            return False
        visited[r][c] = True
        # Explore neighbors: up, down, left, right
        if dfs(r - 1, c) or dfs(r + 1, c) or dfs(r, c - 1) or dfs(r, c + 1):
            return True
        return False

    return dfs(entrance[0], entrance[1])

