def reverseKGroup(arr, k):
    """
    Reverses the given list in groups of k elements.
    If there are fewer than k elements remaining, they are left as they are.
    """
    if k <= 1 or not arr:
        return arr

    result = []
    length = len(arr)

    for i in range(0, length, k):
        if i + k <= length:
            result.extend(arr[i:i+k][::-1])
        else:
            result.extend(arr[i:])

    return result

