def can_form_palindrome(s, k):
    """
    Determine whether you can remove exactly k indices from s
    to make the remaining string a palindrome.
    """
    def is_palindrome(string):
        return string == string[::-1]

    def can_remove_to_form_palindrome(s, k):
        if is_palindrome(s):
            return k % 2 == 0
        if k == 0:
            return is_palindrome(s)

        for i in range(len(s)):
            if can_remove_to_form_palindrome(s[:i] + s[i+1:], k-1):
                return True
        return False

    return can_remove_to_form_palindrome(s, k)

