def min_candies(ratings):
    """
    Returns the minimum number of candies required to distribute
    foreach employee such that the higher rated employee gets more
    candies than his immediate neighbors.

    :param ratings: List[int]
    :return: int
    """
    n = len(ratings)

    # Initialize candies list
    candies = [1] * n

    # First pass, left to right
    for i in range(1, n):
        if ratings[i] > ratings[i - 1]:
            candies[i] = candies[i - 1] + 1

    # Second pass, right to left
    for i in range(n - 2, -1, -1):
        if ratings[i] > ratings[i + 1]:
            candies[i] = max(candies[i], candies[i + 1] + 1)

    return sum(candies)

