def can_reach_last_building(heights, k):
    """
    Determine if it's possible to reach the last building from the first building.

    Parameters:
    heights (List[int]): List of integers representing the heights of buildings.
    k (int): Maximum number of steps you can jump.

    Returns:
    bool: True if it's possible to reach the last building, False otherwise.
    """
    n = len(heights)
    if n == 1:
        return True

    reachable = [False] * n
    reachable[0] = True

    for i in range(n):
        if reachable[i]:
            for j in range(1, k+1):
                if i + j < n and heights[i + j] <= heights[i]:
                    reachable[i + j] = True

    return reachable[-1]

