def longest_subsequence(nums):
    if not nums:
        return 0

    counts = {}
    max_length = 0

    for num in nums:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    for num in counts:
        length = counts[num]
        if num - 1 in counts:
            length += counts[num - 1]
        if num + 1 in counts:
            length += counts[num + 1]
        max_length = max(max_length, length)

    return max_length

