def max_sum_of_k_subarrays(nums, k):
    """
    Returns the maximum possible value of the sum of the maximum element from each subarray
    when split into exactly k subarrays.
    """
    n = len(nums)

    # Special case: If k equals the length of the list
    if k == n:
        return sum(nums)

    # Use dynamic programming to keep track of the max values
    dp = [[0] * (k + 1) for _ in range(n)]

    for i in range(n):
        dp[i][1] = max(nums[:i+1])

    for subarray_count in range(2, k + 1):
        for i in range(subarray_count - 1, n):
            current_max, max_sum = float('-inf'), float('-inf')
            for j in range(i, subarray_count - 2, -1):
                current_max = max(current_max, nums[j])
                max_sum = max(max_sum, (dp[j-1][subarray_count-1] if j > 0 else 0) + current_max)
            dp[i][subarray_count] = max_sum

    return dp[n-1][k]

