from typing import List

def letter_combinations(digits: str) -> List[str]:
    """
    Given a string of digits from 2-9, return all possible letter combinations
    the number could represent.
    """
    if not digits:
        return []

    phone_mapping = {
        '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
        '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    }

    def backtrack(current_combination, next_digits):
        if not next_digits:
            combinations.append(current_combination)
        else:
            for letter in phone_mapping[next_digits[0]]:
                backtrack(current_combination + letter, next_digits[1:])

    combinations = []
    backtrack("", digits)
    return combinations

from heapq import heappush, heappop

def max_buildings(heights, bricks, ladders):
    """
    Return the maximum number of buildings that can be visited using given bricks and ladders optimally.
    """

    min_heap = []
    n = len(heights)

    for i in range(1, n):
        jump = heights[i] - heights[i-1]
        if jump > 0:
            heappush(min_heap, jump)

        if len(min_heap) > ladders:
            bricks -= heappop(min_heap)

        if bricks < 0:
            return i - 1

    return n - 1

