def unique_paths_with_obstacles(obstacle_grid):
    """
    Calculates the number of unique paths in a grid with obstacles from the top-left to the bottom-right corner.

    :param obstacle_grid: List[List[int]], 2D grid where 0 is an empty cell and 1 is an obstacle.
    :return: int, the number of unique paths from (0, 0) to (m-1, n-1)
    """
    if not obstacle_grid or obstacle_grid[0][0] == 1 or obstacle_grid[-1][-1] == 1:
        return 0

    m, n = len(obstacle_grid), len(obstacle_grid[0])
    dp = [[0] * n for _ in range(m)]  # Create a 2D list to store number of paths

    # Initialize the starting point
    dp[0][0] = 1

    # Fill the dp array
    for i in range(m):
        for j in range(n):
            if obstacle_grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

