def find_peak(arr):
    """
    Returns the index of the peak element if the array is mountain-shaped.
    If the array does not form a mountain shape return -1.
    """
    n = len(arr)
    if n < 3:
        return -1

    peak_index = -1

    # Find the peak
    for i in range(1, n-1):
        if arr[i] > arr[i-1] and arr[i] > arr[i+1]:
            if peak_index != -1:
                return -1  # more than one peak
            peak_index = i

    if peak_index == -1:
        return -1  # no peak found

    # Check for strictly increasing sequence before the peak
    for i in range(1, peak_index):
        if arr[i] <= arr[i-1]:
            return -1

    # Check for strictly decreasing sequence after the peak
    for i in range(peak_index + 1, n):
        if arr[i] >= arr[i-1]:
            return -1

    return peak_index

def max_length_ascending_subarray(nums):
    """
    Returns the length of the longest subarray with contiguous elements in ascending order.
    """
    if not nums:
        return 0

    max_len = 1
    curr_len = 1
    for i in range(1, len(nums)):
        if nums[i] > nums[i-1]:
            curr_len += 1
            max_len = max(max_len, curr_len)
        else:
            curr_len = 1

    return max_len

