def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        parent[rootY] = rootX

def smallestStringWithSwaps(s, pairs):
    n = len(s)
    parent = list(range(n))

    for a, b in pairs:
        union(parent, a, b)

    from collections import defaultdict
    components = defaultdict(list)

    for index in range(n):
        root = find(parent, index)
        components[root].append(index)

    s = list(s)
    for indices in components.values():
        chars = sorted(s[index] for index in indices)
        for i, index in enumerate(sorted(indices)):
            s[index] = chars[i]

    return "".join(s)

