def is_subsequence(seq, word):
    """
    Helper function to check if 'word' is a subsequence of 'seq'.
    """
    it = iter(seq)
    return all(char in it for char in word)

def longest_subsequence_length(sequence, words):
    """
    Returns the length of the longest string in 'words' that is a subsequence of 'sequence'.
    If no word is a subsequence of 'sequence', returns 0.
    """
    max_length = 0
    for word in words:
        if is_subsequence(sequence, word):
            max_length = max(max_length, len(word))
    return max_length

