def get_smallest_string(s, k):
    """
    Returns the lexicographically smallest string that can be obtained by performing at most k adjacent swaps.
    """
    if k >= len(s) - 1:
        return ''.join(sorted(s))

    s = list(s)  # convert string to list for easier operations
    for i in range(len(s)):
        pos = i
        for j in range(i + 1, min(i + k + 1, len(s))):
            if s[j] < s[pos]:
                pos = j
        for j in range(pos, i, -1):
            s[j], s[j - 1] = s[j - 1], s[j]
            k -= 1
            if k == 0:
                return ''.join(s)
    return ''.join(s)

