def spiralOrder(matrix):
    """
    Returns all elements of the matrix in spiral order.
    """
    if not matrix or not matrix[0]:
        return []

    m, n = len(matrix), len(matrix[0])
    result = []
    left, right, top, bottom = 0, n-1, 0, m-1

    while left <= right and top <= bottom:
        for j in range(left, right + 1):
            result.append(matrix[top][j])
        for i in range(top + 1, bottom + 1):
            result.append(matrix[i][right])
        if top < bottom:
            for j in range(right - 1, left - 1, -1):
                result.append(matrix[bottom][j])
        if left < right:
            for i in range(bottom - 1, top, -1):
                result.append(matrix[i][left])
        left += 1
        right -= 1
        top += 1
        bottom -= 1

    return result

def longest_peak_subarray(arr):
    """
    Returns the length of the longest subarray where every element is a peak.
    A peak is an element that is greater than its neighbors.
    """
    n = len(arr)
    if n < 3:
        return 0

    longest = 0
    current_length = 0

    for i in range(1, n - 1):
        if arr[i] > arr[i - 1] and arr[i] > arr[i + 1]:
            if current_length == 0:
                current_length = 3
            else:
                current_length += 1
        else:
            if current_length > longest:
                longest = current_length
            current_length = 0

    if current_length > longest:
        longest = current_length

    return longest

