def search_in_mountain_array(arr, target):
    """
    Search for the target value in a mountain array and return its index.
    If the target is not found, return -1.
    """
    def find_peak(arr):
        low, high = 0, len(arr) - 1
        while low < high:
            mid = (low + high) // 2
            if arr[mid] < arr[mid + 1]:
                low = mid + 1
            else:
                high = mid
        return low

    def binary_search(arr, target, low, high, asc=True):
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == target:
                return mid
            if asc:
                if arr[mid] < target:
                    low = mid + 1
                else:
                    high = mid - 1
            else:
                if arr[mid] > target:
                    low = mid + 1
                else:
                    high = mid - 1
        return -1

    peak = find_peak(arr)
    result = binary_search(arr, target, 0, peak, True)
    if result != -1:
        return result

    return binary_search(arr, target, peak + 1, len(arr) - 1, False)

