from typing import List

def fourSum(nums: List[int], target: int) -> List[List[int]]:
    nums.sort()
    res = []
    length = len(nums)

    for i in range(length - 3):
        # Avoid duplicate quadruplets with the same first number
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        for j in range(i + 1, length - 2):
            # Avoid duplicate quadruplets with the same second number
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue

            left, right = j + 1, length - 1

            while left < right:
                total = nums[i] + nums[j] + nums[left] + nums[right]

                if total == target:
                    res.append([nums[i], nums[j], nums[left], nums[right]])

                    # Avoid duplicate quadruplets with the same third and fourth numbers
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1

                    left += 1
                    right -= 1
                elif total < target:
                    left += 1
                else:
                    right -= 1

    return res

def find_longest_string(words):
    """
    Returns the longest string in words that can be formed by deleting some characters
    of another string in words without reordering the remaining characters. If there are
    multiple possible results, returns the lexicographically smallest one.
    """
    if not words:
        return ""

    def is_subsequence(x, y):
        it = iter(y)
        return all(c in it for c in x)

    longest = ""
    words.sort()

    for word in sorted(words, key=lambda x: (-len(x), x)):
        for potential in words:
            if word != potential and is_subsequence(word, potential):
                if len(word) > len(longest) or (len(word) == len(longest) and word < longest):
                    longest = word
                break

    return longest

