def minScore(nums, k):
    def canDivide(target):
        count = 0
        curr_sum = 0
        for num in nums:
            if curr_sum + num > target:
                count += 1
                curr_sum = num
                if curr_sum > target:
                    return False
            else:
                curr_sum += num
        return count < k

    low, high = max(nums), sum(nums)
    while low < high:
        mid = (low + high) // 2
        if canDivide(mid):
            high = mid
        else:
            low = mid + 1
    return low

