def num_resource_islands(grid):
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(x, y):
        stack = [(x, y)]
        has_resource = False

        while stack:
            i, j = stack.pop()

            if grid[i][j] == 'X':
                has_resource = True

            for di, dj in directions:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and not visited[ni][nj] and (grid[ni][nj] == '1' or grid[ni][nj] == 'X'):
                    visited[ni][nj] = True
                    stack.append((ni, nj))

        return has_resource

    count = 0
    for i in range(m):
        for j in range(n):
            if (grid[i][j] == '1' or grid[i][j] == 'X') and not visited[i][j]:
                visited[i][j] = True
                if dfs(i, j):
                    count += 1

    return count

def closed_island(grid):
    """
    Returns the number of closed islands in the given grid.
    An island is considered closed if it is surrounded by water on all sides.
    """
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        if grid[r][c] == 1:
            return True
        grid[r][c] = 1  # Mark as visited
        up = dfs(r - 1, c)
        down = dfs(r + 1, c)
        left = dfs(r, c - 1)
        right = dfs(r, c + 1)

        return up and down and left and right

    closed_islands = 0

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0:
                if dfs(i, j):
                    closed_islands += 1

    return closed_islands

