def longest_increasing_subarray(nums):
    """
    Returns the length of the longest subarray where the elements
    are in strictly increasing order.
    """
    if not nums:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current_len += 1
            max_len = max(max_len, current_len)
        else:
            current_len = 1

    return max_len

