def partition_labels(s):
    """
    Return the starting and ending indices of the smallest number of non-overlapping
    substrings such that each letter appears in at most one substring.
    """
    if not s:
        return []

    last_occurrence = {char: idx for idx, char in enumerate(s)}
    partitions = []
    start, end = 0, 0

    for idx, char in enumerate(s):
        end = max(end, last_occurrence[char])
        if idx == end:
            partitions.append((start, end))
            start = idx + 1

    return partitions

def partition(arr, low, high):
    pivot = arr[high]
    i = low - 1
    for j in range(low, high):
        if arr[j] <= pivot:
            i += 1
            arr[i], arr[j] = arr[j], arr[i]
    arr[i + 1], arr[high] = arr[high], arr[i + 1]
    return i + 1

def quick_select(arr, low, high, k):
    if low < high:
        pivot_index = partition(arr, low, high)
        if pivot_index == k:
            return arr
        elif pivot_index > k:
            return quick_select(arr, low, pivot_index - 1, k)
        else:
            return quick_select(arr, pivot_index + 1, high, k)
    return arr

def rearrange_around_k(arr, k):
    """
    Rearranges the array such that the element at the kth position is in its final sorted position.
    """
    return quick_select(arr, 0, len(arr) - 1, k)

def three_sum(arr, target):
    """
    Determines if there exist three integers in `arr` such that their sum is `target`.

    :param arr: List of integers
    :param target: Integer target sum
    :return: Boolean indicating if there is a combination of three integers that sum to `target`
    """
    arr.sort()
    n = len(arr)

    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            total = arr[i] + arr[left] + arr[right]
            if total == target:
                return True
            elif total < target:
                left += 1
            else:
                right -= 1

    return False

def largest_group(employees_projects):
    from collections import defaultdict

    # Create a dictionary to map employee to projects
    employee_projects = defaultdict(set)

    for project, employees in employees_projects.items():
        for employee in employees:
            employee_projects[employee].add(project)

    # Create a graph where nodes are employees and edges exist if they share a project
    graph = defaultdict(list)

    for project, employees in employees_projects.items():
        for i in range(len(employees)):
            for j in range(i + 1, len(employees)):
                graph[employees[i]].append(employees[j])
                graph[employees[j]].append(employees[i])

    # To find the largest connected component, we perform DFS/BFS on the graph
    def dfs(employee, visited):
        stack = [employee]
        size = 0
        while stack:
            emp = stack.pop()
            if emp not in visited:
                visited.add(emp)
                size += 1
                for neighbor in graph[emp]:
                    if neighbor not in visited:
                        stack.append(neighbor)
        return size

    visited = set()
    max_group_size = 0

    for employee in employee_projects.keys():
        if employee not in visited:
            max_group_size = max(max_group_size, dfs(employee, visited))

    return max_group_size

