def split_array_minimized_max_sum(arr, k):
    def can_split(max_sum):
        current_sum, splits = 0, 1
        for num in arr:
            if current_sum + num > max_sum:
                splits += 1
                current_sum = num
                if splits > k:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(arr), sum(arr)
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1
    return left

