def remove_duplicates(s):
    """
    Returns a new string by arranging the letters in the order they first appeared
    in the string s, but with all subsequent occurrences of each character removed.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

