def remove_duplicates(nums):
    """
    Removes duplicates from a sorted array and returns a new array with unique elements.

    :param nums: List of integers sorted in non-decreasing order
    :return: New list containing only unique elements, in the same order as original
    """
    if not nums:
        return []

