def min_operations_to_make_strictly_increasing(arr, k):
    n = len(arr)
    # Find the longest increasing subsequence (LIS) length in arr.
    lis_len = lis_length(arr)

    # Calculate the minimum number of operations needed
    min_operations = n - lis_len

    # If the minimum number of operations needed is less than or equal to k, return it. Otherwise, return -1.
    return min_operations if min_operations <= k else -1

def lis_length(arr):
    if not arr:
        return 0

    # This will hold the increasing subsequence
    lis = []

    for num in arr:
        # Use binary search to determine the position to replace in `lis`
        left, right = 0, len(lis)
        while left < right:
            mid = (left + right) // 2
            if lis[mid] < num:
                left = mid + 1
            else:
                right = mid

        # If left is within the lis array bounds, replace the element at `left`
        if left < len(lis):
            lis[left] = num
        else:
            # Otherwise, append the number to the lis array
            lis.append(num)

    # The length of `lis` is the length of the longest increasing subsequence
    return len(lis)

def exist(board, word):
    if not board or not word:
        return False

    rows, cols = len(board), len(board[0])

    def backtrack(r, c, index):
        if index == len(word):
            return True

        if r < 0 or r >= rows or c < 0 or c >= cols or board[r][c] != word[index]:
            return False

        tmp, board[r][c] = board[r][c], '#'
        found = (backtrack(r+1, c, index+1) or
                 backtrack(r-1, c, index+1) or
                 backtrack(r, c+1, index+1) or
                 backtrack(r, c-1, index+1))
        board[r][c] = tmp
        return found

    for row in range(rows):
        for col in range(cols):
            if backtrack(row, col, 0):
                return True

    return False

