def maximum_subarray_with_k(arr, k):
    if not arr:
        return 0

    n = len(arr)
    max_sum = float('-inf')
    current_sum = 0

    for i in range(n):
        if i == 0 or abs(arr[i] - arr[i - 1]) <= k:
            current_sum += arr[i]
        else:
            current_sum = arr[i]

        max_sum = max(max_sum, current_sum)

    return max_sum

