def find_closest_visible_buildings(heights):
    """
    For each building in the heights array, find the index of the closest building
    that it can see. If no such building exists, return -1 for that index.
    """
    n = len(heights)
    answer = [-1] * n

    for i in range(n):
        for j in range(i + 1, n):
            if heights[j] > heights[i]:
                can_see = True
                for k in range(i + 1, j):
                    if heights[k] >= heights[j]:
                        can_see = False
                        break
                if can_see:
                    answer[i] = j
                    break

    return answer

