from collections import Counter
import math

def is_perfect_square(n):
    root = int(math.sqrt(n))
    return root * root == n

def count_tuples(arr):
    count = 0
    n = len(arr)

    # Pre-compute the prime factor counts for all numbers in arr
    def prime_factor_counts(x):
        counts = Counter()
        d = 2
        while d * d <= x:
            while (x % d) == 0:
                counts[d] += 1
                x //= d
            d += 1
        if x > 1:
            counts[x] += 1
        return counts

    factor_counts = [prime_factor_counts(x) for x in arr]

    def can_form_perfect_square(i, j, k, l):
        combined_counts = Counter()
        for idx in [i, j, k, l]:
            combined_counts += factor_counts[idx]
        for count in combined_counts.values():
            if count % 2 != 0:
                return False
        return True

    # Search for all quadruples (i, j, k, l)
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                for l in range(k+1, n):
                    if can_form_perfect_square(i, j, k, l):
                        count += 1

    return count

