def search_insert(nums, target):
    """
    Returns the index of the target in the sorted array nums if present.
    If the target is not present, returns the index where it would be inserted.
    The algorithm runs in O(log n) time complexity using binary search.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return left

