import heapq

def is_trip_possible(flights, trips):
    # Create a graph from the list of flights
    graph = {}
    for start, end, price in flights:
        if start not in graph:
            graph[start] = []
        graph[start].append((end, price))

    def dijkstra(origin, destination, budget):
        # Priority queue to store (cost, node)
        pq = [(0, origin)]
        # Dictionary to store the minimum cost to reach each node
        min_cost = {origin: 0}

        while pq:
            current_cost, current_city = heapq.heappop(pq)

            if current_city == destination and current_cost <= budget:
                return True

            if current_cost > budget:
                continue

            for neighbor, price in graph.get(current_city, []):
                new_cost = current_cost + price
                if new_cost < min_cost.get(neighbor, float('inf')):
                    min_cost[neighbor] = new_cost
                    heapq.heappush(pq, (new_cost, neighbor))

        return min_cost.get(destination, float('inf')) <= budget

    results = []
    for origin, destination, budget in trips:
        results.append(dijkstra(origin, destination, budget))

    return results

from collections import deque, defaultdict

def min_steps_to_reach(grid):
    if not grid or not grid[0]:
        return -1

    m, n = len(grid), len(grid[0])

    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return -1

    teleports = defaultdict(list)
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 2:
                teleports[(i, j)].append((i, j))

    visited = set()
    q = deque([(0, 0, 0)])  # (x, y, steps)
    visited.add((0, 0))

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while q:
        x, y, steps = q.popleft()

        if (x, y) == (m-1, n-1):
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < m and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] != 1:
                visited.add((nx, ny))
                q.append((nx, ny, steps + 1))

                if grid[nx][ny] == 2:
                    for teleport in teleports:
                        if teleport != (nx, ny) and teleport not in visited:
                            visited.add(teleport)
                            q.append((teleport[0], teleport[1], steps + 2))

    return -1

def exist(board, word):
    def dfs(board, word, i, j, index):
        if index == len(word):
            return True
        if i < 0 or i >= len(board) or j < 0 or j >= len(board[0]) or board[i][j] != word[index]:
            return False

        temp = board[i][j]
        board[i][j] = '#'

        found = dfs(board, word, i+1, j, index+1) or \
                dfs(board, word, i-1, j, index+1) or \
                dfs(board, word, i, j+1, index+1) or \
                dfs(board, word, i, j-1, index+1)

        board[i][j] = temp
        return found

    for i in range(len(board)):
        for j in range(len(board[0])):
            if dfs(board, word, i, j, 0):
                return True
    return False

def remove_adjacent_pairs(s: str) -> str:
    stack = []
    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)
    return ''.join(stack)

