def is_almost_palindrome(s):
    """
    Determines if the string can be transformed into a palindrome by removing at most one character.

    :param s: Input string
    :return: Boolean indicating if the string is an "almost palindrome"
    """
    def is_palindrome_range(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True

    start, end = 0, len(s) - 1
    while start < end:
        if s[start] != s[end]:
            # Try removing either start or end character
            return is_palindrome_range(start + 1, end) or is_palindrome_range(start, end - 1)
        start += 1
        end -= 1
    return True

