            grid[r][c] = 0
            shape.append(direction)
            dfs(r + 1, c, 'd', shape)  # move down
            dfs(r - 1, c, 'u', shape)  # move up
            dfs(r, c + 1, 'r', shape)  # move right
            dfs(r, c - 1, 'l', shape)  # move left
            shape.append('b')  # mark backtracking

    shapes = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 1:
                shape = []
                dfs(r, c, 'o', shape)  # origin
                shapes.add(tuple(shape))

    return len(shapes)

