def find_peak_2d(matrix):
    def is_peak(x, y):
        curr = matrix[x][y]
        if x > 0 and matrix[x-1][y] >= curr:
            return False
        if x < len(matrix) - 1 and matrix[x+1][y] >= curr:
            return False
        if y > 0 and matrix[x][y-1] >= curr:
            return False
        if y < len(matrix[0]) - 1 and matrix[x][y+1] >= curr:
            return False
        return True

    for i in range(len(matrix)):
        for j in range(len(matrix[0])):
            if is_peak(i, j):
                return [i, j]
    return None  # In case there are no peaks which should not be possible with given problem constraints.

