def lexicographically_smallest_string(s: str) -> str:
    """
    Returns the lexicographically smallest string that can be obtained
    after an infinite number of the allowed operations.
    """
    if not s:
        return ""

    smallest_char = min(s)
    return smallest_char * len(s)

