def num_islands(grid):
    if not grid:
        return 0

    num_rows, num_cols = len(grid), len(grid[0])
    visited = [[False for _ in range(num_cols)] for _ in range(num_rows)]

    def dfs(r, c):
        if r < 0 or r >= num_rows or c < 0 or c >= num_cols or grid[r][c] == '0' or visited[r][c]:
            return
        visited[r][c] = True
        dfs(r - 1, c)
        dfs(r + 1, c)
        dfs(r, c - 1)
        dfs(r, c + 1)

    island_count = 0
    for r in range(num_rows):
        for c in range(num_cols):
            if grid[r][c] == '1' and not visited[r][c]:
                island_count += 1
                dfs(r, c)

    return island_count

def longestSubstring(s, k):
    """
    Returns the length of the longest substring of s in which each character appears at least k times.
    """
    def helper(s, k, start, end):
        if end - start < k:
            return 0

        char_count = {}
        for i in range(start, end):
            char_count[s[i]] = char_count.get(s[i], 0) + 1

        for mid in range(start, end):
            if char_count[s[mid]] < k:
                mid_next = mid + 1
                while mid_next < end and char_count[s[mid_next]] < k:
                    mid_next += 1
                return max(helper(s, k, start, mid), helper(s, k, mid_next, end))

        return end - start

    return helper(s, k, 0, len(s))

