def minimizeMaxTime(tasks):
    from itertools import combinations

    def canDistribute(tasks, limit):
        n = len(tasks)
        for i in range(1 << n):  # All subsets
            group1 = sum(tasks[j] for j in range(n) if i & (1 << j))
            group2 = sum(tasks) - group1
            if max(group1, group2) <= limit:
                return True
        return False

    lo, hi = max(tasks), sum(tasks)
    while lo < hi:
        mid = (lo + hi) // 2
        if canDistribute(tasks, mid):
            hi = mid
        else:
            lo = mid + 1
    return lo

