def is_prime(num):
    """
    Check if a number is prime.
    """
    if num < 2:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def sum_of_primes(m, n):
    """
    Returns the sum of all prime numbers between m and n inclusive.
    """
    return sum(num for num in range(m, n + 1) if is_prime(num))

