def subarray_sum(nums, k):
    """
    Returns True if there is a contiguously subarray in nums that sums to k, otherwise False.
    """
    cum_sum = 0
    sum_dict = {0: 1}

    for num in nums:
        cum_sum += num
        if (cum_sum - k) in sum_dict:
            return True
        if cum_sum in sum_dict:
            sum_dict[cum_sum] += 1
        else:
            sum_dict[cum_sum] = 1

    return False

