def lexicographically_smallest_string(s):
    """
    Returns the lexicographically smallest string possible by performing
    the given operation any number of times.
    """
    if not s:
        return s

    s = list(s)

    # Simply replace all 'b' and 'c' to 'a' because 'a' is the smallest
    for i in range(len(s)):
        if s[i] != 'a':
            s[i] = 'a'

    return "".join(s)

def findSubsequences(nums):
    def backtrack(start, path):
        if len(path) > 1:
            result.add(tuple(path))
        for i in range(start, len(nums)):
            if not path or nums[i] >= path[-1]:
                backtrack(i + 1, path + [nums[i]])

    result = set()
    backtrack(0, [])
    return list(result)

