def minimize_max_time(times, k):
    def can_divide_with_time_limit(max_time_limit):
        current_sum = 0
        team_count = 1
        for time in times:
            if current_sum + time <= max_time_limit:
                current_sum += time
            else:
                team_count += 1
                current_sum = time
                if team_count > k:
                    return False
        return True

    times.sort()
    low, high = max(times), sum(times)
    while low < high:
        mid = low + (high - low) // 2
        if can_divide_with_time_limit(mid):
            high = mid
        else:
            low = mid + 1
    return low

