def contains_nearby_almost_duplicate(arr, k, t):
    """
    Returns true if there are two distinct indices i and j in the array
    such that abs(arr[i] - arr[j]) <= t and abs(i - j) <= k.
    """
    if k <= 0 or t < 0:
        return False

    n = len(arr)
    for i in range(n):
        for j in range(i + 1, min(i + k + 1, n)):
            if abs(arr[i] - arr[j]) <= t:
                return True

    return False

from heapq import heappush, heappop
from collections import Counter, deque

def rearrange_string(s, k):
    if k == 0:
        return s

    freq = Counter(s)
    max_heap = []
    for char, count in freq.items():
        heappush(max_heap, (-count, char))

    result_queue = deque()
    result = []
    while max_heap:
        curr_count, curr_char = heappop(max_heap)
        result.append(curr_char)
        result_queue.append((curr_count + 1, curr_char))

        if len(result_queue) < k:
            continue

        front_count, front_char = result_queue.popleft()
        if -front_count > 0:
            heappush(max_heap, (front_count, front_char))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return ""

