def groupUniqueLetters(s):
    """
    Returns the processed string where each group of identical consecutive characters
    is replaced by a single character and all unique characters at their first
    appearance are maintained in their relative order.
    """
    if not s:
        return ""

    result = [s[0]]  # Initialize the result list with the first character of the string.

    for char in s[1:]:
        if char != result[-1]:
            result.append(char)

    return "".join(result)

