def is_path(grid):
    """
    Determines if there is a path from the top-left to the bottom-right corner of the maze.

    Args:
    grid (list of list of int): The maze represented as a 2D list where 1 is a wall and 0 is an open path.

    Returns:
    bool: True if there is a path, False otherwise.
    """
    if not grid or not grid[0] or grid[0][0] == 1 or grid[-1][-1] == 1:
        return False

    m, n = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right

    def dfs(x, y):
        if x == m-1 and y == n-1:
            return True
        grid[x][y] = 1  # Mark as visited by setting to 1 (wall)
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0:
                if dfs(nx, ny):
                    return True
        grid[x][y] = 0  # Unmark (backtrack)
        return False

    return dfs(0, 0)

def count_prefixes(words):
    """
    Returns the number of strings in `words` that are prefixes of at least one other string in the list.
    """
    count = 0
    for i, word1 in enumerate(words):
        is_prefix = any(word2.startswith(word1) for j, word2 in enumerate(words) if i != j)
        if is_prefix:
            count += 1
    return count

