def depth_sum(nestedList):
    """
    Calculates the weighted sum of all numbers in the nested list
    based on their depth levels.
    """

    def helper(nList, depth):
        result = 0
        for element in nList:
            if isinstance(element, int):
                result += element * depth
            else:
                result += helper(element, depth + 1)
        return result

    return helper(nestedList, 1)

