def mergeSort(nums):
    if len(nums) <= 1:
        return nums

    def merge(left, right):
        sorted_array = []
        i = j = 0

        while i < len(left) and j < len(right):
            if left[i] < right[j]:
                sorted_array.append(left[i])
                i += 1
            else:
                sorted_array.append(right[j])
                j += 1

        while i < len(left):
            sorted_array.append(left[i])
            i += 1

        while j < len(right):
            sorted_array.append(right[j])
            j += 1

        return sorted_array

    mid = len(nums) // 2
    left_half = mergeSort(nums[:mid])
    right_half = mergeSort(nums[mid:])

    return merge(left_half, right_half)

