def is_valid(workloads, k, max_workload):
    current_sum = 0
    workers_needed = 1
    for workload in workloads:
        if current_sum + workload > max_workload:
            workers_needed += 1
            current_sum = workload
            if workers_needed > k:
                return False
        else:
            current_sum += workload
    return True

def minimize_maximum_time(projects, k):
    low, high = max(projects), sum(projects)
    while low < high:
        mid = (low + high) // 2
        if is_valid(projects, k, mid):
            high = mid
        else:
            low = mid + 1
    return low

