from typing import List

def minimum_cameras(buildings: List[int]) -> int:
    n = len(buildings)
    if n == 0:
        return 0

    cameras = 1  # Place the first camera on the tallest building from the right
    tallest = buildings[-1]  # Start with the last building as the tallest

    for i in range(n-2, -1, -1):
        if buildings[i] > tallest:
            cameras += 1
            tallest = buildings[i]

    return cameras

