def is_magic_square(submatrix):
    s = 15  # Sum of each row/column/diagonal in a 3x3 magic square of 1-9
    return (
        sum(submatrix[0]) == s and
        sum(submatrix[1]) == s and
        sum(submatrix[2]) == s and
        sum(submatrix[i][0] for i in range(3)) == s and
        sum(submatrix[i][1] for i in range(3)) == s and
        sum(submatrix[i][2] for i in range(3)) == s and
        submatrix[0][0] + submatrix[1][1] + submatrix[2][2] == s and
        submatrix[0][2] + submatrix[1][1] + submatrix[2][0] == s and
        sorted(submatrix[i][j] for i in range(3) for j in range(3)) == list(range(1, 10))
    )

def contains_magic_square(matrix):
    rows, cols = len(matrix), len(matrix[0])

    for i in range(rows - 2):
        for j in range(cols - 2):
            submatrix = [matrix[i + x][j:j + 3] for x in range(3)]
            if is_magic_square(submatrix):
                return True

    return False

def maximalSquare(matrix):
    """
    Returns the area of the largest square that can be formed where all buildings
    in that square have the same height.
    """
    if not matrix:
        return 0

    n = len(matrix)
    m = len(matrix[0])

    # Create a 3D dp array to store the maximum side length of squares with the same height ending at (i, j)
    dp = [[[0 for _ in range(201)] for _ in range(m)] for _ in range(n)]

    max_side = 0

    for i in range(n):
        for j in range(m):
            current_height = matrix[i][j]
            dp[i][j][current_height] = 1
            if i > 0 and j > 0:
                for h in range(1, 201):
                    if matrix[i][j] == h:
                        dp[i][j][h] = min(dp[i-1][j][h], dp[i][j-1][h], dp[i-1][j-1][h]) + 1
            max_side = max(max_side, dp[i][j][current_height])

    # Return the area of the largest square
    return max_side * max_side

