def find_unobstructed_buildings(heights):
    """
    Returns a list of indices of the unobstructed buildings in the heights array.
    """
    n = len(heights)
    unobstructed = []

    max_height = 0
    for i in range(n - 1, -1, -1):
        if heights[i] > max_height:
            unobstructed.append(i)
            max_height = heights[i]

    return sorted(unobstructed)

