def min_distance(word1, word2):
    """
    Returns the minimum number of steps required to make word1 and word2 equal by deleting characters.
    """
    m, n = len(word1), len(word2)

    # Initialize DP table
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the table with base cases
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # delete all from word2
            elif j == 0:
                dp[i][j] = i  # delete all from word1
            elif word1[i - 1] == word2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1])  # delete from either word1 or word2

    return dp[m][n]

