def find_min_radius(houses, heaters):
    """
    Finds the minimum radius required for heaters to cover all houses.

    :param houses: List[int] - Positions of the houses
    :param heaters: List[int] - Positions where heaters are placed
    :return: int - Minimum radius required for heaters to cover all houses
    """
    houses.sort()
    heaters.sort()

    def is_covered(radius):
        heater_index = 0
        for house in houses:
            while (heater_index < len(heaters) and heaters[heater_index] + radius < house):
                heater_index += 1
            if heater_index == len(heaters) or heaters[heater_index] - radius > house:
                return False
        return True

    lo, hi = 0, max(max(houses), max(heaters)) - min(min(houses), min(heaters))
    while lo < hi:
        mid = (lo + hi) // 2
        if is_covered(mid):
            hi = mid
        else:
            lo = mid + 1

    return lo

