def get_factors(n):
    """
    Returns a list of all unique combinations of factors
    (excluding 1 and the number itself) that multiply to `n`.
    Each combination is sorted in ascending order, and the result list
    is sorted lexicographically.
    """

    def backtrack(start, target, path):
        if target == 1:
            if len(path) > 1:
                result.append(path[:])
            return

        for i in range(start, target + 1):
            if target % i == 0:
                path.append(i)
                backtrack(i, target // i, path)
                path.pop()

    result = []
    backtrack(2, n, [])
    return result

