def min_cost_transform(s, t):
    """
    Returns the minimum cost to transform string s into string t.
    The cost is 1 unit per character change.
    """
    if len(s) != len(t):
        return -1

    # Cost is determined by the number of differing characters.
    cost = 0
    for sc, tc in zip(s, t):
        if sc != tc:
            cost += 1
    return cost

