def splitArray(arr, N):
    """
    Divide the array into exactly N contiguous subarrays such that the maximum sum of any subarray is minimized.

    Parameters:
    arr (list): Array of integers.
    N (int): Number of subarrays.

    Returns:
    int: The minimized maximum sum of any subarray.
    """
    def canSplit(maxSubarraySum):
        subarrayCount = 1
        currentSum = 0

        for num in arr:
            if currentSum + num > maxSubarraySum:
                subarrayCount += 1
                currentSum = num
                if subarrayCount > N:
                    return False
            else:
                currentSum += num

        return True

    left = max(arr)
    right = sum(arr)
    while left < right:
        mid = (left + right) // 2
        if canSplit(mid):
            right = mid
        else:
            left = mid + 1

    return left

