def is_path_exists(grid):
    """
    Returns true if there is a path from the top-left corner to the bottom-right corner of the grid.
    We can only move up, down, left, or right and only through cells that contain the value 1.
    """
    m, n = len(grid), len(grid[0])
    if grid[0][0] == 0 or grid[m-1][n-1] == 0:
        return False

    # Directions: up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False]*n for _ in range(m)]

    def dfs(x, y):
        if x == m - 1 and y == n - 1:
            return True
        visited[x][y] = True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not visited[nx][ny] and grid[nx][ny] == 1:
                if dfs(nx, ny):
                    return True
        return False

    return dfs(0, 0)

