def split_array(nums, m):
    """
    Minimizes the maximum sum of any subarray when the given array is split into m subarrays.
    """
    def can_split(largest_sum):
        current_sum = 0
        count = 1
        for num in nums:
            if current_sum + num > largest_sum:
                current_sum = num
                count += 1
                if count > m:
                    return False
            else:
                current_sum += num
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1
    return left

