def max_sum_submatrix(matrix, k, l):
    """
    Returns the maximum sum of a contiguous submatrix of size k x l in the given matrix.
    """
    m = len(matrix)
    n = len(matrix[0])

    # Initialize max sum to a very low value
    max_sum = float('-inf')

    # Iterate over all possible top-left corners of k x l submatrices in the matrix
    for i in range(m - k + 1):
        for j in range(n - l + 1):
            # Calculate the sum of the current k x l submatrix
            current_sum = 0
            for row in range(k):
                for col in range(l):
                    current_sum += matrix[i + row][j + col]
            # Update max_sum if we found a new max
            if current_sum > max_sum:
                max_sum = current_sum

    return max_sum

def numFullySurroundedIslands(grid):
    if not grid or not grid[0]:
        return 0

    def dfs(i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == 0:
            return
        grid[i][j] = 0
        for x, y in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            dfs(i + x, j + y)

    def is_on_boundary(i, j):
        return i == 0 or i == len(grid) - 1 or j == 0 or j == len(grid[0]) - 1

    # Turn boundary-connected '1's and their connected components into '0's
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if is_on_boundary(i, j) and grid[i][j] == 1:
                dfs(i, j)

    # Count the fully surrounded islands
    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                count += 1
                dfs(i, j)

    return count

