def lcs_length(nums1, nums2):
    """
    Returns the length of the Longest Common Subsequence (LCS) between two sequences nums1 and nums2.
    """
    n = len(nums1)
    m = len(nums2)

    dp = [[0 for _ in range(m+1)] for _ in range(n+1)]

    for i in range(1, n+1):
        for j in range(1, m+1):
            if nums1[i-1] == nums2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[n][m]

