def maximum_savings(prices, discount, k):
    if k > len(prices):
        return 0

    max_saving = 0
    discount = discount / 100

    for i in range(len(prices) - k + 1):
        subarray = prices[i:i+k]
        savings = sum(subarray) * discount
        max_saving = max(max_saving, savings)

    return max_saving

def longestEvenSubstring(s):
    """
    Returns the length of the longest substring where every character appears an even number of times.
    """
    n = len(s)
    if n == 0:
        return 0

    prefixXOR = [0] * (n + 1)
    xorIndex = {0: -1}
    max_length = 0

    for i in range(n):
        prefixXOR[i + 1] = prefixXOR[i] ^ (1 << (ord(s[i]) - ord('a')))
        if prefixXOR[i + 1] in xorIndex:
            max_length = max(max_length, i - xorIndex[prefixXOR[i + 1]])
        else:
            xorIndex[prefixXOR[i + 1]] = i

    return max_length

