def can_partition_k_subsets(arr, k):
    """
    Determine if the array can be split into k non-empty groups such that
    the sum of the elements in each group is the same.
    Returns True if such a division is possible, otherwise False.
    """
    total_sum = sum(arr)

    if total_sum % k != 0:
        return False

    target_sum = total_sum // k
    subsets = [0] * k
    arr.sort(reverse=True)

    def backtrack(index):
        if index == len(arr):
            return all(s == target_sum for s in subsets)

        for i in range(k):
            if subsets[i] + arr[index] <= target_sum:
                subsets[i] += arr[index]
                if backtrack(index + 1):
                    return True
                subsets[i] -= arr[index]
            if subsets[i] == 0:
                break
        return False

    return backtrack(0)

