def find_unsorted_subarray(nums):
    """
    Returns the shortest continuous subarray which if sorted will make the whole array sorted.
    Also returns the starting and ending indices of that subarray.
    If the array is already sorted, returns an empty list.
    """
    # Edge case for an empty array
    if not nums:
        return []

    n = len(nums)
    left, right = None, None

    # Find the left boundary
    for i in range(n - 1):
        if nums[i] > nums[i + 1]:
            left = i
            break

    # If the array is already sorted
    if left is None:
        return []

    # Find the right boundary
    for j in range(n - 1, 0, -1):
        if nums[j] < nums[j - 1]:
            right = j
            break

    # Find the min and max of the unsorted subarray
    sub_min = min(nums[left:right + 1])
    sub_max = max(nums[left:right + 1])

    # Expand the left boundary if needed
    for i in range(left):
        if nums[i] > sub_min:
            left = i
            break

    # Expand the right boundary if needed
    for j in range(n - 1, right, -1):
        if nums[j] < sub_max:
            right = j
            break

    return nums[left:right + 1], (left, right)

