from typing import List

def canTypeSentence(words: List[str], s: str) -> bool:
    """
    Returns True if the sentence `s` can be typed using the provided list of words, False otherwise.
    Each letter can only be used once.
    """
    # Create a dictionary to count the frequency of each character in words list
    letter_count = {}
    for word in words:
        for letter in word:
            if letter not in letter_count:
                letter_count[letter] = 0
            letter_count[letter] += 1

    # Check if we can form the sentence s with the given letters
    for letter in s:
        if letter != ' ':
            if letter not in letter_count or letter_count[letter] == 0:
                return False
            letter_count[letter] -= 1

    return True

