def max_subarray_sum_circular(nums):
    """
    Returns the maximum sum of any subarray within the circular array nums.
    """
    def kadane(arr):
        curr_sum = max_sum = arr[0]
        for num in arr[1:]:
            curr_sum = max(num, curr_sum + num)
            max_sum = max(max_sum, curr_sum)
        return max_sum

    max_kadane = kadane(nums)

    total_sum = sum(nums)
    for i in range(len(nums)):
        nums[i] = -nums[i]

    inverted_kadane = kadane(nums)
    max_wraparound = total_sum + inverted_kadane

    if max_wraparound == 0:
        return max_kadane
    else:
        return max(max_kadane, max_wraparound)

