def can_partition(nums, k, max_sum):
    current_sum = 0
    required_parts = 1

    for num in nums:
        if current_sum + num > max_sum:
            required_parts += 1
            current_sum = num
            if required_parts > k:
                return False
        else:
            current_sum += num

    return True

def split_array(nums, k):
    left = max(nums)
    right = sum(nums)

    while left < right:
        mid = (left + right) // 2
        if can_partition(nums, k, mid):
            right = mid
        else:
            left = mid + 1

    return left

