def search_matrix(matrix, target):
    """
    Determines if a given integer `target` exists in the matrix.
    The matrix has the property of rows and columns being sorted in ascending order.
    """
    if not matrix or not matrix[0]:
        return False

    rows = len(matrix)
    cols = len(matrix[0])

    # Start from top-right corner
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] > target:
            col -= 1
        else:
            row += 1

    return False

