def evaluate_expression(s):
    """
    Evaluates the given mathematical expression string and returns its value.

    Arguments:
    s -- a string representing a mathematical expression containing integers, '+', '-', '*', '/' operators, and spaces.

    Returns:
    The result of evaluating the expression as an integer.
    """
    s = s.replace(' ', '')
    num, stack, sign = 0, [], '+'
    i = 0

    while i < len(s):
        if s[i].isdigit():
            num = num * 10 + int(s[i])

        if s[i] in '+-*/' or i == len(s) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack.append(stack.pop() * num)
            elif sign == '/':
                stack.append(int(stack.pop() / num))

            sign = s[i]
            num = 0

        i += 1

    return sum(stack)

