def max_time_spent_on_task(logs):
    """
    Returns the id of the employee who has the maximum time spent on a task.

    :param logs: List of logs. Each log is a list with three elements [id, status, timestamp]
    :return: id of the employee with maximum time spent on a task
    """
    task_times = {}
    start_times = {}

    for log in logs:
        emp_id, status, timestamp = log
        if status == "start":
            start_times[emp_id] = timestamp
        elif status == "end":
            if emp_id in start_times:
                elapsed_time = timestamp - start_times[emp_id]
                if emp_id in task_times:
                    task_times[emp_id] = max(task_times[emp_id], elapsed_time)
                else:
                    task_times[emp_id] = elapsed_time

    max_time = -1
    max_id = float('inf')

    for emp_id, time in task_times.items():
        if time > max_time or (time == max_time and emp_id < max_id):
            max_time = time
            max_id = emp_id

    return max_id

