def word_mapper(words):
    """
    Returns a dictionary where each key is a word from the list and
    the value is a list of indices at which the word appears in the list.
    """
    word_dict = {}
    for index, word in enumerate(words):
        if word in word_dict:
            word_dict[word].append(index)
        else:
            word_dict[word] = [index]
    return word_dict

