def simplify_path(path):
    """
    Simplify a given absolute Unix file path.

    Args:
    path (str): A string representing the absolute Unix file path.

    Returns:
    str: The simplified canonical path.
    """
    parts = path.split('/')
    stack = []

    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)

    result = '/' + '/'.join(stack)
    return result

