def consecutive_sum_ways(n):
    """
    Returns the total number of ways to express n as the sum of one or more consecutive positive integers.
    """
    count = 0
    for start in range(1, n + 1):
        sum_consecutive = 0
        for i in range(start, n + 1):
            sum_consecutive += i
            if sum_consecutive == n:
                count += 1
                break
            elif sum_consecutive > n:
                break
    return count

