from typing import List

def countSubarrays(nums: List[int], target: int) -> int:
    """
    Returns the number of contiguous subarrays that sum to the given target.
    """
    count = 0
    current_sum = 0
    prefix_sums = {0: 1}

    for num in nums:
        current_sum += num
        if current_sum - target in prefix_sums:
            count += prefix_sums[current_sum - target]

        if current_sum in prefix_sums:
            prefix_sums[current_sum] += 1
        else:
            prefix_sums[current_sum] = 1

    return count

