def findTarget(matrix, target):
    """
    Returns True if there exists a rectangle in the given k x k matrix whose sum is equal to the target.
    Otherwise, returns False.
    """
    if not matrix:
        return False

    rows, cols = len(matrix), len(matrix[0])

    # Calculate prefix sums for the matrix
    prefix_sums = [[0] * (cols + 1) for _ in range(rows + 1)]

    for r in range(1, rows + 1):
        for c in range(1, cols + 1):
            prefix_sums[r][c] = matrix[r-1][c-1] \
                                + prefix_sums[r-1][c] \
                                + prefix_sums[r][c-1] \
                                - prefix_sums[r-1][c-1]

    # Check all possible rectangles
    for r1 in range(1, rows + 1):
        for r2 in range(r1, rows + 1):
            for c1 in range(1, cols + 1):
                for c2 in range(c1, cols + 1):
                    rect_sum = prefix_sums[r2][c2] \
                               - prefix_sums[r1-1][c2] \
                               - prefix_sums[r2][c1-1] \
                               + prefix_sums[r1-1][c1-1]
                    if rect_sum == target:
                        return True
    return False

