from typing import List

def add_operators(num: str, target: int) -> List[str]:
    def backtrack(index, path, value, last):
        if index == len(num):
            if value == target:
                result.append(path)
            return

        for i in range(index, len(num)):
            temp_str = num[index:i+1]
            temp_val = int(temp_str)

            if i != index and num[index] == '0':
                break

            if index == 0:
                backtrack(i + 1, temp_str, temp_val, temp_val)
            else:
                backtrack(i + 1, path + '+' + temp_str, value + temp_val, temp_val)
                backtrack(i + 1, path + '-' + temp_str, value - temp_val, -temp_val)
                backtrack(i + 1, path + '*' + temp_str, value - last + last * temp_val, last * temp_val)

    result = []
    backtrack(0, "", 0, 0)
    return result

