def count_k_complementary_pairs(nums, k):
    """
    Returns the number of k-complementary pairs in the given array.

    :param nums: List of integers
    :param k: Target integer sum for k-complementary pairs
    :return: Number of k-complementary pairs
    """
    num_count = {}
    pair_count = 0

    for num in nums:
        complement = k - num
        if complement in num_count:
            pair_count += num_count[complement]
        if num in num_count:
            num_count[num] += 1
        else:
            num_count[num] = 1

    return pair_count

