from collections import defaultdict

def build_tree(parent):
    tree = defaultdict(list)
    root = -1
    n = len(parent)
    for i in range(n):
        if parent[i] == -1:
            root = i
        else:
            tree[parent[i]].append(i)
    return tree, root

def count_nodes_greater_than_x(tree, values, u, x):
    def dfs(node):
        count = 0
        if values[node] > x:
            count += 1
        for child in tree[node]:
            count += dfs(child)
        return count

    return dfs(u)

def query_subtree_greater_than_x(parent, value, queries):
    tree, root = build_tree(parent)
    result = []
    for u, x in queries:
        result.append(count_nodes_greater_than_x(tree, value, u, x))
    return result

