def exists_pair(nums):
    """
    Determine if there exists a pair of indices (i, j) such that i < j
    and nums[i] + nums[j] > nums[k] for some k where k is any index in
    the range [0, n-1] excluding i and j.
    """
    # The minimum number of elements to find such a pair is 3
    if len(nums) < 3:
        return False

    for i in range(len(nums) - 1):
        if nums[i] + nums[i + 1] > nums[-1]:
            return True

    return False

