def pacific_atlantic(grid):
    if not grid or not grid[0]:
        return []

    m, n = len(grid), len(grid[0])

    def bfs(starts):
        visited = set(starts)
        queue = starts[:]
        while queue:
            i, j = queue.pop(0)
            for di, dj in ((0, 1), (1, 0), (0, -1), (-1, 0)):
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and (ni, nj) not in visited and grid[ni][nj] >= grid[i][j]:
                    visited.add((ni, nj))
                    queue.append((ni, nj))
        return visited

    pacific_starts = [(i, 0) for i in range(m)] + [(0, j) for j in range(1, n)]
    atlantic_starts = [(i, n - 1) for i in range(m)] + [(m - 1, j) for j in range(n - 1)]

    pacific_reachable = bfs(pacific_starts)
    atlantic_reachable = bfs(atlantic_starts)

    return list(pacific_reachable.intersection(atlantic_reachable))

def min_days_to_unique_heights(trees):
    """
    Determines the minimum number of days required to ensure that no two adjacent trees have the same height.
    If it’s not possible to achieve this condition, returns -1.
    """
    # Early low-length check cases
    if not trees:
        return 0
    if len(trees) == 1:
        return 0

    days = 0
    n = len(trees)

    # Check for each tree if it can be removed to satisfy the condition
    i = 0
    while i < len(trees) - 1:
        if trees[i] == trees[i + 1]:
            days += 1
            if i + 2 < n:
                trees.pop(i + 1)
            else:
                trees.pop(i)
        else:
            i += 1

    # Verify all adjacent trees have different heights (final check)
    for i in range(1, len(trees)):
        if trees[i] == trees[i - 1]:
            return -1

    return days

