def smallest_subgrid(grid):
    n = len(grid)
    if n == 0:
        return []

    m = len(grid[0])
    if m == 0:
        return []

    min_row, max_row = n, -1
    min_col, max_col = m, -1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                if i < min_row:
                    min_row = i
                if i > max_row:
                    max_row = i
                if j < min_col:
                    min_col = j
                if j > max_col:
                    max_col = j

    if min_row == n:
        return []

    return [min_row, min_col, max_row, max_col]

