def largest_island_perimeter(grid):
    """
    Returns the perimeter of the largest island in the grid.
    """
    def dfs(r, c):
        stack = [(r, c)]
        visited.add((r, c))
        perimeter = 0
        island_size = 0

        while stack:
            x, y = stack.pop()
            island_size += 1

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n:
                    if grid[nx][ny] == '0':
                        perimeter += 1
                    elif grid[nx][ny] == '1' and (nx, ny) not in visited:
                        stack.append((nx, ny))
                        visited.add((nx, ny))
                else:
                    perimeter += 1

        return perimeter, island_size

    m, n = len(grid), len(grid[0])
    visited = set()
    max_perimeter = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and (i, j) not in visited:
                perimeter, island_size = dfs(i, j)
                if island_size > 0:
                    max_perimeter = max(max_perimeter, perimeter)

    return max_perimeter

