def min_path_sum(matrix):
    """
    Finds the path from top-left to bottom-right in a matrix such that the sum of
    integers along the path is minimized. Returns the minimum sum and the path taken.
    Path is returned as a list of coordinates.
    """
    if not matrix or not matrix[0]:
        return 0, []

    m, n = len(matrix), len(matrix[0])

    # Initialize a dp array to store the minimum sum up to each cell
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = matrix[0][0]

    # Populate the dp table and path tracking
    for i in range(m):
        for j in range(n):
            if i == 0 and j > 0:
                dp[i][j] = dp[i][j-1] + matrix[i][j]
            elif j == 0 and i > 0:
                dp[i][j] = dp[i-1][j] + matrix[i][j]
            elif i > 0 and j > 0:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    # Backtrack to find the path
    path = []
    i, j = m - 1, n - 1
    path.append((i, j))
    while i > 0 or j > 0:
        if i == 0:
            j -= 1
        elif j == 0:
            i -= 1
        elif dp[i-1][j] < dp[i][j-1]:
            i -= 1
        else:
            j -= 1
        path.append((i, j))

    return dp[m-1][n-1], path[::-1]

def largestIsland(grid):
    """
    Returns the size of the largest island that can be achieved
    by converting at most one '0' to '1' in the grid.
    """
    rows, cols = len(grid), len(grid[0])

    def dfs(r, c, index):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] != 1:
            return 0
        grid[r][c] = index
        area = 1
        for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            area += dfs(r + dr, c + dc, index)
        return area

    index = 2
    area_map = {0: 0}

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                area = dfs(r, c, index)
                area_map[index] = area
                index += 1

    max_area = max(area_map.values(), default=0)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                seen = set()
                for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] > 1:
                        seen.add(grid[nr][nc])
                max_area = max(max_area, 1 + sum(area_map[index] for index in seen))

    return max_area

