def minAddToMakeValid(s):
    """
    Return the minimum number of parentheses to be added to make the string valid.
    """
    left_count = 0
    right_needed = 0

    for char in s:
        if char == '(':
            left_count += 1
        elif char == ')':
            if left_count > 0:
                left_count -= 1
            else:
                right_needed += 1

    return left_count + right_needed

