def min_changes_to_satisfy_condition(heights):
    """
    Returns the minimum number of students that need to change positions
    so that all students have heights strictly different from both their neighbors.
    """
    n = len(heights)
    if n < 3:
        return 0  # If there are less than 3 students, no changes are needed.

    changes = 0
    for i in range(1, n-1):
        if heights[i] == heights[i-1] or heights[i] == heights[i+1]:
            changes += 1
            if heights[i-1] != heights[i+1]:
                heights[i] = heights[i-1] if heights[i] != heights[i-1] else heights[i+1]
            else:
                heights[i] = heights[i-1] + 1  # Changing height to ensure it's different from both neighbors

    return changes

