def max_path_sum(grid):
    """
    Finds the maximum sum of values along any path from the top-left to the bottom-right corner.

    :param grid: List of lists of integers, the grid data
    :return: Integer, the maximum sum
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])

    # iterate through grid and update the sum path
    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue  # starting point
            elif i == 0:
                grid[i][j] += grid[i][j-1]
            elif j == 0:
                grid[i][j] += grid[i-1][j]
            else:
                grid[i][j] += max(grid[i-1][j], grid[i][j-1])

    return grid[m-1][n-1]

