def longest_substring_with_one_replacement(s):
    """
    Returns the length of the longest substring containing at most one unique character
    after performing one replacement.
    """
    if not s:
        return 0

    def max_length_with_replacement(s, target_char):
        left = 0
        max_len = 0
        replacement_used = 0

        for right in range(len(s)):
            if s[right] != target_char:
                replacement_used += 1
            while replacement_used > 1:
                if s[left] != target_char:
                    replacement_used -= 1
                left += 1
            max_len = max(max_len, right - left + 1)

        return max_len

    max_len = 0
    for char in set(s):
        max_len = max(max_len, max_length_with_replacement(s, char))

    return max_len

