def match_queries(words, queries):
    def is_one_char_diff(word1, word2):
        """
        Helper function to determine if two words differ by exactly one character.
        """
        if len(word1) != len(word2):
            return False
        count_diff = 0
        for a, b in zip(word1, word2):
            if a != b:
                count_diff += 1
                if count_diff > 1:
                    return False
        return count_diff == 1

    result = []
    for query in queries:
        count = 0
        for word in words:
            if is_one_char_diff(word, query):
                count += 1
        result.append(count)

    return result

