def can_construct(s, word_list):
    from collections import Counter

    def backtrack(remaining_s, counter):
        if not remaining_s:
            return True
        for word in counter:
            if counter[word] > 0 and remaining_s.startswith(word):
                counter[word] -= 1
                if backtrack(remaining_s[len(word):], counter):
                    return True
                counter[word] += 1
        return False

    word_counter = Counter(word_list)
    return backtrack(s, word_counter)

