def length_of_longest_sorted_subsequence(arr):
    """
    Returns the length of the longest subsequence in arr that is sorted in ascending order.
    """
    if not arr:
        return 0

    n = len(arr)
    # Create an array to store the length of the longest increasing subsequence up to each element
    lis = [1] * n

    # Calculate the length of LIS for each element
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] >= arr[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    return max(lis)

