def fizz_buzz(n):
    """
    Returns a list of strings representing the numbers from 1 to n.
    But for multiples of three, returns "Fizz" instead of the number and for the multiples of five, returns "Buzz".
    For numbers which are multiples of both three and five, returns "FizzBuzz".
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

