from collections import Counter
from heapq import heappush, heappop
from typing import List

def rearrange_string_k_distance(s: str, k: int) -> str:
    if k == 0:
        return s

    counter = Counter(s)
    max_heap = []

    for char, freq in counter.items():
        heappush(max_heap, (-freq, char))

    wait_list = []
    result = []

    while max_heap:
        freq, char = heappop(max_heap)
        result.append(char)
        wait_list.append((char, freq + 1))

        if len(wait_list) < k:
            continue

        char, freq = wait_list.pop(0)
        if -freq > 0:
            heappush(max_heap, (freq, char))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return ""

