def remove_most_frequent_character(s):
    """
    Removes the most frequent character from the string. If there's a tie, removes any one of them.
    """
    if not s:
        return ""

    from collections import Counter
    char_count = Counter(s)
    most_frequent_char = max(char_count, key=char_count.get)

    return s.replace(most_frequent_char, '', 1)

