import math

def smallest_divisor(arr, threshold):
    def get_sum_of_divisions(divisor):
        return sum(math.ceil(x / divisor) for x in arr)

    low, high = 1, max(arr)
    while low < high:
        mid = (low + high) // 2
        if get_sum_of_divisions(mid) > threshold:
            low = mid + 1
        else:
            high = mid
    return low

def aggregate_requests(csv_log):
    """
    Aggregates the total number of requests for each unique IP address in the CSV formatted log.

    Args:
    csv_log (str): A string representing a CSV formatted mirror log file.

    Returns:
    dict: A dictionary with IP addresses as keys and their respective total request counts as values.
    """
    lines = csv_log.split('\n')
    request_counts = {}

    for line in lines:
        if line.strip():
            ip, count = line.split(',')
            count = int(count)
            if ip in request_counts:
                request_counts[ip] += count
            else:
                request_counts[ip] = count

    return request_counts

