from itertools import combinations

def longest_unique_string_length(words, k):
    """
    Returns the length of the longest string that can be formed by concatenating exactly k words
    from the list `words` such that no letter occurs more than once in the string.
    If it's not possible to form such a string, returns 0.
    """
    def is_unique(s):
        return len(s) == len(set(s))

    max_length = 0
    for combo in combinations(words, k):
        combined = ''.join(combo)
        if is_unique(combined):
            max_length = max(max_length, len(combined))

    return max_length

def majority_element(nums):
    """
    Returns the list of elements that appear more than n/3 times in the array.
    If no such element exists, returns an empty list.
    """
    if not nums:
        return []

    n = len(nums)
    count1, count2, candidate1, candidate2 = 0, 0, None, None

    for num in nums:
        if candidate1 is not None and num == candidate1:
            count1 += 1
        elif candidate2 is not None and num == candidate2:
            count2 += 1
        elif count1 == 0:
            candidate1, count1 = num, 1
        elif count2 == 0:
            candidate2, count2 = num, 1
        else:
            count1 -= 1
            count2 -= 1

    result = []
    for c in (candidate1, candidate2):
        if c is not None and nums.count(c) > n // 3:
            result.append(c)

    return result

