def max_distinct_substrings(s, k):
    """
    Returns the maximum number of substrings of length k with distinct characters
    that can be removed from the string s without overlap.
    """
    def are_all_chars_distinct(substring):
        return len(set(substring)) == len(substring)

    n = len(s)
    count = 0
    i = 0

    while i <= n - k:
        potential_substring = s[i:i+k]
        if are_all_chars_distinct(potential_substring):
            count += 1
            i += k
        else:
            i += 1

    return count

