def min_substrings(s):
    """
    Returns the minimum number of substrings that you can obtain such that each substring is either "abc" or "acb".
    """
    count = 0
    i = 0
    while i < len(s):
        if i + 2 < len(s) and (s[i:i+3] == "abc" or s[i:i+3] == "acb"):
            count += 1
            i += 3
        else:
