def find_missing_positive(arr):
    """
    Find the smallest positive integer missing from the array.
    """
    n = len(arr)

    # Step 1: Replace negative numbers and zeros with a number larger than the array size
    for i in range(n):
        if arr[i] <= 0:
            arr[i] = n + 1

    # Step 2: Mark the presence of numbers within the range 1 to n by using indices
    for i in range(n):
        num = abs(arr[i])
        if num <= n:
            arr[num - 1] = -abs(arr[num - 1])

    # Step 3: Find the first positive index
    for i in range(n):
        if arr[i] > 0:
            return i + 1

    return n + 1

