def largest_island(matrix):
    """
    Finds the size of the largest island in the matrix.

    Parameters:
    matrix (List[List[int]]): 2D list of integers representing heights of cells in the grid.

    Returns:
    int: Size of the largest island.
    """
    if not matrix:
        return 0

    m, n = len(matrix), len(matrix[0])
    visited = [[False] * n for _ in range(m)]
    max_island_size = 0

    def dfs(i, j, height):
        if i < 0 or i >= m or j < 0 or j >= n or visited[i][j] or matrix[i][j] != height:
            return 0
        visited[i][j] = True
        return 1 + dfs(i + 1, j, height) + dfs(i - 1, j, height) + dfs(i, j + 1, height) + dfs(i, j - 1, height)

    for i in range(m):
        for j in range(n):
            if not visited[i][j]:
                island_size = dfs(i, j, matrix[i][j])
                max_island_size = max(max_island_size, island_size)

    return max_island_size

