def max_area(heights):
    max_area = 0
    result = (0, 0)

    for i in range(len(heights)):
        for j in range(i + 1, len(heights)):
            area = (j - i) * min(heights[i], heights[j])
            if area > max_area:
                max_area = area
                result = (i, j)
            elif area == max_area:
                if i < result[0] or (i == result[0] and j < result[1]):
                    result = (i, j)
    return list(result)

