def count_triplets(nums):
    """
    Returns the total number of triplets (nums[i], nums[j], nums[k]) where
    0 <= i < j < k < len(nums) and nums[i] < nums[j] < nums[k].
    """
    count = 0
    n = len(nums)
    # Check all possible combinations of triplets
    for i in range(n):
        for j in range(i+1, n):
            for k in range(j+1, n):
                if nums[i] < nums[j] < nums[k]:
                    count += 1
    return count

