def longest_subsequence(arr, d):
    if not arr:
        return 0

    n = len(arr)
    dp = [1] * n  # dp[i] is the length of longest subsequence ending at index i

    for i in range(1, n):
        for j in range(i):
            if abs(arr[i] - arr[j]) <= d:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

