def can_transform(s, t, k):
    """
    Determines if t can be obtained from s by no more than k adjacent swaps.
    """
    if sorted(s) != sorted(t):
        return False

    # Count the minimum number of adjacent swaps needed to match t
    n = len(s)
    num_swaps = 0
    s_list = list(s)

    for i in range(n):
        if s_list[i] != t[i]:
            # Find the matching character in the remaining substring
            for j in range(i + 1, n):
                if s_list[j] == t[i]:
                    # Perform the adjacent swaps to move s_list[j] to position i
                    while j > i:
                        s_list[j], s_list[j - 1] = s_list[j - 1], s_list[j]
                        j -= 1
                        num_swaps += 1

    return num_swaps <= k

