def contains_difference(nums, k):
    """
    Returns true if there exist two distinct indices i and j in nums such that the absolute difference
    between nums[i] and nums[j] is exactly k, otherwise returns false.
    """
    num_set = set(nums)

    for num in nums:
        if (num + k) in num_set or (num - k) in num_set:
            return True

    return False

