def numIslands(grid: List[List[str]]) -> int:
    if not grid:
        return 0

    m, n = len(grid), len(grid[0])

    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] != '1':
            return
        grid[x][y] = '0'
        dfs(x-1, y)
        dfs(x+1, y)
        dfs(x, y-1)
        dfs(x, y+1)

    num_islands = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                num_islands += 1
                dfs(i, j)

    return num_islands

def remove_suspicious(ids):
    """
    Removes IDs that contain two consecutive identical characters.
    """
    def is_suspicious(id_):
        """Returns True if the ID contains two consecutive identical characters."""
        for i in range(len(id_) - 1):
            if id_[i] == id_[i + 1]:
                return True
        return False

    valid_ids = [id_ for id_ in ids if not is_suspicious(id_)]

    return valid_ids

