def max_area_of_block_with_k_ones(matrix, k):
    """
    Return the maximum area of a block containing exactly k 1's. If no such block exists, return 0.
    The input matrix is a 2D integer array where each cell contains either a 0 or a 1.
    """
    m, n = len(matrix), len(matrix[0])
    # Prepare auxiliary dp arrays to store consecutive 1s
    left = [[0] * n for _ in range(m)]
    up = [[0] * n for _ in range(m)]

    # Populate left and up arrays
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 1:
                left[i][j] = (left[i][j-1] + 1) if j > 0 else 1
                up[i][j] = (up[i-1][j] + 1) if i > 0 else 1

    max_area = 0

    # Explore all possible submatrices
    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 1:
                min_width = left[i][j]
                for row in range(i, -1, -1):
                    if matrix[row][j] == 0:
                        break
                    min_width = min(min_width, left[row][j])
                    height = i - row + 1
                    area = min_width * height
                    ones_count = sum(matrix[r][j-min_width+1:j+1].count(1) for r in range(row, row + height))
                    if ones_count == k:
                        max_area = max(max_area, area)

    return max_area

def min_operations(nums, x):
    target = sum(nums) - x
    if target == 0:
        return len(nums)

    left, current_sum = 0, 0
    max_len = -1

    for right in range(len(nums)):
        current_sum += nums[right]

        while current_sum > target and left <= right:
            current_sum -= nums[left]
            left += 1

        if current_sum == target:
            max_len = max(max_len, right - left + 1)

    return len(nums) - max_len if max_len != -1 else -1

