def longest_staircase_subsequence(heights):
    """
    Returns the length of the longest staircase subsequence found in heights.
    """
    if not heights:
        return 0

    n = len(heights)
    longest_length = 1
    current_length = 1

    for i in range(1, n):
        if heights[i] == heights[i - 1] + 1:
            current_length += 1
            longest_length = max(longest_length, current_length)
        else:
            current_length = 1

    return longest_length

