def max_width_below_threshold(height, h):
    """
    Returns the maximum width of a rectangular subarray in which each building has a height greater than or equal to h.
    """
    max_width = 0
    current_width = 0

    for ht in height:
        if ht >= h:
            current_width += 1
            max_width = max(max_width, current_width)
        else:
            current_width = 0

