def is_alien_sorted(words, order):
    """
    Determines if the given list of words is sorted lexicographically according to the provided alien order.

    :param words: List of strings representing the words.
    :param order: String representing the alphabetical order in an alien language.
    :return: True if the list of words is sorted according to the alien order, False otherwise.
    """
    order_index = {char: index for index, char in enumerate(order)}

    def compare_words(word1, word2):
        for c1, c2 in zip(word1, word2):
            if order_index[c1] < order_index[c2]:
                return True
            elif order_index[c1] > order_index[c2]:
                return False
        return len(word1) <= len(word2)

    for i in range(len(words) - 1):
        if not compare_words(words[i], words[i + 1]):
            return False
    return True

def minSubsetSumDifference(nums):
    """
    Given a list of integers, partition the list into two subsets such that the difference
    between the sums of the subsets is minimized, and return the minimum possible difference.
    """
    total_sum = sum(nums)
    n = len(nums)
    target = total_sum // 2

    dp = [False] * (target + 1)
    dp[0] = True

    for num in nums:
        for j in range(target, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]

    for i in range(target, -1, -1):
        if dp[i]:
            subset_sum1 = i
            break

    subset_sum2 = total_sum - subset_sum1
    return abs(subset_sum2 - subset_sum1)

