def count_groups(matrix):
    """
    Returns the number of distinct groups of connected empty cells in the given binary matrix.
    """
    rows = len(matrix)
    if rows == 0:
        return 0

    cols = len(matrix[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols or matrix[r][c] == 1 or visited[r][c]:
            return
        visited[r][c] = True
        direction_vectors = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dv in direction_vectors:
            dfs(r + dv[0], c + dv[1])

    count = 0
    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 0 and not visited[r][c]:
                dfs(r, c)
                count += 1

    return count

