def is_valid_distribution(books, n, k, max_pages):
    count_students = 1
    pages_assigned = 0

    for i in range(n):
        if pages_assigned + books[i] > max_pages:
            count_students += 1
            pages_assigned = books[i]
            if count_students > k:
                return False
        else:
            pages_assigned += books[i]

    return True

def find_minimum_pages(books, n, k):
    if n < k:
        return -1

    low, high = max(books), sum(books)
    result = high

    while low <= high:
        mid = (low + high) // 2
        if is_valid_distribution(books, n, k, mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1

    return result

