def min_operations_to_sort(nums, k):
    """
    Returns the minimum number of operations needed to sort the entire array nums
    in non-decreasing order by reversing any subarray of length k.
    """
    n = len(nums)
    sorted_nums = sorted(nums)

    # Edge case: if array is already sorted
    if nums == sorted_nums:
        return 0

    # Special cases
    if k == 1:
        return -1  # Impossible to sort (only individual elements can be swapped)
    if k == n:
        return 1 if nums != sorted_nums else 0  # One operation is sufficient if it sorts the array entirely

    # To keep track of contiguous blocks of increasing elements
    increasing_blocks = 1
    for i in range(1, n):
        if nums[i] < nums[i - 1]:
            increasing_blocks += 1

    return (increasing_blocks + (k - 1)) // k  # Number of operations needed

