def construct_string(s, k):
    """
    Constructs a new string of length k using characters from s in lexicographical order.

    Parameters:
        s (str): The input string consisting of only lowercase English letters.
        k (int): The target length of the new string.

    Returns:
        str: The constructed string of length k or an empty string if it's not possible.
    """
    if k > len(s):
        return ""

    result = []
    s = sorted(s)

    for i in range(len(s)):
        if len(result) < k:
            result.append(s[i])
        elif len(result) > k:
            result.pop()
        else:
            break

    return ''.join(result)

def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def minimal_edges_to_add(num_cities, edges, unreliable_edges):
    parent = []
    rank = []

    for node in range(num_cities):
        parent.append(node)
        rank.append(0)

    reliable_edges = [edge for edge in edges if edge not in unreliable_edges]

    for u, v in reliable_edges:
        uroot = find(parent, u)
        vroot = find(parent, v)
        if uroot != vroot:
            union(parent, rank, uroot, vroot)

    root_set = set(find(parent, i) for i in range(num_cities))
    return max(0, len(root_set) - 1)

def reachable_nodes_within_k_steps(n, edges, start, k):
    """
    Returns a list of nodes that are reachable from `start` within exactly `k` steps.
    The nodes in the returned list are sorted in ascending order.
    """
    from collections import defaultdict, deque

    # Create adjacency list representation of the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Use a queue to perform BFS
    queue = deque([(start, 0)])
    reachable_nodes = set()

    while queue:
        node, steps = queue.popleft()
        if steps == k:
            reachable_nodes.add(node)
        elif steps < k:
            for neighbor in graph[node]:
                queue.append((neighbor, steps + 1))

    return sorted(reachable_nodes)

