def count_subarrays(nums, target):
    """
    Returns the number of distinct continuous subarrays where
    the sum of the subarrays is less than the target.
    """
    n = len(nums)
    subarray_count = 0

    for start in range(n):
        current_sum = 0
        for end in range(start, n):
            current_sum += nums[end]
            if current_sum < target:
                subarray_count += 1
            else:
                break

    return subarray_count

