from typing import List

def pacificAtlantic(grid: List[List[int]]) -> List[List[int]]:
    if not grid or not grid[0]:
        return []

    m, n = len(grid), len(grid[0])
    pacific_reachable = [[False] * n for _ in range(m)]
    atlantic_reachable = [[False] * n for _ in range(m)]

    def dfs(x: int, y: int, reachable: List[List[bool]]):
        reachable[x][y] = True

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not reachable[nx][ny] and grid[nx][ny] >= grid[x][y]:
                dfs(nx, ny, reachable)

    for i in range(m):
        dfs(i, 0, pacific_reachable)
        dfs(i, n - 1, atlantic_reachable)

    for j in range(n):
        dfs(0, j, pacific_reachable)
        dfs(m - 1, j, atlantic_reachable)

    result = []
    for i in range(m):
        for j in range(n):
            if pacific_reachable[i][j] and atlantic_reachable[i][j]:
                result.append([i, j])

    return result

def min_days_to_complete_projects(days, k):
    """
    Returns the minimum number of days required to finish all the projects
    given the number of employees.
    """
    def can_complete_in_days(days, k, limit):
        employees_required = 1
        current_load = 0

        for day in days:
            if current_load + day > limit:
                employees_required += 1
                current_load = day
                if employees_required > k:
                    return False
            else:
                current_load += day
        return True

    if k >= len(days):
        return max(days)

    left, right = max(days), sum(days)
    while left < right:
        mid = (left + right) // 2
        if can_complete_in_days(days, k, mid):
            right = mid
        else:
            left = mid + 1

    return left

