def longest_increasing_path(matrix):
    if not matrix:
        return 0

    rows, cols = len(matrix), len(matrix[0])
    memo = [[-1 for _ in range(cols)] for _ in range(rows)]

    def dfs(row, col):
        if memo[row][col] != -1:
            return memo[row][col]

        moves = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        max_path = 1
        for move in moves:
            new_row, new_col = row + move[0], col + move[1]
            if 0 <= new_row < rows and 0 <= new_col < cols and matrix[new_row][new_col] > matrix[row][col]:
                max_path = max(max_path, 1 + dfs(new_row, new_col))

        memo[row][col] = max_path
        return memo[row][col]

    longest_path = 0
    for row in range(rows):
        for col in range(cols):
            longest_path = max(longest_path, dfs(row, col))

    return longest_path

