def rearrangeArray(arr):
    def has_equal_differences(arr):
        if len(arr) < 3:
            return False
        diffs = set()
        for i in range(1, len(arr)):
            diffs.add(arr[i] - arr[i - 1])
        return len(diffs) == 1

    arr.sort()

    # Try to create a non-arithmetic progression arrangement
    # by starting from ends, taking from the start one time, then from the end.
    n = len(arr)
    res = []

    left, right = 0, n - 1
    while left <= right:
        if left != right:
            res.append(arr[left])
            res.append(arr[right])
        else:
            res.append(arr[left])
        left += 1
        right -= 1

    if has_equal_differences(res):
        return "Not possible"
    return res

def min_swaps_to_palindrome(s):
    """
    Returns the minimum number of adjacent swaps needed to make the string a palindrome.
    If it is not possible to form a palindrome, returns -1.
    """
    def is_palindrome_possible(s):
        odd_count = sum(freq % 2 for freq in Counter(s).values())
        return odd_count <= 1

    def min_swaps_needed(l):
        swaps = 0
        for i in range(len(l)//2):
            left = i
            right = len(l) - left - 1
            while left < right:
                if l[left] == l[right]:
                    break
                else:
                    right -= 1
            if left == right:
                l[left], l[left + 1] = l[left + 1], l[left]
                swaps += 1
                continue
            for j in range(right, len(l) - left - 1):
                l[j], l[j + 1] = l[j + 1], l[j]
                swaps += 1
        return swaps

    from collections import Counter
    if not is_palindrome_possible(s):
        return -1

    s_list = list(s)
    return min_swaps_needed(s_list)

