def has_path(graph, start, end):
    """
    Determines if there is a path between the start and end nodes in the graph.

    :param graph: Dict, where keys are node integers and values are lists of adjacent nodes
    :param start: Int, starting node
    :param end: Int, ending node
    :return: Boolean, True if a path exists from start to end, else False
    """
    visited = set()

    def dfs(node):
        if node == end:
            return True

        visited.add(node)

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                if dfs(neighbor):
                    return True

        return False

    return dfs(start)

