def lexicographically_smallest_string(s: str, k: int) -> str:
    """
    Returns the lexicographically smallest string that can be obtained
    after exactly k transformations, where each transformation consists
    of choosing any substring and moving it to the beginning.
    """
    if k == 1:
        # Find the smallest rotation by trying all rotations
        smallest = s
        for i in range(len(s)):
            rotated = s[i:] + s[:i]
            if rotated < smallest:
                smallest = rotated
        return smallest
    else:
        # If k >= 2, we can use sorting to get the smallest string
        return ''.join(sorted(s))

def max_sum_after_single_swap(arr, k):
    n = len(arr)
    if n < k:
        return None  # Not enough elements to form a subarray of length k

    max_sum = -float('inf')
    current_sum = sum(arr[:k])

    for i in range(n - k + 1):
        current_sum = sum(arr[i:i + k])
        max_sum = max(max_sum, current_sum)

    for i in range(n):
        for j in range(i + 1, n):
            arr[i], arr[j] = arr[j], arr[i]

            for start in range(n - k + 1):
                current_sum = sum(arr[start:start + k])
                max_sum = max(max_sum, current_sum)

            arr[i], arr[j] = arr[j], arr[i]

    return max_sum

