def min_operations_to_unique_substrings(s):
    """
    Given a string s, return the minimum number of operations needed
    to make all substrings of s composed of distinct characters.
    """
    if not s:
        return 0

    # Create a frequency dictionary for the characters in the string
    char_freq = {}
    for char in s:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

    # The number of operations is the number of characters that appear more than once
    operations = 0
    for freq in char_freq.values():
        if freq > 1:
            operations += freq - 1

    return operations

