def min_island_removal(grid):
    if not grid or not grid[0]:
        return -1

    m, n = len(grid), len(grid[0])

    visited = [[False]*n for _ in range(m)]

    def dfs(x, y):
        stack = [(x, y)]
        island_cells = []
        while stack:
            cx, cy = stack.pop()
            if 0 <= cx < m and 0 <= cy < n and not visited[cx][cy] and grid[cx][cy] == 1:
                visited[cx][cy] = True
                island_cells.append((cx, cy))
                for nx, ny in [(cx - 1, cy), (cx + 1, cy), (cx, cy - 1), (cx, cy + 1)]:
                    stack.append((nx, ny))
        return island_cells

    islands = []
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                islands.append(dfs(i, j))

    if len(islands) <= 1:
        return -1

    min_cells = min(len(island) for island in islands)

    return min_cells

