def invalid_transactions(transactions):
    """
    Returns a list of invalid transactions.

    A transaction is considered invalid if:
    1. The amount exceeds $1000, or
    2. There are multiple transactions within 60 minutes from two different cities for the same person.
    """
    invalid = set()
    transactions_info = []

    for transaction in transactions:
        name, city, time, amount = transaction.split(',')
        time = int(time)
        amount = int(amount)
        transactions_info.append((name, city, time, amount, transaction))

    for i, (name1, city1, time1, amount1, transaction1) in enumerate(transactions_info):
        if amount1 > 1000:
            invalid.add(transaction1)

        for j, (name2, city2, time2, amount2, transaction2) in enumerate(transactions_info):
            if i != j and name1 == name2 and city1 != city2 and abs(time1 - time2) <= 60:
                invalid.add(transaction1)
                invalid.add(transaction2)

    return list(invalid)

def three_sum(nums, target):
    """
    Returns True if there exist three integers in nums whose sum equals target, otherwise False.
    """
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        left, right = i + 1, n - 1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False

