from collections import deque

def find_highest_peak(heights):
    """
    Finds the highest peak and its coordinates in the matrix.
    """
    max_height = float('-inf')
    peak_coords = []

    for i in range(len(heights)):
        for j in range(len(heights[0])):
            if heights[i][j] > max_height:
                max_height = heights[i][j]
                peak_coords = [(i, j)]
            elif heights[i][j] == max_height:
                peak_coords.append((i, j))

    return peak_coords, max_height

def bfs_to_water(heights, start_points, max_height):
    """
    Breadth-First Search (BFS) to find shortest path from the highest peak to the water.
    """
    m, n = len(heights), len(heights[0])
    queue = deque([(x, y, 0) for x, y in start_points])
    visited = set(start_points)

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        x, y, moves = queue.popleft()

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < m and 0 <= ny < n:
                if heights[nx][ny] == 0:
                    return moves + 1
                if heights[nx][ny] <= heights[x][y] and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append((nx, ny, moves + 1))

    return -1  # When there's no path to water

def min_moves_to_water(heights):
    if not heights or not heights[0]:
        return -1

    start_points, max_height = find_highest_peak(heights)

    return bfs_to_water(heights, start_points, max_height)

