def findAnagrams(s, p):
    """
    Returns a list of start indices of p's anagrams in s.
    """
    from collections import Counter

    p_count = Counter(p)
    s_count = Counter()
    result = []
    p_len = len(p)

    for i in range(len(s)):
        s_count[s[i]] += 1
        if i >= p_len:
            if s_count[s[i - p_len]] == 1:
                del s_count[s[i - p_len]]
            else:
                s_count[s[i - p_len]] -= 1
        if s_count == p_count:
            result.append(i - p_len + 1)

    return result

