def find_peak(arr: list) -> int:
    """
    Returns a peak element from the given list of unsorted integers.
    A peak element is defined as an element that is not smaller than its neighbors.
    """
    n = len(arr)
    if n == 1:
        return arr[0]

    if arr[0] >= arr[1]:
        return arr[0]

    if arr[n-1] >= arr[n-2]:
        return arr[n-1]

    for i in range(1, n-1):
        if arr[i] >= arr[i-1] and arr[i] >= arr[i+1]:
            return arr[i]

