def increment_nested_dictionary_values(nested_dict, increment_value):
    """
    Recursively increments all integer values in a nested dictionary by the given increment value.

    :param nested_dict: A dictionary which may contain nested dictionaries with integer values
    :param increment_value: The integer value to increment each integer in the dictionary by
    :return: A new dictionary with all integer values incremented by increment_value
    """
    new_dict = {}

    for key, value in nested_dict.items():
        if isinstance(value, dict):
            new_dict[key] = increment_nested_dictionary_values(value, increment_value)
        elif isinstance(value, int):
            new_dict[key] = value + increment_value
        else:
            new_dict[key] = value

    return new_dict

