from datetime import datetime, timedelta

def calculate_project_timeline(tasks, dependencies, start_date):
    task_end_dates = {}
    visited = set()
    stack = set()

    def get_end_date(task):
        if task in visited:
            return task_end_dates[task]
        if task in stack:
            raise Exception("Circular dependency detected")

        stack.add(task)
        if task not in dependencies or not dependencies[task]:
            end_date = datetime.strptime(start_date, '%Y-%m-%d') + timedelta(days=tasks[task])
        else:
            max_dep_end_date = max([get_end_date(dep) for dep in dependencies[task]])
            end_date = max_dep_end_date + timedelta(days=tasks[task])

        task_end_dates[task] = end_date
        visited.add(task)
        stack.remove(task)
        return end_date

    for task in tasks:
        get_end_date(task)

    formatted_task_end_dates = {task: date.strftime('%Y-%m-%d') for task, date in task_end_dates.items()}
    project_end_date = max(task_end_dates.values()).strftime('%Y-%m-%d')
    formatted_task_end_dates['Project End Date'] = project_end_date

    return formatted_task_end_dates

