def expand_pattern(s: str) -> str:
    def expand_range(start, end):
        return ''.join(chr(i) for i in range(ord(start), ord(end) + 1))

    i = 0
    result = []
    while i < len(s):
        if i + 2 < len(s) and s[i + 1] == '-' and s[i].isalnum() and s[i + 2].isalnum():
            start, end = s[i], s[i + 2]
            if ord(start) <= ord(end):
                result.append(expand_range(start, end))
                i += 3
            else:
                result.append(s[i:i+3])
                i += 3
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)

