def flatten_dict(d: dict, parent_key: str = '', sep: str = '.') -> dict:
    """
    Returns a flat dictionary where the keys represent the path to the value
    in the original nested dictionary, using dots to separate keys at each level.
    """
    items = {}
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.update(flatten_dict(v, new_key, sep=sep))
        else:
            items[new_key] = v
    return items

