def longest_warm_streak(temps: list, threshold: float) -> int:
    """
    Returns the length of the longest streak of consecutive days with temperatures above the given threshold.
    """
    longest_streak = 0
    current_streak = 0

    for temp in temps:
        if temp > threshold:
            current_streak += 1
            if current_streak > longest_streak:
                longest_streak = current_streak
        else:
            current_streak = 0

    return longest_streak

