from typing import List, Union

def fill_missing_values(data: List[List[Union[float, None]]]) -> List[List[float]]:
    if not data:
        return []

    rows, cols = len(data), len(data[0])
    means = [0] * cols
    count = [0] * cols

    # Calculate sums and counts for mean calculation
    for row in data:
        for col in range(cols):
            if row[col] is not None:
                means[col] += row[col]
                count[col] += 1

    # Calculate means
    for col in range(cols):
        if count[col] > 0:
            means[col] /= count[col]
        else:
            means[col] = None  # Use None if entire column is None

    # Replace None with corresponding mean
    result = []
    for row in data:
        new_row = row[:]
        for col in range(cols):
            if new_row[col] is None:
                if means[col] is not None:
                    new_row[col] = means[col]
        result.append(new_row)

    return result

def find_largest_unique_substring(s: str) -> int:
    char_index_map = {}
    start = 0
    max_length = 0

    for end in range(len(s)):
        if s[end] in char_index_map:
            start = max(start, char_index_map[s[end]] + 1)
        char_index_map[s[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

