from typing import List
from collections import deque

def longest_subarray_length(nums: List[int], k: int) -> int:
    if not nums:
        return 0

    max_deque, min_deque = deque(), deque()
    left = 0
    max_length = 0

    for right, num in enumerate(nums):
        while max_deque and num > max_deque[-1]:
            max_deque.pop()
        while min_deque and num < min_deque[-1]:
            min_deque.pop()
        max_deque.append(num)
        min_deque.append(num)

        while max_deque[0] - min_deque[0] > k:
            if max_deque[0] == nums[left]:
                max_deque.popleft()
            if min_deque[0] == nums[left]:
                min_deque.popleft()
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

