from typing import List

def count_islands(grid: List[List[str]]) -> int:
    if not grid:
        return 0

    def dfs(i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == '0':
            return
        grid[i][j] = '0'  # Mark as visited
        # Explore all 4 directions
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                count += 1
                dfs(i, j)

    return count

from typing import List, Tuple
from datetime import datetime

def merge_meetings(meetings: List[Tuple[str, str]]) -> List[Tuple[str, str]]:
    def convert_to_datetime(time_str):
        return datetime.strptime(time_str, "%H:%M")

    # Convert meeting times to datetime for easy comparison
    meetings_dt = [(convert_to_datetime(start), convert_to_datetime(end)) for start, end in meetings]

    # Sort meetings by start time
    meetings_dt.sort(key=lambda meeting: meeting[0])

    merged_meetings = []

    for current_start, current_end in meetings_dt:
        if not merged_meetings:
            merged_meetings.append((current_start, current_end))
        else:
            last_start, last_end = merged_meetings[-1]
            if current_start <= last_end:
                # If meetings overlap or touch, merge them
                merged_meetings[-1] = (last_start, max(last_end, current_end))
            else:
                # Otherwise, add the current meeting as a new interval
                merged_meetings.append((current_start, current_end))

    # Convert datetime objects back to "HH:MM" format
    merged_meetings_str = [(start.strftime("%H:%M"), end.strftime("%H:%M")) for start, end in merged_meetings]

    return merged_meetings_str

