from typing import List

def find_critical_connections(n: int, connections: List[List[int]]) -> List[List[int]]:
    def dfs(node, parent, discovery_time):
        visited[node] = True
        discover[node] = low[node] = discovery_time
        discovery_time += 1

        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if not visited[neighbor]:
                dfs(neighbor, node, discovery_time)
                low[node] = min(low[node], low[neighbor])
                if low[neighbor] > discover[node]:
                    critical_edges.append([node, neighbor])
            else:
                low[node] = min(low[node], discover[neighbor])

    graph = [[] for _ in range(n)]
    for u, v in connections:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    discover = [float('inf')] * n
    low = [float('inf')] * n
    critical_edges = []

    for i in range(n):
        if not visited[i]:
            dfs(i, -1, 0)

    return critical_edges

