def simplify_path(path: str) -> str:
    """
    Simplifies a given Unix-style absolute file path.

    Parameters:
    path (str): The absolute file path to simplify.

    Returns:
    str: The simplified canonical path.
    """
    stack = []

    # Split the path by slashes
    parts = path.split("/")

    for part in parts:
        if part == "..":
            if stack:
                stack.pop()  # Go back one directory if stack is not empty
        elif part == "." or part == "":
            continue  # Ignore current directory and empty segments
        else:
            stack.append(part)  # Add valid directory name to stack

    return "/" + "/".join(stack)

