def evaluate_expression(expression):
    """
    This function takes a string containing a mathematical expression involving basic arithmetic operations (+, -, *, /)
    and computes the result while respecting the precedence of the operators.
    """
    try:
        # Use Python's eval function to evaluate the expression.
        # It is assumed that the input is a valid arithmetic expression.
        result = eval(expression)
        return float(result)
    except (SyntaxError, ZeroDivisionError, TypeError, NameError):
        raise ValueError("Invalid input expression.")

