def optimize_delivery(item_weights: list, truck_capacity: int) -> int:
    # Sort the item weights in descending order
    item_weights.sort(reverse=True)

    trucks = []

    for weight in item_weights:
        placed = False
        for truck in trucks:
            if sum(truck) + weight <= truck_capacity:
                truck.append(weight)
                placed = True
                break

        if not placed:
            trucks.append([weight])

    return len(trucks)

