import math

def find_nearest_passenger(taxis, passengers):
    def euclidean_distance(p1, p2):
        return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

    results = []
    available_passengers = set(passengers)

    for taxi in taxis:
        if not available_passengers:
            break

        nearest_passenger = min(available_passengers, key=lambda passenger: euclidean_distance(taxi, passenger))
        results.append((taxi, nearest_passenger))
        available_passengers.remove(nearest_passenger)

    return results

