def categorize_numbers(nums: list) -> dict:
    """
    Categorizes numbers into positive, negative, and zero categories.

    :param nums: List of integers.
    :return: Dictionary with keys 'positive', 'negative', and 'zero', which
             correspond to lists of positive, negative, and zero numbers
             from the input list.
    """
    result = {
        'positive': [],
        'negative': [],
        'zero': []
    }

    for num in nums:
        if num > 0:
            result['positive'].append(num)
        elif num < 0:
            result['negative'].append(num)
        else:
            result['zero'].append(num)

    return result

