def is_valid_sequence(s):
    """
    Returns True if the sequence of parentheses, brackets, and braces is valid.
    """
    stack = []
    matching_parentheses = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses.keys():
            if stack == [] or matching_parentheses[char] != stack.pop():
                return False
        else:
            return False

    return stack == []

def calculate(operation: str, num1: int, num2: int):
    """
    Performs an arithmetic operation on two integers.

    Parameters:
        operation (str): The operation to perform ('add', 'subtract', 'multiply', 'divide').
        num1 (int): The first integer.
        num2 (int): The second integer.

    Returns:
        float or str: The result of the arithmetic operation, or an error message if division by zero.
    """
    if operation == 'add':
        return float(num1 + num2)
    elif operation == 'subtract':
        return float(num1 - num2)
    elif operation == 'multiply':
        return float(num1 * num2)
    elif operation == 'divide':
        if num2 == 0:
            return "Error: Division by zero"
        else:
            return float(num1 / num2)
    else:
        raise ValueError(f"Invalid operation '{operation}'")

