def find_combinations(numbers, target):
    def backtrack(start, target, path, res):
        if target == 0:
            res.append(path)
            return
        for i in range(start, len(numbers)):
            if numbers[i] > target:
                break
            if i > start and numbers[i] == numbers[i-1]:
                continue
            backtrack(i, target - numbers[i], path + [numbers[i]], res)

    numbers.sort()
    result = []
    backtrack(0, target, [], result)
    return result

def compress_string(data):
    """
    Compress a string using run-length encoding.
    """
    if not data:
        return ""

    compressed = []
    count = 1
    previous_char = data[0]

    for i in range(1, len(data)):
        if data[i] == previous_char:
            count += 1
        else:
            compressed.append(f"{previous_char}{count}")
            previous_char = data[i]
            count = 1

    # Append the last accumulated character and its count
    compressed.append(f"{previous_char}{count}")

    return ''.join(compressed)

