def unique_divisibles(numbers, divisor):
    """
    Returns the count of unique elements in the list that are divisible by the divisor.
    """
    if divisor == 0:
        raise ValueError("Divisor cannot be zero.")

    unique_numbers = set(numbers)
    divisible_numbers = [num for num in unique_numbers if num % divisor == 0]

    return len(divisible_numbers)

