def manage_inventory(inventory, actions, valid_items, max_quantity):
    for action in actions:
        action_type, item_name, quantity = action

        if action_type == 'add':
            if item_name in valid_items:
                if item_name not in inventory:
                    inventory[item_name] = 0
                inventory[item_name] = min(max_quantity, inventory[item_name] + quantity)
        elif action_type == 'remove':
            if item_name in inventory:
                inventory[item_name] = max(0, inventory[item_name] - quantity)
        elif action_type == 'summary':
            return inventory.copy()

    return inventory.copy()

