def word_ladder(beginWord, endWord, wordList):
    """
    Find the shortest transformation sequence from beginWord to endWord.

    Parameters:
    beginWord (str): The initial word.
    endWord (str): The target word.
    wordList (list[str]): List of valid transformation words.

    Returns:
    int: The length of the shortest transformation sequence, or 0 if no such sequence exists.
    """

    from collections import deque

    if endWord not in wordList:
        return 0

    L = len(beginWord)
    all_combo_dict = {}
    for word in wordList:
        for i in range(L):
            new_word = word[:i] + "*" + word[i + 1 :]
            if new_word not in all_combo_dict:
                all_combo_dict[new_word] = [word]
            else:
                all_combo_dict[new_word].append(word)

    queue = deque([(beginWord, 1)])
    visited = {beginWord: True}

    while queue:
        current_word, level = queue.popleft()
        for i in range(L):
            intermediate_word = current_word[:i] + "*" + current_word[i + 1 :]

            for word in all_combo_dict.get(intermediate_word, []):
                if word == endWord:
                    return level + 1
                if word not in visited:
                    visited[word] = True
                    queue.append((word, level + 1))
            all_combo_dict[intermediate_word] = []
    return 0

def simulate_file_system(operations):
    file_system = {}
    result = []

    for operation in operations:
        op_type = operation[0]
        if op_type == "create":
            file_name, content = operation[1], operation[2]
            file_system[file_name] = content
        elif op_type == "delete":
            file_name = operation[1]
            if file_name in file_system:
                del file_system[file_name]
        elif op_type == "read":
            file_name = operation[1]
            if file_name in file_system:
                result.append(file_system[file_name])

    return result

def solveNQueens(N):
    def isSafe(board, row, col):
        # Check for queen in the same column
        for i in range(row):
            if board[i] == col:
                return False
        # Check for queens on the left upper diagonal
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i] == j:
                return False
        # Check for queens on the right upper diagonal
        for i, j in zip(range(row, -1, -1), range(col, N)):
            if board[i] == j:
                return False
        return True

    def solveNQueensUtil(board, row):
        if row == N:
            result.append([(i, board[i]) for i in range(N)])
            return
        for col in range(N):
            if isSafe(board, row, col):
                board[row] = col
                solveNQueensUtil(board, row + 1)
                board[row] = -1  # backtrack

    result = []
    board = [-1] * N
    solveNQueensUtil(board, 0)
    return result

