def categorize_books(book_codes):
    def get_prefix(book_code):
        """ Extracts the prefix from a book code """
        prefix = []
        for char in book_code:
            if char.isdigit():
                break
            prefix.append(char)
        return ''.join(prefix)

    categorized_books = {}

    for code in book_codes:
        prefix = get_prefix(code)
        if prefix in categorized_books:
            categorized_books[prefix].append(code)
        else:
            categorized_books[prefix] = [code]

    return categorized_books

