def categorize_expenses(transactions):
    """
    Groups transactions by their category and calculates the total amount spent in each category.

    Parameters:
    transactions (list of tuples): Each tuple contains (amount, category, description)

    Returns:
    dict: A dictionary with categories as keys and total amounts as values.
    """
    categorized_expenses = {}
    for amount, category, description in transactions:
        if category in categorized_expenses:
            categorized_expenses[category] += amount
        else:
            categorized_expenses[category] = amount
    return categorized_expenses

