from typing import List, Dict

def organize_words(words: List[str]) -> Dict[int, List[str]]:
    """
    Organizes words into categories based on their lengths.

    Args:
    words (List[str]): List of words to be organized.

    Returns:
    Dict[int, List[str]]: Dictionary with keys as word lengths and values
                          as lists of words of that length, sorted alphabetically.
    """
    if not words:
        return {}

    length_dict = {}

    for word in words:
        word_length = len(word)
        if word_length not in length_dict:
            length_dict[word_length] = []
        length_dict[word_length].append(word)

    for length in length_dict:
        length_dict[length].sort()

    return length_dict

