from typing import List

def count_paths(grid: List[List[int]]) -> int:
    # If the start or end cell is an obstacle, no paths are possible
    if grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    rows, cols = len(grid), len(grid[0])
    dp = [[0] * cols for _ in range(rows)]

    # Initialize the starting point
    dp[0][0] = 1

    # Fill the dp table
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                dp[r][c] = 0  # No path through an obstacle
            else:
                if r > 0:
                    dp[r][c] += dp[r - 1][c]
                if c > 0:
                    dp[r][c] += dp[r][c - 1]

    return dp[rows - 1][cols - 1]

