    if not nums or k == 0:
        return 0

    n = len(nums)
    if k >= n // 2:
        return sum(max(nums[i] - nums[i - 1], 0) for i in range(1, n))

    dp = [[0] * n for _ in range(k + 1)]

    for i in range(1, k + 1):
        max_diff = -nums[0]
        for j in range(1, n):
            dp[i][j] = max(dp[i][j - 1], nums[j] + max_diff)
            max_diff = max(max_diff, dp[i - 1][j] - nums[j])

    return dp[k][n - 1]

