def can_partition(arr, k, mid):
    current_sum = 0
    required_parts = 1
    for num in arr:
        if current_sum + num > mid:
            required_parts += 1
            current_sum = num
            if required_parts > k:
                return False
        else:
            current_sum += num
    return True

def min_max_partition(arr, k):
    low, high = max(arr), sum(arr)

    while low < high:
        mid = (low + high) // 2
        if can_partition(arr, k, mid):
            high = mid
        else:
            low = mid + 1

    return low

