from typing import List

def longest_unique_path(grid: List[List[str]]) -> int:
    from collections import deque

    n = len(grid)
    m = len(grid[0])
    directions = [(-1,0), (1,0), (0,-1), (0,1)]

    def bfs(x, y):
        queue = deque([((x, y), set(grid[x][y]), 1)])
        max_len = 0

        while queue:
            (cur_x, cur_y), seen, length = queue.popleft()
            max_len = max(max_len, length)

            for dx, dy in directions:
                new_x, new_y = cur_x + dx, cur_y + dy

                if 0 <= new_x < n and 0 <= new_y < m and grid[new_x][new_y] not in seen:
                    queue.append(((new_x, new_y), seen | {grid[new_x][new_y]}, length+1))

        return max_len

    return bfs(0, 0)

def get_email_domains_count(emails):
    """
    Given a list of emails, returns a dictionary with the count of occurrences of each domain.

    :param emails: List of email addresses
    :type emails: List[str]
    :return: Dictionary with domains as keys and their counts as values
    :rtype: dict
    """
    domain_count = {}
    for email in emails:
        domain = email.split('@')[-1].lower()
        if domain in domain_count:
            domain_count[domain] += 1
        else:
            domain_count[domain] = 1
    return domain_count

