import random

def simulate_virus_spread(population_size, initial_infected, infection_rate, recovery_rate, time_steps, seed=None):
    if seed is not None:
        random.seed(seed)

    population = ['susceptible'] * (population_size - initial_infected)
    population.extend(['infected'] * initial_infected)

    results = []

    for _ in range(time_steps):
        new_population = population[:]

        for i in range(population_size):
            if population[i] == 'infected':
                if random.random() < recovery_rate:
                    new_population[i] = 'recovered'
            elif population[i] == 'susceptible':
                infected_contacts = sum(1 for j in range(population_size)
                                        if random.random() < infection_rate and population[j] == 'infected')
                if infected_contacts > 0:
                    new_population[i] = 'infected'

        population = new_population

        susceptible_count = population.count('susceptible')
        infected_count = population.count('infected')
        recovered_count = population.count('recovered')

        results.append((susceptible_count, infected_count, recovered_count))

    return results

