from typing import List, Dict, Any

def order_students(students: List[Dict[str, Any]]) -> Dict[str, List[Dict[str, Any]]]:
    groups = {
        "Group A": [],
        "Group B": [],
        "Group C": []
    }

    for student in students:
        if student["age"] < 13:
            groups["Group A"].append(student)
        elif student["age"] <= 18:
            groups["Group B"].append(student)
        else:
            groups["Group C"].append(student)

    for group in groups:
        groups[group].sort(key=lambda x: x["grade"], reverse=True)

    return groups

