from typing import List, Tuple, Union

def manage_inventory(operations: List[Tuple[str, Union[str, int]]]) -> List[Union[str, Tuple[str, int]]]:
    inventory = {}
    results = []

    for op in operations:
        if op[0] == "ADD":
            item, quantity = op[1], op[2]
            if item in inventory:
                inventory[item] += quantity
            else:
                inventory[item] = quantity

        elif op[0] == "REMOVE":
            item, quantity = op[1], op[2]
            if item in inventory:
                inventory[item] -= quantity
                if inventory[item] <= 0:
                    del inventory[item]

        elif op[0] == "FIND":
            item = op[1]
            if item in inventory:
                results.append(inventory[item])
            else:
                results.append("Item not found")

        elif op[0] == "DISPLAY":
            for item, quantity in sorted(inventory.items()): # sorting to ensure consistent order in display
                results.append((item, quantity))

    return results

from typing import List

def process_text_commands(commands: List[str]) -> List[bool]:
    text = []
    results = []

    for command in commands:
        if command.startswith('add '):
            _, char = command.split()
            text.append(char)
        elif command == 'remove' and text:
            text.pop()
        elif command == 'check':
            if text == text[::-1]:
                results.append(True)
            else:
                results.append(False)

    return results

