def find_connected_components(binary_image):
    def dfs(binary_image, visited, label, x, y):
        stack = [(x, y)]
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Directions for 4-way connectivity

        while stack:
            cx, cy = stack.pop()
            if visited[cx][cy] or binary_image[cx][cy] == 0:
                continue

            visited[cx][cy] = True
            output[cx][cy] = label

            for dx, dy in directions:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < len(binary_image) and 0 <= ny < len(binary_image[0]) and not visited[nx][ny]:
                    stack.append((nx, ny))

    visited = [[False for _ in range(len(binary_image[0]))] for _ in range(len(binary_image))]
    output = [[0 for _ in range(len(binary_image[0]))] for _ in range(len(binary_image))]
    label = 1 # start with label 1

    for i in range(len(binary_image)):
        for j in range(len(binary_image[0])):
            if binary_image[i][j] == 1 and not visited[i][j]:
                dfs(binary_image, visited, label, i, j)
                label += 1

    return output

