from typing import List, Tuple

def minimum_moves_to_touch_all(points: List[Tuple[int, int]]) -> int:
    def dist(p1, p2):
        return max(abs(p1[0] - p2[0]), abs(p1[1] - p2[1]))

    current_position = (0, 0)
    total_moves = 0

    for point in points:
        total_moves += dist(current_position, point)
        current_position = point

    return total_moves

