def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest increasing subsequence in the given list of integers.

    Args:
    arr (List[int]): The list of integers to process.

    Returns:
    int: The length of the longest increasing subsequence.
    """
    if not arr:
        return 0

    # Initialize an array to store the length of the longest increasing subsequence up to each element
    dp = [1] * len(arr)

    # Fill dp array
    for i in range(1, len(arr)):
        for j in range(0, i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest increasing subsequence is the maximum value in dp array
    return max(dp)

