def longest_common_subsequence(list1, list2):
    """
    Returns the longest common subsequence between list1 and list2.
    """
    m, n = len(list1), len(list2)
    # Create a 2D table to store lengths of longest common subsequence.
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if list1[i - 1] == list2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    # Reconstruct the longest common subsequence
    lcs = []
    i, j = m, n
    while i > 0 and j > 0:
        if list1[i - 1] == list2[j - 1]:
            lcs.append(list1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] > dp[i][j - 1]:
            i -= 1
        else:
            j -= 1

    # Reverse the lcs as we built it backwards
    lcs.reverse()
    return lcs

def sort_and_find_median(nums):
    """
    Sorts the list of integers in ascending order and returns the median value.

    :param nums: List of integers
    :return: Median value (integer or float)
    """

    # Implement a basic bubble sort
    n = len(nums)
    for i in range(n):
        for j in range(0, n-i-1):
            if nums[j] > nums[j+1]:
                nums[j], nums[j+1] = nums[j+1], nums[j]

    # Calculate the median
    if n % 2 == 1:
        return nums[n // 2]
    else:
        mid1 = nums[n // 2 - 1]
        mid2 = nums[n // 2]
        return (mid1 + mid2) / 2.0

