def are_brackets_balanced(s: str) -> bool:
    stack = []
    bracket_pairs = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_pairs.values():
            stack.append(char)
        elif char in bracket_pairs.keys():
            if stack == [] or bracket_pairs[char] != stack.pop():
                return False
    return stack == []

def find_max_avg_subarray(nums: list, k: int) -> int:
    if not nums or k > len(nums):
        return -1  # Edge case handling: return -1 if input is invalid

    max_sum = current_sum = sum(nums[:k])
    max_index = 0

    for i in range(k, len(nums)):
        current_sum += nums[i] - nums[i-k]
        if current_sum > max_sum:
            max_sum = current_sum
            max_index = i - k + 1

    return max_index

