def is_symmetric(matrix):
    """
    Checks whether the given matrix is symmetrical along its main diagonal.

    Parameters:
        matrix (list of list of int): The matrix to check.

    Returns:
        boolean: True if the matrix is symmetrical, False otherwise.

    Raises:
        ValueError: If the input matrix is not a square matrix.
    """
    if not matrix or not matrix[0]:
        raise ValueError("Input matrix is empty or invalid")

    size = len(matrix)

    # Check if the matrix is square
    for row in matrix:
        if len(row) != size:
            raise ValueError("Input matrix is not square")

    # Check for symmetry
    for i in range(size):
        for j in range(size):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

