def evaluate_expression(expression: str) -> int:
    """
    Evaluates a mathematical expression involving non-negative integers and the operators +, -, *, and /.
    The expression is a string where numbers and operators are separated by spaces.
    Returns the result as an integer, rounding down for division results.
    Returns None if division by zero occurs.
    """
    import math
    tokens = expression.split()
    stack = []
    i = 0

    while i < len(tokens):
        if tokens[i].isdigit():
            if stack and stack[-1] in '*/':
                operator = stack.pop()
                operand = stack.pop()
                if tokens[i] == '0' and operator == '/':
                    return None
                if operator == '*':
                    stack.append(int(operand) * int(tokens[i]))
                if operator == '/':
                    stack.append(math.floor(int(operand) / int(tokens[i])))
            else:
                stack.append(tokens[i])
        elif tokens[i] in '+-':
            stack.append(tokens[i])
        elif tokens[i] in '*/':
            stack.append(tokens[i])
        i += 1

    result = int(stack.pop(0))
    while stack:
        operator = stack.pop(0)
        operand = int(stack.pop(0))
        if operator == '+':
            result += operand
        if operator == '-':
            result -= operand

    return result

def decode_string(encoded):
    stack = []
    current_string = ""
    k = 0

    for char in encoded:
        if char.isdigit():
            k = k * 10 + int(char)
        elif char == '[':
            # Push the current_string and k to stack
            stack.append((current_string, k))
            # Reset current_string and k
            current_string = ""
            k = 0
        elif char == ']':
            last_string, last_k = stack.pop()
            current_string = last_string + last_k * current_string
        else:
            current_string += char

    return current_string

