def count_string_frequencies(strings):
    """
    Returns a dictionary with the frequency count of unique strings from the list.
    The function is case-insensitive and ignores leading and trailing whitespace.
    """
    frequency_dict = {}

    for string in strings:
        normalized_string = string.strip().lower()
        if normalized_string in frequency_dict:
            frequency_dict[normalized_string] += 1
        else:
            frequency_dict[normalized_string] = 1

    return frequency_dict

