def UpdateInventory(inventory: dict, transactions: list) -> dict:
    for product_id, transaction_type, quantity in transactions:
        if transaction_type == 'add':
            if product_id in inventory:
                inventory[product_id] += quantity
            else:
                inventory[product_id] = quantity
        elif transaction_type == 'remove':
            if product_id in inventory:
                inventory[product_id] = max(0, inventory[product_id] - quantity)
    return inventory

