def bank_operations(actions):
    """
    Simulates a banking system with deposits, withdrawals, and balance checks.

    Parameters:
    actions (list of tuples): A list of tuples where each tuple contains a string command and an integer value.

    Returns:
    list of int: A list of balances after each "balance" command.
    """
    balance = 0
    balance_history = []

    for action in actions:
        command, value = action

        if command == "deposit":
            balance += value
        elif command == "withdraw":
            if balance >= value:
                balance -= value
        elif command == "balance":
            balance_history.append(balance)

    return balance_history

