def Frequent_Sequences(s: str, seq_len: int) -> dict:
    if len(s) < seq_len:
        return {}

    seq_count = {}
    for i in range(len(s) - seq_len + 1):
        seq = s[i:i+seq_len]
        if seq in seq_count:
            seq_count[seq] += 1
        else:
            seq_count[seq] = 1

    max_count = max(seq_count.values(), default=0)

    return {seq: count for seq, count in seq_count.items() if count == max_count}

