def multi_set_operation(set1, set2, operation):
    """
    Perform union, intersection, and difference operations on two multi-sets.

    Args:
    - set1 (dict): The first multi-set.
    - set2 (dict): The second multi-set.
    - operation (str): The operation to perform ('union', 'intersection', 'difference').

    Returns:
    - result (dict): The resulting multi-set after performing the specified operation.
    """
    result = {}

    if operation == 'union':
        all_keys = set(set1.keys()).union(set(set2.keys()))
        for key in all_keys:
            result[key] = max(set1.get(key, 0), set2.get(key, 0))

    elif operation == 'intersection':
        common_keys = set(set1.keys()).intersection(set(set2.keys()))
        for key in common_keys:
            result[key] = min(set1.get(key, 0), set2.get(key, 0))

    elif operation == 'difference':
        for key in set1:
            diff = set1.get(key, 0) - set2.get(key, 0)
            if diff > 0:
                result[key] = diff

    return result

