def evaluate_postfix(expressions):
    """
    Evaluates a list of strings of postfix expressions.

    Params:
    expressions (list of str): List of postfix expressions as strings.

    Returns:
    list: Results of each postfix expression evaluation. None for invalid expressions.
    """
    def eval_expression(expression):
        stack = []
        tokens = expression.split()
        operators = {'+', '-', '*', '/'}

        for token in tokens:
            if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
                stack.append(int(token))
            elif token in operators:
                try:
                    b = stack.pop()
                    a = stack.pop()
                    if token == '+':
                        stack.append(a + b)
                    elif token == '-':
                        stack.append(a - b)
                    elif token == '*':
                        stack.append(a * b)
                    elif token == '/':
                        stack.append(int(a / b))  # Integer division
                except IndexError:
                    return None
            else:
                return None

        if len(stack) != 1:
            return None

        return stack.pop()

    return [eval_expression(expr) for expr in expressions]

