def is_valid_isbn(isbn: str) -> bool:
    """
    Determines if the given string is a valid ISBN-10.

    Args:
    isbn (str): A string representing the ISBN-10 to validate.

    Returns:
    bool: True if the ISBN-10 is valid, False otherwise.
    """
    if len(isbn) != 10:
        return False

    total = 0
    for i in range(9):
        if not isbn[i].isdigit():
            return False
        total += int(isbn[i]) * (i + 1)

    if isbn[9] == 'X':
        total += 10 * 10
    elif isbn[9].isdigit():
        total += int(isbn[9]) * 10
    else:
        return False

    return total % 11 == 0

