def rle_encode(input_str: str) -> list:
    if not input_str:
        return []

    encoded = []
    count = 1
    prev_char = input_str[0]

    for char in input_str[1:]:
        if char == prev_char:
            count += 1
        else:
            encoded.append((prev_char, count))
            prev_char = char
            count = 1
    encoded.append((prev_char, count))  # Add the last run

    return encoded

def rle_decode(encoded_list: list) -> str:
    if not encoded_list:
        return ""

    decoded = "".join(char * count for char, count in encoded_list)
    return decoded

