def task_func(s):
    """
    Return all possible permutations of the input string s.
    """
    # base cases
    if len(s) == 0:
        return [""]
    if len(s) == 1:
        return [s]

    # recursive case
    permutations = []
    for i, char in enumerate(s):
        remaining_chars = s[:i] + s[i+1:]
        for perm in task_func(remaining_chars):
            permutations.append(char + perm)

    return list(set(permutations))  # using set to remove duplicates

