import math

def euclidean_distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def task_func(points):
    if not points:
        return []

    path = []
    visited = {points[0]}
    current_point = points[0]

    while len(visited) < len(points):
        min_dist = float('inf')
        nearest_point = None

        for point in points:
            if point not in visited:
                dist = euclidean_distance(current_point, point)
                if dist < min_dist:
                    min_dist = dist
                    nearest_point = point

        path.append((current_point, nearest_point))
        visited.add(nearest_point)
        current_point = nearest_point

    return path

import random

def longest_heads_streak(num_flips):
    """
    Simulates flipping a coin num_flips times and returns the longest consecutive streak of heads.
    """
    flips = [random.choice(['H', 'T']) for _ in range(num_flips)]
    max_streak = 0
    current_streak = 0

    for flip in flips:
        if (flip == 'H'):
            current_streak += 1
            if current_streak > max_streak:
                max_streak = current_streak
        else:
            current_streak = 0

    return max_streak

def find_three_elements_sum(nums, target):
    """
    Finds three distinct elements in nums that sum up to the target value.
    :param nums: List[int] - List of integers
    :param target: int - Target sum value
    :return: Tuple[int, int, int] or None
    """
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == target:
                return (nums[i], nums[left], nums[right])
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    return None

