from typing import Tuple

def longest_consecutive_sequence(s: str) -> Tuple[str, int]:
    if not s:
        return ('', 0)

    max_char = s[0]
    max_length = 1
    current_char = s[0]
    current_length = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            current_length += 1
        else:
            if current_length > max_length:
                max_char = current_char
                max_length = current_length
            current_char = s[i]
            current_length = 1

    if current_length > max_length:
        max_char = current_char
        max_length = current_length

    return (max_char, max_length)

