def find_duplicates(nums):
    """
    Identifies and returns all duplicates from the list `nums`.
    Each duplicate appears only once in the result and in the order they were first encountered.
    """
    seen = set()
    duplicates = set()
    result = []

    for num in nums:
        if num in seen:
            if num not in duplicates:
                duplicates.add(num)
                result.append(num)
        else:
            seen.add(num)

    return result

