def merge_dictionaries(dict1, dict2):
    """
    Merges two dictionaries into a single dictionary.
    In case of conflicts:
    - If the value for a key is a list in both dictionaries, concatenate the lists.
    - If the value for a key is a dictionary in both dictionaries, merge the dictionaries recursively.
    - In any other case, the value from dict2 overrides the value from dict1.
    """
    result = dict1.copy()

    for key, value in dict2.items():
        if key in result:
            if isinstance(result[key], list) and isinstance(value, list):
                result[key] = result[key] + value
            elif isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = merge_dictionaries(result[key], value)
            else:
                result[key] = value
        else:
            result[key] = value

    return result

