from typing import List, Tuple
import heapq

def find_optimal_path(matrix: List[List[int]], start: Tuple[int, int], end: Tuple[int, int]) -> int:
    """
    Finds the optimal path from start to end in a given matrix using Dijkstra's algorithm.
    """
    def is_valid_position(matrix, position):
        rows, cols = len(matrix), len(matrix[0])
        x, y = position
        return 0 <= x < rows and 0 <= y < cols

    if not (is_valid_position(matrix, start) and is_valid_position(matrix, end)):
        print('Invalid input')
        return

    rows, cols = len(matrix), len(matrix[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    pq = [(matrix[start[0]][start[1]], start)]  # (cost, position)
    visited = set()
    costs = {start: matrix[start[0]][start[1]]}

    while pq:
        current_cost, (x, y) = heapq.heappop(pq)

        if (x, y) in visited:
            continue

        visited.add((x, y))

        if (x, y) == end:
            return current_cost

        for dx, dy in directions:
            next_x, next_y = x + dx, y + dy
            if is_valid_position(matrix, (next_x, next_y)) and (next_x, next_y) not in visited:
                next_cost = current_cost + matrix[next_x][next_y]
                if next_cost < costs.get((next_x, next_y), float('inf')):
                    costs[(next_x, next_y)] = next_cost
                    heapq.heappush(pq, (next_cost, (next_x, next_y)))

    return costs.get(end, float('inf'))

