def assign_letter_grades(students):
    """
    Assigns letter grades to students based on their numeric grades.

    Args:
    students (list): List of dictionaries, where each dictionary contains 'name' and 'grade'.

    Returns:
    list: List of dictionaries, where each dictionary contains 'name' and 'letter_grade'.
    """

    def get_letter_grade(grade):
        if 90 <= grade <= 100:
            return 'A'
        elif 80 <= grade <= 89:
            return 'B'
        elif 70 <= grade <= 79:
            return 'C'
        elif 60 <= grade <= 69:
            return 'D'
        elif 0 <= grade <= 59:
            return 'F'
        else:
            return 'Invalid grade'

    result = []
    for student in students:
        letter_grade = get_letter_grade(student['grade'])
        result.append({'name': student['name'], 'letter_grade': letter_grade})

    return result

