def find_common_elements(lists_of_arrays):
    """
    Returns the common elements among all sub-lists sorted in ascending order.
    """
    if not lists_of_arrays:
        return []

    common_elements = set(lists_of_arrays[0])

    for sublist in lists_of_arrays[1:]:
        common_elements &= set(sublist)

    return sorted(common_elements)

