def process_numbers(numbers, operation="sum", transformer=None):
    """
    Process a list of numbers by applying a given operation and an optional transformer function.

    Args:
        numbers (list): List of numbers.
        operation (str): The operation to perform. Possible values are "sum", "product", "average", "min", or "max".
        transformer (function, optional): A function to apply to each number before performing the operation.

    Returns:
        The result of the specified operation on the (transformed) list of numbers.
    """

    def apply_transformer(numbers, transformer):
        if transformer is None:
            return numbers
        return [transformer(num) for num in numbers]

    def perform_operation(numbers, operation):
        if operation == "sum":
            return sum(numbers)
        elif operation == "product":
            result = 1
            for num in numbers:
                result *= num
            return result
        elif operation == "average":
            return sum(numbers) / len(numbers)
        elif operation == "min":
            return min(numbers)
        elif operation == "max":
            return max(numbers)
        else:
            raise ValueError("Invalid operation given")

    transformed_numbers = apply_transformer(numbers, transformer)
    return perform_operation(transformed_numbers, operation)

