def frequency_of_characters(input_string):
    """
    Returns a dictionary with the frequency of each character in the input string.

    Arguments:
    input_string: The string for which character frequencies need to be determined.

    Returns:
    A dictionary with characters as keys and their respective frequencies as values.
    """
    frequency_dict = {}
    for char in input_string:
        if char in frequency_dict:
            frequency_dict[char] += 1
        else:
            frequency_dict[char] = 1
    return frequency_dict

