from typing import List

def max_pairwise_product(nums: List[int]) -> int:
    if len(nums) < 2:
        raise ValueError("List must contain at least two elements")

    # Initialize the two largest elements
    max1, max2 = float('-inf'), float('-inf')

    for num in nums:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

    return max1 * max2

