def generate_html(structure, indent=0):
    # A set of self-closing tags in HTML
    self_closing_tags = {'img', 'br', 'hr', 'meta', 'link', 'input'}

    def generate_html_recursively(structure, indent):
        html_string = ''
        indent_space = ' ' * indent

        for tag, content in structure.items():
            if tag in self_closing_tags:
                # If the tag is self-closing
                html_string += f"{indent_space}<{tag}>\n"
            else:
                # If content is a string, wrap it in the tag
                if isinstance(content, str):
                    html_string += f"{indent_space}<{tag}>{content}</{tag}>\n"
                # If content is a dict, recursively generate HTML for nested tags
                elif isinstance(content, dict):
                    html_string += f"{indent_space}<{tag}>\n"
                    html_string += generate_html_recursively(content, indent + 2)
                    html_string += f"{indent_space}</{tag}>\n"
        return html_string

    return generate_html_recursively(structure, indent)

