def longest_zigzag(sequence):
    if not sequence:
        return 0

    n = len(sequence)
    if n == 1:
        return 1

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if sequence[i] > sequence[j]:
                up[i] = max(up[i], down[j] + 1)
            elif sequence[i] < sequence[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(max(up), max(down))

