def validate_code(code: str) -> bool:
    lines = code.splitlines()

    for line in lines:
        # Check for trailing whitespace
        if line.rstrip() != line:
            return False

        # Check for line length
        if len(line) > 80:
            return False

        # Check for indentation (either 0 or multiple of 4 spaces)
        leading_spaces = len(line) - len(line.lstrip())
        if leading_spaces % 4 != 0:
            return False

        # Check function definitions
        if line.strip().startswith('def '):
            if not line.strip().startswith('def ') or line.strip().count(' ') != 1:
                return False

    return True

