from typing import List

def word_chain(words: List[str]) -> bool:
    def is_one_edit_away(w1: str, w2: str) -> bool:
        len1, len2 = len(w1), len(w2)
        if abs(len1 - len2) > 1:
            return False

        if len1 == len2:  # Check for one substitution
            diff_count = sum(1 for i in range(len1) if w1[i] != w2[i])
            return diff_count == 1

        if len1 > len2:  # Check for one deletion
            w1, w2 = w2, w1

        # Now len(w1) < len(w2), check for one insertion in w1
        i, j, diff_count = 0, 0, 0
        while i < len(w1) and j < len(w2):
            if w1[i] != w2[j]:
                if diff_count == 1:
                    return False
                diff_count += 1
                j += 1
            else:
                i += 1
                j += 1
        return True

    if not words or not all(isinstance(word, str) for word in words):
        return False

    for i in range(len(words) - 1):
        if not is_one_edit_away(words[i], words[i + 1]):
            return False

    return True

