def schedule_tasks(tasks):
    from collections import defaultdict, deque

    # Create a mapping from task name to task details
    task_map = {task['name']: task for task in tasks}

    # Create adjacency list and in-degree count for topological sort
    adjacency_list = defaultdict(list)
    in_degree = defaultdict(int)

    for task in tasks:
        for dependency in task['dependencies']:
            adjacency_list[dependency].append(task['name'])
            in_degree[task['name']] += 1

    # Initialize queue with all tasks having no dependencies (in-degree 0)
    queue = deque([task['name'] for task in tasks if in_degree[task['name']] == 0])

    # List to hold the topological order of tasks
    topological_order = []

    while queue:
        current_task = queue.popleft()
        topological_order.append(current_task)

        for dependent_task in adjacency_list[current_task]:
            in_degree[dependent_task] -= 1
            if in_degree[dependent_task] == 0:
                queue.append(dependent_task)

    # Check if all tasks are included in the topological order (i.e., no cycle)
    if len(topological_order) != len(tasks):
        raise ValueError("Cyclic dependency detected")

    return topological_order

