def find_longest_unique_substring(s: str) -> tuple:
    """
    Returns the longest substring without repeating characters and its length.
    """
    if not s:
        return ("", 0)

    char_pos = {}
    longest_start = 0
    longest_length = 0
    start = 0

    for i, char in enumerate(s):
        if char in char_pos and char_pos[char] >= start:
            start = char_pos[char] + 1

        char_pos[char] = i
        current_length = i - start + 1

        if current_length > longest_length:
            longest_length = current_length
            longest_start = start

    longest_unique_substring = s[longest_start:longest_start + longest_length]
    return (longest_unique_substring, longest_length)

