import random
from math import sqrt

def k_means(points, k, max_iters):
    def euclidean_distance(p1, p2):
        return sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

    def calculate_centroid(cluster):
        x_coords = [p[0] for p in cluster]
        y_coords = [p[1] for p in cluster]
        return (sum(x_coords) / len(x_coords), sum(y_coords) / len(y_coords))

    if k > len(points):
        raise ValueError("Number of clusters k cannot be greater than number of points")

    # Randomly initialize centroids
    centroids = random.sample(points, k)

    for _ in range(max_iters):
        clusters = [[] for _ in range(k)]

        for point in points:
            distances = [euclidean_distance(point, centroid) for centroid in centroids]
            closest_centroid_index = distances.index(min(distances))
            clusters[closest_centroid_index].append(point)

        new_centroids = [calculate_centroid(cluster) for cluster in clusters if cluster]

        if len(new_centroids) < k:
            # Some clusters might end up empty, assign empty clusters to new random points
            empty_cluster_count = k - len(new_centroids)
            new_centroids.extend(random.sample(points, empty_cluster_count))

        if new_centroids == centroids:
            break

        centroids = new_centroids

    return clusters

