def check_warehouse_inventory(current_stock, requested_items):
    insufficient_items = []

    # Check for non-positive requests and valid stock levels
    for item, requested_qty in requested_items.items():
        if requested_qty <= 0:
            continue # Ignore non-positive requested quantities
        if item not in current_stock or current_stock[item] < requested_qty:
            insufficient_items.append(item)

    if insufficient_items:
        return f"Cannot fulfill the request for: {', '.join(insufficient_items)}"

    # Deduct the requested items from stock
    for item, requested_qty in requested_items.items():
        if requested_qty > 0:
            current_stock[item] -= requested_qty

    return "All items are available and have been reserved."

