def print_letter_grades(grades):
    """
    Prints the corresponding letter grade for a list of integer grades.

    A: 90 and above
    B: 80-89
    C: 70-79
    D: 60-69
    F: below 60
    """
    if not grades:
        print("No grades available.")
        return

    for grade in grades:
        if grade >= 90:
            print("A")
        elif grade >= 80:
            print("B")
        elif grade >= 70:
            print("C")
        elif grade >= 60:
            print("D")
        else:
            print("F")

def construct_nested_dict(key_value_pairs):
    """
    Constructs a nested dictionary from the given key-value pairs.

    Parameters:
    key_value_pairs (list of tuples): Each tuple contains a key path string (with keys separated by dots)
                                      and the corresponding value.

    Returns:
    dict: The constructed nested dictionary.
    """
    result = {}
    for key_path, value in key_value_pairs:
        keys = key_path.split('.')
        d = result
        for key in keys[:-1]:
            if key not in d:
                d[key] = {}
            d = d[key]
        d[keys[-1]] = value
    return result

