import json
import sys

def sum_json_key(input_file, target_key):
    def extract_value(d, keys):
        for key in keys:
            d = d.get(key, 0)
            if not isinstance(d, (dict, int, float)):
                break
        return d if isinstance(d, (int, float)) else 0

    try:
        with open(input_file, 'r') as file:
            data = json.load(file)

        keys = target_key.split('.')
        total_sum = 0

        if isinstance(data, list):
            for item in data:
                total_sum += extract_value(item, keys)
        elif isinstance(data, dict):
            total_sum += extract_value(data, keys)

        return total_sum
    except (FileNotFoundError, json.JSONDecodeError) as e:
        print(f"Error: {e}")
        return 0

