def reverse_lookup(d, value):
    """
    Search for a specific value within a given dictionary and returns a list of keys (in string form)
    that have the specified value. Handles nested dictionaries.
    """
    def search_dict(sub_d, parent_key=''):
        result = []
        for k, v in sub_d.items():
            full_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                result.extend(search_dict(v, full_key))
            elif v == value:
                result.append(full_key)
        return result

    return search_dict(d)

