def find_primes_in_range(start, end):
    """
    Finds all prime numbers in the range [start, end] inclusive
    and calculates the sum of these prime numbers.

    Args:
    start (int): The start of the range.
    end (int): The end of the range.

    Returns:
    tuple: A tuple containing a list of primes in the range and the sum of those primes.
    """
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    primes = [num for num in range(start, end + 1) if is_prime(num)]
    return (primes, sum(primes))

