def digit_sum(n):
    return sum(int(digit) for digit in str(n))

def group_and_sort_by_digit_sum(int_list):
    digit_sum_dict = {}

    for number in int_list:
        d_sum = digit_sum(number)
        if d_sum not in digit_sum_dict:
            digit_sum_dict[d_sum] = []
        digit_sum_dict[d_sum].append(number)

    for key in digit_sum_dict:
        digit_sum_dict[key].sort()

    return digit_sum_dict

