from typing import List

def longest_increasing_subsequence(a: List[int]) -> int:
    if not a:
        return 0

    n = len(a)
    dp = [1] * n  # dp[i] is the length of LIS ending at index i

    for i in range(n):
        for j in range(i):
            if a[i] > a[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

