from typing import List

def find_anagrams(target: str, words: List[str]) -> List[str]:
    target_sorted = sorted(target.strip().lower())
    anagrams = []

    for word in words:
        if sorted(word.strip().lower()) == target_sorted:
            anagrams.append(word)

    return anagrams

