def step_cipher_encode(text: str, step: int) -> str:
    """
    Encodes a given text using a step cipher with the provided step value.

    Parameters:
    text (str): The input string to be encoded.
    step (int): The number of positions to shift each letter.

    Returns:
    str: The encoded string.
    """
    def shift_char(c, step, start, end):
        return chr((ord(c) - start + step) % 26 + start)

    encoded_chars = []
    for char in text:
        if 'a' <= char <= 'z':
            encoded_chars.append(shift_char(char, step, ord('a'), ord('z')))
        elif 'A' <= char <= 'Z':
            encoded_chars.append(shift_char(char, step, ord('A'), ord('Z')))
        else:
            encoded_chars.append(char)

    return ''.join(encoded_chars)

