def get_highest_scores(student_scores):
    """
    Takes in a list of tuples, each containing a student's name and score,
    and returns a dictionary with the student's names as keys and their highest
    scores as values.

    :param student_scores: List of tuples [(name, score), ...]
    :return: Dictionary {name: highest_score, ...}
    """
    highest_scores = {}
    for name, score in student_scores:
        if name not in highest_scores or score > highest_scores[name]:
            highest_scores[name] = score
    return highest_scores

