def invert_dict(input_dict):
    """
    This function takes a dictionary as input and returns a new dictionary with keys and values swapped.
    If a value in the original dictionary is not unique, the function stores all keys that correspond to
    the same value in a list.
    """
    inverted_dict = {}
    for key, value in input_dict.items():
        if value in inverted_dict:
            # If the value is already a list, append the new key to it.
            if isinstance(inverted_dict[value], list):
                inverted_dict[value].append(key)
            else:
                # Otherwise, create a list with the existing key and the new key.
                inverted_dict[value] = [inverted_dict[value], key]
        else:
            # For a unique value, simply invert the key-value pair.
            inverted_dict[value] = key
    return inverted_dict

