from typing import List, Dict, Union

def process_transactions(transactions: List[Dict[str, Union[str, int, float]]]) -> Dict[int, Dict[str, float]]:
    summary = {}

    for transaction in transactions:
        account_id = transaction['account_id']
        trans_type = transaction['type']
        amount = transaction['amount']

        if account_id not in summary:
            summary[account_id] = {'balance': 0.0, 'total_credit': 0.0, 'total_debit': 0.0}

        if trans_type == 'credit':
            summary[account_id]['balance'] += amount
            summary[account_id]['total_credit'] += amount
        elif trans_type == 'debit':
            summary[account_id]['balance'] -= amount
            summary[account_id]['total_debit'] += amount

    return summary

