def inventory_system(actions):
    """
    Manages stock levels of various items based on "add" and "purchase" actions.

    Parameters:
    actions (list of tuples): A list of tuples where each tuple consists of an action ("add" or "purchase") and an item.
    """
    inventory = {}

    for action, item in actions:
        if action == "add":
            if item in inventory:
                inventory[item] += 1
            else:
                inventory[item] = 1
        elif action == "purchase":
            if item in inventory and inventory[item] > 0:
                inventory[item] -= 1
                print("Purchase successful")
            else:
                print("Item out of stock")

from typing import List, Dict, Union, Tuple

def calculate_flights_delay(airlines_data: List[Dict[str, Union[str, int]]], delay_threshold: int) -> Tuple[str, int]:
    airline_delays = {}

    for flight in airlines_data:
        airline = flight['airline']
        delay = flight['delay']

        if delay > delay_threshold:
            if airline in airline_delays:
                airline_delays[airline] += 1
            else:
                airline_delays[airline] = 1

    max_delays = 0
    max_airline = None

    for airline, delays in airline_delays.items():
        if delays > max_delays:
            max_delays = delays
            max_airline = airline

    return (max_airline, max_delays)

