def word_frequency(sentence):
    """
    Returns a dictionary with the word frequency count of each word in the sentence,
    ignoring case sensitivity. Punctuation attached to words is treated as part of the word.

    :param sentence: A string containing multiple words separated by spaces.
    :return: A dictionary with words as keys and their frequencies as values.
    """
    words = sentence.lower().split()
    frequency = {}

    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    return frequency

