def partition_list(nums):
    """
    Partitions a list of integers into two subsets such that the absolute difference of their sums is minimized.
    """
    total_sum = sum(nums)
    n = len(nums)

    # Create a dp array to store achievable subset sums
    dp = [[False] * (total_sum // 2 + 1) for _ in range(n+1)]
    dp[0][0] = True

    for i in range(1, n+1):
        for j in range(total_sum // 2 + 1):
            if nums[i-1] <= j:
                dp[i][j] = dp[i-1][j] or dp[i-1][j-nums[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    # Find the subset with the largest possible sum <= total_sum // 2
    max_sum_half = 0
    for j in range(total_sum // 2 + 1):
        if dp[n][j]:
            max_sum_half = j

    subset1 = []
    subset2 = nums[:]

    # Backtracking to find the subset1 based on dp table
    w = max_sum_half
    for i in range(n, 0, -1):
        if dp[i][w] and not dp[i-1][w]:
            subset1.append(nums[i-1])
            subset2.remove(nums[i-1])
            w -= nums[i-1]

    return (subset1, subset2)

def compress_ranges(numbers):
    """
    Compress a sorted list of integers into range-based representation.

    Parameters:
    numbers (list): A sorted list of integers.

    Returns:
    list: A list of strings with compressed range-based representation.
    """
    if not numbers:
        return []

    compressed = []
    start = numbers[0]
    end = numbers[0]

    for i in range(1, len(numbers)):
        if numbers[i] == end + 1:
            end = numbers[i]
        else:
            if end - start >= 2:
                compressed.append(f"{start}-{end}")
            else:
                compressed.extend(map(str, range(start, end + 1)))
            start = numbers[i]
            end = numbers[i]

    if end - start >= 2:
        compressed.append(f"{start}-{end}")
    else:
        compressed.extend(map(str, range(start, end + 1)))

    return compressed

