def is_symmetric(matrix):
    """
    Checks whether the given square matrix is symmetric.

    Parameters:
    matrix (list of list of int): 2D list representing a square matrix.

    Returns:
    bool: True if the matrix is symmetric, False otherwise.
    """
    n = len(matrix)
    if n == 0:
        return True
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False
    return True

def iterative_factorial(n):
    """
    Returns the factorial of the given positive integer `n` using an iterative approach.
    """
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    result = 1
    for i in range(1, n + 1):
        result *= i
    return result

