def shift_down(arr: list, start: int, end: int) -> None:
    root = start
    while True:
        child = 2 * root + 1
        if child > end:
            break
        if child + 1 <= end and arr[child] < arr[child + 1]:
            child += 1
        if arr[root] < arr[child]:
            arr[root], arr[child] = arr[child], arr[root]
            root = child
        else:
            break

def heapify(arr: list) -> None:
    count = len(arr)
    start = (count - 2) // 2  # the index of the last non-leaf node

    while start >= 0:
        shift_down(arr, start, count - 1)
        start -= 1

from typing import List, Tuple
from collections import deque, defaultdict

def calculate_degrees_of_separation(friendships: List[Tuple[str, str]], person1: str, person2: str) -> int:
    if person1 == person2:
        return 0

    graph = defaultdict(list)

    for friend1, friend2 in friendships:
        graph[friend1].append(friend2)
        graph[friend2].append(friend1)

    visited = set()
    queue = deque([(person1, 0)])

    while queue:
        current_person, degree = queue.popleft()

        if current_person == person2:
            return degree

        if current_person not in visited:
            visited.add(current_person)
            for neighbour in graph[current_person]:
                if neighbour not in visited:
                    queue.append((neighbour, degree + 1))

    return -1

