def zigzag_conversion(s, numRows):
    if numRows == 1 or numRows >= len(s):
        return s

    # Create an array of strings for all numRows
    zigzag = ['' for _ in range(numRows)]
    current_row = 0
    going_down = False

    # Iterate over the string adding characters to the appropriate rows
    for char in s:
        zigzag[current_row] += char
        if current_row == 0 or current_row == numRows - 1:
            going_down = not going_down
        current_row += 1 if going_down else -1

    # Join all rows to get the final string
    return ''.join(zigzag)

