def manageLibrary(library, operations):
    """
    Processes borrowing and returning operations on the library's collection.

    Parameters:
    library (dict): A dictionary where the keys are book titles and values are the number of available copies.
    operations (list of tuples): A list of tuples, each containing an operation ('borrow' or 'return') and a book title.

    Returns:
    dict: The updated library dictionary after processing all operations.
    """
    for operation, title in operations:
        if operation == 'borrow':
            if library.get(title, 0) > 0:
                library[title] -= 1
        elif operation == 'return':
            if title in library:
                library[title] += 1
            else:
                library[title] = 1
    return library

