def find_longest_subarray(arr: list) -> int:
    """
    Finds the length of the longest contiguous subarray with an equal number of 0s and 1s.

    :param arr: List of 0s and 1s
    :return: Length of the longest subarray
    """
    # Dictionary to store the first occurrence of a particular count difference
    count_map = {0: -1}
    max_length = 0
    count = 0  # This will track the difference between the count of 1s and 0s

    for i, num in enumerate(arr):
        # Increment count for 1 and decrement for 0
        if num == 1:
            count += 1
        else:
            count -= 1

        if count in count_map:
            # If this count has been seen before, a subarray with equal 0s and 1s is found
            max_length = max(max_length, i - count_map[count])
        else:
            # Otherwise, store this count with its index
            count_map[count] = i

    return max_length

