from typing import List

def find_subarray_with_max_sum(arr: List[int], k: int) -> List[int]:
    max_sum = float('-inf')
    current_sum = 0
    start_index = 0

    for i in range(len(arr)):
        current_sum += arr[i]

        if i >= k - 1:
            if current_sum > max_sum:
                max_sum = current_sum
                start_index = i - k + 1

            current_sum -= arr[i - k + 1]

    return arr[start_index:start_index + k]

