def find_non_repeating(s: str) -> str:
    length = len(s)
    for i in range(length):
        is_repeating = False
        for j in range(length):
            if i != j and s[i] == s[j]:
                is_repeating = True
                break
        if not is_repeating:
            return s[i]
    return None

