def find_islands(grid):
    """
    Returns the number of islands in the given grid.
    """
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = set()

    def dfs(r, c):
        if (r < 0 or r >= rows or c < 0 or c >= cols or
            grid[r][c] == 0 or (r, c) in visited):
            return
        visited.add((r, c))
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        for dr, dc in directions:
            dfs(r + dr, c + dc)

    island_count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in visited:
                island_count += 1
                dfs(r, c)

    return island_count

def update_inventory(products, transactions):
    for product_name, quantity_sold in transactions:
        if product_name in products:
            if products[product_name] >= quantity_sold:
                products[product_name] -= quantity_sold
            else:
                print(f"Error: Not enough stock for {product_name}")
        else:
            print(f"Error: Product {product_name} does not exist in inventory")
    return products

