def count_votes(votes):
    """
    Counts the votes for each candidate from a list of votes.

    Args:
    votes (List[str]): A list of strings where each string represents a vote for a candidate.

    Returns:
    dict: A dictionary where the keys are candidate names and the values are their corresponding vote counts.
    """
    vote_count = {}
    for vote in votes:
        if vote in vote_count:
            vote_count[vote] += 1
        else:
            vote_count[vote] = 1
    return vote_count

