def evaluate_postfix(expression):
    """
    Evaluates a postfix (Reverse Polish Notation) expression and returns the result.
    Handles addition (+), subtraction (-), multiplication (*), and division (/).
    Raises ValueError for invalid input and ZeroDivisionError for division by zero.
    """
    if not expression:
        raise ValueError("The input string is empty.")

    stack = []
    operators = {"+", "-", "*", "/"}

    tokens = expression.split()
    for token in tokens:
        if token.lstrip('-').replace('.', '', 1).isdigit():  # Check if the token is a number
            stack.append(float(token))
        elif token in operators:
            if len(stack) < 2:
                raise ValueError(f"Invalid expression: insufficient operands for operator '{token}'.")

            b = stack.pop()
            a = stack.pop()

            if token == "+":
                stack.append(a + b)
            elif token == "-":
                stack.append(a - b)
            elif token == "*":
                stack.append(a * b)
            elif token == "/":
                if b == 0:
                    raise ZeroDivisionError("Division by zero encountered.")
                stack.append(a / b)
        else:
            raise ValueError(f"Invalid character or operator: '{token}'.")

    if len(stack) != 1:
        raise ValueError("Invalid expression: remaining operands without operators.")

    return stack.pop()

