def validate_isbn13(isbn: str) -> bool:
    """
    Validate if the given ISBN-13 number is valid.
    :param isbn: A string representing the ISBN-13 number.
    :return: True if the ISBN is valid, False otherwise.
    """
    if len(isbn) != 13 or not isbn.isdigit():
        return False

    sum = 0
    for i in range(12):
        digit = int(isbn[i])
        if i % 2 == 0:
            sum += digit * 1
        else:
            sum += digit * 3

    check_digit = (10 - (sum % 10)) % 10
    return check_digit == int(isbn[12])

