def longest_contiguous_subarray(arr: list) -> list:
    if not arr:
        return []

    max_length = 1
    current_length = 1
    max_subarray_start = 0
    current_start = 0

    for i in range(1, len(arr)):
        if arr[i] == arr[i - 1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                max_subarray_start = current_start
            current_length = 1
            current_start = i

    if current_length > max_length:
        max_length = current_length
        max_subarray_start = current_start

    return arr[max_subarray_start:max_subarray_start + max_length]

