def validate_brackets(s):
    """
    This function checks if the sequence of brackets in the given string is valid.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            return False  # in case there are any other characters which should not be the case as per the constraints
    return stack == []

import random

def number_guessing_game(lower, upper, attempts):
    target = random.randint(lower, upper)
    print(f"Guess a number between {lower} and {upper}. You have {attempts} attempts.")

    while attempts > 0:
        try:
            guess = int(input("Enter your guess: "))

            if guess < lower or guess > upper:
                print(f"Please enter a number within the range {lower}-{upper}.")
                continue

            if guess == target:
                print("Congratulations! You guessed the number correctly.")
                return True
            elif guess < target:
                print("Your guess is too low.")
            else:
                print("Your guess is too high.")

            attempts -= 1
            print(f"You have {attempts} attempts remaining.")

        except ValueError:
            print("Invalid input. Please enter an integer.")

    print(f"Sorry, you've run out of attempts. The number was {target}.")
    return False

from typing import List

def generatePossibleWords(digits: str) -> List[str]:
    """
    Given an input string of digits, returns all possible letter combinations
    based on a traditional phone keypad.
    """
    if not digits:
        return []

    digit_to_char = {
        '2': 'abc', '3': 'def', '4': 'ghi', '5': 'jkl',
        '6': 'mno', '7': 'pqrs', '8': 'tuv', '9': 'wxyz'
    }

    def backtrack(index: int, path: str):
        if index == len(digits):
            combinations.append(path)
            return

        possible_chars = digit_to_char[digits[index]]
        for char in possible_chars:
            backtrack(index + 1, path + char)

    combinations = []
    backtrack(0, "")
    return combinations

