def manage_inventory(inventory, operations):
    """
    Manage the inventory by performing a list of operations.

    Args:
    - inventory (dict): The initial inventory dictionary.
    - operations (list): A list of operations to perform.

    Returns:
    - dict: The updated inventory.
    """
    for operation in operations:
        op_type, item, details = operation
        if op_type == 'add':
            if item in inventory:
                inventory[item]['price'] = details['price']
                inventory[item]['quantity'] += details['quantity']
            else:
                inventory[item] = details
        elif op_type == 'update':
            if item in inventory:
                inventory[item]['quantity'] += details['quantity']
        elif op_type == 'remove':
            if item in inventory:
                del inventory[item]
    return inventory

