def quicksort(arr):
    if not isinstance(arr, list):
        raise ValueError("Input should be a list")
    if any(not isinstance(x, int) for x in arr):
        raise ValueError("All elements in the list should be integers")

    comparisons = [0]
    sorted_list = _quicksort(arr, comparisons)
    return sorted_list, comparisons[0]

def _quicksort(arr, comparisons):
    if len(arr) <= 1:
        return arr

    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]

    comparisons[0] += (len(arr) - 1)  # all comparisons in this call

    return _quicksort(left, comparisons) + middle + _quicksort(right, comparisons)

def generate_primes(n: int) -> list:
    """
    Returns a list of the first n prime numbers using the Sieve of Eratosthenes algorithm.
    """
    if n == 0:
        return []

    primes = []
    candidate = 2
    while len(primes) < n:
        is_prime = True
        for prime in primes:
            if prime * prime > candidate:
                break
            if candidate % prime == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1

    return primes

