def format_list(items):
    """
    Formats a given list of items into a readable sentence.

    Parameters:
    items (list of str): A list of strings to format.

    Returns:
    str: A formatted string based on the length of the list.
    """
    if not items:
        return ""
    elif len(items) == 1:
        return items[0]
    elif len(items) == 2:
        return f"{items[0]} and {items[1]}"
    else:
        return ", ".join(items[:-1]) + ", and " + items[-1]

