def merge_and_sort_dicts(dicts, sort_key):
    """
    Merges and sorts a list of dictionaries based on a given key.

    Parameters:
    - dicts: List of dictionaries to be merged.
    - sort_key: The key name that will be used to sort the values in the merged dictionary.

    Returns:
    - A dictionary where keys are the unique keys from all dictionaries in the input list,
      and values are lists of values from the original dictionaries, sorted according to
      the values of `sort_key`.
    """
    # Initialize the merged dictionary
    merged_dict = {}

    # Merge dictionaries while concatenating values for same keys
    for dictionary in dicts:
        for key, value in dictionary.items():
            if key in merged_dict:
                merged_dict[key].append(value)
            else:
                merged_dict[key] = [value]

    # Sort the merged dictionary based on the sort_key values
    if sort_key in merged_dict:
        sort_order = merged_dict[sort_key]
        for key in merged_dict:
            merged_dict[key] = [value for _, value in sorted(zip(sort_order, merged_dict[key]))]

    return merged_dict

