from typing import List

def rotate_matrix(matrix: List[List[int]]) -> None:
    """
    Rotates an NxN matrix 90 degrees clockwise in place.
    """
    n = len(matrix)

    # Step 1: Transpose the matrix
    for i in range(n):
        for j in range(i, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Step 2: Reverse each row
    for i in range(n):
        matrix[i].reverse()

def latest_logs_by_level(log_entries):
    """
    Retrieves the latest log entry for each log level.

    :param log_entries: List of tuples, where each tuple consists of a timestamp and a log level.
    :return: Dictionary with log levels as keys and their latest log entry as values.
    """
    latest_logs = {}

    for timestamp, level in log_entries:
        if level not in latest_logs or timestamp > latest_logs[level][0]:
            latest_logs[level] = (timestamp, level)

    return latest_logs

