import heapq

def dijkstra_shortest_path(graph, start_node, end_node):
    num_nodes = len(graph)
    distances = [float('inf')] * num_nodes
    previous_nodes = [None] * num_nodes
    distances[start_node] = 0
    priority_queue = [(0, start_node)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in enumerate(graph[current_node]):
            if weight > 0:
                distance = current_distance + weight
                if distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous_nodes[neighbor] = current_node
                    heapq.heappush(priority_queue, (distance, neighbor))

    path = []
    node = end_node
    while node is not None:
        path.append(node)
        node = previous_nodes[node]
    path.reverse()

    if distances[end_node] == float('inf'):
        return [], float('inf')

    return path, distances[end_node]

def process_order(order: dict, catalog: dict) -> bool:
    # Check if the entire order can be fulfilled
    for item, quantity in order.items():
        if catalog.get(item, 0) < quantity:
            return False

    # Update the catalog since the order can be fully fulfilled
    for item, quantity in order.items():
        catalog[item] -= quantity

    return True

