def find_balanced_substring(s: str) -> int:
    max_length = 0
    balance_count = 0
    balance_index_map = {0: -1}

    for i, char in enumerate(s):
        if char == 'a':
            balance_count += 1
        elif char == 'b':
            balance_count -= 1

        if balance_count in balance_index_map:
            max_length = max(max_length, i - balance_index_map[balance_count])
        else:
            balance_index_map[balance_count] = i

    return max_length

