def count_prime_factors(n: int) -> int:
    """
    Returns the number of distinct prime factors of the given integer n.
    """
    if n <= 1:
        return 0

    prime_factors = set()
    divisor = 2

    while n > 1:
        if n % divisor == 0:
            prime_factors.add(divisor)
            while n % divisor == 0:
                n //= divisor
        divisor += 1

    return len(prime_factors)

