from typing import List, Tuple

def final_position(n: int, m: int, start: Tuple[int, int], moves: List[str]) -> Tuple[int, int]:
    row, col = start

    for move in moves:
        if move == "up":
            if row > 0:
                row -= 1
        elif move == "down":
            if row < n - 1:
                row += 1
        elif move == "left":
            if col > 0:
                col -= 1
        elif move == "right":
            if col < m - 1:
                col += 1

    return (row, col)

