import heapq

def shortest_path_dijkstra(map_data: dict, start: str, end: str) -> float:
    if start not in map_data or end not in map_data:
        return float('inf')

    if start == end:
        return 0

    # Initialize distances and priority queue
    distances = {point: float('inf') for point in map_data}
    distances[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_distance, current_point = heapq.heappop(priority_queue)

        if current_point == end:
            return current_distance

        if current_distance > distances[current_point]:
            continue

        for neighbor, weight in map_data[current_point]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return float('inf')

