def consolidate_inventory(list1, list2):
    """
    Merges two inventory lists into a single list, updating quantities and prices as needed.
    """
    inventory = {}

    # Process first list
    for item in list1:
        inventory[item['product_id']] = item

    # Process second list
    for item in list2:
        if item['product_id'] in inventory:
            # Update quantity and keep the larger price
            inventory[item['product_id']]['quantity'] += item['quantity']
            inventory[item['product_id']]['price'] = max(inventory[item['product_id']]['price'], item['price'])
        else:
            inventory[item['product_id']] = item

    # Convert dictionary back to list
    return list(inventory.values())

