def traffic_simulation(events):
    """
    Simulates a simple traffic signal system at an intersection.

    Args:
    events (list of str): A list of events to be processed.

    Returns:
    dict: A dictionary representing the final state of the intersection.
    """

    # Initial state
    state = {
        'NS': 'Red',
        'EW': 'Red',
    }

    for event in events:
        if event == 'NS_Green':
            state['NS'] = 'Green'
            state['EW'] = 'Red'
        elif event == 'NS_Yellow':
            state['NS'] = 'Yellow'
            state['EW'] = 'Red'
        elif event == 'NS_Red':
            state['NS'] = 'Red'
        elif event == 'EW_Green':
            state['EW'] = 'Green'
            state['NS'] = 'Red'
        elif event == 'EW_Yellow':
            state['EW'] = 'Yellow'
            state['NS'] = 'Red'
        elif event == 'EW_Red':
            state['EW'] = 'Red'

    return state

