def calculate_average_rating(products):
    """
    Calculate the average rating for each product in the list.

    :param products: List of dictionaries, each containing a product_id and a list of reviews.
    :return: Dictionary with product IDs as keys and average ratings as values.
    """
    average_ratings = {}

    for product in products:
        product_id = product.get("product_id")
        reviews = product.get("reviews", [])

        if reviews:
            average_rating = round(sum(reviews) / len(reviews), 2)
        else:
            average_rating = 0.0

        average_ratings[product_id] = average_rating

    return average_ratings

