def subset_sum_combinations(numbers, target_sum):
    def find_combinations(start, target, path, results):
        if target == 0:
            results.append(path)
            return
        for i in range(start, len(numbers)):
            if numbers[i] > target:
                break
            find_combinations(i + 1, target - numbers[i], path + [numbers[i]], results)

    if not isinstance(numbers, list) or not all(isinstance(num, int) for num in numbers):
        raise ValueError("The 'numbers' argument must be a list of integers.")
    if not isinstance(target_sum, int):
        raise ValueError("The 'target_sum' argument must be an integer.")

    numbers.sort()
    results = []
    find_combinations(0, target_sum, [], results)
    return results

