def extract_integer_ranges(numbers: list) -> list:
    if not numbers:
        return []

    ranges = []
    start = numbers[0]
    count = 1

    for i in range(1, len(numbers)):
        if numbers[i] == numbers[i-1] + 1:
            count += 1
        else:
            if count >= 3:
                ranges.append((start, numbers[i-1]))
            start = numbers[i]
            count = 1

    if count >= 3:
        ranges.append((start, numbers[-1]))

    return ranges

