def matrix_transform(matrix, command):
    if command == 'rotate':
        return [[matrix[j][i] for j in range(len(matrix)-1, -1, -1)] for i in range(len(matrix[0]))]
    elif command == 'row_sum':
        return [sum(row) for row in matrix]
    elif command == 'col_sum':
        return [sum(matrix[i][j] for i in range(len(matrix))) for j in range(len(matrix[0]))]
    elif command == 'transpose':
        return [[matrix[j][i] for j in range(len(matrix))] for i in range(len(matrix[0]))]
    elif command == 'flatten':
        return [item for row in matrix for item in row]
    else:
        raise ValueError("Invalid command")

