def optimal_cooking_schedule(dishes):
    from collections import defaultdict, deque

    # Create a dictionary to store the preparation times and dependencies
    prep_times = {dish['name']: dish['prep_time'] for dish in dishes}
    dependencies = {dish['name']: dish['dependencies'] for dish in dishes}

    # Create a graph to represent the dependencies
    graph = defaultdict(list)
    in_degree = defaultdict(int)

    # Build the graph and the in-degree dict
    for dish in dishes:
        for dependency in dish['dependencies']:
            graph[dependency].append(dish['name'])
            in_degree[dish['name']] += 1

    # Use a queue to perform topological sort
    queue = deque()
    for dish in prep_times:
        if in_degree[dish] == 0:
            queue.append((dish, 0))

    schedule = []
    start_times = {}

    while queue:
        dish, start_time = queue.popleft()
        start_times[dish] = start_time
        schedule.append((dish, start_time))

        end_time = start_time + prep_times[dish]

        for dependent in graph[dish]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                max_start_time = max(start_times[dep] + prep_times[dep] for dep in dependencies[dependent])
                queue.append((dependent, max_start_time))

    return schedule

from collections import Counter
import math

def knn_classifier(train_data, test_data, k):
    def euclidean_distance(point1, point2):
        return math.sqrt(sum((x - y) ** 2 for x, y in zip(point1, point2)))

    def get_neighbors(train_data, test_point, k):
        distances = []
        for features, label in train_data:
            distance = euclidean_distance(features, test_point)
            distances.append((distance, label))
        distances.sort(key=lambda x: x[0])
        return distances[:k]

    def get_majority_label(neighbors):
        labels = [label for _, label in neighbors]
        most_common = Counter(labels).most_common(1)
        return most_common[0][0]

    predicted_labels = []
    for test_point in test_data:
        neighbors = get_neighbors(train_data, test_point, k)
        majority_label = get_majority_label(neighbors)
        predicted_labels.append(majority_label)

    return predicted_labels

