def remove_consecutive_duplicates(s):
    """
    This function takes a string and removes consecutive duplicate characters while preserving the order of characters.
    """
    if not s:
        return ""

    result = [s[0]]  # Initialize result list with the first character

    for char in s[1:]:
        if char != result[-1]:
            result.append(char)

    return ''.join(result)

