def second_minimum(arr):
    """
    Returns the second minimum value in the array. If the array does not contain at least
    two distinct elements, return -1.
    """
    if len(arr) < 2:
        return -1

    first_min = float('inf')
    second_min = float('inf')

    for num in arr:
        if num < first_min:
            second_min = first_min
            first_min = num
        elif first_min < num < second_min:
            second_min = num

    return second_min if second_min < float('inf') else -1

