def second_largest(numbers):
    """
    Returns the second largest number in the given list of numbers.
    If the list has less than two unique elements, returns None.
    """
    if len(numbers) < 2:
        return None

    first, second = float('-inf'), float('-inf')

    for number in numbers:
        if number > first:
            second = first
            first = number
        elif first > number > second:
            second = number

    return second if second != float('-inf') else None

