def reverse_list_recursively(lst):
    """
    Reverses the order of elements in the list using recursion.

    Parameters:
    lst (list): The list to be reversed.

    Returns:
    list: The reversed list.
    """
    if len(lst) == 0:
        return []
    else:
        return [lst[-1]] + reverse_list_recursively(lst[:-1])

