from itertools import permutations

def generate_anagrams(s):
    """
    Returns all possible anagrams of the given string s.
    """
    if len(s) <= 1:
        return [s]

    perms = permutations(s)
    anagrams = [''.join(p) for p in perms]
    return sorted(anagrams)

