def find_min_with_stack(arr):
    """
    Returns the minimum element from the array using a stack.
    If the array is empty, returns -1.
    """
    if not arr:
        return -1

    stack = []
    stack.append(arr[0])

    for num in arr[1:]:
        if num < stack[-1]:
            stack.append(num)

    return stack[-1]

