def find_unsorted_subarray(nums):
    """
    Returns the length of the shortest subarray that, if sorted, results in the whole array being sorted.
    If the array is already sorted, returns 0.
    """
    n = len(nums)
    start, end = 0, -1
    min_val, max_val = float('inf'), float('-inf')

    # Traverse from left to right to find the end of the needed subarray
    for i in range(n):
        if nums[i] < max_val:
            end = i
        else:
            max_val = nums[i]

    # Traverse from right to left to find the start of the needed subarray
    for i in range(n-1, -1, -1):
        if nums[i] > min_val:
            start = i
        else:
            min_val = nums[i]

    return end - start + 1

