def count_islands(matrix):
    """
    Returns the number of islands in a given 2D boolean matrix.
    """
    if not matrix or not matrix[0]:
        return 0

    rows = len(matrix)
    cols = len(matrix[0])

    def dfs(matrix, x, y):
        if x < 0 or x >= rows or y < 0 or y >= cols or not matrix[x][y]:
            return
        matrix[x][y] = False # Mark the current cell as visited
        dfs(matrix, x + 1, y)
        dfs(matrix, x - 1, y)
        dfs(matrix, x, y + 1)
        dfs(matrix, x, y - 1)

    island_count = 0

    for i in range(rows):
        for j in range(cols):
            if matrix[i][j]:
                island_count += 1
                dfs(matrix, i, j)

    return island_count

