def sieve_of_eratosthenes(limit):
    """
    Generates prime numbers up to a given limit using the Sieve of Eratosthenes algorithm.

    :param limit: Integer, the upper limit to generate prime numbers
    :return: List of prime numbers up to and including the limit
    """
    if limit < 2:
        return []

    sieve = [True] * (limit + 1)
    sieve[0], sieve[1] = False, False  # 0 and 1 are not primes

    for start in range(2, int(limit**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, limit + 1, start):
                sieve[multiple] = False

    return [num for num, is_prime in enumerate(sieve) if is_prime]

