def collatz_steps(n):
    """
    Returns the number of steps it takes to reach 1 using the Collatz conjecture operations.
    """
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

