def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def next_prime(n):
    """
    Returns the smallest prime number greater than or equal to n.
    """
    if n <= 1:
        return 2
    prime = n
    while not is_prime(prime):
        prime += 1
    return prime

