def factorial(n, memo = {}):
    """
    Returns the factorial of a given number n using memoization.
    """
    if n in memo:
        return memo[n]
    if n <= 1:
        memo[n] = 1
    else:
        memo[n] = n * factorial(n - 1, memo)
    return memo[n]

