def next_palindrome(num):
    """
    Returns the next smallest palindrome greater than the given number.
    """
    num_str = str(num)
    length = len(num_str)
    next_pal = None

    # Helper function to check if a number is a palindrome
    def is_palindrome(s):
        return s == s[::-1]

    if is_palindrome(num_str) and int(num_str) > num:
        return int(num_str)

    while True:
        num += 1
        num_str = str(num)
        if is_palindrome(num_str):
            next_pal = num
            break

    return next_pal

