import xml.etree.ElementTree as ET

def parse_xml_to_dict(xml_string):
    """
    Parses an XML string and extracts the information into a dictionary.

    Args:
    xml_string (str): The XML data as a string.

    Returns:
    dict: The parsed XML data as a dictionary.
    """
    def parse_element(element):
        parsed_data = {}

        # Process child elements recursively
        for child in element:
            child_data = parse_element(child)
            if child.tag in parsed_data:
                if not isinstance(parsed_data[child.tag], list):
                    parsed_data[child.tag] = [parsed_data[child.tag]]
                parsed_data[child.tag].append(child_data)
            else:
                parsed_data[child.tag] = child_data

        # Add attributes
        if element.attrib:
            parsed_data.update(element.attrib)

        # Add text data
        if element.text and element.text.strip():
            parsed_data['text'] = element.text.strip()

        return parsed_data

    root = ET.fromstring(xml_string)
    return {root.tag: parse_element(root)}

