from math import factorial

def stirling_second_kind(n, k):
    """
    Returns the number of ways to distribute n distinct items into k distinct bins such that no bin is empty.
    """
    if n == k:
        return 1
    elif k == 0 or k > n:
        return 0
    else:
        return k * stirling_second_kind(n - 1, k) + stirling_second_kind(n - 1, k - 1)

def distribute_items(n, k):
    """
    Calculates the number of ways to distribute n distinct items into k distinct bins such that no bin is empty.
    """
    if n < k:
        return 0
    # Calculate Stirling number of the second kind
    stirling_number = stirling_second_kind(n, k)
    # Multiply by k! because we have to consider the permutations of the bins
    return stirling_number * factorial(k)

