def find_pair_with_zero_sum(arr):
    """
    This function finds a pair of indices in an array such that the sum
    of the elements at those indices is zero. If such a pair exists,
    it returns the indices in a tuple (i, j). If no such pair exists,
    it returns None.
    """
    index_map = {}
    for i, num in enumerate(arr):
        if -num in index_map:
            return (index_map[-num], i)
        index_map[num] = i
    return None

