def generate_primes(n):
    """
    Returns a list of all prime numbers from 1 to n.
    """
    if n < 2:
        return []

    primes = []
    for num in range(2, n + 1):
        is_prime = True
        for divisor in range(2, int(num ** 0.5) + 1):
            if num % divisor == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

def decrypt_caesar_cipher(encrypted_text, key):
    """
    Decrypts a message encrypted using a Caesar cipher with the given key.

    :param encrypted_text: The encrypted message string.
    :param key: The key used for the Caesar cipher.
    :return: The decrypted message string.
    """
    decrypted_text = []
    for char in encrypted_text:
        if char.isalpha():
            shift = 65 if char.isupper() else 97
            decrypted_char = chr((ord(char) - shift - key) % 26 + shift)
            decrypted_text.append(decrypted_char)
        else:
            decrypted_text.append(char)

    return ''.join(decrypted_text)

