def frequency_table(data):
    """
    Generates a frequency table from the given list of data values.

    Parameters:
    data (list): A list of data values

    Returns:
    dict: A dictionary where keys are unique data values and values are their frequencies
    """
    freq_table = {}
    for value in data:
        if value in freq_table:
            freq_table[value] += 1
        else:
            freq_table[value] = 1
    return freq_table

