def factorials_of_numbers(numbers):
    """
    Calculate the factorials of all numbers in the input list.

    :param numbers: List of integers
    :return: List of factorials corresponding to the input list
    """
    def factorial(num):
        if num == 0 or num == 1:
            return 1
        return num * factorial(num - 1)

    return [factorial(num) for num in numbers]

