def detect_cycle_in_directed_graph(graph):
    """
    Detects cycles in a directed graph.

    Parameters:
    graph (dict): A dictionary representing the adjacency list of the graph.

    Returns:
    bool: True if a cycle is detected, otherwise False.
    """
    def visit(node):
        if node in temp_mark:
            return True
        if node in perm_mark:
            return False
        temp_mark.add(node)
        for neighbour in graph.get(node, []):
            if visit(neighbour):
                return True
        temp_mark.remove(node)
        perm_mark.add(node)
        return False

    temp_mark = set()
    perm_mark = set()
    for node in graph:
        if visit(node):
            return True
    return False

