def prime_factors(n):
    """
    Returns a list of prime factors of the absolute value of n.
    """
    if n < 0:
        n = abs(n)
    factors = []
    div = 2
    while div * div <= n:
        while (n % div) == 0:
            factors.append(div)
            n //= div
        div += 1
    if n > 1:
        factors.append(n)
    return factors

