def is_valid_path(grid):
    """
    Determines if there is a valid path from the top-left to the bottom-right of a 2D grid.

    Args:
    grid (list of list of int): The 2D grid (0 for an empty cell, 1 for an obstacle).

    Returns:
    bool: True if a valid path exists, False otherwise.
    """
    if not grid or not grid[0]:
        return False

    rows, cols = len(grid), len(grid[0])

    def dfs(x, y):
        if x < 0 or y < 0 or x >= rows or y >= cols or grid[x][y] == 1:
            return False
        if x == rows - 1 and y == cols - 1:
            return True

        grid[x][y] = 1  # mark as visited

        # Explore neighboring cells
        if (dfs(x+1, y) or dfs(x-1, y) or dfs(x, y+1) or dfs(x, y-1)):
            return True

        grid[x][y] = 0  # unmark as visited
        return False

    return dfs(0, 0)

