def max_even_pairs(arr):
    """
    Returns the maximum number of even number pairs that can be formed from an array of integers.
    Only adjacent elements can be paired, and each pair is considered if both elements are even.
    """
    if len(arr) < 2:
        return 0

    even_pair_count = 0
    for i in range(len(arr) - 1):
        if arr[i] % 2 == 0 and arr[i + 1] % 2 == 0:
            even_pair_count += 1
    return even_pair_count

