def square_root_bisection(num, tolerance=1e-10):
    """
    Returns the square root of a given number using the bisection method.

    :param num: The number to find the square root of.
    :param tolerance: The tolerance for the approximation error.
    :return: The square root of the given number.
    """
    if num < 0:
        raise ValueError("Cannot compute the square root of a negative number.")

    if num == 0:
        return 0.0

    low, high = 0, max(1, num)
    guess = (low + high) / 2

    while abs(guess**2 - num) > tolerance:
        if guess**2 < num:
            low = guess
        else:
            high = guess
        guess = (low + high) / 2
    return guess

