def first_missing_positive(nums):
    """
    Returns the first missing positive integer from the array.
    """
    n = len(nums)

    # Step 1: Mark numbers which are out of range and negatives with a specific number (n + 1)
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            nums[i] = n + 1

    # Step 2: Use the index as a hash key and number sign as a presence detector
    for i in range(n):
        num = abs(nums[i])
        if num <= n:
            nums[num - 1] = -abs(nums[num - 1])

    # Step 3: Find the first cell which isn't negative (i.e., its index + 1 is missing in the array)
    for i in range(n):
        if nums[i] > 0:
            return i + 1

    # If no cell is found, then the missing number is n + 1
    return n + 1

