def factorial(n):
    """
    Returns the factorial of a given number n.
    If n is negative, returns -1.
    If n is 0, returns 1.
    For other numbers, returns the factorial of the number.
    """
    if n < 0:
        return -1
    elif n == 0:
        return 1
    else:
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

