def second_smallest(arr):
    """
    Returns the second smallest element in the given array.
    If array length is less than 2, returns None.
    """
    if len(arr) < 2:
        return None

    first = second = float('inf')

    for num in arr:
        if num < first:
            second = first
            first = num
        elif first < num < second:
            second = num

    if second == float('inf'):
        return None
    else:
        return second

