def fibonacci_sequence(n):
    """
    Generates a list containing the Fibonacci sequence up to n terms using memoization.
    """
    memo = {0: 0, 1: 1}

    def fib_memo(m):
        if m not in memo:
            memo[m] = fib_memo(m - 1) + fib_memo(m - 2)
        return memo[m]

    return [fib_memo(i) for i in range(n)]

