import math

def nth_root(number, n):
    """
    Calculates the Nth root of a number using Python's native `math` library.
    Returns a tuple with both the real and complex roots if necessary.

    Parameters:
    number (float): the number to find the Nth root of
    n (int): the root to calculate

    Returns:
    tuple: a tuple containing the real and complex roots
    """
    if n == 0:
        raise ValueError("n cannot be 0")

    if number >= 0:
        # Real root for non-negative numbers
        real_root = number ** (1 / n)
        return (real_root,)
    else:
        if n % 2 == 0:
            # Return complex roots for negative numbers and even n
            real_part = 0
            imaginary_part = abs(number) ** (1 / n)
            return (complex(real_part, imaginary_part), complex(real_part, -imaginary_part))
        else:
            # Real root for negative numbers and odd n
            real_root = -((-number) ** (1 / n))
            return (real_root,)

