def fibonacci(n):
    """
    Returns the first N Fibonacci numbers.
    """
    if n <= 0:
        return []

    fib_numbers = [0, 1]
    for i in range(2, n):
        fib_numbers.append(fib_numbers[-1] + fib_numbers[-2])

    return fib_numbers[:n]

