def find_max(arr):
    """
    Returns the maximum element in an array using a divide and conquer approach.
    """
    return find_max_recursive(arr, 0, len(arr) - 1)

def find_max_recursive(arr, low, high):
    # Base case: Only one element
    if low == high:
        return arr[low]

    # Find the middle point
    mid = (low + high) // 2

    # Recursively find the maximum element in both halves
    left_max = find_max_recursive(arr, low, mid)
    right_max = find_max_recursive(arr, mid + 1, high)

    # Return the maximum of both halves
    return max(left_max, right_max)

