def is_valid_heap(arr, min_heap=True):
    """
    Checks if the given array is a valid heap.

    Parameters:
    arr (list): List of elements to be checked
    min_heap (bool): True if checking for a min-heap, False if checking for a max-heap

    Returns:
    bool: True if the array represents a valid heap, False otherwise
    """
    def compare(parent, child):
        if min_heap:
            return parent <= child
        else:
            return parent >= child

    n = len(arr)

    for i in range((n // 2) - 1, -1, -1):
        if 2 * i + 1 < n and not compare(arr[i], arr[2 * i + 1]):
            return False
        if 2 * i + 2 < n and not compare(arr[i], arr[2 * i + 2]):
            return False

    return True

