def longest_palindrome(s):
    """
    Returns the longest palindrome that can be formed by inserting characters at the end of the string.
    """
    def is_palindrome(s):
        return s == s[::-1]

    if is_palindrome(s):
        return s

    n = len(s)
    for i in range(n):
        if is_palindrome(s[i:]):
            prefix = s[:i]
            return s + prefix[::-1]

    return s

