def find_odd_occurrence(nums):
    """
    Returns an integer that appears an odd number of times in the list nums.
    If multiple integers appear an odd number of times, return any one of them.
    If no integer appears an odd number of times, return -1.
    """
    frequency = {}

    for num in nums:
        frequency[num] = frequency.get(num, 0) + 1

    for num, count in frequency.items():
        if count % 2 != 0:
            return num

    return -1

