def calculate_total_price(subtotal, tax_rate):
    """
    Calculates the total price of an order including tax.

    :param subtotal: The subtotal of the order (pre-tax amount).
    :param tax_rate: The tax rate as a floating-point number (e.g., 0.07 for 7% tax).
    :return: The total price including tax.
    """
    if not (0 <= tax_rate <= 1):
        raise ValueError("The tax rate must be a floating-point number between 0 and 1.")
    return subtotal + (subtotal * tax_rate)

