def find_min_and_index(arr):
    """
    Returns the minimum value and the index position of that minimum value in the array.
    If there are multiple occurrences of the minimum value, returns the index of the first occurrence.

    :param arr: List[int], a list of integers
    :return: Tuple[int, int], the minimum value and the index of the first occurrence of that minimum value
    """
    if not arr:
        raise ValueError("Array must not be empty")

    min_value = arr[0]
    min_index = 0

    for index, value in enumerate(arr):
        if value < min_value:
            min_value = value
            min_index = index

    return (min_value, min_index)

