def sum_of_largest_and_smallest(nums):
    """
    Returns the sum of the largest and smallest numbers in the list.
    Raises ValueError if the list contains non-integer elements.
    If the list is empty, return 0.
    If the list contains only one element, return that element twice.
    """
    if not all(isinstance(num, int) for num in nums):
        raise ValueError("List contains non-integer elements")

    if not nums:
        return 0

    if len(nums) == 1:
        return nums[0] * 2

    return min(nums) + max(nums)

