def find_duplicates(arr):
    """
    Returns a list of duplicates in the given array.

    Parameters:
    arr (list): A list of integers.

    Returns:
    list: A list containing duplicates, empty if none.
    """
    seen = set()
    duplicates = set()

    for num in arr:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)

    return list(duplicates)

