def average(numbers):
    """
    Returns the average of a list of numbers, ignoring None values.
    """
    if not numbers:
        return None

    valid_numbers = [num for num in numbers if num is not None]

    if not valid_numbers:
        return None

    return sum(valid_numbers) / len(valid_numbers)

