def longest_subarray_with_sum_zero(arr):
    """
    Returns the length of the longest subarray with a sum of zero.
    If no such subarray exists, returns -1.
    """
    sum_map = {}
    max_len = 0
    curr_sum = 0

    for i in range(len(arr)):
        curr_sum += arr[i]

        if arr[i] == 0 and max_len == 0:
            max_len = 1

        if curr_sum == 0:
            max_len = i + 1

        if curr_sum in sum_map:
            max_len = max(max_len, i - sum_map[curr_sum])
        else:
            sum_map[curr_sum] = i

    return max_len if max_len != 0 else -1

