def has_repeated_pattern(s):
    """
    Checks whether the string s contains a pattern that repeats itself.
    """
    length = len(s)
    for i in range(1, length // 2 + 1):
        if length % i == 0:
            pattern = s[:i]
            repeated = pattern * (length // i)
            if repeated == s:
                return True
    return False

