def int_to_binary(n):
    """
    Returns the binary representation of an integer as a string.
    Handles both positive and negative integers.
    """
    if n == 0:
        return "0"
    elif n > 0:
        return bin(n)[2:]
    else:
        return "-" + bin(abs(n))[2:]

