def find_smallest_even_largest_odd(numbers):
    """
    Returns the smallest even number and the largest odd number in the list.
    If there is no even or odd number, returns None for that value.

    :param numbers: List of integers
    :return: Tuple (smallest_even, largest_odd)
    """
    smallest_even = None
    largest_odd = None

    for num in numbers:
        if num % 2 == 0:
            if smallest_even is None or num < smallest_even:
                smallest_even = num
        else:
            if largest_odd is None or num > largest_odd:
                largest_odd = num

    return smallest_even, largest_odd

