def most_frequent_char(s):
    """
    Returns the character that appears the most times in the string s. If there are multiple
    characters with the same highest frequency, returns the first one encountered.
    """
    if not s:
        return None

    freq_dict = {}
    for char in s:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1

    most_frequent = max(freq_dict, key=freq_dict.get)
    return most_frequent

