def is_prime(n):
    """
    Helper function that checks if a number is prime.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def factorial(n):
    """
    Helper function that calculates the factorial of a number.
    """
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

def prime_factorial(n):
    """
    Returns the factorial of a number if it is prime, otherwise
    returns 'Input is not a prime number'.
    """
    if is_prime(n):
        return factorial(n)
    else:
        return "Input is not a prime number"

