def longest_palindromic_string(string_list):
    """
    Returns the longest palindrome in the list. If no palindrome is found or list is empty, returns an empty string.
    """
    def is_palindrome(s):
        return s == s[::-1]

    longest_palindrome = ""
    for s in string_list:
        if is_palindrome(s) and len(s) > len(longest_palindrome):
            longest_palindrome = s

    return longest_palindrome

