def generate_primes(n):
    """
    Generates a list of prime numbers up to n (inclusive).

    Args:
    n (int): The upper limit up to which primes are generated.

    Returns:
    List[int]: A list of prime numbers up to n.
    """
    if n < 2:
        return []
    primes = []
    for num in range(2, n + 1):
        is_prime = True
        for divisor in range(2, int(num ** 0.5) + 1):
            if num % divisor == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(num)
    return primes

