def longest_increasing_substring(s):
    """
    Returns the length of the longest increasing substring in the given string s.
    """
    if not s:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(s)):
        if s[i] > s[i-1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
            current_length = 1

    return max(max_length, current_length)

