def smallest_subarray_sum_divisible_by_k(arr, k):
    """
    Returns the smallest subarray sum that is divisible by k. If no such subarray exists, return -1.
    """
    n = len(arr)
    min_length = float('inf')
    for start in range(n):
        sub_sum = 0
        for end in range(start, n):
            sub_sum += arr[end]
            if sub_sum % k == 0:
                min_length = min(min_length, end - start + 1)

    return min_length if min_length != float('inf') else -1

