def longest_palindrome_prefix(s):
    """
    Returns the length of the longest palindrome prefix of the string s.

    :param s: Input string
    :return: Length of the longest palindrome prefix
    """
    def is_palindrome(sub):
        return sub == sub[::-1]

    for i in range(len(s), 0, -1):
        if is_palindrome(s[:i]):
            return i
    return 0

