def capitalize_words(s):
    """
    Returns a new string where each word is capitalized and the first letter
    after any non-letter character is also capitalized.
    """
    result = []
    capitalize_next = True

    for char in s:
        if not char.isalpha():
            capitalize_next = True
            result.append(char)
        else:
            if capitalize_next:
                result.append(char.upper())
                capitalize_next = False
            else:
                result.append(char.lower())

    return ''.join(result)

