def replace_vowels(s):
    """
    Replaces every vowel in the string s with the next consonant in the alphabet.
    Handles both uppercase and lowercase vowels.
    """
    vowel_map = {
        'a': 'b', 'e': 'f', 'i': 'j', 'o': 'p', 'u': 'v',
        'A': 'B', 'E': 'F', 'I': 'J', 'O': 'P', 'U': 'V'
    }

    return ''.join(vowel_map[char] if char in vowel_map else char for char in s)

