def fibonacci(n):
    """
    Returns the nth Fibonacci number. Raises ValueError if n is negative or not an integer.
    """
    if not isinstance(n, int):
        raise ValueError("Input must be an integer.")
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

def to_pig_latin(text):
    """
    Converts a string of English text to Pig Latin.

    Parameters:
    text (str): The input string in English.

    Returns:
    str: The converted string in Pig Latin.
    """
    vowels = 'aeiou'
    words = text.split()
    pig_latin_words = []

    for word in words:
        first_letter = word[0].lower()
        if first_letter in vowels:
            pig_latin_word = word + 'way'
        else:
            for i, char in enumerate(word):
                if char.lower() in vowels:
                    pig_latin_word = word[i:] + word[:i] + 'ay'
                    break
            else:
                pig_latin_word = word + 'ay'

        if word[0].isupper():
            pig_latin_word = pig_latin_word.capitalize()

        pig_latin_words.append(pig_latin_word)

    return ' '.join(pig_latin_words)

