def intersect_sorted_lists(list1, list2):
    """
    Returns the intersection of two sorted lists.
    """
    intersection = []
    i, j = 0, 0
    while i < len(list1) and j < len(list2):
        if list1[i] < list2[j]:
            i += 1
        elif list1[i] > list2[j]:
            j += 1
        else:
            intersection.append(list1[i])
            i += 1
            j += 1
    return intersection

