def is_prime(n):
    """
    Returns True if n is a prime number, else False.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_of_primes(start, end):
    """
    Returns the sum of all prime numbers between start and end (inclusive).
    """
    total = 0
    for num in range(start, end + 1):
        if is_prime(num):
            total += num
    return total

