def char_frequency(s):
    """
    Returns the frequency of each alphabetic character in the string s,
    ignoring digits and special characters.
    """
    frequency = {}
    for char in s:
        if char.isalpha():
            char = char.lower()
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1
    return frequency

