def divisors(n):
    """
    Returns a sorted list of all positive integers that evenly divide n without leaving a remainder.
    The list includes 1 and n itself.
    """
    if n < 1:
        raise ValueError("Input must be a positive integer")

    return sorted([i for i in range(1, n + 1) if n % i == 0])

