def compare_lexicographically(str1, str2):
    """
    Compare two strings lexicographically.

    Capital letters are considered less than lowercase letters.

    Parameters:
    str1 (str): First string.
    str2 (str): Second string.

    Returns:
    int: -1 if str1 < str2, 1 if str1 > str2, 0 if str1 == str2.
    """
    for c1, c2 in zip(str1, str2):
        if c1 < c2:
            return -1
        elif c1 > c2:
            return 1

    # If all characters are the same in the shared length, the longer string is lexicographically greater.
    if len(str1) < len(str2):
        return -1
    elif len(str1) > len(str2):
        return 1
    else:
        return 0

