def median(numbers):
    """
    Returns the median of a list of numbers.
    """
    if not numbers:
        raise ValueError("The list is empty")

    sorted_numbers = sorted(numbers)
    n = len(sorted_numbers)

    if n % 2 == 1:
        return sorted_numbers[n // 2]
    else:
        mid1, mid2 = n // 2 - 1, n // 2
        return (sorted_numbers[mid1] + sorted_numbers[mid2]) / 2

