def character_count(s):
    """
    Returns a dictionary where keys are the unique characters in the string s
    and values are the counts of how many times each character appears in the string.

    :param s: The input string
    :type s: str
    :return: A dictionary with character counts
    :rtype: dict
    """
    result = {}
    for char in s:
        if char in result:
            result[char] += 1
        else:
            result[char] = 1
    return result

