def longest_string(lst):
    """
    Returns the string with the maximum length from the list.
    If there are multiple strings with the maximum length, returns the first one encountered.
    If the list is empty, returns None.
    """
    if not lst:
        return None

    longest = lst[0]
    for string in lst[1:]:
        if len(string) > len(longest):
            longest = string

    return longest

