def is_symmetric(matrix):
    """
    Check if the given matrix is symmetric.

    Args:
    matrix (list of list of int): 2D list of integers representing the matrix.

    Returns:
    bool: True if the matrix is symmetric, False otherwise.
    """
    n = len(matrix)

    # Check for square matrix
    for row in matrix:
        if len(row) != n:
            return False

    # Check symmetry
    for i in range(n):
        for j in range(n):
            if matrix[i][j] != matrix[j][i]:
                return False

    return True

