def majority_element(arr):
    """
    Returns the majority element in the array if it exists, otherwise returns -1.
    The majority element is an element that appears more than ⌊n / 2⌋ times.
    """
    count_dict = {}
    n = len(arr)

    for num in arr:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    for num, count in count_dict.items():
        if count > n // 2:
            return num

    return -1

