def reverse_string(s: str) -> str:
    """
    Returns the reverse of the input string s, ignoring non-alphabetical characters.
    If the input string is empty or contains only whitespace, it returns an empty string.
    """
    if not s.strip():
        return ""

    alphabets = [char for char in s if char.isalpha()]
    reversed_alphabets = reversed(alphabets)

    return ''.join(reversed_alphabets)

