def product_or_sum(lst):
    """
    Returns the product of all elements in the list if any element is even,
    and the sum of all elements if all elements are odd.

    Parameters:
    lst (list): A list of integers.

    Returns:
    int: The product if any element is even, otherwise the sum.
    """
    if any(x % 2 == 0 for x in lst):
        product = 1
        for num in lst:
            product *= num
        return product
    else:
        return sum(lst)

def compare_arrays(arr1, arr2):
    """
    Compares two arrays and returns a boolean indicating whether they are identical.
    The comparison should be case-insensitive if one array contains strings and the other does not.
    """

    def normalize(item):
        if isinstance(item, str):
            return item.lower()
        return item

    if len(arr1) != len(arr2):
        return False

    for i in range(len(arr1)):
        if normalize(arr1[i]) != normalize(arr2[i]):
