def max_subarray_sum_circular(arr):
    """
    Calculates the maximum sum of a subarray within a one-dimensional array
    of numbers which has been circularly wrapped around.
    """
    def kadane(nums):
        max_ending_here = max_so_far = nums[0]
        for x in nums[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)
        return max_so_far

    max_kadane = kadane(arr)
    max_wrap = sum(arr) + kadane([-x for x in arr])

    if max_wrap == 0:
        return max_kadane

    return max(max_kadane, max_wrap)

