def bellman_ford(graph, source):
    """
    Find the shortest path from the source to all vertices in the given graph.
    If a negative cycle exists, the function will return that a negative cycle exists.

    :param graph: List of tuples (u, v, w) representing edge from u to v with weight w
    :param source: The source vertex
    :return: A dictionary with shortest path distances from the source to each vertex
             or a statement that a negative cycle exists
    """
    # Step 1: Initialize distances from source to all other vertices as INFINITE
    distances = {vertex: float('inf') for vertex in {u for edge in graph for u in edge[:2]}}
    distances[source] = 0

    # Step 2: Relax all edges |V| - 1 times
    for _ in range(len(distances) - 1):
        for u, v, w in graph:
            if distances[u] != float('inf') and distances[u] + w < distances[v]:
                distances[v] = distances[u] + w

    # Step 3: Check for negative-weight cycles
    for u, v, w in graph:
        if distances[u] != float('inf') and distances[u] + w < distances[v]:
            return "A negative cycle exists"

    return distances

