def two_largest_numbers(nums):
    """
    Returns the two largest numbers in the list.
    If the list has less than two numbers, return an empty list.
    """
    if len(nums) < 2:
        return []
    first, second = float('-inf'), float('-inf')
    for num in nums:
        if num > first:
            second = first
            first = num
        elif num > second and num != first:
            second = num
    return [first, second]

