def count_duplicates(arr):
    """
    Returns a dictionary where the keys are the duplicate elements
    and the values are their frequencies.
    """
    freq = {}
    # Establish a frequency dictionary for all elements
    for elem in arr:
        if elem in freq:
            freq[elem] += 1
        else:
            freq[elem] = 1

    # Filter out elements that are not duplicates
    duplicates = {key: value for key, value in freq.items() if value > 1}

    return duplicates

