    """
    Returns the `n`th prime number using the Sieve of Eratosthenes algorithm.
    """
    if n < 1:
        return None  # Return None for non-positive inputs

    # Estimating the upper bound for the nth prime using the prime number approximation
    import math
    if n < 6:
        upper_bound = 15
    else:
        upper_bound = int(n * (math.log(n) + math.log(math.log(n))))

    sieve = [True] * (upper_bound + 1)
    p = 2

    while p * p <= upper_bound:
        if sieve[p]:
            for i in range(p * p, upper_bound + 1, p):
                sieve[i] = False
        p += 1

    primes = []
    for p in range(2, upper_bound + 1):
        if sieve[p]:
            primes.append(p)

    return primes[n-1] if n <= len(primes) else None

