def sum_even_odd(numbers):
    """
    Takes a list of numbers and returns a tuple (sum of even numbers, sum of odd numbers).
    """
    even_sum = 0
    odd_sum = 0
    for number in numbers:
        if number % 2 == 0:
            even_sum += number
        else:
            odd_sum += number
    return (even_sum, odd_sum)

