def fibonacci_recursive(n, memo={}):
    """
    Returns the n-th Fibonacci number using recursion with memoization.
    Also includes error handling for invalid input.
    """
    if n < 0:
        raise ValueError("Input cannot be negative.")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    if n in memo:
        return memo[n]

    memo[n] = fibonacci_recursive(n - 1, memo) + fibonacci_recursive(n - 2, memo)
    return memo[n]

def generate_fibonacci_sequence(n=10):
    """
    Returns a tuple with the first 'n' elements of the Fibonacci sequence.
    """
    return tuple(fibonacci_recursive(i) for i in range(n))

