def capitalize_consonants(s):
    """
    Returns the input string with all consonants capitalized.
    """
    vowels = 'aeiouAEIOU'
    result = []
    for char in s:
        if char.isalpha() and char not in vowels:
            result.append(char.upper())
        else:
            result.append(char)
    return ''.join(result)

