def sum_of_digits(n):
    """
    Returns the sum of each digit in the integer n using recursion.
    """
    n = abs(n)  # Handle negative numbers by taking absolute value
    if n == 0:
        return 0
    else:
        return n % 10 + sum_of_digits(n // 10)

