def convert_string_to_list(s):
    """
    Converts a string in the format "1a2b3c" into a list of strings ["1a", "2b", "3c"].
    """
    try:
        result = []
        if len(s) % 2 != 0:
            raise ValueError("Input string length should be even to form pairs.")
        for i in range(0, len(s), 2):
            result.append(s[i:i+2])
        return result
    except Exception as e:
        return str(e)

