def remainder_finder(n, d, r):
    """
    Returns a list of numbers from 1 to n that produce a remainder r when divided by d.
    """
    result = []
    for i in range(1, n+1):
        if i % d == r:
            result.append(i)
    return result

def sum_of_remainders(n, d, r):
    """
    Returns the sum of all integers from 1 to n that have a remainder of r when divided by d.
    """
    numbers_with_remainder_r = remainder_finder(n, d, r)
    return sum(numbers_with_remainder_r)

