def remove_duplicates(arr):
    """
    Returns a new array with all duplicates removed.
    """
    if len(arr) == 0:
        return []

    result = []

    for i in range(len(arr)):
        is_duplicate = False
        for j in range(i):
            if arr[i] == arr[j]:
                is_duplicate = True
                break
        if not is_duplicate:
            result.append(arr[i])

    return result

