def max_sum_of_two_elements(arr):
    """
    Returns the maximum sum of two elements in the array.
    If the array has less than two elements, returns None.
    """
    if len(arr) < 2:
        return None

    first_max = second_max = float('-inf')

    for num in arr:
        if num > first_max:
            second_max = first_max
            first_max = num
        elif num > second_max:
            second_max = num

    return first_max + second_max

