def is_palindrome_recursive(n):
    """
    Checks if a given integer is a palindrome using recursion.

    Parameters:
    n (int): The integer to check.

    Returns:
    bool: True if the integer is a palindrome, False otherwise.
    """

    def helper(s, start, end):
        # Base case for recursion: start index has passed end index
        if start >= end:
            return True
        # Check if characters at the start and end are the same
        if s[start] != s[end]:
            return False
        # Recursive call moving towards the center of the string
        return helper(s, start + 1, end - 1)

    # Convert number to string to check for palindrome properties
    s = str(n)
    return helper(s, 0, len(s) - 1)

