def print_sequence(start, end, direction):
    """
    Prints all the numbers in the sequence from start to end if direction is 'forward',
    or from end to start if direction is 'reverse'. Returns "Invalid direction" for other directions.
    """
    if direction == 'forward':
        return list(range(start, end + 1))
    elif direction == 'reverse':
        return list(range(end, start - 1, -1))
    else:
        return "Invalid direction"

def is_isomorphic(s, t):
    """
    Determines if two strings s and t are isomorphic.
    """
    if len(s) != len(t):
        return False

    map_st = {}
    map_ts = {}

    for char_s, char_t in zip(s, t):
        if (char_s in map_st and map_st[char_s] != char_t) or (char_t in map_ts and map_ts[char_t] != char_s):
            return False
        map_st[char_s] = char_t
        map_ts[char_t] = char_s

    return True

