def longest_subsequence(arr):
    def has_common_char(s1, s2):
        return bool(set(s1) & set(s2))

    def dfs(idx, current):
        nonlocal max_length, best_sequence
        if len(current) > max_length:
            max_length = len(current)
            best_sequence = sorted(current)
        for i in range(idx, len(arr)):
            if all(not has_common_char(arr[i], s) for s in current):
                current.append(arr[i])
                dfs(i + 1, current)
                current.pop()

    max_length = 0
    best_sequence = []
    dfs(0, [])
    return best_sequence

