def fibonacci(n):
    """
    Returns a list containing the first n Fibonacci numbers.
    """
    if n <= 0:
        return []
    if n == 1:
        return [0]

    fib_seq = [0, 1]
    for _ in range(2, n):
        fib_seq.append(fib_seq[-1] + fib_seq[-2])

    return fib_seq

