def are_anagrams(str1, str2):
    """
    Check if two strings are anagrams by comparing their frequency dictionaries.

    Parameters:
        str1 (str): The first string.
        str2 (str): The second string.

    Returns:
        bool: True if the strings are anagrams, otherwise False.
    """
    if len(str1) != len(str2):
        return False

    freq_dict1 = {}
    freq_dict2 = {}

    for char in str1:
        freq_dict1[char] = freq_dict1.get(char, 0) + 1

    for char in str2:
        freq_dict2[char] = freq_dict2.get(char, 0) + 1

    return freq_dict1 == freq_dict2

