def find_max_min(lst):
    """
    Returns the maximum and minimum elements in a list of integers.
    """
    if not lst:
        return None, None

    max_val = lst[0]
    min_val = lst[0]

    for num in lst:
        if num > max_val:
            max_val = num
        if num < min_val:
            min_val = num

    return max_val, min_val

