def get_value_from_dict(d, key):
    """
    Returns the value associated with the given key in the dictionary.
    If the key does not exist, returns None. Handles nested dictionaries.
    """
    if key in d:
        return d[key]

    for k, v in d.items():
        if isinstance(v, dict):
            result = get_value_from_dict(v, key)
            if result is not None:
                return result

    return None

