def arrange_by_frequency(s, fmap):
    """
    Arrange characters in the string `s` according to the frequency map `fmap`.
    """
    # Create a dictionary to hold lists of characters at each frequency
    freq_dict = {}

    # Populate freq_dict with characters from fmap
    for char, freq in fmap.items():
        if freq not in freq_dict:
            freq_dict[freq] = []
        freq_dict[freq].append(char)

    # Sort frequencies in descending order
    sorted_frequencies = sorted(freq_dict.keys(), reverse=True)

    # Build the resulting string
    res = []
    used_chars = set()

    for freq in sorted_frequencies:
        for char in freq_dict[freq]:
            res.append(char * freq)
            used_chars.add(char)

    # Append characters not present in fmap in their original order
    for char in s:
        if char not in used_chars:
            res.append(char)

    return ''.join(res)

