def word_frequency(sentence):
    """
    Returns the frequency of each word in the sentence.
    The words in the sentence can be separated by spaces or commas and case is ignored.
    """
    # Remove punctuation and convert to lower case
    sentence = sentence.replace(",", " ").lower()
    words = sentence.split()

    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1

    return frequency

