def fibonacci(n):
    """
    Returns a list containing the first n numbers of the Fibonacci sequence using recursion.
    """
    def fib_helper(a, b, n, sequence):
        if n == 0:
            return sequence
        return fib_helper(b, a + b, n - 1, sequence + [a])

    return fib_helper(0, 1, n, [])

