def sort_by_digit_sum(nums):
    """
    Sorts a list of non-negative integers based on the sum of their digits.

    Parameters:
    nums (List[int]): The list of non-negative integers to be sorted.

    Returns:
    List[int]: A new list with the numbers sorted based on the sum of their digits.
    """
    def digit_sum(n):
        return sum(int(digit) for digit in str(n))

    return sorted(nums, key=digit_sum)

