import string

def count_unique_characters(message):
    """
    Returns a tuple with the count of each unique character in the message.
    The function ignores case sensitivity and non-alphabetic characters.
    """
    message = message.lower()
    counter = {}
    for char in message:
        if char in string.ascii_lowercase:
            if char in counter:
                counter[char] += 1
            else:
                counter[char] = 1
    return tuple(sorted((char, count) for char, count in counter.items()))

