def factorial(n):
    """
    Returns the factorial of a given number n.
    """
    if n == 0 or n == 1:
        return 1
    result = 1
    for i in range(2, n+1):
        result *= i
    return result

def number_of_permutations(n):
    """
    Returns the number of permutations for a set of n distinct values.
    """
    return factorial(n)

