def longest_common_subsequence(str1, str2):
    """
    Returns the longest common sub-sequence (LCS) between two strings.
    """
    m, n = len(str1), len(str2)

    # Create a DP table to store lengths of longest common subsequence
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Build the DP table in bottom-up fashion
    for i in range(m):
        for j in range(n):
            if str1[i] == str2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    # Now, let's construct the LCS from the dp array
    lcs = []
    while m > 0 and n > 0:
        if dp[m][n] == dp[m-1][n]:
            m -= 1
        elif dp[m][n] == dp[m][n-1]:
            n -= 1
        else:
            lcs.append(str1[m-1])
            m -= 1
            n -= 1
    lcs.reverse()

    return ''.join(lcs)

