def remove_element(arr, element):
    """
    Removes all instances of `element` from `arr` by iterating through the array backwards.
    """
    i = len(arr) - 1
    while i >= 0:
        if arr[i] == element:
            arr.pop(i)
        i -= 1
    return arr

