def find_pair_with_sum(numbers, target):
    """
    Returns a tuple of two numbers from the list that sum up to the target.
    If no such pair exists, returns None.
    """
    seen = set()
    for number in numbers:
        complement = target - number
        if complement in seen:
            return (complement, number)
        seen.add(number)
    return None

