def min_deletions_to_sort(arr):
    """
    Returns the minimum number of deletions required to make the array sorted.
    """
    n = len(arr)
    if n <= 1:
        return 0

    # Find the length of the longest increasing subsequence
    lis = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # The minimum deletions required is the total elements minus the length of LIS
    length_of_lis = max(lis)
    return n - length_of_lis

