def is_balanced_parentheses(s):
    """
    Checks if a string contains a balanced number of parentheses.

    :param s: Input string to check
    :return: True if the parentheses are balanced, False otherwise
    """
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                return False

    return len(stack) == 0

