def is_palindrome(n):
    """
    Returns True if the integer n is a palindrome, otherwise returns False.
    """
    str_n = str(n)
    length = len(str_n)

    for i in range(length // 2):
        if str_n[i] != str_n[length - i - 1]:
            return False

    return True

