def find_min_max(arr):
    """
    Returns a tuple containing the minimum and maximum values in the array.
    """
    if not arr:
        raise ValueError("Array is empty")
    min_val = float('inf')
    max_val = float('-inf')
    for num in arr:
        if num < min_val:
            min_val = num
        if num > max_val:
            max_val = num
    return (min_val, max_val)

