def reverse_string_with_spaces(s):
    """
    Reverses the characters of each word in the input string, while keeping spaces in place.
    """
    result = []
    word = []

    for char in s:
        if char == ' ':
            result.append(''.join(reversed(word)))
            result.append(' ')
            word = []
        else:
            word.append(char)

    if word:
        result.append(''.join(reversed(word)))

    return ''.join(result)

