def is_prime_with_smallest_factor(n):
    """
    Checks if the given number n is a prime number. If n is prime, returns True and the smallest prime factor.
    If n is not a prime, returns False and indicates there are no prime factors other than 1.

    Parameters:
    n (int): The number to check.

    Returns:
    tuple: (bool, smallest prime factor or message)
    """
    if n <= 1:
        return (False, "No prime factors other than 1")

    if n == 2:
        return (True, 2)

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return (False, "No prime factors other than 1")

    return (True, n)

