def is_balanced_parentheses(s):
    """
    Returns True if each opening parenthesis has a corresponding closing parenthesis.
    Otherwise, returns False.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

def count_characters(s):
    """
    Takes a string as input and returns a tuple containing the counts of
    uppercase letters, lowercase letters, digits, and special characters.
    """
    upper_count = 0
    lower_count = 0
    digit_count = 0
    special_count = 0

    for char in s:
        if 'A' <= char <= 'Z':
            upper_count += 1
        elif 'a' <= char <= 'z':
            lower_count += 1
        elif '0' <= char <= '9':
            digit_count += 1
        else:
            special_count += 1

    return (upper_count, lower_count, digit_count, special_count)

