def circular_permutations(n):
    """
    Returns the number of distinct ways to arrange 'n' distinct items in a circle.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return factorial(n - 1)

def factorial(num):
    """
    Helper function to compute the factorial of a given number.
    """
    if num <= 1:
        return 1
    else:
        return num * factorial(num - 1)

