def two_sum(nums, target):
    """
    Returns a tuple of two indices in the list such that the integers at these indices add up to the target integer.

    Parameters:
        nums (list of int): The list of integers.
        target (int): The target integer.

    Returns:
        tuple: A tuple of two indices.
    """
    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], i)
        num_to_index[num] = i
    return None

