def max_subarray_sum(nums):
    """
    Returns the maximum possible sum of a subarray within the given list of numbers.

    This function implements Kadane's algorithm.
    """
    if not nums:
        return 0  # Non-existent subarray

    max_current = max_global = nums[0]

    for num in nums[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

