def union_sorted_lists(list1, list2):
    """
    Returns the union of two sorted lists as a new sorted list without duplicates.
    """
    result = []
    i, j = 0, 0
    len1, len2 = len(list1), len(list2)

    while i < len1 and j < len2:
        if list1[i] < list2[j]:
            if not result or list1[i] != result[-1]:
                result.append(list1[i])
            i += 1
        elif list1[i] > list2[j]:
            if not result or list2[j] != result[-1]:
                result.append(list2[j])
            j += 1
        else:
            if not result or list1[i] != result[-1]:
                result.append(list1[i])
            i += 1
            j += 1

    while i < len1:
        if not result or list1[i] != result[-1]:
            result.append(list1[i])
        i += 1

    while j < len2:
        if not result or list2[j] != result[-1]:
            result.append(list2[j])
        j += 1

    return result

