def char_frequency(s):
    """
    Returns a dictionary with characters as keys and their frequencies as values,
    and the character that appears most frequently.
    If there are multiple characters with the same maximum frequency, returns any one of them.
    """
    if not s:
        return {}, None

    freq = {}
    max_char = s[0]
    max_count = 0

    for char in s:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1

        if freq[char] > max_count:
            max_count = freq[char]
            max_char = char

    return freq, max_char

