def divisible_by_three_and_five(n):
    """
    Returns a list of numbers up to n that are divisible by three and five.
    Each number divisible by three and five is included only once.
    """
    result = []
    for i in range(1, n+1):
        if i % 3 == 0 and i % 5 == 0:
            result.append(i)

    return result

