def findMaxLength(nums):
    """
    Finds the longest subarray with equal number of 0s and 1s in a given binary array.
    """
    count_map = {0: -1}
    max_length = 0
    count = 0

    for i, num in enumerate(nums):
        count += -1 if num == 0 else 1

        if count in count_map:
            max_length = max(max_length, i - count_map[count])
        else:
            count_map[count] = i

    return max_length

