def longest_common_subsequence(list1, list2):
    """
    Returns the longest common subsequence between two lists.
    If no common subsequence exists, returns an empty list.
    """
    n, m = len(list1), len(list2)
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    for i in range(n):
        for j in range(m):
            if list1[i] == list2[j]:
                dp[i + 1][j + 1] = dp[i][j] + 1
            else:
                dp[i + 1][j + 1] = max(dp[i + 1][j], dp[i][j + 1])

    # Construct the longest common subsequence
    lcs = []
    i, j = n, m
    while i > 0 and j > 0:
        if list1[i - 1] == list2[j - 1]:
            lcs.append(list1[i - 1])
            i -= 1
            j -= 1
        elif dp[i - 1][j] >= dp[i][j - 1]:
            i -= 1
        else:
            j -= 1
    lcs.reverse()
    return lcs

