def find_max_value(lst):
    """
    Returns the maximum value in the given integer list. If the list is empty,
    returns -1. If the list contains only one element, returns that element.
    If the list is in descending order, returns the first element.
    Otherwise, returns the maximum value in the list by performing bubble sort
    and returning the last element.
    """
    if not lst:
        return -1
    if len(lst) == 1:
        return lst[0]
    if lst == sorted(lst, reverse=True):
        return lst[0]

    # Bubble sort
    n = len(lst)
    for i in range(n):
        for j in range(0, n-i-1):
            if lst[j] > lst[j+1]:
                lst[j], lst[j+1] = lst[j+1], lst[j]

    return lst[-1]

