def longest_subarray_with_sum(arr, k):
    """
    Returns the length of the longest contiguous subarray where the sum of the elements is equal to k.

    :param arr: List of integers
    :param k: Integer sum to be matched
    :return: Length of the longest contiguous subarray
    """
    # Dictionary to store sum until each index
    sum_map = {}
    current_sum = 0
    max_length = 0

    for i, num in enumerate(arr):
        current_sum += num

        if current_sum == k:
            max_length = i + 1

        if current_sum - k in sum_map:
            max_length = max(max_length, i - sum_map[current_sum - k])

        if current_sum not in sum_map:
            sum_map[current_sum] = i

    return max_length

