def is_valid_hex(s):
    """
    This function checks if the given string is a valid hexadecimal string.

    A valid hexadecimal string consists of the characters from 0-9 and A-F (uppercase),
    with no spaces or special characters and the string should not start with multiple
    0's unless it is exactly "0".

    :param s: input string
    :return: True if the string is a valid hex, otherwise False
    """
    if len(s) == 0:
        return False

    if s == "0":
        return True

    if s[0] == "0":
        return False

    for char in s:
        if char.isdigit() or ('A' <= char <= 'F'):
            continue
        else:
            return False

    return True

