def char_frequency(s):
    """
    Returns a dictionary containing the frequency of each character in the input string, excluding spaces.
    """
    frequency = {}
    for char in s:
        if char != ' ':
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1
    return frequency

