def is_prime(num):
    """
    Returns True if num is a prime number, else False.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def sum_of_primes_less_than(n):
    """
    Returns the sum of all prime numbers less than n.
    """
    return sum(num for num in range(2, n) if is_prime(num))

