def second_largest(numbers):
    """
    Returns the second largest number in the list of integers.
    If the list has fewer than 2 unique elements, return None.
    """
    if len(numbers) < 2:
        return None

    first, second = float('-inf'), float('-inf')

    for number in numbers:
        if number > first:
            second = first
            first = number
        elif first > number > second:
            second = number

    return second if second != float('-inf') else None

def fib(n):
    """
    Returns the nth Fibonacci number using matrix exponentiation.
    """
    def multiply_matrices(A, B):
        return [
            [
                A[0][0] * B[0][0] + A[0][1] * B[1][0],
                A[0][0] * B[0][1] + A[0][1] * B[1][1]
            ],
            [
                A[1][0] * B[0][0] + A[1][1] * B[1][0],
                A[1][0] * B[0][1] + A[1][1] * B[1][1]
            ]
        ]

    def matrix_power(matrix, power):
        result = [[1, 0], [0, 1]]  # Identity matrix
        base = matrix

        while power > 0:
            if power % 2 == 1:
                result = multiply_matrices(result, base)
            base = multiply_matrices(base, base)
            power //= 2

        return result

    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        F = [[1, 1], [1, 0]]
        result_matrix = matrix_power(F, n-1)
        return result_matrix[0][0]

def second_largest(nums):
    """
    Returns the second-largest number in a list of positive integers.
    Assumes that the list always has at least two distinct numbers.
    """
    largest = second = float('-inf')
    for num in nums:
        if num > largest:
            second = largest
            largest = num
        elif num > second and num < largest:
            second = num
    return second

