def generate_primes(limit):
    """
    Generates a list of all prime numbers up to a given limit using the Sieve of Eratosthenes.

    :param limit: int - The upper boundary of the range to look for prime numbers.
    :return: list of int - A list containing all prime numbers up to limit.
    """
    if limit < 2:
        return []

    sieve = [True] * (limit + 1)
    sieve[0] = sieve[1] = False

    for start in range(2, int(limit**0.5) + 1):
        if sieve[start]:
            for multiple in range(start*start, limit + 1, start):
                sieve[multiple] = False

    return [num for num in range(2, limit + 1) if sieve[num]]

