def flatten_list(nested_list):
    """
    Flattens a given nested list.

    :param nested_list: List that potentially contains other lists
    :return: A single list with all elements in a flat structure
    """
    flat_list = []

    def flatten(sublist):
        for item in sublist:
            if isinstance(item, list):
                flatten(item)
            else:
                flat_list.append(item)

    flatten(nested_list)
    return flat_list

