def are_anagrams(str1, str2):
    """
    Returns True if str2 is an anagram of str1, otherwise False.
    """
    # Anagrams must be the same length
    if len(str1) != len(str2):
        return False

    # Anagrams must have the same letters exactly the same number of times
    return sorted(str1) == sorted(str2)

