def sum_of_unique_elements(arr):
    """
    Returns the sum of all unique elements in the array.
    """
    element_count = {}
    for element in arr:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1

    unique_sum = sum(key for key, value in element_count.items() if value == 1)
    return unique_sum

