def frequency_count(arr):
    """
    Returns the frequency of each integer in the array.

    Parameters:
    arr (list): A list of integers.

    Returns:
    dict: A dictionary where keys are the integers from the array and values are their corresponding frequencies.
    """
    frequency_dict = {}
    for num in arr:
        if num in frequency_dict:
            frequency_dict[num] += 1
        else:
            frequency_dict[num] = 1
    return frequency_dict

