def average_excluding_divisible_by_3(numbers):
    """
    Calculate the average of a given list of numbers, excluding any numbers that are divisible by 3.

    :param numbers: List of integers
    :return: The average of the numbers not divisible by 3.
    """
    filtered_numbers = [num for num in numbers if num % 3 != 0]

    if not filtered_numbers:
        return 0

    return sum(filtered_numbers) / len(filtered_numbers)

