def longest_repeated_substring(input_string):
    """
    Returns the longest substring that appears at least twice in the input string.
    """
    def get_suffix_array(s):
        """Builds the suffix array for given string s."""
        return sorted(range(len(s)), key=lambda k: s[k:])

    def longest_common_prefix(s, a, b):
        """Returns the length of the longest common prefix of s starting from indexes a and b."""
        lcp = 0
        while a + lcp < len(s) and b + lcp < len(s) and s[a + lcp] == s[b + lcp]:
            lcp += 1
        return lcp

    n = len(input_string)

    if n == 0:
        return ""

    suffix_array = get_suffix_array(input_string)
    max_len = 0
    start_index = 0
    for i in range(1, n):
        lcp = longest_common_prefix(input_string, suffix_array[i - 1], suffix_array[i])
        if lcp > max_len:
            max_len = lcp
            start_index = suffix_array[i]

    return input_string[start_index:start_index + max_len] if max_len > 0 else ""

