def perform_operation(arr, operation):
    """
    Performs the specified operation on the elements of the array and returns the result as a new array.

    Parameters:
    arr (list of int): Array of integers
    operation (str): Operation to be performed. One of '+', '*', '/'

    Returns:
    list of int: New array after performing the operation
    """

    if not arr:
        return arr

    if operation == '+':
        return [element + element for element in arr]
    elif operation == '*':
        return [element * element for element in arr]
    elif operation == '/':
        return [element / 2 for element in arr if element != 0]
    else:
        raise ValueError("Unsupported operation. Please use one of '+', '*', '/'")

