def sum_of_squares_of_digits(n):
    """
    Returns the sum of the squares of the digits of a positive integer n.
    Raises ValueError if n is not a positive integer.
    """
    if not isinstance(n, int) or n <= 0:
        raise ValueError("Input must be a positive integer")

    return sum(int(digit) ** 2 for digit in str(n))

def can_insert_char_to_sort(s):
    """
    Checks if it's possible to insert at most one character anywhere in the string
    to make the string lexicographically sorted.
    """
    if len(s) < 2:
        return True

    insertions_needed = 0

    for i in range(1, len(s)):
        if s[i-1] > s[i]:
            insertions_needed += 1
            if insertions_needed > 1:
                return False

    return True

