import math

def lcm(a, b):
    """
    Returns the least common multiple (LCM) of two positive integers a and b.
    If the integers are not valid or no LCM can be calculated, the function returns -1.
    """
    if isinstance(a, int) and isinstance(b, int) and a > 0 and b > 0:
        return abs(a * b) // math.gcd(a, b)
    else:
        return -1

def larger_of_two(a, b):
    """
    Returns the larger of the two numbers. If they are equal, returns one of the numbers.
    """
    if a >= b:
        return a
    else:
        return b

