def longest_common_prefix_length(s):
    """
    Returns the length of the longest common prefix among all the prefixes of the string.
    """
    if not s:  # if the string is empty
        return 0

    prefix = s[0]

    for char in s[1:]:
        if char == prefix[-1]:
            prefix += char
        else:
            break

    return len(prefix)

