def first_substring_alphabetical(s):
    """
    Returns the substring that appears first in alphabetical order.
    If multiple substrings are first, returns all in a list.
    """
    if not s:
        return []

    substrings = {s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)}
    first_alpha = min(substrings)

    return [substring for substring in substrings if substring == first_alpha]

