def count_upper_lower(s):
    """
    Takes a string and returns a dictionary with the count of upper-case and lower-case letters.

    :param s: string
    :return: dictionary with keys "upper" and "lower"
    """
    counts = {"upper": 0, "lower": 0}
    for char in s:
        if char.isupper():
            counts["upper"] += 1
        elif char.islower():
            counts["lower"] += 1
    return counts

