def sum_even_numbers(a, b):
    """
    Returns the sum of all even numbers between a and b, inclusive.
    If a is greater than b, return 0.
    If either of the numbers is not an integer, return an error message.
    """
    if not isinstance(a, int) or not isinstance(b, int):
        return "Both inputs must be integers"

    if a > b:
        return 0

    return sum(number for number in range(a, b + 1) if number % 2 == 0)

