def is_prime(n):
    """
    Determines if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_primes(start, end):
    """
    Generates a list of all prime numbers within the range [start, end].
    """
    return [num for num in range(start, end + 1) if is_prime(num)]

