def is_letter_or_space(s):
    """
    Checks if the string contains only letters or spaces.
    """
    return all(c.isalpha() or c.isspace() for c in s)

def is_palindrome(s):
    """
    Checks if the string is a palindrome, ignoring case, spaces and punctuation.
    """
    # Filter only letters and make lowercase for palindrome check
    filtered_chars = ''.join(c.lower() for c in s if c.isalpha())
    # Check if the filtered string is palindrome
    return filtered_chars == filtered_chars[::-1]

def check_string(s):
    """
    Checks if the string contains only letters and spaces, and if it is a palindrome.
    Returns a tuple containing a boolean for each check.
    """
    if not is_letter_or_space(s):
        return (False, False)
    return (True, is_palindrome(s))

