def common_divisors(a, b):
    """
    Returns a list of all the common divisors of a and b, sorted in descending order.
    """
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def get_divisors(n):
        divisors = set()
        for i in range(1, int(n ** 0.5) + 1):
            if n % i == 0:
                divisors.add(i)
                if i != n // i:
                    divisors.add(n // i)
        return divisors

    gcd_value = gcd(a, b)
    common_divisors = get_divisors(gcd_value)

    return sorted(common_divisors, reverse=True)

