def median_filter(image):
    """
    Apply a median filter to a 2D array (image).

    Args:
    image (list of list of int): 2D array representing the image.

    Returns:
    list of list of int: 2D array with median filter applied.
    """
    def get_median(values):
        sorted_vals = sorted(values)
        length = len(sorted_vals)
        if length % 2 == 1:
            return sorted_vals[length // 2]
        else:
            return (sorted_vals[length // 2 - 1] + sorted_vals[length // 2]) / 2

    import numpy as np

    image_array = np.array(image)
    filtered_image = np.copy(image_array)

    for i in range(1, image_array.shape[0] - 1):
        for j in range(1, image_array.shape[1] - 1):
            neighbors = []
            for k in range(-1, 2):
                for l in range(-1, 2):
                    neighbors.append(image_array[i + k, j + l])
            filtered_image[i, j] = get_median(neighbors)

    return filtered_image.tolist()

