def find_max_min(arr):
    """
    Returns a tuple with the maximum and minimum values in the array.

    :param arr: List of integers
    :return: Tuple (max_value, min_value)
    """
    if not arr:
        raise ValueError("Array must not be empty")

    max_value = min_value = arr[0]

    for num in arr[1:]:
        if num > max_value:
            max_value = num
        elif num < min_value:
            min_value = num

    return (max_value, min_value)

