def is_point_in_polygon(vertices, point):
    """
    Determines if a point is inside or outside a non-convex polygon.

    vertices: List of tuples representing the vertices of the polygon in (x, y) format.
    point: A tuple representing the point to check in (x, y) format.

    Returns True if the point is inside the polygon, otherwise False.
    """

    x, y = point
    n = len(vertices)
    inside = False

    p1x, p1y = vertices[0]
    for i in range(n + 1):
        p2x, p2y = vertices[i % n]
        if y > min(p1y, p2y):
            if y <= max(p1y, p2y):
                if x <= max(p1x, p2x):
                    if p1y != p2y:
                        xinters = (y - p1y) * (p2x - p1x) / (p2y - p1y) + p1x
                    if p1x == p2x or x <= xinters:
                        inside = not inside
        p1x, p1y = p2x, p2y

    return inside

