def combination_sum(num, target):
    """
    Prints all the combinations of numbers from 1 to `num` that sum up to `target`.
    """
    def find_combinations(remaining, start, path):
        if remaining == 0:
            print(path)
            return
        for i in range(start, num + 1):
            if i > remaining:
                break
            find_combinations(remaining - i, i + 1, path + [i])

    find_combinations(target, 1, [])

