def check_tuples_length_and_integers(tuples_list):
    """
    Check if all tuples in the list have the same length and if all elements in the tuples are integers.
    """
    if not tuples_list:
        return True

    first_length = len(tuples_list[0])

    for tpl in tuples_list:
        if len(tpl) != first_length:
            return False
        if not all(isinstance(item, int) for item in tpl):
            return False

    return True

