def char_to_binary(c):
    if c.isdigit():
        return 'd' + bin(ord(c))[2:].zfill(8)
    elif c.isalpha():
        return 'l' + bin(ord(c))[2:].zfill(8)
    elif c in '!"#$%&\'()*+,-./:;<=>?@[\\]^_`{|}~':
        return 'p' + bin(ord(c))[2:].zfill(8)
    else:
        return None

def string_to_special_binary(s):
    result = []
    for c in s:
        binary_representation = char_to_binary(c)
        if binary_representation:
            result.append(binary_representation)
    return ' '.join(result)

