def product_of_numbers(number_string):
    """
    Takes a string of numbers separated by commas and returns the product of all numbers.
    Returns "Invalid input" if the string is empty or contains non-numeric characters.
    """
    if not number_string:
        return "Invalid input"

    try:
        numbers = [int(num) for num in number_string.split(',')]
    except ValueError:
        return "Invalid input"

    product = 1
    for num in numbers:
        product *= num

    return product

