def is_subsequence(arr1, arr2):
    """
    Determines if arr1 is a subsequence of arr2 or vice versa.
    """
    def check_subsequence(small, large):
        iter_large = iter(large)
        return all(number in iter_large for number in small)

    return check_subsequence(arr1, arr2) or check_subsequence(arr2, arr1)

