def ascii_values(strings):
    """
    Takes a list of strings and returns a list of integers representing the ASCII values
    of the characters at the same positions in all strings.
    """
    if not strings:
        return []

    # Assert all strings are of the same length
    length = len(strings[0])
    for string in strings:
        if len(string) != length:
            raise ValueError("All strings must be of the same length")

    result = []
    for i in range(length):
        result.append([ord(string[i]) for string in strings])

    return result

