def decimal_to_binary(n):
    """
    Convert a non-negative integer to its binary equivalent as a string using recursion.
    """
    if n == 0:
        return "0"
    elif n == 1:
        return "1"
    else:
        return decimal_to_binary(n // 2) + str(n % 2)

