def is_perfect_square(num):
    """
    Determines if the given non-negative integer 'num' is a perfect square.

    :param num: Non-negative integer
    :return: True if 'num' is a perfect square, otherwise False
    """
    if num < 0:
        return False
    left, right = 0, num
    while left <= right:
        mid = (left + right) // 2
        square = mid * mid
        if square == num:
            return True
        elif square < num:
            left = mid + 1
        else:
            right = mid - 1
    return False

