def find_duplicates(nums):
    """
    Returns a list of duplicate numbers in the provided list of integers.
    """
    seen = set()
    duplicates = set()

    for num in nums:
        if num in seen:
            duplicates.add(num)
        else:
            seen.add(num)

    return list(duplicates)

