def decimal_to_hexadecimal(n):
    """
    Converts a decimal number to its hexadecimal representation using bitwise operations.
    """
    if n == 0:
        return "0"

    hex_chars = "0123456789ABCDEF"
    result = []

    while n > 0:
        remainder = n & 0xF  # Get the last 4 bits
        result.append(hex_chars[remainder])
        n = n >> 4  # Shift right by 4 bits to process the next digit

    return ''.join(result[::-1])

