def product_with_zero(arr):
    """
    Returns the product of all elements in the array. If the array contains a zero,
    the product is set to zero. If the array is empty, the product is also zero.
    """
    if not arr:
        return 0

    product = 1
    for num in arr:
        if num == 0:
            return 0
        product *= num

    return product

