def two_sum(nums, target):
    """
    Identify two numbers in a list that add up to the target sum.

    Args:
    nums (list): List of numbers.
    target (int): Target sum.

    Returns:
    tuple: A tuple of two indices that add up to the target sum.
    """
    num_dict = {}
    for index, num in enumerate(nums):
        complement = target - num
        if complement in num_dict:
            return (num_dict[complement], index)
        num_dict[num] = index
    return None

def sieve_of_eratosthenes(n):
    """
    Returns a list of prime numbers between 1 and n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return []

    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False

    for i in range(2, int(n**0.5) + 1):
        if sieve[i]:
            for j in range(i*i, n + 1, i):
                sieve[j] = False

    return [i for i in range(2, n + 1) if sieve[i]]

