def zigzag(arr):
    """
    Arrange the elements of the array in zigzag order.
    A zigzag order means that for every element arr[i]:
    - if i is even, arr[i] <= arr[i+1]
    - if i is odd, arr[i] >= arr[i+1]

    Parameters:
    arr (list): A list of integers.

    Returns:
    list: A list arranged in zigzag pattern.
    """
    # Traverse all elements in the array
    for i in range(len(arr) - 1):
        if i % 2 == 0:
            if arr[i] > arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
        else:
            if arr[i] < arr[i + 1]:
                arr[i], arr[i + 1] = arr[i + 1], arr[i]
    return arr

