def max_consecutive_numbers(nums):
    """
    Returns the maximum number of consecutive numbers in the given list.
    """
    if not nums:
        return 0

    max_count = 1
    current_count = 1

    for i in range(1, len(nums)):
        if nums[i] == nums[i - 1] + 1:
            current_count += 1
        else:
            if current_count > max_count:
                max_count = current_count
            current_count = 1

    return max(max_count, current_count)

