def char_count(s):
    """
    Returns a dictionary with unique characters as keys and their counts as values.
    """
    count_dict = {}
    for char in s:
        if char in count_dict:
            count_dict[char] += 1
        else:
            count_dict[char] = 1
    return count_dict

