def sum_of_two_largest_numbers(nums):
    """
    Returns the sum of the two largest numbers in the given array of integers.
    """
    if len(nums) < 2:
        raise ValueError("The input array must contain at least two elements.")

    first = second = float('-inf')
    for num in nums:
        if num > first:
            second = first
            first = num
        elif num > second:
            second = num

    return first + second

