def fibonacci(n):
    """
    Returns the nth Fibonacci number.
    """
    if n <= 0:
        raise ValueError("n should be a positive integer.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    a, b = 0, 1
    for _ in range(n - 2):
        a, b = b, a + b
    return b

