def multiply(a, b):
    """
    Returns the product of a and b using a recursive approach.
    Positive case and adjustment for negative numbers are handled separately.
    """

    # Base Case: when b is 0, the product is 0.
    if b == 0:
        return 0

    # Handle the case where b is negative
    if b < 0:
        return -multiply(a, -b)

    # Recursive Step: b is positive, sum up 'a' b times
    return a + multiply(a, b - 1)

