from typing import Optional, List

def most_frequent(nums: List[int]) -> Optional[int]:
    """
    Returns the integer that occurs most frequently in the list.
    If there is a tie, return the smallest integer among the most frequent.
    If the list is empty, return None.
    """
    if not nums:
        return None

    frequency = {}

    for num in nums:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    most_freq = max(frequency.values())
    candidates = [num for num, freq in frequency.items() if freq == most_freq]

    return min(candidates)

