def sumEvenNumbers(start, end):
    """
    Returns the sum of all even numbers between start and end (inclusive).
    If start is greater than end, returns -1.
    """
    if start > end:
        return -1

    # Ensure start is even
    if start % 2 != 0:
        start += 1

    # Ensure end is even
    if end % 2 != 0:
        end -= 1

    # Sum of all even numbers in the range
    return sum(range(start, end+1, 2))

