def replace_every_other(x):
    """
    Takes a single integer, x, as input and returns a new string where every other character is replaced by
    the word 'removed', starting with the first character (index 0).
    """
    x_str = str(x)
    result = []
    for i in range(len(x_str)):
        if i % 2 == 0:
            result.append('removed')
        else:
            result.append(x_str[i])
    return ''.join(result)

