def find_largest(a, b, c):
    """
    Returns the largest of the three integers or "Tie" if there is a tie.
    """
    if a > b and a > c:
        return a
    elif b > a and b > c:
        return b
    elif c > a and c > b:
        return c
    elif a == b and a > c:
        return "Tie"
    elif a == c and a > b:
        return "Tie"
    elif b == c and b > a:
        return "Tie"
    else:
        return "Tie"

