def binary_to_decimal(binary_str):
    """
    Converts a given binary string to its decimal equivalent.
    It handles both 8-bit and 16-bit binary strings.
    It also handles errors for invalid binary strings.
    """
    # Check if binary_str is valid (contains only '0' or '1')
    if not set(binary_str).issubset({'0', '1'}):
        raise ValueError("Invalid binary string. Only '0' and '1' are allowed.")

    # Check for 8-bit or 16-bit length
    if len(binary_str) not in [8, 16]:
        raise ValueError("Invalid binary string length. Only 8-bit and 16-bit lengths are allowed.")

    return int(binary_str, 2)

