def int_to_string_representation(n):
    """
    Returns a string representation of the given integer as specified:

    - If the integer is negative, return its absolute value followed by " negative".
    - If the integer is positive, return its string representation.
    - If the integer is zero, return "Zero".
    """
    if n < 0:
        return f"{abs(n)} negative"
    elif n > 0:
        return str(n)
    else:
