def is_prime(n):
    """
    Checks if a given number n is a prime number.

    A prime number is only divisible by 1 and itself.

    :param n: int
    :return: bool
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def longest_unique_substring(s):
    """
    Returns the longest substring without repeating characters.
    """
    if not s:
        return ""

    start = 0
    max_len = 0
    max_substr = ""
    used_chars = {}

    for i, char in enumerate(s):
        if char in used_chars and used_chars[char] >= start:
            start = used_chars[char] + 1

        used_chars[char] = i
        if i - start + 1 > max_len:
            max_len = i - start + 1
            max_substr = s[start:i+1]

    return max_substr

