def sort_descending(lst):
    """
    Takes a list of integers as input and returns a list of the same integers, but sorted in descending order.
    Does not use the built-in sort() or sorted() functions.
    """
    for i in range(len(lst)):
        for j in range(i + 1, len(lst)):
            if lst[i] < lst[j]:
                lst[i], lst[j] = lst[j], lst[i]
    return lst

