def caesar_cipher(text, shift):
    """
    Encrypts the input text using a Caesar cipher with a given shift.
    :param text: string to be encrypted
    :param shift: integer representing the shift for the cipher
    :return: encrypted string
    """
    result = []

    # Loop through each character in the text
    for char in text:
        if char.isalpha():
            shift_amount = shift % 26  # There are 26 letters in the alphabet

            # Calculate the new position for lowercase or uppercase letters
            if char.islower():
                new_char = chr((ord(char) - ord('a') + shift_amount) % 26 + ord('a'))
            else:
                new_char = chr((ord(char) - ord('A') + shift_amount) % 26 + ord('A'))

            result.append(new_char)
        else:
            result.append(char)  # non-alphabetic characters are not shifted

    return ''.join(result)

