def dict_to_query_string(d, parent_key=''):
    """
    Converts a nested dictionary into a query string, flattening nested dictionaries
    and concatenating keys with ".".

    :param d: Dictionary to convert.
    :param parent_key: The base key for the current level of recursion (used for nested dictionaries).
    :return: A URL query string representation of the dictionary.
    """
    parts = []

    for key, value in d.items():
        full_key = f"{parent_key}.{key}" if parent_key else key
        if isinstance(value, dict):
            parts.extend(dict_to_query_string(value, full_key).split('&'))
        else:
            parts.append(f"{full_key}={value}")

    return '&'.join(parts)

