def character_frequency(s: str) -> dict:
    """
    Returns a dictionary where each key is a unique character (ignoring case and spaces) from the string,
    and the value is the frequency of that character in the string.

    :param s: Input string
    :return: Dictionary with character frequencies
    """
    frequency = {}
    for char in s.lower():
        if char != ' ':
            if char in frequency:
                frequency[char] += 1
            else:
                frequency[char] = 1
    return frequency

