def process_number(n):
    """
    Takes an integer n. If n is even or less than or equal to zero, returns n/2.
    If n is odd and greater than zero, returns 3n + 1.
    """
    if n <= 0 or n % 2 == 0:
        return n / 2
    else:
        return 3 * n + 1

def unique_substrings(s):
    """
    Returns the number of unique substrings of the input string s.
    """
    substrings_set = set()
    n = len(s)

    for i in range(n):
        for j in range(i + 1, n + 1):
            substrings_set.add(s[i:j])

    return len(substrings_set)

