def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5)+1, 2):
        if n % i == 0:
            return False
    return True

def prime_product(lst):
    """
    Returns the product of all prime numbers in the list.
    """
    product = 1
    has_prime = False
    for num in lst:
        if is_prime(num):
            product *= num
            has_prime = True
    return product if has_prime else None

