def factorial(n):
    """
    Returns the factorial of a given integer n using recursion.
    Throws ValueError if the input is not an integer or if the integer is negative.
    """
    if not isinstance(n, int):
        raise ValueError("Input must be an integer.")
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

