def sum_from_n_to_k(n, k):
    """
    Calculate the sum of all numbers from n down to k (inclusive),
    where k is less than or equal to n.
    """
    if k > n:
        raise ValueError("k should be less than or equal to n")
    return sum(range(k, n + 1))

