def nth_smallest(arr, n):
    """
    Returns the nth smallest value in the given array of integers using a selection algorithm.

    Parameters:
    arr (list of int): List of integers
    n (int): The nth smallest value to find

    Returns:
    int or None: The nth smallest value or None if n is out of bounds
    """
    if n <= 0 or n > len(arr):
        return None

    def partition(arr, left, right):
        pivot = arr[right]
        i = left
        for j in range(left, right):
            if arr[j] < pivot:
                arr[i], arr[j] = arr[j], arr[i]
                i += 1
        arr[i], arr[right] = arr[right], arr[i]
        return i

    def quickselect(arr, left, right, n):
        if left == right:
            return arr[left]
        pivot_index = partition(arr, left, right)
        if n == pivot_index:
            return arr[pivot_index]
        elif n < pivot_index:
            return quickselect(arr, left, pivot_index - 1, n)
        else:
            return quickselect(arr, pivot_index + 1, right, n)

    return quickselect(arr, 0, len(arr) - 1, n - 1)  # n-1 for zero-based index

