def is_prime(n):
    """
    Helper function that returns True if n is a prime number, otherwise False.
    """
    if n <= 1:
        return False
    if n == 2 or n == 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def primes_up_to(n):
    """
    Returns a list of all prime numbers up to and including n.
    """
    return [x for x in range(n + 1) if is_prime(x)]

