def fibonacci(n):
    """
    Returns a lambda function that calculates the nth Fibonacci number.
    """

    def nth_fibonacci(k):
        if k == 0:
            return 0
        elif k == 1:
            return 1
        a, b = 0, 1
        for _ in range(2, k + 1):
            a, b = b, a + b
        return b

    return lambda: nth_fibonacci(n)

