def count_unique_consonants(s):
    """
    Returns the number of unique consonants in the given string s.
    """
    vowels = set('aeiouAEIOU')
    consonants = set()

    for char in s:
        if char.isalpha() and char not in vowels:
            consonants.add(char.lower())

    return len(consonants)

