def remove_vowels(s):
    """
    Returns a new string where all the vowels (a, e, i, o, u) are removed using recursion.
    """
    if s == "":
        return s
    elif s[0].lower() in "aeiou":
        return remove_vowels(s[1:])
    else:
        return s[0] + remove_vowels(s[1:])

