def sum_first_last_5_even_numbers(nums):
    """
    Returns the sum of the first 5 even numbers and the last 5 even numbers from the list.
    If there are fewer than 5 even numbers, sum whatever even numbers are present.
    """
    even_numbers = [num for num in nums if num % 2 == 0]

    if len(even_numbers) < 5:
        first_5 = even_numbers
        last_5 = []
    else:
        first_5 = even_numbers[:5]
        last_5 = even_numbers[-5:]

    return sum(first_5) + sum(last_5)

