def find_shortest_word(words):
    """
    Returns the shortest word in a given list of words.
    If multiple words have the same shortest length, returns the first one encountered.
    If the list is empty, returns None.
    """
    if not words:
        return None

    shortest_word = words[0]
    for word in words[1:]:
        if len(word) < len(shortest_word):
            shortest_word = word

    return shortest_word

