def longest_unique_substring(s):
    """
    Returns the longest substring without repeating characters.
    """
    n = len(s)
    if n == 0:
        return ""

    longest_substr = ""
    start_idx = 0
    char_index_map = {}

    for end_idx, char in enumerate(s):
        if char in char_index_map and char_index_map[char] >= start_idx:
            start_idx = char_index_map[char] + 1
        char_index_map[char] = end_idx
        if len(longest_substr) < end_idx - start_idx + 1:
            longest_substr = s[start_idx:end_idx + 1]

    return longest_substr

