def fibonacci_sequence(n):
    """
    Generates the Fibonacci sequence of length n starting with 1 and 2.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [1]

    sequence = [1, 2]
    while len(sequence) < n:
        next_value = sequence[-1] + sequence[-2]
        sequence.append(next_value)

    return sequence

