def search_string_in_dict(nested_dict, target):
    results = []

    def search(current_dict, current_path):
        for key, value in current_dict.items():
            new_path = current_path + [key]
            if target in str(key):
                results.append(".".join(map(str, new_path)))
            if isinstance(value, dict):
                search(value, new_path)
            elif target in str(value):
                results.append(".".join(map(str, new_path)))

    search(nested_dict, [])
    return results

