def two_smallest_numbers(lst):
    """
    Returns a list containing the two smallest numbers from the given list
    in ascending order.
    """
    # Guard against invalid input
    if len(lst) < 2:
        raise ValueError("List must contain at least two elements")

    # Find two smallest numbers
    first, second = float('inf'), float('inf')
    for number in lst:
        if number < first:
            first, second = number, first
        elif number < second:
            second = number

    return [first, second]

