def merge_arrays(arr1, arr2):
    """
    Merges two arrays into a single array without duplicates.
    """
    merged_array = []
    unique_elements = {}

    for item in arr1:
        if item not in unique_elements:
            unique_elements[item] = True
            merged_array.append(item)

    for item in arr2:
        if item not in unique_elements:
            unique_elements[item] = True
            merged_array.append(item)

    return merged_array

def max_subarray_sum(nums):
    """
    Returns the maximum subarray sum for the input list of integers.
    """
    if not nums:
        return 0

    max_current = max_global = nums[0]

    for num in nums[1:]:
        max_current = max(num, max_current + num)
        if max_current > max_global:
            max_global = max_current

    return max_global

