def reverse_list_iterative(lst):
    """
    Returns a new list with the elements in reverse order using iterative method.
    """
    reversed_list = []
    for i in range(len(lst)-1, -1, -1):
        reversed_list.append(lst[i])
    return reversed_list

def reverse_list_recursive(lst):
    """
    Returns a new list with the elements in reverse order using recursive method.
    """
    if len(lst) == 0:
        return []
    return [lst[-1]] + reverse_list_recursive(lst[:-1])

