def longest_common_prefix(str1, str2):
    """
    Finds the longest common prefix between two strings.
    """
    min_length = min(len(str1), len(str2))
    prefix = ""

    for i in range(min_length):
        if str1[i] == str2[i]:
            prefix += str1[i]
        else:
            break

    return prefix

