def word_count(sentence):
    """
    Takes a sentence and returns a dictionary with each word as a key and the number of times it appears as the value.
    """
    words = sentence.split()
    word_dict = {}

    for word in words:
        word = word.lower()  # To make it case insensitive
        if word in word_dict:
            word_dict[word] += 1
        else:
            word_dict[word] = 1

    return word_dict

