def most_frequent_char(s):
    """
    Returns the most frequently occurring character in the given string.
    If there are multiple characters that occur most frequently, returns any one of them.
    If the input string is empty, returns None.
    """
    if not s:
        return None

    frequency = {}

    # Count the frequency of each character
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    # Find the character with the maximum frequency
    max_freq = -1
    most_frequent = None
    for char, freq in frequency.items():
        if freq > max_freq:
            max_freq = freq
            most_frequent = char

    return most_frequent

