import math

def sum_of_squares_floor(n):
    """
    Returns the floor value of the sum of the squares of the first n natural numbers.
    """
    if n < 1:
        return 0
    sum_squares = sum(i**2 for i in range(1, n + 1))
    return math.floor(sum_squares)

