def sum_of_divisors_excluding_n(n):
    """
    Returns the sum of all divisors of n excluding n itself.
    """
    if n <= 0:
        return 0

    divisors_sum = 0
    for i in range(1, n):
        if n % i == 0:
            divisors_sum += i
    return divisors_sum

