def count_consecutive_chars(s):
    """
    Returns the number of times the first character appears consecutively in the string s.
    """
    if not s:
        return 0

    first_char = s[0]
    count = 0

    for char in s:
        if char == first_char:
            count += 1
        else:
            break

    return count

