def fibonacci(n):
    """
    Returns the nth Fibonacci number using dynamic programming.
    """
    if n <= 0:
        raise ValueError("Input should be a positive integer.")
    if n == 1:
        return 0
    if n == 2:
        return 1

    fib_nums = [0, 1]
    for i in range(2, n):
        fib_nums.append(fib_nums[-1] + fib_nums[-2])

    return fib_nums[-1]

