def two_largest_numbers(arr):
    """
    Returns the two largest numbers in the array.

    Parameters:
    arr (list): List of integers.

    Returns:
    tuple: Two largest numbers in the array.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements.")

    first, second = float('-inf'), float('-inf')
    for number in arr:
        if number > first:
            second = first
            first = number
        elif number > second:
            second = number

    return (first, second)

