def find_max(nums):
    """
    Recursive helper function to find the maximum number in a list.
    """
    if len(nums) == 1:
        return nums[0]
    else:
        return max(nums[0], find_max(nums[1:]))

def find_second_largest(nums):
    """
    Recursive function to find the second largest number in a list.
    """
    if len(nums) < 2:
        raise ValueError("List must contain at least two elements")

    max_val = find_max(nums)
    nums_without_max = [num for num in nums if num != max_val]

    return find_max(nums_without_max)

