def nth_fibonacci_with_index(n):
    """
    Returns the nth Fibonacci number and its index in the form of a tuple (Fibonacci number, index).

    :param n: The index (0-based) of the Fibonacci number to retrieve.
    :return: A tuple containing the nth Fibonacci number and its index.
    """
    if n < 0:
        raise ValueError("Index cannot be negative")

    if n == 0:
        return (0, 0)
    elif n == 1:
        return (1, 1)

    a, b = 0, 1
    for i in range(2, n + 1):
        a, b = b, a + b

    return (b, n)

