def min_moves_to_convert(str1, str2):
    """
    Returns the minimum number of moves required to convert str1 to str2
    by inserting, deleting, or replacing characters.
    """
    m = len(str1)
    r = len(str2)

    # Create a DP table to store results of subproblems
    dp = [[0 for x in range(r + 1)] for x in range(m + 1)]

    # Fill dp[][] in bottom up manner
    for i in range(m + 1):
        for j in range(r + 1):
            if i == 0:
                dp[i][j] = j    # Min. operations = j
            elif j == 0:
                dp[i][j] = i    # Min. operations = i
            elif str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i][j - 1],      # Insert
                                   dp[i - 1][j],      # Remove
                                   dp[i - 1][j - 1])  # Replace
    return dp[m][r]

