def sort_descending(arr, stable=False):
    """
    Sorts an array of integers in descending order.

    Parameters:
    arr (list): A list of integers to be sorted.
    stable (bool): Optional; if True, the sorting will be stable.
                   Defaults to False.

    Returns:
    list: A new list of integers sorted in descending order.
    """
    if stable:
        return sorted(arr, key=lambda x: -x, reverse=False)
    else:
        return sorted(arr, reverse=True)

