def smallest_repdigit():
    """
    Calculate the smallest positive integer n such that the decimal number formed by
    concatenating n-1 copies of n equals a number whose decimal representation ends in all n's.
    """
    def is_repdigit(s):
        return all(c == s[0] for c in s)

    n = 1
    while True:
        concatenated = str(n) * (n - 1)
        if is_repdigit(concatenated + str(n)):
            return n
        n += 1

