def two_smallest_distinct_numbers(numbers):
    """
    Returns a tuple of the two smallest distinct numbers in the list.

    :param numbers: List of integers
    :return: Tuple of two smallest distinct integers
    """
    if len(numbers) < 2:
        raise ValueError("List must contain at least two distinct numbers")

    distinct_numbers = list(set(numbers))

    if len(distinct_numbers) < 2:
        raise ValueError("List must contain at least two distinct numbers")

    smallest = float('inf')
    second_smallest = float('inf')

    for number in distinct_numbers:
        if number < smallest:
            second_smallest = smallest
            smallest = number
        elif number < second_smallest:
            second_smallest = number

    return (smallest, second_smallest)

