def sieve_of_eratosthenes(n):
    """
    Generate a list of unique prime numbers up to a given number n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return []

    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0], is_prime[1] = False, False  # 0 and 1 are not prime numbers

    for num in range(2, n + 1):
        if is_prime[num]:
            primes.append(num)
            for multiple in range(num * num, n + 1, num):
                is_prime[multiple] = False

    return primes

