def eval_rpn(tokens):
    """
    Evaluate the value of an arithmetic expression in Reverse Polish Notation (RPN).

    :param tokens: List[str], a list of tokens in RPN format
    :return: int, the result of the expression
    """
    stack = []

    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                # Perform integer division that truncates towards zero
                stack.append(int(a / b))
        else:
            stack.append(int(token))

    return stack[0]

