def is_permutation_of_palindrome(input_str):
    """
    Checks if the input string is a permutation of a palindrome.

    A permutation of a palindrome is a string that can be rearranged to form a palindrome.
    This function ignores spaces, case, and punctuation.
    """
    # Normalize the string: remove spaces and lowercase
    input_str = ''.join(filter(str.isalnum, input_str)).lower()

    # Count frequency of each character
    char_count = {}
    for char in input_str:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Check that at most one character has an odd count
    odd_count = 0
    for count in char_count.values():
        if count % 2 != 0:
            odd_count += 1

    return odd_count <= 1

