def update_scores(scores, updates):
    """
    Updates the list of scores based on the rules provided in the updates dictionary.

    :param scores: List of tuples, where each tuple contains (student_id, current_score).
    :param updates: Dictionary where each key is a student's ID and each value is the points to be added.
    :return: A new list of tuples with updated scores.
    """
    scores_dict = dict(scores)
    for student_id, points in updates.items():
        if student_id in scores_dict:
            scores_dict[student_id] += points
        else:
            scores_dict[student_id] = points
    return list(scores_dict.items())

