def max_blocks_after_operations(arr):
    """
    Returns the maximum number of blocks after performing certain operations on a list of integers.
    """
    n = len(arr)
    if n == 0:
        return 0

    max_blocks = 1
    for i in range(1, n):
        if arr[i] != arr[i - 1]:
            max_blocks += 1

    return max_blocks

