def sum_triangular_matrix(matrix, row=0, col=0):
    """
    Recursively calculates and returns the sum of all elements in a triangular matrix.

    Parameters:
    matrix (list of lists): The triangular matrix.
    row (int): Current row index.
    col (int): Current column index.

    Returns:
    int: The sum of all elements in the triangular matrix.
    """
    if row >= len(matrix):
        return 0
    if col >= len(matrix[row]):
        return sum_triangular_matrix(matrix, row+1, 0)
    return matrix[row][col] + sum_triangular_matrix(matrix, row, col+1)

