def primes_upto(limit):
    """
    Returns a list of prime numbers from 2 up to the given limit (inclusive).
    """
    if limit < 2:
        return []

    primes = []
    is_prime = [True] * (limit + 1)

    for num in range(2, limit + 1):
        if is_prime[num]:
            primes.append(num)
            for multiple in range(num * num, limit + 1, num):
                is_prime[multiple] = False

    return primes

