def factorial(num):
    """
    Returns the factorial of a given non-negative integer num using an iterative approach.
    Raises a ValueError if num is not an integer or is a negative integer.
    """
    if not isinstance(num, int):
        raise ValueError("Input must be an integer.")
    if num < 0:
        raise ValueError("Input must be a non-negative integer.")

    result = 1
    for i in range(2, num + 1):
        result *= i
    return result

