def subset_sum(nums, target):
    """
    Checks if there is a subset of the list `nums` that sums up to `target`.

    Args:
    nums (list of int): The list of integers.
    target (int): The target sum.

    Returns:
    bool: True if there is a subset that sums up to `target`, False otherwise.
    """
    n = len(nums)
    dp = [[False] * (target + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, target + 1):
            if j < nums[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - nums[i - 1]]

    return dp[n][target]

