def decode_caesar_cipher(s, shift=5):
    """
    Decodes a given string using Caesar cipher with a shift of 5.
    """
    decoded_string = ""
    for char in s:
        if char.isalpha():
            shift_base = ord('A') if char.isupper() else ord('a')
            decoded_char = chr((ord(char) - shift_base - shift) % 26 + shift_base)
            decoded_string += decoded_char
        else:
            decoded_string += char
    return decoded_string

