def title_case(string):
    """
    Formats the given string to title case. Title case capitalizes the first letter of each
    word except for certain small words like 'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'a',
    'an', and 'the', unless they start the string.
    """
    small_words = {'and', 'but', 'or', 'nor', 'for', 'so', 'yet', 'a', 'an', 'the'}
    words = string.lower().split()
    if not words:
        return ""
    words[0] = words[0].capitalize()
    for i in range(1, len(words)):
        if words[i] not in small_words:
