def unique_paths_with_obstacles(obstacle_grid):
    """
    Calculate the number of unique paths from top-left corner to bottom-right corner
    on a grid with obstacles.

    :param obstacle_grid: List[List[int]], 2D grid where 1 represents an obstacle and 0 represents free space.
    :return: int, number of unique paths.
    """
    if not obstacle_grid or obstacle_grid[0][0] == 1:
        return 0

    m, n = len(obstacle_grid), len(obstacle_grid[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if obstacle_grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

