def max_product(arr):
    """
    Returns the maximum product that can be obtained from two numbers in the given array.

    Parameters:
    arr (list of int): The array of integers.

    Returns:
    int: The maximum product of any two numbers in the array.
    """
    if len(arr) < 2:
        raise ValueError("Array must contain at least two elements to calculate a product.")

    # Find the two largest numbers in the array
    max1 = max2 = float('-inf')
    for num in arr:
        if num > max1:
            max2 = max1
            max1 = num
        elif num > max2:
            max2 = num

    # Find the two smallest numbers in the array (for cases with large negative numbers)
    min1 = min2 = float('inf')
    for num in arr:
        if num < min1:
            min2 = min1
            min1 = num
        elif num < min2:
            min2 = num

    return max(max1 * max2, min1 * min2)

