    Returns the second largest element in the list `arr`.
    If the second largest element does not exist, returns None.
    """
    if not arr or len(arr) < 2:
        return None

    first = second = float('-inf')

    for num in arr:
        if num > first:
            first, second = num, first
        elif first > num > second:
            second = num

    return second if second != float('-inf') else None

