def is_prime(num):
    """
    Check if a number is a prime number.
    """
    if num <= 1:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def sum_of_primes_between(n, m):
    """
    Returns the sum of all prime numbers between integers n and m (inclusive).
    """
    if n > m:
        n, m = m, n
    return sum(num for num in range(n, m + 1) if is_prime(num))

def first_non_repeating_character(s):
    """
    Returns the first non-repeating character from the string `s`.
    If every character repeats, it returns '_'.
    """
    char_count = {}

    # Count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character with a count of 1
    for char in s:
        if char_count[char] == 1:
            return char

    return '_'

