def find_max(arr):
    """
    Returns the maximum number in an array of integers.
    Handles exceptions if the input is not a list or if the list is empty.
    """
    if not isinstance(arr, list):
        raise TypeError("Input should be of type list.")
    if len(arr) == 0:
        raise ValueError("Array should not be empty.")

    max_num = arr[0]
    for num in arr:
        if num > max_num:
            max_num = num

    return max_num

