def closest_to_zero(numbers):
    """
    Returns the closest number to zero from a given list of numbers.
    If there are multiple numbers with the same distance to zero, return the first one encountered.
    """
    if not numbers:
        return None

    closest = numbers[0]
    for num in numbers[1:]:
        if abs(num) < abs(closest) or (abs(num) == abs(closest) and num == closest):
            closest = num

    return closest

