def max_occurring_char(s):
    """
    Finds the maximum occurring character in a string and its frequency.
    If there are multiple characters with the same frequency, returns the one that appears first.

    Args:
    s (str): The input string

    Returns:
    tuple: A tuple containing the character and its frequency
    """
    if not s:
        return (None, 0)

    frequency = {}
    max_char = s[0]
    max_count = 0

    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

        if frequency[char] > max_count or (frequency[char] == max_count and s.index(max_char) > s.index(char)):
            max_char = char
            max_count = frequency[char]

    return (max_char, max_count)

