def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in a string irrespective of case.
    If there is no such character, returns an underscore '_'.
    """
    s = s.lower()
    count = {}

    # Count the occurrences of each character
    for char in s:
        if char in count:
            count[char] += 1
        else:
            count[char] = 1

    # Find the first character that occurs only once
    for char in s:
        if count[char] == 1:
            return char

    return '_'

