def find_smallest_recursive(lst, n=None, smallest=None):
    """
    Returns the smallest number in a list using recursion.
    """
    if n is None:
        n = len(lst) - 1

    if smallest is None:
        smallest = lst[n]

    if n < 0:
        return smallest

    if lst[n] < smallest:
        smallest = lst[n]

    return find_smallest_recursive(lst, n - 1, smallest)

# Example usage:
# print(find_smallest_recursive([3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5]))  # Output should be 1

