def remove_duplicates(s):
    """
    Removes all duplicate characters from a string and returns the modified string
    maintaining the original order of characters.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

