def sum_of_digits_in_multilevel_list(lst):
    """
    Traverses a multilevel list, adds up the digits of each number, and returns the total sum.

    Parameters:
    lst (list): A nested list of integers

    Returns:
    int: The total sum of the digits
    """
    total_sum = 0

    def sum_digits(n):
        """Returns the sum of the digits of a number n."""
        return sum(int(digit) for digit in str(n) if digit.isdigit())

    def traverse_and_sum(sublist):
        nonlocal total_sum
        for item in sublist:
            if isinstance(item, list):
                traverse_and_sum(item)
            elif isinstance(item, int):
                total_sum += sum_digits(item)

    traverse_and_sum(lst)
    return total_sum

