def numDistinctIslands(grid):
    """
    Returns the number of distinct islands in the given grid.

    Args:
    grid: List[List[int]] - a 2D array representing the grid where 1 is land and 0 is water.

    Returns:
    int - the number of distinct islands.
    """

    def dfs(x, y, origin_x, origin_y, island_shape):
        if x < 0 or y < 0 or x >= len(grid) or y >= len(grid[0]) or grid[x][y] != 1:
            return
        grid[x][y] = -1  # mark the cell as visited
        island_shape.append((x - origin_x, y - origin_y))
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

        for dx, dy in directions:
            dfs(x + dx, y + dy, origin_x, origin_y, island_shape)

    distinct_islands = set()

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 1:
                island_shape = []
                dfs(i, j, i, j, island_shape)
                distinct_islands.add(tuple(island_shape))

    return len(distinct_islands)

