def distinct_substrings(s):
    """
    Returns the number of distinct substrings of the given string 's'.
    """
    substrings = set()
    n = len(s)

    # Generate all possible substrings
    for i in range(n):
        for j in range(i+1, n+1):
            substrings.add(s[i:j])

    return len(substrings)

