def generate_primes(n):
    """
    Generate all prime numbers less than a given number n.
    """
    if n <= 2:
        return []

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False  # 0 and 1 are not prime numbers.

    p = 2
    while p * p < n:
        if is_prime[p]:
            for multiples in range(p * p, n, p):
                is_prime[multiples] = False
        p += 1

    return [num for num in range(2, n) if is_prime[num]]

