def insert_into_sorted_list(sorted_list, value):
    """
    Inserts a value into a sorted list and returns a new sorted list with the value inserted.
    """
    new_list = sorted_list.copy()
    for i in range(len(new_list)):
        if value < new_list[i]:
            new_list.insert(i, value)
            break
    else:
        new_list.append(value)
    return new_list

