def is_perfect_cube(n):
    """
    Checks if a given number n is a perfect cube.
    If n is a perfect cube, returns its cube root.
    Otherwise, returns the number itself.
    """
    if n < 0:
        candidate = int(round(abs(n)**(1/3.0))) * -1
    else:
        candidate = int(round(n**(1/3.0)))

    if candidate ** 3 == n:
        return candidate
    else:
        return n

