def longest_unique_substring(s):
    """
    Returns the longest substring with all unique characters in the given string s.
    """
    last_seen = {}
    start = 0
    max_len = 0
    max_substr = ""

    for end in range(len(s)):
        if s[end] in last_seen:
            start = max(start, last_seen[s[end]] + 1)
        last_seen[s[end]] = end
        if end - start + 1 > max_len:
            max_len = end - start + 1
            max_substr = s[start:end+1]

    return max_substr

