def count_frequencies(array):
    """
    Counts the frequency of elements in the given array and returns a dictionary
    with elements as keys and their frequencies as values.

    :param array: List of elements to count frequencies.
    :type array: list
    :return: Dictionary with elements as keys and frequencies as values.
    :rtype: dict
    """
    frequency_dict = {}
    for element in array:
        if element in frequency_dict:
            frequency_dict[element] += 1
        else:
            frequency_dict[element] = 1
    return frequency_dict

