def generate_primes(n):
    """
    Generates the first n prime numbers.

    :param n: The number of prime numbers to generate.
    :return: A list containing the first n prime numbers.
    """
    if n <= 0:
        return []

    primes = []
    candidate = 2  # Start checking for primes from 2

    while len(primes) < n:
        is_prime = True
        for p in primes:
            if candidate % p == 0:
                is_prime = False
                break
        if is_prime:
            primes.append(candidate)
        candidate += 1

    return primes

