def is_prime(n):
    """
    Helper function to determine if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def find_primes_in_interval(l, r):
    """
    Returns a list of all prime numbers in the interval [l, r].
    """
    primes = []
    for num in range(l, r + 1):
        if is_prime(num):
            primes.append(num)
    return primes

