def is_prime(num):
    """
    Helper function to check whether a number is prime.
    """
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def product_of_primes(numbers):
    """
    Returns the product of all prime numbers in the given list.
    If there are no prime numbers, returns 0.
    """
    primes = [num for num in numbers if is_prime(num)]
    if not primes:
        return 0

    product = 1
    for prime in primes:
        product *= prime

    return product

