def get_minimum_value(lst):
    """
    Returns the minimum value in a list. Assumes the list is non-empty.
    """
    if not lst:
        raise ValueError("The list is empty.")

    min_value = lst[0]
    for value in lst[1:]:
        if value < min_value:
            min_value = value

    return min_value

