import math

def is_prime(n):
    """
    Utility function to check if n is a prime number.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def largest_prime_in_range(start, end):
    """
    Returns the largest prime number within the given range.
    If no prime number is found, returns None.
    """
    largest_prime = None
    for num in range(end, start - 1, -1):
        if is_prime(num):
            largest_prime = num
            break
    return largest_prime

