def max_depth(tree):
    """
    Returns the maximum depth of the binary tree.

    Args:
    tree (list): A list of lists where each sublist contains the node value and its two children as indices.

    Returns:
    int: The maximum depth of the binary tree.
    """
    if not tree:
        return 0

    def depth(node_index):
        if node_index == -1:
            return 0
        left_index = tree[node_index][1]
        right_index = tree[node_index][2]
        return 1 + max(depth(left_index), depth(right_index))

    return depth(0)

