def most_frequent_element(lst):
    """
    Finds the most frequent element in a list.
    If there is a tie, returns the first one encountered.

    Parameters:
    lst (list): A list of elements.

    Returns:
    The most frequent element in the list.
    """
    if not lst:
        return None

    frequency = {}
    max_frequency = 0
    most_frequent = lst[0]

    for item in lst:
        if item in frequency:
            frequency[item] += 1
        else:
            frequency[item] = 1

        if frequency[item] > max_frequency:
            max_frequency = frequency[item]
            most_frequent = item
        elif frequency[item] == max_frequency and lst.index(item) < lst.index(most_frequent):
            most_frequent = item

    return most_frequent

