def factorial(n):
    """
    Returns the factorial of a non-negative integer n.
    If n is negative, raises a ValueError.
    """
    if n < 0:
        raise ValueError("Input must be non-negative.")
    elif n == 0:
        return 1
    else:
        result = 1
        for i in range(1, n + 1):
            result *= i
        return result

