def sieve_of_eratosthenes(n):
    """
    Returns the first n prime numbers using the Sieve of Eratosthenes algorithm.
    """
    if n <= 0:
        return []

    def nth_upper_bound(n):
        """Estimate the upper bound for the nth prime using the nth prime approximation"""
        if n < 6:
            return 15
        from math import log
        return int(n * (log(n) + log(log(n))) + 10)

    upper_bound = nth_upper_bound(n)
    sieve = [True] * (upper_bound + 1)
    sieve[0] = sieve[1] = False  # 0 and 1 are not primes
    p = 2

    while p ** 2 <= upper_bound:
        if sieve[p]:
            for i in range(p * p, upper_bound + 1, p):
                sieve[i] = False
        p += 1

    primes = [i for i, is_prime in enumerate(sieve) if is_prime]

    return primes[:n]

