def nth_fibonacci(n):
    """
    Returns the Nth Fibonacci number using recursion.
    """
    if n <= 0:
        raise ValueError("n must be a positive integer.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        return nth_fibonacci(n - 1) + nth_fibonacci(n - 2)

# Improved version with memoization
def nth_fibonacci_memo(n, memo=None):
    """
    Returns the Nth Fibonacci number using recursion with memoization.
    """
    if memo is None:
        memo = {}

    if n <= 0:
        raise ValueError("n must be a positive integer.")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        if n not in memo:
            memo[n] = nth_fibonacci_memo(n - 1, memo) + nth_fibonacci_memo(n - 2, memo)
        return memo[n]

def find_first_last_occurrence(arr, n, x):
    """
    Returns the first and last occurrence of x in the sorted array arr.
    If x is not found, returns (-1, -1).
    """
    def find_first(arr, n, x):
        low, high = 0, n - 1
        first_occurrence = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == x:
                first_occurrence = mid
                high = mid - 1
            elif arr[mid] < x:
                low = mid + 1
            else:
                high = mid - 1
        return first_occurrence

    def find_last(arr, n, x):
        low, high = 0, n - 1
        last_occurrence = -1
        while low <= high:
            mid = (low + high) // 2
            if arr[mid] == x:
                last_occurrence = mid
                low = mid + 1
            elif arr[mid] < x:
                low = mid + 1
            else:
                high = mid - 1
        return last_occurrence

    first = find_first(arr, n, x)
    last = find_last(arr, n, x)
    return (first, last)

