def merge_sort_desc(lst):
    """
    Sorts the given list in descending order using the merge sort algorithm.
    """
    if len(lst) <= 1:
        return lst

    mid = len(lst) // 2
    left_half = merge_sort_desc(lst[:mid])
    right_half = merge_sort_desc(lst[mid:])

    return merge_desc(left_half, right_half)

def merge_desc(left, right):
    """
    Merges two lists into one in descending order.
    """
    result = []
    while left and right:
        if left[0] > right[0]:
            result.append(left.pop(0))
        else:
            result.append(right.pop(0))

    result.extend(left)
    result.extend(right)

    return result

