def factorial_iterative(n, mod=None):
    """
    Returns the factorial of n using iterative method.
    Optionally uses modulus operation for large numbers.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")

    result = 1
    for i in range(1, n + 1):
        result *= i
        if mod is not None:
            result %= mod
    return result

def factorial_recursive(n):
    """
    Returns the factorial of n using recursive method.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")

    if n == 0 or n == 1:
        return 1
    else:
        return n * factorial_recursive(n - 1)

