def sieve_of_eratosthenes(start, end):
    """
    Generates a list of prime numbers within the given range [start, end] using the Sieve of Eratosthenes algorithm.
    """
    if start > end:
        return []

    # Initialize a boolean array indicating the primality of each number
    sieve = [True] * (end + 1)
    p = 2

    while (p * p <= end):
        if sieve[p]:
            for i in range(p * p, end + 1, p):
                sieve[i] = False
        p += 1

    primes = [p for p in range(max(2, start), end + 1) if sieve[p]]
    return primes

