def sieve_of_eratosthenes(num):
    """
    Returns a list of all prime numbers less than or equal to `num` using the Sieve of Eratosthenes algorithm.
    """
    if num < 2:
        return []

    is_prime = [True] * (num + 1)
    p = 2
    while (p * p <= num):
        if (is_prime[p] == True):
            for i in range(p * p, num + 1, p):
                is_prime[i] = False
        p += 1
    primes = [p for p in range(2, num + 1) if is_prime[p]]
    return primes

