def has_cycle(graph):
    """
    Detects if there is a cycle in a directed graph using DFS.

    :param graph: Dictionary representing an adjacency list of the directed graph
                  {node: [list of adjacent nodes]}
    :return: True if there is a cycle, False otherwise
    """
    def dfs(node):
        nonlocal has_cycle
        if node in visiting:
            has_cycle = True
            return
        if node in visited:
            return

        visiting.add(node)
        for neighbour in graph.get(node, []):
            dfs(neighbour)
        visiting.remove(node)
        visited.add(node)

    visited = set()
    visiting = set()
    has_cycle = False

    for node in graph:
        if node not in visited:
            dfs(node)
            if has_cycle:
                break

    return has_cycle

