def find_values_with_max_at_least_k(nums, k):
    """
    Returns a list of values from the array `nums` where the maximum element is at least `k`.
    """
    if not nums:
        return []
    max_val = max(nums)
    if max_val < k:
        return []
    return [num for num in nums if num >= k]

