def find_max_and_min(arr):
    """
    Returns a tuple containing the maximum and minimum value in the array.

    Parameters:
    arr (list): List of integers

    Returns:
    tuple: (max_value, min_value)
    """
    if not arr:
        raise ValueError("Array cannot be empty")

    max_value = arr[0]
    min_value = arr[0]

    for number in arr[1:]:
        if number > max_value:
            max_value = number
        if number < min_value:
            min_value = number

    return (max_value, min_value)

