def find_duplicates(arr):
    """
    Returns a list of elements that appear more than once in the input array.

    :param arr: List of elements
    :type arr: List[int]
    :return: List of duplicate elements
    :rtype: List[int]
    """
    element_count = {}
    duplicates = []

    for elem in arr:
        if elem in element_count:
            element_count[elem] += 1
        else:
            element_count[elem] = 1

    for elem, count in element_count.items():
        if count > 1:
            duplicates.append(elem)

    return duplicates

