def merge_multi_dimensional_list(multi_list):
    """
    Merges all the elements of a multi-dimensional list into a single list without using the append() method.
    """
    if not multi_list:
        return []

    result = []
    for element in multi_list:
        if isinstance(element, list):
            result.extend(merge_multi_dimensional_list(element))
        else:
            result.extend([element])

    return result

