def find_min_max_recursive(lst, min_val=None, max_val=None, index=0):
    """
    Returns a tuple (min_val, max_val) for the given list using recursion.
    """
    # Base case: if the list is empty
    if len(lst) == 0:
        return (None, None)

    # Initialization in the first call
    if index == 0:
        min_val = lst[0]
        max_val = lst[0]

    # Base case: when all elements have been processed
    if index == len(lst):
        return (min_val, max_val)

    # Update min and max values
    current_value = lst[index]
    if current_value < min_val:
        min_val = current_value
    if current_value > max_val:
        max_val = current_value

    # Recursive call for the next element
    return find_min_max_recursive(lst, min_val, max_val, index + 1)

