def nth_power_prime(base, exponent):
    """
    Returns the Nth power of a number if N is a prime number.
    """
    def is_prime(num):
        """Helper function to check if a number is prime."""
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    if not is_prime(exponent):
        raise ValueError("The exponent must be a prime number.")

    return base ** exponent

