def caesar_cipher_encrypt(text, shift):
    """
    Encrypts the given text using Caesar cipher with the specified shift.

    Parameters:
    text (str): the text to be encrypted.
    shift (int): the shift value for the cipher.

    Returns:
    str: the encrypted text.
    """
    result = []

    for char in text:
        if char.isupper():
            result.append(chr((ord(char) + shift - 65) % 26 + 65))
        elif char.islower():
            result.append(chr((ord(char) + shift - 97) % 26 + 97))
        else:
            result.append(char)

    return ''.join(result)

