def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def sum_primes_in_range(start, end):
    """
    Returns the sum of all prime numbers in the given range [start, end].
    """
    total = 0
    for num in range(start, end + 1):
        if is_prime(num):
            total += num
    return total

