def check_divisible_by_5(n):
    """
    Recursively checks if a number is divisible by 5, counting downward.
    If n becomes 1, return 1.
    If n is divisible by 5, return 0.
    If neither condition is met, return 2.
    """
    # Base case: if n is divisible by 5
    if n % 5 == 0:
        return 0
    # Base case: if n becomes 1
    elif n == 1:
        return 1
    # Recursively count downward
    else:
        return check_divisible_by_5(n - 1)

