def fibonacci(length):
    """
    Returns a list of Fibonacci numbers up to the given length.
    """
    if length <= 0:
        return []
    elif length == 1:
        return [0]
    elif length == 2:
        return [0, 1]

    fib_list = [0, 1]
    for i in range(2, length):
        fib_list.append(fib_list[-1] + fib_list[-2])

    return fib_list

