def fibonacci_squares(n):
    """
    Returns a list of the first n Fibonacci numbers, each squared.
    """
    if n <= 0:
        return []

    def fibonacci(num):
        if num == 0:
            return 0
        elif num == 1:
            return 1
        else:
            return fibonacci(num - 1) + fibonacci(num - 2)

    return [(fibonacci(i) ** 2) for i in range(n)]

