def find_maximum(numbers):
    """
    Returns the maximum element in the list 'numbers'.
    If the list is empty, returns None.
    If the list contains non-numeric elements, gracefully handles them by ignoring them.
    """
    if not numbers:
        return None

    max_number = None
    for num in numbers:
        try:
            num = float(num)  # Attempt to convert to float to handle numeric strings
            if max_number is None or num > max_number:
                max_number = num
        except ValueError:
            # Ignore non-numeric elements
            continue

    return max_number

