def factorial(n):
    """
    Returns the factorial of a given number n.
    If n is not a non-negative integer, returns None.
    """
    if not isinstance(n, int) or n < 0:
        return None

    if n == 0 or n == 1:
        return 1

    result = 1
    for i in range(2, n + 1):
        result *= i

    return result

