def has_cycle(graph):
    """
    Detects if there is a cycle in an undirected graph using DFS.
    The graph is represented as an adjacency list.

    :param graph: List[List[int]], adjacency list of the graph
    :return: bool, True if there is a cycle, False otherwise
    """
    def dfs(node, parent):
        visited[node] = True
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if dfs(neighbor, node):
                    return True
            elif neighbor != parent:
                return True
        return False

    visited = [False] * len(graph)

    for node in range(len(graph)):
        if not visited[node]:
            if dfs(node, -1):
                return True
    return False

def longest_palindromic_substring_length(s):
    """
    Returns the length of the longest palindromic substring in the given string s.
    """
    if not s:
        return 0

    n = len(s)
    dp = [[False] * n for _ in range(n)]
    max_length = 1

    for i in range(n):
        dp[i][i] = True

    start = 0
    for i in range(n-1):
        if s[i] == s[i+1]:
            dp[i][i+1] = True
            start = i
            max_length = 2

    for k in range(3, n+1):
        for i in range(n - k + 1):
            j = i + k - 1
            if dp[i+1][j-1] and s[i] == s[j]:
                dp[i][j] = True
                start = i
                max_length = k

    return max_length

