def number_of_communities(adj_list):
    """
    Returns the number of connected components in the graph.

    :param adj_list: Dictionary where keys are nodes and values are lists of connected nodes
    :return: Number of connected components (communities)
    """
    def dfs(node, visited):
        stack = [node]
        while stack:
            curr = stack.pop()
            for neighbor in adj_list.get(curr, []):
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    visited = set()
    count = 0

    for node in adj_list:
        if node not in visited:
            dfs(node, visited)
            count += 1

    return count

