def find_second_largest(numbers):
    """
    Finds the second largest number in a list. If the second largest number does not exist,
    returns None.
    """
    if len(numbers) < 2:
        return None

    first = second = float('-inf')

    for number in numbers:
        if number > first:
            second = first
            first = number
        elif first > number > second:
            second = number

    return second if second != float('-inf') else None

