def count_substrings_with_at_most_k_distinct(s, k):
    """
    Given a string s and an integer k, returns the count of substrings containing at most k distinct characters.
    """
    n = len(s)
    if n == 0 or k == 0:
        return 0

    start = 0
    end = 0
    count = 0
    char_map = {}

    while end < n:
        if s[end] in char_map:
            char_map[s[end]] += 1
        else:
            char_map[s[end]] = 1

        while len(char_map) > k:
            char_map[s[start]] -= 1
            if char_map[s[start]] == 0:
                del char_map[s[start]]
            start += 1

        count += end - start + 1
        end += 1

    return count

