def num_multiples_of_3_4(start, end):
    """
    Returns the number of integers within a given range [start, end] that are multiples of both 3 and 4.
    """
    count = 0
    for i in range(start, end + 1):
        if i % 3 == 0 and i % 4 == 0:
            count += 1
    return count

