def find_duplicates(elements):
    """
    Returns a list of duplicate elements in the input list.
    """
    seen = set()
    duplicates = set()

    for element in elements:
        if element in seen:
            duplicates.add(element)
        else:
            seen.add(element)

    return list(duplicates)

