def is_perfect_square(n):
    """
    Returns True if n is a perfect square, otherwise False.
    Uses binary search to determine if a number is a perfect square.
    """
    if n < 0:
        return False
    if n in (0, 1):
        return True

    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        square = mid * mid
        if square == n:
            return True
        elif square < n:
            low = mid + 1
        else:
            high = mid - 1
    return False

