def sum_nested(data):
    """
    Recursively sums all numbers in a nested dictionary, where numbers can be within
    dictionaries or lists within the dictionary.
    """
    if isinstance(data, dict):
        return sum(sum_nested(value) for value in data.values())
    elif isinstance(data, list):
        return sum(sum_nested(item) for item in data)
    elif isinstance(data, (int, float)):
        return data
    else:
        return 0

