def primes_up_to(n):
    """
    Prints all prime numbers up to a given number n.
    """
    if n < 2:
        return []

    primes = []
    is_prime = [True] * (n + 1)

    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False

    return primes

# Time Complexity: O(n log log n)
# Space Complexity: O(n)

