def find_min_max_elements(lists):
    """
    Find the minimum and maximum elements in a list of lists.

    Args:
    lists (list of lists): A list containing sub-lists.

    Returns:
    tuple: A tuple containing the minimum and maximum elements found in any of the sub-lists.
    """
    if not lists:
        return (None, None)

    min_element = float('inf')
    max_element = float('-inf')

    for sublist in lists:
        if sublist:
            min_element = min(min_element, min(sublist))
            max_element = max(max_element, max(sublist))

    min_element = min_element if min_element != float('inf') else None
    max_element = max_element if max_element != float('-inf') else None

    return (min_element, max_element)

