def recursive_add(a, b):
    """
    Adds two numbers a and b using recursion.
    """
    if b == 0:
        return a
    elif b > 0:
        return recursive_add(a + 1, b - 1)
    else:  # b < 0
        return recursive_add(a - 1, b + 1)

