import math

def smallest_multiple(n):
    """
    Returns the smallest positive integer that is evenly divisible by all numbers from 1 to n.
    """
    def lcm(a, b):
        return a * b // math.gcd(a, b)

    smallest_mult = 1
    for i in range(1, n + 1):
        smallest_mult = lcm(smallest_mult, i)

    return smallest_mult

