def count_factors(n):
    """
    Returns the number of factors of the given number n.
    """
    if n <= 0:
        return 0

    count = 0
    for i in range(1, int(n ** 0.5) + 1):
        if n % i == 0:
            count += 2 if i != n // i else 1

    return count

