def sum_of_digits_even_numbers(number_list):
    """
    Returns the sum of the digits of all even numbers in a given list.

    Parameters:
    number_list (list): List of integers.

    Returns:
    int: Sum of the digits of all even numbers.
    """
    def sum_digits(n):
        return sum(int(digit) for digit in str(abs(n)))

    even_numbers = [number for number in number_list if number % 2 == 0]
    return sum(sum_digits(number) for number in even_numbers)

