def levenshtein_similarity(doc1, doc2):
    """
    Returns the similarity between two documents based on their Levenshtein distance
    as a percentage.
    """
    def levenshtein_distance(s1, s2):
        if len(s1) < len(s2):
            return levenshtein_distance(s2, s1)
        if len(s2) == 0:
            return len(s1)
        previous_row = range(len(s2) + 1)
        for i, c1 in enumerate(s1):
            current_row = [i + 1]
            for j, c2 in enumerate(s2):
                insertions = previous_row[j + 1] + 1
                deletions = current_row[j] + 1
                substitutions = previous_row[j] + (c1 != c2)
                current_row.append(min(insertions, deletions, substitutions))
            previous_row = current_row

        return previous_row[-1]

    lev_distance = levenshtein_distance(doc1, doc2)
    max_len = max(len(doc1), len(doc2))
    similarity_percentage = ((max_len - lev_distance) / max_len) * 100 if max_len != 0 else 100

    return similarity_percentage

