def is_palindrome_recursive(num):
    """
    Returns whether a given number is a palindrome using recursion.
    """
    num_str = str(num)

    def helper(s, start, end):
        if start >= end:
            return True
        if s[start] != s[end]:
            return False
        return helper(s, start + 1, end - 1)

    return helper(num_str, 0, len(num_str) - 1)

