def has_subsequence_with_sum(nums, target):
    """
    Returns True if there exists a subsequence in nums that sums to target, otherwise False.
    """
    def find_subsequence(index, current_sum):
        if current_sum == target:
            return True
        if index == len(nums):
            return False
        return find_subsequence(index + 1, current_sum + nums[index]) or find_subsequence(index + 1, current_sum)

    return find_subsequence(0, 0)

import math

def is_perfect_power(n):
    """
    Returns True if n is a perfect power, otherwise False.
    A number n is a perfect power if there exist positive integers x and k such that n = x^k.
    """
    if n < 2:
        return False

    max_base = int(math.sqrt(n))
    for base in range(2, max_base + 1):
        power = 2  # Start with the square of base
        while (result := base ** power) <= n:
            if result == n:
                return True
            power += 1

    return False

