def caesar_cipher_encrypt(plain_text, shift):
    """
    Encrypts the plain_text using Caesar Cipher with the given shift.
    """
    encrypted_text = []
    for char in plain_text:
        if char.isalpha():
            shift_base = 65 if char.isupper() else 97
            encrypted_text.append(chr((ord(char) - shift_base + shift) % 26 + shift_base))
        else:
            encrypted_text.append(char)
    return ''.join(encrypted_text)

def caesar_cipher_decrypt(cipher_text, shift):
    """
    Decrypts the cipher_text using Caesar Cipher with the given shift.
    """
    return caesar_cipher_encrypt(cipher_text, -shift)

