def four_sum(nums, target):
    """
    Finds all unique quadruplets in the list 'nums' that sum up to the 'target'.

    Parameters:
    nums (list): The list of integers.
    target (int): The target sum for the quadruplets.

    Returns:
    list: A list of lists, where each sublist is a unique quadruplet that sums up to the target.
    """
    nums.sort()
    results = []
    length = len(nums)

    for i in range(length - 3):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        for j in range(i + 1, length - 2):
            if j > i + 1 and nums[j] == nums[j - 1]:
                continue
            left, right = j + 1, length - 1
            while left < right:
                quad_sum = nums[i] + nums[j] + nums[left] + nums[right]
                if quad_sum == target:
                    results.append([nums[i], nums[j], nums[left], nums[right]])
                    while left < right and nums[left] == nums[left + 1]:
                        left += 1
                    while left < right and nums[right] == nums[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif quad_sum < target:
                    left += 1
                else:
                    right -= 1
    return results

