def remove_duplicates_and_count(s):
    """
    Removes repeated characters from the string while preserving the original order
    and returns a tuple containing the resulting string and the count of unique characters.
    """
    seen = set()
    result = []
    for char in s:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result), len(result)

