from collections import deque

def shortest_distance(matrix):
    rows = len(matrix)
    cols = len(matrix[0])
    distance = [[float('inf')] * cols for _ in range(rows)]

    queue = deque()

    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 0:
                queue.append((r, c))
                distance[r][c] = 0

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    while queue:
        r, c = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if distance[nr][nc] > distance[r][c] + 1:
                    distance[nr][nc] = distance[r][c] + 1
                    queue.append((nr, nc))

    min_distance = float('inf')

    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 1:
                min_distance = min(min_distance, distance[r][c])

    return min_distance if min_distance != float('inf') else -1

