def is_perfect_square(num):
    """
    Checks if a number is a perfect square. Returns the square root if true, otherwise -1.

    Parameters:
    num (int): The number to check

    Returns:
    int: The square root if it's a perfect square, otherwise -1
    """
    if num < 0:
        return -1
    if num == 0:
        return 0

    start, end = 1, num
    while start <= end:
        mid = (start + end) // 2
        square = mid * mid

        if square == num:
            return mid
        elif square < num:
            start = mid + 1
        else:
            end = mid - 1

    return -1

