def fib(n, memo={}):
    """
    Returns the nth term of the Fibonacci sequence using recursion with memoization.
    """
    if n in memo:
        return memo[n]
    if n <= 1:
        memo[n] = n
    else:
        memo[n] = fib(n-1, memo) + fib(n-2, memo)

    return memo[n]

def binary_search(arr, target):
    """
    Perform binary search to find the target in a sorted array.
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = left + (right - left) // 2
        if arr[mid] == target:
            return True
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return False

def intersection_of_sorted_arrays(A, B):
    """
    Find the intersection of two sorted arrays A and B.
    """
    C = []
    for element in A:
        if binary_search(B, element) and element not in C:
            C.append(element)
    return C

