def sum_of_primes_below(n):
    """
    Calculate the sum of all prime numbers less than n.

    Parameters:
    n (int): the upper limit to calculate the sum of primes below

    Returns:
    int: the sum of all primes below n
    """
    if n <= 2:
        return 0

    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False

    p = 2
    while p * p < n:
        if is_prime[p]:
            for i in range(p * p, n, p):
                is_prime[i] = False
        p += 1

    return sum(i for i, prime in enumerate(is_prime) if prime)

