def is_sorted(arr):
    """
    Returns True if the array is sorted in non-decreasing order, otherwise returns False.
    """
    if len(arr) < 2:
        return True
    for i in range(len(arr) - 1):
        if arr[i] > arr[i + 1]:
            return False
    return True

