def remove_duplicates(nums):
    """
    Remove duplicates from an unsorted list in-place without using any extra space.

    :param nums: List[int] -- The list from which to remove duplicates.
    :return: List[int] -- The modified list with duplicates removed.
    """
    if not nums:
        return nums

    index = 0
    while index < len(nums):
        current_num = nums[index]
        next_index = index + 1
        while next_index < len(nums):
            if nums[next_index] == current_num:
                nums.pop(next_index)
            else:
                next_index += 1
        index += 1
    return nums

