def is_valid_isbn10(isbn):
    """
    Checks if a given string is a valid ISBN-10 number.
    """
    if len(isbn) != 10:
        return False

    total = 0
    for i in range(10):
        if isbn[i] == 'X' and i == 9:
            value = 10
        elif '0' <= isbn[i] <= '9':
            value = int(isbn[i])
        else:
            return False
        total += value * (i + 1)

    return total % 11 == 0

