def bubble_sort_names(names_list):
    """
    Sort a list of names using bubble sort algorithm.

    :param names_list: List of names to be sorted
    :return: Sorted list of names in ascending order
    """
    n = len(names_list)
    for i in range(n):
        for j in range(0, n - i - 1):
            if names_list[j] > names_list[j + 1]:
                names_list[j], names_list[j + 1] = names_list[j + 1], names_list[j]
    return names_list

