def count_distinct_substrings(s):
    """
    Counts the number of substrings in the given string that contain all distinct characters.

    Parameters:
    s (str): The input string

    Returns:
    int: The number of substrings with all distinct characters
    """
    def has_all_unique_chars(sub):
        return len(set(sub)) == len(sub)

    count = 0
    for i in range(len(s)):
        for j in range(i + 1, len(s) + 1):
            if has_all_unique_chars(s[i:j]):
                count += 1
    return count

