def find_max_min(numbers):
    """
    Returns a tuple containing the maximum and minimum values in the list of numbers.

    Parameters:
    numbers (list): A list of numbers.

    Returns:
    tuple: A tuple containing the maximum and minimum values.
    """
    if not numbers:
        raise ValueError("The list is empty")

    max_val = numbers[0]
    min_val = numbers[0]

    for num in numbers[1:]:
        if num > max_val:
            max_val = num
        if num < min_val:
            min_val = num

    return (max_val, min_val)

