def find_unique_numbers(nums):
    """
    Returns the two unique numbers in a list where every other number appears twice.
    """
    xor_result = 0
    for num in nums:
        xor_result ^= num

    # Get the rightmost set bit in xor_result (a bit which is 1)
    set_bit = xor_result & -xor_result

    unique1, unique2 = 0, 0
    for num in nums:
        if num & set_bit:
            unique1 ^= num
        else:
            unique2 ^= num

    return (unique1, unique2)

