def nth_prime(n):
    """
    Returns the nth prime number.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    primes = []
    candidate = 2

    while len(primes) < n:
        for prime in primes:
            if candidate % prime == 0:
                break
        else:
            primes.append(candidate)
        candidate += 1

    return primes[-1]

