def first_unique_character(s):
    """
    This function returns the first unique character (appears only once)
    in the given string. If no unique character exists, it returns '_'.
    """
    freq = {}

    # Count the occurrences of each character
    for char in s:
        freq[char] = freq.get(char, 0) + 1

    # Find the first character that appears only once
    for char in s:
        if freq[char] == 1:
            return char

    return '_'

