def count_occurrences(elements):
    """
    Returns a dictionary with the count of each element in the given list.

    :param elements: List of elements to count occurrences for
    :return: Dictionary with elements as keys and their count as values
    """
    occurrence_dict = {}
    for element in elements:
        if element in occurrence_dict:
            occurrence_dict[element] += 1
        else:
            occurrence_dict[element] = 1
    return occurrence_dict

