def max_profit(prices):
    """
    Determines the maximum profit that can be made by buying and selling a stock.

    :param prices: List[int] - List of stock prices where each element is the price on a given day.
    :return: int - The maximum profit possible
    """
    if not prices:
        return 0

    max_profit = 0
    for i in range(1, len(prices)):
        if prices[i] > prices[i - 1]:
            max_profit += prices[i] - prices[i - 1]

    return max_profit

