def sort_array_via_swapping(arr):
    """
    Sorts an array of integers in ascending order using only swapping operations.
    """
    n = len(arr)

    # Bubble sort algorithm that uses only swapping for sorting
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                # Swapping elements
                arr[j], arr[j+1] = arr[j+1], arr[j]

    return arr

