def max_sum_three_distinct_subarrays(arr):
    n = len(arr)
    if n < 3:
        return "Array should have at least 3 elements"

    max_sum = float('-inf')

    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                curr_sum = arr[i] + arr[j] + arr[k]
                if curr_sum > max_sum:
                    max_sum = curr_sum

    return max_sum

