def max_length_valid_parentheses(s):
    """
    Returns the maximum length of a valid parentheses substring.
    """
    stack = []
    max_length = 0
    last_invalid = -1

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:  # char == ')'
            if not stack:
                last_invalid = i
            else:
                stack.pop()
                if not stack:
                    max_length = max(max_length, i - last_invalid)
                else:
                    max_length = max(max_length, i - stack[-1])

    return max_length

