def basic_calculator(operations):
    """
    Performs the given operations in the order they are provided.

    Parameters:
    operations (list): A list of tuples, where each tuple contains an operation
                       ('+', '-', '*', '/') and two operands.

    Returns:
    list: A list of results corresponding to each operation.
    """
    results = []
    for operation in operations:
        if len(operation) != 3:
            raise ValueError("Each operation must be a tuple of length 3")

        op, a, b = operation
        if op == '+':
            results.append(a + b)
        elif op == '-':
            results.append(a - b)
        elif op == '*':
            results.append(a * b)
        elif op == '/':
            if b == 0:
                raise ValueError("Division by zero is not allowed")
            results.append(a / b)
        else:
            raise ValueError(f"Unsupported operation: {op}")

    return results

