def count_edges(adj_matrix):
    """
    Calculate the number of edges in a graph represented by an adjacency matrix.

    :param adj_matrix: List of lists representing the adjacency matrix of the graph
    :return: Integer number of edges in the graph
    """
    num_edges = 0
    for i in range(len(adj_matrix)):
        for j in range(i, len(adj_matrix[i])):
            if adj_matrix[i][j] != 0:
                num_edges += 1
    return num_edges

