def second_max(numbers):
    """
    Returns the second maximum value from the list of numbers.
    If the list contains fewer than two distinct numbers, returns None.
    """
    if len(numbers) < 2:
        return None

    first_max = second_max = float('-inf')
    for number in numbers:
        if number > first_max:
            second_max, first_max = first_max, number
        elif first_max > number > second_max:
            second_max = number

    return second_max if second_max != float('-inf') else None

