def solve_n_queens(n):
    def create_board(state):
        board = []
        for row in state:
            board.append("".join("Q" if i == row else "." for i in range(n)))
        return board

    def is_valid_state(state):
        current_queen_row, current_queen_col = len(state) - 1, state[-1]
        for row, col in enumerate(state[:-1]):
            diff = abs(current_queen_col - col)
            if diff == 0 or diff == current_queen_row - row:
                return False
        return True

    def search(state):
        if len(state) == n:
            solutions.append(create_board(state))
            return

        for col in range(n):
            state.append(col)
            if is_valid_state(state):
                search(state)
            state.pop()

    solutions = []
    search([])
    return solutions

