def max_length_subarray_with_sum(nums, target):
    """
    Returns the length of the largest subarray with a sum equal to the target.
    If no such subarray exists, returns -1.
    """
    sum_indices = {}
    current_sum = 0
    max_len = -1

    for i, num in enumerate(nums):
        current_sum += num

        if current_sum == target:
            max_len = i + 1

        if (current_sum - target) in sum_indices:
            max_len = max(max_len, i - sum_indices[current_sum - target])

        if current_sum not in sum_indices:
            sum_indices[current_sum] = i

    return max_len

