def find_min_max(numbers):
    """
    Returns the minimum and maximum number in the list as a tuple (min_num, max_num).
    """
    if not numbers:
        raise ValueError("The list must not be empty.")

    min_num = float('inf')
    max_num = float('-inf')

    for number in numbers:
        if number < min_num:
            min_num = number
        if number > max_num:
            max_num = number

    return min_num, max_num

