def list_to_dict(lst):
    """
    Converts a list of strings into a dictionary where the keys are the strings
    and the values are their corresponding indices in the list.
    If a string appears more than once in the list, store an empty list as its value.
    If the list is empty, return an empty dictionary.
    """
    result = {}
    for i, s in enumerate(lst):
        if s in result:
            result[s] = []
        else:
            result[s] = [i]
    return {k: v if v != [] else [] for k, v in result.items()}

