def find_zero_sum_vectors(grid, size):
    """
    Returns all 2D vectors in the given 2D grid which sum up to zero.

    Args:
    grid (list of list of int): 2D grid of integers
    size (int): The number of rows and columns in the grid

    Returns:
    list of tuples: Each tuple represents a pair of coordinates whose elements sum to zero
    """
    zero_sum_vectors = []

    for i in range(size):
        for j in range(size):
            for k in range(i, size):
                for l in range(j if i == k else 0, size):
                    if (i != k or j != l) and (grid[i][j] + grid[k][l] == 0):
                        zero_sum_vectors.append(((i, j), (k, l)))

    return zero_sum_vectors

