def frequency_dict(elements):
    """
    Returns a dictionary where keys are elements from the
    input list and values are their respective frequencies.

    :param elements: List of elements
    :return: Dictionary with element frequencies
    """
    freq_dict = {}
    for element in elements:
        if element in freq_dict:
            freq_dict[element] += 1
        else:
            freq_dict[element] = 1
    return freq_dict

