def find_local_minimum(arr):
    """
    Returns the first local minimum value in a list.

    A local minimum is defined as an element which is less than or equal to its neighbors (if they exist).

    :param arr: List of integers
    :return: The first local minimum value found, or None if no local minimum exists
    """
    n = len(arr)
    if n == 0:
        return None
    elif n == 1:
        return arr[0]

    # Check the first and last elements separately
    if arr[0] <= arr[1]:
        return arr[0]
    if arr[n-1] <= arr[n-2]:
        return arr[n-1]

    # Check the rest of the elements
    for i in range(1, n-1):
        if arr[i] <= arr[i-1] and arr[i] <= arr[i+1]:
            return arr[i]

    return None

