def remove_duplicates(input_string):
    """
    Removes duplicate characters from the input string while preserving the order
    of characters. It returns a string with unique characters only.
    """
    seen = set()
    result = []
    for char in input_string:
        if char not in seen:
            seen.add(char)
            result.append(char)
    return ''.join(result)

