def int_to_binary(n):
    """
    Returns the binary representation of an integer as a string.
    """
    if n == 0:
        return "0b0"
    elif n < 0:
        return "-0b" + bin(-n)[2:]
    else:
        return "0b" + bin(n)[2:]

def is_non_iterable(element):
    """ Check if the element is non-iterable (besides strings). """
    return isinstance(element, (int, float, complex, bool, bytes, type(None)))

def flatten(nested_list):
    """
    Flattens a nested list. Non-iterable elements are left unchanged.
    Dictionaries are unpacked into tuples of (key, value) pairs.
    """
    if is_non_iterable(nested_list) or isinstance(nested_list, str):
        return [nested_list]

    flattened_list = []
    stack = [nested_list]

    while stack:
        current = stack.pop()

        if isinstance(current, dict):
            for key, value in current.items():
                flattened_list.append((key, value))
        elif isinstance(current, list):
            for item in reversed(current):
                stack.append(item)
        else:
            flattened_list.append(current)

    return flattened_list

