def is_prime(number):
    """
    Returns True if the number is prime, otherwise False.
    If the number is not an integer, raises a ValueError.
    If the number is less than 2, raises a ValueError.
    """
    if not isinstance(number, int):
        raise ValueError("Input must be an integer.")
    if number < 2:
        raise ValueError("Number must be greater than or equal to 2 to be considered for prime.")

    for i in range(2, int(number**0.5) + 1):
        if number % i == 0:
            return False
    return True

