def first_unique_char(s):
    """
    Returns the first unique character in the string s.
    If all characters are repeated, returns -1.
    """
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s:
        if char_count[char] == 1:
            return char

    return -1

