def sum_even_odd(numbers):
    """
    Returns a dictionary with the sum of all even numbers and all odd numbers in the given list.

    Parameters:
    numbers (list): A list of integers.

    Returns:
    dict: A dictionary with keys "even" and "odd" and their corresponding sums as values.
    """
    sums = {'even': 0, 'odd': 0}
    for number in numbers:
        if number % 2 == 0:
            sums['even'] += number
        else:
            sums['odd'] += number
    return sums

