import re

def is_valid_hex_color(hex_color):
    """
    Returns True if hex_color is a valid hexadecimal color code, else False.
    A valid hexadecimal color code starts with '#' followed by exactly six hex digits.
    """
    if not isinstance(hex_color, str):
        return False

    pattern = r'^#[0-9A-Fa-f]{6}$'
    return bool(re.match(pattern, hex_color))

