def find_max_min(arr):
    """
    Returns the maximum and minimum value in an array as a tuple.

    Parameters:
    arr (list of numbers): The input array containing numbers.

    Returns:
    tuple: A tuple containing (maximum, minimum) values from the array.
    """
    if not arr:
        raise ValueError("Array cannot be empty")

    max_val = arr[0]
    min_val = arr[0]

    for num in arr:
        if num > max_val:
            max_val = num
        if num < min_val:
            min_val = num

    return (max_val, min_val)

