def find_slope(x1, y1, x2, y2):
    """
    Returns the slope of the line passing through the points (x1, y1) and (x2, y2).
    If the line is vertical (x1 == x2), the slope is undefined and the function returns None.
    """
    if x1 == x2:
        return None
    return (y2 - y1) / (x2 - x1)

