def is_prime(num):
    """
    Helper function to check if a number is prime.
    """
    if num <= 1:
        return False
    for i in range(2, int(num**(0.5)) + 1):
        if num % i == 0:
            return False
    return True

def prime_pairs_sum(N):
    """
    Returns a list of all pairs of prime numbers that sum up to N.
    If no such pairs exist, returns an empty list.
    """
    if N % 2 != 0 or N < 2:
        return "No such pair exists"

    primes = [i for i in range(2, N) if is_prime(i)]
    pairs = []

    for pr in primes:
        if is_prime(N - pr) and (N - pr, pr) not in pairs:
            pairs.append((pr, N - pr))

    if pairs:
        return pairs
    else:
        return "No such pair exists"

