def multiplication_table(n):
    """
    Returns the multiplication table of the given number n in string format.
    Each line of the table contains 'n * i = result' for i from 1 to 10.
    """
    table = ""
    for i in range(1, 11):
        table += f"{n} * {i} = {n * i}\n"
    return table.strip()

