def search_2d_matrix(matrix, target):
    """
    Returns True if target exists in the 2D sorted array, otherwise False.

    :param matrix: List[List[int]], a 2D list where each row and column are sorted.
    :param target: int, the target value to search for in the matrix.
    :return: bool, True if target is found in the matrix, otherwise False.
    """
    if not matrix or not matrix[0]:
        return False

    rows, cols = len(matrix), len(matrix[0])
    row, col = 0, cols - 1

    while row < rows and col >= 0:
        if matrix[row][col] == target:
            return True
        elif matrix[row][col] < target:
            row += 1
        else:
            col -= 1

    return False

