def sieve_of_eratosthenes(lower_bound, upper_bound):
    """
    Returns a list of prime numbers between lower_bound and upper_bound using the Sieve of Eratosthenes algorithm.
    """
    if lower_bound > upper_bound:
        return []

    sieve = [True] * (upper_bound + 1)
    sieve[0] = sieve[1] = False

    for start in range(2, int(upper_bound ** 0.5) + 1):
        if sieve[start]:
            for multiple in range(start * start, upper_bound + 1, start):
                sieve[multiple] = False

    primes = [num for num in range(max(2, lower_bound), upper_bound + 1) if sieve[num]]
    return primes

