def count_pairs_with_sum(nums, target_sum):
    """
    Returns the number of pairs in nums that add up to target_sum.

    Args:
    nums (list): List of integers.
    target_sum (int): The target sum for the pairs.

    Returns:
    int: The number of pairs that add up to target_sum.
    """
    count = 0
    num_dict = {}

    for num in nums:
        complement = target_sum - num
        if complement in num_dict and num_dict[complement] > 0:
            count += 1
            num_dict[complement] -= 1
        else:
            if num in num_dict:
                num_dict[num] += 1
            else:
                num_dict[num] = 1

    return count

