def create_number_generator(start, end, step):
    """
    Creates a generator function that yields numbers from start to end with the given step.
    When reaching the end, it starts again from the beginning.
    """
    def generator():
        current = start
        while True:
            yield current
            current += step
            if current > end:
                current = start

    return generator

