def find_maximal_element(multidimensional_array):
    """
    Finds and returns the maximal element in a multidimensional array.
    """
    maximal_element = float('-inf')

    def find_max_recursive(array):
        nonlocal maximal_element
        for item in array:
            if isinstance(item, list):
                find_max_recursive(item)
            else:
                maximal_element = max(maximal_element, item)

    find_max_recursive(multidimensional_array)
    return maximal_element

