def factorial(n):
    """
    Compute the factorial of a non-negative integer n.
    :param n: non-negative integer
    :return: factorial of n
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    if n == 0 or n == 1:
        return 1
    return n * factorial(n - 1)

