def first_non_repeating_char(s):
    """
    Finds the first character in the string s that appears only once.
    Returns the character or "_" if there is no such character.
    """
    char_count = {}
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s:
        if char_count[char] == 1:
            return char

    return "_"

