def fibonacci(n):
    """
    Returns the Fibonacci number at the given position 'n' in the sequence.
    The sequence starts with 0 and 1.
    """
    if n < 0:
        raise ValueError("Position cannot be negative")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(n - 1):
        a, b = b, a + b
    return b

