def remove_duplicates(records):
    """
    Removes duplicate records from a list of dictionaries using the "id" key.
    The newest entry (i.e., the entry that appears later in the list) is kept.

    :param records: List of dictionaries containing an "id" key.
    :return: List of dictionaries with duplicates removed.
    """
    seen_ids = {}
    result = []
    for record in reversed(records):
        if record['id'] not in seen_ids:
            seen_ids[record['id']] = record
            result.append(record)
    return list(reversed(result))

