def solve_n_queens(n):
    """
    Solves the N-Queens problem and returns the number of distinct solutions
    for an n×n chessboard.
    """
    def is_not_under_attack(row, col):
        return not (cols[col] or hills[row - col] or dales[row + col])

    def place_queen(row, col):
        cols[col] = 1
        hills[row - col] = 1  # "hill" diagonals
        dales[row + col] = 1  # "dale" diagonals

    def remove_queen(row, col):
        cols[col] = 0
        hills[row - col] = 0
        dales[row + col] = 0

    def backtrack(row = 0, count = 0):
        # If all n queens are placed successfully
        if row == n:
            count += 1
        else:
            for col in range(n):  # Iterate through columns at the current row.
                if is_not_under_attack(row, col):
                    place_queen(row, col)  # Place the queen on the board.
                    count = backtrack(row + 1, count)  # Move on to the next row with updated placements.
                    remove_queen(row, col)  # Remove the queen from the board.
        return count

    # Columns, hill diagonals, and dale diagonals
    cols = [0] * n
    hills = [0] * (2 * n - 1)  # "hill" diagonals
    dales = [0] * (2 * n - 1)  # "dale" diagonals

    return backtrack()

