def prime_factors(n):
    """
    Returns a list of prime factors of the given integer, sorted in ascending order.
    If the input number is less than 2, returns an empty list.
    """
    if n < 2:
        return []

    factors = []
    divisor = 2

    while n >= divisor:
        if n % divisor == 0:
            factors.append(divisor)
            n //= divisor
        else:
            divisor += 1

    return factors

