def next_smallest_same_digits(n):
    """
    Finds the next smallest number with the same digits as the given number.
    If such a number does not exist, returns -1.
    """
    digits = list(str(n))
    length = len(digits)

    # Step 1: Find the rightmost digit that is larger than the digit next to it
    for i in range(length - 2, -1, -1):
        if digits[i] > digits[i + 1]:
            break
    else:
        return -1  # No such digit found means the digits are in ascending order

    # Step 2: Find the largest digit to the right of digits[i] that is smaller than digits[i]
    for j in range(length - 1, i, -1):
        if digits[j] < digits[i]:
            break

    # Step 3: Swap the found digits
    digits[i], digits[j] = digits[j], digits[i]

    # Step 4: Reverse the digits after position i to get the smallest permutation
    digits = digits[:i + 1] + sorted(digits[i + 1:], reverse=True)

    # Convert list of digits back to integer
    return int("".join(digits))

