def max_subarray_sum(arr):
    """
    Function to find the maximum subarray sum with complexity O(n^2).
    """
    max_sum = float('-inf')
    n = len(arr)

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += arr[j]
            if current_sum > max_sum:
                max_sum = current_sum

    return max_sum

