def sum_of_evens(start, end):
    """
    Returns the sum of all even numbers between start and end, inclusive.
    Raises ValueError if start or end are not integers or if start is greater than end.
    """
    if not isinstance(start, int) or not isinstance(end, int):
        raise ValueError("Both start and end must be integers")
    if start > end:
        raise ValueError("Start must be less than or equal to end")

    return sum(num for num in range(start, end + 1) if num % 2 == 0)

