def factorial(n, memo={}):
    """
    Returns the factorial of n using recursion and memoization.
    """
    if n in memo:
        return memo[n]
    if n <= 1:
        return 1
    else:
        memo[n] = n * factorial(n-1, memo)
        return memo[n]

def sum_of_factorials(n):
    """
    Returns the sum of the factorials of numbers from 1 to n.
    """
    memo = {}
    total = 0
    for i in range(1, n+1):
        total += factorial(i, memo)
    return total

