def sum_of_divisors_excluding_n(n):
    """
    Returns the sum of all divisors of 'n' excluding 'n' itself.
    If 'n' is a prime number, return 1.
    """
    if n < 2:
        return 0  # edge case for n < 2 (1 has no divisors other than itself)

    sum_divisors = 0
    for i in range(1, n):
        if n % i == 0:
            sum_divisors += i

    # Check if n is a prime number
    if sum_divisors == 1:
        return 1

    return sum_divisors

