def hamiltonian_path_exists(graph):
    """
    Determines if a Hamiltonian Path exists in the given graph.

    :param graph: list of adjacency lists representing the graph
    :return: True if there is a Hamiltonian Path, else False
    """
    def backtrack(current_vertex, visited, path_length):
        if path_length == len(graph):
            return True # All vertices are visited

        for neighbor in graph[current_vertex]:
            if not visited[neighbor]:
                visited[neighbor] = True
                if backtrack(neighbor, visited, path_length + 1):
                    return True
                visited[neighbor] = False
        return False

    for vertex in range(len(graph)):
        visited = [False] * len(graph)
        visited[vertex] = True
        if backtrack(vertex, visited, 1):
            return True

    return False

