def sum_array(arr):
    """
    Returns the sum of elements in the array using the divide and conquer method.
    """
    if len(arr) == 0:
        return 0
    elif len(arr) == 1:
        return arr[0]
    else:
        mid = len(arr) // 2
        left_sum = sum_array(arr[:mid])
        right_sum = sum_array(arr[mid:])
        return left_sum + right_sum

