def prime_factors(n):
    """
    Returns a list of all prime factors of a number n in ascending order.
    """
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

