def detect_triangle_type(a, b, c):
    """
    Detect the type of triangle based on the lengths of its sides.
    Returns 'Equilateral', 'Isosceles', 'Scalene', or 'Invalid'.
    """
    if a <= 0 or b <= 0 or c <= 0:
        return "Invalid"
    if a + b <= c or a + c <= b or b + c <= a:
        return "Invalid"
    if a == b == c:
        return "Equilateral"
    elif a == b or b == c or a == c:
        return "Isosceles"
    else:
        return "Scalene"

