def solve_n_queens(n):
    """
    Solves the N-Queens problem and returns a list of lists representing the board.
    Each inner list represents a row of the board with queens indicated by 1 and empty spaces by 0.

    :param n: int - the number of queens and the dimensions of the board (n x n)
    :return: List[List[int]] - a solution to the N-Queens problem
    """
    def is_safe(board, row, col):
        # Check this column on upper side
        for i in range(row):
            if board[i][col] == 1:
                return False

        # Check upper diagonal on left side
        for i, j in zip(range(row, -1, -1), range(col, -1, -1)):
            if board[i][j] == 1:
                return False

        # Check upper diagonal on right side
        for i, j in zip(range(row, -1, -1), range(col, n)):
            if board[i][j] == 1:
                return False

        return True

    def solve(board, row):
        if row >= n:
            return True
        for i in range(n):
            if is_safe(board, row, i):
                board[row][i] = 1
                if solve(board, row + 1):
                    return True
                board[row][i] = 0 # backtrack
        return False

    board = [[0 for _ in range(n)] for _ in range(n)]
    solve(board, 0)
    return board

