def longest_increasing_subsequence(nums):
    """
    Finds the length of the longest increasing subsequence in the list of numbers.

    :param nums: List[int] - A list of integers.
    :return: int - The length of the longest increasing subsequence.
    """
    if not nums:
        return 0

    # Initialize the dp array with 1s
    dp = [1] * len(nums)

    # Fill the dp array with the length of LIS that ends with nums[i]
    for i in range(len(nums)):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the longest increasing subsequence
    return max(dp)

