def smallest_repeating_element(arr):
    """
    Returns the smallest repeating element in a list.
    If there is no repeating element, returns None.
    """
    element_count = {}
    for element in arr:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1

    repeating_elements = [key for key, value in element_count.items() if value > 1]

    if not repeating_elements:
        return None

    return min(repeating_elements)

