def find_max_min(arr):
    """
    Returns the maximum and minimum elements in an array of integers.
    """
    if len(arr) == 0:
        raise ValueError("Array must not be empty")

    def recursive_max_min(arr, low, high):
        if low == high:
            return arr[low], arr[low]

        if high == low + 1:
            if arr[low] > arr[high]:
                return arr[low], arr[high]
            else:
                return arr[high], arr[low]

        mid = (low + high) // 2
        max1, min1 = recursive_max_min(arr, low, mid)
        max2, min2 = recursive_max_min(arr, mid + 1, high)

        maximum = max1 if max1 > max2 else max2
        minimum = min1 if min1 < min2 else min2

        return maximum, minimum

    return recursive_max_min(arr, 0, len(arr) - 1)

