def longest_common_substring(str1, str2):
    """
    Find the longest common substring between two strings using dynamic programming.
    Returns the longest common substring.
    """
    m, n = len(str1), len(str2)
    # Create a table to store lengths of longest common suffixes of substrings
    lcsuff = [[0] * (n + 1) for _ in range(m + 1)]
    length_max = 0  # store length of the longest common substring
    end_index = 0  # store the ending index of the longest common substring in str1

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                lcsuff[i][j] = lcsuff[i - 1][j - 1] + 1
                if lcsuff[i][j] > length_max:
                    length_max = lcsuff[i][j]
                    end_index = i
            else:
                lcsuff[i][j] = 0

    if length_max == 0:
        return ""

    return str1[end_index - length_max: end_index]

