def multiply(x, y):
    """
    Multiplies two numbers without using the '*' operator and without using loops.
    This function uses recursion to achieve multiplication.
    """
    # base case for recursion
    if y == 0:
        return 0
    # if y is negative, process the multiplication and flip the sign
    elif y < 0:
        return -multiply(x, -y)
    # recursive step
    else:
        return x + multiply(x, y - 1)

