def find_maximum(numbers):
    """
    Returns the maximum element in a given list of integers.

    :param numbers: List of integers
    :return: The maximum integer in the list
    """
    if not numbers:
        raise ValueError("List is empty")

    max_number = numbers[0]
    for num in numbers:
        if num > max_number:
            max_number = num
    return max_number

