def fibonacci(n):
    """
    Returns the N th Fibonacci number.
    """
    if n <= 0:
        return "Invalid input. The position must be a positive integer."
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    a, b = 0, 1
    for _ in range(n - 2):
        a, b = b, a + b
    return b

