def longest_palindromic_substring(s):
    """
    Returns the starting and ending indices of the longest palindromic substring.
    """
    def expand_around_center(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return left + 1, right - 1

    start, end = 0, 0
    for i in range(len(s)):
        l1, r1 = expand_around_center(s, i, i)  # Odd-length palindromes
        l2, r2 = expand_around_center(s, i, i + 1)  # Even-length palindromes

        if r1 - l1 > end - start:
            start, end = l1, r1
        if r2 - l2 > end - start:
            start, end = l2, r2

    return start, end

