def prefix_search(main_string, sub_string):
    """
    Returns the starting index of the substring if it is found at the start
    of the main string, and -1 otherwise.
    """
    if not isinstance(main_string, str) or not isinstance(sub_string, str):
        return -1
    if sub_string == "":
        return -1

    if main_string.startswith(sub_string):
        return 0

    return -1

