def fibonacci_iterative(n):
    """
    Returns the nth Fibonacci number using an iterative approach.
    """
    if n <= 0:
        raise ValueError("Input should be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1

    a, b = 0, 1
    for _ in range(2, n):
        a, b = b, a + b
    return b

def fibonacci_recursive(n):
    """
    Returns the nth Fibonacci number using a recursive approach.
    """
    if n <= 0:
        raise ValueError("Input should be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)

def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers less than or equal to n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return []

    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    return [i for i in range(n + 1) if is_prime[i]]

