import math

def recursive_log10(n, base_value=None):
    """
    Recursively calculates logarithm base 10 of a number.

    Parameters:
    n (float): Number to calculate the logarithm.
    base_value (float): Current value of the logarithm being calculated.

    Returns:
    float: The base 10 logarithm of n.
    """
    if base_value is None:
        base_value = n

    if n == 10:
        return 1
    elif 0 < n < 10:
        return math.log10(n)
    else:
        return 1 + recursive_log10(n / 10, base_value)

