def evaluate_postfix(expression):
    """
    Evaluates a postfix expression and returns the calculated result.

    Args:
    expression (str): A string containing the postfix expression with integers and operators +, -, *, /.

    Returns:
    int: The result of evaluating the postfix expression.
    """
    stack = []
    operators = set(['+', '-', '*', '/'])

    for token in expression.split():
        if token not in operators:
            stack.append(int(token))
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(int(a / b))  # Using int() to mimic integer division behavior in some languages

    return stack[0]

