def factorial(n):
    """
    Returns the factorial of a given non-negative integer n using recursion.
    Raises a ValueError for negative inputs.
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers.")

    if n == 0 or n == 1:
        return 1

    return n * factorial(n - 1)

