def has_palindrome_substring(s):
    """
    Returns True if the given string contains any palindrome substring of at least 2 characters, else False.
    """
    n = len(s)

    # A helper function to check if a given substring is a palindrome
    def is_palindrome(sub):
        return sub == sub[::-1]

    # Check all substrings of length at least 2
    for length in range(2, n + 1):
        for start in range(n - length + 1):
            if is_palindrome(s[start:start + length]):
                return True

    return False

