def sqrt_newton_raphson(x, tolerance=1e-6):
    """
    Calculate the square root of a given number using the Newton-Raphson method.

    Parameters:
    x (float): The number to find the square root of.
    tolerance (float): The tolerance level for approximating the result.

    Returns:
    float: The square root of the number up to 5 decimal places.
    """
    if x < 0:
        raise ValueError("Cannot compute square root of a negative number.")
    if x == 0:
        return 0.0

    guess = x
    while True:
        new_guess = 0.5 * (guess + x / guess)
        if abs(guess - new_guess) < tolerance:
            break
        guess = new_guess
    return round(guess, 5)

