def third_max(nums):
    """
    Returns the third maximum number in the array if it exists,
    otherwise returns the maximum number.
    """
    first, second, third = float('-inf'), float('-inf'), float('-inf')

    for num in nums:
        if num in (first, second, third):
            continue
        if num > first:
            first, second, third = num, first, second
        elif num > second:
            second, third = num, second
        elif num > third:
            third = num

    return third if third != float('-inf') else first

