def string_to_hashmap(s):
    """
    Converts a string into a hashmap with each unique character as a key and its frequency as a value.

    Parameters:
    s (str): Input string

    Returns:
    dict: A dictionary with characters as keys and their frequencies as values.
    """
    hashmap = {}
    for char in s:
        if char in hashmap:
            hashmap[char] += 1
        else:
            hashmap[char] = 1
    return hashmap

