def intersection(arr1, arr2):
    """
    Returns the intersection of the two arrays including duplicates,
    in the same order as they appear in the first array.
    """
    counter = {}
    for num in arr2:
        if num in counter:
            counter[num] += 1
        else:
            counter[num] = 1

    result = []
    for num in arr1:
        if num in counter and counter[num] > 0:
            result.append(num)
            counter[num] -= 1

    return result

