def three_sum_zero(nums):
    """
    Finds the number of triplet combinations from an array of integers where the sum of the triplet is zero.

    Args:
    - nums (List[int]): List of integers

    Returns:
    - int: Count of zero-sum triplets
    """
    nums.sort()
    n = len(nums)
    count = 0

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                count += 1
                while left < right and nums[left] == nums[left + 1]:
                    left += 1
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif total < 0:
                left += 1
            else:
                right -= 1

    return count

