def factorial(num, output_type):
    """
    Calculates the factorial of a given number `num` and returns it
    either as an integer or a float, based on the `output_type` parameter.

    :param num: Integer, the number to calculate the factorial of.
    :param output_type: String, specifies the return type ('int' or 'float').
    :return: Factorial of `num` as specified by `output_type` or -1 in case of an invalid `output_type`.
    """
    if not isinstance(num, int) or num < 0:
        return -1

    factorial = 1
    for i in range(1, num + 1):
        factorial *= i

    if output_type == 'int':
        return factorial
    elif output_type == 'float':
        return float(factorial)
    else:
        return -1

