def second_smallest(numbers):
    """
    Returns the second smallest number in an array of integers. If the array contains
    a single number or does not have a second smallest number, returns None.
    """
    if len(numbers) < 2:
        return None

    first, second = float('inf'), float('inf')

    for n in numbers:
        if n < first:
            first, second = n, first
        elif first < n < second:
            second = n

    return second if second != float('inf') else None

