def is_prime(n):
    """Helper function to check if a number is prime."""
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def primes_between(start, end):
    """
    Returns a list of all prime numbers between start and end (both inclusive).
    Handles errors for non-integer inputs and cases where start > end.
    """
    if not isinstance(start, int) or not isinstance(end, int):
        raise ValueError("Start and end must be integers.")

    if start > end:
        raise ValueError("Start number must be less than or equal to end number.")

    primes = [n for n in range(start, end + 1) if is_prime(n)]

    return primes

