def sum_of_series(n):
    """
    Returns the sum of the series 1/1! + 1/2! + 1/3! + ... + 1/n!.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    series_sum = 0
    for i in range(1, n+1):
        series_sum += 1 / factorial(i)
    return series_sum

