import math

def replace_nan_with_mean(matrix):
    """
    Replaces NaN values in a matrix with the mean of each column.

    Parameters:
    matrix (list of lists of floats): The input 2D list (matrix).

    Returns:
    list of lists of floats: The matrix with NaN values replaced.
    """
    if not matrix or not matrix[0]:
        return matrix

    num_rows = len(matrix)
    num_cols = len(matrix[0])

    column_sums = [0] * num_cols
    column_counts = [0] * num_cols

    for row in matrix:
        for j in range(num_cols):
            if not math.isnan(row[j]):
                column_sums[j] += row[j]
                column_counts[j] += 1

    column_means = [
        (column_sums[j] / column_counts[j]) if column_counts[j] > 0 else 0
        for j in range(num_cols)
    ]

    result_matrix = []
    for row in matrix:
        result_row = [
            column_means[j] if math.isnan(row[j]) else row[j]
            for j in range(num_cols)
        ]
        result_matrix.append(result_row)

    return result_matrix

