def find_max_min(arr):
    """
    Returns the maximum and minimum values in an array of integers as a tuple.
    """
    if not arr:
        raise ValueError("Array must not be empty")

    max_val = min_val = arr[0]
    for num in arr:
        if num > max_val:
            max_val = num
        if num < min_val:
            min_val = num

    return (max_val, min_val)

