def find_median(arr):
    """
    Returns the median of an array of numbers.
    """
    if not arr:
        raise ValueError("Array is empty")

    sorted_arr = sorted(arr)
    n = len(sorted_arr)
    mid = n // 2

    if n % 2 == 0:
        return (sorted_arr[mid - 1] + sorted_arr[mid]) / 2
    else:
        return sorted_arr[mid]

