def is_palindrome(n):
    """
    Checks if the given integer n is a palindrome.
    """
    return str(n) == str(n)[::-1]

def steps_to_palindrome(n):
    """
    Returns a tuple (is_palindrome, steps) where:
    - is_palindrome is a boolean indicating if n is already a palindrome.
    - steps is the number of steps required to transform n into a palindrome.
    """
    steps = 0
    while not is_palindrome(n):
        n = n + int(str(n)[::-1])
        steps += 1
    return (True, steps)

def palindrome_transformation(n):
    """
    Main function to check if n is a palindrome and return the steps required to transform.
    """
    if is_palindrome(n):
        return (True, 0)
    return steps_to_palindrome(n)

