def factorial(n):
    """
    Returns the factorial of n using recursion.
    """
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def optimized_factorial(n, accumulator=1):
    """
    Returns the factorial of n using recursion.
    Uses tail recursion to optimize and prevent stack overflow.
    """
    if n == 0:
        return accumulator
    else:
        return optimized_factorial(n - 1, n * accumulator)

