def min_toggles_to_alternate(s):
    """
    Returns the minimum number of toggles needed to make a binary string alternate.
    """
    toggles_01 = 0
    toggles_10 = 0

    for i, char in enumerate(s):
        expected_01 = '0' if i % 2 == 0 else '1'
        expected_10 = '1' if i % 2 == 0 else '0'

        if char != expected_01:
            toggles_01 += 1
        if char != expected_10:
            toggles_10 += 1

    return min(toggles_01, toggles_10)

