def fibonacci_sequence(n):
    """
    Returns the Fibonacci sequence up to a given number n (inclusive).
    """
    if n < 0:
        return []
    if n == 0:
        return [0]
    sequence = [0, 1]
    while sequence[-1] + sequence[-2] <= n:
        sequence.append(sequence[-1] + sequence[-2])
    return sequence

