def is_prime(n):
    """
    Check if a number n is a prime number.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for current in range(3, int(n**0.5) + 1, 2):
        if n % current == 0:
            return False
    return True

def generate_primes(start, end):
    """
    Generate a list of prime numbers within the given range [start, end].
    """
    primes = []
    for num in range(start, end + 1):
        if is_prime(num):
            primes.append(num)
    return primes

