def find_duplicates(arr):
    """
    Returns a list of elements that appear more than once in the given array.
    The returned list should not have duplicate elements and should be case-sensitive.

    :param arr: List of elements
    :return: List of duplicated elements
    """
    seen = set()
    duplicates = set()

    for item in arr:
        if item in seen:
            duplicates.add(item)
        else:
            seen.add(item)

    return list(duplicates)

