def convert_s(s):
    """
    Converts the string `s` to all uppercase if at least half of its characters
    are uppercase, otherwise returns it in all lowercase.
    """
    uppercase_count = sum(1 for char in s if char.isupper())
    if uppercase_count >= len(s) / 2:
        return s.upper()
    else:
        return s.lower()

