def factorial_digit_sum(n):
    """
    Calculate the factorial of a number n and return the sum of the digits of the factorial result.
    """
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        else:
            return x * factorial(x - 1)

    fact = factorial(n)
    return sum(int(digit) for digit in str(fact))

