def string_to_integer(s):
    """
    Converts a string to an integer without using built-in conversion functions.
    Raises a ValueError if the string is not a valid integer representation.
    """
    if not s:
        raise ValueError("Empty string")

    s = s.strip()
    if not s:
        raise ValueError("String contains only whitespace")

    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
    elif s[0] == '+':
        s = s[1:]

    if not s:
        raise ValueError("String does not contain any digits after sign")

    result = 0
    for char in s:
        if char < '0' or char > '9':
            raise ValueError(f"Invalid character '{char}' in input string")
        result = result * 10 + (ord(char) - ord('0'))

    return -result if negative else result

