def remove_duplicates(s):
    """
    Removes all duplicate characters from a string, preserving the original order of characters.
    Assumes the input string consists of ASCII characters.
    """
    seen = [False] * 128  # There are 128 ASCII characters
    result = []

    for char in s:
        if not seen[ord(char)]:
            result.append(char)
            seen[ord(char)] = True

    return ''.join(result)

