def fibonacci_sequence(n):
    """
    Returns the Fibonacci sequence up to the nth term (inclusive).
    """
    if n == 0:
        return [0]
    elif n == 1:
        return [0, 1]

    fib_sequence = [0, 1]
    while len(fib_sequence) <= n:
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])

    return fib_sequence

