def evaluate_postfix(expression):
    """
    Evaluates a postfix (reverse Polish notation) expression.

    Args:
    expression (str): The postfix expression as a space-separated string.

    Returns:
    float: The result of the postfix expression.
    """
    stack = []
    operators = set(['+', '-', '*', '/'])

    for token in expression.split():
        if token not in operators:
            stack.append(float(token))  # Convert number tokens to float and push onto stack
        else:
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                stack.append(a / b)

    return stack[0]

