def unique_paths_with_obstacles(obstacle_grid):
    """
    Returns the number of unique paths from the top-left corner to the bottom-right corner
    of a m x n grid with obstacles. The obstacle_grid is a list of lists containing 0 (no obstacle)
    and 1 (obstacle).
    """
    if not obstacle_grid or obstacle_grid[0][0] == 1:
        return 0

    m, n = len(obstacle_grid), len(obstacle_grid[0])

    # Initialize the dp grid with 0s
    dp = [[0] * n for _ in range(m)]

    # Start point
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if obstacle_grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

