def remove_duplicates(arr):
    """
    Removes duplicates from an array using a single loop and
    without using additional memory.
    """
    if not arr:
        return []

    write_index = 1  # Start from the second element

    for read_index in range(1, len(arr)):
        unique = True
        for i in range(write_index):
            if arr[read_index] == arr[i]:
                unique = False
                break

        if unique:
            arr[write_index] = arr[read_index]
            write_index += 1

    return arr[:write_index]

