def bubble_sort(arr):
    """
    Sorts an array using the bubble sort algorithm.

    :param arr: list of integers
    :return: sorted list of integers
    """
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

