def max_consecutive_metastatic_cells(cells: str) -> int:
    """
    Returns the maximum number of consecutive metastatic ('1') cells in the given string.
    """
    max_count = 0
    current_count = 0

    for cell in cells:
        if cell == '1':
            current_count += 1
            if current_count > max_count:
                max_count = current_count
        else:
            current_count = 0

    return max_count

