def fibonacci_recursive(n):
    """
    Returns the nth Fibonacci number using recursion.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci_recursive(n - 1) + fibonacci_recursive(n - 2)

def fibonacci_memoized(n, memo={}):
    """
    Returns the nth Fibonacci number using memoization.
    """
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    if n in memo:
        return memo[n]

    memo[n] = fibonacci_memoized(n - 1, memo) + fibonacci_memoized(n - 2, memo)
    return memo[n]

def remove_consecutive_repeating_chars(s):
    """
    Detects and removes consecutive repeating characters from a string.
    """
    if not s:
        return ""

    result = [s[0]]

    for char in s[1:]:
        if char != result[-1]:
            result.append(char)

    return ''.join(result)

