def fibonacci(n):
    """
    Returns the nth Fibonacci number.
    """
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    # Base cases
    if n == 0:
        return 0
    elif n == 1:
        return 1

    # Starting with the first two numbers of the sequence
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

