def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers up to n using the Sieve of Eratosthenes algorithm.
    """
    if n < 2:
        return []

    primes = [True] * (n + 1)
    primes[0] = primes[1] = False

    for start in range(2, int(n**0.5) + 1):
        if primes[start]:
            for multiple in range(start * start, n + 1, start):
                primes[multiple] = False

    return [num for num, is_prime in enumerate(primes) if is_prime]

def primes_in_range(start, end):
    """
    Returns a list of all prime numbers within the range [start, end] using the Sieve of Eratosthenes algorithm.
    """
    if start > end:
        return []

    all_primes = sieve_of_eratosthenes(end)
    return [num for num in all_primes if num >= start]

def max_value_in_even_subarray(arr):
    """
    Returns the maximum value in a subarray of the given array that is divisible by 2
    and has a minimum length of 2. If no such subarray exists, returns -1.
    """
    if len(arr) < 2:
        return -1

    max_val = -1
    for i in range(len(arr) - 1):
        for j in range(i + 1, len(arr)):
            subarray = arr[i:j+1]
            if len(subarray) >= 2 and all(x % 2 == 0 for x in subarray):
                max_val = max(max_val, max(subarray))

    return max_val

