def is_valid_isbn_10(isbn):
    """
    Check if the given number is a valid ISBN-10 number.
    """
    if len(isbn) != 10:
        return False

    total = 0
    for i in range(9):
        if not isbn[i].isdigit():
            return False
        total += (i + 1) * int(isbn[i])

    if isbn[9] == 'X':
        total += 10 * 10
    elif isbn[9].isdigit():
        total += 10 * int(isbn[9])
    else:
        return False

    return total % 11 == 0

