def fibonacci(n, a=0, b=1, sequence=None):
    """
    Generates Fibonacci sequence up to a given number n using recursion.
    """
    if sequence is None:
        sequence = []

    if a > n:
        return sequence

    sequence.append(a)
    return fibonacci(n, b, a + b, sequence)

