def longest_non_decreasing_span(temperatures):
    """
    Returns the length of the longest span of consecutive days
    with non-decreasing temperatures.

    Args:
    temperatures: List[int] : list of temperatures over several days.

    Returns:
    int: length of the longest span with non-decreasing temperatures.
    """
    if not temperatures:
        return 0

    max_span = 1
    current_span = 1

    for i in range(1, len(temperatures)):
        if temperatures[i] >= temperatures[i - 1]:
            current_span += 1
        else:
            max_span = max(max_span, current_span)
            current_span = 1

    return max(max_span, current_span)

