def find_common_events(data):
    from collections import defaultdict
    event_years = defaultdict(set)

    current_year = None

    for line in data.splitlines():
        line = line.strip()

        if line.isdigit():
            current_year = int(line)

        elif len(line) > 2 and line[:2] == "* ":
            event = line[2:].strip().lower()
            event_years[event].add(current_year)

    max_years = max(len(years) for years in event_years.values())

    common_events = [
        event for event, years in event_years.items() if len(years) == max_years
    ]

    return sorted(common_events)

