def create_sequence(n, d):
    if d >= n:
        return "Not possible"

    sequence = []
    for i in range(1, n+1, d):
        sequence.append(i)

    remaining = [x for x in range(1, n+1) if x not in sequence]

    while remaining:
        sequence.append(remaining.pop(0))

    for i in range(1, len(sequence)):
        if abs(sequence[i] - sequence[i-1]) < d:
            return "Not possible"

    return sequence

