def max_books_in_increasing_order(n, widths):
    """
    This function finds the maximum number of books that can be selected
    from the list such that their widths are in strictly increasing order.
    """
    if n == 0:
        return 0

    # Initialize the length of longest increasing subsequence (LIS) for each book
    lis = [1] * n

    # Fill lis[] using DP
    for i in range(1, n):
        for j in range(0, i):
            if widths[i] > widths[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Return the maximum value from lis[]
    return max(lis)

