import math

def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def isPrimeList(arr):
    """
    Returns a list of booleans indicating whether each integer in the input list is a prime number.
    """
    return [is_prime(num) for num in arr]

