def can_segment_string(s, dictionary):
    """
    Returns True if the string `s` can be segmented into a space-separated sequence of one or more dictionary words
    from the set `dictionary`. Otherwise, returns False.
    """
    word_set = set(dictionary)
    dp = [False] * (len(s) + 1)
    dp[0] = True  # Empty string can always be segmented

    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break

    return dp[len(s)]

def solve_word_break(test_cases):
    results = []
    for case in test_cases:
        s, dictionary = case
        if can_segment_string(s, dictionary):
            results.append("Yes")
        else:
            results.append("No")
    return results

def normalize_dna_sequence(sequence):
    """
    Normalizes the given DNA sequence according to the specified rules.

    Parameters:
    sequence (str): A string representing the DNA sequence composed of A, C, G, T.

    Returns:
    str: The normalized DNA sequence.
    """
    if not sequence:
        return sequence

    normalized_sequence = []
    prev_char = ''
    count = 0

    for char in sequence:
        if char == prev_char:
            count += 1
        else:
            count = 1
            prev_char = char

        if count == 1 or (count == 2 and len(normalized_sequence) > 0 and normalized_sequence[-1] != char):
            normalized_sequence.append(char)

    return ''.join(normalized_sequence)

