def zigzag(arr):
    """
    Rearranges the elements of the array into a zigzag sequence in place and returns the array.
    """
    n = len(arr)
    for i in range(n-1):
        if i % 2 == 0:  # ascending
            if arr[i] > arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]
        else:  # descending
            if arr[i] < arr[i+1]:
                arr[i], arr[i+1] = arr[i+1], arr[i]
    return arr

def process_test_cases(test_cases):
    results = []
    for (n, arr) in test_cases:
        results.append(zigzag(arr))
    return results

