def calculate(s: str) -> float:
    """
    Evaluates a mathematical expression string and returns the result.
    """
    def evaluate(tokens):
        stack = []
        num = 0
        sign = '+'
        while tokens:
            token = tokens.pop(0)
            if token.isdigit() or token == '.':
                while tokens and (tokens[0].isdigit() or tokens[0] == '.'):
                    token += tokens.pop(0)
                num = float(token) if '.' in token else int(token)
            if token == '(':
                num = evaluate(tokens)
            if token == ')' or not tokens or token in '+-*/':
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack.append(stack.pop() * num)
                elif sign == '/':
                    stack.append(stack.pop() / num)
                num = 0
                sign = token
            if token == ')':
                break
        return sum(stack)

    return evaluate(list(s.replace(' ', '')))

