def is_possible_to_plant_trees(orchard):
    N = len(orchard)
    M = len(orchard[0])

    empty_spots = [(i, j) for i in range(N) for j in range(M) if orchard[i][j] == '.']

    for i, j in empty_spots:
        if not any(
            orchard[x][y] == 'T'
            for x in range(max(0, i-1), min(N, i+2))
            for y in range(max(0, j-1), min(M, j+2))
            if (x, y) != (i, j)
        ):
            return "NO"

    return "YES"

