from collections import deque

def shortest_path(grid, n, start, end):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start = (start[0] - 1, start[1] - 1)
    end = (end[0] - 1, end[1] - 1)
    q = deque([(start[0], start[1], 0)])
    visited = set()
    visited.add(start)
    while q:
        x, y, dist = q.popleft()
        if (x, y) == end:
            return dist
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited and grid[nx][ny] == '.':
                q.append((nx, ny, dist + 1))
                visited.add((nx, ny))
    return -1

def solve(t, test_cases):
    results = []
    for case in test_cases:
        n, grid, start, end = case
        results.append(shortest_path(grid, n, start, end))
    return results

from collections import deque

def is_possible_to_water_all_plants(n, m, w, garden):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    water_positions = []

    total_plants = 0
    for i in range(n):
        for j in range(m):
            if garden[i][j] == 'W':
                water_positions.append((i, j, 0))  # (row, col, distance_from_water_source)
            elif garden[i][j] == 'P':
                total_plants += 1

    if total_plants == 0:
        return "YES"  # No plants to water

    visited = [[False]*m for _ in range(n)]
    queue = deque(water_positions)

    while queue:
        x, y, dist = queue.popleft()
        if visited[x][y]:
            continue
        visited[x][y] = True

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny]:
                if garden[nx][ny] == '.':
                    queue.append((nx, ny, dist + 1))
                elif garden[nx][ny] == 'P':
                    if dist + 1 <= w:
                        total_plants -= 1
                        if total_plants == 0:
                            return "YES"
                    queue.append((nx, ny, dist + 1))

    return "NO"

