def max_sum_non_adjacent(arr):
    """
    Returns the maximum sum of non-adjacent elements in the list `arr`.
    """
    n = len(arr)
    if n == 0:
        return 0
    elif n == 1:
        return arr[0]

    include = arr[0]
    exclude = 0

    for i in range(1, n):
        new_exclude = max(include, exclude)
        include = exclude + arr[i]
        exclude = new_exclude

    return max(include, exclude)

