from collections import deque

def shortest_path_in_grid(R, C, grid):
    if grid[0][0] == '#' or grid[R-1][C-1] == '#':
        return -1

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set((0, 0))

    while queue:
        r, c, dist = queue.popleft()

        if (r, c) == (R-1, C-1):
            return dist

        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == '.' and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))

    return -1

def is_interleave(a, b, c):
    """
    Checks if string C can be formed by interleaving strings A and B while preserving their orders.
    """
    m, n = len(a), len(b)

    if m + n != len(c):
        return "No"

    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(m + 1):
        for j in range(n + 1):
            if i > 0 and dp[i - 1][j] and a[i - 1] == c[i + j - 1]:
                dp[i][j] = True
            if j > 0 and dp[i][j - 1] and b[j - 1] == c[i + j - 1]:
                dp[i][j] = True

    return "Yes" if dp[m][n] else "No"

