def create_palindromic_list(n):
    """
    Generate a list of n integers such that every contiguous subsequence of length 3 is a palindrome.
    If it's not possible, return "No".
    """
    if n < 3:
        return "No"  # Not enough elements for subsequences of length 3

    # We can create a palindromic sequence using repeating pattern like 1, 2, 1, 2, 1, 2, ...
    result = []
    for i in range(n):
        if i % 2 == 0:
            result.append(1)
        else:
            result.append(2)

    return "Yes " + " ".join(map(str, result))

