import heapq

def minFare(routes, start, destination):
    """
    Find the minimum fare from start to destination.
    """
    graph = {}

    for u, v, cost in routes:
        if u not in graph:
            graph[u] = []
        graph[u].append((v, cost))

    # Dijkstra's algorithm
    pq = [(0, start)]
    distances = {start: 0}

    while pq:
        current_cost, current_node = heapq.heappop(pq)

        if current_node == destination:
            return current_cost

        if current_cost > distances.get(current_node, float('inf')):
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_cost + weight

            if distance < distances.get(neighbor, float('inf')):
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return -1

def digit_count(s):
    """
    Returns a dictionary with the count of each digit in the string s.

    Parameters:
    s (str): The input string consisting of digits.

    Returns:
    dict: A dictionary where keys are digits and values are the counts.
          Returns an empty dictionary if the string is empty.
          Returns 'undefined' if the input is not a string.
    """
    if not isinstance(s, str):
        return 'undefined'
    count_dict = {}
    for char in s:
        if char.isdigit():
            if char in count_dict:
                count_dict[char] += 1
            else:
                count_dict[char] = 1
    return count_dict

