def longest_sub_palindrome(s):
    def expand_around_center(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left+1:right]

    longest_palindrome = ""
    for i in range(len(s)):
        # Odd length palindromes
        pal1 = expand_around_center(s, i, i)
        # Even length palindromes
        pal2 = expand_around_center(s, i, i+1)

        # Update the longest palindrome found
        if len(pal1) > len(longest_palindrome):
            longest_palindrome = pal1
        if len(pal2) > len(longest_palindrome):
            longest_palindrome = pal2

    return longest_palindrome

