from collections import deque

def min_steps_to_reach(m, n, sx, sy, tx, ty, grid):
    if grid[sx][sy] == 1 or grid[tx][ty] == 1:
        return -1  # If start or end point is an obstacle

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(sx, sy, 0)])
    visited = set((sx, sy))

    while queue:
        x, y, steps = queue.popleft()

        if (x, y) == (tx, ty):
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] == 0 and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1

