def get_high_scores(data):
    def process_test_case(n, sessions):
        scores = {}
        for session in sessions:
            name, score = session
            name = name.lower()
            score = int(score)
            if name not in scores or score > scores[name]:
                scores[name] = score

        sorted_scores = sorted(scores.items(), key=lambda item: (-item[1], item[0]))
        return '\n'.join(f"{name.title()} {score}" for name, score in sorted_scores)

    result = []
    iterator = iter(data)
    num_test_cases = int(next(iterator))
    for _ in range(num_test_cases):
        n = int(next(iterator))
        sessions = [next(iterator).split() for _ in range(n)]
        result.append(process_test_case(n, sessions))
    return "\n".join(result)

from typing import List

def canServeAllRequests(candies: List[int], quantity: List[int], request: List[int], required: List[int]) -> bool:
    # Create a dictionary to map the candy types to their quantities
    candy_dict = {c: q for c, q in zip(candies, quantity)}

    # Check if each request can be fulfilled
    for candy, req_qty in zip(request, required):
        if candy not in candy_dict or candy_dict[candy] < req_qty:
            return False
    return True

