def is_power_of_two(n):
    """
    Helper function to determine if a number is a power of two.
    """
    return (n & (n - 1)) == 0 and n != 0

def longestPowerOfTwoSubsequence(arr):
    """
    Returns the length of the longest subsequence where each element is a power of two.
    """
    return sum(1 for x in arr if is_power_of_two(x))

