from collections import defaultdict

def has_cycle_dfs(node, visited, rec_stack, graph):
    visited[node] = True
    rec_stack[node] = True

    for neighbour in graph[node]:
        if not visited[neighbour]:
            if has_cycle_dfs(neighbour, visited, rec_stack, graph):
                return True
        elif rec_stack[neighbour]:
            return True

    rec_stack[node] = False
    return False

def contains_cycle(n, edges):
    graph = defaultdict(list)

    for u, v in edges:
        graph[u].append(v)

    visited = [False]*(n+1)
    rec_stack = [False]*(n+1)

    for node in range(1, n+1):
        if not visited[node]:
            if has_cycle_dfs(node, visited, rec_stack, graph):
                return True
    return False

def solve(test_cases):
    results = []
    for n, m, edges in test_cases:
        if contains_cycle(n, edges):
            results.append("YES")
        else:
            results.append("NO")
    return results

