def is_valid_sudoku(board):
    def is_valid_unit(unit):
        unit = [i for i in unit if i != '.']
        return len(unit) == len(set(unit))

    def is_valid_row(board):
        for row in board:
            if not is_valid_unit(row):
                return False
        return True

    def is_valid_column(board):
        for col in range(9):
            if not is_valid_unit([board[row][col] for row in range(9)]):
                return False
        return True

    def is_valid_subgrid(board):
        for i in range(0, 9, 3):
            for j in range(0, 9, 3):
                block = []
                for k in range(3):
                    block.extend(board[i + k][j:j + 3])
                if not is_valid_unit(block):
                    return False
        return True

    return "Valid" if is_valid_row(board) and is_valid_column(board) and is_valid_subgrid(board) else "Invalid"

