def count_characters(s):
    """
    Takes a string and returns a dictionary with the count of each character
    that appears in the string (ignoring case), but only for alphabetical characters.
    """
    char_count = {}
    for char in s:
        if char.isalpha():
            char = char.lower()
            if char in char_count:
                char_count[char] += 1
            else:
                char_count[char] = 1
    return char_count

