from collections import defaultdict, deque

def can_complete_tasks(n, m, dependencies):
    graph = defaultdict(list)
    in_degree = [0] * (n + 1)

    for u, v in dependencies:
        graph[u].append(v)
        in_degree[v] += 1

    queue = deque()

    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    processed = 0

    while queue:
        node = queue.popleft()
        processed += 1

        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if processed == n:
        return "Yes"
    else:
        return "No"

def longest_continuous_increase(n, views):
    if n == 0:
        return 0
    if n == 1:
        return 1

    longest_increase = 1
    current_increase = 1

    for i in range(1, n):
        if views[i] > views[i - 1]:
            current_increase += 1
            if current_increase > longest_increase:
                longest_increase = current_increase
        else:
            current_increase = 1

    return longest_increase

