def min_difficulty(N, M, max_diff, S_0, P, Q, R, W_0, X, Y, Z):
    MOD = 1000000003

    # Generate the difficulty matrix D
    S = [S_0]
    D = [[0] * M for _ in range(N)]

    for i in range(N * M):
        S_new = (P * S[-1] * S[-1] + Q * S[-1] + R) % MOD
        S.append(S_new)
        D[i // M][i % M] = S_new

    # Dynamic Programming table to store min difficulty for each path in each mountain
    dp = [[float('inf')] * M for _ in range(N)]

    # Initialize the first mountain difficulty levels
    for j in range(M):
        dp[0][j] = D[0][j]

    # Fill the DP table
    for i in range(1, N):
        for j in range(M):
            dp[i][j] = float('inf')
            for k in range(M):
                cost_to_switch = 0
                if D[i][j] > D[i-1][k] + max_diff:
                    cost_to_switch = D[i][j] - (D[i-1][k] + max_diff)

                dp[i][j] = min(dp[i][j], dp[i-1][k] + cost_to_switch)

    # Find the minimum difficulty to reach the last mountain
    return min(dp[-1])

def maximum_subgrid_sum(grid):
    """
    Returns the maximum sum of any contiguous sub-grid.
    """
    def max_subarray(arr):
        max_ending_here = max_so_far = arr[0]

        for x in arr[1:]:
            max_ending_here = max(x, max_ending_here + x)
            max_so_far = max(max_so_far, max_ending_here)

        return max_so_far

    n = len(grid)
    m = len(grid[0])

    max_sum = float('-inf')

    for left in range(m):
        temp = [0] * n
        for right in range(left, m):
            for row in range(n):
                temp[row] += grid[row][right]

            max_sum = max(max_sum, max_subarray(temp))

    return max_sum

def solve(T, test_cases):
    results = []
    for test_case in test_cases:
        n, m, grid = test_case
        results.append(maximum_subgrid_sum(grid))
    return results

