def longest_increasing_subseq_after_removal(nums):
    """
    Returns the length of the longest strictly increasing subsequence
    that can be obtained after removing exactly one element from the array.
    """
    n = len(nums)
    if n == 2:  # If length of nums is 2, we can't remove and have a subsequence of length > 1
        return 2 if nums[0] != nums[1] else 1

    # Compute LIS ending at each index
    LIS = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                LIS[i] = max(LIS[i], LIS[j] + 1)

    # Compute LIS starting at each index
    LISRev = [1] * n
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if nums[i] < nums[j]:
                LISRev[i] = max(LISRev[i], LISRev[j] + 1)

    # Determine the max length of increasing subsequence after removing exactly one element
    max_length = max(LIS) # without removing any element
    for i in range(1, n-1): # removing one element from the array
        if nums[i-1] < nums[i+1]:
            max_length = max(max_length, LIS[i-1] + LISRev[i+1])

    return max_length

