def final_sequence_length(N, sequence):
    """
    Determines the length of the final sequence after performing the operation.

    Parameters:
    N (int): The length of the sequence.
    sequence (list of int): The elements of the sequence.

    Returns:
    int: The length of the final sequence after performing operations.
    """
    stack = []

    for num in sequence:
        if stack and (stack[-1] % 2 != num % 2):
            stack.pop()
        else:
            stack.append(num)

    return len(stack)

