def is_valid_bst(tree):
    """
    Determines if the given binary tree is a valid BST.

    :param tree: List of tuples where each tuple represents (value, left_index, right_index)
    :return: "YES" if the binary tree is a valid BST, otherwise "NO"
    """

    if not tree:
        return "YES"

    def validate(node_idx, min_val, max_val):
        if node_idx == -1:
            return True

        node_val, left_idx, right_idx = tree[node_idx - 1]

        if not (min_val < node_val < max_val):
            return False

        return validate(left_idx, min_val, node_val) and validate(right_idx, node_val, max_val)

    return "YES" if validate(1, float('-inf'), float('inf')) else "NO"

