def minimal_cost(N, S, prices, discounts):
    dp = [[float('inf')] * S for _ in range(N)]
    for j in range(S):
        dp[0][j] = prices[0][j]

    for i in range(1, N):
        for j in range(S):
            min_cost_previous = float('inf')
            for k in range(S):
                min_cost_previous = min(min_cost_previous, dp[i-1][k])
            discount_available = discounts[i-2][j] if i > 1 else 0
            dp[i][j] = min_cost_previous + max(0, prices[i][j] - discount_available)

    return min(dp[N-1])

def minimize_expenditure(T, test_cases):
    results = []
    for t in range(T):
        N, S, prices, discounts = test_cases[t]
        results.append(minimal_cost(N, S, prices, discounts))
    return results

