def best_positions(event_results):
    """
    Returns a dictionary summarizing the best position each student achieved across all events.

    Parameters:
    event_results (dict): A dictionary where the keys are event names, and the values are lists of tuples.
                          Each tuple consists of a student's name and the position they achieved.

    Returns:
    dict: A dictionary where the keys are student names and the values are their best positions across all events.
    """
    result = {}

    for event, participants in event_results.items():
        for student, position in participants:
            if student not in result or position < result[student]:
                result[student] = position

    return result

