def numberToWords(n):
    """Convert a number between 1 and 100 to its word representation."""
    if not (1 <= n <= 100):
        raise ValueError("The input must be between 1 and 100 inclusive.")

    units = ["", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"]
    teens = ["ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen",
             "sixteen", "seventeen", "eighteen", "nineteen"]
    tens = ["", "ten", "twenty", "thirty", "forty", "fifty",
            "sixty", "seventy", "eighty", "ninety"]

    if n == 100:
        return "one hundred"

    if n < 10:
        return units[n]

    if 10 <= n < 20:
        return teens[n - 10]

    if n % 10 == 0:
        return tens[n // 10]

    return tens[n // 10] + "-" + units[n % 10]

