import math

def lcm(a, b):
    return abs(a * b) // math.gcd(a, b)

def smallest_common_multiple(a, b, c, x):
    multiple = lcm(lcm(a, b), c)
    if x % multiple == 0:
        return x + multiple
    else:
        return ((x // multiple) + 1) * multiple

