from typing import List
from collections import defaultdict

def minimumTreeSequence(trees: List[int], n: int) -> int:
    required_types = set(range(1, n + 1))
    tree_count = defaultdict(int)
    total_unique = 0

    min_length = float('inf')
    left = 0

    for right in range(len(trees)):
        current_tree = trees[right]
        if current_tree in required_types:
            if tree_count[current_tree] == 0:
                total_unique += 1
            tree_count[current_tree] += 1

        while total_unique == n and left <= right:
            min_length = min(min_length, right - left + 1)
            left_tree = trees[left]
            if left_tree in required_types:
                tree_count[left_tree] -= 1
                if tree_count[left_tree] == 0:
                    total_unique -= 1
            left += 1

    return min_length

def containsNearbyAlmostDuplicate(nums, k, t):
    if t < 0 or k <= 0:
        return False

    num_dict = {}
    for i, num in enumerate(nums):
        bucket = num // (t + 1)

        if bucket in num_dict:
            return True
        if bucket - 1 in num_dict and abs(num - num_dict[bucket - 1]) <= t:
            return True
        if bucket + 1 in num_dict and abs(num - num_dict[bucket + 1]) <= t:
            return True

        num_dict[bucket] = num

        if i >= k:
            del num_dict[nums[i - k] // (t + 1)]

    return False

