def oddNumberFrequency(arr):
    """
    Function that returns the integer which appears an odd number of times in the array.
    """
    frequency = {}

    # Count the frequency of each number
    for num in arr:
        frequency[num] = frequency.get(num, 0) + 1

    # Find and return the number that appears an odd number of times
    for num, count in frequency.items():
        if count % 2 != 0:
            return num

def find_pair(nums, target):
    """
    Returns a tuple (a, b) such that a + b = target and a and b are distinct elements in the list.
    If no such pair exists, returns None.
    """
    seen = {}
    for num in nums:
        complement = target - num
        if complement in seen:
            return (complement, num)
        seen[num] = True
    return None

