def longest_increasing_subarray(days, distances):
    if days == 0:
        return 0
    if days == 1:
        return 1

    max_length = 1
    current_length = 1

    for i in range(1, days):
        if distances[i] > distances[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

