def smallest_prime_factor(n):
    """
    Returns the smallest prime factor of n and the count of how many times this prime factor can divide n.
    """
    if n <= 1:
        raise ValueError("n should be greater than 1")

    # check for smallest prime factor
    # start checking from 2 upwards
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            count = 0
            while n % i == 0:
                n //= i
                count += 1
            return (i, count)

    # if no smaller factor found, n must be prime
    return (n, 1)

