def rearrangeEvenOdd(N, nums):
    even_index = 0
    odd_index = 1

    while even_index < N and odd_index < N:
        # Find next even number at even index
        while even_index < N and nums[even_index] % 2 == 0:
            even_index += 2

        # Find next odd number at odd index
        while odd_index < N and nums[odd_index] % 2 == 1:
            odd_index += 2

        # If we find a mismatch where even_index has odd number and odd_index has even number, swap them
        if even_index < N and odd_index < N:
            nums[even_index], nums[odd_index] = nums[odd_index], nums[even_index]

    return nums

