    for i in range(T):
        n, m, locations = test_cases[i]
        locations.sort(key=lambda x: x[1])
        dp = [0] * (m + 1)

        for s, e, v in locations:
            for t in range(m, s - 1, -1):
                if t >= e:
                    dp[t] = max(dp[t], dp[t - (e - s)] + v)

        results.append(max(dp))
    return results

