import math

def gcd_of_unblocked_intersections(n, m, k, blocked):
    blocked_set = set((r, c) for r, c in blocked)

    gcd_all = None

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if (i, j) not in blocked_set:
                val = i * j
                if gcd_all is None:
                    gcd_all = val
                else:
                    gcd_all = math.gcd(gcd_all, val)

    return gcd_all if gcd_all is not None else 0

def mostFrequentSubstring(s, k):
    from collections import defaultdict

    substring_count = defaultdict(int)

    for i in range(len(s) - k + 1):
        substring = s[i:i+k]
        substring_count[substring] += 1

    max_count = max(substring_count.values())

    most_frequent_substrings = [sub for sub, count in substring_count.items() if count == max_count]

    return min(most_frequent_substrings)

