def simplify_path(path):
    """
    Simplify a given Unix-style file path.

    Args:
    path (str): The given path to be simplified.

    Returns:
    str: The simplified absolute path.
    """
    parts = path.split("/")
    stack = []

    for part in parts:
        if part == "..":
            if stack:
                stack.pop()
        elif part == "." or part == "":
            continue
        else:
            stack.append(part)

    return "/" + "/".join(stack)

