from collections import defaultdict, deque

def findOrder(words, N, K):
    # Create adjacency list and in-degree dictionary
    adj = defaultdict(set)
    in_degree = {ch: 0 for word in words for ch in word}

    # Build the graph
    for i in range(N - 1):
        word1, word2 = words[i], words[i + 1]
        for ch1, ch2 in zip(word1, word2):
            if ch1 != ch2:
                if ch2 not in adj[ch1]:
                    adj[ch1].add(ch2)
                    in_degree[ch2] += 1
                break

    # Topological Sort using Kahn's Algorithm (BFS)
    queue = deque([ch for ch in in_degree if in_degree[ch] == 0])
    order = []

    while queue:
        ch = queue.popleft()
        order.append(ch)
        for neighbor in adj[ch]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) != len(in_degree):
        return ""
    return "".join(order)

