def unique_paths_with_obstacles(grid):
    N = len(grid)
    M = len(grid[0])
    if grid[0][0] == 1 or grid[N-1][M-1] == 1:
        return 0

    dp = [[0] * M for _ in range(N)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[N-1][M-1]

def find_unique_paths(T, test_cases):
    results = []
    for case in test_cases:
        N, M, grid = case
        result = unique_paths_with_obstacles(grid)
        results.append(result)
    return results

def longest_increasing_subsequence(arr):
    """
    Returns the length of the longest strictly increasing subsequence in the given array.
    """
    if not arr:
        return 0

    n = len(arr)
    lis = [1] * n  # Initialize LIS values for all indexes to 1

    # Compute optimized LIS values in a bottom up manner
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Return maximum value in lis[]
    return max(lis)

