def find_divisors(n):
    """
    Finds and returns a sorted list of all divisors of a given integer n.
    """
    divisors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return sorted(divisors)

