def longest_common_substring(dna_sequences):
    """
    Returns the longest common substring among multiple DNA sequences.
    :param dna_sequences: List of DNA sequences
    :return: Longest common substring
    """
    if not dna_sequences:
        return ""

    def is_common_substring(sub):
        return all(sub in seq for seq in dna_sequences)

    shortest_seq = min(dna_sequences, key=len)
    max_len = len(shortest_seq)

    for length in range(max_len, 0, -1):
        for start in range(max_len - length + 1):
            candidate = shortest_seq[start:start+length]
            if is_common_substring(candidate):
                return candidate
    return ""

