def countPairs(arr, target):
    """
    Returns the number of pairs in the array that sum up to target.
    The result is taken modulo (10^9 + 7).
    """
    MOD = 10**9 + 7
    count = 0
    freq = {}

    for number in arr:
        complement = target - number
        if complement in freq:
            count += freq[complement]
        if number in freq:
            freq[number] += 1
        else:
            freq[number] = 1

    return count % MOD

