from typing import List

def min_subset_difference(nums: List[int]) -> int:
    total_sum = sum(nums)
    n = len(nums)
    target = total_sum // 2

    # Initialize DP array
    dp = [False] * (target + 1)
    dp[0] = True

    # Fill DP array
    for num in nums:
        for j in range(target, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]

    # Find the largest j such that dp[j] is True
    for j in range(target, -1, -1):
        if dp[j]:
            subset1_sum = j
            break

    subset2_sum = total_sum - subset1_sum
    return abs(subset2_sum - subset1_sum)

