from itertools import permutations

def largest_valid_time(s):
    def is_valid_time(hh, mm):
        return 0 <= hh < 24 and 0 <= mm < 60

    max_time = -1
    best_time = "Not possible"

    for perm in permutations(s, 4):
        hh = int(perm[0] + perm[1])
        mm = int(perm[2] + perm[3])
        if is_valid_time(hh, mm):
            time_in_minutes = hh * 60 + mm
            if time_in_minutes > max_time:
                max_time = time_in_minutes
                best_time = f"{hh:02}:{mm:02}"

    return best_time

