def is_prime(num):
    """
    Helper function to check if a number is prime.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def smallest_prime_greater_equal(N):
    """
    Finds the smallest prime number P that is greater than or equal to N.
    """
    candidate = N
    while not is_prime(candidate):
        candidate += 1
    return candidate

