def is_prime(num):
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while (i * i) <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def max_consecutive_primes(n, segments):
    primes = [is_prime(seg) for seg in segments]
    max_count = 0
    count = 0
    for _ in range(n):
        if primes[_]:
            count += 1
            if count > max_count:
                max_count = count
        else:
            count = 0
    return max_count

