def collatz_steps(n: int) -> int:
    """
    Returns the number of steps required to reduce 'n' to 1 using the Collatz conjecture.
    """
    steps = 0
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        steps += 1
    return steps

