def countOccurrences(N, A, target):
    """
    Finds the occurrence count of the target number in the array using binary search technique.
    If the target is not present in the array, returns 0.

    :param N: int - size of the array
    :param A: List[int] - sorted array of integers
    :param target: int - target number to count
    :return: int - count of occurrences of target in the array
    """
    def find_first_occurrence(A, target):
        low, high = 0, len(A) - 1
        first_occurrence = -1
        while low <= high:
            mid = (low + high) // 2
            if A[mid] == target:
                first_occurrence = mid
                high = mid - 1
            elif A[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return first_occurrence

    def find_last_occurrence(A, target):
        low, high = 0, len(A) - 1
        last_occurrence = -1
        while low <= high:
            mid = (low + high) // 2
            if A[mid] == target:
                last_occurrence = mid
                low = mid + 1
            elif A[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return last_occurrence

    first = find_first_occurrence(A, target)
    if first == -1:
        return 0
    last = find_last_occurrence(A, target)
    return (last - first + 1)

