def process_operations(N, M, operations):
    grid = [[0] * M for _ in range(N)]
    results = []

    for operation in operations:
        if operation.startswith("Add"):
            _, x, y, v = operation.split()
            x, y, v = int(x) - 1, int(y) - 1, int(v)
            grid[x][y] += v
        elif operation.startswith("Sum"):
            _, x1, y1, x2, y2 = operation.split()
            x1, y1, x2, y2 = int(x1) - 1, int(y1) - 1, int(x2) - 1, int(y2) - 1
            total_sum = 0
            for i in range(x1, x2 + 1):
                for j in range(y1, y2 + 1):
                    total_sum += grid[i][j]
            results.append(total_sum)

    return results

def find_paths(grid):
    n = len(grid)
    if grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    dp = [[0] * n for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 0:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

def max_gold_coins(m, n, grid):
    """
    Returns the maximum number of gold coins that can be collected
    starting from any cell in the first column and reaching any cell in the last column.
    """
    # Initialize a DP table to store the maximum coins collected up to each cell
    dp = [[0] * n for _ in range(m)]

    # Fill the first column with initial values from grid
    for i in range(m):
        dp[i][0] = grid[i][0]

    # Process each column from second to the last
    for j in range(1, n):
        for i in range(m):
            # Get the maximum coins we can collect from the three possible previous cells
            best_previous = dp[i][j-1]
            if i > 0:
                best_previous = max(best_previous, dp[i-1][j-1])
            if i < m-1:
                best_previous = max(best_previous, dp[i+1][j-1])
            # Update the current cell with the maximum coins collected
            dp[i][j] = grid[i][j] + best_previous

    # The result is the maximum value in the last column
    return max(dp[i][n-1] for i in range(m))

