def max_participants(participants):
    from collections import defaultdict

    def bpm(u, match_r, seen):
        for v in participant_books[u]:
            if not seen[v]:
                seen[v] = True
                if match_r[v] == -1 or bpm(match_r[v], match_r, seen):
                    match_r[v] = u
                    return True
        return False

    participant_books = defaultdict(list)
    for i, books in enumerate(participants):
        for book in books:
            participant_books[i].append(book)

    match_r = [-1] * 101
    result = 0
    for i in participant_books:
        seen = [False] * 101
        if bpm(i, match_r, seen):
            result += 1

    return result

