import heapq
import sys

def shortest_path(N, M, edges):
    """
    Finds the shortest path distances from the source node (1) to all other nodes in the directed graph.

    :param N: Number of nodes
    :param M: Number of edges
    :param edges: List of edges where each edge is represented as a tuple (u, v, w)
    :return: List of shortest path distances from node 1 to nodes 1 to N, where -1 represents an unreachable node
    """
    graph = {i: [] for i in range(1, N+1)}
    for u, v, w in edges:
        graph[u].append((v, w))

    dist = {i: float('inf') for i in range(1, N+1)}
    dist[1] = 0
    pq = [(0, 1)]
    while pq:
        current_dist, u = heapq.heappop(pq)
        if current_dist > dist[u]:
            continue
        for v, weight in graph[u]:
            distance = current_dist + weight
            if distance < dist[v]:
                dist[v] = distance
                heapq.heappush(pq, (distance, v))

    result = []
    for i in range(1, N+1):
        if dist[i] == float('inf'):
            result.append(-1)
        else:
            result.append(dist[i])

    return result

