def blooming_sets_count(N, K):
    """
    Function to count the number of distinct "blooming sets" of length K modulo 10^9 + 7.
    """
    MOD = 10**9 + 7

    # If K > N, it's impossible to form such a blooming set
    if K > N:
        return 0

    # If K == 2, the result is simply the number of flowers (adjacent pairs)
    if K == 2:
        return N

    # For K >= 3, the result is 0 unless K alternate adjacent flowers can cover around the circle
    if N % 2 == 0 and K == N:
        return 0
    if K % 2 == 1:
        return (2 * N) % MOD
    else:
        return 0

