def process_queries(n, elements, q, queries):
    results = []

    for query in queries:
        parts = query.split()
        command = parts[0]
        a = int(parts[1])
        b = int(parts[2])

        if command == "SumRange":
            result = sum(elements[a:b+1])
            results.append(result)

        elif command == "IncrementRange":
            k = int(parts[3])
            for i in range(a, b+1):
                elements[i] += k

        elif command == "MaxRange":
            result = max(elements[a:b+1])
            results.append(result)

    return results

