def is_valid_sudoku(grid):
    """
    This function checks whether a given 9x9 grid is a valid Sudoku solution.
    """

    def is_valid_block(block):
        """
        Helper function to check if a block (row, column or subgrid) contains all digits from 1 to 9 exactly once.
        """
        return sorted(block) == list(range(1, 10))

    # Check each row
    for row in grid:
        if not is_valid_block(row):
            return "Invalid"

    # Check each column
    for col in range(9):
        if not is_valid_block([grid[row][col] for row in range(9)]):
            return "Invalid"

    # Check each 3x3 subgrid
    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            subgrid = []
            for row in range(3):
                for col in range(3):
                    subgrid.append(grid[i + row][j + col])
            if not is_valid_block(subgrid):
                return "Invalid"

    return "Valid"

