def containsNearbyAlmostDuplicate(nums, k, t):
    """
    Checks if there are two distinct indices i and j in the array such that
    the absolute difference between nums[i] and nums[j] is at most t and
    the absolute difference between i and j is at most k.
    """
    if k == 0 or t < 0 or not nums:
        return False

    num_dict = {}
    for i, num in enumerate(nums):
        bucket = num // (t + 1)

        if bucket in num_dict:
            return True

        if bucket - 1 in num_dict and abs(num_dict[bucket - 1] - num) <= t:
            return True

        if bucket + 1 in num_dict and abs(num_dict[bucket + 1] - num) <= t:
            return True

        num_dict[bucket] = num

        if i >= k:
            del num_dict[nums[i - k] // (t + 1)]

    return False

def process_queries(n, q, b, queries):
    results = []
    for query in queries:
        if query[0] == 1:
            l, r, x = query[1] - 1, query[2] - 1, query[3]
            for i in range(l, r + 1):
                b[i] += x
        elif query[0] == 2:
            l, r = query[1] - 1, query[2] - 1
            max_value = max(b[l:r + 1])
            results.append(max_value)
    return results

import bisect

def sequence_operations(operations):
    sequence = []
    results = []

    for operation in operations:
        op, value = operation
        if op == "ADD":
            bisect.insort(sequence, value)
        elif op == "MAX":
            idx = bisect.bisect_left(sequence, value)
            if idx < len(sequence):
                results.append(sequence[idx])
            else:
                results.append("NONE")
    return results

