def shortest_bridge(N_A, townA_points, N_B, townB_points):
    minimum_distance = float('inf')

    for x1, y1 in townA_points:
        for x2, y2 in townB_points:
            squared_distance = (x2 - x1) ** 2 + (y2 - y1) ** 2
            if squared_distance < minimum_distance:
                minimum_distance = squared_distance

    return minimum_distance

def first_missing_positive(nums):
    """
    Function to find the first missing positive integer in a list.
    """
    n = len(nums)

    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            correct_idx = nums[i] - 1
            nums[i], nums[correct_idx] = nums[correct_idx], nums[i]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

