def atm_withdrawal(amount):
    """
    Returns a dictionary with the minimal number of each denomination
    that the ATM will dispense for the given amount.
    """
    if amount % 10 != 0:
        return {}

    denominations = [100, 50, 20, 10]
    result = {}

    for denom in denominations:
        count = amount // denom
        if count > 0:
            result[str(denom)] = count
            amount -= count * denom

    return result

