from collections import deque

def number_of_robots_that_can_reach_charging_station(M, N, grid, batteries):
    def bfs(start, battery):
        q = deque([(start, battery)])
        visited = set([start])
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        while q:
            (x, y), b = q.popleft()

            if grid[x][y] == 'C':
                return True

            if b > 0:
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < M and 0 <= ny < M and (nx, ny) not in visited:
                        visited.add((nx, ny))
                        q.append(((nx, ny), b - 1))

        return False

    start_positions = []
    for i in range(M):
        for j in range(M):
            if grid[i][j] == 'R':
                start_positions.append((i, j))

    reachable_robots = 0
    for start, battery in zip(start_positions, batteries):
        if bfs(start, battery):
            reachable_robots += 1

    return reachable_robots

