def minimum_bonuses(n, scores):
    """
    Given the number of employees and their performance scores, determine the minimum bonuses
    that needs to be distributed such that the rules are met.
    """
    if n == 1:
        return 1

    bonuses = [1] * n

    # Scan from left to right
    for i in range(1, n):
        if scores[i] > scores[i - 1]:
            bonuses[i] = bonuses[i - 1] + 1

    # Scan from right to left
    for i in range(n - 2, -1, -1):
        if scores[i] > scores[i + 1]:
            bonuses[i] = max(bonuses[i], bonuses[i + 1] + 1)

    return sum(bonuses)

