def maximalSquare(matrix):
    if not matrix:
        return 0

    n = len(matrix)
    m = len(matrix[0])
    dp = [[0] * m for _ in range(n)]
    max_side_length = 0

    for i in range(n):
        for j in range(m):
            if matrix[i][j] == '1':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side_length = max(max_side_length, dp[i][j])

    return max_side_length * max_side_length

def can_water_flow_to_destination(N, grid):
    start = None
    destination = None

    # Find the coordinates of 's' and 'd'
    for i in range(N):
        for j in range(N):
            if grid[i][j] == 's':
                start = (i, j)
            elif grid[i][j] == 'd':
                destination = (i, j)

    if not start or not destination:
        return False

    # Create a visited matrix
    visited = [[False for _ in range(N)] for _ in range(N)]

    # Define directions for movement
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Depth-First Search (DFS) function
    def dfs(x, y):
        if (x, y) == destination:
            return True
        visited[x][y] = True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N and \
               not visited[nx][ny] and grid[nx][ny] in ['.', 'd']:
                if dfs(nx, ny):
                    return True
        return False

    # Start DFS from the starting point
    return dfs(start[0], start[1])

