def process_operations(operations):
    """
    Process the series of operations and return the results of the queries.

    :param operations: list of strings, each string being an operation
    :return: list of results from query operations
    """
    array = []
    results = []

    for operation in operations:
        op_parts = operation.split()
        if op_parts[0] == 'add':
            array.append(int(op_parts[1]))
        elif op_parts[0] == 'remove':
            if array:
                array.pop()
        elif op_parts[0] == 'query':
            if not array:
                results.append(-1)
            else:
                k = int(op_parts[1])
                if k < 1 or k > len(array):
                    results.append(-1)
                else:
                    sorted_array = sorted(array)
                    results.append(sorted_array[k-1])

    return results

def longest_common_prefix_length(s1, s2):
    """
    Returns the length of the longest common prefix of two strings s1 and s2.
    """
    min_length = min(len(s1), len(s2))
    common_length = 0

    for i in range(min_length):
        if s1[i] == s2[i]:
            common_length += 1
        else:
            break

    return common_length

def longest_non_decreasing_subarray_length(n, stops):
    if n == 0:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, n):
        if stops[i] >= stops[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

