def canBeNonDecreasing(arr):
    """
    Determine if the array can become non-decreasing by modifying at most one element.
    """
    # Find the number of places where the array is decreasing
    decrease_count = 0
    for i in range(1, len(arr)):
        if arr[i] < arr[i - 1]:
            decrease_count += 1
            if decrease_count > 1:
                return False

            # Check if modifying arr[i-1] or arr[i] could fix the issue
            if i == 1 or arr[i] >= arr[i - 2]:
                # Modify arr[i-1]
                arr[i - 1] = arr[i]
            else:
                # Modify arr[i]
                arr[i] = arr[i - 1]

    return True

