def maxLengthGP(arr):
    if len(arr) < 2:
        return len(arr)

    max_length = 1
    current_length = 1
    common_ratio = None

    for i in range(1, len(arr)):
        if arr[i] == 0 or arr[i-1] == 0:
            current_length = 1
            common_ratio = None
            continue

        if common_ratio is None:
            common_ratio = arr[i] / arr[i-1]
            current_length = 2
        elif arr[i] / arr[i-1] == common_ratio:
            current_length += 1
        else:
            common_ratio = arr[i] / arr[i-1]
            current_length = 2

        max_length = max(max_length, current_length)

    return max_length

