def is_valid_coloring(graph, colors, v, c):
    for i in range(len(graph)):
        if graph[v][i] == 1 and colors[i] == c:
            return False
    return True

def graph_coloring_util(graph, m, colors, v, k):
    if v == m:
        return True

    for c in range(1, k + 1):
        if is_valid_coloring(graph, colors, v, c):
            colors[v] = c
            if graph_coloring_util(graph, m, colors, v + 1, k):
                return True
            colors[v] = 0

    return False

def graph_coloring(n, m, k, edges):
    # Create adjacency matrix
    graph = [[0 for i in range(n)] for j in range(n)]
    for u, v in edges:
        graph[u - 1][v - 1] = 1
        graph[v - 1][u - 1] = 1

    # Initialize colors for all vertices
    colors = [0] * n

    if graph_coloring_util(graph, n, colors, 0, k):
        return colors
    else:
        return -1

