def minimum_edges_to_connect_graph(n, g):
    def dfs(node, visited):
        visited[node] = True
        for neighbor in range(n):
            if g[node][neighbor] == 1 and not visited[neighbor]:
                dfs(neighbor, visited)

    visited = [False] * n
    components = 0

    for i in range(n):
        if not visited[i]:
            dfs(i, visited)
            components += 1

    return max(0, components - 1)

def is_prime(M):
    """
    Determines whether a number M is a prime number.

    Parameters:
    M (int): The number to be checked.

    Returns:
    str: "Prime" if M is a prime number, otherwise "Not Prime".
    """
    if M <= 1:
        return "Not Prime"
    if M <= 3:
        return "Prime"
    if M % 2 == 0 or M % 3 == 0:
        return "Not Prime"

    i = 5
    while (i * i) <= M:
        if M % i == 0 or M % (i + 2) == 0:
            return "Not Prime"
        i += 6

    return "Prime"

def can_make_dish(A, B, C, D):
    """
    Returns 'YES' if Chef can make the dish exactly once with the given ingredients,
    otherwise returns 'NO'.
    """
    required = A + B + C
    if D >= required:
        return "YES"
    else:
        return "NO"

def process_test_cases(test_cases):
