def isValidParentheses(s):
    """
    Returns True if the string s is a valid parentheses expression, False otherwise.
    """
    stack = []
    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()
    return not stack

from math import ceil

def min_servers_to_update(n, links):
    if n == 1:
        return 0

    adjacency_list = [[] for _ in range(n + 1)]
    for u, v in links:
        adjacency_list[u].append(v)
        adjacency_list[v].append(u)

    leaf_count = sum(1 for node in range(1, n + 1) if len(adjacency_list[node]) == 1)
    return ceil(leaf_count / 2)

def min_distance(s1, s2):
    """
    Calculate the minimum number of operations required to convert s1 to s2.
    Operations include insert, delete, and replace.
    """
    m, n = len(s1), len(s2)

    # Create a 2D DP array
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize base cases
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Compute the minimum operations
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],  # Deletion
                                   dp[i][j - 1],  # Insertion
                                   dp[i - 1][j - 1])  # Replacement

    return dp[m][n]

def min_operations(test_cases):
    results = []
    for s, t in test_cases:
        results.append(min_distance(s, t))
    return results

