def min_segments(n, memory, L):
    segments = []
    current_sum = 0
    current_count = 0

    for value in memory:
        if current_sum + value <= L:
            current_sum += value
            current_count += 1
        else:
            segments.append(current_count)
            current_sum = value
            current_count = 1

    # Append the last segment
    if current_count > 0:
        segments.append(current_count)

    return len(segments), segments

def max_square_garden_side_length(n, m, flowers, t):
    """
    Determines the maximum side length of a square garden where each cell contains at least t flowers.
    """
    def is_valid_square(size):
        for i in range(n - size + 1):
            for j in range(m - size + 1):
                valid = True
                for k in range(i, i + size):
                    for l in range(j, j + size):
                        if flowers[k][l] < t:
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    return True
        return False

    left, right = 0, min(n, m)
    while left < right:
        mid = (left + right + 1) // 2
        if is_valid_square(mid):
            left = mid
        else:
            right = mid - 1

    return left

def removeDuplicates(s: str) -> str:
    """
    Removes adjacent duplicate letters from the input string until no more removals can be done.

    Args:
    s (str): The input string.

    Returns:
    str: The final string after all duplicate removals.
    """
    stack = []

    for char in s:
        if stack and stack[-1] == char:
            stack.pop()
        else:
            stack.append(char)

    return ''.join(stack)

