def count_pairs(arr, target):
    """
    Returns the number of pairs of elements in arr that sum up to the target.

    Parameters:
        arr (list): List of integers.
        target (int): The target sum for pairs.

    Returns:
        int: The number of pairs that sum up to the target.
    """
    count = 0
    freq = {}

    for num in arr:
        complement = target - num
        if complement in freq:
            count += freq[complement]
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    return count

