def longest_increasing_perfect_squares(arr):
    """
    Returns the length of the longest subsequence such that all elements of the subsequence are
    strictly increasing perfect squares.
    """
    def is_perfect_square(x):
        return int(x**0.5)**2 == x

    perfect_squares = [x for x in arr if is_perfect_square(x)]
    n = len(perfect_squares)

    if n == 0:
        return 0

    # LIS on perfect squares
    lis = [1] * n
    for i in range(1, n):
        for j in range(i):
            if perfect_squares[i] > perfect_squares[j]:
                lis[i] = max(lis[i], lis[j] + 1)

    return max(lis)

