def is_valid_parenthesis(s):
    """
    Check if the input string containing brackets is valid.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'
            if mapping[char] != top_element:
                return "NO"
        else:
            stack.append(char)

    return "YES" if not stack else "NO"

