def find_connected_groups(N, friendships):
    # Function to perform a breadth-first search (BFS) for unvisited nodes
    def bfs(start):
        queue = [start]
        visited[start] = True
        while queue:
            node = queue.pop(0)
            for neighbor in adj_list[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    # Create adjacency list
    adj_list = [[] for _ in range(N + 1)]  # 1-based index
    for u, v in friendships:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Initialize visited list
    visited = [False] * (N + 1)

    connected_groups = 0

    # Perform BFS for each unvisited employee
    for employee in range(1, N + 1):
        if not visited[employee]:
            bfs(employee)
            connected_groups += 1

    return connected_groups

def minimum_adjacent_swaps(arr):
    """
    Given a list of integers, return the minimum number of adjacent swaps
    needed to sort the list.
    """
    n = len(arr)
    swap_count = 0

    # Using Bubble Sort to count the number of swaps
    for i in range(n):
        for j in range(n - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swap_count += 1

    return swap_count

def solve_test_cases(test_cases):
    results = []
    for test_case in test_cases:
        n, priorities = test_case
        results.append(minimum_adjacent_swaps(priorities))
    return results

