import math

def evaluate_expression(expression):
    """
    Evaluates a simple arithmetic expression and rounds down the result to the nearest integer.
    The expression is in the form 'a#b' where 'a' and 'b' are digits from 0 to 9 and '#' is one of '+', '-', '*', '/'.

    Parameters:
    expression (str): The input arithmetic expression.

    Returns:
    int: The result of the expression rounded down to the nearest integer.
    """
    a = int(expression[0])
    operator = expression[1]
    b = int(expression[2])

    if operator == '+':
        return a + b
    elif operator == '-':
        return a - b
    elif operator == '*':
        return a * b
    elif operator == '/':
        return math.floor(a / b)
    else:
        raise ValueError("Invalid operator")

