def char_count(input_str):
    """
    Returns a dictionary with characters as keys and their count as values in a case-insensitive manner.
    Whitespace is ignored.
    """
    if not isinstance(input_str, str):
        return "Not valid"

    input_str = input_str.lower()
    char_dict = {}

    for char in input_str:
        if char.isspace():
            continue
        if char in char_dict:
            char_dict[char] += 1
        else:
            char_dict[char] = 1

    return char_dict

