            cx, cy = stack.pop()
            grid[cx][cy] = '#'
            for nx, ny in [(cx-1, cy), (cx+1, cy), (cx, cy-1), (cx, cy+1)]:
                if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.':
                    stack.append((nx, ny))

    num_spaces = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                num_spaces += 1
                dfs(i, j)

    return num_spaces

