from collections import defaultdict, deque

def schedule_tasks(T, D, tasks, dependencies):
    # Create graph and indegree dict
    graph = defaultdict(list)
    indegree = {task: 0 for task in tasks}

    # Populate the graph and indegree based on dependencies
    for dep in dependencies:
        u, v = dep
        graph[u].append(v)
        indegree[v] += 1

    # Initialize queue with tasks that have zero indegree
    queue = deque([task for task in tasks if indegree[task] == 0])
    result = []

    # Perform topological sort
    while queue:
        current_task = queue.popleft()
        result.append(current_task)

        for neighbor in graph[current_task]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    # If all tasks were not processed, return "IMPOSSIBLE"
    if len(result) != T:
        return "IMPOSSIBLE"

    return " ".join(result)

def generate_schedule(T, D, tasks, dependencies):
    return schedule_tasks(T, D, tasks, dependencies)

def min_operations_to_sort(A):
    """
    Returns the minimum number of adjacent swaps needed to make
    the sequence A non-decreasing.
    """
    n = len(A)
    swaps = 0
    for i in range(n):
        for j in range(0, n-i-1):
            if A[j] > A[j+1]:
                A[j], A[j+1] = A[j+1], A[j]
                swaps += 1
    return swaps

