import heapq
from collections import defaultdict

def minimum_travel_cost(n, highways, queries):
    # Construct the graph with modified weights.
    graph = defaultdict(list)
    for a, b, t, l in highways:
        cost = min(t, l)
        graph[a].append((cost, b))
        graph[b].append((cost, a))

    def dijkstra(start, end):
        pq = [(0, start)]
        dist = {i: float('inf') for i in range(1, n + 1)}
        dist[start] = 0

        while pq:
            current_cost, u = heapq.heappop(pq)
            if u == end:
                return current_cost
            if current_cost > dist[u]:
                continue

            for toll, v in graph[u]:
                next_cost = current_cost + toll
                if next_cost < dist[v]:
                    dist[v] = next_cost
                    heapq.heappush(pq, (next_cost, v))

        return -1

    results = []
    for u, v in queries:
        results.append(dijkstra(u, v))

    return results

def generate_parentheses(n):
    """
    Generates all balanced sequences of parentheses with n pairs.
    """
    def backtrack(s='', left=0, right=0):
        if len(s) == 2 * n:
            res.append(s)
            return
        if left < n:
            backtrack(s + '(', left + 1, right)
        if right < left:
            backtrack(s + ')', left, right + 1)

    res = []
    backtrack()
    return res

def generate_all_cases(test_cases):
    """
    Takes a list of test cases and generates parentheses sequences accordingly.
    """
    results = []
    for n in test_cases:
        results.append(sorted(generate_parentheses(n)))
    return results

