def compute_max_min_tasks(test_cases):
    results = []

    for logs in test_cases:
        max_sum = float('-inf')
        min_sum = float('inf')

        for i in range(len(logs)):
            current_sum = 0
            for j in range(i, len(logs)):
                current_sum += logs[j]
                if current_sum > max_sum:
                    max_sum = current_sum
                if current_sum < min_sum:
                    min_sum = current_sum

        results.append((max_sum, min_sum))

    return results

def process_input(input_string):
    lines = input_string.strip().split("\n")
    index = 0
    T = int(lines[index])
    index += 1
    test_cases = []

    for _ in range(T):
        N = int(lines[index])
        index += 1
        logs = list(map(int, lines[index].split()))
        index += 1
        test_cases.append(logs)

    return test_cases

def main(input_string):
    test_cases = process_input(input_string)
    results = compute_max_min_tasks(test_cases)

    output_lines = [f"{max_tasks} {min_tasks}" for max_tasks, min_tasks in results]
    return "\n".join(output_lines)

