def min_operations_to_non_negative(t, test_cases):
    """
    Returns the minimum number of subarrays that need to be multiplied by -1
    in order to make all elements of each array in test cases non-negative.
    """
    results = []
    for case in test_cases:
        n, a = case
        count = 0
        in_negative_segment = False
        for num in a:
            if num < 0:
                if not in_negative_segment:
                    count += 1
                    in_negative_segment = True
            else:
                in_negative_segment = False
        results.append(count)
    return results

def count_paths(n, grid):
    # If the starting cell or ending cell are blocked, there are 0 paths
    if grid[0][0] == '1' or grid[n-1][n-1] == '1':
        return 0

    # Create a dp table to store the number of ways to reach each cell
    dp = [[0] * n for _ in range(n)]

    # Set the initial position
    dp[0][0] = 1

    # Fill the dp table
    for i in range(n):
        for j in range(n):
            if grid[i][j] == '1':  # Obstacle
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][n-1]

