def smallest_product_number(n):
    """
    Finds the smallest positive integer x such that the product of the digits of x is equal to n.
    """
    if n == 1:
        return 1

    # Handle the cases where n is a single digit
    if 1 <= n <= 9:
        return n

    # Start checking from 10 upwards
    x = 10
    while True:
        if product_of_digits(x) == n:
            return x
        x += 1

def product_of_digits(x):
    """
    Calculates the product of the digits of x.
    """
    product = 1
    for digit in str(x):
        product *= int(digit)
    return product

