def countPairsWithDifference(lst, k):
    """
    Returns the number of distinct pairs (i, j) in the list such that the absolute
    difference between elements at those positions is equal to k.
    """
    seen = set()
    pairs = set()

    for number in lst:
        if number + k in seen:
            pairs.add((min(number, number + k), max(number, number + k)))
        if number - k in seen:
            pairs.add((min(number, number - k), max(number, number - k)))
        seen.add(number)

    return len(pairs)

