def findSecondLargest(arr):
    """
    Finds the second largest element in the given array or returns 'All elements are equal'
    if no such element exists.
    """
    if len(arr) < 2:
        return 'All elements are equal'

    first = second = float('-inf')

    for num in arr:
        if num > first:
            second = first
            first = num
        elif num > second and num < first:
            second = num

    if second == float('-inf'):
        return 'All elements are equal'

    return second

