def min_operations(s1, s2):
    """
    Returns the minimum number of operations required to transform s1 into s2.
    """
    m, n = len(s1), len(s2)

    # Create a DP array to store the results of subproblems
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill dp array
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j    # If first string is empty, insert all characters of second string
            elif j == 0:
                dp[i][j] = i    # If second string is empty, remove all characters of first string
            elif s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # Characters match, no extra operation required
            else:
                dp[i][j] = 1 + min(dp[i][j - 1],      # Insert
                                   dp[i - 1][j],      # Remove
                                   dp[i - 1][j - 1])  # Replace

    return dp[m][n]

from typing import List

def bubble_sort(arr: List[int]) -> List[int]:
    """
    Sorts an array of integers in ascending order using the Bubble Sort algorithm.
    """
    n = len(arr)
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                # Swap if the elements are in the wrong order
                arr[j], arr[j+1] = arr[j+1], arr[j]
    return arr

