def palindromic_substrings(s):
    """
    Returns all palindromic substrings in a given string.
    """
    def is_palindrome(sub):
        return sub == sub[::-1]

    n = len(s)
    result = set()

    for i in range(n):
        for j in range(i, n):
            substring = s[i:j+1]
            if is_palindrome(substring):
                result.add(substring)

    return list(result)

