def fourSum(nums, target):
    nums.sort()
    results = set()
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            left = j + 1
            right = n - 1
            while left < right:
                current_sum = nums[i] + nums[j] + nums[left] + nums[right]
                if current_sum == target:
                    results.add((nums[i], nums[j], nums[left], nums[right]))
                    left += 1
                    right -= 1
                elif current_sum < target:
                    left += 1
                else:
                    right -= 1

    return [list(result) for result in results]

def rotate_and_reflect_matrix(T, matrices):
    def rotate_90_clockwise(matrix):
        N = len(matrix)
        return [[matrix[N - j - 1][i] for j in range(N)] for i in range(N)]

    results = []
    for matrix in matrices:
        rotated_matrix = rotate_90_clockwise(matrix)
        results.append(rotated_matrix)

    return results

def restructured_matrix(T, matrices):
    return rotate_and_reflect_matrix(T, matrices)

def minimal_difference_partition(N, books):
    total_sum = sum(books)
    half_sum = total_sum // 2
    dp = [False] * (half_sum + 1)
    dp[0] = True

    for book in books:
        for j in range(half_sum, book - 1, -1):
            dp[j] = dp[j] or dp[j - book]

    for i in range(half_sum, -1, -1):
        if dp[i]:
            return abs(total_sum - 2 * i)

def process_test_cases(test_cases):
    results = []
    for test in test_cases:
        N, books = test
        results.append(minimal_difference_partition(N, books))
    return results

