def twoSum(nums, target):
    """
    Given an array of integers and a target sum, determine if any two numbers in the array add up to the target sum.
    Return the indices of the two numbers in an array if found, otherwise return an empty array.
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        diff = target - num
        if diff in num_to_index:
            return [num_to_index[diff], i]
        num_to_index[num] = i

    return []

def max_depth(n, folder_structure):
    from collections import defaultdict

    # Create an adjacency list representation of the folder structure
    tree = defaultdict(list)
    root = None

    for x, p in folder_structure:
        if p == -1:
            root = x
        else:
            tree[p].append(x)

    def dfs(node):
        if not tree[node]:
            return 1
        return 1 + max(dfs(child) for child in tree[node])

    return dfs(root)

def uniquePaths(grid):
    """
    Returns the number of unique paths from top-left corner to bottom-right
    corner of the grid while avoiding obstacles.
    """
    # Check for an empty grid
    if not grid or not grid[0]:
        return 0

    n, m = len(grid), len(grid[0])

    # If the starting or the ending cell is blocked, return 0 as no paths exist
    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return 0

    # Create a dp table to store the number of ways to reach each cell
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    # Fill the dp table
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

