def min_non_empty_subarrays(test_cases):
    results = []
    for boxes in test_cases:
        count = 0
        in_subarray = False

        for box in boxes:
            if box == '1' and not in_subarray:
                count += 1
                in_subarray = True
            elif box == '0':
                in_subarray = False

        results.append(count)
    return results

def solve(input_string):
    lines = input_string.strip().split('\n')
    T = int(lines[0])
    test_cases = lines[1:T+1]
    results = min_non_empty_subarrays(test_cases)
    return results

