def minPathSum(mat):
    if not mat:
        return 0

    m, n = len(mat), len(mat[0])
    dp = [[0] * n for _ in range(m)]

    dp[0][0] = mat[0][0]

    for i in range(1, m):
        dp[i][0] = dp[i-1][0] + mat[i][0]

    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + mat[0][j]

    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = min(dp[i-1][j], dp[i][j-1]) + mat[i][j]

    return dp[-1][-1]

