def count_interesting_subarrays(N, D, A):
    """
    Returns the number of interesting subarrays in the given array.
    An interesting subarray is one where the difference between its largest and smallest elements is exactly D.
    """
    count = 0
    for i in range(N):
        min_elem = max_elem = A[i]
        for j in range(i, N):
            min_elem = min(min_elem, A[j])
            max_elem = max(max_elem, A[j])
            if max_elem - min_elem == D:
                count += 1
            elif max_elem - min_elem > D:
                break
    return count

