def longest_subsequence_to_remove(N, A):
    if N == 0:
        return 0

    # Create an array to store the length of LIS ending at each position
    lis = [1] * N

    # Compute the LIS values
    for i in range(1, N):
        for j in range(i):
            if A[i] > A[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Get the length of the longest increasing subsequence (LIS)
    max_lis_length = max(lis)

    # The length of the longest subsequence that can be removed is
    # the difference between N and the length of the LIS
    return N - max_lis_length

