def min_trucks_required(boxes, truck_limit):
    boxes.sort(reverse=True)
    trucks = 0
    while boxes:
        trucks += 1
        current_weight = 0
        to_remove = []
        for i in range(len(boxes)):
            if current_weight + boxes[i] <= truck_limit:
                current_weight += boxes[i]
                to_remove.append(i)
        for i in reversed(to_remove):
            del boxes[i]
    return trucks

