def find_all_compounds(C, R, initial_compounds, reactions):
    from collections import defaultdict

    possible_compounds = set(initial_compounds)
    reactions_map = defaultdict(list)

    for A, B, D in reactions:
        reactions_map[(A, B)].append(D)
        reactions_map[(B, A)].append(D)

    changed = True
    while changed:
        changed = False
        new_compounds = set()

        for (A, B), result_list in reactions_map.items():
            if A in possible_compounds and B in possible_compounds:
                for result in result_list:
                    if result not in possible_compounds:
                        new_compounds.add(result)
                        changed = True

        possible_compounds.update(new_compounds)

    return sorted(possible_compounds)

