def min_path_sum_from_root_to_leaf(n, weights, edges):
    from collections import defaultdict
    import sys

    tree = defaultdict(list)
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)

    def dfs(node, parent):
        # If the node is a leaf node
        if not tree[node] or (len(tree[node]) == 1 and tree[node][0] == parent):
            return weights[node - 1]

        min_sum = sys.maxsize
        for neighbor in tree[node]:
            if neighbor != parent:
                min_sum = min(min_sum, dfs(neighbor, node))
        return weights[node - 1] + min_sum

    return dfs(1, -1)

import heapq

def dijkstra(graph, start, n):
    """
    Returns the minimum travel time from start to all other stops using Dijkstra's algorithm.
    """
    min_time = {i: float('inf') for i in range(1, n + 1)}
    min_time[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_time, current_stop = heapq.heappop(priority_queue)

        if current_time > min_time[current_stop]:
            continue

        for neighbor, travel_time in graph[current_stop]:
            time = current_time + travel_time
            if time < min_time[neighbor]:
                min_time[neighbor] = time
                heapq.heappush(priority_queue, (time, neighbor))

    return min_time

def solve(n, m, q, routes, queries):
    """
    Solves the problem of finding the minimum travel time for each query.
    """
    graph = {i: [] for i in range(1, n + 1)}

    for u, v, w in routes:
        graph[u].append((v, w))

    results = []
    for s, d in queries:
        min_time = dijkstra(graph, s, n)
        if min_time[d] == float('inf'):
            results.append(-1)
        else:
            results.append(min_time[d])

    return results

