def check_identification_codes(codes):
    """
    Checks if each identification code in the list follows the alternating letter-digit format,
    starting with a letter.
    """
    results = []
    for code in codes:
        is_valid = True
        if len(code) < 2 or not code[0].isalpha():
            is_valid = False
        else:
            for i in range(1, len(code)):
                if i % 2 == 1 and not code[i].isdigit():
                    is_valid = False
                    break
                elif i % 2 == 0 and not code[i].isalpha():
                    is_valid = False
                    break
        results.append("VALID" if is_valid else "INVALID")
    return results

