def count_unique_substrings(s):
    """
    Returns the number of unique substrings in the given string `s`.
    """
    n = len(s)
    substrings_set = set()

    for i in range(n):
        for j in range(i + 1, n + 1):
            substrings_set.add(s[i:j])

    return len(substrings_set)

