def simulate_parking_lot(n, m, k, operations):
    # Initialize the parking lot as an n x m grid of zeros (empty spaces)
    parking_lot = [[0] * m for _ in range(n)]

    for operation in operations:
        op_type, r, c = operation
        # Adjust indices to zero-based
        r -= 1
        c -= 1

        if op_type == 1:
            # Car arrival
            if parking_lot[r][c] == 0:
                parking_lot[r][c] = 1
        elif op_type == 2:
            # Car departure
            if parking_lot[r][c] == 1:
                parking_lot[r][c] = 0

    return parking_lot

def find_duplicates(test_cases):
    results = []
    for case in test_cases:
        N, M, original_list, merged_list = case
        item_count = {}

        for item in merged_list:
            if item in item_count:
                item_count[item] += 1
            else:
                item_count[item] = 1

        duplicates = sorted([item for item, count in item_count.items() if count > 1])

        if duplicates:
            results.append(' '.join(duplicates))
        else:
            results.append('No duplicates')

    return results

