def caesar_cipher(shift, message):
    """
    Encrypts the given message using Caesar Cipher with the given shift value.

    :param shift: The number of positions each letter in the message is shifted.
    :param message: The plaintext message to be encrypted.
    :return: The encrypted message.
    """
    encrypted_message = []
    for char in message:
        if char == " ":
            encrypted_message.append(" ")
        else:
            shifted_char = chr(((ord(char) - ord('a') + shift) % 26) + ord('a'))
            encrypted_message.append(shifted_char)
    return "".join(encrypted_message)

