def fizz_buzz(n):
    """
    Returns the FizzBuzz sequence from 1 to n.

    Parameters:
    n (int): The upper limit of the sequence (inclusive).

    Returns:
    list of str: The FizzBuzz sequence where each element follows the rule.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

