def can_draw_unique_lots(n, m, restricted_pairs):
    # Represent each card with a node in the graph.
    # If there is a restriction between two cards, it is an edge in the graph.
    graph = [[] for _ in range(n + 1)]

    for a, b in restricted_pairs:
        graph[a].append(b)
        graph[b].append(a)

    # To determine if it's possible to pick unique lots, we need to ensure that
    # the graph is bipartite.

    color = [-1] * (n + 1)

    def is_bipartite(v = 1):
        queue = [v]
        color[v] = 1

        while queue:
            node = queue.pop(0)
            for neighbor in graph[node]:
                if color[neighbor] == -1:
                    # Assign the opposite color to the neighbor
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    # If the neighbor has the same color, the graph is not bipartite
                    return False
        return True

    for i in range(1, n + 1):
        if color[i] == -1:
            if not is_bipartite(i):
                return "IMPOSSIBLE"

    return "POSSIBLE"

