def find_maximal_sum_subarray(arr):
    max_sum = current_sum = arr[0]
    start = end = temp_start = 0
    for i in range(1, len(arr)):
        if current_sum + arr[i] < arr[i]:
            current_sum = arr[i]
            temp_start = i
        else:
            current_sum += arr[i]

        if current_sum > max_sum or (current_sum == max_sum and i - temp_start < end - start):
            max_sum = current_sum
            start = temp_start
            end = i
    return arr[start:end+1], max_sum

def process_test_cases(t, test_cases):
    results = []
    for case in test_cases:
        n = case[0]
        arr = case[1:]
        subarray, max_sum = find_maximal_sum_subarray(arr)
        results.append(f"{subarray} {max_sum}")
    return results

