def find_element(matrix, n, k):
    """
    Returns "Yes" if the element k is found in the n x n matrix else returns "No".
    The matrix is sorted in ascending order both row-wise and column-wise.
    """
    row, col = 0, n - 1  # Start from the top-right corner of the matrix

    while row < n and col >= 0:
        if matrix[row][col] == k:
            return "Yes"
        elif matrix[row][col] > k:
            col -= 1
        else:
            row += 1

    return "No"

