def max_points(N, A):
    if N == 0:
        return 0
    if N == 1:
        return A[0]

    dp = [0] * N
    dp[0] = A[0]
    dp[1] = max(A[0], A[1])

    for i in range(2, N):
        dp[i] = max(dp[i-1], dp[i-2] + A[i])

    return dp[N-1]

