import heapq
from collections import Counter

def rearrange_string(s, k):
    if k == 1:
        return ''.join(sorted(s))  # For k = 1, just return the sorted string

    counter = Counter(s)
    max_heap = [(-freq, char) for char, freq in counter.items()]
    heapq.heapify(max_heap)

    queue = []
    result = []

    while max_heap or queue:
        if queue and queue[0][1] <= len(result):
            heapq.heappush(max_heap, queue.pop(0)[0])

        if not max_heap:
            return 'Not Possible'

        freq, char = heapq.heappop(max_heap)
        result.append(char)

        if -freq > 1:
            queue.append(((freq + 1, char), len(result) + k - 1))

    return ''.join(result)

