import math

def canBeSumOfSquares(x):
    """
    Determines if an integer x can be represented as the sum of two squares.
    """
    for a in range(int(math.isqrt(x)) + 1):
        b_squared = x - a*a
        if b_squared < 0:
            return "No"
        b = int(math.isqrt(b_squared))
        if b*b == b_squared:
            return "Yes"
    return "No"

