def takahashi_game(X, S):
    """
    Perform a series of 'double' and 'halve' operations on the initial integer X
    according to the instructions in string S.
    """
    for instruction in S:
        if instruction == 'd':
            X *= 2
        elif instruction == 'h':
            X //= 2
    return X

