def maxRobbedAmount(nums):
    """
    Returns the maximum amount of money that can be robbed without robbing two consecutive houses.

    :param nums: List of non-negative integers representing money in each house
    :return: Integer representing the maximum amount of money robable
    """
    if not nums:
        return 0
    elif len(nums) == 1:
        return nums[0]
    elif len(nums) == 2:
        return max(nums[0], nums[1])

    prev1, prev2 = 0, 0

    for num in nums:
        current = max(prev1, prev2 + num)
        prev2 = prev1
        prev1 = current

    return prev1

