def process_operations(n, k, grid, operations):
    for operation in operations:
        parts = operation.split()
        if parts[0] == "swap":
            r1, c1, r2, c2 = int(parts[1])-1, int(parts[2])-1, int(parts[3])-1, int(parts[4])-1
            grid[r1][c1], grid[r2][c2] = grid[r2][c2], grid[r1][c1]
        elif parts[0] == "add":
            r, c, v = int(parts[1])-1, int(parts[2])-1, int(parts[3])
            grid[r][c] += v
        elif parts[0] == "subtract":
            r, c, v = int(parts[1])-1, int(parts[2])-1, int(parts[3])
            grid[r][c] -= v
    return grid

def find_minimum_difference(T, test_cases):
    results = []
    for case in test_cases:
        N, M, A, B = case
        A.sort()
        B.sort()
        i = j = 0
        min_diff = float('inf')

        while i < N and j < M:
            min_diff = min(min_diff, abs(A[i] - B[j]))
            if A[i] < B[j]:
                i += 1
            else:
                j += 1

        results.append(min_diff)

    return results

