def is_hamiltonian_path_possible(n, m, routes, s):
    from collections import defaultdict, deque

    # Create an adjacency list to represent the graph
    graph = defaultdict(list)
    in_degrees = [0] * (n + 1)
    out_degrees = [0] * (n + 1)

    for u, v in routes:
        graph[u].append(v)
        in_degrees[v] += 1
        out_degrees[u] += 1

    # Check if any vertex does not have incoming or outgoing edges and is not the starting point
    for vertex in range(1, n + 1):
        if (in_degrees[vertex] == 0 or out_degrees[vertex] == 0) and vertex != s:
            return "Not Possible"

    # Try to find a Hamiltonian path using a modified DFS approach
    def can_visit_all(current, visited_count, visited):
        if visited_count == n:
            return True
        for neighbor in graph[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                if can_visit_all(neighbor, visited_count + 1, visited):
                    return True
                visited[neighbor] = False
        return False

    visited = [False] * (n + 1)
    visited[s] = True
    if can_visit_all(s, 1, visited):
        return "Possible"
    return "Not Possible"

