from collections import deque

def min_moves_to_target(s_i, s_j, t_i, t_j, blocked_cells):
    """
    Returns the minimum number of moves to reach the target cell (t_i, t_j) from the start cell (s_i, s_j).
    If it's not possible to reach the target cell, returns -1.
    """
    if (s_i, s_j) == (t_i, t_j):
        return 0

    blocked_set = set(blocked_cells)
    if (s_i, s_j) in blocked_set or (t_i, t_j) in blocked_set:
        return -1

    def neighbors(x, y):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if (nx, ny) not in blocked_set:
                yield (nx, ny)

    queue = deque([(s_i, s_j, 0)])
    visited = set()
    visited.add((s_i, s_j))

    while queue:
        x, y, dist = queue.popleft()
        for nx, ny in neighbors(x, y):
            if (nx, ny) == (t_i, t_j):
                return dist + 1
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

