def intersecting_pairs(T, test_cases):
    def do_overlap(r1, r2):
        # Check if one rectangle is to the left of the other or above/below the other
        if r1[2] <= r2[0] or r1[0] >= r2[2]:
            return False
        if r1[3] <= r2[1] or r1[1] >= r2[3]:
            return False
        return True

    results = []
    for i in range(T):
        N, rectangles = test_cases[i]
        count = 0
        for j in range(N):
            for k in range(j + 1, N):
                if do_overlap(rectangles[j], rectangles[k]):
                    count += 1
        results.append(count)

    return results

