from collections import deque

def burn_forest(forest):
    n = len(forest)
    m = len(forest[0])

    # Checking if the forest has only empty cells
    if all(forest[i][j] == '.' for i in range(n) for j in range(m)):
        return -1

    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    queue = deque([(0, 0, 0)])
    visited = set([(0, 0)])

    while queue:
        x, y, time = queue.popleft()

        # Spread the fire to all four directions
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and forest[nx][ny] == 'T':
                visited.add((nx, ny))
                queue.append((nx, ny, time + 1))

    # Check if all trees were burned
    for i in range(n):
        for j in range(m):
            if forest[i][j] == 'T' and (i, j) not in visited:
                return -1

    return time if queue else time

def maximize_sequence(k, sequence):
    """
    This function takes two parameters:
    k: an integer representing the number of digits in the original sequence
    sequence: a string of length k which includes digits (0-9) and/or placeholders ('?')

    The function returns the sequence such that the sum of its digits is maximized.
    In case of tie, it returns the lexicographically smallest sequence.
    """
    result = []

    for char in sequence:
        if char == '?':
            result.append('9')
        else:
            result.append(char)

    return ''.join(result)

def determine_profit_or_loss(transactions):
    total_revenue = 0
    for transaction in transactions:
        action, amount = transaction.split()
        amount = int(amount)
        if action == "sale":
            total_revenue += amount
        elif action == "return":
            total_revenue -= amount
    if total_revenue > 0:
        return "Profit"
    elif total_revenue < 0:
        return "Loss"
    else:
        return "No Profit No Loss"

def process_transactions(test_cases):
    results = []
    for transactions in test_cases:
        results.append(determine_profit_or_loss(transactions))
    return results

