def count_vowels(words):
    """
    Returns a dictionary with counts of each vowel (a, e, i, o, u) in the given list of words.
    """
    # Initialize a dictionary to hold the count of each vowel
    vowel_counts = {'a': 0, 'e': 0, 'i': 0, 'o': 0, 'u': 0}

    # Iterate through each word in the list
    for word in words:
        # Iterate through each character in the word
        for char in word:
            # If the character is a vowel, increment its count in the dictionary
            if char in vowel_counts:
                vowel_counts[char] += 1

    return vowel_counts

