def min_flips_to_make_valid(N, S):
    """
    Determines the minimum number of flips required to make the binary string valid.

    Args:
    N (int): The length of the binary string.
    S (str): The binary string.

    Returns:
    int: The minimum number of flips required.
    """
    # Pattern when starting with '0', e.g., "010101..."
    flip_0 = 0
    # Pattern when starting with '1', e.g., "101010..."
    flip_1 = 0

    for i in range(N):
        if i % 2 == 0:
            if S[i] != '0':
                flip_0 += 1
            if S[i] != '1':
                flip_1 += 1
        else:
            if S[i] != '1':
                flip_0 += 1
            if S[i] != '0':
                flip_1 += 1

    return min(flip_0, flip_1)

