def find_increasing_trio(n, heights):
    """
    Finds three student indices such that their heights are in strictly increasing order.
    If no such indices exist, returns [-1, -1, -1].
    """
    # Traverse the list and keep track of the smaller values on the left
    smallest = [None] * n
    smallest[0] = -1

    for i in range(1, n):
        if heights[i] > heights[0]:
            smallest[i] = 0
        else:
            smallest[i] = smallest[i - 1]

    # Traverse the list and find the increasing triplet
    for j in range(1, n):
        for k in range(j + 1, n):
            if heights[j] > heights[smallest[j]] and heights[k] > heights[j]:
                return [smallest[j] + 1, j + 1, k + 1]

    return [-1, -1, -1]

