def subset_sum(N, K, sequence):
    # Initialize a DP table of size (N+1) x (2*K+1)
    offset = 1000
    dp = [[False] * (2 * offset + 1) for _ in range(N + 1)]
    dp[0][offset] = True  # Base condition

    for i in range(1, N+1):
        for j in range(-offset, offset+1):
            if dp[i-1][j + offset]:
                dp[i][j + offset] = True  # don't include sequence[i-1]
                dp[i][j + sequence[i-1] + offset] = True  # include sequence[i-1]

    return "YES" if dp[N][K + offset] else "NO"

def subset_sum_solver(T, test_cases):
    results = []
    for test_case in test_cases:
        N, K, sequence = test_case
        results.append(subset_sum(N, K, sequence))
    return results

