def remove_duplicate_letters(s):
    """
    Removes duplicate letters from string s so that every letter appears once
    and only once. The result must be the smallest in lexicographic order among
    all possible results.
    """
    stack = []
    seen = set()
    last_occurrence = {ch: i for i, ch in enumerate(s)}

    for i, ch in enumerate(s):
        if ch not in seen:
            while stack and ch < stack[-1] and i < last_occurrence[stack[-1]]:
                seen.discard(stack.pop())
            seen.add(ch)
            stack.append(ch)

    return ''.join(stack)

def solve(test_cases):
    results = []
    for s in test_cases:
        results.append(remove_duplicate_letters(s))
    return results

