def can_fulfill_requests(n, m, packages, requests, k):
    results = []
    for si, ti, pi in requests:
        if pi <= k and packages[si-1] >= pi:
            results.append("yes")
            packages[si-1] -= pi  # Deduct the packages from the starting warehouse
        else:
