def can_reassign_letters(N, pairs):
    """
    Determine if it is possible to reassign the letters of the alphabet such that for each pair (s_i, t_i),
    s_i can be transformed into t_i.

    :param N: Number of string pairs
    :param pairs: List of tuple pairs (s_i, t_i)
    :returns: "YES" if transformation is possible for all pairs, otherwise "NO"
    """
    for s, t in pairs:
        if len(s) != len(t):
            return "NO"

        # Check mapping from s to t
        mapping_st = {}
        mapping_ts = {}
        for si, ti in zip(s, t):
            if si in mapping_st and mapping_st[si] != ti:
                return "NO"
            if ti in mapping_ts and mapping_ts[ti] != si:
                return "NO"
            mapping_st[si] = ti
            mapping_ts[ti] = si

    return "YES"

