def min_palindrome_partitions(t, cases):
    def is_palindrome(s):
        return s == s[::-1]

    result = []
    for s in cases:
        n = len(s)
        if is_palindrome(s):
            result.append(1)
        else:
            cuts = [0] * n
            for i in range(n):
                min_cut = i
                for j in range(i + 1):
                    if s[j:i + 1] == s[j:i + 1][::-1]:
                        min_cut = 0 if j == 0 else min(min_cut, cuts[j - 1] + 1)
                cuts[i] = min_cut
            result.append(cuts[-1] + 1)
    return result

