def longest_palindromic_substrings(s: str):
    """
    Returns all longest palindromic substrings of the given string s sorted lexicographically.
    """
    def expand_around_center(s, left, right):
        while left >= 0 and right < len(s) and s[left] == s[right]:
            left -= 1
            right += 1
        return s[left + 1:right]

    if not s:
        return ""

    longest = []
    max_length = 0

    for i in range(len(s)):
        # Odd length palindromes
        palindrome1 = expand_around_center(s, i, i)
        # Even length palindromes
        palindrome2 = expand_around_center(s, i, i + 1)

        longer_palindrome = palindrome1 if len(palindrome1) >= len(palindrome2) else palindrome2

        if len(longer_palindrome) > max_length:
            longest = [longer_palindrome]
            max_length = len(longer_palindrome)
        elif len(longer_palindrome) == max_length:
            longest.append(longer_palindrome)

    return ' '.join(sorted(set(longest)))

