def can_invite(friends, connections):
    """
    Returns True if there's an independent set of friends such that no two friends in this subset know each other.
    """
    from collections import defaultdict, deque

    # Build graph
    graph = defaultdict(set)
    for a, b in connections:
        graph[a].add(b)
        graph[b].add(a)

    color = {}

    def bfs(start):
        queue = deque([start])
        color[start] = 0
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor in color:
                    if color[neighbor] == color[node]:
                        return False
                else:
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
        return True

    for friend in friends:
        if friend not in color:
            if not bfs(friend):
                return False
    return True

