def assign_buses_to_routes(routes, buses):
    # Sort buses by their seating capacity in descending order
    buses.sort(reverse=True)

    # Sort routes by their demand and penalty in descending order of demand
    routes = sorted(routes, key=lambda x: (-x[1], -x[2]))

    assigned_routes = []
    total_penalty = 0

    for bus_index, bus_capacity in enumerate(buses):
        for route_index in range(len(routes)):
            if routes[route_index][1] <= bus_capacity:
                assigned_routes.append((bus_index + 1, routes[route_index][0]))
                routes.pop(route_index)
                break

    for route_index in range(len(routes)):
        total_penalty += routes[route_index][1] * routes[route_index][2]

    return len(assigned_routes), total_penalty, assigned_routes


def solve(bus_capacities, route_demands_penalties):
    routes = [(i + 1, demand, penalty) for i, (demand, penalty) in enumerate(route_demands_penalties)]
    assigned_routes_count, total_penalty, assignments = assign_buses_to_routes(routes, bus_capacities)

    print(assigned_routes_count, total_penalty)
    for bus, route in assignments:
        print(bus, route)

