from collections import deque

def min_moves_to_reach_end(N, M, grid):
    # Directions for moving up, down, left, right
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # BFS queue initialization
    queue = deque([(0, 0, 0)])  # (row, col, distance)
    visited = set((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        # If we reached the bottom-right corner
        if x == N - 1 and y == M - 1:
            return dist

        # Explore all possible movements
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and (nx, ny) not in visited and grid[nx][ny] == '.':
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

# Function to parse input and call the main function
def solve_puzzle_game(N, M, grid_lines):
    grid = [list(row) for row in grid_lines]
    return min_moves_to_reach_end(N, M, grid)

def max_reward(n, rewards):
    """
    Computes the maximum reward that can be collected by
    visiting checkpoints in a strictly increasing order.

    Args:
    n (int): the number of checkpoints.
    rewards (list of int): rewards at each checkpoint.

    Returns:
    int: the maximum reward that can be collected.
    """
    if n == 0:
        return 0

    # dp[i] will store the maximum reward collected ending at checkpoint i
    dp = [0] * n

    for i in range(n):
        dp[i] = rewards[i]
        for j in range(i):
            if rewards[j] < rewards[i]:
                dp[i] = max(dp[i], dp[j] + rewards[i])

    return max(dp)

