from collections import deque, defaultdict

def shortest_path(n, edges, start, end):
    """
    Returns the length of the shortest path between start and end nodes.
    If there is no path, returns -1.
    """
    if start == end:
        return 0

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        current_node, distance = queue.popleft()

        for neighbor in graph[current_node]:
            if neighbor == end:
                return distance + 1
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))

    return -1

import heapq

def dijkstra(graph, start, n):
    distances = [float('inf')] * (n + 1)
    distances[start] = 0
    pq = [(0, start)]

    while pq:
        current_distance, current_vertex = heapq.heappop(pq)

        if current_distance > distances[current_vertex]:
            continue

        for neighbor, weight in graph[current_vertex]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return distances

def process_graph(n, edges, queries):
    graph = [[] for _ in range(n + 1)]

    for u, v, w in edges:
        graph[u].append((v, w))

    results = []
    distance_from_all_nodes = {}

    for u, v in queries:
        if u not in distance_from_all_nodes:
            distance_from_all_nodes[u] = dijkstra(graph, u, n)
        shortest_path_weight = distance_from_all_nodes[u][v]
        if shortest_path_weight == float('inf'):
            results.append(-1)
        else:
            results.append(shortest_path_weight)

    return results

