from collections import deque

def min_moves_to_target(grid, n, m, sx, sy, tx, ty):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)] # Up, Down, Left, Right

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == '.'

    # Convert 1-based coordinates to 0-based
    start = (sx - 1, sy - 1)
    target = (tx - 1, ty - 1)

    if not is_valid(*start) or not is_valid(*target):
        return -1

    queue = deque([(start[0], start[1], 0)]) # (x, y, distance)
    visited = set()
    visited.add(start)

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == target:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

# Main function to translate input and output format
def superhero_grid_path(n, m, grid, sx, sy, tx, ty):
    return min_moves_to_target(grid, n, m, sx, sy, tx, ty)

