def smallest_missing_number(arr):
    """
    Returns the smallest number that is not present in the array.
    The returned number should also be greater than or equal to zero.
    """
    n = len(arr)
    presence = [False] * (n + 1)

    for num in arr:
        if 0 <= num <= n:
            presence[num] = True

    for i in range(n + 1):
        if not presence[i]:
            return i

    return n + 1

