def is_prime(num):
    """
    Check if the number is a prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    limit = int(num ** 0.5) + 1
    for i in range(3, limit, 2):
        if num % i == 0:
            return False
    return True

def can_form_magical_sequence(arr):
    """
    Determine if the array can be rearranged into a magical sequence.
    """
    prime_count = 0
    composite_count = 0

    for num in arr:
        if is_prime(num):
            prime_count += 1
        else:
            composite_count += 1

    return prime_count == 1 and composite_count == len(arr) - 1

