from collections import deque

def find_path(start, target, obstacles):
    directions = {
        "U": (-1, 0),
        "D": (1, 0),
        "L": (0, -1),
        "R": (0, 1)
    }

    def is_valid(x, y):
        return 0 <= x < 15 and 0 <= y < 15 and (x, y) not in obstacles

    queue = deque([(start[0], start[1], "")])
    visited = set()
    visited.add((start[0], start[1]))

    while queue:
        x, y, path = queue.popleft()

        if (x, y) == (target[0], target[1]):
            return path

        for dir in directions:
            new_x, new_y = x + directions[dir][0], y + directions[dir][1]
            if is_valid(new_x, new_y) and (new_x, new_y) not in visited:
                visited.add((new_x, new_y))
                queue.append((new_x, new_y, path + dir))

    return "NO PATH"

