def is_balanced(inputString):
    """
    Check if the parentheses in the input string are balanced and correctly nested.
    """
    stack = []
    matching_parentheses = {')': '(', ']': '[', '}': '{'}

    for char in inputString:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses.keys():
            if stack == [] or stack.pop() != matching_parentheses[char]:
                return False
    return stack == []

def check_shipment_in_inventory(inventory_list, shipment_list):
    """
    Returns "YES" if all items in the shipment list are found in the inventory list, otherwise "NO".
    """
    inventory_set = set(inventory_list)
    for item in shipment_list:
        if item not in inventory_set:
            return "NO"
    return "YES"

