def arrange_until_minus_one(lst):
    """
    Returns a new list that contains the elements of the original list arranged in ascending order up to the first
    occurrence of -1. The elements after the first occurrence of -1 remain in their original positions.
    """
    if -1 in lst:
        pos = lst.index(-1)
        return sorted(lst[:pos]) + lst[pos:]
    else:
        return sorted(lst)

