from itertools import permutations

def has_hamiltonian_cycle(N, M, edges):
    # Create adjacency matrix for the graph
    adj_matrix = [[0] * N for _ in range(N)]
    for (a, b) in edges:
        adj_matrix[a-1][b-1] = 1
        adj_matrix[b-1][a-1] = 1

    # Check all permutations for a Hamiltonian cycle
    nodes = range(N)
    for perm in permutations(nodes):
        is_cycle = True
        for i in range(N):
            if not adj_matrix[perm[i]][perm[(i + 1) % N]]:
                is_cycle = False
                break
        if is_cycle:
            return "YES"
    return "NO"

