def longest_balanced_subsequence(sequence):
    n = len(sequence)
    prefix_sum_to_index = {0: -1}
    prefix_sum = 0
    max_length = 0

    for i in range(n):
        prefix_sum += sequence[i]
        if prefix_sum in prefix_sum_to_index:
            subsequence_length = i - prefix_sum_to_index[prefix_sum]
            max_length = max(max_length, subsequence_length)
        else:
            prefix_sum_to_index[prefix_sum] = i

    return max_length

