def final_position(commands):
    """
    Calculate the final position of the robot on a 2D plane after executing all commands.

    Parameters:
    commands (str): A string containing the sequence of robot movements.

    Returns:
    tuple: A tuple (x, y) representing the final coordinates of the robot.
    """
    x, y = 0, 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
    return x, y

def floyd_warshall(n, roads):
    # Initialize distance matrix with 'inf' and 0s along the diagonal
    dist = [[float('inf')] * n for _ in range(n)]
    for i in range(n):
        dist[i][i] = 0

    # Fill in initial distances based on given roads
    for u, v, w in roads:
        dist[u-1][v-1] = min(dist[u-1][v-1], w)
        dist[v-1][u-1] = min(dist[v-1][u-1], w)

    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Convert 'inf' entries to -1 for no path situations
    for i in range(n):
        for j in range(n):
            if dist[i][j] == float('inf'):
                dist[i][j] = -1

    return dist

def byteland_product(test_cases):
    results = []
    for case in test_cases:
        N, K = case[0]
        array = case[1]
        product = 1
        for num in array:
            product = (product * num) % K
        results.append(product)
    return results

