import heapq

def find_shortest_paths(n, m, roads):
    graph = {i: [] for i in range(1, n+1)}
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))

    distances = {i: float('inf') for i in range(1, n+1)}
    distances[1] = 0
    priority_queue = [(0, 1)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return [distances[i] if distances[i] != float('inf') else -1 for i in range(1, n+1)]

def longest_increasing_subsequence_length(packets):
    """
    Returns the length of the longest strictly increasing subsequence in the list of packets.
    """
    if not packets:
        return 0

    n = len(packets)
    lis = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if packets[i] > packets[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    return max(lis)

