def longest_common_prefix(strs):
    """
    Returns the longest common prefix among the strings in the input list.
    If there is no common prefix, returns an empty string.
    """
    if not strs:
        return ""

    # The longest common prefix cannot be longer than the shortest string in the array.
    shortest_str = min(strs, key=len)

    for i, char in enumerate(shortest_str):
        for other in strs:
            if other[i] != char:
                return shortest_str[:i]

    return shortest_str

