from collections import defaultdict

def isCyclic(n, edges):
    """
    Determines if the undirected graph contains a cycle using DFS.

    Parameters:
    n (int): Number of vertices.
    edges (List[List[int]]): List of undirected edges.

    Returns:
    bool: True if the graph contains a cycle, False otherwise.
    """
    def dfs(v, parent):
        visited[v] = True

        for neighbor in graph[v]:
            if not visited[neighbor]:
                if dfs(neighbor, v):
                    return True
            elif parent != neighbor:
                return True

        return False

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            if dfs(i, -1):
                return True

    return False

