def does_robot_return(commands: str) -> bool:
    """
    Determines if the robot returns to its initial position after executing the sequence of commands.

    Parameters:
    - commands (str): The movement commands consisting of 'L', 'R', 'U', and 'D'.

    Returns:
    - bool: True if the robot returns to its initial position, False otherwise.
    """
    x, y = 0, 0

    for command in commands:
        if command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
        elif command == 'U':
            y += 1
        elif command == 'D':
            y -= 1

    return x == 0 and y == 0

