def min_adjacent_swaps_to_sort(heights):
    """
    Returns the minimum number of adjacent swaps required to sort the list of heights.
    """
    n = len(heights)
    count = 0
    # Perform bubble sort and count the swaps
    for i in range(n):
        for j in range(0, n-i-1):
            if heights[j] > heights[j+1]:
                heights[j], heights[j+1] = heights[j+1], heights[j]
                count += 1
    return count

