def min_changes_to_alternating(T, strings):
    results = []
    for S in strings:
        changes_1 = 0  # Assume starting with 'A'
        changes_2 = 0  # Assume starting with 'B'

        for i, c in enumerate(S):
            if i % 2 == 0:  # Even index
                if c != 'A':
                    changes_1 += 1
                if c != 'B':
                    changes_2 += 1
            else:  # Odd index
                if c != 'B':
                    changes_1 += 1
                if c != 'A':
                    changes_2 += 1

        results.append(min(changes_1, changes_2))

    return results

