def distinct_path_sums(grid):
    """
    Returns the number of distinct path sums from the top-left to the bottom-right of the grid.
    """
    N = len(grid)
    M = len(grid[0])

    from collections import defaultdict
    dp = defaultdict(set)
    dp[(0, 0)].add(grid[0][0])

    for r in range(N):
        for c in range(M):
            if r > 0:
                for s in dp[(r-1, c)]:
                    dp[(r, c)].add(s + grid[r][c])
            if c > 0:
                for s in dp[(r, c-1)]:
                    dp[(r, c)].add(s + grid[r][c])

    return len(dp[(N-1, M-1)])

# Function to read the input, process and return number of distinct path sums
def process_input_return_distinct_path_sums(N, M, grid_values):
    grid = []
    for i in range(N):
        grid.append(list(map(int, grid_values[i])))
    return distinct_path_sums(grid)

