def minDanger(N, danger):
    if N == 0:
        return 0

    dp = [[0] * 3 for _ in range(N)]

    dp[0][0] = danger[0][0]
    dp[0][1] = danger[0][1]
    dp[0][2] = danger[0][2]

    for i in range(1, N):
        dp[i][0] = danger[i][0] + min(dp[i-1][1], dp[i-1][2])
        dp[i][1] = danger[i][1] + min(dp[i-1][0], dp[i-1][2])
        dp[i][2] = danger[i][2] + min(dp[i-1][0], dp[i-1][1])

    return min(dp[N-1][0], dp[N-1][1], dp[N-1][2])

def largest_product(digits, n):
    if not digits or n <= 0 or n > len(digits) or any(c not in '0123456789' for c in digits):
        return 0

    max_product = 0

    for i in range(len(digits) - n + 1):
        product = 1
        for j in range(n):
            product *= int(digits[i + j])
        max_product = max(max_product, product)

    return max_product

def max_non_overlapping_events(t, test_cases):
    results = []

    for case in test_cases:
        n, events = case
        events.sort(key=lambda x: x[1])  # Sort events by their end times
        max_events = 0
        last_end_time = -1

        for event in events:
            if event[0] >= last_end_time:
                max_events += 1
                last_end_time = event[1]

        results.append(max_events)

    return results

