def most_frequent_character(s):
    """
    Returns the alphabetic character that appears the highest number of times in the string s.
    If two or more characters have the highest frequency, returns the character which comes
    first alphabetically. If the string is empty, returns None.
    """
    if not s:
        return None

    frequency = {}
    for char in s:
        if char in frequency:
            frequency[char] += 1
        else:
            frequency[char] = 1

    max_frequency = max(frequency.values())
    most_frequent_chars = [char for char, count in frequency.items() if count == max_frequency]

    return min(most_frequent_chars)

