def is_jolly_jumper(n, sequence):
    if n <= 1:
        return True

    diffs = set()
    for i in range(1, n):
        diff = abs(sequence[i] - sequence[i - 1])
        if diff == 0 or diff >= n or diff in diffs:
            return False
        diffs.add(diff)

    return len(diffs) == n - 1

