def is_super_palindrome(s):
    """
    Check if the given string is a Super Palindrome.
    """
    # Split the string into words
    words = s.split()

    # Check if each word is a palindrome
    for word in words:
        if word != word[::-1]:
            return "false"

    # Check if the string read as a whole in reverse matches the original
    if s == ' '.join(reversed(words)):
        return "true"
    else:
        return "false"

