def is_prime(n):
    """
    Check if a number n is prime. A number is prime if it is greater than 1 and is only divisible by 1 and itself.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_palindrome(n):
    """
    Check if a number n is a palindrome. A number is a palindrome if it reads the same forwards and backwards.
    """
    return str(n) == str(n)[::-1]

def smallest_prime_palindrome(m):
    """
    Find the smallest prime palindrome greater than or equal to m.
    """
    while True:
        if is_prime(m) and is_palindrome(m):
            return m
        m += 1

