def largestCubeRoot(n):
    """
    Finds the largest integer k such that k^3 ≤ n.
    """
    if n == 0:
        return 0

    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        if mid**3 <= n:
            low = mid + 1
        else:
            high = mid - 1

    return high

