def process_queries(n, m, q, grid, queries):
    results = []

    for query in queries:
        if query[0] == 1:
            _, x, y, v = query
            grid[x-1][y-1] = v
        elif query[0] == 2:
            _, x1, y1, x2, y2 = query
            max_val = -1
            for i in range(x1-1, x2):
                for j in range(y1-1, y2):
                    if grid[i][j] > max_val:
                        max_val = grid[i][j]
            results.append(max_val)
        elif query[0] == 3:
            _, x = query
            all_even = all(value % 2 == 0 for value in grid[x-1])
            if all_even:
                results.append("Yes")
            else:
                results.append("No")

    return results

def findMaxLength(arr):
    """
    Finds the length of the longest subarray with an equal number of 0s and 1s.
    """
    # Dictionary to store the first occurrence of each cumulative sum
    first_occurrence = {}
    curr_sum = 0
    max_len = 0

    for i in range(len(arr)):
        # Replace 0 with -1 to treat the problem similar to finding subarrays with sum 0
        if arr[i] == 0:
            curr_sum += -1
        else:
            curr_sum += 1

        if curr_sum == 0:
            max_len = i + 1
        elif curr_sum in first_occurrence:
            max_len = max(max_len, i - first_occurrence[curr_sum])
        else:
            first_occurrence[curr_sum] = i

    return max_len

