def can_traverse(paths, start_room, end_room):
    """
    Determines if there is a path from start_room to end_room.

    Parameters:
    paths (list of tuples): A list of tuples where each tuple represents a one-way path from one room to another.
    start_room: The room identifier to start from.
    end_room: The room identifier to reach.

    Returns:
    bool: True if there is a path from start_room to end_room, False otherwise.
    """
    from collections import defaultdict

    # Create adjacency list
    adjacency_list = defaultdict(list)
    for (src, dest) in paths:
        adjacency_list[src].append(dest)

    # Depth-First Search (DFS) to check for path
    def dfs(current, target, visited):
        if current == target:
            return True
        visited.add(current)
        for neighbor in adjacency_list[current]:
            if neighbor not in visited:
                if dfs(neighbor, target, visited):
                    return True
        return False

    return dfs(start_room, end_room, set())

