def update_inventory(m, operations):
    """
    Update the inventory based on a list of operations.

    Parameters:
    - m: int, the number of operations.
    - operations: list of tuples, where each tuple is an operation in the form
                  ("ADD" or "REMOVE", ISBN, count).

    Returns:
    - dict, the final inventory with ISBN as keys and counts as values.
    """
    inventory = {}

    for operation in operations:
        action, isbn, count = operation
        count = int(count)

        if action == 'ADD':
            if isbn in inventory:
                inventory[isbn] += count
            else:
                inventory[isbn] = count
        elif action == 'REMOVE':
            if isbn in inventory and inventory[isbn] >= count:
                inventory[isbn] -= count
                if inventory[isbn] == 0:
                    del inventory[isbn]

    # Return the sorted inventory
    return {isbn: inventory[isbn] for isbn in sorted(inventory)}

# Function to format the output as required by the question
def inventory_to_string(inventory):
    return '\n'.join(f"{isbn} {count}" for isbn, count in sorted(inventory.items()))

