from collections import deque

def minimal_synchronizations(N, initial_versions, M, connections):
    max_version = max(initial_versions)

    graph = [[] for _ in range(N)]
    for a, b in connections:
        graph[a-1].append(b-1)

    queue = deque([(i, 0) for i in range(N) if initial_versions[i] == max_version])
    visited = [False] * N
    for i in range(N):
        if initial_versions[i] == max_version:
            visited[i] = True

    counter = 0

    while queue:
        node, step = queue.popleft()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                initial_versions[neighbor] = max_version
                visited[neighbor] = True
                queue.append((neighbor, step + 1))
                counter = step + 1

    if all(version == max_version for version in initial_versions):
        return counter
    else:
        return -1

def can_distribute_bonuses(N, M, matchups):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in matchups:
        graph[u].append(v)
        graph[v].append(u)

    color = {}

    def bfs(node):
        queue = deque([node])
        color[node] = 0

        while queue:
            current = queue.popleft()
            for neighbor in graph[current]:
                if neighbor in color:
                    if color[neighbor] == color[current]:
                        return False
                else:
                    color[neighbor] = 1 - color[current]
                    queue.append(neighbor)
        return True

    for node in range(1, N + 1):
        if node not in color:
            if not bfs(node):
                return "NO"

    return "YES"

