def closest_three_sum(n, target, arr):
    """
    Returns a tuple of three integers from the list such that the sum is closest to the given target.
    """

    arr.sort()
    closest_sum = float('inf')
    closest_tuple = ()

    for i in range(n - 2):
        left, right = i + 1, n - 1

        while left < right:
            current_sum = arr[i] + arr[left] + arr[right]

            if abs(target - current_sum) < abs(target - closest_sum):
                closest_sum = current_sum
                closest_tuple = (arr[i], arr[left], arr[right])

            if current_sum < target:
                left += 1
            elif current_sum > target:
                right -= 1
            else:
                return (arr[i], arr[left], arr[right])

    return closest_tuple

from typing import List
from collections import deque

def wallsAndGates(grid: List[List[int]]) -> None:
    INF = 2**31 - 1
    rows, cols = len(grid), len(grid[0])
    queue = deque()

    # Enqueue all gates (0s)
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                queue.append((r, c))

    # BFS from the gates
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    while queue:
        r, c = queue.popleft()
        for dr, dc in directions:
            rr, cc = r + dr, c + dc
            if 0 <= rr < rows and 0 <= cc < cols and grid[rr][cc] == INF:
                grid[rr][cc] = grid[r][c] + 1
                queue.append((rr, cc))

