def find_max_donations_team(n, donations):
    from collections import defaultdict

    team_donations = defaultdict(int)

    for name, donation in donations:
        team_donations[name] += donation

    max_donation = max(team_donations.values())
    max_teams = [team for team, amount in team_donations.items() if amount == max_donation]

    return min(max_teams)

