def find_minimum_spanning_tree(N, M, roads):
    """
    Returns the minimum possible total length of roads that connects all cities,
    or -1 if not possible to connect all cities.
    """
    if M == 0:
        return -1 if N > 1 else 0  # No roads and more than one city means we can't connect all cities.

    from heapq import heappop, heappush

    # Start with a graph represented as adjacency list
    graph = {i: [] for i in range(1, N+1)}

    for u, v, w in roads:
        graph[u].append((w, v))
        graph[v].append((w, u))

    # Prim's Algorithm to find MST
    min_heap = [(0, 1)]  # (cost, start_node)
    visited = set()
    total_cost = 0

    while min_heap and len(visited) < N:
        cost, u = heappop(min_heap)
        if u not in visited:
            total_cost += cost
            visited.add(u)
            for next_cost, v in graph[u]:
                if v not in visited:
                    heappush(min_heap, (next_cost, v))

    return total_cost if len(visited) == N else -1

