from collections import deque

def shoe_order_system(operations):
    queue = deque()
    results = []

    for operation in operations:
        if operation.startswith("place_order"):
            _, x = operation.split()
            queue.append(int(x))
        elif operation == "process_order":
            if queue:
                queue.popleft()
        elif operation == "peek_order":
            if queue:
                results.append(queue[0])
        elif operation == "count_orders":
            results.append(len(queue))

    return results

# Read input operations
def process_input(input_lines):
    n = int(input_lines[0])
    operations = input_lines[1: n + 1]
    return shoe_order_system(operations)

def max_photos(n, C, battery_powers, recharge_points):
    recharge_set = set(recharge_points)
    battery = C
    count = 0

    for i, power in enumerate(battery_powers):
        if battery >= power:
            battery -= power
            count += 1
        else:
            break

        if (i + 1) in recharge_set:
            battery = C  # Recharge to full battery

    return count

