def is_prime(n):
    """
    Returns True if n is a prime number, else False.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def level_checker(levels):
    """
    Returns the average level (rounded to the nearest integer) of names whose levels are prime numbers.
    If there are no prime levels, returns 0.
    """
    prime_levels = [level for level in levels.values() if is_prime(level)]
    if not prime_levels:
        return 0
    return round(sum(prime_levels) / len(prime_levels))

