def longest_increasing_subsequence(heights):
    """
    Finds the length of the longest increasing subsequence in a list of heights.
    Args:
    - heights (list of int): The heights of the plant over several days.

    Returns:
    int: The length of the longest increasing subsequence.
    """
    if not heights:
        return 0

    # LIS array to store the subsequence lengths
    lis = [1] * len(heights)

    # Build the lis array
    for i in range(1, len(heights)):
        for j in range(i):
            if heights[i] > heights[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Return the maximum value in lis array
    return max(lis)

