def is_magic_square(matrix, row, col):
    """
    Helper function to check if a 3x3 grid with top-left corner at (row, col)
    is a magic square.
    """
    s = set()

    # Sum of the first row
    magic_sum = sum(matrix[row][col:col+3])
    for i in range(3):
        if sum(matrix[row+i][col:col+3]) != magic_sum:
            return False
        s.update(matrix[row+i][col:col+3])

    for j in range(3):
        col_sum = sum(matrix[row+i][col+j] for i in range(3))
        if col_sum != magic_sum:
            return False

    # Sum of diagonals
    if sum(matrix[row+i][col+i] for i in range(3)) != magic_sum:
        return False
    if sum(matrix[row+i][col+2-i] for i in range(3)) != magic_sum:
        return False

    return len(s) == 9  # There should be exactly 9 distinct values

def contains_magic_square(grid):
    """
    Returns "YES" if the grid contains any magic square of size 3x3, otherwise "NO".
    """
    n = len(grid)
    for i in range(n - 2):
        for j in range(n - 2):
            if is_magic_square(grid, i, j):
                return "YES"
    return "NO"

