def findMedian(matrix):
    """
    Returns the median of a matrix where each row is sorted in ascending order.
    """
    r = len(matrix)  # number of rows
    c = len(matrix[0])  # number of columns

    def countLessthanEqual(matrix, mid):
        count = 0
        for i in range(r):
            l, h = 0, c-1
            while l <= h:
                md = (l + h) // 2
                if matrix[i][md] <= mid:
                    l = md + 1
                else:
                    h = md - 1
            count += l
        return count

    low, high = matrix[0][0], matrix[0][0]
    for i in range(r):
        low = min(low, matrix[i][0])
        high = max(high, matrix[i][c-1])

    while low < high:
        mid = (low + high) // 2
        count = countLessthanEqual(matrix, mid)

        if count < (r * c + 1) // 2:
            low = mid + 1
        else:
            high = mid
    return low

