def process_bookings(test_cases):
    """
    Processes a given list of bookings and cancellations, returning the final
    list of booked packages for each customer, sorted alphabetically.

    :param test_cases: A list of test cases where each test case contains a list of actions.
    :return: A list of strings representing the final booking list for each customer.
    """
    results = []

    for actions in test_cases:
        booking_dict = {}
        for action in actions:
            customer_id, action_type, package = action
            if customer_id not in booking_dict:
                booking_dict[customer_id] = set()
            if action_type == 'book':
                booking_dict[customer_id].add(package)
            elif action_type == 'cancel' and package in booking_dict[customer_id]:
                booking_dict[customer_id].remove(package)

        result_lines = []
        for customer in sorted(booking_dict):
            packages = sorted(booking_dict[customer])
            result_lines.append(f"{customer}: {packages}")

        results.append('\n'.join(result_lines))

    return results

