def find_closest_sum_pair(nums, target):
    """
    Finds two integers in nums whose sum is closest to the target.
    """
    nums.sort()
    closest_sum = float('inf')
    closest_pair = (0, 0)

    left, right = 0, len(nums) - 1

    while left < right:
        current_sum = nums[left] + nums[right]
        if abs(target - current_sum) < abs(target - closest_sum):
            closest_sum = current_sum
            closest_pair = (nums[left], nums[right])

        if current_sum < target:
            left += 1
        elif current_sum > target:
            right -= 1
        else:
            break

    return closest_pair

from typing import List, Dict

def most_active_user(messages: List[Dict[str, str]]) -> str:
    user_counts = {}
    for message in messages:
        username = message['username']
        if username not in user_counts:
            user_counts[username] = 0
        user_counts[username] += 1

    most_active = None
    max_count = 0

    for message in messages:
        username = message['username']
        if user_counts[username] > max_count:
            max_count = user_counts[username]
            most_active = username

    return most_active

def findPaths(grid):
    """
    Returns the number of ways to reach the bottom-right corner of the grid from the top-left corner.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    n = len(grid)
    m = len(grid[0])

    dp = [[0] * m for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

