def process_library_operations(n, operations):
    user_books = {}
    results = []

    for operation in operations:
        action, user_id = operation.split()
        user_id = int(user_id)

        if action == 'borrow':
            if user_id in user_books and user_books[user_id] == 1:
                results.append(f"User {user_id} cannot borrow another book.")
            else:
                user_books[user_id] = 1
                results.append(f"User {user_id} borrowed a book.")
        elif action == 'return':
            if user_id in user_books and user_books[user_id] == 1:
                user_books[user_id] = 0
                results.append(f"User {user_id} returned the book.")
            else:
                results.append(f"User {user_id} cannot return a book they haven't borrowed.")

    return results

