def can_complete_circular_route(n, fuel):
    total_fuel = 0
    total_cost = 0
    current_fuel = 0
    start_index = 0

    for i in range(n):
        total_fuel += fuel[i]
        total_cost += (i + 1)
        current_fuel += fuel[i] - (i + 1)

        if current_fuel < 0:
            start_index = i + 1
            current_fuel = 0

    if total_fuel >= total_cost:
        return "YES"
    else:
        return "NO"

