import math
from itertools import combinations

def distance(troll1, troll2):
    return math.sqrt((troll1[0] - troll2[0]) ** 2 + (troll1[1] - troll2[1]) ** 2)

def max_trolls_affected(N, R, trolls):
    max_affected = 0

    for troll1, troll2 in combinations(trolls, 2):
        mid_point = ((troll1[0] + troll2[0]) / 2, (troll1[1] + troll2[1]) / 2)
        if distance(troll1, mid_point) <= R:
            count = sum(1 for troll in trolls if distance(troll, mid_point) <= R)
            max_affected = max(max_affected, count)

    for troll in trolls:
        count = sum(1 for other in trolls if distance(troll, other) <= R)
        max_affected = max(max_affected, count)

    return max_affected

# Input Reading and Handling
def main():
    N, R = map(int, input().split())
    trolls = [tuple(map(int, input().split())) for _ in range(N)]
    print(max_trolls_affected(N, R, trolls))

