def longestFibSubseq(A):
    """
    Takes an integer list and returns the length of the longest Fibonacci-like subsequence.
    If there is no such subsequence, returns 0.
    """
    if not A or len(A) < 3:
        return 0

    index = {x: i for i, x in enumerate(A)}
    longest = {}
    max_len = 0

    for k in range(len(A)):
        for j in range(k):
            i = index.get(A[k] - A[j], None)
            if i is not None and i < j:
                cand = longest.get((i, j), 2) + 1
                longest[(j, k)] = cand
                max_len = max(max_len, cand)

    return max_len if max_len >= 3 else 0

