def is_quasi_palindrome(s):
    """
    Returns True if the string s can be a palindrome by removing at most one character, False otherwise.
    """
    # Helper function to check if a substring is a palindrome
    def is_palindrome_range(l, r):
        while l < r:
            if s[l] != s[r]:
                return False
            l += 1
            r -= 1
        return True

    l, r = 0, len(s) - 1
    while l < r:
        if s[l] != s[r]:
            # Try removing character at l or r and check if it's a palindrome
            return is_palindrome_range(l + 1, r) or is_palindrome_range(l, r - 1)
        l += 1
        r -= 1
    return True

def determine_quasi_palindromes(n, strings):
    """
    Determines if each string in the list 'strings' is a quasi-palindrome.

    Parameters:
    - n: int, the number of datasets
    - strings: list of str, the strings to check

    Returns:
    - list of str, "YES" or "NO" for each string
    """
    results = []
    for s in strings:
        if is_quasi_palindrome(s):
            results.append("YES")
        else:
            results.append("NO")
    return results

