def warehouse_operations(n, operations):
    """
    Function to process warehouse operations and return the results of queries.

    :param n: Number of operations (int)
    :param operations: List of strings where each string is an operation of the form "add X Y" or "query X"
    :return: List of integers which are the results of the queries
    """
    stock = {}
    results = []

    for operation in operations:
        parts = operation.split()
        if parts[0] == "add":
            product_code = int(parts[1])
            quantity = int(parts[2])
            if product_code in stock:
                stock[product_code] += quantity
            else:
                stock[product_code] = quantity
        elif parts[0] == "query":
            product_code = int(parts[1])
            results.append(stock.get(product_code, 0))

    return results

