def shortest_palindrome(s):
    """
    Returns the shortest palindrome that can be formed by adding characters to the start of the given string.
    """
    if s == s[::-1]:
        return s

    for i in range(len(s) - 1, -1, -1):
        if s[:i + 1] == s[:i + 1][::-1]:
            return s[i + 1:][::-1] + s

    return s[::-1] + s

