from collections import defaultdict, deque

def can_transfer_power(n, m, p, lines, s, t):
    def bfs(source, target):
        visited = set()
        queue = deque([source])
        while queue:
            node = queue.popleft()
            if node == target:
                return True
            for neighbor in adj_list[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return False

    adj_list = defaultdict(list)
    for ai, bi, ci in lines:
        if ci >= p:
            adj_list[ai].append(bi)
            adj_list[bi].append(ai)

    return "YES" if bfs(s, t) else "NO"

def find_special_index(n, sequence):
    if n == 1:
        return 1 if sequence[0] == 1 else -1

    prefix_product = [1] * n
    suffix_product = [1] * n

    # Building prefix product array
    for i in range(1, n):
        prefix_product[i] = prefix_product[i - 1] * sequence[i - 1]

    # Building suffix product array
    for i in range(n - 2, -1, -1):
        suffix_product[i] = suffix_product[i + 1] * sequence[i + 1]

    # Finding the special index
    for i in range(n):
        if prefix_product[i] == suffix_product[i]:
            return i + 1

    return -1

