def find_smallest_missing_prime(numbers):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = set()
    i = 2
    while len(primes) < 500:
        if is_prime(i):
            primes.add(i)
        i += 1

    numbers_set = set(numbers)
    for prime in sorted(primes):
        if prime not in numbers_set:
            return prime

