def exist(board, word):
    if not board:
        return False

    rows, cols = len(board), len(board[0])

    def dfs(r, c, index):
        if index == len(word):
            return True
        if not (0 <= r < rows) or not (0 <= c < cols) or board[r][c] != word[index]:
            return False

        # Mark this cell as visited
        temp, board[r][c] = board[r][c], '#'
        found = (dfs(r+1, c, index+1) or
                 dfs(r-1, c, index+1) or
                 dfs(r, c+1, index+1) or
                 dfs(r, c-1, index+1))
        board[r][c] = temp
        return found

    for r in range(rows):
        for c in range(cols):
            if dfs(r, c, 0):
                return True
    return False

def find_words_in_grid(grid, words):
    result = []
    for word in words:
        if exist([list(row) for row in grid], word):
            result.append("YES")
        else:
            result.append("NO")
    return result

