def find_indices(arr, target):
    """
    Given a list of integers `arr` and an integer `target`,
    return the indices of the two numbers in the list that add up to the `target`.
    """
    num_to_index = {}

    for index, num in enumerate(arr):
        complement = target - num
        if complement in num_to_index:
            return [num_to_index[complement], index]
        num_to_index[num] = index

    return []  # This line theoretically will never be reached since there is always exactly one solution.

