def can_travel(grid, n, h):
    from collections import deque

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def bfs(height_diff):
        queue = deque([(0, 0)])
        visited = set((0, 0))

        while queue:
            x, y = queue.popleft()

            if (x, y) == (n-1, n-1):
                return True

            for dx, dy in directions:
                nx, ny = x + dx, y + dy

                if 0 <= nx < n and 0 <= ny < n and (nx, ny) not in visited:
                    if abs(grid[nx][ny] - grid[x][y]) <= height_diff:
                        queue.append((nx, ny))
                        visited.add((nx, ny))

        return False

    left, right = 0, max(max(row) for row in grid)

    while left < right:
        mid = (left + right) // 2

        if bfs(mid):
            right = mid
        else:
            left = mid + 1

    return left

def find_min_height_diff(n, m, grid):
    return can_travel(grid, n, m)

