def max_altitude(steps: str) -> int:
    """
    Returns the maximum altitude achieved during the sequence of steps.
    """
    current_altitude = 0
    max_altitude = 0

    for step in steps:
        if step == '+':
            current_altitude += 1
        elif step == '-':
            current_altitude -= 1
        max_altitude = max(max_altitude, current_altitude)

    return max_altitude

