def is_palindromic_subsequence_exists(dna_seq, k):
    n = len(dna_seq)
    if k > n:
        return "NO"

    # Dynamic programming table to store the length of the longest palindromic
    # subsequence in dna_seq[i...j]
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # All substrings of length 1 are palindromes
    for i in range(n):
        dp[i][i] = 1

    # Build the dp table
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if dna_seq[i] == dna_seq[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Check if there is a palindromic subsequence of length k
    return "YES" if any(dp[i][j] >= k for i in range(n) for j in range(i + k - 1, n)) else "NO"

