def longest_chain(words):
    word_set = set(words)
    longest = 0
    dp = {}

    for word in sorted(words, key=len):
        dp[word] = 1
        for i in range(len(word)):
            predecessor = word[:i] + word[i+1:]
            if predecessor in word_set:
                dp[word] = max(dp[word], dp[predecessor] + 1)
        longest = max(longest, dp[word])

    return longest

