def min_removals_to_increasing_array(A):
    """
    Returns the minimum number of elements to remove from A to make it strictly increasing
    and the list of elements to remove.
    """
    removals = []
    last_seen = set()

    for num in A:
        if num in last_seen:
            removals.append(num)
        else:
            last_seen.add(num)

    return len(removals), removals

