def countIslands(grid):
    def dfs(x, y):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == 'W':
            return
        grid[x][y] = 'W'  # Mark as visited
        # Explore adjacent cells
        dfs(x+1, y)
        dfs(x-1, y)
        dfs(x, y+1)
        dfs(x, y-1)

    if not grid:
        return 0

    num_islands = 0

    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == 'L':
                num_islands += 1
                dfs(i, j)

    return num_islands

def findProduct(N, A):
    """
    Computes the product of all non-zero elements in the array A of size N.
    """
    product = 1
    found_non_zero = False
    for num in A:
        if num != 0:
            product *= num
            found_non_zero = True
    if not found_non_zero:
        return 0
    return product

