import random

def game() -> str:
    """
    Simulates a "Guess the Number" game where the computer selects a random number between 1 and 100,
    and the user attempts to guess the number. The function provides feedback after each guess and
    returns the number of attempts once the user guesses correctly.
    """
    number_to_guess = random.randint(1, 100)
    attempts = 0

    while True:
        try:
            guess = int(input("Enter your guess (between 1 and 100): "))
            attempts += 1

            if guess < number_to_guess:
                print("Too low!")
            elif guess > number_to_guess:
                print("Too high!")
            else:
                return f"Congratulations! You've guessed the correct number in {attempts} attempts."
        except ValueError:
            print("Please enter a valid integer.")

def can_reach_target(xs, ys, xt, yt, u, d, l, r):
    """
    Determine if the robot can reach the target position given the constraints on the number of moves.
    """
    dx = xt - xs
    dy = yt - ys

    if dx >= 0 and dx <= r and dx >= -l and dy >= 0 and dy <= u and dy >= -d:
        return "YES"
    elif dx <= 0 and -dx <= l and dx >= -r and dy >= 0 and dy <= u and dy >= -d:
        return "YES"
    elif dx <= 0 and -dx <= l and dx >= -r and dy <= 0 and -dy <= d and dy >= -u:
        return "YES"
    elif dx >= 0 and dx <= r and dx >= -l and dy <= 0 and -dy <= d and dy >= -u:
        return "YES"
    else:
        return "NO"

