def max_active_developers(test_cases):
    results = []
    for case in test_cases:
        N, K, activity = case
        max_active = 0
        current_active_streak = 0

        for day in activity:
            if day == 1:
                current_active_streak += 1
            else:
                if current_active_streak >= K:
                    max_active += 1
                current_active_streak = 0

        if current_active_streak >= K:
            max_active += 1

        results.append(max_active)
    return results

def process_input(input_str):
    input_lines = input_str.strip().split('\n')
    T = int(input_lines[0])
    test_cases = []
    index = 1

    for _ in range(T):
        N, K = map(int, input_lines[index].split())
        activity = list(map(int, input_lines[index + 1].split()))
        test_cases.append((N, K, activity))
        index += 2

    return test_cases

