def min_difference(n, ratings):
    from functools import lru_cache

    total_sum = sum(ratings)

    @lru_cache(None)
    def dfs(i, curr_sum):
        if i == n:
            return abs((total_sum - curr_sum) - curr_sum)
        return min(dfs(i + 1, curr_sum + ratings[i]), dfs(i + 1, curr_sum))

    return dfs(0, 0)

