import heapq
from typing import List, Tuple, Dict

def shortestTravelTime(n: int, roads: List[Tuple[int, int, int]], start: int, end: int) -> int:
    """
    Find the shortest travel time between two specified warehouses using Dijkstra's algorithm.
    """
    # Create adjacency list for the graph
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in roads:
        graph[u].append((v, w))
        graph[v].append((u, w))  # Assuming undirected roads

    # Implement Dijkstra's algorithm
    def dijkstra(start: int, end: int) -> int:
        min_heap = [(0, start)]  # (travel_time, node)
        shortest_time = {i: float('inf') for i in range(1, n + 1)}
        shortest_time[start] = 0

        while min_heap:
            curr_time, u = heapq.heappop(min_heap)
            if u == end:
                return curr_time
            for v, w in graph[u]:
                new_time = curr_time + w
                if new_time < shortest_time[v]:
                    shortest_time[v] = new_time
                    heapq.heappush(min_heap, (new_time, v))

        return -1 if shortest_time[end] == float('inf') else shortest_time[end]

    return dijkstra(start, end)

