from typing import List

def find_path(grid: List[List[int]]) -> str:
    rows = len(grid)
    cols = len(grid[0])

    def backtrack(r, c, path):
        if r >= rows or c >= cols or grid[r][c] == 0:
            return False

        if r == rows - 1 and c == cols - 1:
            return True

        # Mark this cell as visited
        grid[r][c] = 0

        # Move right
        if backtrack(r, c + 1, path):
            path.append('R')
            return True

        # Move down
        if backtrack(r + 1, c, path):
            path.append('D')
            return True

        # Unmark this cell
        grid[r][c] = 1
        return False

    path = []
    if backtrack(0, 0, path):
        return ''.join(reversed(path))
    else:
        return 'NO PATH'

