def look_and_say(n: int) -> str:
    """
    Returns the n-th term in the look-and-say sequence.
    """
    if n == 1:
        return "1"

    def next_term(current: str) -> str:
        result = []
        i = 0
        while i < len(current):
            count = 1
            while i + 1 < len(current) and current[i] == current[i + 1]:
                i += 1
                count += 1
            result.append(f"{count}{current[i]}")
            i += 1
        return ''.join(result)

    term = "1"
    for _ in range(1, n):
        term = next_term(term)

    return term

