def construct_array(n):
    """
    Determines if it's possible to construct an array of length `n`
    containing only the integers 1 and 2 such that the absolute
    difference between the counts of 1s and 2s in any prefix of the
    array is at most 1. If possible, returns one such array.
    If not, returns "Impossible".
    """
    if n == 1:
        return [1]
    elif n == 2:
        return [1, 2]
    else:
        array = []
        for i in range(n):
            if (i % 2) == 0:
                array.append(1)
            else:
                array.append(2)
        return array

