from typing import List

def findLargestSquare(matrix: List[List[int]]) -> int:
    if not matrix:
        return 0

    n = len(matrix)
    max_side = 0

    dp = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side ** 2

