def valid_path_exists(M, N, grid):
    def dfs(x, y, horizontal):
        if x == M-1 and y == N-1:
            return True
        if horizontal:
            if y+1 < N and grid[x][y+1] == '-' and dfs(x, y+1, not horizontal):
                return True
        else:
            if x+1 < M and grid[x+1][y] == '-' and dfs(x+1, y, not horizontal):
                return True
        return False

    if grid[0][0] == '-' and (dfs(0, 1, False) or dfs(1, 0, True)):
        return "YES"
    return "NO"

