def maxTrees(m, n, farm):
    def bpm(u, seen, matchR):
        for v in range(n):
            if farm[u][v] and not seen[v]:
                seen[v] = True

                if matchR[v] == -1 or bpm(matchR[v], seen, matchR):
                    matchR[v] = u
                    return True
        return False

    matchR = [-1] * n
    result = 0
    for i in range(m):
        seen = [False] * n
        if bpm(i, seen, matchR):
            result += 1

    return result

