def find_minimum_paving_distance(n, m, roads):
    # Define a function for finding the minimum spanning tree using Kruskal's algorithm

    parent = list(range(n))
    rank = [0] * n

    def find(u):
        if parent[u] != u:
            parent[u] = find(parent[u])
        return parent[u]

    def union(u, v):
        root_u = find(u)
        root_v = find(v)
        if root_u != root_v:
            if rank[root_u] > rank[root_v]:
                parent[root_v] = root_u
            elif rank[root_u] < rank[root_v]:
                parent[root_u] = root_v
            else:
                parent[root_v] = root_u
                rank[root_u] += 1

    if m == 0:
        return "IMPOSSIBLE" if n > 1 else 0

    roads.sort(key=lambda x: x[2])
    min_distance = 0
    edges_used = 0

    for u, v, w in roads:
        if find(u - 1) != find(v - 1):
            union(u - 1, v - 1)
            min_distance += w
            edges_used += 1
        if edges_used == n - 1:
            break

    if edges_used != n - 1:
        return "IMPOSSIBLE"

    return min_distance

