def compress_string(S):
    """
    Compresses the string S by repeatedly encoding the longest contiguous substrings of identical characters.
    """
    def find_longest_run(s):
        max_char = ''
        max_count = 0
        current_char = ''
        current_count = 0
        for char in s:
            if char == current_char:
                current_count += 1
            else:
                if current_count > max_count:
                    max_char = current_char
                    max_count = current_count
                current_char = char
                current_count = 1
        if current_count > max_count:
            max_char = current_char
            max_count = current_count
        return max_char, max_count

    while True:
        char, count = find_longest_run(S)
        if count <= 1:
            break
        S = S.replace(char*count, f"{char}[{count}]", 1)

    return S

