def find_treasure(map):
    """
    Returns the coordinates of the treasure 'T' in the map grid.

    Parameters:
    map (list of list of str): The map represented as a grid of characters.

    Returns:
    (int, int): Tuple of (row, column) of the treasure cell or (-1, -1) if not found.
    """
    for row in range(len(map)):
        for col in range(len(map[row])):
            if map[row][col] == 'T':
                return (row, col)

    return (-1, -1)

