def min_total_distance(n, desired_order, initial_belt):
    item_position = {item: idx for idx, item in enumerate(initial_belt)}
    total_distance = 0

    for i in range(n):
        item = desired_order[i]
        current_position = item_position[item]
        distance = abs(current_position - i)
        total_distance += distance

        # Update the positions of the remaining items
        for j in range(n):
            if initial_belt[j] == item:
                initial_belt[j], initial_belt[i] = initial_belt[i], initial_belt[j]
                break

    return total_distance

