def can_sum_to_k(n, A, B, k):
    current_sum = sum(A)
    if current_sum == k:
        return "Yes"

    deficit = k - current_sum
    if deficit < 0:
        return "No"

    B.sort(reverse=True)

    for value in B:
        if deficit <= 0:
            break
        deficit -= value

    return "Yes" if deficit <= 0 else "No"

