def countSubsets(weights, values, N, W):
    # Create a DP array to store the number of subsets with exact weight equal to the index
    dp = [0] * (W + 1)
    dp[0] = 1  # There is one subset (the empty subset) with weight 0

    for weight in weights:
        # Traverse the dp array from right to left to avoid using the same element multiple times
        for w in range(W, weight - 1, -1):
            dp[w] += dp[w - weight]

    return dp[W]

