def splitArray(nums, k):
    """
    This function returns the minimized maximum sum of `k` non-empty consecutive subarrays
    from the input list `nums`.
    """
    def valid_partition(max_sum):
        count, curr_sum = 1, 0
        for num in nums:
            if curr_sum + num > max_sum:
                count += 1
                curr_sum = num
                if count > k:
                    return False
            else:
                curr_sum += num
        return True

    left, right = max(nums), sum(nums)

    while left < right:
        mid = (left + right) // 2
        if valid_partition(mid):
            right = mid
        else:
            left = mid + 1

    return left

