def sum_unique_transactions(n, transactions):
    """
    Sum unique transaction amounts based on their timestamps.

    :param n: Number of transactions recorded.
    :param transactions: List of transactions as strings.
    :return: Sum of unique transaction amounts rounded to two decimals.
    """
    unique_transactions = {}

    for transaction in transactions:
        timestamp, amount = transaction.rsplit(' ', 1)
        amount = float(amount)
        if timestamp not in unique_transactions:
            unique_transactions[timestamp] = amount

    return round(sum(unique_transactions.values()), 2)

def match_pattern(s, p):
    """
    Checks if the given string matches the given pattern.
    The pattern may contain at most one dot ('.'), which can match any single character.
    """
    # Check if the lengths of the string and pattern match
    if len(s) != len(p):
        return False

    for i in range(len(s)):
        # '.' in pattern can match any single character in the string
        if p[i] != '.' and s[i] != p[i]:
            return False

    return True

