def find_treasure_placement(grid, n, m):
    positions = []
    for row in range(n):
        found = False
        for col in range(m):
            if grid[row][col] != 'T':
                # Check if the column is already taken by the other treasure
                if any(pos[1] == col for pos in positions):
                    continue
                positions.append((row + 1, col + 1))
                found = True
                break
        if not found:
            return "NO"

    if len(positions) == n:
        result = ["YES"]
        for pos in positions:
            result.append(f"{pos[0]} {pos[1]}")
        return "\n".join(result)
    else:
        return "NO"

import heapq

def dijkstra(n, m, s, edges):
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u].append((w, v))
        graph[v].append((w, u))

    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[s] = 0

    pq = [(0, s)]
    visited = set()

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_node in visited:
            continue
        visited.add(current_node)

        for weight, neighbor in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return [distances[i] if distances[i] != float('inf') else -1 for i in range(1, n + 1)]

def shortest_travel_times(T, test_cases):
    results = []
    for i in range(T):
        N, M, S = test_cases[i][0]
        edges = test_cases[i][1]
        result = dijkstra(N, M, S, edges)
        results.append(result)
    return results

def maxPoints(points):
    """
    Finds the maximum number of points that lie on the same straight line.

    :param points: List of tuples representing points in a 2D plane.
    :return: Integer, maximum number of points that can lie on the same straight line.
    """
    if len(points) <= 1:
        return len(points)

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    from collections import defaultdict
    max_points = 1

    for i in range(len(points)):
        slopes = defaultdict(int)
        duplicate = 1

        for j in range(i + 1, len(points)):
            x1, y1 = points[i]
            x2, y2 = points[j]

            if x1 == x2 and y1 == y2:
                duplicate += 1
                continue

            dx = x2 - x1
            dy = y2 - y1
            g = gcd(dx, dy)

            dx //= g
            dy //= g

            slopes[(dx, dy)] += 1

        current_max = duplicate
        for count in slopes.values():
            if count + duplicate > current_max:
                current_max = count + duplicate

        if current_max > max_points:
            max_points = current_max

    return max_points

