def four_sum_count(nums, target):
    """
    Returns the number of unique quadruplets that sum to the target value.
    """
    nums.sort()
    quadruplets = set()
    n = len(nums)

    for i in range(n):
        for j in range(i + 1, n):
            left, right = j + 1, n - 1
            while left < right:
                total = nums[i] + nums[j] + nums[left] + nums[right]
                if total == target:
                    quadruplets.add((nums[i], nums[j], nums[left], nums[right]))
                    left += 1
                    right -= 1
                elif total < target:
                    left += 1
                else:
                    right -= 1

    return len(quadruplets)

