def can_win_by_removing_one(char_string):
    """
    Determines if by removing one character from the string we can make it a palindrome.
    """
    n = len(char_string)

    def is_palindrome(s):
        return s == s[::-1]

    for i in range(n):
        if is_palindrome(char_string[:i] + char_string[i+1:]):
            return "Win"
    return "Draw"

def process_cases(T, cases):
    results = []
    for i in range(T):
        results.append(can_win_by_removing_one(cases[i]))
    return results

