def rob(nums):
    """
    Returns the maximum amount of money that can be robbed without alerting the police.
    Each house has a connected security system, so two adjacent houses cannot be robbed.
    """
    if not nums:
        return 0
    if len(nums) == 1:
        return nums[0]
    if len(nums) == 2:
        return max(nums)

    def rob_line(houses):
        prev1, prev2 = 0, 0
        for house in houses:
            temp = prev1
            prev1 = max(prev2 + house, prev1)
            prev2 = temp
        return prev1

    # Either we rob houses from 0 to n-2 or from 1 to n-1
    return max(rob_line(nums[:-1]), rob_line(nums[1:]))

