def max_profit(prices):
    """
    Returns the maximum profit that can be achieved from a single transaction.
    If no profit is possible, return 0.
    """
    if not prices:
        return 0

    min_price = prices[0]
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        current_profit = price - min_price
        if current_profit > max_profit:
            max_profit = current_profit

    return max_profit

