import math

def flowerbeds_overlap(flowerbeds):
    n = len(flowerbeds)
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1, r1 = flowerbeds[i]
            x2, y2, r2 = flowerbeds[j]
            distance = math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)
            if distance < (r1 + r2):
                return "YES"
    return "NO"

