def max_rectangle_area(grid):
    n = len(grid)
    m = len(grid[0])
    max_area = 0

    # Pre-process each row to get the maximum width of same height cells
    def process_row(row):
        widths = []
        current_height = row[0]
        current_width = 1
        for i in range(1, len(row)):
            if row[i] == current_height:
                current_width += 1
            else:
                widths.append((current_height, current_width))
                current_height = row[i]
                current_width = 1
        widths.append((current_height, current_width))
        return widths

    for row in range(n):
        row_widths = process_row(grid[row])
        for height, width in row_widths:
            # Check vertically
            for start_col in range(m - width + 1):
                col_idx = start_col
                min_width = width
                for r in range(row, n):
                    if all(grid[r][c] == height for c in range(col_idx, col_idx + min_width)):
                        max_area = max(max_area, (r - row + 1) * min_width)
                    else:
                        break

    return max_area

