def can_form_groups(n, k, energy_levels):
    """
    Determines if it is possible to form groups of k robots each with distinct energy levels.
    """
    if len(set(energy_levels)) < n:
        return "Impossible"

    energy_count = {}
    for energy in energy_levels:
        if energy in energy_count:
            energy_count[energy] += 1
        else:
            energy_count[energy] = 1

    for count in energy_count.values():
        if count > k:
            return "Impossible"

    return "Possible"

