def can_travel(N, M, Q, K, roads, queries):
    from collections import defaultdict, deque

    # Create adjacency list for the graph representation of cities and roads
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    # Helper function to perform BFS and check if two cities are connected
    def bfs(start, target):
        visited = set()
        queue = deque([start])
        while queue:
            current = queue.popleft()
            if current == target:
                return True
            visited.add(current)
            for neighbor in graph[current]:
                if neighbor not in visited:
                    queue.append(neighbor)
        return False

    # For each query (A, B), determine if they are in the same connected component
    results = []
    for A, B in queries:
        if bfs(A, B):
            results.append("Yes")
        else:
            results.append("No")

    return results

def longest_equal_zeros_ones(T, test_cases):
    results = []
    for N, S in test_cases:
        max_length = 0
        balance = 0
        balance_index_map = {0: -1}

        for i, char in enumerate(S):
            balance += 1 if char == '1' else -1

            if balance in balance_index_map:
                max_length = max(max_length, i - balance_index_map[balance])
            else:
                balance_index_map[balance] = i

        results.append(max_length)
    return results

def min_removals_to_palindrome(necklace):
    """
    Returns the minimum number of character removals needed to make the given necklace a palindrome.
    """
    n = len(necklace)

    # Helper function to find the length of the longest palindromic subsequence
    def longest_palindromic_subsequence(s):
        dp = [[0] * n for _ in range(n)]

        for i in range(n):
            dp[i][i] = 1

        for length in range(2, n+1):
            for start in range(n-length+1):
                end = start + length - 1
                if s[start] == s[end]:
                    dp[start][end] = 2 + dp[start+1][end-1]
                else:
                    dp[start][end] = max(dp[start+1][end], dp[start][end-1])

        return dp[0][n-1]

    lps_length = longest_palindromic_subsequence(necklace)
    return n - lps_length

