def longest_palindromic_sequence(grid):
    def is_palindrome(s):
        return s == s[::-1]

    def find_longest_palindrome(seq):
        n = len(seq)
        max_palindrome = ""
        for start in range(n):
            for end in range(start + 1, n + 1):
                substring = seq[start:end]
                if is_palindrome(substring) and len(substring) > len(max_palindrome):
                    max_palindrome = substring
        return max_palindrome

    longest = ""
    # Check each row (horizontal)
    for row in grid:
        row_str = ''.join(row)
        candidate = find_longest_palindrome(row_str)
        if len(candidate) > len(longest) or (len(candidate) == len(longest) and candidate < longest):
            longest = candidate

    # Check each column (vertical)
    if grid:
        num_cols = len(grid[0])
        num_rows = len(grid)
        for col in range(num_cols):
            col_str = ''.join(grid[row][col] for row in range(num_rows))
            candidate = find_longest_palindrome(col_str)
            if len(candidate) > len(longest) or (len(candidate) == len(longest) and candidate < longest):
                longest = candidate

    return longest

