def daily_temperatures(n, arr):
    result = [0] * n
    stack = []
    for i in range(n):
        while stack and arr[stack[-1]] < arr[i]:
            prev_day = stack.pop()
            result[prev_day] = i - prev_day
        stack.append(i)
    return result

