def is_prime(num):
    """
    Helper function to check if a number is a prime number.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def twinPrimes(n):
    """
    Returns all twin primes up to n (inclusive).
    """
    if not isinstance(n, int) or n <= 1:
        return []

    primes = [num for num in range(2, n + 1) if is_prime(num)]
    twin_prime_pairs = [(primes[i], primes[i + 1])
                        for i in range(len(primes) - 1)
                        if primes[i + 1] - primes[i] == 2]

    return twin_prime_pairs

