def min_operations_to_make_blocks_uniform(n, blocks):
    """
    Returns the minimum number of operations required to make all blocks the same color.
    """
    # Count the number of contiguous segments of 'R' and 'B'
    if n == 0:
        return 0

    red_segments = 0
    blue_segments = 0

    current_color = blocks[0]
    if current_color == 'R':
        red_segments += 1
    else:
        blue_segments += 1

    for i in range(1, n):
        if blocks[i] != current_color:
            current_color = blocks[i]
            if current_color == 'R':
                red_segments += 1
            else:
                blue_segments += 1

    # The number of operations needed is the minimum of red_segments and blue_segments
    return min(red_segments, blue_segments)

