def max_gold(t, test_cases):
    def getMaxGold(chests):
        n = len(chests)

        if n == 0:
            return 0
        elif n == 1:
            return chests[0]

        # dp[i] will be the max gold that can be collected up to chest i
        dp = [0] * n
        dp[0] = chests[0]
        dp[1] = max(chests[0], chests[1])

        for i in range(2, n):
            dp[i] = max(dp[i-1], dp[i-2] + chests[i])

        return dp[-1]

    results = []

