def sort_segments(arr):
    """
    Sorts each segment of the array separated by zeroes in non-decreasing order.
    The zeroes remain in their original positions.
    """
    n = len(arr)
    result = []
    segment = []

    for i in range(n):
        if arr[i] == 0:
            if segment:
                result.extend(sorted(segment))
                segment = []
            result.append(0)
        else:
            segment.append(arr[i])

    if segment:
        result.extend(sorted(segment))

    return result

