from collections import defaultdict, deque

def process_queries(n, m, edges, q, queries):
    # Create the adjacency list for the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def bfs_shortest_path(start, end):
        if start == end:
            return 0
        visited = set()
        queue = deque([(start, 0)])
        while queue:
            current, distance = queue.popleft()
            if current == end:
                return distance
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, distance + 1))
        return -1

    def is_directly_connected(x, y):
        return "yes" if y in graph[x] else "no"

    results = []
    for t, x, y in queries:
        if t == 1:
            results.append(bfs_shortest_path(x, y))
        elif t == 2:
            results.append(is_directly_connected(x, y))

    return results

from collections import deque

def min_moves_to_reach_end(grid, R, C, start, end):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    r_start, c_start = start
    r_end, c_end = end

    if grid[r_start][c_start] == '#' or grid[r_end][c_end] == '#':
        return -1

    queue = deque([(r_start, c_start, 0)])
    visited = set((r_start, c_start))

    while queue:
        x, y, dist = queue.popleft()

        if (x, y) == (r_end, c_end):
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < R and 0 <= ny < C and (nx, ny) not in visited and grid[nx][ny] == '.':
                queue.append((nx, ny, dist + 1))
                visited.add((nx, ny))

    return -1

def main(input_lines):
    R, C = map(int, input_lines[0].strip().split())
    grid = [list(input_lines[i + 1].strip()) for i in range(R)]
    r_start, c_start = map(int, input_lines[R + 1].strip().split())
    r_end, c_end = map(int, input_lines[R + 2].strip().split())

    return min_moves_to_reach_end(grid, R, C, (r_start, c_start), (r_end, c_end))

def longest_palindromic_subsequence(s):
    """
    Returns the length of the longest palindromic subsequence in the given string.
    """
    n = len(s)
    dp = [[0 for _ in range(n)] for _ in range(n)]

    # Base case: a single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the table
    for cl in range(2, n+1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])

    return dp[0][n-1]

def find_longest_palindromic_subsequences(test_cases):
    results = []
    for s in test_cases:
        results.append(longest_palindromic_subsequence(s))
    return results

