def max_consecutive_empty_benches(grid):
    def max_consecutive_zeros(arr):
        max_zeros = 0
        count = 0
        for num in arr:
            if num == 0:
                count += 1
                max_zeros = max(max_zeros, count)
            else:
                count = 0
        return max_zeros

    max_zeros_in_rows = max(max_consecutive_zeros(row) for row in grid)
    max_zeros_in_columns = max(max_consecutive_zeros(col) for col in zip(*grid))

    return max(max_zeros_in_rows, max_zeros_in_columns)

