def has_unique_characters(s):
    """
    Determines if a string has all unique characters.

    Args:
    s (str): The input string.

    Returns:
    bool: True if all characters are unique, False otherwise.
    """
    for i in range(len(s)):
        for j in range(i + 1, len(s)):
            if s[i] == s[j]:
                return False
    return True

