def text_formatting(commands, text):
    """
    Processes text according to formatting commands.
    """
    full_text = ' '.join(text).strip()

    for command in commands:
        com = command.split()
        if com[0] == 'UPPER':
            full_text = full_text.upper()
        elif com[0] == 'LOWER':
            full_text = full_text.lower()
        elif com[0] == 'CAPITALIZE':
            full_text = full_text.title()
        elif com[0] == 'LEFT':
            width = int(com[1])
            full_text = full_text.ljust(width)
        elif com[0] == 'RIGHT':
            width = int(com[1])
            full_text = full_text.rjust(width)
        elif com[0] == 'CENTER':
            width = int(com[1])
            full_text = full_text.center(width)

    return full_text

def findTriplet(nums):
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            total = nums[i] + nums[left] + nums[right]
            if total == 0:
                return "yes"
            elif total < 0:
                left += 1
            else:
                right -= 1

    return "no"

