def max_consecutive_increasing_days(T, test_cases):
    results = []
    for case in test_cases:
        N, growth_measurements = case
        max_length = 0
        current_length = 1

        for i in range(1, N):
            if growth_measurements[i] > growth_measurements[i-1]:
                current_length += 1
            else:
                if current_length > max_length:
                    max_length = current_length
                current_length = 1

        # To check last sequence length if it was the longest
        if current_length > max_length:
            max_length = current_length

        results.append(max_length)
    return results

