def remove_min_chars(s):
    """
    Remove the minimum number of characters so that no three consecutive characters are the same.
    """
    if len(s) < 3:
        return s

    result = []

    for char in s:
        # Check if the last two characters in the result and the current character are the same
        if len(result) >= 2 and result[-1] == result[-2] == char:
            continue
        result.append(char)

    return ''.join(result)

