def primeSum(N):
    """
    Returns the sum of all prime numbers less than or equal to N.
    """
    if N < 2:
        return 0

    sieve = [True] * (N + 1)
    sieve[0] = sieve[1] = False

    for start in range(2, int(N**0.5) + 1):
        if sieve[start]:
            for multiple in range(start * start, N + 1, start):
                sieve[multiple] = False

    return sum(i for i, prime in enumerate(sieve) if prime)

def minimum_difference(n, weights):
    """
    Finds the minimum possible difference between the total weights of two groups.

    Args:
    - n (int): Number of crates.
    - weights (List[int]): List of weights for each crate.

    Returns:
    int: The minimum possible difference.
    """
    total_weight = sum(weights)
    dp = [False] * (total_weight + 1)
    dp[0] = True

    for weight in weights:
        for j in range(total_weight, weight - 1, -1):
            if dp[j - weight]:
                dp[j] = True

    for j in range(total_weight // 2, -1, -1):
        if dp[j]:
            return total_weight - 2 * j

    return total_weight

