def find_min_additional_roads(N, M, roads, I, intersections):
    from collections import defaultdict
    import itertools

    # Adjacency list for the roads
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    # To keep track of visited nodes
    visited = set()

    def dfs(node):
        stack = [node]
        component = set()
        while stack:
            cur = stack.pop()
            if cur not in visited:
                visited.add(cur)
                component.add(cur)
                for neighbor in graph[cur]:
                    if neighbor not in visited:
                        stack.append(neighbor)
        return component

    # Find all connected components
    components = []
    for place in range(1, N + 1):
        if place not in visited:
            component = dfs(place)
            components.append(component)

    # Number of additional roads needed is the number of disconnected components - 1
    return max(0, len(components) - 1)

def process_commands(commands):
    todo_list = []
    results = []

    for cmd in commands:
        if cmd.startswith("ADD "):
            task = cmd[4:]
            todo_list.append(task)
        elif cmd.startswith("REMOVE "):
            index = int(cmd[7:]) - 1
            if 0 <= index < len(todo_list):
                todo_list.pop(index)
        elif cmd == "LIST":
            if todo_list:
                results.append("\n".join(todo_list))
            else:
                results.append("No tasks")

    return results

def zigzag_sort(arr):
    """
    Modifies the array in-place to become a zigzag array.
    """
    n = len(arr)
    for i in range(1, n):
        if i % 2 == 1:
            if arr[i] <= arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
        else:
            if arr[i] >= arr[i - 1]:
                arr[i], arr[i - 1] = arr[i - 1], arr[i]
    return arr

def process_multiple_cases(test_cases):
    results = []
    for case in test_cases:
        results.append(zigzag_sort(case))
    return results

