import math

def arrange_photos(n):
    """
    Arrange 'n' photos into a grid format with r rows and c columns such that the grid
    is filled most evenly. If multiple configurations are possible, choose the one with
    the smallest row count first.

    :param n: Integer, number of photos.
    :return: Tuple (r, c) representing rows and columns.
    """
    if n == 0:
        return (0, 0)

    best_r, best_c = None, None
    min_difference = math.inf

    # Iterate through possible row counts
    for r in range(1, math.isqrt(n) + 1):
        if n % r == 0:
            c = n // r
            difference = abs(r - c)
            if difference < min_difference or (difference == min_difference and r < best_r):
                best_r, best_c = r, c
                min_difference = difference

    return (best_r, best_c)

