def longest_balanced_substring(s):
    """
    Returns the length of the longest balanced substring containing
    an equal number of 'x' and 'y'.
    """
    max_length = 0
    balance_counter = {0: -1}
    balance = 0

    for i, char in enumerate(s):
        if char == 'x':
            balance -= 1
        elif char == 'y':
            balance += 1

        if balance in balance_counter:
            max_length = max(max_length, i - balance_counter[balance])
        else:
            balance_counter[balance] = i

    return max_length

