def second_smallest(numbers):
    """
    Finds the second smallest number in the list.
    If there is no such number, returns None.
    """
    if len(numbers) < 2:
        return None

    smallest = second = float('inf')
    for num in numbers:
        if num < smallest:
            smallest, second = num, smallest
        elif smallest < num < second:
            second = num

    return second if second < float('inf') else None

