from typing import List
from collections import deque

def max_distance_to_park(grid: List[List[str]]) -> int:
    if not grid or not grid[0]:
        return -1

    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # up, down, left, right
    parks = deque()

    # Step 1: Collect all parks
    for r in range(N):
        for c in range(N):
            if grid[r][c] == 'P':
                parks.append((r, c))

    # If there are no parks or no buildings, return -1
    if not parks or all(grid[r][c] == 'P' for r in range(N) for c in range(N)):
        return -1

    steps = -1
    seen = set(parks)

    # Step 2: Perform multi-source BFS from all parks
    while parks:
        steps += 1
        for _ in range(len(parks)):
            r, c = parks.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < N and 0 <= nc < N and (nr, nc) not in seen and grid[nr][nc] == 'B':
                    parks.append((nr, nc))
                    seen.add((nr, nc))

    return steps

