import heapq

def dijkstra(N, edges, S):
    graph = {i: [] for i in range(1, N+1)}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    distances = {i: float('inf') for i in range(1, N+1)}
    distances[S] = 0
    priority_queue = [(0, S)]

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return [distances[i] if distances[i] != float('inf') else -1 for i in range(1, N+1)]

def find_coconut_row(numCoconuts, numRows, position):
    cycle_len = 2 * numRows - 2 if numRows > 1 else 1
    pos_in_cycle = position % cycle_len

    if pos_in_cycle < numRows:
        return pos_in_cycle
    else:
        return cycle_len - pos_in_cycle

def process_test_cases(t, test_cases):
    results = []
    for i in range(t):
        numCoconuts, numRows, position = test_cases[i]
        results.append(find_coconut_row(numCoconuts, numRows, position))
    return results

