def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def isPrimePower(n):
    if n <= 1:
        return False
    for p in range(2, int(n**0.5) + 1):
        if is_prime(p):
            power = p
            while power <= n:
                power *= p
                if power == n:
                    return True
    return is_prime(n)

def largest_connected_component(n, edges):
    from collections import defaultdict

    def dfs(node, visited, graph):
        stack = [node]
        component_size = 0
        while stack:
            current = stack.pop()
            if not visited[current]:
                visited[current] = True
                component_size += 1
                for neighbor in graph[current]:
                    if not visited[neighbor]:
                        stack.append(neighbor)
        return component_size

    # Building the graph as an adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * (n + 1)
    largest_size = 0

    for i in range(1, n + 1):
        if not visited[i]:
            component_size = dfs(i, visited, graph)
            largest_size = max(largest_size, component_size)

    return largest_size

