def find_two_sum_indices(nums, target):
    """
    Returns the indices of the two numbers in the list that add up to the target value.
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (num_to_index[complement], i)
        num_to_index[num] = i

    return None  # Return None if no pair is found (only for safety, as the problem guarantees a solution)

def stack_operations(n, operations):
    stack = []
    result = []

    for operation in operations:
        parts = operation.split()
        if parts[0] == "PUSH":
            stack.append(int(parts[1]))
        elif parts[0] == "POP":
            if stack:
                stack.pop()
        elif parts[0] == "PRINT":
            if stack:
                result.append(stack[-1])
        elif parts[0] == "INCREMENT":
            k, v = int(parts[1]), int(parts[2])
            for i in range(min(k, len(stack))):
                stack[i] += v

    return result

