def find(parent, i):
    if parent[i] == i:
        return i
    else:
        parent[i] = find(parent, parent[i])  # path compression
        return parent[i]

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def min_max_weight_kruskal(n, edges):
    edges.sort(key=lambda x: x[2])
    parent = [i for i in range(n)]
    rank = [0] * n

    max_edge_in_mst = 0

    for edge in edges:
        u, v, w = edge
        u -= 1
        v -= 1
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            max_edge_in_mst = max(max_edge_in_mst, w)
            n -= 1
            if n == 1:  # if only one component is left
                break

    return max_edge_in_mst

def canSegmentString(s, words):
    word_set = set(words)
    dp = [False] * (len(s) + 1)
    dp[0] = True

    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break

    return dp[len(s)]

