def can_be_increasing(arr):
    """
    Determines if the given array can be made strictly increasing by removing at most one element.
    """
    def is_strictly_increasing(seq):
        return all(x < y for x, y in zip(seq, seq[1:]))

    n = len(arr)
    for i in range(n):
        if is_strictly_increasing(arr[:i] + arr[i+1:]):
            return "YES"
    return "NO"

