def sum_at_kth_level(N, parent_nodes, k):
    from collections import deque, defaultdict

    if k < 1 or k > N:
        return 0

    # Build the tree as an adjacency list
    tree = defaultdict(list)
    root = None
    for i in range(N):
        if parent_nodes[i] == -1:
            root = i + 1
        else:
            tree[parent_nodes[i]].append(i + 1)

    if root is None:
        return 0

    # Perform BFS to find the sum of values at the kth level
    level = 1
    queue = deque([root])
    while queue:
        if level == k:
            return sum(queue)
        level_length = len(queue)
        for i in range(level_length):
            node = queue.popleft()
            for child in tree[node]:
                queue.append(child)
        level += 1

    return 0

def process_commands(k, commands):
    lst = []
    for command in commands:
        if command.startswith("APPEND"):
