def max_consecutive_high_sales_days(S):
    """
    Return the maximum number of consecutive 'H' (High sales days) in the string S.
    """
    max_count = 0
    current_count = 0
    for char in S:
        if char == 'H':
            current_count += 1
            if current_count > max_count:
                max_count = current_count
        else:
            current_count = 0
    return max_count

