def can_sort_by_reversing_subarray(arr):
    n = len(arr)
    sorted_arr = sorted(arr)

    # Find the first and last position where arr and sorted_arr differ
    start = end = -1
    for i in range(n):
        if arr[i] != sorted_arr[i]:
            if start == -1:
                start = i
            end = i

    # If start and end are not updated, the array is already sorted
    if start == -1:
        return "YES 1 1"

    # Reverse the subarray from start to end and check if it sorts the array
    subsequence_reversed = arr[:start] + arr[start:end+1][::-1] + arr[end+1:]

    if subsequence_reversed == sorted_arr:
        return f"YES {start + 1} {end + 1}"
    else:
        return "NO"

def process_test_cases(test_cases):
    results = []
    for n, arr in test_cases:
        results.append(can_sort_by_reversing_subarray(arr))
    return results

