def longestSubstringWithKDistinct(s, queries):
    def length_of_longest_substring_with_k_distinct(k):
        n = len(s)
        if k == 0:
            return 0
        char_count = {}
        left = 0
        max_length = 0

        for right in range(n):
            if s[right] in char_count:
                char_count[s[right]] += 1
            else:
                char_count[s[right]] = 1

            while len(char_count) > k:
                char_count[s[left]] -= 1
                if char_count[s[left]] == 0:
                    del char_count[s[left]]
                left += 1

            max_length = max(max_length, right - left + 1)

        return max_length

    results = []
    for k in queries:
        results.append(length_of_longest_substring_with_k_distinct(k))
    return results

import math

def is_prime(num):
    """
    Checks if a number is prime.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False

    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6

    return True

def smallest_prime_greater_than(n):
    """
    Finds the smallest prime number greater than n.
    """
    num = n + 1
    while not is_prime(num):
        num += 1
    return num

def solve(test_cases):
    results = []
    for n in test_cases:
        results.append(smallest_prime_greater_than(n))
    return results

def find_roads(n, k):
    roads = []
    for a in range(1, n):
        for b in range(a+1, n+1):
            if (a * b) % k == 0:
                roads.append((a, b))

    if len(roads) == 0:
        return -1
    return roads

