def robot_path(commands: str) -> bool:
    x, y = 0, 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
    return x == 0 and y == 0

def length_of_longest_substring_n_distinct(n, s):
    """
    Returns the length of the longest substring with at most n distinct characters.
    """
    if n == 0 or not s:
        return 0

    left = 0
    max_length = 0
    char_count = {}

    for right in range(len(s)):
        if s[right] in char_count:
            char_count[s[right]] += 1
        else:
            char_count[s[right]] = 1

        while len(char_count) > n:
            char_count[s[left]] -= 1
            if char_count[s[left]] == 0:
                del char_count[s[left]]
            left += 1

        max_length = max(max_length, right - left + 1)

    return max_length

