from collections import deque

def shortest_path(R, C, grid):
    if grid[0][0] == 1 or grid[R-1][C-1] == 1:
        return -1

    directions = [(1, 0), (0, 1)]  # Down, Right
    queue = deque([(0, 0, 0)])  # (row, col, steps)
    visited = set((0, 0))

    while queue:
        r, c, steps = queue.popleft()

        if r == R-1 and c == C-1:
            return steps

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                queue.append((nr, nc, steps + 1))

    return -1

def process_image_operations(m, pixels, operations):
    def compress(pixels, p, q):
        avg = sum(pixels[p-1:q]) // (q - p + 1)
        for i in range(p-1, q):
            pixels[i] = avg

    def enhance(pixels, p, q, k):
        for i in range(p-1, q):
            pixels[i] //= k

    results = []
    for op in operations:
        if op[0] == 1:
            _, p, q = op
            compress(pixels, p, q)
        elif op[0] == 2:
            _, p, q, k = op
            enhance(pixels, p, q, k)
        elif op[0] == 3:
            results.append(max(pixels))

    return results

def maximalRectangle(matrix):
    if not matrix:
        return 0

    m, n = len(matrix), len(matrix[0])
    heights = [0] * n
    max_area = 0

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == '0':
                heights[j] += 1
            else:
                heights[j] = 0

        max_area = max(max_area, largestRectangleArea(heights))

    return max_area

def largestRectangleArea(heights):
    stack = []
    max_area = 0
    heights.append(0)

    for i in range(len(heights)):
        while stack and heights[i] < heights[stack[-1]]:
            h = heights[stack.pop()]
            w = i if not stack else i - stack[-1] - 1
            max_area = max(max_area, h * w)
        stack.append(i)

    heights.pop()
    return max_area

from collections import Counter

def most_frequent_item(items):
    if not items:
        return ""

    freq = Counter(items)
    most_common = freq.most_common()

    max_count = most_common[0][1]
    candidates = [item for item, count in most_common if count == max_count]

    return min(candidates)

