def knapsack(n, W, items):
    dp = [0] * (W + 1)
    for i in range(n):
        weight, value = items[i]
        # Traverse from W to weight.
        for w in range(W, weight - 1, -1):
            dp[w] = max(dp[w], dp[w - weight] + value)
    return max(dp)

# Example usage:
# n = 4
# W = 7
# items = [(1, 1), (3, 4), (4, 5), (5, 7)]
# print(knapsack(n, W, items))  # Output: 9

