def is_subset_sum(arr, target_sum):
    """
    Determines if there is a subset of the given array with a sum equal to the given target_sum.
    """
    n = len(arr)
    dp = [[False] * (target_sum + 1) for _ in range(n + 1)]

    # If sum is 0, then answer is True since we can always have an empty subset
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the dp table in bottom up manner
    for i in range(1, n + 1):
        for j in range(1, target_sum + 1):
            if j < arr[i - 1]:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]

    return dp[n][target_sum]

import re

def validate_passwords(test_cases):
    results = []
    special_characters = re.compile(r'[!@#$%^&*()]')

    for password in test_cases:
        if len(password) < 8:
            results.append("INVALID")
        elif ' ' in password:
            results.append("INVALID")
        elif not any(char.isupper() for char in password):
            results.append("INVALID")
        elif not any(char.isdigit() for char in password):
            results.append("INVALID")
        elif not special_characters.search(password):
            results.append("INVALID")
        else:
            results.append("VALID")

    return results

