def calculate_water_trapped(n, heights, leaks):
    if n <= 2:
        return 0

    left_max = [0] * n
    right_max = [0] * n

    left_max[0] = heights[0]
    for i in range(1, n):
        if leaks[i] == 1:
            left_max[i] = 0
        else:
            left_max[i] = max(left_max[i - 1], heights[i])

    right_max[n - 1] = heights[n - 1]
    for i in range(n - 2, -1, -1):
        if leaks[i] == 1:
            right_max[i] = 0
        else:
            right_max[i] = max(right_max[i + 1], heights[i])

    water_trapped = 0
    for i in range(n):
        if leaks[i] == 1:
            continue
        height = min(left_max[i], right_max[i])
        if height > heights[i]:
            water_trapped += height - heights[i]

    return water_trapped

