def find_hamiltonian_cycle(n, edges):
    from itertools import permutations

    # Create an adjacency matrix
    adj_matrix = [[0] * n for _ in range(n)]
    for u, v in edges:
        adj_matrix[u-1][v-1] = 1
        adj_matrix[v-1][u-1] = 1

    # Check all possible permutations (Hamiltonian paths)
    for perm in permutations(range(n)):
        valid_path = True
        for i in range(len(perm) - 1):
            if adj_matrix[perm[i]][perm[i + 1]] == 0:
                valid_path = False
                break
        if valid_path and adj_matrix[perm[-1]][perm[0]] == 1:
            return "YES"

    return "NO"

def process_test_cases(test_cases):
    results = []
    for n, m, edges in test_cases:
        result = find_hamiltonian_cycle(n, edges)
        results.append(result)
    return results

def is_prime(n):
    """
    Returns True if n is a prime number, else False
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def is_prime_list(integers):
    """
    Returns a list of booleans indicating the primality of each integer in the input list.
    """
    return [is_prime(num) for num in integers]

