def special_summation_sequence(n):
    """
    Returns the Nth number in the Special Summation Sequence.
    """
    if n == 1:
        return 1
    elif n == 2:
        return 2

    sequence = [1, 2]
    for i in range(2, n):
        next_number = sum(sequence)
        sequence.append(next_number)

    return sequence[n-1]

