import heapq
from collections import Counter, deque

def rearrange_string(s, k):
    if k == 0:
        return s

    count_map = Counter(s)
    max_heap = [(-value, key) for key, value in count_map.items()]
    heapq.heapify(max_heap)

    queue = deque()
    result = []

    while max_heap:
        count, char = heapq.heappop(max_heap)
        result.append(char)
        queue.append((char, count + 1))

        if len(queue) < k:
            continue

        front_char, front_count = queue.popleft()
        if -front_count > 0:
            heapq.heappush(max_heap, (front_count, front_char))

    if len(result) == len(s):
        return ''.join(result)
    else:
        return ""

