def min_partition_difference(n, elements):
    total_sum = sum(elements)
    target = total_sum // 2

    dp = [False] * (target + 1)
    dp[0] = True

    for num in elements:
        for j in range(target, num - 1, -1):
            dp[j] = dp[j] or dp[j - num]

    for i in range(target, -1, -1):
        if dp[i]:
            closest_sum = i
            break

    return abs(total_sum - 2 * closest_sum)

