def min_height_shelf(books, shelf_width):
    n = len(books)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        total_thickness = 0
        max_height = 0
        for j in range(i, 0, -1):
            total_thickness += books[j - 1][0]
            if total_thickness > shelf_width:
                break
            max_height = max(max_height, books[j - 1][1])
            dp[i] = min(dp[i], dp[j - 1] + max_height)

    return round(dp[-1], 2)

def is_valid_circular_chain(n, clues):
    visited = [False] * n
    current = 0
    for _ in range(n):
        if visited[current]:
            return "NO"
        visited[current] = True
        current = clues[current] - 1

    return "YES" if current == 0 else "NO"

