def max_books(n, k, pages):
    remainder_map = {0: -1}  # maps remainder to its first occurrence index
    running_sum = 0
    max_length = 0

    for i in range(n):
        running_sum += pages[i]
        remainder = running_sum % k

        if remainder in remainder_map:
            max_length = max(max_length, i - remainder_map[remainder])
        else:
            remainder_map[remainder] = i

    return max_length

