    return results

def minimum_segments(T, test_cases):
    results = []
    for i in range(T):
        N, L = test_cases[i][0]
        packets = test_cases[i][1]
        segments = 0
        for packet in packets:
            if packet % L == 0:
                segments += packet // L
            else:
                segments += packet // L + 1
        results.append(segments)
    return results

