def count_anagrammatic_pairs(s):
    from collections import defaultdict

    n = len(s)
    substrings = defaultdict(int)

    # Iterate over all possible substrings
    for i in range(n):
        for j in range(i, n):
            substr = ''.join(sorted(s[i:j+1]))
            substrings[substr] += 1

    # Compute pairs
    count = 0
    for key in substrings:
        count += (substrings[key] * (substrings[key] - 1)) // 2

    return count

def sherlock_anagrammatic_pairs(test_cases):
    results = []
    for s in test_cases:
        results.append(count_anagrammatic_pairs(s))
    return results

