def check_winner(board):
    winning_combinations = [
        [(0, 0), (0, 1), (0, 2)], # horizontal rows
        [(1, 0), (1, 1), (1, 2)],
        [(2, 0), (2, 1), (2, 2)],
        [(0, 0), (1, 0), (2, 0)], # vertical columns
        [(0, 1), (1, 1), (2, 1)],
        [(0, 2), (1, 2), (2, 2)],
        [(0, 0), (1, 1), (2, 2)], # diagonals
        [(0, 2), (1, 1), (2, 0)]
    ]

    for combination in winning_combinations:
        values = [board[r][c] for r, c in combination]
        if values == ['X', 'X', 'X']:
            return 'X wins'
        elif values == ['O', 'O', 'O']:
            return 'O wins'

    if any('.' in row for row in board):
        return 'Ongoing'  # For the context of unit tests, assuming the game can still be ongoing
    else:
        return 'Draw'

