def manage_time_slots(n, q, initial_times, queries):
    times = initial_times.copy()  # Copy initial times to mutable list
    availability = [True] * n  # Mark all slots initially available

    results = []
    for query in queries:
        query_type, singer_index, param = query
        singer_index -= 1  # Convert to 0-based index for internal use

        if query_type == 1:
            times[singer_index] = param
        elif query_type == 2:
            availability[singer_index] = False
        elif query_type == 3:
            if availability[singer_index] and times[singer_index] == param:
                results.append(times[singer_index])
            else:
                results.append("unavailable")

    return results

