def word_with_max_vowels(words):
    """
    Returns the word with the maximum number of vowels. If two words have the same
    number of vowels, the word that appears first in the list is returned.
    """
    vowels = set('aeiouAEIOU')

    def count_vowels(word):
        return sum(1 for char in word if char in vowels)

    max_vowels = -1
    result_word = ""

    for word in words:
        current_vowels = count_vowels(word)
        if current_vowels > max_vowels:
            max_vowels = current_vowels
            result_word = word

    return result_word

