def exists_cycle(n, m, grid):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(nx, ny, px, py):
        return 0 <= nx < n and 0 <= ny < m and (nx != px or ny != py)

    def dfs(x, y, px, py, char):
        visited[x][y] = True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny, px, py) and grid[nx][ny] == char:
                if not visited[nx][ny]:
                    if dfs(nx, ny, x, y, char):
                        return True
                elif nx != px or ny != py:
                    return True
        return False

    visited = [[False] * m for _ in range(n)]

    for i in range(n):
        for j in range(m):
            if not visited[i][j]:
                if dfs(i, j, -1, -1, grid[i][j]):
                    return "YES"
    return "NO"

def max_coins(N, M, grid):
    """
    Returns the maximum number of coins a player can collect from (0,0) to (N-1,M-1) in a given grid.
    """
    # Initialize a dp array with zeros
    dp = [[0] * M for _ in range(N)]

    # Base case: starting position
    dp[0][0] = grid[0][0]

    # Fill the dp array
    for i in range(N):
        for j in range(M):
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + grid[i][j])

    return dp[N-1][M-1]

def max_gold(n, A, G):
    def dfs(node, visited):
        visited[node] = True
        total_gold = A[node]

        for adj in range(n):
            if G[node][adj] == 1 and not visited[adj]:
                total_gold += dfs(adj, visited)

        return total_gold

    visited = [False] * n
    return dfs(0, visited)

from typing import List

def spiral_order(matrix: List[List[int]]) -> List[int]:
    result = []

    if not matrix:
        return result

    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # Traverse from left to right
        for i in range(left, right + 1):
            result.append(matrix[top][i])
        top += 1

        # Traverse downwards
        for i in range(top, bottom + 1):
            result.append(matrix[i][right])
        right -= 1

        if top <= bottom:
            # Traverse from right to left
            for i in range(right, left - 1, -1):
                result.append(matrix[bottom][i])
            bottom -= 1

        if left <= right:
            # Traverse upwards
            for i in range(bottom, top - 1, -1):
                result.append(matrix[i][left])
            left += 1

    return result

