def distinct_paths(grid):
    """
    This function computes the number of distinct paths in a grid, avoiding obstacles.
    """
    N = len(grid)
    M = len(grid[0])

    # Initialize a table to store the number of ways to reach each cell
    dp = [[0]*M for _ in range(N)]

    if grid[0][0] == 1 or grid[N-1][M-1] == 1:
        return 0

    # Starting point
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if grid[i][j] == 1:
                dp[i][j] = 0  # No way to go through an obstacle
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[N-1][M-1]

