from collections import deque

def is_one_letter_different(word1, word2):
    """
    Check if the two words differ by exactly one letter.
    """
    count = 0
    for a, b in zip(word1, word2):
        if a != b:
            count += 1
        if count > 1:
            return False
    return count == 1

def min_transformations(initial, target, dictionary):
    if initial == target:
        return 0

    word_set = set(dictionary)
    if target not in word_set:
        return -1

    queue = deque([(initial, 0)])
    visited = set([initial])

    while queue:
        current_word, steps = queue.popleft()

        for word in list(word_set):
            if is_one_letter_different(current_word, word) and word not in visited:
                if word == target:
                    return steps + 1
                visited.add(word)
                queue.append((word, steps + 1))

    return -1

