def longest_palindromic_subsequence(s: str) -> int:
    n = len(s)
    # Create a dp array to store the length of longest palindromic subsequence
    dp = [[0] * n for _ in range(n)]

    # All single character substrings are palindromes of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table
    # cl is the length of the substring
    for cl in range(2, n+1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i+1][j-1] + 2
            else:
                dp[i][j] = max(dp[i][j-1], dp[i+1][j])

    # The length of the longest palindromic subsequence is in the right upper corner of the matrix
    return dp[0][n-1]

