def longest_sequence(N, D, points):
    def distance(p1, p2):
        return ((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)**0.5

    points.sort()
    dp = [1] * N

    for i in range(N):
        for j in range(i):
            if distance(points[i], points[j]) <= D:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def min_changes_to_beautiful(t, test_cases):
    results = []
    for i in range(t):
        n, k, A = test_cases[i]
        target = A[0]  # we can choose any number as initial target
        changes = 0

        for j in range(n - 1):
            if abs(A[j] - A[j + 1]) > k:
                changes += 1
                A[j + 1] = A[j] + k if A[j] < A[j + 1] else A[j] - k

        results.append(changes)

    return results

