from collections import Counter

def min_operations_to_equalize_array(t, test_cases):
    results = []

    for test_case in test_cases:
        n, arr = test_case
        if n == 1:
            results.append((0, arr[0]))
            continue

        counter = Counter(arr)
        most_common_element, freq = counter.most_common(1)[0]

        if len(counter) == 1:
            results.append((0, arr[0]))
            continue
        elif freq == 1:
            results.append((-1))
        else:
            results.append((n - freq, most_common_element))

    return results

