def inventory_management_system(operations):
    inventory = {}
    result = []

    for operation in operations:
        parts = operation.split()
        command, x = parts[0], int(parts[1])

        if command == "Add":
            y = int(parts[2])
            if x in inventory:
                inventory[x] += y
            else:
                inventory[x] = y
        elif command == "Remove":
            y = int(parts[2])
            if x in inventory:
                inventory[x] = max(0, inventory[x] - y)
        elif command == "Check":
            result.append(inventory.get(x, 0))

    return result

def determine_winner(auctions):
    results = []
    for bids in auctions:
        highest_bid = -1
        winning_user = -1
        for user, bid in bids:
            if bid > highest_bid:
                highest_bid = bid
                winning_user = user
        results.append((winning_user, highest_bid))
    return results

