import re

def camel_to_snake_case(code):
    """
    Convert all variable names in the provided code from camelCase to snake_case.

    Parameters:
    code (str): A single line of code containing variable declarations and assignments.

    Returns:
    str: The code with variables converted to snake_case.
    """
    def replacer(match):
        return match.group(1) + '_' + match.group(2).lower()

    # This pattern searches for camel case variable names
    pattern = re.compile(r'([a-z0-9])([A-Z])')

    while re.search(pattern, code):
        code = re.sub(pattern, replacer, code)

    return code.lower()

