def longest_contiguous_ones(binary_str):
    """
    Returns the length of the longest contiguous sequence of 1s in the binary representation.
    """
    max_length = 0
    current_length = 0

    for char in binary_str:
        if char == '1':
            current_length += 1
            if current_length > max_length:
                max_length = current_length
        else:
            current_length = 0

    return max_length

