def max_subset_sum(n, S, arr):
    # Generate all possible subsets
    from itertools import combinations
    max_sum = 0
    for i in range(n+1):
        for subset in combinations(arr, i):
            subset_sum = sum(subset)
            if subset_sum <= S and subset_sum > max_sum:
                max_sum = subset_sum
    return max_sum

