def max_length_even_odd_subarray(n, arr):
    count = {0: -1}
    max_length = 0
    balance = 0

    for i in range(n):
        if arr[i] % 2 == 0:
            balance += 1  # even
        else:
            balance -= 1  # odd

        if balance in count:
            max_length = max(max_length, i - count[balance])
        else:
            count[balance] = i

    return max_length

def process_queries(queries):
    results = []
    for n, arr in queries:
        results.append(max_length_even_odd_subarray(n, arr))
    return results

