def can_reorder_to_xor_target(t, test_cases):
    results = []
    for i in range(t):
        n, k, prices, target = test_cases[i]

        if k == 1:
            meets_target = any(price == target for price in prices)
            results.append("YES" if meets_target else "NO")
            continue

        prefix_xor = [0] * (n + 1)
        for j in range(n):
            prefix_xor[j + 1] = prefix_xor[j] ^ prices[j]

        found = False
        seen = {}
        for j in range(n - k + 1):
            xor_segment = prefix_xor[j + k] ^ prefix_xor[j]
            if xor_segment == target:
                found = True
                break
            seen[prefix_xor[j]] = j

        if not found:
            for j in range(n):
                needed = target ^ prefix_xor[j + 1]
                if needed in seen and seen[needed] < j + 1 - k:
                    found = True
                    break

        results.append("YES" if found else "NO")
    return results

def containsPythagoreanTriplet(arr, N):
    # Square all elements
    squared_arr = [x * x for x in arr]

    # Use a set to check for existence
    squared_set = set(squared_arr)

    # Check for each pair (i, j)
    for i in range(N):
        for j in range(i + 1, N):
            if squared_arr[i] + squared_arr[j] in squared_set:
                return True
    return False

