def count_distinct_crops(grid):
    """
    Counts the number of distinct crops in a farm grid.

    Parameters:
    - grid: List of lists, where each inner list represents a row of cells in the farm grid

    Returns:
    - int: The number of distinct crops (connected components of fertile cells)
    """
    if not grid or not grid[0]:
        return 0

    R, C = len(grid), len(grid[0])

    def dfs(x, y):
        if x < 0 or x >= R or y < 0 or y >= C or grid[x][y] == 0:
            return
        grid[x][y] = 0  # Mark the cell as visited by setting it to 0
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            dfs(x + dx, y + dy)

    count = 0
    for i in range(R):
        for j in range(C):
            if grid[i][j] != 0:
                count += 1
                dfs(i, j)

    return count

