import itertools

def count_valid_murals(n):
    def is_valid_mural(mural):
        length = len(mural)
        for k in range(1, length):
            for i in range(length - k):
                if mural[i:i + k] == mural[i + k:i + 2 * k]:
                    return False
        return True

    colors = list(range(1, n + 1))
    valid_count = 0

    for mural in itertools.permutations(colors):
        if is_valid_mural(mural):
            valid_count += 1

    return valid_count

