def can_visit_landmarks(n, m, roads, landmarks):
    from collections import defaultdict, deque

    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)

    for i in range(len(landmarks) - 1):
        current, next_landmark = landmarks[i], landmarks[i + 1]
        queue = deque([current])
        visited = set()

        found = False
        while queue:
            node = queue.popleft()
            if node == next_landmark:
                found = True
                break
            if node not in visited:
                visited.add(node)
                for neighbor in graph[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)
        if not found:
            return "impossible"

    return "possible"

def print_pattern(n, elements):
    """
    Returns a list of elements in the specified pattern.
    """
    result = []
    for i in range((n + 1) // 2):
        if i < len(elements):
            result.append(elements[i])
        if n - i - 1 != i and n - i - 1 < len(elements):
            result.append(elements[n - i - 1])
    return result

