def is_path_exist(n, tracks, start, end):
    from collections import defaultdict, deque

    # Create a graph as an adjacency list
    graph = defaultdict(list)
    for A, B in tracks:
        graph[A].append(B)
        graph[B].append(A)

    # Perform BFS to check for existence of path
    visited = set()
    queue = deque([start])

    while queue:
        node = queue.popleft()
        if node == end:
            return True
        if node not in visited:
            visited.add(node)
            for neighbor in graph[node]:
                if neighbor not in visited:
                    queue.append(neighbor)

    return False

