def is_valid_sudoku(grid):
    """
    Returns True if the grid is a valid Sudoku grid, otherwise False.
    A valid Sudoku grid must have each number from 1 to 9 appear only once
    in each row, column, and 3x3 sub-grid.
    """

    def is_valid_block(block):
        nums = [num for num in block if num != 0]
        return len(nums) == len(set(nums))

    # Check rows
    for row in grid:
        if not is_valid_block(row):
            return False

    # Check columns
    for col in range(9):
        if not is_valid_block([grid[row][col] for row in range(9)]):
            return False

    # Check 3x3 sub-grids
    for i in range(0, 9, 3):
        for j in range(0, 9, 3):
            block = []
            for row in range(i, i + 3):
                for col in range(j, j + 3):
                    block.append(grid[row][col])
            if not is_valid_block(block):
                return False

    return True

