def is_special_number(n):
    """
    Determines if the number n has exactly three distinct natural number divisors.
    """
    # Function to count the number of divisors of a number
    def count_divisors(num):
        divisors = set()
        for i in range(1, int(num ** 0.5) + 1):
            if num % i == 0:
                divisors.add(i)
                divisors.add(num // i)
        return len(divisors)

    # Check if the number has exactly three divisors
    return count_divisors(n) == 3

