def fibonacci_sequence(n):
    """
    Returns an array of the first n Fibonacci numbers using an iterative approach.
    """
    if n <= 0:
        return []
    if n == 1:
        return [1]

    sequence = [1, 1]
    while len(sequence) < n:
        sequence.append(sequence[-1] + sequence[-2])
    return sequence

