def contains_nearby_duplicate(nums, k):
    """
    Determines if there are two distinct indices i and j in the array such that:
    - nums[i] == nums[j]
    - abs(i - j) <= k
    """
    num_dict = {}

    for i, num in enumerate(nums):
        if num in num_dict and i - num_dict[num] <= k:
            return True
        num_dict[num] = i

    return False

def absolute_difference_sums(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        array = test_cases[i][1]
        binary_str = test_cases[i][2]

        group1_sum = 0
        group2_sum = 0

        for j in range(N):
            if binary_str[j] == '1':
                group1_sum += array[j]
            else:
                group2_sum += array[j]

        absolute_diff = abs(group1_sum - group2_sum)
        results.append(absolute_diff)

    return results

