def count_good_subarrays(nums, k):
    from collections import defaultdict

    def at_most_k_distinct(nums, k):
        count = defaultdict(int)
        left = 0
        res = 0

        for right in range(len(nums)):
            if count[nums[right]] == 0:
                k -= 1
            count[nums[right]] += 1

            while k < 0:
                count[nums[left]] -= 1
                if count[nums[left]] == 0:
                    k += 1
                left += 1

            res += right - left + 1

        return res

    return at_most_k_distinct(nums, k) - at_most_k_distinct(nums, k - 1)

def bubble_sort(n, arr):
    """
    Sorts the array using bubble sort algorithm and prints the array after each pass.

    Parameters:
    n (int): the length of the array
    arr (list): the list of integers to be sorted
    """
    for i in range(n):
        swapped = False
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swapped = True
        if swapped:
            print(' '.join(map(str, arr)))
        else:
            break

