def min_height_to_trim(plants):
    def is_symmetric_with_peak(peak):
        left = plants[:peak + 1]
        right = plants[peak:]
        return left == right[::-1]

    n = len(plants)
    max_height = max(plants)
    for peak in range(n):
        if is_symmetric_with_peak(peak):
            return plants[peak]

    return max_height

# Solution function
def solve(n, plant_heights):
    return min_height_to_trim(plant_heights)

