def max_subarray_sum(n, A):
    """
    Returns the maximum sum of any contiguous subarray within A.
    """
    max_sum = float('-inf')
    current_sum = 0

    for num in A:
        if current_sum < 0:
            current_sum = num
        else:
            current_sum += num
        max_sum = max(max_sum, current_sum)

    return max_sum

