def findPosition(nums, target):
    """
    Returns the position of the target in the array if present,
    otherwise returns the position where it can be inserted to maintain sorted order.
    """
    left, right = 0, len(nums) - 1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return left

