def minimizeMaxDeliveryTime(M, deliveryTimes):
    def canDistribute(deliveryTimes, M, maxTime):
        current_sum = 0
        required_drivers = 1
        for time in deliveryTimes:
            if current_sum + time > maxTime:
                required_drivers += 1
                current_sum = time
                if required_drivers > M:
                    return False
            else:
                current_sum += time
        return True

    low, high = max(deliveryTimes), sum(deliveryTimes)

    while low < high:
        mid = (low + high) // 2
        if canDistribute(deliveryTimes, M, mid):
            high = mid
        else:
            low = mid + 1

    return low

