def can_transform(S, T):
    if len(S) != len(T):
        return "NO"

    first_offset = (ord(T[0]) - ord(S[0])) % 26
    for i in range(1, len(S)):
        current_offset = (ord(T[i]) - ord(S[i])) % 26
        if current_offset != first_offset:
            return "NO"

    return "YES"

def process_queries(queries):
    results = []
    for S, T in queries:
        results.append(can_transform(S, T))
    return results

