def longest_zigzag_subsequence(arr):
    n = len(arr)
    if n < 2:
        return n

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            up[i] = down[i - 1] + 1
            down[i] = down[i - 1]
        elif arr[i] < arr[i - 1]:
            down[i] = up[i - 1] + 1
            up[i] = up[i - 1]
        else:
            up[i] = up[i - 1]
            down[i] = down[i - 1]

    return max(up[-1], down[-1])

