def compress_string(s):
    """
    Compresses the given string by replacing sequences of the same character
    length greater than one by that character followed by the sequence length.
    If the length is one, keep the character as it is.

    :param s: The input string to compress
    :return: The compressed string
    """
    if not s:
        return ""

    compressed = []
    count = 1
    previous_char = s[0]

    for char in s[1:]:
        if char == previous_char:
            count += 1
        else:
            if count > 1:
                compressed.append(f'{previous_char}{count}')
            else:
                compressed.append(previous_char)
            previous_char = char
            count = 1

    # Handle the last character(s)
    if count > 1:
        compressed.append(f'{previous_char}{count}')
    else:
        compressed.append(previous_char)

    return ''.join(compressed)

