        num_dict[num] = i

def min_operations_to_limit_max(n, x, a):
    """
    Returns the minimum number of operations required to make the maximum element of the array `a` not greater than `x`.
    """
    max_a = max(a)

    if max_a <= x:
        return 0
    else:
        return max_a - x

