import math

def calculate_std_dev(arr):
    n = len(arr)
    mean = sum(arr) / n
    variance = sum((x - mean) ** 2 for x in arr) / n
    return math.sqrt(variance)

def min_std_dev_after_removal(arr):
    n = len(arr)
    if n <= 1:
        return 0

    original_std_dev = calculate_std_dev(arr)
    min_std_dev = original_std_dev

    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        new_std_dev = calculate_std_dev(new_arr)
        min_std_dev = min(min_std_dev, new_std_dev)

    return round(min_std_dev, 6)

