from collections import deque

def is_adjacent(word1, word2):
    """
    Returns True if word1 and word2 differ by exactly one character.
    """
    difference_count = 0
    for c1, c2 in zip(word1, word2):
        if c1 != c2:
            difference_count += 1
        if difference_count > 1:
            return False
    return difference_count == 1

def shortest_word_ladder_length(words, start, end):
    """
    Returns the length of the shortest word ladder from start to end.
    If no such ladder exists, returns -1.
    """
    if start == end:
        return 1

    word_set = set(words)
    queue = deque([(start, 1)])
    visited = set()
    visited.add(start)

    while queue:
        current_word, current_length = queue.popleft()
        for word in word_set:
            if word not in visited and is_adjacent(current_word, word):
                if word == end:
                    return current_length + 1
                queue.append((word, current_length + 1))
                visited.add(word)

    return -1

