from collections import defaultdict, deque

def alienDictionary(words):
    def build_graph(words):
        graph = defaultdict(set)
        indegree = {char: 0 for word in words for char in word}

        for i in range(len(words) - 1):
            first_word = words[i]
            second_word = words[i + 1]
            min_length = min(len(first_word), len(second_word))

            if first_word[:min_length] == second_word[:min_length] and len(first_word) > len(second_word):
                # invalid case where prefix longer is ahead
                return {}, {}

            for j in range(min_length):
                if first_word[j] != second_word[j]:
                    if second_word[j] not in graph[first_word[j]]:
                        graph[first_word[j]].add(second_word[j])
                        indegree[second_word[j]] += 1
                    break

        return graph, indegree

    def topological_sort(graph, indegree):
        queue = deque([char for char in indegree if indegree[char] == 0])
        top_order = []

        while queue:
            char = queue.popleft()
            top_order.append(char)

            for neighbor in graph[char]:
                indegree[neighbor] -= 1
                if indegree[neighbor] == 0:
                    queue.append(neighbor)

        if len(top_order) == len(indegree):
            return ''.join(top_order)
        else:
            return ""

    graph, indegree = build_graph(words)
    if not graph and not indegree:
        return ""

    return topological_sort(graph, indegree)

