from datetime import datetime, timedelta
from collections import defaultdict

def detect_bots(log_data):
    def parse_log_entry(entry):
        # Split the log entry parts
        parts = entry.split(maxsplit=2)
        timestamp = parts[0] + " " + parts[1]
        user_id = parts[2].split(maxsplit=1)[0]
        message = parts[2].split(maxsplit=1)[1] if len(parts[2].split(maxsplit=1)) > 1 else ""
        return timestamp, user_id, message

    def is_bot_activity(times):
        if len(times) < 3:
            return False
        # Check the time difference within the 10-minute window (600 seconds)
        for i in range(2, len(times)):
            if (times[i] - times[i-2]).total_seconds() <= 600:
                return True
        return False

    log_dict = defaultdict(lambda: defaultdict(list))
    results = set()

    for entry in log_data:
        if entry == "end":
            break
        timestamp, user_id, message = parse_log_entry(entry)
        timestamp = datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S')
        log_dict[user_id][message].append(timestamp)

    for user_id, messages in log_dict.items():
        for message_timestamps in messages.values():
            if is_bot_activity(sorted(message_timestamps)):
                results.add(user_id)

    return sorted(results)

from typing import List

def threeSum(nums: List[int]) -> List[List[int]]:
    nums.sort()  # Sort the input list to aid the two-pointer technique
    triplets = []
    n = len(nums)

    for i in range(n - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue  # Skip duplicates

        left, right = i + 1, n - 1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s == 0:
                triplets.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1  # Skip duplicates
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1  # Skip duplicates
                left += 1
                right -= 1
            elif s < 0:
                left += 1
            else:
                right -= 1

    return triplets

