def calculate_intersection_area(rect1, rect2):
    """
    Returns a tuple with 'yes' or 'no' indicating if the rectangles overlap and the intersection area.
    rect1: tuple (x1, y1, x2, y2) Bottom-left to top-right coordinates of the first rectangle.
    rect2: tuple (x3, y3, x4, y4) Bottom-left to top-right coordinates of the second rectangle.
    """
    x1, y1, x2, y2 = rect1
    x3, y3, x4, y4 = rect2

    # Calculate the overlapping region boundaries
    overlap_x1 = max(x1, x3)
    overlap_y1 = max(y1, y3)
    overlap_x2 = min(x2, x4)
    overlap_y2 = min(y2, y4)

    # Check if there's an overlap
    if overlap_x1 < overlap_x2 and overlap_y1 < overlap_y2:
        overlap_area = (overlap_x2 - overlap_x1) * (overlap_y2 - overlap_y1)
        return ('yes', overlap_area)
    else:
        return ('no', 0)

