def count_unique_paths(matrix):
    n = len(matrix)
    m = len(matrix[0])

    # If the starting or ending cell is 1, return 0 as no path exists
    if matrix[0][0] == 1 or matrix[n-1][m-1] == 1:
        return 0

    # Create a 2D dp array with the same dimensions as matrix
    dp = [[0] * m for _ in range(n)]

    # Initialization: Number of ways to reach any cell in the first row
    for i in range(m):
        if matrix[0][i] == 0:
            dp[0][i] = 1
        else:
            break

    # Initialization: Number of ways to reach any cell in the first column
    for i in range(n):
        if matrix[i][0] == 0:
            dp[i][0] = 1
        else:
            break

    # Fill up the dp array
    for i in range(1, n):
        for j in range(1, m):
            if matrix[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[n-1][m-1]

