def min_number_of_guides(n, schedules):
    """
    Returns the minimum number of guides required to lead all group visits on a given day.

    :param n: Number of visitor groups
    :param schedules: A list of visitation schedules, each represented by a string of 7 zeroes and ones
    :return: Minimum number of guides required
    """
    slots = [0] * 7  # there are 7 time slots

    for schedule in schedules:
        for i in range(7):
            if schedule[i] == '1':
                slots[i] += 1

    return max(slots)

