def sum_of_unique_prime_factors(n):
    """
    Given an integer n (2 ≤ n ≤ 10^12), return the sum of its unique prime factors.
    """
    def get_prime_factors(num):
        prime_factors = set()
        # Check for the number of 2s
        while num % 2 == 0:
            prime_factors.add(2)
            num //= 2
        # Check for odd factors from 3 upwards
        for i in range(3, int(num**0.5) + 1, 2):
            while num % i == 0:
                prime_factors.add(i)
                num //= i
        # This condition is to check if num is a prime greater than 2
        if num > 2:
            prime_factors.add(num)
        return prime_factors

    prime_factors = get_prime_factors(n)
    return sum(prime_factors)

