def count_non_overlapping_occurrences(s, p):
    """
    Returns the number of non-overlapping occurrences of pattern p in string s.
    """
    count = 0
    i = 0
    while i <= len(s) - len(p):
        if s[i:i + len(p)] == p:
            count += 1
            i += len(p)
        else:
            i += 1
    return count

