def two_sum(nums, target):
    """
    Finds two distinct indices in the nums list such that the elements at those indices add up to the target.

    Parameters:
    nums (list): A list of distinct integers.
    target (int): The target sum.

    Returns:
    tuple: A tuple of two indices in ascending order where the numbers at those indices add up to the target.
    """
    if len(nums) < 2:
        return None

    num_to_index = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in num_to_index:
            return (min(i, num_to_index[complement]), max(i, num_to_index[complement]))
        num_to_index[num] = i

    return None  # This line should theoretically never be reached due to problem constraints.

