def is_prime(num):
    """
    Helper function to determine if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def check_prime_rows_and_columns(matrix):
    """
    Function to check if any row or column in the matrix consists only of prime numbers.
    """
    N = len(matrix)

    # Check rows for prime-only rows
    for row in matrix:
        if all(is_prime(num) for num in row):
            return "YES"

    # Check columns for prime-only columns
    for col in range(N):
        if all(is_prime(matrix[row][col]) for row in range(N)):
            return "YES"

    return "NO"

def categorize_age(age):
    if age >= 0 and age <= 2:
        return "Infant"
    elif age >= 3 and age <= 12:
        return "Child"
    elif age >= 13 and age <= 17:
        return "Teen"
    elif age >= 18 and age <= 64:
        return "Adult"
    elif age >= 65:
        return "Senior"
    else:
        raise ValueError("Invalid age")

def process_ages(ages):
