def isMeetingRoomAvailable(schedules, requestedSlot):
    def are_slots_conflicting(slot1, slot2):
        return not (slot1[1] <= slot2[0] or slot2[1] <= slot1[0])

    start_req, end_req = requestedSlot

    available_room = None

    for room in sorted(schedules.keys()):
        is_available = True
        for booked_slot in schedules[room]:
            if are_slots_conflicting(booked_slot, requestedSlot):
                is_available = False
                break
        if is_available:
            available_room = room
            break

    return available_room if available_room else "No meeting room available"

