from collections import defaultdict, deque

def min_beacons(n, k, beacon_hills, paths):
    if k >= n:
        return n

    adjacency_list = defaultdict(list)
    for path in paths:
        x, y = path
        adjacency_list[x].append(y)
        adjacency_list[y].append(x)

    beacons = set(beacon_hills)
    covered = set(beacon_hills)

    for b in beacon_hills:
        for neighbor in adjacency_list[b]:
            covered.add(neighbor)

    return len(beacons) if len(covered) == n else -1

import heapq

def dijkstra(n, edges, start, destination):
    """
    Returns the shortest path between the start and destination cities using Dijkstra's algorithm.
    If there's no possible path, return -1.
    """
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))  # Since the graph is undirected

    # Min-heap priority queue
    heap = [(0, start)]  # (distance, node)
    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[start] = 0
    visited = set()

    while heap:
        current_distance, current_node = heapq.heappop(heap)
        if current_node in visited:
            continue
        visited.add(current_node)

        if current_node == destination:
            return current_distance

        for neighbor, weight in graph[current_node]:
            if neighbor in visited:
                continue
            new_distance = current_distance + weight
            if new_distance < distances[neighbor]:
                distances[neighbor] = new_distance
                heapq.heappush(heap, (new_distance, neighbor))

    return -1 if distances[destination] == float('inf') else distances[destination]

