def calculate_interaction_times(events):
    """
    Calculate the total interaction times for each customer from the given list of events.

    Parameters:
    - events: list of tuples (customer_id, event_type, timestamp)

    Returns:
    - dict: customer_id to total interaction time in seconds
    """
    interaction_times = {}
    start_times = {}

    for event in events:
        customer_id, event_type, timestamp = event

        if event_type == "start":
            start_times[customer_id] = timestamp
        elif event_type == "end":
            if customer_id in start_times:
                duration = timestamp - start_times.pop(customer_id)
                if customer_id in interaction_times:
                    interaction_times[customer_id] += duration
                else:
                    interaction_times[customer_id] = duration

    return interaction_times

