def max_profit(prices):
    if not prices or len(prices) < 2:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

def balance(s):
    """
    Returns the minimum number of parentheses needed to make the input string valid.
    """
    open_count = 0
    close_needed = 0

    for char in s:
        if char == '(':
            open_count += 1
        elif char == ')':
            if open_count > 0:
                open_count -= 1
            else:
                close_needed += 1

    return open_count + close_needed

