from collections import deque

def can_reach(grid, r_start, c_start, r_end, c_end):
    n = len(grid)
    m = len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == '.'

    queue = deque([(r_start, c_start)])
    visited = set()
    visited.add((r_start, c_start))

    while queue:
        x, y = queue.popleft()
        if (x, y) == (r_end, c_end):
            return 'YES'

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return 'NO'

