def can_spacecraft_reach_destination(n, m, f, grid):
    from collections import deque

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == '.'

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    queue = deque([(0, 0, 1)])  # (x, y, cells visited)
    visited = set((0, 0))

    while queue:
        x, y, cells_visited = queue.popleft()

        if cells_visited > f:
            continue

        if x == n - 1 and y == m - 1:
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, cells_visited + 1))

    return "NO"

