def MinimumCorridorLength(N, M):
    """
    Returns the minimum total length of the corridors required to connect all outposts.

    :param N: int, number of outposts
    :param M: list of lists where each inner list contains three integers u, v, and w
    :return: int, minimum total length of corridors
    """

    def find(parent, i):
        if parent[i] == i:
            return i
        else:
            parent[i] = find(parent, parent[i])
            return parent[i]

    def union(parent, rank, x, y):
        root_x = find(parent, x)
        root_y = find(parent, y)

        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            elif rank[root_x] < rank[root_y]:
                parent[root_x] = root_y
            else:
                parent[root_y] = root_x
                rank[root_x] += 1

    # Sort all the edges in non-decreasing order based on their weight
    M.sort(key=lambda x: x[2])

    parent = list(range(N))
    rank = [0] * N

    min_length = 0
    edges_used = 0

    for u, v, w in M:
        if find(parent, u) != find(parent, v):
            union(parent, rank, u, v)
            min_length += w
            edges_used += 1
            if edges_used == N - 1:
                break

    return min_length

