from collections import defaultdict

def max_distinct_elements(t, test_cases):
    results = []
    for case in test_cases:
        n, k, arr = case
        window_counts = defaultdict(int)
        distinct_count = 0
        max_distinct = 0

        for i in range(n):
            if i >= k:
                if window_counts[arr[i - k]] == 1:
                    distinct_count -= 1
                window_counts[arr[i - k]] -= 1

            if window_counts[arr[i]] == 0:
                distinct_count += 1
            window_counts[arr[i]] += 1

            if i >= k - 1:
                max_distinct = max(max_distinct, distinct_count)

        results.append(max_distinct)
    return results

