def max_combined_beauty(n, flowers):
    max_beauty = -1
    max_beauty_so_far = [0] * n

    max_val = 0
    for i in range(n):
        max_val = max(max_val, flowers[i][1])
        max_beauty_so_far[i] = max_val

    for j in range(1, n):
        for i in range(j):
            if flowers[i][0] < flowers[j][0] and flowers[i][1] < flowers[j][1]:
                max_beauty = max(max_beauty, flowers[i][1] + flowers[j][1])

    return max_beauty

