def calculate_shipping_cost(categories, items):
    """
    Calculate the total efficient shipping cost for the cart based on categories.
    """
    category_info = {}
    for category in categories:
        name, cost1, cost2 = category.split()
        cost1 = int(cost1)
        cost2 = int(cost2)
        category_info[name] = (cost1, cost2)

    category_count = {}
    total_cost = 0

    for item in items:
        item_name, *item_categories = item.split()
        for category in item_categories:
            if category not in category_count:
                category_count[category] = 0
            category_count[category] += 1

            if category_count[category] == 1:
                total_cost += category_info[category][0]
            else:
                total_cost += category_info[category][1]

    return total_cost

def check_storage(T, test_cases):
    results = []
    for t in range(T):
        N, shelf_items, limit = test_cases[t]
        total_items = sum(shelf_items)
        if total_items <= limit:
            results.append("Possible")
        else:
            results.append("Impossible")
    return results

