def canFollowCommands(n, m, grid, s):
    def isValid(i, j):
        return 0 <= i < n and 0 <= j < m and grid[i][j] == 1

    directions = {'L': (0, -1), 'R': (0, 1), 'U': (-1, 0), 'D': (1, 0)}

    for start_i in range(n):
        for start_j in range(m):
            if grid[start_i][start_j] == 1:
                i, j = start_i, start_j
                valid = True
                for command in s:
                    di, dj = directions[command]
                    i += di
                    j += dj
                    if not isValid(i, j):
                        valid = False
                        break
                if valid:
                    return 1
    return 0

def maxSubarraySum(arr):
    """
    Returns the maximum sum of any non-empty subarray of consecutive elements.
    """
    max_current = max_global = arr[0]

    for number in arr[1:]:
        max_current = max(number, max_current + number)
        if max_current > max_global:
            max_global = max_current

    return max_global

