def count_unique_statements(statements):
    """
    Returns the number of unique problem statements considering anagrams as identical.
    """
    def normalize(statement):
        """
        Normalizes the statement by sorting the characters (excluding spaces)
        """
        return ''.join(sorted(statement.replace(' ', '')))

    unique_statements = set()
    for statement in statements:
        normalized = normalize(statement)
        unique_statements.add(normalized)

    return len(unique_statements)

