def number_of_island_groups(N, M, bridges):
    from collections import defaultdict, deque

    # Adjacency list for graph
    graph = defaultdict(list)

    # Construct the graph
    for u, v in bridges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()

    def bfs(start):
        queue = deque([start])
        while queue:
            node = queue.popleft()
            for neighbor in graph[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    groups = 0

    # Traverse all nodes to count connected components
    for i in range(1, N+1):
        if i not in visited:
            bfs(i)
            groups += 1

    return groups

