def find_intersection(a1, b1, a2, b2):
    """
    Finds the intersection of two intervals [a1, b1] and [a2, b2].
    Returns the intersection as a tuple (start, end) if they intersect, or "NO" if they do not.
    """
    start = max(a1, a2)
    end = min(b1, b2)

    if start <= end:
        return (start, end)
    else:
        return "NO"

def process_test_cases(t, test_cases):
    results = []
    for i in range(t):
        a1, b1, a2, b2 = test_cases[i]
        result = find_intersection(a1, b1, a2, b2)
        results.append(result)
    return results

