def smallest_palindrome(n, s):
    s = list(s)  # Convert string to a list for mutability
    left, right = 0, n - 1

    while left <= right:
        if s[left] == s[right] == '?':
            s[left], s[right] = 'a', 'a'
        elif s[left] == '?':
            s[left] = s[right]
        elif s[right] == '?':
            s[right] = s[left]
        elif s[left] != s[right]:
            return "-1"
        left += 1
        right -= 1

    return "".join(s)

