def max_total_size(n, k, files):
    # Sort the files first by their required number of computers,
    # and by their size in descending order if computers required is the same
    files.sort(key=lambda x: (x[1], -x[0]))

    max_size = 0
    count = 0  # Track the number of files processed concurrently

    for size, comps in files:
        if count < k:
            max_size += size
            count += 1
        else:
            break

    return max_size

