def tsp(graph, start=0):
    n = len(graph)
    END_STATE = (1 << n) - 1
    cache = [[None] * (1 << n) for _ in range(n)]

    def find_path(last, visited):
        if visited == END_STATE:
            return graph[last][start]

        if cache[last][visited] is not None:
            return cache[last][visited]

        res = float('inf')
        for city in range(n):
            if visited & (1 << city) == 0:
                distance = graph[last][city] + find_path(city, visited | (1 << city))
                res = min(res, distance)

        cache[last][visited] = res
        return res

    return find_path(start, 1 << start)

