def box_operations(operations):
    boxes = {}
    results = []

    for operation in operations:
        op = operation.split()

        if op[0] == 'CREATE':
            x = int(op[1])
            boxes[x] = []

        elif op[0] == 'ADD':
            x = int(op[1])
            y = int(op[2])
            boxes[x].append(y)

        elif op[0] == 'MOVE':
            x = int(op[1])
            y = int(op[2])
            boxes[y].extend(boxes[x])
            boxes[x] = []

        elif op[0] == 'QUERY':
            x = int(op[1])
            results.append(len(boxes[x]))

    return results

def is_bipartite_graph(N, M, edges):
    """
    Determines if a graph can be colored using exactly two colors
    such that no two adjacent nodes have the same color.
    """
    from collections import deque

    # Create an adjacency list
    adjacency_list = [[] for _ in range(N)]
    for u, v in edges:
        adjacency_list[u-1].append(v-1)
        adjacency_list[v-1].append(u-1)

    colors = [-1] * N  # -1 signifies no color assigned yet

    def bfs(source):
        queue = deque([source])
        colors[source] = 0

        while queue:
            node = queue.popleft()
            current_color = colors[node]

            for neighbor in adjacency_list[node]:
                if colors[neighbor] == -1:
                    # If the neighbor hasn't been colored, color it with opposite color to current node
                    colors[neighbor] = 1 - current_color
                    queue.append(neighbor)
                elif colors[neighbor] == current_color:
                    # If the neighbor is colored and has the same color as current node, it's not bipartite
                    return False
        return True

    # As the graph could be disconnected, we need to check each component
    for node in range(N):
        if colors[node] == -1:
            if not bfs(node):
                return "NO"

    return "YES"

from typing import List

def max_profit(prices: List[int]) -> int:
    if not prices or len(prices) < 2:
        return 0
    min_price = prices[0]
    max_profit = 0

    for price in prices[1:]:
        if price < min_price:
            min_price = price
        else:
            profit = price - min_price
            if profit > max_profit:
                max_profit = profit

    return max_profit

