import math

def gcd_query(M, B, P, queries):
    results = []

    # For each query, compute the GCD of the subarray
    for l, r in queries:
        subarray_gcd = B[l-1]  # Initializing with the first element of the subarray
        for i in range(l, r):
            subarray_gcd = math.gcd(subarray_gcd, B[i])
            if subarray_gcd == 1:
                break  # no point in continuing if the GCD is 1
        results.append(subarray_gcd)

    return results

def longestBitonicSubarray(arr):
    n = len(arr)
    if n < 2:
        return n

    # Arrays to store lengths of increasing and decreasing subarrays
    inc = [1] * n
    dec = [1] * n

    # Fill the inc[] array
    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            inc[i] = inc[i - 1] + 1

    # Fill the dec[] array
    for i in range(n - 2, -1, -1):
        if arr[i] > arr[i + 1]:
            dec[i] = dec[i + 1] + 1

    # Calculate the length of the
    # longest bitonic subarray
    max_len = 1
    for i in range(n):
        max_len = max(max_len, inc[i] + dec[i] - 1)

    return max_len

