from typing import List

def combination_sum(nums: List[int], target: int) -> List[List[int]]:
    def backtrack(start: int, target: int, path: List[int]):
        if target == 0:
            result.append(path[:])
            return
        if target < 0:
            return

        for i in range(start, len(nums)):
            if i > start and nums[i] == nums[i - 1]:
                continue
            path.append(nums[i])
            backtrack(i + 1, target - nums[i], path)
            path.pop()

    nums.sort()
    result = []
    backtrack(0, target, [])
    return result

def min_trays(capacity, produce_weights):
    trays = []

    for weight in produce_weights:
        placed = False
        for tray in trays:
            if sum(tray) + weight <= capacity:
                tray.append(weight)
                placed = True
                break
        if not placed:
            trays.append([weight])

    return len(trays)

