def min_changes_to_avoid_adjacent_duplicates(n, colors):
    changes = 0
    for i in range(1, n):
        if colors[i] == colors[i - 1]:
            changes += 1
            if i + 1 < n and colors[i + 1] != colors[i]:
                colors[i] = colors[i - 1]
            else:
                colors[i] = colors[i - 1] + 1
    return changes

