def longest_continuous_sunlight(n, intervals):
    intervals.sort()

    max_interval = (0, 0)
    current_start, current_end = intervals[0]

    for i in range(1, n):
        start, end = intervals[i]
        if start <= current_end:
            current_end = max(current_end, end)
        else:
            if (current_end - current_start) > (max_interval[1] - max_interval[0]):
                max_interval = (current_start, current_end)
            current_start, current_end = start, end

    if (current_end - current_start) > (max_interval[1] - max_interval[0]):
        max_interval = (current_start, current_end)

    return max_interval

