def maximalRectangle(matrix):
    """
    Given a binary matrix filled with 0's and 1's, find the largest rectangle containing only 1's and return its area.
    """
    if not matrix:
        return 0

    max_area = 0
    n = len(matrix)
    m = len(matrix[0])

    heights = [0] * (m + 1)

    for row in matrix:
        for i in range(m):
            if row[i] == 1:
                heights[i] += 1
            else:
                heights[i] = 0

        stack = [-1]
        for i in range(m + 1):
            while heights[i] < heights[stack[-1]]:
                h = heights[stack.pop()]
                w = i - stack[-1] - 1
                max_area = max(max_area, h * w)
            stack.append(i)

    return max_area

def firstUnique(nums):
    """
    Returns the first unique integer in the list nums. If there is no unique integer, returns -1.
    """
    count = {}
    for num in nums:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    for num in nums:
        if count[num] == 1:
            return num

    return -1

