def flatten_json(json_obj, delimiter):
    """
    Flattens a nested JSON object into a single-level dictionary.

    Parameters:
    - json_obj (dict): The nested JSON object.
    - delimiter (str): The string used to separate keys in the flattened dictionary.

    Returns:
    - dict: The flattened JSON object.
    """
    def flatten(current_obj, parent_key, flattened_dict):
        if isinstance(current_obj, dict):
            for key, value in current_obj.items():
                new_key = f"{parent_key}{delimiter}{key}" if parent_key else key
                flatten(value, new_key, flattened_dict)
        elif isinstance(current_obj, list):
            for i, item in enumerate(current_obj):
                new_key = f"{parent_key}[{i}]"
                flatten(item, new_key, flattened_dict)
        else:
            flattened_dict[parent_key] = current_obj

    result = {}
    flatten(json_obj, "", result)
    return result

