def count_divisibles(a, b, k):
    """
    Returns the count of numbers between a and b (inclusive) that are divisible by k.
    """
    if a % k == 0:
        start = a
    else:
        start = a + (k - a % k)

    if b % k == 0:
        end = b
    else:
        end = b - b % k

    if start > b:
        return 0

    return (end - start) // k + 1

