def increasingTripletSubseq(nums):
    """
    Returns True if there exists a triple (i, j, k) such that i < j < k and nums[i] < nums[j] < nums[k],
    otherwise returns False.
    """
    first = second = float('inf')
    for n in nums:
        if n <= first:
            first = n
        elif n <= second:
            second = n
        else:
            return True
    return False

