def min_books_to_remove(arr):
    """
    Function to find the minimum number of books to add or remove
    to make the sequence strictly increasing.
    """
    n = len(arr)
    dp = [1] * n   # dp[i] will store the length of LIS ending at index i

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    lis = max(dp)  # the length of the longest increasing subsequence
    return n - lis

