def find_majority_element(nums: List[int]) -> int:
    """
    Finds the majority element in the array which appears more than n/2 times.
    """
    candidate = None
    count = 0

    for num in nums:
        if count == 0:
            candidate = num
        if num == candidate:
            count += 1
        else:
            count -= 1

    return candidate

