from collections import defaultdict, deque

def shortest_path_from_start_to_destination(n, m, q, bus_routes, queries):
    # Create a map of bus stops to buses that visit those stops
    stop_to_buses = defaultdict(list)
    for bus_num, route in enumerate(bus_routes):
        for stop in route:
            stop_to_buses[stop].append(bus_num)

    def bfs(start, destination):
        if start == destination:
            return 0

        visited_stops = set()
        visited_buses = set()
        queue = deque([(start, 0)])  # (current stop, bus count)

        while queue:
            current_stop, bus_count = queue.popleft()
            if current_stop == destination:
                return bus_count

            for bus in stop_to_buses[current_stop]:
                if bus in visited_buses:
                    continue
                visited_buses.add(bus)
                for next_stop in bus_routes[bus]:
                    if next_stop not in visited_stops:
                        visited_stops.add(next_stop)
                        queue.append((next_stop, bus_count + 1))
        return -1

    results = []
    for start, destination in queries:
        results.append(bfs(start, destination))

    return results

