def max_contiguous_blocks(buildings: List[int]) -> int:
    if not buildings:
        return 0

    max_blocks = 1
    current_blocks = 1

    for i in range(1, len(buildings)):
        if buildings[i] == buildings[i - 1]:
            current_blocks += 1
            if current_blocks > max_blocks:
                max_blocks = current_blocks
        else:
            current_blocks = 1

    return max_blocks

