def is_secret_santa_possible(n, preferences):
    """
    Determines if a valid secret Santa assignment is possible, where everyone gets
    exactly one present from another participant and gives exactly one present to another
    participant based on given preferences.

    :param n: Number of participants
    :param preferences: List of strings where each string represents preferences of a participant
    :return: 'possible' if a valid assignment exists, otherwise 'impossible'
    """
    from collections import defaultdict, deque

    def can_match(pref):
        match = [-1] * n
        visited = [False] * n

        def bpm(u):
            for v in range(n):
                if pref[u][v] == '1' and not visited[v]:
                    visited[v] = True
                    if match[v] == -1 or bpm(match[v]):
                        match[v] = u
                        return True
            return False

        for i in range(n):
            visited = [False] * n
            if not bpm(i):
                return False
        return True

    # Check if a perfect bipartite matching is possible
    if can_match(preferences):
        return 'possible'
    else:
        return 'impossible'

import heapq
import sys

def dijkstra(graph, start, end, n):
    """
    Uses Dijkstra's algorithm to find the minimum total risk level path from start to end.
    """
    # Initialize distances as infinity
    distances = {i: float('inf') for i in range(1, n + 1)}
    distances[start] = 0

    # Priority queue to manage visiting nodes
    priority_queue = [(0, start)]  # (distance, node)

    while priority_queue:
        current_distance, current_node = heapq.heappop(priority_queue)

        if current_node == end:
            return current_distance

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph.get(current_node, []):
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return -1 if distances[end] == float('inf') else distances[end]

def minimum_risk_levels(T, test_cases):
    results = []

    for i in range(T):
        N, M, edges, Q, queries = test_cases[i]

        # Construct graph
        graph = {}
        for u, v, w in edges:
            if u not in graph:
                graph[u] = []
            graph[u].append((v, w))

        # Answer queries
        for a, b in queries:
            result = dijkstra(graph, a, b, N)
            results.append(result)

    return results

