def max_sum_subgrid(test_cases):
    results = []
    for grid in test_cases:
        R, C = grid[0]
        matrix = grid[1:]
        max_sum = float('-inf')

        # We use Kadane's algorithm extended to 2D
        for left in range(C):
            temp = [0] * R
            for right in range(left, C):
                for i in range(R):
                    temp[i] += matrix[i][right]

                current_max = max_subarray_sum(temp)
                max_sum = max(max_sum, current_max)

        results.append(max_sum)

    return results

def max_subarray_sum(array):
    max_so_far = float('-inf')
    max_ending_here = 0
    for x in array:
        max_ending_here += x
        if max_so_far < max_ending_here:
            max_so_far = max_ending_here
        if max_ending_here < 0:
            max_ending_here = 0
    return max_so_far

def parse_input(input_lines):
    index = 0
    T = int(input_lines[index])
    index += 1
    test_cases = []
    for _ in range(T):
        R, C = map(int, input_lines[index].split())
        index += 1
        grid = []
        for _ in range(R):
            grid.append(list(map(int, input_lines[index].split())))
            index += 1
        test_cases.append([(R, C)] + grid)
    return test_cases

