def minimum_reverse_operations(n, array):
    """
    Determine the minimum number of operations required to sort the list in non-decreasing order
    by reversing the order of some contiguous subarray.
    """
    sorted_array = sorted(array)

    if array == sorted_array:
        return 0, []

    result = []
    left = 0

    # Find the first mismatching pair from the beginning
    while array[left] == sorted_array[left]:
        left += 1

    right = n - 1

    # Find the first mismatching pair from the end
    while array[right] == sorted_array[right]:
        right -= 1

    while left < right:
        result.append((left + 1, right + 1))
        array[left:right + 1] = array[left:right + 1][::-1]

        while left < n and array[left] == sorted_array[left]:
            left += 1

        while right >= 0 and array[right] == sorted_array[right]:
            right -= 1

        if left < right:
            result.append((left + 1, right + 1))
            array[left:right + 1] = array[left:right + 1][::-1]

        if array == sorted_array:
            break

    if array != sorted_array:
        return -1, []

    return len(result), result

