def has_non_decreasing_subsequence(nums):
    """
    Returns True if there exists a non-decreasing subsequence of length at least 3, otherwise False.
    """
    n = len(nums)
    if n < 3:
        return False

    first_min = float('inf')
    second_min = float('inf')

    for num in nums:
        if num <= first_min:
            first_min = num
        elif num <= second_min:
            second_min = num
        else:
            return True
    return False

