def min_venues(T, test_cases):
    results = []
    for test_case in test_cases:
        N, events = test_case
        times = []
        for start, end in events:
            times.append((start, 'start'))
            times.append((end, 'end'))

        times.sort()
        max_venues = 0
        current_venues = 0

        for time in times:
            if time[1] == 'start':
                current_venues += 1
                if current_venues > max_venues:
                    max_venues = current_venues
            else:
                current_venues -= 1

        results.append(max_venues)

    return results

def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True

    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False

    return True

