def find_peak_element(grid):
    """
    Given a 2D grid of integers, find one peak element in the grid. A peak element is
    an element which is greater than or equal to its directly adjacent neighbors.
    """
    n = len(grid)

    def is_peak(i, j):
        current = grid[i][j]
        if i > 0 and current < grid[i-1][j]:
            return False
        if i < n-1 and current < grid[i+1][j]:
            return False
        if j > 0 and current < grid[i][j-1]:
            return False
        if j < n-1 and current < grid[i][j+1]:
            return False
        return True

    for i in range(n):
        for j in range(n):
            if is_peak(i, j):
                return grid[i][j]

    return None # if no peak is found (though there should always be at least one peak)

def can_distribute_equally(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        genres = test_cases[i][1]
        genre_count = {}

        for genre in genres:
            if genre in genre_count:
                genre_count[genre] += 1
            else:
                genre_count[genre] = 1

        counts = list(genre_count.values())
        if len(set(counts)) == 1:
            results.append("Possible")
        else:
            results.append("Not Possible")

    return results

