from typing import List, Tuple

def find_pairs(numbers: List[int], targetSum: int) -> List[Tuple[int, int]]:
    """
    Returns all unique pairs of integers in the list that sum up to the targetSum.
    Each pair is sorted in increasing order, and the result list is sorted lexicographically.
    """
    seen = {}
    pairs = set()

    for number in numbers:
        complement = targetSum - number
        if complement in seen:
            pairs.add(tuple(sorted((number, complement))))
        seen[number] = 1  # mark the number as seen

    return sorted(pairs)

def find_median_score(scores):
    """
    Returns the median score from a list of scores.
    """
    scores.sort()
    n = len(scores)
    if n % 2 == 1:
        return scores[n // 2]
    else:
        return (scores[n // 2 - 1] + scores[n // 2]) / 2

