from collections import deque

def can_escape(grid, n, m):
    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]  # Down, Right, Up, Left
    visited = [[False] * m for _ in range(n)]
    queue = deque([(0, 0)])  # Start from the top-left corner

    while queue:
        x, y = queue.popleft()
        if x == n - 1 and y == m - 1:  # Reach the bottom-right corner
            return True
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny))
    return False

def is_path_exists(n, m, q, grid, operations):
    for x, y in operations:
        grid[x-1], grid[y-1] = grid[y-1], grid[x-1]  # Adjust for 0-indexing

    return "YES" if can_escape(grid, n, m) else "NO"

