    return results

def maxSumNonAdjacent(N, arr):
    if N == 0:
        return 0
    if N == 1:
        return arr[0]

    prev1 = max(0, arr[0])
    prev2 = 0

    for i in range(1, N):
        current = max(prev1, prev2 + arr[i])
        prev2 = prev1
        prev1 = current

    return prev1

