def days_between_dates(date1, date2):
    def date_to_days(date):
        day, month, year = date.split('-')
        day = int(day)
        year = int(year)

        months_to_days = {
            'january': 0, 'february': 30, 'march': 60, 'april': 90,
            'may': 120, 'june': 150, 'july': 180, 'august': 210,
            'september': 240, 'october': 270, 'november': 300, 'december': 330
        }

        return day + months_to_days[month] + (year - 1) * 360

    days1 = date_to_days(date1)
    days2 = date_to_days(date2)

    return abs(days1 - days2)

def process_input(T, test_cases):
    results = []
    for i in range(T):
        date1, date2 = test_cases[i].split()
        results.append(days_between_dates(date1, date2))
    return results

