def find_max_difference(nums):
    """
    Returns the maximum difference between any two elements in the list such that
    the larger element comes after the smaller one.
    If no such pair exists, return -1.
    """
    if len(nums) < 2:
        return -1

    min_element = nums[0]
    max_difference = -1

    for num in nums[1:]:
        if num > min_element:
            max_difference = max(max_difference, num - min_element)
        else:
            min_element = min(min_element, num)

    return max_difference

