def infix_to_postfix(expression):
    """
    Convert an infix expression to a postfix expression.
    """
    precedence = {'^': 3, '*': 2, '/': 2, '+': 1, '-': 1}
    is_right_associative = {'^': True, '+': False, '-': False, '*': False, '/': False}

    def has_higher_precedence(op1, op2):
        if (op1 in precedence and op2 in precedence):
            if is_right_associative[op1]:
                return precedence[op1] > precedence[op2]
            else:
                return precedence[op1] >= precedence[op2]
        return False

    output = []
    stack = []

    for char in expression:
        if char.isalpha():  # Operand
            output.append(char)
        elif char == '(':  # Left Parenthesis
            stack.append(char)
        elif char == ')':  # Right Parenthesis
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # Remove '(' from stack
        else:  # Operator
            while stack and has_higher_precedence(stack[-1], char):
                output.append(stack.pop())
            stack.append(char)

    while stack:
        output.append(stack.pop())

    return ''.join(output)

