def find_consecutive_segments(n, item_ids):
    item_ids.sort()
    segments = []
    start = item_ids[0]
    for i in range(1, n):
        if item_ids[i] != item_ids[i-1] + 1:
            segments.append((start, item_ids[i-1]))
            start = item_ids[i]
    segments.append((start, item_ids[-1]))

    return segments

