from collections import defaultdict, deque

def find_task_order(num_tasks, task_dependencies):
    """
    Determine the order of tasks based on their dependencies.
    :param num_tasks: Integer, number of tasks.
    :param task_dependencies: List of tuples, each containing task id and the list of its dependencies.
    :return: List of tasks in possible order, or "IMPOSSIBLE" if no valid ordering exists.
    """
    graph = defaultdict(list)
    in_degree = {i: 0 for i in range(1, num_tasks + 1)}

    # Build the graph and in-degree count
    for task_id, dependencies in task_dependencies:
        for dep in dependencies:
            graph[dep].append(task_id)
            in_degree[task_id] += 1

    # Find all nodes with zero in-degree
    zero_in_degree = deque([node for node in in_degree if in_degree[node] == 0])
    topological_order = []

    while zero_in_degree:
        current = zero_in_degree.popleft()
        topological_order.append(current)

        # Decrease the in-degree of each neighbor
        for neighbor in graph[current]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                zero_in_degree.append(neighbor)

    if len(topological_order) == num_tasks:
        return topological_order
    else:
        return "IMPOSSIBLE"

def find_first_duplicate(T, test_cases):
    result = []
    for case in test_cases:
        n, ids = case
        seen = set()
        first_duplicate = -1
        for id in ids:
            if id in seen:
                first_duplicate = id
                break
            seen.add(id)
        result.append(first_duplicate)
    return result

