def smallest_integer_with_digit_sum(N):
    if N > 45:  # The maximum sum we can achieve with digits 1 to 9 (which is 1+2+3+...+9)
        return -1

    digits = []
    for digit in range(9, 0, -1):
        if N >= digit:
            digits.append(digit)
            N -= digit

    digits.sort()
    return int(''.join(map(str, digits)))

def process_test_cases(T, test_cases):
    results = []
    for N in test_cases:
        results.append(smallest_integer_with_digit_sum(N))
