def count_paths(n, m, maze):
    """
    Counts the number of distinct paths from the top-left to the bottom-right corner of a maze,
    avoiding obstacles.

    Parameters:
    n (int): number of rows in the maze.
    m (int): number of columns in the maze.
    maze (list of list of int): 2D list representing the maze where 0 indicates an empty cell
                                and 1 indicates an obstacle.

    Returns:
    int: Number of distinct paths.
    """
    if maze[0][0] == 1 or maze[n-1][m-1] == 1:
        return 0

    dp = [[0 for _ in range(m)] for _ in range(n)]
    dp[0][0] = 1

    for i in range(n):
        for j in range(m):
            if maze[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

