def run_length_encoding(s):
    """
    Returns the run-length encoded version of the input string s.
    """
    if not s:
        return ""

    encoded_str = []
    prev_char = s[0]
    count = 1

    for char in s[1:]:
        if char == prev_char:
            count += 1
        else:
            encoded_str.append(prev_char + str(count))
            prev_char = char
            count = 1

    encoded_str.append(prev_char + str(count))  # Handle the last set of characters
    return ''.join(encoded_str)

