def uniquePathsWithObstacles(grid):
    m = len(grid)
    if m == 0:
        return 0
    n = len(grid[0])
    if n == 0:
        return 0

    # If the start or end cell is blocked, return 0
    if grid[0][0] == 1 or grid[m-1][n-1] == 1:
        return 0

    # Initialize a DP array with the same dimensions as the grid
    dp = [[0] * n for _ in range(m)]

    # Initialize the start cell
    dp[0][0] = 1

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]

    # Fill the rest of the dp table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

