def three_sum_zero(arr):
    """
    Returns a list of all unique triplets (a, b, c) in the array such that a + b + c = 0.
    """
    arr.sort()
    N = len(arr)
    result = []

    for i in range(N - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue

        left, right = i + 1, N - 1
        while left < right:
            total = arr[i] + arr[left] + arr[right]
            if total == 0:
                result.append((arr[i], arr[left], arr[right]))

                while left < right and arr[left] == arr[left + 1]:
                    left += 1
                while left < right and arr[right] == arr[right - 1]:
                    right -= 1

                left += 1
                right -= 1
            elif total < 0:
                left += 1
            else:
                right -= 1

    if not result:
        return "No triplets found"
    else:
        return result

def addPermission(perm, currentPerms):
    """
    Adds the permission by setting the perm bit in currentPerms.
    """
    return currentPerms | (1 << perm)

def removePermission(perm, currentPerms):
    """
    Removes the permission by clearing the perm bit in currentPerms.
    """
    return currentPerms & ~(1 << perm)

def checkPermission(perm, currentPerms):
    """
    Checks if the permission is set in currentPerms.
    """
    return 1 if currentPerms & (1 << perm) else 0

