def first_non_repeating_character(s):
    """
    Returns the first non-repeating character in the string `s`.
    If all characters are repeating, returns an empty string.
    """
    char_count = {}

    # Count the occurrences of each character
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character that occurs only once
    for char in s:
        if char_count[char] == 1:
            return char

    return ''

def find_cycle(n, m, edges):
    from collections import defaultdict

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    visited = [0] * (n + 1)  # 0 = not visited, 1 = visiting, 2 = visited
    stack = []
    parent = [-1] * (n + 1)

    def dfs(v):
        visited[v] = 1
        stack.append(v)

        for neighbour in graph[v]:
            if visited[neighbour] == 0:
                parent[neighbour] = v
                if dfs(neighbour):
                    return True
            elif visited[neighbour] == 1:
                cycle = []
                u = v
                while u != neighbour:
                    cycle.append(u)
                    u = parent[u]
                cycle.append(neighbour)
                cycle.append(v)
                cycle.reverse()
                print(" ".join(map(str, cycle)))
                return True

        visited[v] = 2
        stack.pop()
        return False

    for i in range(1, n + 1):
        if visited[i] == 0:
            if dfs(i):
                return

    print("No cycle")

