def is_prime(n):
    """
    Determine if a number is a prime.

    :param n: An integer number to check.
    :return: True if n is a prime number, False otherwise.
    """
    if n <= 1:
        return False

    if n == 2:
        return True

    if n % 2 == 0:
        return False

    for i in range(3, int(n ** 0.5) + 1, 2):
        if n % i == 0:
            return False

    return True

def classify_number(n):
    """
    Classify a number as prime, composite or neither.

    :param n: An integer number to classify.
    :return: "prime number", "composite number" or "neither"
    """
    if n <= 1:
        return "neither"

    if is_prime(n):
        return "prime number"
    else:
        return "composite number"

