def max_square_subgrid_sum(grid):
    """
    Returns the maximum sum of integers in the largest square sub-grid within the given grid.
    """
    n = len(grid)

    # Helper function to get sum of sub-grid from (i, j) with size k
    def subgrid_sum(i, j, k):
        return sum(grid[x][y] for x in range(i, i + k) for y in range(j, j + k))

    max_sum = 0

    for k in range(1, n + 1):  # size of the sub-grid
        for i in range(n - k + 1):
            for j in range(n - k + 1):
                current_sum = subgrid_sum(i, j, k)
                if current_sum > max_sum:
                    max_sum = current_sum

    return max_sum

def maximizePoints(k, points):
    """
    Returns the maximum total points an employee can earn by participating in up to k exercises.
    """
    if k >= len(points):
        return sum(points)
    points.sort(reverse=True)
    return sum(points[:k])

