from collections import deque

def calculate_distances(n, edges, queries):
    # Build the graph from edges
    graph = {i: [] for i in range(1, n+1)}
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    # Find distances using BFS from any node, we choose 1 to start with
    def bfs(start):
        distances = {i: -1 for i in range(1, n+1)}
        distances[start] = 0
        q = deque([start])
        while q:
            node = q.popleft()
            for neighbor in graph[node]:
                if distances[neighbor] == -1:
                    distances[neighbor] = distances[node] + 1
                    q.append(neighbor)
        return distances

    # We find distances of all nodes from the root node (chosen arbitrarily as node 1)
    root_distances = bfs(1)

    # We precompute the distances for all other nodes to reuse in queries
    all_distances = {i: bfs(i) for i in range(1, n+1)}

    # Process each query
    results = []
    for u, v in queries:
        results.append(all_distances[u][v])

    return results

def evaluateExpression(expression):
    """
    Evaluates the given arithmetic expression and returns the result as an integer.
    The expression can contain single-digit integers and the operators +, -, *, and /
    and follows standard operator precedence.
    """
    stack = []
    current_number = 0
    operation = '+'

    for i, char in enumerate(expression):
        if char.isdigit():
            current_number = current_number * 10 + int(char)

        if char in "+-*/" or i == len(expression) - 1:
            if operation == '+':
                stack.append(current_number)
            elif operation == '-':
                stack.append(-current_number)
            elif operation == '*':
                stack.append(stack.pop() * current_number)
            elif operation == '/':
                stack.append(int(stack.pop() / current_number))  # using int() for integer division truncation

            operation = char
            current_number = 0

    return sum(stack)

