def dice_game(T, rolls):
    """
    Calculate final scores of Jane and John after T turns and determine the winner.

    Args:
    T : int : number of turns
    rolls : list of tuples : contains T tuples of 4 integers each (j1, j2, h1, h2)

    Returns:
    str : final scores of Jane and John, and the result ("Jane wins", "John wins", or "Draw")
    """
    jane_score = 0
    john_score = 0

    for roll in rolls:
        j1, j2, h1, h2 = roll

        # Calculate Jane's score for the turn
        if j1 == j2:
            jane_score += j1 + j2 + 2 * j1
        else:
            jane_score += j1 + j2

        # Calculate John's score for the turn
        if h1 == h2:
            john_score += h1 + h2 + 2 * h1
        else:
            john_score += h1 + h2

    if jane_score > john_score:
        result = f"Jane: {jane_score} John: {john_score} Jane wins"
    elif john_score > jane_score:
        result = f"Jane: {jane_score} John: {john_score} John wins"
    else:
        result = f"Jane: {jane_score} John: {john_score} Draw"

    return result

def most_frequent_lake(trip_data):
    """
    Analyzes trip data to find the lake with the highest number of trips and the respective number of trips.
    If multiple lakes have the highest number of trips, returns the lexicographically first one.

    Parameters:
    trip_data (list of lists): Each element is a list containing the trip information for one query.

    Returns:
    list of tuples: Each tuple contains the name of the lake and the number of trips.
    """
    results = []
    for trips in trip_data:
        lake_count = {}
        for lake in trips:
            if lake in lake_count:
                lake_count[lake] += 1
            else:
                lake_count[lake] = 1

        max_trips = 0
        frequent_lake = ""
        for lake, count in lake_count.items():
            if count > max_trips or (count == max_trips and lake < frequent_lake):
                max_trips = count
                frequent_lake = lake

        results.append((frequent_lake, max_trips))

    return results

