def minimal_max_coordinates(n, plates):
    max_width = 0
    max_height = 0

    for height, width in plates:
        max_width = max(max_width, max(width, height))
        max_height = max(max_height, min(width, height))

    return max_width, max_height

def store_plates(n, plate_dimensions):
    max_w = 0
    max_h = 0

    for h, w in plate_dimensions:
        if h > w:
            h, w = w, h

        max_w = max(max_w, w)
        max_h = max(max_h, h)

    return max_w, max_h

