def can_form_team(N, K, preferences):
    from itertools import combinations

    def is_valid_team(team, preferences):
        for member in team:
            for other_member in team:
                if member != other_member and other_member + 1 not in preferences[member]:
                    return False
        return True

    if K > N:
        return "NO"

    for team in combinations(range(N), K):
        if is_valid_team(team, preferences):
            return "YES"

    return "NO"

