def search_nested_object(obj, key):
    """
    Recursively searches for a key in a nested object and returns its value if found, else returns None.
    """
    if key in obj:
        return obj[key]

    for k, v in obj.items():
        if isinstance(v, dict):
            found = search_nested_object(v, key)
            if found:
                return found

    return None

