def isBalanced(s: str) -> bool:
    """
    Determines whether a given string of parentheses is balanced or not.
    Supports three types of parentheses: '()', '{}' and '[]'.
    """
    stack = []
    matching = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in matching.values():
            stack.append(char)
        elif char in matching.keys():
            if stack == [] or stack.pop() != matching[char]:
                return False
        else:
            # This part is redundant as per conditions, s should only contains '(){}[]'
            return False

    return stack == []

# Example usage
# print(isBalanced("()")) # True
# print(isBalanced("{(})")) # False
# print(isBalanced("[()]{}{[()()]()}")) # True

