def max_bridges(n, A, B):
    bridges = sorted(zip(A, B))
    LIS = []

    for bridge in bridges:
        pos = binary_search(LIS, bridge[1])
        if pos == len(LIS):
            LIS.append(bridge[1])
        else:
            LIS[pos] = bridge[1]

    return len(LIS)

def binary_search(LIS, value):
    low, high = 0, len(LIS) - 1
    while low <= high:
        mid = (low + high) // 2
        if LIS[mid] < value:
            low = mid + 1
        else:
            high = mid - 1
    return low

