def categorize_students(N, scores):
    """
    Categorizes student scores into 'Excellent', 'Good', and 'Needs Improvement'.

    Parameters:
    N (int): The number of students.
    scores (list of int): The list of scores of the students.

    Returns:
    tuple: A tuple containing counts of 'Excellent', 'Good', and 'Needs Improvement'.
    """
    excellent_count = 0
    good_count = 0
    needs_improvement_count = 0

    for score in scores:
        if score >= 85:
            excellent_count += 1
        elif 60 <= score < 85:
            good_count += 1
        else:
            needs_improvement_count += 1

    return (excellent_count, good_count, needs_improvement_count)

