def reverse_alternating(s):
    """
    This function takes a single string as input and returns a new string with alternating words reversed,
    starting from the second word.
    """
    words = s.split()
    for i in range(1, len(words), 2):
        words[i] = words[i][::-1]
    return " ".join(words)

