def longest_unique_subarray_in_range(arr, l, r):
    """
    Returns the length of the longest contiguous subarray within the range [l, r]
    that does not contain any repeated elements.
    """
    n = len(arr)
    left, right = 0, 0
    max_len = 0
    seen = {}

    while right < n:
        if l <= arr[right] <= r:
            if arr[right] in seen and seen[arr[right]] >= left:
                left = seen[arr[right]] + 1
            seen[arr[right]] = right
            max_len = max(max_len, right - left + 1)
        else:
            left = right + 1
            seen = {}
        right += 1
    return max_len

def max_non_overlapping_tasks(datasets):
    results = []
    for tasks in datasets:
        tasks.sort(key=lambda x: x[1])
        count = 0
        end_time = 0
        for start, end in tasks:
            if start >= end_time:
                count += 1
                end_time = end
        results.append(count)
    return results

def uniquePaths(m, n, grid):
    if grid[0][0] == '1' or grid[m-1][n-1] == '1':
        return 0

    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

