def find_missing_number(sequence):
    """
    Takes a list of integers representing an arithmetic sequence with one missing term.
    Returns the missing number or "invalid input" if input is invalid.
    """
    # Validate input
    if not all(isinstance(x, int) for x in sequence) or len(sequence) < 3:
        return "invalid input"

    # Calculate the common difference
    n = len(sequence)
    total_diff = (sequence[-1] - sequence[0]) // n
    current_diff = (sequence[1] - sequence[0])

    if total_diff != current_diff:
        missing_num = sequence[0] + total_diff
    else:
        for i in range(n-1):
            if sequence[i+1] - sequence[i] != current_diff:
                missing_num = sequence[i] + current_diff
                break
    return missing_num

