def max_discount(t, test_cases):
    results = []

    for i in range(t):
        n = test_cases[i][0]
        categories = test_cases[i][1]
        m = test_cases[i][2]
        coupons = test_cases[i][3]

        category_discounts = {}

        for coupon in coupons:
            category, discount = coupon
            if category in category_discounts:
                category_discounts[category] = max(category_discounts[category], discount)
            else:
                category_discounts[category] = discount

        total_discount = 0

        for category in categories:
            if category in category_discounts:
                total_discount += category_discounts[category]

        results.append(total_discount)

    return results

