def longest_subsequence_with_max_sum(T, test_cases):
    results = []
    for case in test_cases:
        N, K, dishes = case
        max_length = 0

        for start in range(N):
            current_sum = 0
            for end in range(start, N):
                current_sum += dishes[end]
                if current_sum > K:
                    break
                max_length = max(max_length, end - start + 1)

        results.append(max_length)
    return results

