def calculate_bmi(weight, height):
    """
    Calculates the BMI and returns the corresponding BMI category.

    :param weight: weight in kilograms
    :param height: height in meters
    :return: String indicating the BMI category
    """
    bmi = round(weight / (height ** 2), 2)

    if bmi < 18.5:
        return "Underweight"
    elif 18.5 <= bmi < 24.9:
        return "Normal weight"
    elif 24.9 <= bmi < 29.9:
        return "Overweight"
    else:
        return "Obesity"

def categorize_books(book_titles, statuses):
    """
    Categorizes books based on their status.

    Parameters:
    book_titles (list of str): List of book titles.
    statuses (list of str): List of statuses corresponding to each book title.

    Returns:
    dict: A dictionary with two keys, "Available" and "Checked Out", each containing
          a list of book titles that match the respective status.
    """

    if not book_titles or not statuses or len(book_titles) != len(statuses):
        return {}

    categorized_books = {"Available": [], "Checked Out": []}

    for title, status in zip(book_titles, statuses):
        if status in categorized_books:
            categorized_books[status].append(title)

    return categorized_books

