def top_student(students: List[Dict[str, Union[str, int]]]) -> Union[str, List[str]]:
    if not students:
        return []

    max_score = max(student['score'] for student in students)
    top_scorers = [student['name'] for student in students if student['score'] == max_score]

    if len(top_scorers) == 1:
        return top_scorers[0]
    else:
        return sorted(top_scorers)

