def max_coins_distribution(T, test_cases):
    results = []
    for t in range(T):
        N, K = test_cases[t][0]
        capacities = sorted(test_cases[t][1], reverse=True)

        total_distributed = 0
        for capacity in capacities:
            if total_distributed + capacity <= K:
                total_distributed += capacity
            else:
                total_distributed += min(K - total_distributed, capacity)

        results.append(total_distributed)
    return results

from typing import List, Dict, Union, Tuple

def calculate_letter_grades(students: List[Dict[str, Union[str, List[int]]]]) -> List[Tuple[str, str]]:
    def average_grade(grades: List[int]) -> float:
        return sum(grades) / len(grades)

    def letter_grade(average: float) -> str:
        if average >= 90:
            return 'A'
        elif average >= 80:
            return 'B'
        elif average >= 70:
            return 'C'
        elif average >= 60:
            return 'D'
        else:
            return 'F'

    result = []
    for student in students:
        avg = average_grade(student["grades"])
        grade = letter_grade(avg)
        result.append((student["name"], grade))

    return result

