def check_balanced_parentheses(paragraph):
    """
    Takes a paragraph and returns a list of boolean values indicating whether each sentence
    in the paragraph has balanced parentheses.
    """
    sentences = paragraph.split('.')
    result = []

    for sentence in sentences:
        sentence = sentence.strip()
        if not sentence:
            continue

        stack = []
        balanced = True

        for char in sentence:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if stack and stack[-1] == '(':
                    stack.pop()
                else:
                    balanced = False
                    break

        if stack:
            balanced = False

        result.append(balanced)

    return result

