from collections import deque

def bfs(n, m, grid, start):
    visited = [[False] * m for _ in range(n)]
    queue = deque([start])
    visited[start[0]][start[1]] = True

    while queue:
        x, y = queue.popleft()
        # Traverse in all 4 possible directions (up, down, left, right)
        for nx, ny in [(x-1,y), (x+1,y), (x,y-1), (x,y+1)]:
            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny))
    return visited

def min_knights_required(t, cases):
    results = []
    for i in range(t):
        n, m = cases[i][0]
        grid = cases[i][1]

        coverage = [[0] * m for _ in range(n)]
        knights = []

        for r in range(n):
            for c in range(m):
                if grid[r][c] == 'K':
                    knights.append((r, c))

        for kx, ky in knights:
            visited = bfs(n, m, grid, (kx, ky))
            for r in range(n):
                for c in range(m):
                    if visited[r][c]:
                        coverage[r][c] += 1

        empty_cells = [(r, c) for r in range(n) for c in range(m) if grid[r][c] == '.']

        # Check if all empty cells are covered
        covered_counts = [coverage[r][c] for r, c in empty_cells]

        if all(count > 0 for count in covered_counts):
            results.append(len(knights))
        else:
            results.append(-1)

    return results

