def longest_route(n, edges):
    from collections import defaultdict

    # Build graph
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    def dfs(city, visited):
        visited.add(city)
        max_distance = 0

        for neighbor, weight in graph[city]:
            if neighbor not in visited:
                trip_distance = weight + dfs(neighbor, visited)
                max_distance = max(max_distance, trip_distance)

        visited.remove(city)
        return max_distance

    longest_distance = 0

    for city in range(n):
        longest_distance = max(longest_distance, dfs(city, set()))

    return longest_distance

