def water_stations(d, n):
    """
    Given the total distance of the race d and the number of desired water stations n,
    this function calculates and returns the positions of the water stations as a list.
    """
    if n >= d:
        return list(range(1, min(d, n) + 1))

    interval = d // n
    positions = [interval * i for i in range(1, n + 1)]

    return positions

