from typing import List

def longest_bitonic_subsequence(arr: List[int]) -> int:
    n = len(arr)

    if n == 0:
        return 0

    # Initialize increasing and decreasing subsequence lists
    inc = [1] * n
    dec = [1] * n

    # Compute lengths of increasing subsequences
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j]:
                inc[i] = max(inc[i], inc[j] + 1)

    # Compute lengths of decreasing subsequences
    for i in range(n-2, -1, -1):
        for j in range(n-1, i, -1):
            if arr[i] > arr[j]:
                dec[i] = max(dec[i], dec[j] + 1)

    # Find the maximum of the sum of inc[i] and dec[i] - 1
    max_length = 0
    for i in range(n):
        max_length = max(max_length, inc[i] + dec[i] - 1)

    return max_length

