def daily_temperatures(T):
    """
    Calculates the number of days you would have to wait until a warmer temperature for each day.
    """
    answer = [0] * len(T)
    stack = []

    for i in range(len(T) - 1, -1, -1):
        while stack and T[i] >= T[stack[-1]]:
            stack.pop()
        if stack:
            answer[i] = stack[-1] - i
        stack.append(i)

    return answer

