import math

def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def primes_in_range(a, b):
    """
    Returns a list of all prime numbers in the range [a, b] (both inclusive).
    """
    return [x for x in range(a, b + 1) if is_prime(x)]

def find_primes_in_multiple_ranges(test_cases):
    """
    Accepts list of tuples where each tuple contains two integers a and b
    Returns a list of lists where each list contains the prime numbers in the range [a, b]
    for each tuple (a, b) in the input list.
    """
    results = []
    for a, b in test_cases:
        results.append(primes_in_range(a, b))
    return results

