from collections import deque

def min_moves_to_reach_end(grid):
    n = len(grid)
    m = len(grid[0])
    directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == '.'

    queue = deque([(0, 0, 0)])  # (x, y, distance)
    visited = set([(0, 0)])

    while queue:
        x, y, dist = queue.popleft()

        if x == n - 1 and y == m - 1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny, dist + 1))

    return -1

def parse_input(input_str):
    input_lines = input_str.strip().split('\n')
    n, m = map(int, input_lines[0].split())
    grid = [list(line) for line in input_lines[1:n+1]]
    return grid

def escape_grid(input_str):
    grid = parse_input(input_str)
    return min_moves_to_reach_end(grid)

