        if book_id not in borrowed_books:
            if genre not in genre_count:
                genre_count[genre] = 0
            borrowed_books[book_id] = genre
            genre_count[genre] += 1

    def return_book(book_id, genre):
        if book_id in borrowed_books:
            borrowed_genre = borrowed_books.pop(book_id)
            genre_count[borrowed_genre] -= 1
            if genre_count[borrowed_genre] == 0:
                del genre_count[borrowed_genre]

    def query():
        if not genre_count:
            return "EMPTY"
        result = [f"{genre}:{count}" for genre, count in sorted(genre_count.items())]
        return "\n".join(result)

    result = []
    for operation in operations:
        parts = operation.split()
        if parts[0] == "BORROW":
            _, book_id, genre = parts
            borrow(book_id, genre)
        elif parts[0] == "RETURN":
            _, book_id, genre = parts
            return_book(book_id, genre)
        elif parts[0] == "QUERY":
            result.append(query())
        elif parts[0] == "STOP":
            break

    return result

def generate_triangle_patterns(test_cases):
    results = []

    for N in test_cases:
        pattern = []
        for i in range(N, 0, -1):
            row = ' '.join(map(str, range(1, i+1)))
            pattern.append(row)
        results.append('\n'.join(pattern))

    return results

