import heapq
import sys

def shortest_path(N, M, edges):
    graph = [[] for _ in range(N+1)]
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    dist = [float('inf')] * (N + 1)
    dist[1] = 0
    pq = [(0, 1)]  # (distance, node)
    visited = set()

    while pq:
        d, node = heapq.heappop(pq)
        if node in visited:
            continue
        visited.add(node)

        for neighbor, weight in graph[node]:
            if dist[neighbor] > d + weight:
                dist[neighbor] = d + weight
                heapq.heappush(pq, (dist[neighbor], neighbor))

    result = []
    for i in range(2, N + 1):
        if dist[i] == float('inf'):
            result.append(-1)
        else:
            result.append(dist[i])

    return result

def valid_palindrome(s):
    """
    Returns true if the string s can be made into a palindrome by deleting at most one character.
    """

    def is_palindrome_range(i, j):
        return all(s[k] == s[j - k + i] for k in range(i, j))

    left, right = 0, len(s) - 1
    while left < right:
        if s[left] != s[right]:
            # If there's a mismatch, check the two possible strings (one with either character removed)
            return is_palindrome_range(left + 1, right) or is_palindrome_range(left, right - 1)
        left += 1
        right -= 1
    return True

