def minimum_point_difference(M, points):
    total_points = sum(points)
    half_points = total_points // 2
    dp = [0] * (half_points + 1)

    for point in points:
        for j in range(half_points, point - 1, -1):
            dp[j] = max(dp[j], dp[j - point] + point)

    best_distribution = dp[half_points]
    other_distribution = total_points - best_distribution
    return abs(best_distribution - other_distribution)

# Example function to call the above method with appropriate input
def min_difference(M, points):
    return minimum_point_difference(M, points)

