def find_duplicates(names):
    """
    Given a list of names, this function returns the names that appear
    more than once, each on a new line, in the order they first appear.
    If there are no duplicates, it returns "No duplicates".
    """
    name_count = {}
    duplicates = []

    for name in names:
        if name in name_count:
            name_count[name] += 1
        else:
            name_count[name] = 1

    for name in names:
        if name_count[name] > 1 and name not in duplicates:
            duplicates.append(name)

    if duplicates:
        return '\n'.join(duplicates)
    else:
        return "No duplicates"


