def count_distinct_substrings(s):
    """
    Returns the number of distinct substrings of the string s.
    """
    n = len(s)

    # Using a set to keep track of all unique substrings
    substrings = set()

    # Generating all possible substrings
    for i in range(n):
        for j in range(i + 1, n + 1):
            substrings.add(s[i:j])

    return len(substrings)

