def first_missing_positive(nums):
    """
    Given an array of integers, return the smallest missing positive integer.
    """
    n = len(nums)

    # First pass: Place each number in its right place
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            # Swap nums[i] with the number at its correct position
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    # Second pass: Find the first index whose value is incorrect
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    # If all values are correct, return the next number
    return n + 1

