def find_max_availability(n, schedules):
    availability = [[0] * 24 for _ in range(7)]

    for schedule in schedules:
        i = 0
        while i < len(schedule):
            day, start, end = schedule[i], schedule[i + 1], schedule[i + 2]
            for hour in range(start, end):
                availability[day][hour] += 1
            i += 3

    max_available = 0
    best_day = 0
    best_hour = 0

    for day in range(7):
        for hour in range(24):
            if availability[day][hour] > max_available:
                max_available = availability[day][hour]
                best_day = day
                best_hour = hour

    return best_day, best_hour

