def find_peak_element(nums):
    """
    Returns the index of the first peak element in the array of integers.
    A peak element is an element that is strictly greater than its neighbors.

    :param nums: List[int]
    :return: int
    """
    if not nums:
        return -1

    n = len(nums)
    if n == 1:
        return 0

    for i in range(n):
        if i == 0:
            if nums[i] > nums[i + 1]:
                return i
        elif i == n - 1:
            if nums[i] > nums[i - 1]:
                return i
        else:
            if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
                return i
    return -1

