def min_rotations_to_unlock(n, initial_combination, target_combination):
    """
    Returns the minimum number of rotations needed to unlock the device.
    """
    def min_single_wheel_rotations(start, end):
        """Helper function to calculate minimum rotations for a single wheel."""
        return min(abs(start - end), 10 - abs(start - end))

    rotations = 0
    for i in range(n):
        start_digit = int(initial_combination[i])
        target_digit = int(target_combination[i])

        rotations += min_single_wheel_rotations(start_digit, target_digit)

    return rotations

