def handle_operations(N, K, A, operations):
    results = []

    for operation in operations:
        op_type = operation[0]

        if op_type == 'E':
            X, Y = operation[1], operation[2]
            A[X - 1] = Y
        elif op_type == 'S':
            L, R = operation[1], operation[2]
            sum_even = sum(x for x in A[L-1:R] if x % 2 == 0)
            results.append(sum_even)

    return results

