def canPartitionKSubsets(nums, k):
    def can_partition(start, k, subset_sum, target, used):
        if k == 0:
            return True
        if subset_sum == target:
            return can_partition(0, k - 1, 0, target, used)
        for i in range(start, len(nums)):
            if not used[i] and subset_sum + nums[i] <= target:
                used[i] = True
                if can_partition(i + 1, k, subset_sum + nums[i], target, used):
                    return True
                used[i] = False
        return False

    total_sum = sum(nums)
    if total_sum % k != 0:
        return False
    target = total_sum // k
    nums.sort(reverse=True)
    used = [False] * len(nums)
    return can_partition(0, k, 0, target, used)

