def is_prime(n):
    """
    Returns "Prime" if n is a prime number, otherwise returns "Not Prime".
    """
    if n < 2:
        return "Not Prime"
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return "Not Prime"
    return "Prime"

def max_sum_submatrix(matrix, n, k):
    """
    Returns the maximum sum of elements of a k x k sub-matrix in an n x n matrix.
    """
    # Initialize the maximum sum variable
    max_sum = float('-inf')

    # Compute prefix sum matrix
    prefix_sum = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n):
        for j in range(n):
            prefix_sum[i+1][j+1] = matrix[i][j] + prefix_sum[i][j+1] + prefix_sum[i+1][j] - prefix_sum[i][j]

    # Iterate through possible k x k sub-matrices
    for i in range(k, n + 1):
        for j in range(k, n + 1):
            current_sum = prefix_sum[i][j] - prefix_sum[i-k][j] - prefix_sum[i][j-k] + prefix_sum[i-k][j-k]
            if current_sum > max_sum:
                max_sum = current_sum

    return max_sum

from functools import cmp_to_key

def largest_formed_number(nums):
    def compare(a, b):
        return (int(b + a) - int(a + b))

    nums_str = list(map(str, nums))
    nums_str.sort(key=cmp_to_key(compare))

    res = ''.join(nums_str)

    return res.lstrip('0') or '0'

