def longestWord(S, dict):
    def is_subsequence(x, y):
        # Check if x is subsequence of y
        it = iter(y)
        return all(c in it for c in x)

    # Sort dictionary primarily by length in descending order and secondarily by lexicographical order
    dict.sort(key=lambda x: (-len(x), x))

    for word in dict:
        if is_subsequence(word, S):
            return word
    return ""

import heapq
import sys

def dijkstra(graph, start, n):
    dist = [sys.maxsize] * (n + 1)
    dist[start] = 0
    priority_queue = [(0, start)]

    while priority_queue:
        current_dist, current_node = heapq.heappop(priority_queue)

        if current_dist > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_dist + weight
            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return dist

def shortest_paths(n, m, edges, q, queries):
    graph = [[] for _ in range(n + 1)]

    for u, v, w in edges:
        graph[u].append((v, w))

    results = []
    for a, b in queries:
        dist = dijkstra(graph, a, n)
        result = dist[b] if dist[b] != sys.maxsize else -1
        results.append(result)

    return results

