def number_of_paths(n):
    """
    Returns the number of distinct paths in an n x n grid from the top-left corner to the bottom-right corner
    where only movements to the right and down are allowed.
    """
    # The number of ways to reach a cell (i, j) is the sum of ways to reach (i-1, j) and (i, j-1)
    # This is analogous to pascal's triangle, where each cell is the binomial coefficient C(i+j, j)
    grid = [[0] * n for _ in range(n)]

    for i in range(n):
        grid[i][0] = 1
    for j in range(n):
        grid[0][j] = 1

    for i in range(1, n):
        for j in range(1, n):
            grid[i][j] = grid[i-1][j] + grid[i][j-1]

    return grid[n-1][n-1]

