def process_queries(queries):
    """
    Processes the given list of queries and returns the results for "Cr" type queries.

    Args:
        queries (list): A list of query strings.

    Returns:
        list: A list containing the results of "Cr" type queries.
    """
    grid = {}
    result = []

    for query in queries:
        parts = query.split()
        if parts[0] == 'Ia':
            x, y, c = int(parts[1]), int(parts[2]), parts[3]
            if (x, y) not in grid:
                grid[(x, y)] = c
        elif parts[0] == 'Cr':
            x1, y1, x2, y2 = int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
            count = 0
            for x in range(x1, x2 + 1):
                for y in range(y1, y2 + 1):
                    if (x, y) in grid:
                        grid[(x, y)] = 'R'
                        count += 1
            result.append(count)

    return result

from typing import List

def longest_zigzag(nums: List[int]) -> int:
    if not nums:
        return 0

    n = len(nums)
    if n == 1:
        return 1

    up = [1] * n
    down = [1] * n

    for i in range(1, n):
        if nums[i] > nums[i-1]:
            up[i] = down[i-1] + 1
            down[i] = down[i-1]
        elif nums[i] < nums[i-1]:
            down[i] = up[i-1] + 1
            up[i] = up[i-1]
        else:
            down[i] = down[i-1]
            up[i] = up[i-1]

    return max(up[-1], down[-1])

