def is_magic_matrix(matrix, n, m):
    elements_set = set()
    for row in matrix:
        if len(set(row)) != m:  # Check for distinct elements in the row
            return False
        elements_set.update(row)

    if len(elements_set) != n * m:  # Check if all elements are unique in the matrix
        return False

    for col in range(m):
        col_set = set()
        for row in matrix:
            col_set.add(row[col])
        if len(col_set) != n:  # Check for distinct elements in the column
            return False

    return True

def evaluate_matrices(test_cases):
    results = []
    for n, m, matrix in test_cases:
        if is_magic_matrix(matrix, n, m):
            results.append("YES")
        else:
            results.append("NO")
    return results

