def has_majority_element(arr):
    """
    Checks if there is an integer in the array such that the number of its occurrences is
    greater than or equal to half of the length of the array.

    :param arr: List of integers
    :return: "YES" if such an integer exists, otherwise "NO"
    """
    n = len(arr)
    count_dict = {}

    # Count occurrences of each element
    for num in arr:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Check if any element has occurrences greater than or equal to half the array length
    for count in count_dict.values():
        if count >= n / 2:
            return "YES"

    return "NO"

