def can_reach_destination(N, M, grid):
    from collections import deque

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < M and grid[x][y] == 'O'

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(0, 0)])
    visited = set()
    visited.add((0, 0))

    while queue:
        x, y = queue.popleft()
        if (x, y) == (N-1, M-1):
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return "NO"

