def can_construct(S, T):
    """
    Determine if S can be constructed by repeatedly removing any one-character substring of T.
    """
    # Pointers for S and T
    s_ptr, t_ptr = 0, 0

    while s_ptr < len(S) and t_ptr < len(T):
        if S[s_ptr] == T[t_ptr]:
            s_ptr += 1
        t_ptr += 1

    return s_ptr == len(S)

