def count_local_maximums(grid):
    rows = len(grid)
    cols = len(grid[0])
    count = 0

    for i in range(rows):
        for j in range(cols):
            is_local_max = True

            if i > 0 and grid[i][j] <= grid[i-1][j]:
                is_local_max = False
            if i < rows - 1 and grid[i][j] <= grid[i+1][j]:
                is_local_max = False
            if j > 0 and grid[i][j] <= grid[i][j-1]:
                is_local_max = False
            if j < cols - 1 and grid[i][j] <= grid[i][j+1]:
                is_local_max = False

            if is_local_max:
                count += 1

    return count

