def shiftAlphabet(S):
    """
    Given a string, replace each character by the next character in the English alphabet.
    Replace 'z' by 'a' and 'Z' by 'A'. Non-alphabet characters should remain unchanged.
    """
    result = []
    for ch in S:
        if 'a' <= ch <= 'z':
            if ch == 'z':
                result.append('a')
            else:
                result.append(chr(ord(ch) + 1))
        elif 'A' <= ch <= 'Z':
            if ch == 'Z':
                result.append('A')
            else:
                result.append(chr(ord(ch) + 1))
        else:
            result.append(ch)
    return ''.join(result)

