def min_operations_to_transform(t, test_cases):
    results = []

    for i in range(t):
        n, A, B = test_cases[i]
        move_count = 0

        B_index_map = {b: i for i, b in enumerate(B)}

        last_index = -1
        for a in A:
            if B_index_map[a] > last_index:
                last_index = B_index_map[a]
            else:
                move_count += 1

        results.append(move_count)

    return results

