def perform_operations(R, C, Q, operations):
    # Initialize the grid with zeros
    grid = [[0] * C for _ in range(R)]

    # Apply each operation
    for r1, c1, r2, c2, V in operations:
        for r in range(r1-1, r2):
            for c in range(c1-1, c2):
                grid[r][c] += V

    return grid

