def alternating_squares(n):
    """
    Generates an n x n grid where Sasha and Masha alternately place '1' and '2' starting from the top left corner.
    """
    grid = [[0] * n for _ in range(n)]

    for i in range(n):
        for j in range(n):
            if (i + j) % 2 == 0:
                grid[i][j] = 1
            else:
                grid[i][j] = 2

    return grid

import math

def min_distance_point(points1, points2):
    """
    Calculate the minimum Euclidean distance between any two points,
    one from points1 and one from points2.

    :param points1: List of points [x, y]
    :param points2: List of points [x, y]
    :return: Minimum Euclidean distance rounded to 5 decimal places
    """
    min_dist = float('inf')
    for p1 in points1:
        for p2 in points2:
            dist = math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)
            if dist < min_dist:
                min_dist = dist
    return round(min_dist, 5)

