def garden_operations(n, m, queries):
    garden = [[False] * m for _ in range(n)]
    results = []

    for query in queries:
        operation = query[0]
        i = query[1] - 1  # Convert 1-based index to 0-based index
        j = query[2] - 1  # Convert 1-based index to 0-based index

        if operation == 1:
            garden[i][j] = True
        elif operation == 2:
            garden[i][j] = False
        elif operation == 3:
            if garden[i][j]:
                results.append("Yes")
            else:
                results.append("No")

    return results

