def is_valid_brackets(s):
    """
    Determine if the input string of brackets is valid.
    """
    stack = []
    mapping = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in mapping:
            top_element = stack.pop() if stack else '#'

            if mapping[char] != top_element:
                return False
        else:
            stack.append(char)

    return not stack

