def num_islands(grid):
    """
    Returns the number of distinct islands in the grid.
    """
    if not grid or not grid[0]:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False] * n for _ in range(m)]

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or visited[i][j] or grid[i][j] == '0':
            return
        visited[i][j] = True
        # Explore all 4 possible directions
        dfs(i + 1, j)
        dfs(i - 1, j)
        dfs(i, j + 1)
        dfs(i, j - 1)

    island_count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1' and not visited[i][j]:
                dfs(i, j)
                island_count += 1

    return island_count

# Helper function to build the grid from input values
def build_grid(input_lines):
    rows = input_lines.strip().split('\n')
    grid = [list(row.strip()) for row in rows[1:]]
    return grid

# Main function to handle the input and output
def main(input_lines):
    grid = build_grid(input_lines)
    return num_islands(grid)

