from collections import Counter
from math import gcd
from functools import reduce

def prime_factors(n):
    """Returns a Counter (hashmap) of prime factors of n with their powers."""
    i = 2
    factors = Counter()
    while i * i <= n:
        while (n % i) == 0:
            factors[i] += 1
            n //= i
        i += 1
    if n > 1:
        factors[n] += 1
    return factors

def min_operations_to_perfect_square(n, integers):
    combined_factors = Counter()

    for number in integers:
        factors = prime_factors(number)
        combined_factors.update(factors)

    # Calculate the number of operations needed
    operations = 0
    for factor, count in combined_factors.items():
        if count % 2 != 0:
            operations += 1  # Need one operation to make this factor's power even

    return operations

def solve(test_cases):
    results = []
    for n, integers in test_cases:
        results.append(min_operations_to_perfect_square(n, integers))
    return results

