def reverse_words(s):
    """
    Reverses the words in the given input string s. Leading or trailing spaces
    and multiple spaces between words are reduced to a single space separating words.
    """
    def trim_spaces(s):
        n = len(s)
        left, right = 0, n - 1
        # remove leading spaces
        while left <= right and s[left] == ' ':
            left += 1
        # remove trailing spaces
        while left <= right and s[right] == ' ':
            right -= 1
        # reduce multiple spaces to single space
        output = []
        while left <= right:
            if s[left] != ' ':
                output.append(s[left])
            elif output[-1] != ' ':
                output.append(s[left])
            left += 1
        return ''.join(output)

    def reverse(l, left, right):
        while left < right:
            l[left], l[right] = l[right], l[left]
            left, right = left + 1, right - 1

    # Convert string to list of characters for in-place manipulation
    l = list(trim_spaces(s))
    n = len(l)

    # Step 1: Reverse the entire string
    reverse(l, 0, n - 1)

    # Step 2: Reverse each word in the reversed string
    start = 0
    for i in range(n + 1):
        if i == n or l[i] == ' ':
            reverse(l, start, i - 1)
            start = i + 1

    return ''.join(l)

