import sys
from collections import defaultdict, deque

def rank_players(n, m, matches):
    incoming_edges = {i: 0 for i in range(1, n + 1)}
    adj_list = defaultdict(list)

    for winner, loser in matches:
        adj_list[winner].append(loser)
        incoming_edges[loser] += 1

    zero_indegree = deque([node for node in incoming_edges if incoming_edges[node] == 0])

    ranking = []
    while zero_indegree:
        current = zero_indegree.popleft()
        ranking.append(current)

        for neighbor in adj_list[current]:
            incoming_edges[neighbor] -= 1
            if incoming_edges[neighbor] == 0:
                zero_indegree.append(neighbor)

    if len(ranking) == n:
        return ranking
    else:
        return []

# Example function to handle input
def main():
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    m = int(data[1])
    matches = [(int(data[i]), int(data[i+1])) for i in range(2, len(data), 2)]

    ranking = rank_players(n, m, matches)
    if ranking:
        print(" ".join(map(str, ranking)))
    else:
        print("IMPOSSIBLE")

