from collections import deque

def shortestPath(N, M, grid):
    if grid[0][0] == 'X' or grid[N-1][M-1] == 'X':
        return -1

    # Directions to move in the grid
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    # Queue for BFS
    queue = deque([(0, 0, 0)])  # (x, y, distance)
    visited = set()
    visited.add((0, 0))

    while queue:
        x, y, dist = queue.popleft()

        if x == N-1 and y == M-1:
            return dist

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < M and (nx, ny) not in visited and grid[nx][ny] == 'O':
                queue.append((nx, ny, dist + 1))
                visited.add((nx, ny))

    return -1

def find_median_sorted_arrays(A, B):
    """
    This function calculates the median of the union of two sorted arrays A and B.
    """
    m, n = len(A), len(B)
    if m > n:
        A, B, m, n = B, A, n, m

    imin, imax, half_len = 0, m, (m + n + 1) // 2
    while imin <= imax:
        i = (imin + imax) // 2
        j = half_len - i
        if i < m and B[j-1] > A[i]:
            imin = i + 1
        elif i > 0 and A[i-1] > B[j]:
            imax = i - 1
        else:
            if i == 0: max_of_left = B[j-1]
            elif j == 0: max_of_left = A[i-1]
            else: max_of_left = max(A[i-1], B[j-1])

            if (m + n) % 2 == 1:
                return max_of_left

            if i == m: min_of_right = B[j]
            elif j == n: min_of_right = A[i]
            else: min_of_right = min(A[i], B[j])

            return (max_of_left + min_of_right) / 2.0

