def max_in_grid(n, m, k, operations):
    grid = [[0] * m for _ in range(n)]

    for a, b, c, d in operations:
        for i in range(a-1, c):
            for j in range(b-1, d):
                grid[i][j] += 1

    max_value = 0
    max_count = 0

    for row in grid:
        for val in row:
            if val > max_value:
                max_value = val
                max_count = 1
            elif val == max_value:
                max_count += 1

    return max_value, max_count

def edit_distance(s1, s2):
    """
    Calculate the edit distance (Levenshtein distance) between two strings using dynamic programming.

    :param s1: First string
    :param s2: Second string
    :return: Integer representing the edit distance
    """
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0:
                dp[i][j] = j  # If s1 is empty, insert all characters of s2
            elif j == 0:
                dp[i][j] = i  # If s2 is empty, remove all characters of s1
            elif s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = 1 + min(dp[i-1][j],      # Remove
                                   dp[i][j-1],      # Insert
                                   dp[i-1][j-1])    # Replace

    return dp[m][n]

def find_smallest_missing(nums):
    """
    Given an array consisting of positive integers, determine the smallest positive integer
    that is not present in the array.
    The time complexity of the solution is linear, and the extra space complexity is constant.
    """

    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

