def count_distinct_islands(grid):
    """
    Returns the number of distinct islands in the grid.
    """
    if not grid:
        return 0

    m, n = len(grid), len(grid[0])
    visited = [[False for _ in range(n)] for _ in range(m)]

    def dfs(x, y):
        if x < 0 or y < 0 or x >= m or y >= n or visited[x][y] or grid[x][y] == 0:
            return
        visited[x][y] = True
        dfs(x+1, y)
        dfs(x-1, y)
        dfs(x, y+1)
        dfs(x, y-1)

    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1

    return count

