def isValid(s: str) -> bool:
    stack = []
    bracket_pair = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_pair.values():
            stack.append(char)
        elif char in bracket_pair.keys():
            if not stack or stack.pop() != bracket_pair[char]:
                return False
        else:
            return False

    return not stack

