def categorize_numbers(test_cases):
    results = []

    for case in test_cases:
        n = case[0]
        numbers = case[1:]
        categorized = []

        i = 0
        while i < n:
            start = numbers[i]
            while i + 1 < n and numbers[i + 1] == numbers[i] + 1:
                i += 1
            end = numbers[i]
            if start == end:
                categorized.append(str(start))
            else:
                categorized.append(f"{start}-{end}")
            i += 1

        results.append(", ".join(categorized))

    return results

