def countNumbers(S):
    """
    Return the count of all the numbers present in the string S.
    Numbers are contiguous sequences of digits.
    """
    count = 0
    in_number = False

    for char in S:
        if char.isdigit():
            if not in_number:
                count += 1
                in_number = True
        else:
            in_number = False

    return count

