def smallest_prime_divisor(n):
    """
    Returns the smallest prime divisor of n.
    If n is a prime number itself, the smallest prime divisor of n is n.
    """
    if n <= 1:
        return None

    if n % 2 == 0:
        return 2

    i = 3
    while i * i <= n:
        if n % i == 0:
            return i
        i += 2

    return n

def process_test_cases(t, cases):
    results = []
    for n in cases:
        results.append(smallest_prime_divisor(n))
    return results

