def largest_single_type_square(grid, R, C):
    def is_valid_square(x, y, length, plant_type):
        if x + length > R or y + length > C:
            return False
        for i in range(x, x + length):
            for j in range(y, y + length):
                if grid[i][j] != plant_type:
                    return False
        return True

    max_length = 0
    for i in range(R):
        for j in range(C):
            if grid[i][j] > 0:  # Only consider non-empty sites
                current_plant_type = grid[i][j]
                length = 1
                while is_valid_square(i, j, length, current_plant_type):
                    max_length = max(max_length, length)
                    length += 1
    return max_length

# Parsing input
def main(input_str):
    lines = input_str.strip().split('\n')
    R, C = map(int, lines[0].split())
    grid = [list(map(int, line.split())) for line in lines[1:]]
    return largest_single_type_square(grid, R, C)

