def validate_string_array(strings):
    """
    Validates the array of strings based on the given conditions.
    """
    if not strings:
        return "Invalid"

    # Check if all strings are the same length
    first_length = len(strings[0])
    if not all(len(s) == first_length for s in strings):
        return "Invalid"

    # Check if each string is in strictly increasing order
    for i in range(1, len(strings)):
        if int(strings[i]) <= int(strings[i-1]):
            return "Invalid"

    # Check if no string starts with zero unless it is '0'
    for s in strings:
        if s[0] == '0' and s != '0':
            return "Invalid"

    return "Valid"

