def handle_instructions(test_cases):
    results = []

    for instructions in test_cases:
        tree = {1: 0}  # root node with ID 1 has depth 0
        for instruction in instructions:
            parts = instruction.split()
            if parts[0] == "ADD":
                parent_id = int(parts[1])
                child_id = int(parts[2])
                tree[child_id] = tree[parent_id] + 1
            elif parts[0] == "QUERY":
                node_id = int(parts[1])
                results.append(tree[node_id])

    return results

