def lexicographically_smallest_non_increasing_array(arr, k):
    """
    Returns the lexicographically smallest array that can be obtained after exactly k swap operations.
    """
    n = len(arr)
    for i in range(n):
        for j in range(i + 1, n):
            # Swap the elements to potentially create a lexicographically smaller array
            arr[i], arr[j] = arr[j], arr[i]
            if k > 0:
                k -= 1
            if k == 0:
                return sorted(arr, reverse=True)
            arr[j], arr[i] = arr[i], arr[j]

    # If we have exhausted k swaps, sort the array in non-increasing order
    return sorted(arr, reverse=True)

