def increasing_triplet(nums):
    """
    Returns true if there exists a triplet (i, j, k) such that
    i < j < k and nums[i] < nums[j] < nums[k], otherwise false.
    """
    first = second = float('inf')

    for num in nums:
        if num <= first:
            first = num
        elif num <= second:
            second = num
        else:
            return True

    return False

