from collections import deque, defaultdict

def can_calibrate(n, E, dependencies):
    graph = defaultdict(list)
    in_degree = {i: 0 for i in range(1, n + 1)}
    energy_cost = {i: 0 for i in range(1, n + 1)}

    for a, b, e in dependencies:
        graph[a].append((b, e))
        in_degree[b] += 1
        energy_cost[a] += e

    zero_in_degree = deque([node for node in range(1, n + 1) if in_degree[node] == 0])
    calibrated_sequence = []
    total_energy = 0

    while zero_in_degree:
        node = zero_in_degree.popleft()
        calibrated_sequence.append(node)
        if total_energy + energy_cost[node] > E:
            return "NO"
        total_energy += energy_cost[node]

        for neighbor, energy in graph[node]:
            in_degree[neighbor] -= 1
            energy_cost[neighbor] -= energy
            if in_degree[neighbor] == 0:
                zero_in_degree.append(neighbor)

    if len(calibrated_sequence) == n:
        return "YES", calibrated_sequence
    else:
        return "NO"

