def most_borrowed_book(test_cases):
    results = []

    for case in test_cases:
        n, records = case
        book_count = {}

        for book in records:
            if book in book_count:
                book_count[book] += 1
            else:
                book_count[book] = 1

        # Determine the most borrowed book, considering lexicographical order in case of ties
        most_borrowed = min(book_count.items(), key=lambda x: (-x[1], x[0]))

        results.append(most_borrowed[0])

    return results

