def is_balanced(s):
    """
    Returns 'YES' if the brackets in the string are balanced and 'NO' otherwise.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return "NO"
        else:
            stack.append(char)

    return "YES" if not stack else "NO"

