def is_knights_tour_possible(N, start_x, start_y):
    def is_valid_move(x, y, N, visited):
        return 0 <= x < N and 0 <= y < N and not visited[x][y]

    def knights_tour(N, x, y, move_i, visited, x_move, y_move):
        if move_i == N * N:
            return True

        for i in range(8):
            next_x = x + x_move[i]
            next_y = y + y_move[i]
            if is_valid_move(next_x, next_y, N, visited):
                visited[next_x][next_y] = True
                if knights_tour(N, next_x, next_y, move_i + 1, visited, x_move, y_move):
                    return True
                visited[next_x][next_y] = False

        return False

    visited = [[False] * N for _ in range(N)]
    visited[start_x][start_y] = True

    x_move = [2, 1, -1, -2, -2, -1, 1, 2]
    y_move = [1, 2, 2, 1, -1, -2, -2, -1]

    if knights_tour(N, start_x, start_y, 1, visited, x_move, y_move):
        return "Yes"
    else:
        return "No"

def solve_knights_tour(test_cases):
    results = []
    for N, start_x, start_y in test_cases:
        results.append(is_knights_tour_possible(N, start_x, start_y))
    return results

