def find_added_character(s, t):
    """
    Returns the character that was added to t compared to s.
    """
    char_count = [0] * 26

    for char in s:
        char_count[ord(char) - ord('a')] -= 1

    for char in t:
        char_count[ord(char) - ord('a')] += 1

    for i in range(26):
        if char_count[i] > 0:
            return chr(i + ord('a'))

