def max_steal(n, A):
    if n == 0:
        return 0
    if n == 1:
        return A[0]
    if n == 2:
        return max(A[0], A[1])

    dp = [0] * n
    dp[0] = A[0]
    dp[1] = max(A[0], A[1])

    for i in range(2, n):
        dp[i] = max(dp[i-1], A[i] + dp[i-2])

    return dp[-1]

