def arrayTransformation(arr):
    """
    Transforms the input array based on the rules:
    - If the number is even, divide the number by 2.
    - If the number is odd and greater than 10, subtract 5 from the number.
    - If the number is odd and less than or equal to 10, add 3 to the number.
    """
    transformed_array = []
    for num in arr:
        if num % 2 == 0:
            transformed_array.append(num // 2)
        elif num > 10:
            transformed_array.append(num - 5)
        else:
            transformed_array.append(num + 3)
    return transformed_array

