from typing import List, Union

def reserve_seats(seating_plan: List[List[int]], num_seats: int, row: int) -> Union[str, List[List[int]]]:
    """
    Try to reserve `num_seats` consecutive seats in the requested `row` of the `seating_plan`.
    Return the updated seating plan if successful or a message indicating failure otherwise.
    """
    if row < 0 or row >= len(seating_plan):
        return 'Cannot reserve seats'

    consecutive = 0
    start_index = -1
    for i in range(len(seating_plan[row])):
        if seating_plan[row][i] == 0:
            if consecutive == 0:
                start_index = i
            consecutive += 1
            if consecutive == num_seats:
                for j in range(start_index, start_index + num_seats):
                    seating_plan[row][j] = 1
                return seating_plan
        else:
            consecutive = 0
            start_index = -1

    return 'Cannot reserve seats'

