def is_symmetric(matrix):
    """
    Determines if a given square matrix is symmetric.

    A square matrix is symmetric if it is equal to its transpose.

    :param matrix: A list of lists where each sublist represents a row of the matrix.
    :return: True if the matrix is symmetric, False otherwise.
    """
    n = len(matrix)

    for i in range(n):
        for j in range(i, n):
            if matrix[i][j] != matrix[j][i]:
                return False

    return True

def countPaths(grid):
    m, n = len(grid), len(grid[0])

    # If starting or ending cell is a wall, return 0
    if grid[0][0] == '#' or grid[m-1][n-1] == '#':
        return 0

    # Initialize a 2D dp array with zeroes
    dp = [[0] * n for _ in range(m)]
    dp[0][0] = 1  # Starting point

    # Fill the dp array
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[m-1][n-1]

def is_path_to_bottom_right(n, m, grid):
    """
    Determines if there is a path from the top-left to the bottom-right corner
    of the grid without hitting any asteroids.

    :param n: Number of rows in the grid
    :param m: Number of columns in the grid
    :param grid: n x m grid represented as a list of lists
    :return: "YES" if there is a path, otherwise "NO"
    """
    if n == 0 or m == 0:
        return "NO"

    # Initialize dp matrix with False
    dp = [[False] * m for _ in range(n)]
    dp[0][0] = True  # Starting point

    # Fill the dp matrix
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dp[i][j] = False
            else:
                if i > 0:
                    dp[i][j] = dp[i][j] or dp[i-1][j]
                if j > 0:
                    dp[i][j] = dp[i][j] or dp[i][j-1]

    return "YES" if dp[n-1][m-1] else "NO"

