def manage_fleet_operations(n, q, battery_levels, operations):
    def add_value_to_range(batteries, l, r, v):
        for i in range(l-1, r):
            batteries[i] = min(100, max(0, batteries[i] + v))

    def average_battery_in_range(batteries, l, r):
        total = sum(batteries[l-1:r])
        return total // (r - l + 1)

    results = []
    for op in operations:
        if op[0] == 1:
            _, l, r, v = op
            add_value_to_range(battery_levels, l, r, v)
        elif op[0] == 2:
            _, l, r = op
            avg = average_battery_in_range(battery_levels, l, r)
            results.append(avg)

    return results

