from bisect import bisect_left

def longest_increasing_subsequence_length(sequence):
    if not sequence:
        return 0

    # This will store the end elements of increasing subsequences
    subseq_end_elements = []

    for num in sequence:
        idx = bisect_left(subseq_end_elements, num)
        if idx == len(subseq_end_elements):
            subseq_end_elements.append(num)
        else:
            subseq_end_elements[idx] = num

    return len(subseq_end_elements)

