def determine_winner(P1, P2):
    """
    Determines the winner of the game given the initial number of stones in Alice's pile (P1)
    and Bob's pile (P2). Alice always goes first. The players play optimally.
    Returns "Alice" if Alice wins, and "Bob" if Bob wins.
    """
    if P1 >= P2:
        return "Alice"
    else:
        return "Bob"

def find_anagram_pairs(words):
    """
    Given a list of words, finds all pairs of different words that are anagrams of each other.

    Args:
    words (list of str): List of words.

    Returns:
    list of tuple: List of tuples containing pairs of anagrams.
    """
    def sorted_word(word):
        return ''.join(sorted(word.replace(' ', '').lower()))

    anagram_pairs = []
    checked_pairs = set()
    words_sorted = [(word, sorted_word(word)) for word in words]

    for i in range(len(words_sorted)):
        for j in range(i + 1, len(words_sorted)):
            word1, sorted1 = words_sorted[i]
            word2, sorted2 = words_sorted[j]
            if sorted1 == sorted2:
                pair = tuple(sorted([word1, word2]))
                if pair not in checked_pairs:
                    checked_pairs.add(pair)
                    anagram_pairs.append(pair)

    anagram_pairs.sort()
    return anagram_pairs

# To facilitate easier reading of the function.
def main(N, word_list):
    pairs = find_anagram_pairs(word_list)
    if pairs:
        for pair in pairs:
            print(f"{pair[0]} {pair[1]}")
    else:
        print("No anagrams found")

def exist(board, word):
    """
    Determines if a word exists in a board constructed from sequentially adjacent cells.
    """

    def dfs(board, word, i, j, word_index):
        if word_index == len(word):
            return True
        if i < 0 or i >= len(board) or j < 0 or j >= len(board[0]) or board[i][j] != word[word_index]:
            return False

        temp = board[i][j]
        board[i][j] = "#"  # mark as visited

        found = (
            dfs(board, word, i + 1, j, word_index + 1) or
            dfs(board, word, i - 1, j, word_index + 1) or
            dfs(board, word, i, j + 1, word_index + 1) or
            dfs(board, word, i, j - 1, word_index + 1)
        )

        board[i][j] = temp  # unmark

        return found

    for i in range(len(board)):
        for j in range(len(board[0])):
            if board[i][j] == word[0] and dfs(board, word, i, j, 0):
                return True

    return False

def max_gold(n, grid):
    if n == 0:
        return 0

    dp = [[0] * n for _ in range(n)]
    dp[0][0] = grid[0][0]

    for i in range(n):
        for j in range(n):
            if i > 0:
                dp[i][j] = max(dp[i][j], dp[i-1][j] + grid[i][j])
            if j > 0:
                dp[i][j] = max(dp[i][j], dp[i][j-1] + grid[i][j])

    return dp[-1][-1]

def maximize_diagonals(n):
    """
    Construct an n x n matrix with distinct integers that maximizes the sum of the sums of the diagonals.
    """
    matrix = [[0] * n for _ in range(n)]
    num = 1
    for i in range(n):
        for j in range(n):
            matrix[i][j] = num
            num += 1

    # Swapping to maximize the diagonal sums
    for i in range(n):
        for j in range(i, n):
            if i != j:
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    return matrix

