def find_indices(nums, target):
    """
    Finds two distinct indices i and j such that nums[i] + nums[j] equals target.

    Args:
    nums (list of int): The list of integers.
    target (int): The target sum.

    Returns:
    tuple of int: A tuple containing the indices (i, j) such that nums[i] + nums[j] = target.
                  If no such indices exist, returns (-1, -1).
    """
    num_to_index = {}

    for index, num in enumerate(nums):
        complement = target - num

        if complement in num_to_index:
            return (num_to_index[complement], index)

        num_to_index[num] = index

    return (-1, -1)

