def hasZeroSumSubarray(arr, n):
    if len(arr) < n:
        return False

    current_sum = sum(arr[:n])

    if current_sum == 0:
        return True

    for i in range(n, len(arr)):
        current_sum += arr[i] - arr[i - n]
        if current_sum == 0:
            return True

    return False

