def longest_palindromic_substring(n, words):
    def is_palindrome(word):
        return word == word[::-1]

    # Initialize the variable to store the longest palindromic substring
    longest_palindrome = ""

    for word in words:
        length = len(word)
        for i in range(length):
            for j in range(i + 1, length + 1):
                substring = word[i:j]
                if is_palindrome(substring):
                    # Check if the current palindrome is longer than the stored one
                    # or if they are the same length but lexicographically smaller
                    if (len(substring) > len(longest_palindrome) or
                       (len(substring) == len(longest_palindrome) and substring < longest_palindrome)):
                        longest_palindrome = substring

    return longest_palindrome

