def is_prime(num):
    """
    Check if a number is a prime number.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def can_be_expressed_as_sum_of_two_primes(n):
    """
    Check if the number n can be expressed as the sum of two prime numbers.
    """
    for i in range(2, n // 2 + 1):
        if is_prime(i) and is_prime(n - i):
            return "YES"
    return "NO"

