def find_max_visits(n, intervals):
    # Create a list for the number of visits per day for each of the 365 days in a year
    visits = [0] * 366  # To handle day numbers from 1 to 365

    # Process each interval
    for s, e, v in intervals:
        for day in range(s, e + 1):
            visits[day] += v

    # Find the maximum number of visits on any single day
    max_visits = max(visits)

    return max_visits

from collections import defaultdict, deque

def can_reach(n, edges, queries):
    def bfs(start, goal):
        visited = [False] * (n + 1)
        visited[start] = True
        queue = deque([start])

        while queue:
            node = queue.popleft()
            if node == goal:
                return True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)
        return False

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)

    # Check each query
    results = []
    for a, b in queries:
        if bfs(a, b):
            results.append("YES")
        else:
            results.append("NO")

    return results

