def canPartitionKSubsets(nums, k):
    """
    Determines if the array can be partitioned into k subsets with equal sum
    """
    total_sum = sum(nums)

    if total_sum % k != 0:
        return False

    target_sum = total_sum // k
    nums.sort(reverse=True)
    used = [False] * len(nums)

    def canPartition(start, k, current_sum):
        if k == 1:
            return True  # The last subset must be valid because sum total_sum is divisible by k

        if current_sum == target_sum:
            return canPartition(0, k-1, 0)

        for i in range(start, len(nums)):
            if not used[i]:
                if current_sum + nums[i] <= target_sum:
                    used[i] = True
                    if canPartition(i + 1, k, current_sum + nums[i]):
                        return True
                    used[i] = False

        return False

    return canPartition(0, k, 0)

def min_in_subarray(arr, n, x):
    """
    Transforms the array such that each element arr[i] is replaced by the
    smallest element from arr[i+1] to arr[i+x] (both inclusive).
    If there are fewer than x elements remaining, consider only available elements.
    """
    result = []
    for i in range(n):
        if i + 1 >= n:
            result.append(-1)
        else:
            result.append(min(arr[i+1:min(i+x+1, n)]))
    return result

