def process_queries(N, Q, queries):
    stack = []
    max_stack = []
    results = []

    for query in queries:
        if query.startswith("PUSH"):
            _, x = query.split()
            x = int(x)
            if len(stack) < N:
                stack.append(x)
                if not max_stack or x >= max_stack[-1]:
                    max_stack.append(x)
        elif query == "POP":
            if stack:
                popped = stack.pop()
                if popped == max_stack[-1]:
                    max_stack.pop()
            else:
                results.append("EMPTY")
        elif query == "MAX":
            if max_stack:
                results.append(max_stack[-1])
            else:
                results.append("EMPTY")

    return results

