def max_shoppers(test_cases):
    results = []
    for case in test_cases:
        events = []
        for entry, exit in case:
            events.append((entry, 'entry'))
            events.append((exit, 'exit'))
        events.sort()

        current_shoppers = 0
        max_shoppers = 0

        for time, event in events:
            if event == 'entry':
                current_shoppers += 1
                max_shoppers = max(max_shoppers, current_shoppers)
            else:
                current_shoppers -= 1

        results.append(max_shoppers)
    return results

