def find_cycle(graph):
    """
    Detects a cycle in a directed graph and returns one of the cycles found.
    If no cycle is found, returns an empty list.
    """
    def dfs(node, stack, visited, rec_stack):
        visited[node] = True
        rec_stack[node] = True
        stack.append(node)

        if node in graph:
            for neighbour in graph[node]:
                if not visited[neighbour]:
                    if dfs(neighbour, stack, visited, rec_stack):
                        return True
                elif rec_stack[neighbour]:
                    stack.append(neighbour)
                    return True

        stack.pop()
        rec_stack[node] = False
        return False

    visited = {node: False for node in graph}
    rec_stack = {node: False for node in graph}
    stack = []

    for node in graph:
        if not visited[node]:
            if dfs(node, stack, visited, rec_stack):
                # Extract the cycle from the stack
                cycle_start = stack[-1]
                cycle = []
                while stack:
                    current = stack.pop()
                    cycle.append(current)
                    if current == cycle_start and len(cycle) > 1:
                        cycle.reverse()
                        return cycle
    return []

