def min_operations_to_sort_books(n, books):
    """
    Returns the minimum number of operations required to sort the books in ascending order.
    n: int - number of books
    books: List[int] - current ordering of books
    """
    def lis_length(sequence):
        from bisect import bisect_left
        lis = []
        for x in sequence:
            pos = bisect_left(lis, x)
            if pos == len(lis):
                lis.append(x)
            else:
                lis[pos] = x
        return len(lis)

    lis_len = lis_length(books)
    return n - lis_len

