def min_operations_to_sort(n, array):
    if n <= 1:
        return 0

    sorted_array = sorted(array)
    if array == sorted_array:
        return 0

    l, r = 0, n - 1
    while l < n and array[l] == sorted_array[l]:
        l += 1
    while r >= 0 and array[r] == sorted_array[r]:
        r -= 1

    if l > r:
        return 0

    if array[l:r+1] == sorted(array[l:r+1])[::-1]:
        return 1

    return 2

