def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)

    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def minimum_cost_to_connect_cities(n, m, roads):
    if m < n - 1:
        return -1  # Not enough roads to connect all cities

    roads.sort(key=lambda x: x[2])
    parent = []
    rank = []

    for node in range(n):
        parent.append(node)
        rank.append(0)

    result = []
    i = 0
    e = 0

    while e < n - 1:
        if i >= len(roads):
            return -1  # Not enough roads to connect all cities

        u, v, w = roads[i]
        i = i + 1
        x = find(parent, u - 1)
        y = find(parent, v - 1)

        if x != y:
            e = e + 1
            result.append(w)
            union(parent, rank, x, y)

    return sum(result)

