def find_peak_point(grid, n, m):
    def is_peak(i, j):
        """Determines if grid[i][j] is a peak"""
        neighbors = [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]
        for ni, nj in neighbors:
            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] > grid[i][j]:
                return False
        return True

    for i in range(n):
        for j in range(m):
            if is_peak(i, j):
                return i, j
    return -1, -1

def parse_input_and_find_peak(input_string):
    data = input_string.strip().split('\n')
    n, m = map(int, data[0].split())
    grid = [list(map(int, row.split())) for row in data[1:]]
    return find_peak_point(grid, n, m)

