def calculate_total_sales(sales, recruits):
    def get_total_sales(distributor, visited):
        if distributor in visited:
            return 0
        visited.add(distributor)
        total = sales.get(distributor, 0)
        for recruit in recruits.get(distributor, []):
            total += get_total_sales(recruit, visited)
        return total

    total_sales = {}
    for distributor in sales:
        visited = set()
        total_sales[distributor] = get_total_sales(distributor, visited)

    return total_sales

