def count_subarrays_with_min_value(test_cases):
    results = []
    for n, x, arr in test_cases:
        count = 0
        subarray_count = 0
        for i in range(n):
            if arr[i] >= x:
                count += (subarray_count + 1) * (n - i)
                subarray_count = 0
            else:
                subarray_count += 1
        results.append(count)
    return results

