def replace_vowels_with_ascii(s):
    """
    Replace each vowel in the input string with its ASCII value.
    The function is case insensitive but preserves the case of consonants.
    """
    vowels_to_ascii = {
        'a': '97', 'e': '101', 'i': '105', 'o': '111', 'u': '117',
        'A': '97', 'E': '101', 'I': '105', 'O': '111', 'U': '117'
    }

    result = []
    for char in s:
        if char in vowels_to_ascii:
            result.append(vowels_to_ascii[char])
        else:
            result.append(char)
    return ''.join(result)

def character_occurrences(s):
    """
    Returns a dictionary with each character from the string as the key
    and the number of its occurrences as the value. The function is case insensitive.
    """
    s = s.lower()
    occurrences = {}
    for char in s:
        if char in occurrences:
            occurrences[char] += 1
        else:
            occurrences[char] = 1
    return occurrences

