def count_islands(grid, n, m):
    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            i, j = stack.pop()
            if 0 <= i < n and 0 <= j < m and grid[i][j] == 1:
                grid[i][j] = -1  # mark as visited
                stack.extend([(i + 1, j), (i - 1, j), (i, j + 1), (i, j - 1)])

    islands = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 1:
                dfs(i, j)
                islands += 1
    return islands

def number_of_islands(test_cases):
    results = []
    for grid, n, m in test_cases:
        results.append(count_islands(grid, n, m))
    return results

def is_possible_to_pair(n, s):
    from collections import Counter
    shoe_counts = Counter(s)

    for count in shoe_counts.values():
        if count % 2 != 0:
            return "NO"
    return "YES"

def process_cases(T, cases):
    results = []
    for i in range(T):
        n, s = cases[i]
        results.append(is_possible_to_pair(n, s))
    return results

def min_effort_path(grid):
    """
    Returns the minimum effort required to traverse from the top-left corner
    to the bottom-right corner of the grid.
    """
    n = len(grid)
    m = len(grid[0])

    # To handle boundary conditions when n or m is 1
    if n == 1:
        return sum(grid[0])
    if m == 1:
        return sum(grid[i][0] for i in range(n))

    # Initialize a dp table
    dp = [[0] * m for _ in range(n)]
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, m):
        dp[0][j] = dp[0][j - 1] + grid[0][j]

    # Fill the first column
    for i in range(1, n):
        dp[i][0] = dp[i - 1][0] + grid[i][0]

    # Fill the rest of the dp table
    for i in range(1, n):
        for j in range(1, m):
            dp[i][j] = min(dp[i - 1][j], dp[i][j - 1]) + grid[i][j]

    return dp[n - 1][m - 1]

