def most_frequent_character(S, queries):
    """
    Returns a list of most frequent characters for each query range [L, R].
    If there is a tie, returns the lexicographically smallest character.

    S: str, the given string
    queries: list of tuples, each tuple containing two integers L and R
    """
    results = []

    for L, R in queries:
        substring = S[L:R+1]
        freq_map = {}

        for char in substring:
            if char in freq_map:
                freq_map[char] += 1
            else:
                freq_map[char] = 1

        max_freq = max(freq_map.values())
        most_freq_chars = [char for char, freq in freq_map.items() if freq == max_freq]

        results.append(min(most_freq_chars))

    return results

