def count_distinct_substrings(s, k):
    """
    Returns the number of distinct substrings of length k in the string s.
    """
    if k > len(s):
        return 0

    substrings = set()

    for i in range(len(s) - k + 1):
        substr = s[i:i+k]
        substrings.add(substr)

    return len(substrings)

