def tablet_energy_value(n, matrix, operation):
    from functools import reduce

    def apply_operation(x, y, op):
        if op == "+":
            return x + y
        elif op == "*":
            return x * y
        elif op == "max":
            return max(x, y)
        elif op == "min":
            return min(x, y)

    # Flatten the matrix into a list of values
    values = [matrix[i][j] for i in range(n) for j in range(n)]

    # Reduce all values into a single value by applying the operation
    energy_value = reduce(lambda x, y: apply_operation(x, y, operation), values)

    return energy_value

