import heapq

def shortest_path_times(N, M, S, paths, K, key_rooms):
    # Create a graph from the given paths
    graph = {i: [] for i in range(1, N+1)}
    for A, B, T in paths:
        graph[A].append((B, T))
        graph[B].append((A, T))  # Assuming this is an undirected graph

    # Initialize the distances dictionary with infinity
    distances = {i: float('inf') for i in range(1, N+1)}
    distances[S] = 0

    # Min-heap to store (distance, node)
    heap = [(0, S)]

    while heap:
        current_distance, current_node = heapq.heappop(heap)

        # If the popped distance is still the best known distance
        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))

    # Extract the shortest times for the key rooms
    result = []
    for room in key_rooms:
        if distances[room] == float('inf'):
            result.append(-1)
        else:
            result.append(distances[room])

    return result

def min_operations_to_palindrome(n, s):
    """
    Returns the minimum number of operations required to transform the given string into a palindrome.
    """
    def lcs(x, y):
        """ Helper function to find the longest common subsequence """
        m = len(x)
        n = len(y)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0 or j == 0:
                    dp[i][j] = 0
                elif x[i - 1] == y[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1] + 1
                else:
                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

        return dp[m][n]

    reverse_s = s[::-1]
    lcs_length = lcs(s, reverse_s)

    # Minimum operations to make the string palindrome
    return n - lcs_length

