def second_largest(numbers):
    """
    Returns the second largest integer in the list of numbers.
    Assumes the list has at least two unique integers.
    """
    first, second = float('-inf'), float('-inf')
    for num in numbers:
        if num > first:
            first, second = num, first
        elif first > num > second:
            second = num
    return second

