import heapq

def optimize_network(n, m, D, links):
    def kruskal():
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                if rank[rootX] > rank[rootY]:
                    parent[rootY] = rootX
                elif rank[rootX] < rank[rootY]:
                    parent[rootX] = rootY
                else:
                    parent[rootY] = rootX
                    rank[rootX] += 1
                return True
            return False

        # sorting links by bandwidth capacity in descending order
        links.sort(key=lambda x: (-x[2], x[3]))
        total_bandwidth = 0
        total_distance = 0
        selected_edges = 0

        for u, v, c, d in links:
            if union(u - 1, v - 1):
                total_bandwidth += c
                total_distance += d
                selected_edges += 1
            if selected_edges == n - 1:
                break

        if selected_edges == n - 1 and total_distance <= D:
            return total_bandwidth
        else:
            return "Impossible"

    return kruskal()

def is_perfect_number(num):
    if num <= 1:
        return False
    sum_of_divisors = 1
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            sum_of_divisors += i
            if i != num // i:
                sum_of_divisors += num // i
    return sum_of_divisors == num

