def balance_brackets(s):
    """
    Checks if the brackets in the given string are balanced.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():  # if it's an opening bracket
            stack.append(char)
        elif char in bracket_map.keys():  # if it's a closing bracket
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            continue  # ignore non-bracket characters

    return stack == []  # True if balanced, False otherwise

def generate_matrix(N, K):
    matrix = []
    for i in range(N):
        row = []
        for j in range(N):
            row.append((i + j) * K)
        matrix.append(row)
    return matrix

def solve(test_cases):
    results = []
    for N, K in test_cases:
        matrix = generate_matrix(N, K)
        results.append(matrix)
    return results

