def unique_elements(lst):
    """
    Returns a new list composed of only the unique elements of the original list,
    in the same order they first appeared.
    """
    seen = {}
    unique_lst = []
    for elem in lst:
        if elem not in seen:
            seen[elem] = True
            unique_lst.append(elem)
    return unique_lst

