def find_largest_palindrome(arr):
    """
    Returns the largest palindromic string from the list of strings.
    If no palindromic string is found, returns an empty string.
    If the input is not a list, returns None.
    """
    if not isinstance(arr, list):
        return None

    largest_palindrome = ""

    for string in arr:
        if isinstance(string, str):
            normalized_str = string.lower()
            if normalized_str == normalized_str[::-1]:
                if len(string) > len(largest_palindrome):
                    largest_palindrome = string

    return largest_palindrome

