def process_commands(m, commands):
    """
    Processes a list of commands that manipulate a set of integers.

    m: int - Number of commands
    commands: list - A list of commands.
    """
    result = []
    int_set = set()

    for command in commands:
        if command.startswith("ADD"):
            _, x = command.split()
            int_set.add(int(x))
        elif command.startswith("REMOVE"):
            _, x = command.split()
            int_set.discard(int(x))
        elif command.startswith("CHECK"):
            _, x = command.split()
            result.append("1" if int(x) in int_set else "0")
        elif command.startswith("TOGGLE"):
            _, x = command.split()
            x = int(x)
            if x in int_set:
                int_set.remove(x)
            else:
                int_set.add(x)
        elif command == "ALL":
            int_set = set(range(1, 101))

    return result

def findMinSubstrLength(str, pat):
    from collections import Counter

    if not str or not pat:
        return -1

    pat_counter = Counter(pat)
    str_counter = Counter()

    required = len(pat_counter)
    formed = 0

    left = 0
    min_length = float('inf')

    for right, char in enumerate(str):
        str_counter[char] += 1

        if char in pat_counter and str_counter[char] == pat_counter[char]:
            formed += 1

        while left <= right and formed == required:
            current_window_length = right - left + 1
            if current_window_length < min_length:
                min_length = current_window_length

            str_counter[str[left]] -= 1
            if str[left] in pat_counter and str_counter[str[left]] < pat_counter[str[left]]:
                formed -= 1
            left += 1

    return min_length if min_length != float('inf') else -1

def exists_path(grid, N, M):
    from collections import deque

    def get_neighbors(x, y):
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and grid[nx][ny] != 'X':
                yield nx, ny

    # Find starting and ending positions
    start, end = None, None
    for i in range(N):
        for j in range(M):
            if grid[i][j] == 'S':
                start = (i, j)
            if grid[i][j] == 'E':
                end = (i, j)

    if not start or not end:
        return "NO"

    queue = deque([start])
    visited = set(start)

    while queue:
        x, y = queue.popleft()

        if (x, y) == end:
            return "YES"

        for nx, ny in get_neighbors(x, y):
            if (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append((nx, ny))

    return "NO"

