def find_optimal_track(test_cases):
    results = []
    for idx, case in enumerate(test_cases):
        n = case[0]
        runners = case[1]
        track_times = {}

        for runner in runners:
            k = runner[0]
            preferred_tracks = runner[1:]

            for i in range(0, len(preferred_tracks), 2):
                track_id = preferred_tracks[i]
                finish_time = preferred_tracks[i + 1]

                if track_id in track_times:
                    track_times[track_id] += finish_time
                else:
                    track_times[track_id] = finish_time

        optimal_track = min(track_times, key=lambda x: (track_times[x], x))
        results.append(f"Case #{idx + 1}: {optimal_track}")

    return results

def parse_input(input_text):
    lines = input_text.strip().split('\n')
    t = int(lines[0])
    test_cases = []

    index = 1
    for _ in range(t):
        n = int(lines[index])
        runners = []
        for i in range(n):
            runner_data = list(map(int, lines[index + i + 1].split()))
            runners.append(runner_data)
        test_cases.append((n, runners))
        index += n + 1

    return test_cases

def median_of_three_quick_sort(arr: list) -> None:
    def median_of_three(a, b, c):
        if (a - b) * (c - a) >= 0:
            return a
        elif (b - a) * (c - b) >= 0:
            return b
        else:
            return c

    def partition(low, high):
        mid = (low + high) // 2
        pivot_index = arr.index(median_of_three(arr[low], arr[mid], arr[high]))
        arr[pivot_index], arr[high] = arr[high], arr[pivot_index]
        pivot = arr[high]

        i = low - 1
        for j in range(low, high):
            if arr[j] <= pivot:
                i += 1
                arr[i], arr[j] = arr[j], arr[i]
        arr[i + 1], arr[high] = arr[high], arr[i + 1]
        return i + 1

    def quick_sort(low, high):
        if low < high:
            pi = partition(low, high)
            quick_sort(low, pi - 1)
            quick_sort(pi + 1, high)

    quick_sort(0, len(arr) - 1)

def is_path_possible(n, m, grid):
    from collections import deque

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return "NO"

    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
    visited = [[False] * m for _ in range(n)]
    queue = deque([(0, 0)])
    visited[0][0] = True

    while queue:
        x, y = queue.popleft()

        if x == n - 1 and y == m - 1:
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and not visited[nx][ny] and grid[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny))

    return "NO"

def count_palindromes(set_chars, length):
    """
    Returns the count of palindromes of the given length using characters from the given set.
    """
    m = len(set_chars)

    if length == 1:
        return m

    if length % 2 == 0:
        return m ** (length // 2)
    else:
        return m ** ((length // 2) + 1)

