def are_anagrams(a, b):
    """
    Returns True if the two strings a and b are anagrams of each other, False otherwise.
    """
    # Anagram strings must be of the same length
    if len(a) != len(b):
        return False

    # Check if both strings have the same frequency of characters
    from collections import Counter
    return Counter(a) == Counter(b)

