import heapq

def find_shortest_paths(T, test_cases):
    results = []

    for i in range(T):
        N, M, edges, S, G = test_cases[i]

        graph = {i: [] for i in range(1, N + 1)}
        for u, v, w in edges:
            graph[u].append((w, v))

        distance = {i: float('inf') for i in range(1, N + 1)}
        distance[S] = 0

        priority_queue = [(0, S)]
        while priority_queue:
            current_distance, node = heapq.heappop(priority_queue)

            if current_distance > distance[node]:
                continue

            for weight, neighbor in graph[node]:
                distance_via_node = current_distance + weight
                if distance_via_node < distance[neighbor]:
                    distance[neighbor] = distance_via_node
                    heapq.heappush(priority_queue, (distance_via_node, neighbor))

        if distance[G] == float('inf'):
            results.append("unreachable")
        else:
            results.append(distance[G])

    return results

def find_maximum(arr):
    """
    Returns the maximum value in the array using a limited number of comparisons.
    Assumes N, the length of the array, is an even number.
    """
    if len(arr) == 0:
        return None

    # Standard linear search to find the maximum value
    max_value = arr[0]

    for i in range(1, len(arr)):
        if arr[i] > max_value:
            max_value = arr[i]

    return max_value

