def fourSum(arr):
    """
    Returns all the unique quadruplets [a, b, c, d] such that a + b + c + d = 0.
    """
    arr.sort()
    n = len(arr)
    quadruplets = set()

    for i in range(n - 3):
        for j in range(i + 1, n - 2):
            left = j + 1
            right = n - 1
            while left < right:
                total = arr[i] + arr[j] + arr[left] + arr[right]
                if total == 0:
                    quadruplets.add((arr[i], arr[j], arr[left], arr[right]))
                    left += 1
                    right -= 1
                elif total < 0:
                    left += 1
                else:
                    right -= 1

    return [list(quad) for quad in sorted(quadruplets)]

