def can_sort_books(n, books):
    """
    Determines if it is possible to sort the books in ascending order.
    """
    # Check inversions count
    inversions = 0
    for i in range(n):
        for j in range(i + 1, n):
            if books[i] > books[j]:
                inversions += 1

    # If inversions count is even, the books can be sorted
    if inversions % 2 == 0:
        return "YES"
    else:
        return "NO"

