from math import gcd
from itertools import permutations

def gcd_pair(a, b):
    """Helper function to check gcd > 1 for a pair"""
    return gcd(a, b) > 1

def reorder_list(n, lst):
    """
    Reorder list such that every consecutive pair of numbers has a GCD > 1
    """
    for perm in permutations(lst):
        valid = True
        for i in range(1, n):
            if not gcd_pair(perm[i-1], perm[i]):
                valid = False
                break
        if valid:
            return "YES", perm
    return "NO", []

# Function to facilitate the direct response as specified in the problem statement
def list_reorder_response(n, lst):
    result, perm = reorder_list(n, lst)
    if result == "NO":
        return "NO"
    else:
        return "YES\n" + ' '.join(map(str, perm))

