def wordExists(m, n, grid, word):
    def dfs(x, y, index):
        if index == len(word):
            return True
        if x < 0 or y < 0 or x >= m or y >= n or grid[x][y] != word[index]:
            return False

        temp = grid[x][y]
        grid[x][y] = '#'  # Mark as visited

        # Explore all adjacent cells (up, down, left, right)
        found = (dfs(x + 1, y, index + 1) or
                 dfs(x - 1, y, index + 1) or
                 dfs(x, y + 1, index + 1) or
                 dfs(x, y - 1, index + 1))

        grid[x][y] = temp  # Unmark as visited
        return found

    for i in range(m):
        for j in range(n):
            if grid[i][j] == word[0] and dfs(i, j, 0):
                return "Yes"
    return "No"

