def longest_increasing_subsequence(T, test_cases):
    def lis_length(arr):
        if not arr:
            return 0

        dp = [arr[0]]

        for num in arr[1:]:
            if num > dp[-1]:
                dp.append(num)
            else:
                # Binary search to find the smallest element >= num
                left, right = 0, len(dp) - 1
                while left < right:
                    mid = (left + right) // 2
                    if dp[mid] < num:
                        left = mid + 1
                    else:
                        right = mid
                dp[left] = num

        return len(dp)

    results = []
    for case in test_cases:
        N, sales_records = case
        result = lis_length(sales_records)
        results.append(result)

    return results

