def max_histogram_area(histogram):
    stack = list()
    max_area = 0
    index = 0

    while index < len(histogram):
        if not stack or histogram[stack[-1]] <= histogram[index]:
            stack.append(index)
            index += 1
        else:
            top_of_stack = stack.pop()
            area = (histogram[top_of_stack] *
                    ((index - stack[-1] - 1) if stack else index))
            max_area = max(max_area, area)

    while stack:
        top_of_stack = stack.pop()
        area = (histogram[top_of_stack] *
                ((index - stack[-1] - 1) if stack else index))
        max_area = max(max_area, area)

    return max_area

def max_rectangle_area(grid):
    if not grid:
        return 0

    max_area = 0
    row_area = [0] * len(grid[0])

    for row in grid:
        for index in range(len(row)):
            if row[index] == '1':
                row_area[index] += 1
            else:
                row_area[index] = 0

        max_area = max(max_area, max_histogram_area(row_area))

    return max_area

