def catalan_number(n):
    """
    Return the nth Catalan number. This function uses a dynamic programming approach.
    """
    if n == 0:
        return 1
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1

    for i in range(2, n + 1):
        for j in range(i):
            dp[i] += dp[j] * dp[i - j - 1]

    return dp[n]

def max_non_crossing_handshakes(N):
    """
    Return the maximum number of non-crossing handshakes for N employees.
    This is the (N/2)th Catalan number.
    """
    if N % 2 != 0:
        raise ValueError("N must be even")
    return catalan_number(N // 2)

def solve(T, test_cases):
    results = []
    for N in test_cases:
        results.append(max_non_crossing_handshakes(N))
    return results

