def optimal_ride_sharing(m, n, p, passenger_routes):
    from itertools import permutations
    import math

    # Function to calculate distance for a car covering certain passengers
    def calculate_car_distance(passenger_indices):
        if not passenger_indices:
            return 0
        min_start = min(passenger_routes[i][0] for i in passenger_indices)
        max_end = max(passenger_routes[i][1] for i in passenger_indices)
        return max_end - min_start

    # Function to distribute passengers among cars
    def distribute_passengers():
        passenger_indices = list(range(p))
        min_total_distance = math.inf
        best_distribution = None

        for perm in permutations(passenger_indices):
            current_distribution = [list() for _ in range(m)]
            index = 0
            for i in range(m):
                for _ in range(n):
                    if index < p:
                        current_distribution[i].append(perm[index])
                        index += 1

            total_distance = sum(calculate_car_distance(car) for car in current_distribution)
            if total_distance < min_total_distance:
                min_total_distance = total_distance
                best_distribution = current_distribution

        return min_total_distance, best_distribution

    min_total_distance, best_distribution = distribute_passengers()

    # Prepare output
    output = []
    output.append(f"{min_total_distance:.1f}")

    for car in best_distribution:
        output.append(f"{len(car)} " + " ".join(str(i + 1) for i in car))

    return '\n'.join(output)

import math
import collections

def is_prime(num):
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    limit = int(math.sqrt(num)) + 1
    for i in range(3, limit, 2):
        if num % i == 0:
            return False
    return True

def find_min_edges(N, M, edges):
    adjacency_list = collections.defaultdict(list)
    for u, v, w in edges:
        if is_prime(w):
            adjacency_list[u].append(v)
            adjacency_list[v].append(u)

    queue = collections.deque([(1, 0)])  # start from node 1 with 0 edges
    visited = set()
    visited.add(1)

    while queue:
        current_node, current_depth = queue.popleft()

        if current_node == N:
            return current_depth

        for neighbor in adjacency_list[current_node]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, current_depth + 1))

    return -1

def process_test_cases(T, test_cases):
    results = []
    for i in range(T):
        N, M = test_cases[i][0]
        edges = test_cases[i][1:]
        result = find_min_edges(N, M, edges)
        results.append(result)
    return results

import heapq

def shortest_travel_times(N, M, roads, queries):
    def dijkstra(graph, src):
        dist = [float('inf')] * N
        dist[src] = 0
        pq = [(0, src)]

        while pq:
            current_distance, current_node = heapq.heappop(pq)

            if current_distance > dist[current_node]:
                continue

            for neighbor, weight in graph[current_node]:
                distance = current_distance + weight

                if distance < dist[neighbor]:
                    dist[neighbor] = distance
                    heapq.heappush(pq, (distance, neighbor))

        return dist

    # Build the graph
    graph = [[] for _ in range(N)]
    for u, v, t in roads:
        graph[u - 1].append((v - 1, t))
        graph[v - 1].append((u - 1, t))

    # Prepare answers for each query using Dijkstra's algorithm
    answers = []
    for src, dest in queries:
        dist = dijkstra(graph, src - 1)
        travel_time = dist[dest - 1]
        if travel_time == float('inf'):
            answers.append("INFINITY")
        else:
            answers.append(travel_time)

    return answers

def generateSequenceSum(N):
    if N <= 0:
        return []
    sequence_sum = []
    current_sum = 0
    for i in range(1, N+1):
        current_sum += i
        sequence_sum.append(current_sum)
    return sequence_sum

