def max_trade_value(n, B, items):
    # Implementing a dynamic programming approach to solve the knapsack problem
    dp = [0] * (B + 1)

    for i in range(n):
        s, v = items[i]
        for b in range(B, v - 1, -1):
            dp[b] = max(dp[b], dp[b - v] + v)

    return dp[B]

