def is_valid_transport_sequence(events):
    """
    This function checks whether a given sequence of board and alight events is valid.
    """
    on_board = set()

    for action, rider_id in events:
        if action == "board":
            if rider_id in on_board:
                return "INVALID"
            on_board.add(rider_id)
        elif action == "alight":
            if rider_id not in on_board:
                return "INVALID"
            on_board.remove(rider_id)

    return "VALID"

