def longest_balanced_subsequence(n, sequence):
    """
    Returns the length of the longest balanced subsequence in the given sequence of integers.
    A sequence is balanced if it contains equal numbers of 0s, 1s, and 2s.
    """
    count_0 = count_1 = count_2 = 0

    for num in sequence:
        if num == 0:
            count_0 += 1
        elif num == 1:
            count_1 += 1
        elif num == 2:
            count_2 += 1

    # The longest balanced subsequence length will be 3 * min(count_0, count_1, count_2)
    return 3 * min(count_0, count_1, count_2)

