            return 0
        # Table to store the palindrome status
        dp = [[False] * n for _ in range(n)]
        max_length = 1
        # Single letter palindromes
        for i in range(n):
            dp[i][i] = True
        # Two consecutive letters palindromes
        for i in range(n - 1):
            if substring[i] == substring[i + 1]:
                dp[i][i + 1] = True
                max_length = 2
        # Substrings longer than 2
        for length in range(3, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                if substring[i] == substring[j] and dp[i + 1][j - 1]:
                    dp[i][j] = True
                    max_length = length
        return max_length

    results = []
    for li, ri in queries:
        sub_str = s[li-1:ri]
        results.append(longest_palindrome_length(sub_str))
    return results

def find_duplicates(batches):
    """
    Given details of multiple batches of stamps, find and return the duplicate stamps in each batch.

    :param batches: List of tuples [(m, stamps)]
    :return: List of strings, where each string contains duplicate stamp IDs or "No duplicates"
    """
    results = []

    for m, stamps in batches:
        counter = {}
        for stamp in stamps:
            if stamp in counter:
                counter[stamp] += 1
            else:
                counter[stamp] = 1

        duplicates = [stamp for stamp, count in counter.items() if count > 1]

        if duplicates:
            results.append(" ".join(map(str, duplicates)))
        else:
            results.append("No duplicates")

    return results

