def is_perfect_rectangle(n, blocks):
    total_area = 0
    min_x = min_y = float('inf')
    max_x = max_y = float('-inf')
    block_set = set()

    for x, y, w, h in blocks:
        total_area += w * h
        min_x = min(min_x, x)
        min_y = min(min_y, y)
        max_x = max(max_x, x + w)
        max_y = max(max_y, y + h)

        for i in range(w):
            for j in range(h):
                if (x + i, y + j) in block_set:
                    return "NO"
                block_set.add((x + i, y + j))

    if total_area == (max_x - min_x) * (max_y - min_y):
        return "YES"
    else:
        return "NO"

