def categorize_books(books):
    """
    Categorizes books into three categories based on the number of pages.

    Parameters:
    books (list): List of dictionaries where each dictionary represents a book.

    Returns:
    dict: A dictionary with three keys: 'short', 'medium', 'long'.
          Each key contains a list of book titles that fall into that category.
    """
    categories = {
        'short': [],
        'medium': [],
        'long': []
    }

    for book in books:
        if book['pages'] < 100:
            categories['short'].append(book['title'])
        elif 100 <= book['pages'] <= 300:
            categories['medium'].append(book['title'])
        else:
            categories['long'].append(book['title'])

    return categories

