def evaluate_expression(expression: str) -> float:
    """
    Evaluates a basic mathematical expression and returns its result as a floating-point number.
    Supports addition, subtraction, multiplication, division, and parentheses for order of operations.
    """
    try:
        # Using eval to evaluate the expression
        result = eval(expression)
        return float(result)
    except ZeroDivisionError:
        raise ValueError("Division by zero is not allowed.")
    except Exception as e:
        raise ValueError(f"Invalid expression: {e}")

