def can_place_books(books, shelves, max_width):
    current_width = 0
    required_shelves = 1

    for book in books:
        if current_width + book > max_width:
            required_shelves += 1
            current_width = book
            if required_shelves > shelves:
                return False
        else:
            current_width += book

    return True

def minimizeShelfWidth(books, shelves):
    left, right = max(books), sum(books)

    while left < right:
        mid = (left + right) // 2
        if can_place_books(books, shelves, mid):
            right = mid
        else:
            left = mid + 1

    return left

