import heapq

def shortest_transmission_time(n, m, A, B, edges):
    # Create the adjacency list representation of the graph
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    # Dijkstra's algorithm to find the shortest path from A to B
    pq = [(0, A)]
    dist = {i: float('inf') for i in range(1, n + 1)}
    dist[A] = 0
    visited = set()

    while pq:
        current_dist, node = heapq.heappop(pq)

        if node in visited:
            continue
        visited.add(node)

        if node == B:
            return current_dist

        for neighbor, weight in graph[node]:
            if neighbor not in visited:
                new_dist = current_dist + weight
                if new_dist < dist[neighbor]:
                    dist[neighbor] = new_dist
                    heapq.heappush(pq, (new_dist, neighbor))

    return -1 if dist[B] == float('inf') else dist[B]

def packageCookies(cookies):
    full_boxes = cookies // 20
    leftover_cookies = cookies % 20

    if 12 <= leftover_cookies <= 19:
        partial_boxes = 1
        leftover_cookies -= leftover_cookies  # This will make leftover_cookies 0
    else:
        partial_boxes = 0

    return [full_boxes, partial_boxes, leftover_cookies]

