def is_path_exist(n, m, grid):
    from collections import deque

    if grid[0][0] == '#' or grid[n-1][m-1] == '#':
        return "NO"

    # Directions: Up, Down, Left, Right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(0, 0)])
    visited = set()
    visited.add((0, 0))

    while queue:
        x, y = queue.popleft()
        if (x, y) == (n-1, m-1):
            return "YES"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] == '.' and (nx, ny) not in visited:
                queue.append((nx, ny))
                visited.add((nx, ny))

    return "NO"

def create_access_code(s):
    """
    Convert an initial string into a valid access code with minimal changes.

    Args:
    s (str): The initial string consisting of only English letters.

    Returns:
    str: The valid access code string following the rules.
    """
    n = len(s)
    access_code = []

    # Make the first character uppercase
    if not s[0].isupper():
        access_code.append(s[0].upper())
    else:
        access_code.append(s[0])

    # Alternate between uppercase and lowercase
    for i in range(1, n):
        if i % 2 == 0:
            # Even index: should be uppercase
            if not s[i].isupper():
                access_code.append(s[i].upper())
            else:
                access_code.append(s[i])
        else:
            # Odd index: should be lowercase
            if not s[i].islower():
                access_code.append(s[i].lower())
            else:
                access_code.append(s[i])

    return ''.join(access_code)

