def find_two_non_repeating_numbers(numbers):
    """
    Finds and returns the two elements that appear only once in the array.
    The rest of the elements appear exactly twice.
    """
    xor_result = 0
    for num in numbers:
        xor_result ^= num

    # Get the rightmost set bit of xor_result
    rightmost_set_bit = xor_result & -xor_result

    # Divide elements into two groups based on the rightmost set bit
    num1 = 0
    num2 = 0
    for num in numbers:
        if (num & rightmost_set_bit) == 0:
            num1 ^= num
        else:
            num2 ^= num

    return sorted([num1, num2])

