def count_unique_prime_factors_of_factorial(N):
    """
    Returns the count of unique prime factors of N!
    """
    def sieve_of_eratosthenes(max_num):
        """
        Generates a list of primes up to max_num using the Sieve of Eratosthenes algorithm.
        """
        is_prime = [True] * (max_num + 1)
        p = 2
        while (p * p <= max_num):
            if (is_prime[p] == True):
                for i in range(p * p, max_num + 1, p):
                    is_prime[i] = False
            p += 1
        prime_list = []
        for p in range(2, max_num + 1):
            if is_prime[p]:
                prime_list.append(p)
        return prime_list

    # Generate all primes up to N using the sieve of Eratosthenes
    primes = sieve_of_eratosthenes(N)

    return len(primes)

