def find_unique_employees(employees):
    """
    Returns a list of employee IDs who are the only ones in their department.
    """
    dept_count = {}

    for employee in employees:
        department = employee['department']
        if department in dept_count:
            dept_count[department].append(employee['id'])
        else:
            dept_count[department] = [employee['id']]

    unique_employees = []
    for ids in dept_count.values():
        if len(ids) == 1:
            unique_employees.append(ids[0])

    return unique_employees

