from typing import Tuple

def count_vowels_and_consonants(input_string: str) -> Tuple[int, int]:
    vowels_set = {'a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'}
    vowels_count = 0
    consonants_count = 0

    for char in input_string:
        if char.isalpha():
            if char in vowels_set:
                vowels_count += 1
            else:
                consonants_count += 1

    return (vowels_count, consonants_count)

