def minimumBoatRuns(weights, capacity):
    weights.sort()
    i, j = 0, len(weights) - 1
    runs = 0

    while i <= j:
        if weights[i] + weights[j] <= capacity:
            i += 1
        j -= 1
        runs += 1

    return runs

