from typing import List

# This would be a mock function for the example
def isFile(path: str) -> bool:
    """
    Mock `isFile` function definition.
    This function should determine whether the given path is a file.
    It's expected to return `True` if the path is a file, `False` if it's a directory.
    """
    file_system = {
        "/": False,
        "/folder1/": False,
        "/folder1/file1.txt": True,
        "/folder1/folder2/": False,
        "/folder1/folder2/file2.txt": True,
        "/folder1/folder3/": False,
        "/folder1/folder3/file3.txt": True,
        "/file4.txt": True,
    }
    return file_system.get(path, False)

def listFiles(path: str) -> List[str]:
    file_structure = {
        "/": ["folder1/", "file4.txt"],
        "/folder1/": ["file1.txt", "folder2/", "folder3/"],
        "/folder1/folder2/": ["file2.txt"],
        "/folder1/folder3/": ["file3.txt"]
    }

    def list_files_recursive(current_path: str) -> List[str]:
        if isFile(current_path):
            return [current_path]

        results = []
        for sub_path in file_structure.get(current_path, []):
            full_sub_path = current_path + sub_path
            results.extend(list_files_recursive(full_sub_path))
        return results

    return list_files_recursive(path)

