def is_prime(num):
    """
    Helper function to check if a number is prime.
    """
    if num < 2:
        return False
    for i in range(2, int(num ** 0.5) + 1):
        if num % i == 0:
            return False
    return True

def prime_sum_triple(n):
    """
    Function to determine if n can be represented as a sum of three prime numbers.
    Returns one possible combination as a list [p1, p2, p3], or an empty list if no combination exists.
    """
    primes = [num for num in range(2, n) if is_prime(num)]

    # Check all combinations of three primes
    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] + primes[j] + primes[k] == n:
                    return [primes[i], primes[j], primes[k]]

    return []

