def unique_paths_with_obstacles(n, m, obstacles):
    # Create a 2D DP array initialized to 0
    dp = [[0] * m for _ in range(n)]

    # Turn obstacles into a set for faster access
    obstacle_set = {(u-1, v-1) for u, v in obstacles}

    # Initialize the starting point
    if (0, 0) not in obstacle_set:
        dp[0][0] = 1

    # Fill the DP table
    for i in range(n):
        for j in range(m):
            if (i, j) in obstacle_set:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

def number_of_unique_paths(T, test_cases):
    results = []
    for i in range(T):
        case = test_cases[i]
        N, M = case['grid_size']
        obstacles = case['obstacles']
        result = unique_paths_with_obstacles(N, M, obstacles)
        results.append(result)
    return results

