def is_perfect_number(n):
    """
    Determines if a number n is a perfect number.
    """
    if n < 2:
        return False

    sum_divisors = 1
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            sum_divisors += i
            if i != n // i:
                sum_divisors += n // i

    return sum_divisors == n

