def is_valid_matrix(n, k, matrix):
    # Check each row for validity
    for row in matrix:
        if sorted(row) != list(range(1, k + 1)):
            return "NO"

    # Check each column for validity
    for col in range(n):
        column_elements = [matrix[row][col] for row in range(n)]
        if sorted(column_elements) != list(range(1, k + 1)):
            return "NO"

    return "YES"

from typing import List

def word_search(grid: List[List[str]], word: str) -> bool:
    rows, cols = len(grid), len(grid[0])

    def dfs(r, c, index):
        if index == len(word):
            return True
        if r < 0 or c < 0 or r >= rows or c >= cols or grid[r][c] != word[index]:
            return False

        tmp, grid[r][c] = grid[r][c], '#'
        found = (
            dfs(r+1, c, index+1) or
            dfs(r-1, c, index+1) or
            dfs(r, c+1, index+1) or
            dfs(r, c-1, index+1)
        )
        grid[r][c] = tmp
        return found

    for i in range(rows):
        for j in range(cols):
            if dfs(i, j, 0):
                return True
    return False

