def process_operations(initial_value, operations):
    """
    Processes a series of operations on an initial value.

    Args:
    initial_value (int): The initial integer value.
    operations (str): A string of characters representing operations.

    Returns:
    int: The final value after processing all operations.
    """
    value = initial_value
    for operation in operations:
        if operation == 'A':
            value += 1
        elif operation == 'S':
            value -= 1
        elif operation == 'M':
            value *= 2
        elif operation == 'D':
            value //= 2
    return value

