def isPerfectNumber(n):
    """
    Determines whether a given positive integer n is a perfect number.

    :param n: The integer to be checked.
    :return: True if n is a perfect number, otherwise False.
    """
    if n <= 1:
        return False
    divisors_sum = 1  # Start with 1 as a divisor
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            divisors_sum += i
            if i != n // i:
                divisors_sum += n // i
    return divisors_sum == n

