def min_path_sum(grid):
    if not grid or not grid[0]:
        return 0

    R, C = len(grid), len(grid[0])
    dp = [[0] * C for _ in range(R)]
    dp[0][0] = grid[0][0]

    for i in range(1, R):
        dp[i][0] = dp[i - 1][0] + grid[i][0]
    for j in range(1, C):
        dp[0][j] = dp[0][j - 1] + grid[0][j]

    for i in range(1, R):
        for j in range(1, C):
            dp[i][j] = grid[i][j] + min(dp[i - 1][j], dp[i][j - 1])

    return dp[R - 1][C - 1]

def process_input(input_data):
    lines = input_data.strip().split('\n')
    index = 0
    T = int(lines[index])
    index += 1
    results = []
    for _ in range(T):
        R, C = map(int, lines[index].split())
        index += 1
        grid = []
        for _ in range(R):
            row = list(map(int, lines[index].split()))
            grid.append(row)
            index += 1
        results.append(min_path_sum(grid))

    return results

