def is_back_to_start(moves: str) -> str:
    """
    Determines if the sequence of moves returns to the starting position.

    Args:
    moves (str): a string representing the sequence of movements.

    Returns:
    str: "Yes" if the sequence returns to the starting point, "No" otherwise.
    """
    x, y = 0, 0

    for move in moves:
        if move == 'L':
            x -= 1
        elif move == 'R':
            x += 1
        elif move == 'U':
            y += 1
        elif move == 'D':
            y -= 1

    return "Yes" if x == 0 and y == 0 else "No"

def is_magic_square(grid):
    """
    Determines if a given 3x3 grid is a magic square.

    Parameters:
        grid (list of list of int): A 3x3 grid of integers.

    Returns:
        bool: True if the grid is a magic square, False otherwise.
    """
    if len(grid) != 3 or any(len(row) != 3 for row in grid):
        return False

    # Calculate the sum of the first row to set our magic sum target
    magic_sum = sum(grid[0])

    # Check sums of all rows
    for row in grid:
        if sum(row) != magic_sum:
            return False

    # Check sums of all columns
    for col in range(3):
        if sum(grid[row][col] for row in range(3)) != magic_sum:
            return False

    # Check sums of the two diagonals
    if sum(grid[i][i] for i in range(3)) != magic_sum:
        return False

    if sum(grid[i][2-i] for i in range(3)) != magic_sum:
        return False

    return True

