def longest_arithmetic_subarray(arr):
    """
    Returns the length of the longest arithmetic sub-array in a given list of positive integers.
    """
    if len(arr) < 2:
        return len(arr)

    max_len = 2
    current_len = 2
    current_diff = arr[1] - arr[0]

    for i in range(2, len(arr)):
        if arr[i] - arr[i - 1] == current_diff:
            current_len += 1
        else:
            current_diff = arr[i] - arr[i - 1]
            current_len = 2

        max_len = max(max_len, current_len)

    return max_len

