def hackathon_feasibility(n, m, hackers_per_city, sponsors):
    # Tracks if every city has at least one sponsor
    city_sponsorship = [0] * n

    for sponsor in sponsors:
        c = sponsor[0]
        sponsor_info = sponsor[1:]
        supported_cities = {sponsor_info[i * 2] - 1: sponsor_info[i * 2 + 1] for i in range(c)}

        for city in range(n):
            if hackers_per_city[city] <= supported_cities.get(city, 0):
                city_sponsorship[city] += 1

    # Check if every city has at least one sponsor
    if all(sponsor_count > 0 for sponsor_count in city_sponsorship):
        return "POSSIBLE"
    else:
        return "IMPOSSIBLE"

