def count_categories(s):
    """
    Returns a dictionary with counts of uppercase letters, lowercase letters, and digits in the string.
    If the string contains any other type of character, returns False.
    """
    counts = {'uppercase': 0, 'lowercase': 0, 'digits': 0}

    for char in s:
        if char.isupper():
            counts['uppercase'] += 1
        elif char.islower():
            counts['lowercase'] += 1
        elif char.isdigit():
            counts['digits'] += 1
        else:
            return False

    return counts

