def canFormPalindrome(s):
    """
    Check if a given string can be made into a palindrome by replacing at most one character.
    """
    def is_palindrome_range(i, j):
        """
        Helper function to check if a substring s[i:j+1] is a palindrome.
        """
        return all(s[k] == s[j - k + i] for k in range(i, j + 1))

    left, right = 0, len(s) - 1

    while left < right:
        if s[left] != s[right]:
            # Try to ignore one character from either end
            return is_palindrome_range(left + 1, right) or is_palindrome_range(left, right - 1)
        left += 1
        right -= 1

    # String is already a palindrome
    return True

