def can_construct_network(n, m, pipes):
    from collections import defaultdict
    from itertools import combinations

    def is_connected(graph, n):
        visited = [False] * n
        def dfs(node):
            visited[node] = True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    dfs(neighbor)

        dfs(0)
        return all(visited)

    def remove_edge(graph, u, v):
        graph[u].remove(v)
        graph[v].remove(u)

    def add_edge(graph, u, v):
        graph[u].append(v)
        graph[v].append(u)

    # Build the adjacency list
    graph = defaultdict(list)
    for u, v in pipes:
        add_edge(graph, u, v)

    # Check if the entire graph is initially connected
    if not is_connected(graph, n):
        return "NO"

    # Check connectivity after removing each edge
    for u, v in pipes:
        remove_edge(graph, u, v)
        if not is_connected(graph, n):
            add_edge(graph, u, v)
        else:
            add_edge(graph, u, v)
            return "YES"

    return "NO"

