def min_jumps(arr):
    """
    Function to determine the minimum number of jumps required to reach the end of the array.

    Parameters:
    arr (list): List of integers where each element represents the maximum steps you can move from that position.

    Returns:
    int: Minimum number of jumps required to reach the end of the array.
    """
    if len(arr) <= 1:
        return 0

    if arr[0] == 0:
        return float('inf')

    # initializing variables
    max_reach = arr[0]
    step = arr[0]
    jump = 1

    for i in range(1, len(arr)):
        if i == len(arr) - 1:
            return jump

        max_reach = max(max_reach, i + arr[i])
        step -= 1

        if step == 0:
            jump += 1

            if i >= max_reach:
                return float('inf')

            step = max_reach - i

    return jump

