def calculate_average_rating(movies):
    """
    Calculate the average rating for each movie and round it to the nearest whole number.
    If a movie has no ratings, return 0 as the average rating.

    :param movies: A dictionary where keys are movie titles and values are lists of ratings.
    :return: A dictionary where keys are movie titles and values are average ratings.
    """
    average_ratings = {}
    for movie, ratings in movies.items():
        if ratings:
            average_ratings[movie] = round(sum(ratings) / len(ratings))
        else:
            average_ratings[movie] = 0
    return average_ratings

