from collections import deque

def min_roads_to_travel(n, roads, initial_city, destination_city):
    # Build the adjacency list
    adj_list = {i: [] for i in range(1, n+1)}
    for u, v in roads:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Perform BFS to find the shortest path
    queue = deque([(initial_city, 0)])  # (current_city, distance)
    visited = set()
    visited.add(initial_city)

    while queue:
        current_city, distance = queue.popleft()

        if current_city == destination_city:
            return distance

        for neighbor in adj_list[current_city]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, distance + 1))

    return -1  # This line should never be reached due to the problem constraints

def has_duplicates(matrix):
    """
    Checks if there are duplicates in any row or column of the matrix.
    """
    n = len(matrix)
    m = len(matrix[0])

    # Check rows for duplicates
    for row in matrix:
        if len(set(row)) < len(row):
            return "Yes"

    # Check columns for duplicates
    for col in range(m):
        seen = set()
        for row in range(n):
            if matrix[row][col] in seen:
                return "Yes"
            seen.add(matrix[row][col])

    return "No"

def process_test_cases(test_cases):
    results = []
    for case in test_cases:
        results.append(has_duplicates(case))
    return results

def min_operations_to_sort(arr):
    """
    Returns the minimum number of subarray reversals required to sort the array.
    """
    n = len(arr)
    if sorted(arr) == arr:
        return 0

    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            # If we detect a point where the trend breaks, we need 1 reversal
            return 1

    return 0


def process_test_cases(T, test_cases):
    results = []
    for i in range(T):
        N, A = test_cases[i]
        results.append(min_operations_to_sort(A))
    return results

