def longest_unique_subarray_length(arr, queries):
    def max_unique_in_range(l, r):
        seen = set()
        max_len = 0
        current_len = 0
        for i in range(l, r + 1):
            if arr[i] in seen:
                max_len = max(max_len, current_len)
                seen = set()
                current_len = 0
            seen.add(arr[i])
            current_len += 1
        return max(max_len, current_len)

    results = []
    for l, r in queries:
        results.append(max_unique_in_range(l - 1, r - 1))

    return results

