def rotateClockwise(matrix):
    """
    Rotates the matrix 90 degrees clockwise in-place.
    """
    N = len(matrix)
    M = len(matrix[0])

    # Create a new transposed, reversed matrix
    new_matrix = [[0] * N for _ in range(M)]

    # Populate the new_matrix
    for i in range(N):
        for j in range(M):
            new_matrix[j][N-1-i] = matrix[i][j]

    # Copy new_matrix to the original matrix
    for r in range(M):
        for c in range(N):
            if r < len(matrix) and c < len(matrix[0]):
                matrix[r][c] = new_matrix[r][c]

    # Reshape original matrix if needed
    if len(matrix) != len(new_matrix):
        matrix[:] = new_matrix

    return matrix

