from collections import deque

def bfs(grid, start, end, N, M):
    sx, sy = start
    ex, ey = end
    if grid[sx][sy] == '#' or grid[ex][ey] == '#':
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    visited = [[False] * M for _ in range(N)]
    queue = deque([(sx, sy, 0)])  # (row, col, steps)
    visited[sx][sy] = True

    while queue:
        x, y, steps = queue.popleft()

        if (x, y) == (ex, ey):
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and not visited[nx][ny] and grid[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny, steps + 1))

    return -1

def min_steps_each_robot(N, M, grid, robots):
    results = []
    for (sx, sy, ex, ey) in robots:
        steps = bfs(grid, (sx, sy), (ex, ey), N, M)
        results.append(steps)
    return results

