def find_overlapping_employees(n, tasks):
    from collections import defaultdict

    overlaps = defaultdict(list)
    for task in tasks:
        employee_id, start_time, end_time = task
        if not overlaps[employee_id]:
            overlaps[employee_id].append((start_time, end_time))
        else:
            for s_time, e_time in overlaps[employee_id]:
                if not (end_time <= s_time or start_time >= e_time):
                    return sorted([employee for employee in overlaps.keys()])
            overlaps[employee_id].append((start_time, end_time))
    return []

# Helper function to parse inputs
def parse_input(input_string):
    lines = input_string.strip().split('\n')
    n = int(lines[0])
    tasks = [tuple(map(int, line.split())) for line in lines[1:n+1]]
    return n, tasks

