def evaluate_expression(expression):
    """
    Evaluate a mathematical expression containing integers and operators (+, -, *, /).

    Args:
    expression (str): The mathematical expression to evaluate.

    Returns:
    int: The result of the evaluation.
    """
    stack = []
    num = 0
    sign = "+"
    expression += "+"  # To force the last number to be processed

    for char in expression:
        if char.isdigit():
            num = num * 10 + int(char)
        elif char in "+-*/":
            if sign == "+":
                stack.append(num)
            elif sign == "-":
                stack.append(-num)
            elif sign == "*":
                stack[-1] *= num
            elif sign == "/":
                # Integer division truncates toward zero
                if stack[-1] < 0:
                    stack[-1] = -(-stack[-1] // num)
                else:
                    stack[-1] //= num
            sign = char
            num = 0

    return sum(stack)

