def generate_schedule(N, M, preferences):
    adjacency_list = {i: set() for i in range(1, N+1)}
    for u, v in preferences:
        adjacency_list[u].add(v)
        adjacency_list[v].add(u)

    schedule = []

    # Using a set to keep track of matched pairs to avoid duplicates
    matched_pairs = set()

    for u in range(1, N+1):
        for v in adjacency_list[u]:
            if (u, v) not in matched_pairs and (v, u) not in matched_pairs:
                schedule.append((u, v))
                matched_pairs.add((u, v))

    if len(schedule) < M:
        return -1
    return schedule

