def can_transform(s1, s2):
    """
    Determines if s1 can be transformed into s2 with at most one modification.
    """
    len1, len2 = len(s1), len(s2)

    # If the length difference is more than 1, return False directly
    if abs(len1 - len2) > 1:
        return False

    # Now handle the edit distance of 0 or 1 modification
    if len1 > len2:
        s1, s2 = s2, s1 # Make sure s1 is always the shorter one

    len1, len2 = len(s1), len(s2)
    i, j = 0, 0
    found_difference = False

    while i < len1 and j < len2:
        if s1[i] != s2[j]:
            if found_difference:
                return False
            found_difference = True
            if len1 == len2:
                i += 1 # If lengths are the same, move both pointers
        else:
            i += 1
        j += 1 # Always move pointer for longer string

    return True

def handle_test_cases(test_cases):
    results = []
    for s1, s2 in test_cases:
        if can_transform(s1, s2):
            results.append("Yes")
        else:
            results.append("No")
    return results

