def is_almost_prime(k):
    """
    Determine if a number k is almost prime.
    A number is almost prime if it has exactly three distinct divisors.
    """
    divisors = set()
    for i in range(1, k + 1):
        if k % i == 0:
            divisors.add(i)
        if len(divisors) > 3:
            return "NO"
    return "YES" if len(divisors) == 3 else "NO"

