def char_frequency(s):
    """
    Returns a dictionary with the frequency of each character in the string s.
    The dictionary is sorted by the characters in alphabetical order.
    """
    freq_dict = {}
    for char in s:
        if char in freq_dict:
            freq_dict[char] += 1
        else:
            freq_dict[char] = 1
    return dict(sorted(freq_dict.items()))

