from typing import List, Tuple

def find_submatrix(M: List[List[int]], P: List[List[int]]) -> Tuple[int, int]:
    n, m = len(M), len(M[0])
    k, l = len(P), len(P[0])

    for i in range(n - k + 1):
        for j in range(m - l + 1):
            match = True
            for x in range(k):
                for y in range(l):
                    if M[i + x][j + y] != P[x][y]:
                        match = False
                        break
                if not match:
                    break
            if match:
                return (i, j)

    return (-1, -1)

def find_missing_positive(nums):
    """
    Finds the smallest positive number missing from the list.
    """
    n = len(nums)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            # Swap nums[i] with the number at its correct position
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

# Function to interpret input and output in required format
def smallest_missing_positive_number(n, numbers):
    return find_missing_positive(numbers)

def most_frequent_char(s):
    """
    Returns the most frequently occurring character in the string.
    If there are multiple characters with the same highest frequency,
    returns the alphabetically smallest character.
    Returns an empty string if the input is not a string or is an empty string.
    """
    if not isinstance(s, str) or not s:
        return ""

    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Find the character with the highest frequency and smallest alphabetically in case of a tie
    max_char = ''
    max_count = 0
    for char, count in char_count.items():
        if count > max_count or (count == max_count and char < max_char):
            max_char = char
            max_count = count

    return max_char

