def findMaxInRange(nums, X, Y):
    """
    Returns the maximum integer in the array that is less than or equal to X
    but greater than or equal to Y. If no such number exists, returns -1.
    """
    max_num = -1
    for num in nums:
        if Y <= num <= X:
            if num > max_num:
                max_num = num
    return max_num

