def evalRPN(tokens):
    """
    Evaluates a given RPN (Reverse Polish Notation) expression and returns the result.

    :param tokens: List of strings representing the RPN expression
    :return: Integer result of the RPN expression
    """
    stack = []

    for token in tokens:
        if token in "+-*/":
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                result = a + b
            elif token == '-':
                result = a - b
            elif token == '*':
                result = a * b
            elif token == '/':
                # Ensure integer division truncates towards zero (Python 3's // operator with int cast)
                result = int(a / b)
            stack.append(result)
        else:
            stack.append(int(token))

    return stack[0]

# Example usage:
# print(evalRPN(["2", "1", "+", "3", "*"])) # Output should be 9

