def findLongestSubarray(arr):
    n = len(arr)
    if n == 0:
        return 0

    longest = 1

    for i in range(n - 1):
        min_val = max_val = arr[i]

        for j in range(i + 1, n):
            min_val = min(min_val, arr[j])
            max_val = max(max_val, arr[j])

            if (max_val - min_val) == (j - i):
                longest = max(longest, j - i + 1)

    return longest

