def firstNFibonacci(n):
    """
    Returns a list containing the first n elements of the Fibonacci sequence.
    """
    if n <= 0:
        return []
    elif n == 1:
        return [0]
    fib_sequence = [0, 1]
    for i in range(2, n):
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])
    return fib_sequence

