    i = 1

    # walk up
    while i < n and arr[i] > arr[i - 1]:
        i += 1

    # peak can't be first or last
    if i == 1 or i == n:
        return False

    # walk down
    while i < n and arr[i] < arr[i - 1]:
        i += 1

    return i == n

def min_palindrome_substrings(s: str) -> int:
    """
    Returns the minimum number of contiguous substrings from the given string such that each substring is a palindrome.
    """
    if not s:
        return 0
    if s == s[::-1]:
        return 1
    return len(s)

