import heapq

def find_min_time(N, M, paths):
    from collections import defaultdict
    graph = defaultdict(list)

    for a, b, t in paths:
        graph[a].append((b, t))
        graph[b].append((a, t))

    pq = [(0, 1)]  # (time, attraction)
    dist = {i: float('inf') for i in range(1, N + 1)}
    dist[1] = 0

    while pq:
        current_time, u = heapq.heappop(pq)

        if u == N:
            return current_time

        if current_time > dist[u]:
            continue

        for v, time in graph[u]:
            if current_time + time < dist[v]:
                dist[v] = current_time + time
                heapq.heappush(pq, (dist[v], v))

    return -1 if dist[N] == float('inf') else dist[N]

