def find_largest_plateau(n, heights):
    """
    Finds the largest flat top plateau in terms of number of blocks.

    Parameters:
    n (int): Number of blocks
    heights (list of int): Heights of the blocks

    Returns:
    tuple: Starting index (1-based) and length of the largest plateau. If no plateau is found, returns 0.
    """
    max_length = 0
    max_start_index = -1

    current_length = 1

    for i in range(1, n):
        if heights[i] == heights[i-1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
                max_start_index = i - current_length

            current_length = 1

    if current_length > max_length:
        max_length = current_length
        max_start_index = n - current_length

    if max_length >= 2:
        return (max_start_index + 1, max_length)
    else:
        return 0

