def findLargestSquare(N, M):
    if N == 0:
        return 0

    max_side = 0
    dp = [[0] * N for _ in range(N)]

    for i in range(N):
        for j in range(N):
            if i == 0 or j == 0:
                dp[i][j] = 1
            else:
                if M[i][j] == M[i-1][j] == M[i][j-1] == M[i-1][j-1]:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                else:
                    dp[i][j] = 1
            max_side = max(max_side, dp[i][j])

    return max_side

