def two_sum_indices(arr, target):
    """
    Returns indices of the two numbers from the array that add up to the target.
    """
    num_to_index = {}
    for i, num in enumerate(arr):
        complement = target - num
        if complement in num_to_index:
            return num_to_index[complement], i
        num_to_index[num] = i

def process_input(Q, test_cases):
    results = []
    for i in range(Q):
