def count_unique_and_non_unique_elements(numbers):
    """
    Count the number of unique and non-unique elements in a list.

    Args:
    numbers (list): A list of integers where the end is marked by -1.

    Returns:
    tuple: A tuple with the number of unique elements and non-unique elements.
    """
    num_count = {}
    for num in numbers:
        if num == -1:
            break
        if num in num_count:
            num_count[num] += 1
        else:
            num_count[num] = 1

    unique_count = sum(1 for count in num_count.values() if count == 1)
    non_unique_count = sum(1 for count in num_count.values() if count > 1)

    return unique_count, non_unique_count

