def final_position_and_origin(moves):
    """
    Calculate the final position of the robot and determine if it returns to origin.

    Parameters:
    moves (str): A string representing the moves made by the robot.

    Returns:
    tuple: Final coordinates of the robot and a string "YES" if the robot returns to origin, otherwise "NO".
    """
    x, y = 0, 0

    for move in moves:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return (x, y, "YES" if x == 0 and y == 0 else "NO")

