def min_abs_difference(nums):
    total_sum = sum(nums)
    n = len(nums)
    dp = [False] * (total_sum // 2 + 1)
    dp[0] = True

    for num in nums:
        for s in range(total_sum // 2, num - 1, -1):
            dp[s] = dp[s] or dp[s - num]

    for s in range(total_sum // 2, -1, -1):
        if dp[s]:
            first_part_sum = s
            break

    second_part_sum = total_sum - first_part_sum
    return abs(first_part_sum - second_part_sum)

def min_abs_differences(test_cases):
    results = []
    for nums in test_cases:
        results.append(min_abs_difference(nums))
    return results

