def findSubsets(integers, T):
    """
    Given a set of distinct positive integers, find all subsets that sum up to T.
    """
    result = []

    def backtrack(start, path, target):
        if target == 0:
            result.append(path)
            return
        elif target < 0:
            return

        for i in range(start, len(integers)):
            backtrack(i + 1, path + [integers[i]], target - integers[i])

    backtrack(0, [], T)
    return result

