def longest_run_length(s):
    """
    Returns the length of the longest run of identical characters in the given string.
    """
    if not s:
        return 0

    max_length = current_length = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
        else:
            current_length = 1

    return max_length

