def generate_fizz_list(n, m):
    """
    Generate a list of integers from 1 to n with all multiples of m replaced with "Fizz".

    :param n: int, upper limit of the range
    :param m: int, the divisor for "Fizz"
    :return: list, the generated list with replacements
    """
    if n < 1 or m < 1:
        return []

    result = []
    for i in range(1, n+1):
        if i % m == 0:
            result.append("Fizz")
        else:
            result.append(i)

    return result

