def splitArray(nums, k):
    def can_split(mid):
        current_sum = 0
        subarrays = 1
        for num in nums:
            if current_sum + num > mid:
                subarrays += 1
                current_sum = 0
            current_sum += num
        return subarrays <= k

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1
    return left

