def can_reorder_no_adjacent_same_points(t, cases):
    results = []
    for case in cases:
        n, points = case
        freq = {}
        for p in points:
            if p in freq:
                freq[p] += 1
            else:
                freq[p] = 1

        max_freq = max(freq.values())
        if max_freq > (n + 1) // 2:
            results.append("NO")
        else:
            results.append("YES")
    return results

