def min_total_bonus(T, test_cases):
    results = []

    for case in test_cases:
        N, scores = case
        if N == 0:
            results.append(0)
            continue

        bonuses = [1] * N

        # Left to right pass
        for i in range(1, N):
            if scores[i] > scores[i-1]:
                bonuses[i] = bonuses[i-1] + 1

        # Right to left pass
        for i in range(N-2, -1, -1):
            if scores[i] > scores[i+1]:
                bonuses[i] = max(bonuses[i], bonuses[i+1] + 1)

        results.append(sum(bonuses))

    return results

