def knapsack(t, cases):
    def knapsack_single(n, W, items):
        dp = [[0] * (W + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            for w in range(W + 1):
                if items[i-1][0] <= w:
                    dp[i][w] = max(dp[i-1][w], dp[i-1][w-items[i-1][0]] + items[i-1][1])
                else:
                    dp[i][w] = dp[i-1][w]

        return dp[n][W]

    results = []
    for case in cases:
        n, W, items = case
        result = knapsack_single(n, W, items)
        results.append(result)

    return results

import math

def is_prime(n):
    """
    Helper function to check if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        if n % i == 0:
            return False
    return True

def next_prime(N):
    """
    Function to find the smallest prime number greater than N.
    """
    number = N + 1
    while True:
        if is_prime(number):
            return number
        number += 1

