def longest_increasing_subsequence(heights):
    """
    Returns the length of the longest increasing subsequence.
    """
    if not heights:
        return 0

    # Create an array to store longest increasing subsequence length for each element
    lis = [1] * len(heights)

    # Calculate the LIS values in a bottom up manner
    for i in range(1, len(heights)):
        for j in range(0, i):
            if heights[i] > heights[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # The maximum value in lis[] is the length of the longest increasing subsequence
    return max(lis)

