def schedule_tournament(n):
    if n % 2 != 0 or n < 2 or n > 100:
        return ("NO",)

    rounds = []
    players = list(range(1, n + 1))

    for i in range(n - 1):
        round_matches = []
        for j in range(n // 2):
            player1 = players[j]
            player2 = players[n - 1 - j]
            round_matches.append((player1, player2))
        rounds.append(round_matches)
        # Rotate the array for the next round, fixing the first element
        players = [players[0]] + [players[-1]] + players[1:-1]

    return ("YES", rounds)

# Formatting the output
def format_schedule_tournament(n):
    result = schedule_tournament(n)
    if result[0] == "NO":
        return "NO"
    else:
        output = ["YES"]
        for round_matches in result[1]:
            round_representation = " ".join(f"{p1} {p2}" for p1, p2 in round_matches)
            output.append(round_representation)
        return "\n".join(output)

