def maxPowerOutput(n, d, s, w):
    total_power_output = 0

    for i in range(n):
        if d[i] == s[i]:
            total_power_output += s[i]
        elif d[i] == w[i]:
            total_power_output += w[i]
        else:
            return -1

    return total_power_output

