def two_sum_indices(arr, target):
    """
    Returns the indices of the two numbers in arr that add up to the target.
    """
    index_map = {}
    for i, num in enumerate(arr):
        complement = target - num
        if complement in index_map:
            return sorted([index_map[complement], i])
        index_map[num] = i

