def max_nested_depth(s):
    """
    Determines the deepest level of nested parentheses in the input string.

    Parameters:
    s (str): The input string containing parentheses.

    Returns:
    int: The maximum depth of nested parentheses if properly nested, otherwise -1.
    """
    max_depth = 0
    current_depth = 0
    for char in s:
        if char == "(":
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif char == ")":
            if current_depth == 0:
                return -1  # Unmatched closing parenthesis
            current_depth -= 1
    if current_depth != 0:
        return -1  # Unmatched opening parenthesis
    return max_depth

