def calculate_user_scores(test_cases):
    """
    Calculate and sort user scores based on activity logs.
    """
    results = []
    for case in test_cases:
        activity_entries = case[1:]
        user_scores = {}
        for entry in activity_entries:
            user_id, activity_type = entry.split()
            if user_id not in user_scores:
                user_scores[user_id] = 0
            if activity_type == 'Post':
                user_scores[user_id] += 5
            elif activity_type == 'Comment':
                user_scores[user_id] += 3
            elif activity_type == 'Like':
                user_scores[user_id] += 1

        sorted_users = sorted(user_scores.items(), key=lambda x: (-x[1], x[0]))
        results.append(sorted_users)
    return results

