from typing import List

def minMaxSubarraySum(A: List[int], k: int) -> int:
    def canSplit(mid: int) -> bool:
        current_sum = 0
        parts = 1

        for num in A:
            if current_sum + num > mid:
                parts += 1
                current_sum = num
                if parts > k:
                    return False
            else:
                current_sum += num

        return True

    low, high = max(A), sum(A)

    while low < high:
        mid = (low + high) // 2
        if canSplit(mid):
            high = mid
        else:
            low = mid + 1

    return low

def min_boxes(n, volumes, box_capacity):
    """
    Determine the minimum number of boxes required to pack all the bottles.

    :param n: Number of bottles
    :param volumes: List of volumes of the bottles
    :param box_capacity: Maximum volume a box can hold
    :return: Minimum number of boxes required
    """
    volumes.sort(reverse=True)
    boxes = []

    for volume in volumes:
        placed = False
        for i in range(len(boxes)):
            if boxes[i] + volume <= box_capacity:
                boxes[i] += volume
                placed = True
                break
        if not placed:
            boxes.append(volume)

    return len(boxes)

