def is_consistent_pattern(s, t, u):
    def is_valid_transformation(source, target):
        mapping = {}
        reverse_mapping = {}
        for a, b in zip(source, target):
            if a in mapping and mapping[a] != b:
                return False
            if b in reverse_mapping and reverse_mapping[b] != a:
                return False
            mapping[a] = b
            reverse_mapping[b] = a
        return True

    return "Yes" if is_valid_transformation(s, t) and is_valid_transformation(t, u) else "No"

from typing import List

def numIslands(grid: List[str]) -> int:
    if not grid:
        return 0

    rows, cols = len(grid), len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == '0' or visited[r][c]:
            return
        visited[r][c] = True
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for dr, dc in directions:
            dfs(r + dr, c + dc)

    island_count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '1' and not visited[r][c]:
                dfs(r, c)
                island_count += 1

    return island_count

