def max_consecutive_buildings(n, heights):
    if n == 1:
        return 1

    max_count = 0

    for i in range(n): # Try removing each building once
        new_heights = heights[:i] + heights[i+1:]
        current_count = 1
        max_temp_count = 1

        for j in range(1, n-1):
            if new_heights[j] == new_heights[j-1]:
                current_count += 1
                max_temp_count = max(max_temp_count, current_count)
            else:
                current_count = 1

        max_count = max(max_count, max_temp_count)

    return max_count

