def find_concatenated_word(test_cases):
    results = []
    for words in test_cases:
        found = "No valid word"
        word_set = set(words)
        for word in words:
            for i in range(1, len(word)):
                prefix, suffix = word[:i], word[i:]
                if prefix in word_set and suffix in word_set:
                    found = word
                    break
            if found != "No valid word":
                break
        results.append(found)
    return results

def parse_input(input_string):
    lines = input_string.strip().split('\n')
    T = int(lines[0])
    test_cases = []
    index = 1
    for _ in range(T):
        N = int(lines[index])
        words = lines[index + 1:index + 1 + N]
        test_cases.append(words)
        index += N + 1
    return test_cases

