def min_battery_limit(M, D, positions):
    positions.sort()

    def possible(battery):
        count = 1
        last_position = positions[0]

        for i in range(1, M):
            if (positions[i] - last_position) % (positions[-1] - positions[0] + positions[0]) <= battery:
                continue
            count += 1
            last_position = positions[i]
            if count > D:
                return False
        return True

    low, high = 0, positions[-1] - positions[0]
    result = high

    while low <= high:
        mid = (low + high) // 2
        if possible(mid):
            result = mid
            high = mid - 1
        else:
            low = mid + 1
    return result

