def pacific_atlantic(matrix):
    if not matrix or not matrix[0]:
        return []

    m, n = len(matrix), len(matrix[0])
    pacific_reachable = [[False for _ in range(n)] for _ in range(m)]
    atlantic_reachable = [[False for _ in range(n)] for _ in range(m)]

    def dfs(x, y, reachable):
        reachable[x][y] = True
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < m and 0 <= ny < n and not reachable[nx][ny] and matrix[nx][ny] >= matrix[x][y]:
                dfs(nx, ny, reachable)

    # Initialize borders
    for i in range(m):
        dfs(i, 0, pacific_reachable)
        dfs(i, n - 1, atlantic_reachable)
    for j in range(n):
        dfs(0, j, pacific_reachable)
        dfs(m - 1, j, atlantic_reachable)

    # Find all cells that can reach both oceans
    result = []
    for i in range(m):
        for j in range(n):
            if pacific_reachable[i][j] and atlantic_reachable[i][j]:
                result.append([i, j])

    # Sort the result lexicographically by row and column
    result.sort()
    return result

import math

def checkSquare(num):
    """
    Determines if num is a perfect square and returns the square root.
    If num is a perfect square, returns (squareRoot, True).
    Otherwise, returns (ceilSquareRoot, False).
    """
    sqrt_num = math.isqrt(num)
    if sqrt_num * sqrt_num == num:
        return (sqrt_num, True)
    else:
        return (sqrt_num + 1, False)

