from collections import deque, defaultdict

def shortest_path_length(n, m, edges):
    """
    Returns the length of the shortest path from node 1 to node n in an undirected graph.
    """
    # Create adjacency list from edges
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Perform BFS to find the shortest path from node 1 to node n
    queue = deque([(1, 0)])
    visited = set()

    while queue:
        current_node, distance = queue.popleft()

        if current_node == n:
            return distance

        if current_node not in visited:
            visited.add(current_node)
            for neighbor in graph[current_node]:
                if neighbor not in visited:
                    queue.append((neighbor, distance + 1))

    return -1

