def capitalize_kth_character(s, k):
    """
    Returns a new string where every k-th character in the input string s is capitalized.

    :param s: Input string consisting of lowercase alphabetic characters.
    :param k: The interval of characters to capitalize.
    :return: A new string with every k-th character capitalized.
    """
    if k > len(s):
        return s

    result = []
    for i in range(len(s)):
        if (i + 1) % k == 0:
            result.append(s[i].upper())
        else:
            result.append(s[i])

    return ''.join(result)

