def unique_paths_with_obstacles(grid):
    n = len(grid)
    m = len(grid[0])

    # Create a 2D table to store the number of paths to each cell
    dp = [[0] * m for _ in range(n)]

    # Initialize the starting point
    dp[0][0] = 1 if grid[0][0] == '.' else 0

    # Fill the dp table
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][m-1]

from collections import deque

def sum_of_max_elements(N, K, array):
    if K > N or not array:
        return 0

    deq = deque()
    max_sum = 0

    for i in range(K):
        while deq and array[i] >= array[deq[-1]]:
            deq.pop()
        deq.append(i)

    for i in range(K, N):
        max_sum += array[deq[0]]

        while deq and deq[0] <= i - K:
            deq.popleft()

        while deq and array[i] >= array[deq[-1]]:
            deq.pop()

        deq.append(i)

    max_sum += array[deq[0]]

    return max_sum

