def longest_increasing_arithmetic_subsequence_length(arr):
    """
    Returns the length of the longest subsequence in the array that forms a
    strictly increasing arithmetic progression.
    """

    if len(arr) < 2:
        return 0

    n = len(arr)
    # dp[i][d] will store the length of the longest arithmetic progression
    # ending at index i with common difference d
    dp = {}
    max_length = 1

    for i in range(n):
        for j in range(i):
            diff = arr[i] - arr[j]
            if (j, diff) in dp:
                dp[(i, diff)] = dp[(j, diff)] + 1
            else:
                dp[(i, diff)] = 2  # starting a new subsequence with two elements

            max_length = max(max_length, dp[(i, diff)])

    return max_length

def solve(test_cases):
    results = []

    for n, arr in test_cases:
        results.append(longest_increasing_arithmetic_subsequence_length(arr))

    return results

def minimum_adjacent_swaps(arr):
    """
    Returns the minimum number of adjacent swaps needed to sort the array in non-decreasing order.
    """
    swaps = 0
    n = len(arr)

    # A modified Bubble Sort to count the swaps
    for i in range(n):
        for j in range(0, n-i-1):
            if arr[j] > arr[j+1]:
                # Swap adjacent elements if they are in the wrong order
                arr[j], arr[j+1] = arr[j+1], arr[j]
                swaps += 1

    return swaps

# Input parser
def robotic_assistant(N, array):
    return minimum_adjacent_swaps(array)

