def filter_primes(lst):
    """
    Returns a new list containing only the prime numbers from the given list.

    Args:
    lst: List of integers.

    Returns:
    List of prime integers.
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    return [x for x in lst if is_prime(x)]

