def can_reorder_words(t, test_cases):
    import math
    results = []

    for i in range(t):
        n = test_cases[i * 2]
        words = test_cases[i * 2 + 1]

        first_letter_count = {}
        for word in words:
            first_letter = word[0]
            if first_letter in first_letter_count:
                first_letter_count[first_letter] += 1
            else:
                first_letter_count[first_letter] = 1

        max_count = max(first_letter_count.values())
        if max_count > math.ceil(n / 2):
            results.append("NO")
        else:
            results.append("YES")

    return results

