from typing import List

def energy_state(activities: List[str]) -> str:
    # Energy costs associated with each activity
    energy_costs = {
        "working": 8,
        "exercising": 5,
        "socializing": 3,
        "relaxing": -2,
        "sleeping": -8
    }

    # Calculate the Net Energy Score (NES)
    nes = sum(energy_costs[activity] for activity in activities if activity in energy_costs)

    # Determine the energy state based on the NES
    if nes < 0:
        return 'Exhausted'
    elif 0 <= nes < 10:
        return 'Tired'
    elif 10 <= nes < 20:
        return 'Balanced'
    else:
        return 'Energetic'

