def check_winner(board, n, k):
    def has_winner(char):
        # Check rows
        for row in range(n):
            for col in range(n - k + 1):
                if all(board[row][col + i] == char for i in range(k)):
                    return True

        # Check columns
        for col in range(n):
            for row in range(n - k + 1):
                if all(board[row + i][col] == char for i in range(k)):
                    return True

        # Check diagonals (left to right)
        for row in range(n - k + 1):
            for col in range(n - k + 1):
                if all(board[row + i][col + i] == char for i in range(k)):
                    return True

        # Check diagonals (right to left)
        for row in range(n - k + 1):
            for col in range(k - 1, n):
                if all(board[row + i][col - i] == char for i in range(k)):
                    return True

        return False

    if has_winner('A'):
        return 'Alice'
    elif has_winner('B'):
        return 'Bob'
    else:
        return 'None'

# Function to parse input and call check_winner
def patterndash(n, k, grid):
    return check_winner(grid, n, k)

def find_highest_congestion_stop(m, routes):
    stop_counts = {}

    for route in routes:
        stops = route[1:]
        for stop in stops:
            if stop in stop_counts:
                stop_counts[stop] += 1
            else:
                stop_counts[stop] = 1

    max_congestion = max(stop_counts.values())
    most_congested_stops = [stop for stop, count in stop_counts.items() if count == max_congestion]

    return min(most_congested_stops)

