def text_editor(operations):
    S = ""
    output = []

    for operation in operations:
        parts = operation.split()
        command = parts[0]

        if command == "APPEND":
            W = parts[1]
            S += W
        elif command == "DELETE":
            k = int(parts[1])
            S = S[:-k]
        elif command == "PRINT":
            p = int(parts[1])
            output.append(S[p-1])

    return output

