def capitalize_headings(markdown):
    """
    Returns the markdown document with all the headings capitalized.
    """
    lines = markdown.split('\n')
    result = []

    for line in lines:
        if line.startswith('#'):
            first_space = line.find(' ')
            if first_space != -1:
                heading_text = line[first_space+1:]
                capitalized_heading = line[:first_space+1] + heading_text.upper()
                result.append(capitalized_heading)
            else:
                result.append(line)
        else:
            result.append(line)

    return '\n'.join(result)

