from collections import deque

def min_steps_to_exit(grid, start_x, start_y):
    N = len(grid)
    M = len(grid[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # Right, Down, Left, Up

    # BFS initialization
    queue = deque([(start_x, start_y, 0)])  # store (current_x, current_y, steps)
    visited = set((start_x, start_y))

    while queue:
        x, y, steps = queue.popleft()

        # Check if the current position is at the boundary of the grid (exit points)
        if x == 0 or x == N-1 or y == 0 or y == M-1:
            return steps

        # Explore all 4 possible directions
        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < M and (nx, ny) not in visited and grid[nx][ny] == '.':
                visited.add((nx, ny))
                queue.append((nx, ny, steps + 1))

    return -1  # If no exit is found

def min_steps_grid(N, M, grid, S_x, S_y):
    return min_steps_to_exit(grid, S_x, S_y)

