def lcs_length(P, Q):
    N = len(P)
    M = len(Q)
    dp = [[0] * (M+1) for _ in range(N+1)]

    for i in range(1, N+1):
        for j in range(1, M+1):
            if P[i-1] == Q[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    return dp[N][M]

def min_cost_to_form_lcs(N, M, P, Q):
    lcs_len = lcs_length(P, Q)
    return lcs_len

