def process_grid_operations(n, m, operations):
    grid = [[0] * m for _ in range(n)]

    for op in operations:
        if op[0] == 1:
            x, y, v = op[1], op[2], op[3]
            for i in range(x, n + 1):
                for j in range(y, m + 1):
                    grid[i - 1][j - 1] = v

        elif op[0] == 2:
            x1, y1, x2, y2 = op[1], op[2], op[3], op[4]
            for i in range(x1, x2 + 1):
                for j in range(y1, y2 + 1):
                    grid[i - 1][j - 1] += 1

    return grid

