def can_transform(n, m, matrix_a, matrix_b):
    for j in range(m):
        factor = None
        for i in range(n):
            if matrix_a[i][j] != 0:
                if matrix_b[i][j] % matrix_a[i][j] != 0:
                    return False
                elif factor is None:
                    factor = matrix_b[i][j] // matrix_a[i][j]
                elif factor != matrix_b[i][j] // matrix_a[i][j]:
                    return False
        for i in range(n):
            if factor is not None and matrix_a[i][j] != 0:
                matrix_a[i][j] *= factor

    for i in range(n):
        offset = matrix_b[i][0] - matrix_a[i][0]
        for j in range(m):
            if matrix_a[i][j] + offset != matrix_b[i][j]:
                return False

    return True

def frodo_exploring(t, test_cases):
    results = []
    for case in test_cases:
        n, m = case['n'], case['m']
        matrix_a, matrix_b = case['matrix_a'], case['matrix_b']
        if can_transform(n, m, matrix_a, matrix_b):
            results.append("YES")
        else:
            results.append("NO")
    return results

