def garden_operations(n, m, heights, operations):
    results = []
    for operation in operations:
        if operation[0] == 1:
            _, l, r, h = operation
            for i in range(l - 1, r):
                heights[i] += h
        elif operation[0] == 2:
            _, l, r = operation
            results.append(max(heights[l - 1:r]))
    return results

