def determine_winner(score1, score2, skill1, skill2):
    """
    Determines the winner of the tournament based on the skill levels
    and scores of the two players.

    Parameters:
        score1 (int): The score of player 1.
        score2 (int): The score of player 2.
        skill1 (int): The skill level of player 1.
        skill2 (int): The skill level of player 2.

    Returns:
        str: "Player 1" if player 1 wins, "Player 2" if player 2 wins, "Draw" if it's a draw.
    """
    if skill1 > skill2:
        return "Player 1"
    elif skill2 > skill1:
        return "Player 2"
    else:
        if score1 > score2:
            return "Player 1"
        elif score2 > score1:
            return "Player 2"
        else:
            return "Draw"

