def calculate_total_dispensed_water(t, test_cases):
    results = []

    for i in range(t):
        s, w, c, commands = test_cases[i]
        total_dispensed = 0
        dispensing = False

        for command in commands:
            if command == "start":
                dispensing = True
            elif command == "stop" and dispensing:
                total_dispensed += s
                dispensing = False
            elif command == "reset":
                dispensing = False

        results.append(total_dispensed)

    return results

