def merge_orb_sets(t, test_cases):
    results = []
    for case in test_cases:
        n, m, set1, set2 = case
        merged_set = set(set1 + set2)  # Merge and remove initial duplicates
        duplicates = set(set1).intersection(set2)

        # Remove duplicates
        for item in duplicates:
            merged_set.discard(item)

        sorted_result = sorted(merged_set)
        if sorted_result:
            results.append(' '.join(map(str, sorted_result)))
        else:
            results.append("Empty Set")

    return results

