def separate_characters(s):
    """
    Separates the input string into three categories:
    - all lowercase letters in the order they appear.
    - all digits in the order they appear.
    - all special characters in the order they appear.

    Returns a tuple of three strings in the order of lowercase letters, digits, and special characters.
    """
    letters = []
    digits = []
    special_chars = []

    for char in s:
        if char.islower():
            letters.append(char)
        elif char.isdigit():
            digits.append(char)
        else:
            special_chars.append(char)

    return ''.join(letters), ''.join(digits), ''.join(special_chars)

