def is_subarray(A, N, M, B, P, Q):
    if P > N or Q > M:
        return "NO"
    for i in range(N - P + 1):
        for j in range(M - Q + 1):
            match = True
            for x in range(P):
                for y in range(Q):
                    if A[i + x][j + y] != B[x][y]:
                        match = False
                        break
                if not match:
                    break
            if match:
                return "YES"
    return "NO"

def matrix_subarray(test_cases):
    results = []
    for case in test_cases:
        A, B = case['A'], case['B']
        N, M = case['N'], case['M']
        P, Q = case['P'], case['Q']
        result = is_subarray(A, N, M, B, P, Q)
        results.append(result)
    return results

