def is_alien_sorted(words, order):
    """
    Determine if the given words list is sorted according to the alien language order.

    Parameters:
    words (List[str]): List of words in alien language.
    order (str): The order of characters in the alien language.

    Returns:
    bool: True if words are sorted lexicographically according to the alien language, False otherwise.
    """

    # Create a dictionary to map each character to its position in the alien alphabet
    order_map = {char: index for index, char in enumerate(order)}

    def alien_comparator(word1, word2):
        # Compare each character of the two words
        for c1, c2 in zip(word1, word2):
            if c1 != c2:
                return order_map[c1] < order_map[c2]
        # If all characters were the same but lengths are different, the shorter word should come first
        return len(word1) <= len(word2)

    for i in range(len(words) - 1):
        if not alien_comparator(words[i], words[i + 1]):
            return False

    return True

