import re

def categorize_passwords(n, passwords):
    """
    Categorizes each password as either "weak", "medium", or "strong" based on the defined criteria.

    :param n: Integer, the number of passwords (1 ≤ n ≤ 100)
    :param passwords: List of n passwords, each consisting of letters, digits, and special characters (max length 50)
    :return: List of strings, each representing the strength category of the corresponding password
    """
    def check_strength(password):
        if len(password) < 6:
            return "weak"
        elif 6 <= len(password) < 10:
            if re.search("[a-zA-Z]", password) and re.search("[0-9]", password):
                return "medium"
            else:
                return "weak"
        elif len(password) >= 10:
            if re.search("[a-zA-Z]", password) and re.search("[0-9]", password) and re.search("[^a-zA-Z0-9]", password):
                return "strong"
            else:
                return "medium"
        else:
            return "weak"

    return [check_strength(password) for password in passwords]

