def evaluate_expression(expression):
    def helper(tokens):
        stack = []
        num = 0
        sign = '+'

        while len(tokens) > 0:
            char = tokens.pop(0)

            if char.isdigit():
                num = num * 10 + int(char)
            if char == '(':
                num = helper(tokens)
            if (not char.isdigit() and not char.isspace()) or len(tokens) == 0:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack[-1] = stack[-1] * num
                elif sign == '/':
                    stack[-1] = int(stack[-1] / num)
                sign = char
                num = 0
            if char == ')':
                break

        return sum(stack)

    tokens = list(expression)
    return helper(tokens)

