from typing import List

def multiply_matrices(matrix1: List[List[int]], matrix2: List[List[int]]) -> List[List[int]]:
    # Check if matrices are square and of same size
    if not matrix1 or not matrix2 or len(matrix1) != len(matrix2) or len(matrix1[0]) != len(matrix2[0]):
        return []

    size = len(matrix1)
    result = [[0 for _ in range(size)] for _ in range(size)]

    # Matrix multiplication
    for i in range(size):
        for j in range(size):
            for k in range(size):
                result[i][j] += matrix1[i][k] * matrix2[k][j]

    return result

