def min_operations_to_one(n):
    """
    Returns the minimum number of operations needed to transform n into 1.
    """
    operations = 0
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        operations += 1
    return operations

