def current_occupants(events):
    """
    Function to determine the current occupants inside the building after processing a series of events.

    Args:
    events: list of tuples (timestamp, personID, eventType)

    Returns:
    List of unique personIDs currently inside the building, sorted in ascending order.
    """
    occupant_status = {}

    for timestamp, personID, eventType in events:
        if eventType == "enter":
            occupant_status[personID] = occupant_status.get(personID, 0) + 1
        elif eventType == "exit":
            occupant_status[personID] = occupant_status.get(personID, 0) - 1

    return sorted([person for person, status in occupant_status.items() if status > 0])

