def is_prime(n):
    """
    Helper function to check if a number is a prime.
    """
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while (i * i) <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def sumOfPrimes(arr):
    """
    Returns the sum of all prime numbers in the array.
    """
    return sum(n for n in arr if is_prime(n))

