from collections import deque, defaultdict

def min_specific_intersections(n, roads):
    def bfs(graph, n):
        colors = [-1] * (n + 1)
        specific_count = defaultdict(int)
        q = deque([(1, 0)])
        colors[1] = 0

        while q:
            node, color = q.popleft()
            for neighbor in graph[node]:
                if colors[neighbor] == -1:
                    colors[neighbor] = 1 - color
                    q.append((neighbor, 1 - color))

        for node in range(1, n + 1):
            if len(graph[node]) == 3:
                specific_count[colors[node]] += 1

        return min(specific_count[0], specific_count[1])

    graph = defaultdict(list)
    for x, y in roads:
        graph[x].append(y)
        graph[y].append(x)

    return bfs(graph, n)

from collections import deque

def min_steps(maze, Sx, Sy, Ex, Ey):
    N = len(maze)
    M = len(maze[0])

    if maze[Sx][Sy] == '#' or maze[Ex][Ey] == '#':
        return -1

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    visited = [[False] * M for _ in range(N)]
    queue = deque([(Sx, Sy, 0)])

    visited[Sx][Sy] = True

    while queue:
        x, y, steps = queue.popleft()

        if x == Ex and y == Ey:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < N and 0 <= ny < M and not visited[nx][ny] and maze[nx][ny] == '.':
                visited[nx][ny] = True
                queue.append((nx, ny, steps + 1))

    return -1

def solve_maze(N, M, maze_lines, start_end_positions):
    maze = [list(line) for line in maze_lines]
    Sx, Sy, Ex, Ey = start_end_positions
    return min_steps(maze, Sx, Sy, Ex, Ey)

def check_winner(grid, n):
    # Check rows and columns
    for i in range(n):
        if all(grid[i][j] == 'A' for j in range(n)) or all(grid[j][i] == 'A' for j in range(n)):
            return 'A'
        if all(grid[i][j] == 'B' for j in range(n)) or all(grid[j][i] == 'B' for j in range(n)):
            return 'B'

    # Check main diagonal
    if all(grid[i][i] == 'A' for i in range(n)):
        return 'A'
    if all(grid[i][i] == 'B' for i in range(n)):
        return 'B'

    # Check anti-diagonal
    if all(grid[i][n-i-1] == 'A' for i in range(n)):
        return 'A'
    if all(grid[i][n-i-1] == 'B' for i in range(n)):
        return 'B'

    # Check for draw or pending
    if all(grid[i][j] in ['A', 'B'] for i in range(n) for j in range(n)):
        return 'Draw'

    return 'Pending'


