def longest_equal_positive_negative_subarray(arr):
    """
    Returns the length of the longest subarray with equal numbers of positive and negative integers.
    """
    sum_to_index = {0: -1}
    prefix_sum = 0
    max_length = 0

    for i, num in enumerate(arr):
        if num > 0:
            prefix_sum += 1
        elif num < 0:
            prefix_sum -= 1

        if prefix_sum in sum_to_index:
            max_length = max(max_length, i - sum_to_index[prefix_sum])
        else:
            sum_to_index[prefix_sum] = i

    return max_length

