def is_palindromic(num):
    """
    Helper function to determine if a number is palindromic.
    """
    s = str(num)
    return s == s[::-1]

def has_prime_digits_only(num):
    """
    Helper function to determine if a number contains only prime digits (2, 3, 5, 7).
    """
    prime_digits = {'2', '3', '5', '7'}
    return all(digit in prime_digits for digit in str(num))

def palindromic_prime_digit_numbers(n):
    """
    Returns a list of all integers in the range [1, n] (inclusive) that are palindromic
    and that consist of prime digits only.
    """
    result = []
    for i in range(1, n + 1):
        if is_palindromic(i) and has_prime_digits_only(i):
            result.append(i)
    return result

