def longest_odd_segment(n, a):
    """
    Returns the length of the longest subarray where the number of odd and even numbers are equal.
    """
    # Dictionary to store the first occurrence of a balance value
    balance_map = {0: -1}
    balance = 0
    max_length = 0

    for i in range(n):
        # Increment balance for odd numbers, decrement for even numbers
        if a[i] % 2 == 0:
            balance -= 1
        else:
            balance += 1

        # Check if this balance has been seen before
        if balance in balance_map:
            max_length = max(max_length, i - balance_map[balance])
        else:
            balance_map[balance] = i

    return max_length

