def min_shelves(w, b, box_weights):
    # Sort the weights in descending order to maximize space utilization
    box_weights.sort(reverse=True)
    shelves = []

    for weight in box_weights:
        placed = False
        for shelf in shelves:
            if sum(shelf) + weight <= w:
                shelf.append(weight)
                placed = True
                break
        if not placed:
            shelves.append([weight])

    return len(shelves)

def solve(input_data):
    results = []
    idx = 0
    while idx < len(input_data):
        w, b = input_data[idx]
        if w == 0 and b == 0:
            break
        box_weights = input_data[idx + 1]
        results.append(min_shelves(w, b, box_weights))
        idx += 2
    return results

