def solve(S: str) -> str:
    """
    Finds the first non-repeating character in the string S.
    If all characters are repeating or the string is empty, returns an underscore "_".
    """
    from collections import OrderedDict

    char_count = OrderedDict()

    # Count the occurrences of each character in the string
    for char in S:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Find the first character that has a count of 1
    for char, count in char_count.items():
        if count == 1:
            return char

    # If no character has a count of 1, return underscore
    return "_"

