def longest_increasing_path(palaces):
    """
    Returns the length of the longest strictly increasing path
    in terms of either x or y coordinates from the list of palaces.

    A path is represented as a sequence of coordinates (x, y).
    """
    if not palaces:
        return 0

    def longest_increasing_subsequence(sequence):
        from bisect import bisect_left

        lis = []
        for value in sequence:
            pos = bisect_left(lis, value)
            if pos == len(lis):
                lis.append(value)
            else:
                lis[pos] = value
        return len(lis)

    # Sort palaces by x-coordinate first, then y-coordinate to cover x increasing first
    palaces.sort()
    ys = [y for x, y in palaces]

    return longest_increasing_subsequence(ys)

