def compress_rle(s: str) -> str:
    """
    Compresses the input string using the Run-Length Encoding (RLE) algorithm.
    """
    if not s:
        return ""

    compressed = []
    i = 0
    while i < len(s):
        count = 1
        while (i + 1) < len(s) and s[i] == s[i + 1]:
            i += 1
            count += 1
        compressed.append(f"{s[i]}{count}")
        i += 1

    return "".join(compressed)

def decompress_rle(s: str) -> str:
    """
    Decompresses the RLE-compressed input string into its original form.
    """
    if not s:
        return ""

    decompressed = []
    i = 0
    while i < len(s):
        char = s[i]
        i += 1
        count = 0
        while i < len(s) and s[i].isdigit():
            count = count * 10 + int(s[i])
            i += 1
        decompressed.append(char * count)

    return "".join(decompressed)

def longest_palindromic_substring(s):
    """
    Returns the longest palindromic substring in s.
    If there are multiple such substrings of the same length, returns the first one that appears.
    """
    if not s:
        return ""

    n = len(s)
    start = 0
    max_length = 1

    dp = [[False for _ in range(n)] for _ in range(n)]

    for i in range(n):
        dp[i][i] = True

    for i in range(n - 1):
        if s[i] == s[i + 1]:
            dp[i][i + 1] = True
            start = i
            max_length = 2

    for length in range(3, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if dp[i + 1][j - 1] and s[i] == s[j]:
                dp[i][j] = True
                if length > max_length:
                    start = i
                    max_length = length

    return s[start:start + max_length]

