def smallest_subarray_length(t, test_cases):
    results = []

    for test_case in test_cases:
        n, k, A = test_case
        min_length = float('inf')
        current_sum = 0
        start = 0

        for end in range(n):
            current_sum += A[end]

            while current_sum >= k:
                min_length = min(min_length, end - start + 1)
                current_sum -= A[start]
                start += 1

        if min_length == float('inf'):
            results.append(-1)
        else:
            results.append(min_length)

    return results

