def watch_together(T, test_cases):
    result = []

    for i in range(T):
        U, M, user_data, k = test_cases[i]

        # Convert user data to a dictionary with a set of watched movies for each user
        user_watched = {}
        for user_id, movies in user_data:
            user_watched[user_id] = set(movies)

        # Compare each pair of users
        count_pairs = 0
        user_ids = list(user_watched.keys())
        for j in range(U):
            for l in range(j + 1, U):
                common_movies = user_watched[user_ids[j]].intersection(user_watched[user_ids[l]])
                if len(common_movies) >= k:
                    count_pairs += 1

        result.append(count_pairs)

    return result

