def max_encoded_value(S):
    """
    Given a string S containing uppercase letters and at most one '*',
    returns the maximum possible encoded value after optimally choosing the value of '*'.
    """
    def char_value(char):
        if char == '*':
            return 26  # We assume the maximum value for '*'
        return ord(char) - ord('A') + 1

    total_sum = 0
    for char in S:
        total_sum += char_value(char)

    return total_sum * len(S)

def solve(test_cases):
    results = []
    for case in test_cases:
        results.append(max_encoded_value(case))
    return results

