def min_operations_to_equal_elements(T, test_cases):
    results = []
    for i in range(T):
        n, array = test_cases[i]
        if n == 1:
            results.append(0)
            continue
        unique_elements = set(array)
        if len(unique_elements) == 1:
            results.append(0)
        elif len(unique_elements) > 1:
            results.append(n - 1)
    return results

