def largest_square_submatrix(matrix):
    if not matrix:
        return 0

    M = len(matrix)
    N = len(matrix[0])

    # Create DP table to store size of largest square submatrix ending at each cell
    dp = [[0] * N for _ in range(M)]

    max_size = 0

    # Populate the DP table
    for i in range(M):
        for j in range(N):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_size = max(max_size, dp[i][j])

    return max_size

def int_to_words(num):
    ones = [
        "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine"
    ]
    teens = [
        "ten", "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    ]
    tens = [
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    ]

    if num == 0:
        return "zero"

    words = []

    # Hundreds place
    if num // 100 > 0:
        words.append(ones[num // 100])
        words.append("hundred")
        num = num % 100

    # Tens and Ones places
    if num >= 20:
        words.append(tens[num // 10])
        if num % 10 > 0:
            words.append(ones[num % 10])
    elif num >= 10:
        words.append(teens[num - 10])
    elif num > 0:
        words.append(ones[num])

    return " ".join(words)

from typing import List

def four_sum(arr: List[int], target: int) -> List[List[int]]:
    arr.sort()
    quadruplets = []
    n = len(arr)

    for i in range(n - 3):
        if i > 0 and arr[i] == arr[i-1]:
            continue
        for j in range(i + 1, n - 2):
            if j > i + 1 and arr[j] == arr[j - 1]:
                continue
            left, right = j + 1, n - 1
            while left < right:
                current_sum = arr[i] + arr[j] + arr[left] + arr[right]
                if current_sum == target:
                    quadruplets.append([arr[i], arr[j], arr[left], arr[right]])
                    while left < right and arr[left] == arr[left + 1]:
                        left += 1
                    while left < right and arr[right] == arr[right - 1]:
                        right -= 1
                    left += 1
                    right -= 1
                elif current_sum < target:
                    left += 1
                else:
                    right -= 1

    return quadruplets

