def longest_increasing_sequence(elevations):
    """
    Returns the length of the longest sequence of strictly increasing elevations.
    """
    if len(elevations) < 2:
        return len(elevations)

    max_length = 1
    current_length = 1

    for i in range(1, len(elevations)):
        if elevations[i] > elevations[i - 1]:
            current_length += 1
        else:
            if current_length > max_length:
                max_length = current_length
            current_length = 1

    # Check last sequence
    if current_length > max_length:
        max_length = current_length

    return max_length

