from collections import deque

def min_steps_to_destination(grid, start, destination):
    n = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]  # Up, Down, Left, Right

    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < n and grid[x][y] == '.'

    visited = set()
    queue = deque([(start[0], start[1], 0)])  # (row, col, steps)

    while queue:
        x, y, steps = queue.popleft()
        if (x, y) == destination:
            return steps
        if (x, y) in visited:
            continue
        visited.add((x, y))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and (nx, ny) not in visited:
                queue.append((nx, ny, steps + 1))

    return -1

def process_input(test_cases):
    results = []

    for case in test_cases:
        n, grid, start, destination = case
        result = min_steps_to_destination(grid, start, destination)
        results.append(result)

    return results

def can_transform(s, t, k):
    def edit_distance(s, t):
        m, n = len(s), len(t)
        dp = [[0] * (n + 1) for _ in range(m + 1)]

        for i in range(m + 1):
            for j in range(n + 1):
                if i == 0:
                    dp[i][j] = j
                elif j == 0:
                    dp[i][j] = i
                elif s[i - 1] == t[j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = 1 + min(dp[i][j - 1], dp[i - 1][j], dp[i - 1][j - 1])

        return dp[m][n]

    return 1 if edit_distance(s, t) <= k else 0

