def numDistinctIslands(grid):
    def dfs(x, y, direction, path):
        if x < 0 or x >= len(grid) or y < 0 or y >= len(grid[0]) or grid[x][y] == 0:
            return
        grid[x][y] = 0
        path.append(direction)
        dfs(x + 1, y, 'D', path)
        dfs(x - 1, y, 'U', path)
        dfs(x, y + 1, 'R', path)
        dfs(x, y - 1, 'L', path)
        path.append('B') # Backtracking

    distinct_islands = set()
    for i in range(len(grid)):
        for j in range(len(grid[i])):
            if grid[i][j] == 1:
                path = []
                dfs(i, j, 'S', path) # Start
                distinct_islands.add(tuple(path))
    return len(distinct_islands)

def countDistinctIslands(m, n, grid_str):
    grid = [[int(c) for c in line] for line in grid_str.split()]
    return numDistinctIslands(grid)

