def sum_of_digits(n):
    """
    Helper function to calculate the sum of the digits of a number.
    """
    return sum(int(digit) for digit in str(n))

def find_special_number(x):
    """
    Given an integer x, find the smallest number y (y > x) such that:
    - y is divisible by 3 but not by 9
    - the sum of digits of y is divisible by 3 but not by 9
    """
    y = x + 1
    while True:
        if y % 3 == 0 and y % 9 != 0:
            digit_sum = sum_of_digits(y)
            if digit_sum % 3 == 0 and digit_sum % 9 != 0:
                return y
        y += 1

