def most_frequent_flower(R, C, garden, queries):
    def get_submatrix_frequency(r1, c1, r2, c2):
        frequency = defaultdict(int)
        for i in range(r1, r2 + 1):
            for j in range(c1, c2 + 1):
                frequency[garden[i][j]] += 1
        max_frequency = max(frequency.values())
        most_frequent_flowers = [flower for flower, freq in frequency.items() if freq == max_frequency]
        return min(most_frequent_flowers)

    results = []
    for r1, c1, r2, c2 in queries:
        r1, c1, r2, c2 = r1 - 1, c1 - 1, r2 - 1, c2 - 1
        results.append(get_submatrix_frequency(r1, c1, r2, c2))
    return results

