def max_distinct_cells(R, C, grid):
    """
    Returns the maximum number of distinct cells Miro can visit on his path from (1, 1) to (R, C).
    """
    if grid[0][0] == '#' or grid[R-1][C-1] == '#':
        return -1  # No path if starting or ending cells are obstacles

    # Initialize a 2D list to store the maximum cells visited up to each cell
    dp = [[0] * C for _ in range(R)]

    for i in range(R):
        for j in range(C):
            if grid[i][j] == '#':
                dp[i][j] = -1
            else:
                current_max = 0
                if i > 0 and dp[i-1][j] != -1:
                    current_max = max(current_max, dp[i-1][j])
                if j > 0 and dp[i][j-1] != -1:
                    current_max = max(current_max, dp[i][j-1])
                dp[i][j] = current_max + 1

    return dp[R-1][C-1] if dp[R-1][C-1] != -1 else -1

