def most_frequent_theme(n, m, instructions):
    # Initialize the table with no theme (represented by 0)
    table = [0] * n

    # Apply each instruction to the table
    for a, b, t in instructions:
        for i in range(a-1, b):
            table[i] = t

    # Count the frequencies of each theme
    frequencies = {}
    for theme in table:
        if theme in frequencies:
            frequencies[theme] += 1
        else:
            frequencies[theme] = 1

    # Find the most frequent theme, and in case of ties, the smallest ID
    max_frequency = 0
    most_frequent_theme_id = float('inf')
    for theme, frequency in frequencies.items():
        if frequency > max_frequency or (frequency == max_frequency and theme < most_frequent_theme_id):
            max_frequency = frequency
            most_frequent_theme_id = theme

    return most_frequent_theme_id

