from itertools import permutations

def can_rearrange_words(words):
    """
    Determines if the sequence of words can be rearranged such that the last character of each word
    matches the first character of the next word in the sequence.
    """
    for perm in permutations(words):
        if all(perm[i][-1] == perm[i+1][0] for i in range(len(perm) - 1)):
            return "yes"
    return "no"

