from typing import List, Tuple

def maze_solver(maze: List[List[int]], start: Tuple[int, int]) -> bool:
    """
    Determines if there is a path from start position to the exit in the maze.

    Parameters:
    maze (List[List[int]]): A two-dimensional list representing the maze.
    start (Tuple[int, int]): The starting position (row, column).

    Returns:
    bool: True if there is a path from start to exit, otherwise False.
    """

    rows, cols = len(maze), len(maze[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def is_exit(r, c):
        return maze[r][c] == 2

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols and maze[r][c] != 1

    def dfs(r, c):
        if not is_valid(r, c) or maze[r][c] == -1:
            return False

        if is_exit(r, c):
            return True

        # mark the current cell as visited
        maze[r][c] = -1

        for dr, dc in directions:
            if dfs(r + dr, c + dc):
                return True

        return False

    start_row, start_col = start
    return dfs(start_row, start_col)

