def sumSubmatrix(matrix, queries):
    """
    Returns the sum of the elements in the specified submatrices.
    """
    result = []
    for x1, y1, x2, y2 in queries:
        submatrix_sum = 0
        for i in range(x1, x2 + 1):
            for j in range(y1, y2 + 1):
                submatrix_sum += matrix[i][j]
        result.append(submatrix_sum)
    return result

def update_flower_beds(flower_beds, i, x):
    flower_beds[i - 1] = x

def query_flower_beds(flower_beds, l, r):
    return len(set(flower_beds[l - 1:r]))

def process_operations(n, m, q, initial_flower_beds, operations):
    results = []
    flower_beds = initial_flower_beds[:]

    for operation in operations:
        op_type = operation[0]
        if op_type == 1:
            i, x = operation[1], operation[2]
            update_flower_beds(flower_beds, i, x)
        elif op_type == 2:
            l, r = operation[1], operation[2]
            result = query_flower_beds(flower_beds, l, r)
            results.append(result)

    return results

