def max_in_columns(matrix):
    """
    Returns a list of the maximum elements from each column in the matrix.

    :param matrix: List of lists where each sublist represents a row in the matrix
    :return: List of integers representing the maximum elements from each column
    """
    if not matrix or not matrix[0]:
        return []

    num_cols = len(matrix[0])
    max_elements = [float('-inf')] * num_cols

    for row in matrix:
        for col_index in range(num_cols):
            if row[col_index] > max_elements[col_index]:
                max_elements[col_index] = row[col_index]

    return max_elements

