def count_ways(n):
    """
    Returns the number of distinct ways to reach the top of a staircase with n steps,
    where one can take 1, 2, or 3 steps at a time.
    """
    if n == 0:
        return 0
    if n == 1:
        return 1
    if n == 2:
        return 2
    if n == 3:
        return 4

    ways = [0] * (n + 1)
    ways[1] = 1
    ways[2] = 2
    ways[3] = 4

    for i in range(4, n + 1):
        ways[i] = ways[i - 1] + ways[i - 2] + ways[i - 3]

    return ways[n]

