def longest_zigzag_subsequence_length(arr):
    """
    Returns the length of the longest zigzag subsequence in an array.
    """
    n = len(arr)
    if n == 0:
        return 0

    up = down = 1

    for i in range(1, n):
        if arr[i] > arr[i - 1]:
            up = down + 1
        elif arr[i] < arr[i - 1]:
            down = up + 1

    return max(up, down)

