import heapq

def minRemainingTime(tasks):
    if not tasks:
        return 0

    # Convert into a max-heap by negating the values
    tasks = [-task for task in tasks]
    heapq.heapify(tasks)

    while len(tasks) > 1:
        largest = -heapq.heappop(tasks)
        second_largest = -heapq.heappop(tasks)

        if largest > second_largest:
            heapq.heappush(tasks, -(largest - second_largest))

    return -tasks[0] if tasks else 0

