def min_replacements_to_beautiful_string(t, test_cases):
    results = []
    for i in range(t):
        n, s = test_cases[i]
        replacements = 0
        for j in range(1, n):
            if s[j] == s[j-1]:
                replacements += 1
                # Change current character to something different
                s = s[:j] + ('a' if s[j] != 'a' else 'b') + s[j+1:]
        results.append(replacements)
    return results

