def maxSquareSize(matrix):
    """
    Returns the size of the largest square sub-matrix of 1's.

    Args:
    matrix: List[List[int]] - 2D list representing the matrix.

    Returns:
    int - size of the largest square sub-matrix of 1's.
    """
    if not matrix or not matrix[0]:
        return 0

    n = len(matrix)
    m = len(matrix[0])

    # Create a DP array and initialize it with 0's.
    dp = [[0] * m for _ in range(n)]

    max_size = 0

    for i in range(n):
        for j in range(m):
            if matrix[i][j] == 1:
                if i == 0 or j == 0:
                    dp[i][j] = 1  # The edge cells copy the same value as matrix
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                if dp[i][j] > max_size:
                    max_size = dp[i][j]

    return max_size

