def can_partition(t, test_cases):
    results = []
    for n, k, a in test_cases:
        total_sum = sum(a)
        if total_sum % k != 0:
            results.append("NO")
            continue

        target_sum = total_sum // k
        a.sort(reverse=True)
        partitions = [0] * k

        def can_partition_recursive(index):
            if index == n:
                return all(partition == target_sum for partition in partitions)
            for i in range(k):
                if partitions[i] + a[index] <= target_sum:
                    partitions[i] += a[index]
                    if can_partition_recursive(index + 1):
                        return True
                    partitions[i] -= a[index]
                if partitions[i] == 0:
                    break
            return False

        if can_partition_recursive(0):
            results.append("YES")
        else:
            results.append("NO")

    return results

