def generate_strings(N):
    """
    Generates all strings of length N using the characters 'a', 'b', and 'c' in lexicographical order.
    """
    def backtrack(current_string, length):
        if length == N:
            results.append(current_string)
            return
        for char in 'abc':
            backtrack(current_string + char, length + 1)

    results = []
    backtrack('', 0)
    return results

