def compare_geometric_sum(a1, r, n, x):
    """
    Compares the sum of the first n terms of a geometric sequence with a given value x.

    :param a1: First term of the geometric sequence (a_1)
    :param r: Common ratio of the geometric sequence (r)
    :param n: Number of terms (n)
    :param x: Value to compare against (x)
    :return: 'GREATER', 'EQUAL' or 'LESS' based on the comparison
    """
    if r == 1:
        sum_n = a1 * n
    else:
        sum_n = a1 * (1 - r**n) / (1 - r)
    if sum_n > x:
        return "GREATER"
    elif sum_n == x:
        return "EQUAL"
    else:
        return "LESS"

def countPairs(arr, X):
    """
    Returns the number of pairs (i, j) in the given array such that arr[i] + arr[j] <= X and i != j.
    """
    count = 0
    n = len(arr)

    for i in range(n):
        for j in range(i + 1, n):
            if arr[i] + arr[j] <= X:
                count += 1

    return count

