def min_operations_to_all_ones(s):
    """
    Returns the minimum number of operations required to transform the binary string 's' to a string of all '1's.
    """
    # If the string is empty or already all 1's, return 0.
    if not s or all(char == '1' for char in s):
        return 0

    # Count the number of contiguous '0' chunks
    count = 0
    in_zero_part = False
    for char in s:
        if char == '0':
            if not in_zero_part:
                count += 1
                in_zero_part = True
        else:
            in_zero_part = False

    return count

