def get_ranking_class(points):
    """
    Returns the ranking class based on the given points.
    """
    if points < 0 or points > 1000:
        raise ValueError("Points should be between 0 and 1000 inclusive")

    if points < 100:
        return 'E'
    elif points < 200:
        return 'D'
    elif points < 300:
        return 'C'
    elif points < 400:
        return 'B'
    elif points < 500:
