from collections import defaultdict, deque

def find_task_order(T, test_cases):
    def topological_sort(N, adj_list):
        in_degree = [0] * (N + 1)
        for u in range(1, N + 1):
            for v in adj_list[u]:
                in_degree[v] += 1

        queue = deque([i for i in range(1, N + 1) if in_degree[i] == 0])
        order = []

        while queue:
            node = queue.popleft()
            order.append(node)
            for neighbor in adj_list[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        if len(order) == N:
            return order
        else:
            return -1

    results = []

    for case in test_cases:
        N, M, edges = case
        adj_list = defaultdict(list)
        for u, v in edges:
            adj_list[u].append(v)

        order = topological_sort(N, adj_list)
        if order == -1:
            results.append("-1")
        else:
            results.append(" ".join(map(str, order)))

    return results

