def final_variable_state(commands):
    """
    Returns the final state of the variable after executing all the commands.
    """
    variable = 0
    for command in commands:
        operation, x = command.split()
        x = int(x)
        if operation == "add":
            variable += x
        elif operation == "subtract":
            variable -= x
        elif operation == "multiply":
            variable *= x
        elif operation == "divide":
            variable //= x
    return variable

