def longest_scenic_segment(n, elevations):
    if n == 1:
        return 1

    max_length = 1
    current_length = 1

    for i in range(1, n):
        if elevations[i] > elevations[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

