def is_valid_parentheses(s):
    """
    Determines if the input string has valid matching and properly nested parentheses.
    Returns "YES" if the string is valid, otherwise returns "NO".
    """
    stack = []
    matching_parentheses = {")": "(", "}": "{", "]": "["}

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses.keys():
            if stack == [] or matching_parentheses[char] != stack.pop():
                return "NO"
        else:
            return "NO"  # Invalid character

    return "YES" if not stack else "NO"

def two_sum(nums, target):
    """
    Returns the indices of the two numbers such that they add up to the target.

    :param nums: List of integers
    :param target: Target integer
    :return: List containing two indices
    """
    seen = {}
    for i, num in enumerate(nums):
        complement = target - num
        if complement in seen:
            return [seen[complement], i]
        seen[num] = i

