def gardening_schedule(T, test_cases):
    result = []

    for case in test_cases:
        n, m = case
        slots_per_participant = m
        result.append(str(slots_per_participant * n))

        for p in range(1, n + 1):
            start_time = 1
            for _ in range(slots_per_participant):
                result.append(f"{p} {start_time} {start_time + 1}")
                start_time += 2

    return result

