    return '\n'.join(gardening_schedule(T, test_cases))

from collections import defaultdict

def top_k_scores(n, scores, k):
    player_scores = defaultdict(set)

    for player_id, score in scores:
        player_scores[player_id].add(score)

    result = []
    for player_id in sorted(player_scores.keys()):
        top_scores = sorted(player_scores[player_id], reverse=True)[:k]
        result.append((player_id, top_scores))

    return result

