from collections import Counter

def find_anagrams(s, p):
    if len(p) > len(s):
        return []

    p_count = Counter(p)
    s_count = Counter(s[:len(p) - 1])

    result = []
    for i in range(len(p) - 1, len(s)):
        s_count[s[i]] += 1   # include a new character in the window

        # This step is to compare window with p_count dictionary
        if s_count == p_count:
            result.append(i - len(p) + 1)

        s_count[s[i - len(p) + 1]] -= 1  # remove the leftmost character of the window
        if s_count[s[i - len(p) + 1]] == 0:
            del s_count[s[i - len(p) + 1]]  # clean up the dictionary

    return result

