def can_form_k_teams(n, k, skills):
    total_skill = sum(skills)
    min_team_sum = total_skill // k
    max_team_sum = min_team_sum + 1
    num_teams_with_max_sum = total_skill % k

    return all(skill <= max_team_sum for skill in skills) and num_teams_with_max_sum <= k

def is_possible_to_form_teams(n, k, skills):
    if k > n:
        return "NO"
    if can_form_k_teams(n, k, skills):
        return "YES"
    else:
        return "NO"

