def assign_rooms(r, d, requests):
    rooms = [False] * r
    patient_results = []
    current_room = 0

    for req in requests:
        if req == "doctor":
            while current_room < r and rooms[current_room]:
                current_room += 1
            if current_room < r:
                rooms[current_room] = True
        elif req == "patient":
            while current_room < r and rooms[current_room]:
                current_room += 1
            if current_room < r:
                patient_results.append(current_room + 1)
                rooms[current_room] = True
            else:
                patient_results.append(-1)

    return patient_results

