def can_press_k_consecutive_tiles(n, k, tile_sequence):
    if k == 1:
        return "yes"

    for i in range(n - k + 1):
        valid_sequence = True
        for j in range(i, i + k - 1):
            if tile_sequence[j] == tile_sequence[j + 1]:
                valid_sequence = False
                break
        if valid_sequence:
            return "yes"

    return "no"

def solve_sudoku(board):
    """
    Solves the given Sudoku board in-place and returns True if a solution exists, else False.
    """
    def is_valid(board, row, col, num):
        # Check if num is not in the current row
        for x in range(9):
            if board[row][x] == num:
                return False

        # Check if num is not in the current column
        for x in range(9):
            if board[x][col] == num:
                return False

        # Check if num is not in the current 3x3 box
        start_row, start_col = 3 * (row // 3), 3 * (col // 3)
        for i in range(3):
            for j in range(3):
                if board[i + start_row][j + start_col] == num:
                    return False

        return True

    def solve(board):
        for row in range(9):
            for col in range(9):
                if board[row][col] == 0:
                    for num in range(1, 10):
                        if is_valid(board, row, col, num):
                            board[row][col] = num
                            if solve(board):
                                return True
                            board[row][col] = 0
                    return False
        return True

    return solve(board)

def rearrange_to_palindrome(s):
    from collections import Counter

    def is_palindrome_formable(counter):
        odd_count = sum(1 for count in counter.values() if count % 2 != 0)
        return odd_count <= 1

    counter = Counter(s)

    if not is_palindrome_formable(counter):
        return "IMPOSSIBLE"

    half = []
    middle = []
    for char in sorted(counter):
        half.extend(char * (counter[char] // 2))
        if counter[char] % 2 == 1:
            middle = [char]

    half_str = ''.join(half)
    return half_str + ''.join(middle) + half_str[::-1]

