def max_subsequence_sum(nums):
    """
    Returns the maximum sum of any non-empty sub-sequence of the input list of integers.
    """
    # Include only positive numbers to maximize the sum
    positive_sum = sum(x for x in nums if x > 0)

    # If there are no positive numbers, return the maximum negative number
    if positive_sum == 0:
        return max(nums)

    return positive_sum

