from collections import deque

def min_knight_moves(n, x, y):
    directions = [
        (2, 1), (1, 2), (-1, 2), (-2, 1),
        (-2, -1), (-1, -2), (1, -2), (2, -1)
    ]

    start = (1, 1)
    target = (x, y)
    if start == target:
        return 0

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (curr_x, curr_y), dist = queue.popleft()
        for dx, dy in directions:
            new_x, new_y = curr_x + dx, curr_y + dy
            if (new_x, new_y) == target:
                return dist + 1
            if 1 <= new_x <= n and 1 <= new_y <= n and (new_x, new_y) not in visited:
                visited.add((new_x, new_y))
                queue.append(((new_x, new_y), dist + 1))

    return -1

def solve_knight_moves(T, cases):
    results = []
    for n, x, y in cases:
        results.append(min_knight_moves(n, x, y))
    return results

