def treasure_hunt(n, m, queries, k, treasure_positions):
    treasures = {}
    found_treasures = set()

    for r, c, t in treasure_positions:
        treasures[(r, c)] = t

    results = []
    for query in queries:
        query_type, value = query
        if query_type == 1:
            r, c = value
            if (r, c) in treasures and treasures[(r, c)] not in found_treasures:
                found_treasures.add(treasures[(r, c)])
        elif query_type == 2:
            t = value
            results.append("YES" if t in found_treasures else "NO")

    return results

def is_valid_parentheses(s):
    """
    Verifies whether a given sequence of parentheses is valid.
    Parameters:
    s (str): Input string containing parentheses.

    Returns:
    str: "YES" if the sequence is valid, "NO" otherwise.
    """
    stack = []
    matching_parentheses = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses.keys():
            if stack == [] or stack.pop() != matching_parentheses[char]:
                return "NO"
        else:
            return "NO"

    return "YES" if stack == [] else "NO"

