def minStudentsToRemove(heights):
    def length_of_lis(arr):
        from bisect import bisect_left
        lis = []
        for num in arr:
            pos = bisect_left(lis, num)
            if pos == len(lis):
                lis.append(num)
            else:
                lis[pos] = num
        return len(lis)

    n = len(heights)
    lis_length = length_of_lis(heights)
    return n - lis_length

