def longest_non_repeating_substring(s):
    """
    Returns the longest substring without repeating characters.
    If there are multiple substrings of the same length, the first one is returned.
    """
    char_index = {}
    longest_substr = ""
    start = 0

    for end, char in enumerate(s):
        if char in char_index and char_index[char] >= start:
            start = char_index[char] + 1
        char_index[char] = end
        if end - start + 1 > len(longest_substr):
            longest_substr = s[start:end+1]

    return longest_substr

