import math
from typing import List

def gcd_subarray(n: int, q: int, array: List[int], queries: List[List[int]]) -> List[int]:
    result = []
    for l, r in queries:
        subarray_gcd = array[l-1]
        for i in range(l, r):
            subarray_gcd = math.gcd(subarray_gcd, array[i])
        result.append(subarray_gcd)
    return result

