import heapq

def find_minimum_toll(n, m, edges, k, queries):
    # Create adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v, c in edges:
        adj[u].append((v, c))
        adj[v].append((u, c))

    # Dijkstra to find minimum toll cost between all pairs of cities
    def dijkstra(source):
        dist = [float('inf')] * (n + 1)
        dist[source] = 0
        pq = [(0, source)]
        while pq:
            current_dist, u = heapq.heappop(pq)
            if current_dist > dist[u]:
                continue
            for v, weight in adj[u]:
                if dist[u] + weight < dist[v]:
                    dist[v] = dist[u] + weight
                    heapq.heappush(pq, (dist[v], v))
        return dist

    results = []
    for a, b, max_budget in queries:
        dist_from_a = dijkstra(a)
        if dist_from_a[b] <= max_budget:
            results.append(f"YES {dist_from_a[b]}")
        else:
            results.append("NO")

    return results

def min_swaps_to_transform(initial, target):
    if sorted(initial) != sorted(target):
        return -1

    index_dict = {v: i for i, v in enumerate(target)}
    for i in range(len(initial)):
        initial[i] = index_dict[initial[i]]

    visited = [False] * len(initial)
    swaps = 0

    for i in range(len(initial)):
        if visited[i] or initial[i] == i:
            continue

        cycle_size = 0
        x = i
        while not visited[x]:
            visited[x] = True
            x = initial[x]
            cycle_size += 1

        if cycle_size > 0:
            swaps += (cycle_size - 1)

    return swaps

# Function to be called
def min_swaps_helper(N, initial, target):
    return min_swaps_to_transform(initial, target)

