def max_height_difference(n, activities):
    """
    Returns the maximum height difference at each unique timestamp in ascending order.
    """
    height_map = {}

    for t, d in activities:
        if t in height_map:
            height_map[t] = max(height_map[t], d)
        else:
            height_map[t] = d

    result = sorted(height_map.items())
    return result

