def decode_string(s: str) -> str:
    def decode(index):
        result = ""
        k = 0

        while index < len(s):
            if s[index].isdigit():
                k = k * 10 + int(s[index])
            elif s[index] == '[':
                decoded_string, end_index = decode(index + 1)
                result += k * decoded_string
                k = 0
                index = end_index
            elif s[index] == ']':
                return result, index
            else:
                result += s[index]
            index += 1

        return result, index

    decoded_string, _ = decode(0)
    return decoded_string

