from typing import List

def can_partition(nums: List[int]) -> bool:
    total = sum(nums)

    # If the total sum is odd, it's impossible to partition it into two equal parts
    if total % 2 != 0:
        return False

    target = total // 2
    dp = [False] * (target + 1)
    dp[0] = True

    for num in nums:
        for i in range(target, num - 1, -1):
            dp[i] = dp[i] or dp[i - num]

    return dp[target]

