def can_schedule_all_appointments(I, A, interviewers, applicants):
    # Convert interviewer availability into intervals
    available_intervals = []
    for i in range(I):
        start, end = interviewers[i]
        available_intervals.append((start, end))

    # Sort available intervals by start time
    available_intervals.sort()

    for start_time, duration in applicants:
        needed_end_time = start_time + duration
        can_schedule = False
        for index, (int_start, int_end) in enumerate(available_intervals):
            if int_start <= start_time < int_end and needed_end_time <= int_end:
                # Remove this interval to ensure it is not used again
                available_intervals.pop(index)
                can_schedule = True
                break
        if not can_schedule:
            return "NO"

    return "YES"

def find_subarray_with_sum(T, test_cases):
    results = []
    for i in range(T):
        n, S = test_cases[i][0]
        arr = test_cases[i][1]

        current_sum = 0
        start_index = 0
        found = False

        for end_index in range(n):
            current_sum += arr[end_index]

            while current_sum > S and start_index <= end_index:
                current_sum -= arr[start_index]
                start_index += 1

            if current_sum == S:
                results.append(f"{start_index + 1} {end_index + 1}")
                found = True
                break

        if not found:
            results.append("-1")

    return results

def find_minimized_max_edge(n, coordinates):
    import heapq

    # Helper function to calculate Manhattan distance
    def manhattan_dist(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    # Create all edges with their Manhattan distances
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            distance = manhattan_dist(coordinates[i], coordinates[j])
            edges.append((distance, i, j))

    # Kruskal's algorithm to find MST
    edges.sort()
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    mst_max_edge = 0
    for distance, u, v in edges:
        if find(u) != find(v):
            union(u, v)
            mst_max_edge = distance
            # If MST is connected with all n nodes
            if len(set(find(x) for x in range(n))) == 1:
                break

    return mst_max_edge

