def sum_of_absolute_differences(T, test_cases):
    results = []

    for i in range(T):
        N = test_cases[i][0]
        sequence = test_cases[i][1]

        sum_abs_diff = 0
        for j in range(N):
            for k in range(j + 1, N):
                sum_abs_diff += abs(sequence[j] - sequence[k])

        results.append(sum_abs_diff)

    return results

