from collections import defaultdict

def find_max_rating_users(M, messages):
    rating_counts = defaultdict(lambda: defaultdict(int))

    for user_id, message_id, rating_value in messages:
        rating_counts[rating_value][user_id] += 1

    result = []

    for rating_value in range(1, 6):
        users = rating_counts[rating_value]
        if users:
            max_ratings = max(users.values())
            max_users = [user for user, count in users.items() if count == max_ratings]
            result.append(min(max_users))
        else:
            result.append("No ratings")

    return result

def average_positive_numbers(numbers):
    """
    Returns the average of positive numbers in the list.
    If there are no positive numbers, returns 0.
    """
    positive_numbers = [num for num in numbers if num > 0]
    if not positive_numbers:
        return 0
    return sum(positive_numbers) / len(positive_numbers)

