def min_moves_to_remove_palindromes(T, strings):
    def is_palindrome(s):
        return s == s[::-1]

    result = []
    for s in strings:
        if is_palindrome(s):
            result.append(1)
        else:
            result.append(2 if not is_palindrome(s[::-1]) else 1)
    return result

def transform_strings(k, test_cases):
    def get_operations(n, s, t):
        operations = []

        # Step 1: Align characters by swap if needed
        s = list(s)
        for i in range(n):
            if s[i] != t[i]:
                for j in range(i+1, n):
                    if s[j] == t[i]:
                        # Swap s[i] and s[j]
                        s[i], s[j] = s[j], s[i]
                        operations.append(f"1 {i+1}")
                        break

        # Step 2: Replace characters to match target
        s = list(s)
        for i in range(n):
            if s[i] != t[i]:
                operations.append(f"2 {i+1} {t[i]}")

        return operations

    results = []
    for i in range(k):
        n = test_cases[i][0]
        s = test_cases[i][1]
        t = test_cases[i][2]
        operations = get_operations(n, s, t)
        results.append((len(operations), operations))
    return results

def longest_contiguous_subarray(test_cases):
    results = []
    for case in test_cases:
        n, array = case
        max_len = 1
        current_len = 1
        for i in range(1, n):
            if array[i] == array[i-1]:
                current_len += 1
                if current_len > max_len:
                    max_len = current_len
            else:
                current_len = 1
        results.append(max_len)
    return results

