from typing import List, Tuple

def twoSum(nums: List[int], target: int) -> Tuple[int, int]:
    """
    Returns the indices of the two numbers such that they add up to target.
    """
    num_to_index = {}

    for i, num in enumerate(nums):
        difference = target - num
        if difference in num_to_index:
            return (num_to_index[difference], i)
        num_to_index[num] = i

    return (-1, -1)

