def sieve_of_eratosthenes(limit):
    prime = [True] * (limit + 1)
    p = 2
    while (p * p <= limit):
        if (prime[p] == True):
            for i in range(p * p, limit + 1, p):
                prime[i] = False
        p += 1
    prime[0], prime[1] = False, False
    return prime


def count_ones_in_range(L, R, prime):
    return sum(prime[L:R+1])


def process_queries(T, queries):
    max_R = max(r for _, r in queries)
    prime = sieve_of_eratosthenes(max_R)

    results = []
    for L, R in queries:
        results.append(count_ones_in_range(L, R, prime))
    return results

def extract_house_number(label):
    """
    Extracts the house number from the package label which is guaranteed to have digits only at the end.
    """
    house_number = ''

    # Traverse the string in the reverse order to find the digits at the end
    for char in reversed(label):
        if char.isdigit():
            house_number = char + house_number
        else:
            break

    return int(house_number)

