def can_be_sorted_by_one_change(sequence):
    n = len(sequence)

    # Helper function to check if a sequence is sorted in non-decreasing order
    def is_sorted(seq):
        return all(seq[i] <= seq[i + 1] for i in range(len(seq) - 1))

    if is_sorted(sequence):
        return sequence  # Already sorted

    # Find the first position where the sequence is not sorted
    for i in range(n - 1):
        if sequence[i] > sequence[i + 1]:
            break
    else:
        # If no break statement encountered, the sequence is sorted
        return sequence

    # Try changing sequence[i]
    original_value = sequence[i]
    sequence[i] = sequence[i + 1]
    if is_sorted(sequence):
        return sequence

    # Restore the original value and try changing sequence[i + 1]
    sequence[i] = original_value
    sequence[i + 1] = sequence[i]
    if is_sorted(sequence):
        return sequence

    # If neither modification works, return -1
    return -1

# Wrapper function to fit the required input-output format
def sequence_sort_check(n, seq):
    result = can_be_sorted_by_one_change(seq)
    if result == -1:
        return -1
    else:
        return result

