def get_maximum_height(trees, start_index):
    from collections import deque

    def is_adjacent(tree1, tree2):
        x1, y1, _ = tree1
        x2, y2, _ = tree2
        return (x1 == x2 and abs(y1 - y2) == 1) or (y1 == y2 and abs(x1 - x2) == 1)

    n = len(trees)
    start_tree = trees[start_index - 1]
    max_height = start_tree[2]
    visited = [False] * n
    queue = deque([start_index - 1])

    while queue:
        current = queue.popleft()
        if visited[current]:
            continue
        visited[current] = True
        current_tree = trees[current]
        for i in range(n):
            if not visited[i] and is_adjacent(current_tree, trees[i]) and trees[i][2] >= current_tree[2]:
                queue.append(i)
                max_height = max(max_height, trees[i][2])

    return max_height

def max_height_from_each_test_case(T, test_cases):
    results = []
    for i in range(T):
        N = test_cases[i][0]
        trees = test_cases[i][1]
        S = test_cases[i][2]
        results.append(get_maximum_height(trees, S))
    return results

def equidistant_cells(T, test_cases):
    results = []

    for case in test_cases:
        N, M = case
        equidistant_positions = []

        for i in range(N):
            for j in range(M):
                if i == N-1-i and j == M-1-j:
                    equidistant_positions.append((i, j))

        if equidistant_positions:
            results.append(equidistant_positions)
        else:
            results.append("No cells")

    return results

