from collections import deque, defaultdict
import sys

def minimum_assembly_time(n, m, edges):
    # Create an adjacency list and calculate in-degrees
    graph = defaultdict(list)
    in_degree = {i: 0 for i in range(1, n+1)}
    time = {i: float('inf') for i in range(1, n+1)}
    time[1] = 0

    for u, v, w in edges:
        graph[u].append((v, w))
        in_degree[v] += 1

    # Topological sort using Kahn's algorithm
    queue = deque([node for node in range(1, n+1) if in_degree[node] == 0])

    while queue:
        u = queue.popleft()
        for v, w in graph[u]:
            if time[u] + w < time[v]:
                time[v] = time[u] + w
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    return time[n] if time[n] != float('inf') else "impossible"

def assemble_toy_cars(test_cases):
    results = []
    for n, m, edges in test_cases:
        result = minimum_assembly_time(n, m, edges)
        results.append(result)
    return results

def minimize_max_sum(nums, K):
    """
    Minimizes the maximum sum of K sub-arrays.

    :param nums: List of integers representing the difficulty levels.
    :param K: Integer representing the number of sub-arrays.
    :return: Integer representing the minimal value of the maximum sum of the K sub-arrays.
    """

    def can_split(max_sum):
        current_sum = 0
        sub_array_count = 1

        for num in nums:
            if current_sum + num > max_sum:
                sub_array_count += 1
                current_sum = num
                if sub_array_count > K:
                    return False
            else:
                current_sum += num

        return True

    left, right = max(nums), sum(nums)

    while left < right:
        mid = (left + right) // 2
        if can_split(mid):
            right = mid
        else:
            left = mid + 1

    return left

