def count_crops_clusters(m, n, grid):
    """
    Returns the number of isolated crop clusters in the m x n grid.
    """
    def dfs(x, y):
        # Stack approach for DFS to avoid recursion depth issues in large grids
        stack = [(x, y)]
        visited.add((x, y))
        while stack:
            i, j = stack.pop()
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 'C' and (ni, nj) not in visited:
                    visited.add((ni, nj))
                    stack.append((ni, nj))

    visited = set()
    clusters_count = 0

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 'C' and (i, j) not in visited:
                dfs(i, j)
                clusters_count += 1

    return clusters_count

