def is_path_exists(grid):
    from collections import deque

    n = len(grid)
    m = len(grid[0])

    # Find the starting point 'S'
    start = None
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'S':
                start = (i, j)
                break
        if start:
            break

    # Direction vectors for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Use a queue to perform BFS
    queue = deque([start])
    visited = set()
    visited.add(start)

    while queue:
        x, y = queue.popleft()

        if grid[x][y] == 'E':
            return "Yes"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy

            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and grid[nx][ny] != 'B':
                queue.append((nx, ny))
                visited.add((nx, ny))

    return "No"

import math
import heapq

def calculate_distance(x1, y1, x2, y2):
    return math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2)

def minimum_spanning_tree(n, coordinates):
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = coordinates[i]
            x2, y2 = coordinates[j]
            distance = calculate_distance(x1, y1, x2, y2)
            edges.append((distance, i, j))

    edges.sort()
    parent = list(range(n))

    def find(v):
        if parent[v] != v:
            parent[v] = find(parent[v])
        return parent[v]

    def union(v1, v2):
        root1 = find(v1)
        root2 = find(v2)
        if root1 != root2:
            parent[root2] = root1

    mst_cost = 0
    for distance, i, j in edges:
        if find(i) != find(j):
            union(i, j)
            mst_cost += distance

    return mst_cost

