def longest_subarray_with_sum(nums, target):
    """
    Returns the length of the longest subarray whose sum is equal to the given target.
    """
    prefix_sum = 0
    max_length = 0
    prefix_sum_indices = {0: -1}

    for i, num in enumerate(nums):
        prefix_sum += num

        if prefix_sum - target in prefix_sum_indices:
            max_length = max(max_length, i - prefix_sum_indices[prefix_sum - target])

        if prefix_sum not in prefix_sum_indices:
            prefix_sum_indices[prefix_sum] = i

    return max_length

def categorize_query(query):
    """
    Categorizes the query into "Order Inquiry", "Product Inquiry", or "General Inquiry".
    """
    order_keywords = {"order", "shipment", "delivery", "track", "purchase"}
    product_keywords = {"price", "availability", "features", "specification", "details"}

    query_lower = query.lower()

    for word in order_keywords:
        if word in query_lower:
            return "Order Inquiry"

    for word in product_keywords:
        if word in query_lower:
            return "Product Inquiry"

    return "General Inquiry"

def search(nums, target):
    """
    Returns the index of the target in a rotated sorted array or -1 if the target is not found.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1

