def are_dictionaries_approximately_equal(A, B, t):
    """
    Determine if two dictionaries A and B are approximately equal given a tolerance level t.
    """
    if set(A.keys()) != set(B.keys()):
        return "NO"

    for key in A:
        if abs(A[key] - B[key]) > t:
            return "NO"

    return "YES"

