def findMaxProduct(arr):
    """
    Returns the maximum product of any two distinct elements in the array and their indices.
    """
    if len(arr) < 2:
        return -1, -1, -1

    max1, max2 = float('-inf'), float('-inf')
    min1, min2 = float('inf'), float('inf')
    max1_idx, max2_idx, min1_idx, min2_idx = -1, -1, -1, -1

    for i, num in enumerate(arr):
        if num > max1:
            max2, max2_idx = max1, max1_idx
            max1, max1_idx = num, i
        elif num > max2:
            max2, max2_idx = num, i

        if num < min1:
            min2, min2_idx = min1, min1_idx
            min1, min1_idx = num, i
        elif num < min2:
            min2, min2_idx = num, i

    max_prod = max1 * max2
    min_prod = min1 * min2

    if max_prod > min_prod:
        return max_prod, min(max1_idx, max2_idx), max(max1_idx, max2_idx)
    else:
        return min_prod, min(min1_idx, min2_idx), max(min1_idx, min2_idx)

