def canPair(arr, k):
    """
    This function checks if the given array can be divided into pairs such that
    the sum of every pair is divisible by k. Each element of the array should be used exactly once.
    """
    if len(arr) % 2 != 0:
        return False  # If the number of elements in array is odd, return False

    remainder_count = [0] * k

    for num in arr:
        remainder = num % k
        remainder_count[remainder] += 1

    for i in range(1, (k//2) + 1):
        if remainder_count[i] != remainder_count[k - i]:
            return False

    # For the case where remainder is 0, there should be even number of such elements
    if remainder_count[0] % 2 != 0:
        return False

    return True

