def is_prime(n):
    """
    Checks if a number is prime.
    """
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def solvePrimeSumQueries(N, Q, A, queries):
    """
    Solves the prime number sum for the given queries on the array A.
    """
    prime_sums = []
    for query in queries:
        L, R = query
        subarray = A[L:R+1]
        prime_sum = sum(x for x in subarray if is_prime(x))
        prime_sums.append(prime_sum)
    return prime_sums

