def longest_decreasing_from_peak(n, heights):
    if n == 1:
        return 1

    def is_peak(i):
        if i == 0:
            return heights[i] > heights[i+1]
        if i == n-1:
            return heights[i] > heights[i-1]
        return heights[i] > heights[i-1] and heights[i] > heights[i+1]

    max_length = 1

    for i in range(n):
        if is_peak(i):
            length = 1
            while i+1 < n and heights[i] > heights[i+1]:
                length += 1
                i += 1
            max_length = max(max_length, length)

    return max_length

