def fibonacci(n):
    """
    Returns the n-th Fibonacci number.
    """
    # Using dynamic programming approach to save previous values and avoid redundant calculations.
    if n <= 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b

    return b

# `m` is not used in the Fibonacci calculation based on problem description,
# Assuming we need only the Fibonacci number at position `n`.
def main(n, m):
    return fibonacci(n)

