def add_one_to_string_number(num_str):
    """
    Adds one to a large integer represented as a string and returns the resulting number as a string.
    Leading zeros are preserved in the output if present in the input.
    """
    # Convert the number to a list of characters to allow mutable operations
    num_list = list(num_str)
    carry = 1  # Adding one implies we start with a carry of one

    # Loop from the end to the start of the list
    for i in range(len(num_list) - 1, -1, -1):
        if num_list[i] == '9' and carry == 1:
            num_list[i] = '0'
        else:
            num_list[i] = str(int(num_list[i]) + carry)
            carry = 0
            break

    # If carry is still 1 after the loop, it means we need an extra digit at the start
    if carry == 1:
        num_list.insert(0, '1')

    return ''.join(num_list)

