def min_trucks(weights, max_capacity):
    """
    Returns the minimum number of trucks required to deliver all parcels.
    """
    # Count number of parcels that can be delivered with given max_capacity
    count = 0
    for weight in weights:
        if weight <= max_capacity:
            count += 1
    return count

def final_coordinates(instructions):
    """
    Computes the final coordinates after following the given directions starting from the origin (0,0).

    Parameters:
    instructions (list of tuple): Each tuple contains a direction as a string and steps as an integer.

    Returns:
    tuple: Final coordinates as (x, y).
    """
    x, y = 0, 0

    for direction, steps in instructions:
        if direction == 'right':
            x += steps
        elif direction == 'left':
            x -= steps
        elif direction == 'up':
            y += steps
        elif direction == 'down':
            y -= steps

    return x, y

