def largest_square_subgrid(n, m, grid):
    """
    Returns the size of the largest square subgrid consisting only of 'O' characters.
    """

    if not grid:
        return 0

    # A dp(i, j) stores the length of the largest square subgrid ending at (i, j)
    dp = [[0] * m for _ in range(n)]
    max_side = 0

    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'O':
                if i == 0 or j == 0:
                    dp[i][j] = 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side = max(max_side, dp[i][j])

    return max_side

