def decrypt_message(encrypted: str) -> str:
    """
    Takes an encrypted message and returns the decrypted message.
    Lowercase and uppercase letters are substituted by their respective position in the alphabet.
    Digits remain unchanged.
    The result is a space-separated string of numbers.
    """
    decrypted = []
    for char in encrypted:
        if char.isdigit():
            decrypted.append(char)
        elif char.islower():
            decrypted.append(str(ord(char) - ord('a') + 1))
        elif char.isupper():
            decrypted.append(str(ord(char) - ord('A') + 27))
    return ' '.join(decrypted)

