def robot_final_position(commands):
    """
    Returns the final coordinates of the robot after executing all commands.

    Args:
    commands (str): A string consisting of 'U', 'D', 'L', 'R' commands.

    Returns:
    tuple: The final coordinates of the robot in the format (x, y).
    """
    x, y = 0, 0
    for command in commands:
        if command == 'U':
            y += 1
        elif command == 'D':
            y -= 1
        elif command == 'L':
            x -= 1
        elif command == 'R':
            x += 1
    return (x, y)

