from typing import List

def smallest_missing(n: int, arr: List[int]) -> int:
    # Create a set of numbers from 1 to n
    nums = set(range(1, n + 1))
    # Eliminate numbers present in arr from nums
    nums = nums - set(arr)
    if nums:
        # Return the smallest missing number
        return min(nums)
    else:
        # If all numbers from 1 to n are present
        return 0

