def num_of_islands(matrix):
    """
    Returns the number of distinct islands in the matrix.
    """
    def dfs(matrix, i, j, n):
        if i < 0 or i >= n or j < 0 or j >= n or matrix[i][j] == 0:
            return
        matrix[i][j] = 0
        # Traverse the matrix in the four possible directions.
        dfs(matrix, i + 1, j, n)
        dfs(matrix, i - 1, j, n)
        dfs(matrix, i, j + 1, n)
        dfs(matrix, i, j - 1, n)

    n = len(matrix)
    island_count = 0

    for i in range(n):
        for j in range(n):
            if matrix[i][j] == 1:
                island_count += 1
                dfs(matrix, i, j, n)

    return island_count

def distinct_islands(test_cases):
    result = []
    for matrix in test_cases:
        result.append(num_of_islands(matrix))
    return result

