def largest_prime_factor(n):
    """
    Returns the largest prime factor of the given number n.
    """
    def prime_factors(n):
        factors = []
        # Factor out the number 2
        while n % 2 == 0:
            factors.append(2)
            n //= 2
        # Factor out odd numbers
        for i in range(3, int(n**0.5) + 1, 2):
            while n % i == 0:
                factors.append(i)
                n //= i
        if n > 2:
            factors.append(n)
        return factors

    factors = prime_factors(n)
    return max(factors)

def solve_cases(test_cases):
    results = []
    for n in test_cases:
        results.append(largest_prime_factor(n))
    return results

