def two_sum(nums, k):
    """
    Finds the indices of the two numbers in nums that add up to k.
    """
    num_indices = {}
    for i, num in enumerate(nums):
        complement = k - num
        if complement in num_indices:
            return [num_indices[complement], i]
        num_indices[num] = i
    return None

