def is_valid_expression(expression):
    """
    Checks if the arithmetic expression is valid based on specific constraints.
    """
    if not expression or expression[0] in '+*' or expression[-1] in '+*':
        return False

    num_additions = 0
    num_multiplications = 0
    prev_char = None

    for char in expression:
        if not char.isdigit() and char not in '+*':
            return False
        if char in '+*' and prev_char in '+*':
            return False
        if char == '+':
            num_additions += 1
        if char == '*':
            num_multiplications += 1
        if num_additions > 2 or num_multiplications > 3:
            return False
        prev_char = char

    return True

def validate_expressions(expressions):
    """
    Validates a list of arithmetic expressions.
    """
    results = []
    for expression in expressions:
        if is_valid_expression(expression):
            results.append("Valid")
        else:
            results.append("Invalid")
    return results

