import math

def get_prime_factors(n):
    prime_factors = set()
    # Check if 2 is a prime factor
    while n % 2 == 0:
        prime_factors.add(2)
        n //= 2
    # Check for odd prime factors
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            prime_factors.add(i)
            n //= i
    # This condition is to check if n is a prime number greater than 2
    if n > 2:
        prime_factors.add(n)
    return prime_factors

def countPrimeFactors(M, B):
    all_prime_factors = set()
    for number in B:
        prime_factors = get_prime_factors(number)
        all_prime_factors.update(prime_factors)
    return len(all_prime_factors)

