def can_make_elements_equal(matrix):
    # Calculate the difference between first row and all other rows
    row_diffs = []
    reference_first_row = matrix[0]

    for i in range(1, len(matrix)):
        diff = [matrix[i][j] - reference_first_row[j] for j in range(len(matrix[0]))]
        row_diffs.append(diff)

    # Check if all row differences are the same
    for i in range(1, len(row_diffs)):
        if row_diffs[i] != row_diffs[0]:
            return "NO"

    # Calculate the difference between first column and all other columns
    col_diffs = []
    reference_first_col = [matrix[i][0] for i in range(len(matrix))]

    for j in range(1, len(matrix[0])):
        diff = [matrix[i][j] - reference_first_col[i] for i in range(len(matrix))]
        col_diffs.append(diff)

    # Check if all column differences are the same
    for i in range(1, len(col_diffs)):
        if col_diffs[i] != col_diffs[0]:
            return "NO"

    return "YES"

# Function to read inputs and return the result
