def maximalRectangle(matrix):
    if not matrix or not matrix[0]:
        return 0

    n = len(matrix)
    m = len(matrix[0])
    max_area = 0
    height = [0] * (m + 1)

    for i in range(n):
        for j in range(m):
            if matrix[i][j] == 'W':
                height[j] += 1
            else:
                height[j] = 0

        stack = []
        for j in range(m + 1):
            while stack and height[stack[-1]] > height[j]:
                h = height[stack.pop()]
                w = stack[-1] if stack else -1
                max_area = max(max_area, h * (j - w - 1))
            stack.append(j)

    return max_area

def is_balanced_brackets(n, s):
    """
    Determines if the given sequence of brackets is balanced.

    Parameters:
    n (int): Length of the sequence
    s (str): Sequence of brackets

    Returns:
    str: "YES" if the sequence is balanced, "NO" otherwise
    """
    stack = []
    brackets = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in brackets.values():
            stack.append(char)
        elif char in brackets.keys():
            if stack == [] or brackets[char] != stack.pop():
                return "NO"
    return "YES" if stack == [] else "NO"

