from collections import defaultdict, deque

def alien_order(n, words):
    # Step 1: Create data structures and add all unique letters to the graph
    adj_list = defaultdict(set)
    indegree = {char: 0 for word in words for char in word}

    # Step 2: Find all the edges and update the adjacency list and indegree count
    for first_word, second_word in zip(words, words[1:]):
        for c1, c2 in zip(first_word, second_word):
            if c1 != c2:
                if c2 not in adj_list[c1]:
                    adj_list[c1].add(c2)
                    indegree[c2] += 1
                break
        else:
            if len(second_word) < len(first_word):
                return ""

    # Step 3: Topological Sort using Breadth-First Search
    queue = deque([char for char in indegree if indegree[char] == 0])
    order = []

    while queue:
        char = queue.popleft()
        order.append(char)
        for neighbor in adj_list[char]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) == len(indegree):
        return "".join(order)

    return ""

