def is_palindrome(n):
    """
    Check if a given number is a palindrome.
    """
    return str(n) == str(n)[::-1]

def count_palindromic_numbers_in_range(L, R):
    """
    Count the number of palindromic and non-palindromic numbers in the range [L, R].
    """
    palindromic_count = 0
    non_palindromic_count = 0

    for number in range(L, R + 1):
        if is_palindrome(number):
            palindromic_count += 1
        else:
            non_palindromic_count += 1

    return (palindromic_count, non_palindromic_count)

def process_test_cases(T, test_cases):
    """
