    for L, R in test_cases:
        results.append(count_palindromic_numbers_in_range(L, R))
    return results

def count_safe_paths(n, grid):
    """
    Returns the number of safe paths from top-left to bottom-right in the grid.
    """
    if grid[0][0] == 1 or grid[n-1][n-1] == 1:
        return 0

    dp = [[0] * n for _ in range(n)]

    dp[0][0] = 1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][n-1]

