def find_longest_word(S, D):
    """
    Finds the longest word in D that can be formed by deleting some characters of S
    without reordering the remaining characters. If there are multiple results that
    are the same length, returns the lexicographically smallest one. If there is no
    possible result, returns an empty string.
    """
    def is_subsequence(x):
        it = iter(S)
        return all(char in it for char in x)

    D_sorted = sorted(D, key=lambda x: (-len(x), x))
    for word in D_sorted:
        if is_subsequence(word):
            return word
    return ""

