def can_sort_with_swaps(arr, d):
    """
    Function to determine if an array can be sorted with the given swap threshold.

    Parameters:
    arr (list): The array of integers to check.
    d (int): The threshold for allowable swaps.

    Returns:
    bool: True if the array can be sorted, False otherwise.
    """
    n = len(arr)
    sorted_arr = sorted(arr)

    # We will use disjoint set (union-find) to group the elements that can be swapped
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            parent[rootY] = rootX

    # Connect the indices with allowable swaps
    for i in range(n):
        for j in range(i + 1, n):
            if abs(arr[i] - arr[j]) <= d:
                union(i, j)

    # Check if each element in the sorted array can map to its indices in the original array
    for i in range(n):
        if find(i) != find(arr.index(sorted_arr[i])):
            return False

    return True

