def findPairs(nums, target):
    """
    Returns a list of unique pairs of integers from `nums` that add up to `target`.
    Each pair will be a tuple and the list is sorted in non-decreasing order.
    """
    pairs = set()
    seen = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            pairs.add(tuple(sorted((num, complement))))
        seen.add(num)

    return sorted(list(pairs))

def max_chocolates_stolen(n, chocolates):
    if n == 0:
        return 0
    if n == 1:
        return chocolates[0]

    # Initialize a list to store the maximum chocolates that can be stolen up to each house
    dp = [0] * n
    dp[0] = chocolates[0]
    if n > 1:
        dp[1] = max(chocolates[0], chocolates[1])

    for i in range(2, n):
        # The thief can either steal from the current house and add to the maximum from i-2 houses,
        # or skip the current house and take the maximum from i-1 houses.
        dp[i] = max(chocolates[i] + dp[i-2], dp[i-1])

    return dp[-1]

