def longest_common_subsequence(S1, S2):
    # Create a 2D array to store lengths of longest common subsequence.
    m, n = len(S1), len(S2)
    L = [[0] * (n + 1) for _ in range(m + 1)]

    # Building the L[m+1][n+1] in bottom up fashion.
    for i in range(m + 1):
        for j in range(n + 1):
            if i == 0 or j == 0:
                L[i][j] = 0
            elif S1[i - 1] == S2[j - 1]:
                L[i][j] = L[i - 1][j - 1] + 1
            else:
                L[i][j] = max(L[i - 1][j], L[i][j - 1])

    # Following code is used to print LCS by backtracking through the 2D array.
    index = L[m][n]
    lcs = [""] * (index + 1)
    lcs[index] = ""

    i, j = m, n
    while i > 0 and j > 0:
        if S1[i - 1] == S2[j - 1]:
            lcs[index - 1] = S1[i - 1]
            i -= 1
            j -= 1
            index -= 1
        elif L[i - 1][j] > L[i][j - 1]:
            i -= 1
        else:
            j -= 1

    return "".join(lcs)

def find_lcs_for_multiple_cases(test_cases):
    results = []
    for s1, s2 in test_cases:
        results.append(longest_common_subsequence(s1, s2))
    return results

def unique_paths_with_obstacles(M, N, grid):
    MOD = 10**9 + 7

    # If the start or end point is an obstacle, return 0 directly
    if grid[0][0] == -1 or grid[M-1][N-1] == -1:
        return 0

    # Create a DP array to store the number of unique paths to each cell
    dp = [[0]*N for _ in range(M)]

    # Initialize the starting point
    dp[0][0] = 1

    for i in range(M):
        for j in range(N):
            if grid[i][j] == -1:
                dp[i][j] = 0 # No path through an obstacle
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j] % MOD
                if j > 0:
                    dp[i][j] += dp[i][j-1] % MOD

    return dp[M-1][N-1] % MOD

