def longest_path_even_integers(grid):
    def dfs(x, y, visited):
        visited.add((x, y))
        max_length = 1
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in visited and grid[nx][ny] % 2 == 0:
                max_length = max(max_length, 1 + dfs(nx, ny, visited))
        visited.remove((x, y))
        return max_length

    max_path_length = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] % 2 == 0:
                max_path_length = max(max_path_length, dfs(i, j, set()))

    return max_path_length

def grid_longest_paths(test_cases):
    results = []
    for grid in test_cases:
        results.append(longest_path_even_integers(grid))
    return results

