def evaluate_expression(expr):
    """
    Evaluates a mathematical expression provided as a string.
    Supported operators are +, -, *, / and parentheses.
    """
    def calculate(tokens):
        stack = []
        num = 0
        sign = '+'
        while len(tokens) > 0:
            c = tokens.pop(0)
            if c.isdigit():
                num = num * 10 + int(c)
            if c == '(':
                num = calculate(tokens)
            if (not c.isdigit() and c != ' ') or len(tokens) == 0:
                if sign == '+':
                    stack.append(num)
                elif sign == '-':
                    stack.append(-num)
                elif sign == '*':
                    stack.append(stack.pop() * num)
                elif sign == '/':
                    last = stack.pop()
                    if last // num < 0 and last % num != 0:
                        stack.append(last // num + 1)
                    else:
                        stack.append(last // num)
                sign = c
                num = 0
            if c == ')':
                break
        return sum(stack)

    return calculate(list(expr))

def evaluate_expressions(T, expressions):
    results = []
    for expr in expressions:
        result = evaluate_expression(expr)
        results.append(result)
    return results

