def tsp(n, cost):
    # Define the memoization dictionary
    dp = {}

    # Define a recursive function with the current position and the set of visited cities
    def visit(city, visited):
        if visited == (1 << n) - 1:
            return cost[city][0]

        if (city, visited) in dp:
            return dp[(city, visited)]

        min_cost = float('inf')
        for next_city in range(n):
            if visited & (1 << next_city) == 0:
                total_cost = cost[city][next_city] + visit(next_city, visited | (1 << next_city))
                min_cost = min(min_cost, total_cost)

        dp[(city, visited)] = min_cost
        return min_cost

    # Start the recursion from city 0 with the first city as visited
    return visit(0, 1)

