import heapq

def dijkstra(graph, start, n):
    distances = [float('inf')] * (n + 1)
    distances[start] = 0
    pq = [(0, start)]

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return distances

def solve_kingdom_problems(test_cases):
    results = []

    for n, m, edges in test_cases:
        graph = [[] for _ in range(n + 1)]
        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        all_distances = []

        for i in range(1, n + 1):
            distances = dijkstra(graph, i, n)
            all_distances.append(distances[1:])  # exclude distance to itself from the results

        # Trying to find the minimum of the maximum distances in all shortest paths
        min_of_max_distances = float('inf')

        for row in all_distances:
            max_distance = max(row)
            min_of_max_distances = min(min_of_max_distances, max_distance)

        results.append(min_of_max_distances)

    return results

