def min_operations_to_convert(A, B):
    """
    Returns the minimum number of operations required to make array A equal to array B
    by reversing any number of subarrays. If impossible, return -1.
    """
    if sorted(A) != sorted(B):
        return -1

    n = len(A)
    l, r = 0, n - 1

    while l < n and A[l] == B[l]:
        l += 1

    while r >= 0 and A[r] == B[r]:
        r -= 1

    if l >= r:
        return 0

    reversed_segment = list(reversed(A[l:r+1]))
    if reversed_segment == B[l:r+1]:
        return 1

    return -1

def convert_multiple_cases(test_cases):
    results = []
    for n, A, B in test_cases:
        results.append(min_operations_to_convert(A, B))
    return results

