def will_reservoir_overflow(R, P, H, capacities, init_water, rates, pipes):
    # Initial water in each reservoir
    water = init_water[:]

    for hour in range(H):
        # Adding water to each reservoir
        for i in range(R):
            water[i] += rates[i]

        # Checking for overflow
        for i in range(R):
            if water[i] > capacities[i]:
                return "Yes"

        # Calculating the water flow through pipes and adjusting the water levels
        for u, v, f in pipes:
            if water[u-1] > water[v-1] and water[u-1] - water[v-1] > f:
                flow = f
            else:
                flow = max(0, water[u-1] - water[v-1])

            water[u-1] -= flow
            water[v-1] += flow

            # Checking for overflow after flow adjustment
            for i in range(R):
                if water[i] > capacities[i]:
                    return "Yes"

    return "No"

