from typing import List

def maxProfit(prices: List[int], n: int) -> int:
    if n < 2:
        return 0

    min_price = prices[0]
    max_profit = 0

    for i in range(1, n):
        if prices[i] < min_price:
            min_price = prices[i]
        else:
            profit = prices[i] - min_price
            if profit > max_profit:
                max_profit = profit

    return max_profit

