def count_unique_elements(N, M, array, queries):
    element_count = {}

    for num in array:
        if num in element_count:
            element_count[num] += 1
        else:
            element_count[num] = 1

    for query in queries:
        q, x, k = query
        if x in element_count:
            count_x = element_count[x]
            del element_count[x]
            if q == 1:
                x_new = x + k
            else:
                x_new = x - k

            if x_new in element_count:
                element_count[x_new] += count_x
            else:
                element_count[x_new] = count_x

    return len(element_count)

def allPalindromicSubstrings(S):
    def is_palindrome(sub):
        return sub == sub[::-1]

    palindromes = []
    n = len(S)

    for i in range(n):
        for j in range(i, n):
            substring = S[i:j+1]
            if is_palindrome(substring):
                palindromes.append(substring)

    return palindromes

def max_passengers(N, M, trips):
    changes = [0] * (N + 1)

    for S, D in trips:
        changes[S] += 1
        if D + 1 <= N:
            changes[D + 1] -= 1

    current_passengers = 0
    max_passengers = 0

    for i in range(1, N + 1):
        current_passengers += changes[i]
        if current_passengers > max_passengers:
            max_passengers = current_passengers

    return max_passengers

