def longest_palindrome_length(l, r, T):
    # Get the substring of T from l-1 to r-1
    substring = T[l-1:r]
    # Count frequency of each character in the substring
    freq = {}
    for char in substring:
        if char in freq:
            freq[char] += 1
        else:
            freq[char] = 1
    length = 0
    odd_count = 0
    # Calculate the length of the longest possible palindrome
    for count in freq.values():
        if count % 2 == 0:
            length += count
        else:
            length += count - 1
            odd_count += 1
    # If there are any odd counts, we can place one character in the middle
    if odd_count > 0:
        length += 1
    return length

def handle_queries(M, T, Q, queries):
    results = []
    for query in queries:
        l, r = query
        length = longest_palindrome_length(l, r, T)
        results.append(length)
    return results

def phone_combinations(digits):
    if not digits:
        return []

    digit_to_letters = {
        '2': 'ABC', '3': 'DEF', '4': 'GHI',
        '5': 'JKL', '6': 'MNO', '7': 'PQRS',
        '8': 'TUV', '9': 'WXYZ'
    }

    def backtrack(index, path):
        if len(path) == len(digits):
            combinations.append("".join(path))
            return

        possible_letters = digit_to_letters[digits[index]]
        for letter in possible_letters:
            path.append(letter)
            backtrack(index + 1, path)
            path.pop()

    combinations = []
    backtrack(0, [])

    return combinations

