def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary. Keys in the flattened dictionary will be
    the paths to the values in the original dictionary, joined by dots.
    """
    items = []
    for k, v in d.items():
        new_key = f"{parent_key}{sep}{k}" if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dict(v, new_key, sep=sep).items())
        else:
            items.append((new_key, v))
    return dict(items)

