def does_robot_return(S):
    """
    Determines if the robot returns to the starting position (0, 0) after following all instructions.

    Args:
    S (str): A string containing the sequence of instructions.

    Returns:
    str: 'YES' if the robot returns to the starting position, otherwise 'NO'.
    """
    x, y = 0, 0

    for direction in S:
        if direction == 'U':
            y += 1
        elif direction == 'D':
            y -= 1
        elif direction == 'L':
            x -= 1
        elif direction == 'R':
            x += 1

    if x == 0 and y == 0:
        return 'YES'
    else:
        return 'NO'

