def isMatch(s, p):
    """
    Returns whether the pattern p matches the entire string s.
    """
    # Initialize a 2D DP array with False values
    dp = [[False] * (len(p) + 1) for _ in range(len(s) + 1)]
    dp[0][0] = True  # empty pattern matches empty string

    # Fill the first row (empty string scenarios)
    for j in range(1, len(p) + 1):
        if p[j - 1] == '*':
            dp[0][j] = dp[0][j - 2]

    # Fill the rest of the DP table
    for i in range(1, len(s) + 1):
        for j in range(1, len(p) + 1):
            if p[j - 1] == '.' or p[j - 1] == s[i - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            elif p[j - 1] == '*':
                dp[i][j] = dp[i][j - 2] or (dp[i - 1][j] if (p[j - 2] == '.' or p[j - 2] == s[i - 1]) else False)

    return dp[len(s)][len(p)]

