def game_winner(target_score, allowed_numbers):
    # Use dynamic programming to determine if the first player to move has a winning strategy
    dp = [False] * (target_score + 1)

    for current_score in range(target_score + 1):
        for num in allowed_numbers:
            if current_score + num <= target_score and not dp[current_score]:
                dp[current_score + num] = True

    # The result in dp[target_score] tells if the first player (Ananya) has a winning strategy
    return "Ananya" if dp[target_score] else "Amar"

def determine_game_winners(t, cases):
    results = []
    for i in range(t):
        target_score = cases[i][0]
