def longestUniformSubarray(arr):
    """
    Function to find the length of the longest subarray with all elements equal.
    """
    if not arr:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(arr)):
        if arr[i] == arr[i-1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

