def generate_matches(N):
    """
    Generates a list of matches in lexicographical order for a round-robin tournament.
    Each match is represented as a tuple (i, j) where 1 <= i < j <= N.
    """
    matches = []
    for i in range(1, N+1):
        for j in range(i+1, N+1):
            matches.append((i, j))
    return matches

def perform_operations(operations):
    text = ""
    history = []

    for operation in operations:
        if operation.startswith("APPEND"):
            _, append_text = operation.split(maxsplit=1)
            history.append(text)
            text += append_text
        elif operation == "UNDO":
            if history:
                text = history.pop()
        elif operation == "PRINT":
            print(text)

    return text

