def execute_stack_commands(commands):
    stack = []

    for command in commands:
        parts = command.split()
        op = parts[0]

        if op == "PUSH":
            stack.append(int(parts[1]))
        elif op == "POP":
            if stack:
                stack.pop()
        elif op == "ADD":
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(a + b)
        elif op == "SUB":
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(b - a)
        elif op == "MULT":
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                stack.append(a * b)
        elif op == "DIV":
            if len(stack) >= 2:
                a = stack.pop()
                b = stack.pop()
                if a != 0:
                    stack.append(b // a)

    return stack

