def create_decorated_string(base_str, repetitions):
    """
    Create a decorated string by repeating a base string a specified
    number of times, with every second repetition reversed.

    :param base_str: The base string to be repeated
    :param repetitions: The number of repetitions
    :return: The final decorated string
    """
    decorated_str = []
    for i in range(repetitions):
        if i % 2 == 0:
            decorated_str.append(base_str)
        else:
            decorated_str.append(base_str[::-1])
    return '-'.join(decorated_str)

