def rotate(matrix):
    """
    Rotates the n x n 2D matrix by 90 degrees clockwise in-place.
    """
    n = len(matrix)

    # Transpose the matrix
    for i in range(n):
        for j in range(i + 1, n):
            matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]

    # Reverse each row
    for i in range(n):
        matrix[i].reverse()

def three_sum(nums):
    """
    Given a list of integers, find all unique triplets in the list which gives the sum of zero.
    """
    nums.sort()  # Sort the array
    result = []
    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i-1]:  # Skip duplicates
            continue
        left, right = i + 1, len(nums) - 1
        while left < right:
            s = nums[i] + nums[left] + nums[right]
            if s < 0:
                left += 1
            elif s > 0:
                right -= 1
            else:
                # Found a triplet
                result.append([nums[i], nums[left], nums[right]])
                while left < right and nums[left] == nums[left + 1]:
                    left += 1  # Skip duplicates
                while left < right and nums[right] == nums[right - 1]:
                    right -= 1  # Skip duplicates
                left += 1
                right -= 1
    return result

def format_triplets(triplets):
    """
    Utility function to format the triplets for printing.
    """
    return "\n".join(" ".join(map(str, triplet)) for triplet in sorted(triplets))

