def longest_distinct_substring(s: str) -> str:
    """
    Finds the longest substring with all distinct characters.
    """
    longest = ""
    chars_seen = {}
    start = 0

    for end, char in enumerate(s):
        if char in chars_seen and chars_seen[char] >= start:
            start = chars_seen[char] + 1
        chars_seen[char] = end

        if end - start + 1 > len(longest):
            longest = s[start:end + 1]

    return longest

