def can_transform(t, cases):
    results = []
    for case in cases:
        n, a, b = case
        possible = True

        # Check if we can transform a to b
        for i in range(n):
            if a[i] > b[i]:
                possible = False
                break

        if not possible:
            results.append("NO")
            continue

        # Additional pass to check the incremental differences
        for i in range(1, n):
            if b[i] - b[i-1] < a[i] - a[i-1]:
                possible = False
                break

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    return results

