def ways_to_get_sum(N):
    dp = [0] * (N + 1)
    dp[0] = 1  # There is one way to get the sum 0, which is using 0 dice

    for i in range(1, N + 1):
        for j in range(1, 7):
            if i - j >= 0:
                dp[i] += dp[i - j]

    return dp[N]

