def is_valid_identifier(s):
    """
    Determines if the given string is a valid identifier.

    :param s: input string representing the identifier
    :return: "YES" if the string is a valid identifier, otherwise "NO"
    """
    if not s:
        return "NO"

    if s[0].isdigit():
        return "NO"

    previous_char = ''
    for char in s:
        if char not in 'abcdefghijklmnopqrstuvwxyz0123456789_':
            return "NO"
        if char == '_' and previous_char == '_':
            return "NO"
        previous_char = char

    return "YES"

