def min_travel_cost(n, m, roads, d):
    import math

    # Initialize the cost matrix with "infinity"
    cost_matrix = [[math.inf] * n for _ in range(n)]

    # Road costs after applying discounts
    discounted_roads = [(a, b, max(c - d, 0)) for a, b, c in roads]

    # Fill the cost matrix with the discounted roads
    for a, b, cost in discounted_roads:
        cost_matrix[a-1][b-1] = cost
        cost_matrix[b-1][a-1] = cost

    # Set the diagonal to zero
    for i in range(n):
        cost_matrix[i][i] = 0

    # Apply Floyd-Warshall Algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if cost_matrix[i][j] > cost_matrix[i][k] + cost_matrix[k][j]:
                    cost_matrix[i][j] = cost_matrix[i][k] + cost_matrix[k][j]

    return cost_matrix

def prime_factors(n):
    """
    Returns a dictionary where the keys are the prime factors of n and the values are their corresponding exponents.
    """
    factors = {}
    # Check factor of 2 first
    count = 0
    while n % 2 == 0:
        n //= 2
        count += 1
    if count > 0:
        factors[2] = count

    # Check for odd factors from 3 onwards
    factor = 3
    while factor * factor <= n:
        count = 0
        while n % factor == 0:
            n //= factor
            count += 1
        if count > 0:
            factors[factor] = count
        factor += 2

    # If n is still greater than 1, then it is a prime number
    if n > 1:
        factors[n] = 1

    return factors

