def preprocess_forest(R, C, forest):
    # Create a 2D array to store cumulative sum
    dp = [[0] * (C + 1) for _ in range(R + 1)]

    # Fill the cumulative sum array
    for r in range(1, R + 1):
        for c in range(1, C + 1):
            dp[r][c] = (1 if forest[r - 1][c - 1] == 'A' else 0) + dp[r - 1][c] + dp[r][c - 1] - dp[r - 1][c - 1]

    return dp

def query_animals(dp, r1, c1, r2, c2):
    # Convert to 1-based indexing for calculation
    return dp[r2][c2] - dp[r1 - 1][c2] - dp[r2][c1 - 1] + dp[r1 - 1][c1 - 1]

# Function to handle the entire process based on input
def forest_animals(R, C, forest, queries):
    # Preprocess the forest to create the cumulative sum array
    dp = preprocess_forest(R, C, forest)

    # Process each query and get the result
    results = []
    for r1, c1, r2, c2 in queries:
        results.append(query_animals(dp, r1, c1, r2, c2))

    return results

