def canPartition(nums, k):
    """
    Determines if the list can be partitioned into k non-empty subsets with equal sum.
    """
    def can_partition(start, k, current_sum, target, visited):
        if k == 1:  # Only need one more subset to be equal to target
            return True
        if current_sum == target:  # Found a subset, move to the next one
            return can_partition(0, k - 1, 0, target, visited)
        for i in range(start, len(nums)):
            if not visited[i] and current_sum + nums[i] <= target:
                visited[i] = True
                if can_partition(i + 1, k, current_sum + nums[i], target, visited):
                    return True
                visited[i] = False
        return False

    if sum(nums) % k != 0:
        return False
    target = sum(nums) // k
    visited = [False] * len(nums)
    nums.sort(reverse=True)  # Optimization to consider larger elements first
    return can_partition(0, k, 0, target, visited)

