def can_be_palindrome(inputString):
    def is_palindrome(s):
        return s == s[::-1]

    left, right = 0, len(inputString) - 1
    while left < right:
        if inputString[left] != inputString[right]:
            # Try removing either the left character or the right character
            return is_palindrome(inputString[left+1:right+1]) or is_palindrome(inputString[left:right])
        left += 1
        right -= 1
    return True

