def check_words_in_text(n, words, text):
    words = words.split()
    text_words = text.split()

    word_index = 0

    for text_word in text_words:
        if word_index < n and text_word == words[word_index]:
            word_index += 1

    return "YES" if word_index == n else "NO"

def largest_non_adjacent_sum(arr):
    """
    Returns the largest sum of a subsequence where no two elements are adjacent.
    """
    n = len(arr)

    if n == 0:
        return 0
    if n == 1:
        return max(0, arr[0])

    prev_prev = max(0, arr[0])
    prev = max(prev_prev, arr[1])

    for i in range(2, n):
        current = max(prev, prev_prev + arr[i])
        prev_prev, prev = prev, current

    return prev

