from collections import deque

def find_shortest_path(maze):
    def bfs(start, end, maze, m, n):
        queue = deque([start])
        visited = set()
        visited.add(start)
        directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]
        steps = 0

        while queue:
            for _ in range(len(queue)):
                x, y = queue.popleft()
                if (x, y) == end:
                    return steps
                for dx, dy in directions:
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < m and 0 <= ny < n and maze[nx][ny] != '#' and (nx, ny) not in visited:
                        queue.append((nx, ny))
                        visited.add((nx, ny))
            steps += 1

        return -1

    # Find the positions of 'S' and 'E'
    start, end = None, None
    m = len(maze)
    n = len(maze[0])
    for i in range(m):
        for j in range(n):
            if maze[i][j] == 'S':
                start = (i, j)
            elif maze[i][j] == 'E':
                end = (i, j)

    return bfs(start, end, maze, m, n)

def solve_mazes(T, test_cases):
    results = []
    for maze in test_cases:
        results.append(find_shortest_path(maze))
    return results

