def process_grid_queries(T, test_cases):
    results = []

    for case in test_cases:
        n, q, queries = case['n'], case['q'], case['queries']
        grid = [[0] * n for _ in range(n)]  # Initialize an n x n grid with zeros

        for query in queries:
            if query[0] == 1:
                x, y, val = query[1] - 1, query[2] - 1, query[3]
                grid[x][y] = val
            elif query[0] == 2:
                x1, y1, x2, y2 = query[1] - 1, query[2] - 1, query[3] - 1, query[4] - 1
                max_val = float('-inf')
                for i in range(x1, x2 + 1):
                    for j in range(y1, y2 + 1):
                        if grid[i][j] > max_val:
                            max_val = grid[i][j]
                results.append(max_val)

    return results

