def distinct_elements_in_subarray(arr, K):
    from collections import defaultdict

    n = len(arr)
    if n == 0 or K == 0 or K > n:
        return []

    distinct_count = []
    count_map = defaultdict(int)
    distinct = 0

    for i in range(K):
        if count_map[arr[i]] == 0:
            distinct += 1
        count_map[arr[i]] += 1

    distinct_count.append(distinct)

    for i in range(K, n):
        if count_map[arr[i - K]] == 1:
            distinct -= 1
        count_map[arr[i - K]] -= 1

        if count_map[arr[i]] == 0:
            distinct += 1
        count_map[arr[i]] += 1

        distinct_count.append(distinct)

    return distinct_count

