def can_sum(arr, target):
    """
    Determines if any combination of numbers from the list can sum to the target.
    Uses dynamic programming to solve the problem.
    """
    dp = [False] * (target + 1)
    dp[0] = True

    for i in range(1, target + 1):
        for num in arr:
            if i - num >= 0:
                dp[i] = dp[i] or dp[i - num]
            if dp[i]:
                break

    return dp[target]

