def reorder_array(arr):
    """
    Rearranges the input array such that all even numbers come before all odd numbers,
    while maintaining the relative order of the even and odd numbers.
    """
    even_numbers = []
    odd_numbers = []

    for num in arr:
        if num % 2 == 0:
            even_numbers.append(num)
        else:
            odd_numbers.append(num)

    return even_numbers + odd_numbers

