def partition_number(n: int, k: int) -> int:
    # Initialize a DP table with dimensions (n+1, k+1)
    dp = [[0] * (k + 1) for _ in range(n + 1)]

    # There is one way to partition 0 into 0 parts
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, n + 1):
        for j in range(1, k + 1):
            if i >= j:
                dp[i][j] = dp[i - 1][j - 1] + dp[i - j][j]

    return dp[n][k]

