def task_combinations(tasks, T):
    from itertools import combinations

    # Sort the tasks to manage the order in the subsets
    tasks.sort()

    # Helper function to find all combinations that sum up to T
    def find_combinations():
        results = set()
        # Try all possible lengths of combinations
        for r in range(1, len(tasks) + 1):
            for combination in combinations(tasks, r):
                if sum(combination) == T:
                    results.add(combination)
        return results

    # Get the combinations and convert them to a list of lists
    combinations_set = find_combinations()
    return [list(combination) for combination in combinations_set]

