def nth_fibonacci(N):
    """
    Returns the N-th Fibonacci number (1-indexed).
    """
    if N == 1:
        return 0
    elif N == 2:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, N):
            a, b = b, a + b
        return b

