def is_happy_number(n: int) -> str:
    def sum_of_squares(num: int) -> int:
        total = 0
        while num > 0:
            digit = num % 10
            total += digit * digit
            num //= 10
        return total

    seen = set()
    while n != 1:
        n = sum_of_squares(n)
        if n in seen:
            return "Unhappy Number"
        seen.add(n)
    return "Happy Number"

