def find_palindromes(s):
    """
    Returns all the start and end indices of every palindrome present in the string s.
    """
    result = []
    length = len(s)

    # Helper function to check range expanding from the middle
    def extend_palindrome(left, right):
        while left >= 0 and right < length and s[left] == s[right]:
            result.append((left, right))
            left -= 1
            right += 1

    for i in range(length):
        # Check for odd-length palindromes (single character center)
        extend_palindrome(i, i)
        # Check for even-length palindromes (two character center)
        if i + 1 < length:
            extend_palindrome(i, i + 1)

    return sorted(result)

