def is_valid_parentheses(s):
    """
    Returns whether the input string `s` representing a sequence of parentheses is valid.
    """
    stack = []

    for char in s:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0

