def can_segment_string(s, wordDict):
    """
    Determines if the string s can be segmented into a sequence of words in wordDict.
    """
    word_set = set(wordDict)
    dp = [False] * (len(s) + 1)
    dp[0] = True

    for i in range(1, len(s) + 1):
        for j in range(i):
            if dp[j] and s[j:i] in word_set:
                dp[i] = True
                break

    return "YES" if dp[len(s)] else "NO"

