def is_valid_parentheses(sequence):
    """
    Returns "YES" if the sequence of parentheses is valid, otherwise "NO".
    """
    stack = []
    for char in sequence:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if stack:
                stack.pop()
            else:
                return "NO"
    return "YES" if not stack else "NO"

def check_valid_sequences(test_cases):
    """
    Given a list of test case strings, return a list of results for each sequence.
    """
    results = []
    for sequence in test_cases:
        results.append(is_valid_parentheses(sequence))
    return results

