def countExchangeGroups(N, pairs):
    """
    Returns the number of distinct exchange groups.
    """
    from collections import defaultdict, deque

    def bfs(node, visited, adj_list):
        queue = deque([node])
        visited[node] = True
        while queue:
            current = queue.popleft()
            for neighbor in adj_list[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

    adj_list = defaultdict(list)
    visited = [False] * (N + 1)

    for a, b in pairs:
        adj_list[a].append(b)
        adj_list[b].append(a)

    group_count = 0
    for person in range(1, N + 1):
        if not visited[person]:
            group_count += 1
            bfs(person, visited, adj_list)

    return group_count

