def knapsack(T, data):
    results = []

    for t in range(T):
        N, C = data[t]['N'], data[t]['C']
        weights = data[t]['weights']
        values = data[t]['values']

        dp = [[0 for x in range(C + 1)] for x in range(N + 1)]

        for i in range(N + 1):
            for w in range(C + 1):
                if i == 0 or w == 0:
                    dp[i][w] = 0
                elif weights[i-1] <= w:
                    dp[i][w] = max(values[i-1] + dp[i-1][w - weights[i-1]], dp[i-1][w])
                else:
                    dp[i][w] = dp[i-1][w]

        results.append(dp[N][C])

    return results

def sparse_multiply(A, B):
    """
    Multiplies two sparse matrices A and B and returns the resultant sparse matrix.
    """
    # Resultant matrix
    C = {}

    # Iterate through each row in matrix A
    for i in A:
        # Iterate through each column in matrix B
        for k in A[i]:
            if k in B:
                for j in B[k]:
                    if i not in C:
                        C[i] = {}
                    if j not in C[i]:
                        C[i][j] = 0
                    C[i][j] += A[i][k] * B[k][j]

    # Removing zero entries
    for i in list(C.keys()):
        for j in list(C[i].keys()):
            if C[i][j] == 0:
                del C[i][j]
        if not C[i]:
            del C[i]

    return C

