def largest_square_subgrid(N, M, grid):
    """
    Returns the side length of the largest square sub-grid that contains only the character `.`.
    """
    dp = [[0] * M for _ in range(N)]
    max_side_length = 0

    for i in range(N):
        for j in range(M):
            if grid[i][j] == '.':
                if i == 0 or j == 0:
                    dp[i][j] = 1  # The edge cells themselves can form a square of side 1
                else:
                    dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1
                max_side_length = max(max_side_length, dp[i][j])

    return max_side_length

