def is_prime(num):
    """
    Checks if the number is a prime number.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def longest_increasing_prime_subsequence(nums):
    """
    Determines the length of the longest strictly increasing subsequence of prime numbers.
    """
    primes = [num for num in nums if is_prime(num)]
    primes.sort()
    if not primes:
        return 0
    # To find LIS, we use a DP approach
    dp = [1] * len(primes)
    for i in range(1, len(primes)):
        for j in range(i):
            if primes[i] > primes[j]:
                dp[i] = max(dp[i], dp[j] + 1)
    return max(dp)

