def max_collinear_points(points):
    from collections import defaultdict
    import math

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def slope(p1, p2):
        dx, dy = p2[0] - p1[0], p2[1] - p1[1]
        if dx == 0:
            return ('inf', 0)
        elif dy == 0:
            return (0, 'inf')
        else:
            g = gcd(dx, dy)
            return (dy // g, dx // g)

    max_points = 0

    for i in range(len(points)):
        slope_count = defaultdict(int)
        for j in range(len(points)):
            if i != j:
                slope_count[slope(points[i], points[j])] += 1
        if slope_count:
            max_points = max(max_points, max(slope_count.values()) + 1)

    return max_points

def collinear_subsets(test_cases):
    result = []
    for points in test_cases:
        result.append(max_collinear_points(points))
    return result

