def count_islands(grid):
    if not grid:
        return 0

    n = len(grid)
    m = len(grid[0])
    visited = [[False] * m for _ in range(n)]

    def dfs(x, y):
        if x < 0 or x >= n or y < 0 or y >= m or visited[x][y] or grid[x][y] == '0':
            return
        visited[x][y] = True
        dfs(x+1, y)
        dfs(x-1, y)
        dfs(x, y+1)
        dfs(x, y-1)

    island_count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '1' and not visited[i][j]:
                dfs(i, j)
                island_count += 1

    return island_count

