def binary_gap(n):
    """
    This function takes an integer n and returns the length of the longest sequence of consecutive
    zeros that is surrounded by ones at both ends in the binary representation of n.
    """
    binary_rep = bin(n)[2:]  # Convert to binary and remove the '0b' prefix
    gaps = binary_rep.strip('0').split('1')

    if len(gaps) <= 1:
        return 0

    return max(len(gap) for gap in gaps)

