def first_non_repeated_char(s):
    """
    Finds the first non-repeated character in the string `s`.
    If no such character exists, returns an empty string.
    """
    char_count = {}

    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    for char in s:
        if char_count[char] == 1:
            return char

    return ""

