def exists_increasing_subsequence(n, sequence):
    """
    Determines if there exists a strictly increasing subsequence of the given sequence with length at least 3.
    """
    if n < 3:
        return "NO"

    first = second = float('inf')

    for num in sequence:
        if num <= first:
            first = num
        elif num <= second:
            second = num
        else:
            return "YES"

    return "NO"

