from functools import cmp_to_key

def largest_number(nums):
    """
    Returns the largest number possible by concatenating the numbers in any order.
    """
    def compare(x, y):
        return (x + y) > (y + x)

    # Convert numbers to strings for easier comparison and manipulation
    str_nums = [str(num) for num in nums]

    # Sort numbers based on custom comparator
    sorted_nums = sorted(str_nums, key=cmp_to_key(lambda x, y: 1 if x + y > y + x else -1), reverse=True)

    # Edge case: when the largest number is '0' (e.g., [0, 0])
    if sorted_nums[0] == '0':
        return '0'

    # Join sorted numbers to form the largest number
    return ''.join(sorted_nums)

