from collections import deque, defaultdict

def min_time_to_complete_tasks(numTasks, prerequisites):
    in_degree = [0] * numTasks
    adj_list = defaultdict(list)

    for pre in prerequisites:
        adj_list[pre[0]].append(pre[1])
        in_degree[pre[1]] += 1

    queue = deque([i for i in range(numTasks) if in_degree[i] == 0])
    time_units = 0
    completed_tasks = 0

    while queue:
        time_units += 1
        for _ in range(len(queue)):
            task = queue.popleft()
            completed_tasks += 1
            for next_task in adj_list[task]:
                in_degree[next_task] -= 1
                if in_degree[next_task] == 0:
                    queue.append(next_task)

    if completed_tasks != numTasks:
        raise ValueError("There exists a cycle in the graph.")

    return time_units

