def min_days_to_read_m_words(T, test_cases):
    results = []
    for i in range(T):
        N, M = test_cases[i][0]
        words_list = test_cases[i][1]

        words_list.sort(reverse=True)
        total_words = 0
        days = 0

        for words in words_list:
            if total_words >= M:
                break
            total_words += words
            days += 1

        if total_words >= M:
            results.append(days)
        else:
            results.append("Impossible")

    return results

def longest_balanced_parentheses(s):
    """
    Returns the length of the longest balanced parentheses substring.
    """
    max_length = 0
    stack = [-1]  # Initialize stack with -1 to handle base case

    for i, char in enumerate(s):
        if char == '(':
            stack.append(i)
        else:  # char == ')'
            stack.pop()
            if not stack:
                stack.append(i)
            else:
                max_length = max(max_length, i - stack[-1])

    return max_length

