def min_edges_to_remove(n, m, k, edges):
    from collections import defaultdict, deque

    def dfs(node):
        stack = [node]
        visited.add(node)
        count = 0
        while stack:
            current = stack.pop()
            count += 1
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)
        return count

    if k > n:
        return -1

    if k == n:
        return m

    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    component_sizes = []
    for node in range(1, n + 1):
        if node not in visited:
            comp_size = dfs(node)
            component_sizes.append(comp_size)

    num_components = len(component_sizes)

    if num_components > k:
        return -1
    elif num_components == k:
        return 0

    component_sizes.sort()
    edges_to_split = k - num_components

    return edges_to_split

