def manage_warehouse(n, m, q, commands):
    # Initial positions of items
    warehouse = {(i, j): (i, j) for i in range(1, n + 1) for j in range(1, m + 1)}

    def move(item, direction):
        x, y = item
        if direction == 'UP' and x > 1:
            return (x - 1, y)
        elif direction == 'DOWN' and x < n:
            return (x + 1, y)
        elif direction == 'LEFT' and y > 1:
            return (x, y - 1)
        elif direction == 'RIGHT' and y < m:
            return (x, y + 1)
        else:
            return 'Invalid Move'

    for command in commands:
        _, i, j, direction = command.split()
        i, j = int(i), int(j)
        if warehouse[(i, j)] != 'Invalid Move':
            new_position = move((i, j), direction)
            if new_position != 'Invalid Move':
                warehouse[(i, j)] = new_position
            else:
                warehouse[(i, j)] = new_position

    return warehouse

