def wordBreak(s, wordDict):
    def backtrack(start):
        if start in memo:
            return memo[start]
        if start == len(s):
            return [[]]

        result = []
        for end in range(start + 1, len(s) + 1):
            word = s[start:end]
            if word in wordDict:
                rest_of_the_sentences = backtrack(end)
                for sentence in rest_of_the_sentences:
                    result.append([word] + sentence)

        memo[start] = result
        return result

    wordDict = set(wordDict)
    memo = {}
    break_sentences = backtrack(0)
    return [" ".join(words) for words in break_sentences]

