import heapq

def dijkstra(n, edges, start, end):
    graph = {i: [] for i in range(1, n + 1)}
    for u, v, w in edges:
        graph[u].append((v, w))
        graph[v].append((u, w))

    pq = [(0, start)]
    dist = {i: float('inf') for i in range(1, n + 1)}
    dist[start] = 0

    while pq:
        current_distance, current_node = heapq.heappop(pq)

        if current_distance > dist[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < dist[neighbor]:
                dist[neighbor] = distance
                heapq.heappush(pq, (distance, neighbor))

    return dist[end] if dist[end] != float('inf') else -1

def minimal_travel_cost(n, m, routes, start, end):
    return dijkstra(n, routes, start, end)

def longest_increasing_subsequence_with_even_sum(arr):
    n = len(arr)
    dp = [0] * n  # dp[i] will store the length of LIS ending at index i
    even_sum = [0] * n  # even_sum[i] will store the sum of the LIS ending at index i if it's even

    max_length = -1

    for i in range(n):
        dp[i] = 1
        even_sum[i] = arr[i] if arr[i] % 2 == 0 else 0

        for j in range(i):
            if arr[j] < arr[i] and dp[j] + 1 > dp[i]:
                dp[i] = dp[j] + 1
                if (even_sum[j] + arr[i]) % 2 == 0:
                    even_sum[i] = even_sum[j] + arr[i]
                else:
                    even_sum[i] = 0

        if even_sum[i] % 2 == 0 and even_sum[i] > 0:
            max_length = max(max_length, dp[i])

    return max_length

def process_test_cases(test_cases):
    results = []
    for n, arr in test_cases:
        results.append(longest_increasing_subsequence_with_even_sum(arr))
    return results

def get_maximum_gold(grid):
    def dfs(r, c):
        if r < 0 or r >= R or c < 0 or c >= C or grid[r][c] == 0:
            return 0

        gold = grid[r][c]
        grid[r][c] = 0  # mark as visited

        max_gold = 0
        for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            max_gold = max(max_gold, dfs(r + dr, c + dc))

        grid[r][c] = gold  # backtrack
        return gold + max_gold

    R, C = len(grid), len(grid[0])
    max_gold_collected = 0

    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0:
                max_gold_collected = max(max_gold_collected, dfs(r, c))

    return max_gold_collected

