def min_operations_for_binary_strings(T, cases):
    results = []

    for A, B in cases:
        # Calculate the number of 1s and 0s that need to be swapped or flipped
        diff_zero_to_one = diff_one_to_zero = swaps_needed = 0

        for a_bit, b_bit in zip(A, B):
            if a_bit != b_bit:
                if a_bit == '0':
                    diff_zero_to_one += 1
                else:
                    diff_one_to_zero += 1

        swaps_needed = min(diff_zero_to_one, diff_one_to_zero)
        flips_needed = abs(diff_zero_to_one - diff_one_to_zero)
        min_operations = swaps_needed + flips_needed

        results.append(min_operations)

    return results

