def char_frequency(s: str) -> dict:
    """
    Determines the frequency of each character in the given string.
    Characters are case-sensitive.
    """
    frequency_dict = {}
    for char in s:
        if char in frequency_dict:
            frequency_dict[char] += 1
        else:
            frequency_dict[char] = 1
    return frequency_dict

