def longestBitonicSubsequence(n, arr):
    if n == 0:
        return 0

    # dp1[i] will be the length of LIS ending at index i
    dp1 = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                dp1[i] = max(dp1[i], dp1[j] + 1)

    # dp2[i] will be the length of LDS starting from index i
    dp2 = [1] * n

    for i in range(n-2, -1, -1):
        for j in range(i+1, n):
            if arr[i] > arr[j]:
                dp2[i] = max(dp2[i], dp2[j] + 1)

    # Find the longest bitonic subsequence
    max_length = 0
    for i in range(n):
        max_length = max(max_length, dp1[i] + dp2[i] - 1)

    return max_length

