def is_peak_array(n, array):
    """
    Determines if the array follows the described peak pattern and finds the peak element.
    Returns a tuple (boolean, peak_element) where boolean is True if it follows the pattern, else False.
    """
    if n < 3:
        return (False, )

    increasing = True
    peak_element = None
    peak_index = -1

    for i in range(1, n):
        if increasing:
            if array[i] < array[i-1]:
                increasing = False
                peak_element = array[i-1]
                peak_index = i - 1
            elif array[i] == array[i-1]:
                return (False, )
        else:
            if array[i] >= array[i-1]:
                return (False, )

    if increasing or peak_index == n - 1:
        return (False, )

    return (True, peak_element)

