def max_profit_days(T, test_cases):
    results = []

    for test_case in test_cases:
        N, prices = test_case
        if N < 2:
            results.append("0 0")
            continue

        min_price_index = 0
        max_profit = 0
        buy_day = 0
        sell_day = 0

        for i in range(1, N):
            if prices[i] < prices[min_price_index]:
                min_price_index = i
            else:
                profit = prices[i] - prices[min_price_index]
                if profit > max_profit:
                    max_profit = profit
                    buy_day = min_price_index + 1
                    sell_day = i + 1

        if max_profit == 0:
            results.append("0 0")
        else:
            results.append(f"{buy_day} {sell_day}")

    return results

def is_palindrome(s, l, r):
    """
    Checks if the substring s[l:r+1] is a palindrome.
    """
    while l < r:
        if s[l] != s[r]:
            return False
        l += 1
        r -= 1
    return True

def count_palindromic_substrings(n, s):
    """
    Returns the number of palindromic substrings where r is the smallest index
    for the given substring.
    """
    count = 0
    for r in range(n):
        for l in range(r + 1):
            if is_palindrome(s, l, r):
                count += 1
    return count

def process_test_cases(t, test_cases):
    """
    Processes multiple test cases and returns the results in a list.
    """
    results = []
    for i in range(t):
        n, s = test_cases[i]
        results.append(count_palindromic_substrings(n, s))
    return results

