def max_accessible_depots(n, m, roads, k):
    from collections import deque, defaultdict

    # Create an adjacency list for the graph
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start):
        visited = set()
        queue = deque([(start, 1)])  # (current_zone, zones_visited)
        max_zones = 0

        while queue:
            zone, count = queue.popleft()
            if zone not in visited:
                visited.add(zone)
                max_zones = max(max_zones, count)
                if count < k:
                    for neighbor in graph[zone]:
                        queue.append((neighbor, count + 1))
        return max_zones

    # Since we can start from any zone, we need to check the maximum for each starting point
    max_depots = 0
    for start_zone in range(1, n + 1):
        max_depots = max(max_depots, bfs(start_zone))

    return max_depots

def count_paths(grid):
    M = len(grid)
    N = len(grid[0])

    if grid[0][0] == 1 or grid[M-1][N-1] == 1:
        return 0

    dp = [[0 for _ in range(N)] for _ in range(M)]
    dp[0][0] = 1

    for i in range(M):
        for j in range(N):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[M-1][N-1]

