def transform_string(s):
    """
    Transforms the string such that each character is replaced by the letter immediately
    following it in the English alphabet. Wraps around from 'z' to 'a' and 'Z' to 'A'.

    :param s: Input string with lowercase and uppercase letters
    :return: Transformed string
    """
    result = []
    for char in s:
        if char.islower():
            if char == 'z':
                result.append('a')
            else:
                result.append(chr(ord(char) + 1))
        elif char.isupper():
            if char == 'Z':
                result.append('A')
            else:
                result.append(chr(ord(char) + 1))
    return ''.join(result)

