from collections import defaultdict, deque

def find_seating_arrangement(N, people, M, pairs):
    # Create an adjacency list for people who do not get along
    adjacency_list = defaultdict(list)
    for a, b in pairs:
        adjacency_list[a].append(b)
        adjacency_list[b].append(a)

    # Graph coloring with two colors (bipartite graph can use two colors)
    color = {}

    def bfs(start):
        queue = deque([start])
        color[start] = 0  # Start coloring with 0

        while queue:
            person = queue.popleft()
            current_color = color[person]
            next_color = 1 - current_color  # Alternate between 0 and 1

            for neighbor in adjacency_list[person]:
                if neighbor in color:
                    if color[neighbor] == current_color:  # Conflict, not bipartite
                        return False
                else:
                    color[neighbor] = next_color
                    queue.append(neighbor)
        return True

    for person in people:
        if person not in color:
            if not bfs(person):
                return "impossible"

    # If the graph is successfully colored, we generate the seating.
    group1 = [person for person in people if color[person] == 0]
    group2 = [person for person in people if color[person] == 1]

    return " ".join(group1 + group2)

# Example usage:
# N = 4
# people = ['alice', 'bob', 'charlie', 'david']
# M = 2
# pairs = [('alice', 'bob'), ('charlie', 'david')]
