def can_distribute_weights(n, m, weights, capacities):
    weights.sort(reverse=True)
    capacities.sort(reverse=True)

    for weight in weights:
        for i in range(m):
            if capacities[i] >= weight:
                capacities[i] -= weight
                break
        else:
            return "NO"
    return "YES"

