def find_most_common_topic(n, q, support_logs, queries):
    """
    Finds the most common support topic within given time ranges.
    """
    from collections import defaultdict, Counter

    # Create a dictionary with time as key and list of topics at that time as value
    time_to_topics = defaultdict(list)

    for t, s in support_logs:
        time_to_topics[t].append(s)

    results = []
    for t_start, t_end in queries:
        topic_counter = Counter()

        for t in range(t_start, t_end + 1):
            if t in time_to_topics:
                topic_counter.update(time_to_topics[t])

        if topic_counter:
            most_common_topic = min(topic_counter, key=lambda x: (-topic_counter[x], x))
            results.append(most_common_topic)
        else:
            results.append(None)  # If there are no logs in the range, append None

    return results

def num_islands(matrix):
    if not matrix:
        return 0

    R = len(matrix)
    C = len(matrix[0])
    visited = [[False for _ in range(C)] for _ in range(R)]

    def dfs(r, c):
        stack = [(r, c)]
        while stack:
            row, col = stack.pop()
            if 0 <= row < R and 0 <= col < C and not visited[row][col] and matrix[row][col] == '1':
                visited[row][col] = True
                stack.append((row+1, col))
                stack.append((row-1, col))
                stack.append((row, col+1))
                stack.append((row, col-1))

    island_count = 0
    for r in range(R):
        for c in range(C):
            if matrix[r][c] == '1' and not visited[r][c]:
                dfs(r, c)
                island_count += 1

    return island_count

def parse_input(input_str):
    lines = input_str.strip().split('\n')
    R, C = map(int, lines[0].split())
    matrix = [list(line) for line in lines[1:]]
    return matrix

def count_islands(input_str):
    matrix = parse_input(input_str)
    return num_islands(matrix)

def find_collisions(vehicle_paths):
    from collections import defaultdict

    point_visits = defaultdict(int)
    potential_collisions = set()

    for path in vehicle_paths:
        visited_points = set()
        for point in path:
            if point in visited_points:
                # Prevent counting the same vehicle revisiting the same point in its own path
                continue
            point_visits[point] += 1
            visited_points.add(point)
            if point_visits[point] > 1:
                potential_collisions.add(point)

    return potential_collisions

def process_input(input_data):
    input_lines = input_data.strip().split('\n')
    results = []
    index = 0

    while index < len(input_lines):
        m = int(input_lines[index].strip())
        if m == 0:
            break
        index += 1

        vehicle_paths = []
        for _ in range(m):
            path_data = list(map(int, input_lines[index].strip().split()))
            path = [(path_data[i], path_data[i+1]) for i in range(1, len(path_data), 2)]
            vehicle_paths.append(path)
            index += 1

        collisions = find_collisions(vehicle_paths)
        if collisions:
            results.extend(["{} {}".format(p[0], p[1]) for p in collisions])
        else:
            results.append("No collisions")

    return "\n".join(results)

