def combination_sum(arr, target):
    """
    Returns all unique combinations of arr where the numbers sum to target.
    """
    # We'll use a recursive helper function to generate the combinations.
    def backtrack(start, target, path, res):
        if target == 0:
            res.append(path)
            return
        if target < 0:
            return
        for i in range(start, len(arr)):
            if i > start and arr[i] == arr[i - 1]:
                continue
            backtrack(i + 1, target - arr[i], path + [arr[i]], res)

    arr.sort()
    result = []
    backtrack(0, target, [], result)
    return result

