def gcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def canMeasureWater(x: int, y: int, z: int) -> bool:
    """
    Determine if it's possible to measure exactly z liters using jugs of size x and y.
    """
    # If z exceeds the combined capacity of both jugs, it's impossible
    if z > x + y:
        return False

    # If z is 0, it's always possible (just have both jugs empty)
    if z == 0:
        return True

    # Use the properties of the greatest common divisor (GCD)
    return z % gcd(x, y) == 0

