def can_survivors_reach_safety(test_cases):
    results = []
    for case in test_cases:
        n, keys_distances, gates_distances = case
        keys_distances.sort()
        gates_distances.sort()

        can_reach = True
        for i in range(n):
            if keys_distances[i] >= gates_distances[i]:
                can_reach = False
                break

        if can_reach:
            results.append("Survivors can reach safety")
        else:
            results.append("Survivors cannot reach safety")

    return results

