def canFrogsCross(stones, strengths):
    if not stones:
        return 'No'
    max_stone = stones[-1]

    for strength in strengths:
        position = 0
        for stone in stones:
            if stone - position <= strength:
                position = stone
            if position == max_stone:
                break
        if position != max_stone:
            return 'No'
    return 'Yes'

