def find_non_repeating(array):
    """
    Returns the first non-repeating element of the array.
    If all elements repeat or the array is empty, returns None.
    """
    if not array:
        return None

    element_count = {}

    # First pass: count the occurrences of each element
    for element in array:
        if element in element_count:
            element_count[element] += 1
        else:
            element_count[element] = 1

    # Second pass: find the first element with count 1
    for element in array:
        if element_count[element] == 1:
            return element

    return None

