def firstUniqChar(s):
    """
    Returns the index of the first non-repeating character in the string s.
    If there is no non-repeating character, return -1.
    """
    # Create a dictionary to store character frequencies
    char_count = {}

    # Populate the dictionary with the count of each character in the string
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Iterate through the string again and return the index of the first non-repeating character
    for index, char in enumerate(s):
        if char_count[char] == 1:
            return index

    # If no non-repeating character is found, return -1
    return -1

