def find_missing_number(n, numbers):
    """
    Returns the missing number from the array.
    """
    expected_sum = n * (n + 1) // 2
    actual_sum = sum(numbers)
    return expected_sum - actual_sum

def process_test_cases(T, cases):
    if T < 1 or T > 10:
        return "Invalid Test"

    results = []
    for N, array in cases:
        if N < 2 or N > 100 or len(array) != N - 1:
            results.append("Invalid Input")
        else:
            results.append(find_missing_number(N, array))
    return results

