def longest_non_decreasing_subsequence_length(nums):
    """
    Returns the length of the longest non-decreasing consecutive sub-sequence in the list of temperatures nums.
    """
    if not nums:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(nums)):
        if nums[i] >= nums[i - 1]:
            current_length += 1
            max_length = max(max_length, current_length)
        else:
            current_length = 1

    return max_length

