def prime_spell_operations(n, array, operations):
    results = []

    def power_operation(x, v):
        array[x - 1] = v

    def spell_potency_operation(l, r, p):
        s = sum(x ** p for x in array[l-1:r])
        results.append(s)

    for op in operations:
        if op[0] == 1:
            power_operation(op[1], op[2])
        elif op[0] == 2:
            spell_potency_operation(op[1], op[2], op[3])

    return results

