def evaluate_expression(expression):
    """
    Evaluates a mathematical expression containing non-negative integers and '+', '-', '*', '/' operators.
    The expression may include whitespace characters which should be ignored.
    """
    # Remove all whitespace characters
    expression = expression.replace(" ", "")

    stack = []
    num = 0
    sign = '+'

    for i, char in enumerate(expression):
        if char.isdigit():
            num = num * 10 + int(char)
        if char in "+-*/" or i == len(expression) - 1:
            if sign == '+':
                stack.append(num)
            elif sign == '-':
                stack.append(-num)
            elif sign == '*':
                stack[-1] = stack[-1] * num
            elif sign == '/':
                stack[-1] = int(stack[-1] / num)  # Truncate towards zero

            sign = char
            num = 0

    return sum(stack)

