def three_sum_zero(nums):
    """
    Returns True if there are three distinct elements in nums that sum up to zero, else False.
    """
    nums.sort()
    n = len(nums)

    for i in range(n - 2):
        # To avoid duplicates
        if i > 0 and nums[i] == nums[i - 1]:
            continue

        left, right = i + 1, n - 1

        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1

    return False

