def findPairWithGivenDifference(arr, K):
    """
    Returns True if there exists a pair of elements in the list such that their difference is exactly K.
    """
    num_set = set(arr)
    for num in arr:
        if (num + K) in num_set or (num - K) in num_set:
            return True
    return False

def are_permutations(str1, str2):
    """
    Determines if one string is a permutation of the other.
    """
    if len(str1) != len(str2):
        return False

    # Sort both strings and compare
    return sorted(str1) == sorted(str2)

