def closestDistance(S, C):
    n = len(S)
    result = [float('inf')] * n

    # First pass: Left to right
    prev_pos = -float('inf')
    for i in range(n):
        if S[i] == C:
            prev_pos = i
        result[i] = i - prev_pos

    # Second pass: Right to left
    prev_pos = float('inf')
    for i in range(n-1, -1, -1):
        if S[i] == C:
            prev_pos = i
        result[i] = min(result[i], prev_pos - i)

    return result

