def is_almost_palindrome(s):
    """
    Determines if a string can be made into a palindrome by removing at most one character.
    """
    def is_palindrome_range(i, j):
        while i < j:
            if s[i] != s[j]:
                return False
            i += 1
            j -= 1
        return True

    i, j = 0, len(s) - 1
    while i < j:
        if s[i] != s[j]:
            return is_palindrome_range(i + 1, j) or is_palindrome_range(i, j - 1)
        i += 1
        j -= 1
    return True

def process_test_cases(t, test_cases):
    results = []
    for s in test_cases:
        if is_almost_palindrome(s):
            results.append("YES")
        else:
            results.append("NO")
    return results

