def three_sum_closest(nums, target):
    nums.sort()  # Sort the array to use the two-pointer strategy efficiently
    n = len(nums)
    closest_sum = float('inf')

    for i in range(n - 2):
        # Fix one element and use two-pointer approach for the rest
        left, right = i + 1, n - 1
        while left < right:
            current_sum = nums[i] + nums[left] + nums[right]

            if abs(current_sum - target) < abs(closest_sum - target):
                closest_sum = current_sum  # Update closest_sum if the current one is closer

            if current_sum < target:
                left += 1  # Move left pointer to the right to increase the sum
            elif current_sum > target:
                right -= 1  # Move right pointer to the left to decrease the sum
            else:
                # If current_sum is exactly the target, we can return it directly
                return current_sum

    return closest_sum

