def num_trees(n):
    """
    Returns the number of structurally unique BSTs that have exactly n nodes of unique values from 1 to n.
    """
    if n == 0 or n == 1:
        return 1

    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1

    for nodes in range(2, n + 1):
        for root in range(1, nodes + 1):
            dp[nodes] += dp[root - 1] * dp[nodes - root]

    return dp[n]

