def count_balanced_subsegments(n, d):
    """
    Returns the number of balanced subsegments.

    :param n: int - The size of the compressed sequence
    :param d: List[int] - List containing the lengths of segments in the compressed sequence
    :return: int - Total number of balanced subsegments
    """
    total_subsegments = 0

    for start in range(n):
        dots = 0
        dashes = 0
        for end in range(start, n):
            if (end - start) % 2 == 0:
                dashes += d[end]
            else:
                dots += d[end]

            if dots == dashes:
                total_subsegments += 1

    return total_subsegments

