import heapq
from collections import defaultdict
import sys

def shortest_path(N, M, roads):
    graph = defaultdict(list)
    for u, v, l in roads:
        graph[u].append((v, l))
        graph[v].append((u, l))

    # Dijkstra's algorithm
    queue = [(0, 1)]  # (distance, node)
    distances = {i: float('inf') for i in range(1, N+1)}
    distances[1] = 0

    while queue:
        current_distance, current_node = heapq.heappop(queue)

        if current_distance > distances[current_node]:
            continue

        for neighbor, weight in graph[current_node]:
            distance = current_distance + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(queue, (distance, neighbor))

    return distances[N] if distances[N] != float('inf') else -1

# Example test function which reads input and utilizes the function
def find_shortest_path_from_input(input_data):
    input_lines = input_data.strip().split('\n')
    first_line = list(map(int, input_lines[0].split()))
    N, M = first_line[0], first_line[1]
    roads = [tuple(map(int, line.split())) for line in input_lines[1:]]
    return shortest_path(N, M, roads)

