def longest_arith_seq_length(nums):
    """
    Returns the length of the longest arithmetic subsequence in nums.
    """
    if not nums:
        return 0

    n = len(nums)
    if n <= 2:
        return n

    dp = [{} for _ in range(n)]
    max_len = 2

    for i in range(1, n):
        for j in range(i):
            diff = nums[i] - nums[j]
            if diff in dp[j]:
                dp[i][diff] = dp[j][diff] + 1
            else:
                dp[i][diff] = 2

            max_len = max(max_len, dp[i][diff])

    return max_len

