def caesar_cipher(s, k):
    """
    Encrypts the input string s using Caesar Cipher with a shift of k.

    Parameters:
    s (str): The string to be encrypted.
    k (int): The shift value.

    Returns:
    str: The encrypted string.
    """
    encrypted = []
    for char in s:
        if char.isalpha():
            shift = k % 26  # Reduce the shift within the range of the alphabet
            new_char = ''
            if char.islower():
                new_char = chr((ord(char) - ord('a') + shift) % 26 + ord('a'))
            elif char.isupper():
                new_char = chr((ord(char) - ord('A') + shift) % 26 + ord('A'))
            encrypted.append(new_char)
        else:
            encrypted.append(char)
    return ''.join(encrypted)

def longest_contiguous_distinct_subarray(n, arr):
    """
    Returns the length of the longest contiguous subarray where all elements are distinct.
    """
    if n == 0:
        return 0

    seen = {}
    start = 0
    max_length = 0

    for end in range(n):
        if arr[end] in seen:
            start = max(start, seen[arr[end]] + 1)

        seen[arr[end]] = end
        max_length = max(max_length, end - start + 1)

    return max_length

