def can_assign_instruments(test_cases):
    results = []

    for case in test_cases:
        n, instruments = case
        instruments.sort()

        for i in range(1, n):
            if instruments[i] == instruments[i - 1]:
                instruments[i] += 1

        if len(set(instruments)) == n:
            results.append(f"YES {' '.join(map(str, instruments))}")
        else:
            results.append("NO")

    return results

