def smallest_window_with_subsequence(S, T):
    S_len, T_len = len(S), len(T)
    dp = [[-1] * (T_len + 1) for _ in range(S_len + 1)]

    for i in range(S_len + 1):
        dp[i][0] = i

    for i in range(1, S_len + 1):
        for j in range(1, T_len + 1):
            if S[i - 1] == T[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = dp[i - 1][j]

    start, min_len = -1, float('inf')
    for i in range(1, S_len + 1):
        if dp[i][T_len] != -1:
            cur_len = i - dp[i][T_len]
            if cur_len < min_len:
                min_len = cur_len
                start = dp[i][T_len]

    if start == -1:
        return -1
    else:
        return start + 1, start + min_len

