def collect_leaves(N, M, park, allergy_trees):
    unique_trees = set()
    for r in range(N):
        if r % 2 == 0:
            # Move right
            for c in range(M):
                if park[r][c] not in allergy_trees:
                    unique_trees.add(park[r][c])
        else:
            # Move left
            for c in range(M-1, -1, -1):
                if park[r][c] not in allergy_trees:
                    unique_trees.add(park[r][c])

    return len(unique_trees)

