def max_grid_sum(T, test_cases):
    results = []

    for case in test_cases:
        M, N, grid = case['M'], case['N'], case['grid']

        max_sum = 0  # Initialize sum accumulator

        for row in grid:
            for value in row:
                if value < 0:
                    max_sum -= value  # Add the absolute value of the negative number
                else:
                    max_sum += value  # Add the positive number

        results.append(max_sum)

    return results

