def longest_divisible_subarray(t, test_cases):
    results = []

    def find_longest_subarray(n, k, a):
        max_len = 0
        current_len = 0

        for num in a:
            if num % k == 0:
                current_len += 1
                max_len = max(max_len, current_len)
            else:
                current_len = 0

        return max_len

    for case in test_cases:
        n, k, a = case
        results.append(find_longest_subarray(n, k, a))

    return results

