def num_paths(grid):
    """
    Calculates the number of unique paths from the top-left corner to the bottom-right corner
    in a grid with some cells being obstacles (trees). The only moves allowed are right or down.

    Parameters:
    grid (List[List[int]]): A 2D list representing the grid. 1 denotes a tree, 0 denotes walkable terrain.

    Returns:
    int: The number of unique paths from the top-left to the bottom-right corner.
    """
    if not grid or grid[0][0] == 1 or grid[-1][-1] == 1:
        return 0

    m, n = len(grid), len(grid[0])
    dp = [[0 for _ in range(n)] for _ in range(m)]

    dp[0][0] = 1

    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[-1][-1]

