def longest_increasing_subsequence(sequence):
    if not sequence:
        return 0

    n = len(sequence)
    dp = [1] * n  # Initialize dp array with 1

    for i in range(1, n):
        for j in range(i):
            if sequence[i] > sequence[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

