import heapq

def dijkstra(n, roads, A, B):
    graph = {i: [] for i in range(1, n+1)}
    for x, y, d in roads:
        graph[x].append((y, d))
        graph[y].append((x, d))

    distances = {i: float('inf') for i in range(1, n+1)}
    distances[A] = 0
    priority_queue = [(0, A)]

    while priority_queue:
        current_distance, current_town = heapq.heappop(priority_queue)

        if current_distance > distances[current_town]:
            continue

        for neighbor, weight in graph[current_town]:
            distance = current_distance + weight
            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(priority_queue, (distance, neighbor))

    return distances[B] if distances[B] != float('inf') else -1

def minimum_distance(n, m, A, B, roads):
    return dijkstra(n, roads, A, B)

