def analyze_inventory(inventory):
    size_limits = {
        "small": 10,
        "medium": 5,
        "large": 2
    }

    count_dict = {}

    # Initialize the count dictionary
    for size in size_limits:
        count_dict[size] = 0

    # Count pets by size
    for pet in inventory:
        size = pet['size']
        if size in count_dict:
            count_dict[size] += 1

    result = {}

    for size in size_limits:
        num_pets = count_dict[size]
        pen_limit = size_limits[size]

        pens_ready = num_pets // pen_limit
        pets_left = num_pets % pen_limit

        result[size] = {
            "pens_ready": pens_ready,
            "pets_left": pets_left
        }

    return result

