from collections import Counter

def can_group_rocks(t, cases):
    results = []
    for i in range(t):
        n, k = cases[i][0]
        weights = cases[i][1]
        weight_counts = Counter(weights)

        possible = True
        for count in weight_counts.values():
            if count % k != 0:
                possible = False
                break

        if possible:
            results.append("YES")
        else:
            results.append("NO")

    return results

