def floyd_warshall(n, edges):
    # Initialize distance matrix with infinity
    dist = [[float('inf')] * n for _ in range(n)]

    # Distance from a city to itself is 0
    for i in range(n):
        dist[i][i] = 0

    # Populate the distance matrix with the given edges
    for u, v, t in edges:
        dist[u-1][v-1] = t
        dist[v-1][u-1] = t

    # Floyd-Warshall algorithm to find all pairs shortest paths
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

def min_travel_time(n, m, q, roads, queries):
    dist = floyd_warshall(n, roads)

    result = []
    for a, b in queries:
        if dist[a-1][b-1] == float('inf'):
            result.append(-1)
        else:
            result.append(dist[a-1][b-1])

    return result

