def aquarium_system(queries):
    registered_fish = {}
    current_day = 0
    results = []

    for query in queries:
        parts = query.split()
        if parts[0] == "1":
            current_day += 1
            i, d = int(parts[1]), int(parts[2])
            registered_fish[i] = (d, current_day)
        elif parts[0] == "2":
            current_day += 1
            i = int(parts[1])
            if i in registered_fish:
                del registered_fish[i]
        elif parts[0] == "3":
            current_day += 1
            all_alive = True
            for fish_id, (lifespan, registered_day) in registered_fish.items():
                if current_day - registered_day >= lifespan:
                    all_alive = False
                    break
            results.append("YES" if all_alive else "NO")

    return results

