def battleship_count(grid):
    def sink_ship(r, c):
        """ Mark the entire ship starting from (r, c) """
        # Use a stack for iterative DFS
        stack = [(r, c)]
        while stack:
            i, j = stack.pop()
            grid[i][j] = '0'  # Mark the cell as visited
            # Explore all 4 directions (up, down, left, right)
            for ni, nj in [(i-1, j), (i+1, j), (i, j-1), (i, j+1)]:
                if 0 <= ni < 10 and 0 <= nj < 10 and grid[ni][nj] == '1':
                    stack.append((ni, nj))

    ships = 0
    for row in range(10):
        for col in range(10):
            if grid[row][col] == '1':  # Found an unvisited part of a ship
                ships += 1
                sink_ship(row, col)

    return ships

