def count_pairs_with_sum(arr, target_sum):
    """
    Returns the number of distinct pairs of integers in the list that add up to the target sum.
    Each pair should be counted only once, regardless of the order of integers in the pair.
    """
    seen = set()
    pairs = set()

    for number in arr:
        complement = target_sum - number
        if complement in seen:
            pairs.add((min(number, complement), max(number, complement)))
        seen.add(number)

    return len(pairs)

