def is_subsequence(target, candidate):
    it = iter(target)
    return all(char in it for char in candidate)

def find_longest_subsequence(n, T, candidates):
    longest_match = ""
    for candidate in candidates:
        if is_subsequence(T, candidate):
            if len(candidate) > len(longest_match):
                longest_match = candidate
            elif len(candidate) == len(longest_match) and candidates.index(candidate) < candidates.index(longest_match):
                longest_match = candidate
    return longest_match if longest_match else "No Match"

