def maximum_path_sum(pyramid):
    """
    Given a nested list of integers representing a pyramid, return the maximum path sum from the top to the bottom.
    """
    if not pyramid:
        return 0

    # Start from the second last row and move upwards
    for row in range(len(pyramid) - 2, -1, -1):
        for col in range(len(pyramid[row])):
            pyramid[row][col] += max(pyramid[row + 1][col], pyramid[row + 1][col + 1])

    return pyramid[0][0]

