def max_trash_collected(N, trash):
    if N == 0:
        return 0
    if N == 1:
        return trash[0]

    dp = [0] * N
    dp[0] = trash[0]

    if N > 1:
        dp[1] = max(trash[0], trash[1])

    if N > 2:
        dp[2] = max(trash[0] + trash[2], trash[1])

    if N > 3:
        dp[3] = max(trash[0] + trash[3], trash[1] + trash[3])

    for i in range(4, N):
        dp[i] = max(dp[i-1], dp[i-2] + trash[i], dp[i-3] + trash[i], dp[i-4] + trash[i])

    return max(dp)

def solve_neighborhood_cleanup(T, cases):
    results = []
    for i in range(T):
        N, trash = cases[i]
        results.append(max_trash_collected(N, trash))
    return results

