def elevator_sequence(current_floor, target_floor):
    """
    Returns the sequence of floors the elevator will go through to reach the target floor.
    """
    if current_floor == target_floor:
        return [current_floor]

    step = 1 if target_floor > current_floor else -1
    return list(range(current_floor, target_floor + step, step))

