from collections import defaultdict, deque

def max_commodities(N, M, commodities, roads):
    # Build graph
    graph = defaultdict(list)
    for u, v in roads:
        graph[u].append(v)

    # Function to perform DFS and find maximum commodities
    def dfs(start):
        stack = [(start, set())]
        max_commodities_collected = 0

        while stack:
            city, collected_commodities = stack.pop()
            collected_commodities.add(commodities[city - 1])

            max_commodities_collected = max(max_commodities_collected, len(collected_commodities))

            for neighbor in graph[city]:
                if commodities[neighbor - 1] not in collected_commodities:
                    stack.append((neighbor, collected_commodities.copy()))

        return max_commodities_collected

    max_commodities_result = 0
    for city in range(1, N + 1):
        max_commodities_result = max(max_commodities_result, dfs(city))

    return max_commodities_result

