def num_decodings(s):
    if not s or s[0] == '0':
        return 0

    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        one_digit = int(s[i-1])
        two_digits = int(s[i-2:i])

        if 1 <= one_digit <= 9:
            dp[i] += dp[i-1]
        if 10 <= two_digits <= 26:
            dp[i] += dp[i-2]

    return dp[n]

def decode_messages(messages):
    results = []
    for message in messages:
        results.append(num_decodings(message))
    return results

def uniquePaths(N, M, BlockedCells):
    # Create a 2D DP array initialized to 0
    dp = [[0] * M for _ in range(N)]

    # If the starting cell is not blocked, set it to 1
    if (0, 0) not in BlockedCells:
        dp[0][0] = 1

    # Convert BlockedCells to a set for faster lookup
    blocked_set = set(BlockedCells)

    # Fill the DP array
    for i in range(N):
        for j in range(M):
            if (i, j) in blocked_set:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[N-1][M-1]

