def ensure_distance(grid, n, m, d):
    Bs = []
    for i in range(n):
        for j in range(m):
            if grid[i][j] == 'B':
                Bs.append((i, j))

    for x1, y1 in Bs:
        for x2, y2 in Bs:
            if (x1, y1) != (x2, y2) and abs(x1 - x2) + abs(y1 - y2) < d:
                return "Impossible"

    output = [''.join(row) for row in grid]
    return output

# Function to parse input and produce output for each test case
def solve_problems(t, test_cases):
    results = []
    for case in test_cases:
        n, m, d, grid = case
        result = ensure_distance(grid, n, m, d)
        results.append(result)
    return results

