            interest_rate = 0.04
        else:
            interest_rate = 0.05
    elif account_type == "Fixed":
        if deposit_amount <= 5000:
            interest_rate = 0.06
        else:
            interest_rate = 0.07
    elif account_type == "Recurring":
        if deposit_amount <= 2000:
            interest_rate = 0.08
        else:
            interest_rate = 0.09

    return round(deposit_amount * interest_rate * years, 2)

def process_customers(customers):
    """
    Process multiple customers to calculate their interest earned.

    Parameters:
    customers (list of tuples): List of tuples containing account type, deposit amount, and years.

    Returns:
    list of float: List of interest earned for each customer.
    """
    results = []
    for account_type, deposit_amount, years in customers:
        interest = calculate_interest(account_type, deposit_amount, years)
        results.append(interest)
    return results

