def min_operations_to_equalize_array(arr):
    """
    Returns the minimum number of operations required to make all elements of the array equal,
    or -1 if it is not possible.
    """
    if len(arr) == 0:
        return -1

    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    n = len(arr)
    overall_gcd = arr[0]

    for num in arr[1:]:
        overall_gcd = gcd(overall_gcd, num)

    if overall_gcd != arr[0]:
        return -1

    operations = 0
    for num in arr:
        operations += (num // overall_gcd - 1)

    return operations

