def character_indices(s):
    """
    Returns a dictionary where the keys are the unique characters in the string `s` and the values are lists containing
    the indices of each occurrence of those characters in the string.
    """
    result = {}
    for index, char in enumerate(s):
        if char in result:
            result[char].append(index)
        else:
            result[char] = [index]
    return result

