def min_sensors(n, m, grid):
    def is_monitored(i, j, sensors):
        # Check current position and directly adjacent positions
        for di, dj in [(0, 0), (1, 0), (-1, 0), (0, 1), (0, -1)]:
            ni, nj = i + di, j + dj
            if 0 <= ni < n and 0 <= nj < m and sensors[ni][nj]:
                return True
        return False

    def place_sensors(sensors):
        # Place a sensor on unmonitored artwork adjacent cells
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 'A' and not is_monitored(i, j, sensors):
                    sensor_placed = False
                    for di, dj in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                        ni, nj = i + di, j + dj
                        if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.':
                            sensors[ni][nj] = True
                            sensor_placed = True
                            break
                    if not sensor_placed:
                        return -1
        return sum(sum(row) for row in sensors)

    # Initialize the sensor grid
    sensors = [[False] * m for _ in range(n)]
    return place_sensors(sensors)

def fibonacci(n):
    """
    Returns the nth Fibonacci number if n is a non-negative integer.
    If n is not an integer or is negative, returns -1.
    """
    if not isinstance(n, int) or n < 0:
        return -1

    if n == 0:
        return 0
    if n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

