def max_score(tokens):
    n = len(tokens)
    if n == 0:
        return 0
    if n == 1:
        return max(0, tokens[0])

    dp = [0] * n
    dp[0] = max(0, tokens[0])
    dp[1] = max(dp[0], tokens[1])

    for i in range(2, n):
        dp[i] = max(dp[i - 1], dp[i - 2] + tokens[i])

    return dp[-1]

def solve_game(n, token_values):
    return max_score(token_values)

