def max_depth(arr):
    """
    Returns the maximum depth of nested arrays within the provided array.
    """
    if not isinstance(arr, list):
        return 0

    def find_depth(item):
        if isinstance(item, list):
            return 1 + max((find_depth(subitem) for subitem in item), default=0)
        else:
            return 0

    return 1 + max((find_depth(item) for item in arr), default=0)

