def num_islands(matrix):
    if not matrix:
        return 0

    N = len(matrix)
    M = len(matrix[0])

    def dfs(matrix, i, j):
        if i < 0 or j < 0 or i >= N or j >= M or matrix[i][j] == 0:
            return
        matrix[i][j] = 0  # Mark the land as visited
        # visit all 4 adjacent cells (up, down, left, right)
        dfs(matrix, i+1, j)
        dfs(matrix, i-1, j)
        dfs(matrix, i, j+1)
        dfs(matrix, i, j-1)

    island_count = 0

    for i in range(N):
        for j in range(M):
            if matrix[i][j] == 1:
                island_count += 1
                dfs(matrix, i, j)

    return island_count

def filter_products(products, filters):
    """
    Returns a list of products that match all the specified filters.
    """
    filtered_products = []
    for product in products:
        matches_all_filters = True
        for key, value in filters.items():
            if key not in product or product[key] != value:
                matches_all_filters = False
                break
        if matches_all_filters:
            filtered_products.append(product)
    return filtered_products

