def isPower(x):
    if x < 2:
        return False

    for base in range(2, int(x**0.5) + 1):
        temp = x
        while temp % base == 0:
            temp //= base
        if temp == 1:
            return True

    return False

def longest_bitonic_subsequence(arr):
    n = len(arr)

    if n == 0:
        return 0

    # Create arrays to store the length of longest increasing subsequence
    # ending at each index and starting at each index
    lis = [1] * n
    lds = [1] * n

    # Compute the LIS values from left to right
    for i in range(1, n):
        for j in range(0, i):
            if arr[i] > arr[j] and lis[i] < lis[j] + 1:
                lis[i] = lis[j] + 1

    # Compute the LDS values from right to left
    for i in reversed(range(n-1)): # or (n-2) to -1
        for j in range(n-1, i, -1):
            if arr[i] > arr[j] and lds[i] < lds[j] + 1:
                lds[i] = lds[j] + 1

    # Compute the maximum value of (lis[i] + lds[i] - 1)
    max_bitonic_length = 0
    for i in range(n):
        max_bitonic_length = max(max_bitonic_length, lis[i] + lds[i] - 1)

    return max_bitonic_length

