def max_profit(prices):
    """
    Calculate the maximum profit that can be achieved by executing
    at most one buy and one sell operation.
    """
    if not prices:
        return 0

    min_price = float('inf')
    max_profit = 0

    for price in prices:
        if price < min_price:
            min_price = price
        elif price - min_price > max_profit:
            max_profit = price - min_price

    return max_profit

