def find(parent, i):
    if parent[i] == i:
        return i
    return find(parent, parent[i])

def union(parent, rank, x, y):
    xroot = find(parent, x)
    yroot = find(parent, y)
    if rank[xroot] < rank[yroot]:
        parent[xroot] = yroot
    elif rank[xroot] > rank[yroot]:
        parent[yroot] = xroot
    else:
        parent[yroot] = xroot
        rank[xroot] += 1

def min_cable_to_upgrade(n, m, edges):
    edges.sort(key=lambda x: x[2])
    parent = []
    rank = []
    for node in range(n):
        parent.append(node)
        rank.append(0)

    result = []
    i, e = 0, 0
    while e < n - 1 and i < len(edges):
        u, v, w = edges[i]
        i += 1
        x = find(parent, u - 1)
        y = find(parent, v - 1)
        if x != y:
            e += 1
            result.append((u, v, w))
            union(parent, rank, x, y)

    if len(result) != n - 1:
        return -1
    min_bottleneck = min(result, key=lambda x: x[2])[2]
    return min_bottleneck

