def max_gold(grid):
    """
    Returns the maximum amount of gold a player can collect from the leftmost column to the rightmost column.
    """
    n = len(grid)
    m = len(grid[0])

    dp = [[0] * m for _ in range(n)]

    for col in range(m-1, -1, -1):
        for row in range(n):
            right = dp[row][col+1] if col < m-1 else 0
            right_up = dp[row-1][col+1] if row > 0 and col < m-1 else 0
            right_down = dp[row+1][col+1] if row < n-1 and col < m-1 else 0

            dp[row][col] = grid[row][col] + max(right, right_up, right_down)

    return max(dp[row][0] for row in range(n))

def max_gold_collected(test_cases):
    results = []
    for n, m, grid in test_cases:
        results.append(max_gold(grid))
    return results

