def modify_string(s):
    """
    Modify the input string based on the specified rules.
    """
    if not s:
        return "Empty String"

    if s.isalpha():
        reversed_s = s[::-1]
        return ''.join([char.lower() if char.isupper() else char.upper() for char in reversed_s])

    if s.isdigit():
        return str(sum(int(char) for char in s))

    if all(char.isalnum() for char in s):
        result = []
        for char in s:
            if char.isalpha():
                position = ord(char.lower()) - ord('a') + 1
                result.append(str(position))
            else:
                result.append(char)
        return ''.join(result)

    return "Invalid Input"

