def fibonacci(N):
    """
    Returns the Nth number in the Fibonacci sequence.
    """
    if N == 0:
        return 0
    elif N == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, N + 1):
            a, b = b, a + b
        return b

