def three_sum_zero(arr):
    """
    Determines if there exist three distinct elements in the list that sum to zero.

    Parameters:
    arr (list): List of unique integers.

    Returns:
    str: "YES" if such triplet exists, otherwise "NO".
    """
    arr.sort()
    n = len(arr)
    for i in range(n - 2):
        if i > 0 and arr[i] == arr[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            total = arr[i] + arr[left] + arr[right]
            if total == 0:
                return "YES"
            elif total < 0:
                left += 1
            else:
                right -= 1
    return "NO"

def numDistinctPaths(N, M, grid):
    if grid[0][0] == '#' or grid[-1][-1] == '#':
        return 0

    dp = [[0] * M for _ in range(N)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

    return dp[-1][-1]

