def min_actions_to_defeat_monster(t, test_cases):
    results = []
    for idx in range(t):
        n = test_cases[idx][0]
        actions = sorted(test_cases[idx][1], reverse=True)
        m = test_cases[idx][2]
        monsters = test_cases[idx][3]

        for monster_hp in monsters:
            remaining_hp = monster_hp
            action_count = 0
            for action in actions:
                remaining_hp -= action
                action_count += 1
                if remaining_hp <= 0:
                    results.append(action_count)
                    break

            if remaining_hp > 0:
                results.append(-1)

    return results

def is_continuous_session(timestamps, timeout):
    """
    Determines if a user's session is continuous based on given timestamps and timeout period.

    :param timestamps: List of integer timestamps in seconds representing user activity
    :param timeout: Integer timeout period in seconds
    :return: Boolean indicating if the session is continuous
    """
    if len(timestamps) <= 1:
        return True

    for i in range(1, len(timestamps)):
        if timestamps[i] - timestamps[i - 1] > timeout:
            return False

    return True

