                subtree_nodes.extend(dfs(child))

        for sub_node in subtree_nodes:
            if sub_node > node:
                count[node-1] += 1

        return subtree_nodes

    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    count = [0] * n
    visited = [False] * (n + 1)

