def find_shortest_loop(n, coordinates):
    visited = {}
    shortest_loop = float('inf')
    loop_found = False

    for i, coord in enumerate(coordinates):
        if coord in visited:
            loop_length = i - visited[coord] + 1
            shortest_loop = min(shortest_loop, loop_length)
            loop_found = True
        visited[coord] = i

    return shortest_loop if loop_found else -1

