def process_queries(R, C, grid, queries):
    result = []
    for query in queries:
        q = query.split()
        t = int(q[0])
        if t == 1:
            r1, c1, r2, c2 = map(int, q[1:])
            for r in range(r1, r2 + 1):
                for c in range(c1, c2 + 1):
                    grid[r][c] += 1
        elif t == 2:
            r, c = map(int, q[1:])
            result.append(grid[r][c])
    return result

def floyd_warshall(n, rates):
    from collections import defaultdict
    import math

    dist = defaultdict(lambda: defaultdict(lambda: math.inf))

    for u in range(n):
        dist[chr(ord('A') + u)][chr(ord('A') + u)] = 1.0

    for u, v, r in rates:
        dist[u][v] = r

    for k in range(n):
        for i in range(n):
            for j in range(n):
                dist[chr(ord('A') + i)][chr(ord('A') + j)] = min(
                    dist[chr(ord('A') + i)][chr(ord('A') + j)],
                    dist[chr(ord('A') + i)][chr(ord('A') + k)] * dist[chr(ord('A') + k)][chr(ord('A') + j)]
                )

    return dist

def find_exchange_rates(n, m, rates, queries):
    dist = floyd_warshall(n, rates)
    results = []
    for u, v in queries:
        if dist[u][v] == float('inf'):
            results.append(-1)
        else:
            results.append(dist[u][v])
    return results

def is_prime(x):
    """
    Returns True if x is a prime number, False otherwise.
    """
    if x <= 1:
        return False
    if x <= 3:
        return True
    if x % 2 == 0 or x % 3 == 0:
        return False
    i = 5
    while i * i <= x:
        if x % i == 0 or x % (i + 2) == 0:
            return False
        i += 6
    return True

