def longest_increasing_streak(step_counts):
    """
    Returns the length of the longest increasing subsequence within the given daily step counts.
    :param step_counts: List of integers, ending with -1, representing daily step counts.
    :return: Length of the longest increasing subsequence.
    """
    # Remove the terminating -1 from the list
    step_counts = step_counts[:-1]

    if not step_counts:
        return 0

    # Initialize the length of the longest streak
    longest_streak = 1
    current_streak = 1

    # Iterate over the step counts
    for i in range(1, len(step_counts)):
        if step_counts[i] > step_counts[i - 1]:
            current_streak += 1
        else:
            if current_streak > longest_streak:
                longest_streak = current_streak
            current_streak = 1

    return max(longest_streak, current_streak)

