def min_awards(t, test_cases):
    results = []
    for i in range(t):
        n, ratings = test_cases[i]
        if n == 1:
            results.append(1)
            continue

        awards = [1] * n

        # Left to right scan
        for j in range(1, n):
            if ratings[j] > ratings[j - 1]:
                awards[j] = awards[j - 1] + 1

        # Right to left scan
        for j in range(n - 2, -1, -1):
            if ratings[j] > ratings[j + 1]:
                awards[j] = max(awards[j], awards[j + 1] + 1)

        results.append(sum(awards))

    return results


def parse_input(input_str):
    lines = input_str.strip().split('\n')
    t = int(lines[0])
    test_cases = []
    index = 1
    for _ in range(t):
        n = int(lines[index])
        ratings = list(map(int, lines[index + 1].split()))
        test_cases.append((n, ratings))
        index += 2
    return t, test_cases


def format_output(results):
    return '\n'.join(map(str, results))

def min_removals_to_make_non_decreasing(T, test_cases):
    def length_of_lis(sequence):
        if not sequence:
            return 0
        lis = [sequence[0]]
        for height in sequence[1:]:
            if height >= lis[-1]:
                lis.append(height)
            else:
                left, right = 0, len(lis) - 1
                while left < right:
                    mid = (left + right) // 2
                    if lis[mid] < height:
                        left = mid + 1
                    else:
                        right = mid
                lis[left] = height
        return len(lis)

    results = []
    for i in range(T):
        N = test_cases[i][0]
        heights = test_cases[i][1]
        len_lis = length_of_lis(heights)
        results.append(N - len_lis)
    return results

