def max_buildings_in_subsequences(n, heights):
    def longest_non_decreasing_subseq(arr):
        if not arr:
            return []

        # Initialize the DP array with the last element
        dp = [arr[0]]

        for i in range(1, len(arr)):
            if arr[i] >= dp[-1]:
                dp.append(arr[i])
            else:
                for j in range(len(dp)):
                    if dp[j] > arr[i]:
                        dp[j] = arr[i]
                        break
        return dp

    def longest_non_increasing_subseq(arr):
        if not arr:
            return []

        # Initialize the DP array with the last element
        dp = [arr[0]]

        for i in range(1, len(arr)):
            if arr[i] <= dp[-1]:
                dp.append(arr[i])
            else:
                for j in range(len(dp)):
                    if dp[j] < arr[i]:
                        dp[j] = arr[i]
                        break
        return dp

    max_buildings = 0

    for i in range(n + 1):
        left = longest_non_decreasing_subseq(heights[:i])
        right = longest_non_increasing_subseq(heights[i:])
        max_buildings = max(max_buildings, len(left) + len(right))

    return max_buildings

