def extract_unique_dates(date_times):
    """
    Given a list of date-time strings in the format "yyyy-mm-dd hh:mm:ss",
    returns a sorted list of unique dates in the format "yyyy-mm-dd".
    """
    dates = set()
    for date_time in date_times:
        date = date_time.split(' ')[0]
        dates.add(date)

    return sorted(dates)

