def calculate_total_points(missions, player_actions):
    mission_points = {mission_id: points for mission_id, points in missions}
    player_scores = {}

    for player_id, mission_id, success in player_actions:
        if player_id not in player_scores:
            player_scores[player_id] = 0
        if success:
            player_scores[player_id] += mission_points[mission_id]

    return player_scores

def is_balanced(sequence):
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in sequence:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
        else:
            continue

    return stack == []

