def is_bipartite(n, edges):
    from collections import deque, defaultdict

    # Create adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    # Initialize color array, -1 indicates no color
    color = [-1] * (n + 1)

    def bfs(start):
        queue = deque([start])
        color[start] = 1  # Start coloring with 1

        while queue:
            node = queue.popleft()
            current_color = color[node]
            next_color = 2 if current_color == 1 else 1

            for neighbor in graph[node]:
                if color[neighbor] == -1:
                    color[neighbor] = next_color
                    queue.append(neighbor)
                elif color[neighbor] == current_color:
                    return False
        return True

    # Check every disconnected component
    for node in range(1, n + 1):
        if color[node] == -1:  # Not colored yet
            if not bfs(node):
                return -1

    # Return coloring starting from 1 to n (ignoring color[0])
    return color[1:]

