def minDifference(arr):
    """
    Returns the minimum difference between the sums of the two subarrays.
    """
    total_sum = sum(arr)
    n = len(arr)

    # Initialize a DP array
    dp = [[False] * (total_sum + 1) for _ in range(n + 1)]

    # There is always a way to get sum 0: by not choosing any element
    for i in range(n + 1):
        dp[i][0] = True

    # Fill the partition table
    for i in range(1, n + 1):
        for j in range(1, total_sum + 1):
            if arr[i-1] <= j:
                # Either include the element or exclude it
                dp[i][j] = dp[i-1][j] or dp[i-1][j-arr[i-1]]
            else:
                dp[i][j] = dp[i-1][j]

    # Find the largest j such that dp[n][j] is true
    # This j will be as close to total_sum / 2 as possible
    min_diff = float('inf')
    for j in range(total_sum // 2 + 1):
        if dp[n][j]:
            min_diff = min(min_diff, abs(total_sum - 2 * j))

    return min_diff

