def is_unique_characters(s):
    """
    Returns "YES" if the string contains all unique characters, otherwise returns "NO".
    """
    # Sort the string and then check adjacent characters
    sorted_s = sorted(s)
    for i in range(1, len(sorted_s)):
        if sorted_s[i] == sorted_s[i - 1]:
            return "NO"
    return "YES"

