def max_consecutive_group_size(T):
    """
    Returns the size of the largest group of participants that can start together
    with consecutive starting times.
    """
    if not T:
        return 0

    T.sort()
    max_count = 1
    current_count = 1

    for i in range(1, len(T)):
        if T[i] == T[i - 1] + 1:
            current_count += 1
        else:
            max_count = max(max_count, current_count)
            current_count = 1

    return max(max_count, current_count)

