def final_position(movements):
    """
    Returns the final coordinates of the robot after the sequence of movements.

    :param str movements: String representing the sequence of movements
    :return: Tuple (x, y) representing the final coordinates of the robot
    """
    x, y = 0, 0

    for move in movements:
        if move == 'U':
            y += 1
        elif move == 'D':
            y -= 1
        elif move == 'L':
            x -= 1
        elif move == 'R':
            x += 1

    return (x, y)

