def max_increasing_triplet_sum(N, A):
    """
    Calculates the maximum sum of an increasing triplet in the array A of size N.
    If no such triplet exists, returns -1.
    """
    # Initialize the maximum sum to -1
    max_sum = -1

    # Iterate over all possible triplets (i, j, k) in the array
    for i in range(N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                if A[i] < A[j] < A[k]:
                    current_sum = A[i] + A[j] + A[k]
                    if current_sum > max_sum:
                        max_sum = current_sum
    return max_sum

