def floyd_warshall(n, roads, queries):
    # Initialize distances matrix with infinity
    inf = float('inf')
    dist = [[inf] * n for _ in range(n)]

    # Distance to self is 0
    for i in range(n):
        dist[i][i] = 0

    # Populate the direct roads
    for u, v, t in roads:
        dist[u-1][v-1] = min(dist[u-1][v-1], t)
        dist[v-1][u-1] = min(dist[v-1][u-1], t)

    # Run Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    # Extract results for the queries
    results = []
    for x, y in queries:
        result = dist[x-1][y-1]
        results.append(result if result != inf else -1)

    return results

def answer_queries(n, m, roads_data, q, queries_data):
    roads = [tuple(road) for road in roads_data]
    queries = [tuple(query) for query in queries_data]
    return floyd_warshall(n, roads, queries)

