from collections import defaultdict, deque

def find_task_order(n, m, task_times, dependencies):
    graph = defaultdict(list)
    indegree = {i: 0 for i in range(1, n + 1)}

    for x, y in dependencies:
        graph[x].append(y)
        indegree[y] += 1

    queue = deque([node for node in range(1, n + 1) if indegree[node] == 0])
    order = []

    while queue:
        node = queue.popleft()
        order.append(node)
        for neighbor in graph[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                queue.append(neighbor)

    if len(order) == n:
        return "POSSIBLE", order
    else:
        return "IMPOSSIBLE", []

# Example usage:
# task_times = [(1, 1), (2, 1), (3, 1), (4, 1)]
# dependencies = [(1, 2), (2, 3), (3, 4), (4, 1)]
