def longest_k_palindrome_substring(s, k):
    def is_k_palindrome_substring(sub):
        n = len(sub)
        mismatches = 0
        for i in range(n // 2):
            if sub[i] != sub[n - i - 1]:
                mismatches += 1
                if mismatches > k:
                    return False
        return True

    n = len(s)
    max_len = 0

    for length in range(1, n + 1):
        for i in range(n - length + 1):
            if is_k_palindrome_substring(s[i:i + length]):
                max_len = max(max_len, length)

    return max_len

def solve_k_palindrome_problem(test_cases):
    results = []
    for s, k in test_cases:
        results.append(longest_k_palindrome_substring(s, k))
    return results

