def generate_pascals_triangle(N):
    """
    Generates the first N rows of Pascal's triangle.
    """
    if N < 0 or N > 30:
        return []

    triangle = []

    for i in range(N):
        row = [1] * (i + 1)
        for j in range(1, i):
            row[j] = triangle[i-1][j-1] + triangle[i-1][j]
        triangle.append(row)

    return triangle

def format_pascals_triangle(triangle):
    """
    Formats Pascal's triangle into a string with each row as a new line.
    """
    return '\n'.join(' '.join(map(str, row)) for row in triangle)

