def has_equal_sum_disjoint_subsets(n, a):
    import itertools

    # Generate all possible subsets of the array
    all_subsets = []
    for i in range(1, n+1):
        all_subsets.extend(itertools.combinations(a, i))

    # Convert each subset into a sum and check for equal sums
    subset_sums = {}

    for subset in all_subsets:
        subset_sum = sum(subset)
        subset_elements = set(subset)

        if subset_sum in subset_sums:
            # Check if the current subset is disjoint with any other subset with the same sum
            for existing_subset in subset_sums[subset_sum]:
                if subset_elements.isdisjoint(existing_subset):
                    return "YES"
            subset_sums[subset_sum].append(subset_elements)
        else:
            subset_sums[subset_sum] = [subset_elements]

    return "NO"

