def sieve(n):
    """Generate a list of primes up to n using the Sieve of Eratosthenes."""
    is_prime = [True] * (n+1)
    p = 2
    while (p * p <= n):
        if (is_prime[p] == True):
            for i in range(p * p, n+1, p):
                is_prime[i] = False
        p += 1
    prime_numbers = [p for p in range(2, n+1) if is_prime[p]]
    return prime_numbers

def count_prime_pairs(k):
    """
    Count the number of distinct pairs of prime numbers (p1, p2)
    such that p1 + p2 = k, where (p1, p2) and (p2, p1) are considered the same pair.
    """
    primes = sieve(k)
    prime_set = set(primes)

    count = 0
    for p1 in primes:
        if p1 > k // 2:
            break
        p2 = k - p1
        if p2 in prime_set:
            count += 1
    return count

def solve_primes(q, queries):
    results = []
    for k in queries:
        results.append(count_prime_pairs(k))
    return results

def push_dominos(s):
    """
    Returns the final state of the domino line after all possible falls have occurred.
    """
    n = len(s)
    forces = [0] * n

    # Apply forces from right-falling dominos
    force = 0
    for i in range(n):
        if s[i] == 'R':
            force = n  # Assign a large positive force
        elif s[i] == 'L':
            force = 0  # Reset the force
        else:
            force = max(force - 1, 0)  # Reduce force by distance, ensuring it's not negative
        forces[i] += force

    # Apply forces from left-falling dominos
    force = 0
    for i in range(n-1, -1, -1):
        if s[i] == 'L':
            force = n  # Assign a large negative force
        elif s[i] == 'R':
            force = 0  # Reset the force
        else:
            force = max(force - 1, 0)  # Reduce force by distance, ensuring it's not negative
        forces[i] -= force

    # Determine final state based on net forces
    result = []
    for f in forces:
        if f == 0:
            result.append('.')
        elif f > 0:
            result.append('R')
        else:
            result.append('L')

    return ''.join(result)

