def find_contest_winners(num_employees, num_days, productivity_data, K):
    """
    Returns a list of indices of employees who have at least one sequence of K consecutive days
    with strictly increasing productivity.
    """
    winners = []

    for i in range(num_employees):
        for j in range(num_days - K + 1):
            is_increasing = True
            for k in range(K - 1):
                if productivity_data[i][j + k] >= productivity_data[i][j + k + 1]:
                    is_increasing = False
                    break
            if is_increasing:
                winners.append(i)
                break

    return winners

def process_bookings(n, m, k, tables, requests):
    accepted = 0
    rejected = 0

    for req in requests:
        tables.sort()  # ensures we are filling the least filled tables first
        accommodated = False

        for i in range(n):
            if tables[i] + req <= m:
                tables[i] += req
                accepted += 1
                accommodated = True
                break

        if not accommodated:
            rejected += 1

    return accepted, rejected

