def caesar_cipher(text, shift):
    """
    Encrypts the given text using Caesar Cipher with the specified shift.

    :param text: The input string to be encrypted.
    :param shift: The number of positions to shift each letter.
    :return: The encrypted string.
    """
    result = []

    for char in text:
        if char.isalpha():
            shift_base = ord('A') if char.isupper() else ord('a')
            shifted_char = chr(shift_base + (ord(char) - shift_base + shift) % 26)
            result.append(shifted_char)
        else:
            result.append(char)

    return ''.join(result)

