from collections import deque, defaultdict
from typing import List, Tuple, Dict

def minimumFollows(N: int, pairs: List[Tuple[int, int]]) -> Dict[int, int]:
    # Create a graph as an adjacency list
    graph = defaultdict(list)
    for u, v in pairs:
        graph[v].append(u)

    # Create a dictionary to store the minimum follows required to reach each user
    min_follows = {}

    # Breadth-First Search (BFS) from user 1
    queue = deque([(1, 0)])  # (current user, current distance)
    visited = set([1])

    while queue:
        current, dist = queue.popleft()

        for neighbor in graph[current]:
            if neighbor not in visited:
                visited.add(neighbor)
                min_follows[neighbor] = dist + 1
                queue.append((neighbor, dist + 1))

    return min_follows

