def find_large_files(n, directories, size_threshold):
    files_above_threshold = []

    for directory in directories:
        path, files = directory
        for filename, size in files:
            if size > size_threshold:
                files_above_threshold.append((filename, size))

    # Sort files by size (descending) and by filename lexicographically
    files_above_threshold.sort(key=lambda x: (-x[1], x[0]))

    return [filename for filename, size in files_above_threshold]

