def exists_in_grid(n, m, grid, k):
    """
    Determines if the integer k exists in the n x m grid.
    The grid's rows and columns are sorted in non-decreasing order.
    """
    row = 0
    col = m - 1

    while row < n and col >= 0:
        if grid[row][col] == k:
            return "YES"
        elif grid[row][col] < k:
            row += 1
        else:
            col -= 1

    return "NO"

