def max_unique_dishes(N, M, dishes):
    dishes_by_ingredient = {}

    for ingredient, cost in dishes:
        if ingredient not in dishes_by_ingredient:
            dishes_by_ingredient[ingredient] = []
        dishes_by_ingredient[ingredient].append(cost)

    for ingredient in dishes_by_ingredient:
        dishes_by_ingredient[ingredient].sort()

    selected_dishes = []
    for costs in dishes_by_ingredient.values():
        selected_dishes.append(costs[0])

    selected_dishes.sort()

    total_cost = 0
    count = 0
    for cost in selected_dishes:
        if total_cost + cost <= M:
            total_cost += cost
            count += 1
        else:
            break

    return count

