from datetime import datetime, timedelta

def parse_time(time_str):
    return datetime.strptime(time_str, "%H:%M")

def calculate_fee(start, end):
    time_diff = end - start
    total_hours = time_diff.total_seconds() / 3600
    fee = (total_hours // 1 + (1 if total_hours % 1 > 0 else 0)) * 10
    return int(fee)

def manage_parking_lot(N, M, events):
    parking_lot = {}
    parked_cars = {}
    fees = []

    for event in events:
        event_details = event.split()
        event_type = event_details[0]
        car_id = event_details[1]
        event_time = parse_time(event_details[2])

        if event_type == "entry":
            if len(parking_lot) < N:
                parking_lot[car_id] = event_time
        elif event_type == "exit":
            if car_id in parking_lot:
                start_time = parking_lot.pop(car_id)
                fee = calculate_fee(start_time, event_time)
                fees.append(f"{car_id} {fee}")

    return fees

