def can_make_array_uniform(t: int, cases: List[List[int]]) -> List[str]:
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    def gcd_of_array(arr):
        return reduce(gcd, arr)

    results = []
    for i in range(t):
        n = cases[i][0]
        arr = cases[i][1]

        if len(set(arr)) == 1:   # All elements already equal
            results.append("YES")
            continue

        if gcd_of_array(arr) == 1:
            results.append("YES")
        else:
            results.append("NO")

    return results

