def sieve_of_eratosthenes(n):
    """
    Returns a list of all prime numbers less than n using the Sieve of Eratosthenes algorithm.
    """
    if n <= 2:
        return []

    # Initialize a list of boolean values, where prime[i] = True means i is potentially a prime
    prime = [True] * n
    prime[0] = prime[1] = False  # We know 0 and 1 are not primes

    for start in range(2, int(n**0.5) + 1):
        if prime[start]:
            # Set multiples of the starting number as not primes
            for multiple in range(start*start, n, start):
                prime[multiple] = False

    # Return all numbers that are still marked as primes
    return [num for num, is_prime in enumerate(prime) if is_prime]

def longest_palindromic_subsequence(s):
    """
    Determines the length of the longest palindromic subsequence in a given string s.

    :param s: input string
    :return: length of the longest palindromic subsequence
    """
    n = len(s)
    # create a table to store the results of subproblems
    dp = [[0] * n for _ in range(n)]

    # strings of length 1 are palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # cl is the length of the current substring
    for cl in range(2, n + 1):
        for i in range(n - cl + 1):
            j = i + cl - 1
            if s[i] == s[j] and cl == 2:
                dp[i][j] = 2
            elif s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return dp[0][n - 1]

def is_sorted_lexicographically(custom_alphabet, words):
    """
    Checks if the list of words is sorted in lexicographic order according to the custom alphabet.

    Parameters:
    custom_alphabet (str): A string of 26 characters representing the custom alphabet.
    words (list of str): A list of words to be checked.

    Returns:
    str: "YES" if the words are sorted, otherwise "NO".
    """
    # Create a map for character positions according to the custom alphabet
    char_position = {char: idx for idx, char in enumerate(custom_alphabet)}

    def compare(word1, word2):
        # Compare each character of both words according to character positions in the custom alphabet
        for c1, c2 in zip(word1, word2):
            if char_position[c1] < char_position[c2]:
                return -1
            elif char_position[c1] > char_position[c2]:
                return 1
        # If all characters are identical, the shorter word should come first
        return len(word1) - len(word2)

    # Compare each pair of consecutive words
    for i in range(len(words) - 1):
        if compare(words[i], words[i + 1]) > 0:
            return "NO"

    return "YES"

