def can_sort_with_swaps(n, k, arr):
    """
    Determines if the array `arr` can be sorted in non-decreasing order
    using the allowed adjacent swap operations.
    """
    sorted_arr = sorted(arr)

    # A function to perform BFS to check if we can reach all correct positions
    def can_reach_sorted_position(start, sorted_value):
        queue = [start]
        visited = set()
        while queue:
            index = queue.pop(0)
            if arr[index] == sorted_value:
                return True
            visited.add(index)
            # Check neighbors if within bounds and not visited
            if index > 0 and abs(arr[index] - arr[index - 1]) <= k and (index - 1) not in visited:
                queue.append(index - 1)
            if index < n - 1 and abs(arr[index] - arr[index + 1]) <= k and (index + 1) not in visited:
                queue.append(index + 1)
        return False

    for i in range(n):
        if not can_reach_sorted_position(i, sorted_arr[i]):
            return "NO"
    return "YES"

