def decrypt_message(k: int, message: str) -> str:
    """
    Decrypts a message by shifting each alphabetic character k positions back in the alphabet.

    Parameters:
    k (int): The number of positions each letter in the message has been shifted.
    message (str): The encrypted message.

    Returns:
    str: The decrypted message.
    """
    decrypted_message = []

    for char in message:
        if 'a' <= char <= 'z':
            decrypted_message.append(chr((ord(char) - ord('a') - k) % 26 + ord('a')))
        elif 'A' <= char <= 'Z':
            decrypted_message.append(chr((ord(char) - ord('A') - k) % 26 + ord('A')))
        else:
            decrypted_message.append(char)

    return ''.join(decrypted_message)

