def min_moves_to_clean_grid(N, M, grid):
    # Finding the initial position of the robotic cleaner
    start = None
    total_empty_cells = 0

    for i in range(N):
        for j in range(M):
            if grid[i][j] == 'R':
                start = (i, j)
            if grid[i][j] == '.':
                total_empty_cells += 1

    if not start:
        return -1

    # Directions for moving up, down, left, right
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # BFS initialization
    queue = deque([(start[0], start[1], 0)])  # (row, column, distance)
    visited = set()
    visited.add(start)
    cleaned_cells = 0

    while queue:
        r, c, dist = queue.popleft()

        for dr, dc in directions:
            nr, nc = r + dr, c + dc

            if 0 <= nr < N and 0 <= nc < M and (nr, nc) not in visited and grid[nr][nc] != '#':
                visited.add((nr, nc))
                queue.append((nr, nc, dist + 1))
                if grid[nr][nc] == '.':
                    cleaned_cells += 1

        if cleaned_cells == total_empty_cells:
            return dist + 1

    return -1  # If not all cells could be cleaned

# Parsing input
def parse_input():
    N, M = map(int, input().split())
    grid = [input().strip() for _ in range(N)]
    return N, M, grid

def execute_commands(commands):
    from datetime import datetime, timedelta

    removed_commands = []
    current_breaks = []

    for i, command in enumerate(commands):
        parts = command.split()

        time = datetime.strptime(parts[0], '%H:%M')
        operation = parts[1]

        if operation == "BREAK":
            duration = int(parts[2])
            end_break_time = time + timedelta(minutes=duration)
            current_breaks.append((time, end_break_time))
        elif operation == "MOVE":
            for break_start, break_end in current_breaks:
                if break_start <= time < break_end:
                    removed_commands.append(i+1)
                    break

    if removed_commands:
        return "OPERATION(S) REMOVED\n" + "\n".join(map(str, removed_commands))
    else:
        return "ALL OPERATIONS SUCCESSFUL"

