def min_steps_to_one(n, memo=None):
    if memo is None:
        memo = {}

    if n in memo:
        return memo[n]

    if n == 1:
        return 0

    steps = float('inf')

    if n % 3 == 0:
        steps = min(steps, 1 + min_steps_to_one(n // 3, memo))
    if n % 2 == 0:
        steps = min(steps, 1 + min_steps_to_one(n // 2, memo))

    steps = min(steps, 1 + min_steps_to_one(n - 1, memo))

    memo[n] = steps
    return steps

