def count_divisible_pairs(n, array, k):
    """
    Returns the number of pairs (i, j) such that 0 ≤ i < j < n
    and the product of array[i] and array[j] is divisible by k.
    """
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            if (array[i] * array[j]) % k == 0:
                count += 1
    return count

