from itertools import permutations

def is_balanced(plates, L, U):
    """
    Check if a given permutation of plates is balanced.
    """
    for i in range(len(plates) - 1):
        ratio = plates[i+1] / plates[i]
        if not (L <= ratio <= U):
            return False
    return True

def balance_stack(n, m, weights, L, U):
    """
    Determine if it is possible to reorder the plates such that the stack is balanced
    and return the balanced order or "Not Possible".
    """
    # Check all permutations of the plates
    for perm in permutations(weights):
        if is_balanced(perm, L, U):
            return perm
    return "Not Possible"

