def two_sum(array, target):
    """
    Returns the indices of the two numbers in the array that add up to the target.
    If no solution exists, returns "No Solution".
    """
    seen = {}
    for i, num in enumerate(array):
        difference = target - num
        if difference in seen:
            return seen[difference], i
        seen[num] = i
    return "No Solution"

def solve_test_cases(test_cases):
    """
    Solves the test cases based on provided inputs.
    """
    results = []
    for array, target in test_cases:
        result = two_sum(array, target)
        if result == "No Solution":
            results.append(result)
        else:
            results.append(f"{result[0]} {result[1]}")
    return results

