def max_building_height(blocks):
    if not blocks:
        return 0
    blocks.sort()
    n = len(blocks)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if abs(blocks[i] - blocks[j]) == 1:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

