def final_position(commands):
    """
    Returns the final position of the robot after executing the given sequence of commands.

    Parameters:
    commands (list of str): List of commands. Each command is either "Up", "Down", "Left", or "Right".

    Returns:
    list of int: Final position of the robot as [x, y].
    """
    x, y = 0, 0
    for command in commands:
        if command == "Up":
            y += 1
        elif command == "Down":
            y -= 1
        elif command == "Left":
            x -= 1
        elif command == "Right":
            x += 1
    return [x, y]

