def longest_subarray_with_sum_k(nums, k):
    """
    Returns the length of the longest contiguous subarray whose sum is exactly k.

    :param nums: List of integers
    :param k: Integer target sum
    :return: Length of the longest subarray with sum k
    """
    sum_map = {}
    current_sum = 0
    max_length = 0

    for i in range(len(nums)):
        current_sum += nums[i]

        if current_sum == k:
            max_length = i + 1

        if (current_sum - k) in sum_map:
            max_length = max(max_length, i - sum_map[current_sum - k])

        if current_sum not in sum_map:
            sum_map[current_sum] = i

    return max_length

