def find_dominant_element(n, A):
    """
    Determines the dominant element in the array A.

    Parameters:
    n (int): The size of the array.
    A (list): The array of integers.

    Returns:
    int: The dominant element or -1 if there is no dominant element.
    """
    count = {}
    for num in A:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    for num, freq in count.items():
        if freq > n // 2:
            return num

    return -1

