def max_difficulty_sum(n, D, difficulties):
    """
    Returns the maximum sum of difficulties that does not exceed D.
    This can be solved using a variation of the Knapsack problem (0/1 Knapsack).
    """
    dp = [0] * (D + 1)  # Initialize a DP array of size D+1 with zeros

    for difficulty in difficulties:
        for j in range(D, difficulty - 1, -1):
            dp[j] = max(dp[j], dp[j - difficulty] + difficulty)

    return dp[D]

