def longestNonDecreasingSubseq(resources):
    if not resources:
        return 0

    # DP array to store the length of the longest subsequence ending at each position
    dp = [1] * len(resources)

    for i in range(1, len(resources)):
        for j in range(i):
            if resources[i] >= resources[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

