def encode_rle(s: str) -> str:
    """
    Encodes the given string using Run-Length Encoding (RLE).
    """
    if not s:
        return ""

    encoded_str = []
    count = 1

    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            encoded_str.append(f"{count}{s[i-1]}")
            count = 1

    encoded_str.append(f"{count}{s[-1]}")
    return ''.join(encoded_str)

def decode_rle(s: str) -> str:
    """
    Decodes the given Run-Length Encoded (RLE) string.
    """
    decoded_str = []
    num = ""

    for char in s:
        if char.isdigit():
            num += char
        else:
            decoded_str.append(char * int(num))
            num = ""

    return ''.join(decoded_str)

def maximize_lexicographical_string(T, test_cases):
    results = []

    for S, K in test_cases:
        if K == 1:
            results.append(''.join(sorted(S, reverse=True)))
        else:
            results.append(''.join(sorted(S, reverse=True)))
    return results

