def deepSum(nested_list):
    """
    Returns the sum of all integers within the nested list.
    """
    total = 0

    def helper(sublist):
        nonlocal total
        for element in sublist:
            if isinstance(element, list):
                helper(element)
            else:
                total += element

    helper(nested_list)
    return total

