def length_of_LIS(nums):
    if not nums:
        return 0

    # This array will store the smallest possible tail value for all increasing subsequences of different lengths.
    tails = []

    for num in nums:
        # Binary search to find the position of the current element in tails
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid
        # If left is equal to the length of tails, it means num is larger than all elements in tails
        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num

    return len(tails)

