from collections import deque, defaultdict

def shortest_cycle(n, m, edges):
    if m == 0:
        return -1

    def bfs(start):
        dist = [float("inf")] * (n + 1)
        parent = [-1] * (n + 1)
        q = deque([start])
        dist[start] = 0

        while q:
            node = q.popleft()

            for neighbor in graph[node]:
                if dist[neighbor] == float("inf"):
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    q.append(neighbor)
                elif parent[node] != neighbor:
                    # Found a cycle
                    return dist[node] + dist[neighbor] + 1

        return float("inf")

    # Build the graph
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    shortest = float("inf")
    for i in range(1, n + 1):
        shortest = min(shortest, bfs(i))

    return -1 if shortest == float("inf") else shortest

def max_subarray_with_even(A):
    """
    Returns the maximum possible sum of a subarray that contains at least one even number.
    """
    def kadane_with_even(arr, n):
        max_so_far = -float('inf')
        max_ending_here = -float('inf')
        has_even = False
        for i in range(n):
            if arr[i] % 2 == 0:
                has_even = True
            if max_ending_here < 0:
                max_ending_here = arr[i]
            else:
                max_ending_here += arr[i]

            if has_even:
                max_so_far = max(max_so_far, max_ending_here)

        if not has_even:
            return -float('inf')
        return max_so_far

    return kadane_with_even(A, len(A))

def solve(T, test_cases):
    results = []
    for i in range(T):
        N, A = test_cases[i]
        results.append(max_subarray_with_even(A))
    return results

