def find_best_car_to_rent(T, test_cases):
    results = []

    for i in range(T):
        B, N, cars = test_cases[i]
        max_days = 0
        chosen_car = -1

        for cost in cars:
            if cost <= B:
                days = B // cost
                if days > max_days or (days == max_days and cost < chosen_car):
                    max_days = days
                    chosen_car = cost

        if chosen_car == -1:
            results.append("Not Affordable")
        else:
            results.append(chosen_car)

    return results

