def find_rich_numbers(up_to):
    """
    Finds all rich numbers less than or equal to up_to.

    A rich number is an integer greater than 1 that can be written as the sum
    of positive integers in at least two distinct ways, where the order of terms does not matter.

    Parameters:
    up_to (int): The upper limit to search for rich numbers.

    Returns:
    list: A list of all rich numbers up to the specified limit.
    """
    def is_rich_number(n):
        count = 0
        for i in range(1, (n // 2) + 1):
            remainder = n - i
            if remainder > i:
                count += 1
            else:
                break
            if count >= 2:
                return True
        return False

    rich_numbers = []
    for number in range(2, up_to + 1):
        if is_rich_number(number):
            rich_numbers.append(number)

    return rich_numbers

