def can_perform_spell(n, potion_types, quantities, recipe):
    potion_dict = {potion: quantities[i] for i, potion in enumerate(potion_types)}
    used_potions = {potion: 0 for potion in potion_types}

    for char in recipe:
        if char in potion_dict and potion_dict[char] > 0:
            potion_dict[char] -= 1
            used_potions[char] += 1
        else:
            return "Impossible"

    return ' '.join(str(used_potions[char]) for char in potion_types)

