def count_unended_processes(n, events):
    started_processes = set()
    ended_processes = set()

    for event in events:
        if event.startswith("START"):
            process_id = event[5:]
            started_processes.add(process_id)
        elif event.startswith("END"):
            process_id = event[3:]
            if process_id in started_processes:
                ended_processes.add(process_id)

    return len(started_processes - ended_processes)

