from functools import reduce

def max_sum_of_subsequence_with_gcd(nums, k):
    def gcd_of_list(lst):
        return reduce(gcd, lst)

    # Filtering out elements divisible by k
    filtered_nums = [num for num in nums if num % k == 0]

    # If no elements are divisible by k, return 0
    if not filtered_nums:
        return 0

    return sum(filtered_nums)

def compress_string(s):
    """
    Compresses the given string using a Run-Length Encoding-like format.

    Args:
    s (str): The input string containing only uppercase and lowercase English letters.

    Returns:
    str: The compressed version of the string.
    """
    if not s:
        return ""

    compressed = []
    i = 0
    while i < len(s):
        count = 1
        while i + 1 < len(s) and s[i] == s[i+1]:
            count += 1
            i += 1
        if count > 1:
            compressed.append(f"{s[i]}{count}")
        else:
            compressed.append(s[i])
        i += 1

    return "".join(compressed)

