def can_fulfill_requests(m, initial_copies, transactions):
    available_copies = initial_copies[:]

    for transaction in transactions:
        book_id, action = transaction

        if action == 1:  # Borrowing a copy
            if available_copies[book_id - 1] > 0:
                available_copies[book_id - 1] -= 1
            else:
                return "NO"
        elif action == -1:  # Returning a copy
            available_copies[book_id - 1] += 1

    return "YES"

