def classify_ip(ip_address):
    """
    Classify the given IP address as either 'Private' or 'Public'.
    """
    parts = list(map(int, ip_address.split('.')))

    if parts[0] == 10:
        return "Private"
    elif parts[0] == 172 and 16 <= parts[1] <= 31:
        return "Private"
    elif parts[0] == 192 and parts[1] == 168:
        return "Private"
    else:
        return "Public"

