def can_transform(N, A, B):
    # Remove all '*' from A and compare the rest of characters.
    A_filtered = [char for char in A if char != '*']

    if len(A_filtered) > len(B):
        return "NO"

    # Create a frequency dictionary for A_filtered and B
    freq_A = {}
    freq_B = {}

    for char in A_filtered:
        if char in freq_A:
            freq_A[char] += 1
        else:
            freq_A[char] = 1

    for char in B:
        if char in freq_B:
            freq_B[char] += 1
        else:
            freq_B[char] = 1

    # Compare the frequency dictionaries
    for char, count in freq_A.items():
        if char not in freq_B or freq_B[char] < count:
            return "NO"

    return "YES"

