def is_fibonacci(n):
    """
    Check if a given number n is a Fibonacci number.
    A number is a Fibonacci number if and only if one (or both) of (5*n^2 + 4) or (5*n^2 - 4) is a perfect square.
    """
    if n == 0 or n == 1:
        return True
    def is_perfect_square(x):
        s = int(x**0.5)
        return s*s == x

    return is_perfect_square(5*n*n + 4) or is_perfect_square(5*n*n - 4)

def determine_level(score):
    if is_fibonacci(score):
        return "Elite"
    if score < 40:
        return "Beginner"
    elif score <= 70:
        return "Intermediate"
    else:
        return "Advanced"

def coding_competition_levels(t, scores):
    results = []
    for score in scores:
        results.append(determine_level(score))
    return results

