def is_balanced(s):
    """
    Checks if the input string s has balanced brackets.

    :param s: str, the input string containing various types of brackets.
    :return: bool, True if the brackets are balanced, otherwise False.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False
    return stack == []

