from typing import List

def levenshtein_distance(s1: str, s2: str) -> int:
    """
    Compute the Levenshtein distance between two strings s1 and s2.
    """
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    if len(s2) == 0:
        return len(s1)

    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1):
        current_row = [i + 1]
        for j, c2 in enumerate(s2):
            insertions = previous_row[j + 1] + 1
            deletions = current_row[j] + 1
            substitutions = previous_row[j] + (c1 != c2)
            current_row.append(min(insertions, deletions, substitutions))
        previous_row = current_row

    return previous_row[-1]

def find_closest_matches(dictionary: List[str], words_to_check: List[str]) -> List[str]:
    closest_matches = []

    for word in words_to_check:
        if word in dictionary:
            closest_matches.append(word)
            continue

        closest_word = None
        closest_distance = float('inf')

        for dict_word in dictionary:
            distance = levenshtein_distance(word, dict_word)
            if distance < closest_distance:
                closest_distance = distance
                closest_word = dict_word

        closest_matches.append(closest_word)

    return closest_matches

def count_islands(m, n, grid):
    def dfs(x, y):
        if x < 0 or x >= m or y < 0 or y >= n or grid[x][y] == '0':
            return
        grid[x][y] = '0'  # Mark the cell as visited
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            dfs(x + dx, y + dy)

    islands = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == '1':
                islands += 1
                dfs(i, j)
    return islands

def solve_islands_problem(m, n, input_grid_str):
    grid = [list(row) for row in input_grid_str.split()]
    return count_islands(m, n, grid)

