def reachable_nodes(n, m, edges, starting_node):
    from collections import defaultdict, deque

    def bfs(start_node):
        visited = set()
        queue = deque([start_node])
        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                queue.extend(graph[node] - visited)
        return visited

    graph = defaultdict(set)
    for u, v in edges:
        graph[u].add(v)
        graph[v].add(u)

    visited_nodes = bfs(starting_node)
    if len(visited_nodes) == n:
        return "reachable"
    else:
        return "unreachable"

