def can_be_sorted_by_one_swap(heights):
    """
    Returns True if the list heights can be sorted in strictly increasing order
    by performing at most one swap, otherwise returns False.
    """
    def is_sorted(lst):
        return all(lst[i] < lst[i+1] for i in range(len(lst)-1))

    n = len(heights)
    if n <= 1:
        return True

    # Find the first pair of elements that are out of order
    first = second = -1
    for i in range(n - 1):
        if heights[i] > heights[i + 1]:
            if first == -1:
                first = i
            elif second == -1:
                second = i + 1

    if first == -1:
        # Already sorted
        return True
    if second == -1:
        # Only one pair out of order
        second = first + 1

    # Swap the two out of order elements and check if the list becomes sorted
    heights[first], heights[second] = heights[second], heights[first]
    result = is_sorted(heights)

    # Swap back to restore original list
    heights[first], heights[second] = heights[second], heights[first]

    return result

