def return_to_start(instructions: str) -> bool:
    """
    Determines whether the robot returns to the starting position after executing
    a sequence of instructions.

    Args:
    instructions (str): A string consisting of the characters 'L', 'R', 'U', 'D'

    Returns:
    bool: True if the robot returns to the starting position, False otherwise.
    """
    x, y = 0, 0

    for instr in instructions:
        if instr == 'L':
            x -= 1
        elif instr == 'R':
            x += 1
        elif instr == 'U':
            y += 1
        elif instr == 'D':
            y -= 1

    return x == 0 and y == 0

