def calculate_total_salary(company_structure):
    """
    Recursively calculates the total salary of all employees in the company structure.

    :param company_structure: dict, The nested dictionary representing the company structure
    :return: int, Total salary of all employees
    """

    def helper(department):
        total = 0
        for key, value in department.items():
            if key == 'employees':
                for employee in value:
                    total += employee['salary']
            elif isinstance(value, dict):
                total += helper(value)
        return total

    return helper(company_structure)

