from typing import List

def maxCoins(grid: List[List[int]]) -> int:
    """
    Returns the maximum number of coins that can be collected when moving
    from the top-left corner to the bottom-right corner of the grid.
    If it is impossible to reach the bottom-right corner, returns 0.
    """
    if not grid or not grid[0] or grid[0][0] == -1 or grid[-1][-1] == -1:
        return 0

    m, n = len(grid), len(grid[0])

    # Initialize dp array with -1 since -1 represents obstacles
    dp = [[-1] * n for _ in range(m)]

    # Starting point
    dp[0][0] = grid[0][0]

    # Fill the first row
    for j in range(1, n):
        if grid[0][j] == -1:
            break
        dp[0][j] = dp[0][j-1] + grid[0][j]

    # Fill the first column
    for i in range(1, m):
        if grid[i][0] == -1:
            break
        dp[i][0] = dp[i-1][0] + grid[i][0]

    # Fill the rest of the dp array
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] != -1:
                if dp[i-1][j] != -1 and dp[i][j-1] != -1:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + grid[i][j]
                elif dp[i-1][j] != -1:
                    dp[i][j] = dp[i-1][j] + grid[i][j]
                elif dp[i][j-1] != -1:
                    dp[i][j] = dp[i][j-1] + grid[i][j]

    return dp[m-1][n-1] if dp[m-1][n-1] != -1 else 0

