def floyd_warshall(n, edges):
    """
    Floyd-Warshall algorithm to determine the shortest distance between all pairs of nodes.
    """
    # Initialize distance array
    dist = [[float('inf')] * (n + 1) for _ in range(n + 1)]

    # Distance from any node to itself is 0
    for i in range(1, n + 1):
        dist[i][i] = 0

    # Fill initial distances with given edges
    for u, v, w in edges:
        dist[u][v] = w
        dist[v][u] = w

    # Floyd-Warshall algorithm
    for k in range(1, n + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if dist[i][j] > dist[i][k] + dist[k][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    return dist

def shortest_distances(n, edges, queries):
    dist = floyd_warshall(n, edges)
    results = []
    for a, b in queries:
        if dist[a][b] != float('inf'):
            results.append(dist[a][b])
        else:
            results.append(-1)
    return results

