def longest_common_prefix(strs):
    """
    Returns the longest common prefix of an array of strings.
    """
    if not strs:
        return 0

    # The shortest string will limit the comparison of the common prefix.
    min_length = min(len(s) for s in strs)

    for i in range(min_length):
        char = strs[0][i]
        for s in strs[1:]:
            if s[i] != char:
                return i

    return min_length

def find_longest_common_prefix_length(test_cases):
    results = []
    for dishes in test_cases:
        prefix_length = longest_common_prefix(dishes)
        results.append(prefix_length)
    return results

def process_input(input_str):
    input_lines = input_str.strip().split('\n')
    T = int(input_lines[0])
    index = 1
    test_cases = []

    for _ in range(T):
        N = int(input_lines[index])
        dishes = []
        for j in range(N):
            dishes.append(input_lines[index + 1 + j])
        test_cases.append(dishes)
        index += N + 1

    return find_longest_common_prefix_length(test_cases)

def count_connected_components(n, m, edges):
    from collections import defaultdict, deque

    # Creating adjacency list
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()

    def bfs(node):
        queue = deque([node])
        while queue:
            current = queue.popleft()
            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    connected_components = 0

    for node in range(1, n + 1):
        if node not in visited:
            visited.add(node)
            bfs(node)
            connected_components += 1

    return connected_components

