def minimum_energy(n, deliveries):
    """
    Compute the minimum energy required for the robot to complete all deliveries and return to the starting point.

    :param n: Integer, the number of locations
    :param deliveries: List of integers (0s and 1s) representing locations requiring deliveries
    :return: Integer, the minimum energy required
    """
    first = -1
    last = -1

    # Find the first and last delivery points
    for i in range(n):
        if deliveries[i] == 1:
            if first == -1:
                first = i
            last = i

    # No deliveries needed
    if first == -1:
        return 0

    # Minimum energy is 2 * the distance from first to last delivery points
    return 2 * (last - first)

