def removeInvalidParentheses(s):
    def is_valid(string):
        cnt = 0
        for char in string:
            if char == '(':
                cnt += 1
            elif char == ')':
                cnt -= 1
            if cnt < 0:
                return False
        return cnt == 0

    def backtrack(s, start, l, r):
        if l == 0 and r == 0:
            if is_valid(s):
                result.add("".join(s))
            return

        for i in range(start, len(s)):
            if i != start and s[i] == s[i - 1]:
                continue
            if s[i] in ('(', ')'):
                curr = "".join(s[:i] + s[i + 1:])
                if r > 0 and s[i] == ')':
                    backtrack(curr, i, l, r - 1)
                elif l > 0 and s[i] == '(':
                    backtrack(curr, i, l - 1, r)

    l = r = 0
    for char in s:
        if char == '(':
            l += 1
        elif char == ')':
            if l:
                l -= 1
            else:
                r += 1

    result = set()
    backtrack(list(s), 0, l, r)
    return sorted(result)

