def max_unique_path_length(grid):
    M = len(grid)
    N = len(grid[0]) if M > 0 else 0

    def dfs(x, y, visited):
        max_length = 1
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < M and 0 <= ny < N and grid[nx][ny] not in visited:
                max_length = max(max_length, 1 + dfs(nx, ny, visited | {grid[nx][ny]}))
        return max_length

    max_path = 0
    for i in range(M):
        for j in range(N):
            max_path = max(max_path, dfs(i, j, {grid[i][j]}))

    return max_path

