def largest_connected_component(n, m, k, marks):
    def dfs(r, c):
        stack = [(r, c)]
        count = 0
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            count += 1
            for direction in directions:
                nx, ny = x + direction[0], y + direction[1]
                if 1 <= nx <= n and 1 <= ny <= m and (nx, ny) in mark_set:
                    stack.append((nx, ny))
        return count

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    mark_set = set(marks)
    visited = set()
    largest = 0

    for r, c in marks:
        if (r, c) not in visited:
            largest = max(largest, dfs(r, c))

    return largest

