def contains_permutation(S1, S2):
    from collections import Counter

    if len(S1) > len(S2):
        return False

    s1_counter = Counter(S1)
    window_counter = Counter(S2[:len(S1)])

    for i in range(len(S1), len(S2)):
        if s1_counter == window_counter:
            return True
        window_counter[S2[i]] += 1
        window_counter[S2[i - len(S1)]] -= 1
        if window_counter[S2[i - len(S1)]] == 0:
            del window_counter[S2[i - len(S1)]]

    return s1_counter == window_counter

def check_permutations_cases(test_cases):
    results = []
    for S1, S2 in test_cases:
        results.append(contains_permutation(S1, S2))
    return results

