def hollow_square(N):
    """
    Create an N x N square made of asterisks (‘*’) with a hollow center.
    """
    if N == 1:
        return "*"

    result = []
    for i in range(N):
        if i == 0 or i == N - 1:
            result.append('*' * N)
        else:
            result.append('*' + ' ' * (N - 2) + '*')

    return '\n'.join(result)

