def calculate_total_price(price_per_item, quantity):
    """
    Calculates the total price after applying the appropriate discount based on quantity purchased.

    Args:
    price_per_item (float): The price of a single item.
    quantity (int): The quantity of items purchased.

    Returns:
    float: The total price after discount, rounded to two decimal places.
    """

    if quantity >= 100:
        discount = 0.20
    elif quantity >= 50:
        discount = 0.10
    elif quantity >= 20:
        discount = 0.05
    else:
        discount = 0.00

    total_price = price_per_item * quantity * (1 - discount)
    return round(total_price, 2)

