        cols_set = set()
        valid = True

        for r, c in constraints:
            if r in rows_set or c in cols_set:
                valid = False
                break
            rows_set.add(r)
            cols_set.add(c)

        if valid:
            results.append("YES")
        else:
            results.append("NO")

    return results

