def find_path(n, m, grid):
    def is_valid(x, y):
        return 0 <= x < n and 0 <= y < m and grid[x][y] == 0

    def backtrack(x, y):
        if (x, y) == (n-1, m-1):
            path.append((x + 1, y + 1))
            return True
        grid[x][y] = 1
        path.append((x + 1, y + 1))

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny) and backtrack(nx, ny):
                return True

        path.pop()
        return False

    if grid[0][0] == 1 or grid[n-1][m-1] == 1:
        return -1

    directions = [(1, 0), (0, 1), (-1, 0), (0, -1)]
    path = []

    if backtrack(0, 0):
        return path
    else:
        return -1

def can_form_consecutive_sequence(test_cases):
    results = []

    for case in test_cases:
        N, sequence = case
        if N == 1:
            results.append("YES")
            continue

        sequence = sorted(sequence)
        consecutive = True
        for i in range(1, N):
            if sequence[i] != sequence[i-1] + 1:
                consecutive = False
                break

        if consecutive:
            results.append("YES")
        else:
            results.append("NO")

    return results

