def longest_alternating_zigzag_sequence(arr):
    if not arr:
        return 0

    n = len(arr)

    # for storing the lengths of longest AZS ending at each index
    increase = [1] * n
    decrease = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] > arr[j]:
                increase[i] = max(increase[i], decrease[j] + 1)
            elif arr[i] < arr[j]:
                decrease[i] = max(decrease[i], increase[j] + 1)

    return max(max(increase), max(decrease))

def solve(t, test_cases):
    results = []
    for case in test_cases:
        M, arr = case
        results.append(longest_alternating_zigzag_sequence(arr))
    return results

