def max_packages_delivered(n, k, packages):
    # Function to calculate Manhattan distance
    def manhattan(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    # Sort packages by pickup time (is already sorted as per problem statement)
    packages.sort()

    dp = [0] * (k + 1)  # dp[i] represents the maximum packages delivered by picking up i-th package

    for i in range(1, k + 1):
        pi, px, py, di, dx, dy = packages[i - 1]
        j = i - 1
        while j > 0:
            pj, qx, qy, qd, rx, ry = packages[j - 1]
            if pi >= pj + manhattan(rx, ry, px, py):
                dp[i] = max(dp[i], dp[j] + 1)
                break
            j -= 1
        dp[i] = max(dp[i], dp[i - 1], 1)

    return max(dp)

def longest_vowel_substring(s):
    """
    Returns the length of the longest substring that contains only vowels.
    """
    vowels = set("aeiouAEIOU")
    max_length = 0
    current_length = 0

    for char in s:
        if char in vowels:
            current_length += 1
            if current_length > max_length:
                max_length = current_length
        else:
            current_length = 0

    return max_length

