def find_target_in_grid(n, grid, target):
    """
    Finds the position of the target in the n x n grid.

    Parameters:
    n (int): size of the grid
    grid (List[List[int]]): n x n grid of integers
    target (int): the integer to find in the grid

    Returns:
    Tuple[int, int] or int: position (1-based) of the target in the grid, or -1 if not found
    """
    row, col = 0, n - 1

    while row < n and col >= 0:
        if grid[row][col] == target:
            return (row + 1, col + 1)
        elif grid[row][col] > target:
            col -= 1
        else:
            row += 1

    return -1

