def max_candies(N, candies):
    """
    Returns the maximum number of candies that can be collected
    given the constraint of collecting from at most one pair of consecutive houses.
    """
    if N == 1:
        return candies[0]

    max_candies_collected = 0
    for i in range(N):
        for j in range(i, N):
            max_candies_collected = max(max_candies_collected, sum(candies[i:j+1]))

    return max_candies_collected

