from collections import deque

def is_binary_sum_tree(tree):
    if not tree or tree[0] == 'N':
        return True

    idx = 0
    q = deque([tree[idx]])
    idx += 1

    while q:
        node = q.popleft()
        if node == 'N':
            continue

        left_val = tree[idx] if idx < len(tree) else 'N'
        if left_val != 'N':
            q.append(left_val)
        idx += 1

        right_val = tree[idx] if idx < len(tree) else 'N'
        if right_val != 'N':
            q.append(right_val)
        idx += 1

        if node != 'N' and left_val != 'N' and right_val != 'N':
            if node != str(int(left_val) + int(right_val)):
                return False

    return True

def process_test_cases(test_cases):
    results = []
    for i, case in enumerate(test_cases):
        result = is_binary_sum_tree(case.split())
        results.append(f"Case #{i+1}: {'Yes' if result else 'No'}")
    return results

