def max_beauty(n, k, m, beauty_values, magic_values):
    def calculate_beauty_and_magic(start):
        beauty_sum = sum(beauty_values[start:start + k])
        magic_product = 1
        for i in range(start, start + k):
            magic_product *= magic_values[i]
        return beauty_sum, magic_product

    max_beauty = -1
    for i in range(n - k + 1):
        beauty_sum, magic_product = calculate_beauty_and_magic(i)
        if magic_product <= m:
            max_beauty = max(max_beauty, beauty_sum)

    if max_beauty == -1:
        return "impossible"
    else:
        return max_beauty

