from collections import deque, defaultdict

def min_semesters(n, prerequisites):
    # Using Kahn's Algorithm to find minimum semesters (Topological Sort)
    in_degree = [0] * (n + 1)
    graph = defaultdict(list)

    for u, v in prerequisites:
        graph[u].append(v)
        in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    semester_count = 0
    studied_courses = 0

    while queue:
        size = len(queue)
        for _ in range(size):
            course = queue.popleft()
            studied_courses += 1
            for next_course in graph[course]:
                in_degree[next_course] -= 1
                if in_degree[next_course] == 0:
                    queue.append(next_course)
        semester_count += 1

    return semester_count if studied_courses == n else -1

def min_semesters_multiple_cases(cases):
    results = []
    for case in cases:
        n, m, prerequisites = case
        results.append(min_semesters(n, prerequisites))
