def find_peak_element(arr):
    """
    Returns the index of any peak element in the array. The index is 1-based.
    """
    n = len(arr)

    # If there's only one element, it's a peak
    if n == 1:
        return 1

    # Check the first and last elements
    if arr[0] > arr[1]:
        return 1
    if arr[n - 1] > arr[n - 2]:
        return n

    # Check middle elements
    for i in range(1, n - 1):
        if arr[i] > arr[i - 1] and arr[i] > arr[i + 1]:
            return i + 1

    # If no peak is found, return -1 (shouldn't happen with valid inputs)
    return -1

