def is_prime(num):
    """
    Check if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num ** 0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def largest_prime_in_rows(grid):
    """
    Finds the largest prime number within each row of the grid.
    If a row does not contain any prime number, return -1 for that row.
    """
    result = []
    for row in grid:
        largest_prime = -1
        for num in row:
            if is_prime(num):
                largest_prime = max(largest_prime, num)
        result.append(largest_prime)
    return result

def process_grid(n, m, grid):
    """
    Process the input grid and return the largest prime number in each row.
    """
    return largest_prime_in_rows(grid)

