def min_operations(s, t):
    """
    Returns the minimum number of operations required to convert
    string s into string t.
    """
    m, n = len(s), len(t)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Initialize the base cases
    for i in range(m + 1):
        dp[i][0] = i  # Deleting all characters from s[0:i]
    for j in range(n + 1):
        dp[0][j] = j  # Inserting all characters to form t[0:j]

    # Fill the dp table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # Deletion
                                   dp[i][j - 1],    # Insertion
                                   dp[i - 1][j - 1])  # Replacement

    return dp[m][n]

