from typing import List, Tuple

def can_assign_deliveries(t: int, cases: List[Tuple[int, List[int], int, List[int]]]) -> List[str]:
    results = []

    for case in cases:
        n, truck_capacities, m, delivery_weights = case

        # Sort truck capacities in descending order
        truck_capacities.sort(reverse=True)
        # Sort delivery weights in descending order
        delivery_weights.sort(reverse=True)

        possible = True
        for delivery_weight in delivery_weights:
            assigned = False
            for i in range(n):
                if truck_capacities[i] >= delivery_weight:
                    truck_capacities[i] -= delivery_weight
                    assigned = True
                    break

            if not assigned:
                possible = False
                break

        if possible:
            results.append("Possible")
        else:
            results.append("Impossible")

    return results

