from typing import List

def numIslands(grid: List[List[str]]) -> int:
    """
    Returns the number of islands in the given 2D grid.
    """
    if not grid:
        return 0

    def dfs(grid, i, j):
        if i < 0 or i >= len(grid) or j < 0 or j >= len(grid[0]) or grid[i][j] == '0':
            return
        grid[i][j] = '0'  # Mark the land as visited by sinking it
        # Apply DFS in all 4 directions
        dfs(grid, i - 1, j)
        dfs(grid, i + 1, j)
        dfs(grid, i, j - 1)
        dfs(grid, i, j + 1)

    count = 0
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == '1':
                count += 1  # Start of a new island
                dfs(grid, i, j)
    return count

def is_prime(x):
    """
    Helper function to check if a number is prime.
    """
    if x <= 1:
        return False
    if x <= 3:
        return True
    if x % 2 == 0 or x % 3 == 0:
        return False
    i = 5
    while i * i <= x:
        if x % i == 0 or x % (i + 2) == 0:
            return False
        i += 6
    return True

def next_prime(N):
    """
    Function to find the smallest prime number greater than N.
    """
    candidate = N + 1
    while not is_prime(candidate):
        candidate += 1
    return candidate

