def count_pairs(arr, target):
    """
    Count the number of distinct pairs (i, j) in the array such that the sum of the two numbers equals the target.
    """
    seen = {}
    count = 0

    for num in arr:
        complement = target - num
        if complement in seen:
            count += seen[complement]

        if num in seen:
            seen[num] += 1
        else:
            seen[num] = 1

    return count

