def smallest_missing_prime(arr):
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2 or num == 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    known_primes = set()
    max_val = 10000

    sieve = [True] * (max_val + 1)
    sieve[0] = sieve[1] = False

    for start in range(2, max_val + 1):
        if sieve[start]:
            known_primes.add(start)
            for multiple in range(start*start, max_val + 1, start):
                sieve[multiple] = False

    arr_set = set(arr)
    for prime in sorted(known_primes):
        if prime not in arr_set:
            return prime

def solve(test_cases):
    results = []
    for arr in test_cases:
        results.append(smallest_missing_prime(arr))
    return results

