def longest_consecutive_subsequence(nums):
    """
    Returns the longest subsequence of consecutive integers in increasing order.
    If there are multiple subsequences of the same length, returns any one of them.

    :param nums: List of positive integers
    :return: List of integers representing the longest subsequence of consecutive integers
    """
    if not nums:
        return []

    nums = sorted(set(nums))
    longest, current = [], []

    for num in nums:
        if not current or num == current[-1] + 1:
            current.append(num)
        else:
            if len(current) > len(longest):
                longest = current
            current = [num]

    return max(longest, current, key=len)

