def areAnagrams(S1, S2):
    """
    Function to check if two strings S1 and S2 are anagrams of each other.
    """
    # Early exit if the lengths of the strings are not equal
    if len(S1) != len(S2):
        return False

    # Use a dictionary to count characters
    char_count = {}

    # Count each character in S1
    for char in S1:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Decrease the count based on characters in S2
    for char in S2:
        if char in char_count:
            char_count[char] -= 1
        else:
            return False

    # Check if all counts are zero
    for count in char_count.values():
        if count != 0:
            return False

    return True

