def longest_ap_subsequence_length(t, test_cases):
    results = []

    for case in test_cases:
        n, arr = case
        if n <= 1:
            results.append(n)
            continue

        dp = {}
        max_length = 1

        for i in range(n):
            dp[i] = {}
            for j in range(i):
                diff = arr[i] - arr[j]
                if diff in dp[j]:
                    dp[i][diff] = dp[j][diff] + 1
                else:
                    dp[i][diff] = 2
                max_length = max(max_length, dp[i][diff])

        results.append(max_length)
    return results

