def unique_paths_with_obstacles(grid):
    MOD = 10**9 + 7
    N = len(grid)
    M = len(grid[0])

    # Edge case where start or end is blocked
    if grid[0][0] == '#' or grid[N-1][M-1] == '#':
        return 0

    dp = [[0] * M for _ in range(N)]

    dp[0][0] = 1  # Start point

    for i in range(N):
        for j in range(M):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]
                dp[i][j] %= MOD

    return dp[-1][-1]

