def fibonacci_sequence(n):
    """
    Returns the first n numbers of the Fibonacci sequence as a list.
    """
    if n <= 0:
        return []

    sequence = [0, 1] if n > 1 else [0]

    while len(sequence) < n:
        sequence.append(sequence[-1] + sequence[-2])

    return sequence

