def is_arithmetic_sequence(arr):
    """
    Helper function to determine if an array is already an arithmetic sequence.
    """
    if len(arr) <= 1:
        return True

    common_diff = arr[1] - arr[0]
    for i in range(1, len(arr)):
        if arr[i] - arr[i - 1] != common_diff:
            return False
    return True

def min_operations_to_arithmetic_sequence(arr):
    """
    Returns the minimum number of operations needed to make arr an arithmetic sequence.
    """
    if is_arithmetic_sequence(arr):
        return 0

    min_operations = float('inf')
    n = len(arr)

    for i in range(n):
        for j in range(i + 1, n):
            potential_diff = (arr[j] - arr[i]) / (j - i)
            if potential_diff != int(potential_diff):
                continue
            potential_diff = int(potential_diff)

            operations = 0
            for k in range(n):
                expected_value = arr[i] + (k - i) * potential_diff
                if arr[k] != expected_value:
                    operations += 1

            min_operations = min(min_operations, operations)

    return min_operations

