def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def longest_prime_subsequence(arr):
    prime_length = 0
    max_length = 0
    for num in arr:
        if is_prime(num):
            prime_length += 1
            max_length = max(max_length, prime_length)
        else:
            prime_length = 0
    return max_length

def find_longest_prime_subsequence(test_cases):
    results = []
    for n, sequence in test_cases:
        results.append(longest_prime_subsequence(sequence))
    return results

