def arrange_participants(test_cases):
    results = []
    for t in test_cases:
        n, k, energy_levels = t
        energy_levels.sort()

        possible = True
        for i in range(1, n):
            if energy_levels[i] - energy_levels[i-1] < k:
                possible = False
                break

        if possible:
            results.append(f"POSSIBLE\n{' '.join(map(str, energy_levels))}")
        else:
            results.append("IMPOSSIBLE")

    return results

def process_input(input_data):
    input_lines = input_data.split("\n")
    t = int(input_lines[0])
    test_cases = []
    line = 1
    for _ in range(t):
        n, k = map(int, input_lines[line].split())
        energy_levels = list(map(int, input_lines[line + 1].split()))
        test_cases.append((n, k, energy_levels))
        line += 2
    return test_cases

def main(input_data):
    test_cases = process_input(input_data)
    return arrange_participants(test_cases)

