def find_element_between_odd_and_even(nums):
    """
    Given a list of integers, returns the first element that appears
    after the first odd number and before the first even number.
    If no such element exists, returns -1.
    """
    found_odd = False

    for i, num in enumerate(nums):
        if num % 2 != 0:
            found_odd = True
        elif num % 2 == 0 and found_odd:
            if i - 1 >= 0:
                return nums[i-1]
            break

    return -1

