def flatten_dictionary(d, parent_key=''):
    """
    Flattens a dictionary, where the keys can be nested arbitrarily deep.
    """
    items = []
    for k, v in d.items():
        new_key = parent_key + '.' + k if parent_key else k
        if isinstance(v, dict):
            items.extend(flatten_dictionary(v, new_key).items())
        else:
            items.append((new_key, v))
    return dict(items)

