def reorder_string(s):
    """
    Reorders the given string such that all letters come first, followed by all the digits.
    The relative ordering of letters and digits is preserved.
    """
    letters = []
    digits = []

    for char in s:
        if char.isdigit():
            digits.append(char)
        else:
            letters.append(char)

    return ''.join(letters) + ''.join(digits)

