def longest_contiguous_subarray(arr):
    if not arr:
        return []

    max_len = 1
    current_len = 1
    element = arr[0]
    start_index = 0

    for i in range(1, len(arr)):
        if arr[i] == arr[i-1]:
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
                element = arr[i-1]
                start_index = i - current_len

            current_len = 1

    if current_len > max_len:
        max_len = current_len
        element = arr[-1]
        start_index = len(arr) - current_len

    return arr[start_index:start_index + max_len]

