def can_be_sorted_by_rotating(nums):
    """
    Determine if the array can be sorted in non-decreasing order by rotating the array.
    """
    count_inversions = 0
    n = len(nums)

    for i in range(n):
        if nums[i] > nums[(i+1) % n]:
            count_inversions += 1

    return count_inversions <= 1

