def first_missing_positive(nums):
    """
    Given an unsorted integer array nums, return the smallest missing positive integer.
    """
    n = len(nums)

    # We use the indices of the array itself for marking purposes
    # First move every positive integer <= n to its corresponding index (1-based)
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    # After rearranging, the first index i which does not have the number i+1 is the answer
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    # If all numbers are in their correct place, the missing number is n+1
    return n + 1

