def max_non_overlapping_workshops(t, cases):
    results = []

    for i in range(t):
        n, intervals = cases[i]
        intervals.sort(key=lambda x: x[1])

        count = 0
        end_time = 0

        for start, end in intervals:
            if start >= end_time:
                count += 1
                end_time = end

        results.append(count)

    return results

