def can_plant_seeds(n, m, constraints):
    # Create a list to track which fields are restricted for each seed type
    restricted_fields = [set() for _ in range(n+1)]

    # Fill the restricted fields for each seed type based on constraints
    for a, b in constraints:
        restricted_fields[a].add(b)

    # Check each possible arrangement of seed types in the fields
    for start_field in range(1, n+1):
        possible = True
        for seed in range(1, n+1):
            if start_field in restricted_fields[seed]:
                possible = False
                break
        if possible:
            return "YES"

    return "NO"

