def rearrange_possible(n, arr):
    """
    Checks if it is possible to rearrange the list such that the difference between any two
    adjacent numbers is at most 1 and returns the appropriate result.
    """
    arr.sort()

    for i in range(n - 1):
        if arr[i + 1] - arr[i] > 1:
            return "NO", []

    return "YES", arr

