def max_wealth(n, k, wealth):
    """
    Returns the maximum amount of wealth that can be robbed without robbing
    two adjacent houses and without robbing more than k houses.
    """
    if k == 1:
        return max(wealth)

    dp = [[0 for _ in range(k+1)] for _ in range(n+1)]

    for i in range(1, n+1):
        for j in range(1, k+1):
            dp[i][j] = max(dp[i-1][j], wealth[i-1] + (dp[i-2][j-1] if i > 1 else 0))

    return dp[n][k]

