def count_islands(N, grid):
    def dfs(x, y):
        if x < 0 or x >= N or y < 0 or y >= N or grid[x][y] != 'L':
            return
        grid[x][y] = 'V'  # Mark as visited
        # Move in all 4 possible directions
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    island_count = 0

    for i in range(N):
        for j in range(N):
            if grid[i][j] == 'L':
                island_count += 1
                dfs(i, j)

    return island_count

from collections import deque

def min_steps_to_reach_end(garden):
    N = len(garden)
    M = len(garden[0])

    if garden[0][0] == '#' or garden[N - 1][M - 1] == '#':
        return -1

    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([((0, 0), 0)])
    visited = set((0, 0))

    while queue:
        (x, y), steps = queue.popleft()

        if x == N - 1 and y == M - 1:
            return steps

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < M and garden[nx][ny] == '.' and (nx, ny) not in visited:
                visited.add((nx, ny))
                queue.append(((nx, ny), steps + 1))

    return -1

def solve(test_cases):
    results = []
    for case in test_cases:
        N, M, garden = case
        result = min_steps_to_reach_end(garden)
        results.append(result)
    return results

