def two_sum(arr, target):
    """
    Determines whether there are two distinct elements in the array that add up to the target sum.
    Returns their indices as a tuple or None if no such pair exists.
    """
    seen = {}
    for i, num in enumerate(arr):
        complement = target - num
        if complement in seen:
            return (seen[complement], i)
        seen[num] = i
    return None

