def first_non_repeated_character(s):
    """
    Returns the first non-repeated character in the given string.
    """
    # Dictionary to keep the count of each character
    char_count = {}

    # First pass to count all characters
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Second pass to find the first character that has a count of 1
    for char in s:
        if char_count[char] == 1:
            return char

    # If there's no non-repeated character
    return None

