def longestUniquePath(grid):
    def dfs(x, y, visited):
        # Base case: if out of bounds or character has been visited
        if x < 0 or x >= M or y < 0 or y >= N or grid[x][y] in visited:
            return 0
        visited.add(grid[x][y])
        max_length = 1  # Current cell counts as length 1
        # Explore all 4 directions
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            max_length = max(max_length, 1 + dfs(nx, ny, visited))
        visited.remove(grid[x][y])
        return max_length

    M, N = len(grid), len(grid[0])
    max_path_length = 0
    for i in range(M):
        for j in range(N):
            max_path_length = max(max_path_length, dfs(i, j, set()))
    return max_path_length

