def sum_of_primes(n):
    """
    Returns the sum of all prime numbers less than or equal to n.
    """
    if n < 2:
        return 0

    sieve = [True] * (n + 1)
    sieve[0] = sieve[1] = False

    for start in range(2, int(n**0.5) + 1):
        if sieve[start]:
            for i in range(start*start, n + 1, start):
                sieve[i] = False

    return sum(i for i in range(n + 1) if sieve[i])

