def count_and_say(n):
    """
    Returns the nth term of the 'count and say' sequence.
    """
    if n == 1:
        return "1"

    # Helper function to generate the next term in the sequence
    def next_term(s):
        result = []
        i = 0
        while i < len(s):
            count = 1
            while i + 1 < len(s) and s[i] == s[i + 1]:
                i += 1
                count += 1
            result.append(str(count) + s[i])
            i += 1
        return ''.join(result)

    current_term = "1"
    for _ in range(1, n):
        current_term = next_term(current_term)

    return current_term

