def is_balanced(s):
    """
    Checks if the brackets in the string are properly nested and balanced.
    """
    stack = []
    bracket_map = {')': '(', ']': '[', '}': '{', '>': '<'}

    for char in s:
        if char in bracket_map.values():
            stack.append(char)
        elif char in bracket_map.keys():
            if stack == [] or bracket_map[char] != stack.pop():
                return False

    return stack == []

