def longest_ascending_subsequence(n, sequence):
    """
    Determines the length of the longest ascending subsequence in the sequence.

    Parameters:
    n (int): Length of the input sequence.
    sequence (list): The input sequence of integers.

    Returns:
    int: Length of the longest ascending subsequence.
    """
    if n == 0:
        return 0

    # DP array to store the length of the longest subsequence at each position
    dp = [1] * n

    for i in range(1, n):
        for j in range(0, i):
            if sequence[i] > sequence[j] and dp[i] < dp[j] + 1:
                dp[i] = dp[j] + 1

    return max(dp)

