def sum_fibonacci(N):
    """
    Returns the sum of the first N Fibonacci numbers.
    """
    if N == 0:
        return 0
    elif N == 1:
        return 0  # only F(0) = 0
    elif N == 2:
        return 1  # F(0) + F(1) = 0 + 1 = 1

    fib = [0, 1]  # Starting point

    # Building the Fibonacci sequence
    for i in range(2, N):
        fib.append(fib[i-1] + fib[i-2])

    return sum(fib)

