def check_prime_likes(n: int) -> str:
    """
    Determine if the number of likes is a prime number.

    Parameters:
    n (int): The number of likes (1 ≤ n ≤ 1,000,000)

    Returns:
    str: "Special Mention!" if n is a prime number, "Keep Trying!" otherwise.
    """
    if n < 2:
        return "Keep Trying!"
    if n == 2:
        return "Special Mention!"
    if n % 2 == 0:
        return "Keep Trying!"

    sqrt_n = int(n ** 0.5) + 1
    for i in range(3, sqrt_n, 2):
        if n % i == 0:
            return "Keep Trying!"

    return "Special Mention!"

def check_rectangular_path(n, m, grid):
    """
    This function checks if there exists a rectangular path such that
    all the cells along the path are '1's.
    """
    for r1 in range(n):
        for r2 in range(r1 + 1, n):
            for c1 in range(m):
                for c2 in range(c1 + 1, m):
                    if grid[r1][c1] == '1' and grid[r1][c2] == '1' and grid[r2][c1] == '1' and grid[r2][c2] == '1':
                        return "Yes"
    return "No"

