def max_items_collected(n, m, k, grid):
    def dfs(x, y, steps, collected):
        if steps > k:
            return 0

        max_collected = collected + grid[x][y]
        visited.add((x, y))

        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
                max_collected = max(max_collected, dfs(nx, ny, steps + 1, collected + grid[x][y]))

        visited.remove((x, y))
        return max_collected

    max_items = 0
    for i in range(n):
        for j in range(m):
            visited = set()
            max_items = max(max_items, dfs(i, j, 0, 0))

    return max_items

def isBalanced(expression):
    """
    Returns True if the given expression has balanced parentheses, otherwise False.
    """
    stack = []

    for char in expression:
        if char == '(':
            stack.append(char)
        elif char == ')':
            if not stack:
                return False
            stack.pop()

    return not stack

def maximumDistance(lst):
    """
    Returns the maximum distance between any two identical elements in the list.
    If there are no identical elements, returns -1.
    """
    element_indices = {}
    max_distance = -1

    for index, value in enumerate(lst):
        if value in element_indices:
            max_distance = max(max_distance, index - element_indices[value])
        else:
            element_indices[value] = index

    return max_distance

