def uniquePaths(n, m, obstacles):
    """
    Returns the number of unique paths in an n x n grid
    starting from (1, 1) to (n, n) avoiding obstacles.
    """
    grid = [[0] * n for _ in range(n)]

    if m > 0:
        for x, y in obstacles:
            grid[x - 1][y - 1] = -1

    if grid[0][0] == -1 or grid[n-1][n-1] == -1:
        return 0

    grid[0][0] = 1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == -1:
                continue

            if i > 0 and grid[i-1][j] != -1:
                grid[i][j] += grid[i-1][j]

            if j > 0 and grid[i][j-1] != -1:
                grid[i][j] += grid[i][j-1]

    return grid[n-1][n-1]

def process_test_cases(test_cases):
    results = []
    for case in test_cases:
        n, m, obstacles = case
        results.append(uniquePaths(n, m, obstacles))
    return results

def is_valid_parentheses(s):
    """
    Determine if the input string containing only parentheses is valid.
    """
    stack = []
    matching_parentheses = {')': '(', ']': '[', '}': '{'}

    for char in s:
        if char in matching_parentheses.values():
            stack.append(char)
        elif char in matching_parentheses:
            if stack == [] or stack.pop() != matching_parentheses[char]:
                return "INVALID"
        else:
            return "INVALID"

    return "VALID" if stack == [] else "INVALID"

def minimum_subset_sum_diff(arr):
    total_sum = sum(arr)
    n = len(arr)

    dp = [[False] * (total_sum // 2 + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = True

    for i in range(1, n + 1):
        for j in range(1, total_sum // 2 + 1):
            if arr[i - 1] <= j:
                dp[i][j] = dp[i - 1][j] or dp[i - 1][j - arr[i - 1]]
            else:
                dp[i][j] = dp[i - 1][j]

    for j in range(total_sum // 2, -1, -1):
        if dp[n][j]:
            subset_sum_1 = j
            break

    subset_sum_2 = total_sum - subset_sum_1

    return abs(subset_sum_2 - subset_sum_1)

def solve(T, test_cases):
    results = []
    for i in range(T):
        N, arr = test_cases[i]
        results.append(minimum_subset_sum_diff(arr))
    return results

