def run_length_encode(string):
    """
    Returns the Run-Length Encoded string for the given input string.
    """
    if not string:
        return ""

    encoded_string = []
    count = 1

    for i in range(1, len(string)):
        if string[i] == string[i - 1]:
            count += 1
        else:
            encoded_string.append(string[i - 1] + str(count))
            count = 1

    encoded_string.append(string[-1] + str(count))  # Append the last character and its count

    return "".join(encoded_string)


def process_test_cases(test_cases):
    """
    Process multiple test cases of run-length encoding.
    """
    return [run_length_encode(test_case) for test_case in test_cases]

