def count_palindromic_subsequences(seq):
    """
    Counts the number of contiguous palindromic subsequences in the given sequence.

    :param seq: List[int] - A list of integers representing the sequence.
    :return: int - The count of palindromic subsequences.
    """
    n = len(seq)
    dp = [[False] * n for _ in range(n)]
    count = 0

    for i in range(n):
        dp[i][i] = True
        count += 1

    for length in range(2, n + 1):
        for start in range(n - length + 1):
            end = start + length - 1
            if seq[start] == seq[end]:
                if length == 2 or dp[start + 1][end - 1]:
                    dp[start][end] = True
                    count += 1

    return count

