def first_missing_positive(nums):
    """
    Finds the first missing positive integer in an unsorted list of integers.
    """
    n = len(nums)

    # Shift numbers to their corresponding indices
    for i in range(n):
        while 1 <= nums[i] <= n and nums[nums[i] - 1] != nums[i]:
            nums[nums[i] - 1], nums[i] = nums[i], nums[nums[i] - 1]

    # Find the first number that is not at the correct index
    for i in range(n):
        if nums[i] != i + 1:
            return i + 1

    return n + 1

