def min_valid_sequences(S, dictionary):
    n = len(S)
    dp = [-1] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] != -1:
            for word in dictionary:
                if S[i:i + len(word)] == word:
                    if dp[i + len(word)] == -1 or dp[i + len(word)] > dp[i] + 1:
                        dp[i + len(word)] = dp[i] + 1

    return dp[n]

def min_partition(T, test_cases):
    results = []
    for case in test_cases:
        N, S, M, dictionary = case
        if (result := min_valid_sequences(S, set(dictionary))) == -1:
            results.append(-1)
        else:
            results.append(result)

    return results

