def reorder_string(s):
    """
    Reorders the string so that all letters appear before the digits,
    while maintaining the relative order of both letters and digits
    from the original string.
    """
    letters = []
    digits = []

    for char in s:
        if char.isdigit():
            digits.append(char)
        else:
            letters.append(char)

    return ''.join(letters) + ''.join(digits)

