def total_food(days, animalType):
    """
    Returns the total amount of food consumed by an animal type over a number of days.
    """
    if animalType == "elephant":
        return days * 50
    elif animalType == "lion":
        return 3 * days + 1.5 * (days * (days - 1)) / 2
    elif animalType == "monkey":
        return 0.3 * days + 0.1 * (days * (days - 1)) / 2
    else:
        raise ValueError("Invalid animal type")

