def evaluate(expression):
    def parse_expression(expression):
        num_stack = []
        op_stack = []

        precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
        i = 0

        while i < len(expression):
            if expression[i].isdigit():
                num = 0
                while i < len(expression) and expression[i].isdigit():
                    num = num * 10 + int(expression[i])
                    i += 1
                num_stack.append(num)
                i -= 1
            elif expression[i] in precedence:
                while (op_stack and precedence[op_stack[-1]] >= precedence[expression[i]]):
                    apply_operation(num_stack, op_stack)
                op_stack.append(expression[i])
            i += 1

        while op_stack:
            apply_operation(num_stack, op_stack)

        return num_stack[0]

    def apply_operation(num_stack, op_stack):
        if not num_stack or len(num_stack) < 2:
            return

        b = num_stack.pop()
        a = num_stack.pop()
        op = op_stack.pop()

        if op == '+':
            num_stack.append(a + b)
        elif op == '-':
            num_stack.append(a - b)
        elif op == '*':
            num_stack.append(a * b)
        elif op == '/':
            num_stack.append(a // b)

    return parse_expression(expression)

