def minimize_sum_of_maximums(nums, k):
    import math

    def can_partition(mid):
        partitions = 1
        current_max = -math.inf
        for num in nums:
            current_max = max(current_max, num)
            if current_max > mid:
                partitions += 1
                current_max = num
                if partitions > k:
                    return False
        return True

    left, right = max(nums), sum(nums)
    while left < right:
        mid = (left + right) // 2
        if can_partition(mid):
            right = mid
        else:
            left = mid + 1

    return left

