def check_toxicity(test_cases):
    results = []
    for test_case in test_cases:
        main_string = test_case['main_string']
        toxic_subsequences = test_case['subsequences']
        threshold = test_case['threshold']

        total_toxicity = 0

        for subsequence, toxicity in toxic_subsequences:
            # Count occurrences of the toxic subsequence in the main string
            count = main_string.count(subsequence)
            total_toxicity += count * toxicity

        if total_toxicity > threshold:
            results.append("YES")
        else:
            results.append("NO")

    return results

