def find_digit_product_number(P):
    """
    Finds the smallest possible Digit Product Number such that the product of its digits is equal to P.
    If no such number exists, returns -1.
    """
    if P == 1:
        return 1

    if P < 10:
        return P

    factors = []
    for digit in range(9, 1, -1):
        while P % digit == 0:
            factors.append(digit)
            P //= digit

    if P > 1:
        return -1

    factors.sort()
    digit_product_number = int(''.join(map(str, factors)))
    return digit_product_number

