def isWave(arr, n):
    """
    Determine if the array arr is a wave.
    :param arr: List[int] - an array of integers
    :param n: int - the length of the array
    :return: bool - True if the array is a wave, otherwise False
    """
    if n < 2:
        return True

    for i in range(1, n-1):
        if (arr[i] - arr[i-1]) * (arr[i+1] - arr[i]) >= 0:
            return False
    return True

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def count_primes(arr):
    return sum(1 for x in arr if is_prime(x))

