def process_grid_operations(N, M, Q, operations):
    grid = [[0] * M for _ in range(N)]
    results = []

    for op in operations:
        if op[0] == 'row':
            x, y = int(op[1]) - 1, int(op[2])
            for col in range(M):
                grid[x][col] += y
        elif op[0] == 'col':
            x, y = int(op[1]) - 1, int(op[2])
            for row in range(N):
                grid[row][x] += y
        elif op[0] == 'max':
            max_value = max(max(row) for row in grid)
            results.append(max_value)

    return results

def find_robot_final_position(R, C, grid, initial_position, commands):
    x, y = initial_position

    for command in commands:
        if command == 'U':
            new_x, new_y = x - 1, y
        elif command == 'D':
            new_x, new_y = x + 1, y
        elif command == 'L':
            new_x, new_y = x, y - 1
        elif command == 'R':
            new_x, new_y = x, y + 1

        # Check boundaries and obstacles
        if 0 <= new_x < R and 0 <= new_y < C and grid[new_x][new_y] != '#':
            x, y = new_x, new_y
        else:
            break  # stops moving if an obstacle is encountered or out of bounds

    return x, y

def evaluate_fizzlang(expression):
    def helper(expr, start, end):
        num = 0
        stack = []
        sign = "+"

        i = start
        while i <= end:
            char = expr[i]

            if char.isdigit():
                num = num * 10 + int(char)

            if char in "+*" or i == end:
                if sign == "+":
                    stack.append(num)
                elif sign == "*":
                    stack.append(stack.pop() * num)
                sign, num = char, 0

            i += 1

        return sum(stack)

    return helper(expression, 0, len(expression) - 1)

