from typing import List

def find_quadruplets(numbers: List[int], target: int) -> List[List[int]]:
    numbers.sort()  # Sort the array to make it easier to skip duplicates
    quadruplets = []

    for i in range(len(numbers) - 3):
        if i > 0 and numbers[i] == numbers[i - 1]:  # Skip duplicate values for the first element
            continue
        for j in range(i + 1, len(numbers) - 2):
            if j > i + 1 and numbers[j] == numbers[j - 1]:  # Skip duplicate values for the second element
                continue
            left = j + 1
            right = len(numbers) - 1
            while left < right:
                current_sum = numbers[i] + numbers[j] + numbers[left] + numbers[right]
                if current_sum == target:
                    quadruplets.append([numbers[i], numbers[j], numbers[left], numbers[right]])
                    left += 1
                    right -= 1
                    # Skip duplicate values for the third and fourth elements
                    while left < right and numbers[left == numbers[left - 1]]:
                        left += 1
                    while left < right and numbers[right] == numbers[right + 1]:
                        right -= 1
                elif current_sum < target:
                    left += 1
                else:
                    right -= 1
    return quadruplets

def longestRepeatedSequence(message):
    """
    Returns the length of the longest sequence of repeated characters in the given string.
    """
    if not message:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(message)):
        if message[i] == message[i - 1]:
            current_length += 1
        else:
            max_length = max(max_length, current_length)
            current_length = 1

    max_length = max(max_length, current_length)
    return max_length

