def minContainers(products, maxCapacity):
    # Sort products in descending order
    products.sort(reverse=True)

    # List to hold the current weight in each container
    containers = []

    for weight in products:
        placed = False
        # Try to place the current product in one of the existing containers
        for i in range(len(containers)):
            if containers[i] + weight <= maxCapacity:
                containers[i] += weight
                placed = True
                break
        # If the product could not be placed in an existing container, add a new container
        if not placed:
            containers.append(weight)

    return len(containers)

