def count_primes_and_max_gap(X, Y):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [num for num in range(X, Y + 1) if is_prime(num)]
    if len(primes) < 2:
        return len(primes), 0

    max_gap = max(primes[i + 1] - primes[i] for i in range(len(primes) - 1))

    return len(primes), max_gap

