def num_unique_islands(n, m, grid):
    def dfs(x, y):
        stack = [(x, y)]
        while stack:
            i, j = stack.pop()
            for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ni, nj = i + di, j + dj
                if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == '.':
                    stack.append((ni, nj))
                    grid[ni][nj] = '#'  # Mark visited

    island_count = 0
    for i in range(n):
        for j in range(m):
            if grid[i][j] == '.':
                dfs(i, j)
                island_count += 1

    return island_count

