import heapq
import sys
from collections import defaultdict

def shortest_travel_time(N, M, Capital, roads):
    graph = defaultdict(list)

    # Creating the graph
    for u, v, travel_time in roads:
        graph[u].append((v, travel_time))
        graph[v].append((u, travel_time))

    # Dijkstra's algorithm
    heap = [(0, Capital)]
    distances = {i: float('inf') for i in range(1, N+1)}
    distances[Capital] = 0

    while heap:
        current_dist, current_city = heapq.heappop(heap)

        if current_dist > distances[current_city]:
            continue

        for neighbor, weight in graph[current_city]:
            distance = current_dist + weight

            if distance < distances[neighbor]:
                distances[neighbor] = distance
                heapq.heappush(heap, (distance, neighbor))

    result = []
    for i in range(1, N+1):
        if i == Capital:
            result.append(0)
        else:
            result.append(distances[i] if distances[i] != float('inf') else -1)

    return result

def max_product(arr):
    """
    Returns the maximum product that can be obtained by multiplying two distinct elements from the array.
    """
    if len(arr) < 2:
        raise ValueError("The array should contain at least two elements.")

    arr.sort()
    product1 = arr[-1] * arr[-2]
    product2 = arr[0] * arr[1]

    return max(product1, product2)

