def shortest_palindrome_length(s):
    """
    Given a string `s`, this function returns the length of the shortest palindrome
    that can be made by adding characters to the end of `s`.
    """
    if s == s[::-1]:
        return len(s)

    for i in range(len(s)-1, -1, -1):
        if s[:i+1] == s[:i+1][::-1]:
            return len(s) + (len(s) - (i+1))

    return 2 * len(s) - 1

