def max_points(n, T, times, points):
    # Initialize a DP array where dp[i] will store the maximum number of points
    # achievable with exactly i hours
    dp = [0] * (T + 1)

    # Iterate over each problem
    for i in range(n):
        # Iterate over possible total times in reverse to avoid overcounting
        for t in range(T, times[i] - 1, -1):
            dp[t] = max(dp[t], dp[t - times[i]] + points[i])

    return max(dp)

