def generate_password(input_string):
    """
    Generates a secure password based on the given input string based on Zedonia's rules.
    """
    if input_string.islower():
        return input_string[::-1]
    elif input_string.isupper():
        return input_string.lower()
    elif input_string.isdigit():
        return str(sum(int(char) for char in input_string))
    elif input_string.isalpha():
        return input_string.swapcase()
    else:
        return "INVALID"

