def countVowelsAndConsonants(S):
    """
    Takes a string S as input and returns a dictionary with the
    count of vowels and consonants in the string.
    """
    vowels = "aeiouAEIOU"
    vowel_count = 0
    consonant_count = 0

    for char in S:
        if char.isalpha():
            if char in vowels:
                vowel_count += 1
            else:
                consonant_count += 1

    return {"vowels": vowel_count, "consonants": consonant_count}

