def removeDigit(num):
    """
    Given a string containing digits from "0" to "9",
    generate the smallest possible integer number (in string format)
    by removing exactly one digit from the input string.
    """
    for i in range(len(num) - 1):
        if num[i] > num[i + 1]:
            return num[:i] + num[i + 1:]
    return num[:-1]

