def is_valid_bracket_sequence(s):
    """
    Determine if the provided bracket string is valid. A string of brackets is considered
    valid if every opening bracket has a corresponding closing bracket and the pairs
    of brackets are properly nested.
    """
    stack = []
    bracket_map = {')': '(', '}': '{', ']': '['}

    for char in s:
        if char in bracket_map:
            top_element = stack.pop() if stack else '#'
            if bracket_map[char] != top_element:
                return "NO"
        else:
            stack.append(char)

    return "YES" if not stack else "NO"

def unique_paths(grid):
    n = len(grid)
    dp = [[0] * n for _ in range(n)]

    if grid[0][0] == '#' or grid[n-1][n-1] == '#':
        return 0

    dp[0][0] = 1

    for i in range(n):
        for j in range(n):
            if grid[i][j] == '#':
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i-1][j]
                if j > 0:
                    dp[i][j] += dp[i][j-1]

    return dp[n-1][n-1]

