def count_ones_in_binary(n):
    """
    Given a non-negative integer n, returns the count of 1s in its binary representation.
    """
    if n < 0 or n > 1000:
        raise ValueError("Input must be within the range 0 to 1000 inclusive.")
    binary_representation = bin(n)
    return binary_representation.count('1')

