from math import gcd
from functools import reduce

def find_largest_p(N, arr):
    """
    Given a list of N integers, this function returns the largest positive integer P
    such that P is a factor of the sum of the integers in the list and
    P is also the greatest common divisor (GCD) of a subset of the given list.
    """
    def gcd_multiple(numbers):
        return reduce(gcd, numbers)

    total_sum = sum(arr)
    max_p = 1  # Initialize max_p to 1, the smallest possible positive integer factor of any sum

    # Finding the GCD of the entire list first, as any subset's GCD must be a divisor of this
    overall_gcd = gcd_multiple(arr)

    # We will check divisors starting from the largest possible down to 1
    for p in range(overall_gcd, 0, -1):
        if total_sum % p == 0:
            return p

def solve(test_cases):
    results = []

    for N, arr in test_cases:
        results.append(find_largest_p(N, arr))

    return results

