def count_distinct_substrings(n, s):
    """
    Returns the number of distinct substrings of the text after processing
    the input sequence of length n and consisting of lowercase English letters.
    """
    substrings = set()

    for i in range(n):
        for j in range(i + 1, n + 1):
            substrings.add(s[i:j])

    return len(substrings)

