def min_exhibits_to_showcase(T, test_cases):
    from itertools import combinations

    def count_unique_games(selected_exhibits):
        unique_games = set()
        for exhibit in selected_exhibits:
            unique_games.update(exhibit[1:])
        return len(unique_games)

    results = []
    for test_case in test_cases:
        N, X = test_case[0]
        exhibits = test_case[1]

        min_count = float('inf')
        found = False

        for r in range(1, N + 1):
            for combo in combinations(exhibits, r):
                if count_unique_games(combo) >= X:
                    min_count = min(min_count, r)
                    found = True

        results.append(min_count if found else -1)

    return results

def can_form_string(T, m, strings):
    mandatory = []
    optional = []

    for c, s in strings:
        if c == 1:
            mandatory.append(s)
        else:
            optional.append(s)

    # Look for all mandatory strings in T
    for s in mandatory:
        pos = T.find(s)
        if pos == -1:
            return "NO"
        else:
            T = T[:pos] + T[pos+len(s):]

    # Try to match the remaining T using optional strings
    dp = [False] * (len(T) + 1)
    dp[0] = True

    for i in range(len(T)):
        if dp[i]:
            for opt in optional:
                if T.startswith(opt, i):
                    dp[i + len(opt)] = True

    return "YES" if dp[len(T)] else "NO"

def task_scheduler(tasks):
    from collections import defaultdict, deque

    # Parse the tasks input
    task_info = {}
    task_dependencies = defaultdict(list)
    indegree = defaultdict(int)

    for task in tasks:
        task_id, duration, num_deps, *deps = task
        task_info[task_id] = (duration, deps)
        for dep in deps:
            task_dependencies[dep].append(task_id)
        indegree[task_id] = num_deps

    # Initialize with tasks that have no dependencies
    start_times = {}
    end_times = {}
    queue = deque()

    for task_id in task_info:
        if indegree[task_id] == 0:
            queue.append(task_id)
            start_times[task_id] = 0

    # Process the tasks in topological order
    while queue:
        current = queue.popleft()
        duration, deps = task_info[current]
        start_time = start_times[current]
        end_time = start_time + duration
        end_times[current] = end_time

        for dependent in task_dependencies[current]:
            indegree[dependent] -= 1
            if indegree[dependent] == 0:
                queue.append(dependent)
                start_times[dependent] = max(end_times[dep] for dep in task_info[dependent][1])

    # Prepare the result
    result = [(task_id, start_times[task_id], end_times[task_id]) for task_id in sorted(task_info)]

    return result

