def is_match(text, pattern):
    """
    Determines if the given text matches the pattern. The pattern may contain '*'
    (matching zero or more characters) and '.' (matching any single character).
    """
    def dfs(t_index, p_index):
        if p_index == len(pattern):
            return t_index == len(text)

        first_match = (t_index < len(text)) and (pattern[p_index] in {text[t_index], '.'})

        if p_index + 1 < len(pattern) and pattern[p_index + 1] == '*':
            return (dfs(t_index, p_index + 2) or
                    (first_match and dfs(t_index + 1, p_index)))
        else:
            return first_match and dfs(t_index + 1, p_index + 1)

    return "true" if dfs(0, 0) else "false"

