def diamond(n):
    """
    Generates a diamond-shaped pattern of asterisks (*) for a given positive odd integer n.

    If n is not a positive odd integer, returns an empty string.
    """
    if not isinstance(n, int) or n < 1 or n % 2 == 0:
        return ""

    lines = []
    for i in range(n):
        stars = '*' * (2 * i + 1) if i <= n // 2 else '*' * (2 * (n - i) - 1)
        spaces = ' ' * ((n - len(stars)) // 2)
        lines.append(spaces + stars)

    return '\n'.join(lines)

