def transformString(s):
    """
    Transforms the input string such that each character is replaced by the next character
    in the English alphabet. 'z' wraps around to 'a' and 'Z' to 'A'.
    """
    def next_char(c):
        if c == 'z':
            return 'a'
        elif c == 'Z':
            return 'A'
        else:
            return chr(ord(c) + 1)

    return ''.join(next_char(c) for c in s)

