def isValidIPv4(s):
    """
    Returns True if the string s is a valid IPv4 address, else returns False.
    """
    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part.isdigit() or (part[0] == '0' and len(part) > 1) or not (0 <= int(part) <= 255):
            return False

    return True

