def parse_input(input_string):
    lines = input_string.strip().split('\n')
    test_cases = []
    idx = 0

    while idx < len(lines):
        n = int(lines[idx])
        if n == 0:
            break
        idx += 1
        test_case = []
        for _ in range(n):
            serial, civilization = lines[idx].split(maxsplit=1)
            test_case.append((int(serial), civilization))
            idx += 1
        test_cases.append(test_case)

    return test_cases

def max_integer_after_deleting_one_character(s):
    """
    Returns the maximum possible integer value that can be obtained by deleting exactly one character from the string s.
    If deleting one character cannot form a valid integer, returns the original string.
    """
    if len(s) == 1:
        return s

    max_value = -1
    for i in range(len(s)):
        new_value = int(s[:i] + s[i+1:])
        if new_value > max_value:
            max_value = new_value

    return str(max_value)

