def longestIncreasingPath(grid):
    if not grid:
        return 0

    n, m = len(grid), len(grid[0])
    dp = [[-1] * m for _ in range(n)]

    def dfs(x, y):
        if dp[x][y] != -1:
            return dp[x][y]

        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
        max_path = 1
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < n and 0 <= ny < m and grid[nx][ny] > grid[x][y]:
                max_path = max(max_path, 1 + dfs(nx, ny))

        dp[x][y] = max_path
        return max_path

    max_length = 0
    for i in range(n):
        for j in range(m):
            max_length = max(max_length, dfs(i, j))

    return max_length

