def longestZigzag(sequence):
    if not sequence:
        return 0
    if len(sequence) == 1:
        return 1

    up = [1] * len(sequence)
    down = [1] * len(sequence)

    for i in range(1, len(sequence)):
        for j in range(i):
            if sequence[i] > sequence[j]:
                up[i] = max(up[i], down[j] + 1)
            elif sequence[i] < sequence[j]:
                down[i] = max(down[i], up[j] + 1)

    return max(up[-1], down[-1])

