def is_safe_position(n, m, queens):
    def under_attack(x, y):
        for qx, qy in queens:
            if qx == x or qy == y or abs(qx - x) == abs(qy - y):
                return True
        return False

    for x in range(n):
        for y in range(n):
            if not under_attack(x, y):
                return "Yes"
    return "No"

def find_safe_positions(datasets):
    results = []
    for dataset in datasets:
        n, m = dataset[0]
        queens = dataset[1:]
        results.append(is_safe_position(n, m, queens))
    return results

