def minModifyCells(grid):
    m, n = len(grid), len(grid[0])

    # A helper function to check if a path exists from (0, 0) to (m-1, n-1) without any modifications
    def check_path():
        if grid[0][0] == -1:
            return False
        visited = [[False]*n for _ in range(m)]
        stack = [(0, 0)]
        visited[0][0] = True
        while stack:
            x, y = stack.pop()
            if x == m-1 and y == n-1:
                return True
            for dx, dy in [(1, 0), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < m and 0 <= ny < n and grid[nx][ny] != -1 and not visited[nx][ny]:
                    visited[nx][ny] = True
                    stack.append((nx, ny))
        return False

    # If an initial path exists without any modification
    if check_path():
        return 0

    # Try modifying each cell once and check if a path can be created
    for i in range(m):
        for j in range(n):
            if grid[i][j] == -1:  # consider only the cells that are blocked
                grid[i][j] = 0
                if check_path():
                    return 1
                grid[i][j] = -1  # backtrack

    # If no path can be created by modifying at most one cell
    return -1

def find_min_range_subsequence(t, test_cases):
    results = []
    for i in range(t):
        n, a = test_cases[i]
        if n == 1:
            results.append((1, 0))
            continue
        sorted_a = sorted(a)
        min_diff = float('inf')
        for j in range(1, n):
            min_diff = min(min_diff, sorted_a[j] - sorted_a[j - 1])
        results.append((n, min_diff))
    return results

