from typing import List, Tuple

def find_two_sum(nums: List[int], target: int) -> Tuple[int, int]:
    """
    Given a sorted array of distinct integers and a target value, return a tuple containing
    the indices of the two numbers such that they add up to the target.
    """
    left, right = 0, len(nums) - 1
    while left < right:
        current_sum = nums[left] + nums[right]
        if current_sum == target:
            return (left, right)
        elif current_sum < target:
            left += 1
        else:
            right -= 1
    return ()

