def min_add_to_make_valid(s):
    """
    Returns the minimum number of brackets to add to make the sequence valid.
    """
    open_brackets = 0
    close_brackets = 0

    for char in s:
        if char == '(':
            open_brackets += 1
        elif char == ')':
            if open_brackets > 0:
                open_brackets -= 1
            else:
                close_brackets += 1

    return open_brackets + close_brackets

