def roman_to_integer(roman):
    """
    Convert a Roman numeral to an integer. Returns -1 if the input is not a valid Roman numeral.
    """
    roman_values = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    valid_roman_characters = set(roman_values.keys())
    invalid_conditions = [
        lambda r: any(char not in valid_roman_characters for char in r),
        lambda r: r.count('I') > 3 or r.count('X') > 3 or r.count('C') > 3,
        lambda r: r.count('V') > 1 or r.count('L') > 1 or r.count('D') > 1,
    ]

    if any(condition(roman) for condition in invalid_conditions):
        return -1

    integer_value = 0
    prev_value = 0
    for char in reversed(roman):
        value = roman_values[char]
        if value < prev_value:
            integer_value -= value
        else:
            integer_value += value
        prev_value = value

    return integer_value if 0 < integer_value <= 3999 else -1

