def process_ratings_and_queries(n, user_posts, q, queries):
    """
    Determines highest rated post for each user in given queries.

    Parameters:
    - n (int): Number of users
    - user_posts (List[Tuple[int, int, List[Tuple[int, int]]]]): Data about the users and their posts
    - q (int): Number of queries
    - queries (List[int]): List of user IDs to query

    Returns:
    - List[int]: Post IDs corresponding to the highest rated post for each query
    """
    user_max_post = {}

    # Process user posts data
    for user_id, m, posts in user_posts:
        max_rating = -1
        min_post_id = float('inf')
        for post_id, rating in posts:
            if rating > max_rating or (rating == max_rating and post_id < min_post_id):
                max_rating = rating
                min_post_id = post_id
        if max_rating != -1:
            user_max_post[user_id] = min_post_id

    # Process queries
    results = []
    for user_id in queries:
        if user_id in user_max_post:
            results.append(user_max_post[user_id])
        else:
            results.append(-1)

    return results

