def min_diff_partition(arr):
    """
    This function takes a list of integers and returns the minimum absolute difference
    between the sum of two non-empty partitions of the array.
    """
    total_sum = sum(arr)
    n = len(arr)

    # To find the subset with sum closest to total_sum / 2
    dp = [0] * (total_sum // 2 + 1)

    for num in arr:
        for j in range(total_sum // 2, num - 1, -1):
            dp[j] = max(dp[j], dp[j - num] + num)

    sum1 = dp[-1]
    sum2 = total_sum - sum1
    return abs(sum1 - sum2)


def find_min_absolute_difference(n, array):
    return min_diff_partition(array)

