def minCoins(coins, target):
    """
    Returns the minimum number of coins needed to make the target amount using the given coins.
    If it is not possible to make the target amount using any combination of the given coins, returns -1.
    """
    # Initialize DP array with an impossible high value (target+1) for all amounts
    dp = [target + 1] * (target + 1)
    dp[0] = 0  # Base case: 0 coins needed to make amount 0

    for amount in range(1, target + 1):
        for coin in coins:
            if coin <= amount:
                dp[amount] = min(dp[amount], dp[amount - coin] + 1)

    return dp[target] if dp[target] != target + 1 else -1

