from collections import deque, defaultdict

def shortest_cycle(n, m, edges):
    # Graph construction
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def bfs(start):
        dist = {start: 0}
        parent = {start: None}
        queue = deque([start])

        while queue:
            node = queue.popleft()

            for neighbor in graph[node]:
                if neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    parent[neighbor] = node
                    queue.append(neighbor)
                elif parent[node] != neighbor:  # Detect cycle
                    return dist[node] + dist[neighbor] + 1
        return float('inf')

    min_cycle_len = float('inf')

    for node in range(1, n + 1):
        cycle_len = bfs(node)
        min_cycle_len = min(min_cycle_len, cycle_len)

    return min_cycle_len if min_cycle_len != float('inf') else -1

