def count_odd_cells(N, M, operations):
    grid = [[0] * M for _ in range(N)]

    for x1, y1, x2, y2 in operations:
        for i in range(x1 - 1, x2):
            for j in range(y1 - 1, y2):
                grid[i][j] += 1

    odd_count = 0
    for row in grid:
        for cell in row:
            if cell % 2 != 0:
                odd_count += 1

    return odd_count

def longest_increasing_subarray(temperatures):
    if not temperatures:
        return 0

    max_len = 1
    current_len = 1

    for i in range(1, len(temperatures)):
        if temperatures[i] > temperatures[i - 1]:
            current_len += 1
            max_len = max(max_len, current_len)
        else:
            current_len = 1

    return max_len

