def count_paths_with_obstacles(grid):
    """
    Returns the number of different paths from the top-left corner (1,1)
    to the bottom-right corner (N,M) in a grid with obstacles.
    Obstacles are marked as 1 and open cells are marked as 0.
    """
    N = len(grid)
    M = len(grid[0]) if N > 0 else 0

    if grid[0][0] == 1 or grid[N-1][M-1] == 1:
        return 0

    dp = [[0]*M for _ in range(N)]
    dp[0][0] = 1

    for i in range(N):
        for j in range(M):
            if grid[i][j] == 1:
                dp[i][j] = 0
            else:
                if i > 0:
                    dp[i][j] += dp[i - 1][j]
                if j > 0:
                    dp[i][j] += dp[i][j - 1]

    return dp[N-1][M-1]

def nextHigherNumber(n):
    digits = list(str(n))
    i = len(digits) - 2

    while i >= 0 and digits[i] >= digits[i + 1]:
        i -= 1

    if i == -1:
        return -1

    j = len(digits) - 1
    while digits[j] <= digits[i]:
        j -= 1

    digits[i], digits[j] = digits[j], digits[i]

    digits = digits[:i + 1] + digits[i + 1:][::-1]

    return int(''.join(digits))

