def max_even_sum_subarray_length(s):
    """
    Returns the maximum possible size of a group with an even sum.
    """
    n = len(s)
    total_sum = sum(int(num) for num in s)

    if total_sum % 2 == 0:
        return n

    # If sum is odd, we need to remove one odd element (if possible)
    for i in range(n):
        if int(s[i]) % 2 != 0:
            return n - 1

    # If no odd element is found (although there should be based on the input constraints)
    return 0

def find_max_even_group_length(test_cases):
    results = []
    for s in test_cases:
        results.append(max_even_sum_subarray_length(s))
    return results

