def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def max_prime_piles(t, test_cases):
    results = []
    for i in range(t):
        n, piles = test_cases[i]
        prime_piles_count = sum(1 for pile in piles if is_prime(pile))
        results.append(prime_piles_count)
    return results

def solve(s):
    """
    Removes the minimum number of characters from s so that no two adjacent characters are the same
    and returns the altered string.
    """
    if not s:
        return s

    result = [s[0]]  # Start with the first character

    for i in range(1, len(s)):
        if s[i] != s[i - 1]:  # Only add the character if it is not the same as the previous one
            result.append(s[i])

    return ''.join(result)

