from collections import defaultdict
from itertools import combinations

def find_popular_pairs(p, t, transactions, k):
    # Dictionary to store pair count
    pair_count = defaultdict(int)

    # Loop through each transaction to find pairs
    for transaction in transactions:
        m = transaction[0]  # number of products in this transaction
        products = transaction[1:]
        for pair in combinations(sorted(products), 2):
            pair_count[pair] += 1

    # Identify popular pairs
    popular_pairs = sorted(pair for pair, count in pair_count.items() if count > k)

    # Return result based on whether popular pairs exist
    if popular_pairs:
        return "\n".join(f"{x} {y}" for x, y in popular_pairs)
    else:
        return "No popular pairs"

def min_cost_to_buy_fruits(T, test_cases):
    def knapsack(k, bundles, m, n):
        dp = [[float('inf')] * (n + 1) for _ in range(m + 1)]
        dp[0][0] = 0

        for a, b, c in bundles:
            for i in range(m, -1, -1):
                for j in range(n, -1, -1):
                    if dp[i][j] != float('inf'):
                        new_a = min(i + a, m)
                        new_b = min(j + b, n)
                        dp[new_a][new_b] = min(dp[new_a][new_b], dp[i][j] + c)

        return dp[m][n] if dp[m][n] != float('inf') else -1

    results = []
    for case in test_cases:
        k, m, n, bundles = case
        result = knapsack(k, bundles, m, n)
        results.append(result)
    return results

def calculate_adjusted_scores(players_scores):
    adjusted_scores = []

    for player_scores in players_scores:
        num_rounds = player_scores[0]
        scores = player_scores[1:]

        if num_rounds == 1:
            adjusted_scores.append(0)
        else:
            total_score = sum(scores)
            lowest_score = min(scores)
            adjusted_score = total_score - lowest_score
            adjusted_scores.append(adjusted_score)

    return adjusted_scores

def get_input_output(data):
    lines = data.strip().split("\n")
    p = int(lines[0])
    players_scores = [list(map(int, lines[i+1].split())) for i in range(p)]
    result = calculate_adjusted_scores(players_scores)
    return "\n".join(map(str, result))

def shortestToChar(S, C):
    n = len(S)
    result = [float('inf')] * n

    # Forward pass to find shortest distances to previous occurrences of C
    prev = float('-inf')
    for i in range(n):
        if S[i] == C:
            prev = i
        result[i] = i - prev

    # Backward pass to find shortest distances to next occurrences of C
    prev = float('inf')
    for i in range(n - 1, -1, -1):
        if S[i] == C:
            prev = i
        result[i] = min(result[i], prev - i)

    return result

