    """
    Flattens a nested list of arbitrary depth into a single list of strings.
    """
    def _flatten_helper(lst):
        for item in lst:
            if isinstance(item, list):
                yield from _flatten_helper(item)
            else:
                yield item

    return list(_flatten_helper(nested_list))

