def min_moves(N, S):
    if S[0] in 'BO' or S[-1] in 'BO':
        return -1  # can't start or end on a bomb or obstacle

    moves = 0
    i = 0

    while i < N - 1:
        if S[i + 1] == '.':
            i += 1
            moves += 1
        elif S[i + 1] == 'B':
            back_counter = i
            while back_counter > 0 and S[back_counter] == '.':
                back_counter -= 1
            if back_counter == 0:
                return -1  # No safe blocks to go back to
            moves += 1
            i = back_counter - 1  # force backward movement
        elif S[i + 1] == 'O':
            return -1  # block with an obstacle, impossible to move forward

    return moves

