def is_valid_bracket_sequence(s):
    """
    Determines if the given bracket sequence is valid.

    :param s: A string containing only '(', ')', '{', '}', '[' and ']' characters
    :return: "YES" if the bracket sequence is valid, otherwise "NO"
    """
    stack = []
    bracket_map = {'(': ')', '{': '}', '[': ']'}

    for char in s:
        if char in bracket_map:
            stack.append(char)
        elif stack and char == bracket_map[stack[-1]]:
            stack.pop()
        else:
            return "NO"

    return "YES" if not stack else "NO"

def max_artifacts(r, c, grid):
    def dfs(x, y):
        if x < 0 or x >= r or y < 0 or y >= c or grid[x][y] == '#' or visited[x][y]:
            return 0
        visited[x][y] = True
        count = int(grid[x][y]) if grid[x][y].isdigit() else 0
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            count += dfs(x+dx, y+dy)
        return count

    visited = [[False]*c for _ in range(r)]
    max_count = 0
    for i in range(r):
        for j in range(c):
            if grid[i][j] != '#' and not visited[i][j]:
                max_count = max(max_count, dfs(i, j))
    return max_count

def findWords(grid, words):
    """
    Finds all words in the grid that can be formed by sequentially adjacent letters.
    """
    if not grid or not grid[0]:
        return []

    rows, cols = len(grid), len(grid[0])

    def dfs(x, y, node, path, visited):
        if 'end' in node:
            result.add(node['end'])

        if x < 0 or x >= rows or y < 0 or y >= cols or (x, y) in visited or grid[x][y] not in node:
            return

        visited.add((x, y))
        char = grid[x][y]
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            dfs(nx, ny, node[char], path + char, visited)
        visited.remove((x, y))

    def build_trie():
        trie = {}
        for word in words:
            node = trie
            for char in word:
                if char not in node:
                    node[char] = {}
                node = node[char]
            node['end'] = word
        return trie

    trie = build_trie()
    result = set()
    for i in range(rows):
        for j in range(cols):
            dfs(i, j, trie, "", set())
    return sorted(result)

def find_tournament_winner(t, cases):
    def predict_winner(n, power_levels):
        winner = 0
        for i in range(1, n):
            strength_of_i = 0
            strength_of_winner = 0
            # Compare overall strength of i and current winner
            for j in range(n):
                if j != i:
                    strength_of_i += power_levels[i][j]
                if j != winner:
                    strength_of_winner += power_levels[winner][j]
            if strength_of_i > strength_of_winner:
                winner = i
        return winner

    results = []
    index = 0
    for case_index in range(t):
        n = cases[index]
        index += 1
        power_levels = []
        for _ in range(n):
            power_levels.append(cases[index])
            index += 1
        results.append(predict_winner(n, power_levels))

    return results

