def can_partition_k_subsets(nums, k):
    total_sum = sum(nums)
    if total_sum % k != 0:
        return "NO"
    target_sum = total_sum // k

    def can_partition(start, k, current_sum, bucket):
        if k == 1:
            return True
        if current_sum == target_sum:
            return can_partition(0, k - 1, 0, bucket)
        for i in range(start, len(nums)):
            if not bucket[i] and current_sum + nums[i] <= target_sum:
                bucket[i] = True
                if can_partition(i + 1, k, current_sum + nums[i], bucket):
                    return True
                bucket[i] = False
        return False

    nums.sort(reverse=True)
    bucket = [False] * len(nums)
    return "YES" if can_partition(0, k, 0, bucket) else "NO"

def solve(test_cases):
    results = []
    for test_case in test_cases:
        N, k = test_case[0]
        nums = test_case[1]
        results.append(can_partition_k_subsets(nums, k))
    return results

