from bisect import bisect_left

def min_removals(N, heights):
    """
    Returns the minimum number of trees that must be removed
    to ensure the remaining trees' heights are strictly increasing.
    """
    # List to store the longest increasing subsequence
    lis = []

    for height in heights:
        pos = bisect_left(lis, height)
        if pos == len(lis):
            lis.append(height)
        else:
            lis[pos] = height

    # Calculate the number of removals needed
    return N - len(lis)

