def infix_to_postfix(expression: str) -> str:
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    associativity = {'+': 'L', '-': 'L', '*': 'L', '/': 'L', '^': 'R'}

    def has_higher_precedence(op1, op2):
        if precedence[op1] > precedence[op2]:
            return True
        if precedence[op1] == precedence[op2]:
            if associativity[op1] == 'L':
                return True
        return False

    output = []
    stack = []

    for char in expression:
        if char.isalpha(): # if operand, add to output
            output.append(char)
        elif char == '(': # left parenthesis, push to stack
            stack.append(char)
        elif char == ')': # right parenthesis, pop until left parenthesis
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()
        else: # operator encountered
            while (stack and stack[-1] != '(' and has_higher_precedence(stack[-1], char)):
                output.append(stack.pop())
            stack.append(char)

    # pop all the remaining operators into the output
    while stack:
        output.append(stack.pop())

    return "".join(output)

