def count_flowers_after_instructions(R, C, instructions):
    garden = [[0 for _ in range(C)] for _ in range(R)]
    total_flowers = 0
    planted_order = []

    for instruction in instructions:
        if instruction == 'P':
            planted = False
            for i in range(R):
                for j in range(C):
                    if garden[i][j] == 0:
                        garden[i][j] = 1
                        planted_order.append((i, j))
                        total_flowers += 1
                        planted = True
                        break
                if planted:
                    break
        elif instruction == 'R':
            if planted_order:
                i, j = planted_order.pop()
                garden[i][j] = 0
                total_flowers -= 1
        # Ignore '.' character as it does nothing

    return total_flowers

