def is_prime(num):
    """
    Check if a number is prime.
    """
    if num <= 1:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    for i in range(3, int(num**0.5) + 1, 2):
        if num % i == 0:
            return False
    return True

def find_prime_pair(N):
    """
    Find two prime numbers whose sum is N.
    """
    for i in range(2, N):
        if is_prime(i) and is_prime(N - i):
            return i, N - i
    return "NO"

def prime_pairs(T, cases):
    """
    For each test case, output two prime numbers whose sum is N, or "NO" if it isn't possible.
    """
    results = []
    for N in cases:
        pair = find_prime_pair(N)
        if pair == "NO":
            results.append("NO")
        else:
            results.append(f"{pair[0]} {pair[1]}")
    return results

def apply_operations(n, m, edges, operations):
    from collections import defaultdict, deque

    tree = defaultdict(list)
    for u, v in edges:
        tree[u].append(v)
        tree[v].append(u)

    values = [0] * (n + 1)

    subtree_updates = defaultdict(int)

    def bfs(start):
        visited = set()
        queue = deque([start])
        order = []

        while queue:
            node = queue.popleft()
            if node not in visited:
                visited.add(node)
                order.append(node)
                for neighbor in tree[node]:
                    if neighbor not in visited:
                        queue.append(neighbor)

        return order

    root_order = bfs(1)

    for v, x in operations:
        subtree_updates[v] += x

    def dfs(node, parent_value):
        values[node] += parent_value + subtree_updates[node]
        for neighbor in tree[node]:
            if values[neighbor] == 0:  # Ensure we don't go back to parent in undirected graph
                dfs(neighbor, values[node])

    dfs(1, 0)
    return values[1:]

