def rearrange(S):
    """
    Rearranges the characters in S such that all lowercase letters come before any digits.

    Parameters:
    S (str): A string containing digits and lowercase letters.

    Returns:
    str: A string with letters before digits, preserving their relative order.
    """
    letters = []
    digits = []

    for char in S:
        if char.isdigit():
            digits.append(char)
        else:
            letters.append(char)

    return ''.join(letters + digits)

