import re

def validate_password(password):
    """
    Returns "Valid" if the password meets the specified criteria, otherwise returns "Invalid".
    """
    if not (8 <= len(password) <= 12):
        return "Invalid"

    if not re.search("[A-Z]", password):
        return "Invalid"

    if not re.search("[a-z]", password):
        return "Invalid"

    if not re.search("[0-9]", password):
        return "Invalid"

    if not re.search("[!@#$%^&*()-+]", password):
        return "Invalid"

    return "Valid"

