def min_diff_subarray(arr, k):
    n = len(arr)
    if k > n:
        return -1

    arr.sort()
    min_diff = float('inf')

    for i in range(n - k + 1):
        current_diff = arr[i + k - 1] - arr[i]
        if current_diff < min_diff:
            min_diff = current_diff

    return min_diff

