def isHexadecimal(s):
    """
    Returns 1 if the given string is a valid hexadecimal number, otherwise returns 0.
    """
    if s.startswith("0x") or s.startswith("0X"):
        s = s[2:]

    # Check if the string is empty after removing the optional prefix
    if not s:
        return 0

    # Check if all characters in the string are valid hexadecimal characters
    for char in s:
        if not (char.isdigit() or 'a' <= char <= 'f' or 'A' <= char <= 'F'):
            return 0

    return 1

