def find_missing_tags(n, existing_tags):
    all_tags = {'A': set(), 'H': set(), 'J': set(), 'G': set()}
    for breed in all_tags:
        all_tags[breed] = {f"{breed}{str(i).zfill(4)}" for i in range(1, 10000)}

    for tag in existing_tags:
        breed = tag[0]
        all_tags[breed].discard(tag)

    missing_tags = []
    for breed in "AHJG":
        missing_tags.extend(sorted(all_tags[breed]))

    return missing_tags

def longestAlphabeticSubstring(sentence):
    words = sentence.split()
    max_length = 1
    current_length = 1

    for i in range(1, len(words)):
        if words[i][0] >= words[i-1][0]:
            current_length += 1
        else:
            current_length = 1

        if current_length > max_length:
            max_length = current_length

    return max_length

