def reverseStr(s: str, k: int) -> str:
    """
    Reverses the first k characters for every 2k characters in string s.
    """
    n = len(s)
    s = list(s)
    for i in range(0, n, 2 * k):
        s[i:i + k] = reversed(s[i:i + k])
    return "".join(s)

