def unique_simple_path(N, M, bridges, s, d):
    from collections import defaultdict, deque

    def bfs_count_paths(start, end, graph):
        queue = deque([[start]])
        paths_count = 0

        while queue:
            path = queue.popleft()
            node = path[-1]

            if node == end:
                paths_count += 1
                continue

            for neighbor in graph[node]:
                if neighbor not in path:
                    new_path = list(path)
                    new_path.append(neighbor)
                    queue.append(new_path)

        return paths_count

    # Construct the graph
    graph = defaultdict(list)
    for u, v in bridges:
        graph[u].append(v)
        graph[v].append(u)

    # Check number of paths from s to d
    paths_count = bfs_count_paths(s, d, graph)

    if paths_count == 0:
        return "NONE"
    elif paths_count == 1:
        return "UNIQUE"
    else:
        return "MULTIPLE"

