def calculate_rewards(T, testcases):
    result = []

    for i in range(T):
        n, d = testcases[i][0]
        problems = testcases[i][1]
        max_difficulties = testcases[i][2]

        for max_difficulty in max_difficulties:
            total_reward = sum(reward for difficulty, reward in problems if difficulty <= max_difficulty)
            result.append(total_reward)

    return result
